css/style.css:
/* きずなの紋章 ― むかしの RPG ふうの まど */
/* 字の形: ふだんは なめらかな 丸ゴシック（css/fonts.css の KizunaRound）。設定で ドットの 字（KizunaDot）にも できる */
@font-face {
  font-family: 'KizunaDot';
  src: url('../fonts/DotGothic16-Regular.ttf') format('truetype');
  font-display: swap;
}

:root {
  color-scheme: dark;
  --bg: #05071a;
  --win: rgba(4, 6, 22, 0.93);
  --win-solid: #04061a;
  --line: #f3f0ff;
  --text: #ffffff;
  --muted: #a9a8c8;
  --accent: #ffd66b;
  --warn: #ffb347;
  --danger: #ff6464;
  --good: #7dffb0;
  --mp: #8fd0ff;
  --bond-a: #ff8ad8;
  --bond-b: #ffd66b;
  --fs: clamp(14px, 1.6vmin + 8px, 22px);
  --fs-small: calc(var(--fs) * 0.8);
  --fs-big: calc(var(--fs) * 1.3);
  --radius: 9px;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  /* ウインドウ用の 十字キーが したに 出ている ときの たかさ（ふだんは 0） */
  --pad-h: 0px;
  --font-ui: 'KizunaRound', 'Hiragino Maru Gothic ProN', 'Hiragino Sans', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', 'Meiryo', sans-serif;
}

body.big-text { --fs: clamp(17px, 2vmin + 10px, 27px); }
body.dot-font { --font-ui: 'KizunaDot', 'Hiragino Kaku Gothic ProN', 'Hiragino Sans', 'Yu Gothic', 'Meiryo', sans-serif; }

* { box-sizing: border-box; }
[hidden] { display: none !important; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-ui);
  font-size: var(--fs);
  line-height: 1.55;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  overscroll-behavior: none;
  -webkit-touch-callout: none;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

/* iPhone: ピンチや ひっぱりで がめんが うごかないように（スクロールする リストだけ たてに うごかせる） */
#app { position: fixed; inset: 0; overflow: hidden; touch-action: none; }
.scroll, .b-cmd .menu, .b-msg, .title-screen { touch-action: pan-y; }

#field {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
}

/* 2.5D（たちたい）の がめん。うえに 2D の キャンバス（くらやみ・しるし）を かさねる */
#field3d {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

button { cursor: pointer; }
button:focus-visible, input:focus-visible, .item:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

/* ───── まど ───── */
.win {
  background: var(--win);
  border: 3px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0 0 2px #000, inset 0 0 0 2px #000, 0 6px 20px rgba(0, 0, 0, 0.45);
  padding: 0.55em 0.8em;
  color: var(--text);
}

.win h2, .win h3 {
  margin: 0 0 0.3em;
  font-size: var(--fs);
  font-weight: normal;
  color: var(--accent);
  letter-spacing: 0.05em;
}

.muted { color: var(--muted); }
.warn { color: var(--warn); }
.danger { color: var(--danger); }
.good { color: var(--good); }
.gold { color: var(--accent); }
.mpc { color: var(--mp); }
.small { font-size: var(--fs-small); }

/* ───── メニューの ならび ───── */
.menu { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.05em; }
.menu.cols2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 1.2em; }
.menu .item {
  position: relative;
  padding: 0.12em 0.4em 0.12em 1.3em;
  border-radius: 5px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  gap: 0.8em;
  align-items: baseline;
  min-height: 1.9em;
  align-items: center;
}
.menu .item::before {
  content: '';
  position: absolute;
  left: 0.2em;
  top: 50%;
  transform: translateY(-50%);
  border: 0.32em solid transparent;
  border-left: 0.5em solid transparent;
}
.menu .item.sel { background: rgba(255, 255, 255, 0.08); }
.menu .item.sel::before { border-left-color: var(--accent); }
.menu .item.dis { color: #6d6c88; }
.menu .item .r { color: var(--muted); font-size: var(--fs-small); white-space: nowrap; }
.menu .item .r.pen { color: var(--warn); }
.menu .item .r.gold { color: var(--accent); }
.menu .item .r.good { color: var(--good); }
.menu .hdr {
  color: var(--accent);
  font-size: var(--fs-small);
  padding: 0.5em 0.4em 0.1em;
  border-bottom: 1px dashed rgba(255, 214, 107, 0.35);
  margin-bottom: 0.15em;
  pointer-events: none;
}
.menu .hdr:first-child { padding-top: 0.1em; }
.menu .item .face { height: 1.9em; width: auto; image-rendering: pixelated; margin-right: 0.4em; flex: none; object-fit: contain; }
.menu .item .l.wf { display: flex; align-items: center; min-width: 0; flex-wrap: wrap; }
.menu .tag { font-size: 0.7em; padding: 0 0.35em; border: 1px solid currentColor; border-radius: 4px; margin-left: 0.3em; vertical-align: 0.1em; }

.scroll { overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; }
.scroll::-webkit-scrollbar { width: 8px; }
.scroll::-webkit-scrollbar-thumb { background: #3b3a66; border-radius: 4px; }

/* ───── UI の そう ───── */
#ui { position: absolute; inset: 0; pointer-events: none; z-index: 60; }
#ui > * { pointer-events: auto; }

.panel {
  position: absolute;
  max-height: calc(100% - 24px - var(--safe-b) - var(--safe-t));
  display: flex;
  flex-direction: column;
}

.center-panel {
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(92vw, 720px);
}

.modal-back { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.35); }

/* ───── メッセージ ───── */
.dialog {
  position: absolute;
  left: 50%;
  bottom: calc(12px + var(--safe-b));
  transform: translateX(-50%);
  width: min(94vw, 880px);
  min-height: 5.6em;
  padding: 0.7em 1em 0.9em;
  font-size: calc(var(--fs) * 1.05);
  line-height: 1.75;
  white-space: pre-wrap;
  word-break: break-all;
}
.dialog .speaker {
  position: absolute;
  top: -1.35em;
  left: 0.9em;
  background: var(--win-solid);
  border: 3px solid var(--line);
  border-radius: 7px;
  padding: 0 0.6em;
  font-size: var(--fs-small);
  color: var(--accent);
}
.dialog .more {
  position: absolute;
  right: 0.8em;
  bottom: 0.2em;
  animation: blink 0.8s steps(2) infinite;
  color: var(--accent);
}
.dialog.spectator .more { color: var(--muted); }
@keyframes blink { 50% { opacity: 0; } }

.choice {
  position: absolute;
  right: max(3vw, calc(50% - 440px));
  bottom: calc(8.2em + var(--safe-b));
  min-width: 9em;
}
.choice .q { font-size: var(--fs-small); color: var(--muted); margin-bottom: 0.2em; }
/* 第35回: えらぶ 物が 多い とき（仲間が いっぱいの ときの さよなら）は この 中で スクロール */
.choice .menu { max-height: min(52vh, 26em); overflow-y: auto; }
/* 第65回: えらぶ 物ごとの せつめい（お仕事いらい板の 職業・ごほうび）。スマホの たて画面でも 読める 小さな わく */
.choice.has-info { width: min(24em, calc(100vw - 16px)); }
.choice.has-info .menu { max-height: min(40vh, 22em); }
.choice-info { margin-top: 0.3em; padding: 0.3em 0.45em; border-top: 1px solid var(--muted); font-size: var(--fs-small); line-height: 1.35; white-space: pre-line; min-height: 4.1em; max-height: 6.2em; overflow-y: auto; }
.choice-info.empty { visibility: hidden; }

/* ───── HUD ───── */
#hud { position: absolute; inset: 0; pointer-events: none; }
#hud > * { pointer-events: auto; }

.hud-party {
  position: absolute;
  left: calc(8px + var(--safe-l));
  top: calc(8px + var(--safe-t));
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  max-width: 62vw;
  pointer-events: none;
}
.hud-mem {
  padding: 0.15em 0.5em 0.25em;
  font-size: var(--fs-small);
  min-width: 6.5em;
  line-height: 1.3;
}
.hud-mem .nm { display: flex; justify-content: space-between; gap: 0.4em; }
.hud-mem .lv { color: var(--muted); }
.bar { height: 0.36em; background: #22203a; border-radius: 3px; overflow: hidden; margin-top: 0.15em; }
.bar > i { display: block; height: 100%; background: var(--good); transition: width 0.25s; }
.bar.mp > i { background: var(--mp); }
.bar.low > i { background: var(--warn); }
.hud-mem.dead .nm { color: var(--danger); }
/* マルチの ときの 人の 名前は 黄緑。HP が 半分いか オレンジ、1わりいか 赤 */
.hud-mem .n.player { color: #b8f05a; }
.hud-mem .n.orange, .hud-mem .hn.orange { color: #ffa53a; }
.hud-mem .n.red, .hud-mem .hn.red { color: #ff5a5a; }
.bar.orange > i { background: #ff9a2a; }
.bar.red > i { background: #ff4a4a; }
.hud-mem.away { opacity: 0.55; }

.hud-area {
  position: absolute;
  left: 50%;
  top: calc(10px + var(--safe-t));
  transform: translateX(-50%);
  font-size: var(--fs);
  padding: 0.15em 1em;
  opacity: 0;
  transition: opacity 0.6s;
  pointer-events: none;
  white-space: nowrap;
}
.hud-area.show { opacity: 1; }

.hud-obj {
  position: absolute;
  left: calc(8px + var(--safe-l));
  bottom: calc(10px + var(--safe-b));
  max-width: min(54vw, 440px);
  font-size: var(--fs-small);
  padding: 0.3em 0.7em;
  line-height: 1.4;
  cursor: pointer;
}
.hud-obj b { color: var(--accent); font-weight: normal; }

.hud-map {
  position: absolute;
  right: calc(8px + var(--safe-r));
  top: calc(8px + var(--safe-t));
  padding: 3px;
  line-height: 0;
  cursor: pointer;
}
.hud-map canvas { width: clamp(90px, 18vmin, 170px); height: clamp(90px, 18vmin, 170px); image-rendering: pixelated; border-radius: 5px; }
/* 昼・夜の 時計（ちずの 左下に かさねる。ui/clock.js） */
.hud-clock { position: absolute; left: -10px; bottom: -10px; width: clamp(30px, 6.5vmin, 42px); height: clamp(30px, 6.5vmin, 42px); pointer-events: none; filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.6)); }
.hud-map .hud-clock canvas { width: 100%; height: 100%; border-radius: 0; image-rendering: pixelated; }
/* 仲間の粉の のこり（ちずの 上の はしに 小さく。ui/hud.js） */
.hud-powder { position: absolute; left: 3px; right: 3px; top: 3px; padding: 1px 2px; font-size: clamp(9px, 1.6vmin + 3px, 13px); line-height: 1.25; text-align: center; color: #ffe0f4; background: rgba(70, 20, 70, 0.82); border-radius: 4px 4px 0 0; pointer-events: none; white-space: pre-line; overflow: hidden; }
.hud-powder[hidden] { display: none; }
.hud-aura { color: #dff4ff; background: rgba(20, 60, 110, 0.85); border-radius: 4px; }
.hud-aura.lure { color: #ffe6cc; background: rgba(130, 30, 20, 0.86); }
/* 大鳥フウラの ボタン（sky.js） */
.hud-btn.hud-sky, .hud-btn.hud-sky2 { color: #bff0e0; border-color: #5ec8b0; }

.hud-btns {
  position: absolute;
  right: calc(8px + var(--safe-r));
  top: calc(clamp(90px, 18vmin, 170px) + 22px + var(--safe-t));
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.hud-btn {
  padding: 0.2em 0.7em;
  font-size: var(--fs-small);
  min-width: 4.6em;
  text-align: center;
}

.hud-chat {
  position: absolute;
  left: calc(8px + var(--safe-l));
  bottom: calc(3.8em + var(--safe-b));
  max-width: min(60vw, 460px);
  font-size: var(--fs-small);
  display: flex;
  flex-direction: column;
  gap: 2px;
  pointer-events: none;
}
.hud-chat div {
  background: rgba(0, 0, 0, 0.55);
  padding: 0.05em 0.5em;
  border-radius: 5px;
  animation: fadeout 12s forwards;
}
.hud-chat b { color: var(--accent); font-weight: normal; }
@keyframes fadeout { 0%, 80% { opacity: 1; } 100% { opacity: 0; } }

/* プレイヤーの なまえ・ふきだし */
#labels { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.plabel {
  position: absolute;
  transform: translate(-50%, -100%);
  font-size: calc(var(--fs) * 0.7);
  color: #fff;
  text-shadow: 1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000;
  white-space: nowrap;
}
.plabel.party { color: var(--accent); }
.bubble {
  position: absolute;
  transform: translate(-50%, -100%);
  background: #fff;
  color: #111;
  border-radius: 10px;
  padding: 0.1em 0.6em;
  font-size: calc(var(--fs) * 0.8);
  white-space: nowrap;
  animation: pop 0.25s ease-out;
}
.bubble::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -6px;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top-color: #fff;
  border-bottom: 0;
}
@keyframes pop { from { transform: translate(-50%, -80%) scale(0.6); opacity: 0; } }

/* ───── タッチ そうさ ───── */
#touch { position: absolute; inset: 0; pointer-events: none; }
#stick {
  position: absolute;
  width: 128px;
  height: 128px;
  left: calc(26px + var(--safe-l));
  bottom: calc(26px + var(--safe-b));
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  border: 2px solid rgba(255, 255, 255, 0.25);
  opacity: 0.8;
  transition: opacity 0.15s;
}
#stick.on { opacity: 1; border-color: rgba(255, 255, 255, 0.55); }
/* さわった ところに でる スティック（はなすと ひだりしたに もどる） */
#stick.float { transition: none; background: rgba(255, 255, 255, 0.12); }
#stick:not(.on) { opacity: 0.35; }
#stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 54px;
  height: 54px;
  margin: -27px 0 0 -27px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  border: 2px solid rgba(255, 255, 255, 0.6);
}
.tbtn {
  position: absolute;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  border: 3px solid rgba(255, 255, 255, 0.75);
  background: rgba(10, 12, 40, 0.55);
  color: #fff;
  font-size: 24px;
  pointer-events: auto;
  touch-action: none;
}
.tbtn.on { background: rgba(255, 214, 107, 0.5); }
#btn-a { right: calc(22px + var(--safe-r)); bottom: calc(70px + var(--safe-b)); }
#btn-b { right: calc(100px + var(--safe-r)); bottom: calc(26px + var(--safe-b)); }
#btn-run {
  right: calc(30px + var(--safe-r)); bottom: calc(152px + var(--safe-b));
  width: 58px; height: 58px; font-size: 13px; line-height: 1.1;
  border-color: rgba(143, 208, 255, 0.8);
}
#btn-run.on { background: rgba(143, 208, 255, 0.55); border-color: #ffffff; box-shadow: 0 0 12px rgba(143, 208, 255, 0.9); }
#btn-run span { display: block; }
body.touch .hud-obj { bottom: calc(170px + var(--safe-b)); }

/* ───── ウインドウ用の 十字キー（スマホ。input.js の bindPad） ───── */
#pad { position: absolute; inset: 0; pointer-events: none; z-index: 65; }
#pad button { pointer-events: auto; touch-action: none; -webkit-user-select: none; user-select: none; -webkit-tap-highlight-color: transparent; }
#pad-cross {
  position: absolute;
  left: calc(10px + var(--safe-l));
  bottom: calc(10px + var(--safe-b));
  display: grid;
  grid-template-columns: repeat(3, var(--pk));
  grid-template-rows: repeat(3, var(--pk));
  grid-template-areas: ". up ." "left . right" ". down .";
  --pk: 46px;
}
#pad .pk {
  width: var(--pk);
  height: var(--pk);
  padding: 0;
  border: 2px solid rgba(255, 255, 255, 0.75);
  border-radius: 9px;
  background: rgba(10, 12, 40, 0.72);
  color: #fff;
  font-size: 17px;
  line-height: 1;
}
#pad .pk.up { grid-area: up; }
#pad .pk.down { grid-area: down; }
#pad .pk.left { grid-area: left; }
#pad .pk.right { grid-area: right; }
#pad .pk.on, #pad .tbtn.on { background: rgba(255, 214, 107, 0.55); }
#pad-ab { position: absolute; right: calc(10px + var(--safe-r)); bottom: calc(10px + var(--safe-b)); width: 138px; height: 138px; }
#pad-ab .tbtn { width: 64px; height: 64px; font-size: 22px; }
#pad-ab .pa { right: 0; top: 8px; }
#pad-ab .pb { left: 0; bottom: 4px; }
/* 第64回: たて持ちの ボタンの ならび（ui/hand.js。body の data-hand）。よこ持ちは 今のまま */
@media (orientation: portrait) {
  /* 左手用: 左右 はんたい */
  body[data-hand="left"] #stick { left: auto; right: calc(26px + var(--safe-r)); }
  body[data-hand="left"] #btn-a { right: auto; left: calc(22px + var(--safe-l)); }
  body[data-hand="left"] #btn-b { right: auto; left: calc(100px + var(--safe-l)); }
  body[data-hand="left"] #btn-run { right: auto; left: calc(30px + var(--safe-l)); }
  body[data-hand="left"] #pad-cross { left: auto; right: calc(10px + var(--safe-r)); }
  body[data-hand="left"] #pad-ab { right: auto; left: calc(10px + var(--safe-l)); }
  body[data-hand="left"] #pad-ab .pa { right: auto; left: 0; }
  body[data-hand="left"] #pad-ab .pb { left: auto; right: 0; }
  /* 片手（右手）: スティックは 右下。A・B・走るは その 左と 上（親指が とどく 所） */
  body[data-hand="oneR"] #stick { left: auto; right: calc(18px + var(--safe-r)); bottom: calc(24px + var(--safe-b)); }
  body[data-hand="oneR"] #btn-a { right: calc(164px + var(--safe-r)); bottom: calc(100px + var(--safe-b)); }
  body[data-hand="oneR"] #btn-b { right: calc(158px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); }
  body[data-hand="oneR"] #btn-run { right: calc(52px + var(--safe-r)); bottom: calc(166px + var(--safe-b)); }
  body[data-hand="oneR"] #pad-cross { left: auto; right: calc(10px + var(--safe-r)); }
  body[data-hand="oneR"] #pad-ab { right: calc(156px + var(--safe-r)); }
  /* 片手（左手）: 片手（右手）の 左右 はんたい */
  body[data-hand="oneL"] #stick { left: calc(18px + var(--safe-l)); bottom: calc(24px + var(--safe-b)); }
  body[data-hand="oneL"] #btn-a { right: auto; left: calc(164px + var(--safe-l)); bottom: calc(100px + var(--safe-b)); }
  body[data-hand="oneL"] #btn-b { right: auto; left: calc(158px + var(--safe-l)); bottom: calc(22px + var(--safe-b)); }
  body[data-hand="oneL"] #btn-run { right: auto; left: calc(52px + var(--safe-l)); bottom: calc(166px + var(--safe-b)); }
  body[data-hand="oneL"] #pad-ab { right: auto; left: calc(156px + var(--safe-l)); }
  body[data-hand="oneL"] #pad-ab .pa { right: auto; left: 0; }
  body[data-hand="oneL"] #pad-ab .pb { left: auto; right: 0; }
}
/* パッドが 出ている あいだは、ウインドウを パッドの ない ところへ よせる（たて: うえ・よこ: まんなか） */
body.pad-on { --pad-h: calc(160px + var(--safe-b)); }
body.pad-on #ui { bottom: var(--pad-h); }
body.pad-on #ui .panel, body.pad-on #ui .dialog, body.pad-on #ui .choice { max-width: calc(100% - 12px) !important; }
@media (orientation: landscape) {
  body.pad-on { --pad-h: 0px; }
  body.pad-on #ui { bottom: 0; left: calc(140px + var(--safe-l)); right: calc(84px + var(--safe-r)); }
  #pad-cross { --pk: 42px; }
  #pad-ab { width: 66px; height: 136px; }
  #pad-ab .tbtn { width: 60px; height: 60px; }
  #pad-ab .pa { right: 0; top: 0; }
  #pad-ab .pb { left: auto; right: 0; bottom: 0; }
}
body.talking .hud-obj, body.talking .hud-chat { visibility: hidden; }
body.touch .hud-chat { bottom: calc(230px + var(--safe-b)); }

/* ───── トースト・まく ───── */
#toast {
  position: absolute;
  left: 50%;
  top: calc(18% + var(--safe-t));
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
  pointer-events: none;
  z-index: 70;
}
#toast .t {
  white-space: pre-line;
  text-align: center;
  animation: toast 3.2s forwards;
}
@keyframes toast { 0% { opacity: 0; transform: translateY(8px); } 10%, 85% { opacity: 1; transform: none; } 100% { opacity: 0; } }

#curtain {
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.45s;
  z-index: 50;
}
#curtain.on { opacity: 1; }
#curtain.flash { background: #fff; transition: opacity 0.12s; }
/* ようがんの 地面で ダメージ（第3章） */
#curtain.hurt { background: #ff2a1a; opacity: 0.32; transition: opacity 0.1s; }

#fx { position: absolute; inset: 0; pointer-events: none; z-index: 55; }
.chapter {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #000;
  gap: 0.4em;
  animation: chapter 4.2s forwards;
  text-align: center;
  padding: 1em;
}
.chapter .c1 { font-size: var(--fs); color: var(--muted); letter-spacing: 0.4em; }
.chapter .c2 { font-size: calc(var(--fs) * 2); color: var(--accent); letter-spacing: 0.15em; text-shadow: 0 0 18px rgba(255, 214, 107, 0.5); }
@keyframes chapter { 0% { opacity: 0; } 15%, 85% { opacity: 1; } 100% { opacity: 0; } }
/* 第5章 Step 9: エンディングの ふりかえり（スタッフロールふう。client/ui/script.js の roll）*/
.roll { position: absolute; inset: 0; overflow: hidden; background: radial-gradient(ellipse at 50% 120%, #1a2450 0%, #070a1c 60%, #02030a 100%); pointer-events: auto; animation: rollin 1.4s forwards; }
.roll.out { animation: rollout 1.2s forwards; }
.roll-sky { position: absolute; inset: 0; }
.roll-star { position: absolute; width: 2px; height: 2px; background: #fff6d0; border-radius: 50%; box-shadow: 0 0 6px #ffe9a0; animation: rolltw 2.8s infinite alternate; }
.roll-col { position: absolute; left: 0; right: 0; top: 0; padding: 0 16px; text-align: center; will-change: transform; }
.roll-h { font-size: calc(var(--fs) * 1.15); color: var(--accent); letter-spacing: 0.08em; margin-top: 0.6em; text-shadow: 0 0 12px rgba(255, 214, 107, 0.45); }
.roll-t { font-size: var(--fs); color: #e8ecff; margin-top: 0.35em; line-height: 1.5; }
.roll-gap { height: 2.4em; }
.roll-end { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.6em; opacity: 0; transition: opacity 1.6s; text-align: center; padding: 1em; }
.roll-end.show { opacity: 1; }
.roll-end .e1 { font-size: calc(var(--fs) * 2.2); color: var(--accent); letter-spacing: 0.25em; text-shadow: 0 0 22px rgba(255, 214, 107, 0.6); }
.roll-end .e2 { font-size: var(--fs); color: var(--muted); letter-spacing: 0.2em; }
@keyframes rollin { from { opacity: 0; } to { opacity: 1; } }
@keyframes rollout { from { opacity: 1; } to { opacity: 0; } }
@keyframes rolltw { from { opacity: 0.25; } to { opacity: 1; } }

/* ───── タイトル ───── */
.title-screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.2em;
  padding: 1em;
  text-align: center;
}
.logo { display: flex; flex-direction: column; align-items: center; gap: 0.2em; }
.logo .sub { color: var(--muted); letter-spacing: 0.3em; font-size: var(--fs-small); }
.logo .main {
  font-size: clamp(34px, 9vmin, 84px);
  letter-spacing: 0.12em;
  color: #fff6d8;
  text-shadow: 0 0 2px #000, 3px 3px 0 #3c2a8c, 0 0 28px rgba(255, 214, 107, 0.55);
  line-height: 1.1;
}
.logo .crest { width: clamp(56px, 12vmin, 110px); height: auto; image-rendering: pixelated; }
.title-screen .win { min-width: min(88vw, 420px); }
.bigbtn {
  display: block;
