/* 第62回: コントローラーで 書く 文字ばん（ui/kana-pad.js） */
.center-panel.has-kpad { width: min(96vw, 620px); max-height: calc(100% - 12px); overflow-y: auto; }
.kana-pad { display: flex; flex-direction: column; gap: 0.25em; margin-top: 0.5em; }
.kp-row { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 0.25em; }
.kana-pad.num .kp-row { grid-template-columns: repeat(5, minmax(0, 1fr)); }
.kp-row.kp-tools { grid-template-columns: repeat(6, minmax(0, 1fr)); margin-top: 0.2em; }
