}

/* ───── 美容室（ui/salon.js） ───── */
.salon-panel .ct-body { grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); grid-template-rows: none; }
.salon-info { display: flex; flex-direction: column; align-items: center; gap: 0.25em; }
.salon-pv { display: flex; align-items: flex-end; justify-content: center; gap: 0.7em; }
