@media (max-height: 500px) { .stamp-panel { top: calc(48px + var(--safe-t)); max-height: calc(100% - 60px - var(--safe-t) - var(--safe-b)); } }

/* ───── メニュー ───── */
.fmenu { display: grid; grid-template-columns: minmax(8em, auto) 1fr; gap: 10px; }
