  .job-panel .job-list { max-height: calc((80vh - var(--pad-h)) * 0.4); }
  .job-panel .main { min-height: 0; height: calc((80vh - var(--pad-h)) * 0.6); max-height: calc((80vh - var(--pad-h)) * 0.6); }
  .tavern-panel .fmenu { grid-template-columns: 1fr; }
  .tavern-panel .side .menu { display: flex; flex-direction: column; }
  .tavern-panel .tavern-list { max-height: calc((68vh - var(--pad-h)) * 0.62); }
  .tavern-panel .main { min-height: 0; max-height: calc((68vh - var(--pad-h)) * 0.38); }
  .tavern-panel .menu .item.find-kid .face { height: 2.4em; }
  .breed-pv.find-pv .breed-pv-img { height: 4.2em; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .tavern-panel .fmenu { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); }
  .tavern-panel .side .menu { display: flex; flex-direction: column; }
  .tavern-panel .tavern-list, .tavern-panel .main { max-height: calc(62vh - var(--pad-h)); }
  .job-panel .fmenu { grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr); }
  /* よこむきの スマホ: メニューの こうもくは 2れつ（した に はみださない） */
  .fmenu-panel .fmenu { grid-template-columns: minmax(10.5em, auto) 1fr; }
  .fmenu-panel .fmenu .side .menu { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 0.2em; }
  .job-panel .side .menu { display: flex; flex-direction: column; }
  .job-panel .job-list, .job-panel .main { max-height: calc(64vh - var(--pad-h)); height: calc(64vh - var(--pad-h)); }
}

/* ───── お店・教会（ドラクエ風の カウンター） ───── */
.counter-panel {
  left: 50%;
  top: calc(var(--safe-t) + max(6px, 2vh));
  transform: translateX(-50%);
  width: min(96vw, 940px);
  height: min(calc(100% - 12px - 2vh - var(--safe-t) - var(--safe-b)), 680px);
  max-height: none;
  gap: 6px;
}
.counter-panel .svc-head { margin-bottom: 0; min-height: 2.8em; flex: none; }
.counter-panel .win { background: var(--win-solid); }
/* メニュー・お店などの まどは すきとおらない（うしろの 目標の まどが すけて 見えない） */
.panel .win { background: var(--win-solid); }
.ct-title { display: inline-flex; align-items: center; gap: 0.4em; }
.ct-icon { width: 1.7em; height: 1.7em; image-rendering: pixelated; flex: none; }
.ct-gold { margin-left: auto; color: var(--accent); font-size: var(--fs-small); white-space: nowrap; }
.ct-body { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 6px; }
.ct-list, .ct-info { min-height: 0; }
.ct-list.active, .ct-info.active { border-color: var(--accent); }
.ct-msg {
  position: relative;
  flex: none;
  margin-top: 1em;
  min-height: 5em;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4em 0.8em;
  align-items: flex-start;
  padding: 0.75em 1em 0.8em;
  cursor: pointer;
}
.ct-speaker {
  position: absolute;
  top: -1.35em;
  left: 0.9em;
  background: var(--win-solid);
  border: 3px solid var(--line);
  border-radius: 7px;
  padding: 0 0.6em;
  font-size: var(--fs-small);
  color: var(--accent);
}
.ct-text { flex: 1 1 12em; min-width: 0; white-space: pre-wrap; word-break: break-all; line-height: 1.6; font-size: calc(var(--fs) * 1.02); }
.ct-choice { flex: none; margin-left: auto; }
.ct-choice .menu { min-width: 6.5em; }
.ct-choice .menu .item { min-height: 2.3em; }
.ct-more { position: absolute; right: 0.8em; bottom: 0.15em; animation: blink 0.8s steps(2) infinite; color: var(--accent); }
.ct-qty { display: flex; flex-direction: column; align-items: flex-end; gap: 0.3em; }
.ct-qty-val { font-size: 1.15em; white-space: nowrap; }
.ct-qty .row { display: flex; gap: 0.3em; flex-wrap: wrap; justify-content: flex-end; }
.ct-item .hd { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 0.8em; }
.ct-item .hd .st { font-size: var(--fs-small); color: var(--good); }
.ct-item .hd .rk { font-size: var(--fs-small); color: var(--muted); }
.ct-item .detail { margin-top: 0.15em; }
.cmp-head { color: var(--accent); margin: 0.45em 0 0.15em; padding-bottom: 0.1em; border-bottom: 1px dashed rgba(255, 214, 107, 0.35); font-size: var(--fs-small); }
/* 強さの くらべ: 文字だけ・2れつ */
.cmp-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(12.5em, 1fr)); gap: 0.1em 1em; }
.cmp-row { display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 0.45em; padding: 0.08em 0; line-height: 1.3; font-size: var(--fs-small); font-variant-numeric: tabular-nums; }
.cmp-row.dis { color: #6d6c88; }
.cmp-row .nm { min-width: 3.6em; color: var(--text); }
.cmp-row.dis .nm { color: #6d6c88; }
.cmp-row .ar { font-weight: bold; }
.cmp-row .cmp-sub { color: var(--muted); font-size: 0.85em; }
/* お店の 品物の 一覧は つめて たくさん 見せる */
.ct-list { padding-top: 0; }
.ct-list .menu { row-gap: 0; }
.ct-list .menu .item { min-height: 1.75em; font-size: 0.95em; padding-top: 0; padding-bottom: 0; line-height: 1.2; }
.ct-list .menu .item .tag { font-size: 0.66em; }
.ct-list .menu .backchip { justify-self: stretch; align-self: stretch; display: flex; min-height: 2em; border-radius: 8px; margin: 0.35em 0 0.2em; box-shadow: 0 0.3em 0 0.1em var(--win-solid), 0 -0.4em 0 0.1em var(--win-solid); }
.tag.e { color: var(--accent); }
.menu .tag.up { color: var(--good); }
.menu .item .cnt { color: var(--muted); font-size: 0.8em; margin-left: 0.35em; }
.menu .item .r.dis { color: #6d6c88; }
.menu .item .r.up { color: var(--good); }
.menu .item .r.down { color: var(--danger); }
/* 装備を えらぶ まど（menu.js の equipView）: 上がる 強さ（みどり）も 下がる 強さ（赤）も、前→後で 出す */
.eq-pick .menu { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.menu .item.eq-opt { padding-top: 0.2em; padding-bottom: 0.2em; }
.menu .item.eq-opt .l { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.05em 0.8em; }
.eq-sc, .bp-st { display: inline-flex; flex-wrap: wrap; gap: 0 0.9em; font-size: var(--fs-small); font-variant-numeric: tabular-nums; line-height: 1.35; }
.eq-sc .sc, .bp-st .sc { white-space: nowrap; }
/* さいきょう装備の 見こみ（何が 何に 変わるか。「これにする／変えない」の 上） */
.bp-pop .bp-body { flex: 1 1 auto; min-height: 0; margin: 0.35em 0 0.45em; padding-right: 0.2em; }
.bp-pop .menu { flex: none; }
.bp-pop .menu .item { justify-content: center; padding-left: 1.3em; border: 1px solid rgba(255, 255, 255, 0.18); }
.bp-who { padding: 0.3em 0; border-bottom: 1px dashed rgba(255, 255, 255, 0.14); }
.bp-who:last-child { border-bottom: 0; }
.bp-name { color: var(--accent); }
.bp-ch { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 0.45em; padding-left: 0.5em; }
.bp-ch .k { color: var(--muted); min-width: 3.6em; }
.bp-ch .from { color: var(--muted); }
.bp-ch .ar { color: var(--accent); }
.bp-st { padding-left: 0.5em; margin-top: 0.1em; }
/* 預かり所・ふしぎなかじ屋（ui/bank.js・ui/forge.js） */
.menu .tag.mat { color: #9ad8ff; }
.zdrop.mat .tag { color: #9ad8ff; border-color: rgba(154, 216, 255, 0.55); }
.bank-row { display: flex; justify-content: space-between; gap: 1em; padding: 0.1em 0; border-bottom: 1px solid rgba(255, 255, 255, 0.07); font-variant-numeric: tabular-nums; }
.bank-list { margin-top: 0.3em; }
.forge-cost { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; column-gap: 1.1em; margin-top: 0.35em; font-size: var(--fs-small); font-variant-numeric: tabular-nums; line-height: 1.45; }
.forge-cost .hd { color: var(--accent); border-bottom: 1px dashed rgba(255, 214, 107, 0.35); margin-bottom: 0.1em; }
.forge-cost .n { text-align: right; }
.forge-cost .ok { color: var(--good); }
.forge-cost .ng { color: var(--danger); }
.forge-stats { display: grid; grid-template-columns: repeat(4, auto); justify-content: start; column-gap: 0.7em; margin: 0.2em 0; font-variant-numeric: tabular-nums; }
.forge-stat { display: contents; }
.forge-stat .nm { color: var(--muted); }
.forge-stat .b, .forge-stat .a { text-align: right; }
.forge-stat.chg .a { font-weight: bold; }
.forge-who { margin: 0.1em 0 0.2em; }
@media (max-width: 700px) {
  .ct-body { grid-template-columns: 1fr; grid-template-rows: minmax(0, 1.7fr) minmax(0, 1fr); }
  .ct-msg { min-height: 3.3em; margin-top: 0.9em; padding-top: 0.5em; padding-bottom: 0.45em; }
  .ct-text { line-height: 1.45; }
  .ct-choice.wide { flex-basis: 100%; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .counter-panel { top: calc(var(--safe-t) + 4px); height: calc(100% - 8px - var(--safe-t) - var(--safe-b)); }
  .counter-panel .svc-head { min-height: 2.4em; padding-top: 0.2em; padding-bottom: 0.2em; }
  .ct-msg { min-height: 3.2em; padding-top: 0.55em; padding-bottom: 0.45em; margin-top: 0.9em; }
  .ct-text { line-height: 1.4; }
}

/* ───── たたかい ───── */
#battle {
  position: absolute;
  inset: 0;
  background: #000;
  display: flex;
  flex-direction: column;
  padding: calc(6px + var(--safe-t)) calc(6px + var(--safe-r)) calc(6px + var(--safe-b)) calc(6px + var(--safe-l));
  gap: 6px;
  z-index: 20;
}
.b-top { display: flex; gap: 6px; align-items: stretch; }
.b-status { flex: 1; display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: 6px; }
.b-mem { padding: 0.25em 0.55em 0.35em; font-size: var(--fs-small); line-height: 1.35; position: relative; transition: transform 0.1s; }
.b-mem .nm { display: flex; justify-content: space-between; align-items: baseline; gap: 0.3em; white-space: nowrap; overflow: hidden; }
.b-mem .nm .nl { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.b-mem .nm .lv { color: var(--text); font-size: 0.85em; font-variant-numeric: tabular-nums; flex: none; }
.b-mem .tg { font-size: 0.72em; color: #9fd8ff; margin-left: 0.35em; }
/* HP・MP は ゲージと 数字。HP が 半分いか オレンジ、1わりいか 赤 */
.b-mem .grow { display: flex; align-items: center; gap: 0.3em; line-height: 1.25; font-variant-numeric: tabular-nums; }
.b-mem .gl { font-size: 0.72em; color: var(--muted); flex: none; width: 1.5em; }
.b-mem .gb { flex: 1; min-width: 1.2em; height: 0.5em; background: #1c1b36; border-radius: 3px; overflow: hidden; }
.b-mem .gb i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #3fcf6e, #8af0a8); transition: width 0.35s; }
.b-mem .gb.mp i { background: linear-gradient(90deg, #3f8fe8, #8fd0ff); }
.b-mem .gn { flex: none; font-size: 0.86em; text-align: right; }
.b-mem .grow.orange .gb i { background: linear-gradient(90deg, #ff8a1a, #ffc060); }
.b-mem .grow.orange .gn, .b-mem .n.orange { color: #ffa53a; }
.b-mem .grow.red .gb i { background: linear-gradient(90deg, #e02a2a, #ff7a6a); }
.b-mem .grow.red .gn, .b-mem .n.red { color: #ff5a5a; }
.b-mem .n.player { color: #b8f05a; }
.b-mem .n.player.orange { color: #ffa53a; }
.b-mem .n.player.red { color: #ff5a5a; }
.b-mem.dead { border-color: var(--danger); }
.b-mem.dead .nm, .b-mem .n.dead { color: var(--danger); }
.b-mem.me { border-color: var(--accent); }
.b-mem.ready { box-shadow: 0 0 0 2px #000, 0 0 12px rgba(255, 214, 107, 0.8); }
.b-mem.cur { border-color: #ffffff; background: rgba(60, 50, 10, 0.92); }
.b-mem.cur .nm::after { content: ' ◀'; color: var(--accent); }
.b-mem.hit { animation: hit 0.3s; }
.b-mem .sts { font-size: 0.78em; color: #d8a8ff; line-height: 1.2; }
.b-mem .sts:empty { display: none; }
@keyframes hit { 0%, 100% { transform: none; } 25% { transform: translateX(-4px); background: #5a0f0f; } 75% { transform: translateX(4px); } }
.atb { height: 0.42em; background: #1c1b36; border-radius: 3px; overflow: hidden; margin-top: 0.2em; }
.atb i { display: block; height: 100%; background: linear-gradient(90deg, #6fb7ff, #b9e3ff); }
.atb.full i { background: linear-gradient(90deg, #ffd66b, #fff2b8); }

.b-bond { width: 6.5em; padding: 0.25em 0.5em; font-size: var(--fs-small); display: flex; flex-direction: column; justify-content: center; gap: 0.2em; }
.b-bond .bb { height: 0.6em; background: #2a1830; border-radius: 4px; overflow: hidden; }
.b-bond .bb i { display: block; height: 100%; background: linear-gradient(90deg, var(--bond-a), var(--bond-b)); transition: width 0.3s; }
.b-bond.full { border-color: var(--bond-b); animation: glow 1s infinite alternate; }
@keyframes glow { to { box-shadow: 0 0 0 2px #000, 0 0 16px var(--bond-a); } }

.b-stage { flex: 1; position: relative; min-height: 0; display: flex; align-items: center; justify-content: center; }
.b-stage canvas { max-width: 100%; max-height: 100%; image-rendering: pixelated; }
.b-float { position: absolute; inset: 0; pointer-events: none; }
.dmg {
  position: absolute;
  transform: translate(-50%, -50%);
  font-size: calc(var(--fs) * 1.6);
  font-weight: bold;
  color: #fff;
  text-shadow: 2px 2px 0 #000, -2px -2px 0 #000, 2px -2px 0 #000, -2px 2px 0 #000;
  animation: dmg 1.1s forwards;
  white-space: nowrap;
}
.dmg.heal { color: var(--good); }
.dmg.crit { color: var(--accent); font-size: calc(var(--fs) * 2.1); }
.dmg.miss { color: var(--muted); }
.dmg.combo { color: var(--bond-a); font-size: calc(var(--fs) * 1.1); }
.dmg.weak { color: #ffe066; font-size: calc(var(--fs) * 0.95); margin-top: -1.5em; }
/* 第72回: 元気玉で 出した HP（小さい 水色） */
.dmg.genki { color: #a8e4ff; font-size: calc(var(--fs) * 1.05); }
@keyframes dmg { 0% { opacity: 0; transform: translate(-50%, -30%) scale(0.7); } 12% { opacity: 1; transform: translate(-50%, -60%) scale(1.15); } 70% { opacity: 1; transform: translate(-50%, -85%); } 100% { opacity: 0; transform: translate(-50%, -110%); } }
.b-banner {
  position: absolute;
  left: 50%;
  top: 14%;
  transform: translateX(-50%);
  font-size: var(--fs-big);
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  white-space: nowrap;
  animation: banner 1.6s forwards;
  pointer-events: none;
}
@keyframes banner { 0% { opacity: 0; transform: translate(-50%, 10px) scale(0.8); } 15%, 80% { opacity: 1; transform: translate(-50%, 0); } 100% { opacity: 0; } }

/* コマンドは 大きく（2れつの 大きな ボタン）、メッセージは コンパクトに */
.b-bottom { display: flex; gap: 6px; min-height: 10em; }
/* 第52回: たてむきの 大きな「← もどる」（ふだんは 出さない。@media (max-aspect-ratio: 1/1) の 中で 出す） */
.b-backbar { display: none; flex: none; justify-content: flex-start; }
.b-backbig { min-width: 40%; min-height: 2.5em; padding: 0.1em 0.8em; font-size: 1.05em; font-weight: bold; border-width: 2px; border-color: var(--accent); color: var(--accent); background: rgba(10, 12, 40, 0.92); border-radius: 10px; }
.b-backbig:active { background: rgba(255, 214, 107, 0.3); transform: scale(0.97); }
.b-cmd { flex: 2 1 0; min-width: 0; display: flex; flex-direction: column; }
.b-cmd .menu { overflow-y: auto; max-height: 12.5em; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 0.5em; align-content: start; }
.b-cmd .menu .item { min-height: 2.45em; font-size: 1.15em; }
.b-cmd .who { font-size: var(--fs); color: var(--accent); margin-bottom: 0.15em; }
.b-cmd .wait { color: var(--muted); font-size: var(--fs); }
.b-msg { flex: 1 1 0; min-width: 0; font-size: var(--fs-small); line-height: 1.5; overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; }
.b-msg .ln { white-space: pre-wrap; }
.b-msg .ln.old { color: var(--muted); }
/* 技の せつめいは 別の まど（.b-info。第27回）。上から（はみ出したら スクロール）。せつめいが ない ときは 出さない */
.b-info { display: none; flex: 1.3 1 0; min-width: 0; font-size: var(--fs-small); line-height: 1.5; overflow-y: auto; overscroll-behavior: contain; }
#battle.has-info .b-info { display: block; }
.b-info .ln { white-space: pre-wrap; }
.b-tools { position: absolute; right: calc(8px + var(--safe-r)); top: 50%; display: flex; flex-direction: column; gap: 6px; z-index: 2; }
/* 敵の 強さ（設定の「敵の強さ」。ふつう いがいの とき）: え の 左下に 小さな しるし
   （魔物は 地面の 線〈え の 高さの 86%〉の 上に 立つので、左下は あいている。上の 技の 名前の 札・おしらせとも かさならない） */
.b-foe {
  position: absolute; left: 6px; bottom: 5px; z-index: 2; pointer-events: none;
  font-size: calc(var(--fs) * 0.72); line-height: 1.3; padding: 0.05em 0.55em; letter-spacing: 0.04em; white-space: nowrap;
  color: #ffc06a; border: 2px solid currentColor; border-radius: 5px; background: rgba(10, 12, 40, 0.8); box-shadow: 0 0 0 1px #000;
}
.b-foe.r15 { color: #ff8a5a; }
.b-foe.r2 { color: #ff6a8a; }
/* 第4章 Step 7: 水の守りの歌（モルガナ 真の姿。大波が 軽く なる あいだ）: え の 右下に 小さな しるし */
.b-song {
  position: absolute; right: 6px; bottom: 5px; z-index: 2; pointer-events: none;
  font-size: calc(var(--fs) * 0.72); line-height: 1.3; padding: 0.05em 0.55em; white-space: nowrap;
  color: #bfe6ff; border: 2px solid currentColor; border-radius: 5px; background: rgba(10, 30, 60, 0.8); box-shadow: 0 0 0 1px #000;
  animation: b-song-glow 2.4s ease-in-out infinite;
}
@keyframes b-song-glow { 50% { color: #ffffff; box-shadow: 0 0 0 1px #000, 0 0 10px #9ad8f6; } }
/* 水のろうに とじこめられた 人の まど */
.b-mem.prison { box-shadow: 0 0 0 2px #000, inset 0 0 14px rgba(90, 184, 232, 0.9); background-image: linear-gradient(rgba(90, 184, 232, 0.28), rgba(46, 124, 184, 0.18)); }
.b-tools .btn { font-size: var(--fs-small); background: rgba(10, 12, 40, 0.8); }
.b-tools .btn.on { border-color: var(--accent); color: var(--accent); }
.bondjoin {
  position: absolute;
  left: 50%;
  top: 55%;
  transform: translate(-50%, -50%);
  font-size: var(--fs-big);
  padding: 0.6em 1.4em;
  border: 4px solid var(--bond-b);
  background: rgba(60, 10, 60, 0.9);
  color: #fff;
  border-radius: 14px;
  z-index: 5;
  animation: glow 0.5s infinite alternate;
}
.b-result { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(92vw, 640px); max-height: 80%; z-index: 6; }
.win.b-result { background: var(--win-solid); box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 100vmax rgba(0, 0, 0, 0.38); }
.b-result .res-lines > div { padding: 0.06em 0; transform-origin: left center; }
.b-result .res-lines > div:last-child { animation: res-in 0.16s ease-out; }
/* レベルアップの 行: きんいろに ぱっと ひかって、すこし 大きく */
.b-result .res-lines > .lvup { font-weight: bold; text-shadow: 0 0 10px rgba(255, 214, 107, 0.7); animation: lv-pop 0.9s ease-out; }
.b-result .res-lines > .res-stats { color: #ffe9b0; font-size: 0.92em; padding-left: 0.8em; }
/* つぎの 行は ボタンを おすと 出る（▼ が ちかちか） */
.b-result .res-follow { text-align: center; color: var(--muted); font-size: 0.85em; margin-top: 0.4em; }
.b-result .res-more { text-align: center; color: var(--accent); line-height: 1; height: 1em; font-size: 0.85em; opacity: 0; }
.b-result .res-more.on { opacity: 1; animation: blink 0.9s steps(2) infinite; }
@keyframes res-in { from { opacity: 0; transform: translateY(4px); } }
@keyframes lv-pop { 0% { transform: scale(1.22); filter: brightness(1.9); } 40% { transform: scale(0.98); } 100% { transform: none; filter: none; } }
/* 第31回: 1画面の けっか。レベルアップの まとめ（名前・Lv12→15！・強さ）と 覚えた 技（client/battle.js の showResult） */
.b-result .res-lines > div:last-child { animation: none; }
.b-result .res-lines > .res-grow { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.5em; margin-top: 0.18em; }
.b-result .res-grow .rg-name { font-weight: bold; }
.b-result .res-grow .rg-up { color: var(--accent); font-weight: bold; }
.b-result .res-grow .rg-st { display: flex; flex-wrap: wrap; column-gap: 0.7em; color: #ffe9b0; font-size: 0.86em; font-weight: normal; text-shadow: none; }
.b-result .res-grow .rg-st > span { white-space: nowrap; }
.b-result .res-lines > .res-job.res-grow .rg-up { color: #ffd66b; }
.b-result .res-lines > .res-learn { padding-left: 0.9em; font-size: 0.9em; }
.b-result .res-lines > .res-exp, .b-result .res-lines > .res-gold, .b-result .res-lines > .res-found { font-size: 0.92em; }
@media (max-height: 520px) and (orientation: landscape) {
  .b-result { max-height: 92%; padding-top: 0.35em; padding-bottom: 0.2em; }
  .b-result .res-lines { font-size: 0.9em; line-height: 1.3; }
}

/* たてむき（スマホを たてに もつ）: え は よこいっぱい、メッセージは まんなか、コマンドは したで おおきく */
@media (max-aspect-ratio: 1/1) {
  .b-top { flex-direction: column; }
  .b-status { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .b-bond { width: 100%; flex-direction: row; align-items: center; }
  .b-bond .bb { flex: 1; }
  .b-stage { flex: 0 0 auto; height: calc((100vw - 12px - var(--safe-l) - var(--safe-r)) * 0.5625); max-height: 42vh; }
  .b-bottom { flex: 1; flex-direction: column-reverse; min-height: 0; }
  .b-cmd { width: 100%; flex: 1 1 auto; min-height: 0; }
  .b-cmd .menu { max-height: none; flex: 1; min-height: 0; }
  /* 第61回: 技の 字は 大きく、行は すこし うすく（たくさん 見える） */
  .b-cmd .menu .item { min-height: 2.45em; font-size: 1.3em; }
  /* 5人の ときは 3人＋2人の 2だん（4人の ときと おなじ たかさ。コマンドが せまく ならない） */
  .b-status[data-n="5"] { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; }
  .b-status[data-n="5"] .b-mem { grid-column: span 2; padding-left: 0.4em; padding-right: 0.4em; }
  .b-status[data-n="5"] .b-mem:nth-child(n + 4) { grid-column: span 3; }
  .b-status[data-n="5"] .b-mem:nth-child(-n + 3) .tg { display: none; }
  .b-status[data-n="5"] .b-mem:nth-child(-n + 3) .gl { display: none; }
  /* メッセージは 3行ぶん だけ */
  .b-msg { flex: none; height: 5.6em; min-height: 0; }
  /* 第52回: もどれる ときは コマンドの わくの 外・左下に 大きな「← もどる」（わくの 中の 小さい もどるは かくす） */
  #battle.has-back .b-backbar { display: flex; }
  /* 第54回: たてに みじかい 画面では もっと うすく（技の 一覧を つぶさない） */
  /* 第61回: 小さく（左下の わくの 外なので まちがえて おさない） */
  .b-backbig { min-width: 26%; min-height: 32px; padding: 0 0.8em; font-size: 0.9em; border-width: 1.5px; border-radius: 8px; }
  @media (max-height: 700px) { .b-backbig { min-height: 30px; } }
  #battle.has-back .b-cmd .menu .backchip, #battle.has-back .b-tabs .bt-back { display: none; }
  .b-tools { top: 6px; transform: none; }
}

/* ───── ぜんたいマップ ───── */
.worldmap { display: flex; flex-direction: column; align-items: center; gap: 0.4em; }
.worldmap canvas { max-width: 86vw; max-height: calc(72vh - var(--pad-h)); image-rendering: pixelated; border-radius: 6px; }

/* ───── ちいさい がめん ───── */
@media (max-height: 460px) {
  :root { --fs: clamp(12px, 2vmin + 6px, 17px); }
  .b-bottom { min-height: 6.8em; }
  .b-cmd .menu { max-height: 7.2em; }
  .b-cmd .menu .item { min-height: 2.1em; }
}

/* よこむきの スマホ: もくひょう・チャットは した まんなか（スティックと ボタンの あいだ）に。キャラに かさならない */
@media (orientation: landscape) and (max-height: 520px) {
  body.touch .hud-obj {
    left: 50%;
    bottom: calc(8px + var(--safe-b));
    transform: translateX(-50%);
    max-width: min(50vw, 460px);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  body.touch .hud-chat { left: 50%; transform: translateX(-50%); bottom: calc(3.4em + var(--safe-b)); max-width: min(50vw, 460px); }
  /* はしるボタンは B の うえ（メニューの ボタンと かさならない） */
  #btn-run { right: calc(104px + var(--safe-r)); bottom: calc(102px + var(--safe-b)); }
  /* メニュー・チャット・スタンプは ちずの ひだりに よこならび（A・B・走るの ボタンと かさならない） */
  .hud-btns { flex-direction: row; top: calc(8px + var(--safe-t)); right: calc(clamp(90px, 18vmin, 170px) + 28px + var(--safe-r)); }
  .hud-party { max-width: calc(100vw - clamp(90px, 18vmin, 170px) - 20em - 48px - var(--safe-l) - var(--safe-r)); }
  .hud-area { top: calc(3.4em + var(--safe-t)); }
  .hud-mem { min-width: 5.6em; }
}

/* はなしている あいだは スティックと ボタンを しまう（がめんの どこを タップしても すすむ） */
body.talking #touch { display: none; }
.talk-catcher { position: absolute; inset: 0; background: transparent; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

/* なかまに なりたそうな モンスター */
.mon-pop {
  position: absolute; left: 50%; top: 22%; transform: translate(-50%, -50%);
  padding: 0.8em 1.4em; z-index: 3; display: flex; align-items: center; justify-content: center;
  animation: monpop 0.5s ease-out, monbob 1.4s ease-in-out 0.5s infinite;
}
.mon-pop canvas { image-rendering: pixelated; display: block; }
@keyframes monpop { from { transform: translate(-50%, -30%) scale(0.6); opacity: 0; } to { transform: translate(-50%, -50%) scale(1); opacity: 1; } }
@keyframes monbob { 0%, 100% { transform: translate(-50%, -50%); } 50% { transform: translate(-50%, -54%); } }
body.talking .mon-pop { top: 26%; }

/* 紋章が ひかる */
.crest-fx {
  position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%);
  pointer-events: none; z-index: 30;
}
.crest-fx canvas {
  width: min(46vmin, 260px); height: min(46vmin, 260px); image-rendering: pixelated; display: block;
  animation: crest 1.8s ease-out forwards;
  filter: drop-shadow(0 0 18px rgba(255, 214, 107, 0.95)) drop-shadow(0 0 40px rgba(255, 240, 200, 0.7));
}
@keyframes crest {
  0% { transform: scale(0.2) rotate(-30deg); opacity: 0; }
  30% { transform: scale(1.05) rotate(0deg); opacity: 1; }
  70% { transform: scale(1) rotate(0deg); opacity: 1; }
  100% { transform: scale(1.5) rotate(10deg); opacity: 0; }
}

/* ───── みかたの まどの えんしゅつ（たたかい） ───── */
.afx { position: absolute; inset: 0; pointer-events: none; border-radius: inherit; overflow: hidden; z-index: 2; }
.afx-claw::before, .afx-claw::after {
  content: ''; position: absolute; left: calc(50% - 2.4em); width: 4.8em; top: -10%; bottom: -10%;
  background: repeating-linear-gradient(115deg, transparent 0 10px, rgba(255, 90, 90, 0.95) 10px 13px, #ffffff 13px 14px, transparent 14px 26px);
  transform-origin: left top; animation: afx-claw 0.45s ease-out forwards;
}
.afx-claw::after { background: rgba(255, 60, 60, 0.35); left: 0; right: 0; width: auto; animation: afx-fade 0.45s ease-out forwards; }
@keyframes afx-claw { 0% { clip-path: inset(0 100% 100% 0); opacity: 1; } 45% { clip-path: inset(0 0 0 0); opacity: 1; } 100% { clip-path: inset(0 0 0 0); opacity: 0; } }
@keyframes afx-fade { 0% { opacity: 1; } 100% { opacity: 0; } }
.afx-fire { background: radial-gradient(ellipse at 50% 120%, rgba(255, 230, 120, 0.95), rgba(255, 120, 40, 0.8) 40%, rgba(200, 40, 20, 0) 75%); animation: afx-rise 0.8s ease-out forwards; }
.afx-ice { background: linear-gradient(160deg, rgba(230, 251, 255, 0.9), rgba(120, 200, 255, 0.55) 45%, rgba(90, 184, 232, 0.2)); animation: afx-fade 0.8s ease-out forwards; }
.afx-ice::before { content: '✦ ✧ ✦'; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: #ffffff; font-size: 1.2em; text-shadow: 0 0 6px #9ae6ff; }
.afx-wind { background: repeating-linear-gradient(170deg, transparent 0 8px, rgba(216, 255, 224, 0.75) 8px 10px, transparent 10px 18px); animation: afx-wind 0.6s ease-out forwards; }
@keyframes afx-wind { 0% { transform: translateX(-40%); opacity: 1; } 100% { transform: translateX(40%); opacity: 0; } }
.afx-dark { background: radial-gradient(circle at 50% 50%, rgba(200, 168, 240, 0.7), rgba(90, 42, 138, 0.65) 55%, rgba(20, 0, 40, 0.3)); animation: afx-fade 0.8s ease-out forwards; }
.afx-bolt { background: linear-gradient(100deg, transparent 38%, rgba(255, 251, 224, 0.95) 45%, rgba(154, 216, 255, 0.9) 50%, transparent 57%), rgba(255, 246, 176, 0.25); animation: afx-flicker 0.5s steps(2) forwards; }
@keyframes afx-flicker { 0% { opacity: 1; } 50% { opacity: 0.3; } 70% { opacity: 1; } 100% { opacity: 0; } }
.afx-quake { background: linear-gradient(0deg, rgba(160, 128, 96, 0.85), rgba(160, 128, 96, 0) 60%); animation: afx-fade 0.7s ease-out forwards; }
.afx-heal { background: radial-gradient(ellipse at 50% 100%, rgba(125, 255, 176, 0.6), rgba(125, 255, 176, 0) 70%); animation: afx-fade 0.9s ease-out forwards; }
.afx-heal::before, .afx-heal::after {
  content: '＋'; position: absolute; left: 22%; bottom: 0; color: #d8ffe8; font-size: 1.1em; text-shadow: 0 0 6px #7dffb0;
  animation: afx-up 0.9s ease-out forwards;
}
.afx-heal::after { left: 66%; animation-delay: 0.15s; }
.afx-revive { background: linear-gradient(90deg, rgba(255, 246, 176, 0) 20%, rgba(255, 246, 176, 0.9) 50%, rgba(255, 246, 176, 0) 80%); animation: afx-rise 0.9s ease-out forwards; }
.afx-poison { background: radial-gradient(circle at 30% 70%, rgba(176, 106, 224, 0.8) 0 6%, transparent 7%), radial-gradient(circle at 60% 50%, rgba(176, 106, 224, 0.8) 0 5%, transparent 6%), radial-gradient(circle at 80% 80%, rgba(216, 168, 255, 0.8) 0 4%, transparent 5%), rgba(122, 58, 168, 0.3); animation: afx-rise 0.9s ease-out forwards; }
.afx-up, .afx-down, .afx-sleep {
  display: flex; align-items: center; justify-content: center; font-size: 1.05em; letter-spacing: 0.1em;
  text-shadow: 2px 2px 0 #000;
}
.afx-up { color: #ffd66b; background: rgba(255, 214, 107, 0.18); animation: afx-up 0.9s ease-out forwards; }
.afx-down { color: #c8a8f0; background: rgba(138, 90, 200, 0.2); animation: afx-down 0.9s ease-out forwards; }
.afx-sleep { color: #ffffff; background: rgba(247, 200, 232, 0.25); animation: afx-up 1s ease-out forwards; }
.afx-shield { border: 3px solid rgba(143, 208, 255, 0.95); box-shadow: inset 0 0 14px rgba(143, 208, 255, 0.8); animation: afx-fade 0.9s ease-out forwards; }
.afx-charge { box-shadow: inset 0 0 18px rgba(255, 90, 60, 0.95); animation: afx-pulse 0.9s ease-out forwards; }
@keyframes afx-rise { 0% { transform: translateY(40%); opacity: 1; } 100% { transform: translateY(-30%); opacity: 0; } }
@keyframes afx-up { 0% { transform: translateY(35%); opacity: 0; } 25% { opacity: 1; } 100% { transform: translateY(-45%); opacity: 0; } }
@keyframes afx-down { 0% { transform: translateY(-35%); opacity: 0; } 25% { opacity: 1; } 100% { transform: translateY(45%); opacity: 0; } }
@keyframes afx-pulse { 0%, 100% { opacity: 0; } 30%, 60% { opacity: 1; } }

/* 強さ: 全員を 一覧で くらべる */
.allstat-wrap { overflow-x: auto; margin: 0.3em 0; }
.allstat { border-collapse: collapse; font-size: var(--fs-small); font-variant-numeric: tabular-nums; min-width: 100%; }
.allstat th, .allstat td { padding: 0.1em 0.45em; text-align: right; white-space: nowrap; border-bottom: 1px solid rgba(255, 255, 255, 0.08); }
.allstat tr > th:first-child { text-align: left; color: var(--muted); font-weight: normal; position: sticky; left: 0; background: #05071a; }
.allstat tr:first-child th { text-align: center; vertical-align: bottom; font-weight: normal; }
.allstat .face { height: 1.9em; width: auto; image-rendering: pixelated; display: block; margin: 0 auto; }
.allstat .nm { font-size: 1em; line-height: 1.2; }
.allstat .jb { color: var(--muted); font-size: 0.8em; line-height: 1.1; }
.allstat td.gold { color: var(--accent); font-weight: bold; }

/* たたかいの コマンド: 1つずつ わくで かこむ。えらんでいる もの・おした ものが 分かるように */
.b-cmd .menu { row-gap: 0.3em; padding: 0.1em; }
.b-cmd .menu .item {
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  padding: 0.1em 0.5em;
  transition: background 0.08s, transform 0.08s;
}
.b-cmd .menu .item::before { display: none; }
/* なまえは 1行（入りきらない ときは ListMenu の fit が 文字を 小さく する。2行に なって わくから はみ出さない） */
.menu.fit .item > .l { white-space: nowrap; overflow: hidden; min-width: 0; flex: 1 1 auto; }
.menu.fit .item > .l.wf { flex-wrap: nowrap; }
.menu.fit .item > .r { flex: none; }
.menu.fit .item .tag, .menu.fit .item .elem, .menu.fit .item .cnt { white-space: nowrap; }
/* コマンドの わくの 中では 属性・「他」の しるしを 小さめに（名前が 2行に なりにくい） */
.b-cmd .menu .elem { font-size: 0.64em; padding: 0 0.22em; margin-right: 0.22em; }
.b-cmd .menu .tag { margin-left: 0.18em; padding: 0 0.22em; }
/* 相手の しるし（グループ・全体・全員）と グループの かず */
.menu .tag.tgt { color: #9ad8ff; font-size: 0.62em; }
.menu .tag.tgt.t-enemies { color: #ffb4a3; }
.menu .tag.tgt.t-allies, .menu .tag.tgt.t-deadAllies { color: #9af0b0; }
.menu .tag.tgt.t-random { color: #e4c2ff; }
.b-cmd .menu .cnt { font-size: 0.8em; color: var(--muted); margin-left: 0.1em; display: inline-block; white-space: nowrap; }
.b-cmd .menu .item.sel { background: rgba(255, 214, 107, 0.16); box-shadow: 0 0 0 2px var(--accent); border-color: var(--accent); }
.b-cmd .menu .item.press { background: rgba(255, 214, 107, 0.45); transform: scale(0.95); }
.b-cmd .menu .item.dis { border-style: dashed; border-color: rgba(255, 255, 255, 0.15); }
.b-cmd .menu .backchip { border-radius: 8px; }
/* 技の 種類の 色: ダメージ＝赤 回復＝緑 補助＝青 */
.b-cmd .menu .item.k-dmg { border-color: rgba(255, 128, 104, 0.75); }
.b-cmd .menu .item.k-heal { border-color: rgba(112, 224, 136, 0.75); }
.b-cmd .menu .item.k-sup { border-color: rgba(112, 176, 255, 0.75); }
.b-cmd .menu .item.k-dmg .l, .menu .item.k-dmg .l { color: #ffb4a3; }
.b-cmd .menu .item.k-heal .l, .menu .item.k-heal .l { color: #b3f2bf; }
.b-cmd .menu .item.k-sup .l, .menu .item.k-sup .l { color: #b8d6ff; }
.b-cmd .menu .item.sel.k-dmg, .b-cmd .menu .item.sel.k-heal, .b-cmd .menu .item.sel.k-sup { border-color: var(--accent); }
.menu .item.dis .l { opacity: 0.55; }
/* 属性の しるし */
.elem { display: inline-block; font-size: 0.72em; line-height: 1.35; padding: 0 0.3em; margin-right: 0.35em; border-radius: 4px; color: #111; font-weight: bold; vertical-align: 0.12em; }
.elem.e-fire { background: #ff7a4a; }
.elem.e-ice { background: #8ad8ff; }
.elem.e-water { background: #4f8cff; }
.elem.e-wind { background: #7fe08a; }
.elem.e-blast { background: #ffb13d; }
.elem.e-bolt { background: #ffe34d; }
.elem.e-light { background: #fff6c8; }
.elem.e-dark { background: #b58cff; }
.elem.e-void { background: #cfcfe0; }
.aff { font-size: 0.8em; margin-left: 0.3em; }
/* ねらう 相手の 下に 出す 効きぐあい */
.aff-line { display: block; font-size: 0.66em; line-height: 1.15; color: var(--muted); }
.aff-line.a-weak { color: var(--accent); font-weight: bold; }
.aff-line.a-null { color: var(--warn); }
.aff-line.a-normal { color: var(--text); }
.aff-line.a-stance { color: #ffa22a; font-weight: bold; }
.aff.weak { color: var(--accent); font-weight: bold; }
.aff.resist { color: var(--muted); }
.aff.null { color: var(--warn); }

/* 図鑑: 属性の 得手不得手 */
.zukan-aff { display: flex; flex-wrap: wrap; gap: 0.25em 0.55em; align-items: center; margin-top: 0.3em; }
.zaff { white-space: nowrap; }
.zaff .elem { margin-right: 0.15em; }
.zaff.weak { color: var(--accent); font-weight: bold; }
.zaff.resist { color: var(--muted); }
.zaff.null { color: var(--warn); }
.zaff.unk { color: #6d6c88; }
.zukan-drops { display: flex; flex-wrap: wrap; gap: 0.25em 0.7em; align-items: center; margin-top: 0.3em; }
.zdrop { white-space: nowrap; display: inline-flex; align-items: center; gap: 0.25em; }
.zdrop .tag { font-size: 0.78em; padding: 0 0.35em; border-radius: 6px; border: 1px solid rgba(255, 255, 255, 0.25); color: var(--muted); }
.zdrop.rare .tag { color: #ffd66b; border-color: rgba(255, 214, 107, 0.6); }
.zdrop.boss .tag { color: #ff9ad0; border-color: rgba(255, 154, 208, 0.6); }
.zdrop.unk { color: #6d6c88; }
/* 仲間に なりやすさ（4つの 目もりと ことば。なりにくい ほど 色が おちつく） */
.zukan-join { display: flex; flex-wrap: wrap; align-items: center; gap: 0.2em 0.5em; margin-top: 0.25em; }
.join-meter { display: inline-flex; gap: 0.2em; }
.join-meter i { display: block; width: 0.62em; height: 0.62em; border-radius: 50%; border: 1px solid rgba(255, 214, 107, 0.7); box-sizing: border-box; }
.join-meter i.on { background: var(--accent); border-color: var(--accent); }
.join-t { white-space: nowrap; }
.join-t.j4 { color: var(--good); }
.join-t.j3 { color: var(--text); }
.join-t.j2 { color: var(--warn); }
.join-t.j1 { color: var(--danger); }

/* ───── たたかい: だれが 何を したか（技の 名前の 札） ───── */
.b-plate {
  position: absolute; left: 50%; top: 4px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 0.45em; max-width: 94%;
  padding: 0.2em 0.9em; border-radius: 999px; border: 2px solid #9ad8ff;
  background: rgba(6, 12, 40, 0.9); font-size: var(--fs); white-space: nowrap; z-index: 3;
  animation: plate 0.18s ease-out; pointer-events: none;
}
.b-plate .who { color: #cfe8ff; overflow: hidden; text-overflow: ellipsis; }
.b-plate .what { color: #ffffff; font-weight: bold; }
.b-plate .what::before { content: '▶ '; color: #9ad8ff; font-weight: normal; }
.b-plate .ai { font-size: 0.7em; color: #9fd8ff; border: 1px solid currentColor; border-radius: 4px; padding: 0 0.3em; }
.b-plate.enemy { border-color: #ff7a6a; background: rgba(40, 6, 10, 0.9); }
.b-plate.enemy .who { color: #ffc8c0; }
.b-plate.enemy .what::before { color: #ff7a6a; }
.b-plate.hira { border-color: #ffe066; background: rgba(50, 40, 0, 0.92); }
.b-plate.hira .what { color: #ffe066; }
.b-plate.dual { border-color: #ffd66b; background: linear-gradient(90deg, rgba(60, 20, 80, 0.94), rgba(80, 50, 0, 0.94)); }
.b-plate.dual .what { color: #ffd66b; }
@keyframes plate { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }

/* ひらめきの 電球と 大きな 文字 */
.b-mem .bulb {
  position: absolute; left: 50%; top: -0.2em; width: 2.1em; height: 2.6em; transform: translateX(-50%);
  filter: drop-shadow(0 0 6px #fff6b0) drop-shadow(0 0 14px #ffd66b); animation: bulb 2s ease-out forwards; z-index: 4; pointer-events: none;
}
@keyframes bulb { 0% { opacity: 0; transform: translate(-50%, 8px) scale(0.4); } 15% { opacity: 1; transform: translate(-50%, -4px) scale(1.25); } 25% { transform: translate(-50%, 0) scale(1); } 85% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -10px); } }
.b-hira {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.2em;
  background: radial-gradient(circle, rgba(255, 246, 176, 0.35), rgba(0, 0, 0, 0) 65%); z-index: 4; pointer-events: none;
  animation: hira 1.7s ease-out forwards;
}
.b-hira .h0 { width: 3.2em; height: 4em; filter: drop-shadow(0 0 10px #fff6b0); animation: bulb2 0.6s ease-out; }
.b-hira .h1 { font-size: var(--fs); color: #fff; text-shadow: 2px 2px 0 #000; }
.b-hira .h2 { font-size: calc(var(--fs-big) * 1.25); color: #ffe066; font-weight: bold; text-shadow: 3px 3px 0 #000, 0 0 16px #ffd66b; letter-spacing: 0.08em; }
@keyframes hira { 0% { opacity: 0; } 12% { opacity: 1; } 80% { opacity: 1; } 100% { opacity: 0; } }
@keyframes bulb2 { 0% { transform: scale(0.3) rotate(-20deg); } 60% { transform: scale(1.3) rotate(8deg); } 100% { transform: scale(1) rotate(0); } }

/* 合体技の カットイン */
.b-dual { position: absolute; inset: 0; overflow: hidden; z-index: 4; pointer-events: none; animation: hira 1.5s ease-out forwards; }
.b-dual .rays {
  position: absolute; inset: -50%;
  background: repeating-conic-gradient(from 0deg, rgba(255, 214, 107, 0.28) 0deg 6deg, rgba(120, 60, 200, 0.18) 6deg 14deg);
  animation: rays 1.5s linear;
}
@keyframes rays { to { transform: rotate(40deg); } }
.b-dual .l, .b-dual .r { position: absolute; top: 18%; display: flex; flex-direction: column; align-items: center; gap: 0.1em; color: #fff; text-shadow: 2px 2px 0 #000; }
.b-dual .l { left: 6%; animation: inl 0.35s ease-out; }
.b-dual .r { right: 6%; animation: inr 0.35s ease-out; }
.b-dual .cf { height: 42%; min-height: 3.2em; max-height: 7em; width: auto; image-rendering: pixelated; filter: drop-shadow(0 0 8px #ffd66b); }
.b-dual .nm { position: absolute; left: 50%; bottom: 12%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; white-space: nowrap; animation: pop 0.4s 0.2s ease-out both; }
.b-dual .nm small { font-size: var(--fs-small); color: #ffe9b0; text-shadow: 2px 2px 0 #000; }
.b-dual .nm b { font-size: calc(var(--fs-big) * 1.3); color: #ffd66b; text-shadow: 3px 3px 0 #000, 0 0 18px #ff9a3a; letter-spacing: 0.06em; }
@keyframes inl { from { transform: translateX(-160%); } to { transform: none; } }
@keyframes inr { from { transform: translateX(160%); } to { transform: none; } }
@keyframes pop { from { opacity: 0; transform: translateX(-50%) scale(0.4); } to { opacity: 1; transform: translateX(-50%) scale(1); } }

/* 合体技の コマンド・さそい */
.b-cmd .menu .item.k-dual { border-color: #ffd66b; background: linear-gradient(90deg, rgba(120, 60, 200, 0.25), rgba(255, 214, 107, 0.12)); }
.dual-cmd { color: #ffd66b; font-weight: bold; }
.with-line { display: block; font-size: 0.66em; line-height: 1.15; color: #ffe9b0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.menu .tag.hira { color: #ffe066; }
.dual-invite {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 6;
  width: min(92%, 26em); display: flex; flex-direction: column; gap: 0.25em; border-color: #ffd66b; background: rgba(20, 10, 40, 0.97);
}
.dual-invite .di-t { color: #fff; }
.dual-invite .di-n { color: #ffd66b; font-size: var(--fs-big); font-weight: bold; }
.dual-invite .di-d { color: var(--muted); font-size: var(--fs-small); }
.dual-invite .di-bar { height: 0.4em; background: #2a2450; border-radius: 3px; overflow: hidden; }
.dual-invite .di-bar i { display: block; height: 100%; width: 100%; background: #ffd66b; transform-origin: left; animation: dibar linear forwards; }
@keyframes dibar { to { transform: scaleX(0); } }
.dual-invite .menu { display: grid; grid-template-columns: 1fr 1fr; gap: 0.4em; }

/* ───── 戦いの 見ための 設定（設定 → 戦いの 文字の 大きさ・コマンドの 数） ───── */
#battle { --bcmd-fs: 1em; --bcmd-h: 2.15em; --bcols: 2; }
body.bf-s #battle { --bcmd-fs: 0.88em; --bcmd-h: 1.95em; }
body.bf-l #battle { --bcmd-fs: 1.15em; --bcmd-h: 2.5em; }
body.bd-1 #battle { --bcmd-h: 2.6em; }
body.bd-3 #battle { --bcols: 3; --bcmd-h: 1.9em; }
#battle .b-cmd .menu { grid-template-columns: repeat(var(--bcols), minmax(0, 1fr)); }
#battle .b-cmd .menu .item { min-height: var(--bcmd-h); font-size: var(--bcmd-fs); }
body.bd-3 #battle .b-cmd .menu .item { font-size: calc(var(--bcmd-fs) * 0.9); padding-left: 0.3em; padding-right: 0.3em; }
@media (max-aspect-ratio: 1/1) {
  #battle .b-cmd .menu .item { min-height: calc(var(--bcmd-h) * 1.08); font-size: calc(var(--bcmd-fs) * 1.04); }
}

/* 行動ゲージは モノクロ（HP・MP の 色と まざらない） */
.atb { background: #16161c; }
.atb i { background: linear-gradient(90deg, #8e8e8e, #dcdcdc); }
.atb.full i { background: #ffffff; box-shadow: 0 0 6px rgba(255, 255, 255, 0.7); }

/* お気に入りの まど（戦いの 呪文・特技） */
.b-cmd .menu .hdr { grid-column: 1 / -1; font-size: 0.8em; color: var(--muted); padding: 0.15em 0.2em 0; letter-spacing: 0.05em; }
.b-cmd .menu .hdr.fav-h { color: var(--accent); border-bottom: 1px solid rgba(255, 214, 107, 0.4); }
.b-cmd .menu .hdr.all-h { margin-top: 0.3em; border-bottom: 1px solid rgba(255, 255, 255, 0.18); }
.b-cmd .menu .item.fav { background: rgba(255, 214, 107, 0.07); }
.b-info { position: relative; }
.b-info .favbtn { font-size: 0.85em; padding: 0.1em 0.6em; min-height: 0; }
.b-cmd .menu .item.k-bond { border-color: var(--accent); white-space: nowrap; }
.b-info .favbtn.on { border-color: var(--accent); color: var(--accent); }
/* 合体技の よやく */
.b-cmd .menu .item.later { opacity: 0.85; border-style: dashed; }
.b-cmd .menu .item.auto-dual { grid-column: 1 / -1; min-height: 1.8em; }
.b-cmd .dual-cancel { margin-top: 0.4em; align-self: flex-start; }

/* ───── メニューの 上: パーティーの HP・MP・Lv と 所持金（ドラクエ風。重ならない） ───── */
body.menu-open #hud { visibility: hidden; }
.fm-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "party close" "party gold";
  align-items: start;
  gap: 0.25em 0.8em;
  padding-right: 0.7em;
}
.fmenu-panel .fm-head { flex: none; }
.fmenu-panel .fmenu { min-height: 0; flex: 1 1 auto; }
.fm-head .closebtn { position: static; transform: none; grid-area: close; justify-self: end; }
.fm-party { grid-area: party; display: grid; grid-template-columns: repeat(auto-fill, minmax(4.8em, 1fr)); gap: 0.15em 0; font-size: var(--fs-small); min-width: 0; line-height: 1.35; }
.fm-mem { min-width: 0; padding: 0 0.55em; border-left: 1px solid rgba(255, 255, 255, 0.16); }
.fm-mem:first-child { border-left: 0; padding-left: 0.1em; }
.fm-mem .n { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text); }
.fm-mem .v { display: flex; justify-content: space-between; gap: 0.3em; font-variant-numeric: tabular-nums; white-space: nowrap; }
.fm-mem .k { color: var(--muted); }
.fm-mem .orange { color: #ffa53a; }
.fm-mem .red { color: #ff5a5a; }
.fm-mem.dead .n, .fm-mem.dead .v { color: #8a8aa0; }
.fm-gold { grid-area: gold; justify-self: end; align-self: end; white-space: nowrap; font-size: var(--fs-small); font-variant-numeric: tabular-nums; }
.fm-gold .k { color: var(--muted); margin-right: 0.5em; }
.fm-gold .g { color: var(--accent); }
/* HP の バー（ふだんは 出さない。下の 小さい 表示だけ） */
.fm-mem .hpb { display: none; height: 3px; margin: 0.1em 0 0.12em; background: rgba(255, 255, 255, 0.14); border-radius: 2px; overflow: hidden; }
.fm-mem .hpb > i { display: block; height: 100%; background: var(--good); }
.fm-mem .hpb.orange > i { background: #ff9a2a; }
.fm-mem .hpb.red > i { background: #ff4a4a; }
/* 第50回 A: 4人いじょうの 旅（スマホの たて）… 体力表示を 小さく して、メニューの コマンドを ひろく。
   所持金と 閉じるは 上の 1行、メンバーは よこ 1列（名前・H・バー・M。Lv は 強さの 画面で） */
@media (max-width: 700px) and (orientation: portrait) {
  .fm-head.many { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "gold close" "party party"; gap: 0.15em 0.6em; padding: 0.3em 0.55em 0.4em; min-height: 0; }
  .fm-head.many .closebtn { min-height: 30px; padding: 0 0.75em; font-size: var(--fs-small); }
  .fm-head.many .fm-gold { justify-self: start; align-self: center; }
  .fm-head.many .fm-party { grid-template-columns: repeat(var(--n, 5), minmax(0, 1fr)); line-height: 1.22; }
  .fm-head.many .fm-mem { padding: 0.05em 0.4em 0; }
  .fm-head.many .fm-mem:first-child { padding-left: 0.1em; }
  .fm-head.many .fm-mem .n { font-size: 0.94em; }
  .fm-head.many .fm-mem .lv { display: none; }
  .fm-head.many .fm-mem .hpb { display: block; }
  /* コマンドの 一覧は つぶさない（高さが 足りない ときは 下の せつめいの まどを ちぢめる。文字が 大きい 時も） */
  .fmenu-panel:not(.sub-open) .fmenu { display: flex; flex-direction: column; }
  .fmenu-panel:not(.sub-open) .fmenu .side { flex: none; max-height: none; overflow: visible; }
  .fmenu-panel:not(.sub-open) .fmenu .main { flex: 0 1 calc(54vh - var(--pad-h)); height: auto; min-height: 4.5em; }
}
.sort-tabs { align-items: center; }
.sort-tabs .btn { padding: 0.1em 0.7em; min-height: 32px; }
.sort-tabs .btn.on { border-color: var(--accent); color: var(--accent); }
.qdot { display: inline-block; width: 0.8em; height: 0.8em; border: 2px solid #000; border-radius: 50%; }
.qdot.qmain { background: #ff5fd2; transform: rotate(45deg); border-radius: 2px; }
.qdot.sub { background: #5fd8ff; }
.qdot.ready { background: #7dff8a; }
.q-main { display: flex; gap: 0.45em; align-items: baseline; }
.kv .qdot, .q-main .qdot { margin-right: 0.4em; vertical-align: -0.05em; flex: none; }
/* お店の くらべ: パーティー 全員を 1人 1行で（装備できない 人も 変化なしで 出す） */
.cmp-list { display: flex; flex-direction: column; }
.cmp-list .cmp-row { display: grid; grid-template-columns: 4.6em minmax(0, 1fr) auto; align-items: baseline; column-gap: 0.5em; padding: 0.1em 0; border-bottom: 1px solid rgba(255, 255, 255, 0.07); flex-wrap: nowrap; }
.cmp-list .cmp-row .nm { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.cmp-list .cmp-row .st { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.cmp-list .cmp-row .st .cmp-sub { margin-left: 0.6em; }
.cmp-list .cmp-row .no { grid-column: 2 / -1; color: #7a7990; }
.cmp-list .cmp-row .tag.e { justify-self: start; }
@media (max-width: 700px) {
  .ct-body { grid-template-rows: minmax(0, 1.2fr) minmax(0, 1fr); }
  .ct-item .detail { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
}
body:has(#ui .counter-panel) #hud, body:has(#ui .worldmap) #hud { visibility: hidden; }

/* ═════ おとなも 子どもも なじめる 見ため（ドラクエ風） ═════
   細い 白わく・小さい 角・ひかえめな 色・白い カーソル。字は くっきりした ゴシック（設定で 丸ゴシック・ドット） */
:root {
  --win: rgba(5, 7, 22, 0.9);
  --win-solid: #06081a;
  --line: #ecebf3;
  --muted: #a4a3bd;
  --radius: 6px;
  --font-ui: 'KizunaGothic', 'Hiragino Kaku Gothic ProN', 'Hiragino Sans', 'Yu Gothic', 'Meiryo', sans-serif;
}
body.round-font { --font-ui: 'KizunaRound', 'Hiragino Maru Gothic ProN', 'Hiragino Sans', 'Yu Gothic', 'Meiryo', sans-serif; }
body.dot-font { --font-ui: 'KizunaDot', 'Hiragino Kaku Gothic ProN', 'Hiragino Sans', 'Yu Gothic', 'Meiryo', sans-serif; }
.win {
  border-width: 2px;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.75), 0 4px 16px rgba(0, 0, 0, 0.42);
}
.win h2, .win h3 { letter-spacing: 0.08em; }
.btn { border-width: 1px; border-radius: 4px; background: #0e1030; }
.btn.sel { background: #22254f; }
.closebtn { border-width: 1px; border-radius: 4px; min-height: 36px; }
.menu .item { border-radius: 3px; }
.menu .item.sel { background: rgba(255, 255, 255, 0.07); }
.menu .item.sel::before { border-left-color: #ffffff; }
.menu .backchip { border-width: 1px; border-radius: 4px; min-height: 34px; }
.menu .backchip:hover, .menu .backchip:active { border-color: #fff; color: #fff; }
/* たたかいの コマンド: 細い わく。えらんでいる ものは 白く 光る */
.b-cmd .menu .item { border-width: 1px; border-radius: 4px; background: rgba(255, 255, 255, 0.03); }
.b-cmd .menu .item.sel { background: rgba(255, 255, 255, 0.11); box-shadow: 0 0 0 1px #fff; border-color: #fff; }
.b-cmd .menu .item.sel.k-dmg, .b-cmd .menu .item.sel.k-heal, .b-cmd .menu .item.sel.k-sup { border-color: #fff; }
.b-cmd .menu .item.press { background: rgba(255, 255, 255, 0.28); }
.b-cmd .menu .item.k-dmg { border-color: rgba(255, 128, 104, 0.55); }
.b-cmd .menu .item.k-heal { border-color: rgba(112, 224, 136, 0.55); }
.b-cmd .menu .item.k-sup { border-color: rgba(112, 176, 255, 0.55); }
.b-cmd .menu .item.k-bond { border-color: rgba(255, 214, 107, 0.8); }
.b-cmd .menu .backchip { border-radius: 4px; }
.b-mem.ready { box-shadow: 0 0 0 1px #000, 0 0 0 3px rgba(255, 255, 255, 0.35); }
.b-bond.full { animation: none; box-shadow: 0 0 0 1px #000, 0 0 10px rgba(255, 214, 107, 0.55); }
.hud-btn { border-radius: 4px; }
.favbtn, .sort-tabs .btn { border-radius: 4px; }
.sort-tabs .btn.on, .b-info .favbtn.on { border-color: #fff; color: #fff; background: rgba(255, 255, 255, 0.1); }

/* 転職: 覚える技は 全部 ならべる（どんな 技か 1行で）。まどは スクロールできる（下に つづく ときは しるし） */
.job-learn { margin: 0.5em 0; display: flex; flex-direction: column; gap: 0.25em; }
.job-learn .jl-row { display: grid; grid-template-columns: 3.2em 1fr; column-gap: 0.4em; align-items: baseline; }
.job-learn .jl-lv { font-variant-numeric: tabular-nums; }
.job-learn .jl-desc { grid-column: 2; color: var(--muted); font-size: 0.92em; line-height: 1.35; }
.scroll-more { position: sticky; bottom: -0.55em; margin: 1.4em -0.8em -0.55em; padding: 1.5em 0.8em 0.35em; text-align: center; font-size: var(--fs-small); color: var(--accent); background: linear-gradient(rgba(5, 6, 18, 0), var(--win-solid) 1.4em); pointer-events: none; }

/* 呪文・技: 名前の 下に みじかい せつめい。ひらめき・合体技も 上下で 見られる */
.menu .item.sk, .menu .item.sk-row { align-items: flex-start; padding-top: 0.28em; padding-bottom: 0.28em; }
.menu .item.sk .l, .menu .item.sk-row .l { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.35em; min-width: 0; }
.menu .item .sk-desc { flex-basis: 100%; font-size: 0.78em; color: var(--muted); line-height: 1.35; white-space: normal; }
.menu .item.sk.sel .sk-desc { color: #d8d6ee; }
/* 第50回 N1: 威力の 目安（威力×1.8・今の魔力でダメージ約120〜150）。名前の 下に 小さく 1行 */
.menu .item .sk-pow { flex-basis: 100%; font-size: 0.78em; color: var(--accent); line-height: 1.35; white-space: normal; font-variant-numeric: tabular-nums; }
.menu .item.sk-row .ln { flex-basis: 100%; font-size: 0.8em; line-height: 1.35; white-space: normal; }
.menu .item.sk-row .nm { color: var(--accent); }
.menu .item.sk-row.locked .nm { color: #6d6c88; }
.menu .item.sk-row .tag { font-size: 0.72em; border: 1px solid currentColor; border-radius: 4px; padding: 0 0.3em; }
.combo-row .ln { display: block; font-size: 0.8em; line-height: 1.35; }
.tab-hint { font-size: 0.72em; color: var(--muted); margin: -0.15em 0 0.1em; }
.skills-view .sk-head { position: sticky; top: 0; z-index: 2; background: var(--win-solid); padding-bottom: 0.3em; margin-bottom: 0.2em; box-shadow: 0 -1.2em 0 var(--win-solid); }
/* 上下で えらんだ 行が タブの 下に かくれないように */
/* --sk-head-h: タブの 高さ（client/ui/menu.js が はかる。2行に なっても かくれない） */
.skills-view .menu .item { scroll-margin-top: var(--sk-head-h, 5.2em); }
.skills-view .sk-head .tabs { margin-bottom: 0.3em; }
.skills-view .menu .backchip { position: static; }
.sk-mini { font-size: 0.92em; line-height: 1.55; }
.sk-mini .nm { color: var(--fg, #fff); }

/* 設定の みだし（ゲームの難しさ／画面と音・戦い） */
.menu .hdr.set-hdr { color: var(--accent); font-size: var(--fs-small); margin-top: 0.35em; padding-left: 0.2em; }

/* 「動けない時はここをタップ」（client/game.js の 見張り。まっくらの 上にも 出す） */
.rescue-btn {
  position: absolute; left: 50%; top: calc(34% + var(--safe-t)); transform: translateX(-50%); z-index: 70;
  padding: 0.55em 1.2em; font: inherit; font-size: var(--fs); color: var(--accent); border-color: var(--accent); white-space: nowrap; max-width: 94vw;
  cursor: pointer; animation: rescuePulse 1.2s ease-in-out infinite alternate;
}
@keyframes rescuePulse { from { box-shadow: 0 0 0 0 rgba(255, 214, 107, 0.65); } to { box-shadow: 0 0 0 8px rgba(255, 214, 107, 0); } }
.errlog-text { width: 100%; height: min(42vh, 20em); margin: 0.4em 0; font-size: 0.72em; line-height: 1.35; background: rgba(0, 0, 0, 0.35); color: var(--text); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 6px; resize: none; }
/* リーダーが 大鳥に 乗った:「いっしょに 乗る？」（client/sky.js） */
.sky-ask .q { white-space: pre-line; color: var(--text, #fff); font-size: 1em; }
/* 5人パーティーの ときの フィールドの 体力（小さめ。client/ui/hud.js） */
.hud-party.many { gap: 4px; }
.hud-party.many .hud-mem { min-width: 5.4em; padding: 0.1em 0.4em 0.18em; font-size: calc(var(--fs-small) * 0.9); }

/* ───── たたかいの さくせん（仲間の つよさの まどを タップ） ───── */
.b-mem.tac { cursor: pointer; }
.b-tactics {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 7;
  width: min(92%, 18em); max-height: calc(100% - 16px); overflow-y: auto; display: flex; flex-direction: column; gap: 0.2em;
  background: var(--win-solid); font-size: var(--fs);
}
.b-tactics .bt-t { color: var(--accent); font-size: var(--fs-small); }
.b-tactics .menu .item { min-height: 2.1em; }
.b-tactics .menu .item.tac-now .l { color: var(--accent); }
.b-tactics .menu .item .r { color: var(--accent); font-size: 0.8em; }

/* ───── よこむきの スマホ（たかさが みじかい）: たたかいの え を 大きく ───── */
/* ひだりに え（はばいっぱい。のこりの たかさが メッセージ）、みぎの ほそい れつに つよさ（1人 1行）と コマンド。
   みぎの れつは 30vw（200〜270px）。5人 いても つよさは 5行で おさまる */
@media (orientation: landscape) and (max-height: 500px) {
  #battle {
    --bside: clamp(196px, 30vw, 270px);
    /* え の はば（ひだりの れつ）と、その たかさ（16:9）の のこりが メッセージ（すくなくとも 2行半） */
    --bstw: calc(100vw - 18px - var(--safe-l) - var(--safe-r) - var(--bside));
    --bmsg: max(calc(var(--fs-small) * 3.75 + 10px), calc(100vh - 18px - var(--safe-t) - var(--safe-b) - var(--bstw) * 0.5625));
    display: grid;
    grid-template-columns: minmax(0, 1fr) var(--bside);
    grid-template-rows: auto auto minmax(0, 1fr) var(--bmsg);
    grid-template-areas: "stage status" "stage bond" "stage cmd" "msg cmd";
  }
  @supports (height: 100dvh) {
    #battle { --bmsg: max(calc(var(--fs-small) * 3.75 + 10px), calc(100dvh - 18px - var(--safe-t) - var(--safe-b) - var(--bstw) * 0.5625)); }
  }
  .b-top, .b-bottom { display: contents; }
  .b-stage { grid-area: stage; }
  .b-tools { top: 6px; right: 6px; }
  .b-tools .btn { padding: 0.15em 0.6em; }
  .b-msg { grid-area: msg; min-height: 0; padding: 0.3em 0.7em; line-height: 1.42; }
  /* つよさ: 1人 1行（なまえ・HP の ゲージと かず・MP の かず）。行動ゲージは 下の ほそい 線 */
  .b-status { grid-area: status; grid-template-columns: minmax(0, 1fr); gap: 3px; }
  .b-mem {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr) auto;
    column-gap: 0.4em;
    align-items: center;
    padding: 0.15em 0.45em 0.3em;
    font-size: calc(var(--fs) * 0.8);
    line-height: 1.2;
  }
  .b-mem .nm { grid-column: 1; }
  .b-mem .nm .lv, .b-mem .tg { display: none; }
  .b-mem .grow.hp { grid-column: 2; }
  .b-mem .grow.mp { grid-column: 3; }
  .b-mem .grow .gl { display: none; }
  .b-mem .grow.mp .gb { display: none; }
  .b-mem .grow.mp .gn { color: #8fd0ff; min-width: 1.6em; }
  .b-mem .gb { height: 0.45em; }
  .b-mem .gn { font-size: 0.92em; }
  .b-mem .grow.hp .gn { min-width: 3.6em; }
  .b-mem .sts { grid-column: 1 / -1; font-size: 0.85em; }
  .b-mem .atb { position: absolute; left: 0.45em; right: 0.45em; bottom: 2px; height: 2px; margin: 0; }
  .b-bond { grid-area: bond; width: auto; flex-direction: row; align-items: center; padding: 0.05em 0.5em; font-size: calc(var(--fs) * 0.72); }
  .b-bond .bb { flex: 1; height: 0.5em; }
  .b-cmd { grid-area: cmd; width: auto; min-height: 0; overflow: hidden; padding: 0.35em 0.5em; }
  .b-cmd .who { font-size: var(--fs-small); margin-bottom: 0.1em; }
  .b-cmd .menu { max-height: none; flex: 1; min-height: 0; }
  #battle .b-cmd .menu .item { min-height: calc(var(--bcmd-h) * 0.95); padding: 0.1em 0.35em; }
  .b-plate { font-size: var(--fs-small); }
}

/* ───── メニュー: コマンドを えらんで 中の 画面に 入った とき（client/ui/menu.js の setSubOpen） ───── */
/* 見出し（← もどる と、えらんだ コマンドの 名前）。ふだんは かくす */
.fmenu-panel .fm-title { display: none; align-items: center; gap: 0.7em; min-height: 2.6em; }
.fmenu-panel .fm-title .fm-back { min-height: 38px; padding: 0.05em 0.9em; font-size: var(--fs-small); color: var(--muted); border-color: var(--muted); }
.fmenu-panel .fm-title .fm-back:hover, .fmenu-panel .fm-title .fm-back:active { color: #fff; border-color: #fff; }
.fmenu-panel .fm-title .fm-tt { color: var(--accent); font-weight: bold; letter-spacing: 0.08em; }
/* よこに ならぶ 画面（パソコン・よこむき）: コマンドの 一覧は うすく、えらんだ コマンドは 金色 */
.fmenu-panel.sub-open .fmenu .side .menu .item:not(.sel) { opacity: 0.45; }
.fmenu-panel.sub-open .fmenu .side .menu .item.sel { color: var(--accent); }
/* スマホの たてむき: 画面が かわる（コマンドの 一覧を かくして 見出しだけ。中の 画面を 下まで 大きく）
   よこむきの 小さい スマホ（はばが 700より せまい）は 左右に ならぶので、ここには 入れない */
@media (max-width: 700px) and (orientation: portrait) {
  .fmenu-panel.sub-open { height: calc(100% - var(--safe-t) - max(8px, 4vh) - 10px - var(--safe-b)); }
  .fmenu-panel.sub-open .fmenu { grid-template-rows: auto minmax(0, 1fr); }
  .fmenu-panel.sub-open .fmenu .side { padding-top: 0.35em; padding-bottom: 0.35em; }
  .fmenu-panel.sub-open .fmenu .side .menu { display: none; }
  .fmenu-panel.sub-open .fm-title { display: flex; }
  .fmenu-panel.sub-open .fmenu .main { height: auto; max-height: none; min-height: 0; }
  /* もどるは 見出しに ある（リストの 上の もどるは 出さない。行と かさならない） */
  .fmenu-panel.sub-open .fmenu .main .menu .backchip { display: none; }
}

/* 「← もどる」が リストの 上に はりつく とき: はばいっぱいの 帯に して、下に もぐった 行が 横から 見えないように */
.menu .backchip {
  justify-self: stretch;
  align-self: stretch;
  /* 下の すきま（margin-bottom）も ぬりつぶす。上は スクロールの まどの はしに はりつくので いらない（上の 見出しに かぶらない） */
  box-shadow: 0 0.3em 0 0 var(--win-solid);
}
.zukan-list .menu .backchip, .skills-view .menu .backchip { box-shadow: none; }

/* 装備を えらぶ まど: 1つの 物を 2行で（名前 ／ 変わる 強さ）。強さは マスに ならべて 行ごとに そろえる */
/* flex-shrink: 0 … まどの 高さが 足りない ときに 行が つぶれて、3行目が 次の 物に かさならないように（スクロールする） */
.menu .item.eq-opt { flex-shrink: 0; align-items: flex-start; padding-top: 0.35em; padding-bottom: 0.4em; border-bottom: 1px dashed rgba(255, 255, 255, 0.14); border-radius: 0; }
.menu .item.eq-opt.sel { border-radius: 3px; }
/* .l は ブロック（flex の たて ならびの 中に グリッドを 入れると、行の 高さが 2ばいに なる ことが あった） */
.menu .item.eq-opt .l { display: block; min-width: 0; flex: 1; }
.menu .item.eq-opt .eq-nm { display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 0.5em; }
/* 強さは はばを そろえて ならべる（長い ものは そのぶん 広く。文字は きらない） */
.menu .item.eq-opt .eq-sc { display: flex; flex-wrap: wrap; gap: 0 1em; margin-top: 0.1em; font-size: 0.8em; line-height: 1.4; }
.menu .item.eq-opt .eq-sc .sc { flex: 0 0 auto; min-width: 10.5em; white-space: nowrap; }
/* 第64回: 装備 そのものの 強さは 白・今の 装備との 差だけ 色。おすすめは しずかな 印 */
.menu .item.eq-opt .eq-sc .sc { color: #fff; }
.eq-sc .eq-d { margin-left: 0.3em; }
.eq-sc .eq-d.up { color: #7ee08a; }
.eq-sc .eq-d.down { color: #ff8a7a; }
.menu .item .tag.eq-rec { font-size: 0.68em; border: 1px solid rgba(255, 214, 107, 0.7); border-radius: 4px; padding: 0 0.35em; color: var(--accent); }
.eq-compare { margin-top: 0.4em; padding-top: 0.3em; border-top: 1px dashed rgba(255, 255, 255, 0.25); line-height: 1.45; color: #fff; }
.eq-compare .eq-cmp-now { color: var(--muted); }
.eq-compare .eq-cmp-new { min-height: 1.45em; }
.menu .item .tag.eq-tag { font-size: 0.68em; border: 1px solid currentColor; border-radius: 4px; padding: 0 0.35em; color: var(--muted); }
.menu .item.eq-swap .tag.eq-tag { color: #8fd0ff; }
.menu .hdr.eq-none { color: var(--muted); font-size: var(--fs-small); padding: 0.3em 0.2em; }
.eq-swap-body { display: flex; flex-direction: column; gap: 0.2em; margin: 0.4em 0 0.5em; line-height: 1.5; }
/* 装備を えらぶ まどの ならび（入手順・強さ順）。リストは この 下で スクロールする（ボタンは 動かない） */
.eq-pick .gear-sort { flex: none; flex-wrap: nowrap; gap: 0.4em; margin: 0.3em 0 0.35em; }
.eq-pick .gear-sort .btn { min-height: 34px; padding: 0.05em 0.8em; white-space: nowrap; color: var(--muted); border-color: rgba(255, 255, 255, 0.28); background: transparent; }
/* えらんでいる ならびは 白く 光る（えらんでいない ほうは うすい。どちらか すぐ 分かる） */
.eq-pick .gear-sort .btn.on { color: #fff; border-color: #fff; background: rgba(255, 255, 255, 0.16); box-shadow: 0 0 0 1px #fff; font-weight: bold; }
.eq-pick .gear-sort .tab-hint { margin: 0 0 0 auto; white-space: nowrap; }
/* えらぶ まどの 題の 下の ひとこと（道具を 使った けっか・設定の せつめい） */
.pick-note { flex: none; white-space: pre-line; font-size: var(--fs-small); line-height: 1.45; margin: 0.3em 0 0.4em; padding: 0.25em 0.5em; border-left: 3px solid currentColor; background: rgba(255, 255, 255, 0.05); border-radius: 0 4px 4px 0; }
.pick-note.ok { color: var(--good); }
.pick-note.ng { color: var(--warn); }
.pick-note.info { color: var(--muted); border-left-color: rgba(255, 255, 255, 0.25); }
/* だれに使う？（人が 多い ときや よこむきでは リストが スクロールする） */
.pick-target .menu, .foe-pick .menu { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.foe-pick .menu .item .r { color: var(--accent); }
/* えらぶ まどの 題に 改行（「〜が装備している。\n装備を入れかえる？」など） */
.center-panel > .small.gold { white-space: pre-line; }
/* 作戦: オートで 使わない 技 */
.menu .item.auto-off .l { color: #8a8aa0; }
.menu .item.best-all { color: var(--accent); }
/* 見た目装備（menu.js の lookView・pickLook）: まえ と よこ の 見本。えらぶ まどでは カーソルの 物に かわる */
.look-pv { display: flex; justify-content: center; align-items: flex-end; gap: 1.2em; margin: 0.2em 0 0.4em; }
.look-pv .look-big { width: 96px; height: 126px; image-rendering: pixelated; }
.look-pv.small .look-big { width: 64px; height: 84px; }
.look-pick .look-pv-box { flex: none; }
.look-pick .menu { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.menu .item.look-opt .tag.eq-tag { margin-left: 0.5em; color: var(--accent); }
/* よこむきの スマホ（高さが せまい）: 見本を 小さく */
@media (max-height: 500px) {
  .look-pv { margin: 0 0 0.2em; }
  .look-pv .look-big { width: 64px; height: 84px; }
  .look-pv.small .look-big { width: 44px; height: 58px; }
}
/* ひみつのダンジョンの 家族の記録の板（ui/secret.js） */
.sd-board-panel { display: flex; flex-direction: column; max-height: calc(100% - var(--safe-t) - 16px); }
.sd-board { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.sd-board-lead { margin-bottom: 0.3em; }
.sd-rows { display: flex; flex-direction: column; }
.sd-row { display: grid; grid-template-columns: 2.6em minmax(0, 1fr) auto; grid-template-areas: 'rk nm fl' 'rk sb sb'; column-gap: 0.6em; align-items: baseline; padding: 0.25em 0.3em; border-bottom: 1px solid rgba(255, 255, 255, 0.08); }
.sd-row .sd-rank { grid-area: rk; font-weight: bold; color: var(--muted); align-self: center; }
.sd-row .sd-name { grid-area: nm; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sd-row .sd-floor { grid-area: fl; font-weight: bold; font-variant-numeric: tabular-nums; }
.sd-row .sd-sub { grid-area: sb; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sd-row.rank1 .sd-rank { color: #ffd66b; }
.sd-row.rank2 .sd-rank { color: #d8dce8; }
.sd-row.rank3 .sd-rank { color: #e0a070; }
.sd-row.me { background: rgba(160, 120, 255, 0.16); border-radius: 4px; }
.sd-me { margin-top: 0.5em; color: var(--accent); white-space: pre-line; }

/* ───── 戦いの 技・道具の せつめい（第26回 家族の 見なおし。ui/skillinfo.js）─────
   第27回: せつめいは メッセージとは 別の まど（.b-info）。え・メッセージ・せつめい・コマンドが 重ならない。
   お気に入りの ボタンは 右上に うかべて、文は その まわりを 回りこむ（よこに はばを とらない） */
.b-info .favbtn { float: right; margin: 0 0 0.2em 0.5em; }
/* たてむき: 上から え・メッセージ・せつめい・コマンド（.b-bottom は column-reverse。DOM は コマンド・せつめい・メッセージ） */
@media (max-aspect-ratio: 1/1) {
  .b-info { flex: none; height: auto; max-height: 4.9em; padding-top: 0.25em; padding-bottom: 0.25em; line-height: 1.4; }
  /* せつめいが 出ている 間は メッセージを 2行ぶんに（コマンドが せまく ならない） */
  #battle.has-info .b-msg { height: 4.1em; }
}
/* よこむきの スマホ: 左の れつに 上から え・せつめい・メッセージ（え は のこりの 高さで 小さく なる）、右に つよさと コマンド */
@media (orientation: landscape) and (max-height: 500px) {
  #battle.has-info {
    /* メッセージは 3行ぶん（え を できるだけ 大きく のこす） */
    grid-template-rows: auto auto minmax(0, 1fr) auto min(var(--bmsg), calc(var(--fs-small) * 4.3 + 10px));
    grid-template-areas: "stage status" "stage bond" "stage cmd" "info cmd" "msg cmd";
  }
  .b-info { grid-area: info; max-height: 34vh; padding: 0.25em 0.7em; line-height: 1.38; }
}
/* 第27回: 技の 長おし（Y）で 出る「お気に入りに入れる／はずす」の まど */
.b-favpop-back { position: absolute; inset: 0; z-index: 8; background: rgba(0, 0, 0, 0.35); }
.b-favpop {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 9;
  width: min(88%, 20em); display: flex; flex-direction: column; gap: 0.3em; background: var(--win-solid); font-size: var(--fs);
}
.b-favpop .bf-t { color: var(--accent); font-size: var(--fs-small); }
/* たてむき: え の 上に 出す（下の せつめいと コマンドが 見えたまま） */
@media (max-aspect-ratio: 1/1) { .b-favpop { top: 32%; } }
.b-favpop .menu .item { min-height: 2.3em; }
.b-favpop .menu .item.gold .l { color: var(--accent); }
/* 長おしの 間に 文字を えらんだり、iPhone の メニューが 出たり しない */
.b-cmd .menu .item { -webkit-touch-callout: none; -webkit-user-select: none; user-select: none; }

/* ───── 第27回: メニューの 道具（client/ui/menu.js の itemsList）─────
   一覧は まどの 中で スクロール、せつめい（ui/skillinfo.js の menuItemText）は 下に いつも 見える（重ならない） */
.fmenu .main > .items-view { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.items-view > .tabs { flex: none; }
.items-view > .menu { flex: 1 1 auto; min-height: 3em; overflow-y: auto; overscroll-behavior: contain; }
.items-view > .item-detail { flex: none; max-height: 45%; overflow-y: auto; margin-top: 0.3em; padding: 0.3em 0.5em; color: var(--text); border-top: 1px solid rgba(255, 255, 255, 0.18); background: rgba(255, 255, 255, 0.04); border-radius: 0 0 4px 4px; }
.items-view > .item-detail:empty { display: none; }
@media (orientation: landscape) and (max-height: 520px) {
  .items-view > .item-detail { max-height: 40%; line-height: 1.32; }
}

/* ───── レア度（第31回 C）: 名前の 色と ★の 数（★1 緑・★2 青・★3 紫・★4 オレンジ・★5 金と にじ）。client/ui/rarity.js ───── */
.rar { font-weight: bold; }
.rar.r1 { color: #8ef0a8; }
.rar.r2 { color: #7cc8ff; }
.rar.r3 { color: #d7a2ff; }
.rar.r4 { color: #ffa057; }
.rar.r5 {
  color: #ffd66b;
  background: linear-gradient(90deg, #fff08a 0%, #ffb8e6 30%, #a8f0ff 60%, #fff08a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.rar .rs { font-size: 0.7em; margin-left: 0.12em; letter-spacing: -0.06em; font-weight: normal; vertical-align: 0.08em; }
.menu .item.dis .rar { opacity: 0.55; }

/* ───── 配合の 受けつぐ 技（第43回 B）: 2つの 列（親A・親B）。せまい スマホでも 1行に おさめる（ListMenu の fit） ───── */
.breed-pick .menu.cols2 { column-gap: 0.5em; }
.breed-pick .menu .hdr.pk-gap { border: 0; margin: 0; padding: 0.12em 0.4em; color: var(--muted); }
.breed-pick .menu .hdr.pk-hdr { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.breed-pick .menu .item { padding-left: 1.1em; gap: 0.3em; }
.breed-pick .menu .item .l { min-width: 0; white-space: nowrap; overflow: hidden; }

/* ───── 第76回: 画面を 大きく 使う まど（家族の ねがい: 画面を 小さく 使う 必要は ない。見やすく わかりやすく）───── */
/* 大きな まどの あいだは 下の メッセージを かくす（問いは まどの 中に ある） */
body.big-choice #ui .dialog { visibility: hidden; }

/* 装備を えらぶ まど（menu.js の pickGear）: よこ画面は 左に 一らん・右に くらべる まど。たて画面は 上に 一らん・下に くらべる まど */
.center-panel.big-pick { width: calc(100% - 16px); max-width: 1200px; height: calc(100% - 16px - var(--safe-t) - var(--safe-b)); max-height: none; }
.eq-pick.big-pick {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  grid-template-rows: auto auto auto minmax(0, 1fr);
  grid-template-areas: "t t" "n c" "h c" "m c";
  column-gap: 1.1em;
  font-size: calc(var(--fs) * 1.06);
}
.eq-pick.big-pick > .pick-title { grid-area: t; font-size: var(--fs); margin-bottom: 0.2em; }
.eq-pick.big-pick > .pick-note { grid-area: n; margin: 0.1em 0 0.3em; }
.eq-pick.big-pick > .gear-sort { grid-area: h; }
.eq-pick.big-pick > .menu { grid-area: m; min-height: 0; }
.eq-pick.big-pick > .eq-compare { grid-area: c; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.eq-pick.big-pick .menu .item.eq-opt { padding-top: 0.45em; padding-bottom: 0.5em; }
.eq-pick.big-pick .menu .item.eq-opt .eq-sc { font-size: 0.86em; }
@media (orientation: portrait) {
  .eq-pick.big-pick {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto auto minmax(0, 1fr) auto;
    grid-template-areas: "t" "n" "h" "m" "c";
  }
  .eq-pick.big-pick > .eq-compare { max-height: 60vh; margin-top: 0.45em; font-size: 0.94em; }
  .eq-pick.big-pick .menu .item.eq-opt .eq-sc .sc { min-width: 9.5em; }
}
/* 一らんの「もと+68」（きたえる 前の 強さ）と「もとが強い」の しるし */
.eq-sc .eq-base { margin-left: 0.45em; color: #b9b8d8; font-size: 0.9em; }
.menu .item .tag.eq-baseup { font-size: 0.68em; border: 1px solid rgba(143, 208, 255, 0.75); border-radius: 4px; padding: 0 0.35em; color: #8fd0ff; }
/* くらべる まど（client/ui/equip-compare.js） */
.eq-pick .eq-compare { margin: 0; padding: 0.6em 0.8em; border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 8px; background: rgba(255, 255, 255, 0.04); line-height: 1.45; color: #fff; }
.eqc-head { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); gap: 0.45em; align-items: stretch; }
.eqc-card { padding: 0.4em 0.55em; border-radius: 6px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.2); min-width: 0; }
.eqc-card.new { border-color: rgba(255, 214, 107, 0.65); }
.eqc-cap { font-size: var(--fs-small); color: var(--muted); }
.eqc-name { font-size: 1.08em; font-weight: bold; word-break: break-all; }
.eqc-sub { font-size: var(--fs-small); color: #c9c8e8; }
.eqc-to { align-self: center; font-size: 1.4em; color: var(--accent); }
.eqc-tbl { width: 100%; margin-top: 0.6em; border-collapse: collapse; font-variant-numeric: tabular-nums; font-size: 1.05em; }
.eqc-tbl th, .eqc-tbl td { padding: 0.28em 0.35em; text-align: right; white-space: nowrap; border-bottom: 1px dashed rgba(255, 255, 255, 0.16); }
.eqc-tbl tbody th { text-align: left; color: #fff; font-weight: normal; }
.eqc-tbl thead th { font-size: var(--fs-small); color: var(--muted); font-weight: normal; border-bottom: 0; text-align: right; padding-top: 0; padding-bottom: 0; }
.eqc-tbl thead tr:first-child th { text-align: center; color: #fff; }
.eqc-tbl .eqc-b { color: #b9b8d8; }
.eqc-tbl .eqc-new { background: rgba(255, 214, 107, 0.07); }
.eqc-tbl thead tr:first-child th.eqc-new { color: var(--accent); }
.eqc-d { margin-left: 0.25em; font-size: 0.85em; }
.eqc-d.up { color: #7ee08a; }
.eqc-d.down { color: #ff8a7a; }
.eqc-d.same { color: var(--muted); }
.eqc-same { margin-top: 0.6em; padding: 0.4em 0.6em; border-left: 3px solid var(--accent); background: rgba(255, 214, 107, 0.08); border-radius: 0 6px 6px 0; }
.eqc-same.muted { border-left-color: rgba(255, 255, 255, 0.3); background: rgba(255, 255, 255, 0.04); font-size: var(--fs-small); }
.eqc-same-h { font-size: var(--fs-small); color: var(--accent); }
.eqc-same-v { display: flex; flex-wrap: wrap; gap: 0 1.1em; font-size: 1.05em; font-variant-numeric: tabular-nums; }
.eqc-none { margin-top: 0.6em; }
.eqc-legend { margin-top: 0.6em; font-size: calc(var(--fs-small) * 0.95); color: var(--muted); }
@media (orientation: portrait) {
  .eqc-tbl { font-size: 0.98em; }
  .eqc-tbl th, .eqc-tbl td { padding: 0.22em 0.2em; }
}

/* お仕事いらい板の 一らん（せつめいの ある えらぶ まど。script.js の choice）: 大きく まん中に。よこ画面は 右・たて画面は 下に せつめい */
.choice.has-info {
  left: 50%; top: 50%; right: auto; bottom: auto;
  transform: translate(-50%, -50%);
  width: min(calc(100% - 16px), 1100px);
  max-height: calc(100% - 16px - var(--safe-t) - var(--safe-b));
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "q q" "m i";
  column-gap: 1em;
  font-size: calc(var(--fs) * 1.12);
  padding: 0.7em 1em;
}
.choice.has-info .q { grid-area: q; font-size: var(--fs); color: var(--accent); margin-bottom: 0.4em; }
.choice.has-info .menu { grid-area: m; max-height: none; min-height: 0; overflow-y: auto; }
.choice.has-info .menu .item { min-height: 2.25em; align-items: center; border-bottom: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 0; }
.choice.has-info .choice-info {
  grid-area: i; align-self: start; margin: 0; min-height: 0; max-height: none; overflow: visible;
  font-size: var(--fs); line-height: 1.8; padding: 0.6em 0.8em;
  border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 8px; background: rgba(255, 255, 255, 0.05);
}
@media (orientation: portrait) {
  .choice.has-info { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "q" "m" "i"; }
  .choice.has-info .choice-info { margin-top: 0.5em; }
}

/* お仕事いらい板の はり紙（client/ui/paper-pop.js）: 1まいで ぜんぶ。下に 大きな ボタン */
.paper-pop {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(calc(100% - 16px), 1100px);
  max-height: calc(100% - 16px - var(--safe-t) - var(--safe-b));
  display: flex; flex-direction: column;
  font-size: calc(var(--fs) * 1.08);
  background: var(--win-solid);
  padding: 0.7em 1em 0.8em;
}
.pp-paperwrap { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.pp-top { display: flex; flex-wrap: wrap; align-items: center; gap: 0.3em 0.7em; font-size: var(--fs-small); }
.pp-kind { color: var(--accent); border: 1px solid currentColor; border-radius: 4px; padding: 0 0.45em; }
.pp-town { color: var(--muted); }
.pp-state { margin-left: auto; padding: 0 0.6em; border-radius: 4px; font-weight: bold; }
.pp-state.taken { background: rgba(143, 208, 255, 0.2); color: #8fd0ff; }
.pp-state.done { background: rgba(125, 255, 176, 0.18); color: var(--good); }
.paper-pop .pp-title { margin: 0.15em 0 0.45em; font-size: 1.45em; font-weight: bold; color: #fff; letter-spacing: 0.04em; line-height: 1.35; }
.pp-body { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "ask ask" "where job" "reward job"; gap: 0.6em 0.9em; align-items: start; }
.pp-sec { padding: 0.5em 0.75em; border-radius: 8px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.18); min-width: 0; }
.pp-sec.pp-ask { grid-area: ask; background: #f4e7c6; border-color: #c9a86a; color: #3a2a12; }
.pp-sec.pp-where { grid-area: where; }
.pp-sec.pp-job { grid-area: job; align-self: stretch; }
.pp-sec.pp-reward { grid-area: reward; }
.paper-pop .pp-h { margin: 0 0 0.25em; font-size: var(--fs-small); color: var(--accent); font-weight: normal; letter-spacing: 0.1em; }
.paper-pop .pp-ask .pp-h { color: #8a5a1a; }
.pp-paper { white-space: pre-line; font-size: 1.08em; line-height: 1.6; }
.pp-who { font-size: 1.1em; font-weight: bold; }
.pp-place { color: #dcdcf0; line-height: 1.55; }
.pp-jobline { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.2em 0.8em; font-size: 1.05em; }
.pp-has { padding: 0 0.5em; border-radius: 4px; font-weight: bold; }
.pp-has.yes { color: var(--good); background: rgba(125, 255, 176, 0.12); }
.pp-has.no { color: #ff8a7a; background: rgba(255, 100, 100, 0.12); }
.pp-chips { display: flex; flex-wrap: wrap; gap: 0.3em; margin: 0.4em 0; }
.pp-chip { font-size: var(--fs-small); padding: 0.05em 0.55em; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.3); background: rgba(255, 255, 255, 0.06); }
.pp-note { font-size: var(--fs-small); color: var(--muted); }
.pp-rws { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.35em; }
.pp-rw { display: grid; grid-template-columns: 1.7em minmax(0, 1fr) auto; align-items: center; gap: 0.5em; font-size: 1.05em; }
.pp-ic { width: 1.6em; height: 1.6em; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 0.8em; font-weight: bold; background: #2b2d5a; color: #fff; }
.pp-ic.acc { background: #6b3fa0; }
.pp-ic.vehicle { background: #2f6f9f; }
.pp-ic.goods { background: #3f7a4a; }
.pp-ic.gold { background: #d9b23a; color: #2a1d00; }
.pp-ic.medal { background: #4b50a8; color: #ffd66b; }
.pp-rk { font-size: var(--fs-small); color: var(--muted); white-space: nowrap; }
.pp-n { margin-left: 0.25em; color: var(--accent); }
.pp-q { flex: none; margin: 0.6em 0 0.35em; text-align: center; font-size: 1.15em; color: var(--accent); font-weight: bold; }
.pp-q.muted { color: var(--muted); font-weight: normal; }
/* 問いと ボタン（よこ画面は 1行に ならべて、はり紙を 広く） */
.pp-foot { flex: none; display: flex; align-items: center; gap: 0.4em 1.2em; margin-top: 0.6em; padding-top: 0.5em; border-top: 1px dashed rgba(255, 255, 255, 0.22); }
.pp-foot .pp-q { margin: 0; text-align: left; flex: 0 1 auto; }
.pp-foot .menu.pp-btns { flex: 1 1 auto; margin: 0 0 0 auto; }
@media (orientation: portrait) {
  .pp-foot { flex-direction: column; align-items: stretch; }
  .pp-foot .pp-q { text-align: center; }
  .pp-foot .menu.pp-btns { margin: 0 auto; }
}
.paper-pop .menu.pp-btns { flex: none; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.6em; max-width: 34em; width: 100%; margin: 0 auto; }
.paper-pop .menu.pp-btns:not(.cols2) { grid-template-columns: minmax(0, 1fr); max-width: 20em; }
.paper-pop .menu .item.pp-btn { min-height: 2.8em; justify-content: center; align-items: center; font-size: 1.15em; border: 2px solid rgba(255, 255, 255, 0.35); border-radius: 8px; padding-left: 1.3em; }
.paper-pop .menu .item.pp-btn.sel { border-color: var(--accent); background: rgba(255, 214, 107, 0.18); }
.pp-need { display: none; flex-wrap: wrap; align-items: baseline; gap: 0.2em 0.6em; margin: -0.2em 0 0.5em; }
@media (orientation: portrait) {
  .pp-need { display: flex; }
  .pp-body { grid-template-columns: minmax(0, 1fr); grid-template-areas: "ask" "where" "reward" "job"; }
  .pp-chip { font-size: calc(var(--fs-small) * 0.92); }
}

