      { drums: true, v: 0.5, n: 'k:2 h:2 s:2 h:2 k:2 h:2 s:2 h:2 '.repeat(15) + 'k:2 s:2 s:2 k:2 s:2 s:2 s:2 s:2' },
    ],
  },
  yomi_king: {
