        'D5:3 F5:1 A5:4 G5:3 F5:1 E5:4', 'D5:3 D5:1 F5:4 Bb5:8', 'G5:3 A5:1 Bb5:4 D6:4 Bb5:4', 'A5:4 C#6:4 E6:4 A5:4',
