        'G5:3 Bb5:1 D6:4 G6:4 D6:4', 'C#6:3 E6:1 A6:4 G6:4 E6:4', 'F6:3 E6:1 D6:4 A5:4 F5:4', 'E5:4 C#5:4 A4:8',
