};
// 和音の 音を 上の オクターブへ（3つ目の 音が ねより 下に なる ときは 1つ 上）
function voiced(name, oct) {
  const [, notes] = CHORD[name];
  const order = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'Bb', 'B'];
  const idx = (n) => order.indexOf(n === 'Db' ? 'C#' : n);
  let o = oct, prev = -1;
  return notes.map((n) => {
    if (idx(n) <= prev) o++;
    prev = idx(n);
    return `${n}${o}`;
  });
}
// アルペジオ（1小節に 8つ）
