        // 思い出の オルゴールの ような ところ（長調）
        'C6:4 E6:4 G6:6 F6:2', 'D6:4 G6:4 B6:6 A6:2', 'G6:4 E6:4 C6:4 E6:4', 'A6:6 G6:2 E6:8',
