};
export const C8A_SFX = {
  a8n_slash: 'hit', a8n_rush: 'hit', a8n_guard: 'buff', a8n_needle: 'hit', a8n_roll: 'smash', a8n_grow: 'buff', a8n_bite: 'smash', a8n_jump: 'smash', a8n_glare: 'warn',
