// ───────────── え（client/battle.js の monsterCanvas の かわり）─────────────
// ジャハールが 変身したら、おなじ え の コマ 2・3（コブラ）・4・5（魔人）（render/c8a-art.js）
export function c8aSprite(c, frame) {
  // 第8章 第2幕（battle-c8b.js）
  const s8 = c8bSprite(c, frame);
  if (s8) return s8;
  if (c?.species !== C8_JAFAR || !(c.c8form >= 2)) return null;
  return monsterCanvas(C8_JAFAR, (frame ? 1 : 0) + (c.c8form === 2 ? 2 : 4));
}

// 属性の 色（覚えた 呪文の 玉）
const EL_COL = { fire: '#ff6a3a', ice: '#9ae6ff', bolt: '#fff06a', wind: '#9af0b0', light: '#fffbe0', dark: '#a87ae0', water: '#5a9aff', blast: '#ffb04a', void: '#e8e8ff', none: '#e8e8ff' };

// しるしの うしろの くらい まる（背景と まざらない）
function backDot(x, cx, cy, r, base) {
  x.globalAlpha = base * 0.6;
  x.fillStyle = '#0c0814';
  x.beginPath();
  x.arc(cx, cy, r, 0, Math.PI * 2);
  x.fill();
}
// ふきだし（オウムがえしの しるし）
function bubbleMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.ellipse(cx, cy - s * 0.15, s * 0.9, s * 0.65, 0, 0, Math.PI * 2);
  x.fill();
  x.beginPath();
  x.moveTo(cx - s * 0.3, cy + s * 0.3);
  x.lineTo(cx - s * 0.6, cy + s * 0.9);
  x.lineTo(cx + s * 0.05, cy + s * 0.4);
  x.fill();
}
// へびの 目（さいみんじゅつの しるし）
function eyeMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.moveTo(cx - s, cy);
  x.quadraticCurveTo(cx, cy - s * 0.9, cx + s, cy);
  x.quadraticCurveTo(cx, cy + s * 0.9, cx - s, cy);
  x.fill();
  x.fillStyle = '#0c0814';
  x.fillRect(cx - s * 0.12, cy - s * 0.5, s * 0.24, s);
}
// うず（とぐろの しるし）
function coilMark(x, cx, cy, s, col) {
  x.strokeStyle = col;
  x.lineWidth = 1.5;
  x.beginPath();
  for (let i = 0; i <= 18; i++) {
    const a = (i / 18) * Math.PI * 3.2;
    const r = s * (0.15 + (i / 18) * 0.85);
    const px = cx + Math.cos(a) * r, py = cy + Math.sin(a) * r;
    if (i) x.lineTo(px, py);
    else x.moveTo(px, py);
  }
  x.stroke();
}
// ほのお（魔力の しるし）
function flameMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.moveTo(cx, cy - s);
  x.quadraticCurveTo(cx + s * 0.9, cy, cx, cy + s * 0.8);
  x.quadraticCurveTo(cx - s * 0.9, cy, cx, cy - s);
  x.fill();
}
// のこりの しるしを ならべる（on … のこり・max … ぜんぶ）
function marks(x, px, py, w, on, max, base, T, draw, cols) {
  const gap = 11, x0 = px + w / 2 - ((max - 1) * gap) / 2, y0 = Math.max(6, py - 6);
  for (let i = 0; i < max; i++) {
    const lit = i < on;
    const last = lit && on === 1;
    backDot(x, x0 + i * gap, y0, 5, base);
    x.globalAlpha = base * (lit ? (last ? 0.7 + Math.sin(T / 80) * 0.3 : 0.95) : 0.3);
    draw(x, x0 + i * gap, y0, 4, lit ? (last ? cols[1] : cols[0]) : cols[2]);
  }
  x.globalAlpha = base;
}
// 小さな 文字の ふだ（「聞き耳」「×1.5」など）
function tag(x, tx, ty, text, base, bg, fg, wd = 30) {
  x.globalAlpha = base * 0.85;
  x.fillStyle = bg;
  x.fillRect(Math.round(tx - wd / 2), Math.round(ty - 5), wd, 10);
  x.globalAlpha = base;
  x.fillStyle = fg;
  x.font = 'bold 7px sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText(text, tx, ty + 0.5);
  x.textAlign = 'start';
  x.textBaseline = 'alphabetic';
}
// 赤い わ（とぐろ・ランプの 中）
function ring(x, px, py, w, h, base, T, col) {
  for (let i = 0; i < 2; i++) {
    const r = ((T / 9 + i * 20) % 40) / 40;
    x.globalAlpha = base * (0.6 - r * 0.5);
    x.strokeStyle = col;
    x.lineWidth = 2;
    x.beginPath();
    x.ellipse(px + w / 2, py + h * 0.6, w * (0.35 + r * 0.25), h * (0.3 + r * 0.2), 0, 0, Math.PI * 2);
    x.stroke();
  }
  x.globalAlpha = base;
}

// ───────────── たたかいの え（client/battle-c7i.js の c7iDraw から）─────────────
export function c8aDraw(scene, x, m, c, px, py, w, h, base) {
  if (!c?.alive) return;
  // 第8章 第2幕（battle-c8b.js）
  c8bDraw(scene, x, m, c, px, py, w, h, base);
  const T = scene.time || 0;
  // イアゴン: オウムがえしまでの しるし・聞き耳・覚えた 呪文
  if (c.echoEvery) {
    marks(x, px, py, w, c.echoLeft || 0, c.echoEvery, base, T, bubbleMark, ['#fff0c0', '#ff6a4a', '#3a3040']);
    if (c.listen) {
      tag(x, px + w / 2, py + h * 0.18, '聞き耳', base, '#2a0a10', '#ffd66b');
      x.globalAlpha = base * (0.5 + Math.sin(T / 90) * 0.3);
      x.strokeStyle = '#ffd66b';
      x.lineWidth = 1.2;
      for (const s of [-1, 1]) {
        x.beginPath();
        x.arc(px + w / 2 + s * w * 0.12, py + h * 0.25, 4 + ((T / 60) % 6), s < 0 ? Math.PI * 0.6 : -Math.PI * 0.4, s < 0 ? Math.PI * 1.4 : Math.PI * 0.4);
        x.stroke();
      }
      x.globalAlpha = base;
    }
    (c.words || []).forEach((el, i) => {
      const cx = px + w - 6, cy = py + h * 0.35 + i * 11;
      backDot(x, cx, cy, 5, base);
      x.globalAlpha = base * 0.95;
      x.fillStyle = EL_COL[el] || EL_COL.none;
      x.beginPath();
      x.arc(cx, cy, 3.6, 0, Math.PI * 2);
      x.fill();
      x.globalAlpha = base;
    });
    if (c.dizzy) tag(x, px + w / 2, py + h * 0.3, '目をまわした', base, '#2a1a3a', '#ffe890', 46);
  }
  // ジャハール
  if (c.c8form === 1) {
    marks(x, px, py, w, c.hypnoLeft || 0, c.hypnoEvery || 3, base, T, eyeMark, ['#ffd66b', '#ff3a4a', '#3a2a2a']);
    for (let i = 0; i < (c.staffDown || 0); i++) {
      backDot(x, px + 6 + i * 10, py + h - 4, 4.5, base);
      x.globalAlpha = base * 0.9;
      x.fillStyle = '#f2c14e';
      x.fillRect(px + 5.4 + i * 10, py + h - 8, 1.4, 7);
      x.fillStyle = '#e03040';
      x.fillRect(px + 4.6 + i * 10, py + h - 9, 3, 2);
    }
    x.globalAlpha = base;
  }
  if (c.c8form === 2) {
    if (c.coiled) {
      ring(x, px, py, w, h, base, T, '#ff6a4a');
      tag(x, px + w / 2, Math.max(8, py - 4), 'とぐろ！', base, '#2a0808', '#ff8a6a', 34);
    } else marks(x, px, py, w, c.coilLeft || 0, c.coilEvery || 3, base, T, coilMark, ['#f2c14e', '#ff6a4a', '#3a2a20']);
    if (c.openLeft) tag(x, px + w / 2, py + h * 0.42, `×${c.openK ?? 1.5}`, base, '#1a2a10', '#c8ff8a');
  }
  if (c.c8form === 3) {
    if (c.sealLeft) {
      ring(x, px, py, w, h, base, T, '#c8a0ff');
      tag(x, px + w / 2, Math.max(8, py - 4), 'ランプの中', base, '#1a0a20', '#e8d8ff', 44);
      tag(x, px + w / 2, py + h * 0.42, `×${c.sealK ?? 1.6}`, base, '#1a2a10', '#c8ff8a');
    } else marks(x, px, py, w, c.blastLeft || 0, c.blastEvery || 3, base, T, flameMark, ['#c84a8a', '#ff4a4a', '#2a1a2a']);
  }
}

// ───────────── あやつられた 人の まどの しるし ─────────────
const CSS = `
.b-mem.c8a-hypno { box-shadow: 0 0 0 2px #000, inset 0 0 14px rgba(224, 48, 64, 0.9); }
.b-mem.c8a-hypno::after {
  content: 'あやつられている'; position: absolute; left: 50%; top: -0.95em; transform: translateX(-50%); z-index: 3; pointer-events: none;
  font-size: 0.78em; line-height: 1.25; white-space: nowrap; padding: 0 0.45em; color: #ffecec;
  background: rgba(44, 8, 12, 0.94); border: 1px solid #e03040; border-radius: 4px; box-shadow: 0 0 0 1px #000;
}
`;
let styled = false;
function ensureCss() {
  if (styled || typeof document === 'undefined') return;
  styled = true;
  document.head.append(el('style', { id: 'c8a-css', text: CSS }));
}
// あやつられた 人（ev.c8aHypno の 人。目を さますと はずす）を 覚えて おく
export function c8aMarks(scene) {
  if (!scene.allies || !scene.statusBoxes) return;
  const set = scene.c8aHypno || new Set();
  let any = false;
  for (const a of scene.allies()) {
    const s = scene.statusBoxes.get(a.id);
    if (!s) continue;
    // pub の status は じょうたいの 名前の ならび（こんらんが とけたら はずす）
    const on = a.alive && set.has(a.id) && (Array.isArray(a.status) ? a.status.includes('confuse') : true);
    if (on) any = true;
    s.box.classList.toggle('c8a-hypno', !!on);
  }
  if (any) ensureCss();
}

// ───────────── イベントを 見せる とき（client/battle-c7i.js の c7iPresent から）─────────────
export function c8aPresent(scene, ev, fx, anim, actor) {
  const g = scene.game;
  const nameOf = (id) => scene.c?.get?.(id)?.name || '';
  const names = (ids) => (ids || []).map(nameOf).filter(Boolean).join('と');
  // イアゴン
  if (ev.c8aParrot?.listen && ev.c8aParrot.left === 2) {
    g.audio.sfx('warn');
    scene.banner('！イアゴンが聞き耳を立てている…呪文をひかえよう！', 'danger');
  }
  if (ev.c8aParrot?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次にオウムがえし…！', 'danger');
  }
  if (ev.c8aLearn) scene.banner(`イアゴンが呪文を覚えた…（${ev.c8aLearn.words.length}こ）`, 'danger');
  if (ev.c8aEcho) {
    if (ev.c8aEcho.n) {
      scene.shake?.(800, 8);
      scene.banner(`オウムがえし…！覚えた呪文が${ev.c8aEcho.n}つ、はね返ってきた！`, 'danger');
    } else {
      g.audio.sfx('sparkle');
      scene.banner('イアゴンは何も覚えていない！目をまわした！', 'combo');
    }
  }
  // ジャハール
  if (ev.c8aHypnoLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次にさいみんじゅつ…！へびのつえをこわせ！', 'danger');
  }
  if (ev.c8aHypno) {
    scene.c8aHypno = scene.c8aHypno || new Set();
    for (const id of ev.c8aHypno.who || []) scene.c8aHypno.add(id);
    scene.banner(ev.c8aHypno.who?.length ? `${names(ev.c8aHypno.who)}があやつられてしまった…！` : 'さいみんじゅつをこらえた！', ev.c8aHypno.who?.length ? 'danger' : 'combo');
  }
  if (ev.c8aBreak) {
    g.audio.sfx('crit');
    scene.c8aHypno?.clear();
    scene.banner('へびのつえをこわした！さいみんじゅつがとけた！', 'combo');
  }
  if (ev.c8aStaffBack) scene.banner('へびのつえが、ジャハールの手にもどった…！', 'danger');
  if (ev.c8aCobra) {
    scene.c8aHypno?.clear();
    scene.shake?.(900, 9);
    scene.banner('ジャハールが、大きなコブラに姿をかえた…！', 'danger');
  }
  if (ev.c8aCoilLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次にとぐろ…！とぐろの間は攻撃するな！', 'danger');
  }
  if (ev.c8aCoil) scene.banner('とぐろをまいた！攻撃すると、かみつかれる！', 'danger');
  if (ev.c8aBite) scene.banner(`${nameOf(ev.c8aBite.who)}がかみつかれた！`, 'danger');
  if (ev.c8aStrike) {
    scene.shake?.(800, 8);
    scene.banner('大へびのいちげき…！', 'danger');
  }
  if (ev.c8aWhiff) {
    g.audio.sfx('crit');
    scene.banner(`からぶり！コブラがのびきった！今ならダメージ${ev.c8aWhiff.k}倍！`, 'combo');
  }
  if (ev.c8aGenie) {
    scene.shake?.(1000, 10);
    scene.banner('ジャハールが、ランプの魔人に姿をかえた…！', 'danger');
  }
  if (ev.c8aBlastLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次にむげんの魔力…！ランプをこわすか、身を守れ！', 'danger');
  }
  if (ev.c8aBlast) {
    scene.shake?.(900, 9);
    scene.banner('むげんの魔力…！', 'danger');
  }
  if (ev.c8aSeal) {
    g.audio.sfx('crit');
    scene.banner(`ランプをこわした！魔人がランプにすいこまれた！（ダメージ${ev.c8aSeal.k}倍）`, 'combo');
  }
  if (ev.c8aOut) scene.banner('魔人がランプから出てきた…！また火がともった！', 'danger');
  c8aMarks(scene);
  // 第8章 第2幕（battle-c8b.js）
  c8bPresent(scene, ev, fx, anim, actor);
}

js/client/battle-c8b.js:
// 第2部 第8章 第2幕 の ペイニックと パニクル・よみの王ハデロス（おこった すがた）・手下の 魔物の がめん
// （client/battle-c8a.js から よぶ。サーバーがわは shared/battle-c8b.js）
// ・小おに: 頭の 上に ばけばけ大がったいまでの しるし（おばけ。のこり 1つは 赤く ゆれる）。相談の 間は「ひそひそ」の ふだ、けんかの 間は「けんか」。
//   パニックの 間は「あたふた」と「×1.5」・あせの しずく、カンカンの 間は「カンカン」と ひとりばけばけまでの しるし。え は コマ 2・3（c8bSprite）
// ・ハデロス: 1だんめ … けいやくまでの しるし（まき物）・けいやくの 間は「けいやく」と たましいを とられるまでの しるし・赤く ちらちら する 前ぶれ／
//   2だんめ … 大ふん火までの しるし（ほのお）。え は おこった すがた（コマ 2・3）。あちちっ・頭が ひえた 間は ふだ
// ・けいやくされた 人の まどに「けいやく」（c8bMarks）
// ・バナー: 相談・大がったいの 前ぶれ・けんか・がったい・パニック・カンカン・ひとりばけばけの 前ぶれ／
//   けいやくの 前ぶれ・けいやく・すいとる・たましいの 前ぶれ・もやした・たましいを とられた・赤く ちらちら・おこった・ふん火の 前ぶれ・ふん火・ひえた
// ・敵が 使うと がめんの まん中に 大きく 出す 技・味方の まどの えんしゅつ・音（client/battle-ch4.js・client/battle.js に まぜる）
import { C8_PAIN, C8_PANIC, C8_HADES } from '../shared/data/monsters-c8b.js';
import { monsterCanvas } from './render/monsters.js';
import { el } from './ui/dom.js';
// 第2部 第8章 第3幕: マジカメック・初代大魔王クッパード・橋のオノの がめん（battle-c8c.js）
import { C8C_OWN_TELE, c8cSprite, c8cDraw, c8cPresent } from './battle-c8c.js';

// 前ぶれの バナーを 自分で 出す（client/battle-c8a.js の C8A_OWN_TELE に まぜる）
export const C8B_OWN_TELE = [C8_PAIN, C8_PANIC, C8_HADES, ...C8C_OWN_TELE];

export const C8B_SCREEN_ANIMS = ['b8i_fuse', 'b8i_solo', 'b8h_contract', 'b8h_soul', 'b8h_anger', 'b8h_erupt'];
export const C8B_ALLY_FX = {
  b8n_bite: 'claw', b8n_fire: 'fire', b8n_howl: 'down', b8n_fbite: 'claw', b8n_dash: 'claw', b8n_rattle: 'dark',
  b8n_zap: 'bolt', b8n_sting: 'bolt', b8n_flame: 'fire', b8n_wail: 'down', b8n_drain: 'dark', b8n_hbite: 'claw', b8n_heads: 'claw',
  b8i_pound: 'quake', b8i_belly: 'quake', b8i_tease: 'down', b8i_scratch: 'claw', b8i_bluefire: 'fire', b8i_trip: 'claw', b8i_fuse: 'quake', b8i_solo: 'quake',
  b8h_bluefire: 'fire', b8h_skull: 'dark', b8h_talk: 'down', b8h_contract: 'dark', b8h_soul: 'dark',
  b8h_fist: 'quake', b8h_flare: 'fire', b8h_shout: 'down', b8h_erupt: 'fire',
};
export const C8B_SFX = {
  b8n_bite: 'hit', b8n_fire: 'fire', b8n_howl: 'warn', b8n_fbite: 'hit', b8n_dash: 'smash', b8n_rattle: 'warn', b8n_zap: 'bolt', b8n_sting: 'hit', b8n_glow: 'buff',
  b8n_flame: 'fire', b8n_wail: 'warn', b8n_drain: 'dark', b8n_hbite: 'smash', b8n_heads: 'hit', b8n_regrow: 'buff',
  b8i_pound: 'smash', b8i_belly: 'smash', b8i_tease: 'warn', b8i_scratch: 'hit', b8i_bluefire: 'fire', b8i_trip: 'hit', b8i_fuse: 'blast',
  b8i_quarrel: 'hit', b8i_panic: 'warn', b8i_rage: 'blast', b8i_solo: 'blast',
  b8h_bluefire: 'fire', b8h_skull: 'dark', b8h_talk: 'warn', b8h_contract: 'warn', b8h_soul: 'dark', b8h_hot: 'hit', b8h_anger: 'blast',
  b8h_fist: 'smash', b8h_flare: 'fire', b8h_shout: 'warn', b8h_erupt: 'blast', b8h_cool: 'ice',
};

// ───────────── え（client/battle.js の monsterCanvas の かわり）─────────────
// ハデロスが おこったら おなじ え の コマ 2・3。小おにの パニック・カンカンも コマ 2・3（render/c8b-art.js）
export function c8bSprite(c, frame) {
  // 第8章 第3幕（battle-c8c.js）
  const s8 = c8cSprite(c, frame);
  if (s8) return s8;
  const sp = c?.species;
  if (sp === C8_HADES && c.c8hform === 2) return monsterCanvas(C8_HADES, (frame ? 1 : 0) + 2);
  if ((sp === C8_PAIN || sp === C8_PANIC) && c.impForm === 2) return monsterCanvas(sp, (frame ? 1 : 0) + 2);
  return null;
}

// しるしの うしろの くらい まる（背景と まざらない）
function backDot(x, cx, cy, r, base) {
  x.globalAlpha = base * 0.6;
  x.fillStyle = '#060c18';
  x.beginPath();
  x.arc(cx, cy, r, 0, Math.PI * 2);
  x.fill();
}
// おばけ（ばけばけの しるし）
function ghostMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.arc(cx, cy - s * 0.2, s * 0.75, Math.PI, 0);
  x.lineTo(cx + s * 0.75, cy + s * 0.7);
  x.lineTo(cx + s * 0.25, cy + s * 0.4);
  x.lineTo(cx - s * 0.25, cy + s * 0.7);
  x.lineTo(cx - s * 0.75, cy + s * 0.4);
  x.closePath();
  x.fill();
}
// まき物（けいやくの しるし）
function scrollMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.fillRect(cx - s * 0.6, cy - s * 0.7, s * 1.2, s * 1.4);
  x.fillRect(cx - s * 0.85, cy - s * 0.85, s * 1.7, s * 0.35);
  x.fillRect(cx - s * 0.85, cy + s * 0.5, s * 1.7, s * 0.35);
}
// たましい（とられるまでの しるし）
function soulMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.arc(cx, cy + s * 0.2, s * 0.6, 0, Math.PI * 2);
  x.moveTo(cx - s * 0.5, cy);
  x.quadraticCurveTo(cx, cy - s * 1.4, cx + s * 0.3, cy - s * 0.9);
  x.quadraticCurveTo(cx + s * 0.2, cy - s * 0.3, cx + s * 0.55, cy);
  x.fill();
}
// ほのお（ふん火の しるし）
function flameMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.moveTo(cx, cy - s);
  x.quadraticCurveTo(cx + s * 0.9, cy, cx, cy + s * 0.8);
  x.quadraticCurveTo(cx - s * 0.9, cy, cx, cy - s);
  x.fill();
}
// のこりの しるしを ならべる（on … のこり・max … ぜんぶ）
function marks(x, px, py, w, on, max, base, T, draw, cols) {
  const gap = 11, x0 = px + w / 2 - ((max - 1) * gap) / 2, y0 = Math.max(6, py - 6);
  for (let i = 0; i < max; i++) {
    const lit = i < on;
    const last = lit && on === 1;
    backDot(x, x0 + i * gap, y0, 5, base);
    x.globalAlpha = base * (lit ? (last ? 0.7 + Math.sin(T / 80) * 0.3 : 0.95) : 0.3);
    draw(x, x0 + i * gap, y0, 4, lit ? (last ? cols[1] : cols[0]) : cols[2]);
  }
  x.globalAlpha = base;
}
// 小さな 文字の ふだ
function tag(x, tx, ty, text, base, bg, fg, wd = 30) {
  x.globalAlpha = base * 0.85;
  x.fillStyle = bg;
  x.fillRect(Math.round(tx - wd / 2), Math.round(ty - 5), wd, 10);
  x.globalAlpha = base;
  x.fillStyle = fg;
  x.font = 'bold 7px sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText(text, tx, ty + 0.5);
  x.textAlign = 'start';
  x.textBaseline = 'alphabetic';
}
// あせの しずく（パニック）
function sweat(x, px, py, w, h, base, T) {
  for (let i = 0; i < 3; i++) {
    const t = ((T / 400 + i / 3) % 1);
    const sx = px + w * (0.2 + i * 0.3), sy = py + h * 0.2 + t * h * 0.3;
    x.globalAlpha = base * (1 - t) * 0.9;
    x.fillStyle = '#9ad8ff';
    x.beginPath();
    x.moveTo(sx, sy - 3);
    x.quadraticCurveTo(sx + 2.5, sy + 1, sx, sy + 2.5);
    x.quadraticCurveTo(sx - 2.5, sy + 1, sx, sy - 3);
    x.fill();
  }
  x.globalAlpha = base;
}
// 赤い ちらちら（ハデロスが おこる 前ぶれ）
function flicker(x, px, py, w, h, base, T) {
  for (let i = 0; i < 4; i++) {
    const a = 0.4 + Math.sin(T / 70 + i * 1.7) * 0.4;
    if (a <= 0.05) continue;
    x.globalAlpha = base * a;
    flameMark(x, px + w * (0.35 + i * 0.1), py + h * 0.08 + (i % 2) * 3, 3 + (i % 2), '#ff4a2a');
  }
  x.globalAlpha = base;
}

// ───────────── たたかいの え（client/battle-c8a.js の c8aDraw から）─────────────
export function c8bDraw(scene, x, m, c, px, py, w, h, base) {
  if (!c?.alive) return;
  // 第8章 第3幕（battle-c8c.js）
  c8cDraw(scene, x, m, c, px, py, w, h, base);
  const T = scene.time || 0;
  // 小おに
  if (c.impEvery) {
    marks(x, px, py, w, c.impLeft || 0, c.impEvery, base, T, ghostMark, ['#e8f0ff', '#ff6a4a', '#2a3040']);
    if (c.plot) tag(x, px + w / 2, py + h * 0.18, 'ひそひそ', base, '#10203a', '#9ad8ff', 36);
  }
  if (c.quarrel) tag(x, px + w / 2, py + h * 0.3, 'けんか', base, '#3a1a0a', '#ffb06a');
  if (c.panicLeft) {
    sweat(x, px, py, w, h, base, T);
    tag(x, px + w / 2, Math.max(8, py - 4), 'あたふた', base, '#10203a', '#9ad8ff', 36);
    tag(x, px + w / 2, py + h * 0.62, `×${c.panicK ?? 1.5}`, base, '#1a2a10', '#c8ff8a');
  }
  if (c.rage) {
    tag(x, px + w / 2, py + h * 0.18, 'カンカン', base, '#3a0808', '#ff8a6a', 36);
    marks(x, px, py, w, c.soloLeft || 0, c.soloEvery || 2, base, T, ghostMark, ['#ffb0a0', '#ff3a3a', '#3a2020']);
  }
  // ハデロス
  if (c.c8hform === 1) {
    if (c.bound) {
      tag(x, px + w / 2, py + h * 0.18, 'けいやく', base, '#1a0a2a', '#e0c8ff', 36);
      marks(x, px, py, w, (c.soulLeft ?? 0) + 1, 3, base, T, soulMark, ['#c8e0ff', '#ff4a6a', '#2a2a3a']);
    } else marks(x, px, py, w, c.contractLeft || 0, c.contractEvery || 4, base, T, scrollMark, ['#f0e0b0', '#ff6a4a', '#3a3428']);
    if (c.flicker) flicker(x, px, py, w, h, base, T);
  }
  if (c.c8hform === 2) marks(x, px, py, w, c.eruptLeft || 0, c.eruptEvery || 3, base, T, flameMark, ['#ff9a4a', '#ff2a2a', '#3a2010']);
  if (c.hot) tag(x, px + w / 2, py + h * 0.3, 'あちちっ', base, '#3a1a0a', '#ffd06a', 36);
  if (c.cool) tag(x, px + w / 2, py + h * 0.3, 'ひえひえ', base, '#0a1a3a', '#9ae6ff', 36);
}

// ───────────── けいやくされた 人の まどの しるし ─────────────
const CSS = `
.b-mem.c8b-bound { box-shadow: 0 0 0 2px #000, inset 0 0 14px rgba(150, 110, 230, 0.9); }
.b-mem.c8b-bound::after {
  content: 'けいやく'; position: absolute; left: 50%; top: -0.95em; transform: translateX(-50%); z-index: 3; pointer-events: none;
  font-size: 0.78em; line-height: 1.25; white-space: nowrap; padding: 0 0.45em; color: #f0e8ff;
  background: rgba(26, 10, 44, 0.94); border: 1px solid #9a6ae0; border-radius: 4px; box-shadow: 0 0 0 1px #000;
}
`;
let styled = false;
function ensureCss() {
  if (styled || typeof document === 'undefined') return;
  styled = true;
  document.head.append(el('style', { id: 'c8b-css', text: CSS }));
}
// けいやくされた 人（ev.c8bContract の 人。もえる・とられる・おこると はずす）を 覚えて おく
export function c8bMarks(scene) {
  if (!scene.allies || !scene.statusBoxes) return;
  let any = false;
  for (const a of scene.allies()) {
    const s = scene.statusBoxes.get(a.id);
    if (!s) continue;
    const on = a.alive && scene.c8bBound === a.id;
    if (on) any = true;
    s.box.classList.toggle('c8b-bound', !!on);
  }
  if (any) ensureCss();
}

// ───────────── イベントを 見せる とき（client/battle-c8a.js の c8aPresent から）─────────────
export function c8bPresent(scene, ev, fx, anim, actor) {
  const g = scene.game;
  const nameOf = (id) => scene.c?.get?.(id)?.name || '';
  // ペイニックと パニクル
  if (ev.c8bImpLeft?.plot && ev.c8bImpLeft.left > 1) {
    g.audio.sfx('warn');
    scene.banner('！2ひきが、ひそひそ相談している…強い一撃でじゃましよう！', 'danger');
  }
  if (ev.c8bImpLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、ばけばけ大がったい…！', 'danger');
  }
  if (ev.c8bQuarrel) {
    g.audio.sfx('crit');
    scene.banner('作戦がばれた！2ひきがけんかを始めた！', 'combo');
  }
  if (ev.c8bFuse) {
    scene.shake?.(900, 9);
    scene.banner('ばけばけ大がったい…！', 'danger');
  }
  if (ev.c8bPanic) {
    g.audio.sfx('sparkle');
    scene.banner(`${nameOf(ev.c8bPanic.id)}がパニックになった！今ならダメージ${ev.c8bPanic.k}倍！`, 'combo');
  }
  if (ev.c8bRage) {
    scene.shake?.(800, 8);
    scene.banner(`${nameOf(ev.c8bRage.id)}が、カンカンにおこった…！`, 'danger');
  }
  if (ev.c8bSoloLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、ひとりばけばけ…！身を守れ！', 'danger');
  }
  if (ev.c8bSolo) {
    scene.shake?.(800, 8);
    scene.banner('ひとりばけばけ…！', 'danger');
  }
  // ハデロス
  if (ev.c8bContractLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、たましいのけいやく…！', 'danger');
  }
  if (ev.c8bContract) {
    scene.c8bBound = ev.c8bContract.who;
    scene.banner(`${nameOf(ev.c8bContract.who)}に、けいやくしょがはりついた…！炎でもやせ！`, 'danger');
  }
  if (ev.c8bDrain?.left === 0) {
    g.audio.sfx('warn');
    scene.banner(`！次に、${nameOf(ev.c8bDrain.who)}のたましいがとられる…！`, 'danger');
  }
  if (ev.c8bBurnt) {
    g.audio.sfx('crit');
    scene.c8bBound = null;
    scene.banner('けいやくしょがもえた！ハデロスがあわてている！', 'combo');
  }
  if (ev.c8bSoul) {
    scene.c8bBound = null;
    scene.shake?.(700, 7);
    scene.banner(`${nameOf(ev.c8bSoul.who)}のたましいが、とられてしまった…！`, 'danger');
  }
  if (ev.c8bFlicker) {
    g.audio.sfx('warn');
    scene.banner('！ハデロスのかみの毛が、赤くちらちら…もうすぐおこるぞ！', 'danger');
  }
  if (ev.c8bAnger) {
    scene.c8bBound = null;
    scene.shake?.(1000, 10);
    scene.banner('ハデロスがおこった！赤い炎…弱点がかわった！', 'danger');
  }
  if (ev.c8bEruptLeft?.left === 2) {
    g.audio.sfx('warn');
    scene.banner('！もうすぐ、よみの大ふん火…今のうちに氷で頭をひやせ！', 'danger');
  }
  if (ev.c8bEruptLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、よみの大ふん火…！氷で頭をひやせ！', 'danger');
  }
  if (ev.c8bErupt) {
    scene.shake?.(1000, 10);
    scene.banner('よみの大ふん火…！', 'danger');
  }
  if (ev.c8bCool) {
    g.audio.sfx('crit');
    scene.banner('頭がひえた！大ふん火がしぼんだ！', 'combo');
  }
  c8bMarks(scene);
  // 第8章 第3幕（battle-c8c.js）
  c8cPresent(scene, ev, fx, anim, actor);
  void fx; void anim; void actor;
}

js/client/battle-c8c.js:
// 第2部 第8章 第3幕 の マジカメック（ほうき）・初代大魔王クッパード（ギガ）・橋のオノ・手下の 魔物の がめん
// （client/battle-c8b.js から よぶ。サーバーがわは shared/battle-c8c.js）
// ・マジカメック: 頭の 上に でっかくなあれまでの しるし（星。のこり 1 は 赤く ゆれる）。ちびカメックの 間は え が 小さく なり「ちびカメック」と「×2」。
//   ほうきに のると え は コマ 2・3（c8cSprite）
// ・子分: 魔法じんの 間は 足もとに 回る 魔法じんと「×2」。デカ〜に なると え が 大きく なる（c8cSprite が 大きく した え を かえす）
// ・クッパード: 1だんめ … ドッスンヒップドロップまでの しるし（下むきの 三角）・かけらが 光る 前ぶれ（むらさきの きらきら）・
//   また ギガに なるまでの しるし（むらさきの 星）・目を 回している 間は「ぐるぐる」／2だんめ … ギガほのおまでの しるし（ほのお）。え は コマ 2・3
// ・橋のオノ: のこりの たたく 回数（オノの しるし）と「ぶきで たたけ」
// ・バナー: 魔法じん・でっかくなあれの 前ぶれ・でっかくなった・魔法じんが 消えた・ちびカメック・ほうき／
//   ヒップドロップの 前ぶれ・ヒップドロップ・かけらが 光る・ギガ・ギガほのおの 前ぶれ・ギガほのお・オノが かたむいた・橋が おちた・また ギガの 前ぶれ
// ・敵が 使うと がめんの まん中に 大きく 出す 技・味方の まどの えんしゅつ・音（client/battle-ch4.js・client/battle.js に まぜる）
import { C8_KAMEK, C8_BOWSER } from '../shared/data/monsters-c8c.js';
import { monsterCanvas } from './render/monsters.js';

// 前ぶれの バナーを 自分で 出す（client/battle-c8b.js の C8B_OWN_TELE に まぜる）
export const C8C_OWN_TELE = [C8_KAMEK, C8_BOWSER];

export const C8C_SCREEN_ANIMS = ['c8k_grow', 'c8k_broom', 'c8w_pound', 'c8w_giga', 'c8w_gigafire'];
export const C8C_ALLY_FX = {
  c8n_hop: 'fire', c8n_magma: 'fire', c8n_throw: 'claw', c8n_jump: 'quake', c8n_rain: 'claw', c8n_bite: 'claw', c8n_dash: 'claw',
  c8n_drop: 'quake', c8n_quake: 'quake', c8n_glare: 'down', c8n_rush: 'quake', c8n_boom: 'fire',
  c8k_shapes: 'bolt', c8k_spark: 'bolt', c8k_shrink: 'down', c8k_broomhit: 'claw', c8k_kstomp: 'quake',
  c8w_claw: 'claw', c8w_breath: 'fire', c8w_shell: 'quake', c8w_pound: 'quake', c8w_gstomp: 'quake', c8w_gbreath: 'fire', c8w_groar: 'down', c8w_gigafire: 'fire',
};
export const C8C_SFX = {
  c8n_hop: 'fire', c8n_magma: 'fire', c8n_bounce: 'buff', c8n_throw: 'hit', c8n_jump: 'smash', c8n_rain: 'hit', c8n_bite: 'hit', c8n_dash: 'smash', c8n_wind: 'buff',
  c8n_drop: 'smash', c8n_quake: 'smash', c8n_glare: 'warn', c8n_rush: 'smash', c8n_boom: 'blast', c8n_aim: 'buff',
  c8k_shapes: 'bolt', c8k_spark: 'bolt', c8k_shrink: 'warn', c8k_broomhit: 'smash', c8k_grow: 'blast', c8k_summon: 'warn', c8k_broom: 'buff', c8k_fizzle: 'sparkle', c8k_kstomp: 'smash',
  c8w_claw: 'hit', c8w_breath: 'fire', c8w_shell: 'smash', c8w_pound: 'blast', c8w_giga: 'blast', c8w_fallen: 'hit', c8w_gstomp: 'smash', c8w_gbreath: 'fire', c8w_groar: 'warn', c8w_gigafire: 'blast',
};

// ───────────── え（client/battle.js の monsterCanvas の かわり）─────────────
// マジカメックが ほうきに のったら・クッパードが ギガに なったら おなじ え の コマ 2・3。デカ〜の 子分は 大きく した え
const BIG = new Map();
const GIGA_K = 1.8;
const TINY_K = 0.6;
function bigCanvas(sp, frame, k = GIGA_K) {
  if (typeof document === 'undefined') return null;
  const key = `${sp}|${frame}|${k}`;
  if (BIG.has(key)) return BIG.get(key);
  const src = monsterCanvas(sp, frame);
  const c = document.createElement('canvas');
  c.width = src.width;
  c.height = src.height;
  c.getContext('2d').drawImage(src, 0, 0);
  // こまかさ（res）を かえて、がめんでは k ばいの 大きさに 見せる（デカ〜は 大きく・ちびカメックは 小さく）
  c.res = (src.res || 1) / k;
  BIG.set(key, c);
  return c;
}
export function c8cSprite(c, frame) {
  const sp = c?.species;
  if (sp === C8_KAMEK && c.tiny) return bigCanvas(C8_KAMEK, (frame ? 1 : 0) + (c.kmForm === 2 ? 2 : 0), TINY_K);
  if (sp === C8_KAMEK && c.kmForm === 2) return monsterCanvas(C8_KAMEK, (frame ? 1 : 0) + 2);
  if (sp === C8_BOWSER && c.bwForm === 2) return monsterCanvas(C8_BOWSER, (frame ? 1 : 0) + 2);
  if (c?.giga) return bigCanvas(sp, frame ? 1 : 0);
  return null;
}

// しるしの うしろの くらい まる（背景と まざらない）
function backDot(x, cx, cy, r, base) {
  x.globalAlpha = base * 0.6;
  x.fillStyle = '#060c18';
  x.beginPath();
  x.arc(cx, cy, r, 0, Math.PI * 2);
  x.fill();
}
// 星（でっかくなあれ・また ギガの しるし）
function starMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const r = i % 2 ? s * 0.45 : s;
    x.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
  }
  x.closePath();
  x.fill();
}
// 下むきの 三角（ヒップドロップの しるし）
function dropMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.moveTo(cx - s * 0.8, cy - s * 0.6);
  x.lineTo(cx + s * 0.8, cy - s * 0.6);
  x.lineTo(cx, cy + s * 0.8);
  x.closePath();
  x.fill();
}
// ほのお（ギガほのおの しるし）
function flameMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.beginPath();
  x.moveTo(cx, cy - s);
  x.quadraticCurveTo(cx + s * 0.9, cy, cx, cy + s * 0.8);
  x.quadraticCurveTo(cx - s * 0.9, cy, cx, cy - s);
  x.fill();
}
// オノ（橋の オノの しるし）
function axeMark(x, cx, cy, s, col) {
  x.fillStyle = col;
  x.fillRect(cx - s * 0.12, cy - s * 0.9, s * 0.24, s * 1.8);
  x.beginPath();
  x.moveTo(cx, cy - s * 0.8);
  x.lineTo(cx + s * 0.9, cy - s * 0.9);
  x.lineTo(cx + s * 0.9, cy + s * 0.1);
  x.lineTo(cx, cy);
  x.closePath();
  x.fill();
}
// のこりの しるしを ならべる（on … のこり・max … ぜんぶ）
function marks(x, px, py, w, on, max, base, T, draw, cols) {
  const gap = 11, x0 = px + w / 2 - ((max - 1) * gap) / 2, y0 = Math.max(6, py - 6);
  for (let i = 0; i < max; i++) {
    const lit = i < on;
    const last = lit && on === 1;
    backDot(x, x0 + i * gap, y0, 5, base);
    x.globalAlpha = base * (lit ? (last ? 0.7 + Math.sin(T / 80) * 0.3 : 0.95) : 0.3);
    draw(x, x0 + i * gap, y0, 4, lit ? (last ? cols[1] : cols[0]) : cols[2]);
  }
  x.globalAlpha = base;
}
// 小さな 文字の ふだ
function tag(x, tx, ty, text, base, bg, fg, wd = 30) {
  x.globalAlpha = base * 0.85;
  x.fillStyle = bg;
  x.fillRect(Math.round(tx - wd / 2), Math.round(ty - 5), wd, 10);
  x.globalAlpha = base;
  x.fillStyle = fg;
  x.font = 'bold 7px sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText(text, tx, ty + 0.5);
  x.textAlign = 'start';
  x.textBaseline = 'alphabetic';
}
// 足もとで 回る 魔法じん（でっかくなあれの 前ぶれ）
function circle(x, px, py, w, h, base, T) {
  const cx = px + w / 2, cy = py + h - 2, rx = Math.max(12, w * 0.55), ry = rx * 0.3;
  x.globalAlpha = base * (0.55 + Math.sin(T / 120) * 0.25);
  x.strokeStyle = '#ff7ae0';
  x.lineWidth = 1.2;
  x.beginPath();
  x.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
  x.stroke();
  x.beginPath();
  x.ellipse(cx, cy, rx * 0.7, ry * 0.7, 0, 0, Math.PI * 2);
  x.stroke();
  x.fillStyle = '#ffe0fa';
  for (let i = 0; i < 6; i++) {
    const a = T / 500 + (i * Math.PI) / 3;
    x.fillRect(Math.round(cx + Math.cos(a) * rx * 0.85) - 1, Math.round(cy + Math.sin(a) * ry * 0.85) - 1, 2, 2);
  }
  x.globalAlpha = base;
}
// むらさきの きらきら（黒い 星の かけらが 光る 前ぶれ）
function shardGlow(x, px, py, w, h, base, T) {
  for (let i = 0; i < 4; i++) {
    const a = 0.45 + Math.sin(T / 90 + i * 1.6) * 0.45;
    if (a <= 0.05) continue;
    x.globalAlpha = base * a;
    starMark(x, px + w * (0.25 + i * 0.17), py + h * (0.3 + (i % 2) * 0.12), 2.5 + (i % 2), '#c88aff');
  }
  x.globalAlpha = base;
}
// 頭の 上の ぐるぐる（橋から おちて 目を 回している）
function dizzy(x, px, py, w, base, T) {
  for (let i = 0; i < 3; i++) {
    const a = T / 200 + (i * Math.PI * 2) / 3;
    x.globalAlpha = base * 0.9;
    starMark(x, px + w / 2 + Math.cos(a) * 10, Math.max(6, py + 4) + Math.sin(a) * 3, 3, '#fff6a0');
  }
  x.globalAlpha = base;
}

// ───────────── たたかいの え（client/battle-c8b.js の c8bDraw から）─────────────
export function c8cDraw(scene, x, m, c, px, py, w, h, base) {
  if (!c?.alive) return;
  const T = scene.time || 0;
  // マジカメック
  if (c.growEvery) marks(x, px, py, w, c.growLeft || 0, c.growEvery, base, T, starMark, ['#ffe0fa', '#ff4ad8', '#2a2040']);
  if (c.tiny) {
    tag(x, px + w / 2, Math.max(8, py - 4), 'ちびカメック', base, '#2a1040', '#ffd0f8', 44);
    tag(x, px + w / 2, py + h * 0.8, `×${c.tinyK ?? 2}`, base, '#1a2a10', '#c8ff8a');
  }
  // 子分（魔法じん）
  if (c.aimed) {
    circle(x, px, py, w, h, base, T);
    tag(x, px + w / 2, Math.max(8, py - 4), '魔法じん', base, '#2a1040', '#ffb0f0', 36);
    tag(x, px + w / 2, py + h * 0.82, '×2', base, '#1a2a10', '#c8ff8a', 22);
  }
  // クッパード
  if (c.bwForm === 1) {
    if (c.poundEvery) marks(x, px, py, w, c.poundLeft || 0, c.poundEvery, base, T, dropMark, ['#ffd040', '#ff3a3a', '#3a3020']);
    if (c.flicker) shardGlow(x, px, py, w, h, base, T);
    // また ギガに なるまでの のこり（目を 回している 間は 出さない）
    if (c.regrowLeft && !c.fallen) tag(x, px + w / 2, py + h * 0.18, `かけら ${c.regrowLeft}`, base, '#200a30', '#d8a8ff', 36);
    if (c.fallen) {
      dizzy(x, px, py, w, base, T);
      tag(x, px + w / 2, py + h * 0.3, 'ぐるぐる', base, '#3a3010', '#fff6a0', 36);
    }
  }
  if (c.bwForm === 2) marks(x, px, py, w, c.fireLeft || 0, c.fireEvery || 3, base, T, flameMark, ['#ff9a4a', '#ff2a2a', '#3a2010']);
  // 橋の オノ
  if (c.axeMax) {
    marks(x, px, py, w, c.axeLeft || 0, c.axeMax, base, T, axeMark, ['#e0e6f0', '#ffd040', '#2a2a3a']);
    tag(x, px + w / 2, py + h * 0.55, 'ぶきでたたけ', base, '#3a1a0a', '#ffd06a', 44);
  }
}

// ───────────── イベントを 見せる とき（client/battle-c8b.js の c8bPresent から）─────────────
export function c8cPresent(scene, ev, fx, anim, actor) {
  const g = scene.game;
  const nameOf = (id) => scene.c?.get?.(id)?.name || '';
  // マジカメック
  if (ev.c8cAim) {
    g.audio.sfx('warn');
    scene.banner(`！${nameOf(ev.c8cAim.who)}に魔法じん…先にたおせ！`, 'danger');
  }
  if (ev.c8cGrowLeft?.left === 1 && !ev.c8cAim) {
    g.audio.sfx('warn');
    scene.banner('！次に、でっかくなあれ…！', 'danger');
  }
  if (ev.c8cGrow) {
    scene.shake?.(900, 9);
    scene.banner(`${nameOf(ev.c8cGrow.who)}が、大きくなった…！`, 'danger');
  }
  if (ev.c8cAimGone) {
    g.audio.sfx('crit');
    scene.banner('魔法じんが消えた！魔法はから回りするぞ！', 'combo');
  }
  if (ev.c8cFizzle) {
    g.audio.sfx('sparkle');
    scene.banner(`魔法がはね返った！ちびカメック！今ならダメージ${ev.c8cFizzle.k ?? 2}倍！`, 'combo');
  }
  if (ev.c8cBroom) {
    scene.shake?.(600, 6);
    scene.banner('マジカメックがほうきで空へ！魔法が速くなった！', 'danger');
  }
  // クッパード
  if (ev.c8cPoundLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、ドッスンヒップドロップ…！身を守れ！', 'danger');
  }
  if (ev.c8cPound) {
    scene.shake?.(900, 10);
    scene.banner('ドッスンヒップドロップ…！', 'danger');
  }
  if (ev.c8cFlicker) {
    g.audio.sfx('warn');
    scene.banner('！黒い星のかけらが光っている…何かが起こるぞ！', 'danger');
  }
  if (ev.c8cGiga) {
    scene.shake?.(1200, 12);
    scene.banner('ギガクッパード…！橋のオノを、ぶきでたたけ！', 'danger');
  }
  if (ev.c8cFireLeft?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！次に、ギガほのお…！身を守るか、オノをたたけ！', 'danger');
  }
  if (ev.c8cGigaFire) {
    scene.shake?.(1000, 10);
    scene.banner('ギガほのお…！', 'danger');
  }
  if (ev.c8cAxeHit?.left > 0) {
    g.audio.sfx('hit');
    scene.banner(`オノがかたむいた！あと${ev.c8cAxeHit.left}回！`, 'combo');
  }
  if (ev.c8cFall) {
    g.audio.sfx('crit');
    scene.shake?.(1000, 10);
    scene.banner('橋がおちた！クッパードが、もとの大きさにもどった！', 'combo');
  }
  if (ev.c8cRegrow?.left === 1) {
    g.audio.sfx('warn');
    scene.banner('！かけらがまた光り出した…次にギガクッパード！', 'danger');
  }
  void fx; void anim; void actor;
}

