// 第2部 第6章 Step 1・2 の サンドクロック・ギアドンと 新しい 魔物の がめん（client/battle-ch5.js・client/battle.js から よぶ。サーバーがわは shared/battle-ch6.js）
// ・サンドクロック: よこに 砂時計の 目もり（のこりの 砂。あと1つで 赤く 光る）。大砂流の 前ぶれの 間は まわりに 砂色の うずの わ
// ・ギアドン: 時を 覚えている 間は、むねの 大歯車の まわりに 青い 時計の わ（まきもどしまでの のこり）と、雷の 目もり（あと 何回）。
//   ギアプレスの 前ぶれの 間は 赤い わ
// ・前ぶれ・止めた・こわした・まきもどした ときの バナー（ふつうの「大技が来る！」は 出さない … CH6_OWN_TELE）
// ・敵が 使うと がめんの まん中に 大きく 出す 技・味方の まどの えんしゅつ・音
// 第2部 第6章 Step 3・4 の 星くいのよる鳥・ペンデュラ（battle-road.js。ここから よぶ）
import { ROAD_OWN_TELE, roadDraw, roadPresent } from './battle-road.js';
// 第2部 第6章 Step 5 の カリヨン（かねの しるし。battle-tokei.js。ここから よぶ）
import { tokeiDraw, tokeiPresent } from './battle-tokei.js';
// 第2部 第6章 Step 6: ゼンマイが 家来の しかけを 使う 間・時のまぼろしも おなじ 絵と バナー（kindOf … kindAs・base・species。battle-tokei6.js）
import { kindOf, TOKEI6_OWN_TELE, tokei6Draw, tokei6Present } from './battle-tokei6.js';
// 第2部 第7章 第1幕: ウツボきょうだい（いきの しるし・よびもどし）・オクタリア（声うばい・声の貝）。battle-c7.js
import { C7_OWN_TELE, c7Draw, c7Present } from './battle-c7.js';

const SAND = 'sand_clock';
const GEAR = 'geardon';
// 前ぶれの バナーを 自分で 出す 魔物（client/battle.js の ふつうの「大技が来る！」を 出さない）
export const CH6_OWN_TELE = new Set([SAND, GEAR, ...ROAD_OWN_TELE, ...TOKEI6_OWN_TELE, ...C7_OWN_TELE]);

export const CH6_SCREEN_ANIMS = ['a6_stomp', 'a6_storm', 'a6_fall', 'a6_steam', 'a6_press', 'a6_rewind_big', 'a6_slow'];
export const CH6_ALLY_FX = {
  a6_horn: 'claw', a6_stomp: 'quake', a6_amber: 'up', a6_wing: 'wind', a6_dust: 'dark', a6_root: 'down', a6_leaf: 'wind',
  a6_kick: 'claw', a6_bell: 'dark', a6_flow: 'wind', a6_sand: 'dark', a6_tail: 'claw', a6_pinch: 'claw', a6_fist: 'claw', a6_pit: 'quake',
  a6_ghorn: 'claw', a6_spin: 'claw', a6_spear: 'claw', a6_beam: 'up', a6_swing: 'claw', a6_ring: 'dark', a6_tick: 'down',
  a6_tblade: 'claw', a6_slow: 'down', a6_stop: 'bolt', a6_hand: 'ice', a6_song: 'dark', a6_fang: 'claw', a6_web: 'down', a6_jump: 'claw',
  a6_spray: 'claw', a6_pend: 'claw', a6_storm: 'wind', a6_fall: 'quake', a6_gfist: 'claw', a6_cog: 'claw', a6_needle: 'claw', a6_steam: 'fire', a6_press: 'quake',
};
export const CH6_SFX = {
  a6_horn: 'smash', a6_stomp: 'smash', a6_call: 'buff', a6_amber: 'sparkle', a6_wing: 'wind', a6_dust: 'warn', a6_root: 'hit', a6_leaf: 'wind', a6_nut: 'heal',
  a6_kick: 'hit', a6_hurry: 'buff', a6_bell: 'warn', a6_flow: 'wind', a6_sand: 'warn', a6_hide: 'buff', a6_tail: 'hit', a6_pinch: 'hit', a6_shell: 'buff',
  a6_fist: 'smash', a6_pit: 'smash', a6_mend: 'heal', a6_ghorn: 'smash', a6_spin: 'hit', a6_wind: 'buff', a6_spear: 'hit', a6_beam: 'sparkle', a6_guard: 'buff',
  a6_swing: 'hit', a6_ring: 'warn', a6_tick: 'warn', a6_tblade: 'smash', a6_slow: 'warn', a6_stop: 'bolt', a6_hand: 'ice', a6_rewind: 'heal', a6_song: 'warn',
  a6_fang: 'hit', a6_web: 'warn', a6_jump: 'smash', a6_spray: 'hit', a6_pend: 'smash', a6_storm: 'wind', a6_fall_charge: 'warn', a6_fall: 'blast',
  a6_gfist: 'smash', a6_cog: 'hit', a6_needle: 'hit', a6_steam: 'fire', a6_press_charge: 'warn', a6_press: 'blast', a6_record: 'warn', a6_rewind_big: 'warn',
  a6_dew: 'heal', a6_prayer: 'heal', a6_comet: 'sparkle', a6_read: 'buff',
};

// ───────────── たたかいの え（client/battle-ch5.js の towerDraw から）─────────────
export function ch6Draw(scene, x, m, c, px, py, w, h, base) {
  if (!c?.alive) return;
  roadDraw(scene, x, m, c, px, py, w, h, base);
  tokeiDraw(scene, x, m, c, px, py, w, h, base);
  tokei6Draw(scene, x, m, c, px, py, w, h, base);
  c7Draw(scene, x, m, c, px, py, w, h, base);
  const T = scene.time || 0;
  // サンドクロック: 砂の 目もり（右よこ）と 前ぶれの うず
  if (kindOf(c) === SAND && c.sand !== undefined) {
    const max = c.sandMax || 6;
    const bx = Math.min(250, px + w + 3), by = py + h * 0.2, cell = Math.max(4, Math.min(7, Math.floor((h * 0.6) / max)));
    for (let i = 0; i < max; i++) {
      // 下から つむ（上の ほうが さいごの 砂）
      const on = i < c.sand;
      const low = c.sand <= 1 && on;
      x.globalAlpha = base * (on ? (low ? 0.7 + Math.sin(T / 90) * 0.3 : 0.95) : 0.35);
      x.fillStyle = on ? (low ? '#ff6a4a' : '#f0c870') : '#5a4a30';
      x.fillRect(bx, by + (max - 1 - i) * cell, 4, cell - 1);
    }
    x.globalAlpha = base;
    if (c.telegraph) {
      for (let i = 0; i < 3; i++) {
        const a = T / 200 + i * 2.1;
        x.globalAlpha = base * (0.5 + Math.sin(T / 120 + i) * 0.25);
        x.strokeStyle = i % 2 ? '#fff0b8' : '#e8c070';
        x.lineWidth = 2;
        x.beginPath();
        x.ellipse(px + w / 2, py + h * (0.45 + i * 0.12), w * (0.55 - i * 0.05), h * 0.1, 0, a, a + Math.PI * 1.4);
        x.stroke();
      }
      x.globalAlpha = base;
    }
  }
  // ギアドン: まきもどしまでの わ・雷の 目もり / ギアプレスの 前ぶれ
  if (kindOf(c) === GEAR) {
    const cx = px + w / 2, cy = py + h * 0.52;
    if (c.gearRec) {
      const r = Math.max(10, w * 0.24);
      x.globalAlpha = base * (0.65 + Math.sin(T / 110) * 0.25);
      x.strokeStyle = '#7ad0ff';
      x.lineWidth = 2;
      x.beginPath();
      x.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 - Math.PI * 2 * Math.min(1, (c.gearLeft || 0) / 4), true);
      x.stroke();
      // 時計の 針が さかさまに 回る
      const a = -T / 160;
      x.strokeStyle = '#c8f0ff';
      x.beginPath();
      x.moveTo(cx, cy);
      x.lineTo(cx + Math.cos(a) * r * 0.8, cy + Math.sin(a) * r * 0.8);
      x.stroke();
      // 雷の 目もり（当てた 数）
      const need = c.gearNeed || 2;
      for (let i = 0; i < need; i++) {
        x.globalAlpha = base;
        x.fillStyle = i < (c.gearHits || 0) ? '#fff070' : 'rgba(255,255,255,0.3)';
        const qx = cx - (need - 1) * 6 + i * 12, qy = py - 4;
        x.beginPath();
        x.moveTo(qx + 1, qy - 4);
        x.lineTo(qx - 3, qy + 1);
        x.lineTo(qx, qy + 1);
        x.lineTo(qx - 1, qy + 5);
        x.lineTo(qx + 3, qy - 1);
        x.lineTo(qx, qy - 1);
        x.closePath();
        x.fill();
      }
      x.globalAlpha = base;
    }
    if (c.telegraph && !c.gearRec) {
      x.globalAlpha = base * (0.5 + Math.sin(T / 100) * 0.3);
      x.strokeStyle = '#ff6a4a';
      x.lineWidth = 2;
      x.beginPath();
      x.ellipse(cx, py + h * 0.4, w * 0.55, h * 0.45, 0, 0, Math.PI * 2);
      x.stroke();
      x.globalAlpha = base;
    }
  }
}

// ───────────── イベントを 見せる とき（client/battle-ch5.js の towerPresent から）─────────────
export function ch6Present(scene, ev, fx, anim, actor) {
  const g = scene.game;
  roadPresent(scene, ev, fx, anim, actor);
  tokeiPresent(scene, ev, fx, anim, actor);
  tokei6Present(scene, ev, fx, anim, actor);
  c7Present(scene, ev, fx, anim, actor);
  if (fx.type === 'telegraph' && kindOf(actor) === SAND) {
    g.audio.sfx('warn');
    scene.banner('！大砂流の前ぶれ！氷を当てるか、身を守れ！', 'danger');
  } else if (ev.scSand?.lv === 1) {
    g.audio.sfx('warn');
    scene.banner('！砂があと1つ！氷でこおらせて、もどそう', 'danger');
  }
  if (ev.scStop) {
    g.audio.sfx('ice');
    scene.banner('砂がこおって、大砂流を止めた！', 'combo');
  } else if (ev.scBack) {
    g.audio.sfx('ice');
    scene.banner('氷で砂がもどった！', 'combo');
  }
  if (ev.scFall) scene.shake(500, 6);
  if (fx.type === 'telegraph' && kindOf(actor) === GEAR) {
    g.audio.sfx('warn');
    scene.banner('！ギアプレスの前ぶれ！身を守れ！', 'danger');
  }
  if (ev.gdRecord) {
    g.audio.sfx('warn');
    scene.banner(`！${actor?.name || 'ギアドン'}が時を覚えた！雷を${ev.gdRecord.need}回当てて、大歯車をこわせ！`, 'danger');
  }
  if (ev.gdSpark) scene.banner(`大歯車に火花！あと${ev.gdSpark.left}回`, 'combo');
  if (ev.gdBreak) {
    g.audio.sfx('crit');
    scene.shake(400, 5);
    scene.banner('大歯車をこわした！まきもどしを止めた！', 'combo');
  }
  if (ev.gdRewind) {
    scene.banner(ev.gdRewind.heal > 0 ? `時がまきもどった…！キズが${ev.gdRewind.heal}もとにもどった` : '時がまきもどった…！', 'danger');
  }
}

js/client/battle-dual.js:
// たたかいの 画面の 合体技（2人・3人・4人。client/battle.js から よぶ）
//  ・コマンドの「合体技」の 一覧（第31回: 行は 技の 名前だけ 大きく。だれと・何人で・よやくか・必要な 職業は 説明の まどに）
//  ・家族から さそわれた ときの「参加する！／ことわる」
//  ・出す ときの カットインと とどめの えんしゅつ（render/dualfx.js）
import { el, esc, ListMenu, toast } from './ui/dom.js';
import { ABILITIES, ELEMENT_NAMES } from '../shared/data/abilities.js';
import { comboAllowed, weaponOk } from '../shared/stats.js';
import { dualOptions, dualKnown, dualNeedText, dualNeedLabel } from '../shared/data/dual.js';
// 第33回: 男の子の 美少女戦士が 入る ときは 名前・説明が かわる（shared/ability-label.js）
import { dualFor } from '../shared/ability-label.js';
import { faceURL } from './field.js';
import { targetText } from './ui/info.js';
import { playDualCutin, playDualFinale, cutMs, dualFxOf, addDualCss } from './render/dualfx.js';
import { BW, BH } from './render/battlefx.js';

const SECRET = '効果は？？？（一度使うとわかる）';
// その くみあわせ（o.who … 出す 人の id）むけの 合体技
const techOf = (v, o) => dualFor(o.id, (o.who || [o.partner]).map((id) => v.c.get(id)));
const sizeLabel = (n) => `${n}人技`;

// 自分の キャラが 今 出せる 合体技（サーバーでも たしかめる）
export function myDualOptions(v, a) {
  if (!a) return [];
  const info = (x) => ({
    id: x.id, name: x.name, job: x.job, mon: x.mon, alive: x.alive, abilities: x.abilities || [], mp: x.mp, atb: x.atb, ready: x.ready, queued: !!x.queued, hold: !!x.dualHold,
    inviting: false, statuses: x.status || [], weaponCat: x.weaponCat,
    waiting: x.id !== a.id && (!!x.waitDual || (!!x.dualTarget && x.dualTarget !== a.id)),
    usable: (id) => {
      const ab = ABILITIES[id];
      return !!ab && (ab.kind !== 'combo' || comboAllowed(x.pc || { job: x.job, jobs: {} }, id)) && weaponOk(ab, x.weaponCat);
    },
  });
  // 第32回: モンスターの 仲間も（モンスターの 仲間の 組が ある 技だけ）
  const others = v.allies().filter((x) => x.id !== a.id);
  // 人数の 多い 技を 上に
  return dualOptions(info(a), others.map(info), weaponOk, { anyGauge: true }).sort((x, y) => y.size - x.size);
}

// 説明の まど（3行まで）: 人数・属性・相手・いっしょに 出す 人（よやく）／必要な 職業・MP／効果
export function dualInfo(v, o, more = 0) {
  const t = techOf(v, o);
  const tags = [sizeLabel(o.size || 2), ELEMENT_NAMES[o.element], targetText(t)].filter(Boolean).join('・');
  const when = o.now ? '' : '（よやく）';
  const others = more > 0 ? `（ほか${more}通り）` : '';
  const desc = dualKnown(v.game.me, o.id) ? t.desc : SECRET;
  return `【${tags}】${o.partnerName}といっしょに${when}${others}\n${dualNeedLabel(o.id)}：${dualNeedText(o.id, true, v.myActor)}　MP ${o.mp.join('＋')}\n${desc}`;
}

// 合体技の 一覧（コマンド → 合体技）。行は 技の 名前だけ（大きく）。おなじ 技を 出せる 仲間の くみあわせが いくつか ある ときは、
// えらんだ あとに「だれと出す？」を 聞く（1通りなら すぐ）
export function dualMenu(v, opts) {
  if (!opts.length) {
    toast('今は合体技を出せる仲間がいない');
    return v.openCommand();
  }
  addDualCss();
  const role = (t) => (t.parts.some((x) => x.type === 'power') ? 'dmg' : t.parts.some((x) => x.type === 'heal' || x.type === 'cure') ? 'heal' : 'sup');
  // 技ごとに まとめる（すぐ 出せる くみあわせを 先に）
  const groups = new Map();
  for (const o of opts) {
    if (!groups.has(o.id)) groups.set(o.id, []);
    groups.get(o.id).push(o);
  }
  for (const list of groups.values()) list.sort((x, y) => (y.now ? 1 : 0) - (x.now ? 1 : 0));
  const items = [...groups.values()].map((list) => {
    const o = list[0];
    const t = techOf(v, o);
    const n = o.size || 2;
    return { html: `<span class="dual-nm">${esc(t.name)}</span>`, right: `${o.mp[0]}`, value: list, cls: `k-${role(t)} k-dualopt n${n}${list.some((x) => x.now) ? '' : ' later'}` };
  });
  const fire = (o) => {
    const t = techOf(v, o);
    const go = (target) => v.send({ type: 'dual', id: o.id, partner: o.partner, partners: o.partners, target });
    if (t.target === 'enemy' || t.target === 'group') return v.pickFoe(t.target, (tid) => go(tid), t.name, o.element, () => dualMenu(v, myDualOptions(v, v.myActor)));
    return go();
  };
  v.showMenu(items, (it) => {
    const list = it.value;
    if (list.length === 1) return fire(list[0]);
    // だれと 出す？（いっしょに 出す 人の 名前だけ）
    const t = techOf(v, list[0]);
    v.showMenu(list.map((o) => ({ label: `${o.partnerName}${o.now ? '' : '（よやく）'}`, value: o, right: `${o.mp[0]}` })),
      (x) => fire(x.value), () => dualMenu(v, myDualOptions(v, v.myActor)), `「${t.name}」をだれと出す？`, (x) => { if (x) v.info(dualInfo(v, x.value)); });
  }, () => v.openCommand(), '合体技（いっしょに出す人の番を使う）', (it) => {
    if (!it) return;
    v.info(dualInfo(v, it.value[0], it.value.length - 1));
  });
}

// 合体技を えらんだ あとの「返事を待っている」（家族が いっしょなら）
export function askingName(v, cmd) {
  if (cmd.type !== 'dual') return null;
  const ids = cmd.partners?.length ? cmd.partners : [cmd.partner];
  const ask = ids.map((id) => v.c.get(id)).filter((p) => p && p.controller && !p.auto && !v.mine.includes(p.id));
  return ask.length ? ask.map((p) => p.name).join('・') : null;
}

// よやく中・まっている ときの ことば（コマンドの まど）
export function waitText(v, a) {
  if (a.waitDual) {
    const t = dualFor(a.waitDual.id, [a, ...(a.waitDual.partners || [a.waitDual.partner]).map((id) => v.c.get(id))]);
    const names = (a.waitDual.partners || [a.waitDual.partner]).map((id) => v.c.get(id)?.name || '仲間').join('・');
    // ダメージで 力あわせが みだれた（自分の ゲージを ためなおしている）
    if ((a.atb ?? 100) < 99.9) return `力あわせがみだれた！自分と${names}のゲージがたまったら「${t?.name || '合体技'}」を出す…`;
    return `${names}のゲージがたまったら「${t?.name || '合体技'}」を出す。力をためている…`;
  }
  if (a.dualHold) return `${v.c.get(a.dualTarget)?.name || '仲間'}の合体技に参加する。ほかの仲間を待っている…`;
  return null;
}

// サーバーからの できごと（合体技の よやく・まつ）
export function onDualWait(v, ev) {
  const c = v.c.get(ev.id);
  const ids = ev.partners || [ev.partner];
  if (c) { c.waitDual = { id: ev.tech, partner: ids[0], partners: ids }; c.ready = false; }
  for (const id of ids) {
    const p = v.c.get(id);
    if (p) p.dualTarget = ev.id;
  }
}
export function onDualWaitEnd(v, ev) {
  const c = v.c.get(ev.id);
  const ids = ev.partners?.length ? ev.partners : c?.waitDual?.partners || [c?.waitDual?.partner];
  if (c) c.waitDual = null;
  for (const id of ids || []) {
    const p = id && v.c.get(id);
    if (p && p.dualTarget === ev.id) { p.dualTarget = null; p.dualHold = false; }
  }
}
// よやくで まっていた 人が ダメージを 受けて、ゲージが 半分から やり直し（サーバーの battle-dual.js の dualHurt）
export function onDualBreak(v, ev) {
  for (const id of ev.dualBreak || []) {
    const c = v.c.get(id);
    if (!c) continue;
    c.dualHold = false;
    c.atb = Math.min(c.atb ?? 50, 50);
    v.banner(`${c.name}の力あわせがみだれた！`, 'danger');
    if (v.mine.includes(id) && !v.cur) v.renderCmdIdle();
  }
  v.renderStatus();
}

// 仲間が ほかの 仲間を まつ（ゲージは たまった まま）
export function onDualHold(v, ev) {
  const c = v.c.get(ev.id);
  if (c) { c.ready = false; c.dualHold = true; c.dualTarget = ev.by; }
  if (v.mine.includes(ev.id)) {
    v.dropReady(ev.id);
    if (!v.cur) v.renderCmdIdle();
  }
  v.renderStatus();
}

// 家族から 合体技に さそわれた
export function showInvite(v, ev) {
  v.closeInvite();
  const t = dualFor(ev.tech, [ev.from, ...(ev.partners || [ev.to])].map((id) => v.c.get(id)));
  const n = (ev.partners?.length || 1) + 1;
  const bar = el('div', { class: 'di-bar' }, el('i', { style: { animationDuration: `${ev.ms || 7000}ms` } }));
  const who = n >= 3 ? `${ev.fromName}が${n}人技にさそっている！` : `${ev.fromName}が合体技にさそっている！`;
  const box = el('div', { class: 'win dual-invite' },
    el('div', { class: 'di-t', text: who }),
    el('div', { class: 'di-n', text: `「${t?.name || '合体技'}」` }),
    n >= 3 && ev.names ? el('div', { class: 'di-d', text: `いっしょに出す人：${ev.names.join('・')}` }) : null,
    el('div', { class: 'di-d', text: t && dualKnown(v.game.me, ev.tech) ? t.desc : SECRET }), bar);
  const answer = (ok) => {
    v.game.net.send({ t: 'battle', actor: ev.to, cmd: { type: 'dualAnswer', invite: ev.invite, ok } });
    v.closeInvite();
  };
  const m = new ListMenu(v.game.input, {
    items: [{ label: '参加する！', value: true }, { label: 'ことわる', value: false }],
    sound: (x) => v.game.audio.sfx(x),
    onSelect: (it) => answer(it.value),
    onCancel: () => answer(false),
  });
  box.append(m.root);
  v.stage.append(box);
  v.menu?.blur();
  m.focus();
  v.invite = { invite: ev.invite, box, menu: m };
  v.game.audio.sfx('dual');
}

// 合体技の さそいの 返事（ことわった・時間切れ・参加する）
export function onDualAnswer(v, ev) {
  if (v.invite?.invite === ev.invite && (!ev.ok || !ev.partial || v.mine.includes(ev.to))) v.closeInvite();
  if (!v.mine.includes(ev.from)) return;
  const who = v.c.get(ev.to)?.name || '仲間';
  if (ev.ok) {
    if (ev.partial) toast(`${who}が参加する！ほかの仲間の返事を待っている…`);
    return;
  }
  const why = { 'ことわった': `${who}は参加しなかった…`, '時間切れ': `${who}から返事がなかった…`, '出せなくなった': '合体技は出せなくなった…', '倒れた': '合体技は出せなくなった…' }[ev.reason];
  if (why) toast(why);
  const c = v.c.get(ev.from);
  if (c && c.alive && c.ready && !v.readyQ.includes(ev.from)) v.readyQ.unshift(ev.from);
  if (!v.cur) v.nextCommand();
}

// 合体技を 出す 前に 見せる 時間（ミリびょう）
export function dualPre(ev, speed = 1) {
  return cutMs(ev.dual?.n || 2) / speed;
}

// 合体技の カットイン（みんなの 顔と 技の 名前）と、とどめの えんしゅつ
export function dualFx(v, ev) {
  const d = ev.dual;
  const ids = d.m || [d.a, d.b];
  const people = ids.map((id) => v.c.get(id)).map((x) => ({ name: x?.name || '', face: x ? faceURL({ look: x.look, job: x.job, eq: x.eq, mon: x.mon }) : '' }));
  const tempo = v.fxSpeed || 1;
  const n = ids.length;
  const ms = playDualCutin(v.stage, { id: d.id, name: d.name, people, tempo, el });
  const au = v.game.audio;
  au.sfx('dual');
  if (n >= 3) setTimeout(() => au.sfx('bond'), 260 / tempo);
  setTimeout(() => au.sfx(n >= 4 ? 'thunder' : 'smash'), (ms * 0.4));
  v.fx.flash = 200;
  v.fx.flashColor = '#ffffff';
  setTimeout(() => v.shake?.(320 + 80 * n, 4 + 2 * n), ms * 0.4);
  for (const id of ids) v.glowStatus(id, '#ffd66b');
  // とどめ: カットインの あと、技の えんしゅつと いっしょに
  setTimeout(() => {
    if (v.destroyed) return;
    const targets = (ev.fx?.targets || []).map((id) => v.c.get(id)).filter(Boolean);
    const foes = targets.filter((x) => x.side === 'enemy').map((x) => v.center(x)).filter(Boolean);
    const pts = foes.length ? foes : [{ x: BW / 2, y: BH * 0.62 }];
    playDualFinale(v.fx, d.id, pts, n, BW, BH);
    const fin = { bolt: 'bolt', nova: 'blast', storm: 'wind', cross: 'crit', beam: 'blast', quake: 'smash', heal: 'heal', stage: 'buff', laugh: 'hirameki', siren: 'warn', spot: 'hirameki', gadgets: 'item', coins: 'coin', meteor: 'blast', matoi: 'crit' };
    au.sfx(fin[dualFxOf(d.id).finale] || (foes.length ? 'blast' : 'heal'));
  }, ms);
}

