    // 月の鏡の 光（まぼろしの 分身が いる 戦いだけ。{ cd … のこり, max }。battle-ch4.js）
    this.mirror = msg.snap.mirror ? { ...msg.snap.mirror } : null;
    // 敵の 強さ（設定の「敵の強さ」。パーティーでは リーダーの 設定）。ふつう いがいは え の 左下に しるし
    this.enemyRate = ENEMY_RATE_NAMES[msg.snap.enemyRate] ? msg.snap.enemyRate : 1;
    this.c = new Map();
    for (const c of msg.snap.combatants) {
      ensureVariantId(c.species);
      ensureVariantId(c.mon);
    }
    for (const c of msg.snap.combatants) this.c.set(c.id, { ...c, flash: 0, dead: !c.alive ? 1 : 0, lunge: 0 });
    // この たたかいで ためした 属性（'まもの|属性'）。図鑑に のっている ぶんと あわせて ねらう ときに 見せる
    this.tried = new Set();
    // 戦いの 速さ（エフェクト）と 文字の 速さ（サーバーと おなじ あたい）
    this.fxSpeed = msg.snap.speed || 1;
    this.textSpeed = msg.snap.textSpeed || 1;
    // ウェイト: だれか（人）が コマンドを えらんでいる 間は ゲージが 止まる（サーバーと おなじ きまり）
    this.waitMode = !!msg.snap.wait;
    this.fx = new Effects();
    this.bg = battleBackground(msg.snap.bg);
    this.queue = [];
    this.showing = null;
    this.time = 0;
    this.ended = false;
    this.lock = false;
    this.build();
    // 水の守りの歌の しるし（battle-temple.js）
    templeStart(this, msg.snap);
    // 第77回 C: ふつうの 戦いの 曲は 場所で かわる（第2部 battle2・強敵 battle_strong。曲が まだ なければ battle。client/audio-scene.js）
    const sa = this.game.sceneAudio;
    const f = this.game.field;
    const bgm = sa ? sa.battleTrack({ snap: msg.snap, boss: this.boss, story: !!msg.story, mapId: f?.mapId, map: f?.map }) : msg.snap.bgm || (this.boss ? 'boss' : 'battle');
    this.game.audio.play(bgm, { force: true });
    sa?.battleStart();
    const names = this.enemyNames();
    if (msg.resume) this.say(['つなぎ直した！戦いの続きだ！']);
    else if (msg.joined) this.say([`${names}との戦いにかけつけた！`]);
    else this.say([msg.preemptive === 'ally' ? '魔物はまだこちらに気づいていない！' : msg.preemptive === 'enemy' ? '魔物たちがいきなりおそいかかってきた！' : `${names}が現れた！`]);
    // はじまった ときに もう 番が きている 自分の キャラ（つなぎ直し・かけつけ など）
    for (const id of this.mine) {
      const c = this.c.get(id);
      if (c?.ready && c.alive && !c.auto && !this.readyQ.includes(id)) this.readyQ.push(id);
    }
    if (this.readyQ.length) this.nextCommand();
  }

  enemyNames() {
    const counts = {};
    for (const c of this.c.values()) if (c.side === 'enemy') counts[c.species] = (counts[c.species] || 0) + 1;
    return Object.entries(counts).map(([sp, n]) => (n > 1 ? `${MONSTERS[sp].name}たち` : MONSTERS[sp].name)).join('と');
  }

  // じぶんの キャラ（プレイヤー）
  get primary() {
    return this.c.get(this.mine[0]);
  }

  // いま コマンドを えらんでいる キャラ（なかまの ばんなら なかま）
  get myActor() {
    return this.c.get(this.cur) || this.primary;
  }

  // つぎに コマンドを えらぶ キャラへ
  nextCommand() {
    while (this.readyQ.length) {
      const id = this.readyQ[0];
      const a = this.c.get(id);
      const stuck = (a?.status || []).some((x) => x === 'sleep' || x === 'paralyze' || x === 'prison' || x === 'rift');
      if (a && a.alive && a.ready && !a.auto && !stuck && !this.ended) {
        this.cur = id;
        this.openCommand();
        return;
      }
      this.readyQ.shift();
    }
    this.cur = null;
    if (this.menu) this.renderCmdIdle();
  }

  dropReady(id) {
    this.readyQ = this.readyQ.filter((x) => x !== id);
    if (this.cur === id) {
      this.cur = null;
      this.closeMenus();
      this.nextCommand();
      if (!this.cur) this.renderCmdIdle();
    }
  }

  // サーバーに ことわられた: もういちど えらびなおす
  onReject() {
    const id = this.lastSent;
    const a = id && this.c.get(id);
    if (a && a.ready && !this.readyQ.includes(id)) this.readyQ.unshift(id);
    if (!this.cur) this.nextCommand();
  }

  // ───────────── がめんを つくる ─────────────
  build() {
    const root = document.getElementById('battle');
    root.innerHTML = '';
    root.hidden = false;
    this.root = root;
    this.statusEl = el('div', { class: 'b-status' });
    // 第31回: きずなゲージは なくなった（ミナデインは 合体技に）
    const top = el('div', { class: 'b-top' }, this.statusEl);
    this.res = battleRes;
    this.canvas = makeCanvas(BW * this.res, BH * this.res);
    this.ctx = ctxOf(this.canvas);
    this.floatEl = el('div', { class: 'b-float' });
    this.autoBtn = el('button', { class: 'btn', text: 'オート', title: 'SELECT・Mキーでも（戦いのメニュー）', onclick: () => this.toggleAuto() });
    // 第35回: SELECT・M で 戦いの メニュー（オート・作戦・合体技の よやくを やめる。battle-pad.js）
    this.unbindPad = bindBattlePad(this);
    this.speedHint = el('div');
    const tools = el('div', { class: 'b-tools' }, this.autoBtn);
    // 敵の 強さ（ハード・ベリーハード・スーパーハード）の しるし
    const foe = this.enemyRate > 1
      ? el('div', { class: `b-foe r${String(this.enemyRate).replace('.', '')}`, text: ENEMY_RATE_NAMES[this.enemyRate], title: `敵の強さ：${this.enemyRate}倍` })
      : null;
    this.stage = el('div', { class: 'b-stage' }, this.canvas, this.floatEl, tools, foe);
    this.canvas.addEventListener('click', (e) => this.onCanvasClick(e));
    this.cmdEl = el('div', { class: 'win b-cmd' });
    this.msgEl = el('div', { class: 'win b-msg' });
    this.msgEl.addEventListener('click', () => this.skipMsg());
    // 技・道具の せつめいの まど（第27回: 戦いの メッセージとは 別。戦いが 進んでも 消えない・上書きされない）
    this.infoEl = el('div', { class: 'win b-info' });
    const bottom = el('div', { class: 'b-bottom' }, this.cmdEl, this.infoEl, this.msgEl);
    // 第52回: スマホ たてむきの 大きな「← もどる」（コマンドの わくの 外・左下。css の .b-backbar。もどれる 時だけ 出る）
    this.backBar = el('div', { class: 'b-backbar' }, el('button', {
      class: 'btn b-backbig',
      'aria-label': 'もどる',
      text: '← もどる',
      onclick: (e) => {
        e.stopPropagation();
        this.menu?.cancel();
      },
    }));
    root.append(top, this.stage, bottom, this.backBar);
    this.statusBoxes = new Map();
    this.renderStatus(true);
    this.renderCmdIdle();
    this.updateAutoBtn();
    this.resizeCanvas();
    // コマンドの なまえの 大きさも あわせなおす（ListMenu の fit）
    this.onResize = () => { this.resizeCanvas(); this.menu?.fitText && this.menu.fit(); };
    addEventListener('resize', this.onResize);
    // 文字（ウェブフォントの つづき）が とどいたら、コマンドの なまえの 大きさを あわせなおす
    this.onFonts = () => { this.menu?.fitText && this.menu.fit(); };
    document.fonts?.addEventListener?.('loadingdone', this.onFonts);
    // がめんの むきが かわった・もじが よみこまれた ときも あわせる
    if (window.ResizeObserver) {
      this.ro = new ResizeObserver(() => { this.resizeCanvas(); this.menu?.fitText && this.menu.fit(); });
      this.ro.observe(this.stage);
    }
  }

  // たたかいの え を できるだけ おおきく（ドットが そろうように がめんの ほんとうの ピクセルで わりきれる おおきさ）
  resizeCanvas() {
    const r = this.stage.getBoundingClientRect();
    if (!r.width || !r.height) return;
    const dpr = window.devicePixelRatio || 1;
    const kmax = Math.min(r.width / BW, r.height / BH);
    let k = Math.floor(kmax * dpr) / dpr;
    // こまかい がめん（スマホ。dpr 2いじょう）で わりきると 1わり ちかく 小さく なる ときは、いっぱいに（ドットの ずれは 見えない）
    if (k < 0.5 || (dpr >= 2 && k < kmax * 0.94)) k = kmax;
    this.canvas.style.width = `${Math.round(BW * k)}px`;
    this.canvas.style.height = `${Math.round(BH * k)}px`;
    this.cssK = k;
  }

  // 馬車に もどった 人（fled・benched）と、まだ 出てきて いない 人（pending）は のぞく。まどは 場所（slot）の じゅん
  allies() { return [...this.c.values()].filter((c) => c.side === 'ally' && !c.fled && !c.benched && !c.pending).sort((a, b) => (a.slot ?? 0) - (b.slot ?? 0)); }
  enemies() { return [...this.c.values()].filter((c) => c.side === 'enemy' && !c.fled).sort((a, b) => (a.slot ?? 0) - (b.slot ?? 0)); }

  renderStatus(full = false) {
    const allies = this.allies();
    if (full || this.statusBoxes.size !== allies.length || allies.some((a) => !this.statusBoxes.has(a.id))) {
      this.statusEl.innerHTML = '';
      this.statusBoxes.clear();
      // 人数（たてむきの スマホで 5人の ときは 3人＋2人の 2だんに。CSS）
      this.statusEl.dataset.n = String(allies.length);
      for (const a of allies) {
        const box = el('div', { class: 'win b-mem' });
        box.addEventListener('click', () => this.onAllyClick(a.id));
        const name = el('span', { class: 'n', text: a.name });
        const tag = el('span', { class: 'tg' });
        // 第35回: 短い 職業名（男の子の 美少女戦士は「しんし」など。shared/job-label.js）
        const jb = el('span', { class: 'jb' });
        const lv = el('span', { class: 'lv' });
        const nm = el('div', { class: 'nm' }, el('span', { class: 'nl' }, name, tag, jb), lv);
        const gauge = (label, kind) => {
          const bar = el('div', { class: `gb ${kind}` }, el('i'));
          const num = el('span', { class: 'gn' });
          const row = el('div', { class: `grow ${kind}` }, el('span', { class: 'gl', text: label }), bar, num);
          return { row, bar: bar.firstChild, num };
        };
        const hp = gauge('HP', 'hp');
        const mp = gauge('MP', 'mp');
        const sts = el('div', { class: 'sts' });
        const atb = el('div', { class: 'atb' }, el('i'));
        box.append(nm, hp.row, mp.row, sts, atb);
        this.statusEl.append(box);
        this.statusBoxes.set(a.id, { box, name, tag, jb, lv, hp, mp, sts, atb: atb.firstChild, atbBox: atb });
      }
    }
    // 家族と いっしょの ときは、人が 動かしている キャラの 名前を 黄緑に
    const multi = allies.filter((a) => a.kind === 'player').length >= 2;
    for (const a of allies) {
      const s = this.statusBoxes.get(a.id);
      if (!s) continue;
      const r = a.maxHp ? Math.max(0, a.hp) / a.maxHp : 0;
      const hpCls = !a.alive ? 'dead' : r <= 0.1 ? 'red' : r <= 0.5 ? 'orange' : '';
      s.box.classList.toggle('dead', !a.alive);
      s.box.classList.toggle('me', this.mine.includes(a.id));
      s.box.classList.toggle('ready', !!a.ready && this.mine.includes(a.id));
      s.box.classList.toggle('cur', this.cur === a.id);
      // さわると さくせんを かえられる（じぶんと じぶんの なかま）
      s.box.classList.toggle('tac', this.canTactics(a));
      s.name.className = `n ${multi && a.kind === 'player' ? 'player' : ''} ${hpCls}`;
      s.lv.textContent = `Lv${a.lv}`;
      s.jb.textContent = a.mon || a.kind === 'monster' || !JOBS[a.job] ? '' : jobShort(a.job, a);
      s.hp.row.className = `grow hp ${hpCls}`;
      s.hp.bar.style.width = `${Math.round(r * 100)}%`;
      s.hp.num.textContent = `${Math.max(0, a.hp)}/${a.maxHp}`;
      s.mp.bar.style.width = `${a.maxMp ? Math.round(Math.max(0, a.mp) / a.maxMp * 100) : 0}%`;
      s.mp.num.textContent = `${Math.max(0, a.mp)}/${a.maxMp}`;
      s.tag.textContent = a.auto && a.controller ? 'オート' : a.controller && a.kind !== 'player' ? '命令' : a.kind === 'support' ? '仲間' : a.kind === 'monster' ? '魔物' : a.kind === 'guest' ? 'ゲスト' : '';
      fillStatusRow(s.sts, a);
    }
  }

  updateGauges() {
    for (const a of this.allies()) {
      const s = this.statusBoxes.get(a.id);
      if (!s) continue;
      const v = a.alive ? Math.min(100, a.atb) : 0;
      s.atb.style.width = `${v}%`;
      s.atbBox.classList.toggle('full', v >= 99.9);
    }
  }

  // ───────────── メッセージ ─────────────
  say(lines, dur = 1200) {
    this.msgEl.innerHTML = '';
    this.msgEl.classList.remove('info');
    const els = lines.map((l) => el('div', { class: 'ln', text: l }));
    const per = Math.max(90, Math.min(260 / this.textSpeed, (dur * 0.8) / Math.max(1, lines.length)));
    // まだ 出していない 行は ばしょも とらない（まどは した ぞろえ。行が おおい ときに さいしょの 行が 上に かくれない ように）
    els.forEach((e, i) => {
      if (i) e.style.display = 'none';
      this.msgEl.append(e);
      if (i) setTimeout(() => { e.style.display = ''; }, i * per);
    });
    while (this.msgEl.children.length > 7) this.msgEl.firstChild.remove();
  }

  skipMsg() {
    for (const e of this.msgEl.children) e.style.display = '';
  }

  // えらんでいる 技・道具の せつめい（上から 見せる。長くても 1行めが かくれない）。
  // 第27回: メッセージの まど（say）とは 別の まど（.b-info）。コマンドを とじる まで（clearInfo）出た まま
  info(text) {
    if (!this.infoEl) return;
    this.infoEl.innerHTML = '';
    this.infoEl.classList.remove('hasfav');
    if (!text) return this.clearInfo();
    this.infoEl.append(el('div', { class: 'ln small', text }));
    this.infoEl.scrollTop = 0;
    this.root?.classList.add('has-info');
  }

  clearInfo() {
    if (this.infoEl) this.infoEl.innerHTML = '';
    this.root?.classList.remove('has-info');
  }

  // ───────────── コマンド ─────────────
  renderCmdIdle(text) {
    this.closeMenus();
    this.clearInfo();
    this.cmdEl.innerHTML = '';
    const a = this.primary;
    if (!a) {
      this.cmdEl.append(el('div', { class: 'wait', text: '仲間が戦っている…' }));
      return;
    }
    // 合体技の よやく中: 仲間の ゲージを まっている（やめられる）・ほかの 人の 合体技に 入って まっている
    const dw = a.alive && waitText(this, a);
    if (dw) {
      this.cmdEl.append(
        el('div', { class: 'who', text: a.name }),
        el('div', { class: 'wait', text: dw }),
        a.waitDual ? el('button', { class: 'btn dual-cancel', text: 'よやくをやめる', onclick: () => this.game.net.send({ t: 'battle', actor: a.id, cmd: { type: 'dualCancel' } }) }) : null,
      );
      return;
    }
    this.cmdEl.append(el('div', { class: 'who', text: a.name }), el('div', { class: 'wait', text: text || (a.alive ? (a.auto ? 'オートで戦っている' : '行動ゲージがたまるのを待っている…') : '死んでしまった…') }));
  }

  closeMenus() {
    this.root?.classList.remove('has-back');
    if (this.ended) this.closeTactics();
    this.closeFavPop();
    this.menu?.blur();
    this.menu = null;
    this.targeting = null;
    this.hoverGroup = null;
  }

  openCommand() {
    const a = this.myActor;
    if (!a || !a.alive || this.ended) return;
    this.cur = a.id;
    this.clearInfo();
    this.renderStatus();
    this.game.audio.sfx('warn');
    // 転職した あと 今の 職業・ぶきで 使えない 技（ほかの 職業の 掛け合わせ技・剣や ムチが いる 技 など）と
    // フィールドだけの 呪文（ルーラ）は 出さない（shared/stats.js の battleAbilityOk。サーバーも おなじ きまり）。
    // MPが 足りない・呪文を ふうじられた ときは 出して えらべない だけ
    const pc = a.pc || { job: a.job, jobs: {} };
    // 第71回: 「命令で出す技を選ぶ」（作戦）・呪文・技の メニューで「出さない」に した 技は 出さない（サーバーの cmdOff は 同じ 名前の 技も 入っている）。
    //   作戦の「オートで使う技を選ぶ」（autoOff）は オートの AIだけ（一覧からは 消さない）。第69回は autoOff で 消していた
    const off = new Set(a.cmdOff || []);
    // 第69回: ならびは ダメージ・回復の 弱い じゅん（職業の ほせい なしの ふつうの 強さ。shared/skill-sort.js）。★お気に入りは その ならび
    const learned = sortByStdPower((a.abilities || []).filter((id) => !off.has(id) && battleAbilityOk(pc, id, a.weaponCat) && (ABILITIES[id].effect?.type !== 'mahouken' || (this.mahoukenOpts(a).length && !this.noSpells))));
    const spells = learned.filter((id) => ABILITIES[id].kind === 'spell' || ABILITIES[id].spellLike);
    const skills = learned.filter((id) => ABILITIES[id].kind === 'skill' || ABILITIES[id].kind === 'monster' || (ABILITIES[id].kind === 'combo' && !ABILITIES[id].spellLike));
    const duals = this.myDualOptions(a);
    const items = [
      { label: '戦う', value: 'attack' },
      this.noSpells && spells.length
        ? { html: '呪文<span class="tag muted">ふうじられた</span>', value: 'spell', disabled: true }
        : { label: '呪文', value: 'spell', disabled: !spells.length },
      { label: '特技', value: 'skill', disabled: !skills.length },
      { label: '道具', value: 'item' },
      { label: '防御', value: 'defend' },
      { label: '逃げる', value: 'flee', disabled: !this.canFlee },
    ];
    // 馬車の 仲間と いれかえ（馬車が いっしょの とき。ui/wagon.js）
    const wagon = battleWagon(this);
    if (wagon) items.splice(items.length - 1, 0, { label: 'いれかえ', value: 'wagon', disabled: !wagon.outs.length || !wagon.ins.some((x) => x.hp > 0) });
    if (duals.length) items.splice(3, 0, { html: '<span class="dual-cmd">合体技</span>', value: 'dual', cls: 'k-dual' });
    // 地われ・のみこまれ の 仲間が いる 時だけ「手をのばす」（いちばん 上。battle-earth.js）
    const reach = earthReachItem(this, a);
    if (reach) items.unshift(reach);
    // ひとりの 仲間が いる 時の「よびかける」・ソリトゥスの 第3段階の「家族のきずな技」（いちばん 上。battle-final.js）
    const fin = finalCmdItems(this, a);
    if (fin.items.length) items.unshift(...fin.items);
    this.showMenu(items, (it) => {
      switch (it.value) {
        case 'attack': {
          // ムチは グループ、ブーメランは 敵全体（えらばない）
          const reach = attackReach(a.weaponCat);
          return this.pickFoe(reach, (t) => this.send({ type: 'attack', target: t }), reach === 'group' ? 'どのグループをねらう？' : 'だれをねらう？');
        }
        case 'spell': return this.abilityMenu(spells, 'spell');
        case 'skill': return this.abilityMenu(skills, 'skill');
        case 'dual': return this.dualMenu(this.myDualOptions(a));
        case 'item': return this.itemMenu();
        case 'defend': return this.send({ type: 'defend' });
        case 'flee': return this.send({ type: 'flee' });
        case 'wagon': return battleSwapMenu(this);
        case 'reach': return earthReachPick(this, a);
        default: return finalCmdPick(this, a, it.value);
      }
    }, null, this.noSpells ? `${a.name}はどうする？（ここでは呪文がふうじられている）` : `${a.name}はどうする？`);
    // 「手をのばす」が ある ときは せつめいも（battle-earth.js）
    if (reach) this.info(REACH_INFO);
    if (fin.info) this.info(fin.info);
    if (this.noSpells && spells.length && !this.sealNoted) {
      this.sealNoted = true;
      this.info(`${SEALED_REASON}\n特技・道具・攻撃で戦おう。`);
    }
  }

  // keep: { off } … まえに えらんだ 行が リストの 上から 何ピクセルの ところに 見えていたか（その まま の 場所に 出す）
  // tapConfirm: タップで ほかの 行を えらぶと せつめい だけ 出す（もう一度 おすと 決まる。呪文・特技・道具の 一覧）
  // pager: 第69回 スマホでは 技の 一覧の 左右の はしに ◀ ▶（見えている ひとまとまり ずつ 前・つぎへ。pagerWrap）
  showMenu(items, onSelect, onCancel, title, detailFn, start = -1, keep = null, tapConfirm = false, pager = false) {
    this.closeMenus();
    this.cmdEl.innerHTML = '';
    this.cmdEl.classList.remove('has-tabs');
    if (title) this.cmdEl.append(el('div', { class: 'who', text: title }));
    const m = new ListMenu(this.game.input, {
      items,
      sound: (x) => this.game.audio.sfx(x),
      onSelect,
      onCancel: onCancel || null,
      onMove: detailFn ? (it) => detailFn(it) : null,
      press: 130,
      start,
      fit: true,
      tapConfirm,
    });
    // スクロールの 場所を もどす 前に 入れる（あとで 入れかえると スクロールが 0に もどる）
    this.cmdEl.append(pager && this.touchUi() ? this.pagerWrap(m) : m.root);
    this.menu = m;
    // もどれる メニューの ときだけ、たてむきの 大きな「← もどる」を 出す
    this.root?.classList.toggle('has-back', !!onCancel);
    if (start >= 0) this.restoreScroll(m, keep);
    m.focus();
    // さくせんの まどが ひらいている 間は、キーは そちらへ（とじたら こちらに もどる）
    if (this.tac) m.blur();
    if (start >= 0 && detailFn) detailFn(items[m.idx]);
  }

  // 第69回: 技の 一覧の 左右の はしの ◀ ▶（スマホ）。おすと 見えている ひとまとまり ずつ 前・つぎへ（十字キーの 列の はしの 左右と おなじ）。
  //   一覧が まどに 入りきる ときは 出さない。前・つぎが ない ほうは うすく（おせない）
  pagerWrap(m) {
    const wrap = el('div', { class: 'b-pagewrap' });
    const btn = (d) => el('button', {
      class: `btn b-page ${d < 0 ? 'pg-prev' : 'pg-next'}`,
      'aria-label': d < 0 ? 'まえの技' : 'つぎの技',
      text: d < 0 ? '◀' : '▶',
      onclick: (e) => {
        e.stopPropagation();
        if (this.menu === m) m.pageJump(d);
      },
    });
    const prev = btn(-1), next = btn(1);
    wrap.append(prev, m.root, next);
    const upd = () => {
      if (!wrap.isConnected) return;
      const p = m.pageInfo();
      wrap.classList.toggle('pg-on', p.scroll);
      prev.disabled = !p.prev;
      next.disabled = !p.next;
    };
    m.root.addEventListener('scroll', upd, { passive: true });
    const mv = m.onMove;
    m.onMove = (it, i) => {
      mv?.(it, i);
      upd();
    };
    m.pageWrap = wrap;
    requestAnimationFrame(upd);
    return wrap;
  }

  // えらんでいる 行が リストの 上から どこに 見えているか（ピクセル）
  selOffset(m = this.menu) {
    const li = m?.root.children[m.idx];
    return li ? li.getBoundingClientRect().top - m.root.getBoundingClientRect().top : null;
  }

  // まえに えらんだ 行を、その ときと おなじ 場所に（入りきらない ときは 見える ところまで）
  restoreScroll(m, keep) {
    const box = m.root;
    const li = box.children[m.idx];
    if (!li) return;
    if (keep && Number.isFinite(keep.off)) {
      const top = li.getBoundingClientRect().top - box.getBoundingClientRect().top + box.scrollTop;
      box.scrollTop = Math.max(0, top - keep.off);
    }
    const r = li.getBoundingClientRect(), br = box.getBoundingClientRect();
    if (r.top < br.top || r.bottom > br.bottom) m.scrollToSel();
  }

  // まえに えらんだ 技（キャラ・ページごと。つぎの 戦いでも おぼえておく）
  lastPick(a, page) {
    try { return JSON.parse(localStorage.getItem('kizuna_bcur') || '{}')[`${a.charId || a.id}:${page}`] || null; } catch { return null; }
  }

  // その ときの リストの 見え方（えらんだ 行が 上から 何ピクセルの ところ）。もどった ときに おなじ 場所に 出す
  lastScroll(a, page) {
    try {
      const v = JSON.parse(localStorage.getItem('kizuna_bscroll') || '{}')[`${a.charId || a.id}:${page}`];
      return v && Number.isFinite(v.off) ? v : null;
    } catch { return null; }
  }

  rememberPick(a, page, value) {
    const off = this.selOffset();
    try {
      const m = JSON.parse(localStorage.getItem('kizuna_bcur') || '{}');
      m[`${a.charId || a.id}:${page}`] = value;
      localStorage.setItem('kizuna_bcur', JSON.stringify(m));
      if (off !== null) {
        const sc = JSON.parse(localStorage.getItem('kizuna_bscroll') || '{}');
        // fav: お気に入りの まどの 行か（おなじ 技が「ぜんぶ」にも ある）
        sc[`${a.charId || a.id}:${page}`] = { off: Math.round(off), fav: !!this.menu?.current?.fav };
        localStorage.setItem('kizuna_bscroll', JSON.stringify(sc));
      }
    } catch { /* */ }
  }

  favsOf(a) {
    return this.localFavs?.get(a.id) || a.favs || [];
  }

  // お気に入りに 入れる・はずす（サーバーに おぼえてもらう）
  toggleFav(a, id) {
    // この 戦いの 中で かえた お気に入りは 手もとに おぼえる（サーバーの 前の 知らせ〈upd〉が あとから とどいても もどらない）
    const prev = this.favsOf(a).slice();
    const favs = prev.slice();
    const on = !favs.includes(id);
    // 第72回: いっぱい（FAV_MAX こ）の ときは 入れない（まえは ★に なっても サーバーが だまって すてていた。shared/favorites.js）
    if (on && favFull(favs, new Set(a.abilities || []))) {
      toast(FAV_FULL_TEXT);
      this.game.audio.sfx('buzz');
      return false;
    }
    if (on) favs.push(id);
    else favs.splice(favs.indexOf(id), 1);
    (this.localFavs || (this.localFavs = new Map())).set(a.id, favs);
    a.favs = favs;
    const who = String(a.charId || '').includes(':') ? String(a.charId).split(':').pop() : 'self';
    // 知らせは サーバーの 返事（menuRes）で 出る。サーバーが ことわった（いっぱい など）ときは 手もとも もとに もどす（第72回）
    this.game.menuWaiter = (m) => {
      if (m && !m.ok && this.localFavs?.get(a.id) === favs) {
        this.localFavs.set(a.id, prev);
        a.favs = prev;
      }
      return false;
    };
    this.game.net.send({ t: 'menu', action: 'favorite', who, id, op: on ? 'add' : 'remove' });
    return true;
  }

  // keep: お気に入りを かえた ときなど、いまの カーソルと 見え方の まま 出しなおす（{ value, off, tab }）
  // 第35回: 効果ごとの タブ（★お気に入り・今の職業・こうげき1体・こうげき全体・回復・強くする・弱くする・そのほか。
  // 空の タブは 出さない。shared/skill-tabs.js）。スマホは タブを タップ
  // 第69回: タブ（種類）を かえるのは L・R（キーボードの Q・E。ListMenu の onLR）。十字キーの 左右は 列の はしで
  //   見えている ひとまとまり ずつ 前・つぎへ（おなじ タブの 中。ListMenu の onSide → pageJump）。スマホは 一覧の 左右の ◀ ▶。
  //   技の ならびは 弱い じゅん（openCommand。★お気に入りは その ならび）
  abilityMenu(ids, page = 'spell', keep = null) {
    const a = this.myActor;
    // look: 技の 名前・説明を 使う 人 むけに（男の子の 美少女戦士など。shared/ability-label.js）
    // pow: 今の 魔力（呪文の ダメージの 目安。第50回 N1）
    // partyHp: 味方 みんなの 今の HP（元気玉の 目安。第72回 shared/skill-power.js の powStats）
    const partyHp = this.allies().filter((x) => x.alive).map((x) => x.hp || 0);
    const pc = { ...(a.pc || { job: a.job, jobs: this.game.me.jobs }), look: a.look, mon: a.mon, pow: a.pow, partyHp };
    const silenced = (a.status || []).includes('silence');
    // わかっている 弱点（この 戦いの 敵で、図鑑・この 戦いで ためして わかった 物だけ）
    const foes = this.enemies().filter((e) => e.alive);
    const weak = (ab) => abilityElements(ab).some((elm) => foes.some((e) => this.knownAffinity(e, elm) === 'weak'));
    const row = (id, fav) => {
      const ab = abilityFor(id, a);
      const isMk = ab.effect.type === 'mahouken';
      const cost = isMk ? 0 : mpCost(pc, id);
      const pen = penaltyFor(pc, id).penalized;
      const noMp = !isMk && cost > a.mp;
      const sil = (silenced || this.noSpells) && spellSealed(ab);
      const el = ab.effect?.element;
      // 相手の しるし（グループ・全体・全員）
      const tt = targetTag(ab);
      // 技の レベル（Lv2 から 出す。第38回 C。shared/buff-acts.js）
      const slv = a.slv?.[id] || 1;
      return {
        html: `${ELEMENT_NAMES[el] ? `<span class="elem e-${el}">${ELEMENT_NAMES[el]}</span>` : ''}${ab.name}${slv >= 2 ? `<span class="tag slv">Lv${slv}</span>` : ''}${tt ? `<span class="tag tgt t-${ab.effect?.random ? 'random' : ab.target}">${tt}</span>` : ''}${weak(ab) ? '<span class="tag weak">弱点</span>' : ''}${pen ? '<span class="tag warn">他</span>' : ''}${ab.hirameki || ab.kind === 'combo' ? '<span class="tag hira">閃</span>' : ''}`,
        right: isMk ? '▶' : `${cost}`,
        rightCls: pen ? 'pen' : '',
        value: id,
        cls: `k-${abilityRole(ab)}${fav ? ' fav' : ''}`,
        fav: !!fav,
        disabled: noMp || sil,
      };
    };
    const tabs = skillTabs(ids, { abs: (id) => abilityFor(id, a), job: pc.job, favs: this.favsOf(a) });
    const tab = startTab(tabs, keep?.tab || this.lastTab(a, page));
    const cur = tabs.find((t) => t.id === tab) || { id: 'all', ids: [] };
    const items = cur.ids.map((id) => row(id, cur.id === 'fav'));
    // まえに えらんだ 技から はじめる（タブごと。リストの 見え方も その ときの まま）
    const key = `${page}/${cur.id}`;
    const last = keep ? keep.value : this.lastPick(a, key);
    const view = keep || this.lastScroll(a, key);
    const start = last ? items.findIndex((it) => it.value === last) : -1;
    const detail = (it) => {
      if (!it || it.header) return;
      // 効果・威力の 目安・属性・相手・MP（敵が 1体・自分に かける・全体の 技でも 使う 前に 見える。ui/skillinfo.js）
      // 第61回: スマホの たてむきは みじかく（3行まで。技の 一覧を 広く）
      const compact = this.compactInfo();
      const txt = battleSkillText(it.value, pc, { touch: this.touchUi(), lv: a.slv?.[it.value] || 1, compact });
      this.info(compact ? txt : favHint(txt, this.touchUi()));
      const on = this.favsOf(a).includes(it.value);
      this.infoEl.classList.add('hasfav');
      // 右上に うかべる（文は まわりを 回りこむ。css の .b-info .favwrap）
      // 第71回: ボタンの 下に「Y：お気に入り」（キーボード・ゲームパッド）・「長おし：お気に入り」（スマホ）を 小さく 出す（わかりやすく）
      this.infoEl.prepend(el('div', { class: 'favwrap' }, el('button', {
        class: `btn favbtn ${on ? 'on' : ''}`,
        text: on ? '★お気に入り' : '☆お気に入り',
        title: on ? 'お気に入りからはずす' : 'お気に入りに入れる',
        onclick: (e) => {
          e.stopPropagation();
          const off = this.selOffset();
          this.toggleFav(a, it.value);
          this.abilityMenu(ids, page, { value: it.value, off, tab: cur.id });
        },
      }), el('div', { class: 'favkey', text: favKeyHint(this.touchUi(), on) })));
    };
    this.showMenu(items, (it) => {
      const ab = abilityFor(it.value, a);
      this.rememberPick(a, key, it.value);
      if (ab.effect.type === 'mahouken') return this.mahoukenMenu();
      // 相手を えらぶ 間も おなじ せつめい（「もう一度タップ」は もう いらない）
      this.info(battleSkillText(it.value, pc, { lv: a.slv?.[it.value] || 1, compact: this.compactInfo() }));
      const t = ab.target;
      const back = () => this.abilityMenu(ids, page);
      if (t === 'enemy' || t === 'group') return this.pickFoe(t, (tid) => this.send({ type: 'ability', id: it.value, target: tid }), ab.name, ab.effect?.element, back);
      if (t === 'ally' || t === 'deadAlly') return this.pickAlly((tid) => this.send({ type: 'ability', id: it.value, target: tid }), t === 'deadAlly', ab.name, back);
      return this.send({ type: 'ability', id: it.value });
    }, () => this.openCommand(), null, detail, start, view, true, true);
    // 十字キーの 左右: 列の はしで 見えている ひとまとまり ずつ 前・つぎへ（タブは かえない。第69回）
    this.menu.onSide = (d) => this.menu.pageJump(d);
    // タブの 札（タップで かえる）。L・R（Q・E）でも かえる（ListMenu の onLR）
    const go = (id) => {
      if (id === cur.id) return;
      this.rememberTab(a, page, id);
      this.abilityMenu(ids, page, { tab: id });
    };
    if (tabs.length > 1) {
      // 「← もどる」も 札の ならびの 左に（1行 ぶん 技が 多く 見える。css の .has-tabs）
      const bar = el('div', { class: 'b-tabs', role: 'tablist' }, el('button', {
        class: 'btn bt bt-back',
        'aria-label': 'もどる',
        text: '←',
        onclick: (e) => {
          e.stopPropagation();
          this.menu?.cancel();
        },
      }), ...tabs.map((t) => el('button', {
        class: `btn bt ${t.id === cur.id ? 'sel' : ''} bt-${t.id}`,
        role: 'tab',
        title: t.title,
        text: t.label,
        onclick: (e) => {
          e.stopPropagation();
          this.game.audio.sfx('cursor');
          go(t.id);
        },
      })));
      this.cmdEl.insertBefore(bar, this.menu.pageWrap || this.menu.root);
      // えらんでいる 札が 見えるように（よこに スクロール）
      const sel = bar.querySelector('.sel');
      if (sel) {
        const x = sel.getBoundingClientRect().left - bar.getBoundingClientRect().left + bar.scrollLeft;
        bar.scrollLeft = Math.max(0, x - (bar.clientWidth - sel.offsetWidth) / 2);
      }
      this.menu.onLR = (d) => {
        const i = tabs.findIndex((t) => t.id === cur.id);
        this.game.audio.sfx('cursor');
        go(tabs[(i + d + tabs.length) % tabs.length].id);
      };
    }
    this.cmdEl.classList.toggle('has-tabs', tabs.length > 1);
    // 長おし・Y: お気に入りに 入れる／はずす を えらぶ 小さな まど（技は 使わない。第27回）
    this.menu.onLong = (it) => {
      if (!it || it.header) return;
      this.favPopup(a, it.value, () => {
        const off = this.selOffset();
        this.toggleFav(a, it.value);
        this.abilityMenu(ids, page, { value: it.value, off, tab: cur.id });
      });
    };
  }

  // 第35回: まえに 見た タブ（キャラ・呪文／特技ごと。つぎの 戦いでも おぼえておく）
  lastTab(a, page) {
    try { return JSON.parse(localStorage.getItem('kizuna_btab') || '{}')[`${a.charId || a.id}:${page}`] || null; } catch { return null; }
  }

  rememberTab(a, page, tab) {
    try {
      const m = JSON.parse(localStorage.getItem('kizuna_btab') || '{}');
      m[`${a.charId || a.id}:${page}`] = tab;
      localStorage.setItem('kizuna_btab', JSON.stringify(m));
    } catch { /* */ }
  }

  // 第27回: 技を 長おし（Y）した ときの「お気に入りに入れる／はずす」の まど。toggle: 入れる・はずす を えらんだ とき
  favPopup(a, id, toggle) {
    this.closeFavPop();
    const on = this.favsOf(a).includes(id);
    const back = el('div', { class: 'b-favpop-back', onclick: (e) => { e.stopPropagation(); cancel(); } });
    const menu = new ListMenu(this.game.input, {
      items: [{ label: on ? '☆お気に入りからはずす' : '★お気に入りに入れる', value: 'toggle', cls: on ? '' : 'gold' }, { label: 'やめる', value: null }],
      sound: (x) => this.game.audio.sfx(x),
      back: null,
      onSelect: (it) => {
        close();
        if (it.value) toggle();
        else this.menu?.focus();
      },
      onCancel: () => cancel(),
    });
    const box = el('div', { class: 'win b-favpop', role: 'dialog' }, el('div', { class: 'bf-t', text: `${abilityLabel(id, a)}${on ? '（お気に入り）' : ''}` }), menu.root);
    const close = () => {
      menu.blur();
      back.remove();
      box.remove();
      this.favPop = null;
    };
    const cancel = () => {
      close();
      this.menu?.focus();
    };
    this.favPop = { close, id };
    this.menu?.blur();
    this.root.append(back, box);
    menu.focus();
  }

  closeFavPop() {
    this.favPop?.close();
  }

  // 第61回: スマホの たてむき（技の せつめいを 3行までに みじかく）
  compactInfo() {
    return this.touchUi() && !!globalThis.matchMedia?.('(max-aspect-ratio: 1/1)').matches;
  }

  // タッチの 画面（「もう一度タップで使う」を 出す）
  touchUi() {
    return document.body.classList.contains('touch');
  }

  // 魔法剣の くみあわせ（ないときは コマンドにも 出さない）
  mahoukenOpts(a) {
    return mahoukenOptions({ ...(a.pc || this.game.me), job: a.job }, a.abilities || []);
  }

  mahoukenMenu() {
    const a = this.myActor;
    const opts = this.mahoukenOpts(a);
    const items = opts.map((o) => ({ label: o.name, right: `${o.mp}`, value: o, disabled: o.mp > a.mp || !weaponOk({ weapon: 'blade' }, a.weaponCat) }));
    if (!items.length) return toast('魔法剣にできる技がない');
    this.showMenu(items, (it) => {
      this.pickEnemy((tid) => this.send({ type: 'mahouken', spell: it.value.spell, skill: it.value.skill, target: tid }), it.value.name, ABILITIES[it.value.spell]?.effect?.element, () => this.mahoukenMenu());
    }, () => this.openCommand(), '魔法剣（呪文×剣技）', (it) => {
      if (!it) return;
      this.info(`${ABILITIES[it.value.spell].name}の力を${ABILITIES[it.value.skill].name}に宿らせる。\nMP ${it.value.mp}（剣が必要）`);
    });
  }

  itemMenu() {
    const bag = this.game.me.items.filter((e) => ITEMS[e.id]?.battle);
    const a = this.myActor;
    // 月の鏡・そうびしている 魔神のランプ（battle-ch4.js）
    const special = ch4ItemEntries(this, a);
    if (!bag.length && !special.length) {
      toast('戦いで使える道具がない');
      return this.openCommand();
    }
    const bagItems = [...special, ...bag.map((e) => ({ label: ITEMS[e.id].name, right: `×${e.n}`, value: e.id }))];
    const last = a && this.lastPick(a, 'item');
    this.showMenu(bagItems, (it) => {
      if (a) this.rememberPick(a, 'item', it.value);
      if (ch4ItemPick(this, it.value)) return;
      const item = ITEMS[it.value];
      if (item.target === 'self' || item.target === 'allies') return this.send({ type: 'item', id: it.value }); // allies … 全員（ひみつのダンジョンの いやしの大すず）
      return this.pickAlly((tid) => this.send({ type: 'item', id: it.value, target: tid }), item.target === 'deadAlly', item.name, () => this.itemMenu());
    }, () => this.openCommand(), '道具', (it) => {
      if (!it) return;
      // 月の鏡など（battle-ch4.js）は その せつめい。ふつうの 道具は 相手・効果・せつめい（ui/skillinfo.js）
      this.info(ITEMS[it.value] && !special.some((x) => x.value === it.value) ? battleItemText(it.value, { touch: this.touchUi() }) : ch4ItemInfo(it.value));
    }, last ? bagItems.findIndex((x) => x.value === last) : -1, a && this.lastScroll(a, 'item'), true);
  }

  // その 敵に その 属性が どれくらい 効くか（ためした ことが なければ null）
  knownAffinity(e, element) {
    if (!e?.species || !element || element === 'phys') return null;
    const known = this.tried.has(`${e.species}|${element}`) || !!this.game.me?.bestiary?.[e.species]?.[`el_${element}`];
    if (!known) return null;
    return affinityOf(MONSTERS[e.species]?.resist?.[element] ?? 1);
  }

  // ねらう 敵を えらぶ（ドラクエ ふう）
  //   mode 'enemy' … 1体（おなじ 種類が いれば A・B…）/ 'group' …「ゴブリン（2ひき）」の グループ / 'enemies' … えらばない（敵全体）
  //   element: 属性の 技で ねらう とき、ためした ことの ある 敵には 効きぐあいを 出す
  //   back: もどる ボタン（えらぶ まえの メニューへ）
  pickFoe(mode, done, title = 'だれをねらう？', element = null, back = null) {
    // 砂に もぐった 敵は ねらえない（battle-ch4.js。みんな もぐっていたら えらばずに おくる → サーバーが「もぐっている！」）
    const list = this.enemies().filter((e) => e.alive && !e.burrow);
    if (mode === 'enemies' || !list.length) return done(undefined);
    const groups = mode === 'group' ? this.foeGroups(list) : null;
    if (groups ? groups.length === 1 : list.length === 1) return done(groups ? groups[0].lead : list[0].id);
    // 効きぐあいは 名前の 下に 小さく（名前が 2行に ならないように）
    const AFF = { weak: '弱点！', resist: '効きにくい', null: '効かない', normal: 'ふつう' };
    const affTag = (e) => {
      const aff = element ? this.knownAffinity(e, element) : null;
      return aff ? `<span class="aff-line a-${aff}">${AFF[aff]}</span>` : element && ELEMENT_NAMES[element] ? '<span class="aff-line a-unknown">？</span>' : '';
    };
    // 反撃の構えを している 敵（物理で こうげきすると 反撃される）
    const stanceTag = (es) => (es.some((e) => e.stance === 'counter') ? '<span class="aff-line a-stance">反撃の構え</span>' : '');
    const items = groups
      ? groups.map((gp) => ({ html: `${esc(gp.name)}<span class="cnt">（${gp.members.length}ひき）</span>${affTag(gp.members[0])}${stanceTag(gp.members)}`, value: gp.lead }))
      : list.map((e) => ({ html: `${esc(e.name)}${affTag(e)}${stanceTag([e])}`, value: e.id }));
    const hover = (it) => {
      this.hover = it?.value;
      this.hoverGroup = groups ? this.c.get(it?.value)?.species || null : null;
    };
    // まえに ねらった 敵（グループなら おなじ 種類）から カーソルを はじめる（この 戦いの あいだ）
    const prev = this.c.get(this.lastFoe);
    const start = !prev ? 0 : Math.max(0, groups
      ? groups.findIndex((gp) => gp.members[0].species === prev.species)
      : Math.max(list.findIndex((e) => e.id === prev.id), list.findIndex((e) => e.species === prev.species)));
    const pick = (v) => {
      if (v != null) this.lastFoe = v;
      done(v);
    };
    this.showMenu(items, (it) => pick(it.value), back || (() => this.openCommand()), title, hover, start);
    // ねらっている あいだ（showMenu の あとで。スプライトを さわっても えらべる）
    this.targeting = { side: 'enemy', mode, done: pick };
  }

  // 1体を ねらう（むかしの よびかた）
  pickEnemy(done, title = 'だれをねらう？', element = null, back = null) {
    return this.pickFoe('enemy', done, title, element, back);
  }

  // 敵の グループ（おなじ 種類。ならびは 左から）。lead: グループの いちばん 左（これを おくる）
  foeGroups(list = this.enemies().filter((e) => e.alive && !e.burrow)) {
    const out = [];
    for (const e of list) {
      let gp = out.find((x) => x.species === e.species);
      if (!gp) out.push((gp = { species: e.species, name: MONSTERS[e.species]?.name || e.baseName || e.name, members: [], lead: e.id }));
      gp.members.push(e);
    }
    return out;
  }

  pickAlly(done, dead = false, title = 'だれに？', back = null) {
    const list = this.allies();
    this.showMenu(list.map((a) => ({ label: `${a.name}　HP${a.hp}`, value: a.id, disabled: dead ? a.alive : !a.alive })), (it) => done(it.value), back || (() => this.openCommand()), title);
    this.targeting = { side: 'ally', done, dead };
  }

  onCanvasClick(e) {
    if (!this.targeting || this.targeting.side !== 'enemy') return;
    const r = this.canvas.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width * BW, y = (e.clientY - r.top) / r.height * BH;
    for (const m of this.layout || []) {
      if (x >= m.x && x <= m.x + m.w && y >= m.y && y <= m.y + m.h && m.c.alive && !m.c.burrow) {
        this.game.audio.sfx('confirm');
        // グループを えらぶ ときは、さわった 魔物の グループ（いちばん 左を おくる）
        if (this.targeting.mode === 'group') {
          const gp = this.foeGroups().find((g) => g.species === m.c.species);
          return this.targeting.done(gp ? gp.lead : m.c.id);
        }
        return this.targeting.done(m.c.id);
      }
    }
  }

  onAllyClick(id) {
    // ねらう 仲間を えらんでいる とき いがいは、さくせんを かえる まど
    if (!this.targeting || this.targeting.side !== 'ally') return this.tacticsMenu(id);
    const a = this.c.get(id);
    if (!a || (this.targeting.dead ? a.alive : !a.alive)) return;
    this.game.audio.sfx('confirm');
    this.targeting.done(id);
  }

  send(cmd) {
    const a = this.myActor;
    if (!a) return;
    this.closeMenus();
    this.lastSent = a.id;
    this.readyQ = this.readyQ.filter((x) => x !== a.id);
    this.cur = null;
    this.game.net.send({ t: 'battle', actor: a.id, cmd });
    const asking = askingName(this, cmd);
    this.renderCmdIdle(asking ? `${asking}の返事を待っている…` : 'コマンドを選んだ！');
    // めいれいさせろの なかまが まっていれば つづけて えらぶ
    this.nextCommand();
  }

  // オート: じぶんと「めいれいさせろ」の なかま みんな
  toggleAuto() {
    const a = this.primary;
    if (!a) return;
    const on = !a.auto;
    for (const id of this.mine) this.game.net.send({ t: 'battle', actor: id, auto: on });
  }

  updateAutoBtn() {
    const a = this.primary;
    this.autoBtn.classList.toggle('on', !!a?.auto);
    this.autoBtn.textContent = a?.auto ? 'オート中' : 'オート';
    this.autoBtn.hidden = !a;
  }

  // ───────────── サーバーからの できごと ─────────────
  onEvents(evs) {
    for (const ev of evs) {
      switch (ev.t) {
        case 'g':
          for (const [id, v] of Object.entries(ev.g)) {
            const c = this.c.get(id);
            if (c) c.atb = v;
          }
          break;
        case 'ready': {
          const c = this.c.get(ev.id);
          if (c) { c.ready = true; c.atb = 100; c.waitDual = null; c.dualHold = false; }
          if (this.mine.includes(ev.id)) {
            if (!this.readyQ.includes(ev.id)) this.readyQ.push(ev.id);
            if (!this.cur) this.nextCommand();
          }
          this.renderStatus();
          break;
        }
        case 'queued': {
          const c = this.c.get(ev.id);
          if (c) { c.ready = false; c.queued = true; c.waitDual = null; c.dualHold = false; }
          if (this.mine.includes(ev.id)) this.dropReady(ev.id);
          this.renderStatus();
          break;
        }
        case 'auto': {
          const c = this.c.get(ev.id);
          if (c) c.auto = ev.auto;
          if (this.mine.includes(ev.id)) {
            this.updateAutoBtn();
            if (ev.auto) this.dropReady(ev.id);
            if (ev.auto && !this.cur) this.renderCmdIdle();
          }
          this.renderStatus();
          break;
        }
        case 'act':
        case 'msg':
          // 馬車との いれかえは すぐ まどに（メッセージは じゅんばんに）
          if (ev.swap) applyBattleSwap(this, ev);
          this.queue.push(ev);
          break;
        case 'dualInvite': {
          if (this.mine.includes(ev.to)) this.showInvite(ev);
          if (this.mine.includes(ev.from)) {
            const c = this.c.get(ev.from);
            if (c) { c.waitDual = null; c.ready = true; }
            if (!this.cur) this.renderCmdIdle(`${ev.toName}の返事を待っている…`);
          }
          break;
        }
        case 'dualWait': {
          onDualWait(this, ev);
          this.queue.push({ t: 'msg', lines: ev.lines || [], dur: 900 });
          if (this.mine.includes(ev.id)) {
            this.dropReady(ev.id);
            if (!this.cur) this.renderCmdIdle();
          }
          this.renderStatus();
          break;
        }
        case 'dualWaitEnd': {
          onDualWaitEnd(this, ev);
          if (ev.lines?.length && this.mine.includes(ev.id)) toast(ev.lines[0]);
          if (this.mine.includes(ev.id) && !this.cur) this.renderCmdIdle();
          this.renderStatus();
          break;
        }
        case 'dualAnswer':
          onDualAnswer(this, ev);
          break;
        case 'dualHold':
          onDualHold(this, ev);
          break;
        case 'tactics':
          this.onTactics(ev);
          break;
        case 'end':
          this.endPending = ev.outcome;
          break;
        default:
      }
    }
  }

  present(ev) {
    // 第48回の 大技: ためる → はなつ ので、名前の ふだと つぎの 行動を あたる まで まつ（え だけ。たたかいの 中みは かわらない）
    ev.axAnim = axEventAnim(ev);
    // 技ごとの ちがい（男の子の 版・合体技）・2回目（ため 半分）・的の かずは サーバーと おなじ（axEventOpts）
    ev.axOpts = ev.axAnim ? axEventOpts(ev) : null;
    ev.axHold = ev.axAnim ? axHoldMs(ev.axAnim, { tempo: this.fxTempo(), ...ev.axOpts, targets: ev.axOpts.n, crit: (ev.results || []).some((r) => r.crit) }) : 0;
    if (ev.t === 'act') this.plate(ev);
    // 合体技を 使ったら、自分の キャラは 効果が わかる（サーバーでも おぼえる）
    if (ev.dual?.id && (ev.dual.m || [ev.dual.a, ev.dual.b]).some((id) => this.mine.includes(id))) {
      const me = this.game.me;
      if (me) me.dualSeen = { ...(me.dualSeen || {}), [ev.dual.id]: 1 };
    }
    // 合体技・ひらめきは さきに 大きく 見せてから
    const pre = ev.dual ? dualPre(ev, this.fxSpeed) : (ev.hirameki ? AX_HIRA_PRE_MS : 0) / this.fxSpeed;
    if (pre) {
      this.say((ev.lines || []).slice(0, ev.dual ? 2 : 1), 500);
      if (ev.dual) this.dualFx(ev);
      else this.hiramekiFx(ev);
      if (ev.axHold) ev.axHold += pre;
      setTimeout(() => { if (!this.destroyed) this.presentBody(ev); }, pre);
      return;
    }
    this.presentBody(ev);
  }

  presentBody(ev) {
    const g = this.game;
    const wasTele = !!this.c.get(ev.id)?.telegraph;
    // 第48回の 大技: ためて いる 間は 味方の HPの 数を まえの まま（あたった ときに かわる。たおれた 人は すぐ）
    const axHp = ev.axAnim ? new Map() : null;
    const axHit = new Set(ev.axAnim ? (ev.results || []).filter((r) => r.dmg > 0 || r.heal > 0).map((r) => r.id) : []);
    for (const u of ev.upd || []) {
      const c = this.c.get(u.id);
      if (c) {
        const was = c.alive;
        const oldHp = c.hp;
        Object.assign(c, u, { ready: u.ready });
        if (axHp && c.side === 'ally' && c.alive && axHit.has(c.id) && Number.isFinite(oldHp) && c.hp !== oldHp) { axHp.set(c.id, [oldHp, c.hp]); c.hp = oldHp; }
        // 生き返った 敵（ミイラの王アンクの よみがえりの呪文）: もう一度 すがたを あらわす
        if (c.side === 'enemy' && c.alive && !was) { c.dead = 0; c.appear = 1; c.vanished = false; }
      } else this.c.set(u.id, { ...u, flash: 0, dead: 0, lunge: 0 });
    }
    for (const j of ev.joined || []) if (!this.c.has(j.id)) this.c.set(j.id, { ...j, flash: 0, dead: 0, lunge: 0, appear: 1 });
    this.say(ev.lines || [], ev.dur || 1000);
    // 行動の はじめの じわじわ回復（第38回 C）: 回復した 人に みどりの 数
    for (const r of ev.regenHeal || []) {
      const t = this.c.get(r.id);
      if (!t) continue;
      this.floatNum(t, `+${r.heal}`, 'heal');
      if (t.side === 'ally') this.glowStatus(t.id, '#8ff0a8');
    }
    // 第72回: 元気玉で HPを 出した 人（小さい 水色の 数・まどが 光る。shared/battle-genki.js）
    for (const r of ev.genki || []) {
      const t = this.c.get(r.id);
      if (!t) continue;
      this.floatNum(t, `-${r.hp}`, 'genki');
      if (t.side === 'ally') this.glowStatus(t.id, '#a8e4ff');
    }
    const actor = this.c.get(ev.id);
    const fx = ev.fx || {};
    // 反撃の構え: やりかえされた 味方の ダメージは、こうげきが あたった あとで 見せる
    const counterIds = new Set((ev.counter || []).map((k) => k.target));
    const counterRes = counterIds.size ? (ev.results || []).filter((r) => counterIds.has(r.id)) : [];
    if (counterIds.size) ev.results = (ev.results || []).filter((r) => !counterIds.has(r.id));
    if (actor && this.mine.includes(actor.id) && !this.cur) this.renderCmdIdle();
    // エフェクト
    const targets = (fx.targets || []).map((id) => this.c.get(id)).filter(Boolean);
    const enemyPts = targets.filter((t) => t.side === 'enemy').map((t) => this.center(t)).filter(Boolean);
    const anim = ev.axAnim || sigAnim(ev.ability) || r27Anim(ev.ability) || fx.anim || (fx.type === 'attack' ? (fx.side === 'ally' ? (fx.weapon === 'claw' || fx.weapon === 'none' ? 'punch' : 'slash_heavy') : 'hit') : null);
    const crit = (ev.results || []).some((r) => r.crit);
    const fromAlly = fx.side === 'ally';
    const ab = ev.ability ? ABILITIES[ev.ability] : null;
    const tempo = this.fxTempo();
    const allyTargets = targets.filter((t) => t.side === 'ally');
    // こうどうした てきが うごく（こうげき・じゅもん・ブレス…）。lead: みかたに とどく じかん
    // 大技（第48回）を ためる 敵は ためる すがた（まつ 時間は ためる ほうに ふくまれる）
    // 時間は サーバーと おなじ 数（shared/ax-time.js）。hitAt … エフェクトの 時計で あたる 時間（おそい 設定の しぼり こみ）
    const axT = ev.axAnim ? axTiming(ev.axAnim, { tempo, ...ev.axOpts, targets: ev.axOpts.n, crit }) : null;
    const lead = actor && actor.side === 'enemy' && ev.t === 'act' ? (axT?.charge ? axEnemyPose(actor, ev.axAnim, ev.axOpts) : this.enemyAct(actor, fx, ab, allyTargets, wasTele)) : 0;
    // 大技の えに わたす もの（技の キー・2回目・合体技・的の かず・音。actorImg は 第49回から つかわない）
    const axOpts = ev.axAnim ? { ...ev.axOpts, sfx: (id) => { if (!this.destroyed) g.audio.sfx(id); }, actorImg: actor?.side === 'enemy' ? (this.layout || []).find((m) => m.c === actor)?.img || null : null } : {};
    // 味方が ためて いる 間は その 人の まども 光る
    if (axT?.charge && actor?.side === 'ally') {
      // 気（ki）は 黄色い オーラと おなじ 色（第49回）
      const col = axT.kind === 'ki' ? '#ffd23a' : axDef(ev.axAnim)?.charge?.color || '#ffd66b';
      for (let t = 0; t < axT.chargeAt; t += 300) this.fx.at(t, () => { if (!this.destroyed) this.glowStatus(actor.id, col); });
    }
    let hitDelay = 0;
    // ムチ（グループ）・ブーメラン（全体）: 敵ごとに あたる じかんが ちがう（id → ms）
    let perHit = null;
    if (fx.type === 'attack' && fromAlly && fx.reach && enemyPts.length) {
      const hitTs = targets.filter((t) => t.side === 'enemy' && this.center(t));
      const crits = hitTs.map((t) => (ev.results || []).some((r) => r.id === t.id && r.crit));
      const times = this.fx.weaponReach(hitTs.map((t) => this.center(t)), fx.weapon, crits, { id: fx.weaponId, mon: actor?.mon });
      perHit = new Map(hitTs.map((t, i) => [t.id, times[i]]));
      hitDelay = Math.min(...times);
      g.audio.sfx(fx.weapon === 'boomerang' ? 'wind' : 'card');
    } else if (anim && anim !== 'none' && enemyPts.length) {
      if (fx.type === 'attack' && fromAlly) {
        // ぶきごとの エフェクト（あたる じかんが かえってくる）
        hitDelay = this.fx.weaponHit(enemyPts, fx.weapon, crit, { id: fx.weaponId, mon: actor?.mon });
        if (fx.weapon === 'bat') g.audio.sfx('bat');
        else if (fx.weapon === 'axe') g.audio.sfx('smash');
      } else {
        this.fx.play(anim, enemyPts, fx.element, { crit, fromAlly, ability: ev.ability, from: actor && (actor.side === 'ally' ? this.allyPt(actor) : this.center(actor)), ...axOpts });
        hitDelay = axT ? axT.hitAt : r27Hit(anim, ev.ability) ?? HIT_DELAY[anim] ?? 0;
      }
    }
    // 味方に かける 合体技（回復・ステージ）は、たたかいの 画面にも 大きく
    if (fx.type === 'dual' && anim && !enemyPts.length && !axT) this.fx.play(anim, [{ x: BW / 2, y: BH * 0.55 }], fx.element, { fromAlly: true });
    // 自分や 味方に かける 大わざ（金色のオーラ・解放のドラム・空調こう新）も、たたかいの 画面の 下（味方の いる ところ）に 大きく
    // 第48回の 大技を 味方に かける（回復・強化 など）: 味方の いちに（ためるのは つかった 人）
    else if (fromAlly && axT && !enemyPts.length) {
      const pts = allyTargets.length ? allyTargets.map((t) => this.allyPt(t)) : [{ x: BW / 2, y: BH * 0.62 }];
      if (allyTargets.length || axIsParty(anim)) this.fx.play(anim, pts, fx.element, { crit, fromAlly: true, ability: ev.ability, from: actor?.side === 'ally' ? this.allyPt(actor) : undefined, ...axOpts });
      hitDelay = axT.hitAt;
    } else if (fromAlly && (PARTY_ANIMS.has(anim) || PARTY_ANIMS3.has(anim) || PARTY_ANIMS7.has(anim) || PARTY_ANIMS8.has(anim) || PARTY_ANIMS_R41B.has(anim) || PARTY_ANIMS_R41A.has(anim) || PARTY_ANIMS_R43J.has(anim) || PARTY_ANIMS_R66C.has(anim) || SIG4.has(anim)) && !enemyPts.length) this.fx.play(anim, [{ x: BW / 2, y: BH * 0.62 }], fx.element, { fromAlly: true });
    // 第66回 E2 の 味方に かける えんしゅつ（セーブ・ロード・制御装置。render/battlefx-r66e2.js）も、たたかいの 画面の 下に 大きく
    if (fromAlly && !axT && PARTY_ANIMS_R66E2.has(anim) && !enemyPts.length) this.fx.play(anim, [{ x: BW / 2, y: BH * 0.62 }], fx.element, { fromAlly: true });
    // みかたへの えんしゅつ（てきの じゅもんは たまが とんでくる）
    if (anim && anim !== 'none' && allyTargets.length) {
      const kind = allyFxKind(anim, fx, ab);
      let d = lead;
      if (!fromAlly && SPELL_ANIMS.has(anim) && !/^wind/.test(anim) && actor) {
        const from = this.center(actor);
        if (from) {
          this.fx.proj(this.allyPt(allyTargets[0]).x, BH + 8, ELEM_COLORS[fx.element] || ELEM_COLORS.dark, { from, travel: 240, delay: lead, size: 4.5 });
          d = lead + 240;
        }
      }
      if (!fromAlly && anim === 'breath') this.fx.tintAt(fx.element === 'fire' ? 'rgba(255, 120, 40, 0.16)' : 'rgba(200, 230, 255, 0.14)', 500 + lead);
      // ポケモンの 技が みんなに あたる: 出どころ（敵の まん中）から みんなの いちへ（render/battlefx-pokemon.js。あたる ときが うごきの おわりに あう）
      // 第45回の ドラクエふうの 技（dq_…）も おなじ。せかいじゅの子の 回復（味方に かける）も ここで みんなの いちに 出す
      // 第48回の 大技（敵が みんなに。味方が 味方に かけた ときは うえで 出した）も おなじ
      const pkHit = PK_ANIMS.has(anim) || DQ_ANIMS.has(anim) || !!axT;
      if (pkHit && !(axT && fromAlly)) {
        const from = actor && (actor.side === 'ally' ? this.allyPt(actor) : this.center(actor));
        const at = allyTargets.map((t) => this.allyPt(t));
        const hitMs = axT ? axT.hitAt : PK_HIT[anim] || DQ_HIT[anim] || 0;
        d = Math.max(lead, hitMs);
        const go = () => { if (!this.destroyed) this.fx.play(anim, at, fx.element, { crit, fromAlly: false, from: from || undefined, ability: ev.ability, ...axOpts, toParty: true }); };
        if (d - hitMs > 0) this.fx.at(d - hitMs, go);
        else go();
      }
      // てきの こうげきが こちらに あたる（がめんの てまえに 大きく）
      if (axT && fromAlly) d = Math.max(d, axT.hitAt);
      if (actor?.side === 'enemy' && !pkHit) {
        const style = hitStyle(fx, ab, actor);
        const col = actColor('shimmy', fx, ab);
        allyTargets.forEach((t, i) => {
          const r = (ev.results || []).find((x) => x.id === t.id);
          if (!r?.miss) closeUp(this.fx, this.allyPt(t), style, (r?.dmg || 0) / (t.maxHp || 1), d + i * 60, col);
        });
      }
      allyTargets.forEach((t, i) => this.allyFx(t.id, kind, (d + (allyTargets.length > 1 ? i * 60 : 0)) / tempo));
      if (fromAlly && !pkHit && fx.type !== 'dual' && !SIG4.has(anim) && !PARTY_ANIMS.has(anim) && !PARTY_ANIMS3.has(anim) && !PARTY_ANIMS7.has(anim) && !PARTY_ANIMS8.has(anim) && !PARTY_ANIMS_R41B.has(anim) && !PARTY_ANIMS_R41A.has(anim) && !PARTY_ANIMS_R43J.has(anim) && !PARTY_ANIMS_R66C.has(anim)) playAllyR27(this.fx, anim, allyTargets.map((t) => this.allyPt(t)), { ability: ev.ability, element: fx.element, from: actor && this.allyPt(actor) });
      if (!hitDelay) hitDelay = d;
    }
    // じゅもんを となえた みかたは すこし ひかる
    if (fromAlly && actor?.side === 'ally' && ab && (ab.kind === 'spell' || ab.spellLike)) {
      this.glowStatus(actor.id, (ELEM_COLORS[fx.element] || ELEM_COLORS.light)[0]);
    }
    if (fx.type === 'poison') {
      for (const u of ev.upd || []) {
        const c = this.c.get(u.id);
        if (!c || !(c.status || []).includes('poison')) continue;
        if (c.side === 'ally') this.allyFx(c.id, 'poison');
        else {
          const pt = this.center(c);
          if (pt) this.fx.burst(pt.x, pt.y, ['#b06ae0', '#7a3aa8', '#d8a8ff'], 10, 30, { vy: -20 });
        }
      }
    }
    // 第5章 Step 9 の ノクト（本気）・ソリトゥスは、自分の 前ぶれの バナー（client/battle-final.js）
    if (fx.type === 'telegraph' && !FINAL_OWN_TELE.has(actor?.species) && !CH6_OWN_TELE.has(actor?.species)) { g.audio.sfx('warn'); this.banner(fx.chant ? '！呪文の前ぶれ！大きなダメージで止めろ！' : '！大技が来る！防御で身を守れ！', 'danger'); }
    // よみがえりの呪文を 止めた
    if (ev.chantBreak) { g.audio.sfx('crit'); this.banner('呪文を止めた！', 'combo'); }
    if (fx.type === 'stance') { g.audio.sfx('warn'); this.banner('！反撃の構え！なぐると反撃される', 'danger'); }
    // 合体技の よやくで まっていた 人が ダメージ: ゲージが 半分から やり直し（battle-dual.js）
    if (ev.dualBreak) onDualBreak(this, ev);
    if (fx.type === 'flee') g.audio.sfx('flee');
    if (fx.type === 'wagon') wagonSwapFx(this, ev);
    // 月の鏡・まぼろし・ボスの 大技（battle-ch4.js）
    ch4Present(this, ev, fx, anim, actor, lead);
    if (ev.combo >= 2 && !ev.dual) this.banner(`れんけい ${ev.combo}！`, 'combo');
    if (anim === 'minadein') g.audio.sfx('bolt');
    // 大技（第48回）の 音は render/axfx.js が ためる とき・はなつ ときに ならす
    const sfxId = axT ? null : (fx.type !== 'attack' && r27Sfx(anim, ev.ability)) || ANIM_SFX[anim];
    if (anim && sfxId) g.audio.sfx(sfxId);
    else if (fx.type === 'ability' && fromAlly && !axT) g.audio.sfx('spell');
    if (fx.anim === 'quake') {
      const q = () => { if (!this.destroyed) this.shake(500, 7); };
      if (lead) setTimeout(q, lead / tempo);
      else q();
    }
    // けっか（じゅもんは あたった ときに）。only: その 敵の ぶん だけ（ムチ・ブーメラン）
    const apply = (only = null) => {
      if (this.destroyed) return;
      let hurtAlly = false;
      // 大技で まっていた 味方の HPの 数（その あいだに つぎの 行動で かわって いたら そのまま）
      if (axHp?.size) {
        for (const [id, [was, now]] of axHp) { const c = this.c.get(id); if (c && c.hp === was) c.hp = now; }
        axHp.clear();
        this.renderStatus();
      }
      for (const r of ev.results || []) {
        if (only && r.id !== only) continue;
        const t = this.c.get(r.id);
        if (!t) continue;
        // まぼろしの 分身に 当たって 消えた（battle-ch4.js）
        if (r.vanish) { vanishFx(this, t); continue; }
        if (r.aff && r.element && t.species) {
          this.tried.add(`${t.species}|${r.element}`);
          if (r.aff === 'weak' && r.dmg > 0) this.floatNum(t, '弱点！', 'weak');
        }
        if (r.dmg > 0) {
          if (t.side === 'enemy') {
            t.flash = 320;
            if (!fx.anim || fx.type === 'attack' || hitDelay) g.audio.sfx(r.crit ? 'crit' : 'hit');
          } else {
            hurtAlly = true;
            this.hitStatus(t.id, r.dmg / (t.maxHp || 1));
            g.audio.sfx(r.crit ? 'crit' : 'hurt');
          }
          this.floatNum(t, String(r.dmg), r.crit ? 'crit' : '');
        } else if (r.heal > 0) {
          this.floatNum(t, `+${r.heal}`, 'heal');
          if (t.side === 'ally') { if (!allyTargets.includes(t)) this.allyFx(t.id, 'heal'); } else this.fx.play('heal1', [this.center(t)].filter(Boolean));
        } else if (r.miss || r.dmg === 0) {
          this.floatNum(t, 'ミス', 'miss');
          g.audio.sfx('miss');
        }
      }
      // 味方が 大きな ダメージを 受けた（HPの 2わりいじょう・つうこん・ボス）: 画面が ゆれて 赤く 光る
      const bigHurt = (ev.results || []).some((r) => r.dmg > 0 && this.c.get(r.id)?.side === 'ally' && r.dmg >= (this.c.get(r.id).maxHp || 1) * 0.2);
      // いたみの 大きさで がめんが ゆれて、ふちが あかく なる
      const worst = Math.min(1, Math.max(0, ...(ev.results || []).filter((r) => r.dmg > 0 && this.c.get(r.id)?.side === 'ally').map((r) => r.dmg / (this.c.get(r.id).maxHp || 1))));
      if (hurtAlly && actor?.side === 'enemy') {
        this.fx.hitStop(120 + worst * 260, 0, 0.7 + worst * 3.5);
        this.fx.vignette('#ff2020', 460, Math.min(0.55, 0.2 + worst * 0.8));
      }
      if (hurtAlly && actor?.side === 'enemy' && (actor.boss || bigHurt || (ev.results || []).some((r) => r.crit))) {
        this.shake(bigHurt || actor.boss ? 380 : 300, 4 + worst * 8);
        this.fx.flash = 80;
        this.fx.flashColor = '#ff5a5a';
      }
      for (const c of this.c.values()) {
        if (c.side === 'enemy' && !c.alive && !c.dead && (!only || c.id === only)) {
          c.dead = 1;
          g.audio.sfx(c.vanished ? 'sparkle' : 'defeat');
        }
      }
    };
    if (perHit) {
      // あたった じゅんに ダメージの かずを 出す（エフェクトの 時計で。さいごに のこりも まとめて）
      for (const [id, ms] of perHit) this.fx.at(ms, () => apply(id));
      const rest = (ev.results || []).some((r) => !perHit.has(r.id));
      this.fx.at(Math.max(...perHit.values()) + 30, () => {
        if (this.destroyed) return;
        if (rest) for (const r of ev.results || []) if (!perHit.has(r.id)) apply(r.id);
        for (const c of this.c.values()) if (c.side === 'enemy' && !c.alive && !c.dead) c.dead = 1;
      });
    } else if (hitDelay > 0 && axT) this.fx.at(hitDelay, apply); // 大技は エフェクトの 時計で（おもい きかいでも はなつ 前に 数が 出ない）
    else if (hitDelay > 0) setTimeout(apply, hitDelay / tempo);
    else apply();
    if (ev.counter?.length) this.counterFx(ev.counter, counterRes, (perHit ? Math.max(...perHit.values()) : hitDelay) + 380);
    // えらんでいる とちゅうで たおれた・ねむった など
    const cur = this.cur && this.c.get(this.cur);
    if (cur && (!cur.alive || (cur.status || []).some((x) => x === 'sleep' || x === 'paralyze' || x === 'prison' || x === 'rift') || !cur.ready)) this.dropReady(cur.id);
    else if (!this.cur && this.menu && !this.targeting) this.renderCmdIdle();
    this.renderStatus();
    this.updateAutoBtn();
  }

  // ───────────── さくせん（つよさの まどを タップ） ─────────────
  // かえられるのは じぶん（オートの ときの さくせん）と じぶんの なかま（サーバーも たしかめる。world/tactics.js）
  canTactics(a) {
    const me = this.game.me?.id;
    return !!a && a.side === 'ally' && !a.fled && !!me && a.tacBy === me && !this.ended;
  }

  tacticsMenu(id) {
    const a = this.c.get(id);
    if (!this.canTactics(a) || this.destroyed) return;
    this.closeTactics();
    const self = a.kind === 'player';
    const now = a.tactics || 'balanced';
    // じぶんは「めいれいさせろ」なし（いつも じぶんで えらぶ）
    const items = Object.entries(TACTICS).filter(([k]) => !self || k !== 'manual')
      .map(([k, x]) => ({ label: x.name, value: k, right: k === now ? '今' : '', cls: k === now ? 'tac-now' : '' }));
    const m = new ListMenu(this.game.input, {
      items,
      sound: (x) => this.game.audio.sfx(x),
      start: Math.max(0, items.findIndex((it) => it.value === now)),
      back: '閉じる',
      onSelect: (it) => {
        this.closeTactics();
        if (it.value !== now) this.game.net.send({ t: 'battle', actor: id, tactics: it.value });
      },
      onCancel: () => this.closeTactics(),
    });
    const box = el('div', { class: 'win b-tactics' },
      el('div', { class: 'bt-t', text: self ? `${a.name}の作戦（オートのとき）` : `${a.name}の作戦` }), m.root);
    box.addEventListener('click', (e) => e.stopPropagation());
    // 戦いの がめん ぜんたいの まんなか（えの ところが せまい スマホでも ぜんぶ 見える）
    this.root.append(box);
    this.menu?.blur();
    m.focus();
    this.tac = { id, box, menu: m };
    this.game.audio.sfx('cursor');
  }

  closeTactics() {
    const t = this.tac;
    if (!t) return;
    this.tac = null;
    t.menu.blur();
    t.box.remove();
    if (!this.invite) this.menu?.focus();
  }

  // さくせんが かわった（サーバーから）。めいれいさせろ に なった なかまは じぶんが うごかす
  onTactics(ev) {
    const c = this.c.get(ev.id);
    if (!c) return;
    c.tactics = ev.tactics;
    c.controller = ev.controller;
    c.auto = ev.auto;
    const mine = !!ev.controller && ev.controller === this.game.sid;
    if (mine && !this.mine.includes(ev.id)) {
      this.mine.push(ev.id);
      this.mine.sort((x, y) => (this.c.get(x)?.kind === 'player' ? 0 : 1) - (this.c.get(y)?.kind === 'player' ? 0 : 1));
      if (c.ready && c.alive && !c.auto && !this.readyQ.includes(ev.id)) {
        this.readyQ.push(ev.id);
        if (!this.cur) this.nextCommand();
      }
    } else if (!mine && this.mine.includes(ev.id)) {
      this.mine = this.mine.filter((x) => x !== ev.id);
      this.dropReady(ev.id);
    }
    if (this.tac?.id === ev.id) this.closeTactics();
    this.renderStatus();
  }

  // ───────────── 合体技（2人・3人・4人。battle-dual.js） ─────────────
  myDualOptions(a) { return myDualOptions(this, a); }
  dualMenu(opts) { return dualMenu(this, opts); }
  // 家族から 合体技に さそわれた
  showInvite(ev) { showInvite(this, ev); }

  closeInvite() {
    const iv = this.invite;
    if (!iv) return;
    this.invite = null;
    iv.menu.blur();
    iv.box.remove();
    this.menu?.focus();
  }

  // ───────────── だれが 何を したか ─────────────
  plate(ev) {
    const a = this.c.get(ev.id);
    if (!a || !ev.name) return;
    let cls = a.side === 'enemy' ? 'enemy' : 'ally';
    let who = a.name;
    let what = ev.sub ? `${ev.name} → ${ev.sub}` : ev.name;
    if (ev.dual) {
      cls = 'dual';
      who = (ev.dual.m || [ev.dual.a, ev.dual.b]).map((id) => this.c.get(id)?.name || '').join('＆');
      what = ev.dual.name;
    } else if (ev.hirameki) cls = 'hira';
    const ai = a.side === 'ally' && (!a.controller || a.auto);
    this.plateEl?.remove();
    const e = el('div', { class: `b-plate ${cls}` }, el('span', { class: 'who', text: who }), ai ? el('span', { class: 'ai', text: 'オート' }) : null, el('span', { class: 'what', text: what }));
    this.stage.append(e);
    this.plateEl = e;
    clearTimeout(this.plateT);
    this.plateT = setTimeout(() => e.remove(), Math.max(1400, (ev.dur || 900) * 0.9, ev.axHold ? ev.axHold + 200 : 0));
    if (a.side === 'ally' && !ev.dual) this.glowStatus(a.id, ev.hirameki ? '#fff6b0' : '#9ad8ff');
  }

  // ひらめき！（電球と 大きな 文字）
  hiramekiFx(ev) {
    const h = ev.hirameki;
    this.game.audio.sfx('hirameki');
    this.fx.flash = 220;
    this.fx.flashColor = '#fff6b0';
    const s = this.statusBoxes.get(h.actor);
    if (s) {
      const bulb = el('div', { class: 'bulb', html: BULB_SVG });
      s.box.append(bulb);
      setTimeout(() => bulb.remove(), 2000);
      this.glowStatus(h.actor, '#fff6b0');
    }
    const who = this.c.get(h.actor)?.name || '';
    const cut = el('div', { class: 'b-hira' }, el('div', { class: 'h0', html: BULB_SVG }), el('div', { class: 'h1', text: `${who}はひらめいた！` }), el('div', { class: 'h2', text: h.name }));
    this.stage.append(cut);
    setTimeout(() => cut.remove(), 1700);
  }

  // 合体技の カットイン（みんなの かおと 技の 名前）と とどめの えんしゅつ（render/dualfx.js）
  dualFx(ev) { dualFx(this, ev); }

  center(t) {
    const m = (this.layout || []).find((l) => l.c === t || l.c.id === t.id);
    if (!m) return null;
    return { x: m.x + m.w / 2, y: m.y + m.h / 2, w: m.w, h: m.h, foot: m.y + m.h };
  }

  // みかたの いち（がめんの てまえ・したの ほう。まどの じゅんばん）
  allyPt(t) {
    const list = this.allies();
    const n = Math.max(1, list.length);
    const i = Math.max(0, list.findIndex((a) => a.id === t.id));
    return { x: BW / 2 + (i - (n - 1) / 2) * Math.min(58, (BW * 0.8) / n), y: BH - 22 };
  }

  // てきの うごき（こうげき・じゅもん・ブレス…）。へんじ: みかたに とどく じかん
  enemyAct(actor, fx, ab, allyTargets, finisher) {
    const kind = enemyActKind(fx, ab, actor);
    const pt = kind && this.center(actor);
    if (!pt) return 0;
    const to = allyTargets.map((t) => this.allyPt(t));
    return startEnemyAct(this.fx, actor, pt, kind, to, { fx, ab, finisher: finisher && kind !== 'charge' });
  }

  // おもくて カクカク する きかいでは え の こまかさを 1だんずつ さげる（3ばい → 2ばい → 1ばい）
  // 細かく 描いた ボスの ために 上げて いる ときは、まず それを やめる（battleRes は そのまま）
  checkQuality(dt) {
    this.avgDt = this.avgDt ? this.avgDt * 0.9 + dt * 0.1 : 16;
    if (this.res > 1 && this.time > 2500 && this.time - (this.resAt || 0) > 1500 && this.avgDt > 38) {
      if (this.res > battleRes) this.fineOff = true;
      else battleRes = this.res - 1;
      this.res = battleRes;
      this.resAt = this.time;
      this.avgDt = 16;
      this.canvas.width = BW * this.res;
      this.canvas.height = BH * this.res;
    }
  }

  // たたかいの はやさ（せっていの はやさに エフェクトも あわせる）
  fxTempo() {
    // サーバーから きた「戦いの速さ（エフェクト）」（前の セーブも ならした あと の あたい）
    return Math.max(0.5, Math.min(2, this.fxSpeed || 1));
  }

  floatNum(t, text, cls) {
    let px, py;
    if (t.side === 'enemy') {
      const p = this.center(t);
      if (!p) return;
      const r = this.canvas.getBoundingClientRect();
      const sr = this.stage.getBoundingClientRect();
      px = r.left - sr.left + p.x / BW * r.width;
      py = r.top - sr.top + (p.y - 8) / BH * r.height;
      const e = el('div', { class: `dmg ${cls}`, text, style: { left: `${px}px`, top: `${py}px` } });
      this.floatEl.append(e);
      setTimeout(() => e.remove(), 1150);
    } else {
      const s = this.statusBoxes.get(t.id);
      if (!s) return;
      const e = el('div', { class: `dmg ${cls}`, text, style: { left: '50%', top: '40%' } });
      s.box.append(e);
      setTimeout(() => e.remove(), 1150);
    }
  }

  // power: HPに たいする ダメージの わりあい（大きいほど 大きく ゆれて あかく ひかる）
  hitStatus(id, power = 0) {
    const s = this.statusBoxes.get(id);
    if (!s) return;
    s.box.classList.remove('hit');
    void s.box.offsetWidth;
    s.box.classList.add('hit');
    if (power > 0 && s.box.animate) {
      const k = Math.min(1, power * 2.5);
      const px = Math.round(3 + k * 6);
      const red = `0 0 0 2px #000, 0 0 ${Math.round(8 + k * 14)}px rgba(255, 50, 50, ${(0.5 + k * 0.45).toFixed(2)})`;
      s.box.animate([
        { transform: 'translate(0, 0)', boxShadow: red },
        { transform: `translate(${-px}px, 1px)` },
        { transform: `translate(${px}px, -1px)` },
        { transform: `translate(${-Math.round(px / 2)}px, 0)` },
        { transform: 'translate(0, 0)', boxShadow: '0 0 0 2px #000' },
      ], { duration: 300 + k * 200, easing: 'ease-out' });
    }
  }

  // みかたの まどの うえの えんしゅつ（ひっかき・ほのお・こおり・かいふく・↑↓ など）
  allyFx(id, kind, delay = 0) {
    const run = () => {
      if (this.destroyed) return;
      const s = this.statusBoxes.get(id);
      if (!s) return;
      const e = el('div', { class: `afx afx-${kind}` });
      if (kind === 'up') e.textContent = '▲ ▲ ▲';
      else if (kind === 'down') e.textContent = '▼ ▼ ▼';
      else if (kind === 'sleep') e.textContent = 'Z z z';
      s.box.append(e);
      setTimeout(() => e.remove(), 950);
    };
    if (delay > 0) setTimeout(run, delay);
    else run();
  }

  // 反撃の構えの 敵が、こうげきして きた 味方に やりかえす（delay: こうげきが あたった あと）
  counterFx(list, results, delay) {
    const g = this.game;
    const tempo = this.fxTempo();
    setTimeout(() => {
      if (this.destroyed) return;
      this.banner('反撃された！', 'danger');
      list.forEach((k, i) => {
        const by = this.c.get(k.actor), t = this.c.get(k.target);
        if (!t) return;
        const r = results.find((x) => x.id === t.id);
        const lead = (by ? this.enemyAct(by, { type: 'attack' }, null, [t], false) : 0) + i * 120;
        setTimeout(() => {
          if (this.destroyed) return;
          if (!r || r.miss || !(r.dmg > 0)) {
            this.floatNum(t, 'ミス', 'miss');
            g.audio.sfx('miss');
            return;
          }
          const pow = r.dmg / (t.maxHp || 1);
          closeUp(this.fx, this.allyPt(t), 'claw', pow, 0, '#ffa22a');
          this.hitStatus(t.id, pow);
          this.floatNum(t, String(r.dmg), r.crit ? 'crit' : '');
          g.audio.sfx(r.crit ? 'crit' : 'hurt');
          this.fx.vignette('#ff2020', 460, Math.min(0.5, 0.2 + pow * 0.8));
          this.shake(320, 4 + pow * 8);
        }, lead / tempo);
      });
    }, delay / tempo);
  }

  glowStatus(id, color) {
    const s = this.statusBoxes.get(id);
    if (!s) return;
    s.box.animate([{ boxShadow: `0 0 0 2px #000, 0 0 18px ${color}` }, { boxShadow: '0 0 0 2px #000' }], { duration: 700 });
  }

  banner(text, cls = '') {
    const b = el('div', { class: `b-banner ${cls}`, text });
    this.stage.append(b);
    setTimeout(() => b.remove(), 1600);
  }

  shake(ms, px = 5) {
    const a = Math.round(px), b = Math.round(px * 0.4), c = Math.round(px * 0.6);
    this.stage.animate([{ transform: 'translate(0,0)' }, { transform: `translate(${-a}px,${b}px)` }, { transform: `translate(${a}px,${-b}px)` }, { transform: `translate(${-c}px,${Math.round(b / 2)}px)` }, { transform: 'translate(0,0)' }], { duration: ms });
  }

  // ───────────── まいフレーム ─────────────
  update(dt) {
    this.time += dt;
    this.fx.tempo = this.fxTempo();
    this.checkQuality(dt);
    // メッセージの じゅんばん
    if (this.showing) {
      this.showing.left -= dt;
      if (this.showing.left <= 0 || this.queue.length > 2) this.showing = null;
    }
    if (!this.showing && this.queue.length) {
      const ev = this.queue.shift();
      this.present(ev);
      this.showing = { left: Math.max(350, (ev.dur || 900) * 0.75, ev.axHold || 0) };
    }
    if (!this.showing && !this.queue.length && this.endPending && !this.ended) {
      this.ended = true;
      this.closeMenus();
    }
    // ゲージを なめらかに（ウェイトで だれかが えらんでいる 間は 1ミリも うごかさない）
    const locked = !!this.showing || this.choosingPause();
    for (const c of this.c.values()) {
      if (!c.alive || c.ready || locked) continue;
      if (c.rate && c.atb < 100) c.atb = Math.min(99.5, c.atb + c.rate * dt * (this.fxSpeed || 1) * 0.6);
      if (c.flash > 0) c.flash -= dt;
      if (c.lunge > 0) c.lunge -= dt;
    }
    for (const c of this.c.values()) {
      if (c.flash > 0) c.flash -= dt;
      if (c.lunge > 0) c.lunge -= dt;
      if (c.dead > 0 && c.dead < 2) c.dead += dt / 500;
      if (c.appear > 0) c.appear -= dt / 400;
      if (c.act && (c.act.age += dt * this.fx.tempo) >= c.act.dur) c.act = null;
    }
    this.fx.update(dt); // はやさは fx.tempo で かける
    this.updateGauges();
    // 第77回 C: ピンチ（仲間の HP）・ボスの だん（client/audio-scene.js）
    this.game.sceneAudio?.battleTick({ combatants: this.c.values(), boss: this.boss, ended: !!(this.endPending || this.ended) });
    this.draw();
  }

  // 第65回: 細かく 描いた ボス（monsterFine が 1より 大きい）が いる 間の がめんの こまかさ
  fineRes() {
    const fine = !this.fineOff && this.enemies().some((c) => !(c.dead >= 2) && monsterFine(c.species) > 1);
    const want = fine ? Math.max(battleRes, Math.min(FINE_RES_MAX, battleRes * 2)) : battleRes;
    if (want === this.res) return;
    this.res = want;
    this.canvas.width = BW * want;
    this.canvas.height = BH * want;
  }

  // サーバーの「ウェイトモードで 止まっている」と おなじ かんがえかた
  choosingPause() {
    if (!this.waitMode) return false;
    for (const c of this.c.values()) if (c.side === 'ally' && c.controller && !c.auto && c.alive && c.ready) return true;
    return false;
  }

  computeLayout() {
    const list = this.enemies().filter((c) => !(c.dead >= 2));
    // え の 大きさは res（こまかさ）で わって ほんとうの 大きさに
    const sprites = list.map((c) => {
      const frame = Math.floor(this.time / 420 + (c.slot || 0)) % 2;
      // 鏡のうつし身（パーティーの 人の 絵）・水のろう（中の 人）は battle-temple.js
      const img = templeSprite(c, frame) || gaiaSprite(c, frame) || noctoSprite(c, frame) || tokei6Sprite(c) || c7iSprite(c, frame) || monsterCanvas(c.species, frame);
      const r = img.res || 1;
      return { c, img, iw: img.width / r, ih: img.height / r };
    });
    let scale = 1;
    const totalW = () => sprites.reduce((s, x) => s + x.iw * scale + 6, 0);
    while (totalW() > BW - 12 && scale > 0.55) scale -= 0.05;
    let x = (BW - totalW()) / 2 + 3;
    const baseY = 124;
    return sprites.map(({ c, img, iw, ih }) => {
      const w = iw * scale, h = ih * scale;
      const out = { c, img, x, y: baseY - h, w, h };
      x += w + 6;
      return out;
    });
  }

  draw() {
    // 細かく 描いた ボスが いる 間は こまかさを 2ばいに（いなく なったら もどす。キャンバスの 大きさが かわるので さいしょに）
    this.fineRes();
    const x = this.ctx;
    x.imageSmoothingEnabled = false;
    const so = this.fx.shakeOffset;
    if (so.x || so.y) {
      x.fillStyle = '#000';
      x.fillRect(0, 0, this.canvas.width, this.canvas.height);
    }
    // なかみは BW×BH の まま、res ばい（ふつうは BRES）の こまかさで かく
    const R = this.res;
    // はいけいは こまかさに あわせて 1かいだけ 大きく しておく（まいかい のばすと おもい）
    if (!this.bgHi || this.bgHi.width !== BW * R) {
      this.bgHi = makeCanvas(BW * R, BH * R);
      const bx = ctxOf(this.bgHi);
      bx.drawImage(this.bg, 0, 0, BW * R, BH * R);
    }
    x.setTransform(1, 0, 0, 1, Math.round(so.x * R), Math.round(so.y * R));
    x.drawImage(this.bgHi, 0, 0);
    x.setTransform(R, 0, 0, R, so.x * R, so.y * R);
    const snap = (v) => Math.round(v * R) / R;
    this.layout = this.computeLayout();
    for (const m of this.layout) {
      const c = m.c;
      let dx = 0, dy = Math.round(Math.sin(this.time / 300 + (c.slot || 0)) * 1);
      if (c.flash > 0) dx = Math.round(Math.sin(c.flash / 20) * 2);
      const alpha = c.dead > 0 ? Math.max(0, 1 - (c.dead - 1)) : 1;
      if (c.dead > 0 && c.dead < 1.2 && !c.vanished && Math.floor(this.time / 60) % 2) continue;
      const base = c.appear > 0 ? 1 - c.appear : c.dead > 1 ? alpha : 1;
      x.globalAlpha = base;
      // まぼろしの 分身が いる 戦いの 本物: 足もとに 小さな 影（battle-ch4.js）
      if (c.shade && c.alive) drawShade(x, m, base);
      // 砂に もぐっている（ねらえない）: すがたの かわりに 砂の 山（砂が もり上がると 大きく ゆれる。battle-ch4.js）
      if (c.burrow && c.alive) {
        drawBurrow(x, m, this.time, c.burrow === 2, base);
        x.globalAlpha = 1;
        continue;
      }
      // がめんより こまかい え は なめらかに ちぢめる（ドットが ぬけないように）
      x.imageSmoothingEnabled = (m.img.res || 1) > x.getTransform().a * 1.01;
      x.imageSmoothingQuality = 'high';
      // ためこみ中の ボスは あかく ひかる（呪文を となえている ときは むらさき）
      if (c.telegraph && c.alive) {
        const pulse = 0.4 + Math.sin(this.time / 90) * 0.3;
        x.globalAlpha = pulse;
        x.drawImage(white(m.img, c.chant !== null && c.chant !== undefined ? '#b07aff' : '#ff3a3a'), snap(m.x + dx) - 2, snap(m.y + dy) - 2, m.w + 4, m.h + 4);
        x.globalAlpha = base;
      }
      // 反撃の構え: だいだいいろに ひかる（物理で こうげきすると 反撃される）
      if (c.stance && c.alive) {
        const pulse = 0.45 + Math.sin(this.time / 140) * 0.25;
        x.globalAlpha = pulse * base;
        x.drawImage(white(m.img, '#ffa22a'), snap(m.x + dx) - 2, snap(m.y + dy) - 2, m.w + 4, m.h + 4);
        x.globalAlpha = base;
      }
      // こうどうちゅうの すがた（とびこむ・ためる・はく など。あしもとを きじゅんに のびちぢみ）
      const P = c.act ? actPose(c.act) : null;
      const sx = P ? P.sx : 1, sy = P ? P.sy : 1;
      if (P) { dx += P.dx; dy += P.dy; }
      const w = m.w * sx, h = m.h * sy;
      const px = snap(m.x + m.w / 2 + dx - w / 2), py = snap(m.y + m.h + dy - h);
      if (P && P.aura && P.auraA > 0) {
        const r = Math.max(w, h) * 0.8;
        x.globalCompositeOperation = 'lighter';
        x.globalAlpha = P.auraA * 0.6 * base;
        x.drawImage(glowSprite(P.aura), px + w / 2 - r, py + h / 2 - r, r * 2, r * 2);
        x.globalCompositeOperation = 'source-over';
        x.globalAlpha = P.auraA * 0.8 * base;
        x.drawImage(white(m.img, P.aura), px - 1.5, py - 1.5, w + 3, h + 3);
      }
      if (P && P.ghost) {
        // ざんぞう
        for (const [lag, ga] of [[70, 0.18], [35, 0.3]]) {
          const G = actPose(c.act, c.act.age - lag);
          const gw = m.w * G.sx, gh = m.h * G.sy;
          x.globalAlpha = ga * base;
          x.drawImage(white(m.img, '#ffffff'), m.x + m.w / 2 + dx - P.dx + G.dx - gw / 2, m.y + m.h + dy - P.dy + G.dy - gh, gw, gh);
        }
      }
      x.globalAlpha = base;
      const img = c.flash > 0 && Math.floor(c.flash / 60) % 2 === 0 ? white(m.img) : m.img;
      x.drawImage(img, px, py, w, h);
      if (P && P.white > 0) {
        x.globalAlpha = P.white * base;
        x.drawImage(white(m.img), px, py, w, h);
      }
      // 水の衣・光（呪文を はね返す）・大波の 前ぶれ（battle-temple.js）
      templeDraw(this, x, m, c, px, py, w, h, base, white);
      // 見通しの目で 読んで いる 間、アルゴスの 3つの 目が 光る（battle-ch5.js）
      towerDraw(this, x, m, c, px, py, w, h, base);
      // まぼろしの 分身が 消える: むらさきに ゆらいで うすく なる
      if (c.vanished && c.dead > 0) {
        x.globalAlpha = 0.7 * base;
        x.drawImage(white(m.img, '#c8a0ff'), px + Math.sin(this.time / 40) * 1.5, py, w, h);
      }
      // ねらい（グループの ときは その グループ みんなに ▼。すこし しろく ひかる）
      const tg = this.targeting;
      const aimed = tg?.side === 'enemy' && c.alive && (tg.mode === 'group' ? !!this.hoverGroup && c.species === this.hoverGroup : this.hover === c.id);
      if (aimed) {
        x.globalAlpha = (0.16 + 0.12 * Math.sin(this.time / 110)) * base;
        x.drawImage(white(m.img), px, py, w, h);
      }
      x.imageSmoothingEnabled = false;
      x.globalAlpha = 1;
      if (aimed) {
        x.fillStyle = '#ffd66b';
        const ax = Math.round(m.x + m.w / 2);
        const ay = Math.round(m.y - 6 + Math.sin(this.time / 120) * 2);
        x.fillRect(ax - 3, ay - 3, 6, 2); x.fillRect(ax - 2, ay - 1, 4, 2); x.fillRect(ax - 1, ay + 1, 2, 2);
      }
      // 反撃の構えの しるし（頭の 上で ひらいた はさみ ＞＜ が ゆれる）
      if (c.stance && c.alive) {
        const sx0 = Math.round(m.x + m.w / 2), sy0 = Math.round(m.y - 4 + Math.sin(this.time / 160) * 1.5);
        const open = Math.floor(this.time / 280) % 2;
        x.fillStyle = '#2a1206';
        x.fillRect(sx0 - 9, sy0 - 5, 18, 10);
        x.fillStyle = '#ffb03a';
        for (const sgn of [-1, 1]) {
          // 左は ＞、右は ＜（まん中の 点が 内がわ）
          const bx = sx0 + sgn * (5 + open);
          x.fillRect(bx - 1, sy0 - 3, 2, 2); x.fillRect(bx - 1 - sgn * 2, sy0 - 1, 2, 2); x.fillRect(bx - 1, sy0 + 1, 2, 2);
        }
        x.fillStyle = '#ffe2a8';
        x.fillRect(sx0 - 1, sy0 - 1, 2, 2);
      }
      // よみがえりの呪文を となえている（ミイラの王アンク）: 頭の 上に「止める まで」の ゲージ。
      // ダメージが たまって 金色が いっぱいに なると とぎれる。まわりを 古い 文字の 光が まわる
      if (c.chant !== null && c.chant !== undefined && c.alive) {
        const gw = Math.min(48, Math.max(28, Math.round(m.w * 0.5)));
        const gx = Math.round(m.x + m.w / 2 - gw / 2), gy = Math.max(3, Math.round(m.y - 8));
        x.fillStyle = '#1a0a2a';
        x.fillRect(gx - 1, gy - 1, gw + 2, 5);
        x.fillStyle = '#5a2a9a';
        x.fillRect(gx, gy, gw, 3);
        x.fillStyle = Math.floor(this.time / 200) % 2 ? '#ffd66b' : '#fff0a8';
        x.fillRect(gx, gy, Math.round(gw * Math.min(1, c.chant)), 3);
        x.fillStyle = '#d8b8ff';
        for (let k = 0; k < 4; k++) {
          const ang = this.time / 260 + k * (Math.PI / 2);
          x.fillRect(Math.round(m.x + m.w / 2 + Math.cos(ang) * m.w * 0.42), Math.round(m.y + m.h * 0.35 + Math.sin(ang) * 7), 2, 2);
        }
      }
      // じょうたい いじょう
      if (c.alive && (c.status || []).includes('sleep') && Math.floor(this.time / 500) % 2) {
        x.fillStyle = '#ffffff';
        x.font = '8px monospace';
        x.fillText('Z', Math.round(m.x + m.w - 6), Math.round(m.y + 4));
      }
      if (c.alive && (c.status || []).includes('confuse')) {
        x.fillStyle = '#ffe066';
        const a = this.time / 150;
        x.fillRect(Math.round(m.x + m.w / 2 + Math.cos(a) * 8), Math.round(m.y - 2 + Math.sin(a) * 2), 2, 2);
      }
      // バフ・デバフ・じわじわ回復の 札（足もと。のこりの 行動の 回数。battle-buffs.js）
      drawEnemyMarks(x, m, c, BH - 1);
    }
    this.fx.draw(x);
    x.setTransform(1, 0, 0, 1, 0, 0);
  }

  // ───────────── おわり ─────────────
  // けっか（第31回）: ぜんぶの 行を 1画面に 出す。1回の タップ（クリック・Z/Enter/スペース・ゲームパッドA）で とじる（ui/result.js）
  //   レベルアップは 1人 1〜2行の まとめ。レベルアップの きょくは 1回だけ（勝利の きょくの あと）
  //   中みが まどに 入りきらない ときは、タップで 下へ スクロールしてから とじる
  showResult(msg) {
    return new Promise((resolve) => {
      this.closeMenus();
      const g = this.game;
      const au = g.audio;
      if (msg.outcome === 'win') au.play('victory', { force: true });
      else if (msg.outcome === 'lose') au.play('lose', { force: true });
      else au.stop(0.3);
      // ジングルの あとに たたかいの きょくに もどらない（とじたら フィールドの きょく）
      au.resumeTrack = null;
      const sheet = new ResultSheet(msg.lines || [], performance.now());
      if (!sheet.lines.length) return resolve();
      // うしろの まど（たたかいの メッセージ・コマンド）は からに して、けっかだけを 見せる
      this.cmdEl.innerHTML = '';
      this.msgEl.innerHTML = '';
      this.clearInfo();
      const list = el('div', { class: 'res-lines' });
      for (const r of sheet.rows) {
        if (r.grow) {
          // 「ユウ　Lv12→15！　HP+20　力+9」: 名前・上がった もの・強さ
          const row = el('div', { class: `res-${r.kind} res-grow ${r.kind === 'level' ? 'lvup' : ''}` },
            el('span', { class: 'rg-name', text: r.grow.name }),
            el('span', { class: 'rg-up', text: `${r.grow.ups}！` }));
          // 「回復+8」の とちゅうで おりかえさない
          if (r.grow.stats) row.append(el('span', { class: 'rg-st' }, ...r.grow.stats.split('　').map((t) => el('span', { text: t }))));
          list.append(row);
          continue;
        }
        const row = el('div', { class: `res-${r.kind}`, text: r.line });
        if (r.kind === 'job' || /^[★☆]/.test(r.line)) row.classList.add('gold');
        else if (r.kind === 'learn' || r.kind === 'item' || r.kind === 'found') row.classList.add('good');
        paintRare(row, r.line); // 落とした レア装備に 色と ★（ui/rarity.js）
        list.append(row);
      }
      const more = el('div', { class: 'res-more', text: '▼' });
      // 第61回: パーティーの 仲間は、リーダーが とじた 時に いっしょに とじる（自分では とじない。スクロールは できる）
      const follow = msg.followLeader ? el('div', { class: 'res-follow', text: `${msg.followLeader}が閉じると、いっしょに閉じます` }) : null;
      const box = el('div', { class: 'win b-result scroll' }, list, ...(follow ? [follow] : []), more);
      this.root.append(box);
      this.resultBox = box;
      // 音は 1回ずつ: レベルアップの きょく（勝利の きょくの あとに つづけて）・職業レベル・道具
      if (sheet.has('level') && msg.outcome === 'win') au.resumeTrack = 'levelup';
      else if (sheet.has('job')) au.sfx('key');
      if (sheet.has('item') || sheet.has('found')) setTimeout(() => au.sfx('item'), 250);
      for (const who of new Set(sheet.levelNames)) {
        const a = this.allies().find((x) => x.name === who);
        if (a) this.glowStatus(a.id, '#ffd66b');
      }
      let finished = false;
      const moreT = setTimeout(() => { if (!finished) more.classList.add('on'); }, sheet.waitLeft(performance.now()));
      const advance = () => {
        if (finished || sheet.waitLeft(performance.now()) > 0) return;
        // 入りきらない ときは まず 下へ（さいごまで 見てから とじる）
        if (box.scrollTop + box.clientHeight < box.scrollHeight - 4) {
          box.scrollTop += Math.max(40, box.clientHeight * 0.8);
          return;
        }
        // リーダーを まつ（リーダーが 切れた 時の ために、しばらく たったら 自分でも とじられる）
        if (follow && !leaderGone && performance.now() < followUntil) return;
        if (sheet.tap(performance.now())?.close) finish();
      };
      const followUntil = performance.now() + FOLLOW_MAX_MS;
      let leaderGone = false;
      if (follow) {
        const onLeader = () => {
          leaderGone = true;
          // まどが 出た すぐ あとなら、少しだけ 見せてから とじる
          setTimeout(() => finish(), Math.max(0, sheet.readyAt + FOLLOW_SHOW_MS - performance.now()));
        };
        if (this.leaderClosed) onLeader();
        else this.onLeaderClose = onLeader;
      }
      const h = { el: box, onNav: (a) => { if (a === 'a' || a === 'b') advance(); } };
      // がめんの どこを さわっても すすむ
      const onTap = (e) => {
        e.preventDefault();
        advance();
      };
      this.root.addEventListener('click', onTap);
      g.input.push(h);
      const finish = () => {
        if (finished) return;
        finished = true;
        clearTimeout(moreT);
        // とじた あとに レベルアップの きょくが ならない ように
        if (au.resumeTrack === 'levelup') au.resumeTrack = null;
        g.input.pop(h);
        this.root.removeEventListener('click', onTap);
        this.closeResult = null;
        this.onLeaderClose = null;
        resolve();
      };
      // 画面が こわされた（つぎの たたかいが はじまった など）ときも とじる
      this.closeResult = finish;
    });
  }

  // 第61回: リーダーが けっかの まどを とじた（game.js の 'resultClose'）。まだ まどが 出ていなければ 出た 時に とじる
  leaderClose() {
    this.leaderClosed = true;
    this.onLeaderClose?.();
  }

  destroy() {
    this.destroyed = true;
    this.game.sceneAudio?.battleEnd();
    this.unbindPad?.();
    this.closeTactics();
    this.closeResult?.();
    this.closeMenus();
    removeEventListener('resize', this.onResize);
    document.fonts?.removeEventListener?.('loadingdone', this.onFonts);
    this.ro?.disconnect();
    this.root.innerHTML = '';
    this.root.hidden = true;
  }
}

js/client/cloudsave.js:
// クラウドセーブ（claude.ai の アーティファクトで ひとりで 遊ぶ とき）
//
// iPhone の Safari や Claude アプリでは、アーティファクトの 中の ブラウザの ほぞん（localStorage）が
// ブラウザを とじると 消えることが ある。そこで claude.ai の、1人ずつの ひみつの 場所
// （db の data/users/<id>/。持ち主にも 見えない）にも セーブする。
//   data/users/<id>/meta    … { v, createdAt, board, deleted: { キャラID: 消した 時こく }, updatedAt }
//   data/users/<id>/c-<ID>  … { v, savedAt, char }  キャラ 1人 = 1つの 文書（1つ 256KB まで）
// このブラウザと クラウドの 両方に いる キャラは、あとで セーブした ほうを つかう。
import { SAVE_VERSION, upgradeSave } from '../shared/world/save.js';

const OPEN_TIMEOUT = 9000;
const LOAD_TIMEOUT = 15000;
export const WRITE_GAP = 10000; // 1つの 文書に 書く あいだ（ms）
export const MOVE_GAP = 60000; // いちが かわった だけの ときは ゆっくり
const DEBOUNCE = 1500;
const URGENT_DEBOUNCE = 300;
const DOC_PREFIX = 'c-';
const TOMBSTONES_MAX = 200;

// キャラの「さいごに セーブした 時こく」
export const charTime = (c) => Math.max(Number(c?.savedAt) || 0, Number(c?.lastPlayed) || 0);

const clone = (v) => JSON.parse(JSON.stringify(v));

function withTimeout(p, ms) {
  let t;
  const late = new Promise((_, rej) => {
    t = setTimeout(() => rej({ code: 'timeout' }), ms);
  });
  return Promise.race([p, late]).finally(() => clearTimeout(t));
}

// claude.ai の 中なら db と user を つかう。つかえない ときは null（このブラウザだけに セーブ）
//  onWait … 「クラウドセーブを つかって いい？」の 確認を まっている あいだ
export async function openCloud(claude = globalThis.window?.claude, { onWait } = {}) {
  if (!claude || typeof claude.use !== 'function') return null;
  try {
    const [db, user, perms] = await withTimeout(Promise.all([claude.use('db'), claude.use('user'), claude.use('permissions')]), OPEN_TIMEOUT);
    if (!db || !user) return null;
    if (perms) {
      const st = await perms.state();
      // つかえない・ことわられた（ない 名前は つかえない あつかい）
      if (!st.db || st.db === 'denied' || st.db === 'unavailable') return null;
      const ask = ['db', 'user'].filter((n) => st[n] === 'prompt');
      if (ask.length) {
        onWait?.();
        const got = await perms.request(ask);
        if (got.db !== 'granted') return null;
      }
    }
    const uid = await withTimeout(user.id(), OPEN_TIMEOUT);
    if (!uid) return null;
    return new CloudSave(db, uid);
  } catch {
    return null;
  }
}

export class CloudSave {
  constructor(db, uid, { now = () => Date.now(), timers = globalThis } = {}) {
    this.db = db;
    this.uid = uid;
    this.now = now;
    this.timers = timers;
    this.col = db.collection(`data/users/${uid}`);
    this.cloudTimes = new Map(); // キャラID → クラウドに ある ぶんの 時こく
    this.dirty = new Map(); // 文書ID → 書く 予定の 時こく
    this.lastWrite = new Map(); // 文書ID → さいごに 書いた 時こく
    this.remove = new Set(); // 消す 文書ID
    this.deleted = {}; // キャラID → 消した 時こく
    this.remoteMeta = ''; // クラウドに ある meta（かわっていなければ 書かない）
    // on … セーブできる / error … しっぱいが つづいている / readonly … 見るだけの 共有などで 書けない / off … つかえない
    this.state = 'on';
    this.failures = 0;
    this.listeners = new Set();
    this.source = null; // () => いまの セーブ（world.data）
    this.timer = null;
    this.writing = null;
  }

  onChange(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  setState(s) {
    if (this.state === s) return;
    this.state = s;
    if (this.stopped) {
      this.dirty.clear();
      if (this.timer) {
        this.timers.clearTimeout(this.timer);
        this.timer = null;
      }
    }
    for (const fn of this.listeners) {
      try {
        fn(s);
      } catch { /* */ }
    }
  }

  // クラウドの セーブを 読む → { characters, board, createdAt, deleted }
  async load() {
    const snap = await withTimeout(this.col.get(), LOAD_TIMEOUT);
    const out = { characters: {}, board: [], createdAt: 0, deleted: {} };
    for (const d of snap.docs) {
      if (!d.exists) continue;
      const body = clone(d.data() || {});
      if (d.id === 'meta') {
        out.board = Array.isArray(body.board) ? body.board : [];
        out.createdAt = Number(body.createdAt) || 0;
        out.deleted = body.deleted && typeof body.deleted === 'object' ? body.deleted : {};
      } else if (d.id.startsWith(DOC_PREFIX) && body.char && typeof body.char === 'object' && typeof body.char.id === 'string') {
        const up = upgradeSave({ version: Number(body.v) || SAVE_VERSION, characters: { [body.char.id]: body.char } }).data.characters[body.char.id];
        if (!up) continue;
        up.savedAt = Math.max(Number(body.savedAt) || 0, Number(up.savedAt) || 0);
        out.characters[up.id] = up;
        this.cloudTimes.set(up.id, charTime(up));
      }
    }
    this.deleted = { ...out.deleted };
    this.remoteMeta = metaSig(out);
    return out;
  }

  get stopped() {
    return this.state === 'off' || this.state === 'readonly';
  }

  // 読みこんだ あとで: このブラウザの ほうが 新しい キャラ・クラウドに ない キャラを 書く
  prime(data) {
    for (const [id, t] of Object.entries(data.deleted || {})) this.deleted[id] = Math.max(t, this.deleted[id] || 0);
    for (const c of Object.values(data.characters || {})) {
      const t = this.cloudTimes.get(c.id);
      if (t === undefined || charTime(c) > t) this.mark(DOC_PREFIX + c.id, 0);
    }
    for (const id of this.cloudTimes.keys()) if (!data.characters?.[id]) this.markRemove(id);
    if (metaSig({ ...data, deleted: this.deleted }) !== this.remoteMeta) this.mark('meta', 0);
  }

  // セーブ（このブラウザ）の たびに よばれる
  //  urgent … 宿屋・教会・終わる など。間を あけずに すぐ 書く
  noteChanges({ changes = [], gone = [], boardChanged = false, urgent = false } = {}) {
    if (this.stopped) return;
    for (const ch of changes) {
      if (urgent) this.mark(DOC_PREFIX + ch.id, 0, URGENT_DEBOUNCE);
      else this.mark(DOC_PREFIX + ch.id, ch.posOnly ? MOVE_GAP : WRITE_GAP);
    }
    for (const id of gone) {
      this.deleted[id] = this.now();
      this.markRemove(id);
    }
    if (gone.length || boardChanged) this.mark('meta', urgent ? 0 : WRITE_GAP);
  }

  markRemove(id) {
    this.remove.add(DOC_PREFIX + id);
    this.mark(DOC_PREFIX + id, 0);
    this.mark('meta', 0);
  }

  mark(docId, gap, debounce = DEBOUNCE) {
    const now = this.now();
    const due = Math.max(now + debounce, (this.lastWrite.get(docId) || 0) + gap);
    const cur = this.dirty.get(docId);
    this.dirty.set(docId, cur === undefined ? due : Math.min(cur, due));
    this.arm();
  }

  arm() {
    if (this.stopped) {
      // もう 書かない（のこりも すてる。タイマーを 回しつづけない）
      this.dirty.clear();
      return;
    }
    if (this.writing || !this.dirty.size || !this.source) return;
    const next = Math.min(...this.dirty.values());
    if (this.timer) this.timers.clearTimeout(this.timer);
    this.timer = this.timers.setTimeout(() => {
      this.timer = null;
      this.flush(false);
    }, Math.max(0, next - this.now()));
  }

  pendingCount() {
    return this.dirty.size;
  }

  // all = true … ページを とじる とき など、待たずに 全部 書く
  async flush(all = true) {
    if (this.writing) {
      await this.writing;
      if (!all || !this.dirty.size) return;
    }
    if (this.timer) {
      this.timers.clearTimeout(this.timer);
      this.timer = null;
    }
    this.writing = this.writeDue(all);
    try {
      await this.writing;
    } finally {
      this.writing = null;
      this.arm();
    }
  }

  async writeDue(all) {
    const data = this.source?.();
    if (!data || this.stopped) return;
    const now = this.now();
    const ids = [...this.dirty].filter(([, due]) => all || due <= now).map(([id]) => id);
    // キャラを 先に、meta を あとに
    ids.sort((a, b) => (a === 'meta') - (b === 'meta'));
    for (const id of ids) {
      if (this.stopped) return;
      this.dirty.delete(id);
      try {
        await this.writeDoc(id, data);
        this.lastWrite.set(id, this.now());
        this.failures = 0;
        if (this.state !== 'readonly') this.setState('on');
      } catch (e) {
        this.onWriteError(id, e);
      }
    }
  }

  async writeDoc(id, data) {
    const ref = this.col.doc(id);
    if (id === 'meta') {
      const deleted = Object.entries(this.deleted).sort((a, b) => b[1] - a[1]).slice(0, TOMBSTONES_MAX);
      this.deleted = Object.fromEntries(deleted);
      const body = { v: SAVE_VERSION, createdAt: data.createdAt || this.now(), board: (data.board || []).slice(0, 40), deleted: this.deleted, updatedAt: this.now() };
      await withTimeout(ref.set(clone(body)), LOAD_TIMEOUT);
      this.remoteMeta = metaSig(body);
      return;
    }
    const charId = id.slice(DOC_PREFIX.length);
    const c = data.characters?.[charId];
    if (!c) {
      if (this.remove.has(id)) {
        await withTimeout(ref.delete(), LOAD_TIMEOUT);
        this.remove.delete(id);
        this.cloudTimes.delete(charId);
      }
      return;
    }
    this.remove.delete(id);
    await withTimeout(ref.set(clone({ v: SAVE_VERSION, savedAt: charTime(c), char: c })), LOAD_TIMEOUT);
    this.cloudTimes.set(charId, charTime(c));
  }

  onWriteError(id, e) {
    const code = e?.code || 'unavailable';
    if (['not_granted', 'revoked', 'capability_disabled', 'capability_removed'].includes(code)) {
      this.setState('off');
      return;
    }
    if (code === 'invalid_argument' || code === 'transform_error') {
      // 自分の 場所に 書けない（見るだけの 人）・大きすぎる など。もう 書かない
      this.setState('readonly');
      return;
    }
    // quota_exceeded・resource_exhausted・unavailable・timeout … しばらく まって もう いちど
    this.failures++;
    if (this.failures >= 3) this.setState('error');
    const wait = code === 'resource_exhausted' ? 30000 : 5000 * Math.min(this.failures, 6);
    const due = this.now() + wait;
    const cur = this.dirty.get(id);
    this.dirty.set(id, cur === undefined ? due : Math.max(cur, due));
  }
}

function metaSig(m) {
  return JSON.stringify([m.createdAt || 0, (m.board || []).slice(0, 40), Object.entries(m.deleted || {}).sort()]);
}

// クラウドの セーブを いまの せかいに まぜる（遊んでいる キャラは そのまま）
//  もどりち: かわったか
export function adoptCloud(world, remote) {
  const data = world.data;
  const online = (id) => [...world.sessions.values()].some((x) => x.inWorld && x.charId === id);
  const localDeleted = data.deleted || {};
  let changed = false;
  // 別の 場所で 消した キャラ
  for (const [id, t] of Object.entries(remote.deleted || {})) {
    const mine = data.characters[id];
    if (mine && !online(id) && charTime(mine) <= t) {
      delete data.characters[id];
      changed = true;
    }
  }
  for (const c of Object.values(remote.characters || {})) {
    if ((localDeleted[c.id] || 0) >= charTime(c)) continue; // このブラウザで 消した あとの もの
    const mine = data.characters[c.id];
    if (!mine || (!online(c.id) && charTime(c) > charTime(mine))) {
      data.characters[c.id] = c;
      changed = true;
    }
  }
  data.deleted = { ...localDeleted };
  for (const [id, t] of Object.entries(remote.deleted || {})) data.deleted[id] = Math.max(Number(t) || 0, localDeleted[id] || 0);
  const board = new Map((data.board || []).map((b) => [`${b.from}|${b.time}|${b.text}`, b]));
  const before = board.size;
  for (const b of remote.board || []) board.set(`${b.from}|${b.time}|${b.text}`, b);
  if (board.size !== before) {
    data.board = [...board.values()].sort((a, b) => (b.time || 0) - (a.time || 0)).slice(0, 40);
    changed = true;
  }
  if (remote.createdAt && (!data.createdAt || remote.createdAt < data.createdAt)) data.createdAt = remote.createdAt;
  return changed;
}

