// 家族サーバーに つながらない ときに、どこで 止まっているかを しらべる（public/sw.js と おなじ 考え方）
// ・通信エラー … 家の PC まで とどいていない（PC の 電源・スリープ・Tailscale）。家の Wi-Fi の http では 見分けられない
// ・502〜504 … 家の PC（Tailscale Funnel）には とどいたが、家族サーバー（黒い 画面）が 動いていない
//   （家族サーバーは この 番号を 返さない。Tailscale が「うしろの サーバーに つながらない」ときに 返す）
// ・200 … 家族サーバーは 動いている（つなぎなおせば よい）

// もどりち: 'pc' | 'server' | 'up' | 'unknown'
export async function downReason({ fetchImpl = globalThis.fetch, loc = globalThis.location, timeoutMs = 4000 } = {}) {
  const outside = /^https:$/.test(loc?.protocol || '') && !/^(localhost|127\.|\[::1\])/.test(loc?.hostname || '');
  try {
    const ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const t = ctrl ? setTimeout(() => ctrl.abort(), timeoutMs) : null;
    const r = await fetchImpl('api/info', { cache: 'no-store', signal: ctrl?.signal });
    if (t) clearTimeout(t);
    if (r.status >= 502 && r.status <= 504) return 'server';
    return r.ok ? 'up' : 'unknown';
  } catch {
    return outside ? 'pc' : 'unknown';
  }
}

// 画面に 出す 文（さいごの「ひとりで遊ぶサイト」の 文は 出す がわで つける）
export const DOWN_TEXT = {
  pc: '家のPCまで、通信がとどいていません。\n・PCの電源が入っているか、スリープしていないか\n・PCの Tailscale がつながっているか（外からは、このスマホで login.tailscale.com を開くと、PCが「Connected」か見られます）\n・開いているアドレスが、家族サーバーの黒い画面の「★外出先から」のアドレスと同じか（PCの名前を変えると、アドレスも変わります）',
  server: '家のPCにはつながりましたが、家族サーバー（黒い画面）が動いていません。\n・黒い画面が「続行するには…」で止まった時は、閉じて start.bat をもう一度開く\n・黒い画面がない時は、start.bat を開く',
  up: '家族サーバーは動いています。「もう一度つなぐ」をおしてね。',
  unknown: '家のPCの電源と、家族サーバー（黒い画面）が動いているか確かめてください。\n・黒い画面が「続行するには…」で止まった時は、閉じて start.bat をもう一度開く\n・PCがスリープしていないか\n・外出先からの時は、PCの Tailscale がつながっているかも見る',
};

js/client/errlog.js:
// ふぐあいの きろく（うごけなく なった・画面が とまった ときに 原因を さがす ため）
// ・この 端末に さいきんの 20こ（localStorage）。メニューの「設定」→「不具合の記録」で 見て コピーできる
// ・つながっている サーバーにも おくる（家族サーバーの 画面と セーブの errorLog に のこる）
const KEY = 'kizuna_errlog';
const seen = new Set();

export function readErrLog() {
  try {
    const v = JSON.parse(localStorage.getItem(KEY) || '[]');
    return Array.isArray(v) ? v : [];
  } catch {
    return [];
  }
}

function writeErrLog(list) {
  try { localStorage.setItem(KEY, JSON.stringify(list.slice(-20))); } catch { /* */ }
}

export function clearErrLog() {
  writeErrLog([]);
}

// where … どこで おきたか（'script:say'・'frame'・'stuck:busy' など）
export function reportError(game, e, where = '') {
  try {
    const msg = String(e?.message || e || '').slice(0, 300);
    // よその サイトの スクリプトの エラーは 中みが ないので のこさない
    if (!msg || msg === 'Script error.') return;
    // おなじ ものは 1回だけ（まいフレーム おきる エラーで いっぱいに しない）
    const key = `${where}|${msg}`;
    if (seen.has(key) || seen.size > 30) return;
    seen.add(key);
    console.error('[kizuna]', where, e);
    const rec = {
      at: Date.now(),
      where: String(where).slice(0, 40),
      msg,
      stack: String(e?.stack || '').split('\n').slice(0, 6).join('\n').slice(0, 900),
      map: game?.field?.mapId || '',
      state: game?.state || '',
      who: game?.me?.name || '',
    };
    writeErrLog([...readErrLog(), rec]);
    if (game?.me) game.net?.send?.({ t: 'clientError', ...rec });
  } catch { /* きろくの しっぱいで あそびを とめない */ }
}

// コピー用の 文（家族に LINE で おくる など）
export function errLogText(list = readErrLog()) {
  if (!list.length) return '';
  return list.map((r) => {
    const d = new Date(r.at);
    const t = `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
    return `[${t}] ${r.who || '?'} ${r.map || ''} ${r.state || ''} ${r.where}\n${r.msg}${r.stack ? `\n${r.stack}` : ''}`;
  }).join('\n\n');
}

