// 第64回 ⑥a: 赤く した 魔物の え（もとの え → 赤い え）
const huntTints = new WeakMap();

const SPEED = 4.6; // マス/びょう
const RUN = 1.35; // はしると この ばい（はやすぎない ように）
const SHIP = 1.25; // 船は すこし はやい
const ICE_SPEED = 7.2; // 氷の 上を すべる はやさ（マス/びょう）
const CART_SPEED = 7.5; // トロッコの はやさ（マス/びょう）
const FLOW_SPEED = 4.2; // 流れる 砂に 流される はやさ（マス/びょう。行き先が 目で おえる ように 歩くより ゆっくり）
// がめんの こまかさ（せかいの 1ドットを なんドットで かくか）
// 人・モンスターの え は res 4 なので、2D では がめんも 4ばいに する（がめんが おおきすぎる とき・2.5D の ときは 2）
const RES_LO = 2, RES_HI = 4;
const RES_HI_MAX_PX = 2.4e6; // これより おおきい がめんは 4ばいに しない（おそく なるので）

const spriteCache = new Map();
function charSprite(key, opts, dir, frame) {
  const k = `${key}|${dir}|${frame}`;
  let c = spriteCache.get(k);
  if (!c) {
    c = paintHuman(dir, frame, opts).toCanvas();
    spriteCache.set(k, c);
  }
  return c;
}
function specialSprite(kind, dir, frame) {
  const k = `sp:${kind}|${dir}|${frame}`;
  if (spriteCache.has(k)) return spriteCache.get(k);
  const p = paintSpecial(kind, dir, frame);
  const c = p ? p.toCanvas() : null;
  spriteCache.set(k, c);
  return c;
}
// 船（水の 上に いる ときの すがた。みぎむきは はんてん）
// kind … マップの 船（map.ship。第4章の 砂の海は 砂の船「すなかぜ号」'sand_ship'）
export function shipSprite(dir, frame, kind = null) {
  const k = `ship|${kind || ''}|${dir}|${frame}`;
  if (spriteCache.has(k)) return spriteCache.get(k);
  const paint = kind === 'sand_ship' ? paintSandShip : paintShip;
  let c = paint(dir === 'right' ? 'left' : dir, frame).toCanvas();
  if (dir === 'right') c = flipCanvas(c);
  spriteCache.set(k, c);
  return c;
}

// 夜に 光る もの（町の あかり・だんろ・さいだん・家の 入り口から もれる 光）と その 大きさ
const NIGHT_GLOW = { [T.LAMP]: 1, [T.FIREPLACE]: 1, [T.STAR_ALTAR]: 1, [T.DOOR]: 0.55 };

// 2.5D の 船は 水に すこし しずめる（かげ なし）
const SHIP3D = { lift: -0.26, shadow: false };
// 砂の船（すなかぜ号）の NPC は さんばしの はしの マス。え は その 先の 砂の 海に かく
const SAND_SHIP_DY = 0.85;

// 空を とぶ モンスター（フィールドで ふわふわ うかぶ）
const isFlying = (sp) => !!MONSTERS[sp]?.flying;

// 大きな NPC（ボス・たてもの）の 大きさ（'mon:<id>' は え の npc の あたい も つかう。render/monsters.js の bigNpcScale）
const BIG_SCALE = { goldoon_sleep: 0.6, lighthouse_dark: 1, lighthouse_lit: 1, storm_tower: 1 };
const bigScale = (sprite) => BIG_SCALE[sprite] || bigNpcScale(sprite) || 0.5;

// eq: そうび（'ぶき,よろい,たて,あたま' か { weapon, armor, … }）。ないときは しょくぎょうの はじめの そうび
// 人（プレイヤー・なかま）は render/hero.js で こまかく かく。res 4: フィールド / res 8: 大きな みほん
export function playerSprite(look, job, dir, frame, eq, res = 4) {
  const ek = equipKey(eq, job);
  const ck = `h:${heroLookKey(look)}:${job}:${ek}|${dir}|${frame}|${res}`;
  let c = spriteCache.get(ck);
  if (!c) {
    c = heroCanvas(look, job, ek, dir, frame, res);
    spriteCache.set(ck, c);
  }
  return c;
}

// なかま（モンスターは ちいさい モンスターの え。みぎむきは はんてん）
// 大きな 魔物（ヴァルドラゴン など）も、ついてくる ときは 主人公を かくさない ように 24ドットまで
const monFlip = new WeakMap();
const FOLLOW_MAX = 24;
// 通った 道（o.trail。新しい ほうが 先）を、今の いち（o.x, o.y）から want マス もどった ところ（点の 間は なめらかに）
export function trailAt(o, want) {
  let acc = 0;
  let prev = { x: o.x, y: o.y, dir: o.dir };
  for (const p of o.trail) {
    const seg = Math.hypot(p.x - prev.x, p.y - prev.y);
    if (acc + seg >= want) {
      const k = seg > 1e-6 ? (want - acc) / seg : 1;
      return { x: prev.x + (p.x - prev.x) * k, y: prev.y + (p.y - prev.y) * k, dir: p.dir };
    }
    acc += seg;
    prev = p;
  }
  return o.trail.length ? o.trail[o.trail.length - 1] : { x: o.x, y: o.y, dir: o.dir };
}

export function followerSprite(f, dir, frame) {
  if (f.mon) {
    const c = monsterCanvas(f.mon, frame, FOLLOW_MAX);
    if (dir !== 'right') return c;
    let fc = monFlip.get(c);
    if (!fc) { fc = flipCanvas(c); monFlip.set(c, fc); }
    return fc;
  }
  return playerSprite(f.look, f.job, dir, frame, f.eq);
}

// メニューなどに だす かお（えの データURL）
const faceCache = new Map();
export function faceURL(f) {
  const k = f.mon ? `m:${f.mon}` : `h:${heroLookKey(f.look)}:${f.job}:${equipKey(f.eq, f.job)}`;
  let u = faceCache.get(k);
  if (!u) {
    const c = followerSprite(f, 'down', 0);
    try { u = c.toDataURL(); } catch { u = ''; }
    faceCache.set(k, u);
  }
  return u;
}
export function npcSprite(kind, dir, frame) {
  // 大鳥・夜の 人（render/sky-art.js）
  const sky = skyNpcSprite(kind, dir, frame);
  if (sky) return sky;
  // 魔物の すがたの 人（'mon:ID'。ペンギン騎士 など。第3章）
  if (kind.startsWith('mon:')) {
    const c = monsterCanvas(kind.slice(4), frame, true);
    if (dir !== 'right') return c;
    let fc = monFlip.get(c);
    if (!fc) { fc = flipCanvas(c); monFlip.set(c, fc); }
    return fc;
  }
  const o = npcOpts(kind);
  if (o) return charSprite(`n:${kind}`, o, dir, frame);
  return specialSprite(kind, dir, frame);
}

const ROOF = {
  red: ['#b8403a', '#8a2a26', '#d8605a'], blue: ['#3a64b0', '#264a8a', '#5a84d0'], green: ['#3a8a4a', '#276a36', '#5aaa6a'],
  purple: ['#6a4a9a', '#4e3478', '#8a6aba'], white: ['#d8d4e8', '#aaa6c0', '#f4f2ff'], orange: ['#d0782e', '#a45a1e', '#ec9a4e'],
  teal: ['#2a8a8a', '#1e6a6a', '#4aaaaa'], brown: ['#8a5a32', '#6a4222', '#aa7a4e'], pink: ['#d06a9a', '#aa4a7a', '#ec8aba'],
  // 第3章: 雪の つもった やね・鉱山の 町の 石の やね
  snow: ['#e4ecf8', '#a8b4c8', '#ffffff'], snowred: ['#b8403a', '#8a2a26', '#f4f8ff'], snowblue: ['#3a64b0', '#264a8a', '#f4f8ff'],
  snowgreen: ['#3a7a5a', '#26583e', '#f4f8ff'], slate: ['#5a6078', '#3a3e52', '#8a90b0'], rust: ['#9a5a3a', '#6a3a22', '#c88a5a'],
  // 第4章: 砂の国（日干しれんがの 白っぽい やね・赤い かわらの やね・布の やね）
  sand: ['#d8b47a', '#a8844a', '#f0d6a2'], clay: ['#c8703a', '#9a4e22', '#e8986a'], canvas: ['#e8dcc4', '#bba98a', '#fff4e0'],
};

export class Field {
  constructor(game) {
    this.game = game;
    this.canvas = document.getElementById('field');
    this.ctx = ctxOf(this.canvas);
    this.labelsEl = document.getElementById('labels');
    this.me = { x: 0, y: 0, dir: 'down', moving: false, trail: [], anim: 0 };
    this.others = new Map();
    this.syms = new Map();
    // フィールドに ランダムに 出る 宝箱（サーバーの snap の fc）
    this.fchests = [];
    this.actors = new Map();
    this.npcState = new Map();
    this.labels = new Map();
    this.bubbles = [];
    this.explored = {};
    this.exploredDirty = false;
    this.nightOverride = null;
    this.shakeT = 0;
    this.moveTimer = 0;
    this.lastSent = { x: 0, y: 0 };
    this.touchCooldown = new Map();
    this.hideGuests = false;
    this.scriptHidden = new Set(); // イベント中に けした NPC（マップを かえると もどる）
    this.leaderCrumbs = [];
    this.darkCanvas = makeCanvas(64, 64);
    this.roofCache = new Map();
    this.time = 0;
    this.r3d = null;
    this.view = '2d';
    // 氷の 上を すべっている（{ dx, dy, tx, ty }）・トロッコに のっている
    this.slide = null;
    this.riding = null;
    // 流れる 砂に 流されている（{ tx, ty }。第4章の ピラミッド 3階）
    this.flow = null;
    this.hideMe = false;
    // 雪・ふぶき・火の粉（render/weather.js）
    this.weather = new Weather();
    addEventListener('resize', () => this.resize());
    this.resize();
  }

  // ───────────── 2D / 2.5D ─────────────
  static webgl2() {
    try {
      const c = document.createElement('canvas');
      return !!(window.WebGL2RenderingContext && c.getContext('webgl2'));
    } catch {
      return false;
    }
  }

  savedView() {
    let v = null;
    try { v = localStorage.getItem('kizuna_view'); } catch { /* */ }
    if (v === '2d') return '2d';
    return Field.webgl2() ? '3d' : '2d';
  }

  async setView(mode, save = false) {
    if (save) { try { localStorage.setItem('kizuna_view', mode); } catch { /* */ } }
    const cv = document.getElementById('field3d');
    if (mode === '3d' && Field.webgl2() && cv) {
      if (!this.r3d) {
        try {
          const { Field3D } = await import('./render/field3d.js');
          this.r3d = new Field3D(this, cv);
        } catch (e) {
          console.warn('2.5Dにできませんでした', e);
          this.r3d = null;
          mode = '2d';
        }
      }
    } else mode = '2d';
    if (mode === '2d' && this.r3d) {
      this.r3d.dispose();
      this.r3d = null;
    }
    this.view = mode;
    this.resize();
    if (cv) cv.hidden = mode !== '3d';
    document.body.classList.toggle('view3d', mode === '3d');
    return mode;
  }

  resize() {
    const w = innerWidth, h = innerHeight;
    const minDim = Math.min(w, h);
    this.scale = Math.max(2, Math.floor(minDim / (16 * 13)));
    if (Math.min(w, h) / this.scale < 16 * 9) this.scale = Math.max(1, this.scale - 1);
    this.vw = Math.ceil(w / this.scale);
    this.vh = Math.ceil(h / this.scale);
    // 人の ドット絵が こまかい（res 4）ので、がめんも こまかく かく。ざひょうは これまでと おなじ
    // （2.5D の ときは うえに かさねる しるし だけ なので 2 で よい）
    const dpr = window.devicePixelRatio || 1;
    const hi = this.view !== '3d' && !this.resCap && this.scale * dpr >= 3 && this.vw * this.vh * RES_HI * RES_HI <= RES_HI_MAX_PX;
    this.res = hi ? RES_HI : RES_LO;
    this.canvas.width = this.vw * this.res;
    this.canvas.height = this.vh * this.res;
    this.ctx = ctxOf(this.canvas);
    this.ctx.setTransform(this.res, 0, 0, this.res, 0, 0);
    this.darkCanvas.width = this.vw;
    this.darkCanvas.height = this.vh;
  }

  // ───────────── マップ ─────────────
  setMap(mapId, x, y, dir) {
    const changed = this.mapId !== mapId;
    syncTreasureGates(this.game); // 見つけた 宝の地図の 穴
    this.mapId = mapId;
    this.map = MAPS[mapId];
    prepareMap(this.map);
    this.me.x = x;
    this.me.y = y;
    this.me.dir = dir || this.me.dir;
    this.me.trail = [];
    this.leaderCrumbs = [];
    this.slide = null;
    this.flow = null;
    if (changed) {
      this.scriptHidden.clear();
      this.syms.clear();
      this.fchests = [];
      this.others.clear();
      this.npcState.clear();
      this.actors.clear();
      for (const n of this.map.npcs) this.npcState.set(n.id, { x: n.x + 0.5, y: n.y + 0.5, dir: n.dir, t: Math.random() * 2000, hx: n.x + 0.5, hy: n.y + 0.5, moving: false });
      this.loadExplored();
    }
    this.lastArea = null;
    this.snapCamera();
  }

  snapCamera() {
    this.cam = this.targetCam();
  }

  targetCam() {
    const mw = this.map.w * TS, mh = this.map.h * TS;
    // だいほんの ['look', x, y] の 間は その 場所を 見る
    const at = this.lookAt || this.me;
    let cx = at.x * TS - this.vw / 2;
    let cy = (at.y - 0.5) * TS - this.vh / 2;
    if (mw > this.vw) cx = Math.max(0, Math.min(mw - this.vw, cx)); else cx = (mw - this.vw) / 2;
    if (mh > this.vh) cy = Math.max(0, Math.min(mh - this.vh, cy)); else cy = (mh - this.vh) / 2;
    return { x: cx, y: cy };
  }

  // 世界の フラグ（人の いち・橋・とびら など）。さそわれて 手伝っている ときは リーダーの ものがたりの 世界
  hasFlag(f) {
    // 夜の あいだ（夜だけ 出る 人・夜は 家に 帰る 人）・お日さまの むき（'@noon' など。第4章の オベリスクの 影）
    if (f[0] === '@') return this.game.sky ? timeFlag(f, this.game.sky.frac()) : false;
    const world = this.game.worldFlagSet;
    if (world && this.game.visitingLeader()) return world.has(f);
    const c = this.game.me;
    return !!c?.flags?.[f];
  }

  gateFlag(f) {
    return this.hasFlag(f);
  }

  npcVisible(n) {
    if (this.scriptHidden.has(n.id)) return false;
    if (!condOk(n.show, (f) => this.hasFlag(f))) return false;
    if (n.id === 'star_stone') return !this.hasFlag('p_attack') || this.hasFlag('c1_clear');
    return true;
  }

  // ───────────── あたり判定 ─────────────
  // pass: この 人たちは とおれる（いま 体が 重なっている 人から はなれる とき）
  solidAt(tx, ty, forNpc = null, pass = null) {
    if (isBlocked(this.map, tx, ty, (f) => this.gateFlag(f))) return true;
    const key = ty * this.map.w + tx;
    const ch = this.map.chestAt.get(key);
    if (ch && condOk(ch.show, (f) => this.hasFlag(f)) && !this.chestGone(ch)) return true;
    for (const n of this.map.npcs) {
      if (!n.solid || n === forNpc || pass?.has(n) || !this.npcVisible(n)) continue;
      const s = this.npcState.get(n.id);
      if (s && npcCovers(n, s.x, s.y, tx, ty)) return true;
    }
    return false;
  }

  // 自分の 体が (x, y) に 入れるか
  boxFree(x, y) {
    if (this.followAuto && this.warpBlocks(x, y)) return false;
    const pass = this.leavingNpcs(x, y);
    const under = this.stuckTiles();
    return bodyPoints(x, y).every(([px, py]) => {
      const tx = Math.floor(px), ty = Math.floor(py);
      return under.has(ty * this.map.w + tx) || !this.solidAt(tx, ty, null, pass);
    });
  }

  // 第71回: (x, y) の マスが 出入り口で、今 いる マスでは ない（ついていく ときは よける）
  warpBlocks(x, y) {
    const w = this.map.w, k = Math.floor(y) * w + Math.floor(x);
    return k !== Math.floor(this.me.y) * w + Math.floor(this.me.x) && !!this.map.warpAt?.has(k);
  }

  // いま 体が 重なっている、とおれない マス（立っている 所で 炎の 柱が ふき上がった など）。
  // そこからは 出ていける（重なった まま 動けなく ならないように。新しく 入る マスは いつもどおり しらべる）
  stuckTiles() {
    const me = this.me, out = new Set();
    if (!me || !this.map) return out;
    for (const [px, py] of bodyPoints(me.x, me.y)) {
      const tx = Math.floor(px), ty = Math.floor(py);
      if (isBlocked(this.map, tx, ty, (f) => this.gateFlag(f))) out.add(ty * this.map.w + tx);
    }
    return out;
  }

  // いま 体が 重なっている 人（目を覚ました ところに 人が いた・歩く 人が 来た など）。
  // その 人からは はなれる ほうへ だけ 歩ける（重なった まま 動けなく ならないように。近づく ほうへは とおれない）
  leavingNpcs(x, y) {
    const me = this.me;
    let out = null, pts = null;
    for (const n of this.map.npcs) {
      if (!n.solid) continue;
      const s = this.npcState.get(n.id);
      if (!s || Math.abs(s.x - me.x) > 3 || Math.abs(s.y - me.y) > 3 || !this.npcVisible(n)) continue;
      pts ||= bodyPoints(me.x, me.y);
      if (!pts.some(([px, py]) => npcCovers(n, s.x, s.y, Math.floor(px), Math.floor(py)))) continue;
      if (Math.hypot(x - s.x, y - s.y) > Math.hypot(me.x - s.x, me.y - s.y)) (out ||= new Set()).add(n);
    }
    return out;
  }

  // ───────────── まいフレーム ─────────────
  update(dt, controls) {
    this.time += dt;
    this.lastDt = dt;
    const sec = dt / 1000;
    const me = this.me;
    // じぶんの いどう
    let { x: ix, y: iy } = controls.dir;
    const sky = this.game.sky;
    const flying = !!sky?.flying;
    const canMove = controls.canMove && !sky?.blocksMove();
    if (!canMove || this.riding) { ix = 0; iy = 0; }
    // ついていく（リーダーの とおった みちを たどる。はなれたら はしって おいつく）
    let run = !!controls.run;
    // 第71回: ついていく あいだは 出入り口（階だん など）を ふまない（リーダーは 階だんの 上に つく ように なった。
    // リーダーが 出入り口を とおれば サーバーが いっしょに つれていく。world.js の warpFollowers）
    this.followAuto = false;
    if (canMove && ix === 0 && iy === 0 && this.game.follow) {
      const d = this.followStep(dt);
      if (d) { ix = d.x; iy = d.y; run = run || d.far; this.followAuto = true; }
    } else this.followStuck = 0;
    const mag = Math.min(1, Math.hypot(ix, iy));
    // 氷（すべる）: ついていく ときは リーダーの 足あとを そのまま 歩く（すべらない）
    const iceOn = !flying && !(this.game.follow && this.leaderPos());
    if (this.riding) {
      // トロッコ（だいほんの えんしゅつ）
      this.rideStep(sec);
      me.moving = false;
      me.running = false;
    } else if (iceOn && this.slide) {
      // すべっている あいだは とまれない（だいほん・たたかいの あいだは まつ）
      if (canMove) this.slideStep(sec);
      me.moving = false;
      me.running = false;
    } else if (iceOn && (this.flow || (canMove && this.startFlow()))) {
      // 流れる 砂: 流されている あいだは 歩けない（だいほん・たたかいの あいだは まつ）
      if (canMove) this.flowStep(sec);
      me.moving = false;
      me.running = false;
    } else {
      me.moving = mag > 0.05;
      me.running = me.moving && run;
    }
    if (me.moving && !this.riding && !(iceOn && (this.slide || this.flow))) {
      if (Math.abs(ix) > Math.abs(iy)) me.dir = ix > 0 ? 'right' : 'left';
      else me.dir = iy > 0 ? 'down' : 'up';
      const d = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[me.dir];
      const onIce = iceOn && this.isIce(Math.floor(me.x), Math.floor(me.y));
      if (onIce) {
        // 氷の 上で とまっている: むいた ほうへ すべりだす（すぐ前が かべなら むきだけ かえる）
        if (!this.solidAt(Math.floor(me.x) + d[0], Math.floor(me.y) + d[1])) this.startSlide(d[0], d[1]);
        me.moving = false;
      } else {
        const sp = SPEED * sec * (mag > 0.4 ? 1 : 0.6) * (run ? RUN : 1) * (flying ? flySpeed(this.game.me?.flags) : this.isOnWater(me.x, me.y) ? SHIP : 1);
        const nx = me.x + (ix / (Math.hypot(ix, iy) || 1)) * sp;
        const ny = me.y + (iy / (Math.hypot(ix, iy) || 1)) * sp;
        let moved = false;
        // 大鳥で とんでいる ときは マップの はし まで どこでも（sky.js）
        if (flying) moved = sky.flyStep(me, nx, ny, iy, dt);
        else {
          if (this.boxFree(nx, me.y)) { me.x = nx; moved = true; }
          else if (Math.abs(iy) < 0.3) moved = this.nudge('y', me, ix > 0 ? 1 : -1, sp) || moved;
          if (this.boxFree(me.x, ny)) { me.y = ny; moved = true; }
          else if (Math.abs(ix) < 0.3) moved = this.nudge('x', me, iy > 0 ? 1 : -1, sp) || moved;
        }
        if (moved) this.pushTrail(me);
        // 氷に 足を のせた: その まま すべりだす
        if (moved && iceOn && this.isIce(Math.floor(me.x), Math.floor(me.y))) this.startSlide(d[0], d[1]);
      }
    }
    // しゃしんきの いち
    const tc = this.targetCam();
    this.cam.x += (tc.x - this.cam.x) * Math.min(1, sec * 10);
    this.cam.y += (tc.y - this.cam.y) * Math.min(1, sec * 10);
    if (Math.abs(tc.x - this.cam.x) > 200 || Math.abs(tc.y - this.cam.y) > 200) this.cam = tc;
    // ほかの プレイヤー
    for (const o of this.others.values()) {
      const k = Math.min(1, sec * 10);
      const dx = o.tx - o.x, dy = o.ty - o.y;
      if (Math.hypot(dx, dy) > 4) { o.x = o.tx; o.y = o.ty; }
      else { o.x += dx * k; o.y += dy * k; }
      if (Math.hypot(dx, dy) > 0.02) this.pushTrail(o);
    }
    for (const s of this.syms.values()) {
      const k = Math.min(1, sec * 9);
      s.x += (s.tx - s.x) * k;
      s.y += (s.ty - s.y) * k;
    }
    this.updateNpcs(dt);
    this.updateActors(dt);
    // サーバーへ いちを おくる
    this.moveTimer -= dt;
    const tileChanged = Math.floor(me.x) !== Math.floor(this.lastSent.x) || Math.floor(me.y) !== Math.floor(this.lastSent.y);
    if ((this.moveTimer <= 0 && (Math.abs(me.x - this.lastSent.x) > 0.01 || Math.abs(me.y - this.lastSent.y) > 0.01 || this.lastSent.moving !== me.moving || this.lastSent.running !== !!me.running)) || tileChanged) {
      this.moveTimer = 100;
      this.lastSent = { x: me.x, y: me.y, moving: me.moving, running: !!me.running };
      // run … 走っている（ほかの 人に 乗り物の 絵を 見せる。第37回）
      this.game.net.send({ t: 'move', x: +me.x.toFixed(3), y: +me.y.toFixed(3), dir: me.dir, moving: me.moving, run: !!me.running, seq: this.game.posSeq, follow: !!this.game.follow });
    }
    // モンスターに ふれた？・たたかっている なかまの ところに きた？
    if (canMove && !flying) {
      this.checkJoin();
      this.checkTouch();
    }
    this.reveal();
    if (this.shakeT > 0) this.shakeT -= dt;
  }

  // かどを すりぬけやすくする
  nudge(axis, me, dirSign, sp) {
    if (axis === 'y') {
      const cy = Math.floor(me.y) + 0.6;
      for (const off of [0.2, 0.35]) {
        for (const s of [1, -1]) {
          const ty = me.y + s * off;
          if (this.boxFree(me.x + dirSign * 0.1, ty) && Math.abs(ty - cy) <= Math.abs(me.y - cy) + 0.36) {
            const step = Math.min(sp, off) * s;
            if (this.boxFree(me.x, me.y + step)) { me.y += step; return true; }
          }
        }
      }
    } else {
      for (const off of [0.2, 0.35]) {
        for (const s of [1, -1]) {
          const tx = me.x + s * off;
          if (this.boxFree(tx, me.y + dirSign * 0.1)) {
            const step = Math.min(sp, off) * s;
            if (this.boxFree(me.x + step, me.y)) { me.x += step; return true; }
          }
        }
      }
    }
    return false;
  }

  // ───────────── 氷（第3章）─────────────
  // すべる きまり（ポケモンの 氷の ゆかと おなじ）:
  //  ・氷の マスに 入ると、むいた ほうへ 1マスずつ すべる
  //  ・つぎの マスが かべ・岩・人・宝箱 なら その マスで とまる。氷では ない ゆかに 着いたら とまる
  //  ・すべっている あいだは 向きを かえられない
  // マップの しかけは test/ch3-puzzles.test.js が 「どこで とまっても 入口へ もどれる」ことを たしかめる
  isIce(tx, ty) {
    return slidesAt(this.map, tx, ty, (f) => this.gateFlag(f));
  }

  startSlide(dx, dy) {
    this.slide = { dx, dy, tx: Math.floor(this.me.x), ty: Math.floor(this.me.y) };
  }

  slideStep(sec) {
    const s = this.slide, me = this.me;
    let budget = ICE_SPEED * sec;
    for (let guard = 0; guard < 8 && budget > 0 && this.slide; guard++) {
      const gx = s.tx + 0.5, gy = s.ty + 0.5;
      const dx = gx - me.x, dy = gy - me.y, d = Math.hypot(dx, dy);
      if (d > budget) {
        me.x += (dx / d) * budget;
        me.y += (dy / d) * budget;
        budget = 0;
        break;
      }
      me.x = gx;
      me.y = gy;
      budget -= d;
      // マスの まんなかに 着いた: ゆかなら とまる・前が ふさがって いたら とまる
      if (!this.isIce(s.tx, s.ty) || this.solidAt(s.tx + s.dx, s.ty + s.dy)) {
        this.slide = null;
        break;
      }
      s.tx += s.dx;
      s.ty += s.dy;
    }
    this.pushTrail(me);
  }

  // ───────────── 流れる 砂（第4章 Step 4。ピラミッド 3階の ありじごく）─────────────
  // 流される きまり（shared/maps/flow.js の carry と おなじ）:
  //  ・流れる 砂の マスに 立つと、その マスの 矢じるしの むきへ 1マスずつ 流される（とちゅうで 曲がる ことも ある）
  //  ・流れる 砂では ない ゆかに 着いたら とまる。流れの 先が かべなら、その マスで とまる（そこからは 歩ける）
  //  ・ありじごく（ワープの マス）に 着くと、サーバーが 下の 階へ おとす
  flowDir(tx, ty) {
    return TILE_INFO[effectiveTile(this.map, tx, ty, (f) => this.gateFlag(f))]?.flow || null;
  }

  startFlow() {
    const tx = Math.floor(this.me.x), ty = Math.floor(this.me.y);
    const d = this.flowDir(tx, ty);
    if (!d || this.solidAt(tx + d[0], ty + d[1])) return false;
    this.flow = { tx, ty };
    return true;
  }

  flowStep(sec) {
    const s = this.flow, me = this.me;
    let budget = FLOW_SPEED * sec;
    for (let guard = 0; guard < 8 && budget > 0 && this.flow; guard++) {
      const gx = s.tx + 0.5, gy = s.ty + 0.5;
      const dx = gx - me.x, dy = gy - me.y, d = Math.hypot(dx, dy);
      if (d > budget) {
        me.x += (dx / d) * budget;
        me.y += (dy / d) * budget;
        budget = 0;
        break;
      }
      me.x = gx;
      me.y = gy;
      budget -= d;
      // マスの まんなかに 着いた: その マスの 流れの むきへ（流れが ない・先が ふさがって いたら とまる）
      const f = this.flowDir(s.tx, s.ty);
      if (!f || this.solidAt(s.tx + f[0], s.ty + f[1])) {
        this.flow = null;
        break;
      }
      s.tx += f[0];
      s.ty += f[1];
    }
    this.pushTrail(me);
  }

  // ───────────── トロッコ（第3章。だいほんの ['ride', [[x, y], ...]]）─────────────
  ride(points, speed = CART_SPEED) {
    return new Promise((resolve) => {
      this.slide = null;
      this.flow = null;
      this.riding = { pts: points.map(([x, y]) => ({ x, y })), speed, resolve };
    });
  }

  rideStep(sec) {
    const r = this.riding, me = this.me;
    let budget = r.speed * sec;
    while (budget > 0 && r.pts.length) {
      const g = r.pts[0];
      const dx = g.x - me.x, dy = g.y - me.y, d = Math.hypot(dx, dy);
      if (d > 0.001) me.dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');
      if (d > budget) {
        me.x += (dx / d) * budget;
        me.y += (dy / d) * budget;
        budget = 0;
      } else {
        me.x = g.x;
        me.y = g.y;
        budget -= d;
        r.pts.shift();
      }
    }
    this.pushTrail(me);
    if (!r.pts.length) {
      this.riding = null;
      r.resolve();
    }
  }

  pushTrail(o) {
    const last = o.trail[0];
    if (!last || Math.hypot(last.x - o.x, last.y - o.y) >= 0.12) {
      o.trail.unshift({ x: o.x, y: o.y, dir: o.dir || 'down' });
      if (o.trail.length > 60) o.trail.pop();
    }
  }

  leaderPos() {
    const p = this.game.party;
    if (!p || p.leader === this.game.sid) return null;
    const o = this.others.get(p.leader);
    return o || null;
  }

  // リーダーの とおった ばしょ（パンくず）を たどって あるく。つまったら みちを さがす
  followStep(dt) {
    const leader = this.leaderPos();
    const tr = this.leaderCrumbs;
    const me = this.me;
    if (!leader) { tr.length = 0; return null; }
    // リーダーが たたかっていても そばへ いく（ちかづけば とちゅうから さんか）
    const dl = Math.hypot(leader.x - me.x, leader.y - me.y);
    if (dl < 1.4) { tr.length = 0; this.followStuck = 0; return null; }
    if (dl > 45) return null;
    // もう とおりすぎた パンくずは すてる
    let k = -1;
    for (let i = tr.length - 1; i >= 0; i--) if (Math.hypot(tr[i].x - me.x, tr[i].y - me.y) < 0.55) { k = i; break; }
    if (k >= 0) tr.splice(0, k + 1);
    // つまっている？
    const moved = this.followLast ? Math.hypot(me.x - this.followLast.x, me.y - this.followLast.y) : 1;
    this.followLast = { x: me.x, y: me.y };
    this.followStuck = moved < 0.01 ? (this.followStuck || 0) + dt : 0;
    if (this.followStuck > 450) {
      this.followStuck = 0;
      const path = this.findPath(Math.floor(me.x), Math.floor(me.y), Math.floor(leader.x), Math.floor(leader.y));
      if (path) tr.splice(0, tr.length, ...path.slice(1).map(([x, y]) => ({ x: x + 0.5, y: y + 0.5 })));
    }
    const t = tr[0] || leader;
    const dx = t.x - me.x, dy = t.y - me.y;
    const d = Math.hypot(dx, dy) || 1;
    return { x: dx / d, y: dy / d, far: dl > 3.2 };
  }

  // タイルの みちさがし（ちかい ところ だけ）
  findPath(sx, sy, tx, ty, limit = 2500) {
    const w = this.map.w;
    const key = (x, y) => y * w + x;
    const prev = new Map([[key(sx, sy), null]]);
    const q = [[sx, sy]];
    let head = 0;
    while (head < q.length && prev.size < limit) {
      const [x, y] = q[head++];
      if (x === tx && y === ty) {
        const out = [];
        let c = [x, y];
        while (c) { out.unshift(c); c = prev.get(key(c[0], c[1])); }
        return out;
      }
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx, ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= w || ny >= this.map.h) continue;
        const k = key(nx, ny);
        if (prev.has(k)) continue;
        if (!(nx === tx && ny === ty) && (this.solidAt(nx, ny) || this.map.warpAt?.has(k))) continue;
        prev.set(k, [x, y]);
        q.push([nx, ny]);
      }
    }
    return null;
  }

  // たたかっている なかまに ちかづいたら さんかする
  checkJoin() {
    const myParty = this.game.party?.id;
    if (!myParty) return;
    const now = performance.now();
    if (now < (this.joinCooldown || 0)) return;
    for (const o of this.others.values()) {
      if (!o.battle || o.partyId !== myParty) continue;
      if (Math.hypot(o.x - this.me.x, o.y - this.me.y) < 2.0) {
        this.joinCooldown = now + 1500;
        this.game.net.send({ t: 'joinBattle', sid: o.sid });
        return;
      }
    }
  }

  checkTouch() {
    const me = this.me;
    if (this.game.invulnUntil > performance.now()) return;
    for (const s of this.syms.values()) {
      if (Math.hypot(s.x - me.x, s.y - 0.1 - me.y) < 0.75) {
        const last = this.touchCooldown.get(s.id) || 0;
        if (performance.now() - last < 800) continue;
        this.touchCooldown.set(s.id, performance.now());
        this.game.net.send({ t: 'touch', id: s.id });
      }
    }
  }

  updateNpcs(dt) {
    for (const n of this.map.npcs) {
      const s = this.npcState.get(n.id);
      if (!s) continue;
      s.anim = (s.anim || 0) + dt;
      if (!n.wander || this.game.busy || s.talking) continue;
      s.t -= dt;
      if (s.t <= 0) {
        s.t = 1200 + Math.random() * 2600;
        if (Math.random() < 0.45) { s.moving = false; continue; }
        const dirs = [['up', 0, -1], ['down', 0, 1], ['left', -1, 0], ['right', 1, 0]];
        const [d, dx, dy] = dirs[Math.floor(Math.random() * 4)];
        const tx = Math.floor(s.x) + dx, ty = Math.floor(s.y) + dy;
        if (Math.abs(tx + 0.5 - s.hx) > n.wander || Math.abs(ty + 0.5 - s.hy) > n.wander) { s.moving = false; continue; }
        // 自分の 体が かかっている マスには 入らない
        const onMe = bodyPoints(this.me.x, this.me.y).some(([px, py]) => Math.floor(px) === tx && Math.floor(py) === ty);
        if (isBlocked(this.map, tx, ty, () => true) || onMe || this.map.chestAt.has(ty * this.map.w + tx)) { s.moving = false; continue; }
        s.dir = d;
        s.goal = { x: tx + 0.5, y: ty + 0.5 };
        s.moving = true;
      }
      if (s.moving && s.goal) {
        const sp = 1.6 * dt / 1000;
        const dx = s.goal.x - s.x, dy = s.goal.y - s.y;
        const d = Math.hypot(dx, dy);
        if (d < sp) { s.x = s.goal.x; s.y = s.goal.y; s.moving = false; s.goal = null; }
        else { s.x += dx / d * sp; s.y += dy / d * sp; }
      }
    }
  }

  // ───────────── えんしゅつの ひとたち ─────────────
  spawnActor(id, o) {
    this.actors.set(id, { id, sprite: o.sprite, x: o.x, y: o.y, dir: o.dir || 'down', path: [], moving: false });
  }
  removeActor(id) { this.actors.delete(id); }
  faceActor(id, dir) {
    const a = this.actors.get(id);
    if (a) a.dir = dir;
    else if (id === 'me') this.me.dir = dir;
  }
  moveActor(id, path) {
    const a = this.actors.get(id);
    if (!a) return Promise.resolve();
    return new Promise((resolve) => {
      a.path = path.map(([x, y]) => ({ x, y }));
      a.onDone = resolve;
      a.moving = true;
    });
  }
  updateActors(dt) {
    for (const a of this.actors.values()) {
      if (!a.moving) continue;
      const g = a.path[0];
      if (!g) {
        a.moving = false;
        a.onDone?.();
        continue;
      }
      const sp = 3.2 * dt / 1000;
      const dx = g.x - a.x, dy = g.y - a.y;
      const d = Math.hypot(dx, dy);
      if (Math.abs(dx) > Math.abs(dy)) a.dir = dx > 0 ? 'right' : 'left'; else if (Math.abs(dy) > 0.01) a.dir = dy > 0 ? 'down' : 'up';
      if (d <= sp) { a.x = g.x; a.y = g.y; a.path.shift(); }
      else { a.x += dx / d * sp; a.y += dy / d * sp; }
    }
  }

  // ───────────── サーバーからの じょうほう ─────────────
  onSnap(msg) {
    if (msg.map !== this.mapId) return;
    if (msg.fc) this.fchests = msg.fc.map(([id, x, y]) => ({ id, x, y }));
    const seen = new Set();
    for (const p of msg.players) {
      seen.add(p.sid);
      let o = this.others.get(p.sid);
      if (!o) {
        o = { sid: p.sid, x: p.x, y: p.y, trail: [] };
        this.others.set(p.sid, o);
      }
      Object.assign(o, { name: p.name, look: p.look, job: p.job, eq: p.eq, tx: p.x, ty: p.y, dir: p.dir, moving: !!p.mv, battle: !!p.b, away: !!p.aw, partyId: p.pid, fl: p.fl || [], air: !!p.air, ride: !!p.ride, wg: !!p.wg, vh: p.vh || null });
      o.mt = p.mt || null; // のりもの（'dragon' … 星の竜。sky.js）
      // リーダーの とおった みちを おぼえる（ついていく ため）
      if (this.game.follow && p.sid === this.game.party?.leader) {
        const tr = this.leaderCrumbs;
        const last = tr[tr.length - 1];
        // 第71回: 出入り口（階だんの 上に ついた リーダーの 足もと など）は パンくずに しない
        const onWarp = this.map.warpAt?.has(Math.floor(p.y) * this.map.w + Math.floor(p.x));
        if (!onWarp && (!last || Math.hypot(last.x - p.x, last.y - p.y) > 0.5)) {
          tr.push({ x: p.x, y: p.y });
          if (tr.length > 240) tr.shift();
        }
      }
    }
    for (const sid of [...this.others.keys()]) if (!seen.has(sid)) this.others.delete(sid);
    const seenS = new Set();
    for (const s of msg.syms) {
      seenS.add(s.id);
      let o = this.syms.get(s.id);
      if (!o) {
        o = { id: s.id, x: s.x, y: s.y };
        this.syms.set(s.id, o);
      }
      Object.assign(o, { sp: s.sp, tx: s.x, ty: s.y, dir: s.dir, st: s.st, gs: s.gs || null });
    }
    for (const id of [...this.syms.keys()]) if (!seenS.has(id)) this.syms.delete(id);
  }

  // ───────────── しらべる ─────────────
  interact() {
    // 空の 上では おりる
    if (this.game.sky?.flying) {
      this.game.sky.land();
      return true;
    }
    const me = this.me;
    const d = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[me.dir];
    const fx = me.x + d[0] * 0.75, fy = me.y - 0.12 + d[1] * 0.75;
    const tx = Math.floor(fx), ty = Math.floor(fy);
    // ひと
    const npc = this.npcNear(fx, fy) || (TILE_INFO[tileAt(this.map, tx, ty)]?.talkThrough ? this.npcNear(fx + d[0], fy + d[1]) : null);
    if (npc) {
      const s = this.npcState.get(npc.id);
      if (s && !npc.big && !['none', 'flower', 'starstone', 'windstone', 'firestone', 'spring', 'ship', 'slot', 'minecart', 'snowman', 'sand_ship', 'rudder'].includes(npc.sprite)) {
        s.dir = { up: 'down', down: 'up', left: 'right', right: 'left' }[me.dir];
        s.moving = false;
        s.goal = null;
      }
      this.game.net.send({ t: 'interact', kind: 'npc', id: npc.id });
      return true;
    }
    this.game.net.send({ t: 'interact', kind: 'tile', x: tx, y: ty });
    return true;
  }

  npcNear(x, y) {
    let best = null, bd = 0.85;
    for (const n of this.map.npcs) {
      if (!this.npcVisible(n)) continue;
      const s = this.npcState.get(n.id);
      const r = n.big ? 1.9 : 0.85;
      const d = Math.hypot(s.x - x, s.y - 0.2 - y);
      if (d < r && d < (n.big ? 1.9 : bd)) {
        best = n;
        bd = d;
      }
    }
    return best;
  }

  // ───────────── きりの マップ（たんさく） ─────────────
  loadExplored() {
    const m = this.map;
    const n = Math.ceil((m.w * m.h) / 8);
    let bits = new Uint8Array(n);
    const saved = this.game.me?.explored?.[m.id];
    if (saved) {
      try {
        const bin = atob(saved);
        for (let i = 0; i < Math.min(n, bin.length); i++) bits[i] = bin.charCodeAt(i);
      } catch { /* */ }
    }
    this.explored[m.id] = bits;
  }

  reveal() {
    const bits = this.explored[this.mapId];
    if (!bits) return;
    const m = this.map;
    const cx = Math.floor(this.me.x), cy = Math.floor(this.me.y);
    if (this.lastReveal && this.lastReveal[0] === cx && this.lastReveal[1] === cy && this.lastReveal[2] === this.mapId) return;
    this.lastReveal = [cx, cy, this.mapId];
    const R = m.kind === 'dungeon' ? 5 : 8;
    for (let y = cy - R; y <= cy + R; y++) {
      for (let x = cx - R; x <= cx + R; x++) {
        if (x < 0 || y < 0 || x >= m.w || y >= m.h) continue;
        if ((x - cx) ** 2 + (y - cy) ** 2 > R * R) continue;
        const i = y * m.w + x;
        if (!(bits[i >> 3] & (1 << (i & 7)))) {
          bits[i >> 3] |= 1 << (i & 7);
          this.exploredDirty = true;
        }
      }
    }
  }

  isExplored(x, y) {
    const bits = this.explored[this.mapId];
    if (!bits) return true;
    const i = y * this.map.w + x;
    return !!(bits[i >> 3] & (1 << (i & 7)));
  }

  exploredB64() {
    const bits = this.explored[this.mapId];
    let s = '';
    for (let i = 0; i < bits.length; i++) s += String.fromCharCode(bits[i]);
    return btoa(s);
  }

  // 夕ぐれの 色（第5章 Step 7。影の城が うかんだ あとの クモイ地方: map.dusk = { flag, color }。昼でも 夕方くらいの 色に）
  drawDusk(ctx) {
    const d = this.map?.dusk;
    // until … その フラグが たつと 晴れる（第5章 Step 9。ソリトゥスを たおした あと）
    // flag が ない ときは いつも（第6章の 千年前の マップの うすい セピアの まく）
    if (!d || (d.flag && !this.hasFlag(d.flag)) || (d.until && this.hasFlag(d.until))) return;
    ctx.fillStyle = d.color;
    ctx.fillRect(0, 0, this.vw, this.vh);
  }

  // ───────────── よる ─────────────
  // くらさ: サーバーの 時計（パーティーの 時間。shared/world/clock.js）。どうくつ・塔の 中は かわらない
  nightAlpha() {
    if (this.nightOverride !== null) return this.nightOverride ? 0.5 : 0;
    if (this.map.kind !== 'field') return 0;
    return (this.game.sky?.darkness() || 0) * 0.5;
  }

  // ───────────── かく ─────────────
  // 2D が おそい きかいでは がめんの こまかさを 2 に もどす（150コマの うち 3/4 が 28ms より おそい とき）
  watchSpeed() {
    if (this.res !== RES_HI) return;
    this.speedN = (this.speedN || 0) + 1;
    if ((this.lastDt || 0) > 28) this.slowN = (this.slowN || 0) + 1;
    if (this.speedN < 150) return;
    if (this.slowN > 112) {
      this.resCap = true;
      this.resize();
    }
    this.speedN = 0;
    this.slowN = 0;
  }

  render() {
    if (this.r3d && this.map) return this.render3d();
    this.watchSpeed();
    const ctx = this.ctx;
    const m = this.map;
    if (!m) return;
    const t = this.time;
    let camX = Math.round(this.cam.x), camY = Math.round(this.cam.y);
    if (this.shakeT > 0) {
      camX += Math.round((Math.random() - 0.5) * 6);
      camY += Math.round((Math.random() - 0.5) * 6);
    }
    ctx.fillStyle = m.bg2d || (m.kind === 'dungeon' ? '#0a0806' : '#1c3d6e');
    ctx.fillRect(0, 0, this.vw, this.vh);
    const r = prepareMap(m);
    const x0 = Math.max(0, Math.floor(camX / TS)), y0 = Math.max(0, Math.floor(camY / TS));
    const x1 = Math.min(m.w - 1, Math.floor((camX + this.vw) / TS)), y1 = Math.min(m.h - 1, Math.floor((camY + this.vh) / TS));
    const gate = (f) => this.gateFlag(f);
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        const i = y * m.w + x;
        const id = m.gates.length ? effectiveTile(m, x, y, gate) : m.tiles[i];
        const c = tileCanvas(id, r.variant[i], frameOf(id, t), r.mask[i], m.theme);
        ctx.drawImage(c, x * TS - camX, y * TS - camY);
      }
    }
    // きらきら
    if (m.sparkles) {
      const now = Date.now();
      for (const sp of m.sparkles) {
        if (sp.x < x0 - 1 || sp.x > x1 + 1 || sp.y < y0 - 1 || sp.y > y1 + 1) continue;
        const last = this.game.me?.sparkles?.[sp.id] || 0;
        if (now - last < 20 * 60 * 1000) continue;
        // いつも 見える（大きく・小さく またたく）
        const ph = Math.floor(t / 170 + sp.x) % 6;
        const L = ph === 1 || ph === 4 ? 5 : ph === 0 || ph === 3 ? 4 : 3;
        const px = sp.x * TS + 8 - camX, py = sp.y * TS + 8 - camY;
        ctx.fillStyle = ph % 2 ? '#ffffff' : '#fff6b0';
        ctx.fillRect(px - 1, py - L, 2, L * 2);
        ctx.fillRect(px - L, py - 1, L * 2, 2);
        if (L === 5) {
          ctx.fillStyle = '#fff6b0';
          for (const [dx, dy] of [[-3, -3], [2, -3], [-3, 2], [2, 2]]) ctx.fillRect(px + dx, py + dy, 1, 1);
        }
      }
    }
    // 宝の地図の 場所（まだ ほっていない）: 赤むらさきの 光の 柱（きらきらと ちがう 色）
    for (const sp of this.treasureSpots()) {
      if (sp.x < x0 - 2 || sp.x > x1 + 2 || sp.y < y0 - 1 || sp.y > y1 + 4) continue;
      drawTreasureGlow(ctx, sp.x * TS + 8 - camX, sp.y * TS + 11 - camY, t, 1);
    }
    // ものを y の じゅんに ならべて かく
    const objs = [];
    const hasF = (f) => this.hasFlag(f);
    for (const ch of m.chests) {
      if (!condOk(ch.show, hasF) || this.chestGone(ch)) continue;
      objs.push({ y: ch.y + 0.95, draw: () => this.drawChest(ch, camX, camY) });
    }
    for (const fc of this.fchests) objs.push({ y: fc.y + 0.95, draw: () => this.drawChest(fc, camX, camY) });
    for (const n of m.npcs) {
      if (!this.npcVisible(n) || n.sprite === 'none') continue;
      const s = this.npcState.get(n.id);
      objs.push({ y: s.y, draw: () => this.drawNpc(n, s, camX, camY) });
    }
    for (const s of this.syms.values()) {
      objs.push({ y: s.y, draw: () => this.drawSym(s, camX, camY) });
    }
    for (const o of this.others.values()) {
      objs.push({ y: o.y, draw: () => this.drawPlayer(o, camX, camY, o.look, o.job, false, o.eq) });
      o.fl.forEach((f, i) => {
        if (this.hideGuests && f.guest) return;
        const tp = this.trailPos(o, i + 1);
        if (tp && !o.air && !this.otherVehicle(o) && !this.isOnWater(tp.x, tp.y)) objs.push({ y: tp.y, draw: () => this.drawAt(followerSprite(f, tp.dir, this.walkFrame(o.moving)), tp.x, tp.y, camX, camY) });
      });
    }
    // じぶんの なかま（酒場の なかま・モンスター・ゲスト）
    const fl = this.myVehicle() ? [] : this.myFollowers(); // 乗り物に 乗っている 間は みんなで 乗っている（第37回）
    fl.forEach((f, i) => {
      const tp = this.trailPos(this.me, i + 1);
      if (tp && !this.riding && !this.game.sky?.hidesFollowers() && !this.isOnWater(tp.x, tp.y)) objs.push({ y: tp.y, draw: () => this.drawAt(followerSprite(f, tp.dir, this.walkFrame(this.myStep)), tp.x, tp.y, camX, camY) });
    });
    // 馬車（render/wagon.js）
    for (const w of wagonDraws(this)) objs.push({ y: w.y, draw: () => this.drawAt(w.canvas, w.x, w.y, camX, camY) });
    for (const a of this.actors.values()) {
      objs.push({ y: a.y, draw: () => this.game.sky?.drawActor2D(this, a, camX, camY) || this.drawAt(npcSprite(a.sprite, a.dir, this.walkFrame(true)), a.x, a.y, camX, camY) });
    }
    if (!this.hideMe) objs.push({ y: this.me.y, draw: () => this.drawPlayer(this.me, camX, camY, this.game.me.look, this.game.me.job, true, shownEquip(this.game.me)) });
    objs.sort((a, b) => a.y - b.y);
    for (const o of objs) o.draw();
    // やね
    for (const roof of m.roofs || []) this.drawRoof(roof, camX, camY);
    // お店の かんばん（やねの うえに かける）
    for (const b of m.boards || []) {
      if (b.x < x0 - 1 || b.x > x1 + 1 || b.y < y0 - 1 || b.y > y1 + 1) continue;
      const c = boardCanvas(b.kind);
      ctx.drawImage(c, Math.round(b.x * TS + (TS - c.width) / 2 - camX), Math.round(b.y * TS - 4 - camY));
    }
    // くらやみ・よる
    if (m.dark) this.drawDark(camX, camY, x0, y0, x1, y1);
    this.drawDusk(ctx);
    const na = this.nightAlpha();
    if (na > 0) {
      ctx.fillStyle = `rgba(12, 18, 60, ${na})`;
      ctx.fillRect(0, 0, this.vw, this.vh);
      // あかりの まわりは すこし あかるく
      ctx.globalCompositeOperation = 'lighter';
      for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
        const id = m.tiles[y * m.w + x];
        // 町の あかり・家の 入り口から もれる 光
        const rr = NIGHT_GLOW[id];
        if (rr) {
          const R = rr * 40;
          const g = ctx.createRadialGradient(x * TS + 8 - camX, y * TS + 6 - camY, 1, x * TS + 8 - camX, y * TS + 6 - camY, R);
          g.addColorStop(0, `rgba(255, 214, 130, ${na * (rr < 1 ? 0.7 : 1.4)})`);
          g.addColorStop(0.18, `rgba(255, 200, 110, ${na * 0.7})`);
          g.addColorStop(1, 'rgba(255, 200, 110, 0)');
          ctx.fillStyle = g;
          ctx.fillRect(x * TS + 8 - R - camX, y * TS + 6 - R - camY, R * 2, R * 2);
        }
      }
      // きらきらは 夜でも 光って 見える
      for (const sp of this.litSparkles()) {
        if (sp.x < x0 - 1 || sp.x > x1 + 1 || sp.y < y0 - 1 || sp.y > y1 + 1) continue;
        const cx = sp.x * TS + 8 - camX, cy = sp.y * TS + 8 - camY;
        const g = ctx.createRadialGradient(cx, cy, 1, cx, cy, 11);
        g.addColorStop(0, `rgba(255, 246, 176, ${Math.min(1, na * 2.2)})`);
        g.addColorStop(1, 'rgba(255, 246, 176, 0)');
        ctx.fillStyle = g;
        ctx.fillRect(cx - 11, cy - 11, 22, 22);
      }
      ctx.globalCompositeOperation = 'source-over';
    }
    // 雪・ふぶき・火の粉（第3章）・砂ぼこり・砂嵐（第4章。夜は かすみを くらく）。render/weather.js
    this.weather.draw(ctx, this.vw, this.vh, this.lastDt || 16, this.weatherKind(), camX, camY, na);
    this.renderLabels(camX, camY);
  }

  // いまの 天気（マップの weatherAt / weather。だいほんの ['weather', …] が あれば それ）
  weatherKind() {
    if (this.weatherOverride !== undefined && this.weatherOverride !== null) return this.weatherOverride || null;
    const m = this.map;
    if (!m) return null;
    if (m.weatherAt) return m.weatherAt(Math.floor(this.me.x), Math.floor(this.me.y));
    return m.weather || null;
  }

  // ───────────── 2.5D で かく ─────────────
  render3d() {
    const m = this.map;
    this.r3d.render(this.lastDt || 16);
    // うえに かさねる 2D（くらやみ・よる・きらきら・しるし）
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.vw, this.vh);
    const s = innerWidth / this.vw;
    const P = (x, y, up = 0) => {
      const p = this.r3d.project(x, y, up);
      return { x: p.x / s, y: p.y / s, k: this.r3d.tilePx(x, y) / s };
    };
    const t = this.time;
    // きらきら
    if (m.sparkles) {
      const now = Date.now();
      for (const sp of m.sparkles) {
        if (Math.abs(sp.x - this.me.x) > 24 || Math.abs(sp.y - this.me.y) > 24) continue;
        const last = this.game.me?.sparkles?.[sp.id] || 0;
        if (now - last < 20 * 60 * 1000) continue;
        const ph = Math.floor(t / 170 + sp.x) % 6;
        const L = ph === 1 || ph === 4 ? 5 : ph === 0 || ph === 3 ? 4 : 3;
        const p = P(sp.x + 0.5, sp.y + 0.5, 0.25);
        const k = Math.max(1, Math.round(p.k / 16));
        ctx.fillStyle = ph % 2 ? '#ffffff' : '#fff6b0';
        ctx.fillRect(p.x - k, p.y - L * k, 2 * k, 2 * L * k);
        ctx.fillRect(p.x - L * k, p.y - k, 2 * L * k, 2 * k);
        if (L === 5) {
          ctx.fillStyle = '#fff6b0';
          for (const [dx, dy] of [[-3, -3], [2, -3], [-3, 2], [2, 2]]) ctx.fillRect(p.x + dx * k, p.y + dy * k, k, k);
        }
      }
    }
    // 宝の地図の 場所（まだ ほっていない）: 赤むらさきの 光の 柱
    for (const sp of this.treasureSpots()) {
      if (Math.abs(sp.x - this.me.x) > 26 || Math.abs(sp.y - this.me.y) > 26) continue;
      const p = P(sp.x + 0.5, sp.y + 0.55, 0.02);
      drawTreasureGlow(ctx, p.x, p.y, t, Math.max(0.6, p.k / 16));
    }
    // なかまの しるし（たたかいちゅう・つうしんまち）
    const myParty = this.game.party?.id;
    for (const o of this.others.values()) {
      if (o.battle && o.partyId === myParty) {
        const p = P(o.x, o.y);
        const r = (0.8 + Math.sin(t / 160) * 0.12) * p.k;
        ctx.strokeStyle = 'rgba(255, 214, 107, 0.9)';
        ctx.lineWidth = Math.max(1, p.k / 16);
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, r, r * 0.5, 0, 0, Math.PI * 2);
        ctx.stroke();
      }
      if (o.battle || o.away) {
        const p = P(o.x, o.y, 1.55);
        const k = Math.max(1, Math.round(p.k / 16));
        if (o.battle) {
          ctx.fillStyle = '#1b1330';
          ctx.fillRect(p.x - 5 * k, p.y - 5 * k, 11 * k, 11 * k);
          ctx.fillStyle = '#ffd66b';
          for (let i = -3; i <= 3; i++) {
            ctx.fillRect(p.x + i * k, p.y + i * k, k, k);
            ctx.fillRect(p.x - i * k, p.y + i * k, k, k);
          }
        } else {
          const bob = (Math.floor(t / 500) % 2) * k;
          ctx.fillStyle = '#c9d4ff';
          ctx.fillRect(p.x, p.y - bob, 4 * k, k);
          ctx.fillRect(p.x + 2 * k, p.y + k - bob, k, k);
          ctx.fillRect(p.x + k, p.y + 2 * k - bob, k, k);
          ctx.fillRect(p.x, p.y + 3 * k - bob, 4 * k, k);
        }
      }
    }
    // くらやみ（どうくつ）
    if (m.dark) {
      const d = this.darkCanvas;
      const x = ctxOf(d);
      x.globalCompositeOperation = 'source-over';
      x.clearRect(0, 0, d.width, d.height);
      x.fillStyle = 'rgba(4, 2, 10, 0.86)';
      x.fillRect(0, 0, d.width, d.height);
      x.globalCompositeOperation = 'destination-out';
      const light = (p, r, a = 1) => {
        const g = x.createRadialGradient(p.x, p.y, r * 0.25, p.x, p.y, r);
        g.addColorStop(0, `rgba(0,0,0,${a})`);
        g.addColorStop(1, 'rgba(0,0,0,0)');
        x.fillStyle = g;
        x.fillRect(p.x - r, p.y - r, r * 2, r * 2);
      };
      const flick = 1 + Math.sin(t / 90) * 0.03;
      const pm = P(this.me.x, this.me.y, 0.5);
      light(pm, 5 * pm.k * flick);
      for (const o of this.others.values()) { const p = P(o.x, o.y, 0.5); light(p, 3.8 * p.k); }
      for (const a of this.actors.values()) { const p = P(a.x, a.y, 0.5); light(p, 3.2 * p.k, 0.8); }
      const x0 = Math.max(0, Math.floor(this.me.x - 16)), x1 = Math.min(m.w - 1, Math.floor(this.me.x + 16));
      const y0 = Math.max(0, Math.floor(this.me.y - 14)), y1 = Math.min(m.h - 1, Math.floor(this.me.y + 18));
      for (let yy = y0; yy <= y1; yy++) for (let xx = x0; xx <= x1; xx++) {
        const id = tileAt(m, xx, yy);
        if (id === T.TORCH) { const p = P(xx + 0.5, yy + 1.05, 0.9); light(p, 2.8 * p.k * flick, 0.9); }
        else if (id === T.CRYSTAL) { const p = P(xx + 0.5, yy + 0.8, 0.5); light(p, 2 * p.k, 0.7); }
        else if (id === T.CAVE_WATER && m.theme === 'lava' && (xx + yy) % 2 === 0) { const p = P(xx + 0.5, yy + 0.5, 0); light(p, 1.6 * p.k * flick, 0.55); }
      }
      x.globalCompositeOperation = 'source-over';
      ctx.drawImage(d, 0, 0);
    }
    // 夕ぐれの 色（第5章 Step 7）・よる
    this.drawDusk(ctx);
    const na = this.nightAlpha();
    if (na > 0) {
      ctx.fillStyle = `rgba(12, 18, 60, ${na})`;
      ctx.fillRect(0, 0, this.vw, this.vh);
      ctx.globalCompositeOperation = 'lighter';
      const x0 = Math.max(0, Math.floor(this.me.x - 18)), x1 = Math.min(m.w - 1, Math.floor(this.me.x + 18));
      const y0 = Math.max(0, Math.floor(this.me.y - 14)), y1 = Math.min(m.h - 1, Math.floor(this.me.y + 20));
      for (let yy = y0; yy <= y1; yy++) for (let xx = x0; xx <= x1; xx++) {
        const id = m.tiles[yy * m.w + xx];
        const rr = NIGHT_GLOW[id];
        if (rr) {
          const p = P(xx + 0.5, yy + 0.7, id === T.DOOR ? 0.6 : 1);
          const r = 2.6 * rr * p.k;
          const g = ctx.createRadialGradient(p.x, p.y, 1, p.x, p.y, r);
          g.addColorStop(0, `rgba(255, 214, 130, ${na * (rr < 1 ? 0.7 : 1.4)})`);
          g.addColorStop(0.18, `rgba(255, 200, 110, ${na * 0.7})`);
          g.addColorStop(1, 'rgba(255, 200, 110, 0)');
          ctx.fillStyle = g;
          ctx.fillRect(p.x - r, p.y - r, r * 2, r * 2);
        }
      }
      // きらきらは 夜でも 光って 見える
      for (const sp of this.litSparkles()) {
        if (Math.abs(sp.x - this.me.x) > 24 || Math.abs(sp.y - this.me.y) > 24) continue;
        const p = P(sp.x + 0.5, sp.y + 0.5, 0.25);
        const r = 0.75 * p.k;
        const g = ctx.createRadialGradient(p.x, p.y, 1, p.x, p.y, r);
        g.addColorStop(0, `rgba(255, 246, 176, ${Math.min(1, na * 2.2)})`);
        g.addColorStop(1, 'rgba(255, 246, 176, 0)');
        ctx.fillStyle = g;
        ctx.fillRect(p.x - r, p.y - r, r * 2, r * 2);
      }
      ctx.globalCompositeOperation = 'source-over';
    }
    this.weather.draw(ctx, this.vw, this.vh, this.lastDt || 16, this.weatherKind(), this.me.x * TS, this.me.y * TS, na);
    // 第78回: 階段・くさりの 目じるし（▲▼。くらやみ・よるの 上に。render/field3d.js）
    this.r3d.drawMarks?.(ctx, P, t);
    this.renderLabels(0, 0);
  }

  // 2.5D で たてて かく もの の いちらん
  entities3d() {
    const out = [];
    const m = this.map;
    const hasF = (f) => this.hasFlag(f);
    for (const ch of m.chests) {
      if (!condOk(ch.show, hasF) || this.chestGone(ch)) continue;
      out.push({ key: 'c:' + ch.id, canvas: chestCanvas3d(!!this.game.me?.chests?.[ch.id]), x: ch.x + 0.5, y: ch.y + 0.8, anchor: 1, shadowScale: 1.3 });
    }
    for (const fc of this.fchests) out.push({ key: 'f:' + fc.id, canvas: chestCanvas3d(false), x: fc.x + 0.5, y: fc.y + 0.8, anchor: 1, shadowScale: 1.3 });
    // お店の かんばん（かべの まえに うかべる。なかに いる たてものの かんばんは かくす）
    const inside = this.r3d?.inside;
    (m.boards || []).forEach((b, i) => {
      if (inside && b.x >= inside.x && b.x < inside.x + inside.w && b.y >= inside.y && b.y < inside.y + inside.h) return;
      out.push({ key: 'b:' + i, canvas: boardCanvas(b.kind), x: b.x + 0.5, y: b.y + 1.04, lift: 0.5, anchor: 0, shadow: false });
    });
    for (const n of m.npcs) {
      if (!this.npcVisible(n) || n.sprite === 'none') continue;
      const s = this.npcState.get(n.id);
      // 大きな とくべつな え（第6章の 星の木・テント・番兵・星くいのよる鳥 など）は bigNpcCanvas に ないので、ふつうの え の 大きさで
      const bigC = n.big ? bigNpcCanvas(n.sprite, Math.floor(this.time / 600) % 2) : null;
      if (bigC) {
        const k = bigScale(n.sprite);
        out.push({ key: 'n:' + n.id, canvas: bigC, x: s.x, y: s.y, scale: k, anchor: 6 / k, shadowScale: 3 });
        continue;
      }
      const frame = n.wander ? this.walkFrame(s.moving) : Math.floor(this.time / 500) % 2;
      if (n.sprite === 'ship') {
        out.push({ key: 'n:' + n.id, canvas: npcSprite('ship', s.dir, this.shipFrame()), x: s.x, y: s.y, ...SHIP3D });
        continue;
      }
      // 砂の船（第4章の すなかぜ号）: さんばしの 先の 砂の 海に うかべる
      if (n.sprite === 'sand_ship') {
        out.push({ key: 'n:' + n.id, canvas: npcSprite('sand_ship', s.dir, this.shipFrame()), x: s.x, y: s.y + SAND_SHIP_DY, ...SHIP3D });
        continue;
      }
      out.push({ key: 'n:' + n.id, canvas: npcSprite(n.sprite, s.dir, frame), x: s.x, y: s.y, shadow: !['starstone', 'windstone', 'firestone'].includes(n.sprite), anchor: n.sprite.startsWith('mon:') ? 2 : undefined });
    }
    for (const s of this.syms.values()) {
      const c = this.huntTint(s, monsterCanvas(s.sp, Math.floor(this.time / 300 + (s.id.length % 2)) % 2, true));
      const fly = isFlying(s.sp);
      out.push({ key: 's:' + s.id, canvas: c, x: s.x, y: s.y, flip: s.dir === 'right', anchor: 2, lift: fly ? 0.35 + Math.sin(this.time / 200) * 0.12 : 0 });
    }
    for (const o of this.others.values()) {
      // 大鳥に のっている 人（sky.js）
      if (this.game.sky?.entity3d(this, o, false, out, o.look, o.job, o.eq)) continue;
      const mate = o.partyId === this.game.party?.id;
      const oShip = this.isOnWater(o.x, o.y);
      const oVeh = !oShip && this.otherVehicle(o);
      const oc = oShip ? shipSprite(o.dir || 'down', this.shipFrame(), this.map.ship)
        : oVeh ? this.vehicleSprite(oVeh, o.look, o.job, o.eq, o.dir)
          : playerSprite(o.look, o.job, o.dir || 'down', this.walkFrame(o.moving), o.eq);
      out.push({ key: 'p:' + o.sid, canvas: oc, x: o.x, y: o.y, alpha: o.away ? 0.45 : 1, ghost: mate ? '#ffd66b' : null, ...(oShip ? SHIP3D : {}), ...(oVeh ? { shadowScale: vehicleShadow(oVeh) } : {}) });
      o.fl.forEach((f, i) => {
        if (this.hideGuests && f.guest) return;
        if (oVeh) return;
        const tp = this.trailPos(o, i + 1);
        if (tp && !this.isOnWater(tp.x, tp.y)) out.push({ key: `pf:${o.sid}:${i}`, canvas: followerSprite(f, tp.dir, this.walkFrame(o.moving)), x: tp.x, y: tp.y, anchor: f.mon ? 2 : undefined });
      });
    }
    const myVeh = this.myVehicle();
    (myVeh ? [] : this.myFollowers()).forEach((f, i) => {
      const tp = this.trailPos(this.me, i + 1);
      if (tp && !this.riding && !this.game.sky?.hidesFollowers() && !this.isOnWater(tp.x, tp.y)) out.push({ key: 'mf:' + i, canvas: followerSprite(f, tp.dir, this.walkFrame(this.myStep)), x: tp.x, y: tp.y, anchor: f.mon ? 2 : undefined });
    });
    for (const w of wagonDraws(this)) out.push({ key: w.key, canvas: w.canvas, x: w.x, y: w.y, shadowScale: w.side ? 1.65 : 1.1 });
    for (const a of this.actors.values()) {
      out.push(this.game.sky?.actor3d(a, this) || { key: 'a:' + a.id, canvas: npcSprite(a.sprite, a.dir, this.walkFrame(true)), x: a.x, y: a.y });
    }
    this.game.sky?.extra3d(this, out);
    if (!this.hideMe && this.game.me && this.game.sky?.entity3d(this, this.me, true, out, this.game.me.look, this.game.me.job, shownEquip(this.game.me))) return out;
    if (!this.hideMe && this.game.me) {
      const ship = this.isOnWater(this.me.x, this.me.y);
      const mc = ship ? shipSprite(this.me.dir || 'down', this.shipFrame(), this.map.ship)
        : myVeh ? this.vehicleSprite(myVeh, this.game.me.look, this.game.me.job, shownEquip(this.game.me), this.me.dir)
          : playerSprite(this.game.me.look, this.game.me.job, this.me.dir || 'down', this.walkFrame(this.myStep), shownEquip(this.game.me));
      out.push({ key: 'me', canvas: mc, x: this.me.x, y: this.me.y, ghost: '#9fd6ff', ...(ship ? SHIP3D : {}), ...(myVeh && !ship ? { shadowScale: vehicleShadow(myVeh) } : {}) });
      // トロッコに のっている（第3章）
      if (this.riding) out.push({ key: 'me:cart', canvas: npcSprite('minecart', this.me.dir, this.walkFrame(true)), x: this.me.x, y: this.me.y + 0.06, shadow: false });
    }
    return out;
  }

  // 船に のっている？（海の マップの 水の 上）
  isOnWater(x, y) {
    return onWater(this.map, x, y, (f) => this.gateFlag(f));
  }

  // 船は ゆっくり ゆれる
  shipFrame() {
    return Math.floor(this.time / 520) % 2;
  }

  walkFrame(moving) {
    return Math.floor(this.time / (moving ? (moving === 'run' ? 110 : 170) : 420)) % 2;
  }

  // じぶんと なかまの あしぶみ（はしると はやい）
  get myStep() {
    return this.me.running ? 'run' : this.me.moving;
  }

  // 仲間（ついてくる キャラ）の いち: 通った 道（trail）を n 人目 ぶん もどった ところ。
  // 第35回: 道の 点（0.12マスごと）に とびとびに 合わせると、主人公が 歩く たびに こまかく ふるえた。
  // 点と 点の 間を なめらかに うめる（trailAt。test/ui-r35.test.js）
  trailPos(o, n) {
    return trailAt(o, n * 0.95);
  }

  // ───────────── 乗り物（第37回。data/vehicles.js・render/vehicle-art.js） ─────────────
  // 自分: えらんだ 乗り物に、走っている 時だけ 乗る。船・大鳥・竜・トロッコ・イベントで かくれている 時は 乗らない
  myVehicle() {
    const me = this.me, sky = this.game.sky;
    return rideShown(chosenVehicle(this.game.me), {
      running: !!(me.moving && me.running),
      ship: !!this.map && this.isOnWater(me.x, me.y),
      air: !!(sky?.flying || sky?.anim),
      cart: !!this.riding,
      hidden: !!this.hideMe || !!sky?.ridingAlong?.(),
      // 第6章 Step 6: 千年前は ぜんまい馬だけ（data/vehicles.js）
      past: !!this.map?.past,
    });
  }

  // ほかの 人: サーバーの いちの じょうほう（vh … 走って 乗っている 時だけ とどく）
  otherVehicle(o) {
    return rideShown(o?.vh, { running: !!o?.moving, ship: !!this.map && this.isOnWater(o.x, o.y), air: !!o?.air, past: !!this.map?.past });
  }

  // 人を のせた 乗り物の 絵（コマは 時間で。3コマの 乗り物も ある）
  vehicleSprite(id, look, job, eq, dir) {
    const f = Math.floor(this.time / 120) % vehicleFrames(id);
    const key = `${heroLookKey(look)}:${job}:${equipKey(eq, job)}`;
    return vehicleCanvas(id, key, (d, fr) => playerSprite(look, job, d, fr, eq), dir || 'down', f);
  }

  myFollowers() {
    const p = this.game.party;
    if (!p || p.leader !== this.game.sid) return [];
    const out = [];
    // 見た目装備（lookEquip）が あれば その 絵（shared/look-equip.js）
    for (const s of p.supports || []) out.push({ look: s.look, job: s.job, eq: shownEquip(s), mon: colorMon(s.species, s.color) });
    if (!this.hideGuests) for (const g of p.guests || []) out.push({ look: g.look, job: g.job, eq: g.equip, guest: true });
    return out;
  }

  drawAt(c, x, y, camX, camY, shadow = true) {
    if (!c) return;
    // こまかい え（res 4 など）は 見た目の 大きさで おく
    const r = c.res || 1;
    const w = c.width / r, h = c.height / r;
    const px = Math.round(x * TS - w / 2 - camX);
    const py = Math.round(y * TS - h + 3 - camY);
    // かげ
    if (shadow) {
      this.ctx.fillStyle = 'rgba(0,0,0,0.22)';
      this.ctx.fillRect(px + 4, py + h - 3, w - 8, 2);
    }
    this.drawFine(c, px, py, w, h);
  }

  // がめんより こまかい え は なめらかに ちぢめる（ドットが ぬけて ギザギザに ならないように）
  drawFine(c, x, y, w, h) {
    const ctx = this.ctx;
    const soft = (c.res || 1) > this.res;
    if (soft) { ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high'; }
    ctx.drawImage(c, x, y, w, h);
    if (soft) ctx.imageSmoothingEnabled = false;
  }

  drawPlayer(o, camX, camY, look, job, mine = false, eq = undefined) {
    if (!look) return;
    // 大鳥に のっている（sky.js）
    if (this.game.sky?.draw2D(this, o, camX, camY, look, job, mine, eq)) return;
    this.drawPlayerOnFoot(o, camX, camY, look, job, mine, eq);
  }

  drawPlayerOnFoot(o, camX, camY, look, job, mine = false, eq = undefined) {
    const ship = this.isOnWater(o.x, o.y);
    const veh = !ship && (mine ? this.myVehicle() : this.otherVehicle(o));
    const c = ship ? shipSprite(o.dir || 'down', this.shipFrame(), this.map.ship)
      : veh ? this.vehicleSprite(veh, look, job, eq, o.dir)
        : playerSprite(look, job, o.dir || 'down', this.walkFrame(mine ? this.myStep : o.moving), eq);
    const ctx = this.ctx;
    const myParty = this.game.party?.id;
    // なかまが たたかっている: あしもとに ひかる わ（ちかづくと さんか できる）
    if (o.battle && !mine && o.partyId === myParty) {
      const px = o.x * TS - camX, py = o.y * TS - camY;
      const r = 13 + Math.sin(this.time / 160) * 2;
      ctx.save();
      ctx.strokeStyle = 'rgba(255, 214, 107, 0.9)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(Math.round(px), Math.round(py - 1), r, r * 0.45, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    if (o.away) ctx.globalAlpha = 0.45;
    this.drawAt(c, o.x, o.y + (ship ? 0.2 : 0), camX, camY, !ship);
    ctx.globalAlpha = 1;
    // トロッコに のっている（第3章）: 足もとを トロッコで かくす
    if (mine && this.riding) this.drawAt(npcSprite('minecart', o.dir || 'down', this.walkFrame(true)), o.x, o.y + 0.06, camX, camY, false);
    if (o.battle) {
      // ⚔ の しるし
      const px = Math.round(o.x * TS - camX), py = Math.round(o.y * TS - 27 - camY);
      ctx.fillStyle = '#1b1330';
      ctx.fillRect(px - 5, py - 5, 11, 11);
      ctx.fillStyle = '#ffd66b';
      for (let i = -3; i <= 3; i++) {
        ctx.fillRect(px + i, py + i, 1, 1);
        ctx.fillRect(px - i, py + i, 1, 1);
      }
      ctx.fillStyle = '#d9534f';
      ctx.fillRect(px - 4, py + 2, 2, 2);
      ctx.fillRect(px + 3, py + 2, 2, 2);
    } else if (o.away) {
      const px = Math.round(o.x * TS - camX), py = Math.round(o.y * TS - 26 - camY);
      const bob = Math.floor(this.time / 500) % 2;
      ctx.fillStyle = '#c9d4ff';
      ctx.fillRect(px + 2, py - bob, 4, 1);
      ctx.fillRect(px + 4, py + 1 - bob, 1, 1);
      ctx.fillRect(px + 3, py + 2 - bob, 1, 1);
      ctx.fillRect(px + 2, py + 3 - bob, 4, 1);
    }
  }

  drawNpc(n, s, camX, camY) {
    const bigC = n.big ? bigNpcCanvas(n.sprite, Math.floor(this.time / 600) % 2) : null;
    // 大きな とくべつな え（第6章。render/ch6-art.js）は bigNpcCanvas に ないので、下の ふつうの え の 大きさで かく
    if (bigC) {
      const c = bigC;
      const k = bigScale(n.sprite) / (c.res || 1);
      const w = Math.round(c.width * k), h = Math.round(c.height * k);
      this.drawFine(c, Math.round(s.x * TS - w / 2 - camX), Math.round(s.y * TS - h + 6 - camY), w, h);
      return;
    }
    if (n.sprite === 'ship') {
      this.drawAt(npcSprite('ship', s.dir, this.shipFrame()), s.x, s.y + 0.2, camX, camY, false);
      return;
    }
    if (n.sprite === 'sand_ship') {
      this.drawAt(npcSprite('sand_ship', s.dir, this.shipFrame()), s.x, s.y + SAND_SHIP_DY, camX, camY, false);
      return;
    }
    const frame = n.wander ? this.walkFrame(s.moving) : Math.floor(this.time / 500) % 2;
    this.drawAt(npcSprite(n.sprite, s.dir, frame), s.x, s.y, camX, camY);
  }

  // 第64回 ⑥a: さがしている 魔物（素材の 入手先で えらんだ。ui/sources.js）は 赤く 点めつ
  huntTint(s, c) {
    if (!c || !huntMatch(this.game.hunt, s) || Math.floor(this.time / 320) % 2) return c;
    let t = huntTints.get(c);
    if (!t) {
      t = document.createElement('canvas');
      t.width = c.width; t.height = c.height;
      if (c.res) t.res = c.res;
      const x = t.getContext('2d');
      x.drawImage(c, 0, 0);
      x.globalCompositeOperation = 'source-atop';
      x.fillStyle = 'rgba(255, 40, 30, 0.62)';
      x.fillRect(0, 0, t.width, t.height);
      huntTints.set(c, t);
    }
    return t;
  }

  drawSym(s, camX, camY) {
    const c = this.huntTint(s, monsterCanvas(s.sp, Math.floor(this.time / 300 + (s.id.length % 2)) % 2, true));
    const bob = isFlying(s.sp) ? Math.round(Math.sin(this.time / 200) * 2) - 4 : 0;
    const r = c.res || 1;
    const w = c.width / r, h = c.height / r;
    const px = Math.round(s.x * TS - w / 2 - camX);
    const py = Math.round(s.y * TS - h + 2 - camY + bob);
    this.ctx.fillStyle = 'rgba(0,0,0,0.25)';
    this.ctx.fillRect(px + 3, Math.round(s.y * TS - camY), w - 6, 2);
    if (s.dir === 'right') {
      this.ctx.save();
      this.ctx.translate(px + w, py);
      this.ctx.scale(-1, 1);
      this.drawFine(c, 0, 0, w, h);
      this.ctx.restore();
    } else this.drawFine(c, px, py, w, h);
    if (s.st) {
      this.ctx.fillStyle = '#ff5a5a';
      this.ctx.fillRect(px + w / 2 - 1, py - 6, 2, 3);
      this.ctx.fillRect(px + w / 2 - 1, py - 2, 2, 1);
    }
  }

  // 宝の地図の まだ ほっていない 場所（この マップの もの）。さそわれて 手伝っている ときは リーダーの 地図
  treasureSpots() {
    const g = this.game;
    const helper = g.party && g.party.leader !== g.sid && Array.isArray(g.worldTreasure);
    const list = helper ? g.worldTreasure : (g.me?.treasureMaps || []).filter((tm) => !tm.found);
    const id = this.mapId;
    return list.filter((tm) => tm.map === id);
  }

  // まだ ひろって いない（光っている）きらきら
  litSparkles() {
    const list = this.map?.sparkles;
    if (!list?.length) return [];
    const now = Date.now();
    const got = this.game.me?.sparkles || {};
    return list.filter((sp) => now - (got[sp.id] || 0) >= 20 * 60 * 1000);
  }

  // フィールドの 宝箱は 開けると きえる（洞窟・塔・町の 宝箱は 開いた まま のこる）
  chestGone(ch) {
    return chestVanishes(this.map) && !!this.game.me?.chests?.[ch.id];
  }

  drawChest(ch, camX, camY) {
    const opened = !!this.game.me?.chests?.[ch.id];
    const x = ch.x * TS - camX, y = ch.y * TS - camY;
    const c = this.ctx;
    c.fillStyle = '#1b1330';
    c.fillRect(x + 1, y + 4, 14, 11);
    c.fillStyle = opened ? '#6a4220' : '#b8773a';
    c.fillRect(x + 2, y + 5, 12, 9);
    c.fillStyle = opened ? '#3a2410' : '#d8995a';
    c.fillRect(x + 2, y + 5, 12, opened ? 2 : 3);
    c.fillStyle = '#f2c14e';
    c.fillRect(x + 2, y + 8, 12, 1);
    c.fillRect(x + 7, y + 7, 2, 3);
  }

  drawRoof(roof, camX, camY) {
    const me = this.me;
    const inside = !this.game.sky?.flying && me.x >= roof.x + 1 && me.x < roof.x + roof.w - 1 && me.y >= roof.y + 1 && me.y < roof.y + roof.h;
    if (inside) return;
    const key = `${roof.x},${roof.y}`;
    let c = this.roofCache.get(key);
    if (!c) {
      const [base, dark, light] = ROOF[roof.color] || ROOF.red;
      const w = roof.w * TS, h = (roof.h - 1) * TS + 6;
      c = makeCanvas(w, h);
      const x = ctxOf(c);
      x.fillStyle = dark;
      x.fillRect(0, 0, w, h);
      x.fillStyle = base;
      x.fillRect(1, 1, w - 2, h - 3);
      for (let yy = 4; yy < h - 3; yy += 5) {
        x.fillStyle = dark;
        x.fillRect(1, yy, w - 2, 1);
        for (let xx = (yy / 5) % 2 ? 3 : 8; xx < w - 2; xx += 10) x.fillRect(xx, yy - 4, 1, 4);
      }
      x.fillStyle = light;
      x.fillRect(1, 1, w - 2, 2);
      x.fillRect(2, Math.floor(h / 2) - 1, w - 4, 2);
      x.fillStyle = '#1b1330';
      x.fillRect(0, h - 2, w, 2);
      this.roofCache.set(key, c);
    }
    this.ctx.drawImage(c, roof.x * TS - camX, roof.y * TS - camY - 4);
  }

  drawDark(camX, camY, x0, y0, x1, y1) {
    const d = this.darkCanvas;
    const x = ctxOf(d);
    x.globalCompositeOperation = 'source-over';
    x.fillStyle = 'rgba(4, 2, 10, 0.88)';
    x.clearRect(0, 0, d.width, d.height);
    x.fillRect(0, 0, d.width, d.height);
    x.globalCompositeOperation = 'destination-out';
    const light = (lx, ly, r, a = 1) => {
      const g = x.createRadialGradient(lx, ly, r * 0.25, lx, ly, r);
      g.addColorStop(0, `rgba(0,0,0,${a})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      x.fillStyle = g;
      x.fillRect(lx - r, ly - r, r * 2, r * 2);
    };
    const flick = 1 + Math.sin(this.time / 90) * 0.03;
    light(this.me.x * TS - camX, (this.me.y - 0.5) * TS - camY, 78 * flick);
    for (const o of this.others.values()) light(o.x * TS - camX, (o.y - 0.5) * TS - camY, 60);
    const m = this.map;
    for (let yy = y0 - 3; yy <= y1 + 3; yy++) for (let xx = x0 - 3; xx <= x1 + 3; xx++) {
      const id = tileAt(m, xx, yy);
      if (id === T.TORCH) light(xx * TS + 8 - camX, yy * TS + 6 - camY, 44 * flick, 0.9);
      else if (id === T.CRYSTAL) light(xx * TS + 8 - camX, yy * TS + 8 - camY, 30, 0.7);
      else if (id === T.CAVE_WATER && (xx + yy) % (m.theme === 'lava' ? 2 : 5) === 0) light(xx * TS + 8 - camX, yy * TS + 8 - camY, m.theme === 'lava' ? 26 : 14, m.theme === 'lava' ? 0.55 : 0.3);
    }
    for (const a of this.actors.values()) light(a.x * TS - camX, (a.y - 0.5) * TS - camY, 50, 0.8);
    this.ctx.drawImage(d, 0, 0);
  }

  // なまえ・ふきだし（DOM）
  renderLabels(camX, camY) {
    const s = innerWidth / this.vw;
    // あしもとから px ぶん うえの がめんの いち
    const at = this.r3d
      ? (x, y, px) => this.r3d.project(x, y, px / TS)
      : (x, y, px) => ({ x: (x * TS - camX) * s, y: (y * TS - px - camY) * s });
    const alive = new Set();
    const put = (key, text, x, y, cls) => {
      alive.add(key);
      let e = this.labels.get(key);
      if (!e) {
        e = el('div', { class: `plabel ${cls}` });
        this.labelsEl.append(e);
        this.labels.set(key, e);
      }
      if (e.textContent !== text) e.textContent = text;
      e.className = `plabel ${cls}`;
      const p = at(x, y, 22);
      e.style.left = `${p.x}px`;
      e.style.top = `${p.y}px`;
    };
    const myParty = this.game.party?.id;
    for (const o of this.others.values()) {
      const mate = o.partyId === myParty;
      const text = o.away ? `${o.name}（通信待ち）` : o.battle && mate ? `${o.name}（戦い中！近づくと参加）` : o.name;
      put('p:' + o.sid, text, o.x, o.y, mate ? 'party' : '');
    }
    for (const [key, e] of this.labels) if (!alive.has(key)) { e.remove(); this.labels.delete(key); }
    // ふきだし
    const now = performance.now();
    this.bubbles = this.bubbles.filter((b) => {
      if (now > b.until) { b.el.remove(); return false; }
      const o = b.sid === this.game.sid ? this.me : this.others.get(b.sid);
      if (!o) { b.el.style.display = 'none'; return true; }
      b.el.style.display = '';
      const p = at(o.x, o.y, 30);
      b.el.style.left = `${p.x}px`;
      b.el.style.top = `${p.y}px`;
      return true;
    });
  }

  bubble(sid, text) {
    const e = el('div', { class: 'bubble', text });
    this.labelsEl.append(e);
    this.bubbles.push({ sid, el: e, until: performance.now() + 4000 });
  }

  clearLabels() {
    for (const e of this.labels.values()) e.remove();
    this.labels.clear();
    for (const b of this.bubbles) b.el.remove();
    this.bubbles = [];
  }

  // どこに いるか
  areaName() {
    return this.map.areaName(Math.floor(this.me.x), Math.floor(this.me.y));
  }

  areaBgm() {
    // 第4章の 砂ばくは 昼と 夜で 曲が かわる（maps/south.js の southBgmAt）
    // 第5章 Step 7: クモイ地方は 影の城が うかぶと 曲が かわる（4つめ … 世界の フラグ）
    if (this.map.bgmAt) return this.map.bgmAt(Math.floor(this.me.x), Math.floor(this.me.y), !!this.game.sky?.isNight(), (f) => this.hasFlag(f));
    if (this.map.kind === 'dungeon') return this.map.bgm || 'cave';
    const name = this.areaName();
    for (const p of Object.values(PLACES)) if (p.name === name) return p.bgm;
    if (name === 'ささやきの森') return 'forest';
    return 'field';
  }
}

