// ゲーム ぜんたいの しんこう
import { applyHand } from './ui/hand.js';
import { bindLayout } from './ui/layout.js';
import { Input } from './input.js';
import { GameAudio, _TRACKS } from './audio.js';
// 第77回 C: 場面で かわる 音楽（戦いの 曲・ピンチ・だん・ダンジョンの 深さ・昼夜・まわりの音）
import { SceneAudio } from './audio-scene.js';
import { MONSTERS } from '../shared/data/monsters.js';
import { Field } from './field.js';
import { Hud, STAMPS } from './ui/hud.js';
import { FieldMenu, openWorldMap } from './ui/menu.js';
import { ScriptPlayer, wait } from './ui/script.js';
import { BattleScene } from './battle.js';
import { showTitle, showLogin, showSelect, showCreate, showLoading, saveWhere } from './ui/title.js';
import { showServerDown } from './ui/syncui.js';
import { toast, confirmBox, el } from './ui/dom.js';
import { MAPS } from '../shared/maps/index.js';
import { applyBattlePrefs, applyUiFont } from './prefs.js';
import { SkyClient } from './sky.js';
// 第50回 N3: 大事な物の すぐ使う ボタン
import { QuickButton } from './ui/quick-item.js';
// 第58回: マルチプレイの 自動追跡（リーダーに ついていく）の ボタン
import { FollowButton } from './ui/follow-btn.js';
import { HuntButton } from './ui/sources.js';
import { reportError } from './errlog.js';
// 第51回 B: 家族のけいじ板（ui/family-board.js）
import { onBoardMsg, boardOnEnter } from './ui/family-board.js';
// 第67回 C班: モンスター闘技場の その場の 対戦（申しこみの まど・受付の 選びしにも 足す）
import { onMonLive } from './ui/monarena-live.js';
// 第75回: 宝の地図が いっぱいの ときに どれを 捨てるか 聞く（ui/treasure.js）
import { watchTreasureFull } from './ui/treasure.js';

export class Game {
  constructor(net) {
    this.net = net;
    this.input = new Input();
    this.audio = new GameAudio();
    // 第77回 D: はじめて 聞いた 曲の 場所（音楽を聞く の 名前の かわり）
    this.audio.placeOf = () => this.field?.areaName?.();
    this.sceneAudio = new SceneAudio(this.audio, { tracks: _TRACKS, maps: MAPS, monsters: MONSTERS });
    this.field = new Field(this);
    this.hud = new Hud(this);
    // 昼・夜の 時計と 大鳥フウラ（sky.js）
    this.sky = new SkyClient(this);
    // 第50回 N3: 大事な物の すぐ使う ボタン（大鳥・竜の ボタンの 下。ui/quick-item.js）
    this.quick = new QuickButton(this);
    this.followBtn = new FollowButton(this);
    this.huntBtn = new HuntButton(this); // 第64回 ⑥a: 素材を 落とす 魔物を さがす
    this.menu = new FieldMenu(this);
    this.script = new ScriptPlayer(this);
    this.state = 'boot';
    this.me = null;
    this.party = null;
    this.players = [];
    this.busy = false;
    this.menuOpen = false;
    this.follow = false;
    this.posSeq = 0;
    this.invulnUntil = 0;
    this.exploredTimer = 0;
    this.bgmTimer = 0;
    this.titleStars = null;
    this.waiters = new Set(); // 返事を まっている もの（ui/syncui.js の request）
    this.input.fieldHandler = (a) => this.onFieldAction(a);
    // ウインドウが ひらいた・とじた → 十字キーの パッドを 出す・しまう（すぐに。ウインドウが ずれない ように）
    this.input.onStack = () => this.updatePad();
    net.on((m) => this.onMessage(m));
    net.onStatus((s) => {
      this.hud.setConnection(s);
      this.onNetStatus(s);
    });
    // クラウドセーブの ようすが かわったら 画面に 出す（ひとりモード）
    net.local?.cloud?.onChange((st) => this.onCloudState(st));
    try { if (localStorage.getItem('kizuna_bigtext')) document.body.classList.add('big-text'); } catch { /* */ }
    applyHand(); // 第64回: たて持ちの ボタンの ならび（ui/hand.js）
    bindLayout(); // 第67回: 自分で ならべた ボタン（ui/layout.js。たて・よこ 別々）
    applyUiFont();
    applyBattlePrefs();
    // iPhone: さわったら おとを もどす・もどってきたら がめんを つけたままに する
    const kick = () => this.audio.resumeIfNeeded();
    addEventListener('touchend', kick, { passive: true });
    addEventListener('pointerup', kick);
    addEventListener('keydown', kick);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) return;
      this.audio.resumeIfNeeded();
      if (this.inWorld) this.keepAwake(true);
      // スリープから もどった: つなぎ直す 時間を あげてから 数えなおす
      if (this.lostAt) {
        this.lostAt = Date.now();
        this.watchDown();
      }
    });
  }

  get inWorld() {
    return !!this.me && ['field', 'battle', 'battle-intro'].includes(this.state);
  }

  // がめんが きえないように する（せっていで OFF に できる）
  get awakeOn() {
    try { return localStorage.getItem('kizuna_awake') !== 'off'; } catch { return true; }
  }

  set awakeOn(on) {
    try { localStorage.setItem('kizuna_awake', on ? 'on' : 'off'); } catch { /* */ }
    this.keepAwake(on && this.inWorld);
  }

  async keepAwake(on) {
    try {
      if (on && this.awakeOn && !this.wakeLock && navigator.wakeLock && !document.hidden) {
        const lock = await navigator.wakeLock.request('screen');
        this.wakeLock = lock;
        lock.addEventListener('release', () => { if (this.wakeLock === lock) this.wakeLock = null; });
      } else if (!on && this.wakeLock) {
        const lock = this.wakeLock;
        this.wakeLock = null;
        await lock.release();
      }
    } catch { /* ゆるされない ときは なにも しない */ }
  }

  start() {
    this.state = 'title';
    showTitle(this);
    // 2.5D（つかえる ときだけ。せっていで 2D に もどせる）
    this.field.setView(this.field.savedView());
    let last = performance.now();
    const loop = (t) => {
      const dt = Math.min(50, t - last);
      last = t;
      try {
        this.frame(dt);
      } catch (e) {
        reportError(this, e, `frame:${this.state}`);
      }
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
    // どこかで おきた エラーも きろく（うごけなく なった ときの 原因さがし。errlog.js）
    addEventListener('error', (ev) => reportError(this, ev.error || ev.message, 'window'));
    addEventListener('unhandledrejection', (ev) => reportError(this, ev.reason, 'promise'));
    // テスト・デバッグ用
    window.__game = this;
  }

  afterTitle() {
    if (this.net.mode === 'server') {
      this.state = 'login';
      if (this.welcomed) this.onWelcomeReady();
      else showLogin(this);
    } else {
      this.state = 'select';
      // クラウドの セーブを 読みおわるまで まつ（そのあいだ「読みこみ中」）
      if (['loading', 'asking'].includes(this.net.local?.cloud?.state)) showLoading(this);
      this.net.send({ t: 'hello' });
    }
  }

  // 家族サーバーに つながらない（PCが 止まった など）: ひとりで遊ぶサイトを 案内する
  onNetStatus(st) {
    if (st === 'ok') {
      clearTimeout(this.downTimer);
      this.lostAt = 0;
      showServerDown(this, false);
      return;
    }
    // つなぎ直している あいだ（connecting）も 数えつづける
    if (this.net.mode !== 'server' || st !== 'lost' || this.lostAt) return;
    this.lostAt = Date.now();
    this.watchDown();
  }

  // 家族サーバーに つながらない まま しばらく たったら、ひとりで遊ぶサイトへの 案内を 出す
  // （ゲームの 中では 長めに 待つ。スマホの 画面が 消えていた 間は 数えない）
  watchDown() {
    clearTimeout(this.downTimer);
    if (!this.lostAt || this.net.status === 'ok' || document.hidden) return;
    const left = (this.inWorld ? 15000 : 4000) - (Date.now() - this.lostAt);
    if (left > 0) {
      this.downTimer = setTimeout(() => this.watchDown(), left);
      return;
    }
    showServerDown(this, true);
  }

  onCloudState(st) {
    const label = document.querySelector('.title-save');
    if (label) {
      const w = saveWhere(this);
      label.textContent = w.long;
      label.className = `small ${w.warn ? 'warn' : 'muted'} title-save`;
    }
    if (this.state === 'select' && !this.welcomed && ['loading', 'asking'].includes(st)) showLoading(this);
    if (this.state === 'select' && this.welcomed && !document.querySelector('.create, .transfer-panel, .modal-back')) showSelect(this, this.chars || []);
    if (st === 'error' && !this.cloudErrorShown) {
      this.cloudErrorShown = true;
      toast('今はclaude.aiにセーブできません。このブラウザには残っているので、そのまま遊べます', 6000);
    }
    if (st === 'readonly') toast('見るだけの共有なので、claude.aiにはセーブできません（このブラウザだけにセーブします）', 7000);
  }

  // ───────────── まいフレーム ─────────────
  frame(dt) {
    this.input.update();
    this.input.prune();
    const inField = this.state === 'field';
    const touchEl = document.getElementById('touch');
    this.updatePad();
    const hideTouch = !(inField && this.input.touch && !this.menuOpen) || this.padShown;
    if (hideTouch && !touchEl.hidden) this.input.releaseTouch();
    touchEl.hidden = hideTouch;
    if (inField) {
      const canMove = !this.busy && !this.menuOpen && !this.input.busy;
      this.watchStuck(dt, canMove);
      watchTreasureFull(this, dt, canMove);
      this.sky.update(dt);
      this.quick.update();
      this.followBtn.update();
      this.huntBtn.update();
      this.field.update(dt, { dir: this.input.dir, canMove, run: this.input.run });
      this.field.render();
      this.hud.update(dt);
      this.bgmTimer -= dt;
      if (this.bgmTimer <= 0 && !this.busy) {
        this.bgmTimer = 600;
        this.audio.play(this.field.areaBgm());
      }
      this.syncSceneAudio();
      this.exploredTimer -= dt;
      if (this.exploredTimer <= 0 && this.field.exploredDirty) {
        this.exploredTimer = 12000;
        this.field.exploredDirty = false;
        this.net.send({ t: 'explored', map: this.field.mapId, data: this.field.exploredB64() });
      }
    } else if (this.state === 'battle' || this.state === 'battle-intro') {
      this.battle?.update(dt);
      this.watchBattle();
      // 戦いの 画面が できない まま（こわれた など）: 立てなおす
      this.noBattleT = this.battle ? 0 : (this.noBattleT || 0) + dt;
      if (this.noBattleT > 8000) {
        this.noBattleT = 0;
        reportError(this, new Error('battle state without scene'), 'stuck:battle');
        this.rescue();
      }
    } else {
      // タイトル・キャラえらび: まわりの音は 止める
      this.sceneAudio.setAmbience(null);
      this.drawTitleBg(dt);
    }
  }

  // ウインドウ（えらぶ リスト）が 出ている ときの 十字キー・A・B（スマホ。せっていで しまえる）
  updatePad() {
    const inp = this.input;
    const on = !!(inp.touch && inp.padEl && inp.padOn && inp.padWanted && !['battle', 'battle-intro', 'boot'].includes(this.state) && !document.querySelector('.sync-cover'));
    if (on === !!this.padShown) return;
    this.padShown = on;
    if (!on) inp.stopPad?.();
    inp.padEl.hidden = !on;
    document.body.classList.toggle('pad-on', on);
  }

  drawTitleBg(dt) {
    const f = this.field;
    const x = f.ctx;
    const W = f.vw, H = f.vh;
    if (!this.titleStars || this.titleStars.w !== W) {
      this.titleStars = { w: W, list: Array.from({ length: 90 }, () => ({ x: Math.random() * W, y: Math.random() * H * 0.75, p: Math.random() * 6, s: Math.random() < 0.15 ? 2 : 1 })), t: 0, shoot: null };
    }
    const st = this.titleStars;
    st.t += dt;
    const g = x.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#05071a');
    g.addColorStop(0.7, '#1a1a52');
    g.addColorStop(1, '#3a2a6a');
    x.fillStyle = g;
    x.fillRect(0, 0, W, H);
    for (const s of st.list) {
      const tw = (Math.sin(st.t / 500 + s.p) + 1) / 2;
      x.fillStyle = tw > 0.6 ? '#ffffff' : '#9aa8ff';
      x.fillRect(Math.round(s.x), Math.round(s.y), s.s, s.s);
    }
    if (!st.shoot && Math.random() < dt / 2500) st.shoot = { x: Math.random() * W * 0.7 + W * 0.2, y: Math.random() * H * 0.3, a: 0 };
    if (st.shoot) {
      st.shoot.a += dt;
      const k = st.shoot.a / 700;
      x.fillStyle = '#fff6d8';
      for (let i = 0; i < 12; i++) x.fillRect(Math.round(st.shoot.x - (k * 120) + i * 2), Math.round(st.shoot.y + (k * 60) - i), 1, 1);
      if (k > 1) st.shoot = null;
    }
    // やまと むらの かげ
    x.fillStyle = '#0c0a24';
    for (let px = 0; px < W; px++) {
      const h = 20 + Math.abs(Math.sin(px * 0.02) * 26) + Math.abs(Math.sin(px * 0.07) * 8);
      x.fillRect(px, H - h, 1, h);
    }
    x.fillStyle = '#ffd66b';
    for (let i = 0; i < 6; i++) x.fillRect(Math.round(W * (0.15 + i * 0.13)), H - 14 - (i % 2) * 4, 2, 2);
  }

  // ───────────── ボタン ─────────────
  onFieldAction(a) {
    // 会話の まどが 出ているのに ボタンを うけとる ものが ない（たたかいの はじまりで けされた など）: A・B で すすめる
    if (this.state === 'field' && this.busy && (a === 'a' || a === 'b') && this.script.advance) {
      this.script.advance();
      return;
    }
    if (this.state !== 'field' || this.busy || this.menuOpen) return;
    if (a === 'a') this.field.interact();
    else if (a === 'b' || a === 'menu') this.openMenu();
    else if (a === 'map') openWorldMap(this);
    else if (a === 'chat') this.hud.chatInput();
    else if (a === 'fly') this.sky.toggle();
    else if (a === 'ride') this.sky.padButton();
    else if (a === 'quick') this.quick.use();
  }

  openMenu(section) {
    if (this.state !== 'field' || this.busy || this.menuOpen) return;
    this.audio.sfx('confirm');
    this.menu.open();
    if (section) {
      const idx = this.menu.menu.items.findIndex((it) => it.value === section);
      if (idx >= 0) {
        this.menu.menu.idx = idx;
        this.menu.menu.updateSel();
        this.menu.preview(section);
      }
    }
  }

  // ───────────── えんしゅつ ─────────────
  fade(out) {
    const c = document.getElementById('curtain');
    c.classList.remove('flash');
    c.classList.toggle('on', out);
    return wait(480);
  }

  async flash() {
    const c = document.getElementById('curtain');
    const was = c.classList.contains('on');
    c.classList.add('flash', 'on');
    await wait(140);
    c.classList.remove('on');
    await wait(140);
    c.classList.remove('flash');
    if (was) c.classList.add('on');
  }

  applyPos(map, x, y, dir, seq, fly = false) {
    if (seq !== undefined) this.posSeq = seq;
    this.sky.setFlying(fly);
    const changed = this.field.mapId !== map;
    this.field.setMap(map, x, y, dir);
    this.field.lastSent = { x, y, moving: false };
    if (changed) {
      this.audio.sfx('stairs');
      this.hud.lastArea = null;
    }
  }

  setObjective(text) {
    if (this.me) this.me.objective = text;
    this.refreshObjective();
  }

  // さそわれて リーダーの 冒険を 手伝っている ときは リーダーの 目標を 出す
  visitingLeader() {
    const p = this.party;
    if (!p || (p.members?.length || 0) < 2 || !this.sid || p.leader === this.sid) return null;
    return p.members.find((m) => m.sid === p.leader) || null;
  }

  refreshObjective() {
    const leader = this.visitingLeader();
    if (leader) this.hud.setObjective(this.party.objective, leader.name);
    else this.hud.setObjective(this.me?.objective);
  }

  async quitToTitle() {
    this.net.send({ t: 'quit' });
    this.leaveField();
    this.state = 'select';
  }

  leaveField() {
    this.field.clearLabels();
    this.hud.show(false);
    document.getElementById('ui').innerHTML = '';
    this.me = null;
    this.keepAwake(false);
  }

  waitBattleClosed() {
    if (this.state !== 'battle' && !this.battleClosing) return Promise.resolve();
    return new Promise((r) => { this.battleWaiters = (this.battleWaiters || []).concat(r); });
  }

  // ───────────── メッセージ ─────────────
  async onMessage(m) {
    for (const w of [...this.waiters]) w(m);
    switch (m.t) {
      case '_open':
        if (this.pwSent || this.me) {
          let pw = '';
          try { pw = localStorage.getItem('kizuna_pw') || ''; } catch { /* */ }
          this.net.send({ t: 'hello', pw });
        }
        break;
      case '_close':
        break;
      case 'welcome':
        this.welcomed = true;
        this.chars = m.chars;
        this.timeOffset = (m.serverTime || Date.now()) - Date.now();
        this.pwSent = true;
        if (this.me && this.lastCharId) {
          this.net.send({ t: 'play', id: this.lastCharId });
          return;
        }
        if (this.state === 'login' || this.state === 'select') this.onWelcomeReady();
        break;
      case 'helloFail':
        // 待ってね・合言葉が 短い（外出先）の ときは、おぼえた 合言葉は そのまま
        if (!m.code) {
          try { localStorage.removeItem('kizuna_pw'); } catch { /* */ }
        }
        if (this.state !== 'title') showLogin(this, m.reason, m.code);
        break;
      case 'chars':
        this.chars = m.chars;
        if (this.state === 'select' && !this.pendingPlay && !document.querySelector('.create, .transfer-panel')) showSelect(this, m.chars);
        break;
      case 'exportCode':
      case 'importResult':
        this.transferWaiter?.(m);
        break;
      case 'charCreated':
        if (this.pendingPlay) {
          this.pendingPlay = false;
          this.net.send({ t: 'play', id: m.id });
        }
        break;
      case 'enter': return this.onEnter(m);
      case 'self': {
        const prevJob = this.me?.job;
        this.me = m.char;
        // もくひょうは サーバーの ものに あわせる（なかまの イベントの あとも 自分の もくひょう）
        if (m.char?.objective !== undefined) this.refreshObjective();
        this.hud.renderParty();
        this.menu.refresh();
        if (prevJob && prevJob !== m.char.job) this.hud.renderParty();
        break;
      }
      case 'party':
        this.party = m.party;
        this.worldFlagSet = Array.isArray(m.party?.worldFlags) ? new Set(m.party.worldFlags) : null;
        this.worldVisited = Array.isArray(m.party?.worldVisited) ? new Set(m.party.worldVisited) : null;
        this.worldTreasure = Array.isArray(m.party?.worldTreasure) ? m.party.worldTreasure : null;
        this.sky.onParty(m.party);
        this.hud.renderParty();
        this.refreshObjective();
        this.menu.refresh();
        break;
      case 'players':
        this.players = m.players;
        break;
      case 'setPos':
        this.applyPos(m.map, m.x, m.y, m.dir, m.seq, m.fly);
        break;
      case 'fly':
        this.sky.onFly(m);
        break;
      case 'flyAsk':
        this.sky.onAsk(m);
        break;
      case 'flyAskEnd':
        this.sky.onAskEnd(m);
        break;
      case 'clock':
        this.sky.onClock(m);
        break;
      case 'snap':
        this.field.onSnap(m);
        break;
      case 'hurt':
        // ようがんの 地面（第3章。shared/world/hazards.js）
        this.onHurt(m);
        break;
      case 'script':
        this.scriptEnded = false;
        await this.waitBattleClosed();
        this.script.enqueue(m);
        break;
      case 'scriptEnd':
        await this.waitBattleClosed();
        this.scriptEnded = true;
        if (!this.script.running) this.endScript();
        break;
      case 'svcRes':
        if (this.svcWaiter) {
          const w = this.svcWaiter;
          this.svcWaiter = null;
          w(m);
        }
        break;
      case 'menuRes': {
        // メニューが 返事を まっている（道具を 続けて 使う。ui/menu.js の menuCall）: true なら 知らせは メニューの まどに 出す
        const w = this.menuWaiter;
        this.menuWaiter = null;
        let shown = false;
        try { shown = !!w?.(m); } catch (e) { console.error(e); }
        if (m.text && !shown) toast(m.text);
        this.audio.sfx(m.ok ? 'confirm' : 'buzz');
        break;
      }
      // 第67回 C班: その場の 対戦の 知らせ（ui/monarena-live.js）
      case 'monLive':
        onMonLive(this, m);
        break;
      case 'battleStart': return this.onBattleStart(m);
      case 'battleEv':
        // はじまりの えんしゅつ中は とっておいて、戦いの 画面が できてから わたす
        if (this.battleEvBuf) this.battleEvBuf.push(m);
        else this.battle?.onEvents(m.evs);
        break;
      case 'battleRej':
        toast(m.reason);
        this.audio.sfx('buzz');
        this.battle?.onReject();
        break;
      case 'battleEnd': return this.onBattleEnd(m);
      // 第61回: リーダーが けっかの まどを とじた（パーティーで いっしょに たたかった 時）
      case 'resultClose':
        if (this.battle && (m.id === undefined || this.battle.id === m.id)) this.battle.leaderClose();
        break;
      case 'invite': {
        // たたかいや かいわの あいだは おわるまで まつ
        for (let i = 0; i < 600 && (this.state !== 'field' || this.busy || this.menuOpen); i++) await wait(200);
        if (this.state !== 'field') break;
        this.audio.sfx('join');
        const ok = await confirmBox(this.input, `${m.from}からパーティーのおさそいが来た！\nいっしょに冒険する？\n（${m.from}のストーリーを手伝うよ。自分のストーリーは進まないけど、レベルやお金はもらえる）`, '入る！', '今はいい', (x) => this.audio.sfx(x));
        this.net.send({ t: 'party', action: ok ? 'accept' : 'decline' });
        break;
      }
      case 'toast':
        // afterBattle: たたかいの けっかを とじてから 出す（全滅して 目を覚ました ときなど）
        if (m.afterBattle && (this.state === 'battle' || this.battleClosing)) this.waitBattleClosed().then(() => {
          if (m.sfx) this.audio.sfx(m.sfx);
          toast(m.text, 6000);
        });
        else {
          if (m.sfx) this.audio.sfx(m.sfx);
          toast(m.text, m.afterBattle ? 6000 : undefined);
        }
        break;
      case 'chat':
        this.hud.addChat(m.from, m.text, m.stamp);
        if (this.state === 'field') this.field.bubble(m.sid === this.sid ? this.sid : m.sid, m.stamp || m.text);
        this.audio.sfx('stamp');
        break;
      // 第51回 B: 家族のけいじ板
      case 'fboardNew': case 'fboardList': case 'fboardLast':
        onBoardMsg(this, m);
        break;
      case 'joined':
        toast(`${m.name}が冒険にやって来た！`);
        break;
      case 'left':
        toast(`${m.name}がひと休みしている`);
        break;
      case 'kicked':
        toast(m.text, 6000);
        this.leaveField();
        this.state = 'select';
        this.net.send({ t: 'hello', pw: (() => { try { return localStorage.getItem('kizuna_pw') || ''; } catch { return ''; } })() });
        break;
      case 'error':
        toast(m.text);
        this.audio.sfx('buzz');
        if (this.state === 'select' && this.pendingPlay) {
          this.pendingPlay = false;
          showCreate(this);
        }
        break;
      default:
    }
  }

  // ───────────── うごけない まま に ならない ための 見張り ─────────────
  // フィールドで 3びょう いじょう つづいたら なおす:
  //  ・だいほんが おわって いるのに「だいほん中」 ・何も 出ていないのに ボタンを うけとる ものが のこっている
  //  ・メニューが ないのに「メニュー中」 ・だいほんの そとで トロッコに のったまま ・まっくらの まま
  // なおせない（だいほんの とちゅうで まっている）ときは「動けない時はここ」ボタンを 出す（rescue）
  watchStuck(dt, canMove) {
    // 時計で はかる（画面の コマが おそい 端末でも おなじ 3びょう）
    const now = performance.now();
    const w = this.stuckT || (this.stuckT = {});
    const ui = document.getElementById('ui');
    // 見えている まど（会話・メニュー・お店・えらぶ ところ など）
    const shown = [...ui.children].some((x) => !x.hidden && x.id !== 'rescue' && x.getClientRects().length > 0);
    const curtain = document.getElementById('curtain');
    const dark = curtain?.classList.contains('on');
    const since = (k, on) => { w[k] = on ? (w[k] || now) : 0; return w[k] ? now - w[k] : 0; };
    if (since('busy', this.busy && !this.script.running && !this.battleClosing) > 3000) {
      w.busy = 0;
      reportError(this, new Error('busy without script'), 'stuck:busy');
      this.endScript();
    }
    if (since('input', !this.busy && this.input.busy && !shown) > 3000) {
      w.input = 0;
      reportError(this, new Error('input handler without window'), 'stuck:input');
      this.input.stack.length = 0;
    }
    if (since('menu', this.menuOpen && !shown) > 3000) {
      w.menu = 0;
      reportError(this, new Error('menu flag without window'), 'stuck:menu');
      this.menu.close();
      this.menuOpen = false;
    }
    if (since('ride', !!this.field.riding && !this.busy) > 3000) {
      w.ride = 0;
      reportError(this, new Error('cart ride outside script'), 'stuck:ride');
      const r = this.field.riding;
      this.field.riding = null;
      r?.resolve?.();
    }
    if (since('dark', dark && !this.busy && !this.battleClosing) > 3000) {
      w.dark = 0;
      curtain.classList.remove('on', 'flash');
    }
    // だいほんの とちゅうで 何も 出ないまま 長く とまっている・うごこうと しても うごけない: たすけの ボタン
    // （エンディングの ふりかえり〈ui/script.js の roll〉が 流れている 間は 止まっていない）
    const still = since('still', this.busy && this.script.running && !shown && !this.script.rolling);
    const push = since('push', !canMove && !shown && !!(this.input.dir.x || this.input.dir.y));
    if (still > 15000 || push > 4000) this.showRescue();
    else if (canMove && this.rescueBtn && !this.rescueBtn.hidden) this.rescueBtn.hidden = true;
  }

  // 戦いの 見張り: 自分の 番なのに コマンドの まどが 出ない まま → 出しなおす。それでも だめなら 立てなおす
  watchBattle() {
    const b = this.battle;
    const lost = !!b && !b.ended && !b.destroyed && !this.battleClosing && !b.menu && !b.invite && b.readyQ.some((id) => {
      const a = b.c.get(id);
      return a && a.alive && a.ready && !a.auto && !(a.status || []).some((x) => x === 'sleep' || x === 'paralyze');
    });
    if (!lost) {
      this.cmdLostAt = 0;
      this.cmdRetried = false;
      return;
    }
    const now = performance.now();
    if (!this.cmdLostAt) this.cmdLostAt = now;
    const t = now - this.cmdLostAt;
    if (t > 8000) {
      this.cmdLostAt = 0;
      this.cmdRetried = false;
      this.rescue();
    } else if (t > 2500 && !this.cmdRetried) {
      this.cmdRetried = true;
      reportError(this, new Error('command window lost'), 'stuck:battlecmd');
      b.nextCommand();
    }
  }

  // 「動けない時はここ」ボタン（見張りが 出す・メニューの 設定からも）
  showRescue() {
    if (!this.rescueBtn) {
      this.rescueBtn = el('button', { id: 'rescue', class: 'win rescue-btn', text: '動けない時はここをタップ', onclick: () => this.rescue() });
      document.getElementById('app').append(this.rescueBtn);
    }
    this.rescueBtn.hidden = false;
  }

  // 立てなおす: 画面の「とちゅう」を ぜんぶ かたづけて、サーバーから いまの ようすを もらいなおす
  // （つなぎなおしと おなじ。だいほんの とちゅう なら そこから もう一度。world.js の resync）
  rescue() {
    reportError(this, new Error(`rescue busy=${this.busy} menu=${this.menuOpen} input=${this.input.stack.length} script=${this.script.running}`), 'rescue');
    if (this.rescueBtn) this.rescueBtn.hidden = true;
    this.stuckT = null;
    const f = this.field;
    if (f) {
      const r = f.riding;
      f.riding = null;
      r?.resolve?.();
      f.slide = null;
      f.lookAt = null;
      f.hideMe = false;
      f.weatherOverride = null;
    }
    document.getElementById('curtain')?.classList.remove('on', 'flash');
    this.resetUI();
    if (this.state === 'field' || this.state === 'battle') this.net.send({ t: 'resync' });
    toast('立てなおしています…');
  }

  endScript() {
    this.busy = false;
    if (this.field) this.field.lookAt = null;
    this.sky.scriptEnd();
    this.scriptBgm = null;
    this.field.nightOverride = null;
    this.field.hideGuests = false;
    this.field.hideMe = false;
    this.field.weatherOverride = null;
  }

  // ようがんの 地面で ダメージ: 画面が 赤く 光る（はじめての ときだけ せつめい）
  onHurt(m) {
    // 第5章 Step 6: 大地の こどう（kind 'tremor' … ふるえ始めた・'rock' … 落石に 当たった。shared/world/tremor.js）。ことばは サーバーの toast
    if (m.kind === 'tremor') {
      this.audio.sfx('rumble');
      if (this.field) this.field.shakeT = 900;
      return;
    }
    if (m.kind === 'rock') {
      this.audio.sfx('hurt');
      if (this.field) this.field.shakeT = 400;
      const cr = document.getElementById('curtain');
      cr.classList.add('hurt');
      clearTimeout(this.hurtT);
      this.hurtT = setTimeout(() => cr.classList.remove('hurt'), 180);
      return;
    }
    this.audio.sfx('hurt');
    const c = document.getElementById('curtain');
    c.classList.add('hurt');
    clearTimeout(this.hurtT);
    this.hurtT = setTimeout(() => c.classList.remove('hurt'), 180);
    const now = performance.now();
    if (!(this.hurtToastAt > now - 20000)) {
      this.hurtToastAt = now;
      toast('あつい！ようがんの熱で、ダメージを受けた！\n（熱を防ぐ方法が、どこかにあるかもしれない…）', 4200);
    }
  }

  onWelcomeReady() {
    this.state = 'select';
    showSelect(this, this.chars || []);
  }

  // がめんの じょうたいを まっさらに する（つなぎなおし など）
  resetUI() {
    this.menu.close();
    this.script.reset();
    this.input.stack.length = 0;
    if (this.battle) {
      try {
        this.battle.destroy();
      } catch (e) {
        reportError(this, e, 'battle destroy');
      }
      this.battle = null;
    }
    this.battleClosing = false;
    this.battleWaiters = []; // まえの だいほんは つかわない（サーバーが いまの ところを おくりなおす）
    this.hud.stampBox = null;
    document.getElementById('ui').innerHTML = '';
    this.busy = false;
    this.scriptEnded = false;
  }

  onEnter(m) {
    this.resetUI();
    this.me = m.char;
    this.sid = m.sid;
    this.lastCharId = m.char.id;
    this.party = m.party;
    this.worldFlagSet = Array.isArray(m.party?.worldFlags) ? new Set(m.party.worldFlags) : null;
    this.worldVisited = Array.isArray(m.party?.worldVisited) ? new Set(m.party.worldVisited) : null;
    this.worldTreasure = Array.isArray(m.party?.worldTreasure) ? m.party.worldTreasure : null;
    this.players = m.players || [];
    this.posSeq = m.posSeq || 0;
    // サーバーの 時こく（昼・夜の 時計を あわせる）
    if (m.serverTime) this.timeOffset = m.serverTime - Date.now();
    this.sky.onEnter(m);
    this.busy = false;
    this.state = 'field';
    this.field.setMap(m.map, m.x, m.y, m.dir);
    this.hud.show(true);
    this.hud.renderParty();
    this.refreshObjective();
    this.audio.play(this.field.areaBgm());
    this.syncSceneAudio(true);
    this.keepAwake(true);
    if (m.rescued) toast('立てなおしました。動けるか、ためしてみてね', 5000);
    else if (m.resumed) toast('つなぎ直しました。続きから遊べます');
    // 家族の パーティーで 仲間に なった まもの（いない 間に 酒場へ 来た。world/recruit-share.js）
    for (const text of m.tavernNews || []) toast(text, 7000);
    boardOnEnter(this);
    for (const log of m.supportLog || []) {
      toast(`${log.helper}の冒険を${log.count}回手伝って\n経験値${log.exp}と${log.gold}ゴールドをもらった！${log.level ? `\nレベルが${log.level}に上がった！` : ''}`, 6000);
    }
    if (this.net.mode === 'offline' && !this.saveWarned) {
      this.saveWarned = true;
      const cloud = this.net.local?.cloud;
      import('./offline.js').then(({ offlineStorage }) => {
        offlineStorage.load();
        if (cloud?.state === 'on') return;
        if (!offlineStorage.ok) toast('このブラウザではセーブができないかもしれません', 5000);
        else if (cloud?.inViewer && cloud.state === 'off') toast('claude.aiにセーブできないので、このブラウザだけにセーブします。ブラウザを閉じると消えることがあるので、大事なキャラは引っこしコードをメモしておいてください', 8000);
      });
    }
  }

  async onBattleStart(m) {
    this.menu.close();
    this.closeFieldUI();
    if (this.battle) {
      this.battle.destroy();
      this.battle = null;
    }
    // フラッシュの 間に とどいた できごと（自分の 番が きた など）を 落とさないように とっておく
    const buf = [];
    this.battleEvBuf = buf;
    if (!m.resume) {
      this.audio.sfx('encounter');
      this.state = 'battle-intro';
      await this.flash();
    }
    if (this.battleEvBuf !== buf) return; // その 間に べつの 戦いが はじまった
    this.battleEvBuf = null;
    this.hud.show(false);
    this.field.clearLabels();
    this.state = 'battle';
    this.battle = new BattleScene(this, m);
    for (const x of buf) if (!x.id || x.id === this.battle.id) this.battle.onEvents(x.evs);
  }

  // 第77回 C: フィールドの 場面の 音（ダンジョンの 深さ・昼夜・まわりの音）。曲を 鳴らした すぐ あとは force
  syncSceneAudio(force = false) {
    if (!this.field?.map || !this.field.me || this.sceneAudioBroken) return;
    try {
      this.sceneAudio.syncField(this, performance.now(), force);
    } catch (e) {
      // こわれても 音楽は そのまま（1回だけ 記録）
      this.sceneAudioBroken = true;
      reportError(this, e, 'scene audio');
    }
  }

  closeFieldUI() {
    for (const p of document.querySelectorAll('#ui .panel, #ui .modal-back')) {
      if (!p.classList.contains('dialog')) p.remove();
    }
    this.input.stack.length = 0;
  }

  async onBattleEnd(m) {
    // はじまりの えんしゅつ中に おわった ときは、画面が できるのを まつ
    for (let i = 0; i < 40 && this.battleEvBuf && !this.battle; i++) await wait(50);
    const b = this.battle;
    if (!b) {
      this.net.send({ t: 'resultDone' });
      return;
    }
    this.battleClosing = true;
    // のこりの えんしゅつを まつ
    for (let i = 0; i < 100 && (b.queue.length || b.showing); i++) await wait(100);
    await wait(300);
    // けっかは ボタンで 1行ずつ（そのあいだ フィールドは うごかない。サーバーは またない）
    // まどが こわれても フィールドへ もどる（とまった まま に しない）
    try {
      await b.showResult(m);
    } catch (e) {
      reportError(this, e, 'result');
    }
    // 読みおわった（サーバー: つぎの たたかいに まきこめる ように なる・すこしだけ むてき）
    this.net.send({ t: 'resultDone' });
    // 読んでいる あいだに つぎの たたかいが はじまった（ものがたりの つづき など）: その 画面は そのまま
    if (this.battle !== b) return;
    await this.fade(true);
    try {
      b.destroy();
    } catch (e) {
      reportError(this, e, 'battle destroy');
    }
    this.battle = null;
    this.state = 'field';
    this.hud.show(true);
    this.invulnUntil = performance.now() + 2500;
    this.audio.play(this.scriptBgm && this.scriptBgm !== 'resume' ? this.scriptBgm : this.field.areaBgm(), { force: true });
    this.syncSceneAudio(true);
    await this.fade(false);
    this.battleClosing = false;
    const ws = this.battleWaiters || [];
    this.battleWaiters = [];
    for (const w of ws) w();
  }
}

js/client/input.js:
// キーボード・タッチ・ゲームパッドを まとめて あつかう
// ・フィールドでは input.dir（いどう）と A/B を つかう
// ・メニューでは スタックの いちばん うえの ハンドラーに up/down/left/right/a/b を とどける
// ・スマホで ウインドウ（えらぶ リスト）が 出ている ときは、十字キーと A/B の パッド（#pad）でも うごかせる
import { inStickZone as stickZone } from './ui/hand.js';
import { homeStickLayout, floatStickLayout, stickSideOf } from './ui/layout.js';

const KEYMAP = {
  ArrowUp: 'up', KeyW: 'up', ArrowDown: 'down', KeyS: 'down', ArrowLeft: 'left', KeyA: 'left', ArrowRight: 'right', KeyD: 'right',
  KeyZ: 'a', Enter: 'a', Space: 'a', NumpadEnter: 'a', KeyX: 'b', Escape: 'b', Backspace: 'b',
  KeyM: 'map', KeyC: 'chat', Tab: 'menu', KeyF: 'fly', KeyY: 'y',
  // 第35回: G … ゲームパッドの L と おなじ（大鳥・竜を 呼ぶ／空では 別の地方へ）
  KeyG: 'ride',
  // 第50回 N3: T … 大事な物の すぐ使う ボタン（時の砂時計 など。ui/quick-item.js）
  KeyT: 'quick',
  // 第69回: L・R … 戦いの 技えらびで 種類（タブ）を かえる（Q・E と PageUp・PageDown。ListMenu の onLR）
  KeyQ: 'l', KeyE: 'r', PageUp: 'l', PageDown: 'r',
};

export class Input {
  constructor() {
    this.held = new Set();
    this.stack = [];
    this.fieldHandler = null;
    this.stick = { x: 0, y: 0, active: false };
    this.pad = { prev: {}, dir: { x: 0, y: 0 }, repeat: {}, run: false };
    // 第50回 N3: 大事な物の ボタンの 番号（キャラの 設定。game.js が 入れる。-1 … なし。data/quick-item.js の QUICK_PADS）
    this.quickPad = 6;
    this.runToggle = false; // タッチの「はしる」ボタン（おすたびに ON/OFF）
    this.shift = false;
    this.touch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.onStack = null; // ウインドウが ひらいた・とじた（パッドを 出す・しまう）
    this.bindKeys();
    this.bindTouch();
    this.bindPad();
    if (this.touch) document.body.classList.add('touch');
    // iPhone: ピンチで がめんが かくだい されないように
    for (const ev of ['gesturestart', 'gesturechange', 'gestureend']) {
      document.addEventListener(ev, (e) => e.preventDefault(), { passive: false });
    }
  }

  // タッチの ボタンが かくれた ときなど（ゆびを はなした あつかい）
  releaseTouch() {
    this.endStick?.();
  }

  // メニューなどが じぶんの ハンドラーを のせる
  push(h) {
    this.stack.push(h);
    this.onStack?.();
    return h;
  }

  pop(h) {
    const i = this.stack.lastIndexOf(h);
    if (i >= 0) this.stack.splice(i, 1);
    this.onStack?.();
  }

  // がめんから 消えた ウインドウの ハンドラーを かたづける（el を もつ ものだけ）。
  // メニューを とじた あとに のこって、フィールドで 動けなくなる・スティックが 出ない のを ふせぐ
  prune(now = performance.now()) {
    let changed = false;
    for (let i = this.stack.length - 1; i >= 0; i--) {
      const h = this.stack[i];
      if (!h.el) continue;
      if (h.el.isConnected) { h.goneAt = 0; continue; }
      if (!h.goneAt) { h.goneAt = now; continue; }
      if (now - h.goneAt > 400) {
        this.stack.splice(i, 1);
        h.onGone?.();
        changed = true;
      }
    }
    if (changed) this.onStack?.();
  }

  // いちばん うえの ウインドウが 十字キーで うごかせる もの（リスト など）か
  get padWanted() {
    return !!this.stack[this.stack.length - 1]?.pad;
  }

  // パッドを 出すか（せっていで しまえる）
  get padOn() {
    try {
      return localStorage.getItem('kizuna_pad') !== 'off';
    } catch {
      return true;
    }
  }

  set padOn(on) {
    try {
      localStorage.setItem('kizuna_pad', on ? 'on' : 'off');
    } catch { /* */ }
    this.onStack?.();
  }
  get busy() { return this.stack.length > 0; }

  // hot: どの まどが 出ていても 先に うけとる（第35回: 戦いの SELECT・M。battle-pad.js）。true を かえすと そこで おわり
  emit(action, repeat = false) {
    if (!repeat && this.hot?.(action)) return;
    const top = this.stack[this.stack.length - 1];
    if (top) {
      top.onNav?.(action, repeat);
      return;
    }
    if (!repeat) this.fieldHandler?.(action);
  }

  // はしる？（Shift を おしている・はしるボタンが ON・ゲームパッドの X/R）
  get run() {
    return this.shift || this.runToggle || this.pad.run;
  }

  setRunToggle(on) {
    this.runToggle = !!on;
    document.getElementById('btn-run')?.classList.toggle('on', this.runToggle);
    try { localStorage.setItem('kizuna_run', this.runToggle ? '1' : ''); } catch { /* */ }
  }

  get dir() {
    let x = 0, y = 0;
    if (this.held.has('left')) x -= 1;
    if (this.held.has('right')) x += 1;
    if (this.held.has('up')) y -= 1;
    if (this.held.has('down')) y += 1;
    if (this.stick.active) {
      x += this.stick.x;
      y += this.stick.y;
    }
    x += this.pad.dir.x;
    y += this.pad.dir.y;
    const m = Math.hypot(x, y);
    if (m < 0.2) return { x: 0, y: 0 };
    if (m > 1) return { x: x / m, y: y / m };
    return { x, y };
  }

  bindKeys() {
    addEventListener('keydown', (e) => {
      if (e.key === 'Shift') this.shift = true;
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') {
        if (e.code === 'Escape') { document.activeElement.blur(); this.emit('b'); }
        return;
      }
      const a = KEYMAP[e.code];
      if (!a) return;
      e.preventDefault();
      const dirKey = ['up', 'down', 'left', 'right'].includes(a);
      if (dirKey) this.held.add(a);
      if (e.repeat && !dirKey) return;
      this.emit(a, e.repeat);
    });
    addEventListener('keyup', (e) => {
      if (e.key === 'Shift') this.shift = false;
      const a = KEYMAP[e.code];
      if (a) this.held.delete(a);
    });
    addEventListener('blur', () => { this.held.clear(); this.shift = false; });
  }

  bindTouch() {
    const touchEl = document.getElementById('touch');
    const stickEl = document.getElementById('stick');
    const knob = document.getElementById('stick-knob');
    const btnA = document.getElementById('btn-a');
    const btnB = document.getElementById('btn-b');
    const btnRun = document.getElementById('btn-run');
    let stickId = null;
    let origin = null;
    const R = 50;
    const field = document.getElementById('field');
    const field3d = document.getElementById('field3d');
    // スティックは さわった ところに でてくる（がめんの ひだり がわ）。はなすと もとの ばしょに もどる
    // 第64回: たて持ちの ならび（右手用・左手用・片手。ui/hand.js）で かわる
    // 第67回: 自分で ならべた ときは スティックの ある 側（ui/layout.js）
    const inStickZone = (t) => {
      const side = stickSideOf(innerWidth, innerHeight);
      if (side) return side === 'left' ? t.clientX < innerWidth * 0.6 : t.clientX > innerWidth * 0.4;
      return stickZone(t.clientX, t.clientY, innerWidth, innerHeight, document.body.dataset.hand);
    };
    const placeStick = (x, y) => {
      const r = touchEl.getBoundingClientRect();
      stickEl.style.left = `${x - r.left - stickEl.offsetWidth / 2}px`;
      stickEl.style.top = `${y - r.top - stickEl.offsetHeight / 2}px`;
      stickEl.style.bottom = 'auto';
      floatStickLayout(stickEl);
    };
    // もとの 場所へ（第67回: 自分で ならべた ときは その 場所。ui/layout.js）
    const homeStick = () => homeStickLayout(stickEl);
    const startStick = (t) => {
      stickId = t.identifier;
      origin = { x: t.clientX, y: t.clientY };
      placeStick(origin.x, origin.y);
      stickEl.classList.add('on', 'float');
      moveStick(t);
    };
    const moveStick = (t) => {
      let dx = t.clientX - origin.x, dy = t.clientY - origin.y;
      let m = Math.hypot(dx, dy);
      // ゆびが とおくへ いったら スティックも ついていく（むきを かえやすい）
      if (m > R * 1.6) {
        const k = (m - R * 1.6) / m;
        origin = { x: origin.x + dx * k, y: origin.y + dy * k };
        placeStick(origin.x, origin.y);
        dx = t.clientX - origin.x;
        dy = t.clientY - origin.y;
        m = Math.hypot(dx, dy);
      }
      if (m > R) {
        dx = dx / m * R;
        dy = dy / m * R;
      }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.stick = { x: dx / R, y: dy / R, active: true };
      // メニューでは スティックを たおすと カーソルが うごく
      if (this.busy) {
        const now = performance.now();
        const dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');
        if (m > R * 0.6 && (this.stickNav !== dir || now - this.stickNavAt > 260)) {
          this.emit(dir, this.stickNav === dir);
          this.stickNav = dir;
          this.stickNavAt = now;
        } else if (m < R * 0.3) this.stickNav = null;
      }
    };
    const endStick = () => {
      stickId = null;
      knob.style.transform = '';
      this.stick = { x: 0, y: 0, active: false };
      this.stickNav = null;
      stickEl.classList.remove('on', 'float');
      homeStick();
    };
    this.endStick = endStick;
    const onFieldTouch = (e) => {
      for (const t of e.changedTouches) {
        if (stickId === null && inStickZone(t)) startStick(t);
      }
      e.preventDefault();
    };
    field.addEventListener('touchstart', onFieldTouch, { passive: false });
    field3d?.addEventListener('touchstart', onFieldTouch, { passive: false });
    stickEl.addEventListener('touchstart', (e) => {
      for (const t of e.changedTouches) if (stickId === null) startStick(t);
      e.preventDefault();
    }, { passive: false });
    addEventListener('touchmove', (e) => {
      for (const t of e.changedTouches) if (t.identifier === stickId) moveStick(t);
    }, { passive: true });
    const end = (e) => {
      for (const t of e.changedTouches) if (t.identifier === stickId) endStick();
    };
    addEventListener('touchend', end);
    addEventListener('touchcancel', end);
    const bindBtn = (el, action) => {
      el.addEventListener('touchstart', (e) => {
        e.preventDefault();
        el.classList.add('on');
        this.emit(action);
      }, { passive: false });
      el.addEventListener('touchend', () => el.classList.remove('on'));
      el.addEventListener('mousedown', (e) => {
        e.preventDefault();
        this.emit(action);
      });
    };
    bindBtn(btnA, 'a');
    bindBtn(btnB, 'b');
    // はしる（おすたびに ON / OFF）
    if (btnRun) {
      const toggle = (e) => {
        e.preventDefault();
        this.setRunToggle(!this.runToggle);
      };
      btnRun.addEventListener('touchstart', toggle, { passive: false });
      btnRun.addEventListener('mousedown', toggle);
      try { if (localStorage.getItem('kizuna_run')) this.setRunToggle(true); } catch { /* */ }
    }
  }

  // ウインドウ用の パッド（十字キー・A・B）。おしっぱなしで くりかえし うごく
  bindPad() {
    const pad = document.createElement('div');
    pad.id = 'pad';
    pad.hidden = true;
    const key = (k, label, cls, aria) => {
      const b = document.createElement('button');
      b.className = cls;
      b.dataset.k = k;
      b.textContent = label;
      b.setAttribute('aria-label', aria);
      return b;
    };
    const cross = document.createElement('div');
    cross.id = 'pad-cross';
    cross.append(key('up', '▲', 'pk up', '上'), key('left', '◀', 'pk left', '左'), key('right', '▶', 'pk right', '右'), key('down', '▼', 'pk down', '下'));
    const ab = document.createElement('div');
    ab.id = 'pad-ab';
    ab.append(key('b', 'B', 'tbtn pb', 'もどる'), key('a', 'A', 'tbtn pa', '決定'));
    pad.append(cross, ab);
    document.getElementById('app')?.append(pad);
    this.padEl = pad;
    let rep = null;
    const stop = () => {
      clearTimeout(rep?.t);
      rep?.el.classList.remove('on');
      rep = null;
    };
    const press = (el) => {
      stop();
      const k = el.dataset.k;
      el.classList.add('on');
      this.emit(k);
      rep = { el, t: 0 };
      if (['up', 'down', 'left', 'right'].includes(k)) {
        const again = (ms) => {
          rep.t = setTimeout(() => {
            if (!rep || rep.el !== el) return;
            this.emit(k, true);
            again(110);
          }, ms);
        };
        again(330);
      }
    };
    for (const el of pad.querySelectorAll('button')) {
      el.addEventListener('touchstart', (e) => {
        e.preventDefault();
        press(el);
      }, { passive: false });
      el.addEventListener('mousedown', (e) => {
        e.preventDefault();
        press(el);
      });
    }
    for (const ev of ['touchend', 'touchcancel', 'mouseup', 'mouseleave']) pad.addEventListener(ev, stop);
    addEventListener('blur', stop);
    this.stopPad = stop;
  }

  // まいフレーム よぶ（ゲームパッド）
  update() {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    const gp = [...pads].find((p) => p && p.connected);
    // 第79回: コントローラーが つながって いるか（メニューの ヒントを コントローラー向けに する）
    this.pad.on = !!gp;
    if (!gp) {
      this.pad.dir = { x: 0, y: 0 };
      return;
    }
    const b = (i) => !!gp.buttons[i]?.pressed;
    let x = Math.abs(gp.axes[0]) > 0.25 ? gp.axes[0] : 0;
    let y = Math.abs(gp.axes[1]) > 0.25 ? gp.axes[1] : 0;
    if (b(14)) x = -1;
    if (b(15)) x = 1;
    if (b(12)) y = -1;
    if (b(13)) y = 1;
    this.pad.dir = { x, y };
    this.pad.run = b(2) || b(5) || b(7);
    const now = performance.now();
    const edge = (name, pressed) => {
      const was = this.pad.prev[name];
      this.pad.prev[name] = pressed;
      return pressed && !was;
    };
    if (edge('a', b(0))) this.emit('a');
    if (edge('b', b(1))) this.emit('b');
    // Y（3）: 長おしの かわり（戦いの 技の お気に入り。ListMenu の yKey）。ほかでは 今までどおり B
    // 第79回: ブラウザの ボタンの 番号は「場所」で きまる（0 下・1 右・2 左・3 上）。
    //   Xbox などは 上（3）が Y・左（2）が X だが、Switch の プロコンなどは 左（2）が Y・上（3）が X。
    //   前は 上（3）だけを Y に して いた ので、左に Y の ある コントローラーでは「Y」を おしても 何も おきなかった
    //   （覚えた技の 見方・道具の ならべかえ・戦いの お気に入り）。yKey の ある まどでは 左（2）・上（3）の どちらも Y に する。
    //   左（2）は ほかでは 走る（メニューや 戦いの 間は 何も しない）ので ぶつからない
    //   （ボタンごとに おした 時を みる。Y で まどが かわった あと、おした ままでも B に ならない）
    const yKey = !!this.stack[this.stack.length - 1]?.yKey;
    const start = edge('menu', b(9));
    const top = edge('top', b(3));
    const left = edge('left', b(2));
    if (yKey && (top || left)) this.emit('y');
    if (start || (!yKey && top)) this.emit('b');
    if (edge('map', b(8))) this.emit('map');
    // 第35回: L（4）… 大鳥・竜を 呼ぶ／空の 上では 別の地方へ（えらぶ まど）。降りるのは A（sky.js の padButton）
    // 第69回: 戦いの 技えらび（L・R を つかう まど。ListMenu の onLR）の 間は L・R で 種類（タブ）を かえる
    const lr = !!this.stack[this.stack.length - 1]?.lr;
    if (edge('ride', b(4))) this.emit(lr ? 'l' : 'ride');
    if (edge('r', b(5)) && lr) this.emit('r');
    // 第50回 N3: 大事な物の すぐ使う ボタン（ZL・L3・R3 から えらぶ。メニューの「設定」）
    if (edge('quick', this.quickPad >= 0 && b(this.quickPad))) this.emit('quick');
    if (this.busy) {
      const dir = Math.abs(x) > Math.abs(y) ? (x > 0.5 ? 'right' : x < -0.5 ? 'left' : null) : (y > 0.5 ? 'down' : y < -0.5 ? 'up' : null);
      if (dir) {
        const r = this.pad.repeat;
        if (r.dir !== dir) {
          r.dir = dir;
          r.at = now + 320;
          this.emit(dir);
        } else if (now > r.at) {
          r.at = now + 110;
          this.emit(dir, true);
        }
      } else this.pad.repeat.dir = null;
    }
  }
}

js/client/links.js:
// ひとりで遊ぶサイト（Webサイト）と 家族サーバーを 行き来する リンク
//
//   https://…/#kizuna=<引っこしコード>&server=<家族サーバーの アドレス>
//   http://192.168.…:3000/#kizuna=<引っこしコード>
// を 開くと、ログインの あとで「〇〇を連れてきますか？」と 聞く。
// server= は ひとりで遊ぶサイトが おぼえておく（つぎから「家族サーバーへ連れていく」ボタンが つかえる）。
//
// データを 合わせる リンク（sync.js・ui/syncui.js）
//   家族サーバー: http://…/#sync=<キャラの データ>            … 合わせて 保存する
//   サイト:       https://…/#sync=<データ>&back=<家族サーバー>  … 合わせたら、このスマホの データを 持って もどる

// ひとりで遊ぶサイト（GitHub Pages。家族サーバーの config.json の siteUrl で かえられる）
export const DEFAULT_SITE = 'https://koyamaryonetsu-arch.github.io/-DB/kizuna/';
const SERVER_KEY = 'kizuna_family_server';
const PENDING_KEY = 'kizuna_pending_import';
const SYNC_KEY = 'kizuna_pending_sync';
const BACK_KEY = 'kizuna_sync_back';
const ASK_SERVER_KEY = 'kizuna_ask_server';
const MINE_KEY = 'kizuna_mine';

// ページを 開いた ときに よぶ。リンクの 中みを しまって、アドレスバーからは 消す
export function readLinkHash(loc = globalThis.location, hist = globalThis.history) {
  const h = String(loc?.hash || '').replace(/^#/, '');
  if (!/(^|&)(kizuna|server|sync|back)=/.test(h)) return null;
  const params = new URLSearchParams(h);
  const code = params.get('kizuna');
  const sync = params.get('sync');
  const back = normalizeServer(params.get('back'));
  const server = normalizeServer(params.get('server'));
  // 家の 中の アドレス（192.168.… など）なら すぐ おぼえる。ちがう ときは 画面で たしかめてから
  try {
    if (server && (isHomeAddress(server) || server === familyServer())) localStorage.setItem(SERVER_KEY, server);
    else if (server) sessionStorage.setItem(ASK_SERVER_KEY, server);
  } catch { /* */ }
  try {
    if (code) sessionStorage.setItem(PENDING_KEY, code);
    if (sync !== null) sessionStorage.setItem(SYNC_KEY, sync);
    if (back) sessionStorage.setItem(BACK_KEY, back);
    else if (sync !== null) sessionStorage.removeItem(BACK_KEY);
  } catch { /* */ }
  try {
    hist?.replaceState(null, '', loc.pathname + loc.search);
  } catch { /* */ }
  return { code, server, sync, back };
}

// 家の 中（LAN）・Tailscale などの アドレスか（知らない サイトへ データを 送らない ため）
export function isHomeAddress(url) {
  let host = '';
  try {
    host = new URL(normalizeServer(url)).hostname.replace(/^\[|\]$/g, '').toLowerCase();
  } catch {
    return false;
  }
  if (!host) return false;
  if (host === 'localhost' || /\.(local|lan|home|internal|ts\.net)$/.test(host) || !host.includes('.') && !host.includes(':')) return true;
  const m = host.match(/^(\d+)\.(\d+)\.(\d+)\.(\d+)$/);
  if (m) {
    const [a, b] = [Number(m[1]), Number(m[2])];
    return a === 10 || a === 127 || (a === 192 && b === 168) || (a === 172 && b >= 16 && b <= 31) || (a === 169 && b === 254) || (a === 100 && b >= 64 && b <= 127);
  }
  return host === '::1' || /^f[cd][0-9a-f]{2}:/.test(host) || host.startsWith('fe80:');
}

// たしかめ待ちの 家族サーバーの アドレス（家の 外の アドレスが リンクで とどいた とき）
export function takeAskServer() {
  try {
    const s = sessionStorage.getItem(ASK_SERVER_KEY) || '';
    sessionStorage.removeItem(ASK_SERVER_KEY);
    return s;
  } catch {
    return '';
  }
}

// とどいた データ（合わせる）
export function pendingSync() {
  try {
    const text = sessionStorage.getItem(SYNC_KEY);
    return text === null ? null : { text, back: sessionStorage.getItem(BACK_KEY) || '' };
  } catch {
    return null;
  }
}

export function clearPendingSync() {
  try {
    sessionStorage.removeItem(SYNC_KEY);
    sessionStorage.removeItem(BACK_KEY);
  } catch { /* */ }
}

// データを 合わせる リンク
export function syncLink(base, { text = '', back = '', server = '' } = {}) {
  const b = String(base || '').split('#')[0];
  const parts = [`sync=${encodeURIComponent(text)}`];
  if (back) parts.push(`back=${encodeURIComponent(back)}`);
  if (server) parts.push(`server=${encodeURIComponent(server)}`);
  return `${b}${b.endsWith('/') ? '' : '/'}#${parts.join('&')}`;
}

// この スマホで 遊んだ キャラ（家族サーバーの 画面で おぼえる）
export function mineIds() {
  try {
    const a = JSON.parse(localStorage.getItem(MINE_KEY) || '[]');
    return Array.isArray(a) ? a.filter((x) => typeof x === 'string').slice(0, 12) : [];
  } catch {
    return [];
  }
}

export function rememberMine(ids) {
  const list = [...new Set([...(ids || []).filter((x) => typeof x === 'string'), ...mineIds()])].slice(0, 12);
  try {
    localStorage.setItem(MINE_KEY, JSON.stringify(list));
  } catch { /* */ }
  return list;
}

export function pendingImport() {
  try {
    return sessionStorage.getItem(PENDING_KEY) || '';
  } catch {
    return '';
  }
}

export function clearPendingImport() {
  try {
    sessionStorage.removeItem(PENDING_KEY);
  } catch { /* */ }
}

// 「192.168.1.23:3000」→「http://192.168.1.23:3000」
export function normalizeServer(text) {
  let t = String(text || '').trim().replace(/\/+$/, '');
  if (!t) return '';
  if (!/^https?:\/\//i.test(t)) t = 'http://' + t;
  try {
    const u = new URL(t);
    if (!/^https?:$/.test(u.protocol) || !u.hostname) return '';
    return `${u.protocol}//${u.host}`;
  } catch {
    return '';
  }
}

export function familyServer() {
  try {
    return localStorage.getItem(SERVER_KEY) || '';
  } catch {
    return '';
  }
}

export function setFamilyServer(text) {
  const s = normalizeServer(text);
  if (!s) return '';
  try {
    localStorage.setItem(SERVER_KEY, s);
  } catch { /* */ }
  return s;
}

// 家族サーバーへ（ひとりで遊ぶサイトから）
export function linkToFamilyServer(server, code) {
  return `${normalizeServer(server)}/#kizuna=${encodeURIComponent(code)}`;
}

// ひとりで遊ぶサイトへ（家族サーバーから）。server … 家族サーバーの アドレス（おぼえてもらう）
export function linkToSite(site, { code = '', server = '' } = {}) {
  const base = String(site || DEFAULT_SITE).split('#')[0];
  const parts = [];
  if (code) parts.push(`kizuna=${encodeURIComponent(code)}`);
  if (server) parts.push(`server=${encodeURIComponent(server)}`);
  return parts.length ? `${base}#${parts.join('&')}` : base;
}

// この 家族サーバーを、ほかの スマホから 開く アドレス
export function serverAddress(net, loc = globalThis.location) {
  const here = loc?.origin || '';
  const local = /^https?:\/\/(localhost|127\.|\[::1\])/i.test(here);
  if (!local && here) return here;
  return (net?.urls || [])[0] || here;
}

// ひとりで遊ぶサイトに 覚えてもらう 家族サーバーの アドレス
// 外出先からも 開ける https の アドレス（Tailscale Funnel）が あれば そちら（家でも 外でも 開ける・動いているか サイトで 分かる）
export function siteServerAddress(net, loc = globalThis.location) {
  return net?.public || serverAddress(net, loc);
}

js/client/music-amb.js:
// 第77回 A: まわりの 音（環境音）。音楽の 下に うすく ながす ループ（音の ファイルは つかわない）
//   waves（波）・wind（風）・market（市場の ざわめき）・fire（たき火）・cave_drip（洞窟の しずく）・rain（雨）
//   startAmbience(engine, dest, id) → { id, pump(until), stop(fade) }
//   ノードは つねに 10こ ほど ＋ ときどき 鳴る 小さな 音（しずく・パチパチ）

export const AMBIENCES = ['waves', 'wind', 'market', 'fire', 'cave_drip', 'rain'];

// 長めの ざあざあ（1びょうの くりかえしが 聞こえない ように 4びょう）
function longNoise(eng) {
  if (eng.ambNoise) return eng.ambNoise;
  const ctx = eng.ctx;
  const len = ctx.sampleRate * 4;
  const b = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = b.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = eng.rand() * 2 - 1;
  eng.ambNoise = b;
  return b;
}

export function startAmbience(eng, dest, id) {
  if (!AMBIENCES.includes(id)) return null;
  const ctx = eng.ctx;
  const t0 = ctx.currentTime;
  const R = eng.rand;
  const master = ctx.createGain();
  master.gain.setValueAtTime(0, t0);
  master.gain.setTargetAtTime(1, t0, 0.5);
  master.connect(dest);
  const srcs = [];
  const loop = (filters, level) => {
    const s = ctx.createBufferSource();
    s.buffer = longNoise(eng);
    s.loop = true;
    let head = s;
    for (const [type, f, q] of filters) {
      const fl = ctx.createBiquadFilter();
      fl.type = type;
      fl.frequency.value = f;
      fl.Q.value = q ?? 0.7;
      head.connect(fl);
      head = fl;
    }
    const g = ctx.createGain();
    g.gain.value = level;
    head.connect(g);
    g.connect(master);
    s.start(t0, R() * 3);
    srcs.push(s);
    return { s, g, filter: head === s ? null : head };
  };
  const lfo = (rate, depth, param) => {
    const o = ctx.createOscillator();
    o.frequency.value = rate;
    const g = ctx.createGain();
    g.gain.value = depth;
    o.connect(g);
    g.connect(param);
    o.start(t0);
    srcs.push(o);
  };
  // ときどき 鳴る 小さな 音
  const blip = (t, { type = 'sine', f0, f1, dec, vol, toRev = 0 }) => {
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f0, t);
    o.frequency.exponentialRampToValueAtTime(f1, t + dec * 0.6);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0005, t + dec);
    o.connect(g);
    g.connect(master);
    if (toRev && eng.bus) {
      const s = ctx.createGain();
      s.gain.value = toRev;
      g.connect(s);
      s.connect(eng.bus.revIn);
    }
    o.start(t);
    o.stop(t + dec + 0.02);
  };
  const tick = (t, f, dec, vol) => {
    const s = ctx.createBufferSource();
    s.buffer = longNoise(eng);
    const fl = ctx.createBiquadFilter();
    fl.type = 'highpass';
    fl.frequency.value = f;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0005, t + dec);
    s.connect(fl);
    fl.connect(g);
    g.connect(master);
    s.start(t, R() * 3);
    s.stop(t + dec + 0.02);
  };
  let next = t0 + 0.3;
  let event = () => 1;
  let murmur = null;
  switch (id) {
    case 'waves': {
      const low = loop([['lowpass', 520, 0.5]], 0.09);
      const hiss = loop([['bandpass', 1900, 0.4]], 0.025);
      lfo(0.085, 0.075, low.g.gain);
      lfo(0.085, 0.022, hiss.g.gain);
      break;
    }
    case 'wind': {
      const w = loop([['bandpass', 520, 2.5]], 0.11);
      lfo(0.07, 320, w.filter.frequency);
      lfo(0.13, 0.08, w.g.gain);
      break;
    }
    case 'rain': {
      loop([['highpass', 1400], ['lowpass', 7000]], 0.045);
      event = (t) => {
        blip(t, { f0: 2200 + R() * 2400, f1: 1500, dec: 0.03, vol: 0.012 + R() * 0.012 });
        return 0.04 + R() * 0.09;
      };
      break;
    }
    case 'fire': {
      loop([['lowpass', 320]], 0.07);
      event = (t) => {
        tick(t, 2500 + R() * 3000, 0.008 + R() * 0.02, 0.04 + R() * 0.06);
        return 0.06 + R() * 0.35;
      };
      break;
    }
    case 'cave_drip': {
      loop([['lowpass', 160]], 0.06);
      event = (t) => {
        const f = 1100 + R() * 900;
        blip(t, { f0: f, f1: f * 0.62, dec: 0.16, vol: 0.05 + R() * 0.03, toRev: 0.9 });
        return 0.8 + R() * 2.2;
      };
      break;
    }
    case 'market': {
      murmur = loop([['bandpass', 650, 0.9]], 0.05);
      event = (t) => {
        // ざわざわ（大きさを ゆらす）と 話し声の ような 小さな 音・ときどき チリン
        murmur.g.gain.setTargetAtTime(0.03 + R() * 0.05, t, 0.06);
        if (R() < 0.6) {
          const f = 220 + R() * 260;
          blip(t + R() * 0.05, { type: 'triangle', f0: f, f1: f * (0.8 + R() * 0.4), dec: 0.08 + R() * 0.08, vol: 0.012 + R() * 0.01 });
        }
        if (R() < 0.03) blip(t, { f0: 2400 + R() * 600, f1: 2300, dec: 0.5, vol: 0.02 });
        return 0.12 + R() * 0.12;
      };
      break;
    }
    default: break;
  }
  return {
    id,
    pump(until) {
      let guard = 0;
      while (next < until && guard++ < 5000) {
        if (next < ctx.currentTime) next = ctx.currentTime + 0.02;
        next += event(next);
      }
    },
    stop(fade = 1.5) {
      const t = ctx.currentTime;
      master.gain.cancelScheduledValues(t);
      master.gain.setValueAtTime(master.gain.value, t);
      master.gain.setTargetAtTime(0, t, fade / 3);
      for (const s of srcs) { try { s.stop(t + fade * 1.5); } catch { /* */ } }
      setTimeout(() => { try { master.disconnect(); } catch { /* */ } }, fade * 1500 + 300);
      next = Infinity;
    },
  };
}

js/client/music-engine.js:
// 第77回 A: 音楽の エンジン（Web Audio。どの BaseAudioContext でも 動く … AudioContext・OfflineAudioContext）
//
//   new MusicEngine(ctx, dest, { mode, quality, adaptive, trims })
//     mode    … 'new'（新しい音）・'old'（前の音。第76回までと まったく 同じ 鳴らし方 … LegacyPlayer）
//     quality … 'fine'（きれい）・'light'（かるい … 厚みの 重ねと 残きょうを 止める）
//   engine.start(id, track) / stop(fade) / pump(until) / done()
//   engine.playAmbience(id) / stopAmbience()
//
// 曲の データの 書き方・楽器・場面で かわる 音楽の つかい方は docs/plan-r77-audio.md（チーム B・C との やくそく）。
// このファイルは 画面（window）を さわらない。node の テストでも 読みこめる（AudioContext が なければ 何も 鳴らさない）。
import { INSTRUMENTS, defaultInstrument, ROLE_PAN, HARMONY_PANS, ROLE_SEND, DEFAULT_NIGHT, WAVE_LEVEL } from './music-inst.js';
import { startAmbience } from './music-amb.js';

export const NOTE_BASE = { C: 0, 'C#': 1, Db: 1, D: 2, 'D#': 3, Eb: 3, E: 4, F: 5, 'F#': 6, Gb: 6, G: 7, 'G#': 8, Ab: 8, A: 9, 'A#': 10, Bb: 10, B: 11 };

export function freqOf(name) {
  const m = /^([A-G][#b]?)(-?\d)$/.exec(name);
  if (!m) return 0;
  const n = NOTE_BASE[m[1]] + (Number(m[2]) + 1) * 12;
  return 440 * Math.pow(2, (n - 69) / 12);
}

export const midiOf = (f) => 69 + 12 * Math.log2(f / 440);

// ───────────── 楽譜を 読む ─────────────
// 前の 読み方（第76回までと 同じ。前の音 で つかう）: 'C5:4 D5:2 r:2' → [{f, len}]
export function legacyParse(str) {
  return str.trim().split(/\s+/).map((tok) => {
    const [n, l] = tok.split(':');
    const len = Number(l || 4);
    if (n === 'r') return { f: 0, len };
    if (['k', 's', 'h'].includes(n)) return { drum: n, len };
    return { f: freqOf(n), len };
  });
}

// たいこの 名前（rim は R と 同じ）
export const DRUMS = ['k', 's', 'h', 'o', 'c', 'p', 't', 'th', 'tl', 'R'];
const DRUM_SET = new Set([...DRUMS, 'rim']);
const ACCENT = 1.35;
const GHOST = 0.5;

// 新しい 読み方（前の 書き方は 同じ 結果。ふえた 書き方:
//   C5:4!  アクセント（強く）   C5:4?  ゴースト（弱く）   C5:4~  タイ（次が 同じ 音なら つなぐ・ちがう 音なら レガート）
//   C5:4.  スタッカート（短く）  [C4 E4 G4]:8  和音   たいこ: k s h o（オープン） c（シンバル） p（クラップ） t th tl（タム） R（リム）
export function parseNotes(str) {
  const toks = String(str ?? '').trim().match(/\[[^\]]*\](?::\S*)?|\S+/g) || [];
  const out = [];
  let tiePrev = false;
  for (const tok of toks) {
    let name;
    let rest = '';
    if (tok[0] === '[') {
      const j = tok.indexOf(']');
      name = tok.slice(0, j + 1);
      rest = tok.slice(j + 1);
      if (rest[0] === ':') rest = rest.slice(1);
    } else {
      const k = tok.indexOf(':');
      if (k < 0) {
        const mm = /^(.*?)([!?~.]*)$/.exec(tok);
        name = mm[1];
        rest = mm[2];
      } else {
        name = tok.slice(0, k);
        rest = tok.slice(k + 1).split(':')[0];
      }
    }
    const mm = /^(.*?)([!?~.]*)$/.exec(rest);
    const len = Number(mm[1] || 4);
    const mods = mm[2];
    const ev = { len };
    if (name === 'r') ev.f = 0;
    else if (DRUM_SET.has(name)) ev.drum = name === 'rim' ? 'R' : name;
    else if (name[0] === '[') {
      const fs = name.slice(1, -1).trim().split(/\s+/).map(freqOf).filter((f) => f > 0);
      ev.f = fs[0] || 0;
      if (fs.length > 1) ev.fs = fs;
    } else ev.f = freqOf(name);
    if (mods.includes('!')) ev.acc = ACCENT;
    else if (mods.includes('?')) ev.acc = GHOST;
    if (mods.includes('.')) ev.stac = true;
    const tie = mods.includes('~');
    const prev = out[out.length - 1];
    if (tiePrev && prev) {
      if (!ev.drum && ev.f && samePitch(prev, ev)) {
        prev.len += ev.len;
        tiePrev = tie;
        continue;
      }
      prev.leg = true;
    }
    tiePrev = tie;
    out.push(ev);
  }
  if (tiePrev && out.length) out[out.length - 1].leg = true;
  return out;
}

function samePitch(a, b) {
  const fa = a.fs || [a.f];
  const fb = b.fs || [b.f];
  return fa.length === fb.length && fa.every((f, i) => Math.abs(f - fb[i]) < 0.01);
}

// ───────────── 曲を 組み立てる（形・役わり・楽器） ─────────────
// 古い 曲の ベースは 大きめ（三角波 0.22 前後）なので 少し 下げる（ほかの パートが 聞こえる ように）
const LEGACY_BASS = 0.8;
const ROLE_MIN_INTENSITY = { lead: 0, bass: 0, harmony: 0.3, drums: 0.55 };
export const DEFAULT_PHASES = [
  { transpose: 0, tempo: 1 },
  { transpose: 1, tempo: 1.06 },
  { transpose: 2, tempo: 1.12 },
  { transpose: 3, tempo: 1.16 },
];

const compiled = new WeakMap();

function partStats(events) {
  let w = 0;
  let sum = 0;
  let notes = 0;
  let lenSum = 0;
  for (const e of events) {
    if (e.drum || !e.f) continue;
    const m = midiOf(e.f);
    sum += m * e.len;
    w += e.len;
    notes++;
    lenSum += e.len;
  }
  return { avg: w ? sum / w : 0, avgLen: notes ? lenSum / notes : 0, notes };
}

// 1小節の 長さ（16分音符の かず）。bar が なければ たいこの キックの 場所から 4/4（16）か 6/8・3/4（12）かを きめる
function detectBar(tr, partsEvents, total) {
  if (tr.bar) return tr.bar;
  const di = partsEvents.findIndex((p) => p.drums);
  if (di >= 0) {
    const score = (B) => {
      let pos = 0;
      let hit = 0;
      let all = 0;
      for (const e of partsEvents[di].events) {
        if (e.drum === 'k') {
          all++;
          if (pos % B === 0) hit++;
        }
        pos += e.len;
      }
      return all ? hit / all : 0;
    };
    const s16 = score(16);
    const s12 = score(12);
    if (s12 > s16 + 0.15 && total % 12 === 0) return 12;
    return 16;
  }
  return total % 16 !== 0 && total % 12 === 0 ? 12 : 16;
}

// 曲の データ → エンジンが つかう 形（キャッシュ）。曲の データは かえない
export function compileTrack(tr) {
  if (compiled.has(tr)) return compiled.get(tr);
  let partDefs;
  let secSrc;
  let form;
  let loopFrom;
  if (tr.sections) {
    const names = Object.keys(tr.sections);
    const first = tr.sections[names[0]];
    const firstList = Array.isArray(first) ? first : first.ch;
    partDefs = (tr.parts || tr.ch || firstList.map((e) => (typeof e === 'string' ? {} : e))).map((c) => ({ ...c }));
    secSrc = {};
    for (const nm of names) {
      const s = tr.sections[nm];
      const list = Array.isArray(s) ? s : s.ch;
      secSrc[nm] = {
        bpm: Array.isArray(s) ? undefined : s.bpm,
        notes: partDefs.map((_, i) => {
          const e = list[i];
          if (e == null) return '';
          return typeof e === 'string' ? e : e.n || '';
        }),
      };
    }
    form = (tr.form || names).filter((n) => secSrc[n]);
    loopFrom = Math.max(0, Math.min(form.length - 1, tr.loopFrom ?? 0));
  } else {
    partDefs = tr.ch.map((c) => ({ ...c }));
    secSrc = { main: { notes: tr.ch.map((c) => c.n) } };
    form = ['main'];
    loopFrom = 0;
  }
  // 区切りごとに 読む
  const segs = {};
  for (const [nm, s] of Object.entries(secSrc)) {
    const parts = s.notes.map((n) => parseNotes(n));
    const steps = Math.max(1, ...parts.map((p) => p.reduce((a, e) => a + e.len, 0)));
    segs[nm] = { name: nm, bpm: s.bpm, steps, parts };
  }
  // 役わり（さいしょの 区切りで きめる）
  const firstSeg = segs[form[0]];
  const allEvents = partDefs.map((p, i) => Object.values(segs).flatMap((s) => s.parts[i]));
  const stats = allEvents.map((ev) => partStats(ev));
  const melodic = partDefs.map((p, i) => i).filter((i) => !partDefs[i].drums && stats[i].notes > 0);
  const roles = partDefs.map((p) => (p.drums ? 'drums' : p.role || null));
  let leadIdx = roles.findIndex((r) => r === 'lead');
  if (leadIdx < 0 && melodic.length) {
    leadIdx = melodic.find((i) => !roles[i]) ?? -1;
    if (leadIdx >= 0) roles[leadIdx] = 'lead';
  }
  if (!roles.includes('bass')) {
    const cand = melodic.filter((i) => !roles[i]).sort((a, b) => stats[a].avg - stats[b].avg)[0];
    if (cand !== undefined && stats[cand].avg < 57) roles[cand] = 'bass';
  }
  for (let i = 0; i < roles.length; i++) if (!roles[i]) roles[i] = 'harmony';
  let hi = 0;
  const bar = detectBar(tr, partDefs.map((p, i) => ({ drums: !!p.drums, events: firstSeg.parts[i] })), firstSeg.steps);
  const parts = partDefs.map((p, i) => {
    const role = roles[i];
    const st = stats[i];
    const style = st.avgLen >= 8 ? 'long' : st.avgLen <= 2.6 ? 'short' : 'mid';
    const high = st.avg >= 76;
    const inst = p.drums ? null : (INSTRUMENTS[p.i] ? p.i : defaultInstrument(p.w, role, { style, high }));
    let pan = p.pan;
    if (pan === undefined) pan = role === 'harmony' ? HARMONY_PANS[hi++ % HARMONY_PANS.length] : ROLE_PAN[role] ?? 0;
    const minI = p.minIntensity ?? (p.layer != null ? Math.min(1, p.layer * 0.25) : ROLE_MIN_INTENSITY[role] ?? 0);
    return {
      idx: i, drums: !!p.drums, w: p.w, inst, v: (p.v ?? 0.1) * (p.drums || !p.w ? 1 : (WAVE_LEVEL[p.w] ?? 1) * (role === 'bass' ? LEGACY_BASS : 1)), pan, role, style, high, avg: st.avg,
      minI, send: p.send ?? ROLE_SEND[role] ?? 1, oct: p.oct || 0,
    };
  });
  // 主音（ピンチの 重ねに つかう）: ベースの 長さで いちばん 多い 音
  const bassIdx = parts.findIndex((p) => p.role === 'bass');
  const pc = new Array(12).fill(0);
  for (const e of (bassIdx >= 0 ? allEvents[bassIdx] : allEvents[leadIdx] || [])) if (e.f) pc[Math.round(midiOf(e.f)) % 12] += e.len;
  const tonic = pc.indexOf(Math.max(...pc));
  const once = !!tr.once;
  const bpm = tr.bpm || 120;
  const c = {
    src: tr, bpm, once, bar, parts, segs, form, loopFrom, tonic,
    auto: tr.auto ?? (!tr.sections && !once),
    swing: Math.max(0, Math.min(0.3, tr.swing || 0)),
    reverb: tr.reverb ?? (once ? 0.3 : bpm >= 150 ? 0.16 : bpm < 96 ? 0.34 : 0.24),
    fill: tr.fill || 0,
    night: tr.night || DEFAULT_NIGHT,
    pinch: tr.pinch || null,
    phases: tr.phases || DEFAULT_PHASES,
    transpose: tr.transpose || 0,
    leadIdx: parts.findIndex((p) => p.role === 'lead'),
    drumIdx: parts.findIndex((p) => p.drums),
    expanded: new Map(),
  };
  compiled.set(tr, c);
  return c;
}

// 区切りの 次（form の 次。さいごまで 行ったら loopFrom へ もどって loop を 1つ ふやす。once の 曲は おわり）
export function nextPos(c, pos, loop) {
  if (pos + 1 < c.form.length) return { pos: pos + 1, loop, ended: false };
  if (c.once) return { pos, loop, ended: true };
  return { pos: c.loopFrom, loop: loop + 1, ended: false };
}

// 曲の はじめから n こ 分の 区切りの ならび（[区切りの 名前, 何回目の くりかえし]）。テストと 書き出しの どうぐ用
export function formWalk(c, n) {
  const out = [];
  let pos = 0;
  let loop = 0;
  for (let i = 0; i < n; i++) {
    out.push([c.form[pos], loop]);
    const nx = nextPos(c, pos, loop);
    if (nx.ended) break;
    pos = nx.pos;
    loop = nx.loop;
  }
  return out;
}

// 拍の 強さ（小節の 頭を 少し 強く・うらを 少し 弱く）
export function beatAccent(step, bar) {
  if (step % bar === 0) return 1.12;
  if (bar % 2 === 0 && step % (bar / 2) === 0) return 1.05;
  if (step % 4 === 0) return 1;
  if (step % 2 === 0) return 0.94;
  return 0.88;
}

// フィルイン（小節の 後ろ 半分）。16 → 8つ、12 → 6つ
function fillPattern(win) {
  const pat = win >= 8 ? ['s', 's', 's', 's', 'th', 'th', 'tl', 'tl'] : ['s', 's', 'th', 'th', 'tl', 'tl'];
  const n = Math.min(pat.length, Math.floor(win));
  return pat.slice(0, n).map((d, i) => ({ drum: d, off: win - n + i, vel: 0.6 + 0.4 * (i / Math.max(1, n - 1)) }));
}

// 1回分（区切り × くりかえしの 何回目）を 小節ごとの 音の リストに。同じ 入力なら いつも 同じ 結果（キャッシュ）
//   variant … 自動アレンジの 何回目か（0〜3）。auto: false の 曲は いつも 0
//   item: { p, step, len, fs, vel, gate, leg, drum, inst, octShift }
export function expandPass(c, segName, variant = 0) {
  const key = `${segName}:${variant}`;
  if (c.expanded.has(key)) return c.expanded.get(key);
  const seg = c.segs[segName];
  const B = c.bar;
  const nBars = Math.ceil(seg.steps / B);
  const bars = Array.from({ length: nBars }, () => []);
  const v = c.auto ? variant % 4 : 0;
  const lead = c.leadIdx;
  const push = (it) => {
    const b = Math.min(nBars - 1, Math.floor(it.step / B));
    bars[b].push(it);
  };
  seg.parts.forEach((events, p) => {
    const part = c.parts[p];
    if (!part) return;
    let step = 0;
    for (const e of events) {
      const at = step;
      step += e.len;
      if (e.drum) {
        let d = e.drum;
        let vel = (e.acc ?? 1) * beatAccent(at, B);
        if (v === 2) {
          if (d === 's') d = 'R';
          if (d === 'h' || d === 'o') vel *= 0.7;
        }
        push({ p, step: at, len: e.len, drum: d, vel });
        if (v === 3 && d === 's') push({ p, step: at, len: e.len, drum: 'p', vel: vel * 0.55 });
        continue;
      }
      if (!e.f) continue;
      const fs = e.fs || [e.f];
      let vel = (e.acc ?? 1) * beatAccent(at, B);
      let gate = e.stac ? 0.45 : e.leg ? 1.02 : null;
      let inst = part.inst;
      // 2回目: ハーモニーの 楽器を かえる（はじく 音 → マリンバ など）
      if (v === 1 && part.role === 'harmony') inst = INSTRUMENTS[part.inst]?.alt || part.inst;
      if (v === 2) {
        if (part.role === 'harmony') vel *= 0.55;
        if (part.role === 'bass' && gate === null) gate = 0.6;
        if (p === lead) inst = INSTRUMENTS[part.inst]?.alt || part.inst;
      }
      push({ p, step: at, len: e.len, fs, vel, gate, leg: !!e.leg, inst });
      // 2回目・4回目: メロディに 1オクターブの 重ね（高い 曲は 下へ）
      if ((v === 1 || v === 3) && p === lead) {
        push({ p, step: at, len: e.len, fs, vel: vel * 0.4, gate, leg: !!e.leg, inst, octShift: part.avg >= 79 ? -12 : 12, layer: true });
      }
    }
  });
  // フィルイン・シンバル（たいこの パートが ある 曲だけ）
  if (c.drumIdx >= 0) {
    const fillBars = new Set();
    if (c.fill) for (let b = 0; b < nBars; b++) if ((b + 1) % c.fill === 0) fillBars.add(b);
    if (v === 1 || v === 3) fillBars.add(nBars - 1);
    for (const b of fillBars) {
      const bs = b * B;
      const bLen = Math.min(B, seg.steps - bs);
      const win = Math.floor(bLen / 2);
      const from = bs + bLen - win;
      bars[b] = bars[b].filter((it) => !(it.drum && it.step >= from));
      for (const f of fillPattern(win)) bars[b].push({ p: c.drumIdx, step: from + f.off, len: 1, drum: f.drum, vel: f.vel });
    }
    if (v === 1 || v === 3) bars[0].push({ p: c.drumIdx, step: 0, len: 4, drum: 'c', vel: 0.8 });
  }
  for (const list of bars) list.sort((a, b) => a.step - b.step || a.p - b.p);
  const res = { steps: seg.steps, bars, bpm: seg.bpm };
  c.expanded.set(key, res);
  return res;
}

// ───────────── 場面で かわる 音楽（チーム C の つかう ところ） ─────────────
// set〜 は「次の 小節の 頭」で 効く（latch）。強さは 曲ごとに おぼえる（戦いの あとに ダンジョンの 曲へ もどっても そのまま）
export class AdaptiveState {
  constructor() {
    this.want = { intensity: 1, pinch: false, phase: 0, tod: 'day' };
    this.cur = { ...this.want };
    this.byTrack = new Map();
    this.track = null;
  }

  setIntensity(x) {
    const v = Number(x);
    this.want.intensity = Number.isFinite(v) ? Math.max(0, Math.min(1, v)) : 1;
    if (this.track) this.byTrack.set(this.track, this.want.intensity);
  }

  setPinch(on) { this.want.pinch = !!on; }

  setPhase(n) {
    const v = Math.round(Number(n));
    this.want.phase = Number.isFinite(v) ? Math.max(0, Math.min(3, v)) : 0;
  }

  setTimeOfDay(tod) { this.want.tod = tod === 'night' ? 'night' : 'day'; }

  // 曲が かわった（ピンチ・だんは もとに。強さは その 曲で 前に きめた 値。昼夜は そのまま）
  onTrack(id) {
    this.track = id;
    this.want.pinch = false;
    this.want.phase = 0;
    this.want.intensity = this.byTrack.get(id) ?? 1;
    this.cur = { ...this.want };
  }

  latch() {
    this.cur = { ...this.want };
    return this.cur;
  }
}

// テンポを 1小節ごとに 目標へ 1/3 ずつ 近づける（ぴったりに なったら おわり）
export function nextTempo(cur, target) {
  const d = target - cur;
  if (Math.abs(d) < 0.004) return target;
  return cur + d / 3;
}

export function phaseOf(c, n) {
  const list = c.phases;
  return list[Math.max(0, Math.min(list.length - 1, n))] || { transpose: 0, tempo: 1 };
}

// スイング: 8分の うらを おくらせる（1拍 = 16分 4つ の 中で）
export function swingPos(x, s) {
  if (!s) return x;
  const beat = Math.floor(x / 4);
  const q = x - beat * 4;
  return beat * 4 + (q <= 2 ? q * (1 + s) : 2 + 2 * s + (q - 2) * (1 - s));
}

// ───────────── 音を 作る（ノード） ─────────────
const NATIVE = { sine: 'sine', triangle: 'triangle', sawtooth: 'sawtooth', square: 'square', pulse50: 'square' };
const WAVE_HARM = {
  soft: [1, 0.28, 0.1, 0.04],
  organ: [1, 0.7, 0.45, 0, 0.3, 0, 0, 0.22],
  warm: [1, 0.42, 0.22, 0.12, 0.07, 0.04, 0.02],
};

function legacyWaveType(w) {
  if (w === 'pulse') return 'pulse25';
  if (w === 'saw') return 'sawtooth';
  if (w === 'square') return 'pulse50';
  return w || 'pulse25';
}

// 小さな らんすう（同じ たねなら 同じ ならび。曲の くりかえしが 毎回 同じに 聞こえる ため・テストの ため）
export function rng(seed = 1) {
  let s = seed >>> 0 || 1;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeImpulse(ctx, sec = 1.7, seed = 7) {
  const sr = ctx.sampleRate;
  const len = Math.floor(sr * sec);
  const buf = ctx.createBuffer(2, len, sr);
  const r = rng(seed);
  for (let ch = 0; ch < 2; ch++) {
    const d = buf.getChannelData(ch);
    let lp = 0;
    for (let i = 0; i < len; i++) {
      const tt = i / sr;
      // 時間が たつほど こもる（高い 音から 消える）
      const k = 0.55 - 0.45 * Math.min(1, tt / sec);
      lp += k * ((r() * 2 - 1) - lp);
      const pre = tt < 0.012 ? tt / 0.012 : 1;
      d[i] = lp * Math.exp(-tt * 3.6) * pre;
    }
  }
  return buf;
}

function softClipCurve() {
  const n = 2048;
  const c = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * 2 - 1;
    const a = Math.abs(x);
    // 0.6 までは そのまま、それより 上は なめらかに 0.97 へ
    const y = a <= 0.6 ? a : 0.6 + 0.37 * Math.tanh((a - 0.6) / 0.37);
    c[i] = Math.sign(x) * y;
  }
  return c;
}

// 音楽の 通り道（全部の 曲で 1つ）: 曲 → ピンチの 明るさ → コンプ → リミッター → やわらかい クリップ → dest
//                                    残きょう（1つの ConvolverNode）→ コンプ
export function createBus(ctx, dest, quality = 'fine') {
  const input = ctx.createGain();
  const tension = ctx.createBiquadFilter();
  tension.type = 'peaking';
  tension.frequency.value = 2800;
  tension.Q.value = 0.8;
  tension.gain.value = 0;
  // 明るさ（高い 音を 少し 前へ。ねむく ならない ように）
  const air = ctx.createBiquadFilter();
  air.type = 'highshelf';
  air.frequency.value = 4500;
  air.gain.value = 3;
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -20;
  comp.knee.value = 10;
  comp.ratio.value = 3;
  comp.attack.value = 0.006;
  comp.release.value = 0.22;
  const makeup = ctx.createGain();
  // コンプは 自動で 音を 大きく する ので、ここで もどす（前の音と だいたい 同じ 大きさに。曲ごとの そろえは audio-trim.js）
  makeup.gain.value = 0.55;
  const lim = ctx.createDynamicsCompressor();
  lim.threshold.value = -5;
  lim.knee.value = 2;
  lim.ratio.value = 20;
  lim.attack.value = 0.001;
  lim.release.value = 0.09;
  const clip = ctx.createWaveShaper();
  clip.curve = softClipCurve();
  input.connect(tension);
  tension.connect(air);
  air.connect(comp);
  comp.connect(makeup);
  makeup.connect(lim);
  lim.connect(clip);
  clip.connect(dest);
  const revIn = ctx.createGain();
  const revOut = ctx.createGain();
  revOut.gain.value = 0.85;
  let conv = null;
  const bus = {
    input, tension, comp, revIn, revOut, ambIn: ctx.createGain(),
    setQuality(q) {
      try { revIn.disconnect(); } catch { /* */ }
      if (q === 'light') return;
      if (!conv) {
        conv = ctx.createConvolver();
        conv.buffer = makeImpulse(ctx);
        conv.connect(revOut);
        revOut.connect(comp);
      }
      revIn.connect(conv);
    },
  };
  bus.ambIn.connect(comp);
  bus.setQuality(quality);
  return bus;
}

// ───────────── 新しい音の 曲 ─────────────
const DRUM_GAIN = 1;
// たいこごとの 大きさ（前の 音より 少し 大きく。--calib で はかった）
const DRUM_LEVEL = { k: 0.6, s: 0.45, h: 0.5, o: 0.45, c: 0.45, p: 0.5, t: 0.6, th: 0.6, tl: 0.6, R: 0.6 };

class NewPlayer {
  constructor(eng, id, tr, at) {
    this.eng = eng;
    this.ctx = eng.ctx;
    this.id = id;
    this.c = compileTrack(tr);
    this.pos = 0;
    this.loop = 0;
    this.bar = 0;
    this.t = at;
    this.tempo = 1;
    this.transpose = 0;
    this.ended = false;
    this.endT = Infinity;
    this.pinchStep = 0;
    const ctx = this.ctx;
    const trim = Math.pow(10, (eng.trims?.[id] || 0) / 20);
    this.out = ctx.createGain();
    this.out.gain.value = trim;
    this.out.connect(eng.bus.input);
    this.rev = ctx.createGain();
    this.rev.gain.value = trim;
    this.rev.connect(eng.bus.revIn);
    this.strips = this.c.parts.map((p) => this.strip(p.pan, this.c.reverb * p.send));
    this.on = this.c.parts.map(() => true);
    this.hat = this.strip(0.3, this.c.reverb * 0.3);
    this.hatOn = true;
    this.pinchStrip = null;
    this.night = false;
  }

  strip(pan, send) {
    const ctx = this.ctx;
    const g = ctx.createGain();
    let pn = null;
    if (ctx.createStereoPanner) {
      pn = ctx.createStereoPanner();
      pn.pan.value = pan;
      g.connect(pn);
    }
    const tail = pn || g;
    const s = ctx.createGain();
    s.gain.value = send;
    tail.connect(this.out);
    tail.connect(s);
    s.connect(this.rev);
    return { g, pn, s, base: send };
  }

  stop(fade) {
    const t = this.ctx.currentTime;
    for (const n of [this.out, this.rev]) {
      try {
        n.gain.cancelScheduledValues(t);
        n.gain.setValueAtTime(n.gain.value, t);
        n.gain.setTargetAtTime(0, t, Math.max(0.01, fade / 3));
      } catch { /* */ }
    }
    const { out, rev } = this;
    setTimeout(() => { try { out.disconnect(); rev.disconnect(); } catch { /* */ } }, fade * 1000 + 300);
    this.ended = true;
    this.endT = 0;
  }

  done(now) { return this.ended && now > this.endT; }

  pump(until, now = -Infinity) {
    let guard = 0;
    while (!this.ended && this.t < until && guard++ < 512) this.stepBar(now);
  }

  stepBar(now) {
    const c = this.c;
    const segName = c.form[this.pos];
    const ex = expandPass(c, segName, this.loop);
    const B = c.bar;
    const bs = this.bar * B;
    const barSteps = Math.min(B, ex.steps - bs);
    const st = this.eng.adaptive ? this.eng.adaptive.latch() : { intensity: 1, pinch: false, phase: 0, tod: 'day' };
    const ph = phaseOf(c, st.phase);
    this.tempo = nextTempo(this.tempo, ph.tempo || 1);
    this.transpose = (ph.transpose || 0) + c.transpose;
    const bpm = (ex.bpm || c.bpm) * this.tempo;
    const spb = 60 / bpm / 4;
    const t0 = this.t;
    const barDur = swingPos(barSteps, c.swing) * spb;
    const light = this.eng.quality === 'light';
    // 強さ・夜・ピンチ（小節の 頭で なめらかに）
    const night = st.tod === 'night';
    c.parts.forEach((p, i) => {
      const on = st.intensity >= p.minI - 1e-9;
      const str = this.strips[i];
      if (on !== this.on[i]) {
        str.g.gain.setTargetAtTime(on ? 1 : 0, t0, 0.04);
        this.on[i] = on;
      }
      if (night !== this.night) str.s.gain.setTargetAtTime(str.base * (night ? 1.5 : 1) + (night ? 0.08 : 0), t0, 0.1);
    });
    // ハイハットも たいこと いっしょに（たいこの パートが 2つ ある 曲は、どちらかが 鳴って いれば 鳴らす）
    const hatOn = c.parts.some((p, i) => p.drums && this.on[i]);
    if (hatOn !== this.hatOn) {
      this.hat.g.gain.setTargetAtTime(hatOn ? 1 : 0, t0, 0.04);
      this.hatOn = hatOn;
    }
    this.night = night;
    this.eng.setTension(st.pinch, t0);
    const late = now > t0 + barDur;
    if (late) this.eng.lateBars++;
    else {
      const tmul = Math.pow(2, this.transpose / 12);
      for (const it of ex.bars[this.bar] || []) {
        const p = c.parts[it.p];
        if (!this.on[it.p]) continue;
        if (it.layer && st.intensity < 0.8) continue;
        const rel = it.step - bs;
        const ts = t0 + swingPos(rel, c.swing) * spb;
        if (ts < now) {
          this.eng.dropped++;
          continue;
        }
        const dur = (swingPos(rel + it.len, c.swing) - swingPos(rel, c.swing)) * spb;
        if (it.drum) {
          const dest = (it.drum === 'h' || it.drum === 'o') ? this.hat.g : this.strips[it.p].g;
          let vel = p.v * it.vel * DRUM_GAIN;
          if (night) vel *= 0.65;
          this.eng.drum(it.drum, ts, vel, dest);
          continue;
        }
        let inst = it.inst || p.inst;
        if (night) inst = nightInst(c, p, inst);
        const mul = tmul * Math.pow(2, ((p.oct || 0) * 12 + (it.octShift || 0)) / 12);
        const fs = it.fs;
        const vel = (p.v * it.vel) / Math.sqrt(fs.length);
        for (const f of fs.slice(0, 4)) {
          this.eng.voice(f * mul, ts, dur, inst, vel, this.strips[it.p].g, { gate: it.gate, leg: it.leg, light, night, legacyW: p.w });
        }
      }
      if (st.pinch) this.pinchBar(t0, barSteps, spb, tmul);
    }
    this.pinchStep += barSteps;
    this.t = t0 + barDur;
    this.bar++;
    if (bs + barSteps >= ex.steps) {
      this.bar = 0;
      const nx = nextPos(c, this.pos, this.loop);
      this.pos = nx.pos;
      this.loop = nx.loop;
      if (nx.ended) {
        this.ended = true;
        this.endT = this.t;
      }
    }
  }

  // ピンチの 重ね: 高い 音で 主音と 半音上を 8分で きざむ（曲に pinch: { n, i, v } が あれば それを くりかえす）
  pinchBar(t0, steps, spb, tmul) {
    const c = this.c;
    if (!this.pinchStrip) this.pinchStrip = this.strip(0.38, c.reverb * 0.6);
    const g = this.pinchStrip.g;
    if (c.pinch?.n) {
      if (!this.pinchSeq) {
        let at = 0;
        const on = [];
        for (const e of parseNotes(c.pinch.n)) {
          if (e.f) on.push({ at, e });
          at += e.len;
        }
        this.pinchSeq = { on, total: at || 1 };
      }
      const { on, total } = this.pinchSeq;
      const a0 = this.pinchStep;
      for (let k = Math.floor(a0 / total); k * total < a0 + steps; k++) {
        for (const { at, e } of on) {
          const x = at + k * total;
          if (x < a0 || x >= a0 + steps) continue;
          for (const f of e.fs || [e.f]) {
            this.eng.voice(f * tmul, t0 + (x - a0) * spb, e.len * spb, c.pinch.i || 'chip_arp', (c.pinch.v || 0.035) * (e.acc ?? 1), g, { light: this.eng.quality === 'light' });
          }
        }
      }
      return;
    }
    const root = 72 + c.tonic + 12;
    for (let s = 0; s < steps; s += 2) {
      const m = root + (((this.pinchStep + s) / 2) % 2 ? 1 : 0);
      const f = 440 * Math.pow(2, (m - 69) / 12);
      this.eng.voice(f * tmul, t0 + s * spb, 2 * spb, 'chip_arp', 0.03 * (s % 4 === 0 ? 1.15 : 0.85), g, { light: true });
    }
  }
}

function nightInst(c, p, inst) {
  const m = c.night || {};
  if (m[p.idx] && INSTRUMENTS[m[p.idx]]) return m[p.idx];
  if (m[inst] && INSTRUMENTS[m[inst]]) return m[inst];
  if (m[p.role] && INSTRUMENTS[m[p.role]]) return m[p.role];
  return inst;
}

// ───────────── 前の音（第76回までの 鳴らし方を そのまま） ─────────────
const OLD_TOKEN = /^(r|[kshr]|[A-G][#b]?-?\d)(:\d+)?$/;
const LEGACY_DRUM = { k: 'k', s: 's', h: 'h', o: 'h', c: 'h', p: 's', R: 's', t: 'k', th: 'k', tl: 'k' };

// 前の音で 鳴らす チャンネル: tr.legacy（チーム B が 作りなおした 曲の 前の データ）→ tr.ch → 区切りを つなげた もの
export function legacyChannels(tr) {
  if (tr.legacy?.ch) return { bpm: tr.legacy.bpm || tr.bpm, ch: tr.legacy.ch };
  if (tr.ch) return { bpm: tr.bpm, ch: tr.ch };
  const c = compileTrack(tr);
  const ch = c.parts.map((p, i) => ({
    w: p.drums ? undefined : (p.w || 'square'),
    drums: p.drums || undefined,
    v: p.v,
    n: c.form.map((nm) => tr.sections[nm] && (Array.isArray(tr.sections[nm]) ? tr.sections[nm][i] : tr.sections[nm].ch[i])).map((e) => (typeof e === 'string' ? e : e?.n || '')).join(' '),
  }));
  return { bpm: tr.bpm, ch };
}

function legacySeq(str) {
  const toks = String(str || '').trim().split(/\s+/).filter(Boolean);
  if (toks.every((t) => OLD_TOKEN.test(t))) return legacyParse(str);
  // 新しい 書き方 → 前の 形へ（和音は 1音ずつ・ふえた たいこは k/s/h に）
  return parseNotes(str).flatMap((e) => {
    if (e.drum) return [{ drum: LEGACY_DRUM[e.drum] || 's', len: e.len }];
    if (e.fs) return e.fs.map((f, i) => ({ f, len: i === e.fs.length - 1 ? e.len : 0, hold: e.len }));
    return [{ f: e.f || 0, len: e.len }];
  });
}

class LegacyPlayer {
  constructor(eng, id, tr, at) {
    this.eng = eng;
    this.ctx = eng.ctx;
    this.id = id;
    const lc = legacyChannels(tr);
    const spb = 60 / lc.bpm / 4; // 16ぶおんぷ の びょう
    const out = this.ctx.createGain();
    out.gain.value = 1;
    out.connect(eng.dest);
    this.m = {
      id, tr, spb, out,
      chans: lc.ch.map((c) => ({ ...c, seq: legacySeq(c.n), i: 0, t: at })),
      once: !!tr.once,
    };
  }

  stop(fade) {
    const m = this.m;
    try {
      m.out.gain.setTargetAtTime(0, this.ctx.currentTime, fade / 3);
      setTimeout(() => m.out.disconnect(), fade * 1000 + 200);
    } catch { /* */ }
    this.stopped = true;
  }

  pump(until) {
    const m = this.m;
    if (this.stopped) return;
    for (const ch of m.chans) {
      while (ch.t < until) {
        if (ch.i >= ch.seq.length) {
          if (m.once) break;
          ch.i = 0;
        }
        const n = ch.seq[ch.i++];
        const dur = n.len * m.spb;
        // ドラムの パートの r は やすみ（音を 出さない）
        if (ch.drums) { if (n.drum) this.eng.legacyDrum(n.drum, ch.t, ch.v, m.out); }
        else if (n.f) this.eng.legacyNote(n.f, ch.t, n.hold ? n.hold * m.spb : dur, ch.w, ch.v, m.out);
        ch.t += dur;
      }
    }
  }

  done(now) {
    const m = this.m;
    if (this.stopped) return true;
    if (!m.once) return false;
    const allDone = m.chans.every((c) => c.i >= c.seq.length);
    return allDone && now > Math.max(...m.chans.map((c) => c.t));
  }
}

// ───────────── エンジン ─────────────
export class MusicEngine {
  // dest … 音量の ノード（GameAudio の musicGain）。trims … 曲ごとの 音量の そろえ（dB。新しい音だけ）
  constructor(ctx, dest, { mode = 'new', quality = 'fine', adaptive = null, trims = {}, seed = 1, offline = null } = {}) {
    this.ctx = ctx;
    // オフライン（書き出し）では「おくれ」を 見ない
    this.offline = offline ?? (typeof OfflineAudioContext !== 'undefined' && ctx instanceof OfflineAudioContext);
    this.lateBars = 0;
    this.dropped = 0;
    this.dest = dest;
    this.mode = mode === 'old' ? 'old' : 'new';
    this.quality = quality === 'light' ? 'light' : 'fine';
    this.adaptive = adaptive || new AdaptiveState();
    this.trims = trims;
    this.rand = rng(seed);
    this.player = null;
    this.amb = null;
    this.tensionOn = false;
    // 前の音の 波（第76回までと 同じ）
    const real = new Float32Array(32), imag = new Float32Array(32);
    for (let n = 1; n < 32; n++) imag[n] = (2 / (n * Math.PI)) * Math.sin(n * Math.PI * 0.25);
    this.pulseWave = ctx.createPeriodicWave(real, imag);
    const len = ctx.sampleRate;
    this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.waves = {};
    this.bus = null;
  }

  ensureBus() {
    if (!this.bus) this.bus = createBus(this.ctx, this.dest, this.quality);
    return this.bus;
  }

  wave(type) {
    if (this.waves[type]) return this.waves[type];
    const real = new Float32Array(32), imag = new Float32Array(32);
    if (type === 'pulse25' || type === 'pulse12') {
      const duty = type === 'pulse25' ? 0.25 : 0.125;
      for (let n = 1; n < 32; n++) imag[n] = (2 / (n * Math.PI)) * Math.sin(n * Math.PI * duty);
    } else {
      (WAVE_HARM[type] || [1]).forEach((a, i) => { imag[i + 1] = a; });
    }
    this.waves[type] = this.ctx.createPeriodicWave(real, imag);
    return this.waves[type];
  }

  setOsc(o, type) {
    if (NATIVE[type]) o.type = NATIVE[type];
    else o.setPeriodicWave(this.wave(type));
  }

  setQuality(q) {
    this.quality = q === 'light' ? 'light' : 'fine';
    if (this.bus) this.bus.setQuality(this.quality);
  }

  start(id, tr, at = null) {
    this.stop(0.25);
    if (!tr) return;
    const t = at ?? this.ctx.currentTime + 0.08;
    this.adaptive.onTrack(id);
    if (this.mode === 'old') {
      this.player = new LegacyPlayer(this, id, tr, t);
    } else {
      this.ensureBus();
      this.player = new NewPlayer(this, id, tr, t);
    }
  }

  stop(fade = 0.25) {
    if (!this.player) return;
    const p = this.player;
    this.player = null;
    p.stop(fade);
    if (this.bus && this.tensionOn) this.setTension(false, this.ctx.currentTime);
  }

  // until まで 音を 予約する（ふだんは 今 ＋ 0.2びょう。オフラインで 書き出す ときは 曲の さいごまで）
  pump(until) {
    const now = this.ctx.currentTime;
    if (this.player) this.player.pump(until, this.offline ? -Infinity : now);
    if (this.amb) this.amb.pump(until);
  }

  done() { return !!this.player && this.player.done(this.ctx.currentTime); }

  setTension(on, t) {
    if (!this.bus || on === this.tensionOn) return;
    this.tensionOn = on;
    this.bus.tension.gain.setTargetAtTime(on ? 4.5 : 0, t, 0.08);
  }

  // ── 環境音（波・風・市場・たき火・洞窟の しずく・雨）──
  playAmbience(id) {
    if (this.amb?.id === id) return;
    this.stopAmbience();
    if (!id || this.mode === 'old') return;
    const bus = this.ensureBus();
    this.amb = startAmbience(this, bus.ambIn, id);
  }

  stopAmbience(fade = 1.5) {
    if (!this.amb) return;
    this.amb.stop(fade);
    this.amb = null;
  }

  // ── 1音（新しい音）──
  //   f … Hz、t … はじまり、dur … 長さ（秒）、inst … 楽器の 名前、vel … 音量、dest … チャンネルの ノード
  voice(f, t, dur, inst, vel, dest, { gate = null, leg = false, light = false, night = false, legacyW = null } = {}) {
    const ctx = this.ctx;
    const P = INSTRUMENTS[inst] || INSTRUMENTS.lead;
    // osc: 'auto' の 楽器（lead・pluck）は 古い 波を そのまま つかう。gain は pulse で はかった ので、
    // ほかの 波（square など 大きい 波）は その ぶん 小さく（v の WAVE_LEVEL と 二重に ならない ように）
    const norm = P.osc === 'auto' ? WAVE_LEVEL.pulse / (WAVE_LEVEL[legacyW || 'pulse'] ?? 1) : 1;
    const peak = vel * (P.gain ?? 1) * norm;
    if (!(peak > 0) || !(f > 0) || f > 12000) return;
    const a = Math.max(P.a, leg ? 0.02 : 0);
    let rel;
    if (P.ring) rel = t + Math.min(Math.max(dur, 0.12), P.d * 1.5);
    else rel = t + Math.max(a + 0.012, dur * (gate ?? P.gate ?? 0.92));
    const stopAt = rel + P.r * 2.6 + 0.02;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(peak, t + a);
    g.gain.setTargetAtTime(peak * P.s, t + a, Math.max(0.005, P.d / 3));
    g.gain.setTargetAtTime(0, rel, Math.max(0.005, P.r / 3));
    const type = P.osc === 'auto' ? legacyWaveType(legacyW) : P.osc;
    const o = ctx.createOscillator();
    this.setOsc(o, type);
    o.frequency.value = f;
    let head = o;
    let filt = null;
    if (P.filter) {
      filt = ctx.createBiquadFilter();
      filt.type = P.filter.type || 'lowpass';
      filt.Q.value = P.filter.q ?? 0.7;
      const base = Math.min(16000, P.filter.f * Math.pow(f / 261.6, P.filter.key ?? 0) * (night ? 0.7 : 1));
      const top = Math.min(18000, base + (P.filter.env || 0));
      filt.frequency.setValueAtTime(top, t);
      filt.frequency.setTargetAtTime(base, t + a * 0.5, Math.max(0.01, (P.filter.decay || 0.2) / 3));
      o.connect(filt);
      head = filt;
    }
    head.connect(g);
    g.connect(dest);
    const oscs = [o];
    let o2 = null;
    let det2 = 0;
    if (P.fm) {
      const mod = ctx.createOscillator();
      mod.type = 'sine';
      mod.frequency.value = f * P.fm.ratio;
      const mg = ctx.createGain();
      const dev = P.fm.index * f * P.fm.ratio;
      mg.gain.setValueAtTime(dev, t);
      mg.gain.setTargetAtTime(dev * 0.12, t, Math.max(0.01, P.fm.decay / 3));
      mod.connect(mg);
      mg.connect(o.frequency);
      oscs.push(mod);
    } else if (P.osc2 && !(light && !P.osc2.oct)) {
      o2 = ctx.createOscillator();
      const t2 = P.osc2.type === 'auto' ? type : P.osc2.type;
      this.setOsc(o2, t2);
      o2.frequency.value = f * Math.pow(2, (P.osc2.oct || 0) / 12);
      det2 = P.osc2.detune || 0;
      o2.detune.value = det2;
      const mix = P.osc2.mix ?? 1;
      if (mix < 0.999) {
        const mg = ctx.createGain();
        mg.gain.value = mix;
        o2.connect(mg);
        mg.connect(filt || g);
      } else o2.connect(filt || g);
      oscs.push(o2);
    }
    // ビブラート（ノードを ふやさず detune の カーブで）
    if (P.vib && rel - t > P.vib.delay + 0.08) {
      const vs = t + P.vib.delay;
      const vd = stopAt - vs;
      const n = Math.max(8, Math.min(400, Math.ceil(vd * P.vib.rate * 8)));
      const curve = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        const tt = (i / (n - 1)) * vd;
        curve[i] = P.vib.depth * Math.sin(2 * Math.PI * P.vib.rate * tt) * Math.min(1, tt / 0.3);
      }
      try {
        o.detune.setValueCurveAtTime(curve, vs, vd);
        if (o2) o2.detune.setValueCurveAtTime(curve.map((x) => x + det2), vs, vd);
      } catch { /* */ }
    }
    for (const x of oscs) {
      // ずらした 重ね（ユニゾン）は 1/4 周期 おくらせて はじめる（短い 音で 2つが そろって 大きく なりすぎない ように）
      x.start(x === o2 && P.osc2.detune && !P.osc2.oct ? t + 0.25 / f : t);
      x.stop(stopAt);
    }
  }

  // ── たいこ（新しい音）──
  noise(t, dur, { type = 'highpass', f = 7000, q = 0.7 } = {}) {
    const ctx = this.ctx;
    const s = ctx.createBufferSource();
    s.buffer = this.noiseBuf;
    const fl = ctx.createBiquadFilter();
    fl.type = type;
    fl.frequency.value = f;
    fl.Q.value = q;
    s.connect(fl);
    s.start(t, this.rand() * 0.5);
    s.stop(t + dur + 0.03);
    return fl;
  }

  drum(kind, t, vel0, dest) {
    const ctx = this.ctx;
    const vel = vel0 * (DRUM_LEVEL[kind] ?? 0.6);
    const light = this.quality === 'light';
    const env = (src, peak, dec, attack = 0.001) => {
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(peak, t + attack);
      g.gain.exponentialRampToValueAtTime(0.0008, t + dec);
      src.connect(g);
      g.connect(dest);
      return g;
    };
    const tone = (type, f0, f1, sweep, peak, dec) => {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.setValueAtTime(f0, t);
      o.frequency.exponentialRampToValueAtTime(f1, t + sweep);
      env(o, peak, dec, 0.002);
      o.start(t);
      o.stop(t + dec + 0.02);
    };
    switch (kind) {
      case 'k':
        tone('sine', 190, 46, 0.09, vel * 1.25, 0.32);
        if (!light) env(this.noise(t, 0.02, { type: 'lowpass', f: 2600 }), vel * 0.25, 0.018);
        break;
      case 's':
        env(this.noise(t, 0.2, { type: 'bandpass', f: 2000, q: 0.7 }), vel * 0.75, 0.17);
        if (!light) tone('triangle', 200, 150, 0.05, vel * 0.4, 0.09);
        break;
      case 'h':
        env(this.noise(t, 0.05, { type: 'highpass', f: 7500 }), vel * 0.42, 0.045);
        break;
      case 'o':
        env(this.noise(t, 0.3, { type: 'highpass', f: 6500 }), vel * 0.32, 0.28);
        break;
      case 'c':
        env(this.noise(t, 1.4, { type: 'highpass', f: 4200 }), vel * 0.3, 1.3, 0.002);
        break;
      case 'p': {
        const src = this.noise(t, 0.2, { type: 'bandpass', f: 1300, q: 1.4 });
        const g = ctx.createGain();
        g.gain.setValueAtTime(0, t);
        for (const k of [0, 0.011, 0.022]) {
          g.gain.setValueAtTime(vel * 0.8, t + k);
          g.gain.exponentialRampToValueAtTime(vel * 0.12, t + k + 0.01);
        }
        g.gain.exponentialRampToValueAtTime(0.0008, t + 0.16);
        src.connect(g);
        g.connect(dest);
        break;
      }
      case 't': tone('sine', 150, 96, 0.12, vel * 0.95, 0.28); break;
      case 'th': tone('sine', 215, 140, 0.11, vel * 0.9, 0.24); break;
      case 'tl': tone('sine', 108, 68, 0.13, vel * 1, 0.32); break;
      case 'R':
        tone('triangle', 1750, 1600, 0.02, vel * 0.35, 0.035);
        if (!light) env(this.noise(t, 0.03, { type: 'bandpass', f: 3200, q: 1.5 }), vel * 0.3, 0.025);
        break;
      default: break;
    }
  }

  // ── 前の音の 1音・たいこ（第76回までの note()・drum() を そのまま）──
  legacyNote(f, t, dur, wave, vol, out) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    if (wave === 'pulse') o.setPeriodicWave(this.pulseWave);
    else o.type = wave === 'saw' ? 'sawtooth' : wave || 'square';
    o.frequency.value = f;
    const g = ctx.createGain();
    const len = Math.max(0.05, dur * 0.92);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.01);
    g.gain.setTargetAtTime(vol * (wave === 'triangle' ? 0.8 : 0.55), t + 0.02, 0.08);
    g.gain.setTargetAtTime(0, t + len - 0.03, 0.02);
    let node = o;
    if (wave === 'saw') {
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 1400;
      o.connect(lp);
      node = lp;
    }
    node.connect(g);
    g.connect(out);
    o.start(t);
    o.stop(t + len + 0.05);
  }

  legacyDrum(kind, t, vol, out) {
    const ctx = this.ctx;
    if (kind === 'k') {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.frequency.setValueAtTime(150, t);
      o.frequency.exponentialRampToValueAtTime(40, t + 0.12);
      g.gain.setValueAtTime(vol * 0.9, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
      o.connect(g); g.connect(out);
      o.start(t); o.stop(t + 0.16);
    } else {
      const s = ctx.createBufferSource();
      s.buffer = this.noiseBuf;
      const f = ctx.createBiquadFilter();
      f.type = kind === 'h' ? 'highpass' : 'bandpass';
      f.frequency.value = kind === 'h' ? 7000 : 1800;
      const g = ctx.createGain();
      const d = kind === 'h' ? 0.04 : 0.12;
      g.gain.setValueAtTime(vol * (kind === 'h' ? 0.25 : 0.45), t);
      g.gain.exponentialRampToValueAtTime(0.001, t + d);
      s.connect(f); f.connect(g); g.connect(out);
      s.start(t, Math.random() * 0.5); s.stop(t + d + 0.02);
    }
  }
}

// 話す 人の 名前 → 文字の 音の 高さ（Hz）。同じ 名前は いつも 同じ 高さ
const BLIP_STEPS = [0, 2, 4, 7, 9, 12, 14, 16, 19];
export function blipFreq(seed) {
  let h = 2166136261;
  const s = String(seed ?? '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const k = BLIP_STEPS[(h >>> 0) % BLIP_STEPS.length];
  return 523.25 * Math.pow(2, k / 12);
}

