          for (let i = 0; i <= 5; i++) { const a = a0 + i * 0.35, rr = r * (1.05 + 0.35 * hash(f + i)); i ? x.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr) : x.moveTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr); }
