    const env = envOf(p, 90, 160);
    if (env <= 0) return;
    const ang = Math.atan2(p.y1 - p.y0, p.x1 - p.x0);
    const L = Math.hypot(p.x1 - p.x0, p.y1 - p.y0) + p.over;
