// ───────────── つぶの かきかた ─────────────
export const G2_FINE = {
  // らせん丸（青い チャクラの 玉。中で うずの 線が 高速回転）。blades … 風の 刃 4まい（らせん手裏剣）。cols … [こい, 中, あかるい, しん]
  g2Spiral(x, p) {
    const [cx, cy, r0] = kf(p.keys, p.age, p.ease);
    const a = envOf(p, 60, p.fout || 140);
    const r = r0 * (1 + 0.05 * Math.sin(p.age / 30));
    if (!(r > 0.4) || a <= 0) return;
