          const P = (rad, d) => [cx + Math.cos(th + d) * rad, cy + Math.sin(th + d) * rad * (p.sy || 0.8)];
          x.beginPath();
          x.moveTo(...P(r * 0.85, -0.45));
          x.quadraticCurveTo(...P(r * 2.1 * bl, -0.15), ...P(r * 3.1 * bl, 0.5));
          x.quadraticCurveTo(...P(r * 1.75 * bl, 0.22), ...P(r * 0.85, 0.4));
