      x.strokeStyle = '#ffffff';
      x.lineWidth = 0.7;
      x.beginPath(); x.ellipse(cx, cy, r * 2.9 * bl, r * 2.9 * bl * (p.sy || 0.8), 0, 0, TAU); x.stroke();
      softGlow(x, cx, cy, r * 3.2 * bl, '#e8f8ff', 0.25 * a);
