  // 風の 大ドーム（白い まる。中で 細い 針の 線が 光る）。keys: [[ms, r]]、cols: [ふち, 中, 針]
  g2Dome(x, p) {
    const [R] = kf(p.keys, p.age, 'out');
    const a = envOf(p, 40, 220);
    if (!(R > 1) || a <= 0) return;
    const [rim, fill, needle] = p.cols || ['#e8f8ff', '#ffffff', '#5a9ae8'];
    const sy = p.sy || 0.85;
