    } else if (pose === 'kick') {
      limb(0, -7, 8, -9, C.suit, 2.4); limb(0, -7, -2, 0, C.suit, 2.4);
    } else {
      limb(-1.2, -7, -2, 0, C.suit, 2.4); limb(1.2, -7, 2, 0, C.suit, 2.4);
    }
