    else if (pose === 'seal') { arm(2.6, -10.5); arm(2.8, -10); }
    else if (pose === 'throw') { const k = Math.sin(clamp01(p.age / 160) * Math.PI); arm(4 + 4 * k, -14 - 3 * k); arm(-4, -8); }
    else if (pose === 'jump') { arm(5, -16); arm(-5, -15); }
    else { arm(-3.5, -7); arm(3.5, -7); }
