    for (let i = 0; i < n; i++) {
      const an = (i / n) * TAU + (p.seed || 0);
      blobs.push([p.x + Math.cos(an) * r * 0.62, p.y + Math.sin(an) * r * 0.5 - r * 0.1, r * (0.42 + 0.16 * hash(i + (p.seed || 0)))]);
