      }
      x.stroke();
    }
    x.restore();
  },
  // クナイ（ひし形の 刃＋わ）。keys: [[ms, x, y]]。とんで いる あいだは 青い すじ、ついたら ささって のこる
  g2Kunai(x, p) {
