      x.globalCompositeOperation = 'lighter';
      const [tx, ty] = kf(p.keys, Math.max(0, p.age - 70), 'lin');
      x.strokeStyle = p.trail || '#7ab8ff';
      x.lineCap = 'round';
      x.globalAlpha = 0.6 * a;
      x.lineWidth = 2.2 * s;
