      // 大わらい（目は まる、口は 大きく）
      x.strokeStyle = C.ink; x.lineWidth = 0.6;
      x.beginPath(); x.arc(-1.4, -22, 0.9, 0, TAU); x.moveTo(2.3, -22); x.arc(1.4, -22, 0.9, 0, TAU); x.stroke();
      x.fillStyle = '#ff5a6a';
