      for (let i = 0; i < 14; i++) fx.puff(me.x + rnd(-20, 20), c.H - rnd(30, 56), { color: '#ffffff', r0: 3, r1: 11, vx: rnd(-30, 30), vy: rnd(-60, -30), life: 480, alpha: 0.5, delay: i * 60 });
