      k.flash('#ff4a5a', 80, c.hit);
      k.shockwave(me.x, c.H - 30, { r0: 10, r1: 90, color: '#ff4a5a', w: 2.6, n: 2, delay: c.hit });
      k.particles(me.x, c.H - 30, { colors: ['#ff4a5a', '#ffffff', '#1a0a10'], n: 20, speed: 150, delay: c.hit, life: 420 });
