        fx.shock(me.x, c.H - 50, { r0: 10, r1: big ? 70 : 46, color: '#ffffff', w: big ? 3 : 2, delay: bt, life: 340 });
        if (big) k.shapes(me.x, c.H - 50, { shape: 'note', n: 4, colors: ['#ffffff', '#fff6d0'], speed: 70, size: 3, delay: bt, life: 600, add: false, g: -20 });
