      k.particles(me.x, c.H - 40, { colors: WHITE, n: 30, speed: 150, ang: -Math.PI / 2, spread: 1.3, delay: c.hit, life: 560 });
      text(fx, 'ハハハ', me.x < c.W / 2 ? me.x + 74 : me.x - 74, 40, { size: 15, delay: c.hit + 420, life: c.len - c.hit - 560, wave: true });
