  // 雷をつかむ: 白い いなずまが 落ちて、のびた 腕が つかむ → 大きく ふり回して 敵ぜんぶに たたきつける → 雷の 爆発
  ax_kaminari_tsukamu: {
    charge: { color: '#ffffff', color2: '#fff6b0', power: 1.2 },
    sfx: 'ax_g2_kaminari',
    allyFx: 'bolt',
    play(fx, c) {
      const { k } = c;
      const C = c.center;
      bg(fx, 'storm', { a: 0.6, life: c.len - 60 });
      const b = base(c, 0);
      const G = { x: Math.max(30, C.x - 70), y: 18 };
