  },
  // ぐるぐる（おろ）
  spiral(x, p) {
    x.strokeStyle = p.color || '#ffffff'; x.lineWidth = 0.9;
    x.beginPath();
    for (let i = 0; i <= 30; i++) { const a = i * 0.45 + p.age / 90, r = 0.4 + i * 0.22; const px = Math.cos(a) * r, py = Math.sin(a) * r * 0.6; i ? x.lineTo(px, py) : x.moveTo(px, py); }
    x.stroke();
  },
  // あせの しずく
  drop(x, p) {
    x.fillStyle = p.color || '#7ad0ff';
