      x.moveTo(bx - sa * 2 * sg, by + ca * 2 * sg);
      x.lineTo(bx + ca * len * 0.6 + sa * len * sg, by + sa * len * 0.6 - ca * len * sg);
      x.lineTo(bx + ca * 1.5, by + sa * 1.5);
