    x.beginPath();
    for (let i = 0; i < 3; i++) { const a = rot * 0.8 + (i / 3) * Math.PI; x.moveTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r); x.lineTo(cx - Math.cos(a) * r, cy - Math.sin(a) * r); }
