    x.restore();
  },
  // 全画面の 背景（えんしゅつの いちばん 下）
  g3Bg(x, p, t, fx) {
    const W = fx?.W || W0, H = fx?.H || H0;
    let env = p.age < p.fin ? p.age / Math.max(1, p.fin) : 1;
    if (p.age > p.life - p.fout) env *= clamp01((p.life - p.age) / Math.max(1, p.fout));
    if (env <= 0) return;
