  },
  // ───── おせんたくでござる（味方）: 木の たらい・白い あわ → きらきら → 回復 ─────
  ax_osentaku: {
    charge: { ...blade, power: 0.6 },
    sfx: 'ax_g3_wash',
    allyFx: 'wind',
    play(fx, c) {
      const { k } = c;
