  // ───── そう竜閃: 白い 一閃 → すぐ さやの 黒い 一撃（太い 黒の 弧）→ 2回 当たる ─────
  ax_souryusen: {
    charge: blade,
    sfx: 'ax_g3_souryu',
    allyFx: 'claw',
    play(fx, c) {
      const { k } = c;
      c.each((t, i, d) => {
        rich(fx, c, t, d + c.hit, 42, WHITE);
        const s = c.sz, dir = hdir(c, t);
