  // ───── 竜巣閃（Lv10）: 敵ごとに 短い 斬撃の 線 12本が ばらばらの 角度で（巣の ように）→ 白い 火花 → 線が いっしょに 光って 消える ─────
  ax_ryusousen: {
    charge: { ...blade, power: 1.2 },
    sfx: 'ax_g3_ryusou',
    allyFx: 'claw',
    play(fx, c) {
      const { k } = c;
      c.each((t, i, d) => {
        rich(fx, c, t, d + c.hit, 20, WHITE);
