      k.shockwave(c.W / 2, 34, { r0: 10, r1: 80, color: '#ffd23a', w: 2.4, n: 3, gap: 120, delay: 200 });
      k.speedLines(c.W / 2, 34, { color: '#fff0a0', delay: 160, life: 360, r0: 30, r1: 170, n: 22 });
      c.each((t, i, d) => {
