      text(fx, 'ワッショイ!', C.x, 22, { size: 9, color: '#ffffff', color2: '#a01810', life: 520, fout: 160, delay: 160 });
      const xs = c.targets.map((t) => t.x);
      const x0 = Math.min(...xs) - 40, x1 = Math.max(...xs) + 40;
      // 赤い はっぴの 人たちの かげ が かけぬける
      for (let j = 0; j < 3; j++) prop(fx, 'swordsman', -20, C.y + 20 + j * 4, { s: 1.2, pose: 'slash', color: j % 2 ? '#c8202a' : '#e8302a', life: 420, fout: 120, delay: 240 + j * 90, to: { x: c.W + 20, y: C.y + 20 + j * 4 }, travel: 420, ease: 'lin', pop: false, alpha: 0.85 });
      ribbon(fx, [[x0, C.y - 26], [C.x, C.y + 4], [x1, C.y - 16]], { style: 'flame', w: 7, draw: 150, hold: 140, life: 440, delay: c.hit - 120 });
      ribbon(fx, [[x1, C.y - 30], [C.x, C.y - 6], [x0, C.y + 16]], { style: 'blade', w: 7, draw: 130, hold: 140, life: 420, delay: c.hit - 40 });
      c.each((t, i, d) => {
        const h = d + c.hit;
        rich(fx, c, t, h, 70, ['#fff2a0', '#ffb040', '#ff6a1a']);
        blast(fx, t.x, t.y, { r: 22 * c.sz, glow: '#ffa040', core: '#fff2a0', colors: ['#fff2a0', '#ffb040', '#ff6a1a'], n: per(c, 30), smoke: '#4a2010', heavy: i === 0, delay: h });
        k.flames(t.x, t.y + 12, { w: 26 * c.sz, h: 24 * c.sz, n: 5, delay: h + 40, life: 460, embers: c.n < 3 });
      });
      k.flash('#ffe0b0', 120, c.hit);
      k.shake(420, 2.8, c.hit);
    },
  },
};

js/client/render/axfx-g3.js:
// 第48回 G3（鬼滅の刃 ＋ るろうに剣心 ＋ 暴れん坊将軍）: 大技の え（はなつ ところ）。render/axfx.js が useAxGroup('g3', AX_G3, AX_G3_FINE) で とうろく する
// 書きかたは docs/plan-r48-fx.md の「G0 の 決めごと」と docs/plan-r48-fx-engine.md。この ファイルは G3 だけが さわる
// ・時間（tier・charge.kind/ms・hit・len・stagger・party）と 技の つなぎは shared/data/ax-time-g3.js に 書く（ここには 書かない）
// ・中身は 3つの ファイルに 分けた:
//   axfx-g3-kit.js      … G3 の どうぐ（ふでの 帯・竜・太刀すじ・竜巻・日輪・火車・背景・小道具）と つぶの かきかた（g3〜）
//   axfx-g3-kimetsu.js  … 鬼滅の刃（水の呼吸・炎の呼吸・日の呼吸）
//   axfx-g3-rurouni.js  … るろうに剣心（飛天御剣流）
//   axfx-g3-shogun.js   … 暴れん坊将軍 ＋ 合体技
import { G3_FINE, capLife } from './axfx-g3-kit.js';
import { AX_G3_KIMETSU } from './axfx-g3-kimetsu.js';
import { AX_G3_RUROUNI } from './axfx-g3-rurouni.js';
import { AX_G3_SHOGUN } from './axfx-g3-shogun.js';

// どの え も「はなって から len ＋ 敵全体の ずらし ＋ 200ms」までに つぶが きえる（つぎの 行動に かぶらない）
const guard = (defs) => Object.fromEntries(Object.entries(defs).map(([anim, d]) => [anim, {
  ...d,
  play(fx, c) {
    const spread = c.n > 1 ? Math.min(300, c.stagger * (c.n - 1)) : 0;
    return capLife(fx, c.len + spread + 200, () => d.play(fx, c));
  },
}]));

export const AX_G3 = guard({
  ...AX_G3_KIMETSU,
  ...AX_G3_RUROUNI,
  ...AX_G3_SHOGUN,
});

export const AX_G3_FINE = {
  ...G3_FINE,
};

