// ひかる 線（ひかり → からだ → しん の 3かい）
export function glowStroke(x, pts, w, glow, color, core, a = 1, close = false) {
  x.globalCompositeOperation = 'lighter';
  for (const [col, k, al] of [[glow, 2.8, 0.32], [color, 1, 0.9], [core, 0.38, 1]]) {
