      // はばが そろった 棒（はしだけ とがる）。たては 上から、よこは 左から のびる
      const len2 = 2 * L, tip = Math.min(len2 / 2, w * 2.2);
      const dia = (ww2) => {
        const pts = [[0, 0], [tip, -ww2], [len2 - tip, -ww2], [len2, 0], [len2 - tip, ww2], [tip, ww2]];
        return vert ? pts.map(([u, v]) => [v, -s + u]) : pts.map(([u, v]) => [-s + u, v]);
      };
