    const a = clamp01((p.life - p.age) / 120);
    if (a <= 0 || e >= 1) return;
    const hx = lerp(p.x0, p.x1, easeIn(e) * 0.4 + e * 0.6), hy = lerp(p.y0, p.y1, easeIn(e) * 0.4 + e * 0.6);
