    x.restore();
  },
  // 消滅の 白い 球（ふくらむ → しずかに ひかる → ちぢんで きえる）。r … 半径、hold … ひかる ms
  g4Void(x, p) {
    const g = easeOut(clamp01(p.age / 140));
    const hold = p.hold || 360;
    const sh = clamp01((p.age - 140 - hold) / Math.max(1, p.life - 140 - hold));
