    const fl = (p.flap || 0) * Math.sin((p.age - (p.flapAt || 0)) / (p.flapMs || 140)) * (p.age > (p.flapAt || 0) ? 1 : 0);
    const col = p.color || '#7ad8ff', core = p.core || '#ffffff';
