      x.fillStyle = '#ffb860';
      for (let i = 0; i < 6; i++) { const w = 30 - i * 4, yy = 95 + i * 1.6; x.globalAlpha = a * (0.8 - i * 0.1); x.fillRect((p.sx ?? W * 0.5) - w / 2 + Math.sin(p.age / 200 + i) * 2, yy, w, 0.8); }
