      x.fillStyle = '#1e4a32'; x.fillRect(4, 12, W - 8, 80);
      x.fillStyle = '#2a5a3e';
      for (let i = 0; i < 6; i++) { x.globalAlpha = a * 0.5; x.fillRect(4 + hash(i * 2.3) * (W - 40), 18 + hash(i * 4.1) * 64, 26 + hash(i) * 20, 1.2); }
      x.globalAlpha = a; x.fillStyle = '#8a6a4a'; x.fillRect(-8, 92, W + 16, 4);
    } else if (p.v === 'ground') {
