    }
    x.restore();
  },
  // まわる 光の すじ（ほうしゃ。n … かず、r … ながさ）
  g4Rays(x, p) {
    const a = envOf(p, 120, 220) * (p.alpha ?? 0.5);
    if (a <= 0) return;
    const n = p.n || 12, r = (p.r || 60) * (0.6 + 0.4 * easeOut(clamp01(p.age / 300)));
