  },
  // 「人」の 2画（ひだりの はらい → みぎの はらいが ささえる）。s … 大きさ
  g4Hito(x, p) {
    const a = envOf(p, 40, 300);
    if (a <= 0) return;
    const s = p.s || 40;
    const k1 = easeOut(clamp01(p.age / 260)), k2 = easeOut(clamp01((p.age - 300) / 260));
    const glow = p.glow || '#ffb050', col = p.color || '#ffffff';
    x.save();
    x.translate(p.x, p.y);
    // ひだり: 上の まん中から ひだり下へ（ふでの ように まがる）
