        k.bolt(t.x + rnd(-20, 20), -6, t.x + rnd(-6, 6), t.y, { w: 2, color: DEIN.color, glow: '#9ad8ff', forks: 2, amp: 10, life: 300, grow: 40, delay: T0 + 120 });
        k.pillar(t.x, t.y, { w: 9 * c.sz, color: '#fff6b0', glow: '#ffd23a', delay: T0 + 30, life: 320, burst: false });
