function freeze(c, t, d, { w = 30, h = 34, n = 5, hold = 360, shatter = true } = {}) {
  c.add('g5Shards', { x: t.x, y: t.y + 14 * c.sz, w: w * c.sz, h: h * c.sz, n, grow: 140, delay: d, life: hold + 140, fout: 120 });
