    x.restore();
  },
  // 宮殿・城の かげ（style: moon 白銀の 宮殿 / ice 氷の 城 / crystal クリスタルの 塔 / gold）。x … まん中、y … じめん、grow … たちあがる ms
  g5Palace(x, p) {
    const a = env(p, 100, 320) * (p.alpha ?? 1);
