      x.fillRect(p.x - W * 0.42, p.y - H * sweep - 1, W * 0.84, 2);
    }
    x.restore();
  },
  // リボン（cx, cy から 上へ らせん。cols … [おもて, うら]、turns … まわる かず）
  g5Ribbon(x, p) {
