    const e = easeOut(clamp01(p.age / Math.max(1, p.travel)));
    x.save();
    const yAt = (xx, front, k) => front + Math.sin(xx / (p.wl || 18) + p.age / 90 + k * 1.7) * p.amp + Math.sin(xx / 7 - p.age / 60 + k) * 1.5;
    // からだ（すける いろ。うしろの 敵が 見える）
