    x.globalCompositeOperation = 'lighter';
    p.cols.forEach((col, k) => {
      const front = lerp(p.y0, p.y1, e) + k * (p.gap ?? 9);
      for (const [lw, c2, al] of [[3.2, col, 0.55], [1.2, '#ffffff', 0.95]]) {
