      const ts = c.targets.map((t, i) => ({ t, i })).sort((a, b) => a.t.x - b.t.x);
      const rightward = ts.length > 1 ? true : ts[0].t.x >= o.x;
      if (ts.length > 1 && o.x > c.center.x) ts.reverse();
