// あらわれる・きえる（fin・fout ms）
function envOf(p) {
  let a = 1;
  const fin = p.fin ?? 80, fout = p.fout ?? 160;
  if (fin > 0 && p.age < fin) a *= p.age / fin;
  if (fout > 0 && p.age > p.life - fout) a *= clamp01((p.life - p.age) / fout);
  return Math.max(0, Math.min(1, a));
