}
function drawTornado(x, p, env) {
  const e = easeOut(clamp01(p.age / (p.grow || 220)));
  const H = p.h * e;
  const N = 11;
  const cols = p.cols || ['#ff4a1a', '#ffa020', '#fff27a'];
  x.save();
  x.translate(p.x, p.y);
  x.globalCompositeOperation = 'lighter';
