  x.fillStyle = '#9a0c20'; x.fillRect(cx - hw - 10, y0, hw * 2 + 20, 9);
  x.fillStyle = '#ffd23a'; x.fillRect(cx - hw - 10, y0 + 9, hw * 2 + 20, 1.6);
  for (let xx = cx - hw - 9; xx < cx + hw + 10; xx += 4) disc(x, xx, y0 + 11.5, 1, '#ffd23a');
