export const G6_FINE = {
  // かたちの え（SH）。x0,y0 → x1,y1（travel・start・ease・hop）、s → s1（sT）、rot・spin・flip、bob、glow
  g6Spr(x, p) {
    const age = p.age;
    if (p.path) {
      const P = p.path;
      let i = 1;
      while (i < P.length - 1 && age > P[i][2]) i++;
      const a = P[i - 1], b = P[i];
      const u = clamp01((age - a[2]) / Math.max(1, b[2] - a[2]));
      const e = EASE[b[3] || 'lin'](u);
