// ・o1Tri     … 光の 三角形（デルタストライク）
// 画面の 文字は カタカナ・ひらがな・記号だけ（漢字は 出さない）
import { rnd, clamp01, lerp, easeOut, easeInOut, softGlow, disc } from './axkit.js';
