// 文字（カタカナ・記号）
export const text = (fx, s, x, y, o = {}) => g3text(fx, s, x, y, o);
// 何回も あたる 技の j回目の 的（ランダムの かわりに じゅんばん）
export const pick = (c, j) => c.targets[j % c.n];
// 的の かずで つぶを へらす（1体 … n、3体 … n/2、5体 … n×0.3）
