}
// あたった 光（的の かずで つぶを わける）
export function strike(fx, c, t, at, o = {}) {
  const { r = 14, glow = '#bfe4ff', colors = COL.white, n = 18, heavy = false, rings = 1, extra = 0, extraCols = colors } = o;
