// ───────────── かく どうぐ（単位の 大きさ: だいたい -1〜1） ─────────────
const ell = (x, cx, cy, rx, ry, rot = 0) => { x.beginPath(); x.ellipse(cx, cy, Math.max(0.01, rx), Math.max(0.01, ry), rot, 0, TAU); };
