}
const CLOUD = [[-0.62, 0.12, 0.4], [-0.2, -0.22, 0.5], [0.3, -0.12, 0.46], [0.66, 0.16, 0.36], [0.05, 0.22, 0.42], [-0.35, 0.28, 0.32]];
// かみなりの かたち（ギザギザ）
const BOLT = [[0.15, -1], [-0.45, 0.1], [-0.02, 0.1], [-0.28, 1], [0.48, -0.22], [0.06, -0.22], [0.38, -1]];
