// うごく みち: x0,y0 → x1,y1（hop … とびはねる 高さ）
export function pathPos(p, age = p.age) {
  const travel = p.travel || 0;
  if (!(travel > 0)) return [p.x, p.y, 1];
  const e = clamp01((age - (p.start || 0)) / travel);
