const RAINBOW = ['#ff4a4a', '#ff9a2a', '#ffe040', '#5ad860', '#3aa8ff', '#4a5ae8', '#a85ae8'];

export const AX_O10_FINE = {
  // 小物: shape・s（大きさ px）・pop（ふくらむ ms）・spin・rot0・wob（ゆれ）・float（ふわふわ）・glow・glowR・flip・sx（よこの のび）
