// 空 ぜんたいが かわる: 大きな いかずち・めぐみの 雨・真夏の 太陽・台風の うず・にじの かけ橋・ゲリラごう雨・3本の かみなり・
// 晴れ → 雨 → かみなり → にじ（空の大号令）。時間は shared/data/ax-time-o10.js。play の 時間は はなつ しゅんかんが 0
import { rnd } from './axkit.js';
import { obj, text, rain, rays, spiral, rainbow, sky, arrow, UP, above, ground, partyTop, per, hitFx, strike, tierShake, allyGlow, splashAt } from './axfx-o10-kit.js';

