// ぬって ふちどり（明るい はいけいでも 見える）
function fe(x, fill, edge, lw = 0.1) {
  x.fillStyle = fill; x.fill();
  if (edge) { x.lineWidth = lw; x.strokeStyle = edge; x.stroke(); }
