// うごく みち: x0,y0 → x1,y1（hop … とびはねる 高さ）か pts（[[x,y],…] を じゅんに）
export function pathPos(p, age = p.age) {
  const travel = p.travel || 0;
  if (!(travel > 0)) return [p.x0 ?? p.x, p.y0 ?? p.y, 1];
