  // 分割ばらい: 長い レシートが ちょっとずつ のびる（ジ…ジ…ジ…）→ むらさきの じわじわの 泡
  ox_bunkatsu: {
    sfx: 'ax_o3_ribo', allyFx: 'poison',
    play(fx, c) {
