      for (let j = 0; j < 2; j++) obj(fx, 'sweat', t.x + (j ? 10 : -10), t.y - 16, { vx: j ? 30 : -30, vy: -50, g: 180, s: 2.6, life: 380, delay: c.hit + j * 60 });
