    play(fx, c) {
      c.each((t, i, d) => {
        obj(fx, 'cup', t.x, t.y - 26, { s: 8, pop: 160, delay: d, life: c.len - 40, sway: 0.6 });
        for (let j = 0; j < 4; j++) fx.puff(t.x - 3 + j * 2, t.y - 36, { color: '#ffffff', r0: 2, r1: 7, vx: rnd(-6, 6), vy: -26, life: 420, alpha: 0.55, delay: d + 60 + j * 60 });
