  // 年末の大いそがし: 箱・紙・カレンダーが とびかう 中を 6回 体当たり → ゴーン（金の 輪）→ 紙ふぶき
  ox_nenmatsu: {
    charge: { color: '#ff5a3a', color2: '#ffd06a' }, sfx: 'ax_o3_nenmatsu', allyFx: 'claw', minParts: 70,
    play(fx, c) {
