      }
      const hits = picks(c, 6);
      hits.forEach((t, j) => {
        const del = j * 70;
        const ang = (j * 2.1) % (Math.PI * 2);
        const sx = t.x + Math.cos(ang) * 50, sy = t.y + Math.sin(ang) * 30;
        c.k.dash(sx, sy, t.x, t.y, { color: '#ff8a3a', travel: Math.max(60, c.hit - 40), w: 5, h: 22, delay: del });
