    }),
  },
  // げんま「水のせいれい」: 水の せいれいが うかぶ → しずくの 雨が 味方へ → 緑と 青の 光
  ox_genma_undine: {
    charge: { color: BLUE, color2: SKY }, sfx: 'ax_o6_undine', allyFx: 'heal',
    play: wrap((fx, c) => {
