    const base = { sun: '#ffc84a', rain: '#3a5a8a', thunder: '#2a1a4a', space: '#0a0a2a', white: '#ffffff', stadium: '#0a1a38', rainbow: '#bfeaff' }[p.v] || '#ffffff';
    x.globalAlpha = a; x.fillStyle = base; x.fillRect(-8, -8, W + 16, H + 16);
    if (p.v === 'sun') {
