  // 雨の すじ
  o9Rain(x, p) {
    const a = envOf(p, 80, 200) * (p.alpha ?? 0.85);
    if (a <= 0.01) return;
    const n = p.n || 40, ang = p.ang ?? 0.25, len = p.len || 12;
    const x0 = p.x0 ?? 0, x1 = p.x1 ?? 256, y0 = p.y0 ?? -10, y1 = p.y1 ?? 144, span = Math.max(1, y1 - y0);
