  // 大きな にこにこ 太陽
  o9Sun(x, p) {
    const [cx, cy, s, , ka] = at(p);
    const a = envOf(p, 100, 220) * ka;
    if (a <= 0.01) return;
    const r = pos((p.size || 18) * s, 0.5);
    x.save();
