      poly(x, [[-r * 0.2, -r * 0.92], [0, -r * l], [r * 0.2, -r * 0.92]]); fs(x, i % 2 ? '#ffb020' : '#ff8a1a', Math.max(0.6, r * 0.05), '#a05a0a');
