    case 'a7n_frost':
      fx.tintAt('rgba(150,200,240,0.3)', 900);
      for (const [i, t] of targets.entries()) {
        fx.swirl(t.x, t.y - 6, [...ICE, '#c8a0ff'], { n: 12, rad: 12, h: 26, life: 700, delay: i * 50 });
