        for (let k = 0; k < 10; k++) fx.add({ kind: 'flame', x: x + rnd(-18, 18), y: y + 16, h: 28 + rnd(0, 22), w: 7 + rnd(0, 6), c1: '#14041e', c2: '#d070ff', dark: true, ph: rnd(0, 6), vy: -26, life: 700 + rnd(0, 200), delay: d + k * 18 });
