        fx.burst(x, y, COIN_COL, 18, 110, { delay: d + 60 });
        fx.star(x, y, '#ffe07a', 14, d + 60, 240);
        fx.glow(x, y, { color: '#ffd24a', r: 22, delay: d + 60, life: 380 });
      });
      fx.flashAt(70, '#fff6c0', 60);
      return true;
    }
    default:
      return false;
  }
}

