    x.fillStyle = edge;
    const e = s * 0.8;
    for (const [px, py] of cells) x.fillRect(px - e, py - e, s + e * 2, s + e * 2);
  }
  x.fillStyle = fill;
  for (const [px, py] of cells) x.fillRect(px, py, s, s);
