}
// p.x0,y0 → p.x1,y1 へ travel ms で とぶ（そのあと とまる）。かえりち: [x, y, 0〜1]
function flyPos(p, ease = easeOut) {
  const k = clamp01(p.age / Math.max(1, p.travel || 1));
  const e = ease(k);
  return [p.x0 + (p.x1 - p.x0) * e, p.y0 + (p.y1 - p.y0) * e - Math.sin(k * Math.PI) * (p.arc || 0), k];
}

