    case 'pm_wave_charge': // 大波の 前ぶれ
      for (const t of targets) {
        for (let i = 0; i < 3; i++) fx.shock(t.x, t.y + 14, { r0: 8, r1: 46 + i * 6, color: INDIGO[i], delay: i * 160, life: 600 });
