// 第66回 D班の 伝説の 職業 5つの 技の エフェクト（docs/plan-r66-legend.md）
// 技の id では なく「えんしゅつの なまえ（anim）」で ひく。技の データの anim に ここの なまえを 書く（例 anim: 'gekka_sig'）。
// battlefx.js の play() で battlefx-r43j.js の つぎに よばれる（ここに ない anim なら false を かえす）。
// え は「それと わかる、でも そのまま うつさない」かんたんな かたち（ロゼッタや チコの 顔・ロゴは かかない。チコは 目の 点だけの 小さな 星）
//
// 看板の技（なまえは '<職業の id>_sig'）
//  gekka_sig       月下のロイヤルストレートフラッシュ … 夜空に 満月。光る トランプ 5まいが 扇に ならび、つぎつぎに 敵へ（5回ずつ）
//  nobu_dora_sig   ひみつ道具大行進 … ポケットが 光り、空気ほうの わ・名刀電光丸の 光・どこでもドアが つぎつぎ 出る
//  kappa_king_sig  大王の大パッカーン … 大きな 花が 色を かえながら さき（バラ → トウガラシ → さくら → ニンニク）、花びらと 大きな しょうげき
//  truth_gate_sig  真理のとびら・大れん成 … 青い れん成の 円の 上に 大きな とびらが ひらき、大地が せり上がって 敵を つきあげる
//  rosetta_sig     流星群とチコの大行進 … 夜空に 流れ星が ふりそそぎ、小さな 星の 仲間たちが はねながら 敵へ
// ほかの 技（どれも 敵に あたる。みかたに かける 技は 前から ある えんしゅつ）
//  r66d_ace        光る エースの トランプが まっすぐ 飛ぶ
//  r66d_cards      トランプが 花びらの ように まいおどる（敵全体）
//  r66d_vanish     けむりで 消えて、敵の うしろから 2回 きらっと 切る
//  r66d_door       敵の うしろに ピンクの ドアが 出て、ひらいて ポカン
//  r66d_shock      ビビッと しびれる 光の たまが 敵へ
//  r66d_harite     大きな 手のひらが どーんと つっぱる
//  r66d_splash     頭の お皿から 大きな 水しぶき
//  r66d_stonefist  地面から 石の うでが のびて なぐる
//  r66d_terrain    地面が 山と 谷に かわって ぐらり
//  r66d_meteor     流れ星が 1つ 落ちる
//  r66d_spin       星の 光を まとって くるっと 回る（わと きらきら）
//  r66d_luma       小さな 星の 仲間が 大きな 星に なって 体当たり
// ・どれも 2.4びょう いないで おわる。あたる じかんは R66D_HIT（battle.js の HIT_DELAY に まぜる）
// ・文字は 出さない

const rnd = (a, b) => a + Math.random() * (b - a);
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const easeOut = (t) => 1 - (1 - t) * (1 - t) * (1 - t);
const fadeOut = (t, from = 0.7) => (t < from ? 1 : Math.max(0, 1 - (t - from) / (1 - from)));

export const R66D_SIG_JOBS = ['gekka', 'nobu_dora', 'kappa_king', 'truth_gate', 'rosetta'];
export const R66D_SIGS = R66D_SIG_JOBS.map((j) => `${j}_sig`);
export const R66D_MOVES = ['r66d_ace', 'r66d_cards', 'r66d_vanish', 'r66d_door', 'r66d_shock', 'r66d_harite', 'r66d_splash', 'r66d_stonefist', 'r66d_terrain', 'r66d_meteor', 'r66d_spin', 'r66d_luma'];
export const R66D_ANIMS = new Set([...R66D_SIGS, ...R66D_MOVES]);
// あたる じかん（ms。ダメージの 数字を この ときに 出す）
export const R66D_HIT = {
  gekka_sig: 720, nobu_dora_sig: 700, kappa_king_sig: 980, truth_gate_sig: 900, rosetta_sig: 820,
  r66d_ace: 300, r66d_cards: 380, r66d_vanish: 420, r66d_door: 460, r66d_shock: 320, r66d_harite: 300,
  r66d_splash: 360, r66d_stonefist: 420, r66d_terrain: 360, r66d_meteor: 440, r66d_spin: 300, r66d_luma: 420,
};
// たたかいの 音（battle.js の ANIM_SFX に まぜる。audio.js・sfx-r26.js・sfx-r33.js に ある 音）
export const R66D_SFX = {
  gekka_sig: 'r33_cards', nobu_dora_sig: 'gadget', kappa_king_sig: 'muscle', truth_gate_sig: 'r33_clap', rosetta_sig: 'sparkle',
  r66d_ace: 'cardfly', r66d_cards: 'r33_cards', r66d_vanish: 'r33_poof', r66d_door: 'door', r66d_shock: 'bolt', r66d_harite: 'smash',
  r66d_splash: 'splash', r66d_stonefist: 'hammer', r66d_terrain: 'rumble', r66d_meteor: 'kirari', r66d_spin: 'wind', r66d_luma: 'pon',
};

// ───────────── え の ぶひん ─────────────
function softGlow(x, cx, cy, r, col, a) {
  const g = x.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, col);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.globalAlpha = a;
  x.fillStyle = g;
  x.fillRect(cx - r, cy - r, r * 2, r * 2);
}
// 5つの とがりの 星
function starPath(x, cx, cy, r, rot = 0) {
  x.beginPath();
  for (let i = 0; i < 10; i++) {
    const q = rot - Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r * 0.45 : r;
    const px = cx + Math.cos(q) * rr, py = cy + Math.sin(q) * rr;
    if (i) x.lineTo(px, py); else x.moveTo(px, py);
  }
  x.closePath();
}
// 弧の とちゅうの いち（x0,y0 → x1,y1。hop: たかさ）
const arcAt = (p, k) => [p.x0 + (p.x1 - p.x0) * k, p.y0 + (p.y1 - p.y0) * k - Math.sin(k * Math.PI) * (p.hop || 0)];
const SUITS = ['#d8202c', '#1a1a2a', '#d8202c', '#1a1a2a', '#e8b020'];
const STARC = ['#fff6a0', '#a8e8ff', '#ffb0d8', '#b8ffb0', '#ffd080'];
// 花の いろ（バラ → トウガラシ → さくら → ニンニク）
const FLOWERS = [['#e8203a', '#ff7a8a'], ['#ff5a1a', '#ffc040'], ['#ffb0cc', '#fff0f6'], ['#c99ae0', '#f4dcff']];

export const R66D_FINE = {
  // トランプ（白い 板と マーク）。x0,y0 → x1,y1 を とぶ（travel ms）。x0 が なければ x,y に とまる
  r66dCard(x, p, t) {
    let cx = p.x, cy = p.y, rot = p.rot || 0;
    if (p.x0 !== undefined) {
      const k = clamp01(p.age / (p.travel || 300));
      if (p.age > (p.travel || 300) + 60) return;
      [cx, cy] = arcAt(p, easeOut(k));
      rot += p.age / 40;
    }
    const a = p.x0 !== undefined ? 1 : fadeOut(t, 0.75);
    if (a <= 0) return;
    const s = p.s || 1;
    x.save();
    if (p.glow) {
      x.globalCompositeOperation = 'lighter';
      softGlow(x, cx, cy, 10 * s, p.glow, 0.7 * a);
      x.globalCompositeOperation = 'source-over';
    }
    x.globalAlpha = a;
    x.translate(cx, cy);
    x.rotate(rot);
    x.fillStyle = '#2a2a3a';
    x.fillRect(-3.6 * s, -5.1 * s, 7.2 * s, 10.2 * s);
    x.fillStyle = '#fbfbff';
    x.fillRect(-3 * s, -4.5 * s, 6 * s, 9 * s);
    x.fillStyle = p.suit || '#d8202c';
    x.beginPath(); x.arc(0, 0, 1.6 * s, 0, Math.PI * 2); x.fill();
    x.fillRect(-0.5 * s, 0, 1 * s, 2.4 * s);
    x.restore();
  },
  // 満月（夜空の 大きな まるい 月）
  r66dMoon(x, p, t) {
    const a = fadeOut(t, 0.75) * clamp01(p.age / 200);
    if (a <= 0) return;
    const r = p.r || 18;
    x.save();
    x.globalCompositeOperation = 'lighter';
    softGlow(x, p.x, p.y, r * 2.4, 'rgba(255,248,210,0.9)', 0.6 * a);
    x.globalCompositeOperation = 'source-over';
    x.globalAlpha = a;
    x.fillStyle = '#fff8dc';
    x.beginPath(); x.arc(p.x, p.y, r, 0, Math.PI * 2); x.fill();
    x.fillStyle = '#efe2b0';
    x.beginPath(); x.arc(p.x - r * 0.3, p.y - r * 0.2, r * 0.22, 0, Math.PI * 2); x.fill();
    x.beginPath(); x.arc(p.x + r * 0.25, p.y + r * 0.3, r * 0.15, 0, Math.PI * 2); x.fill();
    x.restore();
  },
  // ピンクの ドア（ひらく）
  r66dDoor(x, p, t) {
    const a = fadeOut(t, 0.75) * clamp01(p.age / 120);
    if (a <= 0) return;
    const s = p.s || 1, open = clamp01((p.age - (p.openAt || 200)) / 160);
    const w = 10 * s, h = 18 * s;
    x.save();
    x.globalAlpha = a;
    x.translate(p.x, p.y);
    // わく（中は 光）
    x.fillStyle = '#7a2a4a';
    x.fillRect(-w / 2 - 1.2 * s, -h, w + 2.4 * s, h + 1 * s);
    x.fillStyle = open > 0 ? '#fff6d0' : '#3a1a2a';
    x.fillRect(-w / 2, -h + 1 * s, w, h - 1 * s);
    // とびら（ひらくと よこに うすく なる）
    const dw = w * (1 - open * 0.8);
    x.fillStyle = '#f27ab0';
    x.fillRect(-w / 2, -h + 1 * s, dw, h - 1 * s);
    x.fillStyle = '#ffd040';
    x.fillRect(-w / 2 + dw - 2.2 * s, -h / 2, 1.4 * s, 1.4 * s);
    x.restore();
  },
  // 花（いろが かわりながら ひらく。cols: [[花びら, 中], …]）
  r66dFlower(x, p, t) {
    const a = fadeOut(t, 0.78);
    if (a <= 0) return;
    const s = (p.s || 1) * easeOut(clamp01(p.age / 260));
    const cols = p.cols || FLOWERS;
    const i = Math.min(cols.length - 1, Math.floor(p.age / (p.step || 160)));
    const [pet, mid] = cols[p.fix !== undefined ? p.fix : i];
    x.save();
    x.globalAlpha = a;
    x.translate(p.x, p.y);
    x.rotate(p.age / 600);
    x.fillStyle = pet;
    for (let k = 0; k < 5; k++) {
      const q = (k / 5) * Math.PI * 2;
      x.beginPath(); x.ellipse(Math.cos(q) * 6 * s, Math.sin(q) * 6 * s, 5 * s, 3.4 * s, q, 0, Math.PI * 2); x.fill();
    }
    x.fillStyle = mid;
    x.beginPath(); x.arc(0, 0, 3.2 * s, 0, Math.PI * 2); x.fill();
    x.restore();
  },
  // 大きな とびら（2まいの とびらが ひらく。中は 白い 光）
  r66dGate(x, p, t) {
    const a = fadeOut(t, 0.8) * clamp01(p.age / 160);
    if (a <= 0) return;
    const s = p.s || 1, open = clamp01((p.age - 300) / 400);
    const w = 30 * s, h = 40 * s;
    x.save();
    x.globalAlpha = a;
    x.translate(p.x, p.y);
    if (open > 0) {
      x.globalCompositeOperation = 'lighter';
      softGlow(x, 0, -h / 2, h * (0.6 + open), 'rgba(220,240,255,0.95)', open);
      x.globalCompositeOperation = 'source-over';
    }
    x.globalAlpha = a;
    x.fillStyle = '#3a3448';
    x.fillRect(-w / 2 - 2 * s, -h - 2 * s, w + 4 * s, h + 2 * s);
    x.fillStyle = '#ffffff';
    x.fillRect(-w / 2, -h, w, h);
    const dw = (w / 2) * (1 - open * 0.85);
    x.fillStyle = '#8a8296';
    x.fillRect(-w / 2, -h, dw, h);
    x.fillRect(w / 2 - dw, -h, dw, h);
    x.fillStyle = '#c8bede';
    for (const sx of [-1, 1]) for (let k = 0; k < 4; k++) x.fillRect(sx < 0 ? -w / 2 + dw * 0.3 : w / 2 - dw * 0.7, -h + (k + 0.5) * (h / 4), dw * 0.4, 1.2 * s);
    x.restore();
  },
  // れん成の 円（青い 光の わと 中の 三角）
  r66dCircle(x, p, t) {
    const a = fadeOut(t, 0.7) * clamp01(p.age / 160);
    if (a <= 0) return;
    const r = (p.r || 24) * easeOut(clamp01(p.age / 240));
    x.save();
    x.globalCompositeOperation = 'lighter';
    x.globalAlpha = a;
    x.strokeStyle = p.color || '#7ad0ff';
    x.lineWidth = 1.4;
    x.translate(p.x, p.y);
    x.scale(1, p.sy || 0.4);
    x.rotate(p.age / 500);
    x.beginPath(); x.arc(0, 0, r, 0, Math.PI * 2); x.stroke();
    x.beginPath(); x.arc(0, 0, r * 0.78, 0, Math.PI * 2); x.stroke();
    x.beginPath();
    for (let k = 0; k <= 3; k++) {
      const q = -Math.PI / 2 + (k / 3) * Math.PI * 2;
      if (k) x.lineTo(Math.cos(q) * r * 0.78, Math.sin(q) * r * 0.78); else x.moveTo(Math.cos(q) * r * 0.78, Math.sin(q) * r * 0.78);
    }
    x.stroke();
    x.restore();
  },
  // 地面から せり上がる 石の はしら（うで）
  r66dRock(x, p, t) {
    const a = fadeOut(t, 0.75);
    if (a <= 0) return;
    const up = easeOut(clamp01(p.age / (p.rise || 220)));
    const s = p.s || 1, h = (p.h || 26) * s * up, w = (p.w || 8) * s;
    x.save();
    x.globalAlpha = a;
    x.translate(p.x, p.y);
    x.fillStyle = '#6a5a48';
    x.beginPath();
    x.moveTo(-w / 2, 0); x.lineTo(-w / 2 + 1 * s, -h); x.lineTo(w / 2 - 1 * s, -h - (p.fist ? 2 * s : 3 * s)); x.lineTo(w / 2, 0);
    x.closePath(); x.fill();
    x.fillStyle = '#9a8a72';
    x.fillRect(-w / 2 + 1 * s, -h, 2 * s, h);
    if (p.fist && up > 0.5) {
      x.fillStyle = '#7a6a56';
      x.beginPath(); x.arc(0, -h - 2 * s, w * 0.75, 0, Math.PI * 2); x.fill();
      x.fillStyle = '#a89880';
      x.beginPath(); x.arc(-w * 0.2, -h - 3 * s, w * 0.3, 0, Math.PI * 2); x.fill();
    }
    x.restore();
  },
  // 流れ星（光る 星と しっぽ）。x0,y0 → x1,y1
  r66dMeteor(x, p, t) {
    const travel = p.travel || 360;
    const k = clamp01(p.age / travel);
    if (p.age > travel + 40) return;
    const e = k * k;
    const cx = p.x0 + (p.x1 - p.x0) * e, cy = p.y0 + (p.y1 - p.y0) * e;
    const r = p.r || 5, col = p.color || '#fff6a0';
    x.save();
    x.globalCompositeOperation = 'lighter';
    x.globalAlpha = 0.7;
    x.strokeStyle = col;
    x.lineWidth = r * 0.9;
    x.lineCap = 'round';
    const tx = cx - (p.x1 - p.x0) * 0.25, ty = cy - (p.y1 - p.y0) * 0.25;
    x.beginPath(); x.moveTo(tx, ty); x.lineTo(cx, cy); x.stroke();
    softGlow(x, cx, cy, r * 3, col, 0.9);
    x.globalCompositeOperation = 'source-over';
    x.globalAlpha = 1;
    x.fillStyle = '#ffffff';
    starPath(x, cx, cy, r, p.age / 90);
    x.fill();
    x.restore();
  },
  // 小さな 星の 仲間（目の 点だけの まるい 星）。x0,y0 → x1,y1 を はねる。big: 大きな 星に なる
  r66dLuma(x, p, t) {
    const travel = p.travel || 360;
    const k = clamp01(p.age / travel);
    if (p.age > travel + 80) return;
    const [cx, cy] = arcAt(p, easeOut(k));
    const s = (p.s || 1) * (p.big ? 1 + k : 1);
    const col = p.color || '#fff6a0';
    x.save();
    x.globalCompositeOperation = 'lighter';
    softGlow(x, cx, cy, 9 * s, col, 0.6);
    x.globalCompositeOperation = 'source-over';
    x.globalAlpha = 1;
    x.fillStyle = col;
    starPath(x, cx, cy, 5 * s, Math.sin(p.age / 80) * 0.3);
    x.fill();
    x.fillStyle = '#2a2a3a';
    x.fillRect(cx - 1.6 * s, cy - 0.8 * s, 0.9 * s, 1.4 * s);
    x.fillRect(cx + 0.7 * s, cy - 0.8 * s, 0.9 * s, 1.4 * s);
    x.restore();
  },
  // 大きな 手のひら（つっぱり）。x0 → x1
  r66dPalm(x, p, t) {
    const travel = p.travel || 240;
    const k = clamp01(p.age / travel);
    const a = p.age > travel ? fadeOut(clamp01((p.age - travel) / 200), 0) : 1;
    if (a <= 0) return;
    const cx = p.x0 + (p.x1 - p.x0) * easeOut(k), cy = p.y0 + (p.y1 - p.y0) * easeOut(k);
    const s = p.s || 1;
    x.save();
    x.globalAlpha = a;
    x.translate(cx, cy);
    x.fillStyle = '#7ac84a';
    x.beginPath(); x.ellipse(0, 0, 7 * s, 8 * s, 0, 0, Math.PI * 2); x.fill();
    for (let f = 0; f < 4; f++) {
      x.beginPath(); x.ellipse((-4.5 + f * 3) * s, -9 * s, 1.4 * s, 3.2 * s, 0, 0, Math.PI * 2); x.fill();
    }
    x.beginPath(); x.ellipse(-8 * s, -1 * s, 3 * s, 1.5 * s, -0.5, 0, Math.PI * 2); x.fill();
    x.fillStyle = '#b8f08a';
    x.beginPath(); x.ellipse(-1.5 * s, -1.5 * s, 3 * s, 3.4 * s, 0, 0, Math.PI * 2); x.fill();
    x.restore();
  },
};

// ───────────── エフェクト ─────────────
// fx: Effects（battlefx.js）  targets: [{ x, y }]  W・H: がめんの 大きさ
export function playR66dFx(fx, anim, targets, element, opts = {}, W = 256, H = 144) {
  if (!R66D_ANIMS.has(anim) || !targets || !targets.length) return false;
  const crit = !!opts.crit;
  const all = targets.length > 1;
  const sz = all ? 0.85 : 1;
  const tx = targets.reduce((s, t) => s + t.x, 0) / targets.length;
  const from = opts.from || { x: W / 2, y: H + 6 };
  const each = (fn) => targets.forEach((t, i) => fn(t, i, i * (all ? 60 : 0)));
  const hitMark = (t, d, col, r = 16) => {
    fx.impact(t.x, t.y, { r: (crit ? r + 6 : r) * sz, color: '#ffffff', delay: d });
    fx.sparks(t.x, t.y, { colors: ['#ffffff', col], n: all ? 8 : 14, speed: 150, delay: d, life: 340, len: 7 });
  };
  const fy = Math.min(H - 16, from.y - 18);
  const ground = (t) => Math.min(H - 4, t.y + 12);
  switch (anim) {
    // ───── 看板の技 ─────
    case 'gekka_sig': {
      // 夜空に 満月 → 5まいの トランプが 扇に ならぶ → つぎつぎ 敵へ（5回ずつ）
      fx.tintAt('rgba(8, 12, 40, 0.55)', 2100);
      fx.add({ kind: 'r66dMoon', x: W * 0.78, y: 26, r: 16, life: 2000 });
      for (let k = 0; k < 5; k++) {
        fx.add({ kind: 'r66dCard', x: tx + (k - 2) * 14, y: 30 - Math.abs(k - 2) * 3, rot: (k - 2) * 0.22, s: 1.5, suit: SUITS[k], glow: 'rgba(255,240,180,0.9)', life: 520, delay: 120 + k * 60 });
      }
      for (let r = 0; r < 5; r++) {
        each((t, i, d) => {
          const dd = 640 + r * 130 + d;
          fx.add({ kind: 'r66dCard', x0: tx + (r - 2) * 14, y0: 30, x1: t.x, y1: t.y, hop: 6, travel: 90, s: 1.3, suit: SUITS[r], glow: 'rgba(200,220,255,0.9)', life: 160, delay: dd - 90 });
          hitMark(t, dd, '#fff2b0', r === 4 ? 20 : 13);
        });
      }
      fx.flashAt(90, '#f0f4ff', 1300);
      fx.hitStop(crit ? 260 : 180, 1300, 1.6);
      return true;
    }
    case 'nobu_dora_sig': {
      // ポケットが 光る → 空気ほうの わ → 名刀電光丸の 光 → どこでもドア
      fx.glow(from.x, fy, { color: '#fff6c0', r: 30, life: 500 });
      for (let k = 0; k < 8; k++) fx.twinkle(from.x + rnd(-16, 16), fy - rnd(0, 18), { color: '#ffffff', size: 5, delay: k * 40, life: 320 });
      each((t, i, d) => {
        // 空気ほう（わが 3つ）
        for (let k = 0; k < 3; k++) fx.shock(t.x, t.y, { r0: 4, r1: 30 * sz, color: '#d8f0ff', w: 2.2, delay: 520 + d + k * 70, life: 260 });
        hitMark(t, 700 + d, '#ffd66b', 18);
        // 名刀電光丸（すばやい 光の 切りあと）
        fx.cut(t.x, t.y, { ang: -0.7, len: 40 * sz, color: '#ffffff', glow: '#ffe060', delay: 980 + d, life: 260 });
        fx.cut(t.x, t.y, { ang: 0.7, len: 40 * sz, color: '#ffffff', glow: '#ffe060', delay: 1060 + d, life: 260 });
        hitMark(t, 1060 + d, '#ffe060', 16);
      });
      fx.add({ kind: 'r66dDoor', x: tx, y: Math.min(H - 6, Math.max(...targets.map((t) => t.y)) + 16), s: 1.3, openAt: 1300, life: 900, delay: 1150 });
      fx.flashAt(80, '#ffffff', 700);
      fx.hitStop(crit ? 240 : 160, 700, 1.5);
      return true;
    }
    case 'kappa_king_sig': {
      // 大きな 花が 色を かえながら さく → 花びらと 大きな しょうげき
      fx.tintAt('rgba(20, 30, 10, 0.35)', 1900);
      fx.add({ kind: 'r66dFlower', x: from.x, y: fy - 16, s: 2.0, step: 180, life: 1300 });
      for (let k = 0; k < 10; k++) fx.petal(from.x + rnd(-20, 20), fy - 20, { color: FLOWERS[k % 4][0], vx: rnd(-40, 40), vy: rnd(-60, -20), delay: 720 + k * 25, life: 900 });
      each((t, i, d) => {
        fx.add({ kind: 'r66dFlower', x: t.x, y: t.y - 10, s: 1.2, fix: Math.floor(Math.random() * 4), life: 700, delay: 860 + d });
        hitMark(t, 980 + d, '#ffe060', 24);
        fx.shock(t.x, t.y, { r0: 6, r1: 60 * sz, color: '#fff0a0', w: 3, delay: 980 + d, life: 420 });
      });
      fx.flashAt(110, '#fff6d0', 980);
      fx.hitStop(crit ? 300 : 220, 980, 2.0);
      return true;
    }
    case 'truth_gate_sig': {
      // れん成の 円 → 大きな とびらが ひらく → 大地が せり上がって 敵を つきあげる
      fx.tintAt('rgba(10, 16, 40, 0.5)', 2200);
      fx.add({ kind: 'r66dCircle', x: W / 2, y: H - 30, r: 70, sy: 0.32, life: 1900 });
      fx.add({ kind: 'r66dGate', x: W / 2, y: H * 0.62, s: 1.2, life: 1100 });
      for (let k = 0; k < 6; k++) fx.zap(W / 2 + rnd(-60, 60), H - 30, W / 2 + rnd(-60, 60), H - 50, { color: '#c8f0ff', glow: '#3a8ae8', delay: 200 + k * 90, life: 220 });
      each((t, i, d) => {
        for (let k = 0; k < 3; k++) fx.add({ kind: 'r66dRock', x: t.x + (k - 1) * 9, y: ground(t), h: 20 + k * 6, w: 8, s: sz, rise: 160, life: 760, delay: 760 + d + k * 50 });
        hitMark(t, 900 + d, '#8ad0ff', 22);
        fx.debris(t.x, ground(t), ['#9a8a72', '#6a5a48', '#c8f0ff'], all ? 6 : 10, 900 + d, 110);
      });
      fx.flashAt(110, '#e0f4ff', 900);
      fx.hitStop(crit ? 300 : 220, 900, 2.0);
      return true;
    }
    case 'rosetta_sig': {
      // 夜空に 流れ星が ふりそそぎ、小さな 星の 仲間たちが はねながら 敵へ
      fx.tintAt('rgba(10, 8, 40, 0.55)', 2100);
      for (let k = 0; k < 16; k++) fx.twinkle(rnd(8, W - 8), rnd(6, H * 0.45), { color: STARC[k % STARC.length], size: rnd(3, 6), delay: k * 30, life: 500 });
      for (let k = 0; k < 6; k++) {
        const x0 = rnd(-20, W * 0.5);
        fx.add({ kind: 'r66dMeteor', x0, y0: -10, x1: x0 + 90, y1: H * 0.5, r: 3, color: STARC[k % STARC.length], travel: 420, life: 460, delay: 100 + k * 70 });
      }
      each((t, i, d) => {
        fx.add({ kind: 'r66dMeteor', x0: t.x - 70, y0: -14, x1: t.x, y1: t.y, r: 6, color: '#fff6a0', travel: 380, life: 420, delay: 440 + d });
        hitMark(t, 820 + d, '#fff6a0', 20);
        for (let k = 0; k < 3; k++) fx.add({ kind: 'r66dLuma', x0: from.x + (k - 1) * 14, y0: fy, x1: t.x + (k - 1) * 8, y1: t.y, hop: 30, travel: 360, s: 1.1, color: STARC[(k + i) % STARC.length], life: 440, delay: 1000 + d + k * 80 });
        hitMark(t, 1360 + d, '#ffd0f0', 14);
      });
      fx.flashAt(100, '#fffbe0', 820);
      fx.hitStop(crit ? 260 : 200, 820, 1.8);
      return true;
    }
    // ───── 月下のき術師 ─────
    case 'r66d_ace': {
      each((t, i, d) => {
        fx.add({ kind: 'r66dCard', x0: from.x, y0: fy, x1: t.x, y1: t.y, hop: 10, travel: 280, s: 1.5, suit: '#1a1a2a', glow: 'rgba(255,240,180,0.95)', life: 340, delay: d });
        hitMark(t, 300 + d, '#fff2b0', 18);
      });
      fx.hitStop(crit ? 180 : 110, 300, 1.3);
      return true;
    }
    case 'r66d_cards': {
      for (let k = 0; k < 14; k++) {
        const t = targets[k % targets.length];
        fx.add({ kind: 'r66dCard', x0: from.x + rnd(-30, 30), y0: fy - rnd(0, 20), x1: t.x + rnd(-12, 12), y1: t.y + rnd(-10, 6), hop: rnd(10, 30), travel: 340, s: 1.1, suit: SUITS[k % SUITS.length], life: 380, delay: k * 25 });
      }
      each((t, i, d) => {
        hitMark(t, 380 + d, '#ffd0e0', 14);
        for (let k = 0; k < 3; k++) fx.petal(t.x + rnd(-10, 10), t.y - 8, { color: '#ffd0e0', vx: rnd(-30, 30), vy: -20, delay: 400 + d + k * 30, life: 600 });
      });
      return true;
    }
    case 'r66d_vanish': {
      fx.puff(from.x, fy, { color: '#ffffff', r0: 6, r1: 22, life: 400, alpha: 0.8 });
      each((t, i, d) => {
        fx.puff(t.x + 10, t.y - 4, { color: '#e8ecff', r0: 4, r1: 16, life: 360, alpha: 0.7, delay: 260 + d });
        fx.cut(t.x, t.y, { ang: -0.8, len: 34 * sz, color: '#ffffff', glow: '#a8c0ff', delay: 400 + d, life: 240 });
        hitMark(t, 420 + d, '#c8d8ff', 15);
        fx.cut(t.x, t.y, { ang: 0.8, len: 34 * sz, color: '#ffffff', glow: '#a8c0ff', delay: 560 + d, life: 240 });
        hitMark(t, 580 + d, '#c8d8ff', 15);
      });
      return true;
    }
    // ───── のぶドラ ─────
    case 'r66d_door': {
      each((t, i, d) => {
        fx.add({ kind: 'r66dDoor', x: t.x + 14, y: ground(t), s: 1.2, openAt: 260, life: 760, delay: d });
        fx.glow(t.x + 14, t.y, { color: '#fff6d0', r: 18, delay: 300 + d, life: 300 });
        hitMark(t, 460 + d, '#ffb0d8', 18);
      });
      fx.hitStop(crit ? 180 : 120, 460, 1.4);
      return true;
    }
    case 'r66d_shock': {
      each((t, i, d) => {
        fx.zap(from.x, fy, t.x, t.y, { color: '#fff6b0', glow: '#9ad8ff', w: 1.4, delay: d, life: 260, forks: 2 });
        fx.glow(t.x, t.y, { color: '#c8ecff', r: 18, delay: 260 + d, life: 300 });
        hitMark(t, 320 + d, '#9ad8ff', 14);
      });
      return true;
    }
    // ───── かっぱの大王 ─────
    case 'r66d_harite': {
      each((t, i, d) => {
        fx.add({ kind: 'r66dPalm', x0: from.x, y0: fy, x1: t.x, y1: t.y, travel: 260, s: 1.5, life: 460, delay: d });
        hitMark(t, 300 + d, '#c8ff9a', 22);
        fx.speedLines(t.x, t.y, { delay: 300 + d, r1: 60 });
      });
      fx.hitStop(crit ? 220 : 160, 300, 1.7);
      return true;
    }
    case 'r66d_splash': {
      for (let k = 0; k < 18; k++) fx.drop(from.x + rnd(-10, 10), fy - 10, { color: k % 2 ? '#7ac8ff' : '#e8f6ff', vx: (tx - from.x) * rnd(0.8, 1.4) + rnd(-80, 80), vy: rnd(-200, -120), g: 380, size: 1.8, delay: k * 12, life: 700 });
      each((t, i, d) => {
        hitMark(t, 360 + d, '#9ad8ff', 16);
        for (let k = 0; k < 4; k++) fx.bubble(t.x + rnd(-10, 10), t.y + rnd(-4, 8), { color: '#bfe6ff', delay: 380 + d + k * 40 });
      });
      return true;
    }
    // ───── 真理のとびらをひらく者 ─────
    case 'r66d_stonefist': {
      each((t, i, d) => {
        fx.add({ kind: 'r66dCircle', x: t.x, y: ground(t), r: 20, life: 700, delay: d });
        fx.add({ kind: 'r66dRock', x: t.x - 6, y: ground(t), h: 30, w: 9, s: 1.1, fist: true, rise: 300, life: 800, delay: 120 + d });
        hitMark(t, 420 + d, '#c8f0ff', 20);
        fx.debris(t.x, t.y, ['#9a8a72', '#6a5a48'], all ? 5 : 8, 420 + d, 90);
      });
      fx.hitStop(crit ? 200 : 140, 420, 1.6);
      return true;
    }
    case 'r66d_terrain': {
      fx.add({ kind: 'r66dCircle', x: tx, y: H - 24, r: 60, sy: 0.3, life: 900 });
      each((t, i, d) => {
        for (let k = 0; k < 2; k++) fx.add({ kind: 'r66dRock', x: t.x + (k ? 10 : -10), y: ground(t), h: 16 + k * 8, w: 10, s: sz, rise: 200, life: 700, delay: 200 + d + k * 60 });
        hitMark(t, 360 + d, '#d8c8a0', 16);
        fx.crack(t.x, ground(t) - 2, { n: 5, len: 24, delay: 300 + d });
      });
      fx.hitStop(crit ? 200 : 130, 360, 1.8);
      return true;
    }
    // ───── ロゼッタ ─────
    case 'r66d_meteor': {
      each((t, i, d) => {
        fx.add({ kind: 'r66dMeteor', x0: t.x - 80, y0: -14, x1: t.x, y1: t.y, r: 6, color: '#fff6a0', travel: 420, life: 460, delay: d });
        hitMark(t, 440 + d, '#fff6a0', 20);
        for (let k = 0; k < 5; k++) fx.twinkle(t.x + rnd(-16, 16), t.y + rnd(-14, 8), { color: STARC[k], size: 4, delay: 460 + d + k * 40, life: 320 });
      });
      fx.flashAt(70, '#fffbe0', 440);
      return true;
    }
    case 'r66d_spin': {
      fx.shock(from.x, fy, { r0: 4, r1: 30, color: '#fff6a0', w: 2, life: 300 });
      each((t, i, d) => {
        fx.swirl(t.x, t.y + 6, ['#fff6a0', '#a8e8ff', '#ffffff'], { n: 18, rad: 14, h: 30, delay: 120 + d, life: 420 });
        hitMark(t, 300 + d, '#fff6a0', 15);
      });
      return true;
    }
    case 'r66d_luma': {
      each((t, i, d) => {
        for (let k = 0; k < 3; k++) {
          fx.add({ kind: 'r66dLuma', x0: from.x + (k - 1) * 16, y0: fy, x1: t.x, y1: t.y, hop: 24, travel: 380, s: 1.2, big: true, color: STARC[(k + i) % STARC.length], life: 460, delay: d + k * 60 });
        }
        hitMark(t, 420 + d, '#fff6a0', 16);
      });
      return true;
    }
  }
  return false;
}

js/client/render/battlefx-r66e1.js:
// 第66回 E1班の 技の エフェクト（公安ゼロ・トリプルフェイス・ハイパーレスキュー・火消しの神・登録者1000万人・世界一の配信者）
// 技の id では なく「えんしゅつの なまえ（anim）」で ひく。技の データの anim に ここの なまえを 書く（例 anim: 'triple_face_sig'）。
// battlefx.js の play() で battlefx-r43j.js の つぎに よばれる（ここに ない anim なら false を かえす）。
// え は かんたんな かたち（顔・ロゴ・文字は かかない）。自分や 仲間に かける 技は 前から ある えんしゅつ（buff・guard・heal2 など）なので、ここは 敵に 出す 物だけ
//
// 看板の技（なまえは '<職業の id>_sig'）
//  koan_zero_sig      ゼロの正義ラッシュ … 画面が こい あいいろに → 敵ごとに こぶしの しょうげきが 3回ずつ・さいごに 光の 十字
//  triple_face_sig    トリプル・ジャスティス … 3色（こん・黒・金）の 仮面の かげが 回り、敵ごとに 3回の 連打 → 金の 大きな しょうげき
//  hyper_rescue_sig   ハイパーウォーターキャノン … 下から 太い 水の ビームが 敵へ・大きな しぶき（仲間には 水しぶきの きらきら）
//  hikeshi_god_sig    天の川大放水 … 画面が 夜空に → 星の 川が 上から 流れ落ちて 敵を のみこむ・赤い まといの しるし
//  top_streamer_sig   同時接続1000万人 … コメントの ふきだしと ハートが 画面中を 流れ、敵に 光が ふる
//  world_streamer_sig コメントの大嵐 … 画面が 金色に → ふきだし・ハート・地球の まるが うずを まいて 敵を つつむ
// ほかの 技
//  r66e1_jab       ジャブ … 小さな こぶしの しょうげきが すばやく 3〜4回
//  r66e1_disguise  変そう … 白い けむりが ぽんと 出て、仮面の かげが 敵の 上を 回る・虫めがねの わ
//  r66e1_car       スポーツカー … 白い 車の かげが 左から 右へ 走りぬける（スピードの 線）
//  r66e1_comment   コメント … 白い ふきだしが 右から 左へ 流れて 敵に ぶつかる
//  r66e1_wave      大水 … 水の 大波が 横から 敵を おし流す（しぶき）
// ・どれも 2.2びょう いないで おわる。あたる じかんは R66E1_HIT（battle.js の HIT_DELAY に まぜる）

const rnd = (a, b) => a + Math.random() * (b - a);
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const easeOut = (t) => 1 - (1 - t) * (1 - t) * (1 - t);

export const R66E1_SIG_JOBS = ['koan_zero', 'triple_face', 'hyper_rescue', 'hikeshi_god', 'top_streamer', 'world_streamer'];
export const R66E1_SIGS = R66E1_SIG_JOBS.map((j) => `${j}_sig`);
export const R66E1_MOVES = ['r66e1_jab', 'r66e1_disguise', 'r66e1_car', 'r66e1_comment', 'r66e1_wave'];
export const R66E1_ANIMS = new Set([...R66E1_SIGS, ...R66E1_MOVES]);
// あたる じかん（ms。ダメージの 数字を この ときに 出す）
export const R66E1_HIT = {
  koan_zero_sig: 520, triple_face_sig: 760, hyper_rescue_sig: 560, hikeshi_god_sig: 820, top_streamer_sig: 640, world_streamer_sig: 820,
  r66e1_jab: 200, r66e1_disguise: 380, r66e1_car: 420, r66e1_comment: 420, r66e1_wave: 460,
};
// たたかいの 音（battle.js の ANIM_SFX に まぜる。audio.js・sfx-r26.js に ある 音）
export const R66E1_SFX = {
  koan_zero_sig: 'smash', triple_face_sig: 'smash', hyper_rescue_sig: 'splash', hikeshi_god_sig: 'splash', top_streamer_sig: 'sparkle', world_streamer_sig: 'sparkle',
  r66e1_jab: 'hit', r66e1_disguise: 'pu', r66e1_car: 'train', r66e1_comment: 'pon', r66e1_wave: 'splash',
};

// ───────────── え の ぶひん ─────────────
function roundRect(x, cx, cy, w, h, r) {
  x.beginPath();
  x.moveTo(cx - w / 2 + r, cy - h / 2);
  x.lineTo(cx + w / 2 - r, cy - h / 2);
  x.quadraticCurveTo(cx + w / 2, cy - h / 2, cx + w / 2, cy - h / 2 + r);
  x.lineTo(cx + w / 2, cy + h / 2 - r);
  x.quadraticCurveTo(cx + w / 2, cy + h / 2, cx + w / 2 - r, cy + h / 2);
  x.lineTo(cx - w / 2 + r, cy + h / 2);
  x.quadraticCurveTo(cx - w / 2, cy + h / 2, cx - w / 2, cy + h / 2 - r);
  x.lineTo(cx - w / 2, cy - h / 2 + r);
  x.quadraticCurveTo(cx - w / 2, cy - h / 2, cx - w / 2 + r, cy - h / 2);
  x.closePath();
}
const lerpAt = (p) => {
  const k = easeOut(clamp01(p.age / (p.travel || p.life)));
  return [p.x0 + (p.x1 - p.x0) * k, p.y0 + (p.y1 - p.y0) * k];
};

export const R66E1_FINE = {
  // コメントの ふきだし（白い 角まるの 四角に 色の 線 2本。しっぽ つき）
  e66Bubble(x, p, t) {
    const [cx, cy] = lerpAt(p);
    const s = p.s || 1, w = 22 * s, h = 10 * s;
    x.save();
    x.globalAlpha = Math.max(0, 1 - Math.max(0, t - 0.75) * 4);
    x.fillStyle = '#ffffff';
    roundRect(x, cx, cy, w, h, 3 * s);
    x.fill();
    x.beginPath();
    x.moveTo(cx - w * 0.2, cy + h / 2 - 0.5);
    x.lineTo(cx - w * 0.32, cy + h / 2 + 4 * s);
    x.lineTo(cx - w * 0.05, cy + h / 2 - 0.5);
    x.fill();
    x.strokeStyle = p.color || '#ff48d8';
    x.lineWidth = 1.2 * s;
    x.beginPath();
    x.moveTo(cx - w * 0.35, cy - h * 0.15); x.lineTo(cx + w * 0.3, cy - h * 0.15);
    x.moveTo(cx - w * 0.35, cy + h * 0.18); x.lineTo(cx + w * 0.1, cy + h * 0.18);
    x.stroke();
    x.restore();
  },
  // 白い スポーツカーの かげ（ひくい 車体・まるい 2つの タイヤ・赤い テールランプ）
  e66Car(x, p, t) {
    const [cx, cy] = lerpAt(p);
    const s = p.s || 1, dir = p.x1 >= p.x0 ? 1 : -1;
    x.save();
    x.globalAlpha = Math.max(0, 1 - Math.max(0, t - 0.8) * 5);
    x.translate(cx, cy);
    x.scale(dir * s, s);
    x.fillStyle = p.color || '#f4f4f8';
    x.beginPath();
    x.moveTo(-18, 2); x.lineTo(-17, -4); x.lineTo(-6, -6); x.lineTo(0, -11); x.lineTo(9, -11); x.lineTo(16, -5); x.lineTo(19, -3); x.lineTo(19, 2);
    x.closePath();
    x.fill();
    x.fillStyle = '#3a4a6a';
    x.beginPath(); x.moveTo(1, -10); x.lineTo(8, -10); x.lineTo(13, -5); x.lineTo(-3, -5); x.closePath(); x.fill();
    x.fillStyle = '#1a1a22';
    for (const wx of [-11, 12]) { x.beginPath(); x.arc(wx, 2, 3.6, 0, Math.PI * 2); x.fill(); }
    x.fillStyle = '#ff3a3a';
    x.fillRect(-18.5, -3, 2, 2);
    x.restore();
  },
  // 仮面の かげ（目の あいた アイマスクの 形。col の 色。くるっと 回る）
  e66Mask(x, p, t) {
    const k = p.age / (p.life || 600);
    const a = (p.a0 || 0) + k * (p.spin || 4);
    const cx = p.x + Math.cos(a) * (p.r || 14), cy = p.y + Math.sin(a) * (p.r || 14) * 0.4;
    const s = p.s || 1;
    x.save();
    x.globalAlpha = Math.max(0, 1 - Math.max(0, t - 0.7) * 3.3);
    x.translate(cx, cy);
    x.scale(s, s);
    x.fillStyle = p.color || '#2a2e3e';
    x.beginPath();
    x.ellipse(0, 0, 9, 4.5, 0, 0, Math.PI * 2);
    x.fill();
    // 目の あなは 白く ひかる（下の 絵を けさない）
    x.fillStyle = '#f4f6ff';
    for (const ex of [-4, 4]) { x.beginPath(); x.ellipse(ex, -0.5, 2.4, 1.5, 0, 0, Math.PI * 2); x.fill(); }
    x.restore();
  },
  // 水の 大波（はばの ある 青い 弧が 横に すすむ。上に 白い あわ）
  e66Wave(x, p, t) {
    const k = easeOut(clamp01(p.age / (p.travel || p.life)));
    const cx = p.x0 + (p.x1 - p.x0) * k;
    const h = (p.h || 30) * (0.6 + 0.4 * Math.sin(Math.min(1, k * 1.2) * Math.PI));
    const w = p.w || 46, dir = p.x1 >= p.x0 ? 1 : -1;
    x.save();
    x.globalAlpha = Math.max(0, 1 - Math.max(0, t - 0.75) * 4);
    x.fillStyle = p.color || '#3a8ae8';
    x.beginPath();
    x.moveTo(cx - (w / 2) * dir, p.y);
    x.quadraticCurveTo(cx - (w / 4) * dir, p.y - h * 1.1, cx + (w / 2) * dir, p.y - h);
    x.quadraticCurveTo(cx + (w / 3) * dir, p.y - h * 0.4, cx + (w / 2) * dir, p.y);
    x.closePath();
    x.fill();
    x.strokeStyle = '#eaf6ff';
    x.lineWidth = 2;
    x.beginPath();
    x.moveTo(cx - (w / 4) * dir, p.y - h * 0.85);
    x.quadraticCurveTo(cx + (w / 6) * dir, p.y - h * 1.15, cx + (w / 2) * dir, p.y - h);
    x.stroke();
    x.restore();
  },
  // 太い 水の ビーム（from → to。ゆらゆら ふるえる）
  e66Beam(x, p, t) {
    const grow = clamp01(p.age / 160);
    const fade = Math.max(0, 1 - Math.max(0, t - 0.7) * 3.3);
    const ex = p.x0 + (p.x1 - p.x0) * grow, ey = p.y0 + (p.y1 - p.y0) * grow;
    x.save();
    x.globalAlpha = fade;
    x.lineCap = 'round';
    x.strokeStyle = p.color || '#3a8ae8';
    x.lineWidth = (p.w || 9) + Math.sin(p.age / 30) * 1.5;
    x.beginPath(); x.moveTo(p.x0, p.y0); x.lineTo(ex, ey); x.stroke();
    x.strokeStyle = '#eaf6ff';
    x.lineWidth = (p.w || 9) * 0.35;
    x.beginPath(); x.moveTo(p.x0, p.y0); x.lineTo(ex, ey); x.stroke();
    x.restore();
  },
  // 星の 川（上から 下へ 流れる、星を ちりばめた 青い 帯）
  e66River(x, p, t) {
    const k = clamp01(p.age / (p.travel || 500));
    const y1 = p.y0 + (p.y1 - p.y0) * easeOut(k);
    x.save();
    x.globalAlpha = Math.max(0, 1 - Math.max(0, t - 0.7) * 3.3) * 0.85;
    const g = x.createLinearGradient(p.x - p.w / 2, 0, p.x + p.w / 2, 0);
    g.addColorStop(0, 'rgba(58,138,232,0)');
    g.addColorStop(0.3, '#3a8ae8');
    g.addColorStop(0.5, '#cfeaff');
    g.addColorStop(0.7, '#3a8ae8');
    g.addColorStop(1, 'rgba(58,138,232,0)');
    x.fillStyle = g;
    x.fillRect(p.x - p.w / 2, p.y0, p.w, y1 - p.y0);
    x.fillStyle = '#fff6c0';
    for (let i = 0; i < 10; i++) {
      const sy = p.y0 + ((i * 17 + p.age * 0.12) % Math.max(1, y1 - p.y0));
      const sx = p.x + Math.sin(i * 2.3) * p.w * 0.3;
      x.fillRect(sx - 0.8, sy - 0.8, 1.6, 1.6);
    }
    x.restore();
  },
};

export function playR66e1Fx(fx, anim, targets, element, opts = {}, W = 256, H = 144) {
  if (!R66E1_ANIMS.has(anim) || !targets || !targets.length) return false;
  const crit = !!opts.crit;
  const all = targets.length > 1;
  const sz = all ? 0.85 : 1;
  const from = opts.from || { x: W / 2, y: H + 6 };
  const each = (fn) => targets.forEach((t, i) => fn(t, i, i * (all ? 50 : 0)));
  const punch = (t, d, col = '#ffffff', r = 12) => {
    fx.impact(t.x + rnd(-6, 6), t.y + rnd(-6, 4), { r: (crit ? r + 5 : r) * sz, color: col, delay: d });
    fx.sparks(t.x, t.y, { colors: ['#ffffff', col], n: all ? 5 : 8, speed: 130, delay: d, life: 260, len: 6 });
  };
  const splash = (t, d) => {
    for (let k = 0; k < (all ? 5 : 8); k++) fx.drop(t.x + rnd(-6, 6), t.y - 4, { color: k % 2 ? '#9ad8ff' : '#3a8ae8', vx: rnd(-70, 70), vy: rnd(-120, -50), g: 320, size: 1.6, delay: d, life: 520 });
    fx.shock(t.x, t.y + 6, { r0: 4, r1: 26 * sz, color: '#9ad8ff', w: 2, delay: d, life: 360, sy: 0.4 });
  };
  const COM = ['#ff48d8', '#38e8ff', '#ffd23a', '#7aff7a'];
  switch (anim) {
    // ───── 看板の技 ─────
    case 'koan_zero_sig': {
      fx.tintAt('rgba(10, 16, 40, 0.4)', 1300);
      for (let r = 0; r < 3; r++) each((t, i, d) => punch(t, 160 + r * 150 + d, '#bcd4ff', 13));
      each((t, i, d) => {
        fx.cut(t.x, t.y, { ang: 0, len: 40 * sz, w: 2.5, color: '#ffffff', glow: '#7aa8ff', delay: 640 + d, life: 320 });
        fx.cut(t.x, t.y, { ang: Math.PI / 2, len: 40 * sz, w: 2.5, color: '#ffffff', glow: '#7aa8ff', delay: 640 + d, life: 320 });
      });
      fx.flashAt(90, '#dbe8ff', 640);
      fx.hitStop(crit ? 220 : 160, 520, 1.5);
      return true;
    }
    case 'triple_face_sig': {
      fx.tintAt('rgba(8, 10, 24, 0.5)', 1800);
      const cols = ['#1e2848', '#16161e', '#d0a838'];
      each((t, i, d) => cols.forEach((c, k) => fx.add({ kind: 'e66Mask', x: t.x, y: t.y - 22, r: 16, a0: (k * Math.PI * 2) / 3, spin: 5, s: 1.1, color: c, life: 700, delay: d })));
      for (let r = 0; r < 3; r++) each((t, i, d) => punch(t, 760 + r * 160 + d, cols[r] === '#16161e' ? '#a8a8c8' : cols[r] === '#1e2848' ? '#7aa8ff' : '#ffd66b', 14));
      each((t, i, d) => fx.shock(t.x, t.y, { r0: 6, r1: 52 * sz, color: '#ffd66b', w: 3, delay: 1300 + d, life: 420 }));
      fx.flashAt(110, '#fff2c8', 1300);
      fx.hitStop(crit ? 300 : 240, 760, 2.0);
      return true;
    }
    case 'hyper_rescue_sig': {
      const fy = Math.min(H - 10, from.y - 14);
      each((t, i, d) => {
        fx.add({ kind: 'e66Beam', x0: from.x, y0: fy, x1: t.x, y1: t.y, w: 10, color: '#3a8ae8', life: 900, delay: d });
        splash(t, 560 + d);
        splash(t, 820 + d);
      });
      for (let k = 0; k < 10; k++) fx.twinkle(rnd(16, W - 16), rnd(H * 0.55, H - 8), { color: '#cfeaff', size: rnd(2, 4), delay: 600 + k * 40, life: 360 });
      fx.hitStop(crit ? 220 : 160, 560, 1.4);
      return true;
    }
    case 'hikeshi_god_sig': {
      fx.tintAt('rgba(4, 8, 36, 0.55)', 2000);
      for (let k = 0; k < 14; k++) fx.twinkle(rnd(8, W - 8), rnd(4, H * 0.45), { color: '#fff6c0', size: rnd(2, 4), delay: k * 30, life: 500 });
      each((t, i, d) => {
        fx.add({ kind: 'e66River', x: t.x, y0: 0, y1: t.y + 8, w: 34 * sz, travel: 520, life: 1200, delay: 200 + d });
        splash(t, 820 + d);
        splash(t, 1100 + d);
      });
      fx.pillar(from.x, Math.min(H - 6, from.y - 10), '#d8202c', { w: 4, h: 34, delay: 0, life: 700, edge: '#ffd66b' });
      fx.flashAt(100, '#dff0ff', 820);
      fx.hitStop(crit ? 280 : 220, 820, 1.8);
      return true;
    }
    case 'top_streamer_sig': {
      fx.tintAt('rgba(30, 6, 30, 0.35)', 1500);
      for (let k = 0; k < 10; k++) {
        const y = rnd(10, H * 0.7);
        fx.add({ kind: 'e66Bubble', x0: W + 20, y0: y, x1: -20, y1: y, travel: 900, life: 900, s: rnd(0.8, 1.1), color: COM[k % COM.length], delay: k * 60 });
      }
      each((t, i, d) => {
        for (let k = 0; k < 4; k++) { const hx = from.x + rnd(-30, 30); fx.add({ kind: 'heart', x: hx, y: H, x0: hx, y0: H, x1: t.x + rnd(-8, 8), y1: t.y, travel: 420, life: 460, color: k % 2 ? '#ff7ab8' : '#ff48d8', size: 3, delay: 200 + k * 60 + d }); }
        fx.glow(t.x, t.y, { color: '#ffe0f4', r: 22 * sz, delay: 640 + d, life: 360 });
        punch(t, 640 + d, '#ff7ab8', 15);
      });
      fx.flashAt(90, '#fff0fa', 640);
      return true;
    }
    case 'world_streamer_sig': {
      fx.tintAt('rgba(40, 28, 0, 0.4)', 2000);
      for (let k = 0; k < 16; k++) {
        const y = rnd(8, H * 0.8), ltr = k % 2;
        fx.add({ kind: 'e66Bubble', x0: ltr ? -20 : W + 20, y0: y, x1: ltr ? W + 20 : -20, y1: y + rnd(-10, 10), travel: 1000, life: 1000, s: rnd(0.8, 1.2), color: COM[k % COM.length], delay: k * 45 });
      }
      each((t, i, d) => {
        fx.swirl(t.x, t.y, ['#ffd23a', '#ffffff', '#ff48d8', '#38e8ff'], { n: 28, rad: 22 * sz, h: 46, delay: 300 + d, life: 800 });
        for (let k = 0; k < 3; k++) { const hx = t.x + rnd(-40, 40); fx.add({ kind: 'heart', x: hx, y: -10, x0: hx, y0: -10, x1: t.x, y1: t.y, travel: 480, life: 520, color: '#ff48d8', size: 3, delay: 360 + k * 80 + d }); }
        fx.shock(t.x, t.y, { r0: 6, r1: 56 * sz, color: '#ffd23a', w: 3, delay: 820 + d, life: 420 });
        punch(t, 820 + d, '#ffd23a', 16);
      });
      fx.flashAt(110, '#fff6d0', 820);
      fx.hitStop(crit ? 300 : 240, 820, 2.0);
      return true;
    }
    // ───── ほかの 技 ─────
    case 'r66e1_jab': {
      for (let r = 0; r < 4; r++) each((t, i, d) => punch(t, 60 + r * 90 + d, '#bcd4ff', 9));
      fx.hitStop(crit ? 160 : 90, 200, 1.0);
      return true;
    }
    case 'r66e1_disguise': {
      each((t, i, d) => {
        fx.puff(t.x, t.y - 6, { color: '#eef0f6', r0: 4, r1: 18 * sz, life: 420, alpha: 0.8, delay: d });
        fx.add({ kind: 'e66Mask', x: t.x, y: t.y - 20, r: 12, spin: 4, s: 1, color: '#2a2e3e', life: 700, delay: 120 + d });
        fx.ring(t.x, t.y, '#ffd66b', 2, 380 + d, 360, 22);
      });
      return true;
    }
    case 'r66e1_car': {
      const y = Math.min(H - 14, targets.reduce((s, t) => s + t.y, 0) / targets.length + 10);
      fx.add({ kind: 'e66Car', x0: -30, y0: y, x1: W + 30, y1: y, travel: 760, life: 760, s: 1.3 });
      fx.speedLines(W / 2, y - 6, { color: '#ffffff', n: 14, delay: 200, life: 320, r0: 30, r1: 120 });
      each((t, i, d) => punch(t, 420 + d, '#ffffff', 13));
      fx.hitStop(crit ? 180 : 120, 420, 1.2);
      return true;
    }
    case 'r66e1_comment': {
      each((t, i, d) => {
        for (let k = 0; k < 4; k++) fx.add({ kind: 'e66Bubble', x0: W + 20, y0: t.y - 20 + k * 9, x1: t.x, y1: t.y - 8 + k * 4, travel: 380, life: 460, s: 0.9, color: COM[k % COM.length], delay: k * 40 + d });
        punch(t, 420 + d, '#ff7ab8', 11);
      });
      return true;
    }
    case 'r66e1_wave': {
      const y = Math.min(H - 6, Math.max(...targets.map((t) => t.y)) + 14);
      fx.add({ kind: 'e66Wave', x0: -30, y: y, x1: W + 30, h: 34, w: 60, travel: 900, life: 900, color: '#3a8ae8' });
      each((t, i, d) => splash(t, 460 + d));
      fx.hitStop(crit ? 180 : 120, 460, 1.2);
      return true;
    }
  }
  return false;
}

js/client/render/battlefx-r66e2.js:
// 第66回 E2班の 6つの 職業の 技の エフェクト（data/abilities-r66e2.js。docs/plan-r66-legend.md）
// 技の id では なく「えんしゅつの なまえ（anim）」で ひく。battlefx.js の play() で battlefx-r43j.js の つぎに よばれる
// （ここに ない anim なら false を かえす）。え は かんたんな かたち（ロゴ・顔・文字は かかない）
//
// 看板の技（なまえは '<職業の id>_sig'）
//  esports_king_sig   ワールドチャンピオンコンボ … 4色の ボタンが ひかり、敵 みんなに 4回ずつ 金の コンボの 光
//  game_god_sig       パーフェクトクリア … ドットの ブロックが ふり、金の 星が 光って 敵に 4回ずつ・さいごに 花火（みかたに 守りの やじるし）
//  gold_cardman_sig   楽天ゴールドカード！ … 金の カードが つぎつぎ とんで 敵を 切り、金貨が はねる
//  black_cardman_sig  楽天ブラックカード！ … 黒と 金の カードが うずを まいて 敵に ふりそそぎ、大きな 金の しょうげき
//  psychicer_sig      サイコキネシス・マックス … むらさきの 波が 敵を つつみ、うかせて（つぶが 上へ）地面に たたきつける
//  saiki_sig          やれやれ、本気の超能力 … 画面が くらく なり、ピンクと 緑の 光の わが 広がって、敵 みんなに 大きな 光の しょうげき
// ほかの 技
//  r66e2_combo   ボタンの 光が ぽんぽんと はじけて、小さな あたりが つづく（れんだ・コンボ）
//  r66e2_card    金の カードが くるくる 回って とび、ズバッと 切る
//  r66e2_psy     むらさきの 波が あいてに あつまって、ぎゅっと おしつぶす（念力）
//  r66e2_save    青い セーブの しるし（四角い ディスク）が うかんで、きらきら（みかた）
//  r66e2_load    まき もどしの わ（やじるしの 弧が ぎゃくに 回る）と、回復の 光（みかた）
//  r66e2_limiter ピンクの 光の わと 上へ のびる やじるし（制御装置を はずす。みかた。自分）
// ・どれも 2.2びょう いないで おわる。あたる じかんは R66E2_HIT（battle.js の HIT_DELAY に まぜる）
// ・みかたに つかう えんしゅつ（PARTY_ANIMS_R66E2）は、battle.js が がめんの 下の まん中に 出す

const rnd = (a, b) => a + Math.random() * (b - a);
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const easeOut = (t) => 1 - (1 - t) * (1 - t) * (1 - t);
const fadeOut = (t, from = 0.7) => (t < from ? 1 : Math.max(0, 1 - (t - from) / (1 - from)));

export const R66E2_SIG_JOBS = ['esports_king', 'gold_cardman', 'psychicer', 'game_god', 'black_cardman', 'saiki'];
export const R66E2_SIGS = R66E2_SIG_JOBS.map((j) => `${j}_sig`);
export const R66E2_MOVES = ['r66e2_combo', 'r66e2_card', 'r66e2_psy', 'r66e2_save', 'r66e2_load', 'r66e2_limiter'];
export const R66E2_ANIMS = new Set([...R66E2_SIGS, ...R66E2_MOVES]);
// みかたに つかう えんしゅつ（敵が いない ときは がめんの 下に 大きく 出す）
export const PARTY_ANIMS_R66E2 = new Set(['r66e2_save', 'r66e2_load', 'r66e2_limiter']);
// あたる じかん（ms。ダメージの 数字を この ときに 出す）
export const R66E2_HIT = {
  esports_king_sig: 600, game_god_sig: 760, gold_cardman_sig: 520, black_cardman_sig: 640, psychicer_sig: 700, saiki_sig: 780,
  r66e2_combo: 260, r66e2_card: 360, r66e2_psy: 380,
};
// たたかいの 音（battle.js の ANIM_SFX に まぜる。audio.js・sfx-r26.js に ある 音）
export const R66E2_SFX = {
  esports_king_sig: 'smash', game_god_sig: 'sparkle', gold_cardman_sig: 'cardfly', black_cardman_sig: 'cardfly', psychicer_sig: 'void', saiki_sig: 'void',
  r66e2_combo: 'click', r66e2_card: 'card', r66e2_psy: 'void', r66e2_save: 'item', r66e2_load: 'warp', r66e2_limiter: 'kirari',
};

// ゲームの ボタンの 4色・お金の 金・念力の むらさき・さいきの ピンクと 緑
const PAD = ['#ff4a5a', '#4ac8ff', '#5ae86a', '#ffd040'];
const GOLD = ['#fff6c0', '#ffd84a', '#e0a81c'];
const PSY = ['#f0d0ff', '#c070ff', '#7a2ad8'];
const SAIKI = ['#ffd0e8', '#ff78b8', '#5ae8a0'];

function softGlow(x, cx, cy, r, col, a) {
  const g = x.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, col);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.globalAlpha = a;
  x.fillStyle = g;
  x.fillRect(cx - r, cy - r, r * 2, r * 2);
}

export const R66E2_FINE = {
  // くるくる 回る カード（x0,y0 → x1,y1。c: 色・edge: ふちの 色）
  r66e2Card(x, p, t) {
    const travel = p.travel || 300;
    const k = clamp01(p.age / travel);
    if (p.age > travel + 60) return;
    const e = easeOut(k);
    const cx = p.x0 + (p.x1 - p.x0) * e, cy = p.y0 + (p.y1 - p.y0) * e - Math.sin(k * Math.PI) * (p.hop || 0);
    const s = p.s || 1;
    x.save();
    x.translate(cx, cy);
    x.rotate(p.age / 45 + (p.rot || 0));
    x.globalAlpha = k >= 1 ? fadeOut(clamp01((p.age - travel) / 60), 0) : 1;
    x.fillStyle = p.edge || '#fff6c0';
    x.fillRect(-5.2 * s, -3.4 * s, 10.4 * s, 6.8 * s);
    x.fillStyle = p.c || '#e8b830';
    x.fillRect(-4.6 * s, -2.8 * s, 9.2 * s, 5.6 * s);
    // IC チップ（小さな 四角）と 線
    x.fillStyle = p.chip || '#fff0a0';
    x.fillRect(-3.4 * s, -1.4 * s, 2.4 * s, 1.8 * s);
    x.fillStyle = p.edge || '#fff6c0';
    x.fillRect(-3.4 * s, 1.4 * s, 6.6 * s, 0.6 * s);
    x.restore();
  },
  // ゲームの ボタン（まるい 光が ぽんと ふくらんで 消える）
  r66e2Button(x, p, t) {
    const a = fadeOut(t, 0.5);
    if (a <= 0) return;
    const r = (p.r || 4) * (0.5 + 0.8 * easeOut(clamp01(p.age / 160)));
    x.save();
    x.globalCompositeOperation = 'lighter';
    softGlow(x, p.x, p.y, r * 2.6, p.c || '#ffffff', a * 0.7);
    x.globalCompositeOperation = 'source-over';
    x.globalAlpha = a;
    x.fillStyle = p.c || '#ffffff';
    x.beginPath(); x.arc(p.x, p.y, r, 0, Math.PI * 2); x.fill();
    x.fillStyle = '#ffffff';
    x.beginPath(); x.arc(p.x - r * 0.3, p.y - r * 0.3, r * 0.35, 0, Math.PI * 2); x.fill();
    x.restore();
  },
  // ドットの ブロック（上から おちて くる 四角）
  r66e2Pixel(x, p, t) {
    const a = fadeOut(t, 0.75);
    if (a <= 0) return;
    const y = p.y0 + (p.y1 - p.y0) * easeOut(clamp01(p.age / (p.travel || 400)));
    const s = p.s || 3;
    x.save();
    x.globalAlpha = a;
    x.fillStyle = p.c || '#ffd840';
    x.fillRect(Math.round(p.x - s), Math.round(y - s), Math.round(s * 2), Math.round(s * 2));
    x.fillStyle = 'rgba(255,255,255,0.7)';
    x.fillRect(Math.round(p.x - s), Math.round(y - s), Math.round(s), Math.max(1, Math.round(s * 0.5)));
    x.restore();
  },
  // セーブの しるし（四角い ディスク。青い 体・白い ラベル・銀の まど）
  r66e2Floppy(x, p, t) {
    const a = fadeOut(t, 0.7);
    if (a <= 0) return;
    const s = (p.s || 1) * (0.6 + 0.4 * easeOut(clamp01(p.age / 220)));
    x.save();
    x.globalAlpha = a;
    x.translate(p.x, p.y - p.age * 0.012);
    x.fillStyle = '#1e3c8a';
    x.fillRect(-6 * s, -6 * s, 12 * s, 12 * s);
    x.fillStyle = '#c8ccd8';
    x.fillRect(-3.4 * s, -6 * s, 6.8 * s, 4 * s);
    x.fillStyle = '#1e3c8a';
    x.fillRect(0.8 * s, -5.4 * s, 1.6 * s, 2.8 * s);
    x.fillStyle = '#f6f6fa';
    x.fillRect(-4.4 * s, 0.4 * s, 8.8 * s, 4.6 * s);
    x.restore();
  },
  // まき もどしの わ（やじるしの 弧が ぎゃくに 回る）
  r66e2Rewind(x, p, t) {
    const a = fadeOut(t, 0.6);
    if (a <= 0) return;
    const r = (p.r || 14) * (0.7 + 0.3 * easeOut(clamp01(p.age / 260)));
    const rot = -p.age / 130;
    x.save();
    x.globalAlpha = a;
    x.globalCompositeOperation = 'lighter';
    x.strokeStyle = p.c || '#9af0ff';
    x.lineWidth = 2.2;
    for (let i = 0; i < 2; i++) {
      const a0 = rot + i * Math.PI;
      x.beginPath(); x.arc(p.x, p.y, r, a0, a0 + Math.PI * 0.7); x.stroke();
      // やじるしの さき（ぎゃく まわり）
      const hx = p.x + Math.cos(a0) * r, hy = p.y + Math.sin(a0) * r;
      const tx = Math.sin(a0), ty = -Math.cos(a0);
      x.fillStyle = p.c || '#9af0ff';
      x.beginPath();
      x.moveTo(hx + tx * 4, hy + ty * 4);
      x.lineTo(hx + Math.cos(a0) * 3, hy + Math.sin(a0) * 3);
      x.lineTo(hx - Math.cos(a0) * 3, hy - Math.sin(a0) * 3);
      x.closePath();
      x.fill();
    }
    x.restore();
  },
  // あつまる 波（大きな わが 小さく なって 中に あつまる。念力）
  r66e2Wave(x, p, t) {
    const a = fadeOut(t, 0.55);
    if (a <= 0) return;
    const k = easeOut(clamp01(p.age / (p.travel || 300)));
    const r = (p.r0 || 30) + ((p.r1 ?? 4) - (p.r0 || 30)) * k;
    x.save();
    x.globalCompositeOperation = 'lighter';
    x.globalAlpha = a * 0.9;
    x.strokeStyle = p.c || '#c070ff';
    x.lineWidth = p.w || 1.8;
    x.beginPath(); x.ellipse(p.x, p.y, Math.max(1, r), Math.max(1, r * (p.sy || 0.8)), 0, 0, Math.PI * 2); x.stroke();
    x.restore();
  },
};

// ───────────── エフェクト ─────────────
// fx: Effects（battlefx.js）  targets: [{ x, y }]  W・H: がめんの 大きさ
export function playR66e2Fx(fx, anim, targets, element, opts = {}, W = 256, H = 144) {
  if (!R66E2_ANIMS.has(anim) || !targets || !targets.length) return false;
  if (targets.some((t) => !Number.isFinite(t.x) || !Number.isFinite(t.y))) return false;
  const crit = !!opts.crit;
  const all = targets.length > 1;
  const sz = all ? 0.85 : 1;
  const from = opts.from || { x: W / 2, y: H + 6 };
  const fy = Math.min(H - 16, from.y - 18);
  const each = (fn) => targets.forEach((t, i) => fn(t, i, i * (all ? 50 : 0)));
  const hitMark = (t, d, col, r = 16) => {
    fx.impact(t.x, t.y, { r: (crit ? r + 6 : r) * sz, color: '#ffffff', delay: d });
    fx.sparks(t.x, t.y, { colors: ['#ffffff', col], n: all ? 8 : 12, speed: 150, delay: d, life: 320, len: 7 });
  };
  const cardsTo = (t, d, k, col, edge) => {
    fx.add({ kind: 'r66e2Card', x0: from.x + rnd(-10, 10), y0: fy, x1: t.x, y1: t.y, hop: 16 + k * 4, travel: 300, s: 1.2, c: col, edge, life: 380, delay: d, rot: k });
  };
  const coins = (t, d) => {
    for (let k = 0; k < 4; k++) fx.twinkle(t.x + rnd(-10, 10), t.y - 8, { color: GOLD[k % 3], size: 4, delay: d + k * 40, life: 420, vy: -40, g: 120 });
  };
  switch (anim) {
    // ───── 看板の技 ─────
    case 'esports_king_sig': {
      fx.tintAt('rgba(8, 10, 30, 0.45)', 1500);
      // 4色の ボタンが 手もとで ひかる
      PAD.forEach((c, k) => fx.add({ kind: 'r66e2Button', x: from.x + (k - 1.5) * 12, y: fy - 6 - (k % 2) * 6, r: 4, c, life: 500, delay: k * 60 }));
      // 敵 みんなに 4回ずつ（金の コンボの 光）
      for (let r = 0; r < 4; r++) {
        each((t, i) => {
          const d = 300 + r * 110 + i * 40;
          fx.add({ kind: 'r66e2Button', x: t.x + rnd(-8, 8), y: t.y + rnd(-10, 6), r: 3.4, c: PAD[(r + i) % 4], life: 320, delay: d });
          hitMark(t, d, GOLD[1], 12 + r * 2);
        });
      }
      each((t, i, d) => fx.shock(t.x, t.y, { r0: 6, r1: 44 * sz, color: GOLD[1], w: 2.4, delay: 780 + d, life: 360 }));
      fx.flashAt(90, '#fff6d0', 780);
      fx.hitStop(crit ? 260 : 190, 780, 1.6);
      return true;
    }
    case 'game_god_sig': {
      fx.tintAt('rgba(10, 8, 30, 0.5)', 2000);
      // ドットの ブロックが ふる
      for (let k = 0; k < 18; k++) {
        const px = rnd(10, W - 10);
        fx.add({ kind: 'r66e2Pixel', x: px, y0: -8, y1: rnd(H * 0.2, H * 0.6), s: rnd(2, 3.5), c: [...PAD, '#ffffff'][k % 5], travel: 420, life: 900, delay: k * 30 });
      }
      // 金の 星が 光って 敵に 4回ずつ
      for (let r = 0; r < 4; r++) {
        each((t, i) => {
          const d = 420 + r * 120 + i * 40;
          fx.twinkle(t.x + rnd(-8, 8), t.y + rnd(-12, 4), { color: GOLD[r % 3], size: 7, delay: d, life: 300, spin: 4 });
          hitMark(t, d, GOLD[1], 14);
          fx.debris(t.x, t.y, PAD, all ? 3 : 5, d, 70);
        });
      }
      // さいごに 花火（クリア！）
      each((t, i, d) => {
        fx.shock(t.x, t.y, { r0: 8, r1: 56 * sz, color: '#fff6b0', w: 3, delay: 1000 + d, life: 420 });
        fx.burst(t.x, t.y - 20, [...GOLD, ...PAD], all ? 10 : 18, 110, { delay: 1060 + d });
      });
      fx.flashAt(110, '#fff6d0', 1000);
      fx.hitStop(crit ? 300 : 230, 1000, 2.0);
      return true;
    }
    case 'gold_cardman_sig': {
      fx.tintAt('rgba(40, 24, 0, 0.35)', 1300);
      fx.glow(from.x, fy, { color: GOLD[1], r: 30, life: 500 });
      for (let k = 0; k < 6; k++) {
        const t = targets[k % targets.length];
        cardsTo(t, 120 + k * 70, k, '#e8b830', '#fff6c0');
        hitMark(t, 420 + k * 70, GOLD[1], 14);
      }
      each((t, i, d) => coins(t, 700 + d));
      fx.flashAt(80, '#fff0b0', 520);
      fx.hitStop(crit ? 220 : 150, 520, 1.5);
      return true;
    }
    case 'black_cardman_sig': {
      fx.tintAt('rgba(6, 4, 10, 0.55)', 1600);
      // 黒と 金の カードが うずを まく
      for (let k = 0; k < 10; k++) {
        const a = (k / 10) * Math.PI * 2;
        fx.add({ kind: 'r66e2Card', x0: from.x + Math.cos(a) * 30, y0: fy - 20 + Math.sin(a) * 14, x1: from.x + Math.cos(a + 2) * 18, y1: fy - 30 + Math.sin(a + 2) * 8, hop: 0, travel: 300, s: 1.1, c: '#26222e', edge: '#e0a81c', chip: '#ffd84a', life: 340, delay: k * 25 });
      }
      for (let k = 0; k < 8; k++) {
        const t = targets[k % targets.length];
        fx.add({ kind: 'r66e2Card', x0: from.x + rnd(-24, 24), y0: fy - 30, x1: t.x, y1: t.y, hop: 10, travel: 260, s: 1.3, c: '#26222e', edge: '#e0a81c', chip: '#ffd84a', life: 320, delay: 360 + k * 40 });
        hitMark(t, 620 + k * 40, GOLD[1], 14);
      }
      each((t, i, d) => {
        fx.shock(t.x, t.y, { r0: 8, r1: 54 * sz, color: GOLD[1], w: 3, delay: 940 + d, life: 420 });
        coins(t, 980 + d);
      });
      fx.flashAt(100, '#ffe8a0', 940);
      fx.hitStop(crit ? 280 : 210, 940, 1.9);
      return true;
    }
    case 'psychicer_sig': {
      fx.tintAt('rgba(30, 6, 50, 0.45)', 1600);
      each((t, i, d) => {
        // むらさきの 波が つつむ → うかせる → たたきつける
        for (let k = 0; k < 3; k++) fx.add({ kind: 'r66e2Wave', x: t.x, y: t.y, r0: 40, r1: 8, c: PSY[k % 3], travel: 320, life: 420, delay: d + k * 90 });
        for (let k = 0; k < 6; k++) fx.puff(t.x + rnd(-12, 12), t.y + 10, { color: PSY[0], vy: -60, r0: 2, r1: 6, life: 500, alpha: 0.6, delay: 300 + d + k * 30 });
        fx.shock(t.x, t.y + 10, { r0: 8, r1: 52 * sz, color: PSY[1], w: 3, sy: 0.4, delay: 700 + d, life: 380 });
        fx.debris(t.x, t.y + 12, ['#c8b0e0', '#ffffff', PSY[1]], all ? 5 : 9, 720 + d, 100);
        hitMark(t, 700 + d, PSY[1], 20);
      });
      fx.flashAt(90, '#f0d8ff', 700);
      fx.hitStop(crit ? 260 : 200, 700, 1.8);
      return true;
    }
    case 'saiki_sig': {
      fx.tintAt('rgba(6, 4, 16, 0.6)', 1900);
      // めがねの きらり → ピンクと 緑の 光の わ
      fx.twinkle(from.x - 4, fy - 10, { color: SAIKI[2], size: 8, life: 400 });
      fx.twinkle(from.x + 4, fy - 10, { color: SAIKI[2], size: 8, life: 400, delay: 40 });
      for (let k = 0; k < 4; k++) fx.shock(W / 2, H * 0.45, { r0: 6, r1: 150, color: SAIKI[k % 3], w: 2, delay: 240 + k * 110, life: 520 });
      each((t, i, d) => {
        for (let k = 0; k < 2; k++) fx.add({ kind: 'r66e2Wave', x: t.x, y: t.y, r0: 46, r1: 6, c: SAIKI[k], travel: 360, life: 460, delay: 380 + d + k * 100 });
        fx.glow(t.x, t.y, { color: SAIKI[1], r: 34 * sz, delay: 760 + d, life: 420 });
        fx.shock(t.x, t.y, { r0: 8, r1: 60 * sz, color: '#ffffff', w: 3, delay: 780 + d, life: 420 });
        hitMark(t, 780 + d, SAIKI[1], 22);
      });
      fx.flashAt(120, '#ffe0f0', 780);
      fx.hitStop(crit ? 300 : 240, 780, 2.0);
      return true;
    }
    // ───── ほかの 技 ─────
    case 'r66e2_combo': {
      each((t, i, d) => {
        for (let k = 0; k < 6; k++) {
          const dd = d + k * 45;
          fx.add({ kind: 'r66e2Button', x: t.x + rnd(-10, 10), y: t.y + rnd(-12, 6), r: 3, c: PAD[k % 4], life: 260, delay: dd });
          fx.impact(t.x + rnd(-6, 6), t.y + rnd(-6, 6), { r: 9 * sz, color: '#ffffff', delay: dd + 20 });
        }
      });
      fx.hitStop(crit ? 160 : 90, 260, 1.2);
      return true;
    }
    case 'r66e2_card': {
      each((t, i, d) => {
        cardsTo(t, d, i, '#e8b830', '#fff6c0');
        hitMark(t, 320 + d, GOLD[1], 14);
        coins(t, 360 + d);
      });
      return true;
    }
    case 'r66e2_psy': {
      each((t, i, d) => {
        for (let k = 0; k < 3; k++) fx.add({ kind: 'r66e2Wave', x: t.x, y: t.y, r0: 34, r1: 6, c: PSY[k], travel: 280, life: 360, delay: d + k * 50 });
        fx.glow(t.x, t.y, { color: PSY[1], r: 20 * sz, delay: 360 + d, life: 260 });
        hitMark(t, 380 + d, PSY[1], 16);
      });
      return true;
    }
    case 'r66e2_save': {
      for (const [i, t] of targets.entries()) {
        fx.add({ kind: 'r66e2Floppy', x: t.x, y: t.y - 18, s: 1.1, life: 900, delay: i * 60 });
        fx.glow(t.x, t.y, { color: '#c8e8ff', r: 22, delay: 220 + i * 60, life: 420 });
        for (let k = 0; k < 4; k++) fx.twinkle(t.x + rnd(-12, 12), t.y + rnd(-12, 8), { color: '#ffffff', size: 4, delay: 260 + i * 60 + k * 40, life: 320 });
      }
      return true;
    }
    case 'r66e2_load': {
      for (const [i, t] of targets.entries()) {
        fx.add({ kind: 'r66e2Rewind', x: t.x, y: t.y - 4, r: 16, c: '#9af0ff', life: 800, delay: i * 50 });
        fx.glow(t.x, t.y, { color: '#c8ffd8', r: 26, delay: 300 + i * 50, life: 460 });
        for (let k = 0; k < 4; k++) fx.twinkle(t.x + rnd(-12, 12), t.y + rnd(-14, 8), { color: '#e8fff0', size: 4, delay: 360 + i * 50 + k * 40, life: 320 });
      }
      return true;
    }
    case 'r66e2_limiter': {
      for (const t of targets) {
        fx.twinkle(t.x - 5, t.y - 24, { color: SAIKI[1], size: 6, life: 360 });
        fx.twinkle(t.x + 5, t.y - 24, { color: SAIKI[1], size: 6, life: 360, delay: 40 });
        fx.shock(t.x, t.y, { r0: 6, r1: 36, color: SAIKI[1], w: 2, delay: 200, life: 380 });
        fx.arrows(t.x, t.y, SAIKI[0], true, 3, 260);
      }
      return true;
    }
  }
  return false;
}

