// 第5章 Step 3・4「クモイ地方」と「しずみゆく島の古い神殿」の 戦いの 背景（ch5-tower-bg.js の drawTowerBg から よぶ。BW×BH の まま かく。hor … 地面の たかさ）
// ・kumoi（deco 'kumoi'）… 雲の上の 島: 青い 空・もくもくの 雲・遠くに うかぶ 島（たきが 雲へ おちる）・お日さまの 光。
//   ゆかは 島の 草地。はしの 向こうは 雲の 海
// ・sink_ruin（deco 'sruin'）… しずみゆく島の 古い神殿（1〜3階）: 土色の 石の かべ・古い もようの 柱・こけと 根・かべの われめから さす 光。
//   ゆかは 少し かたむいた 石だたみ（島が かたむいている）
// ・sink_ruin_deep（deco 'sruin_deep'）… 神殿の 下の 階・雲が 入った 所・ガイアイーターの 広間: くらい 石の かべ・太い 根・
//   われめから 雲の きりが ながれこむ。ゆかは われた 石と 白い きり
import { mix } from './pixel.js';

const BW = 256, BH = 144;

export const KUMOI_BG = {
  kumoi: { sky: ['#3a8ae8', '#6aaef0', '#a8d4f8', '#e0f0ff'], far: '#e8f2ff', near: '#5aa84a', ground: ['#7ac860', '#68b450'], deco: 'kumoi' },
  sink_ruin: { sky: ['#1a120a', '#2a1e12', '#3a2a1a'], far: '#5a4630', near: '#8a7458', ground: ['#a08a68', '#8e785a'], deco: 'sruin' },
  sink_ruin_deep: { sky: ['#0e0a10', '#1a141c', '#262028'], far: '#3e3440', near: '#6a6070', ground: ['#7a7282', '#6a6474'], deco: 'sruin_deep' },
};
export const KUMOI_DECOS = new Set(['kumoi', 'sruin', 'sruin_deep']);

// 0〜1 の まいかい おなじ ちらばり（背景は 1回だけ かく）
const rnd = (i, s = 1) => {
  const v = Math.sin(i * 127.1 * s + 311.7) * 43758.5453;
  return v - Math.floor(v);
};
const disc = (x, cx, cy, r, c) => { x.fillStyle = c; x.beginPath(); x.arc(cx, cy, r, 0, Math.PI * 2); x.fill(); };

// もくもくの 雲（cx, cy … まんなかの 下、w … はば）
function cumulus(x, cx, cy, w, shade = '#c8d4f0', body = '#f4f8ff', hi = '#ffffff') {
  const parts = [[-0.36, 0, 0.22], [-0.14, -0.14, 0.28], [0.12, -0.18, 0.3], [0.34, -0.04, 0.22], [0, 0.02, 0.3]];
  for (const [dx, dy, r] of parts) disc(x, cx + dx * w, cy + dy * w + 2, r * w, shade);
  for (const [dx, dy, r] of parts) disc(x, cx + dx * w - 1, cy + dy * w, r * w * 0.92, body);
  for (const [dx, dy, r] of parts.slice(1, 3)) disc(x, cx + dx * w - r * w * 0.3, cy + dy * w - r * w * 0.3, r * w * 0.4, hi);
  x.fillStyle = shade;
  x.fillRect(Math.round(cx - w * 0.5), Math.round(cy + w * 0.12), Math.round(w), 2);
}

// うかぶ 島（cx, cy … 上の まんなか、w … はば）
function floatIsland(x, cx, cy, w, fall = false) {
  // 下の 岩（さかさまの 山）
  x.fillStyle = '#7a6a8a';
  x.beginPath(); x.moveTo(cx - w / 2, cy); x.lineTo(cx + w / 2, cy); x.lineTo(cx + w * 0.12, cy + w * 0.7); x.lineTo(cx - w * 0.08, cy + w * 0.55); x.closePath(); x.fill();
  x.fillStyle = '#a898b0';
  x.beginPath(); x.moveTo(cx - w / 2, cy); x.lineTo(cx - w * 0.1, cy); x.lineTo(cx - w * 0.08, cy + w * 0.55); x.closePath(); x.fill();
  // 草の 上
  x.fillStyle = '#5aa84a';
  x.fillRect(Math.round(cx - w / 2), Math.round(cy - 2), Math.round(w), 3);
  x.fillStyle = '#8ad870';
  x.fillRect(Math.round(cx - w / 2), Math.round(cy - 2), Math.round(w), 1);
  // 木
  for (const d of [-0.25, 0.15]) {
    x.fillStyle = '#6a4a2a'; x.fillRect(Math.round(cx + d * w), Math.round(cy - 5), 1, 4);
    disc(x, cx + d * w + 0.5, cy - 6, Math.max(1.5, w * 0.08), '#3a8a3a');
  }
  // たき（雲へ おちる）
  if (fall) {
    for (let y = cy + 1; y < cy + w * 0.9; y++) {
      x.fillStyle = `rgba(230,244,255,${(0.8 - (y - cy) / (w * 1.2)).toFixed(2)})`;
      x.fillRect(Math.round(cx + w * 0.3), y, 2, 1);
    }
  }
}

// ───── 雲の上の 島 ─────
function drawKumoi(x, hor) {
  // お日さまの 光（右上）
  for (let r = 40; r > 0; r -= 4) {
    x.fillStyle = `rgba(255,250,220,${(0.06 + (40 - r) * 0.004).toFixed(3)})`;
    disc(x, 214, 16, r, x.fillStyle);
  }
  disc(x, 214, 16, 7, '#fffbe8');
  // 遠くの 雲（下の ほうに ひろがる 雲の 海）
  for (let i = 0; i < 9; i++) cumulus(x, 10 + i * 30 + rnd(i) * 10, hor - 16 - rnd(i, 2) * 6, 26 + rnd(i, 3) * 10, '#b8c8ec', '#e8f0ff', '#ffffff');
  // うかぶ 島
  floatIsland(x, 52, 30, 30, true);
  floatIsland(x, 150, 20, 18);
  floatIsland(x, 196, 44, 24, true);
  // 近くの 大きな 雲
  cumulus(x, 22, 26, 26);
  cumulus(x, 110, 40, 30);
  cumulus(x, 244, 52, 22);
  // 鳥の かげ
  x.fillStyle = '#4a6a9a';
  for (const [bx, by] of [[90, 14], [98, 18], [128, 10]]) { x.fillRect(bx, by, 2, 1); x.fillRect(bx + 3, by, 2, 1); x.fillRect(bx + 2, by + 1, 1, 1); }
  // 地平線の 雲の 海（白い おび）
  for (let px = 0; px < BW; px++) {
    const h = 5 + Math.abs(Math.sin(px * 0.09)) * 3 + Math.abs(Math.sin(px * 0.23 + 2)) * 2;
    for (let k = 0; k < h; k++) {
      x.fillStyle = mix('#ffffff', '#c8d8f4', k / h);
      x.fillRect(px, hor - h + k, 1, 1);
    }
  }
}

// ───── 古い神殿（上の 階・下の 階）─────
function drawRuin(x, hor, deep) {
  const wall = deep ? ['#0e0a10', '#2a2430'] : ['#1a120a', '#4a3a28'];
  for (let y = 0; y < hor; y++) {
    const t = y / hor;
    x.fillStyle = mix(wall[0], wall[1], Math.min(1, t * t * 0.8 + t * 0.3));
    x.fillRect(0, y, BW, 1);
  }
  // 石の ブロック（島が かたむいて、めじが 少し ななめ）
  const tilt = deep ? 0.05 : 0.035;
  for (let r = 0; r < 12; r++) {
    const y0 = 2 + r * 7;
    if (y0 > hor) break;
    const t = Math.min(1, (y0 + 4) / hor);
    x.fillStyle = mix('#050304', deep ? '#1a1620' : '#2a1e12', t);
    for (let px = 0; px < BW; px += 1) x.fillRect(px, Math.round(y0 + px * tilt), 1, 1);
    for (let bx = (r % 2) * 11; bx < BW; bx += 22) x.fillRect(bx, Math.round(y0 + bx * tilt), 1, 7);
  }
  // 柱（古い もよう）
  for (const cx of [28, 92, 164, 228]) {
    const top = 6, c1 = deep ? '#4a4252' : '#7a6448', c2 = deep ? '#6a6274' : '#a08a68', c3 = deep ? '#2a2430' : '#4a3a28';
    x.fillStyle = c3; x.fillRect(cx - 9, top, 18, hor - top);
    x.fillStyle = c1; x.fillRect(cx - 8, top, 16, hor - top);
    x.fillStyle = c2; x.fillRect(cx - 8, top, 4, hor - top);
    // もよう（うずまきの ような 古い 線）
    x.fillStyle = c3;
    for (let y = top + 10; y < hor - 6; y += 16) {
      x.fillRect(cx - 4, y, 8, 1); x.fillRect(cx + 3, y, 1, 4); x.fillRect(cx - 2, y + 3, 6, 1); x.fillRect(cx - 2, y + 1, 1, 3);
    }
    // 頭の かざり
    x.fillStyle = c2; x.fillRect(cx - 11, top, 22, 3);
    x.fillStyle = c3; x.fillRect(cx - 11, top + 3, 22, 1);
    // ひび
    x.fillStyle = c3;
    for (let k = 0; k < 6; k++) x.fillRect(cx + 2 + (k % 2), top + 22 + k * 3, 1, 3);
  }
  // こけと 根
  for (let i = 0; i < 18; i++) {
    const px = Math.round(rnd(i, 1.7) * BW), py = Math.round(rnd(i, 2.3) * (hor - 10));
    x.fillStyle = deep ? '#3a4a3a' : '#5a7a3a';
    x.fillRect(px, py, 3 + (i % 3), 2);
    x.fillStyle = deep ? '#5a6a4a' : '#8aa860';
    x.fillRect(px + 1, py, 1 + (i % 2), 1);
  }
  const roots = deep ? 7 : 3;
  for (let i = 0; i < roots; i++) {
    let rx = 10 + rnd(i, 4.1) * (BW - 20);
    x.fillStyle = deep ? '#3a2a1e' : '#5a4028';
    for (let y = 0; y < hor * (0.4 + rnd(i, 5.3) * 0.5); y++) {
      rx += Math.sin(y * 0.2 + i) * 0.6;
      x.fillRect(Math.round(rx), y, deep ? 3 : 2, 1);
    }
  }
  // かべの われめ（上の 階は 光が さす・下の 階は 雲の きりが ながれこむ）
  for (const [cx, w] of [[60, 8], [196, 10]]) {
    x.fillStyle = deep ? '#c8d0e8' : '#ffe8b0';
    for (let y = 4; y < 30; y++) x.fillRect(Math.round(cx + Math.sin(y * 0.6) * 2), y, 2, 1);
    if (!deep) {
      for (let y = 30; y < hor + 12; y++) {
        const a = 0.12 * (1 - (y - 30) / (hor + 12 - 30));
        x.fillStyle = `rgba(255,236,180,${a.toFixed(3)})`;
        x.fillRect(Math.round(cx - w / 2 + (y - 30) * 0.3), y, w, 1);
      }
    }
  }
  if (deep) {
    // 雲の きり（よこに ながれる 白い おび）
    for (let b = 0; b < 4; b++) {
      const by = 20 + b * 16;
      for (let px = 0; px < BW; px++) {
        const a = Math.max(0, Math.sin(px * 0.03 + b * 1.7)) * (0.1 + b * 0.04);
        if (a <= 0.02) continue;
        x.fillStyle = `rgba(220,228,248,${a.toFixed(3)})`;
        x.fillRect(px, by + Math.round(Math.sin(px * 0.05 + b) * 3), 1, 5);
      }
    }
  }
  x.fillStyle = 'rgba(0,0,0,0.3)';
  x.fillRect(0, hor - 4, BW, 4);
}

export function drawKumoiBg(x, d, hor) {
  if (d.deco === 'kumoi') drawKumoi(x, hor);
  else drawRuin(x, hor, d.deco === 'sruin_deep');
}

// ゆか: 島の 草地（はなと 小石）／ かたむいた 石だたみ（われめ・小石）／ われた 石と きり
export function drawKumoiFloorBg(x, d, hor) {
  if (d.deco === 'kumoi') {
    // 草の すじと 花
    for (let i = 0; i < 70; i++) {
      const px = Math.round(rnd(i, 3.3) * BW), py = hor + 5 + Math.round(rnd(i, 4.4) * (BH - hor - 8));
      x.fillStyle = i % 3 ? '#4a9a3a' : '#9ae078';
      x.fillRect(px, py, 1, 2);
    }
    for (let i = 0; i < 16; i++) {
      const px = Math.round(rnd(i, 6.1) * BW), py = hor + 8 + Math.round(rnd(i, 7.2) * (BH - hor - 12));
      x.fillStyle = ['#ffffff', '#ffe060', '#ff9ab0'][i % 3];
      x.fillRect(px, py, 2, 1); x.fillRect(px, py - 1, 1, 1);
    }
    // 小石
    for (let i = 0; i < 6; i++) {
      const px = Math.round(rnd(i, 8.3) * BW), py = hor + 10 + Math.round(rnd(i, 9.1) * 40);
      x.fillStyle = '#a8a8b8'; x.fillRect(px, py, 3, 2);
      x.fillStyle = '#d0d0dc'; x.fillRect(px, py, 2, 1);
    }
    // 島の ふち（手前に 雲が ちらっと）
    x.fillStyle = 'rgba(255,255,255,0.55)';
    for (let k = 0; k < BW; k += 23) x.fillRect(k, BH - 3 - (k % 3), 12, 3);
    return;
  }
  const deep = d.deco === 'sruin_deep';
  const tilt = deep ? 0.06 : 0.045;
  // かたむいた 石だたみの めじ
  for (let i = 0; i < 7; i++) {
    const y = hor + 3 + Math.round(i * i * 1.4);
    if (y >= BH) break;
    x.fillStyle = deep ? 'rgba(20,16,26,0.45)' : 'rgba(40,28,16,0.4)';
    for (let px = 0; px < BW; px += 1) x.fillRect(px, Math.round(y + (px - BW / 2) * tilt), 1, 1);
    const n = 6 + i * 2;
    for (let j = 0; j <= n; j++) {
      const px = Math.round(BW / 2 + (j - n / 2) * (BW / n) * (1 + i * 0.06));
      x.fillRect(px, Math.round(y + (px - BW / 2) * tilt) - Math.round(i * 1.3) - 1, 1, Math.round(i * 1.3) + 1);
    }
  }
  // われめ
  x.fillStyle = deep ? '#1a1420' : '#3a2a18';
  for (const [cx, cy] of [[60, hor + 30], [180, hor + 40], [124, hor + 52]]) {
    let px = cx, py = cy;
    for (let k = 0; k < 14; k++) {
      x.fillRect(Math.round(px), Math.round(py), 2, 1);
      px += 2;
      py += Math.sin(k * 1.3 + cx) * 1.2;
    }
  }
  // 小石
  for (let i = 0; i < 12; i++) {
    const px = Math.round(rnd(i, 5.7) * BW), py = hor + 6 + Math.round(rnd(i, 6.9) * (BH - hor - 10));
    x.fillStyle = deep ? '#8a8494' : '#b8a284'; x.fillRect(px, py, 2, 1);
  }
  if (deep) {
    // ゆかを はう きり
    for (let px = 0; px < BW; px++) {
      const a = 0.18 + Math.max(0, Math.sin(px * 0.04)) * 0.2;
      x.fillStyle = `rgba(228,234,250,${a.toFixed(3)})`;
      x.fillRect(px, hor + 2 + Math.round(Math.sin(px * 0.07) * 2), 1, 6);
      x.fillRect(px, BH - 10 + Math.round(Math.sin(px * 0.05 + 1) * 2), 1, 8);
    }
  }
}

js/client/render/ch5-phantom-bg.js:
// 第5章 Step 8「影の城」の 戦いの 背景（battlefx.js の drawBg から よぶ。BW×BH の まま かく。hor … 地面の たかさ）
// ・castle_wind（deco 'castle_wind'）… 1〜4階「風の階」とストルムのまぼろし: 黒い 石の 広間・高い まどの 外の むらさきの 空と 回る 風車・
//   ちぎれそうに なびく 旗・風の すじ。ゆかは 黒い 石だたみに うずまく 風の もよう
// ・castle_fire（deco 'castle_fire'）… 5〜8階「炎の階」とイグニアのまぼろし: 黒い かべ・むらさきと 赤の 炎の はしら・火ばち。
//   ゆかは 黒曜石の ような 床（われめから 炎の 光）。火の粉が とぶ（embers）
// ・castle_water（deco 'castle_water'）… 9〜12階「水の階」とモルガナのまぼろし: あい色の アーチ・天井から たれる しずく・かべを つたう 水。
//   ゆかは 水が はった 床（はもんと、うつりこみ）
const BW = 256, BH = 144;

export const PHANTOM_BG = {
  castle_wind: { sky: ['#0e0c1a', '#1a1630', '#2a2446', '#3a325a'], far: '#1e1a30', near: '#2a2640', ground: ['#2e2a40', '#24203a'], deco: 'castle_wind' },
  castle_fire: { sky: ['#0e0608', '#1e0a10', '#320e18', '#4a1420'], far: '#1e0a0e', near: '#30101a', ground: ['#2a1014', '#200a10'], deco: 'castle_fire', embers: true },
  castle_water: { sky: ['#060c1a', '#0c1830', '#14264a', '#1e3460'], far: '#0e1a30', near: '#16284a', ground: ['#1a3050', '#142640'], deco: 'castle_water' },
};
export const PHANTOM_DECOS = new Set(['castle_wind', 'castle_fire', 'castle_water']);

// 0〜1 の まいかい おなじ ちらばり（背景は 1回だけ かく）
const rnd = (i, s = 1) => {
  const v = Math.sin(i * 127.1 * s + 311.7) * 43758.5453;
  return v - Math.floor(v);
};
const disc = (x, cx, cy, r, c) => { x.fillStyle = c; x.beginPath(); x.arc(cx, cy, r, 0, Math.PI * 2); x.fill(); };
const line = (x, pts, c, w = 1) => {
  x.strokeStyle = c;
  x.lineWidth = w;
  x.beginPath();
  pts.forEach(([px, py], i) => (i ? x.lineTo(px, py) : x.moveTo(px, py)));
  x.stroke();
};

// 黒い 石の かべ（ブロック）。c … [r, g, b] の もとの 色
function wall(x, hor, c, a = 0.4) {
  for (let row = 0; row * 10 < hor; row++) {
    for (let col = -1; col * 22 < BW; col++) {
      const bx = col * 22 + (row % 2 ? 11 : 0), by = row * 10;
      const v = rnd(row * 31 + col, 2.3);
      x.fillStyle = `rgba(${c[0] + Math.round(v * 24)},${c[1] + Math.round(v * 20)},${c[2] + Math.round(v * 26)},${a})`;
      x.fillRect(bx + 1, by + 1, 20, 8);
    }
  }
}
// 高い まど（アーチ）。sky … まどの 中の 色
function window_(x, cx, top, w, h, sky, frame) {
  x.fillStyle = frame;
  x.fillRect(cx - w / 2 - 2, top + w / 2 - 2, w + 4, h - w / 2 + 2);
  disc(x, cx, top + w / 2, w / 2 + 2, frame);
  x.fillStyle = sky;
  x.fillRect(cx - w / 2, top + w / 2, w, h - w / 2);
  disc(x, cx, top + w / 2, w / 2, sky);
}

// ───── 風の階 ─────
function drawWind(x, hor) {
  wall(x, hor, [40, 34, 66]);
  // 高い まど（外は むらさきの 空と 風車）
  for (const [cx, k] of [[44, 0], [128, 1], [212, 2]]) {
    window_(x, cx, 8, 30, hor - 22, '#4a3a78', '#141022');
    // 外の 雲
    for (let i = 0; i < 4; i++) disc(x, cx - 10 + i * 7, 34 + (i % 2) * 4, 5, 'rgba(150,130,200,0.5)');
    // 風車（まどの 外。はね 4まい）
    const wx = cx + (k - 1) * 4, wy = 40;
    x.fillStyle = '#1a1428';
    x.fillRect(wx - 2, wy, 4, hor - 22 - wy + 4);
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2 + k * 0.5;
      line(x, [[wx, wy], [wx + Math.cos(a) * 11, wy + Math.sin(a) * 11]], '#2a2040', 2);
      x.fillStyle = 'rgba(200,190,230,0.55)';
      x.beginPath();
      x.moveTo(wx + Math.cos(a) * 4, wy + Math.sin(a) * 4);
      x.lineTo(wx + Math.cos(a) * 11, wy + Math.sin(a) * 11);
      x.lineTo(wx + Math.cos(a + 0.35) * 10, wy + Math.sin(a + 0.35) * 10);
      x.closePath();
      x.fill();
    }
    disc(x, wx, wy, 1.5, '#c8b8f0');
  }
  // なびく 旗（まどの 間）
  for (const [fx, c] of [[86, '#5a2a6a'], [170, '#2a4a6a']]) {
    x.fillStyle = '#141022';
    x.fillRect(fx - 1, 6, 2, 6);
    for (let y = 12; y < 52; y += 2) {
      const sw = Math.round(Math.sin(y * 0.25) * 3);
      x.fillStyle = c;
      x.fillRect(fx - 7 + sw, y, 14, 2);
    }
    x.fillStyle = '#c8a040';
    x.fillRect(fx - 3, 24, 6, 6);
  }
  // 風の すじ（ななめに 何本も）
  for (let i = 0; i < 22; i++) {
    const sx = rnd(i, 4.4) * BW, sy = 10 + rnd(i, 5.5) * (hor - 20), len = 14 + rnd(i, 6.6) * 30;
    line(x, [[sx, sy], [sx + len * 0.5, sy - 3], [sx + len, sy + 1]], `rgba(190,200,240,${(0.18 + rnd(i, 7.1) * 0.25).toFixed(2)})`, 1);
  }
  // つむじ風（はしの うず）
  for (const cx of [20, 236]) for (let r = 4; r < 22; r += 4) {
    x.strokeStyle = `rgba(170,180,230,${(0.35 - r * 0.012).toFixed(2)})`;
    x.beginPath(); x.ellipse(cx, hor - 14 - r * 0.6, r, r * 0.35, 0, 0, Math.PI * 2); x.stroke();
  }
}

// ───── 炎の階 ─────
function drawFire(x, hor) {
  wall(x, hor, [46, 14, 22], 0.45);
  // 炎の はしら（むらさきと 赤）
  for (const [cx, w, purple] of [[22, 14, true], [70, 10, false], [186, 10, false], [234, 14, true]]) {
    x.fillStyle = '#120608';
    x.fillRect(cx - w / 2 - 2, 0, w + 4, hor);
    for (let y = 0; y < hor; y += 3) {
      const sw = Math.round(Math.sin(y * 0.3 + cx) * 2);
      const t = y / hor;
      x.fillStyle = purple ? `rgba(${150 + Math.round(t * 60)},${40 + Math.round(t * 30)},${200 - Math.round(t * 60)},0.75)` : `rgba(${230},${70 + Math.round(t * 90)},${40},0.75)`;
      x.fillRect(cx - w / 2 + sw, y, w, 3);
    }
    for (let r = 18; r > 0; r -= 3) disc(x, cx, hor - 10, r, purple ? `rgba(190,90,255,${(0.02 + (18 - r) * 0.01).toFixed(3)})` : `rgba(255,120,60,${(0.02 + (18 - r) * 0.01).toFixed(3)})`);
  }
  // おくの 火ばち
  for (const tx of [108, 148]) {
    x.fillStyle = '#2a1414';
    x.fillRect(tx - 6, hor - 18, 12, 4);
    x.fillRect(tx - 2, hor - 14, 4, 14);
    for (let i = 0; i < 5; i++) {
      x.fillStyle = ['#ff5a2a', '#ffb040', '#ffe070', '#c040ff', '#ff8a3a'][i];
      x.beginPath(); x.moveTo(tx - 5 + i * 2, hor - 18); x.lineTo(tx - 4 + i * 2 + (i % 2 ? 1 : -1), hor - 28 - (i % 3) * 3); x.lineTo(tx - 3 + i * 2, hor - 18); x.closePath(); x.fill();
    }
  }
  // かべの われめから もれる 赤い 光
  for (const [sx, sy] of [[96, 10], [160, 20], [128, 44]]) {
    const pts = [[sx, sy]];
    for (let k = 1; k < 6; k++) pts.push([sx + (k % 2 ? 4 : -3), sy + k * 5]);
    line(x, pts, 'rgba(255,90,60,0.65)', 1);
  }
  // 黒い 炎の もや
  for (let i = 0; i < 14; i++) disc(x, rnd(i, 3.7) * BW, hor - 4 - rnd(i, 8.2) * 12, 4 + rnd(i, 2.2) * 6, 'rgba(60,10,40,0.35)');
}

// ───── 水の階 ─────
function drawWater(x, hor) {
  wall(x, hor, [16, 30, 60], 0.45);
  // アーチ（おくに 3つ）
  for (const cx of [48, 128, 208]) {
    x.fillStyle = '#0a1426';
    x.fillRect(cx - 34, 30, 6, hor - 30);
    x.fillRect(cx + 28, 30, 6, hor - 30);
    x.strokeStyle = '#2a4a7a';
    x.lineWidth = 3;
    x.beginPath(); x.arc(cx, 32, 31, Math.PI, 0); x.stroke();
    x.fillStyle = 'rgba(40,90,150,0.35)';
    x.fillRect(cx - 28, 32, 56, hor - 32);
  }
  // かべを つたう 水
  for (const sx of [14, 90, 166, 242]) {
    for (let y = 0; y < hor; y += 2) {
      x.fillStyle = `rgba(120,200,255,${(0.25 + (y % 6) * 0.03).toFixed(2)})`;
      x.fillRect(sx + Math.round(Math.sin(y * 0.25) * 1.5), y, 1, 2);
    }
  }
  // 天井から たれる しずく
  for (let i = 0; i < 24; i++) {
    const dx = Math.round(rnd(i, 2.9) * BW), dl = 2 + Math.round(rnd(i, 3.3) * 8);
    x.fillStyle = 'rgba(150,210,255,0.6)';
    x.fillRect(dx, 0, 1, dl);
    disc(x, dx + 0.5, dl + 1, 1, 'rgba(200,240,255,0.8)');
  }
  // 水の 光の もよう
  for (let i = 0; i < 18; i++) {
    x.strokeStyle = 'rgba(140,210,255,0.18)';
    x.lineWidth = 1;
    x.beginPath(); x.ellipse(rnd(i, 6.1) * BW, 10 + rnd(i, 7.3) * (hor - 20), 6 + rnd(i, 1.7) * 8, 2, 0, 0, Math.PI * 2); x.stroke();
  }
}

export function drawPhantomBg(x, d, hor) {
  if (d.deco === 'castle_wind') drawWind(x, hor);
  else if (d.deco === 'castle_fire') drawFire(x, hor);
  else drawWater(x, hor);
}

// ゆか: うずまく 風の 石だたみ ／ 炎の われめの 黒い 床 ／ 水の はった 床
export function drawPhantomFloorBg(x, d, hor) {
  // 石だたみの すじ（遠近）
  x.fillStyle = 'rgba(0,0,0,0.3)';
  for (let i = 0; i < 6; i++) {
    const y = hor + 4 + i * i * 2;
    if (y < BH) x.fillRect(0, y, BW, 1);
  }
  for (let j = -8; j <= 8; j++) for (let y = hor + 4; y < BH; y += 2) x.fillRect(Math.round(BW / 2 + j * 18 * (1 + (y - hor) / 40)), y, 1, 2);
  if (d.deco === 'castle_wind') {
    // うずまく 風の もよう
    for (const [cx, cy] of [[60, hor + 30], [190, hor + 24], [128, hor + 46]]) {
      for (let r = 6; r < 30; r += 6) {
        x.strokeStyle = `rgba(170,170,230,${(0.32 - r * 0.008).toFixed(2)})`;
        x.lineWidth = 1;
        x.beginPath(); x.ellipse(cx, cy, r, r * 0.3, 0, 0.3, Math.PI * 1.7); x.stroke();
      }
    }
    for (let i = 0; i < 16; i++) line(x, [[rnd(i, 2.1) * BW, hor + 6 + rnd(i, 3.4) * 50], [rnd(i, 2.1) * BW + 12, hor + 5 + rnd(i, 3.4) * 50]], 'rgba(200,210,250,0.25)', 1);
    return;
  }
  if (d.deco === 'castle_fire') {
    // 黒曜石の つや・われめの 炎の 光
    for (const [sx, sy, len] of [[30, hor + 12, 60], [140, hor + 26, 70], [200, hor + 8, 40], [80, hor + 42, 50]]) {
      const pts = [[sx, sy]];
      for (let k = 1; k <= 6; k++) pts.push([sx + (k * len) / 6, sy + (k % 2 ? 2 : -1)]);
      line(x, pts, 'rgba(255,90,50,0.65)', 1);
    }
    x.fillStyle = 'rgba(200,60,255,0.12)';
    x.beginPath(); x.ellipse(128, hor + 22, 96, 16, 0, 0, Math.PI * 2); x.fill();
    for (let i = 0; i < 20; i++) {
      x.fillStyle = 'rgba(255,255,255,0.12)';
      x.fillRect(Math.round(rnd(i, 4.8) * BW), hor + 4 + Math.round(rnd(i, 5.9) * (BH - hor - 8)), 3, 1);
    }
    return;
  }
  // 水の はった 床: はもん・アーチの うつりこみ・光
  x.fillStyle = 'rgba(80,160,230,0.22)';
  x.fillRect(0, hor, BW, BH - hor);
  for (const cx of [48, 128, 208]) {
    x.fillStyle = 'rgba(10,20,40,0.35)';
    x.fillRect(cx - 34, hor + 2, 6, 14);
    x.fillRect(cx + 28, hor + 2, 6, 14);
  }
  for (let i = 0; i < 16; i++) {
    x.strokeStyle = `rgba(170,230,255,${(0.2 + rnd(i, 1.9) * 0.25).toFixed(2)})`;
    x.lineWidth = 1;
    x.beginPath(); x.ellipse(rnd(i, 8.3) * BW, hor + 8 + rnd(i, 9.1) * (BH - hor - 12), 8 + rnd(i, 3.9) * 14, 2 + rnd(i, 4.2) * 2, 0, 0, Math.PI * 2); x.stroke();
  }
  for (let i = 0; i < 24; i++) {
    x.fillStyle = 'rgba(220,245,255,0.5)';
    x.fillRect(Math.round(rnd(i, 6.6) * BW), hor + 4 + Math.round(rnd(i, 7.7) * (BH - hor - 8)), 2, 1);
  }
}

