}
function paintSeedSpot() {
  const p = new Painter(14, 8);
  p.ellipse(7, 5, 6, 2.5, '#6a4a28'); p.ellipse(7, 4.5, 5, 1.8, '#8a6438');
  for (const [x, y] of [[4, 4], [9, 5], [7, 3]]) p.set(x, y, '#a8804a');
