  p.rect(15, 3, 14, 10, M.b); p.hline(15, 28, 3, M.hl);
  p.hline(17, 26, 7, '#1a1010'); p.set(19, 7, '#ff6a3a'); p.set(24, 7, '#ff6a3a');
