  }
}
export const CH6_SPECIALS = ['hero_statue', 'hero_statue_faded', 'star_tree', 'star_sapling', 'seed_spot', 'star_dew', 'past_tent', 'prayer_stone', 'chibi_astel', 'zenmai', 'geardon_npc', ...ROAD_SPECIALS, ...TOKEI_SPECIALS, ...C7_SPECIALS];

