// 第2部 第6章 Step 1・2 の 戦いの 背景（battlefx.js の battleBackground から よぶ。BW×BH の まま かく。hor … 地面の たかさ）
// ・past_field（deco 'past_field'）… 千年前の ミドリナ地方: 少し セピアがかった 金色の 空・大きな 古い 木の 森・遠くの ほしみの丘。
//   ゆかは 道の ない 草原（花と 長い 草）
// ・toki_shrine（deco 'toki_shrine'）… 時のほこらとサンドクロック: 砂岩の かべ・砂時計の 形の はしら・天井から 流れ落ちる 砂の すじ・
//   かべの 時計の もよう。ゆかは 砂の 波もよう
// ・toki_ruin（deco 'toki_ruin'）… 時のいせき: 白い 石の はしら（時計の 文字ばんの かざり）・かべに うまった 歯車・木の 根。
//   ゆかは 石の タイルと 歯車の もよう
// ・toki_ruin_boss（deco 'toki_ruin_boss'）… 番人の間とギアドン: おくの かべに 大きな 時計・まわりに 歯車・青い 光の すじ。
//   ゆかは 時計の 文字ばんの ような まるい もよう
const BW = 256, BH = 144;

export const PAST_BG = {
  past_field: { sky: ['#e8c890', '#f0d8a8', '#f4e4c0', '#e8e0c0'], far: '#7a8a5a', near: '#5a7a40', ground: ['#86a050', '#76904a'], deco: 'past_field' },
  toki_shrine: { sky: ['#1a1208', '#2a1e10', '#3e2c16', '#523a1e'], far: '#4a3620', near: '#6a5030', ground: ['#b8945a', '#a8844e'], deco: 'toki_shrine' },
  toki_ruin: { sky: ['#141a22', '#1e2834', '#2a3646', '#384656'], far: '#3a4656', near: '#58687a', ground: ['#7a8494', '#6c7686'], deco: 'toki_ruin' },
  toki_ruin_boss: { sky: ['#0a0e1a', '#121a2e', '#1a2642', '#223256'], far: '#22304a', near: '#3a4a6a', ground: ['#4a5a78', '#404e6c'], deco: 'toki_ruin_boss' },
};
export const PAST_DECOS = new Set(['past_field', 'toki_shrine', 'toki_ruin', 'toki_ruin_boss']);

// 0〜1 の まいかい おなじ ちらばり（背景は 1回だけ かく）
const rnd = (i, s = 1) => {
  const v = Math.sin(i * 127.1 * s + 311.7) * 43758.5453;
  return v - Math.floor(v);
};
const disc = (x, cx, cy, r, c) => { x.fillStyle = c; x.beginPath(); x.arc(cx, cy, r, 0, Math.PI * 2); x.fill(); };
const line = (x, pts, c, w = 1) => {
  x.strokeStyle = c;
  x.lineWidth = w;
  x.beginPath();
  pts.forEach(([px, py], i) => (i ? x.lineTo(px, py) : x.moveTo(px, py)));
  x.stroke();
};
// 時計の 文字ばん（cx, cy … まん中・r … 大きさ・a … 針の 角度）
function clockFace(x, cx, cy, r, face, rim, hand, a = 0) {
  disc(x, cx, cy, r + 2, rim);
  disc(x, cx, cy, r, face);
  for (let i = 0; i < 12; i++) {
    const t = (i * Math.PI) / 6;
    x.fillStyle = rim;
    x.fillRect(Math.round(cx + Math.cos(t) * r * 0.8) - (i % 3 ? 0 : 1), Math.round(cy + Math.sin(t) * r * 0.8) - (i % 3 ? 0 : 1), i % 3 ? 1 : 2, i % 3 ? 1 : 2);
  }
  line(x, [[cx, cy], [cx + Math.cos(a) * r * 0.7, cy + Math.sin(a) * r * 0.7]], hand, Math.max(1, r / 10));
  line(x, [[cx, cy], [cx + Math.cos(a * 3 + 1) * r * 0.45, cy + Math.sin(a * 3 + 1) * r * 0.45]], hand, Math.max(1, r / 8));
}
// 歯車（かべの かざり）
function cog(x, cx, cy, r, n, a, c, hole) {
  x.fillStyle = c;
  x.beginPath();
  for (let i = 0; i < n * 2; i++) {
    const t = a + (i * Math.PI) / n;
    const rr = i % 2 ? r * 0.8 : r;
    const px = cx + Math.cos(t) * rr, py = cy + Math.sin(t) * rr;
    if (i) x.lineTo(px, py);
    else x.moveTo(px, py);
  }
  x.closePath();
  x.fill();
  disc(x, cx, cy, r * 0.35, hole);
}

// ───── 千年前の フィールド ─────
function drawField(x, hor) {
  // 遠くの ほしみの丘
  x.fillStyle = 'rgba(150,140,110,0.5)';
  x.beginPath(); x.ellipse(196, hor - 6, 70, 22, 0, Math.PI, 0); x.fill();
  // 大きな 古い 木（みき・枝・葉の かたまり）
  for (const [tx, s] of [[18, 1.2], [70, 0.8], [118, 0.6], [236, 1.1]]) {
    const h = 54 * s;
    x.fillStyle = '#5a4026';
    x.fillRect(tx - 4 * s, hor - h * 0.55, 8 * s, h * 0.55);
    line(x, [[tx, hor - h * 0.45], [tx - 12 * s, hor - h * 0.7]], '#5a4026', 2 * s);
    line(x, [[tx, hor - h * 0.5], [tx + 12 * s, hor - h * 0.72]], '#5a4026', 2 * s);
    for (let i = 0; i < 7; i++) {
      const ox = (rnd(i + tx, 2.2) - 0.5) * 34 * s, oy = (rnd(i + tx, 3.1) - 0.5) * 18 * s;
      disc(x, tx + ox, hor - h * 0.75 + oy, (10 + rnd(i + tx, 4.4) * 6) * s, i % 2 ? '#4e7a34' : '#6a9a44');
    }
    for (let i = 0; i < 4; i++) disc(x, tx + (rnd(i + tx, 5.5) - 0.5) * 24 * s, hor - h * 0.82 + (rnd(i, 6.6) - 0.5) * 10 * s, 4 * s, '#8ab85a');
    // 木の 根
    line(x, [[tx - 4 * s, hor], [tx - 10 * s, hor + 3]], '#4a3420', 2);
    line(x, [[tx + 4 * s, hor], [tx + 10 * s, hor + 3]], '#4a3420', 2);
  }
  // 森の おくの 光の すじ（セピアの 光）
  for (let i = 0; i < 8; i++) {
    const sx = 30 + rnd(i, 7.7) * 200;
    x.fillStyle = 'rgba(255,240,190,0.12)';
    x.beginPath(); x.moveTo(sx, 0); x.lineTo(sx + 10, 0); x.lineTo(sx + 26, hor); x.lineTo(sx + 14, hor); x.closePath(); x.fill();
  }
  // とぶ 光の つぶ（花粉・こはく色）
  for (let i = 0; i < 26; i++) disc(x, rnd(i, 8.1) * BW, 6 + rnd(i, 9.2) * (hor - 12), 0.8 + rnd(i, 1.3), 'rgba(255,230,150,0.7)');
  // 鳥
  for (const [bx, by] of [[150, 18], [162, 14], [172, 20]]) line(x, [[bx - 3, by], [bx, by + 2], [bx + 3, by]], 'rgba(90,70,40,0.7)', 1);
}

// ───── 時のほこら ─────
function drawShrine(x, hor) {
  // 砂岩の かべ（ブロック）
  for (let row = 0; row * 10 < hor; row++) {
    for (let col = -1; col * 24 < BW; col++) {
      const v = rnd(row * 31 + col, 2.3);
      x.fillStyle = `rgba(${120 + Math.round(v * 30)},${86 + Math.round(v * 22)},${46 + Math.round(v * 16)},0.45)`;
      x.fillRect(col * 24 + (row % 2 ? 12 : 0) + 1, row * 10 + 1, 22, 8);
    }
  }
  // 砂時計の 形の はしら
  for (const cx of [26, 230]) {
    x.fillStyle = '#3a2814';
    x.fillRect(cx - 14, 0, 28, 6);
    x.fillRect(cx - 14, hor - 6, 28, 6);
    x.fillStyle = '#7a5a30';
    x.beginPath(); x.moveTo(cx - 12, 6); x.lineTo(cx + 12, 6); x.lineTo(cx + 3, hor / 2); x.lineTo(cx + 12, hor - 6); x.lineTo(cx - 12, hor - 6); x.lineTo(cx - 3, hor / 2); x.closePath(); x.fill();
    x.fillStyle = '#e8c070';
    x.beginPath(); x.moveTo(cx - 9, hor - 6); x.lineTo(cx + 9, hor - 6); x.lineTo(cx, hor / 2 + 8); x.closePath(); x.fill();
    line(x, [[cx, hor / 2 - 2], [cx, hor - 10]], '#f4dca0', 1);
  }
  // かべの 大きな 時計の もよう（2つ）
  clockFace(x, 92, 28, 14, 'rgba(232,200,130,0.45)', '#5a4020', '#3a2410', -1);
  clockFace(x, 168, 34, 11, 'rgba(232,200,130,0.4)', '#5a4020', '#3a2410', 0.8);
  // 天井から 流れ落ちる 砂の すじ
  for (const sx of [58, 128, 200]) {
    for (let y = 0; y < hor; y += 2) {
      x.fillStyle = `rgba(240,210,140,${(0.4 + (y % 6) * 0.05).toFixed(2)})`;
      x.fillRect(sx + Math.round(Math.sin(y * 0.2) * 1), y, 2, 2);
    }
    x.fillStyle = 'rgba(230,190,110,0.6)';
    x.beginPath(); x.ellipse(sx + 1, hor - 2, 10, 4, 0, Math.PI, 0); x.fill();
  }
  // まう 砂の つぶ
  for (let i = 0; i < 30; i++) {
    x.fillStyle = 'rgba(255,230,170,0.6)';
    x.fillRect(Math.round(rnd(i, 3.3) * BW), Math.round(rnd(i, 4.4) * hor), 1, 1);
  }
}

// ───── 時のいせき（と 番人の間）─────
function drawRuin(x, hor, boss) {
  // 白っぽい 石の かべ
  for (let row = 0; row * 12 < hor; row++) {
    for (let col = -1; col * 26 < BW; col++) {
      const v = rnd(row * 17 + col, 3.1);
      const b = boss ? [40, 56, 90] : [96, 108, 124];
      x.fillStyle = `rgba(${b[0] + Math.round(v * 20)},${b[1] + Math.round(v * 20)},${b[2] + Math.round(v * 24)},0.4)`;
      x.fillRect(col * 26 + (row % 2 ? 13 : 0) + 1, row * 12 + 1, 24, 10);
    }
  }
  if (boss) {
    // おくの 大きな 時計と まわりの 歯車
    cog(x, 70, 30, 18, 10, 0.2, 'rgba(160,120,60,0.7)', '#121a2e');
    cog(x, 186, 26, 14, 8, 0.5, 'rgba(160,120,60,0.7)', '#121a2e');
    cog(x, 200, 54, 9, 8, 0.1, 'rgba(120,90,50,0.7)', '#121a2e');
    clockFace(x, 128, 34, 26, 'rgba(220,230,250,0.55)', '#8a6a30', '#1a2030', -1.2);
    // 青い 光の すじ
    for (let i = 0; i < 6; i++) {
      const sx = 20 + i * 44;
      x.fillStyle = 'rgba(120,200,255,0.1)';
      x.beginPath(); x.moveTo(sx, 0); x.lineTo(sx + 8, 0); x.lineTo(sx + 18, hor); x.lineTo(sx + 10, hor); x.closePath(); x.fill();
    }
    for (let i = 0; i < 24; i++) disc(x, rnd(i, 5.1) * BW, rnd(i, 6.2) * hor, 0.8, 'rgba(160,220,255,0.8)');
  } else {
    // かべに うまった 歯車
    for (const [cx, cy, r] of [[100, 18, 10], [114, 30, 6], [160, 48, 12], [178, 40, 7], [60, 56, 8]]) cog(x, cx, cy, r, 8, cx * 0.1, 'rgba(150,130,90,0.55)', '#1e2834');
    // 木の 根（今の 時代の いせき）
    for (const [sx, dir] of [[0, 1], [256, -1]]) {
      line(x, [[sx, 4], [sx + dir * 20, 18], [sx + dir * 26, 40], [sx + dir * 40, 60]], 'rgba(90,70,50,0.8)', 3);
      line(x, [[sx + dir * 20, 18], [sx + dir * 44, 22], [sx + dir * 58, 34]], 'rgba(90,70,50,0.8)', 2);
    }
    for (let i = 0; i < 10; i++) disc(x, (i % 2 ? 20 : 236) + (rnd(i, 2.7) - 0.5) * 30, 10 + rnd(i, 3.9) * 50, 2 + rnd(i, 1.1) * 2, 'rgba(90,140,70,0.6)');
  }
  // 白い 石の はしら（時計の 文字ばんの かざり）
  for (const cx of boss ? [16, 240] : [16, 88, 168, 240]) {
    x.fillStyle = boss ? '#2a3654' : '#8a94a6';
    x.fillRect(cx - 9, 0, 18, hor);
    x.fillStyle = boss ? '#3a4a70' : '#a8b2c2';
    x.fillRect(cx - 7, 0, 5, hor);
    x.fillStyle = boss ? '#1a2238' : '#5e687a';
    x.fillRect(cx - 11, 0, 22, 4);
    x.fillRect(cx - 11, hor - 4, 22, 4);
    clockFace(x, cx, 24, 6, boss ? '#c8d8f0' : '#e8ecf2', boss ? '#8a6a30' : '#5e687a', '#2a2e3a', cx * 0.05);
  }
}

export function drawPastBg(x, d, hor) {
  if (d.deco === 'past_field') drawField(x, hor);
  else if (d.deco === 'toki_shrine') drawShrine(x, hor);
  else drawRuin(x, hor, d.deco === 'toki_ruin_boss');
}

// ゆか: 草原 ／ 砂の 波もよう ／ 石の タイルと 歯車 ／ 文字ばんの もよう
export function drawPastFloorBg(x, d, hor) {
  if (d.deco === 'past_field') {
    // 長い 草と 花
    for (let i = 0; i < 70; i++) {
      const gx = rnd(i, 1.7) * BW, gy = hor + 2 + rnd(i, 2.9) * (BH - hor - 4);
      line(x, [[gx, gy], [gx + (rnd(i, 4.1) - 0.5) * 4, gy - 3 - rnd(i, 5.3) * 4]], i % 3 ? 'rgba(60,100,40,0.6)' : 'rgba(150,180,80,0.6)', 1);
    }
    for (let i = 0; i < 18; i++) disc(x, rnd(i, 6.7) * BW, hor + 4 + rnd(i, 7.9) * (BH - hor - 8), 1.2, ['#f4e070', '#f0a0c0', '#ffffff'][i % 3]);
    return;
  }
  if (d.deco === 'toki_shrine') {
    // 砂の 波もよう
    for (let i = 0; i < 9; i++) {
      const y = hor + 4 + i * 7;
      if (y >= BH) break;
      const pts = [];
      for (let px = 0; px <= BW; px += 8) pts.push([px, y + Math.sin(px * 0.06 + i) * 1.5]);
      line(x, pts, 'rgba(120,90,40,0.35)', 1);
    }
    for (let i = 0; i < 30; i++) {
      x.fillStyle = 'rgba(255,240,200,0.4)';
      x.fillRect(Math.round(rnd(i, 8.8) * BW), hor + 2 + Math.round(rnd(i, 9.9) * (BH - hor - 4)), 2, 1);
    }
    // 砂の 山
    for (const sx of [58, 128, 200]) {
      x.fillStyle = 'rgba(230,190,110,0.5)';
      x.beginPath(); x.ellipse(sx + 1, hor + 3, 14, 4, 0, 0, Math.PI * 2); x.fill();
    }
    return;
  }
  const boss = d.deco === 'toki_ruin_boss';
  // 石の タイル（遠近）
  x.fillStyle = 'rgba(0,0,0,0.25)';
  for (let i = 0; i < 6; i++) {
    const y = hor + 4 + i * i * 2;
    if (y < BH) x.fillRect(0, y, BW, 1);
  }
  for (let j = -8; j <= 8; j++) for (let y = hor + 4; y < BH; y += 2) x.fillRect(Math.round(BW / 2 + j * 20 * (1 + (y - hor) / 40)), y, 1, 2);
  if (boss) {
    // 文字ばんの ような まるい もよう
    for (let r = 20; r <= 100; r += 20) {
      x.strokeStyle = `rgba(140,200,255,${(0.32 - r * 0.0022).toFixed(2)})`;
      x.lineWidth = 1;
      x.beginPath(); x.ellipse(128, hor + 30, r, r * 0.22, 0, 0, Math.PI * 2); x.stroke();
    }
    for (let i = 0; i < 12; i++) {
      const t = (i * Math.PI) / 6;
      x.fillStyle = 'rgba(200,170,90,0.7)';
      x.fillRect(Math.round(128 + Math.cos(t) * 90), Math.round(hor + 30 + Math.sin(t) * 20), 3, 2);
    }
    return;
  }
  // 歯車の もよう
  for (const [cx, cy, r] of [[60, hor + 30, 10], [196, hor + 22, 8], [128, hor + 48, 12]]) cog(x, cx, cy, r, 8, 0.3, 'rgba(150,130,90,0.35)', 'rgba(60,70,90,0.5)');
  for (let i = 0; i < 20; i++) {
    x.fillStyle = 'rgba(255,255,255,0.12)';
    x.fillRect(Math.round(rnd(i, 4.8) * BW), hor + 4 + Math.round(rnd(i, 5.9) * (BH - hor - 8)), 3, 1);
  }
}

js/client/render/ch6-road-bg.js:
// 第2部 第6章 Step 3・4 の 戦いの 背景（battlefx.js の battleBackground から よぶ。BW×BH の まま かく。hor … 地面の たかさ）
// ・hoshimichi（deco 'hoshimichi'）… 星めぐりの古道 1〜4階と 星くいのよる鳥: こい 青の 夜空・天の川・星座の 線・
//   遠くの 山（battlefx.js の ふつうの 山なみ）・道の 両わきの 道しるべの 石（てっぺんに 星の 光）。ゆかは 古い 石だたみの 道と 星くず
// ・hoshimichi_deep（deco 'hoshimichi_deep'）… 5〜8階と ペンデュラ: むらさきの 夜空に 時の うず・うかぶ 時計の かけら・
//   ふりこの 形の 星座。ゆかは 文字ばんの ような 光の わと 石だたみ
const BW = 256, BH = 144;

export const ROAD_BG = {
  hoshimichi: { sky: ['#060a1e', '#0c1430', '#141e44', '#1e2a58'], far: '#121a34', near: '#2a3450', ground: ['#4a4e6a', '#3e4260'], deco: 'hoshimichi' },
  hoshimichi_deep: { sky: ['#0a0618', '#140c2a', '#20123e', '#2c1a52'], far: '#160e2a', near: '#2e2248', ground: ['#4a3e66', '#3c3256'], deco: 'hoshimichi_deep' },
};
export const ROAD_DECOS = new Set(['hoshimichi', 'hoshimichi_deep']);

// 0〜1 の まいかい おなじ ちらばり（背景は 1回だけ かく）
const rnd = (i, s = 1) => {
  const v = Math.sin(i * 127.1 * s + 311.7) * 43758.5453;
  return v - Math.floor(v);
};
const disc = (x, cx, cy, r, c) => { x.fillStyle = c; x.beginPath(); x.arc(cx, cy, r, 0, Math.PI * 2); x.fill(); };
const line = (x, pts, c, w = 1) => {
  x.strokeStyle = c;
  x.lineWidth = w;
  x.beginPath();
  pts.forEach(([px, py], i) => (i ? x.lineTo(px, py) : x.moveTo(px, py)));
  x.stroke();
};
// 4つの 光の 星
function twinkle(x, cx, cy, s, c) {
  x.fillStyle = c;
  x.fillRect(Math.round(cx) - s, Math.round(cy), s * 2 + 1, 1);
  x.fillRect(Math.round(cx), Math.round(cy) - s, 1, s * 2 + 1);
}
// 夜空の 星（top … ここより 上だけ）
function stars(x, n, top, seed, cols) {
  for (let i = 0; i < n; i++) {
    const sx = rnd(i, seed) * BW, sy = rnd(i, seed + 1.3) * top;
    x.fillStyle = cols[i % cols.length];
    x.fillRect(Math.round(sx), Math.round(sy), i % 9 ? 1 : 2, i % 9 ? 1 : 2);
  }
}
// 道しるべの 石（cx … まん中・h … 高さ・c … 石の 色・glow … 星の 光）
function guideStone(x, cx, hor, h, c, cl, glow) {
  x.fillStyle = c;
  x.fillRect(cx - 5, hor - h, 10, h);
  x.fillStyle = cl;
  x.fillRect(cx - 4, hor - h, 3, h);
  x.fillStyle = c;
  x.beginPath(); x.moveTo(cx - 6, hor - h); x.lineTo(cx, hor - h - 6); x.lineTo(cx + 6, hor - h); x.closePath(); x.fill();
  disc(x, cx, hor - h - 9, 6, 'rgba(255,240,170,0.18)');
  disc(x, cx, hor - h - 9, 3, 'rgba(255,240,170,0.45)');
  twinkle(x, cx, hor - h - 9, 3, glow);
  // 石に きざんだ 星の しるし
  twinkle(x, cx, hor - h + 10, 2, 'rgba(180,210,255,0.7)');
}

// ───── 星めぐりの古道 ─────
function drawRoad(x, hor) {
  // 天の川（ななめの うすい 光の おび）
  for (let i = 0; i < 160; i++) {
    const t = rnd(i, 2.1);
    const cx = t * BW, cy = 6 + t * 30 + (rnd(i, 3.3) - 0.5) * 14;
    x.fillStyle = `rgba(200,210,255,${(0.08 + rnd(i, 4.4) * 0.2).toFixed(2)})`;
    x.fillRect(Math.round(cx), Math.round(cy), 1, 1);
  }
  stars(x, 60, hor - 30, 1.7, ['#ffffff', '#cfe0ff', '#fff2c0']);
  // 星座（オオカミと ひつじの 形の 線）
  const wolf = [[30, 14], [44, 10], [58, 16], [70, 12], [80, 20], [66, 26], [50, 24]];
  line(x, wolf, 'rgba(150,200,255,0.45)', 1);
  for (const [px, py] of wolf) twinkle(x, px, py, 1, '#ffffff');
  const ram = [[176, 12], [188, 8], [202, 12], [210, 22], [196, 28], [184, 24]];
  line(x, ram, 'rgba(255,220,150,0.45)', 1);
  for (const [px, py] of ram) twinkle(x, px, py, 1, '#fff2c0');
  // 大きな 星
  twinkle(x, 128, 18, 3, '#fff6c0');
  disc(x, 128, 18, 4, 'rgba(255,246,192,0.2)');
  // 道しるべの 石
  guideStone(x, 22, hor, 30, '#5a5e7a', '#7a809e', '#fff6c0');
  guideStone(x, 234, hor, 26, '#5a5e7a', '#7a809e', '#fff6c0');
  guideStone(x, 92, hor, 14, '#4a4e6a', '#6a6e8a', '#cfe0ff');
  guideStone(x, 168, hor, 12, '#4a4e6a', '#6a6e8a', '#cfe0ff');
  // 草と こけ
  for (let i = 0; i < 30; i++) {
    const gx = rnd(i, 5.5) * BW;
    line(x, [[gx, hor], [gx + (rnd(i, 6.6) - 0.5) * 3, hor - 2 - rnd(i, 7.7) * 4]], 'rgba(60,90,90,0.8)', 1);
  }
}

// ───── 星めぐりの古道の おく ─────
function drawDeep(x, hor) {
  stars(x, 50, hor - 30, 2.9, ['#ffffff', '#e0c8ff', '#c8f0ff']);
  // 時の うず（大きな うずまき）
  for (let r = 6; r < 46; r += 5) {
    x.strokeStyle = `rgba(180,140,255,${(0.42 - r * 0.007).toFixed(2)})`;
    x.lineWidth = 1;
    x.beginPath();
    x.arc(128, 28, r, r * 0.12, r * 0.12 + Math.PI * 1.3);
    x.stroke();
  }
  disc(x, 128, 28, 5, 'rgba(200,240,255,0.35)');
  disc(x, 128, 28, 2, 'rgba(255,255,255,0.8)');
  // うかぶ 時計の かけら
  for (const [cx, cy, r, a] of [[40, 22, 9, 0.4], [214, 18, 7, 2.1], [74, 48, 5, 1.2], [188, 46, 6, 3]]) {
    x.fillStyle = 'rgba(220,226,244,0.55)';
    x.beginPath(); x.moveTo(cx, cy); x.arc(cx, cy, r, a, a + Math.PI * 1.4); x.closePath(); x.fill();
    line(x, [[cx, cy], [cx + Math.cos(a + 0.6) * r * 0.8, cy + Math.sin(a + 0.6) * r * 0.8]], 'rgba(40,30,70,0.9)', 1);
    x.fillStyle = 'rgba(216,176,64,0.8)';
    x.fillRect(Math.round(cx) - 1, Math.round(cy) - 1, 2, 2);
  }
  // ふりこの 形の 星座
  const pend = [[150, 4], [150, 10], [158, 22], [164, 32]];
  line(x, pend.slice(0, 3), 'rgba(255,220,140,0.5)', 1);
  line(x, [[158, 22], [164, 32]], 'rgba(255,220,140,0.5)', 1);
  for (const [px, py] of pend) twinkle(x, px, py, 1, '#fff2c0');
  disc(x, 166, 36, 4, 'rgba(255,220,140,0.35)');
  // 道しるべの 石（こわれかけ）
  guideStone(x, 20, hor, 24, '#4e4268', '#6e6290', '#e0c8ff');
  guideStone(x, 236, hor, 28, '#4e4268', '#6e6290', '#e0c8ff');
  // 時の すじ（ななめの 光）
  for (let i = 0; i < 5; i++) {
    const sx = 30 + i * 50;
    x.fillStyle = 'rgba(160,120,255,0.08)';
    x.beginPath(); x.moveTo(sx, 0); x.lineTo(sx + 6, 0); x.lineTo(sx + 20, hor); x.lineTo(sx + 14, hor); x.closePath(); x.fill();
  }
}

export function drawRoadBg(x, d, hor) {
  if (d.deco === 'hoshimichi') drawRoad(x, hor);
  else drawDeep(x, hor);
}

// ゆか: 古い 石だたみの 道（遠近）と 星くず ／ 文字ばんの ような 光の わ
export function drawRoadFloorBg(x, d, hor) {
  const deep = d.deco === 'hoshimichi_deep';
  // 石だたみ（横の めじ）
  x.fillStyle = 'rgba(0,0,0,0.25)';
  for (let i = 0; i < 7; i++) {
    const y = hor + 4 + i * i * 2;
    if (y < BH) x.fillRect(0, y, BW, 1);
  }
  // たての めじ（遠近）
  for (let j = -7; j <= 7; j++) for (let y = hor + 4; y < BH; y += 2) x.fillRect(Math.round(BW / 2 + (j + (Math.floor((y - hor) / 6) % 2) * 0.5) * 22 * (1 + (y - hor) / 40)), y, 1, 2);
  // 道の ふち（まん中の 道を 少し 明るく）
  x.fillStyle = deep ? 'rgba(170,140,230,0.08)' : 'rgba(180,200,255,0.08)';
  x.beginPath(); x.moveTo(BW / 2 - 30, hor); x.lineTo(BW / 2 + 30, hor); x.lineTo(BW / 2 + 110, BH); x.lineTo(BW / 2 - 110, BH); x.closePath(); x.fill();
  if (deep) {
    // 文字ばんの ような 光の わ
    for (let r = 20; r <= 100; r += 20) {
      x.strokeStyle = `rgba(190,150,255,${(0.3 - r * 0.002).toFixed(2)})`;
      x.lineWidth = 1;
      x.beginPath(); x.ellipse(128, hor + 32, r, r * 0.22, 0, 0, Math.PI * 2); x.stroke();
    }
    for (let i = 0; i < 12; i++) {
      const t = (i * Math.PI) / 6;
      x.fillStyle = 'rgba(216,176,64,0.75)';
      x.fillRect(Math.round(128 + Math.cos(t) * 90), Math.round(hor + 32 + Math.sin(t) * 20), 3, 2);
    }
  }
  // 星くず
  for (let i = 0; i < 40; i++) {
    const sx = rnd(i, 8.1) * BW, sy = hor + 3 + rnd(i, 9.2) * (BH - hor - 5);
    x.fillStyle = i % 3 ? 'rgba(255,246,192,0.55)' : deep ? 'rgba(220,190,255,0.6)' : 'rgba(180,220,255,0.6)';
    x.fillRect(Math.round(sx), Math.round(sy), 1, 1);
  }
  for (let i = 0; i < 6; i++) twinkle(x, rnd(i, 10.3) * BW, hor + 8 + rnd(i, 11.4) * (BH - hor - 14), 1, 'rgba(255,246,192,0.8)');
}

js/client/render/ch6-road-npc-art.js:
// 第6章 Step 3・4 の 人の え と とくべつな え（render/ch6-art.js が まぜる）
// 人（ROAD_NPC_LOOKS）: 星読みのオリハ（ミナモの おばあさん。こい 青の ころもに 星の ふち・白い かみ・つえ）・社の見習いコトハ
// とくべつな え（paintRoadSpecial）: 星くいのよる鳥（大きな 黒い 鳥。おなかに 食べた 星の 光）・ふりこの魔女ペンデュラ（大きな ふりこを もつ 魔女）・
//   タイムカプセルを うめる 所（千年前）・ほる 所（今。土の 下から 光）・きらきらの石
import { Painter } from './pixel.js';

export const ROAD_NPC_LOOKS = {
  oriha: { hair: 5, hairStyle: 'bun', skin: 0, outfit: 'robe', robeMain: '#2a3a7a', robeTrim: '#f0d870', female: true, cane: true, hunch: true, hat: 'circlet', hatGem: '#a8d8ff' },
  kotoha: { hair: '#3a2a5a', hairStyle: 'twin', skin: 0, outfit: 'robe', robeMain: '#e8eeff', robeTrim: '#7a8ad8', female: true, small: true },
};

// 星くいのよる鳥（44×40。2コマで はばたく。おなかの 中で 星が 光る）
function paintStarEater(f) {
  const W = 44, H = 40, p = new Painter(W, H);
  const K = { d: '#0e0c1c', b: '#24203e', l: '#3e3864', hl: '#5e5890' };
  p.ellipse(22, 38.5, 13, 1.6, '#08060e');
  // 羽（コマで 上下）
  const up = f % 2 === 0;
  for (const s of [-1, 1]) {
    for (let k = 0; k < 14; k++) {
      const x = 22 + s * (8 + k);
      const y0 = up ? 14 - Math.floor(k * 0.7) : 18 + Math.floor(k * 0.3);
      p.vline(x, y0, y0 + 9 - Math.floor(k / 3), K.b);
      p.set(x, y0, K.hl);
    }
  }
  // 体
  p.ellipse(22, 22, 10, 11, K.b); p.ellipse(21, 20, 7, 8, K.l);
  // おなかの 星（食べた 星の 光）
  for (const [x, y, c] of [[19, 24, '#ffe680'], [24, 27, '#ffffff'], [22, 21, '#a8c8ff'], [26, 23, '#ffe680'], [18, 28, '#a8c8ff']]) p.set(x, y, (x + f) % 2 ? c : '#fff6c0');
  // 頭・くちばし・目
  p.ellipse(22, 9, 6, 5.5, K.b); p.ellipse(21, 8, 4, 3.5, K.l);
  p.rect(20, 12, 4, 3, '#c8a040'); p.set(22, 15, '#a07820');
  p.set(19, 8, '#ff5a8a'); p.set(25, 8, '#ff5a8a');
  // とさか
  for (let i = 0; i < 4; i++) p.set(21 + i, 2 + (i % 2), K.hl);
  // 足
  p.vline(18, 32, 37, '#c8a040'); p.vline(26, 32, 37, '#c8a040');
  return { p, oc: '#04030a' };
}
// ふりこの魔女ペンデュラ（34×46。むらさきの ドレスと とんがりぼうし。左手に 大きな ふりこ。コマで ふりこが ゆれる）
function paintPendula(f) {
  const W = 34, H = 46, p = new Painter(W, H);
  const D = { d: '#2a1238', b: '#4a2068', l: '#7a3aa0', hl: '#a868d0' };
  p.ellipse(17, 44.5, 10, 1.5, '#0a0410');
  // ドレス
  for (let y = 18; y < 44; y++) { const half = Math.round(4 + (y - 18) * 0.4); p.hline(17 - half, 16 + half, y, D.b); p.set(17 - half, y, D.l); p.set(16 + half, y, D.d); }
  for (let y = 22; y < 44; y += 6) p.hline(17 - Math.round(4 + (y - 18) * 0.4) + 1, 16 + Math.round(4 + (y - 18) * 0.4) - 1, y, D.hl);
  // 顔・かみ
  p.ellipse(17, 14, 4, 4.2, '#e8d0e8'); p.set(15, 14, '#3a0a3a'); p.set(19, 14, '#3a0a3a');
  p.rect(12, 12, 2, 8, '#c8c8e0'); p.rect(20, 12, 2, 8, '#c8c8e0');
  // とんがりぼうし
  for (let y = 0; y < 11; y++) { const half = Math.round(y * 0.6); p.hline(17 - half, 17 + half, y, D.d); }
  p.hline(10, 24, 10, D.l); p.set(17, 0, '#ffe680');
  // ふりこ（左手から。コマで 左右に）
  const sw = f % 2 ? 3 : -3;
  p.vline(5, 18, 20, '#c8a040');
  for (let k = 0; k < 12; k++) p.set(Math.round(5 + (sw * k) / 12), 20 + k, '#c8a040');
  p.ellipse(5 + sw, 34, 3.2, 3.2, '#e0b840'); p.ellipse(4 + sw, 33, 1.4, 1.4, '#fff0a0');
  return { p, oc: '#08020c' };
}
function paintCapsuleHole() {
  const p = new Painter(14, 8);
  p.ellipse(7, 5, 6, 2.5, '#6a4a28'); p.ellipse(7, 4.5, 5, 1.8, '#8a6438');
  p.set(4, 4, '#a8804a'); p.set(10, 5, '#a8804a');
  p.set(7, 2, '#fff6b0');
  return { p, oc: '#3a2410' };
}
function paintCapsuleSpot(f) {
  const p = new Painter(14, 10);
  p.ellipse(7, 7, 6, 2.5, '#6a4a28'); p.ellipse(7, 6.5, 5, 1.8, '#8a6438');
  const c = f % 2 ? '#fff6b0' : '#ffe080';
  for (const [x, y] of [[7, 5], [4, 6], [10, 6], [7, 2], [3, 3], [11, 2]]) p.set(x, y, (x + y + f) % 3 ? c : '#ffffff');
  return { p, oc: '#3a2410' };
}
function paintKira(f) {
  const p = new Painter(10, 10);
  p.ellipse(5, 7, 3, 2.2, '#8a8ab0'); p.ellipse(4.5, 6.5, 2, 1.4, '#c8c8f0');
  const c = f % 2 ? '#ffffff' : '#fff0a0';
  p.set(5, 2, c); p.set(5, 3, c); p.set(4, 3, c); p.set(6, 3, c); p.set(5, 4, c);
  p.set(1, 5, '#a8c8ff'); p.set(8, 4, '#a8c8ff');
  return { p, oc: '#2a2a48' };
}

export function paintRoadSpecial(kind, dir, f) {
  switch (kind) {
    case 'star_eater_npc': return paintStarEater(f);
    case 'pendula_npc': return paintPendula(f);
    case 'capsule_hole': return paintCapsuleHole();
    case 'capsule_spot': return paintCapsuleSpot(f);
    case 'kira_stone': return paintKira(f);
    default: return null;
  }
}
export const ROAD_SPECIALS = ['star_eater_npc', 'pendula_npc', 'capsule_hole', 'capsule_spot', 'kira_stone'];

