      if (side) {
        p.rect(3, 13, 9, 4, c); p.rect(10, 10, 4, 4, c); p.set(13, 11, '#231a2e'); p.set(14, 12, '#231a2e');
        p.rect(10, 9, 2, 2, cD); p.vline(2, 11 + f, 13, c);
        p.rect(4, 17, 1, 3 - f, cD); p.rect(10, 17, 1, 2 + f, cD); p.rect(6, 17, 1, 2 + f, cD); p.rect(8, 17, 1, 3 - f, cD);
      } else {
