    }
    case 'slot': {
      // スロットマシン（上の ランプが ちかちか 光る）
      const [a, b] = f ? ['#ff5a5a', '#fff080'] : ['#fff080', '#ff5a5a'];
      p.stamp(0, 0, [
        '................',
        '...gggggggggg...',
        `..g${'ab'.repeat(5)}g..`,
        '..gggggggggggg..',
        '.MMMMMMMMMMMMMM.',
        '.MmmmmmmmmmmmmM.',
        '.MmKKKKKKKKKKmMo',
        '.MmKWWKWWKWWKmMs',
        '.MmKWrKWyKWcKmMs',
        '.MmKWWKWWKWWKmMs',
        '.MmKKKKKKKKKKmMs',
        '.MmmmmmmmmmmmmMs',
        '.MMMMMMMMMMMMMM.',
        '.MggggggggggggM.',
        '.MmmmmmmmmmmmmM.',
        '.MmmmmyyyymmmmM.',
        '.MmmmmKKKKmmmmM.',
        '.MmmmmmmmmmmmmM.',
        '.MMMMMMMMMMMMMM.',
        '.DDDDDDDDDDDDDD.',
        '................',
      ], { g: '#f2c14e', a, b, M: '#6a2468', m: '#8e3a8a', K: '#1a1a2a', W: '#f4f2fa', r: '#e8303a', y: '#f2c14e', c: '#3a9a3a', D: '#2a1030', o: '#e8303a', s: '#c8c8d8' });
      oc = OUT;
