      p.ellipse(8, 9 - b, 4.4, 4.4, '#7ab8e8');
      p.ellipse(7.4, 8.4 - b, 3.4, 3.4, '#b8e4ff');
      p.ellipse(6.8, 7.6 - b, 1.6, 1.6, '#f0fbff');
      // 上の 三日月の かざり
      p.set(7, 1 - b, '#fff2a0'); p.set(8, 1 - b, '#fff2a0'); p.set(6, 2 - b, '#fff2a0'); p.set(9, 2 - b, '#e8c050');
      p.rect(7, 15 - b, 2, 2, '#8a94b8');
      if (f) { p.set(2, 4, '#ffffff'); p.set(14, 10, '#e6f6ff'); } else { p.set(13, 3, '#ffffff'); p.set(3, 13, '#e6f6ff'); }
      oc = '#2a3a6a';
      break;
    }
    case 'gold_sword': {
      // 王家の黄金の剣（石の 台に ささっている。まわりに 黒い もや）
      const G = '#f2c14e', GL = '#fff0a0', GD = '#a8700e', S = '#c8ae78', SD = '#8a6e40', M = '#4a2a6a', MD = '#2a1640';
      // 台
      p.rect(3, 15, 10, 5, S); p.hline(3, 12, 15, '#e2cc98'); p.vline(12, 16, 19, SD); p.hline(3, 12, 19, SD);
      // 刀身（金色。台に ささっている）
      p.rect(7, 4, 2, 11, GL); p.vline(8, 4, 14, G); p.set(7, 3, GL);
      // つば と つか
      p.hline(4, 11, 3, GD); p.hline(5, 10, 2, G);
      p.vline(7, 0, 1, '#8a3a1a'); p.vline(8, 0, 1, '#6a2a10');
      p.set(7, 2, '#e8303a');
      // のろいの 黒い もや（コマで うごく）
      const mist = f ? [[2, 6], [13, 9], [3, 12], [12, 4], [1, 9]] : [[3, 5], [12, 7], [2, 11], [13, 12], [14, 5]];
      for (const [x, y] of mist) { p.set(x, y, M); p.set(x + 1, y, MD); p.set(x, y + 1, MD); }
      oc = '#3a2408';
      break;
    }
    case 'none':
      break;
    case 'ship':
      return paintShip(dir, f);
    // 第4章 Step 6: 砂の船「すなかぜ号」・ぬすまれた 船のかじ
    case 'sand_ship':
      return paintSandShip(dir, f);
    case 'rudder':
      return paintRudder(f);
    case 'camel':
      return paintCamel(dir, f);
    case 'zaid_demon':
      return paintSandDemon(f);
    case 'zaid_demon_true':
      return paintSandDemon(f, true);
    // 第4章 Step 7: 水の 柱の ろうの ミラ（目を とじている／水が 下がって 目を あけた）・水の守り星（render/temple-chars.js）
    case 'mira_prison':
      return fine(paintMiraPrison(false), '#1a3a5a');
    case 'mira_prison_low':
      return fine(paintMiraPrison(true), '#1a3a5a');
    case 'water_star':
      return fine(paintWaterStar(f), '#1a3a6a');
    // ひみつのダンジョン（render/secret-art.js）: 入口・しまった 入口・家族の記録の板・ごほうびの 宝箱
    case 'sd_door':
      return fine(paintSdDoor(f), SD_OUTLINE.sd_door);
    case 'sd_door_closed':
      return fine(paintSdDoorClosed(f), SD_OUTLINE.sd_door_closed);
    case 'sd_board':
      return fine(paintSdBoard(f), SD_OUTLINE.sd_board);
    case 'sd_chest':
      return fine(paintSdChest(f), SD_OUTLINE.sd_chest);
    default: {
      // 第5章: 星の塔・星祭りの かざり（render/ch5-art.js）
      // 第6章: 勇者の像・星の木・ちびアステル・ゼンマイ など（render/ch6-art.js）
      const c5 = paintCh5Special(kind, dir, f) || paintCh6Special(kind, dir, f);
      return c5 ? fine(c5.p, c5.oc) : null;
    }
  }
  return fine(p, oc);
}

// どうぶつ・船: Scale2x を 2かい で 4ばいの こまかさ（res 4）に して、ひかりと ふちどり
function fine(p, oc) {
  const q = scale2x(scale2x(p));
  rimShade(q, 0.2, 0.16);
  if (oc) outline2(q, oc, 0.4);
  return q;
}

// オベリスク（王家のピラミッドの 前の 大きな 石の 柱。てっぺんは 金色の 小さな ピラミッド。どの むきも おなじ）
// 人より ずっと 高い（14×46）。ひかりは 左から。柱の まん中に たてに 絵文字
function paintObelisk() {
  const W = 14, H = 46, p = new Painter(W, H);
  const S = '#d8c08c', SL = '#f2e0b4', SD = '#a88a58', SDD = '#86683c', GLY = '#7a6038', G = '#ffd84a', GL = '#fff4b8', GD = '#c88e1e';
  // 柱（下が ふとく、上が ほそい）
  for (let y = 6; y < H; y++) {
    const half = 3 + Math.round(((y - 6) / (H - 6)) * 2.4);
    const x0 = 7 - half, x1 = 6 + half;
    p.hline(x0, x1, y, S);
    p.set(x0, y, SL); p.set(x0 + 1, y, SL);
    p.set(x1, y, SDD); p.set(x1 - 1, y, SD);
  }
  // てっぺんの 金の ピラミッド
  for (let y = 0; y < 6; y++) {
    const half = Math.round(y * 0.6) + 1;
    p.hline(7 - half, 6 + half, y, G);
    p.set(7 - half, y, GL);
    p.set(6 + half, y, GD);
  }
  p.set(6, 0, GL); p.set(7, 0, G);
  // 絵文字（上から 太陽・目・鳥・アンク・波）
  const glyphs = [
    [[6, 9], [7, 9], [5, 10], [8, 10], [6, 11], [7, 11]],
    [[5, 15], [6, 15], [7, 15], [8, 15], [6, 16], [7, 16]],
    [[6, 20], [7, 20], [5, 21], [6, 21], [7, 22], [6, 23]],
    [[6, 27], [7, 27], [5, 28], [8, 28], [6, 29], [7, 29], [6, 30], [7, 30], [5, 31], [8, 31]],
    [[5, 35], [7, 35], [6, 36], [8, 36], [5, 37], [7, 37]],
  ];
  for (const g of glyphs) for (const [x, y] of g) p.set(x, y, GLY);
  return fine(p, '#4a3418');
}

// 大臣ザイードの 影（月明かりに うつった、大きな 砂の 魔神の 形。第4章 Step 3 の 夜の 中庭。どの むきも おなじ）
// 人より ずっと 大きい（36×44）。下は 砂の うず。
// lit … 本当の すがた（Step 5 の 夜の 王の間。たたかいの え（ch4-boss-art.js の zaidDemon）と おなじ いろ。金の うでわ・おび・白い ツメ）
function paintSandDemon(f, lit = false) {
  const W = 36, p = new Painter(W, 44);
  const B = lit ? '#352046' : '#25172f', BD = lit ? '#1a0d26' : '#150b1f', BL = lit ? '#5a3f7a' : '#44305a';
  const S = '#7a5e3a', SD = '#4e3a24', SL = '#a8865a';
  const HORN = lit ? '#4e3a5e' : '#3a2848', HORNL = lit ? '#7e6898' : '#6a5084', EYE = '#ff4a3a', EYEL = '#ffd8a8', GEM = '#e8303a';
  // 左右 おなじに かく
  const sym = (y, x0, x1, c) => { p.hline(x0, x1, y, c); p.hline(W - 1 - x1, W - 1 - x0, y, c); };
  // 砂の うず（下半身。下へ いくほど ほそく、まわる すじ）
  for (let y = 29; y <= 43; y++) { const hw = Math.max(2, Math.round(9 - (y - 29) * 0.55)); p.hline(18 - hw, 17 + hw, y, SD); }
  for (let y = 30; y <= 42; y += 3) {
    const hw = Math.max(1, Math.round(8 - (y - 29) * 0.55)), sh = ((y + f * 2) % 4) - 1;
    p.hline(18 - hw + sh, 17 + hw - 2 + sh, y, S); p.set(18 - hw + sh, y, SL);
  }
  // うで（かたから 下へ。先に ツメ）
  for (let y = 15; y <= 27; y++) sym(y, 1 + Math.floor((y - 15) / 6), 8 - Math.floor((y - 15) / 5), B);
  for (const x of [1, 3, 5]) { sym(28, x, x, BD); sym(29, x, x, BD); }
  // からだ（かたが ひろく、こしへ ほそく）
  for (let y = 14; y <= 31; y++) { const hw = y < 17 ? 9 + (y - 14) : Math.round(12 - (y - 17) * 0.45); p.hline(18 - hw, 17 + hw, y, B); }
  // むねの すじ・月明かりの ふち（ひだりが 明るい）
  sym(19, 11, 15, BD); sym(23, 12, 15, BD); p.vline(17, 18, 28, BD); p.vline(18, 18, 28, BD);
  for (let y = 15; y <= 26; y++) p.set(1 + Math.floor((y - 15) / 6), y, BL);
  p.hline(7, 12, 14, BL); p.vline(7, 16, 24, BL);
  // あたま と つの
  p.ellipse(17.5, 8.5, 6.5, 5.5, B);
  for (let i = 0; i < 6; i++) { sym(6 - i, 10 - Math.floor(i * 0.7), 11 - Math.floor(i * 0.7), HORN); }
  p.set(7, 0, HORNL); p.set(28, 0, HORNL);
  p.hline(13, 16, 4, BL);
  // ひたいの 赤い 宝石（大臣の ターバンと おなじ）
  p.rect(17, 5, 2, 2, GEM);
  // 光る 目と 口
  sym(8, 13, 15, EYE); sym(9, 14, 15, EYE); sym(8, 14, 14, EYEL);
  p.hline(15, 20, 11, BD); p.set(16, 12, BD); p.set(19, 12, BD); p.set(15, 11, EYE); p.set(20, 11, EYE);
  if (lit) {
    const G = '#c89a32', GL = '#f2d070', CL = '#efe4c8';
    // 白い ツメ・金の うでわ・こしの 金の おび（赤い 宝石）
    for (const x of [1, 3, 5]) { sym(28, x, x, CL); sym(29, x, x, CL); }
    sym(25, 2, 7, G); sym(24, 3, 5, GL);
    p.hline(12, 23, 30, G); p.hline(13, 18, 29, GL); p.rect(17, 30, 2, 1, GEM);
    // かたの 月明かり
    p.hline(9, 12, 15, BL); p.set(13, 16, BL);
  }
  return fine(p, '#6a3a8a');
}

// ラクダ（キャラバンの ラクダ。こぶに 赤い しきもの・よこに にもつ。第4章 砂の国）
// 人より 大きい（よこむき 30×25・まえ うしろ 18×25）。よこむきは left を かいて、right は はんてん
export function paintCamel(dir, f) {
  const side = dir === 'left' || dir === 'right';
  const p = new Painter(side ? 30 : 18, 25);
  const C = '#d8a868', CD = '#a8783e', CDD = '#7a5228', CL = '#f0cc90';
  const R = '#c83a3a', RD = '#8a2424', Y = '#f2c14e', B = '#3a64c8', BAG = '#8a5a32', BAGD = '#5e3c1e', EYE = '#231a2e';
  // あし（x … ひだりはし、lift … あげる ドット、near … てまえの あし）
  const leg = (x, lift, near) => {
    const c = near ? C : CD;
    p.rect(x, 16, 2, 7 - lift, c);
    p.rect(x, 19 - lift, 3, 2, c); // ひざの こぶ
    p.set(x + 2, 20 - lift, near ? CD : CDD);
    p.rect(x - 1, 23 - lift, 3, 2, near ? CDD : shade(CDD, -0.2));
    if (near) { p.vline(x + 1, 16, 18 - lift, CD); p.set(x, 19 - lift, CL); }
  };
  if (side) {
    const b = f; // あるく ときに 頭が ゆれる
    // むこうの あし
    leg(8, f ? 1 : 0, false);
    leg(21, f ? 0 : 1, false);
    // しっぽ
    p.vline(27, 11, 13, CD); p.rect(26, 14, 2, 2, CDD);
    // からだ と こぶ
    spans(p, [[10, 11, 22], [11, 9, 24], [12, 8, 25], [13, 8, 26], [14, 8, 26], [15, 9, 25], [16, 10, 24], [17, 12, 21]], C);
    spans(p, [[5, 15, 18], [6, 14, 19], [7, 13, 20], [8, 12, 21], [9, 11, 22]], C);
    p.hline(10, 23, 16, CD); p.hline(13, 20, 17, CDD); p.vline(25, 12, 15, CD);
    p.hline(15, 17, 5, CL); p.set(14, 6, CL);
    // こぶに かけた 赤い しきもの（しまと ふさ）
    spans(p, [[6, 15, 18], [7, 14, 19], [8, 13, 20], [9, 12, 21], [10, 12, 21], [11, 12, 21], [12, 12, 21], [13, 12, 21], [14, 12, 21]], R);
    p.hline(12, 21, 9, Y); p.hline(12, 21, 12, B); p.hline(12, 21, 13, Y);
    p.vline(21, 9, 14, RD); p.hline(15, 18, 6, shade(R, 0.25));
    for (let x = 12; x <= 21; x += 2) p.set(x, 15, x % 4 ? Y : B);
    // よこの にもつ（ひもで つるす）
    p.rect(19, 11, 5, 5, BAG); p.hline(19, 23, 11, shade(BAG, 0.25)); p.vline(23, 12, 15, BAGD); p.hline(19, 23, 15, BAGD);
    p.vline(21, 8, 10, BAGD); p.set(21, 13, Y);
    // くび（むねから まえへ のびて 頭へ）
    spans(p, [[7, 4, 7], [8, 5, 8], [9, 6, 9], [10, 7, 10], [11, 7, 10], [12, 8, 10], [13, 8, 10]].map(([y, x0, x1]) => [y + (y < 10 ? b : 0), x0, x1]), C);
    p.vline(4, 7 + b, 8 + b, CD); p.set(5, 9 + b, CD); p.set(6, 10, CD); p.vline(7, 11, 13, CD);
    p.set(8, 8 + b, CL); p.set(9, 9 + b, CL);
    // あたま（はなづらは ひだり）
    spans(p, [[2, 3, 6], [3, 1, 6], [4, 0, 6], [5, 0, 5], [6, 1, 4]].map(([y, x0, x1]) => [y + b, x0, x1]), C);
    p.set(5, 1 + b, CD); p.set(6, 1 + b, C); // みみ
    p.hline(3, 5, 2 + b, CL);
    p.set(3, 3 + b, EYE); p.set(4, 3 + b, CDD);
    p.set(0, 4 + b, CDD); p.hline(0, 2, 5 + b, CD); p.hline(1, 3, 6 + b, CD);
    // おもがい（あたまの ひも）と たづな
    p.vline(3, 4 + b, 6 + b, R); p.set(2, 4 + b, Y);
    p.set(3, 7 + b, RD); p.set(4, 8 + b, RD);
    // てまえの あし
    leg(11, f ? 0 : 1, true);
    leg(23, f ? 1 : 0, true);
  } else if (dir === 'down') {
    const b = f;
    // うしろの あし（からだの かげ）
    p.rect(3, 16, 2, 6, CD); p.rect(13, 16, 2, 6, CD);
    // からだ（こぶに しきもの）
    spans(p, [[8, 4, 13], [9, 3, 14], [10, 2, 15], [11, 2, 15], [12, 2, 15], [13, 2, 15], [14, 2, 15], [15, 3, 14], [16, 4, 13]], R);
    p.hline(2, 15, 11, Y); p.hline(2, 15, 13, B); p.hline(2, 15, 14, Y);
    p.vline(15, 10, 15, RD); p.vline(14, 9, 16, RD);
    for (let x = 3; x <= 14; x += 2) p.set(x, 17, x % 4 === 1 ? Y : B);
    p.rect(1, 11, 2, 4, BAG); p.rect(15, 11, 2, 4, BAGD);
    // むね（まえの 毛）
    spans(p, [[11, 6, 11], [12, 6, 11], [13, 6, 11], [14, 6, 11], [15, 6, 11], [16, 7, 10]], C);
    p.vline(11, 11, 15, CD); p.vline(6, 12, 15, CL);
    // まえあし
    p.rect(5, 16, 2, 7 - (f ? 1 : 0), C); p.rect(11, 16, 2, 7 - (f ? 0 : 1), C);
    p.hline(5, 7, 19 - (f ? 1 : 0), CL); p.hline(10, 12, 19 - (f ? 0 : 1), CL);
    p.rect(4, 23 - (f ? 1 : 0), 4, 2, CDD); p.rect(10, 23 - (f ? 0 : 1), 4, 2, CDD);
    p.vline(6, 16, 18, CD); p.vline(12, 16, 18, CD);
    // くび
    p.rect(7, 8 + b, 4, 4, C); p.vline(10, 8 + b, 11, CD); p.vline(7, 8 + b, 10, CL);
    // あたま（こちらを むく。ほそながい かお と ふくらんだ はなさき）
    spans(p, [[0, 7, 10], [1, 6, 11], [2, 6, 11], [3, 7, 10], [4, 7, 10], [5, 7, 10], [6, 6, 11], [7, 6, 11], [8, 7, 10]].map(([y, x0, x1]) => [y + b, x0, x1]), C);
    p.set(5, 0 + b, CD); p.set(12, 0 + b, CD); // みみ
    p.hline(8, 9, 0 + b, CL); p.vline(8, 3 + b, 5 + b, CL);
    p.set(6, 2 + b, EYE); p.set(11, 2 + b, EYE); // 目は よこに
    p.hline(6, 11, 7 + b, CL); p.set(7, 6 + b, CDD); p.set(10, 6 + b, CDD); p.hline(8, 9, 8 + b, CD);
    p.set(6, 4 + b, R); p.set(11, 4 + b, R); p.hline(7, 10, 5 + b, R); p.set(8, 5 + b, Y);
  } else {
    const b = f;
    // まえの 頭の うしろ（こぶの むこうに すこし みえる）
    spans(p, [[2, 7, 10], [3, 7, 10], [4, 7, 10]].map(([y, x0, x1]) => [y + b, x0, x1]), CD);
    p.set(6, 2 + b, CDD); p.set(11, 2 + b, CDD); p.hline(8, 9, 2 + b, C);
    p.rect(7, 5 + b, 4, 3, CD);
    // こぶと しきもの・からだ
    spans(p, [[6, 6, 11], [7, 5, 12], [8, 4, 13], [9, 3, 14], [10, 2, 15], [11, 2, 15], [12, 2, 15], [13, 2, 15], [14, 2, 15], [15, 3, 14], [16, 4, 13]], C);
    spans(p, [[7, 6, 11], [8, 5, 12], [9, 4, 13], [10, 3, 14], [11, 3, 14], [12, 3, 14], [13, 3, 14]], R);
    p.hline(4, 13, 9, Y); p.hline(3, 14, 12, B); p.hline(3, 14, 13, Y);
    for (let x = 3; x <= 14; x += 2) p.set(x, 14, x % 4 === 1 ? Y : B);
    p.vline(14, 10, 13, RD); p.hline(6, 11, 7, shade(R, 0.25));
    p.rect(1, 11, 2, 4, BAG); p.rect(15, 11, 2, 4, BAGD);
    p.vline(15, 14, 15, CD); p.hline(5, 12, 16, CD);
    // しっぽ
    p.vline(8, 14, 17, CD); p.rect(8, 18, 2, 2, CDD);
    // うしろあし
    p.rect(5, 16, 2, 7 - (f ? 1 : 0), C); p.rect(11, 16, 2, 7 - (f ? 0 : 1), C);
    p.hline(5, 7, 19 - (f ? 1 : 0), CL); p.hline(10, 12, 19 - (f ? 0 : 1), CL);
    p.rect(4, 23 - (f ? 1 : 0), 4, 2, CDD); p.rect(10, 23 - (f ? 0 : 1), 4, 2, CDD);
    p.vline(6, 16, 18, CD); p.vline(12, 16, 18, CD);
  }
  let q = fine(p, OUT);
  if (dir === 'right') q = q.flipX();
  return q;
}

// 船（しおかぜ号）。よこむきは left を かく（right は はんてんして つかう）
// 砂の船「すなかぜ号」（第4章 Step 6。砂の 上を すべる 船。そこに すべり木・砂色の 帆に 赤い おびと 海賊の しるし。
// 波の あわの かわりに 砂しぶき）。大きさと 形の きほんは しおかぜ号（paintShip）と おなじ
export function paintSandShip(dir, f) {
  const p = new Painter(30, 26);
  const hull = '#a8744a', hullD = '#6a4428', hullL = '#d0a066', stripe = '#c83a3a';
  const sail = '#f2e4c0', sailD = '#cdb88e', band = '#c83a3a', mast = '#5a3a22', flag = '#2a1a30', mark = '#3a2418', spray = '#f2d49a', ski = '#4a2e1a';
  const b = f ? 1 : 0;
  const markAt = (pts) => { for (const [x, y] of pts) p.set(x, y + b, mark); };
  if (dir === 'left' || dir === 'right') {
    for (let x = 2; x <= 27; x++) {
      const top = (x < 6 ? 13 + Math.floor((x - 2) / 1.4) : 16) + b;
      const bot = (x < 5 ? 17 : x < 7 ? 19 : x > 25 ? 19 : 20) + b;
      for (let y = top; y <= bot; y++) p.set(x, y, y === top ? hullL : y === bot ? hullD : hull);
      if (x >= 6 && x <= 25) p.set(x, 18 + b, stripe);
    }
    // すべり木（前が そり上がる）と ささえ
    p.hline(4, 26, 22 + b, ski); p.set(3, 21 + b, ski); p.set(2, 20 + b, ski);
    for (const x of [8, 14, 20]) p.set(x, 21 + b, hullD);
    p.vline(15, 2 + b, 15 + b, mast);
    for (let y = 4; y <= 12; y++) {
      const bulge = Math.round(Math.sin(((y - 4) / 8) * Math.PI) * 2);
      p.hline(9 - bulge, 21 - bulge, y + b, y === 10 || y === 11 ? band : sail);
      p.set(21 - bulge, y + b, sailD);
    }
    markAt([[13, 5], [17, 5], [14, 6], [16, 6], [15, 7], [14, 8], [16, 8], [13, 9], [17, 9]]);
    p.rect(16, 1 + b, 4, 2, flag); p.set(f ? 20 : 19, (f ? 1 : 3) + b, flag);
    p.set(1 + f, 22, spray); p.set(27 - f, 23, spray); p.set(6, 24, spray); p.set(22, 24, spray); p.set(12, 23 + f, spray);
  } else {
    const back = dir === 'up';
    for (let y = 15; y <= 21; y++) {
      const half = back ? (y === 21 ? 6 : 7) : (y <= 18 ? 7 : y <= 20 ? 5 : 3);
      for (let x = 15 - half; x <= 14 + half; x++) p.set(x, y + b, y === 15 ? hullL : y === 21 || (!back && y === 20 && Math.abs(x - 14.5) > 3) ? hullD : hull);
    }
    p.hline(8, 21, 17 + b, stripe);
    // すべり木（左右の 2本）
    p.vline(9, 18 + b, 22 + b, ski); p.vline(20, 18 + b, 22 + b, ski);
    p.vline(14, 2 + b, 15 + b, mast); p.vline(15, 2 + b, 15 + b, mast);
    for (let y = 4; y <= 12; y++) {
      const w = 8 + Math.round(Math.sin(((y - 4) / 8) * Math.PI) * 1);
      p.hline(15 - w, 14 + w, y + b, y === 10 || y === 11 ? band : back ? sailD : sail);
    }
    if (!back) markAt([[12, 5], [17, 5], [13, 6], [16, 6], [14, 7], [15, 7], [13, 8], [16, 8], [12, 9], [17, 9]]);
    p.rect(16, 1 + b, 3, 2, flag); p.set(f ? 19 : 18, 3 + b, flag);
    p.set(7 + f, 23 + b, spray); p.set(22 - f, 23 + b, spray); p.set(10, 24, spray); p.set(19, 24, spray);
  }
  return fine(p, OUT);
}

// 船のかじ（砂の古城の たからべやに 立てかけてある。木の わに 8本の とって・まん中に 金の じく。コマで きらり）
function paintRudder(f) {
  const p = new Painter(CW, CH);
  const W = '#8a5a32', WL = '#c08a52', WD = '#5a3a1e', G = '#f2c14e', GL = '#fff0a0';
  const cx = 8, cy = 10;
  p.hline(3, 13, 19, '#3a2a1a');
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4;
    for (let r = 1; r <= 7; r++) p.set(Math.round(cx + Math.cos(a) * r), Math.round(cy + Math.sin(a) * r), r >= 6 ? WD : W);
  }
  for (let t = 0; t < 48; t++) {
    const a = (t * Math.PI) / 24;
    const lit = Math.cos(a - Math.PI * 1.25) > 0.2;
    p.set(Math.round(cx + Math.cos(a) * 4.6), Math.round(cy + Math.sin(a) * 4.6), lit ? WL : W);
  }
  p.rect(7, 9, 3, 3, G); p.set(7, 9, GL);
  if (f) { p.set(3, 4, '#ffffff'); p.set(13, 6, GL); } else { p.set(12, 3, '#ffffff'); p.set(3, 13, GL); }
  return fine(p, '#2a1a0a');
}

export function paintShip(dir, f) {
  const p = new Painter(30, 26);
  const hull = '#8a5a32', hullD = '#5a3a22', hullL = '#b8864a', stripe = '#f4f2fa';
  const sail = '#f4f2fa', sailD = '#c8c4d8', mast = '#5a3a22', flag = '#c83a3a', star = '#f2c14e', foam = '#e6f4ff';
  const b = f ? 1 : 0;
  if (dir === 'left' || dir === 'right') {
    for (let x = 2; x <= 27; x++) {
      const top = (x < 6 ? 13 + Math.floor((x - 2) / 1.4) : 16) + b;
      const bot = (x < 5 ? 17 : x < 7 ? 19 : x > 25 ? 19 : 21) + b;
      for (let y = top; y <= bot; y++) p.set(x, y, y === top ? hullL : y === bot ? hullD : hull);
      if (x >= 6 && x <= 25) p.set(x, 18 + b, stripe);
    }
    for (const x of [10, 15, 20]) p.set(x, 19 + b, hullD);
    p.vline(15, 2 + b, 15 + b, mast);
    for (let y = 4; y <= 12; y++) {
      const bulge = Math.round(Math.sin(((y - 4) / 8) * Math.PI) * 2);
      p.hline(9 - bulge, 21 - bulge, y + b, sail);
      p.set(21 - bulge, y + b, sailD);
    }
    p.hline(13, 17, 8 + b, star); p.vline(15, 6 + b, 10 + b, star);
    p.rect(16, 1 + b, 4, 2, flag); p.set(f ? 20 : 19, (f ? 1 : 3) + b, flag);
    p.set(3 + f, 22, foam); p.set(26 - f, 22, foam); p.set(8, 23, foam); p.set(22, 23, foam);
  } else {
    const back = dir === 'up';
    for (let y = 15; y <= 21; y++) {
      const half = back ? (y === 21 ? 6 : 7) : (y <= 18 ? 7 : y <= 20 ? 5 : 3);
      for (let x = 15 - half; x <= 14 + half; x++) p.set(x, y + b, y === 15 ? hullL : y === 21 || (!back && y === 20 && Math.abs(x - 14.5) > 3) ? hullD : hull);
    }
    p.hline(8, 21, 17 + b, stripe);
    p.vline(14, 2 + b, 15 + b, mast); p.vline(15, 2 + b, 15 + b, mast);
    for (let y = 4; y <= 12; y++) {
      const w = 8 + Math.round(Math.sin(((y - 4) / 8) * Math.PI) * 1);
      p.hline(15 - w, 14 + w, y + b, back ? sailD : sail);
    }
    if (!back) { p.hline(12, 17, 8 + b, star); p.vline(14, 6 + b, 10 + b, star); p.vline(15, 6 + b, 10 + b, star); }
    p.rect(16, 1 + b, 3, 2, flag); p.set(f ? 19 : 18, 3 + b, flag);
    p.set(7 + f, 22 + b, foam); p.set(22 - f, 22 + b, foam);
  }
  return fine(p, OUT);
}

