// 第4章 Step 2（かれた地下水路）: 水路の 底・水の たかさ（通路より ひくい）・水門と こうしの とびらの たかさ・がれきの 山の たかさ
const CANAL_BED_H = -0.42, CANAL_WATER_Y = -0.27, GATE_H = 1.05, DAM_H = 0.62;
// 地面の たかさ（深い 雪は すこし 高く・谷は ふかく・水路の 底は ひくく）
// 時間で かわる とびらの しるし（第5章 Step 8 の 影の城の 炎の 柱。world/clock.js の timeFlag）
const TIMED_FLAGS = new Set(['@fireA', '@fireB']);
const FLOOR_H = { [T.STEPPING]: -0.16, [T.DEEP_SNOW]: 0.14, [T.CHASM]: -0.8, [T.CANAL_BED]: CANAL_BED_H, [T.DAM]: CANAL_BED_H, ...TEMPLE_FLOOR_H, ...TOWER_FLOOR_H, ...KUMOI_FLOOR_H, ...MEMORY_FLOOR_H, ...EARTH_FLOOR_H, ...CASTLE_FLOOR_H, ...CH6_FLOOR_H };
// 雪・氷・砂ばくの 地面の よこの え
const SIDE_OF = {
  [T.SAND]: 'sand_side', [T.SNOW]: 'snow_side', [T.SNOW_PATH]: 'snow_side', [T.DEEP_SNOW]: 'snow_side', [T.ICE]: 'ice_side',
  [T.DESERT]: 'sand_side', [T.DUNE]: 'sand_side', [T.CANAL_FLOOR]: 'canal_side', [T.CANAL_BED]: 'canal_side',
  [T.SUN_SHADOW]: 'sand_side', [T.OBELISK_BASE]: 'sand_side',
};
// 第4章 Step 4: 王家のピラミッド（ふちの だんの 高さ・1だんごとに 高く なる ぶん。てっぺんは 1.3 + 7 × 0.36）
const PYR_H0 = 1.3, PYR_STEP = 0.36;
