export { blockSpec, WALL_TILES, TREE_TILES, SIDE_OF, FLOOR_H, CANAL_WATER_Y, GATE_H };

// タイルの しゅるい: FLOOR / WATER / BLOCK（もの・き は FLOOR の うえに たてる）
function kindOf(id) {
  if (id === T.VOID) return 0;
  if (WATER_TILES.has(id) || LIQUID_TILES[id]) return WATER;
