    cv.part({ ol: 'line' });
    cv.poly(F.P([[a0, -0.92], [a1, -0.92], [a1, 0.92], [a0, 0.92]]), metal('gold'), { n: 'row', cx: 0.6 });
    const gid = cv.cur;
