  if (W.plus || W.star) sparkleList(cv, F, [[L + 3.0, 1.6]], '#ffffff', '#fff6b0');
  ornate(cv, F, W, { gem: [L + 2.7, 0, 0.55], line: [[-8, 0], [L + 1.2, 0]], clip: id, lw: 0.2, glints: [[L + 4.2, 1.0], [L - 2.0, -1.4], [L + 4.2, -1.0], [L * 0.5, 1.4]] });
