    case 'gakuran':
      buttons(cv, [[X(2.55), 22.9 + b], [X(2.6), 24.5 + b], [X(2.6), 26.1 + b], [X(2.55), 27.7 + b], [X(2.4), 29.3 + b]], null, T.gold);
