      cv.poly([[X(1.4), 21.8 + b], [X(-2.4), 21.8 + b], [X(-2.8), 28.8 + b], [X(2.2), 28.8 + b], [X(2.8), 25.2 + b], [X(2.7), 23.0 + b]], T.plate, { cx: 0.8, cy: 0.3 });
      cv.crease([[X(-2.4), 24.8 + b], [X(2.6), 24.8 + b]], 0.26, -0.4, { parts: [cv.cur] });
