      break;
    }
    case 'saiyan': {
      cv.part({ ol: 'line' });
      cv.poly([[X(1.6), 21.4 + b], [X(-2.4), 21.4 + b], [X(-3.1), 23.0 + b], [X(-2.9), 28.6 + b], [X(2.5), 28.6 + b], [X(3.1), 25.4 + b], [X(3.2), 23.4 + b], [X(2.6), 22.0 + b]], T.plate, { n: 'bevel', bw: 1.0, bs: 0.7 });
      const id = cv.cur;
