      cv.poly([[X(1.0), 21.0 + b], [X(2.6), 21.2 + b], [X(2.7), 25.2 + b], [X(2.1), 25.4 + b]], T.tee, { n: [0, 0] });
      cv.part({ ol: 'none', clip: base });
