      cv.crease([[X(0.2), 27.2 + b], [X(2.6), 27.2 + b], [X(3.0), 29.6]], 0.2, -0.45, { parts: [base] });
      if (T.neon) for (const [j, m] of T.neon.entries()) { cv.part({ ol: 'none', clip: base }); cv.stroke([[X(-3.4), 23.4 + j * 1.25 + b], [X(3.4), 24.4 + j * 1.25 + b]], 0.3, m, { n: [0, 0] }); }
