        cv.part({ ol: 'line' });
        cv.ell(X(2.7), 22.3 + b, 0.6, 0.6, T.ribbon, { bulge: 0.6 });
      } else if (T.loose) {
        // ゆるめた ネクタイ（むすびめが さがる）と あけた えりもと
