      }
      if (T.lapel) { cv.part({ ol: 'line' }); cv.poly([[X(0.3), 21.0 + b], [X(1.3), 21.0 + b], [X(2.3), 25.8 + b], [X(1.6), 26.0 + b]], T.lapel, { n: [0.2, -0.1] }); }
      if (T.blazer) emblem(cv, X(0.6), 24.4 + b, 'school', O);
      if (T.rumple) suitWrinkles(cv, base, 'side', X, b);
      if (T.lanyard) {
