        cv.stroke([[X(0.4), 21.0 + b], [X(2.9), 25.0 + b]], 0.24, T.lanyard, { n: [0, 0] });
        idCard(cv, X(3.2), 25.0 + b, T.lanyard);
      }
      if (T.medal) medal(cv, X(2.6), 26.5 + b, T.medal, [[X(0.6), 21.4 + b]]);
