// ───────────── 服の つけたし（outfit26 の つけたしから） ─────────────
export function outfit41b(O, S) {
  if (!S.r41b) return;
  // すきとおった マント（うらも 明るい）
  if (O.cape) O.cape = { ...O.cape, m: sheer(S.cape), inner: sheer(mixC(S.cape, '#ffffff', 0.35)) };
  if (S.gown41b) {
    // 足もとまでの ドレス（すそは 広がる）・むねの 小さな 白い かざり・すける 長い そで
