    this.lum[i] = nx * LX + ny * LY + nz * LZ + bias;
    this.spc[i] = nx * HX + ny * HY + nz * HZ;
    this.pt[i] = this.cur;
    this.fix[i] = -1;
  }

  // だえん（cx, cy, rx, ry はマス。rot: かたむき）
  // o.n: 'sphere'（まるい） | 'flat' | [nx, ny]（いつも おなじ むき） | 'cylV'（たての つつ） | 'cylH'
  // o.bulge: まるみの つよさ  o.bias: あかるさ  o.tex(ix, iy): あかるさの もよう
