// 2.5D（たちたい）がめんの ための え
// ・タイルの え を 1まいに ならべた「アトラス」
// ・かべの よこ・うえ、やま、はし など 3D だけで つかう え
// ・つぼ・さく・かんばん など たてて みせる「もの」の え（せなかは とうめい）
import { T } from '../../shared/tiles.js';
