import { Painter, prand, makeCanvas, ctxOf, shade } from './pixel.js';
import { paintStorm } from './tiles-ch4.js';
import { PYRAMID_EXTRAS } from './tiles-pyramid.js';
// 第4章 Step 7: 砂の底の神殿の たてた もの（3色の レバー・水の 柱の ろう・砂の海賊の ほこら）
import { TEMPLE_PROPS } from './tiles-temple.js';
import { LAB_PROPS } from './tiles-lab.js';
import { TOWER_PROPS } from './tiles-tower.js';
import { KUMOI_PROPS } from './tiles-kumoi.js';
import { MEMORY_PROPS } from './tiles-memory.js';
import { EARTH_PROPS } from './tiles-earth.js';
import { CASTLE_PROPS } from './tiles-castle.js';
import { TOP_PROPS } from './tiles-top.js';
import { CH6_PROPS } from './tiles-ch6.js';
import {
  canalWallFace, canalWallTop, canalSidePaint, damTopPaint, paintCanalWater, sluiceTopPaint, sluiceBoardPaint, pillarSidePaint, pillarTopPaint, rubbleAtlasPaint,
  CANAL_SUN,
} from './tiles-canal.js';

const TAU = Math.PI * 2;

// ───────────── アトラス ─────────────
export class Atlas {
  constructor(size = 512) {
    this.size = size;
    this.cols = Math.floor(size / 16);
    this.canvas = makeCanvas(size, size);
    this.ctx = ctxOf(this.canvas);
    this.slots = new Map();
    this.n = 0;
  }

  // key の え を いれて UV（はんぴくせる うちがわ）を かえす
  uv(key, draw) {
    let r = this.slots.get(key);
    if (r) return r;
    const i = this.n++;
    const cx = (i % this.cols) * 16, cy = Math.floor(i / this.cols) * 16;
    if (cy + 16 > this.size) throw new Error('atlas full');
    const c = draw();
    if (c) this.ctx.drawImage(c, cx, cy);
    const s = this.size, e = 0.5;
    // three.js は v=1 が がぞうの うえ
    r = { u0: (cx + e) / s, u1: (cx + 16 - e) / s, v0: 1 - (cy + 16 - e) / s, v1: 1 - (cy + e) / s };
    this.slots.set(key, r);
    return r;
  }
}

const C = {
