// 2D の 水と おなじ もようの 32×32 の え（2マスぶん。くりかえすと つなぎめが ない。f … コマ 0〜15。flow … 0 東へ・1 南へ）
export function canalWaterPainter(f, flow = 0) {
  const p = new Painter(32, 32);
  paintCanalWater(p, 0, 0, f, 32, 32, flow);
