export const CH3_SPEED = { [T.LAVA]: 380, [T.LAVA_FLOOR]: 640, [T.BRAZIER_LIT]: 140, [T.HOT_SPRING]: 520, [T.FLAME_WALL]: 150 };
// レールの つながり（render/tiles.js の prepareMap）
