const SD = { d: '#5a4220', b: '#8a6a3a', m: '#a8844a', l: '#c8a868', hl: '#e8d098' }; // 砂色の 石
const SAND = { d: '#b8904a', b: '#e0b860', l: '#f8dc90', w: '#fff4c8' };
const GLASS = { f: '#d8f0ff', e: '#7aa8c8', g: '#ffffff' };
const GOLD = { d: '#8a6418', b: '#d8a830', l: '#ffe070' };
const FL = { b: '#9a8058', l: '#b09468', d: '#7a6444', ln: '#5e4a30' };

function floorBase(p, v) {
  p.rect(0, 0, 16, 16, FL.b);
  const r = prand(v * 41 + 5);
  for (let i = 0; i < 7; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), i % 2 ? FL.l : FL.d);
  p.hline(0, 15, 0, FL.ln);
  p.vline(0, 0, 15, FL.ln);
}
// 砂時計の 形（x0, y0 … 左上。h … 高さ 9 か 7。top・bot … 上と 下の 砂の 量 0〜1。fall … 落ちている 砂の すじ）
function hourglass(p, x0, y0, h, top, bot, fall = false, f = 0) {
  const half = Math.floor(h / 2);
  p.hline(x0, x0 + 6, y0, GOLD.b); p.hline(x0, x0 + 6, y0 + h + 1, GOLD.b);
  p.set(x0, y0, GOLD.l); p.set(x0 + 6, y0 + h + 1, GOLD.d);
  for (let i = 0; i < h; i++) {
    const y = y0 + 1 + i;
    const wdt = i < half ? Math.max(0, 2 - Math.floor(i / 2)) : Math.max(0, Math.floor((i - half) / 2));
    const x1 = x0 + 3 - wdt - 1, x2 = x0 + 3 + wdt + 1;
    p.set(x1, y, GLASS.e); p.set(x2, y, GLASS.e);
    for (let x = x1 + 1; x < x2; x++) p.set(x, y, GLASS.f);
  }
  // 上の 砂（上から へる）・下の 砂（下から たまる）
  const tn = Math.round(top * half), bn = Math.round(bot * half);
  for (let i = half - tn; i < half; i++) {
    const wdt = Math.max(0, 2 - Math.floor(i / 2));
    for (let x = x0 + 3 - wdt; x <= x0 + 3 + wdt; x++) p.set(x, y0 + 1 + i, i === half - tn ? SAND.l : SAND.b);
  }
  for (let k = 0; k < bn; k++) {
    const i = h - 1 - k;
    const wdt = Math.max(0, Math.floor((i - half) / 2));
    for (let x = x0 + 3 - wdt; x <= x0 + 3 + wdt; x++) p.set(x, y0 + 1 + i, k === bn - 1 ? SAND.l : SAND.b);
  }
  if (fall) for (let i = half; i < h - bn; i++) if ((i + f) % 2 === 0) p.set(x0 + 3, y0 + 1 + i, SAND.w);
  p.set(x0 + 2, y0 + 2, GLASS.g);
}

// 砂時計の とびら（しまっている）: 砂色の 石の わくと 2まいの 石の とびら・まん中に 砂時計の もよう
function paintSandDoor(p, v) {
  p.rect(0, 0, 16, 16, SD.d);
  p.rect(1, 0, 14, 16, SD.b);
  p.rect(2, 2, 12, 14, SD.m);
  p.vline(7, 2, 15, SD.d); p.vline(8, 2, 15, SD.l);
  p.hline(1, 14, 1, SD.hl); p.hline(2, 13, 15, SD.d);
  for (const y of [5, 10]) { p.hline(3, 6, y, SD.l); p.hline(9, 12, y, SD.l); }
  hourglass(p, 4, 3, 7, 0.4, 0.6);
  p.set(3, 13, SD.d); p.set(12, 13, SD.d);
  const r = prand(v * 7 + 3);
  for (let i = 0; i < 3; i++) p.set(2 + Math.floor(r() * 12), 12 + Math.floor(r() * 3), SAND.d);
}
// 開いた 砂時計の とびら（わくだけ のこり、上から 砂が さらさら こぼれる）
export const DOOR_FRAMES = 3;
function paintSandDoorOpen(p, v, f) {
  floorBase(p, v);
  p.rect(0, 0, 2, 16, SD.b); p.rect(14, 0, 2, 16, SD.b);
  p.vline(1, 0, 15, SD.l); p.vline(14, 0, 15, SD.d);
  p.rect(0, 0, 16, 2, SD.m); p.hline(0, 15, 0, SD.hl);
  const k = f % DOOR_FRAMES;
  for (const x of [4, 8, 11]) for (let y = 2; y < 14; y++) if ((y + k * 2 + x) % 4 < 2) p.set(x, y, SAND.l);
  p.ellipse(8, 14.5, 5, 1.3, SAND.b); p.hline(5, 11, 14, SAND.l);
}
// 砂時計の 台（石の 台の 上に 砂時計。on … 砂が 落ちている）
export const DIAL_FRAMES = 3;
function paintDial(p, v, f, on) {
  floorBase(p, v);
  p.ellipse(8, 14.5, 6, 1.4, FL.ln);
  p.rect(3, 11, 10, 4, SD.b); p.hline(3, 12, 11, SD.hl); p.hline(3, 12, 14, SD.d);
  p.rect(4, 10, 8, 1, SD.l);
  if (on) {
    const k = f % DIAL_FRAMES;
    hourglass(p, 5, 0, 9, 0.85 - k * 0.25, 0.2 + k * 0.25, true, k);
    p.set(2, 2 + k, SAND.w); p.set(13, 4 - k, SAND.w);
  } else hourglass(p, 5, 0, 9, 0, 1);
}
// 時の砂時計の 台座（光の 砂が 下から 上へ 流れる。4コマ）・からっぽの 台座
export const ALTAR_FRAMES = 4;
function paintTimeAltar(p, v, f, empty = false) {
  floorBase(p, v);
  p.ellipse(8, 14.5, 7, 1.4, FL.ln);
  p.rect(1, 11, 14, 4, SD.b); p.hline(1, 14, 11, SD.hl); p.hline(1, 14, 14, SD.d);
  p.rect(2, 9, 12, 2, SD.m); p.hline(2, 13, 9, SD.l);
  for (const x of [3, 12]) { p.set(x, 12, GOLD.b); p.set(x, 13, GOLD.d); }
  if (empty) {
    p.ellipse(8, 9, 3, 0.8, SD.d);
    p.set(5, 7, SAND.l); p.set(11, 6, SAND.l);
    return;
  }
  const k = f % ALTAR_FRAMES;
  hourglass(p, 5, 0, 7, 0.5, 0.5);
  // 光の 砂（下から 上へ）
  for (let i = 0; i < 4; i++) {
    const y = 8 - ((k * 2 + i * 3) % 9);
    p.set(8, Math.max(1, y), '#ffffff');
  }
  p.set(3, 5 - (k % 3), SAND.w); p.set(13, 2 + (k % 3), SAND.w); p.set(2, 8, GOLD.l);
}
// 時が 止まった 泉（灰色の 水。さざなみも 止まっている）
function paintFrozenWater(p, v, f, m) {
  p.rect(0, 0, 16, 16, '#8a9098');
  const r = prand(v * 23 + 1);
  for (let k = 0; k < 3; k++) {
    const y = 2 + k * 5 + Math.floor(r() * 2);
    const x0 = Math.floor(r() * 10);
    p.hline(x0, x0 + 4, y, '#b4bac2');
    p.set(x0 + 1, y - 1, '#a4aab2');
  }
  for (let i = 0; i < 4; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), '#767c84');
  // 岸（となりが 水でない がわ）
  const rim = '#c8ccd2';
  if (m & 1) p.hline(0, 15, 0, rim);
  if (m & 2) p.vline(15, 0, 15, rim);
  if (m & 4) p.hline(0, 15, 15, rim);
  if (m & 8) p.vline(0, 0, 15, rim);
}
// わらの 家の かべ（たてに 木の 柱、よこに わらの たば）。mask 1 … 上から 見た やね（2.5D の 上の 面）
function paintStrawWall(p, v, f, m) {
  const S = { d: '#7a5a28', b: '#b8903e', l: '#d8b45a', hl: '#f0d488' };
  p.rect(0, 0, 16, 16, S.b);
  const r = prand(v * 31 + 9);
  if (m & 1) {
    for (let y = 0; y < 16; y += 2) for (let x = (y / 2) % 2; x < 16; x += 2) p.set(x, y, S.l);
    for (let i = 0; i < 10; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), S.d);
    return;
  }
  for (let y = 1; y < 16; y += 3) {
    p.hline(0, 15, y, S.l);
    for (let x = Math.floor(r() * 3); x < 16; x += 3) p.set(x, y + 1, S.d);
  }
  p.hline(0, 15, 0, S.hl);
  p.vline(0, 0, 15, S.d); p.vline(15, 0, 15, S.d);
  p.vline(7, 0, 15, '#6a4a20');
}
// 時の ふむ石（石の 板に 砂時計の しるし）・しずんだ ふむ石（光る）
function paintTimePlate(p, v, on) {
  p.rect(0, 0, 16, 16, '#6a6478');
  const r = prand(v * 13 + 7);
  for (let i = 0; i < 5; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), '#565064');
  p.rect(2, 2, 12, 12, on ? '#7a7058' : '#9a94aa');
  p.hline(2, 13, 2, on ? '#5a5040' : '#c4bed4'); p.vline(2, 2, 13, on ? '#5a5040' : '#c4bed4');
  p.hline(2, 13, 13, '#4a4458'); p.vline(13, 2, 13, '#4a4458');
  const c = on ? '#ffe680' : '#5a5470';
  for (let i = 0; i < 4; i++) { p.hline(5 + i, 10 - i, 4 + i, c); p.hline(5 + i, 10 - i, 11 - i, c); }
  if (on) { p.set(7, 7, '#ffffff'); p.set(8, 8, '#ffffff'); }
}

export const CH6_PAINTERS = {
  [T.SAND_DOOR]: (p, v) => paintSandDoor(p, v),
  [T.SAND_DOOR_OPEN]: (p, v, f) => paintSandDoorOpen(p, v, f),
  [T.SAND_DIAL]: (p, v, f) => paintDial(p, v, f, false),
  [T.SAND_DIAL_ON]: (p, v, f) => paintDial(p, v, f, true),
  [T.TIME_ALTAR]: (p, v, f) => paintTimeAltar(p, v, f),
  [T.TIME_ALTAR_EMPTY]: (p, v, f) => paintTimeAltar(p, v, f, true),
  [T.FROZEN_WATER]: (p, v, f, m) => paintFrozenWater(p, v, f, m),
  [T.STRAW_WALL]: (p, v, f, m) => paintStrawWall(p, v, f, m),
  [T.TIME_PLATE]: (p, v) => paintTimePlate(p, v, false),
  [T.TIME_PLATE_ON]: (p, v) => paintTimePlate(p, v, true),
  ...HM_PAINTERS,
  ...TK_PAINTERS,
  ...C7_PAINTERS,
};
export const CH6_FRAMES = { [T.SAND_DOOR_OPEN]: DOOR_FRAMES, [T.SAND_DIAL_ON]: DIAL_FRAMES, [T.TIME_ALTAR]: ALTAR_FRAMES, ...HM_FRAMES, ...TK_FRAMES, ...C7_FRAMES };
export const CH6_SPEED = { [T.SAND_DOOR_OPEN]: 160, [T.SAND_DIAL_ON]: 300, [T.TIME_ALTAR]: 220, ...HM_SPEED, ...TK_SPEED, ...C7_SPEED };
export const CH6_TILES = Object.keys(CH6_PAINTERS).map(Number);
// 色を かえない タイル（もとの 色で かいてある。render/themes.js）
export const CH6_KEEP_COLOR = CH6_TILES;

// ───── 2.5D（render/field3d.js・render/tex3d.js）─────
// 泉は 地面より 少し ひくい。とびらと わらの かべは かべ（とびらは 洞窟の かべと おなじ 高さ。わらの かべは 家の かべ）
export const CH6_FLOOR_H = { [T.FROZEN_WATER]: -0.28, [T.TIME_PLATE_ON]: -0.05, ...HM_FLOOR_H, ...TK_FLOOR_H, ...C7_FLOOR_H };
export function ch6BlockSpec(id, v) {
  if (id === T.SAND_DOOR) return { h: 1.6, top: ['x', 'cave_top', v], side: ['x', 'cave_side', v], south: ['t', T.SAND_DOOR, 0, 0] };
  if (id === T.STRAW_WALL) return { h: 1.25, top: ['t', T.STRAW_WALL, v, 1], side: ['t', T.STRAW_WALL, v, 0], south: ['t', T.STRAW_WALL, v, 0] };
  return hmBlockSpec(id, v) || tkBlockSpec(id, v) || c7BlockSpec(id, v);
}
// たてた もの（[はば, 高さ, かく 関数]）
const dialProp = (on) => [16, 22, (p) => {
  p.rect(3, 15, 10, 6, SD.b); p.hline(3, 12, 15, SD.hl); p.hline(3, 12, 20, SD.d); p.rect(4, 14, 8, 1, SD.l);
  hourglass(p, 5, 3, 9, on ? 0.6 : 0, on ? 0.4 : 1, on, 0);
  if (on) { p.set(2, 4, SAND.w); p.set(13, 7, SAND.w); }
}];
const altarProp = (empty) => [20, 26, (p) => {
  p.rect(1, 18, 18, 7, SD.b); p.hline(1, 18, 18, SD.hl); p.hline(1, 18, 24, SD.d);
  p.rect(3, 15, 14, 3, SD.m); p.hline(3, 16, 15, SD.l);
  if (empty) return;
  hourglass(p, 7, 2, 11, 0.5, 0.5);
  for (const [x, y] of [[10, 4], [10, 7], [10, 10], [4, 6], [16, 3]]) p.set(x, y, '#ffffff');
}];
export const CH6_PROPS = {
  [T.SAND_DIAL]: dialProp(false), [T.SAND_DIAL_ON]: dialProp(true),
  [T.TIME_ALTAR]: altarProp(false), [T.TIME_ALTAR_EMPTY]: altarProp(true),
  ...HM_PROPS,
  ...TK_PROPS,
  ...C7_PROPS,
};

// ───── 色（render/themes.js の THEMES に まぜる。明るさを たもって 色だけ かえる）─────
const hex = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
const G = (...stops) => stops.map(([q, h]) => [q, hex(h)]);
const theme = (floor, wall, gem, flame) => ({
  floor: G([0, floor[0]], [0.3, floor[1]], [0.6, floor[2]], [1, '#fff8ec']),
  wall: G([0, wall[0]], [0.3, wall[1]], [0.6, wall[2]], [1, '#f8f0e0']),
  water: G([0, '#0e1a22'], [0.5, '#4a7a98'], [1, '#e8f6ff']),
  gem: G([0, '#2a1a0a'], [0.5, gem], [1, '#ffffff']),
  flame,
});
export const CH6_THEMES = {
  // 千年前の フィールド: もとの 色に セピアを 3わり まぜる（mix）。草の 緑も 水の 青も のこる
  past: { ...theme(['#2a1c0c', '#8a6a3e', '#d8b886'], ['#1e140a', '#6a5030', '#b89868'], '#f0d090', null), mix: 0.3 },
  // 時のほこら: 砂色の 石（金の 光）
  toki_shrine: theme(['#2a1e0c', '#8a6a3a', '#d4b478'], ['#1a1206', '#5a4422', '#a88a56'], '#ffe08a', null),
  // 今の 時のいせき: こけむした 灰みどりの 古い 石
  toki_ruin: theme(['#141a12', '#4e5a46', '#9aa48a'], ['#0c120c', '#34402e', '#6a7a5e'], '#a8e0a0', null),
  // 千年前の 時の神殿: できたばかりの 白っぽい 石と 金
  toki_ruin_past: theme(['#2a2214', '#a08c64', '#e8dab4'], ['#1e180c', '#7a6a48', '#c8b88e'], '#ffe08a', null),
  // 第6章 Step 3・4: 星めぐりの古道（今・千年前）
  ...HM_THEMES,
  // 第6章 Step 5: 止まった時計塔
  ...TK_THEMES,
  // 第7章 Step 1・2: みどりの水の神殿（千年前）
  ...C7_THEMES,
};

js/client/render/tiles-duna.js:
// 第4章 Step 6 の タイル（16×16 ドット）: 砂の海（金色の 砂の 波が ゆっくり 東へ ながれる）・砂クジラの ねどこの 砂の うず
// render/tiles-ch4.js が まぜる。2.5D は render/field3d.js（砂の海は うごく 地面、うずは ねどこ ぜんたいで 1まいの え）
// (p, v, f, m) … Painter / ちがい（うずは ねどこの まん中からの ずれ）/ アニメの コマ / となりの ようす（岸）
import { T } from '../../shared/tiles.js';
import { makeCanvas, ctxOf, prand } from './pixel.js';

const SEA = {
  base: '#d4a050', deep: '#bc8640', trough: '#a8743a', crest: '#ecc272', foam: '#f8dc9c', glint: '#fff2cc',
  shore: '#e8c886', shoreL: '#f6e2aa',
};
export const SAND_SEA_FRAMES = 4;

// 砂の海: 2本の 波がしら（よこ 16ドットで つながる）。コマごとに 4ドット 東へ ながれる。となりが 陸の がわは 明るい 砂の ふち
// m … 1=北 2=東 4=南 8=西 が 陸
export function paintSandSea(p, v, f, m = 0) {
  p.rect(0, 0, 16, 16, SEA.base);
  const r = prand(v * 37 + 5);
  for (let i = 0; i < 8; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), i % 2 ? SEA.deep : SEA.crest);
  const shift = (f % SAND_SEA_FRAMES) * 4;
  for (const [y0, amp, ph] of [[4, 1.2, 0], [11, 1.4, 6]]) {
    for (let x = 0; x < 16; x++) {
      const u = (x + 16 - shift + ph) % 16;
      const y = y0 + Math.round(Math.sin((u / 16) * Math.PI * 2) * amp);
      p.set(x, y + 1, SEA.trough);
      p.set(x, y, SEA.crest);
      if (u < 3) p.set(x, y - 1, SEA.foam);
    }
  }
  if ((v & 3) === 0) p.set((5 + shift) & 15, 8, SEA.glint);
  if (m & 1) { p.hline(0, 15, 0, SEA.shoreL); p.hline(0, 15, 1, SEA.shore); }
  if (m & 4) p.hline(0, 15, 15, SEA.shore);
  if (m & 8) { p.vline(0, 0, 15, SEA.shoreL); p.vline(1, 0, 15, SEA.shore); }
  if (m & 2) p.vline(15, 0, 15, SEA.shore);
}

// ───── 砂の うず（砂クジラの ねどこ。c4_whale で しずまる）─────
const WHIRL = ['#5e3a1e', '#7a4e28', '#956434', '#b07a40', '#c8924c', '#dcaa5e', '#ecc272', '#f8dc9c'];
export const SAND_WHIRL_FRAMES = 8;
// うずの まん中からの ずれ（ドット）での 色。3本の うでが まわる。まん中ほど こい
function whirlColor(gx, gy, f) {
  const r = Math.hypot(gx, gy);
  const a = Math.atan2(gy, gx);
  const s = Math.sin(a * 3 - r * 0.3 + (f % SAND_WHIRL_FRAMES) * (Math.PI / 4));
  const k = Math.max(0, 1 - r / 40);
  const i = Math.round(4.6 + s * 2 - k * 4.2);
  return WHIRL[Math.max(0, Math.min(WHIRL.length - 1, i))];
}
// 2D: v … ねどこの まん中の マスからの ずれ（下4ビット x+8・上4ビット y+8。whirlVariant）
export function paintSandWhirl(p, v, f) {
  const dx = (v & 15) - 8, dy = ((v >> 4) & 15) - 8;
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) p.set(x, y, whirlColor(dx * 16 + x - 7.5, dy * 16 + y - 7.5, f));
}
// render/tiles.js の prepareMap: うずの マスの ちがい（map.whirl … ねどこの まん中の マス）
export function whirlVariant(t, map, x, y, v) {
  if (t !== T.SAND_WHIRL || !map?.whirl) return v;
  return ((x - map.whirl.x + 8) & 15) | (((y - map.whirl.y + 8) & 15) << 4);
}
// 2.5D: ねどこ ぜんたいの うず（n マス × n マス。まん中が ねどこの まん中の マス）
export function whirlCanvas(f, n = 5) {
  const S = n * 16;
  const c = makeCanvas(S, S);
  const x = ctxOf(c);
  for (let py = 0; py < S; py++) {
    for (let px = 0; px < S; px++) {
      x.fillStyle = whirlColor(px - S / 2 + 0.5, py - S / 2 + 0.5, f);
      x.fillRect(px, py, 1, 1);
    }
  }
  return c;
}

export const DUNA_PAINTERS = {
  [T.SAND_SEA]: paintSandSea,
  [T.SAND_WHIRL]: paintSandWhirl,
};
export const DUNA_FRAMES = { [T.SAND_SEA]: SAND_SEA_FRAMES, [T.SAND_WHIRL]: SAND_WHIRL_FRAMES };
export const DUNA_SPEED = { [T.SAND_SEA]: 360, [T.SAND_WHIRL]: 130 };

// 岸: となりが 砂の 海でも うずでも 砂嵐でも ない（陸・さんばし）がわ。1=北 2=東 4=南 8=西（あてはまらない タイルは -1）
const SEAISH = new Set([T.SAND_SEA, T.SAND_WHIRL, T.SANDSTORM]);
export function dunaMask(t, at, x, y) {
  if (t !== T.SAND_SEA) return -1;
  const land = (dx, dy) => { const n = at(x + dx, y + dy); return n !== -1 && !SEAISH.has(n); };
  return (land(0, -1) ? 1 : 0) | (land(1, 0) ? 2 : 0) | (land(0, 1) ? 4 : 0) | (land(-1, 0) ? 8 : 0);
}

js/client/render/tiles-earth.js:
// 第5章 Step 6・7「大地の神殿」と 根の島の タイル（16×16 ドット）と 神殿の 色（テーマ）
// ・根の 橋（太い 根が からみあった 橋）・根の すきまの ふかい 谷（くらやみに 根の ひげ。4コマで ちりが ゆれる）
// ・根の 水がめ（からっぽ／水を そそいだ〈2コマで 水面が ゆれる〉）・土の 守り手（南むき・東むきの 石の ゴーレム）
// ・守り手の 石板（金の しるし）・もとに もどす 石板（青い 回る 矢じるし）・ゆかの あな・あなを うめた ゴーレムの せなか
// ・根の とびら（4階）・こわれた 上り下りの ゆか・直った 上り下りの ゆか・大地の 守り星の 祭だん（3コマ）・神殿の 入口（根の とびら）
// render/tiles.js が まぜる。2.5D は render/field3d.js（EARTH_LIQUIDS・EARTH_FLOOR_H・earthBlockSpec）と render/tex3d.js（EARTH_PROPS）
// テーマ（earth_1 … 1〜2階 土の こげ茶〜 earth_4 … 7〜8階 大地の 心の あかね色）は render/themes.js
// (p, v, f, m) … Painter / ちがい / アニメの コマ / となりの ようす
import { T } from '../../shared/tiles.js';
import { prand } from './pixel.js';

// 根（こげ茶）・谷（くらやみ）・石（灰土色）・水（あおい）・金の 光
const RT = { d: '#3e2814', b: '#6a4626', m: '#8a5e34', l: '#a87a48', hl: '#c89a62' };
const GP = { b: '#0e0a06', m: '#1a120a', l: '#2a1c10', r: '#3a2814', dust: '#6a5038' };
const ST = { d: '#4e463c', b: '#7a7062', m: '#958a78', l: '#b4a890', ln: '#5e5648' };
const WA = { d: '#1e4a7a', b: '#3a78b8', l: '#7ab8e8', hl: '#d8f0ff' };
const GOLD = { g: '#e8c050', gl: '#fff0a0', gd: '#a8842a' };
const FL = { b: '#6a5e50', l: '#7e7262', d: '#544a3e', ln: '#463e34' };

function floorBase(p, v) {
  p.rect(0, 0, 16, 16, FL.b);
  const r = prand(v * 41 + 13);
  for (let i = 0; i < 7; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), i % 2 ? FL.d : FL.l);
  p.hline(0, 15, 0, FL.ln);
}

// 根の すきまの 谷（くらやみの 底に、細い 根の ひげ。ちりが ゆっくり ゆれる）
export const GAP_FRAMES = 4;
function paintRootGap(p, v, f) {
  p.rect(0, 0, 16, 16, GP.b);
  const r = prand(v * 29 + 3);
  for (let i = 0; i < 3; i++) {
    const x = Math.floor(r() * 16), y0 = Math.floor(r() * 6), len = 4 + Math.floor(r() * 7);
    for (let k = 0; k < len; k++) p.set((x + Math.floor(k / 4)) % 16, (y0 + k) % 16, k % 3 ? GP.m : GP.l);
  }
  const r2 = prand(v * 7 + 11);
  for (let i = 0; i < 3; i++) {
    const x = Math.floor(r2() * 16), y = (Math.floor(r2() * 16) + (f % GAP_FRAMES)) % 16;
    p.set(x, y, i === f % 3 ? GP.dust : GP.r);
  }
}
// 根の 橋（太い 根が 3本 からみあう。すきまから 谷が 見える）
function paintRootBridge(p, v) {
  p.rect(0, 0, 16, 16, GP.m);
  const r = prand(v * 17 + 5);
  for (const [y0, w] of [[1, 4], [6, 5], [12, 3]]) {
    const wave = Math.floor(r() * 3);
    for (let x = 0; x < 16; x++) {
      const y = y0 + ((x + wave) % 8 < 4 ? 0 : 1);
      for (let k = 0; k < w; k++) p.set(x, Math.min(15, y + k), k === 0 ? RT.hl : k === w - 1 ? RT.d : k === 1 ? RT.l : RT.m);
    }
  }
  // よこに からむ 細い 根
  for (const x of [3 + (v & 1), 10 + ((v >> 1) & 1)]) for (let y = 0; y < 16; y++) if (y % 5 !== 4) p.set(x, y, y % 2 ? RT.b : RT.m);
  for (let i = 0; i < 4; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), RT.d);
}
// 根の 水がめ（ゆかの 上に、口の 大きな 土の かめ）
export const JAR_FRAMES = 2;
function paintJar(p, v, f, on) {
  floorBase(p, v);
  p.ellipse(8, 14, 5.5, 1.6, FL.d);
  p.ellipse(8, 9.5, 5.5, 5, '#8a5a3a');
  p.ellipse(7, 8.5, 4, 3.5, '#a87048');
  p.rect(4, 3, 9, 3, '#7a4a2e');
  p.hline(4, 12, 3, '#b88050');
  p.ellipse(8, 4, 3.5, 1.2, on ? WA.b : '#2a1a10');
  if (on) {
    p.set(6 + (f % 2), 4, WA.hl); p.set(10 - (f % 2), 4, WA.l);
    for (const [x, y] of [[2, 2], [14, 6], [13, 1]]) p.set(x, y, f % 2 ? WA.hl : WA.l);
  }
  p.set(5, 10, '#6a4028'); p.set(11, 12, '#6a4028');
}
// 土の 守り手（石の ゴーレム。南むきは 正面、東むきは よこ。目が 金に 光る）
function paintGolem(p, v, dir) {
  floorBase(p, v);
  p.ellipse(8, 15, 6, 1.2, FL.ln);
  if (dir === 'S') {
    p.rect(3, 4, 10, 10, ST.b); p.rect(3, 4, 10, 1, ST.l); p.vline(3, 4, 13, ST.l); p.vline(12, 4, 13, ST.d);
    p.rect(5, 1, 6, 4, ST.m); p.hline(5, 10, 1, ST.l);
    p.set(6, 3, GOLD.gl); p.set(9, 3, GOLD.gl);
    p.rect(1, 6, 2, 6, ST.m); p.rect(13, 6, 2, 6, ST.d);
    p.rect(4, 14, 3, 1, ST.d); p.rect(9, 14, 3, 1, ST.d);
    p.hline(5, 10, 8, ST.ln); p.set(8, 10, '#5a8a3a'); p.set(6, 11, '#5a8a3a');
  } else {
    p.rect(3, 4, 9, 10, ST.b); p.rect(3, 4, 9, 1, ST.l); p.vline(3, 4, 13, ST.l); p.vline(11, 4, 13, ST.d);
    p.rect(7, 1, 6, 4, ST.m); p.hline(7, 12, 1, ST.l);
    p.set(11, 3, GOLD.gl); p.set(12, 3, GOLD.g);
    p.rect(10, 7, 4, 2, ST.m); p.set(14, 7, ST.l);
    p.rect(4, 14, 3, 1, ST.d); p.rect(8, 14, 3, 1, ST.d);
    p.set(5, 9, '#5a8a3a'); p.set(7, 11, '#5a8a3a');
  }
}
// 守り手の 石板（たてた 石の 板に 金の ゴーレムの しるし）・もとに もどす 石板（青い 回る 矢じるし）
function paintSlab(p, v, undo) {
  floorBase(p, v);
  p.ellipse(8, 14.5, 5, 1.2, FL.ln);
  p.rect(4, 2, 8, 12, ST.m); p.hline(4, 11, 2, ST.l); p.vline(4, 2, 13, ST.l); p.vline(11, 2, 13, ST.d); p.hline(4, 11, 13, ST.d);
  if (!undo) {
    const c = GOLD.g;
    p.rect(7, 4, 2, 2, c); p.rect(6, 6, 4, 4, c); p.set(5, 7, c); p.set(10, 7, c); p.rect(6, 10, 1, 2, c); p.rect(9, 10, 1, 2, c);
    p.set(7, 4, GOLD.gl);
  } else {
    const c = '#7ab8e8';
    for (const [x, y] of [[6, 4], [7, 4], [8, 4], [9, 5], [10, 6], [10, 7], [10, 8], [9, 9], [8, 10], [7, 10], [6, 9], [5, 8]]) p.set(x, y, c);
    p.set(5, 6, c); p.set(4, 7, c); p.set(6, 7, c); p.set(5, 7, '#d8f0ff');
  }
}
// ゆかの あな（ふかい 四角い あな）・あなを うめた ゴーレムの せなか（こけの 生えた 石。歩ける）
function paintPit(p, v) {
  floorBase(p, v);
  p.rect(2, 2, 12, 12, GP.l); p.rect(3, 3, 10, 10, GP.m); p.rect(4, 5, 8, 8, GP.b);
  p.hline(2, 13, 2, FL.d); p.hline(3, 12, 13, FL.l);
}
function paintFill(p, v) {
  floorBase(p, v);
  p.rect(2, 2, 12, 12, ST.b); p.hline(2, 13, 2, ST.l); p.vline(2, 2, 13, ST.l); p.vline(13, 2, 13, ST.d); p.hline(2, 13, 13, ST.d);
  p.hline(4, 11, 7, ST.ln); p.vline(8, 3, 12, ST.ln);
  const r = prand(v * 13 + 7);
  for (let i = 0; i < 6; i++) p.set(3 + Math.floor(r() * 10), 3 + Math.floor(r() * 10), i % 2 ? '#5a8a3a' : '#7aaa4a');
  p.set(5, 4, GOLD.gd); p.set(10, 4, GOLD.gd);
}
// 根の とびら（太い 根が あみの ように からみあった とびら）
function paintEarthDoor(p, v) {
  p.rect(0, 0, 16, 16, RT.d);
  for (let x = 1; x < 16; x += 4) for (let y = 0; y < 16; y++) p.set(x + ((y >> 2) & 1), y, y % 4 === 0 ? RT.hl : RT.m);
  for (let y = 2; y < 16; y += 5) for (let x = 0; x < 16; x++) p.set(x, y + ((x >> 2) & 1), x % 3 ? RT.l : RT.b);
  p.rect(6, 6, 4, 4, '#5a3a1e'); p.set(7, 7, GOLD.g); p.set(8, 8, GOLD.gd);
  p.hline(0, 15, 15, '#2a1a0a');
  void v;
}
// 上り下りの ゆか（こわれて かたむいた・直って 金の ふちが 光る）
function paintLift(p, v, ok) {
  floorBase(p, v);
  if (!ok) {
    p.rect(1, 1, 14, 14, GP.m);
    for (let y = 4; y < 14; y++) p.hline(3, 12 - Math.floor((y - 4) / 3), y, y % 3 ? '#6a4a2a' : '#4e3418');
    p.set(5, 6, GP.b); p.set(8, 9, GP.b); p.set(6, 11, GP.b);
    p.vline(2, 0, 3, '#7a7a7a'); p.vline(13, 0, 1, '#7a7a7a');
  } else {
    p.rect(1, 1, 14, 14, '#8a6a3a'); p.rect(2, 2, 12, 12, '#a88048');
    for (let y = 4; y < 14; y += 3) p.hline(2, 13, y, '#7a5a2a');
    p.hline(1, 14, 1, GOLD.g); p.hline(1, 14, 14, GOLD.gd); p.vline(1, 1, 14, GOLD.g); p.vline(14, 1, 14, GOLD.gd);
    p.set(2, 2, GOLD.gl); p.set(13, 2, GOLD.gl);
  }
}
// 大地の 守り星の 祭だん（石の 台の 上に、土色の 光の くぼみ）
export const ALTAR_FRAMES = 3;
function paintAltar(p, v, f) {
  floorBase(p, v);
  p.rect(1, 5, 14, 10, '#6a4a3a'); p.hline(1, 14, 5, '#9a6a4a'); p.hline(1, 14, 14, '#3a2418');
  p.rect(2, 3, 12, 3, '#8a5a40'); p.hline(2, 13, 3, '#b8805a');
  p.ellipse(8, 4, 3, 1.4, '#3a1a0a');
  const k = f % ALTAR_FRAMES;
  p.ellipse(8, 3.5, 2, 1, k === 1 ? '#ffb070' : '#e8905a');
  p.set(8, 2 - (k === 2 ? 1 : 0), '#fff0c0');
  for (const [x, y] of [[3, 9], [12, 9], [8, 11]]) p.set(x, y, '#d87a4a');
  p.set(4 + k * 3, 0, '#ffd8a0');
}
// 神殿の 入口（根の とびら。くらい 入口を 根が ふちどる。歩ける）
function paintRootGate(p) {
  p.rect(0, 0, 16, 16, '#2a1a0e');
  p.rect(2, 2, 12, 14, '#140c06');
  for (let y = 0; y < 16; y++) { p.set(1, y, y % 3 ? RT.m : RT.l); p.set(14, y, y % 3 ? RT.b : RT.m); }
  p.hline(1, 14, 0, RT.l); p.hline(2, 13, 1, RT.b);
  p.set(4, 6, '#3a2814'); p.set(11, 9, '#3a2814');
  p.hline(3, 12, 15, '#4a3a28');
}

export const EARTH_PAINTERS = {
  [T.ROOT_BRIDGE]: paintRootBridge, [T.ROOT_GAP]: paintRootGap,
  [T.WATER_JAR]: (p, v, f) => paintJar(p, v, f, false), [T.WATER_JAR_ON]: (p, v, f) => paintJar(p, v, f, true),
  [T.GOLEM_S]: (p, v) => paintGolem(p, v, 'S'), [T.GOLEM_E]: (p, v) => paintGolem(p, v, 'E'),
  [T.GOLEM_SLAB]: (p, v) => paintSlab(p, v, false), [T.UNDO_SLAB]: (p, v) => paintSlab(p, v, true),
  [T.EARTH_PIT]: paintPit, [T.GOLEM_FILL]: paintFill, [T.EARTH_DOOR]: paintEarthDoor,
  [T.LIFT_BROKEN]: (p, v) => paintLift(p, v, false), [T.EARTH_LIFT]: (p, v) => paintLift(p, v, true),
