export const EARTH_FRAMES = { [T.ROOT_GAP]: GAP_FRAMES, [T.WATER_JAR_ON]: JAR_FRAMES, [T.EARTH_ALTAR]: ALTAR_FRAMES };
export const EARTH_SPEED = { [T.ROOT_GAP]: 700, [T.WATER_JAR_ON]: 420, [T.EARTH_ALTAR]: 380 };
