const BR = { d: '#5a3e18', b: '#a07a30', l: '#d8b050', hl: '#f8e090' }; // 金の 真ちゅう
const FL = { b: '#6e5a46', l: '#86705a', d: '#56463a', ln: '#3e322a' }; // 塔の ゆか（くすんだ 茶色の 石）
