function floorBase(p, v, c = FL) {
  p.rect(0, 0, 16, 16, c.b);
  const r = prand(v * 43 + 7);
  for (let i = 0; i < 7; i++) p.set(Math.floor(r() * 16), Math.floor(r() * 16), i % 2 ? c.l : c.d);
  p.hline(0, 15, 0, c.ln);
