  [T.PILLAR]: (p, v) => {
    painters[T.CAVE_FLOOR](p, v);
    p.rect(4, 0, 8, 16, C.stoneD); p.rect(5, 0, 5, 16, C.stone); p.vline(6, 0, 15, C.stoneL);
