  [T.LOCKED_DOOR]: (p) => {
    p.rect(0, 0, 16, 16, '#3a3a48');
    p.rect(1, 0, 14, 16, '#5a5a6e');
    for (let x = 3; x < 14; x += 4) p.vline(x, 0, 15, '#44445a');
    p.hline(1, 14, 4, '#77778e'); p.hline(1, 14, 11, '#77778e');
    p.rect(6, 6, 4, 4, C.gold); p.set(7, 8, '#3a2a10'); p.set(8, 8, '#3a2a10');
  },
  [T.RUBBLE]: (p, v) => {
    painters[T.CAVE_FLOOR](p, v);
    p.ellipse(5, 10, 2.5, 2, C.caveL); p.ellipse(11, 6, 2, 1.6, C.caveL); p.set(9, 12, '#7a6a5a');
  },
  [T.BOSS_FLOOR]: (p, v) => {
    p.rect(0, 0, 16, 16, '#3c3048');
    p.hline(0, 15, 0, '#2c2238'); p.vline(0, 0, 15, '#2c2238');
    if ((v & 3) === 0) { p.set(7, 7, '#8a5ac8'); p.set(8, 8, '#8a5ac8'); p.set(7, 8, '#6a4aa0'); }
  },
  [T.CAVE_BRIDGE]: (p, v, f) => {
    painters[T.CAVE_WATER](p, v, f);
    p.rect(0, 1, 16, 14, '#7a5230');
    for (let x = 0; x < 16; x += 4) p.vline(x, 1, 14, '#5a3a1e');
  },
  [T.PIER]: (p, v, f) => {
    waterBase(p, f, v);
    p.rect(2, 0, 12, 16, C.wood);
    for (let y = 0; y < 16; y += 4) p.hline(2, 13, y, C.woodD);
    p.vline(2, 0, 15, C.woodL);
  },
  [T.WHIRLPOOL]: (p, v, f) => {
    // 嵐の うず（くらい 海に しろい うずまき）
    p.rect(0, 0, 16, 16, '#1a3470');
    const rot = f * 2.1 + v * 1.3;
    for (let i = 0; i < 28; i++) {
      const a = rot + i * 0.42, r = 0.8 + i * 0.25;
      p.set(Math.round(7.5 + Math.cos(a) * r), Math.round(7.5 + Math.sin(a) * r * 0.8), i % 3 === 0 ? '#ffffff' : '#8fb4f0');
    }
    p.rect(7, 7, 2, 2, '#0c1c44');
  },
  [T.RUBBLE_WALL]: (p, v) => {
    grassBase(p, v, 61);
    p.ellipse(5, 10, 5, 4.5, C.rockD); p.ellipse(11, 9, 5, 5, C.rock); p.ellipse(8, 5, 4, 3.5, C.rockL);
  },
};

// 第3章の タイル（雪・氷・ようがん・鉱山・神殿。render/tiles-ch3.js）
Object.assign(painters, CH3_PAINTERS);
// 第4章の タイル（砂ばく・砂丘・砂岩・ヤシ・サボテン・日干しれんが・砂嵐・古井戸・かれた地下水路。render/tiles-ch4.js・tiles-canal.js）
Object.assign(painters, CH4_PAINTERS);
// 第4章 Step 4（王家のピラミッド・オベリスク・歌の ボタン・流れる 砂 など。render/tiles-pyramid.js）
Object.assign(painters, PYRAMID_PAINTERS);
// 第5章「星の塔」（render/tiles-tower.js）
Object.assign(painters, TOWER_PAINTERS);
// 第5章 Step 3・4「クモイ地方」「しずみゆく島の古い神殿」（render/tiles-kumoi.js）
Object.assign(painters, KUMOI_PAINTERS);
// 第5章 Step 5「ノクトの思い出の迷宮」「星読みの里」（render/tiles-memory.js）
Object.assign(painters, MEMORY_PAINTERS);
// 第5章 Step 6・7「大地の神殿」と 根の島（render/tiles-earth.js）
Object.assign(painters, EARTH_PAINTERS);
// 第5章 Step 8「影の城」（render/tiles-castle.js）
Object.assign(painters, CASTLE_PAINTERS);
// 第5章 Step 9「星のない広間」（render/tiles-top.js）
Object.assign(painters, TOP_PAINTERS);
// 第6章 Step 1・2「時の砂時計」（render/tiles-ch6.js）
Object.assign(painters, CH6_PAINTERS);
// ピラミッドの 中の かがり火は 金色の 台（mask 4。tiles-ch4.js の ch4Mask）
for (const [id, lit] of [[T.BRAZIER, false], [T.BRAZIER_LIT, true]]) {
  const base = painters[id];
  painters[id] = (p, v, f, m) => (m & 4 ? paintPyrBrazier(p, v, f, lit) : base(p, v, f, m));
}
// ピラミッドの 中の レバーは 砂岩の 台（mask 4。地下水路の レバーは mask の CANAL_CTX で べつの え）
for (const [id, on] of [[T.LEVER, false], [T.LEVER_ON, true]]) {
  const base = painters[id];
  painters[id] = (p, v, f, m) => (m & 4 && !(m & CANAL_CTX) ? paintPyrLever(p, v, on) : base(p, v, f, m));
}
// 地下水路の まわりの たいまつ・レバー・かいだん・柱・がれき・ボスの ゆかは、水路の え で かく（mask の CANAL_CTX）
for (const [id, canal] of Object.entries(CANAL_CTX_PAINTERS)) {
  const base = painters[id];
  painters[id] = (p, v, f, m) => (m & CANAL_CTX ? canal(p, v, f, m) : base(p, v, f, m));
}

// アニメーションする タイルの コマ数
const FRAMES = {
  [T.WATER]: 3, [T.DEEP]: 3, [T.SWAMP]: 3, [T.FOUNTAIN]: 2, [T.FIREPLACE]: 2, [T.CAVE_WATER]: 3, [T.CRYSTAL]: 3,
  [T.TORCH]: 3, [T.LAMP]: 2, [T.STEPPING]: 3, [T.BRIDGE_H]: 3, [T.BRIDGE_V]: 3, [T.BROKEN_BRIDGE]: 3, [T.CAVE_BRIDGE]: 3, [T.PIER]: 3,
  [T.WHIRLPOOL]: 3,
  ...CH3_FRAMES, ...CH4_FRAMES, ...PYRAMID_FRAMES, ...TOWER_FRAMES, ...KUMOI_FRAMES, ...MEMORY_FRAMES, ...EARTH_FRAMES, ...CASTLE_FRAMES, ...TOP_FRAMES, ...CH6_FRAMES,
};
const SPEED = { [T.TORCH]: 140, [T.FIREPLACE]: 180, [T.CRYSTAL]: 500, [T.LAMP]: 700, ...CH3_SPEED, ...CH4_SPEED, ...PYRAMID_SPEED, ...TOWER_SPEED, ...KUMOI_SPEED, ...MEMORY_SPEED, ...EARTH_SPEED, ...CASTLE_SPEED, ...TOP_SPEED, ...CH6_SPEED };

export function frameOf(id, t) {
  const n = FRAMES[id];
  if (!n) return 0;
  return Math.floor(t / (SPEED[id] || 420)) % n;
}

// タイルの え を ペインターに かく（キャンバスに する まえ。テストでも つかう）
export function paintTile(id, variant = 0, frame = 0, mask = 0) {
  const p = new Painter(TS, TS);
  (painters[id] || painters[T.VOID])(p, variant, frame, mask);
  return p;
}
export const hasTileArt = (id) => !!painters[id];

const cache = new Map();
// theme … 宝の洞窟の しゅるい（'ice' 'lava' 'sand' 'canal'。色だけ かえる。render/themes.js）
// variant … 0〜255（地下水路は ばしょと 流れの むき）、frame … 0〜15、mask … 0〜255
export function tileCanvas(id, variant, frame, mask, theme) {
  const key = ((id * 256 + variant) * 16 + frame) * 256 + mask;
  let c = cache.get(key);
  if (!c) {
    c = paintTile(id, variant, frame, mask).toCanvas();
    cache.set(key, c);
  }
  return theme ? themedCanvas(c, theme, partOfTile(id, mask, theme)) : c;
}

const WATERY = new Set([T.WATER, T.DEEP, T.BROKEN_BRIDGE, T.STEPPING, T.PIER, T.BRIDGE_H, T.BRIDGE_V, T.WHIRLPOOL]);
const WALLS = new Set([T.WALL_STONE, T.WALL_WOOD, T.CAVE_WALL, T.TORCH, ...CH3_WALLS, ...CH4_WALLS, ...PYRAMID_WALLS, ...TOWER_WALLS, ...KUMOI_WALLS]);

// マップごとに いちど だけ けいさん（となりの タイルで かわる みため）
export function prepareMap(map) {
  if (map._render) return map._render;
  const { w, h, tiles } = map;
  const variant = new Uint8Array(w * h);
  const mask = new Uint8Array(w * h);
  const at = (x, y) => (x < 0 || y < 0 || x >= w || y >= h ? -1 : tiles[y * w + x]);
  // 第4章: とびら（砂嵐のかべ）は ひらいた あとの タイルで つながりを 見る（砂丘が かべの 下まで つづく）
  const opened = new Map();
  for (const g of map.gates || []) if (!g.invert) opened.set(g.y * w + g.x, g.open);
  const atOpen = (x, y) => (x < 0 || y < 0 || x >= w || y >= h ? -1 : opened.get(y * w + x) ?? tiles[y * w + x]);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      const t = tiles[i];
      variant[i] = Math.floor(hash2(x, y, 17) * 4);
      // 砂嵐は ばしょで もようを つなげる（4×4マスで ひとまわり）
      if (t === T.SANDSTORM) variant[i] = (x & 3) | ((y & 3) << 2);
      if (t === T.WATER || t === T.DEEP) {
        let m = 0;
        const land = (tt) => tt !== -1 && !WATERY.has(tt);
        if (land(at(x, y - 1))) m |= 1;
        if (land(at(x + 1, y))) m |= 2;
        if (land(at(x, y + 1))) m |= 4;
        if (land(at(x - 1, y))) m |= 8;
        mask[i] = m;
      } else if (WALLS.has(t)) {
        const below = at(x, y + 1);
        if (!WALLS.has(below)) mask[i] = 1;
        // 第4章: 地下水路の かべ（下が 水路・はしの かど）と 水路の かべの たいまつ
        mask[i] |= canalWallBits(t, at, x, y, map.kind !== 'dungeon');
        // 第5章「星の塔」: かべ画・星図の つづき（左右の となり。render/tiles-tower.js）
        const m5 = towerMask(t, at, x, y);
        if (m5 >= 0) mask[i] |= m5;
        variant[i] = towerVariant(t, at, x, y, variant[i]);
        // 第5章 しずみゆく島の 神殿: かべ画の つづき（render/tiles-kumoi.js）
        const mk = kumoiMask(t, at, x, y);
        if (mk >= 0) mask[i] |= mk;
        variant[i] = kumoiVariant(t, at, x, y, variant[i]);
      } else if (RAIL_TILES.has(t)) {
        // レールの つながり（北=1 東=2 南=4 西=8）
        let m = 0;
        if (RAIL_TILES.has(at(x, y - 1))) m |= 1;
        if (RAIL_TILES.has(at(x + 1, y))) m |= 2;
        if (RAIL_TILES.has(at(x, y + 1))) m |= 4;
        if (RAIL_TILES.has(at(x - 1, y))) m |= 8;
        mask[i] = m;
      } else {
        // 第4章（砂丘の つながり・砂岩の がけ・ヤシと サボテンの 下の 草地・地下水路の 岸）
        const m4 = ch4Mask(opened.get(i) ?? t, atOpen, x, y, map);
        if (m4 >= 0) mask[i] = m4 | canalBaseBits(t, at, x, y);
        // 地下水路: 水路の 中は ばしょと 流れの むき・通路は かべの かげ（とびらで 底 ⇔ 水 ⇔ せき が かわっても おなじ）
        variant[i] = canalVariant(t, at, x, y, variant[i]);
        // 砂クジラの ねどこの 砂の うず: ねどこの まん中からの ずれ（render/tiles-duna.js）
        variant[i] = whirlVariant(t, map, x, y, variant[i]);
        // 砂の底の神殿の 水鏡: 水鏡の 左上からの ずれ（render/tiles-temple.js）
        variant[i] = templeVariant(t, map, x, y, variant[i]);
      }
    }
  }
  map._render = { variant, mask };
  return map._render;
}

export function isAnimated(id) {
  return !!FRAMES[id];
}

export { TILE_INFO };

js/client/render/treasure-glow.js:
// 宝の地図の 場所の 光（まだ ほっていない 場所）
//   ひろえる きらきら（白と うすい 黄色の 十字）と まちがえない ように、赤むらさきの 光の 柱・地面の わ・のぼる 火の粉（赤むらさきと 金）
//   x, y … 地面の 点（がめんの 座標）/ t … 時間（ミリびょう）/ k … 大きさ（1マス 16ドットの とき 1）
export const GLOW_MAIN = '#ff3d96';
export const GLOW_SUB = '#ffd23a';

function diamond(ctx, x, y, s) {
  ctx.beginPath();
  ctx.moveTo(x, y - s);
  ctx.lineTo(x + s * 0.7, y);
  ctx.lineTo(x, y + s);
  ctx.lineTo(x - s * 0.7, y);
  ctx.closePath();
  ctx.fill();
}

export function drawTreasureGlow(ctx, x, y, t, k = 1) {
  const pulse = 0.5 + 0.5 * Math.sin(t / 260);
  const H = 54 * k, W = 8 * k;
  ctx.save();
  // 光の 柱（下が こく、上へ 消える）
  const g = ctx.createLinearGradient(0, y, 0, y - H);
  g.addColorStop(0, `rgba(255, 61, 150, ${0.5 + 0.25 * pulse})`);
  g.addColorStop(0.6, `rgba(255, 61, 150, ${0.18 + 0.1 * pulse})`);
  g.addColorStop(1, 'rgba(255, 61, 150, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(x - W / 2, y - H, W, H);
  // まん中の しろっぽい すじ
  const g2 = ctx.createLinearGradient(0, y, 0, y - H * 0.85);
  g2.addColorStop(0, `rgba(255, 225, 240, ${0.55 + 0.3 * pulse})`);
  g2.addColorStop(1, 'rgba(255, 225, 240, 0)');
  ctx.fillStyle = g2;
  ctx.fillRect(x - 1.2 * k, y - H * 0.85, 2.4 * k, H * 0.85);
  // 地面の わ（ふくらんだり ちぢんだり）
  ctx.strokeStyle = `rgba(255, 61, 150, ${0.65 + 0.3 * pulse})`;
  ctx.lineWidth = Math.max(1, 1.6 * k);
  const r = (6.5 + 3 * pulse) * k;
  ctx.beginPath();
  ctx.ellipse(x, y, r, r * 0.45, 0, 0, Math.PI * 2);
  ctx.stroke();
  ctx.strokeStyle = `rgba(255, 210, 58, ${0.35 + 0.35 * (1 - pulse)})`;
  ctx.lineWidth = Math.max(1, k);
  ctx.beginPath();
  ctx.ellipse(x, y, r * 0.55, r * 0.25, 0, 0, Math.PI * 2);
  ctx.stroke();
  // のぼる 火の粉（ひし形）
  for (let i = 0; i < 5; i++) {
    const ph = (t / 1100 + i / 5) % 1;
    const sx = x + Math.sin(i * 2.3 + t / 420) * 5 * k;
    const sy = y - 4 * k - ph * H * 0.9;
    ctx.globalAlpha = Math.max(0, 1 - ph);
    ctx.fillStyle = i % 2 ? GLOW_SUB : GLOW_MAIN;
    diamond(ctx, sx, sy, (2.6 - ph * 1.4) * k);
  }
  ctx.restore();
}

