    const flap = f === 1 ? 1 : 0;
    if (view === 'side') {
      if (layer === 'back') { poly(p, [[cx + 2, g - 1], [cx + 18, g - 6 - flap], [cx + 19, g - 4 - flap], [cx + 3, g + 1]], page); return; }
      poly(p, [[cx - 18, g - 4 - flap], [cx, g], [cx, g + 3], [cx - 19, g - 1 - flap]], cover);
