const MOVE_OF_CAT = { sword: 'sword', dagger: 'dagger', axe: 'axe', spear: 'spear', claw: 'claw', none: 'fist', whip: 'whip', fan: 'fan', staff: 'staff', bat: 'bat', boomerang: 'boomerang' };

