  r33_poof: (a, T) => { poof(a, T, 0); twinkle(T, 0.18, 1319); },
  // まくが おりる ドロロロ… → ジャーン！
  r33_curtain: (a, T) => {
    for (let i = 0; i < 8; i++) T(110 + (i % 2) * 8, 0.05, { vol: 0.1, delay: i * 0.05, type: 'triangle' });
