  },
  // 宝箱が ギィ…パカッ → キラーン
  sg_chest: (a, T) => {
    T(150, 0.2, { vol: 0.07, type: 'saw', slide: 260 });
    a.noise(0.08, { vol: 0.22, delay: 0.2, from: 2400, to: 600 });
