  // わな（ビョン → ガッ）
  sg_trap: (a, T) => {
    T(300, 0.18, { vol: 0.1, type: 'square', slide: 900 });
    a.noise(0.16, { vol: 0.35, delay: 0.12, from: 1500, to: 150 });
    T(140, 0.18, { vol: 0.14, delay: 0.12, type: 'triangle', slide: 60 });
  },
  // ワープ（フィユーン）
  sg_warp: (a, T) => {
    T(300, 0.45, { vol: 0.07, type: 'sine', slide: 1800 });
    T(310, 0.45, { vol: 0.05, delay: 0.03, type: 'triangle', slide: 1900 });
    a.noise(0.4, { vol: 0.12, type: 'bandpass', from: 600, to: 4000, q: 3 });
  },
  // 星（キラキラ〜ン）
  sg_star: (a, T) => {
    [1568, 2093, 2637, 3136, 4186].forEach((f, i) => T(f, 0.22, { vol: 0.045, delay: i * 0.05, type: 'sine' }));
  },
  // 戦いの マス（ジャーン）
  sg_battle: (a, T) => {
    a.noise(0.35, { vol: 0.35, from: 3000, to: 200 });
    [220, 277, 330].forEach((f) => T(f, 0.4, { vol: 0.06, type: 'saw' }));
    T(110, 0.4, { vol: 0.12, type: 'triangle' });
  },
  // ボーナスチャンス（タラララ〜ン！）
  sg_bonus: (a, T) => {
    [523, 659, 784, 1047, 1319, 1568].forEach((f, i) => T(f, 0.12, { vol: 0.07, delay: i * 0.05, type: 'pulse' }));
    T(2093, 0.4, { vol: 0.05, delay: 0.32, type: 'triangle' });
    T(1568, 0.4, { vol: 0.04, delay: 0.32, type: 'triangle' });
  },
  // ルーレットの カチッ（arg … 高さ）
  sg_tick: (a, T, n = 0) => {
    T(1800 + (n % 2) * 200, 0.025, { vol: 0.06, type: 'square' });
  },
  // ルーレットが 止まる（ピンポーン）
  sg_wheel_stop: (a, T) => {
    T(1175, 0.18, { vol: 0.08, type: 'triangle' });
    T(1568, 0.3, { vol: 0.08, delay: 0.14, type: 'triangle' });
  },
  // 魔物の おみやげ（ぷるん♪）
  sg_gift: (a, T) => {
    T(700, 0.1, { vol: 0.08, type: 'sine', slide: 1100 });
    T(1047, 0.12, { vol: 0.06, delay: 0.12, type: 'triangle' });
    T(1319, 0.2, { vol: 0.06, delay: 0.2, type: 'triangle' });
  },
  // 家族の 応援（わーい！）
  sg_cheer: (a, T) => {
    [659, 784, 1047, 784, 1047, 1319].forEach((f, i) => T(f, 0.1, { vol: 0.06, delay: i * 0.07, type: 'pulse' }));
    a.noise(0.3, { vol: 0.08, delay: 0.1, type: 'bandpass', from: 1500, to: 2500, q: 1 });
  },
  // 落とし穴（ヒュ〜〜 ドスン）
  sg_fall: (a, T) => {
    T(1400, 0.6, { vol: 0.08, type: 'sine', slide: 200 });
    a.noise(0.25, { vol: 0.4, delay: 0.6, from: 900, to: 80 });
    T(90, 0.25, { vol: 0.15, delay: 0.6, type: 'triangle', slide: 45 });
  },
  // はしご（トントントン↑）
  sg_ladder: (a, T) => {
    [392, 440, 494, 523, 587, 659].forEach((f, i) => T(f, 0.06, { vol: 0.06, delay: i * 0.08, type: 'triangle' }));
  },
  // すごろく商人（チリンチリン）
  sg_merchant: (a, T) => {
    [0, 0.14].forEach((d) => { T(2093, 0.12, { vol: 0.05, delay: d, type: 'triangle' }); T(2637, 0.16, { vol: 0.04, delay: d + 0.03, type: 'sine' }); });
  },
  // ゴールの ファンファーレ（パッパカパーン）
  sg_fanfare: (a, T) => {
    const N = [[523, 0, 0.12], [523, 0.13, 0.08], [523, 0.22, 0.08], [659, 0.32, 0.12], [784, 0.46, 0.12], [659, 0.6, 0.1], [784, 0.72, 0.1], [1047, 0.84, 0.5]];
    for (const [f, d, l] of N) {
      T(f, l, { vol: 0.08, delay: d, type: 'pulse' });
      T(f / 2, l, { vol: 0.05, delay: d, type: 'triangle' });
    }
    T(1319, 0.5, { vol: 0.05, delay: 0.84, type: 'pulse' });
  },
  // 花火（ヒュ〜 パーン パチパチ）
  sg_firework: (a, T) => {
    T(600, 0.3, { vol: 0.03, type: 'sine', slide: 1600 });
    a.noise(0.35, { vol: 0.32, delay: 0.3, from: 2500, to: 120 });
    for (let i = 0; i < 4; i++) a.noise(0.04, { vol: 0.08, delay: 0.42 + i * 0.07, type: 'highpass', from: 5000, to: 4000 });
  },
  // 景品が 1つ 出る（シャラン）
  sg_reveal: (a, T) => {
    [1319, 1760, 2349].forEach((f, i) => T(f, 0.2, { vol: 0.05, delay: i * 0.04, type: 'sine' }));
  },
};

export function sgSound(audio, id, arg = 0) {
  if (!audio?.ctx || !SG[id]) return false;
  try {
    SG[id](audio, (...x) => audio.tone(...x), arg);
  } catch { /* 音が 出なくても すごろくは つづける */ }
  return true;
}
export const SG_SOUNDS = Object.keys(SG);

js/client/sky.js:
// 空の 旅と 昼・夜の 時計（クライアント）
// ・時計: サーバーの 時こく（game.timeOffset）＋ パーティーの 時計の ずれ（party.clockShift）。宿屋の だいほんの とちゅうは
//   えんしゅつ（['clock', ずれ]）まで 前の 空の まま
// ・大鳥フウラ: サーバー（shared/world/travel.js）が きめた flying を うけて、とぶ・おりる えんしゅつと え を かく
import { el, toast, ListMenu } from './ui/dom.js';
import { dayFrac, isNightFrac, darkness } from '../shared/world/clock.js';
import { SKY_MAPS, FLUTE_ID, RIDE_ASK_MS, edgeAt, regionsFrom, skyBox, clampSkyBox, mountOf, VEIL, veilShown } from '../shared/data/sky.js';
import { birdCanvas, birdRideCanvas, BIRD_W, BIRD_H, RIDE_TOP } from './render/sky-art.js';
import { dragonCanvas, dragonRideCanvas } from './render/dragon-art.js';
import { starDragonCanvas, starDragonRideCanvas } from './render/ch5-dragon.js';
import { playerSprite } from './field.js';
import { equipKey } from './render/chars.js';

export const FLY_SPEED = 1.9; // 歩く はやさの この ばい
const CRUISE = 1.45; // とんでいる たかさ（マス）
const HIGH = 7; // 空の たかい ところ（よぶ・かえる えんしゅつ）
const BIG = 1.3; // 大鳥は 大きく かく
const ACTOR_LIFT = 1.1; // イベントの 大鳥の たかさ
const TS = 16;
const ease = (t) => 1 - (1 - t) * (1 - t);

// のりもの の え（大鳥フウラ・星の竜アステル）
// only … のりもの だけの え、ride … 人を のせた え、flap … はばたきの はやさ（ミリびょう）
// big … 大きさ、shadow … 2D の かげの はば、anchor・anchorOnly・shadowScale … 2.5D の たてた え
const MOUNTS = {
  bird: { only: birdCanvas, ride: birdRideCanvas, flap: 170, big: BIG, shadow: 13, anchor: 14, anchorOnly: 16, shadowScale: 2.4 },
  dragon: { only: dragonCanvas, ride: dragonRideCanvas, flap: 240, big: 1.15, shadow: 17, anchor: 17, anchorOnly: 19, shadowScale: 3 },
  // 第5章: 星の羽を えた 竜（c5_wings。render/ch5-dragon.js）
  star_dragon: { only: starDragonCanvas, ride: starDragonRideCanvas, flap: 240, big: 1.15, shadow: 17, anchor: 17, anchorOnly: 19, shadowScale: 3 },
};
// イベントの 役者（'sky_bird' … 大鳥、'sky_dragon' … 星の竜、'star_dragon' … 星の羽の 竜）
const ACTOR_MOUNT = { sky_bird: 'bird', sky_dragon: 'dragon', star_dragon: 'star_dragon' };
// 「別の地方へ」の 行き先の 名前（第5章の「雲の上」もふくむ）
const regionName = (id) => (id === VEIL.id ? VEIL.name : SKY_MAPS[id].name);
const regionShort = (id) => (id === VEIL.id ? VEIL.short : SKY_MAPS[id].short);

export class SkyClient {
  constructor(game) {
    this.game = game;
    this.flying = false;
    this.anim = null;
    this.shift = 0; // 見せている 時計の ずれ
    this.partyShift = 0;
    this.edgeT = 0;
    this.edgeCool = 0;
    this.sentAt = 0;
    this.btn = el('button', { class: 'win hud-btn hud-sky', text: '大鳥', onclick: () => this.onButton() });
    this.btn2 = el('button', { class: 'win hud-btn hud-sky2', text: '別の地方へ', onclick: () => this.regionButton() });
    this.btn.hidden = true;
    this.btn2.hidden = true;
    game.hud.btns.append(this.btn, this.btn2);
  }

  // ───────────── 時計 ─────────────
  now() { return Date.now() + (this.game.timeOffset || 0); }
  frac() { return dayFrac(this.now(), this.shift); }
  isNight() { return isNightFrac(this.frac()); }
  darkness() { return darkness(this.frac()); }

  onParty(p) {
    this.partyShift = Number(p?.clockShift) || 0;
    // だいほんの とちゅう（宿屋で ねている あいだ）は えんしゅつまで まつ
    if (!this.game.busy) this.shift = this.partyShift;
  }

  // だいほんの ['clock', ずれ]（宿屋: くらく なっている あいだに 時間を かえる）
  scriptClock(shift) {
    this.shift = Number(shift) || 0;
    this.partyShift = this.shift;
  }

  scriptEnd() { this.shift = this.partyShift; }

  // 夜明けのすず・夕焼けのすず
  onClock(m) {
    this.partyShift = Number(m.shift) || 0;
    this.shift = this.partyShift;
    this.game.flash?.();
  }

  // ───────────── 大鳥 ─────────────
  get hasFlute() { return !!this.game.me?.keyItems?.includes(FLUTE_ID); }

  // 入った・つなぎなおした
  onEnter(m) {
    this.flying = !!m.fly;
    this.anim = null;
    this.onParty(m.party);
    this.shift = this.partyShift;
  }

  // サーバーが いちを きめた（ワープ・イベント・べつの 地方へ）
  setFlying(on) {
    this.flying = !!on;
    if (!on && this.anim?.kind === 'call') this.anim = null;
  }

  onFly(m) {
    if (m.refuse) {
      this.game.audio.sfx('buzz');
      return;
    }
    this.flying = !!m.on;
    const me = this.game.field.me;
    if (m.anim && !m.ride) {
      this.anim = { kind: m.anim, t: 0, dur: m.anim === 'call' ? 1300 : 1100, x: me.x, y: me.y, dir: me.dir };
      this.game.audio.sfx(m.anim === 'call' ? 'sparkle' : 'stairs');
    }
    const mount = this.mount();
    if (m.anim === 'call' && !m.ride) toast(`風の笛をふいた！\n${mount.title}${mount.name}が空からおりてきた！`);
    else if (m.on && m.ride) {
      // リーダーの のりものに 乗った: リーダーに ついていく（いっしょに とんで、いっしょに おりる）
      this.game.follow = true;
      this.game.field.leaderCrumbs = [];
      toast(`リーダーといっしょに、${mount.title}${mount.name}に乗った！`);
    }
  }

  // ───────────── リーダーが 大鳥に 乗った:「いっしょに 乗る？」 ─────────────
  // サーバー（world/travel.js の askRiders）から。たたかい・メニューの あいだは まって、あとで きく
  onAsk(m) {
    this.closeAsk();
    this.ask = { ...m, at: performance.now() };
  }

  onAskEnd(m) {
    if (!this.ask || (m.id && this.ask.id !== m.id)) return;
    this.closeAsk();
    this.ask = null;
  }

  closeAsk() {
    if (!this.askBox) return;
    this.askBox.menu.blur();
    this.askBox.box.remove();
    this.askBox = null;
    this.game.menuOpen = false;
  }

  showAsk() {
    const g = this.game;
    const a = this.ask;
    const box = el('div', { class: 'win choice sky-choice sky-ask' },
      el('div', { class: 'q', text: `${a.name}が${a.title}${a.mount}に乗った！\nいっしょに乗る？` }));
    const finish = (yes) => {
      if (!this.askBox) return;
      this.closeAsk();
      this.ask = null;
      g.audio.sfx('confirm');
      g.net.send({ t: 'fly', action: 'ride', id: a.id, yes: !!yes });
      if (!yes) {
        // 乗らない: 地上に のこる（空の リーダーを 追いかけない）
        if (g.follow) g.follow = false;
        toast('地上にのこった。');
      }
    };
    const menu = new ListMenu(g.input, {
      items: [{ label: 'いっしょに乗る', value: true }, { label: '乗らない', value: false }],
      sound: (x) => g.audio.sfx(x),
      back: null,
      onSelect: (it) => finish(it.value),
      onCancel: () => finish(false),
    });
    box.append(menu.root);
    document.getElementById('ui').append(box);
    this.askBox = { box, menu };
    g.menuOpen = true;
    g.audio.sfx('sparkle');
    menu.focus();
  }

  // まっている「いっしょに 乗る？」を 出す（フィールドで ほかの まどが ない とき）
  updateAsk() {
    const g = this.game;
    if (!this.ask || this.askBox) return;
    if (performance.now() - this.ask.at > RIDE_ASK_MS) {
      this.ask = null;
      return;
    }
    if (g.state !== 'field' || g.busy || g.menuOpen || document.querySelector('.sky-choice, .choice')) return;
    this.showAsk();
  }

  send(action, extra = {}) {
    const t = performance.now();
    if (t - this.sentAt < 350) return;
    this.sentAt = t;
    this.game.net.send({ t: 'fly', action, ...extra });
  }

  call() {
    if (this.flying || this.anim) return;
    this.send('call');
  }

  land() {
    if (!this.flying || this.anim) return;
    this.send('land');
  }

  region(edge, to = null) {
    if (!this.flying || this.anim) return;
    this.game.audio.sfx('confirm');
    this.send('region', { edge: !!edge, ...(to ? { to } : {}) });
  }

  // 世界の フラグ（さそわれて 手伝っている ときは リーダーの 世界）
  hasFlag(f) { return this.game.field.hasFlag(f); }

  // のりもの（大鳥フウラ・星の竜アステル）
  mount() {
    return mountOf({ c3_dragon: this.hasFlag('c3_dragon') });
  }

  // 行ける 地方（第5章: 星の羽の 竜なら「雲の上」も。data/sky.js の VEIL）
  regions() {
    const has = (f) => this.hasFlag(f);
    const list = regionsFrom(this.game.field.mapId, has);
    // 雲の上の 地方（クモイ地方。aboveVeil）では「雲の上」は 出さない
    return veilShown(has) && !SKY_MAPS[this.game.field.mapId]?.aboveVeil ? [...list, VEIL.id] : list;
  }

  // 「別の地方へ」ボタン: 行き先が 2つ 以上なら えらぶ
  regionButton() {
    const g = this.game;
    if (!this.flying || this.anim || g.busy || g.menuOpen || document.querySelector('.sky-choice')) return;
    const list = this.regions();
    if (list.length <= 1) return this.region(false, list[0]);
    g.audio.sfx('confirm');
    const box = el('div', { class: 'win choice sky-choice' }, el('div', { class: 'q', text: 'どの地方へ飛ぶ？' }));
    const menu = new ListMenu(g.input, {
      items: [...list.map((id) => ({ label: regionName(id), value: id })), { label: 'やめる', value: null }],
      sound: (x) => g.audio.sfx(x),
      back: null,
      onSelect: (it) => finish(it.value),
      onCancel: () => finish(null),
    });
    box.append(menu.root);
    document.getElementById('ui').append(box);
    g.menuOpen = true;
    menu.focus();
    const finish = (v) => {
      menu.blur();
      box.remove();
      g.menuOpen = false;
      if (v) this.region(false, v);
    };
  }

  onButton() {
    const g = this.game;
    if (g.state !== 'field' || g.busy || g.menuOpen) return;
    if (this.flying) this.land();
    else this.call();
  }

  // フィールドの ボタン（F キー）
  toggle() { this.onButton(); }

  // 第35回: ゲームパッドの L（キーボードの G）。地上では 呼ぶ、空の 上では「別の地方へ」（行き先が なければ 降りる）
  padButton() {
    if (!this.btn.hidden || this.flying) {
      if (this.flying && !this.btn2.hidden) return this.regionButton();
      return this.onButton();
    }
  }

  // えんしゅつ中は うごけない
  blocksMove() {
    const a = this.anim;
    return !!a && ((a.kind === 'call' && a.t < 1000) || (a.kind === 'land' && a.t < 520));
  }

  // なかまの 大鳥に いっしょに のっている（じぶんの すがたは 出さない）
  ridingAlong() {
    const g = this.game;
    if (!this.flying || !g.follow) return false;
    const leader = g.field.leaderPos();
    return !!(leader && leader.air && Math.hypot(leader.x - g.field.me.x, leader.y - g.field.me.y) < 3);
  }

  update(dt) {
    const g = this.game;
    const f = g.field;
    if (this.anim) {
      this.anim.t += dt;
      if (this.anim.t >= this.anim.dur) this.anim = null;
    }
    this.edgeCool = Math.max(0, this.edgeCool - dt);
    this.updateAsk();
    const region = SKY_MAPS[f.mapId];
    const show = g.state === 'field' && !!region && (this.flying || this.hasFlute);
    this.btn.hidden = !show;
    if (show) {
      const label = this.flying ? '降りる' : this.mount().btn;
      if (this.btn.textContent !== label) this.btn.textContent = label;
    }
    const list = show && this.flying ? this.regions() : [];
    this.btn2.hidden = !list.length;
    if (!this.btn2.hidden) {
      const label = list.length > 1 ? '別の地方へ' : `${regionShort(list[0])}へ`;
      if (this.btn2.textContent !== label) this.btn2.textContent = label;
    }
  }

  // とんでいる ときの 1歩（マップの はし まで。はしを こえようと すると となりの 地方へ）
  flyStep(me, nx, ny, iy, dt) {
    const m = this.game.field.map;
    let x = Math.max(0.3, Math.min(m.w - 0.3, nx));
    let y = Math.max(0.6, Math.min(m.h - 0.2, ny));
    // ふぶきの 地方は とべる 場所の 中だけ（data/sky.js の box）
    const box = skyBox(m.id, (f) => this.hasFlag(f));
    if (box) ({ x, y } = clampSkyBox(box, x, y));
    const moved = Math.abs(x - me.x) > 1e-4 || Math.abs(y - me.y) > 1e-4;
    me.x = x;
    me.y = y;
    const e = edgeAt(m.id, me.y, m.h);
    // 行けない 地方の はしでも おくる（サーバーが「ふぶきで 進めない」と 知らせる）
    const pushing = e && (e === 'south' ? iy > 0.5 : iy < -0.5);
    this.edgeT = pushing ? this.edgeT + dt : 0;
    if (this.edgeT > 380 && !this.edgeCool) {
      this.edgeT = 0;
      this.edgeCool = 2500;
      this.region(true);
    }
    return moved;
  }

  // ───────────── え ─────────────
  lift(time) { return CRUISE + Math.sin(time / 320) * 0.08; }

  riderCanvas(look, job, dir, frame, eq, mount = 'bird') {
    const rider = playerSprite(look, job, dir, frame, eq);
    return MOUNTS[mount].ride(`${JSON.stringify(look)}:${job}:${equipKey(eq, job)}`, rider, dir, frame);
  }

  // のりもの（星の竜に のせて もらった 人 … フラグ c3_dragon … は 竜。ほかは 大鳥フウラ）
  // じぶん は キャラの フラグ。ほかの 人 は サーバーの いちの じょうほう（mt）
  mountOf(o, mine) {
    if (mine) {
      const fl = this.game.me?.flags;
      return fl?.c3_dragon ? (fl.c5_wings ? 'star_dragon' : 'dragon') : 'bird';
    }
    return o?.mt === 'dragon' || o?.mt === 'star_dragon' ? o.mt : 'bird';
  }

  // いま どう かくか（mine … じぶん）。null なら ふつうに 歩く すがた
  //  { mounted: true, lift } … のっている / { bird: { x, y, lift, alpha } } … 鳥だけ（そばに いる）
  pose(o, mine, time) {
    if (!mine) return o.air ? { mounted: true, lift: this.lift(time + (o.x * 97 % 500)), hide: !!o.ride } : null;
    if (this.ridingAlong()) return { hide: true };
    const a = this.anim;
    if (a?.kind === 'call') {
      if (a.t < 700) {
        const k = ease(a.t / 700);
        return { walk: true, bird: { x: o.x + 1.3, y: o.y + 0.1, lift: HIGH + (0.25 - HIGH) * k, dir: 'left' } };
      }
      return { mounted: true, lift: 0.25 + (this.lift(time) - 0.25) * ease(Math.min(1, (a.t - 700) / 500)) };
    }
    if (a?.kind === 'land') {
      if (a.t < 500) return { mounted: true, lift: this.lift(time) + (0.2 - this.lift(time)) * ease(a.t / 500) };
      const k = (a.t - 500) / 600;
      return { walk: true, bird: { x: a.x + 0.6 + k * 5, y: a.y - k * 2, lift: 0.2 + (HIGH - 0.2) * k * k, dir: 'right', alpha: 1 - Math.max(0, k - 0.7) / 0.3 } };
    }
    return this.flying ? { mounted: true, lift: this.lift(time) } : null;
  }

  // 2D: 人を かく かわりに 鳥を かく（かいたら true。walk の ときは 人は ふつうに かく）
  draw2D(field, o, camX, camY, look, job, mine, eq) {
    const ps = this.pose(o, mine, field.time);
    if (!ps) return false;
    if (ps.hide) return true;
    const mount = this.mountOf(o, mine), M = MOUNTS[mount];
    const frame = Math.floor(field.time / M.flap) % 2;
    const ctx = field.ctx;
    const shadow = (x, y, lift) => {
      const k = Math.max(0.35, 1 - lift / 12);
      ctx.fillStyle = `rgba(0,0,0,${0.3 * k})`;
      ctx.beginPath();
      ctx.ellipse(Math.round(x * TS - camX), Math.round(y * TS - camY - 1), M.shadow * k, 4 * k, 0, 0, Math.PI * 2);
      ctx.fill();
    };
    const put = (c, x, y, lift, alpha = 1) => {
      const r = c.res || 1;
      const w = (c.width / r) * M.big, h = (c.height / r) * M.big;
      const px = Math.round(x * TS - w / 2 - camX);
      const py = Math.round((y - lift) * TS - h + 8 - camY);
      if (alpha < 1) ctx.globalAlpha = Math.max(0, alpha);
      field.drawFine(c, px, py, w, h);
      ctx.globalAlpha = 1;
    };
    if (ps.bird) {
      shadow(ps.bird.x, ps.bird.y, ps.bird.lift);
      if (ps.walk) field.drawPlayerOnFoot(o, camX, camY, look, job, mine, eq);
      put(M.only(ps.bird.dir, frame), ps.bird.x, ps.bird.y, ps.bird.lift, ps.bird.alpha ?? 1);
      return true;
    }
    shadow(o.x, o.y, ps.lift);
    put(this.riderCanvas(look, job, o.dir || 'down', frame, eq, mount), o.x, o.y, ps.lift);
    return true;
  }

  // 2.5D: 人の かわりの たてた え（out に 入れる）。入れたら true
  entity3d(field, o, mine, out, look, job, eq) {
    const ps = this.pose(o, mine, field.time);
    if (!ps) return false;
    if (ps.hide) return true;
    const mount = this.mountOf(o, mine), M = MOUNTS[mount];
    const frame = Math.floor(field.time / M.flap) % 2;
    const key = mine ? 'me' : 'p:' + o.sid;
    if (ps.bird) {
      if (ps.walk) return false; // 人は ふつうに（鳥は extra3d で）
    }
    const c = this.riderCanvas(look, job, o.dir || 'down', frame, eq, mount);
    out.push({ key: key + ':sky', canvas: c, x: o.x, y: o.y, lift: ps.lift, anchor: M.anchor, scale: M.big, shadowScale: M.shadowScale, air: true, ghost: mine ? '#9fd6ff' : null });
    return true;
  }

  // 2.5D: よぶ・かえる ときの 鳥（竜）だけの え
  extra3d(field, out) {
    const ps = this.pose(field.me, true, field.time);
    if (!ps?.bird) return;
    const M = MOUNTS[this.mountOf(field.me, true)];
    const frame = Math.floor(field.time / M.flap) % 2;
    out.push({ key: 'sky:bird', canvas: M.only(ps.bird.dir, frame), x: ps.bird.x, y: ps.bird.y, lift: ps.bird.lift, anchor: M.anchorOnly, scale: M.big, shadowScale: M.shadowScale * 0.92, air: true, alpha: ps.bird.alpha ?? 1 });
  }

  // イベントの 役者の 大鳥（風のさいだん）・星の竜: 空に うかべて かく
  drawActor2D(field, a, camX, camY) {
    const M = MOUNTS[ACTOR_MOUNT[a.sprite]];
    if (!M) return false;
    const c = M.only(a.dir, Math.floor(field.time / M.flap) % 2);
    const r = c.res || 1;
    const w = (c.width / r) * M.big, h = (c.height / r) * M.big;
    const ctx = field.ctx;
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    ctx.beginPath();
    ctx.ellipse(Math.round(a.x * TS - camX), Math.round(a.y * TS - camY - 1), M.shadow - 1, 3.5, 0, 0, Math.PI * 2);
    ctx.fill();
    field.drawFine(c, Math.round(a.x * TS - w / 2 - camX), Math.round((a.y - ACTOR_LIFT) * TS - h + 8 - camY), w, h);
    return true;
  }

  actor3d(a, field) {
    const M = MOUNTS[ACTOR_MOUNT[a.sprite]];
    if (!M) return null;
    return { key: 'a:' + a.id, canvas: M.only(a.dir, Math.floor(field.time / M.flap) % 2), x: a.x, y: a.y, lift: ACTOR_LIFT, anchor: M.anchorOnly, scale: M.big, shadowScale: M.shadowScale * 0.92, air: true };
  }

  // じぶんの なかま（酒場の なかま など）は 鳥の 上
  hidesFollowers() {
    return this.flying || this.anim?.kind === 'call' && this.anim.t >= 700;
  }
}

export { BIRD_W, BIRD_H, RIDE_TOP };

js/client/time-shift.js:
// 時の砂時計で 時代を 切りかえる ときの 砂の うず（第6章。だいほんの ['timeShift', 'in'|'out', 動く 人の ID, 'past'|'present']）
// ・in … 画面の まわりから 砂色の 光の つぶが うずを まいて あつまり、画面を おおう（0.9びょう）。おおった まま 待つ
// ・out … うずが ほどけて、新しい 時代の 画面が 見える（0.7びょう）
// 2D でも 2.5D でも、画面の いちばん 上（#fx）に かさねる キャンバスなので おなじ ように 見える
// 動く 人（ids）に 自分が いない ときは 何も しない（家族が「ひとりで」時を こえた ときの、のこった 人の 画面）

const COLORS = {
  past: { base: [196, 150, 82], hi: [255, 228, 160], dark: [92, 60, 26] },
  present: { base: [176, 196, 220], hi: [250, 246, 220], dark: [60, 70, 110] },
};
let layer = null;

function ensureLayer() {
  if (layer && layer.canvas.isConnected) return layer;
  const host = document.getElementById('fx') || document.body;
  const canvas = document.createElement('canvas');
  canvas.className = 'time-shift';
  Object.assign(canvas.style, { position: 'absolute', inset: '0', width: '100%', height: '100%', pointerEvents: 'none', zIndex: 5 });
  host.append(canvas);
  layer = { canvas, ctx: canvas.getContext('2d'), level: 0, era: 'past', seed: Math.random() * 1000 };
  return layer;
}

// level … 0（見えない）〜 1（画面を おおう）。t … ミリびょう
export function drawSwirl(L, level, t) {
  const c = L.canvas;
  const w = c.clientWidth || innerWidth, h = c.clientHeight || innerHeight;
  const k = Math.min(2, devicePixelRatio || 1);
  if (c.width !== Math.round(w * k) || c.height !== Math.round(h * k)) { c.width = Math.round(w * k); c.height = Math.round(h * k); }
  const x = L.ctx;
  x.setTransform(k, 0, 0, k, 0, 0);
  x.clearRect(0, 0, w, h);
  if (level <= 0.001) return;
  const C = COLORS[L.era] || COLORS.past;
  const rgba = ([r, g, b], a) => `rgba(${r}, ${g}, ${b}, ${a})`;
  const cx = w / 2, cy = h / 2, R = Math.hypot(w, h) / 2;
  // うずの 中心へ むかって こく なる まく
  const g = x.createRadialGradient(cx, cy, 0, cx, cy, R);
  g.addColorStop(0, rgba(C.hi, Math.min(1, level * 1.1)));
  g.addColorStop(0.55, rgba(C.base, Math.min(1, level * 0.95)));
  g.addColorStop(1, rgba(C.dark, Math.min(1, level * 0.9)));
  x.fillStyle = g;
  x.fillRect(0, 0, w, h);
  // 砂の つぶ（6本の うでの うず。まわりながら 中へ）
  const n = 260;
  for (let i = 0; i < n; i++) {
    const arm = i % 6;
    const f = (i * 0.6180339) % 1;
    const rr = R * (1.15 - level * 0.85) * (0.12 + f * 0.95);
    const ang = arm * (Math.PI / 3) + f * 5.2 + t / 380 + L.seed;
    const px = cx + Math.cos(ang) * rr, py = cy + Math.sin(ang) * rr * 0.92;
    const s = 1.5 + (i % 4);
    x.fillStyle = rgba(i % 3 ? C.hi : C.base, Math.min(1, 0.35 + level * 0.65));
    x.fillRect(Math.round(px), Math.round(py), s, s);
  }
  // まん中の 砂時計の 光
  if (level > 0.5) {
    const a = (level - 0.5) * 2;
    x.fillStyle = rgba([255, 255, 240], a * 0.9);
    const s = 10 + a * 8;
    x.beginPath();
    x.moveTo(cx - s, cy - s * 1.4); x.lineTo(cx + s, cy - s * 1.4); x.lineTo(cx, cy);
    x.lineTo(cx + s, cy + s * 1.4); x.lineTo(cx - s, cy + s * 1.4); x.lineTo(cx, cy);
    x.closePath();
    x.fill();
    // 第6章 Step 5: トキネの砂時計のかざりを 12こ 集めた（c6_orn_done）… 砂時計の まわりに 12の かざりが 光る
    if (L.deco) {
      for (let i = 0; i < 12; i++) {
        const ang = (i * Math.PI) / 6 + t / 900;
        const rr = s * 2.3;
        x.fillStyle = rgba(i % 3 ? [255, 228, 140] : [255, 255, 255], a);
        x.fillRect(Math.round(cx + Math.cos(ang) * rr) - 2, Math.round(cy + Math.sin(ang) * rr) - 2, 4, 4);
      }
    }
  }
}

function animate(L, from, to, ms) {
  return new Promise((resolve) => {
    const t0 = performance.now();
    const step = (now) => {
      const p = Math.min(1, (now - t0) / ms);
      const e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      L.level = from + (to - from) * e;
      drawSwirl(L, L.level, now);
      if (p < 1) requestAnimationFrame(step);
      else resolve();
    };
    requestAnimationFrame(step);
  });
}

// だいほんの 1つの えんしゅつ（client/ui/script.js）
export async function timeShiftFx(game, phase, ids = null, era = 'past') {
  if (Array.isArray(ids) && game?.sid && !ids.includes(game.sid)) return;
  const L = ensureLayer();
  L.deco = !!(game?.me?.flags?.c6_orn_done || game?.worldFlagSet?.has?.('c6_orn_done'));
  if (phase === 'in') {
    L.era = era === 'present' ? 'present' : 'past';
    game?.audio?.sfx('wind');
    await animate(L, L.level, 1, 900);
    return;
  }
  L.era = era === 'present' ? 'present' : 'past';
  game?.audio?.sfx('sparkle');
  await animate(L, Math.max(L.level, 1), 0, 700);
  L.canvas.remove();
  layer = null;
}

// とちゅうで 切れた ときなど（だいほんを すてた とき）に うずを 消す
export function clearTimeShift() {
  if (layer?.canvas) layer.canvas.remove();
  layer = null;
}

js/client/ui/alchemy.js:
// れん金がま（第32回 C）の 画面。メニューの「道具」の いちばん上の「れん金がま」から 開く
//
//   「れん金がまに、何を入れる？」→ レシピから作る／自分で入れてみる／やめる
//   レシピから作る: 知っている レシピ（材料が そろっている 物に「作れる」）→「〇〇＋〇〇で、△△を作る？」→ 入れる → 閉じる
//     いちばん上は「同じ武具を2つ」（きたえられる 回数が 1 ふえる）
//   自分で入れてみる: ふくろの 物を 1つずつ えらぶ（2つ 入れたら「これで、れん金する」）。はずれは もどってくる
//   中に 何か 入っている 間は「あと〇歩ほど」を 出す（レシピは 見られる）
// できあがりの 知らせは サーバーから（world/alchemy.js の finishPot。トースト）
import { sourcesFlow } from './sources.js';
import { GEAR_FX, fxBlock, fxText, fxShort, fxListOf, fxRange, fxStars, fxSlots, fxMatsOf } from '../../shared/data/gear-fx.js';
import { el, esc } from './dom.js';
import { Counter, itemInfo, myTeam } from './counter.js';
import { request } from './shop.js';
import { itemCount } from '../../shared/stats.js';
import { rareNameHtml } from './rarity.js';
import { ITEMS, baseItemId, sortItemIds, SLOT_NAMES } from '../../shared/data/items.js';
import { UPGRADE_TYPES } from '../../shared/data/items-forge.js';
import { setForgeViewer, maxPlus, isShopForge } from '../../shared/data/forge.js';
import {
  ALCHEMY_POT, RECIPE_BY_ID, MERGE_RECIPE, CAP_UP_MAX, LB_MAX, limitMerge, hasPot, knownRecipes, recipeLack, pickIngredients, insText, capUp, potSteps,
} from '../../shared/data/alchemy.js';

// きたえる 回数を 見る 人を 自分の キャラに（道具の 説明・かじ屋の 画面。data/forge.js）
export function bindAlchemy(game) {
  setForgeViewer(() => game.me || null);
}

const CSS = `
.alchemy-panel .al-pot { display: flex; flex-direction: column; gap: 0.35em; }
.alchemy-panel .al-pot .hd { color: #ffd66b; }
.alchemy-panel .al-slots { display: flex; flex-wrap: wrap; gap: 0.3em; align-items: center; }
.alchemy-panel .al-slot { border: 1px solid rgba(255, 214, 107, 0.55); border-radius: 6px; padding: 0.1em 0.45em; min-width: 3.2em; text-align: center; }
.alchemy-panel .al-slot.empty { color: var(--muted); border-style: dashed; }
.alchemy-panel .al-need { display: grid; grid-template-columns: 1fr auto auto; gap: 0 0.6em; font-size: var(--fs-small); }
.alchemy-panel .al-need .ok { color: #8fe08f; }
.alchemy-panel .al-need .ng { color: #ff8f8f; }
.alchemy-panel .al-steps { font-size: 1.15em; color: #ffd66b; }
.menu .tag.pot { color: #ffd66b; border-color: rgba(255, 214, 107, 0.6); }
`;
let cssDone = false;
function ensureCss() {
  if (cssDone || typeof document === 'undefined') return;
  cssDone = true;
  document.head.append(el('style', { id: 'alchemy-css', text: CSS }));
}

// メニューの「道具」の いちばん上の 行（かまを 持っていない ときは null）
export function alchemyRow(c) {
  if (!hasPot(c)) return null;
  ensureCss();
  const busy = !!c.alchemy?.pot;
  return { html: `${esc(ITEMS[ALCHEMY_POT].name)}<span class="tag pot">${busy ? 'れん金中' : '大事'}</span>`, label: ITEMS[ALCHEMY_POT].name, value: ALCHEMY_POT, key: true, pot: true };
}

const nameOf = (id) => ITEMS[id]?.name || id;

// かまの 中の ようす（info の まど）
function potBox(game, pot) {
  const box = el('div', { class: 'al-pot' });
  box.append(el('div', { class: 'hd', text: 'れん金がまの中' }));
  box.append(el('div', { class: 'al-slots' }, ...(pot.ins || []).map((id) => el('span', { class: 'al-slot', text: nameOf(id) }))));
  box.append(el('div', { html: `できる物: ${pot.known ? rareNameHtml(pot.out) : '？？？'}` }));
  if (pot.lb) box.append(el('div', { class: 'small', text: `${nameOf(pot.merge)}が限界とっぱする（★${pot.lb}）` }));
  else if (pot.merge) box.append(el('div', { class: 'small', text: `${nameOf(pot.merge)}のきたえられる回数が1ふえる` }));
  box.append(el('div', { class: 'al-steps', text: `あと${pot.left}歩ほど` }));
  box.append(el('div', { class: 'small muted', text: '歩いていると完成する。' }), el('div', { class: 'small muted', text: '（できたら知らせが出て、ふくろに入る）' }));
  return box;
}

// レシピの 材料と できる 物（info の まど）
function recipeBox(game, rid) {
  const r = RECIPE_BY_ID[rid];
  const box = el('div', { class: 'al-pot' });
  const need = new Map();
  for (const id of r.ins) need.set(id, (need.get(id) || 0) + 1);
  const lack = new Map(recipeLack(game.me, rid).map((x) => [x.id, x]));
  const have = (id) => (game.me.items || []).filter((e) => baseItemId(e.id) === id).reduce((a, e) => a + e.n, 0);
  const grid = el('div', { class: 'al-need' }, el('span', { class: 'muted', text: '材料' }), el('span', { class: 'muted', text: 'いる' }), el('span', { class: 'muted', text: '持っている' }));
  for (const [id, n] of need) {
    grid.append(el('span', { text: nameOf(id) }), el('span', { text: `${n}` }), el('span', { class: lack.has(id) ? 'ng' : 'ok', text: `${have(id)}` }));
  }
  box.append(grid, el('div', { class: 'small muted', text: `あと${potSteps(r.out)}歩ほど歩くとできる` }));
  const info = itemInfo(game, r.out);
  if (info) box.append(info);
  return box;
}

// 同じ 武具を 2つ（ふくろに 2つ いじょう ある 装備。もとの 装備ごと）。店で 買える 装備（★1）は きたえられない ので 出さない（第35回）
function mergeChoices(game) {
  const groups = new Map();
  for (const e of game.me.items || []) {
    const it = ITEMS[e.id];
    if (!it || !UPGRADE_TYPES.includes(it.type) || !(e.n > 0) || isShopForge(e.id)) continue;
    const b = baseItemId(e.id);
    if (!groups.has(b)) groups.set(b, []);
    for (let i = 0; i < e.n; i++) groups.get(b).push(e.id);
  }
  const out = [];
  for (const [b, ids] of groups) {
    if (ids.length < 2) continue;
    ids.sort((x, y) => (ITEMS[y].plus || 0) - (ITEMS[x].plus || 0) || (ITEMS[y].lb || 0) - (ITEMS[x].lb || 0));
    // 回数を ふやす: きたえた 回数が いちばん 多い 物と、いちばん 少ない 物（少ない ほうが なくなる）
    if (capUp(game.me, b) < CAP_UP_MAX) {
      out.push({ base: b, ids: [ids[0], ids[ids.length - 1]], n: ids.length, full: false });
      continue;
    }
    // 第65回: 限界とっぱ（上限まで きたえた 物を 2つ。★の 多い ほうが のこって ★が 1つ ふえる）
    const lb = limitMerge([ids[0], ids[1]], game.me);
    out.push({ base: b, ids: [ids[0], ids[1]], n: ids.length, full: !!lb.why, lb: lb.k || 0, why: lb.why || null, out: lb.out || null });
  }
  return out;
}

export async function alchemyUI(game) {
  ensureCss();
  bindAlchemy(game);
  const ct = new Counter(game, { title: 'れん金がま', keeper: 'れん金がま', cls: 'alchemy-panel' });
  // 画面の 間は フィールドを 歩かない（えらぶ まどが ない すきまも）
  const hold = { onNav: () => {}, pad: true };
  game.input.push(hold);
  ct.hook(() => game.input.pop(hold));
  try {
    await potLoop(game, ct);
  } finally {
    if (!ct.closed) ct.close();
  }
}

async function potLoop(game, ct) {
  let line = null;
  while (!ct.closed) {
    const st = await request(game, { kind: 'alchemy', action: 'status' });
    if (ct.closed) return;
    const pot = st.pot || null;
    ct.info(pot ? potBox(game, pot) : el('div', { class: 'detail', text: '装備や道具を2〜3こ入れて歩くと、新しい物ができる。\n同じ武具を2つ入れると、きたえられる回数がふえる。' }));
    await ct.say(line || (pot ? `れん金がまの中で、${pot.known ? nameOf(pot.out) : '何か'}ができるのを待っている。\nあと${pot.left}歩ほど歩こう。` : 'れん金がまに、何を入れる？'), { narr: true });
    const known = knownRecipes(game.me);
    const cmd = await ct.pick([
      { label: pot ? 'レシピを見る' : 'レシピから作る', value: 'recipe', right: `${known.length + 1}こ` },
      { label: '自分で入れてみる', value: 'try', disabled: !!pot },
      { label: '装備に効果をつける', value: 'enchant' },
      { label: 'やめる', value: 'exit' },
    ], { back: null, onMove: (x) => { if (x?.value === 'try') ct.info(el('div', { class: 'detail', text: 'ふくろの物を2〜3こ入れてみる。\nうまくいけば、新しいレシピになる。\n（はずれは入れられない）' })); else if (x?.value === 'enchant') ct.info(el('div', { class: 'detail', text: ENCHANT_HELP })); else if (pot) ct.info(potBox(game, pot)); } });
    if (ct.closed || !cmd || cmd.value === 'exit') return;
    if (cmd.value === 'enchant') {
      await enchantLoop(game, ct);
      line = null;
      continue;
    }
    const done = cmd.value === 'recipe' ? await recipeLoop(game, ct, !!pot) : await tryLoop(game, ct);
    if (done) return;
    line = null;
  }
}

// ───── 第64回 ⑥c・第65回: 装備に 効果を つける（data/gear-fx.js。すぐ できる。効果は ランダム）─────
const ENCHANT_HELP = '装備（★2から）に、素材で効果をつける。\n効果のしゅるいと強さは、入れてみるまでわからない。レア度が高いほど強い効果が出やすい。\n同じ効果が出ると強くなる。限界とっぱすると、効果を2つつけられる。';
const SLOT_ORDER = ['weapon', 'armor', 'shield', 'head'];
async function enchantLoop(game, ct) {
  const team = myTeam(game);
  let mate = team[0];
  if (team.length > 1) {
    await ct.say('だれの装備に効果をつける？', { narr: true });
    const p = await ct.pick(team.map((m) => ({ label: m.name, right: m.kind, value: m.key })));
    if (ct.closed || !p) return;
    mate = team.find((m) => m.key === p.value);
  }
  const ch = mate.char;
  const listOf = (id) => fxListOf(ch, id);
  const slots = SLOT_ORDER.filter((sl) => ch.equip?.[sl]).map((sl) => {
    const id = ch.equip[sl];
    const fx = listOf(id);
    return { label: `${SLOT_NAMES[sl]}：${nameOf(id)}`, right: fxBlock(id) ? '×' : fx.length ? fxShort(fx) : '効果なし', value: sl, disabled: !!fxBlock(id) };
  });
  if (!slots.length) {
    await ct.say(`${ch.name}は、何も装備していない。`, { narr: true });
    await ct.tap(1600);
    return;
  }
  const detail = (id) => {
    if (fxBlock(id)) return fxBlock(id);
    const fx = listOf(id);
    const [lo, hi] = fxRange(id);
    const mats = fxMatsOf(id);
    return `今の効果（${fx.length}/${fxSlots(ch, id)}）：${fx.length ? fx.map((x) => fxText(x.k, x.v)).join('\n　') : 'なし'}\n出る強さ：+${lo}〜+${hi}（★${fxStars(id)}）\nいる素材：${mats.map(([m, n]) => `${nameOf(m)}${n}こ（${itemCount(game.me, m)}）`).join('・')}`;
  };
  await ct.say('どの装備に効果をつける？\n（店の品・★1にはつけられない）', { narr: true });
  const sp = await ct.pick(slots, { onMove: (x) => { const id = x && ch.equip?.[x.value]; ct.info(el('div', { class: 'detail', text: id ? detail(id) : '' })); } });
  if (ct.closed || !sp) return;
  const slot = sp.value;
  const id = ch.equip[slot];
  const mats = fxMatsOf(id);
  const lack = mats.filter(([m, n]) => itemCount(game.me, m) < n).map(([m, n]) => ({ id: m, need: n, have: itemCount(game.me, m) }));
  if (lack.length) {
    await ct.say(`素材が足りない。\n（${lack.map((x) => `${nameOf(x.id)}があと${x.need - x.have}こ`).join('・')}）`, { narr: true });
    await ct.tap(2200);
    await sourcesFlow(game, ct, lack);
    return;
  }
  const yes = await ct.ask(`${mats.map(([m, n]) => `${nameOf(m)}${n}こ`).join('・')}を使って、\n${ch.name}の${nameOf(id)}に力をこめる？\n（どんな力が出るかは、お楽しみ）`);
  if (ct.closed || yes !== 0) return;
  game.audio.sfx('item');
  const res = await request(game, { kind: 'alchemy', action: 'enchant', who: mate.key, slot });
  if (ct.closed) return;
  if (res.ok) game.audio.sfx('key');
  await ct.say(res.text || '', { narr: true });
  await ct.tap(2400);
  // 効果が いっぱい: 入れかえるか 前の ままか
  if (res.ok && res.fxChoose) {
    const now = res.fxNow || [];
    await ct.say(`生まれた力：${fxText(res.fxRoll.k, res.fxRoll.v)}\nどうする？`, { narr: true });
    const rows = [...now.map((x, i) => ({ label: `${GEAR_FX[x.k]?.name || ''}+${x.v}と入れかえる`, value: i })), { label: '前のままにする', value: -1 }];
    const p = await ct.pick(rows, { back: null, onMove: (x) => ct.info(el('div', { class: 'detail', text: x && x.value >= 0 ? `今：${fxText(now[x.value].k, now[x.value].v)}\n→ ${fxText(res.fxRoll.k, res.fxRoll.v)}` : '生まれた力は消えて、今の効果のまま' })) });
    const r2 = await request(game, { kind: 'alchemy', action: 'enchantPick', replace: p ? p.value : -1 });
    if (ct.closed) return;
    await ct.say(r2.text || '', { narr: true });
    await ct.tap(2000);
  }
}

// 入れる（ids）。うまく いったら true（画面を 閉じる）
async function put(game, ct, ids) {
  game.audio.sfx('item');
  const res = await request(game, { kind: 'alchemy', action: 'put', ids });
  if (ct.closed) return false;
  if (!res.ok) {
    game.audio.sfx('buzz');
    await ct.say(res.text || 'うまくいかなかった。', { narr: true });
    await ct.tap(2400);
    return false;
  }
  setTimeout(() => game.audio.sfx('sparkle'), 300);
  if (res.pot) ct.info(potBox(game, res.pot));
  ct.list(null);
  await ct.say(res.text, { narr: true });
  await ct.tap(3200);
  return true;
}

// ───────────── レシピから 作る ─────────────
async function recipeLoop(game, ct, busy) {
  let idx = 0;
  while (!ct.closed) {
    const list = knownRecipes(game.me);
    const rows = [{ value: MERGE_RECIPE, html: '同じ武具を2つ<span class="tag up">回数+1</span>', right: '' }];
    for (const rid of list) {
      const r = RECIPE_BY_ID[rid];
      const ok = !recipeLack(game.me, rid).length;
      rows.push({ value: rid, html: `${rareNameHtml(r.out)}${ok && !busy ? '<span class="tag up">作れる</span>' : ''}`, right: '', rightCls: ok ? 'gold' : 'dis' });
    }
    await ct.say(busy ? '覚えたレシピ' : '何を作る？', { narr: true });
    const pick = await ct.pick(rows, {
      start: Math.min(idx, rows.length - 1),
      onMove: (x) => ct.info(!x ? null : x.value === MERGE_RECIPE
        ? el('div', { class: 'detail', text: `同じ武具（武器・よろい・たて・頭）を2つ入れると、きたえられる回数が1ふえる。\n（1つの装備で${CAP_UP_MAX}回まで。レア度は変わらない。きたえた回数が多いほうが残る）\n${CAP_UP_MAX}回ふやしたあとは、上限まできたえた物を2つ入れると限界とっぱ（★${LB_MAX}まで）。` })
        : recipeBox(game, x.value)),
    });
    if (ct.closed || !pick) return false;
    idx = rows.findIndex((r) => r.value === pick.value);
    if (busy) continue;
    if (pick.value === MERGE_RECIPE) {
      if (await mergeLoop(game, ct)) return true;
      continue;
    }
    const r = RECIPE_BY_ID[pick.value];
    const lack = recipeLack(game.me, pick.value);
    if (lack.length) {
      await ct.say(`材料が足りない。\n（${lack.map((x) => `${nameOf(x.id)}があと${x.need - x.have}こ`).join('・')}）`, { narr: true });
      await ct.tap(2400);
      await sourcesFlow(game, ct, lack); // 第64回 ⑥a: 入手先
      continue;
    }
    const yes = await ct.ask(`${insText(r.ins)}で、\n${nameOf(r.out)}を作る？`);
    if (ct.closed) return false;
    if (yes !== 0) continue;
    const ids = pickIngredients(game.me, pick.value);
    if (ids && await put(game, ct, ids)) return true;
  }
  return false;
}

// 同じ 武具を 2つ: 右の まど（限界とっぱの ときは、できる 物と わけ）
function mergeInfo(game, m) {
  const box = el('div', {});
  const info = itemInfo(game, m.lb ? m.out : m.ids[0]);
  if (info) box.append(info);
  const top = maxPlus(m.base, game.me);
  const note = m.lb
    ? `限界とっぱ（★${m.lb}）！${m.lb === 1 ? '\nれん金の効果を2つつけられるようになる。' : '\nもう1回きたえたぶん強くなる。'}`
    : m.why === 'capMax' ? `回数はもうふやせない。\n上限（+${top}）まできたえた物を2つ入れると、限界とっぱできる。`
      : m.why === 'lbMax' ? `もう★${LB_MAX}まで限界とっぱしている。`
        : m.why === 'rebirth' ? '生まれ変わる武器は、限界とっぱできない。' : '';
  if (note) box.append(el('div', { class: 'detail', text: note }));
  return box;
}

// 同じ 武具を 2つ
async function mergeLoop(game, ct) {
  while (!ct.closed) {
    const list = mergeChoices(game);
    if (!list.length) {
      await ct.say('同じ武具を2つ持っていない。\n（武器・よろい・たて・頭の装備。店の品〈★1〉はのぞく）', { narr: true });
      await ct.tap(2400);
      return false;
    }
    const rows = list.map((m, i) => {
      const top = maxPlus(m.base, game.me);
      const right = m.lb ? `★${m.lb}へ` : m.full ? (m.why === 'capMax' ? `+${top}まで` : '最大') : `+${top}→+${top + 1}`;
      return { value: i, html: `${rareNameHtml(m.base)}<span class="cnt">×${m.n}</span>`, right, rightCls: m.full ? 'muted' : 'gold', disabled: m.full };
    });
    await ct.say('どの武具を入れる？', { narr: true });
    const pick = await ct.pick(rows, { onMove: (x) => ct.info(x ? mergeInfo(game, list[x.value]) : null) });
    if (ct.closed || !pick) return false;
    const m = list[pick.value];
    const top = maxPlus(m.base, game.me);
    const yes = await ct.ask(m.lb
      ? `${insText(m.ids)}を入れる？\n（${nameOf(m.ids[0])}が限界とっぱして、${nameOf(m.out)}になる）`
      : `${insText(m.ids)}を入れる？\n（${nameOf(m.base)}は+${top}→+${top + 1}まできたえられるようになる）`);
    if (ct.closed) return false;
    if (yes === 0 && await put(game, ct, m.ids)) return true;
  }
  return false;
}

// ───────────── 自分で 入れてみる ─────────────
function slotsBox(slots) {
  const cells = [0, 1, 2].map((i) => (slots[i] ? el('span', { class: 'al-slot', text: nameOf(slots[i]) }) : el('span', { class: 'al-slot empty', text: i < 2 ? '？' : '（なくてもよい）' })));
  return el('div', { class: 'al-pot' }, el('div', { class: 'hd', text: '入れる物' }), el('div', { class: 'al-slots' }, ...cells));
}

async function tryLoop(game, ct) {
  const slots = [];
  while (!ct.closed) {
    const used = new Map();
    for (const id of slots) used.set(id, (used.get(id) || 0) + 1);
    const bag = sortItemIds((game.me.items || []).filter((e) => e.n - (used.get(e.id) || 0) > 0 && ITEMS[e.id] && ITEMS[e.id].type !== 'key').map((e) => e.id), 'type');
    const count = (id) => ((game.me.items || []).find((e) => e.id === id)?.n || 0) - (used.get(id) || 0);
    const rows = [];
    if (slots.length >= 2) rows.push({ value: '#go', html: '<span class="gold">これで、れん金する</span>' });
    if (slots.length) rows.push({ value: '#undo', label: '1つもどす' });
    if (slots.length < 3) for (const id of bag) rows.push({ value: id, html: ITEMS[id].type === 'mat' ? `${esc(nameOf(id))}<span class="tag mat">素材</span>` : rareNameHtml(id), right: `×${count(id)}` });
    ct.info(slotsBox(slots));
    await ct.say(slots.length >= 2 ? (slots.length < 3 ? 'これで入れる？\n3つめを入れてもよい。' : 'これで入れる？') : `${slots.length + 1}つめに、何を入れる？`, { narr: true });
    const pick = await ct.pick(rows, { onMove: (x) => ct.info(x && ITEMS[x.value] ? el('div', {}, slotsBox(slots), itemInfo(game, x.value)) : slotsBox(slots)) });
    if (ct.closed || !pick) return false;
    if (pick.value === '#undo') { slots.pop(); continue; }
    if (pick.value === '#go') {
      if (await put(game, ct, slots.slice())) return true;
      slots.length = 0;
      continue;
    }
    slots.push(pick.value);
  }
  return false;
}

js/client/ui/arena.js:
// 第37回 A: サファラ闘技場の 画面（だいほんの ['ui', …]。shared/world/arena.js）
//   arenaCard … かけ試合の 組み合わせ（4ひきの すがた・オッズ）
//   arenaBout … かけ試合の ようす（1回戦 2つ と 決勝。短い 戦いの ようすを 1行ずつ。タップで 先へ・「とばす」で さいごまで）
//   arenaWall … 王者のかべ（家族サーバーでは 家族みんな、ひとりの サイトでは 自分の キャラたち）
import { el, ListMenu } from './dom.js';
import { monsterCanvas } from '../render/monsters.js';

const CSS = `
.arena-panel { display: flex; flex-direction: column; max-height: calc(100% - var(--safe-t) - 16px); }
.arena-main { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.arena-lead { white-space: pre-line; margin-bottom: 0.4em; }
.arena-card { display: grid; grid-template-columns: 1fr auto 1fr; gap: 0.4em 0.5em; align-items: center; }
.arena-vs { color: #ff8a6a; font-weight: bold; text-align: center; }
.arena-mon { display: flex; flex-direction: column; align-items: center; gap: 0.15em; padding: 0.3em; border-radius: 6px; background: rgba(255, 255, 255, 0.05); min-width: 0; }
.arena-mon.pick { box-shadow: 0 0 0 2px #ffd66b; background: rgba(255, 214, 107, 0.14); }
.arena-mon.out { opacity: 0.45; filter: grayscale(0.7); }
.arena-mon.champ { box-shadow: 0 0 0 2px #ffd66b, 0 0 14px rgba(255, 214, 107, 0.7); }
.arena-mon canvas { image-rendering: pixelated; display: block; }
.arena-mon .nm { font-size: var(--fs-small); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.arena-mon .od { color: #ffd66b; font-weight: bold; font-variant-numeric: tabular-nums; }
.arena-mon .no { color: var(--muted); font-size: 0.8em; }
.arena-hp { width: 100%; height: 0.45em; border-radius: 3px; background: rgba(255, 255, 255, 0.15); overflow: hidden; }
.arena-hp > i { display: block; height: 100%; background: #6ad86a; transition: width 0.35s; }
.arena-hp.low > i { background: #ff7a5a; }
.arena-round { text-align: center; color: #ffd66b; font-weight: bold; margin: 0.2em 0 0.3em; }
.arena-log { min-height: 4.6em; white-space: pre-line; margin-top: 0.4em; padding: 0.35em 0.5em; border-radius: 6px; background: rgba(0, 0, 0, 0.3); line-height: 1.45; }
.arena-result { text-align: center; font-weight: bold; margin-top: 0.4em; white-space: pre-line; }
.arena-result.hit { color: #ffd66b; }
.arena-btns { display: flex; gap: 0.5em; justify-content: center; margin-top: 0.4em; }
.arena-wall-rows { display: flex; flex-direction: column; }
.arena-wall-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: 'nm best' 'st st'; column-gap: 0.6em; padding: 0.3em 0.3em; border-bottom: 1px solid rgba(255, 255, 255, 0.08); }
.arena-wall-row.me { background: rgba(160, 120, 255, 0.16); border-radius: 4px; }
.arena-wall-row .nm { grid-area: nm; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.arena-wall-row .best { grid-area: best; color: #ffd66b; font-weight: bold; white-space: nowrap; }
.arena-wall-row .st { grid-area: st; display: flex; flex-wrap: wrap; gap: 0.2em; font-size: 0.82em; }
.arena-wall-row .st span { padding: 0 0.35em; border-radius: 3px; background: rgba(255, 255, 255, 0.07); color: var(--muted); }
.arena-wall-row .st span.on { background: rgba(255, 214, 107, 0.22); color: #ffe9a8; }
.arena-wall-row .st span.lg.on { background: rgba(255, 120, 200, 0.25); color: #ffd0f0; }
@media (orientation: landscape) and (max-height: 500px) {
  .arena-log { min-height: 3em; }
  .arena-card { gap: 0.2em 0.4em; }
  .arena-matches { display: grid; grid-template-columns: 1fr 1fr; gap: 0 0.8em; }
  .arena-lead { margin-bottom: 0.2em; }
  .arena-round { margin: 0 0 0.2em; }
}
`;
function addCss() {
  if (typeof document === 'undefined' || document.getElementById('arena-r37-css')) return;
  const st = document.createElement('style');
  st.id = 'arena-r37-css';
  st.textContent = CSS;
  document.head.append(st);
}

// 魔物の すがた（大きさは 見た目で そろえる。px … いちばん 長い 辺）
function monPic(sp, px = 64, frame = 0) {
  const src = monsterCanvas(sp, frame);
  const c = document.createElement('canvas');
  c.width = src.width;
  c.height = src.height;
  c.getContext('2d').drawImage(src, 0, 0);
  const r = src.res || 1, w = src.width / r, h = src.height / r;
  const k = px / Math.max(w, h);
  c.style.width = `${Math.round(w * k)}px`;
  c.style.height = `${Math.round(h * k)}px`;
  return c;
}
const picSize = () => (typeof window !== 'undefined' && window.innerHeight < 500 ? 44 : 62);

// まどの 外がわ（見出し・✕）。close で とじる
function shell(game, title, onClose) {
  addCss();
  const back = el('div', { class: 'modal-back' });
  const root = el('div', { class: 'panel center-panel svc-panel arena-panel' });
  const closeBtn = el('button', { class: 'btn closebtn', text: '✕ 閉じる', 'aria-label': '閉じる', onclick: () => { game.audio?.sfx('cancel'); onClose(); } });
  root.append(el('div', { class: 'win svc-head' }, el('span', { class: 'gold', text: title }), el('span', { class: 'svc-right' }), closeBtn));
  const main = el('div', { class: 'win main arena-main' });
  root.append(main);
  back.addEventListener('click', () => onClose());
  document.getElementById('ui').append(back, root);
  return { root, main, remove: () => { back.remove(); root.remove(); } };
}
function okMenu(game, label, onPick) {
  const menu = new ListMenu(game.input, {
    items: [{ label, value: 'ok' }],
    sound: (x) => game.audio?.sfx(x),
    onSelect: () => onPick(),
    onCancel: () => onPick(),
    back: null,
  });
  return menu;
}

function monBox(m, i, extra = '') {
  return el('div', { class: `arena-mon ${extra}`, 'data-i': i },
    el('span', { class: 'no', text: `${i + 1}ばん` }), monPic(m.sp, picSize()), el('span', { class: 'nm', text: m.name }),
    m.odds ? el('span', { class: 'od', text: `${m.odds}倍` }) : null);
}

// ───────────── かけ試合の 組み合わせ ─────────────
export function arenaCardUI(game, data) {
  return new Promise((resolve) => {
    let menu;
    const close = () => {
      menu?.blur();
      s.remove();
      resolve();
    };
    const s = shell(game, 'かけ試合の組み合わせ', close);
    const card = Array.isArray(data?.card) ? data.card : [];
    s.main.append(el('div', { class: 'arena-lead small', text: '1回戦に勝った2ひきが、決勝で戦う。\n最後まで勝ちのこる1ぴきを当てよう！（オッズ＝当たった時の何倍か）' }));
    const matches = el('div', { class: 'arena-matches' });
    for (const [a, b] of data?.pairs || [[0, 1], [2, 3]]) {
      if (!card[a] || !card[b]) continue;
      matches.append(el('div', { class: 'arena-match' },
        el('div', { class: 'arena-round', text: a === 0 ? '1回戦　第1試合' : '1回戦　第2試合' }),
        el('div', { class: 'arena-card' }, monBox(card[a], a), el('span', { class: 'arena-vs', text: 'VS' }), monBox(card[b], b))));
    }
    s.main.append(matches);
    menu = okMenu(game, 'かける魔物を選ぶ', close);
    s.root.append(menu.root);
    menu.focus();
  });
}

// ───────────── かけ試合の ようす ─────────────
export function arenaBoutUI(game, data) {
  return new Promise((resolve) => {
    const card = Array.isArray(data?.card) ? data.card : [];
    const bouts = Array.isArray(data?.bouts) ? data.bouts : [];
    let menu = null, timer = null, done = false, skip = false;
    let next = null;
    const close = () => {
      if (!done) {
        // とちゅうで とじた: さいごまで とばす
        skip = true;
        next?.();
        return;
      }
      clearTimeout(timer);
      menu?.blur();
      s.remove();
      resolve();
    };
    const s = shell(game, 'かけ試合', close);
    const round = el('div', { class: 'arena-round' });
    const field = el('div', { class: 'arena-card' });
    const log = el('div', { class: 'arena-log' });
    const result = el('div', { class: 'arena-result' });
    const skipBtn = el('button', { class: 'btn', text: 'とばす ▶▶', onclick: (e) => { e.stopPropagation(); skip = true; next?.(); } });
    s.main.append(round, field, log, result, el('div', { class: 'arena-btns' }, skipBtn));
    log.addEventListener('click', () => next?.());
    field.addEventListener('click', () => next?.());
    const wait = (ms) => new Promise((r) => {
      if (skip) return r();
      next = () => { clearTimeout(timer); next = null; r(); };
      timer = setTimeout(() => next?.(), ms);
    });
    const hpBar = (hp, max) => {
      const ratio = Math.max(0, Math.min(1, hp / Math.max(1, max)));
      const bar = el('div', { class: `arena-hp ${ratio < 0.3 ? 'low' : ''}` }, el('i', { style: { width: `${Math.round(ratio * 100)}%` } }));
      return bar;
    };
    const setHp = (box, hp, max) => {
      const old = box.querySelector('.arena-hp');
      const bar = hpBar(hp, max);
      if (old) old.replaceWith(bar);
      else box.append(bar);
    };
    (async () => {
      for (const bt of bouts) {
        const A = card[bt.a], B = card[bt.b];
        if (!A || !B) continue;
        round.textContent = bt.final ? '決勝！' : bt.a === 0 ? '1回戦　第1試合' : '1回戦　第2試合';
        field.innerHTML = '';
        const ba = monBox({ ...A, odds: null }, bt.a, bt.a === data.pick ? 'pick' : '');
        const bb = monBox({ ...B, odds: null }, bt.b, bt.b === data.pick ? 'pick' : '');
        const max = bt.maxHp || [1, 1];
        setHp(ba, max[0], max[0]);
        setHp(bb, max[1], max[1]);
        field.append(ba, el('span', { class: 'arena-vs', text: 'VS' }), bb);
        log.textContent = `${A.name} 対 ${B.name}\n戦いがはじまった！`;
        game.audio?.sfx('encounter');
        await wait(1100);
        for (const ln of bt.lines || []) {
          if (skip) break;
          log.textContent = ln.text;
          if (Array.isArray(ln.hp)) {
            setHp(ba, ln.hp[0], max[0]);
            setHp(bb, ln.hp[1], max[1]);
          }
          game.audio?.sfx('hit');
          await wait(1000);
        }
        const W = card[bt.winner];
        (bt.winner === bt.a ? bb : ba).classList.add('out');
        if (bt.winner === bt.a) setHp(bb, 0, max[1]);
        else setHp(ba, 0, max[0]);
        log.textContent = `${W?.name || ''}の勝ち！`;
        await wait(1200);
      }
      // 優勝
      const C = card[data.champ];
      round.textContent = '優勝';
      field.innerHTML = '';
      if (C) field.append(el('span'), monBox({ ...C, odds: null }, data.champ, 'champ'), el('span'));
      const hit = data.champ === data.pick;
      result.className = `arena-result ${hit ? 'hit' : ''}`;
      result.textContent = hit ? `${C?.name || ''}の優勝！\n大当たり！ ${Number(data.win || 0).toLocaleString('ja-JP')}ゴールド！` : `${C?.name || ''}の優勝！\nはずれ…（${Number(data.bet || 0).toLocaleString('ja-JP')}Gかけた）`;
      log.textContent = '';
      log.style.display = 'none';
      skipBtn.remove();
      game.audio?.sfx(hit ? 'win' : 'buzz');
      done = true;
      menu = okMenu(game, 'とじる', close);
      s.root.append(menu.root);
      menu.focus();
    })();
  });
}

// ───────────── 王者のかべ ─────────────
export function arenaWallUI(game, data) {
  return new Promise((resolve) => {
    let menu;
    const close = () => {
      menu?.blur();
      s.remove();
      resolve();
    };
    const title = data?.offline ? '王者のかべ（このスマホのキャラ）' : `王者のかべ${data?.family ? `（${data.family}）` : ''}`;
    const s = shell(game, title, close);
    const ranks = Array.isArray(data?.ranks) ? data.ranks : [];
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    s.main.append(el('div', { class: 'arena-lead small muted', text: 'サファラ闘技場のランクを勝ちぬいた者の名前が、ここにきざまれる。' }));
    if (!rows.length) s.main.append(el('div', { class: 'muted', text: 'まだだれの名前もない。\n1番乗りをめざそう！' }));
    const list = el('div', { class: 'arena-wall-rows' });
    for (const r of rows) {
      const best = ranks.find((x) => x.rank === r.best);
      const label = best ? `${best.legend ? '伝説の部・' : ''}ランク${best.rank}` : '';
      const st = el('div', { class: 'st' });
      ranks.forEach((R, i) => {
        const n = r.ranks?.[i] || 0;
        st.append(el('span', { class: `${n > 0 ? 'on' : ''} ${R.legend ? 'lg' : ''}`, text: `${R.rank}${n > 0 ? '★' : ''}`, title: `${R.champ}${n > 1 ? `（${n}回）` : ''}` }));
      });
      const when = Number.isFinite(r.at) ? (() => { const d = new Date(r.at); return `${d.getMonth() + 1}月${d.getDate()}日`; })() : '';
      const withText = r.with?.length ? `${r.with.join('・')}といっしょ` : '';
      list.append(el('div', { class: `arena-wall-row ${r.id === data?.me?.id ? 'me' : ''}` },
        el('span', { class: 'nm', text: r.name }),
        el('span', { class: 'best', text: label }),
        st,
        (when || withText) ? el('span', { class: 'muted small', style: { gridColumn: '1 / -1' }, text: [when, withText].filter(Boolean).join('　') }) : null));
    }
    s.main.append(list);
    menu = okMenu(game, 'とじる', close);
    s.root.append(menu.root);
    menu.focus();
  });
}

js/client/ui/bank.js:
// 預かり所（ドラクエ風の カウンター）
//
// 「どんなご用でしょう？」→ お金を預ける／お金を引き出す／道具を預ける／道具を引き出す／やめる
//   お金: 100・1000・10000ゴールド・全部・金額を入れる → 「〇〇ゴールドですね。よろしいですか？」
//   道具: ふくろ（預かり所）の 品物を えらぶ → いくつ？ → 預ける（引き出す）
// 全滅すると 持っている お金は 半分に なるが、預けた お金は へらない
import { el, esc, askText } from './dom.js';
import { Counter } from './counter.js';
import { request } from './shop.js';
import { itemStats, rankText } from './info.js';
import { ITEMS } from '../../shared/data/items.js';
import { itemCount } from '../../shared/stats.js';
import { BANK_KINDS, BANK_STACK, BANK_GOLD_MAX } from '../../shared/data/facilities.js';
import { bankGold, bankCount, BAG_STACK } from '../../shared/world/bank.js';
import { boardIconURL } from '../render/boards.js';

const AGAIN = 'ほかにもご用はありますか？';

const bankItems = (game) => (game.me?.bank?.items || []).filter((e) => ITEMS[e?.id] && e.n > 0);

// みぎの まど: 預けている 物の ようす
function summary(game, hint = '') {
  const me = game.me;
  const box = el('div', { class: 'ct-item bank-sum' });
  box.append(
    el('div', { class: 'hd' }, el('span', { class: 'gold', text: '預けている物' })),
    el('div', { class: 'bank-row' }, el('span', { text: '預けているお金' }), el('span', { class: 'gold', text: `${bankGold(me)} G` })),
    el('div', { class: 'bank-row' }, el('span', { text: '持っているお金' }), el('span', { text: `${me.gold} G` })),
    el('div', { class: 'bank-row' }, el('span', { text: '預けている道具' }), el('span', { text: `${bankItems(game).length}／${BANK_KINDS}種類` })),
  );
  const list = bankItems(game);
  if (list.length) box.append(el('div', { class: 'small muted bank-list', text: list.slice(0, 12).map((e) => `${ITEMS[e.id].name}×${e.n}`).join('、') + (list.length > 12 ? '…' : '') }));
  box.append(el('div', { class: 'detail small', text: hint || '全滅すると、持っているお金は半分になってしまう。\n預かり所に預けたお金は、へらずに守られる。' }));
  return box;
}

const HINTS = {
  depositGold: '持っているお金を預ける。\n預けたお金は、全滅してもへらない。',
  withdrawGold: '預けたお金を引き出す。\nどこの預かり所でも引き出せる。',
  depositItem: 'ふくろの道具や装備を預ける。\n1種類99個まで、全部で60種類までお預かりできる。',
  withdrawItem: '預けた道具を、ふくろにもどす。',
  exit: '',
};

export async function bankUI(game, data) {
  const ct = new Counter(game, { title: data.name || '預かり所', keeper: data.keeper || '預かり所の人', icon: boardIconURL('bank') });
  let line = data.hello || 'ようこそ、預かり所へ。\nどんなご用でしょう？';
  while (!ct.closed) {
    await ct.say(line);
    ct.info(summary(game));
    const cmd = await ct.pick([
      { label: 'お金を預ける', value: 'depositGold' },
      { label: 'お金を引き出す', value: 'withdrawGold' },
      { label: '道具を預ける', value: 'depositItem' },
      { label: '道具を引き出す', value: 'withdrawItem' },
      { label: 'やめる', value: 'exit' },
    ], { back: null, onMove: (x) => ct.info(summary(game, HINTS[x?.value])) });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    if (cmd.value === 'depositGold' || cmd.value === 'withdrawGold') await goldFlow(game, ct, cmd.value === 'depositGold');
    else await itemLoop(game, ct, cmd.value === 'depositItem');
    line = AGAIN;
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(summary(game));
  await ct.say('またのおこしをお待ちしております。');
  await ct.tap(1400);
  ct.close();
}

// 全角の 数字も 読む
function parseAmount(t) {
  const s = String(t || '').replace(/[０-９]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0)).replace(/[^0-9]/g, '');
  return s ? Math.floor(Number(s)) : 0;
}

async function goldFlow(game, ct, deposit) {
  const me = game.me;
  const max = deposit ? Math.min(me.gold, BANK_GOLD_MAX - bankGold(me)) : Math.min(bankGold(me), BANK_GOLD_MAX - me.gold);
  if (max <= 0) {
    await ct.say(deposit ? (me.gold > 0 ? 'これ以上はお預かりできません。' : 'おや？お金を持っていないようですね。') : 'お預かりしているお金はありません。');
    await ct.tap(1800);
    return;
  }
  await ct.say(deposit ? `いくら預けますか？\n（持っているお金: ${me.gold}ゴールド）` : `いくら引き出しますか？\n（預けているお金: ${bankGold(me)}ゴールド）`);
  const opts = [100, 1000, 10000].filter((v) => v < max).map((v) => ({ label: `${v}ゴールド`, value: v }));
  opts.push({ label: `全部（${max}ゴールド）`, value: max }, { label: '金額を入れる', value: 'input' });
  const pick = await ct.pick(opts, { back: 'もどる', onMove: () => ct.info(summary(game, HINTS[deposit ? 'depositGold' : 'withdrawGold'])) });
  if (ct.closed || !pick) return;
  let amt = pick.value;
  if (amt === 'input') {
    const t = await askText(game.input, { title: deposit ? `いくら預ける？（${max}ゴールドまで）` : `いくら引き出す？（${max}ゴールドまで）`, placeholder: String(Math.min(max, 1000)), max: 8, numeric: true });
    if (ct.closed || t === null) return;
    amt = parseAmount(t);
    if (amt <= 0) return;
    if (amt > max) {
      await ct.say(deposit ? `おや？お預かりできるのは${max}ゴールドまでです。` : `おや？引き出せるのは${max}ゴールドまでです。`);
      await ct.tap(1800);
      return;
    }
  }
  const yes = await ct.ask(`${amt}ゴールドを${deposit ? '預け' : '引き出し'}ますね。\nよろしいですか？`);
  if (ct.closed || yes !== 0) return;
  const res = await request(game, { kind: 'bank', action: deposit ? 'depositGold' : 'withdrawGold', amount: amt });
  ct.updGold();
  ct.info(summary(game));
  if (res.ok) game.audio.sfx('item');
  await ct.say(res.text || 'おや？何かおかしいようですね。', { narr: !!res.ok });
  await ct.tap(2200);
}

// 品物の せつめい（持っている数・預けている数）
function itemBox(game, id) {
  const it = ITEMS[id];
  if (!it) return null;
  const box = el('div', { class: 'ct-item' });
  box.append(el('div', { class: 'hd' }, el('span', { class: 'gold', text: it.name }), el('span', { class: 'st', text: itemStats(id) }), el('span', { class: 'rk', text: rankText(id) })));
  box.append(el('div', { class: 'detail', text: it.desc || '' }));
  box.append(el('div', { class: 'bank-row small' }, el('span', { text: '持っている数' }), el('span', { text: `${itemCount(game.me, id)}` })));
  box.append(el('div', { class: 'bank-row small' }, el('span', { text: '預けている数' }), el('span', { class: 'gold', text: `${bankCount(game.me, id)}` })));
  return box;
}

async function itemLoop(game, ct, deposit) {
  const AGAIN_I = deposit ? 'ほかに預ける物はありますか？' : 'ほかに引き出す物はありますか？';
  let line = deposit ? '何を預けますか？' : '何を引き出しますか？';
  let idx = 0;
  while (!ct.closed) {
    const me = game.me;
    const list = deposit ? (me.items || []).filter((e) => ITEMS[e.id] && ITEMS[e.id].type !== 'key' && e.n > 0) : bankItems(game);
    if (!list.length) {
      ct.list(null);
      ct.info(summary(game));
      await ct.say(deposit ? 'おや？預けられる道具は持っていないようですね。' : 'お預かりしている道具はありません。');
      await ct.tap(1800);
      return;
    }
    await ct.say(line);
    const rows = list.map((e) => ({
      value: e.id,
      label: ITEMS[e.id].name,
      html: `${esc(ITEMS[e.id].name)}${ITEMS[e.id].type === 'mat' ? '<span class="tag mat">素材</span>' : ''}<span class="cnt">×${e.n}</span>`,
    }));
    const it = await ct.pick(rows, { start: Math.min(idx, rows.length - 1), onMove: (x) => ct.info(x ? itemBox(game, x.value) : null) });
    if (ct.closed || !it) return;
    idx = rows.findIndex((r) => r.value === it.value);
    const d = ITEMS[it.value];
    const have = deposit ? itemCount(me, it.value) : bankCount(me, it.value);
    const room = deposit ? BANK_STACK - bankCount(me, it.value) : BAG_STACK - itemCount(me, it.value);
    const max = Math.min(have, room);
    if (max <= 0) {
      await ct.say(deposit ? `${d.name}は、${BANK_STACK}個までしかお預かりできません。` : `${d.name}は、ふくろに${BAG_STACK}個までしか入りません。`);
      await ct.tap(1800);
      line = AGAIN_I;
      continue;
    }
    let qty = 1;
    if (max > 1) {
      qty = await ct.qty(`${d.name}ですね。\nいくつ${deposit ? '預け' : '引き出し'}ますか？`, max, null, `持っている数: ${itemCount(me, it.value)}　預けている数: ${bankCount(me, it.value)}`);
      if (!qty) {
        line = AGAIN_I;
        continue;
      }
    }
    const res = await request(game, { kind: 'bank', action: deposit ? 'depositItem' : 'withdrawItem', id: it.value, qty });
    if (ct.closed) return;
    if (!res.ok) {
      await ct.say(res.text || 'おや？何かおかしいようですね。');
      await ct.tap(1800);
      line = AGAIN_I;
      continue;
    }
    game.audio.sfx('item');
    ct.info(itemBox(game, it.value));
    await ct.say(res.text, { narr: true });
    await ct.tap(1600);
    line = AGAIN_I;
  }
}

