  .cs-table { justify-content: flex-start; }
  .cs-pay { row-gap: 0; }
  .cs-pay .syms img, .cs-pay .syms .any { width: 1.45em; height: 1.45em; }
  .cs-side .cs-tip { display: none; }
}
`;
  document.head.append(st);
}

