// 昼と 夜の 時計（ちずの よこの 小さな 丸。お日さま・お月さまが 空を うごく）
import { el, toast } from './dom.js';
import { makeCanvas, ctxOf } from '../render/pixel.js';
import { phaseOf, darkness, PHASE_NAMES, clockHour } from '../../shared/world/clock.js';

const S = 22;
const mixHex = (a, b, t) => {
  const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
  const ch = (sh) => Math.round(((pa >> sh) & 255) * (1 - t) + ((pb >> sh) & 255) * t);
  return `rgb(${ch(16)},${ch(8)},${ch(0)})`;
};

export class ClockBadge {
  constructor(game) {
    this.game = game;
    this.canvas = makeCanvas(S, S);
    this.el = el('div', { class: 'hud-clock', title: '時間' });
    this.el.append(this.canvas);
    this.last = { key: '', phase: null };
  }

  update() {
    const g = this.game;
    const sky = g.sky;
    if (!sky || !g.me) return;
    const frac = sky.frac();
    const phase = phaseOf(frac);
    // 夜に なった・夜が 明けた（フィールドに いる ときだけ 知らせる）
    if (this.last.phase && phase !== this.last.phase && g.state === 'field' && !g.busy && g.field.map?.kind === 'field') {
      if (phase === 'night') toast('日がしずんだ…\n夜の魔物が動き出した！');
      else if (this.last.phase === 'night') toast('夜が明けてきた！');
    }
    this.last.phase = phase;
    const key = `${Math.round(frac * 180)}`;
    if (key === this.last.key) return;
    this.last.key = key;
    // 何時ごろか（第4章の 日時計の とびらは 昼の 12時ごろ。11時〜13時）
    this.el.title = `今は${PHASE_NAMES[phase]}（${clockHour(frac)}時ごろ）`;
    this.el.dataset.phase = phase;
    this.draw(frac);
  }

  draw(frac) {
    const x = ctxOf(this.canvas);
    x.clearRect(0, 0, S, S);
    const dk = darkness(frac);
    const dusk = frac >= 0.58 && frac < 0.72 ? 1 - Math.abs(frac - 0.66) / 0.08 : 0;
    const dawn = frac >= 0.93 || frac < 0.06 ? 0.7 : 0;
    const R = 10, cx = 11, cy = 11;
    const inCircle = (px, py) => (px + 0.5 - cx) ** 2 + (py + 0.5 - cy) ** 2 <= R * R;
    // 空
    const top = mixHex('#5aa8f0', '#0b1236', dk), bot = mixHex('#b8e0ff', '#26336e', dk);
    for (let py = 0; py < S; py++) {
      for (let px = 0; px < S; px++) {
        if (!inCircle(px, py)) continue;
        let c = py < 8 ? top : bot;
        if (dusk > 0.2 && py >= 8 && py < 15) c = mixHex('#f08a4a', '#8a3a6a', dk * 0.8);
        if (dawn && py >= 9 && py < 15) c = '#c88ab8';
        x.fillStyle = c;
        x.fillRect(px, py, 1, 1);
      }
    }
    // 星（夜）
    if (dk > 0.5) {
      x.fillStyle = '#ffffff';
      for (const [sx, sy] of [[6, 5], [14, 4], [9, 8], [17, 9], [4, 10]]) x.fillRect(sx, sy, 1, 1);
    }
    // お日さま（明け方〜夕方）・お月さま（夜）が 空を わたる
    const sunUp = frac >= 0.95 || frac < 0.69;
    const t = sunUp ? ((frac + 0.05) % 1) / 0.74 : (frac - 0.69) / 0.26;
    const th = Math.PI * (1 - Math.max(0, Math.min(1, t)));
    const bx = Math.round(cx + Math.cos(th) * 7) - 1, by = Math.round(15 - Math.sin(th) * 9) - 1;
    if (sunUp) {
      x.fillStyle = '#ffd24a';
      x.fillRect(bx, by, 3, 3);
      x.fillStyle = '#fff6b0';
      x.fillRect(bx + 1, by - 1, 1, 1); x.fillRect(bx + 1, by + 3, 1, 1); x.fillRect(bx - 1, by + 1, 1, 1); x.fillRect(bx + 3, by + 1, 1, 1);
      x.fillStyle = '#ffffff';
      x.fillRect(bx, by, 1, 1);
    } else {
      x.fillStyle = '#fff6c8';
      x.fillRect(bx, by, 3, 3);
      x.fillRect(bx + 1, by - 1, 2, 1); x.fillRect(bx + 1, by + 3, 2, 1);
      x.fillStyle = mixHex('#5aa8f0', '#0b1236', dk);
      x.fillRect(bx + 2, by, 2, 3);
    }
    // 地面（おか）
    for (let py = 15; py < S; py++) {
      for (let px = 0; px < S; px++) {
        if (!inCircle(px, py)) continue;
        const hill = py > 15 + Math.round(Math.sin(px * 0.6) * 1.2);
        if (py < 16 && !hill) continue;
        x.fillStyle = mixHex(py < 17 ? '#5bab4b' : '#3f7d3a', '#1a2e3a', dk * 0.75);
        x.fillRect(px, py, 1, 1);
      }
    }
    // わく
    for (let py = 0; py < S; py++) {
      for (let px = 0; px < S; px++) {
        const d = Math.hypot(px + 0.5 - cx, py + 0.5 - cy);
        if (d > R - 0.6 && d <= R + 0.6) { x.fillStyle = '#fff6d8'; x.fillRect(px, py, 1, 1); } else if (d > R + 0.6 && d <= R + 1.6) { x.fillStyle = '#1b1330'; x.fillRect(px, py, 1, 1); }
      }
    }
  }
}

js/client/ui/counter.js:
// お店・教会の カウンター（ドラクエ風: 店の人の ことばと「はい／いいえ」で すすむ）
//
// まどの ならび:
//   うえ: 店の なまえ・所持金・✕閉じる
//   まんなか: ひだり＝品物や コマンド、みぎ＝せつめいと「だれが どう かわるか」
//   した: 店の人の ことば（はい／いいえ は ここの みぎに 出る）
import { el, ListMenu, esc } from './dom.js';
import { ITEMS, sellPrice } from '../../shared/data/items.js';
import { MONSTERS } from '../../shared/data/monsters.js';
// 第53回 D: 色ちがいの 仲間の 絵
import { colorMon } from '../../shared/data/variants.js';
import { jobLabel } from '../../shared/job-label.js';
import { computeStats, canEquipChar, itemCount } from '../../shared/stats.js';
import { itemStats, whoCanEquip, rankText } from './info.js';
import { faceURL } from '../field.js';
import { boardIconURL } from '../render/boards.js';
import { partyRows } from './hud.js';
import { shownEquip } from '../../shared/look-equip.js';
import { rareNameHtml } from './rarity.js';

const TYPE_MS = 18;

// 馬車の しるし（くらべの 行と「どなたが」の えらびし）
let cmpStyled = false;
function cmpStyles() {
  if (cmpStyled || typeof document === 'undefined') return;
  cmpStyled = true;
  document.head.append(el('style', { id: 'cmp-wagon-css', text: `
.menu .tag.wg { color: #9ad8ff; border-color: rgba(154, 216, 255, 0.6); }
.cmp-wg-h { color: #9ad8ff; font-size: var(--fs-small); margin-top: 0.3em; padding-bottom: 0.05em; border-bottom: 1px dashed rgba(154, 216, 255, 0.4); }
.cmp-row.wg .nm { color: #cfe9ff; }
.cmp-row.wg.dis .nm { color: #6d6c88; }
` }));
}
export const EQUIP_TYPES = ['weapon', 'armor', 'shield', 'head', 'acc'];

export class Counter {
  constructor(game, { title, keeper, icon, cls = '' }) {
    this.game = game;
    this.keeper = keeper;
    this.closed = false;
    this.waiters = new Set(); // とじた とき に とく まち
    this.hooks = new Set(); // とじた とき に よぶ かたづけ
    this.back = el('div', { class: 'modal-back', onclick: () => this.userClose() });
    this.goldEl = el('span', { class: 'ct-gold' });
    const titleEl = el('span', { class: 'gold ct-title' }, icon ? el('img', { class: 'ct-icon', src: icon, alt: '' }) : null, title);
    this.head = el('div', { class: 'win svc-head' }, titleEl, this.goldEl,
      el('button', { class: 'btn closebtn', text: '✕ 閉じる', 'aria-label': '閉じる', onclick: () => this.userClose() }));
    this.listBox = el('div', { class: 'win ct-list scroll' });
    this.infoBox = el('div', { class: 'win ct-info scroll' });
    this.speaker = el('div', { class: 'ct-speaker', text: keeper });
    this.text = el('div', { class: 'ct-text' });
    this.choiceBox = el('div', { class: 'ct-choice' });
    this.msg = el('div', { class: 'win ct-msg', onclick: () => this.skipType?.() }, this.speaker, this.text, this.choiceBox);
    this.root = el('div', { class: `panel counter-panel ${cls}` }, this.head, el('div', { class: 'ct-body' }, this.listBox, this.infoBox), this.msg);
    document.getElementById('ui').append(this.back, this.root);
    this.updGold();
  }

  updGold() {
    this.goldEl.textContent = `所持金 ${this.game.me?.gold ?? 0} G`;
  }

  // とじる ときの かたづけを とうろく（もどりちで けせる）
  hook(fn) {
    this.hooks.add(fn);
    return () => this.hooks.delete(fn);
  }

  // まつ（とじたら すぐ とける）
  wait(fn) {
    if (this.closed) return Promise.resolve(fn(null));
    return new Promise((resolve) => {
      const done = (v) => {
        if (!this.waiters.has(done)) return;
        this.waiters.delete(done);
        resolve(v);
      };
      this.waiters.add(done);
      fn(done);
    });
  }

  // 店の人の ことば（すこしずつ 出る。タップで すぐ ぜんぶ）。narr: 店の人で なく ナレーション
  say(text, { narr = false } = {}) {
    clearInterval(this.typing);
    this.speaker.hidden = narr;
    this.choiceBox.innerHTML = '';
    if (this.closed) return Promise.resolve();
    const chars = [...text];
    let i = 0;
    this.text.textContent = '';
    return this.wait((done) => {
      if (!done) return;
      // A・B で すぐに ぜんぶ 出す
      const h = { onNav: (a) => { if (a === 'a' || a === 'b') finish(); } };
      const unhook = this.hook(() => finish());
      const finish = () => {
        unhook();
        this.game.input.pop(h);
        clearInterval(this.typing);
        this.typing = null;
        this.skipType = null;
        this.text.textContent = text;
        done();
      };
      this.game.input.push(h);
      this.skipType = finish;
      this.typing = setInterval(() => {
        i += 2;
        this.text.textContent = chars.slice(0, i).join('');
        if (i % 6 === 0) this.game.audio.sfx('talk');
        if (i >= chars.length) finish();
      }, TYPE_MS);
    });
  }

  // ボタンか タップで すすむ（ms たつと じどうで すすむ）
  tap(ms = 0) {
    return this.wait((done) => {
      if (!done) return;
      const more = el('div', { class: 'ct-more', text: '▼' });
      this.msg.append(more);
      let t = null;
      const h = { onNav: (a) => { if (a === 'a' || a === 'b') end(); } };
      const unhook = this.hook(() => end());
      const end = () => {
        unhook();
        clearTimeout(t);
        this.game.input.pop(h);
        this.msg.removeEventListener('click', end);
        more.remove();
        done();
      };
      this.game.input.push(h);
      this.msg.addEventListener('click', end);
      if (ms) t = setTimeout(end, ms);
    });
  }

  // えらぶ（box: 'list' か 'info'）。もどる・B・とじる は null
  pick(items, { box = 'list', onMove, back = 'もどる', start = null } = {}) {
    return this.wait((done) => {
      if (!done) return null;
      const target = box === 'info' ? this.infoBox : this.listBox;
      const m = new ListMenu(this.game.input, {
        items,
        back,
        sound: (x) => this.game.audio.sfx(x),
        onMove: (it) => onMove?.(it),
        onSelect: (it) => finish(it),
        onCancel: () => finish(null),
      });
      if (start !== null && start >= 0 && start < items.length && !items[start].header) {
        m.idx = start;
        m.render();
      }
      const unhook = this.hook(() => finish(null));
      const finish = (v) => {
        unhook();
        m.blur();
        target.classList.remove('active');
        done(v);
      };
      target.innerHTML = '';
      target.classList.add('active');
      target.append(m.root);
      m.focus();
      // えらべる 行が 下の ほう（馬車の 仲間 など）でも 見える ように（スマホの 十字キーが 出て まどが ちぢんだ あとで）
      const raf = typeof requestAnimationFrame === 'function' ? requestAnimationFrame : (f) => setTimeout(f, 16);
      raf(() => raf(() => { if (m.active) m.scrollToSel(); }));
    });
  }

  // はい／いいえ など（ことばの みぎに 出る）。B は さいごの えらびし。とじたら -1
  async ask(text, options = ['はい', 'いいえ']) {
    await this.say(text);
    return this.wait((done) => {
      if (!done) return -1;
      const m = new ListMenu(this.game.input, {
        items: options.map((o, i) => ({ label: o, value: i })),
        back: null,
        sound: (x) => this.game.audio.sfx(x),
        onSelect: (it) => finish(it.value),
        onCancel: () => finish(options.length - 1),
      });
      const unhook = this.hook(() => finish(-1));
      const finish = (v) => {
        unhook();
        m.blur();
        this.choiceBox.innerHTML = '';
        done(v);
      };
      this.choiceBox.innerHTML = '';
      this.choiceBox.append(m.root);
      m.focus();
    }).then((v) => (v === null || v === undefined ? -1 : v));
  }

  // いくつ？（◀ ▶ か ＋－ で 1つずつ、▲ ▼ か ＋10・－10 で 10ずつ。第60回）。やめる・とじる は 0
  async qty(text, max, price, note = '') {
    await this.say(text);
    return this.wait((done) => {
      if (!done) return 0;
      let q = 1;
      const val = el('div', { class: 'ct-qty-val' });
      // price が null なら ねだんは 出さない（預かり所など）
      const upd = () => { val.textContent = price === null ? `◀ ${q}個 ▶` : `◀ ${q}個 ▶　${price * q}G`; };
      // 1つずつは はしで 一回り（今までどおり）、10ずつは 10・20・30… に そろえて、はしで 止まる
      const one = (d) => { q = d < 0 ? (q > 1 ? q - 1 : max) : (q < max ? q + 1 : 1); };
      const ten = (d) => { q = Math.max(1, Math.min(max, d > 0 ? Math.floor(q / 10) * 10 + 10 : Math.ceil(q / 10) * 10 - 10)); }; // 1 → 10 → 20 …
      const tap = (fn, d) => () => { fn(d); this.game.audio.sfx('cursor'); upd(); };
      const minus10 = el('button', { class: 'btn', text: '－10', onclick: tap(ten, -10) });
      const minus = el('button', { class: 'btn', text: '－', onclick: tap(one, -1) });
      const plus = el('button', { class: 'btn', text: '＋', onclick: tap(one, 1) });
      const plus10 = el('button', { class: 'btn', text: '＋10', onclick: tap(ten, 10) });
      const ok = el('button', { class: 'btn primary', text: '決定', onclick: () => finish(q) });
      const no = el('button', { class: 'btn', text: 'やめる', onclick: () => finish(0) });
      const h = {
        onNav: (a) => {
          if (a === 'a') return finish(q);
          if (a === 'b') return finish(0);
          if (a === 'left') one(-1);
          else if (a === 'right') one(1);
          else if (a === 'down') ten(-10);
          else if (a === 'up') ten(10);
          else return;
          this.game.audio.sfx('cursor');
          upd();
        },
      };
      const unhook = this.hook(() => finish(0));
      const finish = (v) => {
        unhook();
        this.game.input.pop(h);
        this.choiceBox.innerHTML = '';
        this.choiceBox.classList.remove('wide');
        if (v) this.game.audio.sfx('confirm');
        done(v);
      };
      upd();
      this.choiceBox.innerHTML = '';
      this.choiceBox.classList.add('wide');
      this.choiceBox.append(el('div', { class: 'ct-qty' }, val, note ? el('div', { class: 'small muted', text: note }) : null,
        el('div', { class: 'row' }, minus10, minus, plus, plus10),
        el('div', { class: 'row' }, no, ok)));
      this.game.input.push(h);
    }).then((v) => v || 0);
  }

  info(node) {
    this.infoBox.innerHTML = '';
    if (node) this.infoBox.append(node);
  }

  list(node) {
    this.listBox.innerHTML = '';
    if (node) this.listBox.append(node);
  }

  userClose() {
    if (this.closed) return;
    this.game.audio.sfx('cancel');
    this.close();
  }

  close() {
    if (this.closed) return;
    this.closed = true;
    clearInterval(this.typing);
    for (const f of [...this.hooks]) f();
    this.hooks.clear();
    for (const w of [...this.waiters]) w(null);
    this.back.remove();
    this.root.remove();
  }
}

// ───────────── だれが どう かわるか ─────────────
const STAT_NAMES = [['atk', '攻撃力'], ['dfn', '守備力'], ['agi', '素早さ'], ['mag', '攻撃魔力'], ['heal', '回復魔力'], ['maxHp', '最大HP'], ['maxMp', '最大MP']];

// じぶんと じぶんの なかま（いま パーティーに いる 仲間と、馬車の 仲間）。家族の キャラは じぶんで 買いものを する
export function myTeam(game) {
  const me = game.me;
  const out = [{ key: 'self', name: me.name, char: me, face: faceURL({ look: me.look, job: me.job, eq: shownEquip(me) }), kind: jobLabel(me.job, me) }];
  const add = (x, wagon) => {
    if (x.owner !== me.id || x.kind === 'family' || out.some((m) => m.key === x.key)) return;
    const char = {
      name: x.name, level: x.level, job: x.job, jobs: x.jobs || {}, equip: x.equip || {}, seeds: x.seeds || {},
      species: x.species || undefined, plus: x.plus || 0, bonus: x.bonus || undefined, color: x.color || undefined, gearFx: x.gearFx || undefined,
      feats: x.feats || undefined, // 第66回: 幻の職業の 記録（神殿で 仲間の 条件を 見る）
    };
    out.push({
      key: x.key, name: x.name, char, wagon,
      face: faceURL({ look: x.look, job: x.job, eq: shownEquip(x), mon: colorMon(x.species, x.color) }),
      kind: x.species ? MONSTERS[x.species]?.name || '' : jobLabel(x.job, x),
    });
  };
  for (const x of game.party?.supports || []) add(x, false);
  // 馬車の 仲間（リーダーの 馬車。ui/wagon.js）
  for (const x of game.party?.wagon || []) add(x, true);
  return out;
}

// パーティー みんな（ならびの じゅん）。家族の キャラも 見るだけ 出す（mine: false）
export function partyTeam(game) {
  const mine = new Map(myTeam(game).map((m) => [m.key, { ...m, mine: true }]));
  const p = game.party;
  const supports = new Map((p?.supports || []).map((x) => [x.key, x]));
  const other = (x, tag) => ({
    key: null, mine: false, tag, name: x.name,
    char: { name: x.name, level: x.level, job: x.job, jobs: x.jobs || {}, equip: x.equip || {}, seeds: x.seeds || {}, species: x.species || undefined, plus: x.plus || 0, color: x.color || undefined },
    realSt: x.st ? { ...x.st, maxHp: x.maxHp, maxMp: x.maxMp } : null,
  });
  const out = [];
  let humansDone = false;
  for (const r of partyRows(game)) {
    if (r.ref === 'self' || (!r.ref && r.player)) {
      if (humansDone) continue;
      humansDone = true;
      out.push(mine.get('self'));
      for (const m of p?.members || []) if (m.sid !== game.sid) out.push(other(m, '家族'));
    } else if (r.ref && mine.has(r.ref)) out.push(mine.get(r.ref));
    else if (r.ref && supports.has(r.ref)) out.push(other(supports.get(r.ref), supports.get(r.ref).family ? '家族' : '仲間'));
  }
  if (!humansDone) out.unshift(mine.get('self'));
  // 馬車の 仲間（しるし「馬車」。自分の 仲間は その場で 装備できる。家族の うつしは 見るだけ）
  for (const w of p?.wagon || []) {
    if (out.some((m) => m && m.key === w.key)) continue;
    if (mine.has(w.key)) out.push(mine.get(w.key));
    else out.push({ ...other(w, w.family ? '家族' : '仲間'), wagon: true });
  }
  return out.filter(Boolean);
}

// 1人ぶん: 装備したら どう なるか（realSt が あれば その 強さから の 変化）
export function compareOne(member, id) {
  const it = ITEMS[id];
  const c = member.char;
  const slot = it.type;
  const can = canEquipChar(c, id);
  const cur = c.equip?.[slot] || null;
  if (!can) return { ...member, can: false, same: false, cur };
  const before = computeStats(c);
  const after = computeStats({ ...c, equip: { ...(c.equip || {}), [slot]: id } });
  const base = (k) => (member.realSt && Number.isFinite(member.realSt[k]) ? member.realSt[k] : before[k]);
  const diffs = STAT_NAMES.map(([k, n]) => ({ k, n, b: base(k), a: base(k) + after[k] - before[k], d: after[k] - before[k] }));
  let mainKey = slot === 'weapon' ? 'atk' : 'dfn';
  if (slot === 'acc') mainKey = [...diffs].filter((x) => x.d).sort((p, q) => Math.abs(q.d) - Math.abs(p.d))[0]?.k || 'atk';
  const main = diffs.find((x) => x.k === mainKey);
  const extras = diffs.filter((x) => x.k !== mainKey && x.d);
  return { ...member, can: true, same: cur === id, cur, main, extras };
}

export function compareTeam(game, id) {
  return myTeam(game).map((m) => compareOne(m, id));
}

const arrow = (d) => (d > 0 ? `↑${d}` : d < 0 ? `↓${-d}` : '＝');
const arrowCls = (d) => (d > 0 ? 'up' : d < 0 ? 'down' : 'muted');

// パーティーの 1人ぶんの 行: 名前・変わる 強さ（装備できない 人は「装備できない（変化なし）」）
function compareRow(r) {
  const row = el('div', { class: `cmp-row ${r.can ? '' : 'dis'} ${r.wagon ? 'wg' : ''}` }, el('span', { class: 'nm', text: r.name }));
  if (!r.can) {
    row.append(el('span', { class: 'no', text: '装備できない（変化なし）' }));
    return row;
  }
  if (r.same) {
    row.append(el('span', { class: 'tag e', text: 'E' }), el('span', { class: 'muted', text: '装備している' }));
    return row;
  }
  // 1行に: 強さの 変化（大事な ものから）・今の 装備
  const sub = r.extras.map((x) => `${x.n}${x.d > 0 ? '+' : ''}${x.d}`);
  sub.push(`今:${r.cur ? ITEMS[r.cur].name : 'なし'}`);
  if (r.tag) sub.push(r.tag);
  row.append(el('span', { class: 'st' }, `${r.main.n} ${r.main.b}→${r.main.a}`, el('span', { class: 'cmp-sub', text: sub.join('　') })),
    el('span', { class: `ar ${arrowCls(r.main.d)}`, text: arrow(r.main.d) }));
  return row;
}

// 品物の せつめい ＋ みんなの くらべ
export function itemInfo(game, id, { sell = false } = {}) {
  const it = ITEMS[id];
  if (!it) return null;
  cmpStyles();
  const box = el('div', { class: 'ct-item' });
  box.append(el('div', { class: 'hd' }, el('span', { class: 'gold', html: rareNameHtml(id) }), el('span', { class: 'st', text: itemStats(id) }), el('span', { class: 'rk', text: rankText(id) })));
  box.append(el('div', { class: 'detail', text: it.desc || '' }));
  if (EQUIP_TYPES.includes(it.type) && !sell) {
    // パーティー 全員を ならびの じゅんに（装備できない 人も「変化なし」で 出す）
    const team = partyTeam(game).map((m) => compareOne(m, id));
    box.append(el('div', { class: 'cmp-head', text: '装備すると、こう変わる' }));
    // 馬車の 仲間は「馬車の仲間」の みだしの 下に
    const wagon = team.filter((r) => r.wagon);
    box.append(el('div', { class: 'cmp-list' }, ...team.filter((r) => !r.wagon).map(compareRow),
      wagon.length ? el('div', { class: 'cmp-wg-h', text: `馬車の仲間（${wagon.length}人）` }) : null, ...wagon.map(compareRow)));
    if (!team.some((r) => r.can)) box.append(el('div', { class: 'detail', text: whoCanEquip(id) }));
  } else {
    box.append(el('div', { class: 'small', text: `持っている数: ${itemCount(game.me, id)}` }));
    if (sell && sellPrice(id) <= 0) box.append(el('div', { class: 'small warn', text: 'これは引き取ってもらえない' }));
  }
  return box;
}

// 「どなたが 装備しますか？」の えらびし（馬車の 仲間には しるし）
export function whoItems(rows) {
  cmpStyles();
  return rows.map((r) => ({
    value: r.key,
    label: r.name,
    html: r.wagon ? `${esc(r.name)}<span class="tag wg">馬車</span>` : undefined,
    disabled: !r.can || r.same,
    right: !r.can ? '装備できない' : r.same ? 'E 装備している' : `${r.main.n} ${r.main.b}→${r.main.a} ${arrow(r.main.d)}`,
    rightCls: r.can && !r.same ? arrowCls(r.main.d) : '',
  }));
}

