// がめんの パーツを つくる どうぐ

import { kanaPad } from './kana-pad.js';

export function el(tag, attrs = {}, ...kids) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === undefined || v === null || v === false) continue;
    if (k === 'class') e.className = v;
    else if (k === 'text') e.textContent = v;
    else if (k === 'html') e.innerHTML = v;
    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);
    else if (k === 'style' && typeof v === 'object') Object.assign(e.style, v);
    else e.setAttribute(k, v === true ? '' : v);
  }
  for (const k of kids.flat()) {
    if (k === null || k === undefined || k === false) continue;
    e.append(k instanceof Node ? k : document.createTextNode(String(k)));
  }
  return e;
}

export const $ = (s, r = document) => r.querySelector(s);

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// ───────────── えらぶ メニュー ─────────────
// items: [{label, right, disabled, value, cls, title, header}]  header: えらべない みだし
// back: タッチでも もどれるように リストの うえに だす ボタンの もじ（null で なし）
export class ListMenu {
  // press: えらんだ ボタンを この ミリ秒 光らせてから すすむ（どれを おしたか わかるように）
  // start: はじめに カーソルを おく ばんごう（まえに えらんだ ところ など）
  // onSide: 1れつの リストで 左右を おした とき（タブを かえる・せつめいを スクロール など）。-1 か 1
  //   第35回: 2列・3列の リストでも、いちばん右の 列で 右・いちばん左の 列で 左 を おすと onSide（戦いの 技の タブ など）
  // fit: なまえは 1行で。入りきらない ときは 文字を 小さく して ぜんぶ 見せる（せまい ボタンの たたかいの コマンド）
  // tapConfirm: タップ（クリック）で ほかの 行を えらぶと カーソルと せつめい だけ うごく。えらんでいる 行を もう一度 おすと 決まる
  //   （戦いの 呪文・特技・道具。マウスは 先に カーソルが 合うので 1回で 決まる）
  // onLong: 行を 長おし（タッチ・マウス 0.5秒）した とき・Y（キーボードの Y・ゲームパッドの Y）を おした とき（第27回 戦いの お気に入り）。
  //   長おしでは その 行は 決まらない（はなした あとの クリックは すてる）
  // onY: Y（キーボードの Y・ゲームパッドの Y）を おした とき（長おしでは よばない。第35回 道具の ならべかえ）
  // onLR: L・R（キーボードの Q・E／PageUp・PageDown、ゲームパッドの L・R）を おした とき。-1 か 1（第69回 戦いの 技の タブ）
  constructor(input, { items = [], cols = 1, onSelect, onCancel, onMove, onSide, sound, className = '', back, press = 0, start = -1, fit = false, tapConfirm = false, onLong = null, onY = null, onLR = null } = {}) {
    this.input = input;
    this.onLR = onLR;
    this.onY = onY;
    this.tapConfirm = tapConfirm;
    this.onLong = onLong;
    this.fitText = fit;
    this.onSide = onSide || null;
    this.press = press;
    this.pressing = false;
    this.items = items;
    this.cols = cols;
    this.onSelect = onSelect;
    this.onCancel = onCancel;
    this.onMove = onMove;
    this.sound = sound;
    this.back = back === undefined ? (onCancel ? 'もどる' : null) : back;
    this.idx = Math.max(0, items.findIndex((i) => !i.disabled && !i.header));
    if (this.idx < 0) this.idx = 0;
    if (start >= 0 && start < items.length && !items[start].header) this.idx = start;
    this.root = el('ul', { class: `menu ${cols === 2 ? 'cols2' : ''} ${fit ? 'fit' : ''} ${className}`, role: 'listbox' });
    // pad: スマホでは 十字キーの パッドも 出す
    const self = this;
    // yKey: ゲームパッドの Y を「y」で とどける（長おしの かわり。onLong が ある ときだけ。input.js）
    // lr: ゲームパッドの L・R を「l」「r」で とどける（onLR が ある ときだけ。ほかでは L は 大鳥・竜、R は 走る。input.js）
    this.handler = { onNav: (a, rep) => this.nav(a, rep), pad: true, el: this.root, onGone: () => { this.active = false; }, get yKey() { return !!(self.onLong || self.onY); }, get lr() { return !!self.onLR; } };
    this.active = false;
    this.render();
  }

  setItems(items, keepIdx = true) {
    this.items = items;
    if (!keepIdx || this.idx >= items.length || items[this.idx]?.header) this.idx = Math.max(0, items.findIndex((i) => !i.disabled && !i.header));
    this.render();
  }

  render() {
    this.root.innerHTML = '';
    this.items.forEach((it, i) => {
      if (it.header) {
        this.root.append(el('li', { class: `hdr ${it.cls || ''}`, role: 'presentation', text: it.label }));
        return;
      }
      const li = el('li', {
        class: `item ${i === this.idx ? 'sel' : ''} ${it.disabled ? 'dis' : ''} ${it.cls || ''}`,
        role: 'option',
        title: it.title || null,
        onclick: (e) => {
          e.stopPropagation();
          const moved = this.idx !== i;
          this.idx = i;
          this.render();
          // タッチでは ホバーが ないので、タップで せつめいも かえる
          if (moved) this.onMove?.(this.items[i], i);
          if (moved && this.tapConfirm) {
            this.sound?.('cursor');
            return;
          }
          this.choose();
        },
        // 長おし（onLong の ある メニューだけ）
        // （あとから menu.onLong を 入れても 効く）
        onpointerdown: (e) => { if (this.onLong) this.longStart(e, i); },
        oncontextmenu: (e) => { if (this.onLong) e.preventDefault(); },
        // マウスを 本当に うごかした ときだけ カーソルを あわせる
        // （まどが マウスの 下に 出てきた だけで「いいえ」などに かわらないように）
        onmousemove: (e) => {
          if (!e.movementX && !e.movementY) return;
          if (this.idx !== i) {
            this.idx = i;
            this.updateSel();
            this.onMove?.(this.items[i], i);
          }
        },
      });
      const lab = el('span', { class: 'l' });
      if (it.html) lab.innerHTML = it.html;
      else lab.textContent = it.label;
      if (it.face) {
        lab.classList.add('wf');
        lab.prepend(el('img', { class: 'face', src: it.face, alt: '' }));
      }
      li.append(lab);
      if (it.right !== undefined && it.right !== null && it.right !== '') li.append(el('span', { class: `r ${it.rightCls || ''}`, text: it.right }));
      this.root.append(li);
    });
    // さいごに つけるが、みためは いちばん うえ（CSS の order）。ばんごうが ずれないように
    if (this.back && this.onCancel) {
      this.root.append(el('li', {
        class: 'backchip',
        role: 'button',
        'aria-label': this.back,
        text: this.back === '閉じる' ? '✕ 閉じる' : `← ${this.back}`,
        onclick: (e) => {
          e.stopPropagation();
          this.cancel();
        },
      }));
    }
    this.scrollToSel();
    // 画面に 出てから はかる（まだ ならんで いない ときは 0 なので つぎの コマで）。
    // 文字（ウェブフォント）の よみこみが おわったら もう一度（はばが かわる）
    if (this.fitText) {
      requestAnimationFrame(() => this.fit());
      document.fonts?.ready?.then(() => this.fit());
    }
  }

  // 入りきらない なまえの 文字を 小さく（いちばん 小さくて 0.6 ばい）。
  // scrollWidth は 1ピクセル みまんの はみ出しを 見のがすので、中みの はばを 小数まで はかる
  fit() {
    const range = document.createRange();
    for (const lab of this.root.querySelectorAll('.item > .l')) {
      lab.style.fontSize = '';
      const box = lab.clientWidth;
      if (!box) continue;
      const need = () => { range.selectNodeContents(lab); return range.getBoundingClientRect().width; };
      let k = 1;
      while (need() > box - 0.5 && k > 0.6) {
        k -= 0.05;
        lab.style.fontSize = `${k.toFixed(2)}em`;
      }
    }
  }

  // 長おしを はかる（0.5秒。ゆびが 10ピクセル より うごいた・はなした・スクロールに なった ときは やめる）
  longStart(e, i) {
    if (e.button > 0 || this.items[i]?.header) return;
    clearTimeout(this.longT);
    const x0 = e.clientX, y0 = e.clientY;
    const off = () => {
      removeEventListener('pointermove', move);
      removeEventListener('pointerup', stop);
      removeEventListener('pointercancel', stop);
    };
    const stop = () => { clearTimeout(this.longT); off(); };
    const move = (ev) => { if (Math.hypot(ev.clientX - x0, ev.clientY - y0) > 10) stop(); };
    addEventListener('pointermove', move);
    addEventListener('pointerup', stop);
    addEventListener('pointercancel', stop);
    this.longT = setTimeout(() => {
      off();
      if (!this.active || this.pressing || !this.root.isConnected) return;
      // はなした ときの クリックは すてる（行が 決まらない・出てきた まどの 中も おさない）
      const swallow = (ev) => { ev.stopPropagation(); ev.preventDefault(); };
      const release = () => {
        removeEventListener('pointerup', release);
        removeEventListener('pointercancel', release);
        addEventListener('click', swallow, { capture: true, once: true });
        setTimeout(() => removeEventListener('click', swallow, { capture: true }), 500);
      };
      addEventListener('pointerup', release);
      addEventListener('pointercancel', release);
      this.fireLong(i);
    }, ListMenu.LONG_MS);
  }

  fireLong(i = this.idx) {
    const it = this.items[i];
    if (!this.onLong || !it || it.header) return;
    if (this.idx !== i) {
      this.idx = i;
      this.updateSel();
      this.onMove?.(it, i);
    }
    this.sound?.('cursor');
    this.onLong(it, i);
  }

  cancel() {
    if (!this.onCancel) return;
    this.sound?.('cancel');
    this.onCancel();
  }

  updateSel() {
    [...this.root.children].forEach((li, i) => li.classList.toggle('sel', i === this.idx));
    this.scrollToSel();
  }

  scrollToSel() {
    const li = this.root.children[this.idx];
    if (!li || !li.scrollIntoView) return;
    // 上に 固定した 見出し（タブなど）が ある ときは、CSS の scroll-margin-top の ぶん 下に 出す
    // （ブラウザの nearest は 見出しの 下に かくれた 行を「見えている」と みなして うごかない）
    let mt = parseFloat(getComputedStyle(li).scrollMarginTop) || 0;
    // 上に はりつく「← もどる」（.backchip が position: sticky の とき）の 下にも かくれないように。
    // お店の 品物を 下から 上へ えらぶと、行が もどるの 下に もぐって 見えなかった
    const chip = this.root.lastElementChild;
    const sticky = chip?.classList.contains('backchip') && getComputedStyle(chip).position === 'sticky' ? chip : null;
    if (mt > 0 || sticky) {
      let sc = li.parentElement;
      while (sc && !(sc.scrollHeight > sc.clientHeight && /auto|scroll/.test(getComputedStyle(sc).overflowY))) sc = sc.parentElement;
      if (sc) {
        const top0 = sc.getBoundingClientRect().top + sc.clientTop;
        if (sticky) {
          // もどるの 下はし（下の すきまと かげ の ぶんも すこし あける）
          const cs = getComputedStyle(sticky);
          const gap = Math.max(parseFloat(cs.marginBottom) || 0, (parseFloat(cs.fontSize) || 16) * 0.4);
          mt = Math.max(mt, sticky.getBoundingClientRect().bottom - top0 + gap);
        }
        const top = li.getBoundingClientRect().top - top0;
        if (top < mt) {
          sc.scrollTop += top - mt;
          return;
        }
      }
    }
    li.scrollIntoView({ block: 'nearest' });
  }

  get current() { return this.items[this.idx]; }

  focus() {
    if (!this.active) {
      this.input.push(this.handler);
      this.active = true;
    }
    this.onMove?.(this.current, this.idx);
  }

  blur() {
    if (this.active) {
      this.input.pop(this.handler);
      this.active = false;
    }
  }

  // 画面で ならんでいる 列の 数（CSS で 2列・3列に している メニューも 十字キーで みたまま うごく）
  visualCols() {
    if (this.cols > 1) return this.cols;
    const lis = [...this.root.children].filter((li) => li.classList.contains('item'));
    if (lis.length < 2 || !lis[0].offsetParent) return 1;
    const top = lis[0].offsetTop;
    let n = 0;
    for (const li of lis) {
      if (Math.abs(li.offsetTop - top) > 3) break;
      n++;
    }
    return Math.max(1, n);
  }

  // 見出しの ある メニュー（たたかいの お気に入り＋ぜんぶ など）の 画面の ならび。
  // 見出しは 1行 まるごと つかうので「何こ ずつ」では うごけない。行（たかさ）ごとに まとめる
  gridRows() {
    const lis = [...this.root.children];
    const rows = [];
    this.items.forEach((it, i) => {
      const li = lis[i];
      if (it.header || !li?.offsetParent) return;
      const row = rows.find((r) => Math.abs(r.y - li.offsetTop) <= 3);
      const p = { i, x: li.offsetLeft + li.offsetWidth / 2 };
      if (row) row.list.push(p);
      else rows.push({ y: li.offsetTop, list: [p] });
    });
    rows.sort((p, q) => p.y - q.y);
    for (const r of rows) r.list.sort((p, q) => p.x - q.x);
    return rows;
  }

  // 今の 行が 画面の 行の 左はし（d=-1）・右はし（d=1）か。画面に 出ていない ときは cols で はかる
  atEdge(d, cols = this.cols) {
    if (cols <= 1 && !this.items.some((it) => it.header)) {
      // 1列（CSS で 2列・3列に 見える ものは 下の gridRows）
      const lis = [...this.root.children].filter((li) => li.classList.contains('item'));
      if (!lis[0]?.offsetParent) return true;
    }
    const rows = this.gridRows();
    const r = rows.find((row) => row.list.some((p) => p.i === this.idx));
    if (r) {
      const k = r.list.findIndex((p) => p.i === this.idx);
      return d < 0 ? k === 0 : k === r.list.length - 1;
    }
    if (cols <= 1) return true;
    const k = this.idx % cols;
    return d < 0 ? k === 0 : k === cols - 1 || this.idx === this.items.length - 1;
  }

  // 第69回: 見えている ひとまとまり（まどに 入る 行の 数 × 列の 数）ぶん 先・前へ（おなじ 列のまま。はしで とまる）
  //   スクロールが いる ときは まども その ぶん うごかす。もどりち: うごいたか
  pageTarget(d) {
    const n = this.items.length;
    if (!n || this.items.some((it) => it.header)) return this.idx;
    const cols = Math.max(1, this.visualCols());
    const rows = this.pageRows();
    const block = rows * cols;
    const col = this.idx % cols;
    let to = this.idx + d * block;
    if (to > n - 1) {
      // さいごの 行の おなじ 列（なければ さいごの 技）
      const lastRow = Math.floor((n - 1) / cols);
      to = Math.min(n - 1, lastRow * cols + col);
    } else if (to < 0) to = col;
    return to;
  }

  // まどに 入る 行の 数（1行の 高さで はかる。まだ 画面に ない ときは 1）
  pageRows() {
    const lis = [...this.root.children].filter((li) => li.classList.contains('item'));
    if (!lis[0]?.offsetParent) return 1;
    const top = lis[0].offsetTop;
    const next = lis.find((li) => li.offsetTop - top > 3);
    const pitch = next ? next.offsetTop - top : lis[0].offsetHeight;
    const h = this.root.clientHeight;
    return Math.max(1, Math.floor((h + 2) / Math.max(1, pitch)));
  }

  // 前・つぎの まとまりが あるか（スマホの ◀ ▶ を 出す。scroll: まどが スクロールする ほど 長いか）
  pageInfo() {
    const box = this.root;
    return {
      scroll: box.scrollHeight - box.clientHeight > 2,
      prev: this.pageTarget(-1) !== this.idx,
      next: this.pageTarget(1) !== this.idx,
    };
  }

  pageJump(d) {
    const to = this.pageTarget(d);
    if (to === this.idx) {
      this.sound?.('buzz');
      return false;
    }
    const box = this.root;
    const li0 = box.children[this.idx];
    const li1 = box.children[to];
    // まどを おなじ 行の かず ぶん うごかす（えらんだ 技が まどの おなじ 高さに 来る）
    if (li0 && li1) box.scrollTop += li1.offsetTop - li0.offsetTop;
    this.idx = to;
    this.sound?.('cursor');
    this.updateSel();
    this.onMove?.(this.current, this.idx);
    return true;
  }

  nav(a) {
    const n = this.items.length;
    // 第69回: L・R（onLR が ない メニューでは なにも しない）
    if (a === 'l' || a === 'r') {
      this.onLR?.(a === 'l' ? -1 : 1);
      return;
    }
    if (!n && a !== 'b') return;
    const arrow = ['up', 'down', 'left', 'right'].includes(a);
    const hdr = arrow && this.items.some((it) => it.header);
    const cols = arrow && !hdr ? this.visualCols() : this.cols;
    const go = (i) => {
      this.idx = i;
      this.sound?.('cursor');
      this.updateSel();
      this.onMove?.(this.current, this.idx);
    };
    const step = (d) => {
      let i = this.idx;
      for (let k = 0; k < n; k++) {
        i = (i + d + n) % n;
        if (!this.items[i].header) break;
      }
      go(i);
    };
    // 見出しの ある 2列・3列の メニュー: 上下は となりの 行の いちばん ちかい 場所へ、左右は となりへ（見出しは とばす）
    if (hdr) {
      const rows = this.gridRows();
      const r = rows.findIndex((row) => row.list.some((p) => p.i === this.idx));
      if (r >= 0 && rows.some((row) => row.list.length > 1)) {
        if ((a === 'left' || a === 'right') && this.onSide && this.atEdge(a === 'left' ? -1 : 1)) return this.onSide(a === 'left' ? -1 : 1);
        if (a === 'left' || a === 'right') return step(a === 'left' ? -1 : 1);
        const x = rows[r].list.find((p) => p.i === this.idx).x;
        const to = rows[(r + (a === 'up' ? -1 : 1) + rows.length) % rows.length].list;
        const best = to.reduce((p, q) => (Math.abs(q.x - x) < Math.abs(p.x - x) ? q : p));
        return go(best.i);
      }
    }
    // Y: onY が あれば そちら（道具の ならべかえ）。なければ 長おしと おなじ
    if (a === 'y' && this.onY) return this.onY(this.current, this.idx);
    // 列の はしで 左右 → onSide（タブを かえる など。1列の リストは いつも はし）
    if ((a === 'left' || a === 'right') && this.onSide && this.atEdge(a === 'left' ? -1 : 1, cols)) return this.onSide(a === 'left' ? -1 : 1);
    switch (a) {
      case 'up': step(-cols); break;
      case 'down': step(cols); break;
      case 'left': if (cols > 1) step(-1); else this.onSide?.(-1); break;
      case 'right': if (cols > 1) step(1); else this.onSide?.(1); break;
      case 'a': this.choose(); break;
      case 'b': this.cancel(); break;
      case 'y': this.fireLong(); break;
      default:
    }
  }

  choose() {
    const it = this.current;
    if (!it || this.pressing) return;
    if (it.disabled) {
      this.sound?.('buzz');
      return;
    }
    this.sound?.('confirm');
    if (!this.press) {
      this.onSelect?.(it, this.idx);
      return;
    }
    const idx = this.idx;
    const li = this.root.children[idx];
    li?.classList.add('press');
    this.pressing = true;
    setTimeout(() => {
      this.pressing = false;
      li?.classList.remove('press');
      // とじられた メニュー（たたかいが おわった など）では なにも しない
      if (this.active) this.onSelect?.(it, idx);
    }, this.press);
  }
}

// 長おしの 時間（ミリ秒）
ListMenu.LONG_MS = 500;

// ───────────── 十字キーで スクロール（第50回） ─────────────
// えらぶ 行が「もどる」だけの 長い 画面（強さの くわしい 画面・全員の 強さ）を、コントローラーの 上下・左右で 動かす。
// menu の 上下 → ys（たての まど）、左右 → xs（よこに はみ出す 表）。関数でも よい（その ときの まどを かえす）。
// スクロールできない ときは いつもの うごき
export function padScroll(menu, { ys = null, xs = null } = {}) {
  const nav = menu.nav.bind(menu);
  menu.nav = (a, rep) => {
    const d = { up: -1, down: 1, left: -1, right: 1 }[a];
    const tate = a === 'up' || a === 'down';
    const t = tate ? ys : xs;
    const box = typeof t === 'function' ? t() : t;
    if (d && box && scrollStep(box, tate, d, rep)) return;
    return nav(a, rep);
  };
  return menu;
}

// 1回ぶん スクロール（tate: たて・d: -1 か 1・rep: おしっぱなしの くりかえし）。スクロールできる まど なら true
export function scrollStep(box, tate, d, rep = false) {
  const max = tate ? box.scrollHeight - box.clientHeight : box.scrollWidth - box.clientWidth;
  if (!(max > 1)) return false;
  const k = tate ? 'scrollTop' : 'scrollLeft';
  const step = Math.max(40, (tate ? box.clientHeight : box.clientWidth) * (rep ? 0.25 : 0.4));
  box[k] = Math.max(0, Math.min(max, (box[k] || 0) + d * step));
  return true;
}

// el を ふくむ いちばん ちかい たてに スクロールする まど（なければ null）
export function scrollerOf(node) {
  for (let e = node; e && e !== document.body; e = e.parentElement) {
    if (e.scrollHeight > e.clientHeight + 1 && /auto|scroll/.test(getComputedStyle(e).overflowY)) return e;
  }
  return null;
}

// ───────────── おしらせ ─────────────
export function toast(text, ms = 3200) {
  const box = document.getElementById('toast');
  const t = el('div', { class: 'win t', text });
  box.append(t);
  setTimeout(() => t.remove(), ms);
}

// ───────────── かくにん・もじにゅうりょく ─────────────
export function askText(input, { title, placeholder = '', max = 40, initial = '', numeric = false } = {}) {
  return new Promise((resolve) => {
    const ui = document.getElementById('ui');
    // そとを タップしたら キーボードを しまうだけ（かいた もじは きえない）
    const back = el('div', { class: 'modal-back', onclick: () => field.blur() });
    const field = el('input', { class: 'textin', type: 'text', maxlength: String(max), placeholder, value: initial, inputmode: numeric ? 'numeric' : null, autocomplete: 'off', enterkeyhint: 'done' });
    const done = (v) => {
      input.pop(h);
      back.remove();
      box.remove();
      resolve(v);
    };
    const ok = el('button', { class: 'btn primary', text: '決定', onclick: () => done(field.value.trim()) });
    const cancel = el('button', { class: 'btn', text: 'やめる', onclick: () => done(null) });
    // コントローラーが つながって いる ときは そうさの ヒント（第50回）
    let pad = false;
    try { pad = [...(globalThis.navigator?.getGamepads?.() || [])].some((p) => p?.connected); } catch { /* */ }
    // 第62回: コントローラーの ときは 文字ばん（ui/kana-pad.js）。十字キーで えらんで A で 入れる（タップでも おせる）
    const sound = (x) => { try { globalThis.__game?.audio?.sfx?.(x); } catch { /* */ } };
    const kp = pad ? kanaPad(field, { max, numeric, onDone: (v) => done(v), sound }) : null;
    const box = el('div', { class: `win panel center-panel ${kp ? 'has-kpad' : ''}` },
      el('h2', { text: title }),
      field,
      kp ? el('div', { class: 'small muted', style: { marginTop: '0.3em' }, text: 'コントローラー：十字キーで選んでAで入れる・Bで1字けす' }) : null,
      kp ? kp.root : null,
      kp ? null : el('div', { class: 'row end', style: { marginTop: '0.6em' } }, cancel, ok));
    field.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.isComposing) done(field.value.trim());
      if (e.key === 'Escape') done(null);
    });
    // コントローラー: A で 決定（書いて いなければ はじめの 文字の まま）・B で やめる。
    // キーボードは 文字を 書く ので、ここには こない（input.js。Enter・Esc は 上の keydown）
    const h = { onNav: (a) => {
      if (kp) {
        // 書いている（キーボード）時の A・B は 今までどおり。文字ばんの 時は 文字ばんへ
        if (document.activeElement !== field || !['a', 'b'].includes(a)) { kp.nav(a); return; }
      }
      if (a === 'a') done(field.value.trim()); else if (a === 'b') done(null);
    } };
    input.push(h);
    ui.append(back, box);
    // 文字ばんの 時は 文字の 入力に しない（スマホの キーボードが 出て 文字ばんが かくれない ように）
    if (!kp) setTimeout(() => field.focus(), 30);
  });
}

// たしかめる まど。ほかの ポップアップ（宝の地図・道具の まど など。z-index 4〜7）の 上から 開く ことが あるので、
// いつも いちばん 前に 出す（第40回: 宝の地図の「地図を捨てる」で、たしかめる まどが うしろに かくれていた）
export const CONFIRM_Z = 20;
export function confirmBox(input, text, yes = 'はい', no = 'いいえ', sound) {
  return new Promise((resolve) => {
    const ui = document.getElementById('ui');
    const back = el('div', { class: 'modal-back', style: { zIndex: CONFIRM_Z }, onclick: () => finish(false) });
    const menu = new ListMenu(input, {
      items: [{ label: yes, value: true }, { label: no, value: false }],
      sound,
      back: null,
      onSelect: (it) => finish(it.value),
      onCancel: () => finish(false),
    });
    const box = el('div', { class: 'win panel center-panel', style: { width: 'min(90vw, 520px)', zIndex: CONFIRM_Z + 1, background: 'var(--win-solid)' } }, el('div', { style: { whiteSpace: 'pre-line', marginBottom: '0.5em' }, text }), menu.root);
    const finish = (v) => {
      menu.blur();
      back.remove();
      box.remove();
      resolve(v);
    };
    ui.append(back, box);
    menu.focus();
  });
}

// ゲージの バー
export function bar(ratio, cls = '') {
  const r = Math.max(0, Math.min(1, ratio || 0));
  return el('div', { class: `bar ${cls} ${r < 0.26 && !cls.includes('mp') ? 'low' : ''}` }, el('i', { style: { width: `${Math.round(r * 100)}%` } }));
}

js/client/ui/equip-compare.js:
// 第76回: 装備を えらぶ まどの「くらべる まど」（大きく。今の 装備と えらんでいる 物を、今の 強さ・もとの 強さで くらべる）
//   家族の ねがい: きたえると もともとの 武器の 強さが わからなくなる。きたえた 武具を 装備していても、
//   ほかの 武具を もとの 強さで くらべて「きたえたら どっちが 強いか」を 考えられるように。
//   数字は shared/gear-base.js の gearCompare（今＝きたえ・★・れん金を ふくむ・もと＝きたえる 前）
import { ITEMS } from '../../shared/data/items.js';
import { fxListOf, fxShort } from '../../shared/data/gear-fx.js';
import { gearCompare, forgeLabel } from '../../shared/gear-base.js';
import { esc } from './dom.js';
import { rareNameHtml } from './rarity.js';

const signed = (v) => (v > 0 ? `+${v}` : `${v}`);
const arrow = (d) => (d > 0 ? `<span class="eqc-d up">↑${d}</span>` : d < 0 ? `<span class="eqc-d down">↓${-d}</span>` : '<span class="eqc-d same">＝</span>');

// 装備の 下の ひとこと（きたえ・れん金）
function subLine(c, id) {
  if (!id) return '';
  const parts = [];
  const f = forgeLabel(id);
  parts.push(f ? `きたえ ${f}` : 'きたえていない');
  const fx = fxShort(fxListOf(c, id));
  if (fx) parts.push(`れん金 ${fx}`);
  return parts.join('・');
}

function card(c, cap, id, cls, none = 'なし') {
  const name = id && ITEMS[id] ? rareNameHtml(id) : esc(none);
  return `<div class="eqc-card ${cls}"><div class="eqc-cap">${esc(cap)}</div><div class="eqc-name">${name}</div><div class="eqc-sub">${esc(subLine(c, id))}</div></div>`;
}

// 同じだけ きたえると（今の 装備が きたえて あって、えらんでいる 物の ほうが 少ない 時）
function sameLine(cmp) {
  const s = cmp.cand?.same;
  if (!s) return '';
  if (s.none) return '<div class="eqc-same muted">この装備は店の品（★1）なので、きたえられない。</div>';
  const cap = s.capped ? `いちばん上の${esc(s.label)}まで` : `今の装備と同じだけ（${esc(cmp.cur.label)}）`;
  const vals = cmp.rows.filter((r) => r.candSame || r.curNow).map((r) => `<span class="eqc-sv">${esc(r.n)}${signed(r.candSame)}${arrow(r.dSame)}</span>`).join('');
  return `<div class="eqc-same"><div class="eqc-same-h">${cap}きたえると</div><div class="eqc-same-v">${vals}</div></div>`;
}

// c … 装備する 人・slot … 部位・cur … 今の 装備・cand … えらんでいる 物（null: 外す・undefined: やめる など）
export function equipCompareHtml(c, slot, cur, cand) {
  const off = cand === null;
  const pick = cand === undefined ? undefined : cand;
  const cmp = gearCompare(c, slot, cur || null, pick || null);
  const head = `<div class="eqc-head">${card(c, '今の装備', cur, 'cur')}<div class="eqc-to">→</div>${pick === undefined ? '<div class="eqc-card new empty"><div class="eqc-cap">選んだ物</div><div class="eqc-name muted">－</div></div>' : card(c, off ? '外すと' : 'これにすると', pick, 'new', '外す')}</div>`;
  if (pick === undefined) {
    const rows = cmp.rows.map((r) => `<tr><th>${esc(r.n)}</th><td>${signed(r.curNow)}</td><td class="eqc-b">${signed(r.curBase)}</td></tr>`).join('');
    return `${head}${rows ? `<table class="eqc-tbl one"><thead><tr><th></th><th>今</th><th class="eqc-b">もと</th></tr></thead><tbody>${rows}</tbody></table>` : ''}${legend()}`;
  }
  if (!cmp.rows.length) return `${head}<div class="eqc-none muted">強さは変わらない</div>${legend()}`;
  const rows = cmp.rows.map((r) => `<tr><th>${esc(r.n)}</th><td>${signed(r.curNow)}</td><td class="eqc-b">${signed(r.curBase)}</td>`
    + `<td class="eqc-new">${signed(r.candNow)}${arrow(r.dNow)}</td><td class="eqc-b eqc-new">${signed(r.candBase)}${arrow(r.dBase)}</td></tr>`).join('');
  const table = `<table class="eqc-tbl"><thead><tr><th></th><th colspan="2">今の装備</th><th colspan="2" class="eqc-new">${off ? '外すと' : 'これ'}</th></tr>`
    + '<tr class="eqc-sub-h"><th></th><th>今</th><th class="eqc-b">もと</th><th class="eqc-new">今</th><th class="eqc-b eqc-new">もと</th></tr></thead>'
    + `<tbody>${rows}</tbody></table>`;
  return `${head}${table}${sameLine(cmp)}${legend()}`;
}

function legend() {
  return '<div class="eqc-legend">今＝きたえ・★・れん金をふくむ強さ　もと＝きたえる前の強さ</div>';
}

js/client/ui/family-board.js:
// 第51回 B: 家族のけいじ板（メニューの「けいじ板」。サーバーの きまりは shared/world/family-board.js）
//   一覧は 見出しだけ（だれが・何を・いつ）。なりかた・覚えかたは その 行で「見る」を おした 時だけ 出る（ネタバレ よけ）
//   まだ 見ていない 知らせが あると メニューに ●（キャラごとの c.boardSeen）。
//   だれかの 知らせが のると、遊んでいる 人に 小さな 知らせ（戦いの 間は 戦いが おわってから）
import { el, esc, toast } from './dom.js';
import { boardRows, boardUnread, boardWhen } from '../../shared/world/family-board.js';

export const BOARD_TOAST = '家族のけいじ板に、\n新しい知らせがあります';
const TOAST_GAP = 8000;

function stateOf(g) {
  if (!g.fboard) g.fboard = { list: null, last: 0, opened: new Set(), onChange: null, toastWait: false, toastAt: 0 };
  return g.fboard;
}

// まだ 見ていない 知らせが あるか（メニューの ●）
export function hasBoardUnread(g) {
  return !!g?.me && boardUnread(stateOf(g).last, g.me);
}

// メニューが 開いていれば「家族のけいじ板」の ● を 今の ようすに
function markMenu(g) {
  const lm = g.menu?.root && g.menu.menu;
  if (!lm?.items) return;
  const on = hasBoardUnread(g);
  lm.items.forEach((it, i) => {
    if (it.value !== 'fboard') return;
    it.cls = on ? 'has-new' : '';
    lm.root.children[i]?.classList.toggle('has-new', on);
  });
}

// 小さな 知らせ（戦いの 間は おわってから。つづけて 来ても 1回）
function newToast(g) {
  const st = stateOf(g);
  if (st.toastWait || performance.now() - st.toastAt < TOAST_GAP) return;
  const show = () => {
    st.toastWait = false;
    if (!g.me) return;
    st.toastAt = performance.now();
    toast(BOARD_TOAST, 4000);
  };
  if (g.state === 'battle' || g.battleClosing) {
    st.toastWait = true;
    g.waitBattleClosed().then(show);
  } else show();
}

// フィールドに 入った 時（キャラが かわる ことも ある）: 前の 一覧は すてて、さいごの 時こくだけ 聞く
export function boardOnEnter(g) {
  const st = stateOf(g);
  st.list = null;
  st.opened = new Set();
  st.last = 0;
  g.net.send({ t: 'fboard', action: 'peek' });
}

// サーバーからの 知らせ（game.js の onMessage）
export function onBoardMsg(g, m) {
  const st = stateOf(g);
  switch (m.t) {
    case 'fboardLast':
      st.last = Math.max(st.last, m.last || 0);
      markMenu(g);
      return;
    case 'fboardList':
      st.list = Array.isArray(m.list) ? m.list : [];
      st.last = Math.max(st.last, m.last || 0);
      st.onChange?.();
      return;
    case 'fboardNew': {
      const e = m.entry;
      if (!e || !g.me) return;
      if (st.list && !st.list.some((x) => x.id === e.id)) st.list.unshift(e);
      // 自分の 知らせは ● も 知らせも 出さない（自分で 知っている）
      if (e.charId !== g.me.id) st.last = Math.max(st.last, e.at || 0);
      st.onChange?.();
      if (e.charId === g.me.id) return;
      markMenu(g);
      newToast(g);
      return;
    }
    default:
  }
}

// 行の 見た目
function rowItem(r) {
  const head = `<span class="fb-tag fb-${esc(r.kind)}">${esc(r.tag)}</span><span class="fb-tt">${esc(r.title)}</span>`;
  const when = `<span class="ln fb-when">${esc(boardWhen(r.at))}${r.mine ? '　（自分）' : ''}</span>`;
  const body = r.open ? `<span class="ln fb-detail">${esc(r.detail)}</span>` : '';
  return { html: head + when + body, value: r.id, right: r.open ? 'とじる' : '見る', rightCls: 'fb-see', cls: `fb-row ${r.unread ? 'unread' : ''} ${r.open ? 'open' : ''}` };
}

// menu: FieldMenu（mkSub・back を 使う）。active: えらべる 画面か（false は 右の 見本）
export function familyBoardView(menu, active) {
  addCss();
  const g = menu.game;
  const st = stateOf(g);
  const box = el('div', { class: 'items-view fboard-view' });
  if (!active) {
    const fresh = hasBoardUnread(g);
    box.append(el('div', { class: 'muted', text: `${fresh ? '新しい知らせがあります。\n' : ''}家族のだれかが転職したり、ひらめき技や合体技を覚えたりすると、ここに自動でのる。\nなりかた・覚えかたは「見る」をおした時だけ出る。` }));
    return box;
  }
  // ● は この 画面の 間は 出した まま（開いた 時の「見た 時こく」で 見る）
  const seenMe = { id: g.me?.id, boardSeen: g.me?.boardSeen || 0 };
  const m = menu.mkSub({
    items: [{ label: '読みこみ中…', value: null, disabled: true }],
    onSelect: (it) => {
      if (!it?.value) return;
      if (st.opened.has(it.value)) st.opened.delete(it.value);
      else st.opened.add(it.value);
      render();
    },
  });
  const render = () => {
    if (!st.list) return;
    const rows = boardRows(st.list, st.opened, seenMe);
    m.setItems(rows.length ? rows.map(rowItem) : [{ label: 'まだ知らせはない。', value: null, disabled: true }]);
  };
  // 見た ことに する（サーバーに 記録。キャラごと）
  const markSeen = () => {
    if (!st.last || !g.me || st.last <= (g.me.boardSeen || 0)) return;
    g.net.send({ t: 'fboard', action: 'seen', at: st.last });
    g.me.boardSeen = st.last;
    markMenu(g);
  };
  // ひとりモードでは 返事が すぐ 来る ことが ある（まだ 画面に 出す 前）ので、出た あとで はずれていたら やめる
  let born = true;
  setTimeout(() => { born = false; }, 0);
  st.onChange = () => {
    if (!born && !m.root.isConnected) { st.onChange = null; return; }
    render();
    markSeen();
  };
  if (st.list) {
    render();
    markSeen();
  }
  g.net.send({ t: 'fboard', action: 'list' });
  box.append(el('div', { class: 'small muted fb-help', text: '行を選ぶと、なりかた・覚えかたが出る（ネタバレ注意）' }), m.root);
  return box;
}

const CSS = `
.fboard-view > .fb-help { flex: none; margin-bottom: 0.3em; }
/* 行が高くなってもつぶれない */
.fboard-view .fb-row { flex: none; align-items: flex-start; }
.fboard-view .fb-row .l { white-space: normal; line-height: 1.35; min-width: 0; }
.fboard-view .fb-row .fb-tag { display: inline-block; font-size: 0.68em; padding: 0 0.4em; margin-right: 0.35em; border: 1px solid #8fa0d8; border-radius: 3px; color: #b8c4ff; vertical-align: 0.12em; white-space: nowrap; }
.fboard-view .fb-row .fb-hirameki { border-color: #6bd88f; color: #8ff0ae; }
.fboard-view .fb-row .fb-dual { border-color: #ff9a6b; color: #ffb48f; }
.fboard-view .fb-row .fb-phantom_reveal, .fboard-view .fb-row .fb-phantom_get { border-color: #ffd66b; color: #ffd66b; }
.fboard-view .fb-row .fb-when { display: block; color: var(--muted); font-size: 0.78em; }
.fboard-view .fb-row .fb-detail { display: block; margin-top: 0.3em; padding: 0.3em 0.45em; white-space: pre-line; font-size: 0.88em; color: var(--text); background: rgba(255, 255, 255, 0.06); border-left: 3px solid var(--accent); border-radius: 3px; }
.fboard-view .fb-row.unread .fb-tt::after { content: '●'; color: #ff6b6b; font-size: 0.7em; margin-left: 0.3em; vertical-align: 0.15em; }
.fboard-view .fb-row .r.fb-see { flex: none; margin-top: 0.1em; font-size: 0.78em; padding: 0.05em 0.5em; border: 1px solid rgba(255, 255, 255, 0.35); border-radius: 4px; color: var(--accent); white-space: nowrap; }
.fboard-view .fb-row.open .r.fb-see { color: var(--muted); }
`;
function addCss() {
  if (typeof document === 'undefined' || document.getElementById('fboard-css')) return;
  const st = document.createElement('style');
  st.id = 'fboard-css';
  st.textContent = CSS;
  document.head.append(st);
}

js/client/ui/follow-btn.js:
// 第58回: マルチプレイで リーダーに ついていく（自動追跡）の ボタン
// ・家族と パーティーを くんでいて、自分が リーダーで ない ときだけ、フィールドの ボタンの 列に「自動追跡」
// ・おすと オン・オフ（メニューの「仲間」の「リーダーについていく」と おなじ。game.follow）
import { el, toast } from './dom.js';

// 自動追跡の ボタンの 見た目
const CSS = `
.hud-btn.hud-follow { color: #cfd8ff; border-color: #7a8ad8; }
.hud-btn.hud-follow.on { color: #10203a; background: #9fe0ff; border-color: #ffffff; font-weight: bold; }
`;

export const followShown = (g) => g.state === 'field' && !!g.party && (g.party.members?.length || 0) > 1 && g.party.leader !== g.sid;
export const followLabel = (on) => (on ? '自動追跡：オン' : '自動追跡：オフ');

export class FollowButton {
  constructor(game) {
    this.game = game;
    if (!document.getElementById('follow-btn-css')) document.head.append(el('style', { id: 'follow-btn-css', text: CSS }));
    this.btn = el('button', { class: 'win hud-btn hud-follow', text: followLabel(false), onclick: () => this.toggle() });
    this.btn.hidden = true;
    game.hud.btns.append(this.btn);
  }

  // まいフレーム（game.js の frame）
  update() {
    const g = this.game;
    const show = followShown(g);
    if (show) {
      const on = !!g.follow;
      const label = followLabel(on);
      if (this.btn.textContent !== label) this.btn.textContent = label;
      this.btn.classList.toggle('on', on);
    }
    if (this.btn.hidden === show) this.btn.hidden = !show;
  }

  toggle() {
    const g = this.game;
    if (!followShown(g) || g.busy || g.menuOpen) return;
    g.follow = !g.follow;
    g.audio?.sfx?.(g.follow ? 'confirm' : 'cancel');
    toast(g.follow ? 'リーダーについていきます（自動追跡：オン）' : '自分で歩きます（自動追跡：オフ）');
    this.update();
  }
}

js/client/ui/forge.js:
// ふしぎなかじ屋（ドラクエ風の カウンター）
//
// 「今日は何をする？」→ 作る／きたえる／やめる
//   作る:     レシピを えらぶ（みぎに 素材の 数・みんなの 強さが どう かわるか）→「〇〇と〇〇ゴールドがいる。作るか？」
//             →「すぐに装備するか？」→「だれが装備する？」
//   きたえる: 装備を えらぶ（E は 装備している 物）→ みぎに きたえる 前→あとの 強さと 素材
//             第35回: 店で 買える 装備（★1）は きたえられない ので 一覧に 出さない。
//             ただし 生まれ変わりの もとに なる 店の 武器（銅の剣 など 5つ）は 出して、れん金がまの レシピを 見せる
//             （第36回: かくさない。知らない 人には、本だな・メモ・親方で わかると 出す）
//             →「〇〇にきたえるには〇〇がいる。きたえるか？」→ カン！カン！カン！
import { sourcesFlow } from './sources.js';
import { salvageOf } from '../../shared/data/salvage.js';
import { el, esc } from './dom.js';
import { Counter, compareTeam, itemInfo, whoItems, myTeam } from './counter.js';
import { request } from './shop.js';
import { rankText } from './info.js';
import { rareNameHtml } from './rarity.js';
import { ITEMS } from '../../shared/data/items.js';
import { UPGRADE_TYPES, UPGRADE_MAX } from '../../shared/data/items-forge.js';
import { recipeOf, upgradeCost, lackOf, canUpgrade, maxPlus, isShopForge } from '../../shared/data/forge.js';
import { REBIRTH_START } from '../../shared/data/items-alchemy.js';
import { hasPot, knowsRecipe, insText } from '../../shared/data/alchemy.js';
import { bindAlchemy } from './alchemy.js';
import { computeStats, itemCount } from '../../shared/stats.js';
import { boardIconURL } from '../render/boards.js';

const BONUS_NAMES = { str: '力', def: '身の守り', agi: '素早さ', mag: '攻撃魔力', heal: '回復魔力', hp: '最大HP', mp: '最大MP' };

const HINTS = {
  craft: '素材とゴールドで、店では売っていない装備を作る。\n物語が進むと、作れる物がふえる。',
  upgrade: `店では買えない装備（★2から）をきたえる。1回ごとに攻撃力や守備力が上がる。\n店の品（★1）は、きたえられない。\nきたえられる回数は、装備のランクで決まる。（最大+${UPGRADE_MAX}）\n+3からは星のかけらもいる。\nれん金がまで同じ装備を2つ合わせると、回数がふえる。\n上限まできたえると、限界の石で限界とっぱ（★3まで）。`,
  salvage: 'いらない装備（★2から）を分解して、素材にもどす。\nきたえる時に使う素材が手に入る。\n店の品（★1）・ボスの品・装備している物は分解できない。',
  exit: '',
};

const hint = (text) => (text ? el('div', { class: 'detail', text }) : null);

// 生まれ変わりの もとに なる 店の 武器（銅の剣 など。items-alchemy.js の REBIRTH_START）
const REBIRTH_FROM = new Set(REBIRTH_START.map((x) => x.from));
const isRebirthSeed = (id) => REBIRTH_FROM.has(ITEMS[id]?.base || id);
const seedOf = (id) => REBIRTH_START.find((x) => x.from === (ITEMS[id]?.base || id));

// 「鉄のかけら2個・星のかけら1個」
export function matsText(mats) {
  return mats.map(([id, n]) => `${ITEMS[id]?.name || id}${n}個`).join('・');
}

// 必要な 素材と ゴールド（いる数・持っている数。たりない ものは 赤）
function costBlock(game, cost) {
  const me = game.me;
  const box = el('div', { class: 'forge-cost' },
    el('span', { class: 'hd', text: '必要な物' }), el('span', { class: 'hd n', text: 'いる' }), el('span', { class: 'hd n', text: '持っている' }));
  const row = (name, need, have, ok) => box.append(
    el('span', { class: 'nm', text: name }), el('span', { class: 'n', text: need }), el('span', { class: `n ${ok ? 'ok' : 'ng'}`, text: have }));
  for (const [id, n] of cost.mats) {
    const have = itemCount(me, id);
    row(ITEMS[id]?.name || id, `${n}`, `${have}`, have >= n);
  }
  row('ゴールド', `${cost.gold}`, `${me.gold}`, me.gold >= cost.gold);
  return box;
}

export async function forgeUI(game, data) {
  bindAlchemy(game);
  const ct = new Counter(game, { title: data.name || 'ふしぎなかじ屋', keeper: data.keeper || 'かじ屋', icon: boardIconURL('smith') });
  let line = data.hello || 'ここはふしぎなかじ屋だ。\n今日は何をする？';
  // 第32回: れん金がまを もらう・れん金の コツを 教わる（world/alchemy.js の forgePotGift）
  if (data.gift) {
    await ct.say(data.gift);
    await ct.tap();
    game.audio.sfx('key');
    await ct.say(data.giftNote, { narr: true });
    await ct.tap();
  } else if (data.tip) {
    await ct.say(data.tip);
    await ct.tap();
  }
  while (!ct.closed) {
    await ct.say(line);
    ct.info(hint(HINTS.craft));
    const cmd = await ct.pick([
      { label: '作る', value: 'craft' },
      { label: 'きたえる', value: 'upgrade' },
      { label: '分解する', value: 'salvage' },
      { label: 'やめる', value: 'exit' },
    ], { back: null, onMove: (x) => ct.info(hint(HINTS[x?.value])) });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    if (cmd.value === 'craft') await craftLoop(game, ct, data);
    else if (cmd.value === 'salvage') await salvageLoop(game, ct);
    else await upgradeLoop(game, ct);
    line = 'ほかに何かするか？';
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(null);
  await ct.say('またいつでも来てくれ。\n良い素材が手に入ったら、見せてくれよ。');
  await ct.tap(1400);
  ct.close();
}

// ───────────── 第64回 ⑥b: 分解する（ふくろの 装備 → 素材。data/salvage.js）─────────────
async function salvageLoop(game, ct) {
  let line = 'どれを分解する？\n（ふくろの装備だけ。店の品は分解できない）';
  let idx = 0;
  while (!ct.closed) {
    const list = (game.me.items || []).filter((e) => e.n > 0 && salvageOf(e.id));
    if (!list.length) {
      ct.list(null);
      ct.info(null);
      await ct.say('おや？分解できる装備を持っていないようだな。\n店の品（★1）や、装備している物は分解できないんだ。');
      await ct.tap(2000);
      return;
    }
    await ct.say(line);
    const rows = list.map((e, i) => ({ value: i, label: ITEMS[e.id].name, html: `${rareNameHtml(e.id)}${e.n > 1 ? `<span class="cnt">×${e.n}</span>` : ''}`, right: '分解' }));
    const pick = await ct.pick(rows, {
      start: Math.min(idx, rows.length - 1),
      onMove: (x) => ct.info(x ? hint(`分解すると：${matsText(salvageOf(list[x.value].id))}\n（${ITEMS[list[x.value].id].name}はなくなる）`) : null),
    });
    if (ct.closed || !pick) return;
    idx = pick.value;
    const id = list[pick.value].id;
    const yes = await ct.ask(`${ITEMS[id].name}を分解すると、\n${matsText(salvageOf(id))}になる。\n分解するか？`);
    if (ct.closed) return;
    if (yes !== 0) { line = 'ほかに分解する物はあるか？'; continue; }
    game.audio.sfx('hammer');
    const res = await request(game, { kind: 'forge', action: 'salvage', id });
    await ct.say(res.text || '');
    await ct.tap(1600);
    line = 'ほかに分解する物はあるか？';
  }
}

// ───────────── 作る ─────────────
function recipeBox(game, id) {
  const r = recipeOf(id);
  const box = itemInfo(game, id);
  if (!box || !r) return box;
  box.insertBefore(costBlock(game, r), box.children[2] || null);
  return box;
}

async function craftLoop(game, ct, data) {
  let line = '何を作る？';
  let idx = 0;
  while (!ct.closed) {
    await ct.say(line);
    const rows = (data.recipes || []).filter((id) => ITEMS[id] && recipeOf(id)).map((id) => {
      const lack = lackOf(game.me, recipeOf(id));
      return {
        value: id,
        label: ITEMS[id].name,
        html: `${esc(ITEMS[id].name)}${lack.ok ? '<span class="tag up">作れる</span>' : ''}`,
        right: `${recipeOf(id).gold}G`,
        rightCls: lack.ok ? 'gold' : 'dis',
      };
    });
    if (data.locked) rows.push({ value: '__locked', html: `<span class="muted">？？？　×${data.locked}</span>`, right: 'ひみつ', disabled: true });
    const pick = await ct.pick(rows, {
      start: idx,
      onMove: (x) => ct.info(x?.value === '__locked' ? hint('物語が進むと、作れる物がふえる。\n新しい素材を見つけたら、また来てくれ。') : x ? recipeBox(game, x.value) : null),
    });
    if (ct.closed || !pick) return;
    idx = rows.findIndex((r) => r.value === pick.value);
    line = await craftOne(game, ct, pick.value);
  }
}

async function craftOne(game, ct, id) {
  const it = ITEMS[id];
  const r = recipeOf(id);
  const AGAIN = 'ほかに作る物はあるか？';
  const lack = lackOf(game.me, r);
  if (lack.mats.length) {
    await ct.say(`${it.name}を作るには、\n${matsText(r.mats)}がいる。\n素材が足りないようだな。`);
    await ct.tap(2400);
    await sourcesFlow(game, ct, lack.mats); // 第64回 ⑥a: 入手先
    return AGAIN;
  }
  if (lack.gold) {
    await ct.say(`${it.name}を作るには、${r.gold}ゴールドいる。\nおや？ゴールドが足りないようだな。`);
    await ct.tap(2000);
    return AGAIN;
  }
  const yes = await ct.ask(`${it.name}を作るには、\n${matsText(r.mats)}と${r.gold}ゴールドがいる。\n作るか？`);
  if (ct.closed || yes !== 0) return AGAIN;
  let who = null;
  const rows = compareTeam(game, id);
  if (rows.some((x) => x.can && !x.same)) {
    const now = await ct.ask('完成したら、すぐに装備するか？');
    if (ct.closed) return AGAIN;
    if (now === 0) {
      await ct.say('だれが装備する？');
      const w = await ct.pick(whoItems(rows), { box: 'info', back: '装備しない' });
      if (w) who = w.value;
    }
  }
  if (ct.closed) return AGAIN;
  game.audio.sfx('hammer');
  const res = await request(game, { kind: 'forge', action: 'craft', id, who });
  ct.updGold();
  if (!res.ok) {
    await ct.say(res.text || 'おや？何かおかしいようだな。');
    await ct.tap(2000);
    return AGAIN;
  }
  setTimeout(() => game.audio.sfx(who ? 'buff' : 'item'), 700);
  ct.info(recipeBox(game, id));
  await ct.say(res.text, { narr: true });
  await ct.tap(2600);
  return `いい仕上がりだろう？\n${AGAIN}`;
}

// ───────────── きたえる ─────────────
// きたえられる 装備（装備している 物 → ふくろの 物）。まものの 仲間が 武器や よろいを 装備しても おなじ
function candidates(game) {
  const out = [];
  // 店で 買える 装備（★1）は きたえられない ので 出さない。生まれ変わりの もとの 店の 武器だけ（seed）出す（第35回）
  const shown = (id) => !isShopForge(id) || isRebirthSeed(id);
  for (const m of myTeam(game)) {
    for (const slot of UPGRADE_TYPES) {
      const id = m.char.equip?.[slot];
      if (id && ITEMS[id] && shown(id)) out.push({ id, who: m.key, whoName: m.name, char: m.char, seed: isShopForge(id) });
    }
  }
  for (const e of game.me.items || []) {
    if (e.n > 0 && UPGRADE_TYPES.includes(ITEMS[e.id]?.type) && shown(e.id)) out.push({ id: e.id, who: null, n: e.n, seed: isShopForge(e.id) });
  }
  return out;
}

function statLines(id) {
  const it = ITEMS[id];
  const out = new Map();
  if (it.type === 'weapon') out.set('atk', ['攻撃力', it.atk || 0]);
  else out.set('def', ['守備力', it.def || 0]);
  for (const [k, v] of Object.entries(it.bonus || {})) out.set(k, [BONUS_NAMES[k] || k, v]);
  return out;
}

const signed = (k, v) => (k === 'atk' || k === 'def' ? `${v}` : `${v > 0 ? '+' : ''}${v}`);

// きたえる 前 → あと
function upgradeBox(game, cand) {
  const it = ITEMS[cand.id];
  const cost = upgradeCost(cand.id);
  const box = el('div', { class: 'ct-item forge-up' });
  // 第35回: 生まれ変わりの もとに なる 店の 武器 … きたえられないが、れん金がまで 生まれ変わる（第36回: かくさない）
  if (cand.seed) {
    const x = seedOf(cand.id);
    const to = ITEMS[x?.to]?.name || '？？？';
    box.append(el('div', { class: 'hd' }, el('span', { class: 'gold', text: `${it.name} → ${to}` }), el('span', { class: 'rk', text: rankText(cand.id) })));
    if (cand.who) box.append(el('div', { class: 'small muted', text: `${cand.whoName}が装備している` }));
    const how = !hasPot(game.me)
      ? 'カモメ港へ行くと、どこかのかじ屋で「れん金がま」をもらえる。\nかまに入れると、生まれ変わるぞ。'
      : knowsRecipe(game.me, x.id)
        ? `れん金がまに「${insText([x.from, x.mat, 'star_shard'])}」を入れると、${to}に生まれ変わる！`
        : 'れん金がまで、星のかけらと何かを合わせると、生まれ変わる。\n作り方は、本だな・れん金のメモ・かじ屋の親方からわかるぞ。';
    box.append(el('div', { class: 'small forge-reborn forge-seed', style: { whiteSpace: 'pre-line' }, text: `店の品なので、きたえられない。\n…でも、${it.name}が、かすかに光っている。\n${how}` }));
    return box;
  }
  // 生まれ変わる: 何に なるかも 見せる（第36回: かくさない）
  const title = cost ? `${it.name} → ${ITEMS[cost.to]?.name || '？？？'}` : it.name;
  box.append(el('div', { class: 'hd' }, el('span', { class: 'gold', text: title }), el('span', { class: 'rk', text: rankText(cand.id) })));
  if (!cost) {
    if (cand.who) box.append(el('div', { class: 'small muted', text: `${cand.whoName}が装備している` }));
    box.append(el('div', { class: 'detail', text: UPGRADE_TYPES.includes(it.type) ? `これ以上はきたえられない。\n（この装備は+${maxPlus(cand.id)}まで。ランクが高い装備ほど、たくさんきたえられる。れん金がまで同じ装備を2つ合わせると、ふやせる）` : 'これはきたえられない。' }));
    return box;
  }
  if (cost.reborn) {
    box.append(el('div', { class: 'detail forge-reborn', text: `${it.name}が、ふしぎな光をはなっている…。\nもう1回きたえると、${ITEMS[cost.to]?.name || '新しい武器'}に生まれ変わる！` }));
    box.append(costBlock(game, cost));
    return box;
  }
  // きたえられる 回数（ランクで きまる ＋ れん金で ふやした 回数）。生まれ変わる 武器は 上限を こえても きたえられる
  // 第65回: 上限まで きたえて ある → 限界とっぱ（★1〜★3）
  if (cost.limit) box.append(el('div', { class: 'detail forge-reborn', text: `上限（+${it.plus || 0}）まで。限界の石で★${cost.lb}にできるぞ！\n${cost.lb === 1 ? '★1からは、れん金の効果を2つつけられる。' : 'もう1回きたえたぶん強くなる。'}` }));
  else box.append(el('div', { class: 'small muted forge-limit', text: cost.over
    ? `この装備は+${maxPlus(cand.id)}まで…のはずだが、\nまだきたえられそうだ。（今は+${it.plus || 0}）`
    : `この装備は+${maxPlus(cand.id)}まできたえられる。（今は+${it.plus || 0}）` }));
  const before = statLines(cand.id);
  const after = statLines(cost.to);
  const tbl = el('div', { class: 'forge-stats' });
  for (const k of new Set([...before.keys(), ...after.keys()])) {
    const [name] = before.get(k) || after.get(k);
    const a = after.get(k)?.[1] ?? 0;
    const bv = before.get(k)?.[1] ?? 0;
    tbl.append(el('div', { class: `forge-stat ${a !== bv ? 'chg' : ''}` },
      el('span', { class: 'nm', text: name }), el('span', { class: 'b', text: signed(k, bv) }), el('span', { class: 'ar', text: '→' }),
      el('span', { class: `a ${a > bv ? 'up' : ''}`, text: signed(k, a) })));
  }
  box.append(tbl);
  // 装備している 人の 強さ
  if (cand.char) {
    const slot = it.type;
    const s0 = computeStats(cand.char);
    const s1 = computeStats({ ...cand.char, equip: { ...(cand.char.equip || {}), [slot]: cost.to } });
    const key = slot === 'weapon' ? 'atk' : 'dfn';
    box.append(el('div', { class: 'small forge-who' }, `E ${cand.whoName}の${slot === 'weapon' ? '攻撃力' : '守備力'} ${s0[key]} → `,
      el('span', { class: 'up', text: `${s1[key]}` })));
  }
  box.append(costBlock(game, cost));
  return box;
}

// ───────────── 生まれ変わり ─────────────
const REBORN_CSS = `
.reborn-flash { position: fixed; inset: 0; z-index: 30; pointer-events: none; background: radial-gradient(circle at 50% 45%, #fff 0%, #fff6c8 30%, rgba(255, 214, 107, 0.4) 60%, rgba(255, 214, 107, 0) 80%); animation: reborn-flash 1.6s ease-out forwards; }
@keyframes reborn-flash { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; } }
.ct-item.reborn { border: 2px solid #ffd66b; border-radius: 8px; padding: 0.4em; box-shadow: 0 0 14px rgba(255, 214, 107, 0.55); animation: reborn-glow 1.8s ease-in-out infinite alternate; }
.ct-item.reborn .rb-hd { color: #ffd66b; font-size: 1.1em; text-align: center; margin-bottom: 0.2em; }
@keyframes reborn-glow { from { box-shadow: 0 0 6px rgba(255, 214, 107, 0.35); } to { box-shadow: 0 0 18px rgba(255, 214, 107, 0.85); } }
`;
let rebornCss = false;
async function rebornScene(game, ct, res) {
  if (!rebornCss) {
    rebornCss = true;
    document.head.append(el('style', { text: REBORN_CSS }));
  }
  const flash = el('div', { class: 'reborn-flash' });
  document.getElementById('ui').append(flash);
  setTimeout(() => flash.remove(), 1700);
  game.audio.sfx('hirameki');
  setTimeout(() => game.audio.sfx('sparkle'), 900);
  const box = itemInfo(game, res.upgraded);
  if (box) {
    box.classList.add('reborn');
    box.prepend(el('div', { class: 'rb-hd', text: '✦ 生まれ変わった！ ✦' }));
  }
  ct.info(box);
  await ct.say(res.text, { narr: true });
  await ct.tap(4200);
}

async function upgradeLoop(game, ct) {
  let line = 'どれをきたえる？';
  let idx = 0;
  const AGAIN = 'ほかにきたえる物はあるか？';
  while (!ct.closed) {
    const list = candidates(game);
    if (!list.length) {
      ct.list(null);
      ct.info(null);
      await ct.say('おや？きたえられる装備を持っていないようだな。\n店の品（★1）は、きたえられないんだ。');
      await ct.tap(1800);
      return;
    }
    await ct.say(line);
    const rows = list.map((c, i) => {
      const cost = upgradeCost(c.id);
      const lack = cost ? lackOf(game.me, cost) : null;
      return {
        value: i,
        label: ITEMS[c.id].name,
        html: `${c.who ? '<span class="tag e">E</span>' : ''}${rareNameHtml(c.id)}${c.who ? `<span class="cnt">${esc(c.whoName)}</span>` : c.n > 1 ? `<span class="cnt">×${c.n}</span>` : ''}`,
        right: c.seed ? '？？？' : cost ? (cost.reborn ? '？？？' : cost.limit ? `★${cost.lb}へ` : `+${cost.n}へ${cost.over ? '？' : ''}`) : '最大',
        rightCls: !cost ? 'muted' : lack.ok ? 'gold' : 'dis',
        disabled: !canUpgrade(c.id),
      };
    });
    const pick = await ct.pick(rows, { start: Math.min(idx, rows.length - 1), onMove: (x) => ct.info(x ? upgradeBox(game, list[x.value]) : null) });
    if (ct.closed || !pick) return;
    idx = pick.value;
    const cand = list[pick.value];
    const it = ITEMS[cand.id];
    const cost = upgradeCost(cand.id);
    if (!cost) continue;
    const lack = lackOf(game.me, cost);
    if (!lack.ok) {
      await ct.say(`${it.name}を${cost.reborn ? 'もう1回' : cost.limit ? `★${cost.lb}に` : `+${cost.n}に`}きたえるには、\n${matsText(cost.mats)}と${cost.gold}ゴールドがいる。\n${lack.mats.length ? '素材が足りないようだな。' : 'ゴールドが足りないようだな。'}`);
      await ct.tap(2600);
      if (lack.mats.length) await sourcesFlow(game, ct, lack.mats); // 第64回 ⑥a: 入手先
      line = AGAIN;
      continue;
    }
    const yes = await ct.ask(cost.reborn
      ? `${it.name}をもう1回きたえるには、\n${matsText(cost.mats)}と${cost.gold}ゴールドがいる。\n…何かが起こりそうだ。きたえるか？`
      : cost.limit ? `${it.name}を限界とっぱ（★${cost.lb}）するには、\n${matsText(cost.mats)}と${cost.gold}ゴールドがいる。\nとっぱするか？`
      : `${it.name}を+${cost.n}にきたえるには、\n${matsText(cost.mats)}と${cost.gold}ゴールドがいる。\nきたえるか？`);
    if (ct.closed) return;
    if (yes !== 0) {
      line = AGAIN;
      continue;
    }
    game.audio.sfx('hammer');
    const res = await request(game, { kind: 'forge', action: 'upgrade', id: cand.id, who: cand.who });
    ct.updGold();
    if (!res.ok) {
      await ct.say(res.text || 'おや？何かおかしいようだな。');
      await ct.tap(2000);
      line = AGAIN;
      continue;
    }
    // 生まれ変わり（かくし要素）の 場面
    if (res.reborn) {
      await rebornScene(game, ct, res);
      line = `なんと…！こんなことがあるなんて！\n${AGAIN}`;
      continue;
    }
    setTimeout(() => game.audio.sfx('sparkle'), 800);
    // きたえた あとの 品を みぎに（つぎの 回へ）
    const next = candidates(game).find((c) => c.id === res.upgraded && c.who === cand.who);
    if (next) ct.info(upgradeBox(game, next));
    await ct.say(res.text, { narr: true });
    await ct.tap(2600);
    line = `うむ、いい出来だ。\n${AGAIN}`;
  }
}

