// 第38回 B: 職業の試練の がめん（メニューの「強さ」の 職業レベル・しょうごう、「クエスト」の 試練の とちゅう）
// きまりは shared/data/job-trials.js。試練の番人の 話は shared/world/job-trials.js
import { el } from './dom.js';
import { JOBS, ALL_JOBS, JOB_MAX_LEVEL } from '../../shared/data/jobs.js';
import { jobProgress } from '../../shared/stats.js';
import { jobLabel } from '../../shared/job-label.js';
import { trialState, trialName, jobTitle, jobTopCap, PHANTOM_NAME } from '../../shared/data/job-trials.js';

// 職業レベルの 右の 字（「Lv7（あと12回）」「Lv10 ★マスター」「Lv12/15（あと40回）」「Lv15 ★上限」「Lv25 ★きわめた」）
export function jobLevelText(c, j) {
  const pg = jobProgress(c, j);
  const lv = c.jobs?.[j]?.lv || 1;
  if (!pg.done) return { text: pg.cap > JOB_MAX_LEVEL ? `Lv${lv}/${pg.cap}（あと${pg.next}回）` : `Lv${lv}（あと${pg.next}回）`, cls: lv >= JOB_MAX_LEVEL ? 'gold' : '' };
  if (lv <= JOB_MAX_LEVEL) return { text: `Lv${lv} ★マスター`, cls: 'gold' };
  return { text: lv >= jobTopCap(j) ? `Lv${lv} ★きわめた` : `Lv${lv} ★上限`, cls: 'gold' };
}

// 試練の 1行（受けている・受けられる。ない ときは null）
export function trialRow(c, j) {
  const st = trialState(c, j);
  if (st.active) {
    const name = trialName(j, st.active.n, c);
    if (st.ready) return { name, text: `${PHANTOM_NAME}と戦える！（試練の番人へ）`, ready: true };
    return { name, text: `修行 ${st.count}/${st.need}回${j === c.job ? '' : `（${jobLabel(j, c)}の時だけ）`}`, ready: false };
  }
  if (j === c.job && st.canTake) return { name: trialName(j, st.next.n, c), text: '受けられる（星の神殿の試練の番人）', ready: true };
  return null;
}

// 試練の 行（今の 職業を 先に。受けている ものと、今の 職業で 受けられる もの）
export function trialRows(c) {
  if (!c || c.species) return [];
  const jobs = [c.job, ...ALL_JOBS.filter((j) => j !== c.job && c.jobs?.[j]?.tq)];
  return jobs.map((j) => trialRow(c, j)).filter(Boolean);
}

// メニューの「強さ」: しょうごう（Lv15・20・25）と 試練の とちゅう
// self … 自分の キャラ（仲間は 試練を 受けられない ので しょうごうだけ）
export function trialStatusBox(c, self = true) {
  if (!c || c.species || !JOBS[c.job]) return null;
  const box = el('div', { class: 'job-trial-box', style: { marginTop: '0.4em' } });
  const t = jobTitle(c);
  if (t) box.append(el('div', { class: 'kv small' }, el('span', { class: 'k', text: 'しょうごう' }), el('span', { class: 'gold', text: t })));
  for (const r of self ? trialRows(c) : []) box.append(el('div', { class: 'kv small' }, el('span', { text: r.name }), el('span', { class: r.ready ? 'good' : 'muted', text: r.text })));
  return box.childNodes.length ? box : null;
}

// メニューの「クエスト」: 職業の試練
export function trialQuestBox(c) {
  const rows = trialRows(c);
  if (!rows.length) return null;
  const box = el('div');
  box.append(el('h3', { style: { marginTop: '0.6em' }, text: '職業の試練' }));
  for (const r of rows) box.append(el('div', { class: 'kv' }, el('span', {}, el('i', { class: `qdot ${r.ready ? 'ready' : 'sub'}` }), r.name), el('span', { class: r.ready ? 'good' : 'muted', text: r.text })));
  return box;
}

js/client/ui/kana-pad.js:
// 第62回: コントローラーだけで 名前などを 書く 文字ばん（ひらがな・カタカナ・英数）
//   askText（ui/dom.js）が、コントローラーが つながって いる ときに 出す。タップ・クリックでも おせる
//   十字キー … えらぶ　A … 入れる　B … 1文字 けす（何も 書いて いない ときは やめる）
//   「゛゜小」… さいごの 文字を が→か・は→ば→ぱ・つ→っ などに かえる
import { el } from './dom.js';

const HIRA_ROWS = [
  'あかさたなはまやらわ',
  'いきしちにひみゆりを',
  'うくすつぬふむよるん',
  'えけせてねへめゃれー',
  'おこそとのほもゅろょ',
];
const toKata = (s) => s.replace(/[ぁ-ゖ]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x60));
const KATA_ROWS = HIRA_ROWS.map(toKata);
const ABC_ROWS = [
  'ABCDEFGHIJ',
  'KLMNOPQRST',
  'UVWXYZ!?・ー',
  '0123456789',
  'abcdefghij',
];
const NUM_ROWS = ['12345', '67890'];
export const PAD_PAGES = { hira: HIRA_ROWS, kata: KATA_ROWS, abc: ABC_ROWS, num: NUM_ROWS };

// さいごの 文字の かわりかた（゛゜小）。ひとまわりで もとに もどる
const CYCLES = [
  'かが', 'きぎ', 'くぐ', 'けげ', 'こご', 'さざ', 'しじ', 'すず', 'せぜ', 'そぞ', 'ただ', 'ちぢ', 'つっづ', 'てで', 'とど',
  'はばぱ', 'ひびぴ', 'ふぶぷ', 'へべぺ', 'ほぼぽ', 'あぁ', 'いぃ', 'うぅゔ', 'えぇ', 'おぉ', 'やゃ', 'ゆゅ', 'よょ', 'わゎ',
];
const NEXT = new Map();
for (const c of [...CYCLES, ...CYCLES.map(toKata)]) {
  const a = [...c];
  a.forEach((ch, i) => NEXT.set(ch, a[(i + 1) % a.length]));
}
// 「゛゜小」を おした ときの さいごの 文字（かわらない 文字は そのまま）
export function cycleChar(ch) {
  return NEXT.get(ch) || ch;
}
export function cycleLast(text) {
  const a = [...String(text || '')];
  if (!a.length) return String(text || '');
  a[a.length - 1] = cycleChar(a[a.length - 1]);
  return a.join('');
}

// 文字ばんの キー（行ごと）。page: hira / kata / abc / num
export function padKeys(page, numeric = false) {
  const rows = (numeric ? NUM_ROWS : PAD_PAGES[page] || HIRA_ROWS).map((r) => [...r].map((ch) => ({ ch, label: ch })));
  const tools = numeric
    ? [{ act: 'del', label: '1字けす' }, { act: 'ok', label: '決定' }, { act: 'cancel', label: 'やめる' }]
    : [
      { act: 'page', page: page === 'hira' ? 'kata' : 'hira', label: page === 'hira' ? 'カナ' : 'ひら' },
      { act: 'page', page: page === 'abc' ? 'hira' : 'abc', label: page === 'abc' ? 'かな' : '英数' },
      { act: 'cycle', label: '゛゜小' },
      { act: 'del', label: '1字けす' },
      { act: 'ok', label: '決定' },
      { act: 'cancel', label: 'やめる' },
    ];
  return [...rows, tools];
}

// 十字キーの 動き（rows … キーの 行。r・c … 今の 場所）→ 新しい [r, c]（はしは 反対へ 回る）
export function padMove(rows, r, c, dir) {
  const n = rows.length;
  if (dir === 'left' || dir === 'right') {
    const len = rows[r].length;
    return [r, (c + (dir === 'right' ? 1 : -1) + len) % len];
  }
  const nr = (r + (dir === 'down' ? 1 : -1) + n) % n;
  // 行の 長さが ちがう ときは、同じ 横の 位置に ちかい キーへ
  const ratio = rows[r].length > 1 ? c / (rows[r].length - 1) : 0;
  const nc = rows[nr].length === rows[r].length ? c : Math.round(ratio * (rows[nr].length - 1));
  return [nr, Math.min(nc, rows[nr].length - 1)];
}

// 文字ばんを つくる。field … 書く input。max … 文字数。onDone(v) … 決定（文字）・やめる（null）
export function kanaPad(field, { max = 8, numeric = false, onDone, sound } = {}) {
  // はじめの 名前が カタカナなら カタカナの 面から（魔物の 名前など）
  let page = /[ァ-ヶ]/.test(field.value) ? 'kata' : 'hira';
  // はじめは「決定」の 上（そのままの 名前で よければ A だけで 決まる）
  let r = -1, c = 0;
  let rows = [];
  const root = el('div', { class: `kana-pad ${numeric ? 'num' : ''}` });
  const len = () => [...field.value].length;
  const put = (ch) => {
    if (len() >= max) { sound?.('buzz'); return; }
    field.value += ch;
    sound?.('cursor');
  };
  const act = (k) => {
    if (k.ch) return put(k.ch);
    if (k.act === 'page') { page = k.page; sound?.('cursor'); return draw(); }
    if (k.act === 'cycle') { field.value = cycleLast(field.value); sound?.('cursor'); return; }
    if (k.act === 'del') { field.value = [...field.value].slice(0, -1).join(''); sound?.('cancel'); return; }
    if (k.act === 'ok') return onDone?.(field.value.trim());
    if (k.act === 'cancel') return onDone?.(null);
  };
  const draw = () => {
    rows = padKeys(page, numeric);
    if (r < 0) { r = rows.length - 1; c = rows[r].findIndex((k) => k.act === 'ok'); }
    r = Math.min(r, rows.length - 1);
    c = Math.min(c, rows[r].length - 1);
    root.innerHTML = '';
    btns = rows.map((row, ri) => {
      const line = el('div', { class: `kp-row ${ri === rows.length - 1 ? 'kp-tools' : ''}` });
      const bs = row.map((k, ci) => el('button', { class: `btn kp-key ${k.act ? 'kp-act' : ''} ${k.act === 'ok' ? 'primary' : ''}`, text: k.label, onclick: (e) => { e?.preventDefault?.(); r = ri; c = ci; mark(); act(k); } }));
      line.append(...bs);
      root.append(line);
      return bs;
    });
    mark();
  };
  let btns = [];
  const mark = () => {
    for (const bs of btns) for (const b of bs) b.classList?.remove('cur');
    btns[r]?.[c]?.classList?.add('cur');
  };
  // コントローラー・キーボードの 矢印。true … つかった
  const nav = (a) => {
    if (a === 'up' || a === 'down' || a === 'left' || a === 'right') {
      [r, c] = padMove(rows, r, c, a);
      sound?.('cursor');
      mark();
      return true;
    }
    if (a === 'a') { act(rows[r][c]); return true; }
    if (a === 'b') {
      if (len()) act({ act: 'del' });
      else onDone?.(null);
      return true;
    }
    return false;
  };
  draw();
  return { root, nav, get page() { return page; }, get pos() { return [r, c]; } };
}

