export class FieldMenu {
  constructor(game) {
    this.game = game;
    bindAlchemy(game); // きたえる 回数は 自分の れん金の きろくで（ui/alchemy.js）
  }

  get sfx() { return (x) => this.game.audio.sfx(x); }

  open() {
    const g = this.game;
    if (this.root) return;
    g.menuOpen = true;
    this.trail = [];
    this.view = null;
    // そとを タップしても とじる
    this.backdrop = el('div', { class: 'modal-back', onclick: () => this.closeByUser() });
    this.root = el('div', { class: 'panel fmenu-panel' });
    // ドラクエの ように: パーティー みんなの HP・MP・Lv と、所持金
    const head = el('div', { class: 'win fm-head' });
    this.headParty = el('div', { class: 'fm-party' });
    this.headGold = el('div', { class: 'fm-gold' });
    const closeBtn = el('button', { class: 'btn closebtn', text: '✕ 閉じる', 'aria-label': 'メニューを閉じる', onclick: () => this.closeByUser() });
    head.append(this.headParty, this.headGold, closeBtn);
    document.body.classList.add('menu-open');
    this.side = el('div', { class: 'win side' });
    this.main = el('div', { class: 'win main scroll' });
    // えらんだ コマンドの 見出し（スマホの たてむきでは、コマンドの かわりに これだけ 出る。CSS の .sub-open）
    this.titleText = el('span', { class: 'fm-tt' });
    this.titleBar = el('div', { class: 'fm-title' },
      el('button', { class: 'btn fm-back', text: '← もどる', 'aria-label': 'もどる', onclick: (e) => { e.stopPropagation(); this.titleBack(); } }),
      this.titleText);
    this.side.append(this.titleBar);
    this.root.append(head, el('div', { class: 'fmenu' }, this.side, this.main));
    document.getElementById('ui').append(this.backdrop, this.root);
    this.updateHead();
    this.menu = new ListMenu(g.input, {
      items: MAIN.map((it) => ((it.value === 'news' && hasUnreadNews(g.me)) || (it.value === 'quest' && hasNewAsk(g.me)) || (it.value === 'fboard' && hasBoardUnread(g)) ? { ...it, cls: 'has-new' } : it)),
      sound: this.sfx,
      back: null,
      onMove: (it) => this.preview(it.value),
      onSelect: (it) => this.select(it.value),
      onCancel: () => this.close(),
    });
    this.side.append(this.menu.root);
    this.menu.focus();
    prefetchMissions(this); // 第78回 3-10: 家族ミッション（見本・冒険のしおりの 行）
  }

  // コマンドを えらんで 中の 画面に 入った（true）／コマンドの 一覧に もどった（false）
  // スマホの たてむきでは 画面が かわる（コマンドの 一覧を かくして、見出しと もどる だけに）
  setSubOpen(on) {
    if (!this.root) return;
    this.root.classList.toggle('sub-open', !!on);
    if (on) this.titleText.textContent = MAIN.find((m) => m.value === this.current)?.label || '';
  }

  // 見出しの「← もどる」（Bボタンと おなじ。えらぶ まどが 出ている ときは そちらが さき）
  titleBack() {
    if (this.popupOpen) return;
    if (this.sub?.active) this.sub.cancel();
    else if (!this.menu?.active) {
      this.sfx('cancel');
      this.back();
    }
  }

  updateHead() {
    const c = this.game.me;
    this.headParty.innerHTML = '';
    const rows = partyRows(this.game);
    // 第50回 A: 4人いじょうの 旅では、スマホの たてで 体力表示を 小さく（よこ 1列。所持金と 閉じるは 上の 1行。css の .fm-head.many）
    const head = this.headParty.parentElement;
    head?.classList.toggle('many', rows.length >= 4);
    head?.style.setProperty('--n', String(Math.min(6, Math.max(1, rows.length))));
    for (const m of rows) {
      this.headParty.append(el('div', { class: `fm-mem ${m.hp <= 0 ? 'dead' : ''}` },
        el('div', { class: `n ${m.hpCls}`, text: m.name }),
        el('div', { class: `v ${m.hpCls}` }, el('span', { class: 'k', text: 'H' }), `${Math.max(0, m.hp)}`),
        // HP の バー（小さい 表示の ときだけ 見える）
        el('div', { class: `hpb ${m.hpCls}` }, el('i', { style: { width: `${Math.round(Math.max(0, Math.min(1, m.hp / Math.max(1, m.maxHp))) * 100)}%` } })),
        el('div', { class: 'v' }, el('span', { class: 'k', text: 'M' }), `${m.mp}`),
        el('div', { class: 'v lv' }, el('span', { class: 'k', text: 'Lv' }), `${m.level}`),
        // 第35回: 短い 職業名（モンスターは なし。スマホの たてでは せまいので 出さない。ui/r35-css.js）
        m.jb ? el('div', { class: 'jb', text: m.jb }) : null));
    }
    this.headGold.innerHTML = '';
    this.headGold.append(el('span', { class: 'k', text: '所持金' }), el('span', { class: 'g', text: `${c.gold.toLocaleString('ja-JP')} G` }));
  }

  close() {
    this.sub?.blur();
    this.menu?.blur();
    this.root?.remove();
    this.backdrop?.remove();
    this.root = null;
    this.backdrop = null;
    this.game.menuOpen = false;
    document.body.classList.remove('menu-open');
  }

  // ✕ボタン・そとを タップ（えらんでいる とちゅうの ウィンドウが あれば そちらが さき）
  closeByUser() {
    if (this.popupOpen) return;
    this.game.audio.sfx('cancel');
    this.close();
  }

  refresh() {
    if (!this.root) return;
    this.updateHead();
    // みぎの 見本を かきなおすのは、ひだりの メニューを えらんでいる ときだけ
    // （装備・強さ・仲間の 中の 画面や、えらぶ まどが 出ている ときに、自分の 見本に かわって しまわないように）
    if (this.current && this.menu?.active) this.preview(this.current);
  }

  // ───── 画面の つみかさね（もどる で 一つ前の 画面へ。カーソルと スクロールも もとどおり） ─────
  // make: 画面を つくる 関数（えらべる 画面を かえす）。this.view が 今の 画面、this.trail が 前の 画面たち
  showView(make, start = -1, top = 0) {
    this.sub?.blur();
    this.sub = null;
    this.view = make;
    this.startIdx = start;
    const node = make();
    this.startIdx = -1;
    this.focusSub(node);
    if (this.root) this.main.scrollTop = top;
  }

  // ひだりの メニューから 入る（前の 画面は わすれる）
  openView(make) {
    this.trail = [];
    this.showView(make);
  }

  // 今の 画面の 上に つぎの 画面を のせる（もどる で 今の 画面に もどれる）
  pushView(make) {
    if (this.view) this.trail.push({ make: this.view, idx: this.sub ? this.sub.idx : -1, top: this.main.scrollTop });
    this.showView(make);
  }

  // 今の 画面を つくりなおす（装備を かえた あと など。カーソルの 場所は そのまま）
  redraw() {
    if (!this.root) return;
    if (!this.view) {
      if (this.menu.active) this.preview(this.current);
      return;
    }
    this.showView(this.view, this.sub ? this.sub.idx : -1, this.main.scrollTop);
  }

  back() {
    this.sub?.blur();
    this.sub = null;
    if (!this.root) return; // もう とじている（おくれて よばれた とき）
    // 一つ前の 画面が あれば そこへ（えらんでいた 人・スクロールも もとどおり）
    const prev = this.trail?.pop();
    if (prev) return this.showView(prev.make, prev.idx, prev.top);
    this.view = null;
    this.setSubOpen(false);
    this.menu.focus();
    this.preview(this.current);
    this.main.scrollTop = 0;
  }

  preview(v) {
    this.current = v;
    this.main.innerHTML = '';
    const g = this.game;
    // 道具・呪文・技の 中みは、えらんだ ときに はじめて 出す（カーソルを あわせた だけでは せつめいだけ）
    switch (v) {
      case 'items': this.main.append(el('div', { class: 'muted', text: '持っている道具を見る。\n使う・装備する・捨てる。宝の地図もここから見る。' })); break;
      case 'talk': this.main.append(el('div', { class: 'muted', text: '仲間と話す。次にどこへ行けばいいか、仲間がヒントをくれる。' })); break;
      case 'fullheal': this.main.append(el('div', { class: 'muted', text: 'みんなのHPを満タンにする。\n「呪文で」…回復の呪文を、MPのむだが少ない順に使う。\n「道具で」…薬草などを、むだが少ない順に使う。' })); break;
      case 'skills': this.main.append(el('div', { class: 'muted', text: '覚えた呪文・技を見る。\n回復やルーラなど、ここで使える技は「今使える」からすぐ使える。お気に入りのならびも決められる。' })); break;
      case 'equip': this.main.append(this.equipView(false)); break;
      case 'status': this.main.append(this.statusView()); break;
      case 'party': this.main.append(this.partyView(false)); break;
      case 'tactics': this.main.append(this.tacticsView(false)); break;
      case 'vehicle': this.main.append(vehicleMenuView(this, false)); break;
      case 'zukan': this.main.append(this.zukanView(false)); break;
      case 'phantom': this.main.append(phantomBookView(this, false)); break;
      case 'map': this.main.append(el('div', { class: 'muted', text: '探検した場所の地図を見る。（Mキーでも開ける）\n次の行き先はピンク、たのまれごとは水色、報告できるときはみどりのしるし。\n困っている人（クエストで選んだ人）は黄色のしるし。' })); break;
      case 'quest':
        this.main.append(this.questView());
        // 第50回 N4: 困っている人を 見たら ● を けす
        for (const it of this.menu?.items || []) if (it.value === 'quest') it.cls = '';
        for (const n of this.menu?.root.querySelectorAll('.item.has-new') || []) if (n.textContent.includes('クエスト')) n.classList.remove('has-new');
        break;
      case 'settings': this.main.append(this.settingsView(false)); break;
      case 'shiori': this.main.append(shioriPreview(this)); break;
      case 'mission': this.main.append(missionsPreview(this)); break;
      case 'news': this.main.append(newsView(this, false)); break;
      case 'fboard': this.main.append(familyBoardView(this, false)); break;
      case 'quit': {
        const where = g.net.mode !== 'offline' ? '家族サーバー' : g.net.local?.cloud?.state === 'on' ? 'claude.ai' : 'このブラウザ';
        this.main.append(el('div', { class: 'muted', text: `セーブしてタイトルにもどる。（${where}にセーブされます）` }));
        break;
      }
      default:
    }
  }

  // じぶんの なかま（酒場の なかま・モンスター。馬車の 仲間も）
  myMates() {
    const g = this.game;
    return [...(g.party?.supports || []), ...(g.party?.wagon || [])].filter((x) => x.owner === g.me.id && x.kind !== 'family');
  }

  // いっしょに 戦う 人（自分・家族・パーティーの 仲間。馬車の 仲間は 入れない）と、見ている 人 c。
  // 合体技の 一覧で、パーティーに 関係する 技だけ 出す ため（stats.js の partyJobSet。ひらめきは 第32回から 今の 職業だけ＝hiraOfJob）
  // もどりち: { jobs: パーティーの 職業, skills: 覚えている 技（自分と 自分の 仲間の ぶん。家族の キャラの 技は とどかない） }
  partyFocus(c) {
    const g = this.game;
    const chars = [g.me, c];
    for (const m of g.party?.members || []) if (m.charId !== g.me.id) chars.push({ job: m.job, mjobs: m.mjobs });
    for (const x of g.party?.supports || []) chars.push(x.owner === g.me.id && x.kind !== 'family' ? this.charOf(x.key) || x : x);
    const skills = new Set();
    for (const ch of chars) {
      if (!ch || ch.kind === 'family' || (!ch.jobs && !ch.species)) continue;
      try {
        for (const id of learnedAbilities(ch)) skills.add(id);
      } catch { /* 形の ちがう データは とばす */ }
    }
    return { jobs: partyJobSet(chars), skills };
  }

  // key の キャラ（じぶん か なかま）を メニューで つかえる かたちに
  charOf(who) {
    const g = this.game;
    if (!who || who === 'self') return g.me;
    const x = [...(g.party?.supports || []), ...(g.party?.wagon || [])].find((m) => m.key === who && m.owner === g.me.id);
    if (!x) return null;
    return {
      key: x.key, name: x.name, level: x.level, exp: x.exp || 0, job: x.job, jobs: x.jobs || {}, equip: x.equip || {}, seeds: x.seeds || {},
      species: x.species || undefined, color: x.color || undefined, hp: x.hp, mp: x.mp, look: x.look, lookEquip: x.lookEquip, tactics: x.tactics, status: {}, companion: true,
      plus: x.plus || 0, bonus: x.bonus || undefined, inherit: x.inherit || undefined,
      hirameki: x.hirameki || [], skillUse: x.skillUse || {}, favorites: x.favorites || [],
      autoOff: x.autoOff || [],
      // 第71回: 命令の 一覧に 出さない 技（サーバーが cmdOff か、まだ うつして いない 人は autoOff を おくる。party.js の supportInfo）
      cmdOff: x.cmdOff || [],
    };
  }

  // だれの？（なかまが いる ときだけ）
  whoView(next) {
    const g = this.game;
    const box = el('div');
    const mates = this.myMates();
    const title = { skills: 'だれの呪文・技？', equip: 'だれの装備？', status: 'だれの強さ？' }[next] || 'だれ？';
    const items = [{ label: `${g.me.name}（自分）`, value: 'self', face: faceURL({ look: g.me.look, job: g.me.job, eq: shownEquip(g.me) }) },
      ...mates.map((m) => ({ label: `${m.name}（${m.species ? MONSTERS[m.species]?.name : jobLabel(m.job, m)} Lv${m.level}${m.wagon ? '・馬車' : ''}）`, value: m.key, face: faceURL({ look: m.look, job: m.job, eq: shownEquip(m), mon: colorMon(m.species, m.color) }) }))];
    // 強さは「全員」を 一覧で くらべられる
    if (next === 'status') items.unshift({ label: '全員（一覧でくらべる）', value: '__all' });
    // 装備は「みんなさいきょう装備」も ここ（だれかを えらぶ ときと おなじ 場所）
    if (next === 'equip' && mates.length) items.push({ label: 'みんなさいきょう装備', value: '__bestAll', cls: 'best-all' });
    const m = this.mkSub({
      items,
      // つぎの 画面は 上に のせる（もどる で この リストの おなじ 人に もどる）
      onSelect: async (it) => {
        if (it.value === '__bestAll') {
          // いきなり 変えずに「何が 何に 変わるか」を 見せてから えらぶ
          this.sub.blur();
          const done = await this.bestEquipAsk('all');
          setTimeout(() => this.redraw(), done ? 250 : 0);
          return;
        }
        this.pushView(() => (it.value === '__all' ? this.allStatusView(true)
          : next === 'skills' ? this.skillsView(true, it.value) : next === 'equip' ? this.equipView(true, it.value) : this.statusView(it.value, true)));
      },
    });
    box.append(el('div', { class: 'small gold', text: title }), m.root);
    if (next === 'equip' && mates.length) box.append(el('div', { class: 'detail', text: '「みんなさいきょう装備」…自分と仲間みんな（馬車の仲間も）を、ならびの順にさいきょう装備にする。1つしかない物は、戦う仲間が先（何が何に変わるかを見てから決められる）' }));
    return box;
  }

  // パーティーに 自分 いがいの 人（家族・なかま・ゲスト）が いるか
  hasOthers() {
    const p = this.game.party;
    return !!p && ((p.members || []).length > 1 || (p.supports || []).length > 0 || (p.guests || []).length > 0);
  }

  select(v) {
    const g = this.game;
    this.trail = [];
    this.view = null;
    if (['skills', 'equip'].includes(v) && this.myMates().length) return this.openView(() => this.whoView(v));
    if (v === 'status' && (this.myMates().length || this.hasOthers())) return this.openView(() => this.whoView(v));
    switch (v) {
      case 'items': return this.focusSub(this.itemsList(true));
      case 'skills': return this.focusSub(this.skillsView(true));
      case 'equip': return this.openView(() => this.equipView(true));
      case 'party': return this.openView(() => this.partyView(true));
      case 'tactics': return this.openView(() => this.tacticsView(true));
      case 'vehicle': return this.openView(() => vehicleMenuView(this, true));
      case 'zukan': return this.focusSub(this.zukanView(true));
      case 'phantom': return this.openView(() => phantomBookView(this, true));
      case 'settings': return this.focusSub(this.settingsView(true));
      case 'news':
        // 読んだら メニューの ● を けす
        for (const it of this.menu.items) if (it.value === 'news') it.cls = '';
        this.menu.root.querySelector('.item.has-new')?.classList.remove('has-new');
        return this.focusSub(newsView(this, true));
      case 'fboard': return this.focusSub(familyBoardView(this, true));
      case 'shiori':
        this.menu.blur();
        return openShiori(this).then(() => { if (this.root) this.menu.focus(); });
      case 'mission':
        this.menu.blur();
        return openMissions(this).then(() => { if (this.root) this.menu.focus(); });
      case 'talk':
        this.close();
        return partyTalk(g);
      case 'fullheal':
        this.menu.blur();
        return this.pick('どうやって満タンにする？', [{ label: '呪文で', value: 'spell' }, { label: '道具で', value: 'item' }, { label: 'やめる', value: null }]).then((mode) => {
          if (mode) g.net.send({ t: 'menu', action: 'fullHeal', mode });
          if (this.root) this.menu.focus();
        });
      case 'map':
        this.close();
        return openWorldMap(g);
      // 第50回 N4: 困っている人を 1人ずつ（地図に しるし）。いない ときは 右の 見本の まま
      case 'quest':
        if (availableSubQuests(g.me).length) this.openView(() => askView(this) || el('div', { class: 'muted', text: '今は、だれも困っていないみたい。' }));
        return undefined;
      case 'quit':
        this.menu.blur();
        return confirmBox(g.input, 'セーブしてタイトルにもどりますか？', 'はい', 'いいえ', this.sfx).then((ok) => {
          if (ok) {
            this.close();
            g.quitToTitle();
          } else this.menu.focus();
        });
      default:
    }
  }

  focusSub(node) {
    if (!this.root) { this.sub?.blur(); return; }
    this.main.innerHTML = '';
    this.main.append(node);
    if (this.sub) {
      this.menu.blur();
      this.setSubOpen(true);
      this.sub.focus();
    }
  }

  mkSub(opts) {
    // 画面を つくりなおす ときは まえの カーソルの 場所から（showView の start）
    const start = this.startIdx ?? -1;
    this.startIdx = -1;
    this.sub = new ListMenu(this.game.input, { sound: this.sfx, onCancel: () => this.back(), start, ...opts });
    return this.sub;
  }

  // ───── どうぐ ─────
  // focus: { id, idx } … カーソルを おく 道具（使った・装備した 道具。なくなった ときは もとの 場所 idx に いちばん 近い 道具）
  itemsList(active, focus = null) {
    const g = this.game;
    const c = g.me;
    // 第27回: 一覧は まどの 中で スクロール、せつめいは その 下に いつも 見える（css の .items-view）
    const box = el('div', { class: 'items-view' });
    const detail = el('div', { class: 'detail item-detail' });
    const mode = itemSortPref();
    const counts = new Map(c.items.map((e) => [e.id, e.n]));
    // 素材（ふしぎなかじで 使う）には しるし
    const items = sortItemIds(c.items.map((e) => e.id), mode).map((id) => ({ label: ITEMS[id].name, html: ITEMS[id].type === 'mat' ? `${esc(ITEMS[id].name)}<span class="tag mat">素材</span>` : rareNameHtml(id), right: `×${counts.get(id)}`, value: id }));
    // れん金がま（第32回）は いちばん上（ui/alchemy.js）
    const pot = alchemyRow(c);
    if (pot) items.unshift(pot);
    // 第50回 N3: すぐ使う ボタンの 大事な物には「ボタン」の しるし
    const qk = quickItemOf(c);
    for (const k of c.keyItems) if (!pot || k !== pot.value) items.push({ html: `${ITEMS[k].name}<span class="tag gold">大事</span>${k === qk ? '<span class="tag quick">ボタン</span>' : ''}`, value: k, key: true });
    items.push(...treasureRows(c)); // 宝の地図
    const medal = medalItemRow(c);
    if (medal) items.push(medal);
    if (!items.length) {
      box.append(el('div', { class: 'muted', text: '何も持っていない。' }));
      if (active) setTimeout(() => this.back(), 600);
      return box;
    }
    if (!active) {
      box.append(el('div', { class: 'small', text: items.map((i) => i.label || ITEMS[i.value].name).join('、') }));
      return box;
    }
    // 第35回: 道具の 分類の タブ（消もう品・装備品・大事な物・素材・宝の地図。空の タブは 出さない）。
    // スマホは タブを タップ、十字キー・キーボードは 左右（ListMenu の onSide）
    const kinds = ITEM_TABS.map(([k, label]) => ({ k, label, list: items.filter((x) => itemTabOf(x) === k) })).filter((t) => t.list.length);
    const fRow = focus && items.find((x) => x.value === focus.id);
    const want = fRow ? itemTabOf(fRow) : this.itemTab;
    const cur = kinds.find((t) => t.k === want) || kinds.find((t) => t.k === this.itemTab) || kinds[0];
    this.itemTab = cur.k;
    const goTab = (k) => {
      this.itemTab = k;
      this.sfx('cursor');
      this.focusSub(this.itemsList(true));
    };
    const kindTabs = kinds.length > 1 ? el('div', { class: 'item-tabs', role: 'tablist' }, ...kinds.map((t) => el('button', {
      class: `btn ${t.k === cur.k ? 'sel' : ''}`,
      role: 'tab',
      text: t.label,
      onclick: (e) => { e.stopPropagation(); goTab(t.k); },
    }))) : null;
    items.splice(0, items.length, ...cur.list);
    // ならべかえ（あいうえお順・種類順・手に入れた順）
    const tabs = el('div', { class: 'tabs sort-tabs' }, el('span', { class: 'small muted', text: g.input.touch && !g.input.pad?.on ? 'ならべかえ' : 'ならべかえ（Y）' }),
      ...Object.entries(ITEM_SORTS).map(([k, label]) => el('button', {
        class: `btn ${k === mode ? 'on' : ''}`,
        text: label,
        onclick: () => {
          setItemSortPref(k);
          this.sfx('cursor');
          this.focusSub(this.itemsList(true));
        },
      })));
    // じぶんの モンスターの なかま（装備できる 子の 名前を せつめいに 出す）
    const mons = this.myMates().filter((x) => x.species).map((x) => ({ name: x.name, species: x.species }));
    let start = -1;
    if (focus) {
      start = items.findIndex((x) => x.value === focus.id);
      if (start < 0) start = Math.min(Math.max(0, focus.idx || 0), items.length - 1);
    }
    // せつめいは 戦いの 道具と おなじ 文（だれに・効果・せつめい）＋ 使える所（ui/skillinfo.js の menuItemText）。
    // スマホは 戦いと おなじ「タップで せつめい → もう一度で 使う・装備する など」（ListMenu の tapConfirm）
    const touch = !!g.input.touch;
    const m = this.mkSub({
      items,
      start,
      tapConfirm: touch,
      onMove: (it) => {
        detail.textContent = it ? (it.tmap ? treasureDetail(g, it.tmap) : menuItemText(it.value, { touch: touch && !it.key, mons })) : '';
        // せつめいの 高さが かわると 一覧の まどが せまく なる。えらんだ 行が かくれないように
        requestAnimationFrame(() => { if (m.root.isConnected) m.scrollToSel(); });
      },
      onSelect: (it) => this.itemAction(it),
      onSide: kinds.length > 1 ? (d) => goTab(kinds[(kinds.indexOf(cur) + d + kinds.length) % kinds.length].k) : null,
      // 第35回: Y で ならべかえ（コントローラー・キーボード。タップは 上の ボタン）
      onY: () => {
        const keys = Object.keys(ITEM_SORTS);
        setItemSortPref(keys[(keys.indexOf(mode) + 1) % keys.length]);
        this.sfx('cursor');
        this.focusSub(this.itemsList(true));
      },
    });
    box.append(...(kindTabs ? [kindTabs] : []), tabs, m.root, detail);
    return box;
  }

  async itemAction(entry) {
    const g = this.game;
    if (entry.tmap) return openTreasureMap(this, entry.tmap);
    const it = ITEMS[entry.value];
    // おわったら 道具の 一覧へ。カーソルは この 道具（なくなった ときは いちばん 近い 道具）
    const focus = { id: entry.value, idx: this.sub ? this.sub.idx : 0 };
    const backToList = (ms = 150) => setTimeout(() => { if (this.root) this.focusSub(this.itemsList(true, focus)); }, ms);
    // 風の笛（大鳥フウラを 呼ぶ。sky.js）
    if (it.flute) {
      this.sub.blur();
      const act = await this.pick(`${it.name}をどうする？`, [{ label: 'ふく', value: 'use' }, { label: 'やめる', value: null }]);
      if (act === 'use') {
        this.close();
        g.sky.call();
        return;
      }
      backToList();
      return;
    }
    if (entry.pot) {
      this.close();
      return alchemyUI(g);
    }
    // 第6章: 時の砂時計（時代を 切りかえる。world/time-glass.js。使えない ときは サーバーの 知らせ）
    // 第6章 Step 3・4: ミナモの 星読み（menuUse: 'starSight'。world/star-sight.js）も おなじ 形
    if (it.hourglass || it.menuUse) {
      this.sub.blur();
      // 第50回 N3: すぐ使う ボタン（HUD・コントローラー・T キー）に する・はずす
      const onBtn = quickUseOf(entry.value) && quickItemOf(g.me) === entry.value;
      const acts = [{ label: '使う', value: 'use' }];
      if (quickUseOf(entry.value)) acts.push(onBtn ? { label: 'すぐ使うボタンからはずす', value: 'qoff' } : { label: 'すぐ使うボタンにする', value: 'qon' });
      acts.push({ label: 'やめる', value: null });
      const act = await this.pick(`${it.name}をどうする？`, acts);
      if (act === 'use') {
        this.close();
        g.net.send({ t: 'menu', action: it.menuUse || 'timeGlass' });
        return;
      }
      if (act === 'qon' || act === 'qoff') {
        await this.menuCall({ t: 'menu', action: 'quickSet', id: act === 'qon' ? entry.value : '' });
      }
      backToList();
      return;
    }
    if (entry.key || it.type === 'key') return;
    const acts = [];
    if (it.type === 'use' && it.field) acts.push({ label: '使う', value: 'use' });
    const team = ['weapon', 'armor', 'shield', 'head', 'acc'].includes(it.type) ? compareTeam(g, entry.value) : null;
    if (team) acts.push({ label: '装備する', value: 'equip', disabled: !team.some((r) => r.can && !r.same) });
    // 第50回 N6: 家族にあげる（家族サーバーで、ほかの キャラが いる 時だけ。ui/gift.js）
    if (canGift(g, entry.value)) acts.push({ label: '家族にあげる', value: 'gift' });
    acts.push({ label: '捨てる', value: 'drop' }, { label: 'やめる', value: 'cancel' });
    this.sub.blur();
    const act = await this.pick(`${it.name}をどうする？`, acts);
    if (act === 'use') {
      if (it.effect.type === 'warp' && MAPS[g.field?.mapId]?.noEscape) {
        // 王家のピラミッドの 中: 帰り道の羽は 使えない（行き先を えらばずに サーバーへ。わけを 出す）
        await this.menuCall({ t: 'menu', action: 'useItem', id: entry.value });
      } else if (it.effect.type === 'warp') {
        const place = await this.pick('どこへ飛ぶ？', [...this.warpChoices(), { label: 'やめる', value: null }]);
        if (place) {
          g.net.send({ t: 'menu', action: 'useItem', id: entry.value, place });
          this.close();
          return;
        }
      } else if (it.effect.type === 'exit') {
        // みちびきの糸: もどれたら メニューを とじて 外を 見せる（リレミトと おなじ）。
        // 第79回: ひみつのダンジョン（noEscape でも 入口へ もどれる）も サーバーの 返事で きめる。
        // もどれない 所（ピラミッド・町・フィールド など）は わけを 出して メニューは 開いた まま
        const r = await this.menuCall({ t: 'menu', action: 'useItem', id: entry.value });
        if (r?.ok) return this.close();
      } else if (it.target === 'self') {
        // 聖水・すず など（だれも えらばない）: 使った あとも 一覧の この 道具に カーソル
        await this.menuCall({ t: 'menu', action: 'useItem', id: entry.value, ref: 'self' });
      } else {
        // 薬草・魔法の聖水 など: 残っている あいだは、おなじ 道具の「だれに使う？」に もどる
        return this.useOnTargets(entry.value, focus);
      }
    } else if (act === 'equip') {
      // ドラクエと おなじ:「だれが 装備する？」（みんなの 強さが どう かわるか いっしょに 出す）。装備できない 人は 出さない
      const who = team.length === 1 ? 'self'
        : await this.pick(`だれが${it.name}を装備する？`, [...whoItems(team.filter((r) => r.can)), { label: 'やめる', value: null }], { wide: true });
      if (who) await this.menuCall({ t: 'menu', action: 'equip', id: entry.value, who });
    } else if (act === 'gift') {
      await giftFlow(this, entry.value);
    } else if (act === 'drop') {
      if (await confirmBox(g.input, `${it.name}を捨てますか？`, '捨てる', 'やめる', this.sfx)) await this.menuCall({ t: 'menu', action: 'discard', id: entry.value, n: 1 });
    }
    backToList();
  }

  // 道具を だれかに 使う（薬草・魔法の聖水・種 など）。使った あとも、その 道具が 残っている あいだは
  // おなじ 道具の「だれに使う？」に もどる（新しい HP・MPで。カーソルは 前に 使った 人。まどの 上に 使った けっか）。
  // B・やめる で 道具の 一覧の この 道具へ。なくなった・使える 人が いなく なった ときは 一覧の いちばん 近い 道具へ
  async useOnTargets(id, focus) {
    const g = this.game;
    const it = ITEMS[id];
    const dead = it.target === 'deadAlly';
    const goOn = () => !!this.root && itemCount(g.me, id) > 0 && this.partyRefs(dead).some((r) => !r.disabled);
    let last;
    let note = null;
    for (;;) {
      const ref = await this.pickTarget(`${it.name}をだれに使う？（残り${itemCount(g.me, id)}こ）`, dead, { start: last, note });
      if (!ref || !this.root) break;
      last = ref;
      // 返事を まつ（その 前に 自分と パーティーの 新しい ようすが とどく）。つづける ときは けっかを つぎの まどに 出す
      const res = await this.menuCall({ t: 'menu', action: 'useItem', id, ref }, goOn);
      if (!res || !goOn()) break;
      note = { text: res.text, cls: res.ok ? 'ok' : 'ng' };
      // うしろに 見えている 道具の 一覧も 新しい 数に（えらぶ のは まだ「だれに使う？」の まど）
      this.main.innerHTML = '';
      this.main.append(this.itemsList(true, focus));
    }
    if (this.root) this.focusSub(this.itemsList(true, focus));
  }

  // メニューの 操作を サーバーに おくって 返事（menuRes）を まつ。返事より 先に 自分と パーティーの 新しい ようすが とどく
  // （world/services.js の menuAction）。keep(返事) が true なら 知らせ（トースト）は 出さない（メニューの まどに 出す）。
  // 返事が こない（通信が きれた など）ときは null。
  // まつ あいだは すきとおった まくで 画面の タップを うけとめ、キーも すてる（うしろの 一覧を 2回 えらばない。十字キーの パッドも 出した まま）
  menuCall(msg, keep = null) {
    const g = this.game;
    const cover = el('div', { class: 'modal-back', style: { zIndex: 6, background: 'transparent' } });
    const hold = { onNav: () => {}, pad: true };
    document.getElementById('ui').append(cover);
    g.input.push(hold);
    return new Promise((resolve) => {
      const finish = (m) => {
        clearTimeout(timer);
        cover.remove();
        g.input.pop(hold);
        resolve(m);
      };
      const w = (m) => {
        finish(m);
        return !!keep?.(m);
      };
      const timer = setTimeout(() => {
        if (g.menuWaiter === w) g.menuWaiter = null;
        finish(null);
      }, 6000);
      g.menuWaiter = w;
      g.net.send(msg);
    });
  }

  // 帰り道の羽・ルーラの 行き先（行った ことの ある 町・村・港）
  // パーティーの ときは リーダーが 行った ことの ある 場所（リーダーと おなじ。サーバーの world/travel.js warpOwner）
  warpChoices() {
    const g = this.game;
    const helper = g.worldVisited && g.party && g.party.leader !== g.sid;
    const been = helper ? g.worldVisited : new Set(Object.keys(g.me.visited || {}).filter((k) => g.me.visited[k]));
    // 第67回: 千年前に いる 時は 千年前の 町だけ（data/past-places.js）
    const past = !!MAPS[g.field?.mapId]?.past;
    const towns = past
      ? Object.entries(PAST_PLACES).filter(([id]) => (helper ? been.has(id) : pastVisited(g.me, id))).map(([id, p]) => ({ label: p.name, value: id }))
      : Object.entries({ ...PLACES, ...SEA_PLACES }).filter(([id]) => been.has(id) && id !== 'shrine').map(([id, p]) => ({ label: p.name, value: id }));
    // 第59回: 最後にいのった場所（ダンジョンの 泉・教会。手伝っている ときは リーダーの いのりの場所。使えるかは サーバーが きめる）
    const pray = helper || (g.me.spawn && MAPS[g.me.spawn.map] && !/^(tm_|sd_)/.test(g.me.spawn.map));
    return pray ? [{ label: '最後にいのった場所', value: 'pray' }, ...towns] : towns;
  }

  // 不具合の 記録（この 端末の さいきんの もの）。コピーして 家族に 送れる
  errLogPopup() {
    const g = this.game;
    return new Promise((resolve) => {
      const text = errLogText();
      const back = el('div', { class: 'modal-back', style: { zIndex: 4 }, onclick: () => done() });
      const ta = el('textarea', { class: 'errlog-text', readonly: true });
      ta.value = text || '記録はありません（不具合はおきていません）';
      const box = el('div', { class: 'win panel center-panel', style: { width: 'min(94vw, 560px)', zIndex: 5, background: 'var(--win-solid)' } },
        el('div', { class: 'small gold', text: '不具合の記録（動けなくなった時などに、家族に送ってください）' }), ta);
      const copy = () => {
        const ok = () => toast('コピーしました。LINEなどにはりつけて送れます');
        const manual = () => {
          ta.focus({ preventScroll: true });
          ta.select();
          let r = false;
          try { r = document.execCommand('copy'); } catch { /* */ }
          toast(r ? 'コピーしました。LINEなどにはりつけて送れます' : '文字を長おしして、コピーしてください');
        };
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(ta.value).then(ok, manual);
        else manual();
      };
      const m = new ListMenu(g.input, {
        items: [{ label: 'コピーする', value: 'copy', disabled: !text }, { label: '記録を消す', value: 'clear', disabled: !text }, { label: '閉じる', value: null }],
        sound: this.sfx,
        back: null,
        onSelect: (it) => {
          if (it.value === 'copy') return copy();
          if (it.value === 'clear') {
            clearErrLog();
            toast('記録を消しました');
          }
          done();
        },
        onCancel: () => done(),
      });
      box.append(m.root);
      document.getElementById('ui').append(back, box);
      this.popupOpen = true;
      m.focus();
      const done = () => {
        m.blur();
        back.remove();
        box.remove();
        this.popupOpen = false;
        resolve();
      };
    });
  }

  // body: リストの 上に 出す 中み（さいきょう装備の 見こみ など）。その ときは えらびしを 横に ならべ、上下で 中みを スクロール
  // note: 題の すぐ 下の ひとこと（{ text, cls }。道具を 使った けっか〈ok・ng〉・設定の せつめい〈info〉）
  // start: はじめに カーソルを おく えらびしの value（えらべない ときは ふつうどおり 上から）
  // head: (m) => 題と リストの 間に 出す もの（装備の ならべかえ など。m … えらぶ リスト）。onSide: (d, m) … 左右（-1・1）
  // onMove: (it) … カーソルを うごかした とき（見た目装備の 見本を かえる など）
  // foot: リストの 下に 出す もの（装備の くらべる まど など）
  // big … 第76回: 画面を 大きく 使う まど（はばと 高さは CSS の .big-pick。装備を えらぶ まど）
  // tapConfirm … タップで ほかの 行を えらぶと カーソルと せつめい だけ うごく（もう一度 おすと 決まる。dom.js の ListMenu）
  pick(title, items, { wide = false, big = false, tapConfirm = false, cls = '', body = null, note = null, start, head = null, onSide = null, onMove = null, foot = null } = {}) {
    const g = this.game;
    return new Promise((resolve) => {
      const hasCancel = items.some((i) => i.value === null || i.value === 'cancel');
      const back = el('div', { class: 'modal-back', style: { zIndex: 4 }, onclick: () => { this.sfx('cancel'); done(null); } });
      const size = big ? {} : { width: wide ? 'min(94vw, 560px)' : 'min(86vw, 380px)' };
      const box = el('div', { class: `win panel center-panel ${big ? 'big-pick' : ''} ${cls}`, style: { ...size, zIndex: 5, background: 'var(--win-solid)' } }, el('div', { class: 'small gold pick-title', text: title }));
      const at = start === undefined ? -1 : items.findIndex((i) => i.value === start && !i.disabled && !i.header);
      const m = new ListMenu(g.input, {
        items,
        cols: body ? 2 : 1,
        sound: this.sfx,
        back: hasCancel ? null : 'やめる',
        start: at,
        tapConfirm,
        onSide: onSide ? (d) => onSide(d, m) : null,
        onMove: onMove || undefined,
        onSelect: (it) => done(it.value),
        onCancel: () => done(null),
      });
      if (note?.text) box.append(el('div', { class: `pick-note ${note.cls || ''}`, text: note.text }));
      if (head) box.append(head(m));
      if (body) {
        const nav = m.nav.bind(m);
        m.nav = (a, rep) => {
          if (a !== 'up' && a !== 'down') return nav(a, rep);
          body.scrollTop += (a === 'up' ? -1 : 1) * Math.max(40, body.clientHeight * 0.6);
        };
        box.append(body);
      }
      box.append(m.root);
      if (foot) box.append(foot);
      document.getElementById('ui').append(back, box);
      this.popupOpen = true;
      m.focus();
      const done = (v) => {
        m.blur();
        back.remove();
        box.remove();
        this.popupOpen = false;
        resolve(v);
      };
    });
  }

  partyRefs(dead = false) {
    const g = this.game;
    const p = g.party;
    const out = [];
    const st = computeStats(g.me);
    const fmt = (name, hp, maxHp, mp, maxMp) => `${name}　HP ${hp}/${maxHp}　MP ${mp}/${maxMp}`;
    out.push({ label: fmt(g.me.name, g.me.hp, st.maxHp, g.me.mp, st.maxMp), value: 'self', hp: g.me.hp });
    for (const m of p?.members || []) if (m.sid !== g.sid) out.push({ label: fmt(m.name, m.hp, m.maxHp, m.mp, m.maxMp), value: 'sid:' + m.sid, hp: m.hp });
    for (const s of p?.supports || []) out.push({ label: fmt(s.name, s.hp, s.maxHp, s.mp, s.maxMp), value: 'sup:' + s.key, hp: s.hp });
    for (const gu of p?.guests || []) out.push({ label: `${gu.name}　HP ${gu.hp}/${gu.maxHp}`, value: 'guest:' + gu.id, hp: gu.hp });
    // 馬車の 仲間（馬車が いっしょの とき。洞窟・塔の 中では 入り口で 待っている）
    if (wagonHereClient(g)) for (const w of p?.wagon || []) out.push({ label: fmt(`${w.name}（馬車）`, w.hp, w.maxHp, w.mp, w.maxMp), value: 'wagon:' + w.key, hp: w.hp });
    return out.map((o) => ({ ...o, disabled: dead ? o.hp > 0 : o.hp <= 0 }));
  }

  // opts: pick の start（カーソルを おく 人）・note（使った けっか）
  pickTarget(title, dead = false, opts = {}) {
    return this.pick(title, [...this.partyRefs(dead), { label: 'やめる', value: null }], { cls: 'pick-target', ...opts });
  }

  // ───── じゅもん・とくぎ ─────
  // 呪文・技: 「覚えた技・今使える・お気に入り・ひらめき・合体技」の タブ。上下で えらび、左右で タブを かえる
  skillsView(active, who = 'self') {
    const g = this.game;
    const c = this.charOf(who) || g.me;
    const box = el('div', { class: 'skills-view' });
    if (c.companion) box.append(el('div', { class: 'gold small', text: `${c.name}の呪文・技　MP ${c.mp}` }));
    const learned = learnedAbilities(c);
    const detail = el('div', { class: 'detail' });
    // スマホ: タップで せつめい、もう一度で 使う（道具・戦いと おなじ。第27回）
    const touch = !!g.input.touch;
    // フィールドで 使える 技（回復・回復以外。第69回）
    const sealed = !!g.field?.map?.noSpells;
    const usable = splitFieldAbilities(fieldUsableAbilities(c, { mapKind: g.field?.map?.kind, noSpells: sealed }));
    // はじめは 回復（なければ 回復以外 → 覚えた技）。まえに 見た タブが あれば そこ（前の「今使える」は 回復）
    const first = usable.heal.length ? 'heal' : usable.other.length ? 'other' : 'list';
    const mode = SKILL_TABS.some(([k]) => k === this.skillMode) ? this.skillMode : this.skillMode === 'now' ? 'heal' : first;
    if (mode !== 'fav' || this.favGrab?.who !== who) this.favGrab = null;
    const go = (m) => { this.skillMode = m; this.favGrab = null; this.focusSub(this.skillsView(true, who)); };
    const side = (d) => {
      const i = SKILL_TABS.findIndex(([k]) => k === mode);
      this.sfx?.('cursor');
      go(SKILL_TABS[(i + d + SKILL_TABS.length) % SKILL_TABS.length][0]);
    };
    // タブは スクロールしても 上に のこる
    const head = el('div', { class: 'sk-head' },
      el('div', { class: 'tabs' }, ...SKILL_TABS.map(([id, label]) => el('button', { class: `btn ${mode === id ? 'sel' : ''}`, text: label, onclick: () => go(id) }))),
      active ? el('div', { class: 'tab-hint', text: '◀ ▶（左右）でタブを切りかえ' }) : null);
    box.append(head);
    // 第78回 3-6: かんたん表示（設定。キャラごと〈自分の キャラの 設定。仲間の 画面も おなじ〉。shared/menu-view.js）。
    //   かくす だけ: 覚えた技の 見方・タブ／お気に入りの 動かす／えらぶ まどの「命令の一覧に出さない」。データは そのまま 効く
    const simple = menuSimple(g.me);
    if (simple) {
      this.favGrab = null;
      addSimpleCss();
      box.classList.add('sk-simple');
      head.append(el('div', { class: 'simple-note', text: SIMPLE_NOTE }));
    }
    // タブが 2行に なっても（せまい スマホ）えらんだ 行が タブの 下に かくれないように、見出しの 高さを はかる（CSS の scroll-margin-top）
    if (active && typeof ResizeObserver === 'function') {
      new ResizeObserver(() => { if (head.offsetHeight) box.style.setProperty('--sk-head-h', `${head.offsetHeight + 12}px`); }).observe(head);
    }
    // 上下で えらぶ リスト（左右で タブ）
    // 第71回 E: お気に入り・命令の 一覧・使う の あと（つくりなおした あと）も カーソルは おなじ 技に（前は いちばん 上に もどっていた）。
    //   カーソルの 技を this.skFocus に おぼえて、つぎに つくる ときに その 技から はじめる（おなじ 人・おなじ タブの とき）
    const list = (items, opts = {}) => {
      const f = this.skFocus;
      const at = f && f.who === who && f.mode === mode ? items.findIndex((it) => !it.header && it.value === f.id) : -1;
      const mv = opts.onMove;
      const m = this.mkSub({
        items, onSide: side, ...(at >= 0 ? { start: at } : {}), ...opts,
        onMove: (it, i) => {
          if (it && !it.header && it.value !== undefined && it.value !== 'back') this.skFocus = { who, mode, id: it.value };
          mv?.(it, i);
        },
      });
      box.append(m.root);
      return m;
    };
    const backOnly = () => list([{ label: 'もどる', value: 'back' }], { onSelect: () => this.back() });
    // ひらめき・合体技: 1つずつ 上下で 見られる（えらんでも なにも しない）
    const rows = (rs) => {
      if (active && rs.length) list(rs.map((r) => ({ html: r.html, value: r.id, cls: `sk-row ${r.cls || ''}` })), { onSelect: () => {} });
      else for (const r of rs) box.append(el('div', { class: `combo-row ${r.cls || ''}`, html: r.html }));
      if (active && !rs.length) backOnly();
    };
    // 使う（ルーラは 行き先、回復などは だれに を えらんで サーバーへ）。おわったら この タブに もどる
    const useSkill = async (id) => {
      const a = abilityFor(id, c);
      // ルーラ: 行き先を えらぶ（洞窟や 塔の 中では そのまま 唱えて 天井に ぶつかる）
      if (a.effect?.type === 'warp') {
        const inField = g.field.map?.kind === 'field';
        const place = inField ? await this.pick(`${a.name}：どこへ飛ぶ？`, [...this.warpChoices(), { label: 'やめる', value: null }]) : '';
        if (place !== null) {
          g.net.send({ t: 'menu', action: 'cast', id, place, who });
          if (place) { this.close(); return; }
        }
        this.reSkills(who);
        return;
      }
      // リレミト: 洞窟の 中で 使えれば メニューを とじて 外を 見せる（みちびきの糸と 同じ。shared/world/field27.js）
      if (a.effect?.type === 'exit') {
        const r = await this.menuCall({ t: 'menu', action: 'cast', id, ref: 'self', who });
        if (r?.ok) return this.close();
        this.reSkills(who);
        return;
      }
      let ref = 'self';
      if (a.target === 'self' && c.companion) ref = 'sup:' + c.key;
      else if (a.target !== 'allies' && a.target !== 'self') ref = await this.pickTarget(`だれに${a.name}？`, a.target === 'deadAlly');
      if (ref) g.net.send({ t: 'menu', action: 'cast', id, ref, who });
      this.reSkills(who, 200);
    };
    if (mode === 'heal' || mode === 'other') {
      // 回復・回復以外: フィールドで 使える 技だけ（shared/fieldskills.js）。MPが 足りない 技は 出すが えらべない。えらぶと すぐ 使う
      // 呪文が ふうじられた 場所（王家のピラミッド 2階）: 呪文は 出すが えらべない（特技は 使える）
      // 第69回: 回復（弱い じゅん）と 回復以外（ルーラ・リレミトが 上。あとは 弱い じゅん）に わけた
      const now = usable[mode];
      const why = { mp: 'MPが足りない', dead: '死んでいる', seal: '呪文がふうじられている' };
      if (!now.length) {
        box.append(el('div', { class: 'muted', text: mode === 'heal' ? '今ここで使える回復の呪文・技はない。\n回復の呪文などを覚えると、ここからすぐ使える。' : '今ここで使える回復以外の呪文・技はない。\nルーラは外で、リレミトはダンジョンの中で使える。' }));
        if (active) backOnly();
        return box;
      }
      if (!active) {
        for (const x of now) box.append(el('div', { class: 'sk-mini' }, el('span', { class: x.ok ? 'nm' : 'nm muted', text: abilityFor(x.id, c).name }), el('span', { class: 'muted small', text: `　MP${x.cost}　${skillBrief(abilityFor(x.id, c))}` })));
        return box;
      }
      const showNow = (it) => {
        const x = now.find((n) => n.id === it?.value);
        detail.textContent = x ? `${abilityDetail(x.id, c)}${x.ok ? '' : `\n（${why[x.why]}）`}${touch ? '\n▶もう一度タップで「使う・お気に入り」' : ''}` : '';
      };
      // 第71回: えらぶと 小さな まど（使う・お気に入り・命令の一覧に出さない・やめる。skillAsk）。いちばん 上が「使う」（決定 2回で すぐ 使える）。
      //   使えない 技（MPが 足りない など）も えらべる（お気に入り・命令の 一覧の ため）。「使う」が うすく なって わけが 出る
      const m = list(now.map((x) => {
        const a = abilityFor(x.id, c);
        const tt = targetTag(a);
        const hid = this.cmdHidden(c, x.id);
        return {
          html: `${esc(a.name)}${tt ? `<span class="tag tgt t-${a.target}">${tt}</span>` : ''}${x.ok ? '' : `<span class="tag muted">${why[x.why]}</span>`}${hid ? '<span class="tag cmdhide">かくす</span>' : ''}<span class="sk-desc">${esc(skillBrief(a))}</span>`,
          right: `MP${x.cost}`,
          rightCls: x.ok ? '' : 'dis',
          value: x.id,
          cls: `k-${abilityRole(a)} sk${x.ok ? '' : ' dis'}`,
        };
      }), {
        tapConfirm: touch,
        onMove: showNow,
        onSelect: async (it) => {
          const x = now.find((n) => n.id === it.value);
          this.sub.blur();
          const act = await this.skillAsk(c, it.value, { use: { ok: !!x?.ok, why: why[x?.why] || '今は使えない' } });
          if (act === 'use') return useSkill(it.value);
          const did = await this.doSkillAct(c, who, it.value, act);
          this.reSkills(who, did === 'cmd' ? 200 : 0);
        },
      });
      showNow(m.current);
      box.append(el('div', { class: 'small muted', text: `${c.name}のMP ${c.mp}　選ぶと「使う」「お気に入り」などを選べる` }), detail);
      if (sealed) box.append(el('div', { class: 'small gold', text: 'ここでは呪文がふうじられている。特技と道具は使える。' }));
      return box;
    }
    if (mode === 'combo') {
      // ひらめき: 関係する 技を 何回も 使うと、使った しゅんかんに ひらめく
      // 第32回: 出すのは その 人が 今 ついている 職業の ひらめき技だけ（掛け合わせ技は その 職業で ひらめける もの。stats.js の hiraOfJob）
      const known = new Set(learned);
      const use = c.skillUse || {};
      const shown = hiraOfJob(c);
      // ひらめいた 技が 上（どちらも 弱い じゅん。第69回）
      const order = sortByStdPower(shown).sort((x, y) => (known.has(y) ? 1 : 0) - (known.has(x) ? 1 : 0));
      rows(order.map((id) => {
        const a = abilityFor(id, c);
        const ok = known.has(id);
        const reqs = Object.entries(HIRAMEKI[id].from).map(([k, n]) => {
          const seen = k === '@atk' || known.has(k) || use[k] > 0;
          const nm = k === '@atk' ? 'ふつうの攻撃' : seen ? abilityFor(k, c)?.name : '？？？';
          return `${nm} ${seen ? Math.min(use[k] || 0, n) : '?'}/${n}回`;
        }).join('　');
        const prog = hiraProgress(c, id);
        const whoText = a.kind === 'combo' ? `掛け合わせ技（${comboJobNames(id, c).join('・')}とその超級職）` : '';
        const tag = ok ? '<span class="tag good">ひらめいた</span>' : prog >= 1 ? '<span class="tag gold">もうすぐ！</span>' : '';
        return {
          id, cls: ok ? '' : 'locked',
          html: `<span class="nm">${ok ? esc(a.name) : '？？？？'}</span>${tag}<span class="ln">${esc(reqs)}</span>${whoText ? `<span class="ln gold">${esc(whoText)}</span>` : ''}${ok ? `<span class="ln muted">${esc(skillBrief(a))}</span>` : ''}`,
        };
      }));
      const jobName = jobLabel(c.job, c);
      if (!order.length) box.append(el('div', { class: 'muted', text: jobName ? `${jobName}でひらめく技はない。` : 'ひらめく技はない。' }));
      box.append(el('div', { class: 'detail', text: `${c.name}の今の職業（${jobName || 'なし'}）でひらめく技だけ出している。ほかの職業の技は、その職業についた時に出る。\n書いてある回数をこえると、その技を使ったしゅんかんに、ひらめくことがある。神殿の「ひらめきの賢者」がヒントを教えてくれる。` }));
      return box;
    }
    if (mode === 'fav') {
      // お気に入り: 戦いの 呪文・特技の「★」の タブに この じゅんで 出る
      // 第69回: 戦いと おなじ 見え方（呪文・特技の 見出し・戦いの コマンドの 列の 数〈設定の コマンドの 数〉）。
      //   えらぶと「動かす・はずす」。動かす: つかんで 十字キーで となりと 入れかえ（見出しの 中だけ）→ 決定で おく・Bで もとに もどす
      const favs = (c.favorites || []).filter((id) => abilityFor(id, c) && learned.includes(id));
      const secs = FAV_SECS.map(([k, label]) => ({ k, label, ids: favs.filter((id) => favSection(abilityFor(id, c)) === k) })).filter((x) => x.ids.length);
      const cols = battleDensityPref() === 3 ? 3 : 2;
      const gr = this.favGrab;
      if (gr) {
        const sec = secs.find((x) => x.k === gr.sec);
        // お気に入りが かわった（ほかの 画面で はずした など）: つかむのを やめる
        if (!sec || sec.ids.length !== gr.orig.length || !sec.ids.every((id) => gr.orig.includes(id))) this.favGrab = null;
        else sec.ids = gr.ids;
      }
      const grab = this.favGrab;
      if (!favs.length) box.append(el('div', { class: 'muted', text: 'まだお気に入りはない。「覚えた技」で技を選んで「お気に入りに入れる」を選ぼう。' }));
      if (active && favs.length) {
        const items = [];
        for (const sec of secs) {
          items.push({ header: true, label: sec.label, cls: 'fav-h' });
          for (const id of sec.ids) {
            const a = abilityFor(id, c);
            const elm = a.effect?.element;
            const held = grab && grab.sec === sec.k && grab.ids[grab.pos] === id;
            const hid = this.cmdHidden(c, id);
            items.push({
              html: `${ELEMENT_NAMES[elm] ? `<span class="elem e-${elm}">${ELEMENT_NAMES[elm]}</span>` : ''}${esc(a.name)}${held ? '<span class="tag gold">つかんでいる</span>' : ''}`,
              right: a.effect?.type === 'mahouken' ? '▶' : `${mpCost(c, id)}`,
              value: id,
              sec: sec.k,
              cls: `k-${abilityRole(a)} fav${held ? ' grab' : ''}${grab && grab.sec !== sec.k ? ' dim' : ''}${hid ? ' cmd-off' : ''}`,
            });
          }
        }
        const at = grab ? items.findIndex((it) => it.value === grab.ids[grab.pos]) : -1;
        // 画面を つくりなおす（スクロールは そのまま。つかんだ 技が 見えるように）
        const redo = () => {
          const top = this.main.scrollTop;
          this.focusSub(this.skillsView(true, who));
          this.main.scrollTop = top;
          this.sub?.scrollToSel();
        };
        const endGrab = (ok) => {
          const gg = this.favGrab;
          this.favGrab = null;
          // おいた あとも その 技に カーソル
          this.favFocusId = gg ? gg.ids[gg.pos] : null;
          if (ok && gg && gg.ids.some((id, i) => id !== gg.orig[i])) {
            this.sendFavOrder(c, who, mergeSectionOrder(c.favorites || [], gg.orig, gg.ids));
            this.sfx('confirm');
          } else this.sfx(ok ? 'confirm' : 'cancel');
          redo();
        };
        const moveGrab = (dir) => {
          const gg = this.favGrab;
          const r = gg && moveInGrid(gg.ids, gg.pos, dir, cols);
          if (!r) { this.sfx('buzz'); return; }
          gg.ids = r.ids;
          gg.pos = r.pos;
          this.sfx('cursor');
          redo();
        };
        // 第71回: えらんでいる 技（つかんでいる 間は つかんだ 技）の せつめい。戦いの せつめいと おなじ 中身を みじかく（skillCardInfo）
        const info = el('div', { class: 'fav-info' });
        const showInfo = (id) => {
          const x = id && skillCardInfo(id, c);
          info.innerHTML = '';
          if (!x) return;
          const hid = this.cmdHidden(c, id);
          info.append(
            el('div', { class: 'fi-h' }, x.head, hid ? el('span', { class: 'fi-t', text: '命令の一覧に出さない' }) : null),
            x.pow ? el('div', { class: 'fi-p', text: x.pow }) : null,
            el('div', { class: 'fi-d', text: [x.desc, x.warn].filter(Boolean).join('') }),
          );
        };
        const m = list(items, grab ? {
          start: at,
          onSide: null,
          // タップ: おなじ 見出しの 技 → そこと 入れかえ・つかんでいる 技 → おく
          onSelect: (it) => {
            const gg = this.favGrab;
            if (!gg) return;
            const j = gg.ids.indexOf(it.value);
            if (j === gg.pos) return endGrab(true);
            if (j < 0) { this.sfx('buzz'); return redo(); }
            const ids = gg.ids.slice();
            [ids[gg.pos], ids[j]] = [ids[j], ids[gg.pos]];
            gg.ids = ids;
            gg.pos = j;
            this.sfx('cursor');
            redo();
          },
          onCancel: () => endGrab(false),
        } : {
          ...(this.favFocusId ? { start: items.findIndex((it) => it.value === this.favFocusId) } : {}),
          // 第71回: スマホは タップで せつめい、もう一度で「動かす・はずす」（ならべる 前に 技の 効果を 見られる）
          tapConfirm: touch,
          onMove: (it) => showInfo(it?.value),
          onSelect: async (it) => {
            this.sub.blur();
            // 動かす・お気に入りからはずす・命令の一覧に出さない／出す（第71回）・やめる
            // かんたん表示は skillAsk が「動かす」を 出さない（ならびは そのまま）
            const op = await this.skillAsk(c, it.value, { pre: [{ label: '動かす', value: 'move' }] });
            if (op === 'move') {
              const sec = secs.find((x) => x.k === it.sec);
              this.favGrab = { who, sec: sec.k, orig: sec.ids.slice(), ids: sec.ids.slice(), pos: sec.ids.indexOf(it.value) };
              return redo();
            }
            // おわったら その 技に カーソル（はずした ときは 先頭）
            this.favFocusId = op === 'remove' ? null : it.value;
            const did = await this.doSkillAct(c, who, it.value, op);
            this.reSkills(who, did === 'cmd' ? 200 : 0);
          },
        });
        this.favFocusId = null;
        m.root.classList.add('fav-grid');
        m.root.style.setProperty('--fcols', String(cols));
        // 第72回: お気に入りが 多い（60こ まで）ときも せつめいが 見える ように 下に はりつく（つかんでいる 間は ▲▼◀▶ が ある ので そのまま）
        if (!grab) this.stickInfo(box, info);
        showInfo(grab ? grab.ids[grab.pos] : m.current?.value);
        box.append(info);
        if (grab) {
          // つかんでいる 間: 十字キーで うごかす・A（決定）で おく・B で もとに もどす
          m.nav = (a) => {
            if (a === 'a') return endGrab(true);
            if (a === 'b') return endGrab(false);
            if (['up', 'down', 'left', 'right'].includes(a)) moveGrab(a);
          };
          box.classList.add('fav-grabbing');
          // スマホ: 画面の ▲▼◀▶ と「おく」「やめる」
          if (touch) {
            const kb = (text, aria, fn, cls = '') => el('button', { class: `btn ${cls}`, text, 'aria-label': aria, onclick: (e) => { e.stopPropagation(); fn(); } });
            box.append(el('div', { class: 'fav-grab-bar' },
              el('div', { class: 'fg-cross' }, kb('▲', '上へ', () => moveGrab('up'), 'fg-up'), kb('◀', '左へ', () => moveGrab('left'), 'fg-left'), kb('▶', '右へ', () => moveGrab('right'), 'fg-right'), kb('▼', '下へ', () => moveGrab('down'), 'fg-down')),
              el('div', { class: 'fg-ab' }, kb('おく', 'ここにおく', () => endGrab(true), 'gold'), kb('やめる', 'やめる', () => endGrab(false)))));
          }
        }
        box.append(el('div', { class: grab ? 'small muted' : 'detail', text: grab
          ? `「${abilityFor(grab.ids[grab.pos], c).name}」をつかんでいる。${touch ? '▲▼◀▶で動かして「おく」。ほかの技をタップすると、そこと入れかわる。' : '十字キーで動かして、決定でおく。Bでやめる（元にもどる）。'}`
          : simple ? '戦いの「★」のタブと同じならび（呪文と特技に分かれる）。選ぶと「お気に入りからはずす」を選べる。'
            : '戦いの「★」のタブと同じならび（呪文と特技に分かれる）。選ぶと「動かす」「はずす」「命令の一覧に出さない」を選べる。動かすと、つかんだ技を十字キーで動かせる。' }));
      } else if (favs.length) {
        for (const sec of secs) box.append(el('div', { class: 'small', text: `${sec.label}：${sec.ids.map((id) => abilityFor(id, c).name).join('、')}` }));
        box.append(el('div', { class: 'detail', text: '戦いで呪文・特技を開くと、「★」のタブにこのじゅんで出る。' }));
      } else if (active) backOnly();
      return box;
    }
    if (mode === 'dual') {
      // 合体技: 2人の 番を 使う 技。出すのは 使った ことの ある 技と、今の パーティーに 関係する 技だけ（dual.js の dualRelated）
      // 第31回: 名前は 1行に 名前だけ（第71回: 大きさは ふつうの 技と おなじ。dualfx.js の CSS）。人数・MP・必要な 職業は 下の 行に
      addDualCss();
      const focus = this.partyFocus(c);
      const shownDual = DUAL_ORDER.filter((id) => dualKnown(c, id) || dualKnown(g.me, id) || dualRelated(id, focus.jobs, focus.skills));
      const hiddenDual = DUAL_ORDER.length - shownDual.length;
      // 2人技・3人技・4人技の じゅんに（同じ 人数の 中は DUAL_ORDER の じゅん）
      shownDual.sort((x, y) => DUAL_TECHS[x].need.length - DUAL_TECHS[y].need.length);
      // 名前は 見ている キャラ（その 組で ない ときは パーティー）むけ（男の子の 美少女戦士は タキシード仮面ふう）
      const mates = [g.me, ...(g.party?.members || []), ...(g.party?.supports || [])];
      rows(shownDual.map((id) => {
        const t = dualForView(id, c, mates);
        const n = t.need.length;
        // はじめて 使う までは 効果は ひみつ
        const known = dualKnown(c, id) || dualKnown(g.me, id);
        return {
          id, cls: `dual-row n${n}${known ? '' : ' unknown'}`,
          html: `<span class="nm dual-nm">${esc(t.name)}</span><span class="ln">${esc(`${n}人技・MP ${t.mp.join('＋')}・${dualNeedLabel(id)}：${dualNeedText(id, false, c)}`)}</span><span class="ln muted">${known ? esc(t.desc) : '効果は？？？（一度使うとわかる。まだ使っていない）'}</span>`,
        };
      }));
      if (!shownDual.length) box.append(el('div', { class: 'muted', text: '今のパーティーで出せそうな合体技は、まだない。' }));
      box.append(el('div', { class: 'detail', text: (hiddenDual > 0 ? `今のパーティーの職業に関係する合体技だけ出している（ほかにあと${hiddenDual}こ）。\n` : '') + '合体技は、2人・3人・4人でいっしょに出す技。出せるかは、今ついている職業で決まる。出す人みんなの番を使う。自分のゲージがたまった時に「合体技」から選んでおく。いっしょに出す仲間のゲージがたまっていればすぐ、まだの時は「よやく」して、みんなのゲージがたまった時にいっしょに出す（先にたまった仲間は、ほかの仲間を待つ）。\nよやくで待っている間にダメージを受けると、その人のゲージは半分からやり直し。どんな効果かは、一度使うまでわからない。家族のキャラと出す時は、相手の画面に「参加する？」と出る。' }));
      return box;
    }
    // 第69回: 弱い じゅん（ダメージ・回復の 量。職業の ほせい なし。shared/skill-sort.js）
    const order = sortByStdPower(learned);
    if (!order.length) {
      box.append(el('div', { class: 'muted', text: 'まだ何も覚えていない。' }));
      if (active) backOnly();
      return box;
    }
    if (!active) {
      for (const id of order.slice(0, 12)) box.append(el('div', { class: 'sk-mini' }, el('span', { class: 'nm', text: abilityFor(id, c).name }), el('span', { class: 'muted small', text: `　${skillBrief(abilityFor(id, c))}` })));
      if (learned.length > 12) box.append(el('div', { class: 'small muted', text: `ほか${learned.length - 12}こ` }));
      box.append(el('div', { class: 'detail', text: '「他」は今の職業以外で覚えた技。MPが増えたり、威力が下がったりする。' }));
      return box;
    }
    // 第71回 E: 2列の わく（戦いの 技の 一覧・お気に入りと おなじ 列の 数と 色の わく）で、2つの 見方（shared/skill-view.js）
    //   種類で見る: 呪文・特技 → 今の職業・攻撃1体・攻撃全体・回復・強くする・弱くする・そのほか（戦いの タブと おなじ）
    //   職業で見る: 覚えた 職業ごと（今の 職業が 先）・そのほか（ひらめき など）
    //   タブは L・R（Q・E）か タップ。見方は Y か 画面の ボタン。見方と タブは この 機械に おぼえる（learnPref）
    // 第78回 3-6: かんたん表示は 見方・タブを 出さない。強い じゅんの 1つの 一覧（2列だけ）。前に えらんだ 見方・タブ（learnPref）は そのまま
    const pref = this.learnPref();
    const view = pref.view === 'job' ? 'job' : 'kind';
    //   第78回 追加: 「今の職業の技」（強い じゅん）→「ほかの職業の技」（強い じゅん）の 見出しで 分ける（simpleLearnGroups）
    const groups = simple ? simpleLearnGroups(learned, c.species ? null : c.job, (id) => abilityFor(id, c)) : [];
    const tabs = simple ? [{ key: 'simple', id: 'simple', label: '', ids: groups.flatMap((gr) => gr.ids) }]
      : view === 'job' ? learnedJobTabs(c, learned) : learnedKindTabs(learned, { abs: (id) => abilityFor(id, c), job: c.job });
    const cur = simple ? tabs[0] : pickLearnTab(tabs, pref.tab?.[view]);
    const cols = !simple && battleDensityPref() === 3 ? 3 : 2;
    const goTab = (t) => {
      if (!t || t.key === cur.key) return;
      const p = this.learnPref();
      p.tab = { ...(p.tab || {}), [view]: t.key };
      this.saveLearnPref(p);
      this.sfx('cursor');
      this.reSkills(who);
    };
    const setView = (v) => {
      if (v === view) return;
      const p = this.learnPref();
      p.view = v;
      this.saveLearnPref(p);
      this.sfx('cursor');
      this.reSkills(who);
    };
    const chip = (text, on, fn, cls = '', dis = false) => el('button', { class: `btn ${on ? 'sel' : ''} ${cls}`, text, disabled: dis, onclick: (e) => { e.stopPropagation(); fn(); } });
    // 第72回: 家族の ねがい「覚えた技を一覧で見ているとき、上部の技カテゴリは見えるようにしていて」。
    //   見方（種類で見る／職業で見る）・呪文／特技・種類（職業）の タブも、上の タブと いっしょに 上に はりつく 見出し（.sk-head）の 中へ。
    //   技の わくだけが スクロールする（下の せつめいも はりつく）。見出しの 高さは はかって いる ので（--sk-head-h）、カーソルの 技は 見出しの 下に かくれない
    head.classList.add('lv-head');
    head.querySelector('.tab-hint')?.remove();
    if (!simple) head.append(el('div', { class: 'lv-bar' },
      el('div', { class: 'lv-views', role: 'tablist' }, ...Object.entries(LEARN_VIEWS).map(([k, label]) => chip(label, k === view, () => setView(k), 'lv-v'))),
      view === 'kind' ? el('div', { class: 'lv-secs' }, ...LEARN_SECS.map(([k, label]) => {
        const first = tabs.find((t) => t.sec === k);
        return chip(label, cur.sec === k, () => goTab(first), 'lv-s', !first);
      })) : null));
    const subs = view === 'kind' ? tabs.filter((t) => t.sec === cur.sec) : tabs;
    if (!simple) {
      const subBar = el('div', { class: 'tabs lv-tabs' }, ...subs.map((t) => chip(t.label, t.key === cur.key, () => goTab(t), `lv-t${t.id === c.job || t.id === 'job' ? ' now' : ''}`)));
      head.append(subBar);
      // スマホは タップで えらぶ ので 書かない（見出しを ひくく して、技の わくを 広く）
      // 第79回: コントローラーが つながって いる 時は コントローラーの ボタンで 書く（スマホに つないだ 時も 出す）。
      //   Y は 左（Switch など）・上（Xbox など）の どちらの Y でも 効く（input.js）
      if (g.input.pad?.on) head.append(el('div', { class: 'tab-hint pad-hint', text: 'コントローラー：L・Rで種類・Yで見方・◀ ▶（左右のはし）で上のタブ' }));
      else if (!touch) head.append(el('div', { class: 'tab-hint', text: 'L・R（Q・E）で種類・Yで見方・◀ ▶（左右のはし）で上のタブを切りかえ' }));
      // 選んでいる 種類（職業）の タブが 見えるように（横に ながい とき）
      requestAnimationFrame(() => subBar.querySelector('.btn.sel')?.scrollIntoView?.({ block: 'nearest', inline: 'nearest' }));
    } else if (!touch) head.append(el('div', { class: 'tab-hint', text: '今の職業の技が先（強い技が上）・◀ ▶（左右のはし）で上のタブを切りかえ' }));
    // 技の わく: ★ … お気に入り / かくす … 命令の 一覧に 出さない（わくも 点線）/ 他 … 今の 職業 いがいの 技
    const favSet = new Set(c.favorites || []);
    const row = (id) => {
      const a = abilityFor(id, c);
      const elm = a.effect?.element;
      const pen = penaltyFor(c, id).penalized;
      const locked = a.kind === 'combo' && !comboAllowed(c, id);
      const hid = this.cmdHideable(a) && this.cmdHidden(c, id);
      return {
        html: `${favSet.has(id) ? '<span class="favmk">★</span>' : ''}${hid ? '<span class="tag cmdhide">かくす</span>' : ''}${ELEMENT_NAMES[elm] ? `<span class="elem e-${elm}">${ELEMENT_NAMES[elm]}</span>` : ''}${esc(a.name)}${pen ? '<span class="tag warn">他</span>' : ''}`,
        right: a.effect?.type === 'mahouken' ? '' : `${mpCost(c, id)}`,
        rightCls: pen ? 'pen' : '',
        value: id,
        cls: `k-${abilityRole(a)} fav${hid ? ' cmd-off' : ''}${locked ? ' dis' : ''}`,
      };
    };
    // かんたん: 見出し（今の職業の技・ほかの職業の技）を はさむ（見出しは えらべない。お気に入りの わくと おなじ）
    const items = simple
      ? groups.flatMap((gr) => [...(gr.label ? [{ header: true, label: gr.label, cls: 'fav-h' }] : []), ...gr.ids.map(row)])
      : cur.ids.map(row);
    // 効果の 目安（数）・技の レベルと 使った 回数（第38回 C）
    const lvLine = (id) => {
      const n = c.skillUse?.[id] || 0;
      const left = skillLvLeft(n);
      return `技Lv${skillLevel(c.skillUse, id)}（使った回数: ${n}回${left === null ? '・いちばん上' : `・つぎのLvまであと${left}回`}）`;
    };
    // えらんでいる 技の せつめい（お気に入りの まどと おなじ。skillCardInfo）
    const info = el('div', { class: 'fav-info lv-info' });
    const showInfo = (it) => {
      info.innerHTML = '';
      const id = it?.value;
      const x = id && skillCardInfo(id, c);
      if (!x) return;
      const a = abilityFor(id, c);
      const locked = a.kind === 'combo' && !comboAllowed(c, id);
      const hid = this.cmdHideable(a) && this.cmdHidden(c, id);
      info.append(
        el('div', { class: 'fi-h' }, x.head, favSet.has(id) ? el('span', { class: 'fi-t gold', text: '★お気に入り' }) : null, hid ? el('span', { class: 'fi-t', text: '命令の一覧に出さない' }) : null),
        x.pow ? el('div', { class: 'fi-p', text: x.pow }) : null,
        el('div', { class: 'fi-d', text: [x.desc, x.warn, locked ? '⚠掛け合わせ技（上級職で使える）' : ''].filter(Boolean).join('') }),
        el('div', { class: 'fi-l', text: `${lvLine(id)}${touch ? '　▶もう一度タップで「使う・お気に入り」' : ''}` }),
      );
    };
    const m = list(items, {
      tapConfirm: touch,
      onMove: showInfo,
      // 第71回 E: L・R（Q・E）で タブ・Y で 見方
      ...(simple ? {} : {
        onLR: (d) => goTab(nextLearnTab(tabs, cur.key, d)),
        onY: () => setView(view === 'job' ? 'kind' : 'job'),
      }),
      onSelect: async (it) => {
        const a = abilityFor(it.value, c);
        const locked = a.kind === 'combo' && !comboAllowed(c, it.value);
        this.sub.blur();
        // 第71回: 使う・お気に入り・命令の一覧に出さない／出す・やめる（skillAsk）
        const act = await this.skillAsk(c, it.value, { use: a.field && !locked ? { ok: true } : null });
        const did = await this.doSkillAct(c, who, it.value, act);
        if (did) return this.reSkills(who, did === 'cmd' ? 200 : 0);
        if (act !== 'use') return this.reSkills(who);
        await useSkill(it.value);
      },
    });
    m.root.classList.add('fav-grid', 'learn-grid');
    m.root.style.setProperty('--fcols', String(cols));
    this.stickInfo(box, info);
    showInfo(m.current);
    box.append(info, el('div', { class: 'small muted', text: simple
      ? '今の職業の技が先で、その中は強い技が上。選ぶと「使う」「お気に入り」を選べる。★…お気に入り　他…今の職業ではない技'
      : '選ぶと「使う」「お気に入り」「命令の一覧に出さない」を選べる。★…お気に入り　かくす…自分で命令する時、戦いの技の一覧に出さない技（オートで使うかは作戦で決める）　他…今の職業ではない技' }));
    return box;
  }

  // 第72回: 下に はりつく せつめい（覚えた技・お気に入り）。その 高さを はかって、カーソルの 技が せつめいの 下に かくれない ように（--sk-info-h）
  stickInfo(box, info) {
    box.classList.add('sticky-info');
    info.classList.add('lv-info');
    // まどの 下の すきま（.main の padding）にも はりつく（すきまから うしろの 技が のぞかない ように）
    const pb = this.main ? parseFloat(getComputedStyle(this.main).paddingBottom) || 0 : 0;
    if (pb > 0) info.style.bottom = `${-pb}px`;
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(() => { if (info.offsetHeight) box.style.setProperty('--sk-info-h', `${info.offsetHeight + 12}px`); }).observe(info);
    }
  }

  // 第71回 E: つくりなおす（カーソルは おなじ 技・スクロールも そのまま。お気に入り・命令の 一覧・使う の あと）
  reSkills(who, delay = 0) {
    const run = () => {
      if (!this.root) return;
      const top = this.main.scrollTop;
      this.focusSub(this.skillsView(true, who));
      this.main.scrollTop = top;
      this.sub?.scrollToSel();
    };
    if (delay) setTimeout(run, delay);
    else run();
  }

  // 第71回 E: 覚えた技の 見方と タブ（この 機械に おぼえる。{ view: 'kind'|'job', tab: { kind, job } }）
  learnPref() {
    try {
      const v = JSON.parse(localStorage.getItem('kizuna_learnview') || '{}');
      return v && typeof v === 'object' ? v : {};
    } catch { return {}; }
  }

  saveLearnPref(v) {
    try { localStorage.setItem('kizuna_learnview', JSON.stringify(v)); } catch { /* */ }
  }

  // 第69回: お気に入りの ならびを まとめて おくる（つかんで 動かした あと。画面の キャラにも すぐ 入れる）
  sendFavOrder(c, who, ids) {
    const list = Array.isArray(c.favorites) ? c.favorites : (c.favorites = []);
    list.splice(0, list.length, ...ids);
    this.game.net.send({ t: 'menu', action: 'favorite', who: who || 'self', op: 'order', ids });
  }

  // お気に入りを サーバーに おくる（画面の キャラにも すぐ 入れる）。もどりち: 入れた・はずした か
  // 第72回: 家族の ねがい「覚えた技からお気に入りにしても、お気に入りにならない」。
  //   ・まえは 30こ いっぱいの とき、画面は ★に しても サーバーが だまって すてていた（返事は「入れた」）
  //     → FAV_MAX こまで に ふやし、いっぱいの ときは 入れずに わけを 出す（shared/favorites.js の favApply。サーバーと おなじ きまり）
  //   ・まえは 200ミリ秒 まって 画面を つくりなおしていた。その 間に 前の 自分（self）が とどくと ★が 消え、
  //     サーバーの 新しい 自分が とどいても 画面は つくりなおさなかった（家族サーバー）
  //     → サーバーの 返事（menuRes。新しい 自分の あとに とどく）を まってから つくりなおす（menuCall）
  //   もどりちは Promise（返事が きたら true・false）
  sendFav(c, who, id, op) {
    const r = favApply(c.favorites, id, op, new Set(learnedAbilities(c)));
    if (!r.ok) {
      if (r.full) {
        toast(FAV_FULL_TEXT);
        this.sfx('buzz');
      }
      return Promise.resolve(false);
    }
    const list = Array.isArray(c.favorites) ? c.favorites : (c.favorites = []);
    list.splice(0, list.length, ...r.list);
    return this.menuCall({ t: 'menu', action: 'favorite', who: who || 'self', id, op }).then((res) => (res ? !!res.ok : true));
  }

  // ───── 第71回: 命令の 一覧に 出さない 技（cmdOff。shared/cmd-off.js）─────
  // 戦いの 命令の 一覧に 出る ことの ある 技か（ルーラなど フィールドだけの 技・きずな技は 出ない ので 切りかえも 出さない）
  cmdHideable(a) {
    return !!a && !a.fieldOnly && !a.hidden && a.kind !== 'bond';
  }

  // 今 命令の 一覧に 出さない ことに なっているか（同じ 名前の 技の どれかが 出さない なら 出さない。サーバーと おなじ）
  cmdHidden(c, id) {
    const off = cmdOffList(c);
    if (!off.length) return false;
    if (off.includes(id)) return true;
    const nm = abilityFor(id, c)?.name;
    return !!nm && off.some((x) => abilityFor(x, c)?.name === nm);
  }

  // 「命令の 一覧に 出す／出さない」を 切りかえる（サーバーの cmdSkill。画面の キャラにも すぐ 入れる）。もどりち: 出さない に したか
  toggleCmdOff(c, who, id) {
    const key = who || 'self';
    const hide = !this.cmdHidden(c, id);
    const nm = abilityFor(id, c)?.name;
    const same = learnedAbilities(c).filter((x) => x === id || abilityFor(x, c)?.name === nm);
    const cur = cmdOffList(c);
    this.setOffLocal(key, 'cmdOff', hide ? [...new Set([...cur, ...same])] : cur.filter((x) => !same.includes(x)));
    this.game.net.send({ t: 'menu', action: 'cmdSkill', key, id, op: hide ? 'off' : 'on' });
    return hide;
  }

  // 画面の キャラ（自分・仲間）の autoOff・cmdOff を すぐ かえる（サーバーの 返事を またない）
  setOffLocal(key, field, list) {
    const g = this.game;
    const src = key === 'self' ? g.me : [...(g.party?.supports || []), ...(g.party?.wagon || [])].find((x) => x.key === key && x.owner === g.me.id);
    if (!src) return;
    // autoOff を かえる 前に cmdOff を きめておく（まだ うつして いない 人の 命令の 一覧が かわらない ように。サーバーの fixCmdOff と おなじ）
    if (field === 'autoOff' && !Array.isArray(src.cmdOff)) src.cmdOff = cmdOffList(src);
    src[field] = list;
  }

  // 第71回: 呪文・技の メニューで 技を えらんだ ときの 小さな まど（覚えた技・回復・回復以外・お気に入り）
  //   use: null … 「使う」を 出さない / { ok, why } … いちばん 上（カーソルも ここ。決定 2回で すぐ 使える）。使えない ときは うすく・わけ
  //   pre: 「お気に入り」の 前に 入れる 行（お気に入りの「動かす」）
  //   つぎ: お気に入りに入れる／はずす → 命令の一覧に出さない／出す（戦いに 出る 技だけ）→ やめる
  skillAsk(c, id, { use = null, pre = [] } = {}) {
    const a = abilityFor(id, c);
    const fav = (c.favorites || []).includes(id);
    const hidden = this.cmdHidden(c, id);
    // 第72回: お気に入りが いっぱい（FAV_MAX こ）の ときは 入れられない ことと わけを 出す（まえは だまって 入らなかった）
    const full = !c.species && !fav && favFull(c.favorites, new Set(learnedAbilities(c)));
    // 第78回 3-6: かんたん表示は「使う／お気に入り／やめる」だけ（お気に入りの「動かす」・命令の 一覧の 切りかえを 出さない。
    //   前に 決めた ならび・命令に 出さない 技は そのまま 効く）。自分の キャラの 設定（仲間の 画面も おなじ）
    const simple = menuSimple(this.game.me);
    const items = [];
    if (use) items.push(use.ok ? { label: '使う', value: 'use' } : { label: `使う（${use.why}）`, value: 'use', disabled: true });
    if (!simple) items.push(...pre);
    if (full) items.push({ label: `★ お気に入りに入れる（${FAV_MAX}こでいっぱい）`, value: 'add', disabled: true });
    else if (!c.species) items.push({ label: fav ? 'お気に入りからはずす' : '★ お気に入りに入れる', value: fav ? 'remove' : 'add' });
    if (!simple && this.cmdHideable(a)) items.push({ label: hidden ? '命令の一覧に出す' : '命令の一覧に出さない', value: 'cmd' });
    items.push({ label: 'やめる', value: null });
    const note = [full ? FAV_FULL_TEXT : '', hidden ? (simple ? '今は、戦いの命令の一覧に出していない（くわしい表示で変えられる）。' : '今は、戦いの命令の一覧に出していない。') : ''].filter(Boolean).join('\n');
    return this.pick(a.name, items, note ? { note: { text: note, cls: 'muted' } } : {});
  }

  // skillAsk の「お気に入り」「命令の一覧」を おこなう。もどりち: 'fav'（サーバーの 返事まで まった）・'cmd'・false（ほかの 答え）
  async doSkillAct(c, who, id, act) {
    if (act === 'add' || act === 'remove') {
      await this.sendFav(c, who, id, act);
      return 'fav';
    }
    if (act === 'cmd') {
      this.toggleCmdOff(c, who, id);
      return 'cmd';
    }
    return false;
  }

  // ───── そうび ─────
  equipView(active, who = 'self') {
    const g = this.game;
    const c = this.charOf(who) || g.me;
    const box = el('div');
    const detail = el('div', { class: 'detail' });
    const st = computeStats(c);
    const stats = el('div', { class: 'small', text: `攻撃 ${st.atk}　守備 ${st.dfn}　素早さ ${st.agi}　魔力 ${st.mag}　回復 ${st.heal}` });
    const mons = this.myMates().filter((x) => x.species).map((x) => ({ name: x.name, species: x.species }));
    // モンスターの なかまは しゅぞくで 装備できる 部位が きまる（ドラクエ5 ふう。今 何か 装備している 部位は 出す）
    const slots = c.species ? SLOTS.filter((sl) => monsterSlots(c.species).includes(sl) || c.equip?.[sl]) : SLOTS;
    // 第65回: れん金の 効果を 名前の よこに（［炎+3・追撃+5］）
    const fxTag = (id) => { const f = id ? fxShort(fxListOf(c, id)) : ''; return f ? `<span class="muted small">［${esc(f)}］</span>` : ''; };
    const items = slots.map((sl) => ({ label: `${SLOT_NAMES[sl]}：${c.equip?.[sl] ? ITEMS[c.equip[sl]].name : 'なし'}`, html: `${SLOT_NAMES[sl]}：${c.equip?.[sl] ? rareNameHtml(c.equip[sl]) + fxTag(c.equip[sl]) : 'なし'}`, value: sl }));
    // ドラクエの「さいきょう装備」: ふくろの 中で いちばん 強い ものを まとめて 装備
    // （「みんなさいきょう装備」は だれの装備？ の 一覧に ある。whoView）
    items.push({ label: 'さいきょう装備', value: '__best' });
    // 見た目装備（強さは かわらない。モンスターは 絵に 装備が 出ないので ない。lookView）
    if (!c.species) items.push({ label: '見た目装備', value: '__look' });
    if (c.companion) box.append(el('div', { class: 'gold small', text: `${c.name}の装備` }));
    // 魔物の 装備できる 物（リストの 下に。リストが 画面から はみ出さない ように）
    const gear = c.species ? el('div', { class: 'small muted', text: `装備できる物: ${gearText(c.species)}` }) : null;
    if (!active) {
      for (const it of items) box.append(el('div', { text: it.label }));
      box.append(stats, ...(gear ? [gear] : []));
      return box;
    }
    const m = this.mkSub({
      items,
      onMove: (it) => {
        if (it.value === '__best') detail.textContent = 'ふくろの中から、攻撃力・守備力がいちばん上がる武器・よろい・たて・かぶとを選ぶ（アクセサリーはそのまま）\n何が何に変わるかを見てから、決められる';
        else if (it.value === '__look') detail.textContent = LOOK_HELP;
        else {
          const eid = c.equip?.[it.value];
          // 第64回 ⑥c: れん金で つけた 効果（data/gear-fx.js）
          const fl = eid ? fxListOf(c, eid) : [];
          detail.textContent = eid ? `E ${ITEMS[eid].name}（装備している）${fl.length ? `\nれん金の効果：${fl.map((x) => fxText(x.k, x.v)).join('・')}` : ''}\n${itemDetail(eid, mons, c)}` : '';
        }
      },
      onSelect: async (it) => {
        const slot = it.value;
        if (slot === '__look') return this.pushView(() => this.lookView(who));
        if (slot === '__best') {
          // いきなり 変えずに「何が 何に 変わるか」を 見せてから えらぶ
          this.sub.blur();
          const done = await this.bestEquipAsk(who);
          setTimeout(() => this.redraw(), done ? 250 : 0);
          return;
        }
        this.sub.blur();
        const changed = await this.pickGear(c, who, slot);
        // おなじ 部位に カーソルを おいた まま つくりなおす
        setTimeout(() => this.redraw(), changed ? 200 : 0);
      },
    });
    box.append(m.root, stats, ...(gear ? [gear] : []), detail);
    return box;
  }

  // 1つの 部位を えらぶ まど。出すのは その 人が 装備できる 物だけ（ふくろの 物と、ほかの 仲間が 装備している 物。shared/equip-plan.js の gearChoices）。
  // ならびは「入手順」（ふくろの じゅん）か「強さ順」（みんなさいきょう装備と おなじ くらべかた。いちばん 上が さいきょう装備で えらぶ 物）。
  // 上の ボタンか 左右で 切りかえ（この 端末に おぼえる）。「外す」「やめる」は いつも 下。
  // 仲間が 装備している 物を えらぶと「装備を入れかえる？」→ はい で 入れかえ（サーバーの swapEquip）。
  // 1つの 物を 2行で: 名前 ／ 変わる 強さ（上がる ものも 下がる ものも。いつも おなじ じゅん）。変えたら true
  async pickGear(c, who, slot) {
    const g = this.game;
    const cur = c.equip?.[slot] || null;
    const before = computeStats(c);
    const changes = (id) => statChanges(before, computeStats({ ...c, equip: { ...(c.equip || {}), [slot]: id } }));
    // 第64回: 1行に 装備 そのものの 強さ（白）と 今の 装備との 差（色）。強い 上から 3つに「おすすめ」
    const own = (id) => gearOwnStats(c, slot, id);
    // 第76回: きたえた・れん金の 物は 強さの よこに「もと+68」（きたえる 前の 強さ。shared/gear-base.js）。
    // 今は 弱いが もとの 強さが 今の 装備より 上の 物に「もとが強い」（きたえると 強く なるかも）
    const row = (nameHtml, tag, id, rec = false, baseUp = false) => `<span class="eq-nm">${nameHtml}${tag ? `<span class="tag eq-tag">${esc(tag)}</span>` : ''}${rec ? '<span class="tag eq-rec">おすすめ</span>' : ''}${baseUp ? '<span class="tag eq-baseup">もとが強い</span>' : ''}</span><span class="eq-sc">${gearRowHtml(own(id), changes(id), id && hasBoost(c, id) ? gearOwnBase(c, slot, id) : null)}</span>`;
    // 自分と 仲間（パーティー・馬車）が 装備している 物も 候補（入れかえ）
    const others = this.teamChars().filter((m) => m.key !== who);
    const nameOf = (key) => others.find((m) => m.key === key)?.char.name || '';
    const choices = gearChoices(c, slot, g.me, others);
    // おすすめ: 今の 装備より 強い 物の 上から 3つ（ふくろの 物だけ。同じ 物は 1つと 数える）
    const curScore = gearScore(c, slot, cur);
    const recs = new Set(sortGearChoices(choices, 'power').filter((x) => !x.from && x.id !== cur && x.score > curScore).slice(0, 3).map((x) => x.id));
    const baseUp = new Set(choices.filter((x) => x.id !== cur && x.score <= curScore && baseStronger(c, slot, cur, x.id)).map((x) => x.id));
    let mode = gearSortPref();
    const rows = () => {
      const opts = sortGearChoices(choices, mode).map((x) => (x.from
        ? { html: row(rareNameHtml(x.id), `${nameOf(x.from)}が装備中`, x.id, false, baseUp.has(x.id)), value: `swap:${x.from}`, cls: 'eq-opt eq-swap' }
        : { html: row(rareNameHtml(x.id), x.n > 1 ? `×${x.n}` : '', x.id, recs.has(x.id), baseUp.has(x.id)), value: x.id, cls: 'eq-opt' }));
      if (!opts.length) opts.push({ header: true, label: '装備できる物を持っていない', cls: 'eq-none' });
      if (cur) opts.push({ html: row(esc('外す'), '', null), value: '__off', cls: 'eq-opt' });
      opts.push({ label: 'やめる', value: null });
      return opts;
    };
    // 入手順・強さ順の 切りかえ（候補が 2つ いじょうの とき。切りかえたら カーソルは いちばん 上）
    const keys = Object.keys(GEAR_SORTS);
    let chips = null;
    const setMode = (k, m) => {
      if (!GEAR_SORTS[k] || k === mode) return;
      mode = k;
      setGearSortPref(k);
      this.sfx('cursor');
      for (const b of chips?.querySelectorAll('.btn') || []) b.classList.toggle('on', b.dataset.k === mode);
      m.setItems(rows(), false);
      m.root.scrollTop = 0;
    };
    const head = choices.length > 1 ? (m) => (chips = el('div', { class: 'tabs sort-tabs gear-sort' },
      el('span', { class: 'small muted', text: 'ならび' }),
      ...keys.map((k) => el('button', { class: `btn ${k === mode ? 'on' : ''}`, 'data-k': k, text: GEAR_SORTS[k], onclick: (e) => { e.stopPropagation(); setMode(k, m); } })),
      // 左右の キー（スマホは ウインドウの 十字キー）でも 切りかえられる
      !g.input.touch || g.input.padOn ? el('span', { class: 'tab-hint', text: '◀▶で切りかえ' }) : null)) : null;
    const onSide = head ? (d, m) => setMode(keys[(keys.indexOf(mode) + d + keys.length) % keys.length], m) : null;
    // 第64回: くらべる まど（今の 装備 → えらんでいる 物。どちらも 装備 そのものの 強さ）
    // 第76回: 大きな まどに（よこ画面は 右・たて画面は 下）。今の 強さと もとの 強さ・同じだけ きたえると（client/ui/equip-compare.js）
    const foot = el('div', { class: 'eq-compare' });
    const onMove = (it) => {
      const v = it?.value;
      const id = typeof v === 'string' && v.startsWith('swap:') ? others.find((x) => `swap:${x.key}` === v)?.char.equip?.[slot] : v === '__off' ? null : v;
      foot.innerHTML = equipCompareHtml(c, slot, cur, v === null || v === undefined ? undefined : v === '__off' ? null : id && ITEMS[id] ? id : undefined);
    };
    // スマホ（タッチ）は 1回目の タップで くらべる まどに 出して、もう一度で 装備（くらべてから 決められる）
    const touch = !!g.input.touch;
    const title = `${c.companion ? c.name + 'の' : ''}${SLOT_NAMES[slot]}を選ぶ（今：${cur ? ITEMS[cur].name : 'なし'}）`;
    const pick = await this.pick(title, rows(), { wide: true, big: true, tapConfirm: touch, note: touch ? { text: 'タップでくらべる・もう一度タップで装備', cls: 'info' } : null, cls: 'eq-pick', head, onSide, onMove, foot });
    if (!pick) return false;
    if (pick === '__off') {
      g.net.send({ t: 'menu', action: 'unequip', slot, who });
      return true;
    }
    if (pick.startsWith('swap:')) {
      const m = others.find((x) => `swap:${x.key}` === pick);
      const id = m?.char.equip?.[slot];
      if (!id) return false;
      // 相手は 自分の 今の 装備を 受けとる（装備できない ときは ふくろへ）
      const back = !!cur && canEquipChar(m.char, cur);
      const body = el('div', { class: 'eq-swap-body' },
        el('div', { text: `${c.name}：${cur ? ITEMS[cur].name : 'なし'} → ${ITEMS[id].name}` }),
        el('div', { text: `${m.char.name}：${ITEMS[id].name} → ${back ? ITEMS[cur].name : 'なし'}` }),
        ...(cur && !back ? [el('div', { class: 'muted small', text: `（${ITEMS[cur].name}は${m.char.name}には装備できないので、ふくろにしまう）` })] : []));
      const ok = await this.pick(`${m.char.name}が装備している。\n装備を入れかえる？`, [{ label: 'はい', value: 'yes' }, { label: 'いいえ', value: null }], { body, cls: 'eq-swap-pop' });
      if (ok !== 'yes') return false;
      g.net.send({ t: 'menu', action: 'swapEquip', slot, who, from: m.key });
      return true;
    }
    g.net.send({ t: 'menu', action: 'equip', id: pick, who });
    return true;
  }

  // ───── 見た目装備（強さは かわらない。shared/look-equip.js）─────
  // 部位ごとに「今の装備と同じ」「装備なし」「持っている 装備」から えらぶ。上に 見本（まえ・よこ）
  lookView(who = 'self') {
    const g = this.game;
    const c = this.charOf(who) || g.me;
    const box = el('div', { class: 'look-view' });
    box.append(el('div', { class: 'gold small', text: `${c.name}の見た目装備` }), this.lookPreview(c, shownEquip(c)));
    const items = LOOK_SLOTS.map((sl) => ({ html: `<span class="muted">${SLOT_NAMES[sl]}：</span>${esc(this.lookName(c, sl))}`, value: sl }));
    items.push({ label: '全部今の装備と同じにする', value: '__reset', disabled: !c.lookEquip });
    const detail = el('div', { class: 'detail', text: LOOK_HELP });
    const m = this.mkSub({
      items,
      onMove: (it) => { detail.textContent = it.value === '__reset' ? '見た目を、全部本当の装備と同じにもどす' : LOOK_HELP; },
      onSelect: async (it) => {
        this.sub.blur();
        if (it.value === '__reset') await this.menuCall({ t: 'menu', action: 'lookEquip', who, slot: 'all', id: null });
        else await this.pickLook(c, who, it.value);
        // おなじ 行に カーソルを おいた まま つくりなおす（新しい 見た目は 返事の 前に とどいている）
        this.redraw();
      },
    });
    box.append(m.root, detail);
    return box;
  }

  // 見た目装備の 部位の 今の ようす（「今の装備と同じ（鉄の剣）」「装備なし」「はがねの剣」）
  lookName(c, slot) {
    const v = c.lookEquip?.[slot];
    if (v === LOOK_NONE) return '装備なし';
    if (v && ITEMS[v]?.type === slot) return ITEMS[v].name;
    const real = c.equip?.[slot];
    return `今の装備と同じ（${real ? ITEMS[real].name : 'なし'}）`;
  }

  // 見本（まえ と よこ）。eq … 見せる 装備
  lookPreview(c, eq, cls = '') {
    const cache = this.lookCache || (this.lookCache = previewCache(24));
    const row = el('div', { class: `look-pv ${cls}` });
    for (const dir of ['down', 'left']) {
      const sp = cache(c.look, c.job, eq, dir, 0, 8);
      const cv = el('canvas', { class: 'look-big', width: sp.width, height: sp.height });
      const x = cv.getContext('2d');
      x.imageSmoothingEnabled = false;
      x.drawImage(sp, 0, 0);
      row.append(cv);
    }
    return row;
  }

  // 1つの 部位の 見た目を えらぶ まど。カーソルを うごかすと 見本が かわる。かえたら true
  //   えらべる 物は 持っている 物（ふくろ と、自分・仲間が 装備している 物）。職業の きまりは 関係ない
  async pickLook(c, who, slot) {
    const g = this.game;
    const ids = lookChoices(slot, g.me, this.teamChars().map((m) => m.char));
    const v0 = c.lookEquip?.[slot];
    const cur = v0 === LOOK_NONE ? LOOK_NONE : v0 && ITEMS[v0]?.type === slot ? v0 : 'same';
    const real = c.equip?.[slot];
    const mark = (v) => (v === cur ? '<span class="tag eq-tag">今</span>' : '');
    const items = [
      { html: `<span class="eq-nm">今の装備と同じ<span class="muted small">（${esc(real ? ITEMS[real].name : 'なし')}）</span>${mark('same')}</span>`, value: 'same', cls: 'look-opt' },
      { html: `<span class="eq-nm">装備なし${mark(LOOK_NONE)}</span>`, value: LOOK_NONE, cls: 'look-opt' },
      ...(ids.length ? [] : [{ header: true, label: `${SLOT_NAMES[slot]}を持っていない`, cls: 'eq-none' }]),
      ...ids.map((id) => ({ html: `<span class="eq-nm">${esc(ITEMS[id].name)}${mark(id)}</span>`, value: id, cls: 'look-opt' })),
      { label: 'やめる', value: null },
    ];
    const eqFor = (v) => shownEquip({ equip: c.equip || {}, lookEquip: { ...(c.lookEquip || {}), [slot]: v === 'same' ? undefined : v } });
    const pv = el('div', { class: 'look-pv-box' });
    const show = (v) => {
      pv.innerHTML = '';
      pv.append(this.lookPreview(c, eqFor(v), 'small'));
    };
    show(cur);
    const pick = await this.pick(`${c.companion ? c.name + 'の' : ''}${SLOT_NAMES[slot]}の見た目を選ぶ`, items, {
      wide: true, cls: 'look-pick', start: cur, head: () => pv,
      onMove: (it) => { if (it.value) show(it.value); },
    });
    if (!pick || pick === cur) return false;
    const r = await this.menuCall({ t: 'menu', action: 'lookEquip', who, slot, id: pick === 'same' ? null : pick });
    return !!r?.ok;
  }

  // 自分と 自分の 仲間（パーティー・馬車）。装備の 入れかえで 使う
  teamChars() {
    return [{ key: 'self', char: this.game.me }, ...this.myMates().map((x) => ({ key: x.key, char: this.charOf(x.key) })).filter((m) => m.char)];
  }

  // さいきょう装備で きめる じゅんばん（サーバーの ownTeamChars と おなじ: 戦う 仲間を ならびの じゅんに → 馬車の 仲間）
  bestTeam() {
    const g = this.game;
    const mine = (list) => (list || []).filter((x) => x.owner === g.me.id && x.kind !== 'family')
      .map((x) => ({ key: x.key, char: this.charOf(x.key) })).filter((m) => m.char);
    return bestTeamOrder({ key: 'self', char: g.me }, mine(g.party?.supports), mine(g.party?.wagon), g.me.selfPos);
  }

  // さいきょう装備: 何が 何に 変わるかを 見せてから「これにする／変えない」（shared/equip-plan.js）。変えたら true
  async bestEquipAsk(who) {
    const g = this.game;
    const all = who === 'all';
    const team = all ? this.bestTeam() : [{ key: who, char: this.charOf(who) || g.me }];
    const plan = bestEquipPlan(team, g.me);
    if (!plan.length) {
      await this.pick(all ? 'みんな、もういちばん強い装備をしている。\n（変わる物はない）' : `${team[0].char.name}は、もういちばん強い装備をしている。\n（変わる物はない）`, [{ label: 'もどる', value: null }]);
      return false;
    }
    const body = el('div', { class: 'bp-body scroll' });
    for (const p of plan) {
      const sec = el('div', { class: 'bp-who' }, el('div', { class: 'bp-name', text: p.name }));
      // 武器：鉄の剣 → はがねの剣
      for (const x of p.changes) {
        sec.append(el('div', { class: 'bp-ch' }, el('span', { class: 'k', text: `${SLOT_NAMES[x.slot]}：` }),
          el('span', { class: 'from', text: x.from ? ITEMS[x.from].name : 'なし' }), el('span', { class: 'ar', text: '→' }), el('span', { class: 'to', text: ITEMS[x.to].name })));
      }
      // 強さ: 上がる ものも 下がる ものも
      sec.append(el('div', { class: 'bp-st', html: statChangesHtml(statChanges(p.before, p.after)) }));
      body.append(sec);
    }
    const ok = await this.pick(all ? 'みんなをさいきょう装備にすると、こう変わる' : `${team[0].char.name}をさいきょう装備にすると、こう変わる`,
      [{ label: 'これにする', value: 'ok' }, { label: '変えない', value: null }], { wide: true, cls: 'bp-pop', body });
    if (ok !== 'ok') return false;
    g.net.send({ t: 'menu', action: 'bestEquip', who });
    return true;
  }

  // ───── つよさ ─────
  statusView(who = 'self', active = false) {
    const c = this.charOf(who) || this.game.me;
    const st = computeStats(c);
    const box = el('div');
    // レベルは 150まで（stats.js の MAX_LEVEL）
    const next = c.level >= MAX_LEVEL ? null : expForLevel(c.level + 1) - (c.exp || 0);
    const kind = c.species ? `${MONSTERS[c.species]?.name || ''}（モンスター）` : jobLabel(c.job, c);
    box.append(el('h3', { text: `${c.name}　${kind}` }));
    const kv = (k, v, cls = '') => el('div', { class: 'kv' }, el('span', { class: 'k', text: k }), el('span', { class: cls, text: String(v) }));
    box.append(el('div', { class: 'twocol' },
      kv('レベル', c.level), kv('次のレベルまで', next === null ? `最大（Lv${MAX_LEVEL}）` : Math.max(0, next)),
      kv('HP', `${Math.max(0, c.hp)}/${st.maxHp}`), kv('MP', `${c.mp}/${st.maxMp}`),
      kv('力', st.str), kv('身の守り', st.def),
      kv('素早さ', st.agi), kv('攻撃魔力', st.mag),
      kv('回復魔力', st.heal), c.companion ? kv('作戦', TACTICS[c.tactics]?.name || '') : kv('ゴールド', c.gold),
      kv('攻撃力', st.atk, 'gold'), kv('守備力', st.dfn, 'gold')));
    if (c.species) {
      const f = MONSTER_FRIENDS[c.species];
      const learnList = el('div', { style: { marginTop: '0.6em' } }, el('div', { class: 'gold small', text: '覚える技（レベル）' }));
      for (const [l, id] of f?.learn || []) learnList.append(el('div', { class: `small ${c.level >= l ? 'good' : 'muted'}`, text: `Lv${l}　${ABILITIES[id]?.name || id}` }));
      // 第43回 B: 系統の おうぎ（Lv30・45・60。data/abilities-ougi.js）
      for (const [l, id] of ougiLearn(MONSTERS[c.species]?.race)) learnList.append(el('div', { class: `small ${c.level >= l ? 'good' : 'muted'}`, text: `Lv${l}　${ABILITIES[id]?.name || id}（おうぎ）` }));
      box.append(learnList, el('div', { class: 'small', style: { marginTop: '0.4em' }, text: `装備できる物: ${gearText(c.species)}` }), el('div', { class: 'detail', text: f?.note || '' }));
    } else {
      const jobs = el('div', { style: { marginTop: '0.6em' } }, el('div', { class: 'gold small', text: '職業レベル（勝った戦いの数で上がる）' }));
      for (const j of ALL_JOBS) {
        const info = c.jobs?.[j];
        if (!info) continue;
        const lt = jobLevelText(c, j);
        jobs.append(el('div', { class: 'kv small' },
          el('span', { class: j === c.job ? 'good' : '', text: `${jobLabel(j, c)}${JOBS[j].tier ? `（${TIER_NAMES[JOBS[j].tier]}）` : ''}` }),
          el('span', { class: lt.cls, text: lt.text })));
      }
      // 第38回 B: しょうごう・職業の試練の とちゅう（client/ui/job-trials.js）
      const tb = trialStatusBox(c, !c.companion);
      if (tb) jobs.append(tb);
      box.append(jobs, el('div', { class: 'detail', text: '1回の攻撃で終わってしまう戦いでは、職業の修行は半分しか進まない。' }));
      // ひみつのダンジョンの 最高の 階（自分の キャラだけ。仲間には ない）
      const sd = sdRecordOf(c);
      if (sd.best > 0) box.append(el('div', { class: 'kv small' }, el('span', { class: 'k', text: 'ひみつのダンジョン' }), el('span', { class: 'gold', text: `最高は地下${sd.best}階` })));
    }
    // 素早さの 差は すこしだけ（shared/battle.js の ATB）。戦いの 速さの 設定も かける
    const bspeed = normBattleSettings(this.game.me?.battleSettings || {}).speed;
    const speedNote = el('div', { class: 'detail', text: `素早さ ${st.agi}…戦いで約${turnSeconds(st.agi, bspeed).toFixed(1)}秒ごとに順番が来る\n素早さの差は少しだけ（3倍ちがっても約1.2倍）。ピオリムなどは約1.25倍` });
    box.append(speedNote);
    if (active) {
      this.mkSub({ items: [{ label: 'もどる', value: 'back' }], onSelect: () => this.back() });
      // 第50回 C: コントローラーの 上下で 画面を スクロール
      padScroll(this.sub, { ys: () => scrollerOf(box) || this.main });
      box.append(this.sub.root);
    }
    return box;
  }

  // ───── つよさ（全員を 一覧で くらべる） ─────
  allStatusView(active = false) {
    const g = this.game;
    const p = g.party || {};
    const cols = [];
    const add = (x, st, kind) => cols.push({
      name: x.name, level: x.level, hp: x.hp, mp: x.mp, maxHp: st.maxHp ?? x.maxHp, maxMp: st.maxMp ?? x.maxMp, st, kind,
      face: faceURL({ look: x.look, job: x.job, eq: shownEquip(x), mon: colorMon(x.species, x.color) }),
    });
    add(g.me, computeStats(g.me), jobLabel(g.me.job, g.me));
    for (const m of this.myMates()) {
      const c = this.charOf(m.key);
      if (c) add(m, computeStats(c), `${m.wagon ? '馬車・' : ''}${m.species ? MONSTERS[m.species]?.name || '' : jobLabel(m.job, m)}`);
    }
    // 家族（パーティーの ほかの 人）と その なかま、ゲスト
    for (const m of p.members || []) if (m.sid !== g.sid && m.st) add(m, m.st, jobLabel(m.job, m));
    for (const m of p.supports || []) if (m.owner !== g.me.id && m.st) add(m, m.st, m.species ? MONSTERS[m.species]?.name || '' : jobLabel(m.job, m));
    for (const m of p.guests || []) if (m.st) add(m, m.st, jobLabel(m.job, m));
    const rows = [
      ['レベル', (x) => x.level],
      ['HP', (x) => x.maxHp, (x) => `${Math.max(0, x.hp)}/${x.maxHp}`],
      ['MP', (x) => x.maxMp, (x) => `${Math.max(0, x.mp)}/${x.maxMp}`],
      ['力', (x) => x.st.str], ['身の守り', (x) => x.st.def], ['素早さ', (x) => x.st.agi],
      ['攻撃魔力', (x) => x.st.mag], ['回復魔力', (x) => x.st.heal],
      ['攻撃力', (x) => x.st.atk], ['守備力', (x) => x.st.dfn],
    ];
    const table = el('table', { class: 'allstat' });
    const head = el('tr', {}, el('th'));
    for (const x of cols) head.append(el('th', {}, el('img', { class: 'face', src: x.face, alt: '' }), el('div', { class: 'nm', text: x.name }), el('div', { class: 'jb', text: x.kind })));
    table.append(head);
    for (const [label, val, show] of rows) {
      const vals = cols.map(val);
      const best = cols.length > 1 ? Math.max(...vals) : null;
      const tr = el('tr', {}, el('th', { text: label }));
      cols.forEach((x, i) => tr.append(el('td', { class: vals[i] === best ? 'gold' : '', text: String(show ? show(x) : vals[i]) })));
      table.append(tr);
    }
    const box = el('div');
    const wrap = el('div', { class: 'allstat-wrap' }, table);
    box.append(el('h3', { text: '全員の強さ' }), wrap,
      el('div', { class: 'detail', text: '黄色は、その強さが一番高い人。' }));
    if (active) {
      this.mkSub({ items: [{ label: 'もどる', value: 'back' }], onSelect: () => this.back() });
      // 第50回 C: コントローラーの 上下で 画面を、左右で よこに 長い 表を スクロール
      padScroll(this.sub, { ys: () => scrollerOf(box) || this.main, xs: wrap });
      box.append(this.sub.root);
    }
    return box;
  }

  // ───── なかま ─────
  partyView(active) {
    const g = this.game;
    const p = g.party;
    const box = el('div');
    const iAmLeader = p?.leader === g.sid;
    const rows = [];
    const face = (x) => el('img', { class: 'face', src: faceURL({ look: x.look, job: x.job, eq: shownEquip(x), mon: colorMon(x.species, x.color) }), alt: '' });
    const row = (x, name, tag, cls = '') => el('div', { class: 'kv party-row' }, el('span', { class: cls }, face(x), name), el('span', { class: 'small muted', text: tag }));
    // ならびの じゅん（リーダーが きめる。先頭ほど 敵に ねらわれやすい）
    const memRows = (p?.members || []).map((m) => row(m, `${m.sid === p.leader ? '★' : ''}${m.name}（${jobLabel(m.job, m)} Lv${m.level}）`, `HP ${m.hp}/${m.maxHp}`, m.sid === p.leader ? 'gold' : ''));
    const supRows = (p?.supports || []).map((s) => {
      const kind = s.species ? `${MONSTERS[s.species]?.name}${s.plus ? `＋${s.plus}` : ''} Lv${s.level}` : `${jobLabel(s.job, s)} Lv${s.level}`;
      return row(s, `${s.name}（${kind}）`, s.family ? '家族サポート' : s.species ? 'モンスター' : '仲間');
    });
    const pos = Math.max(0, Math.min(supRows.length, p?.selfPos || 0));
    rows.push(...supRows.slice(0, pos), ...memRows, ...supRows.slice(pos));
    rows.forEach((r, i) => r.firstChild.prepend(el('span', { class: 'ord', text: `${i + 1}` })));
    for (const gu of p?.guests || []) rows.push(row(gu, gu.name, 'ゲスト'));
    // 馬車（リーダーの もの。ui/wagon.js）
    if (p?.wagon) {
      rows.push(el('div', { class: 'small gold', style: { marginTop: '0.4em' }, text: `馬車（${p.wagon.length}人）` }));
      for (const w of p.wagon) rows.push(row(w, `${w.name}（${w.species ? MONSTERS[w.species]?.name : jobLabel(w.job, w)} Lv${w.level}）`, w.hp > 0 ? `HP ${w.hp}/${w.maxHp}` : '死んでいる'));
    }
    box.append(...rows);
    if (!active) {
      box.append(el('div', { class: 'detail', text: `遊んでいる家族をパーティーにさそえる。仲間はルミナの町の酒場で探したり入れかえたりできる。\n近くにいる仲間はいっしょに戦う。はなれている仲間も、戦っている場所へかけつけると、とちゅうから参加できる。\n「ならびを変える」で順番を変えられる（先頭ほど敵にねらわれやすい）。${g.me.wagon ? '\n「総入れかえ」で、戦う仲間（1〜4番目）と馬車の仲間（5〜8番目）をまとめて決められる。' : ''}` }));
      return box;
    }
    const acts = [];
    // 総入れかえ（1〜4番目が 戦う 仲間、5〜8番目が 馬車。ui/wagon.js）
    const mates = (g.me.partyKeys || []).length + (g.me.wagonKeys || []).length;
    if (g.me.wagon && (iAmLeader || !p) && mates) acts.push({ label: '総入れかえ', value: { a: 'arrange' } });
    if (iAmLeader && (p?.supports?.length || 0) >= 1) acts.push({ label: 'ならびを変える', value: { a: 'order' } });
    if (g.me.wagon) acts.push({ label: '馬車', value: { a: 'wagon' } });
    const others = (g.players || []).filter((x) => x.sid !== g.sid && x.partyId !== p?.id && !x.away);
    if (iAmLeader) for (const o of others) acts.push({ label: `${o.name}をさそう`, value: { a: 'invite', sid: o.sid } });
    if (iAmLeader) for (const s of p?.supports || []) acts.push({ label: `${s.name}に酒場で待っていてもらう`, value: { a: 'dismiss', key: s.key, name: s.name } });
    if (iAmLeader) for (const m of p?.members || []) if (m.sid !== g.sid) acts.push({ label: `${m.name}をリーダーにする`, value: { a: 'leader', sid: m.sid } });
    if (!iAmLeader && p) acts.push({ label: g.follow ? 'リーダーについていくのをやめる' : 'リーダーについていく（自動）', value: { a: 'follow' } });
    if ((p?.members.length || 1) > 1) acts.push({ label: 'パーティーをぬける', value: { a: 'leave' } });
    if (!acts.length) acts.push({ label: '（今遊んでいる家族はいないみたい）', value: null, disabled: true });
    const m = this.mkSub({
      items: acts,
      onSelect: async (it) => {
        const v = it.value;
        if (!v) return;
        // 馬車: 上に のせる（もどる で この リストの「馬車」に もどる）
        if (v.a === 'wagon') return this.pushView(() => wagonMenuView(this, true));
        if (v.a === 'arrange') {
          if (!wagonHereClient(g)) {
            toast('馬車は入り口で待っている。\n（洞窟や塔の中では乗りかえられない）');
            this.sfx('buzz');
            return;
          }
          this.sub.blur();
          const r = await menuArrange(this);
          // あたらしい ならびを 上から 見せる
          if (r) setTimeout(() => { if (this.root) this.main.scrollTop = 0; }, 300);
        } else if (v.a === 'order') {
          this.sub.blur();
          const order = await this.pickOrder();
          if (order) g.net.send({ t: 'menu', action: 'order', order });
        } else if (v.a === 'follow') {
          g.follow = !g.follow;
          toast(g.follow ? 'リーダーについていきます' : '自分で歩きます');
        } else if (v.a === 'dismiss') {
          this.sub.blur();
          const ok = await confirmBox(g.input, `${v.name}にルミナの町の酒場で待っていてもらう？\n（酒場でまた連れていけるよ）`, 'はい', 'いいえ', this.sfx);
          if (ok) g.net.send({ t: 'party', action: 'dismiss', key: v.key });
        } else g.net.send({ t: 'party', action: v.a, sid: v.sid, key: v.key });
        // カーソルは えらんだ ところの まま
        setTimeout(() => this.redraw(), 250);
      },
    });
    box.append(el('div', { style: { marginTop: '0.5em' } }, m.root));
    return box;
  }

  // ドラクエの ならびかえ: 1番目から じゅんに えらぶ（人の まとまりは いっしょに うごく）
  async pickOrder() {
    const p = this.game.party;
    const people = (p?.members || []).map((m) => m.name).join('・') || this.game.me.name;
    const pool = [{ label: people, value: 'self' }, ...(p?.supports || []).map((s) => ({ label: s.name, value: s.key }))];
    const order = [];
    while (pool.length > 1) {
      const v = await this.pick(`${order.length + 1}番目はだれにする？（先頭ほど敵にねらわれやすい）`, [...pool, { label: 'やめる', value: null }]);
      if (!v) return null;
      order.push(v);
      pool.splice(pool.findIndex((x) => x.value === v), 1);
    }
    order.push(pool[0].value);
    return order;
  }

  // ───── ずかん ─────
  zukanView(active) {
    const c = this.game.me;
    const bs = c.bestiary || {};
    const kills = c.kills || {};
    const order = zukanOrder();
    const st = (sp) => {
      const b = bs[sp] || {};
      const friend = (b.friend || 0) > 0;
      const bred = (b.bred || 0) > 0;
      return { seen: (b.seen || 0) > 0 || (kills[sp] || 0) > 0 || friend || bred, friend, bred, kills: kills[sp] || 0, raw: b };
    };
    const box = el('div', { class: active ? 'zukan-box' : '' });
    const count = (k) => order.filter((sp) => st(sp)[k]).length;
    box.append(el('div', { class: 'small gold', text: `見つけた ${count('seen')}/${order.length}　仲間にした ${count('friend')}　配合で生んだ ${count('bred')}` }));
    if (!active) {
      box.append(el('div', { class: 'detail', text: '出会ったモンスターがのる図鑑。\n仲間にしたモンスターや、配合で生まれたモンスターも記録される。\n「仲間になりやすさ」は4段階。魔物使いやモンスターマスターがいると、もっと仲間になりやすい。\n配合でしか生まれないモンスターもいるらしい…' }));
      return box;
    }
    const detail = el('div', { class: 'detail zukan-detail' });
    const showMon = (sp) => {
      detail.innerHTML = '';
      detail.scrollTop = 0;
      const M = MONSTERS[sp];
      if (!M) return;
      const s = st(sp);
      const src = monsterCanvas(sp, 0);
      const cv = makeCanvas(src.width, src.height);
      const x = ctxOf(cv);
      x.drawImage(src, 0, 0);
      if (!s.seen) {
        // まだ であって いない: かげだけ
        x.globalCompositeOperation = 'source-in';
        x.fillStyle = '#2a2440';
        x.fillRect(0, 0, cv.width, cv.height);
      }
      cv.className = 'zukan-mon';
      detail.append(cv);
      if (!s.seen) {
        detail.append(el('div', { class: 'gold', text: '？？？' }));
        if (M.breedOnly) detail.append(el('div', { class: 'small', text: `${EVOLVE_FROM[sp] ? '進化で会えるらしい…' : '配合で生まれるらしい…'}\nヒント: ${recipeHint(sp, MONSTERS)}${evolveNote(sp) ? `\n（${evolveNote(sp)}）` : ''}` }));
        else detail.append(el('div', { class: 'small muted', text: M.boss ? 'どこかにいる大きな魔物…' : 'まだ出会っていない' }));
        return;
      }
      // 配合でも 生まれる 魔物は ヒントも（ぷるりん騎士 など）
      const hint = recipeHint(sp, MONSTERS);
      // 仲間に なりやすさ（4段階。companions.js の JOIN_TIERS）。スマホでも 見えるように 名前の すぐ 下に 1行で
      const tier = M.boss ? null : joinTier(sp);
      const join = el('div', { class: 'small zukan-join' });
      if (M.breedOnly) join.append(el('span', { text: `${EVOLVE_FROM[sp] ? '進化で生まれる' : '配合で生まれる'}（${hint}）${evolveNote(sp) ? `・${evolveNote(sp)}` : ''}` }));
      else if (tier) {
        join.append(
          el('span', { class: 'muted', text: '仲間になりやすさ' }),
          el('span', { class: 'join-meter', 'aria-hidden': 'true' }, [1, 2, 3, 4].map((i) => el('i', { class: i <= tier.level ? 'on' : '' }))),
          el('span', { class: `join-t j${tier.level}`, text: tier.text }),
        );
      } else join.append(el('span', { text: '仲間にならない' }));
      if (s.friend) join.append(el('span', { class: 'good', text: '★仲間にした' }));
      if (s.bred) join.append(el('span', { class: 'good', text: '★配合で生んだ' }));
      // 第53回 D: 配合で 生んだ 色ちがい（図鑑の color_<しゅるい>）
      const colors = Object.keys(VARIANT_KINDS).filter((k) => s.raw[`color_${k}`] > 0);
      if (colors.length) join.append(el('span', { class: 'good', text: `★色ちがい：${colors.map((k) => VARIANT_KINDS[k].prefix).join('・')}` }));
      const notes = [
        tier && hint ? `配合でも生まれる（${hint}）` : '',
        // 森の主の あとの 夢（魔物の心）より 前
        tier && !c.flags?.monster_bond ? '今はまだ、魔物は仲間にならないようだ…' : '',
      ].filter(Boolean);
      detail.append(
        el('div', { class: 'zukan-title' },
          el('span', { class: 'gold', text: `${M.name}${M.boss ? '（ボス）' : ''}` }),
          el('span', { class: 'small muted', text: `${RACE_NAMES[M.race] || ''}${M.breedOnly ? '' : `　Lv${M.lv}`}　倒した数 ${s.kills}` })),
        join,
        ...notes.map((t) => el('div', { class: 'small', text: t })),
        el('div', { class: 'small', text: M.desc || '' }),
      );
      // 属性の 得手不得手（戦いで ためした ものだけ 分かる）
      const MARK = { weak: '◎', normal: '○', resist: '△', null: '×' };
      const affRow = el('div', { class: 'small zukan-aff' }, el('span', { class: 'muted', text: '属性 ' }));
      for (const e of ELEMENT_ORDER) {
        const known = !!s.raw[`el_${e}`];
        const aff = known ? affinityOf(M.resist?.[e] ?? 1) : null;
        affRow.append(el('span', { class: `zaff ${aff || 'unk'}` }, el('span', { class: `elem e-${e}`, text: ELEMENT_NAMES[e] }), el('span', { text: known ? MARK[aff] : '？' })));
      }
      detail.append(affRow, el('div', { class: 'small muted', text: '◎弱点 ○ふつう △効きにくい ×効かない ？まだためしていない' }));
      // 落とす 物（手に 入れた ものだけ 名前が 分かる）
      const ORDER = { common: 0, mat: 0.5, rare: 1, brare: 1.5, boss: 2 };
      const drops = monsterDrops(sp).sort((p, q) => ORDER[p.kind] - ORDER[q.kind]);
      if (drops.length) {
        const KIND = { boss: 'かならず', brare: 'かならず', rare: 'レア', common: 'よく', mat: '素材' };
        const row = el('div', { class: 'small zukan-drops' }, el('span', { class: 'muted', text: '落とす物 ' }));
        for (const d of drops) {
          const known = !!s.raw[`drop_${d.item}`];
          row.append(el('span', { class: `zdrop ${d.kind} ${known ? '' : 'unk'}` }, el('span', { text: known ? ITEMS[d.item].name : '？？？' }), el('span', { class: 'tag', text: KIND[d.kind] })));
        }
        detail.append(row);
      }
    };
    const m = this.mkSub({
      items: order.map((sp, i) => {
        const s = st(sp);
        const M = MONSTERS[sp];
        return {
          html: `<span class="muted small">No.${String(i + 1).padStart(2, '0')}</span> ${s.seen ? esc(M.name) : '？？？'}`,
          right: [s.friend ? '仲間' : '', s.bred ? '配合' : ''].filter(Boolean).join('・') || (M.boss && s.seen ? 'ボス' : ''),
          rightCls: s.friend || s.bred ? 'good' : '',
          value: sp,
          cls: s.seen ? '' : 'muted',
        };
      }),
      onMove: (it) => showMon(it.value),
    });
    box.append(detail, el('div', { class: 'zukan-list scroll' }, m.root));
    return box;
  }

  // ───── さくせん ─────
  tacticsView(active) {
    const g = this.game;
    const c = g.me;
    const box = el('div');
    const bs = c.battleSettings || {};
    const tname = (t) => TACTICS[t]?.name || t;
    // 第71回: オートで 使わない 技（autoOff）と 命令の 一覧に 出さない 技（cmdOff）の 数
    const offN = (x) => (Array.isArray(x?.autoOff) ? x.autoOff.length : 0);
    const cmdN = (x) => cmdOffList(x).length;
    const offTag = (x) => {
      const t = [offN(x) ? `オートで使わない ${offN(x)}` : '', cmdN(x) ? `命令に出さない ${cmdN(x)}` : ''].filter(Boolean);
      return t.length ? `（${t.join('・')}）` : '';
    };
    const items = [{ label: `${c.name}（オートのとき）：${tname(c.tactics || 'balanced')}${offTag(c)}`, value: { key: 'self', name: c.name } }];
    // 自分の 仲間（パーティー・馬車）
    for (const s of this.myMates()) {
      items.push({ label: `${s.name}${s.wagon ? '（馬車）' : ''}：${tname(s.tactics)}${offTag(s)}`, value: { key: s.key, name: s.name }, face: faceURL({ look: s.look, job: s.job, eq: shownEquip(s), mon: colorMon(s.species, s.color) }) });
    }
    items.push({ label: `戦いの初めからオート：${bs.auto ? 'ON' : 'OFF'}`, value: { toggle: 'auto' } });
    if (!active) {
      for (const it of items) box.append(el('div', { text: it.label }));
      box.append(el('div', { class: 'detail', text: '仲間やオートのときの戦い方を決める。オートで使わない技・命令の一覧に出さない技も選べる（自分も仲間も）。\n仲間を「めいれいさせろ」にすると、仲間のコマンドも自分で選べる。' }));
      return box;
    }
    const m = this.mkSub({
      items,
      onSelect: async (it) => {
        const v = it.value;
        if (v.toggle === 'auto') {
          g.net.send({ t: 'menu', action: 'settings', auto: !bs.auto });
          setTimeout(() => this.redraw(), 250);
          return;
        }
        this.sub.blur();
        // 作戦を かえる か、技を えらぶ か（第71回: 2つに 分けた。主人公も 仲間も）
        //   オートで使う技を選ぶ … オート（主人公の オート・仲間の 作戦）で 使う 技（autoOff）
        //   命令で出す技を選ぶ … 自分で 命令する とき（主人公・「めいれいさせろ」の 仲間）の 技の 一覧に 出す 技（cmdOff）
        const what = await this.pick(v.name, [
          { label: '作戦を変える', value: 'tac' },
          { label: 'オートで使う技を選ぶ', value: 'skills' },
          { label: '命令で出す技を選ぶ', value: 'cmd' },
          { label: 'やめる', value: null },
        ]);
        if (what === 'skills') return this.pushView(() => this.autoSkillsView(v.key));
        if (what === 'cmd') return this.pushView(() => this.cmdSkillsView(v.key));
        if (what === 'tac') {
          const list = Object.entries(TACTICS).filter(([k]) => v.key !== 'self' || k !== 'manual').map(([k, x]) => ({ label: x.name, value: k }));
          const t = await this.pick(v.key === 'self' ? 'オートのときの作戦' : `${v.name}の作戦`, [...list, { label: 'やめる', value: null }]);
          if (t) g.net.send({ t: 'menu', action: 'tactics', key: v.key, tactics: t, label: TACTICS[t].name });
          setTimeout(() => this.redraw(), t ? 250 : 0);
          return;
        }
        this.redraw();
      },
    });
    box.append(m.root, el('div', { class: 'detail', text: 'バッチリがんばれ: バランスよく / ガンガンいこうぜ: 攻撃中心 / いのちだいじに: 回復中心 / じゅもんせつやく: MPを使わない / めいれいさせろ: 自分でコマンドを選ぶ（仲間だけ）\n技の選び方は2つある。\n・「オートで使う技を選ぶ」…オートや作戦で戦う時に、使わない技を決める（技の一覧からは消えない）。\n・「命令で出す技を選ぶ」…自分で命令する時（主人公・「めいれいさせろ」の仲間）に、技の一覧に出さない技を決める（オートでは使うことがある）。\nどちらも、フィールドで使う時は出る。' }));
    return box;
  }

  // オートで 使う 技・使わない 技（作戦の「オートで使う技を選ぶ」）。えらぶ たびに「使う／使わない」が かわる（サーバーの autoSkill・ai.js）
  // 第71回: オートの AIが 使わない だけ。戦いの 技の 一覧からは 消さない（命令の 一覧に 出さない 技は cmdSkillsView）
  autoSkillsView(key) {
    return this.skillOffView(key, 'auto');
  }

  // 第71回: 命令で 出す 技・出さない 技（作戦の「命令で出す技を選ぶ」）。自分で 命令する とき（主人公・「めいれいさせろ」の 仲間）に
  //   戦いの 技の 一覧に 出さない 技（サーバーの cmdSkill。client/battle.js の openCommand）。呪文・技の メニューでも 切りかえられる
  cmdSkillsView(key) {
    return this.skillOffView(key, 'cmd');
  }

  // 2つの 画面の なかみ（kind: 'auto' … autoOff / 'cmd' … cmdOff）。主人公も 仲間（どの 作戦でも）も えらべる。フィールドで 使う 一覧には どちらも 出る
  skillOffView(key, kind = 'auto') {
    const g = this.game;
    const c = this.charOf(key) || g.me;
    const box = el('div');
    const cmd = kind === 'cmd';
    const off = new Set(cmd ? cmdOffList(c) : Array.isArray(c.autoOff) ? c.autoOff : []);
    // 戦いで 使える 技だけ（ルーラなど フィールドだけの 技・きずな技は のぞく）
    // 同じ 名前の 技（大神官と 大賢者の ザオリク など）は 1つに まとめる（サーバーが いっしょに 切りかえる。第41回）
    const seen = new Set();
    const ids = sortByStdPower(learnedAbilities(c)).filter((id) => {
      const a = abilityFor(id, c);
      if (!a || a.fieldOnly || a.hidden || a.kind === 'bond' || seen.has(a.name)) return false;
      seen.add(a.name);
      return true;
    });
    // 同じ 名前の どれかが「使わない（出さない）」なら「使わない（出さない）」と 出す
    const offNames = new Set([...off].map((id) => abilityFor(id, c)?.name).filter(Boolean));
    const W = cmd ? { yes: '出す', no: '出さない', all: '全部出す', action: 'cmdSkill', field: 'cmdOff' } : { yes: '使う', no: '使わない', all: '全部使う', action: 'autoSkill', field: 'autoOff' };
    box.append(el('div', { class: 'gold small', text: cmd ? `${c.name}に命令する時、技の一覧に出す技` : `${c.name}がオートで使う技` }));
    if (!ids.length) {
      box.append(el('div', { class: 'muted', text: 'まだ技を覚えていない。' }));
      this.mkSub({ items: [{ label: 'もどる', value: 'back' }], onSelect: () => this.back() });
      box.append(this.sub.root);
      return box;
    }
    const st = powStats(c);
    const items = [
      { label: W.all, value: '__all', disabled: !off.size },
      ...ids.map((id) => {
        const a = abilityFor(id, c);
        const no = off.has(id) || offNames.has(a.name);
        // MPと 威力の 目安（今の 魔力で。強いか 弱いか わかる ように。第50回 N1）
        const mp = a.effect?.type === 'mahouken' ? '' : `MP${mpCost(c, id)}`;
        const pw = skillPowerLine(id, c, { st });
        const pen = penaltyFor(c, id).penalized;
        return {
          html: `${esc(a.name)}${pen ? '<span class="tag warn">他</span>' : ''}${mp || pw ? `<span class="sk-pow">${esc([mp, pw].filter(Boolean).join('　'))}</span>` : ''}<span class="sk-desc">${esc(skillBrief(a))}</span>`,
          right: no ? W.no : W.yes,
          rightCls: no ? 'dis' : 'up',
          value: id,
          cls: `k-${abilityRole(a)} sk ${no ? 'auto-off' : ''}`,
        };
      }),
    ];
    const m = this.mkSub({
      items,
      onSelect: (it) => {
        if (it.value === '__all') {
          this.setOffLocal(key, W.field, []);
          g.net.send({ t: 'menu', action: W.action, key, op: 'all' });
        } else {
          const nm = abilityFor(it.value, c)?.name;
          const same = learnedAbilities(c).filter((x) => abilityFor(x, c)?.name === nm);
          const no = off.has(it.value) || offNames.has(nm);
          const next = no ? [...off].filter((x) => !same.includes(x)) : [...new Set([...off, ...same])];
          this.setOffLocal(key, W.field, next);
          g.net.send({ t: 'menu', action: W.action, key, id: it.value, op: no ? 'on' : 'off' });
        }
        this.redraw();
      },
    });
    box.append(m.root, el('div', { class: 'detail', text: cmd
      ? '選ぶたびに「出す／出さない」が切りかわる。\n「出さない」にした技は、自分で命令する時（主人公・「めいれいさせろ」の仲間）に、戦いの技の一覧に出ない。オートで使うかは「オートで使う技を選ぶ」で決める。フィールドで使う時は出る。\n呪文・技のメニューで技を選んでも切りかえられる。「全部出す」で元にもどる。'
      : '選ぶたびに「使う／使わない」が切りかわる。\n「使わない」にした技は、オートや作戦で戦う時に使わない。自分で命令する時の技の一覧には出る（出さない技は「命令で出す技を選ぶ」で決める）。「全部使う」で元にもどる。' }));
    return box;
  }

  // ───── クエスト ─────
  questView() {
    const c = this.game.me;
    const box = el('div');
    const leader = this.game.visitingLeader?.();
    if (leader) {
      box.append(el('h3', { text: `${leader.name}の目標（いっしょに冒険中）` }), el('div', { text: this.game.party.objective || '（特になし）' }));
      box.append(el('div', { class: 'detail', text: `${leader.name}の冒険を手伝っているあいだは、自分のストーリーは進みません。\nレベル・お金・道具はそのままもらえるよ。パーティーをぬけると、自分の冒険の場所にもどります。` }));
    }
    box.append(el('h3', { text: leader ? '自分の目標' : '今の目標' }), el('div', { class: 'q-main' }, el('i', { class: 'qdot qmain' }), c.objective || '（特になし）'));
    const tgt = difficultyOf(c).mainMarks && OBJECTIVE_TARGETS[c.objective || ''];
    if (tgt) box.append(el('div', { class: 'small muted', text: `行き先: ${whereName(tgt[tgt.length - 1])}（地図のピンクのしるし）` }));
    // たのまれごと（報告する 人は 地図に 水色・報告できる ときは みどり）
    const f = (k) => !!c.flags[k];
    const active = subQuests(c);
    const done = [['q_mike_done', '迷子のねこミケ'], ['q_jelly_done', 'コックの特製ゼリー'], ['q_wolf_done', 'ウルフ退治'], ['q_bottle_done', 'びんの手紙']].filter(([k]) => f(k));
    done.push(...labDoneQuests(c).map((n) => [null, n]));
    box.append(el('h3', { style: { marginTop: '0.6em' }, text: 'たのまれごと' }));
    if (!active.length && !done.length) box.append(el('div', { class: 'muted small', text: 'まだない。町の人の話を聞くと、たのまれごとが見つかることがある。' }));
    for (const q of active) {
      box.append(el('div', { class: 'kv' }, el('span', {}, el('i', { class: `qdot ${q.ready ? 'ready' : 'sub'}` }), q.name), el('span', { class: q.ready ? 'good' : 'muted', text: q.text })));
    }
    for (const [, n] of done) box.append(el('div', { class: 'kv' }, el('span', { class: 'muted', text: n }), el('span', { class: 'good', text: 'クリア！' })));
    // 第50回 N4: 困っている人（まだ 受けていない たのまれごと）
    box.append(askSection(this.game));
    // 第38回 B: 職業の試練（client/ui/job-trials.js）
    const tq = trialQuestBox(c);
    if (tq) box.append(tq);
    const chests = Object.keys(c.chests || {}).length;
    const total = Object.values(MAPS).reduce((s, m) => s + m.chests.length, 0);
    box.append(el('div', { class: 'detail', text: `宝箱 ${chests}/${total}　フィールドの宝箱 ${c.fieldChests || 0}こ　倒した魔物 ${Object.values(c.kills || {}).reduce((s, x) => s + x, 0)}ひき` }));
    // ひみつのダンジョンの 自分の 記録（data/secret.js）
    const sd = sdRecordOf(c);
    if (sd.best > 0 || sd.tries > 0) box.append(el('div', { class: 'kv' }, el('span', { class: 'muted', text: 'ひみつのダンジョン' }), el('span', { class: 'gold', text: sdRecordText(sd) })));
    const wallet = walletView(c);
    if (wallet) box.append(wallet);
    return box;
  }

  // ───── せってい ─────
  settingsView(active) {
    const g = this.game;
    const c = g.me;
    const bs = c.battleSettings || { wait: false };
    const cur = normBattleSettings(bs);
    const STEP = ['とてもゆっくり', 'ゆっくり', 'ふつう', '速い', 'とても速い'];
    const sp = STEP[BATTLE_SPEEDS.indexOf(cur.speed)] || 'ふつう';
    const tsp = STEP[TEXT_SPEEDS.indexOf(cur.textSpeed)] || 'ふつう';
    const bfs = { s: '小さい', m: 'ふつう', l: '大きい' }[battleFontPref()];
    const bden = { 1: '少なめ（大きく）', 2: 'ふつう', 3: '多め（3列）' }[battleDensityPref()];
    const vol = (v) => '■'.repeat(Math.round(v * 5)) + '□'.repeat(5 - Math.round(v * 5));
    const send = (patch) => g.net.send({ t: 'menu', action: 'settings', speed: cur.speed, textSpeed: cur.textSpeed, wait: !!bs.wait, auto: !!bs.auto, ...patch });
    // ゲームの 難しさ（キャラごと。difficulty.js）
    const dif = difficultyOf(c);
    const sendDif = (patch) => g.net.send({ t: 'menu', action: 'settings', difficulty: patch });
    // 敵の 強さ（ハード 1.2倍 など）。パーティーに さそわれて いる ときは リーダーの 設定で 戦う
    const lead = g.visitingLeader?.();
    const leadRate = lead && ENEMY_RATES.includes(g.party?.enemyRate) ? g.party.enemyRate : null;
    const items = [
      { header: true, label: 'ゲームの難しさ', cls: 'set-hdr' },
      { label: `目的地のしるし（メイン）：${dif.mainMarks ? '出す' : '出さない'}`, value: 'dMain' },
      { label: `目的地のしるし（たのまれごと）：${dif.subMarks ? '出す' : '出さない'}`, value: 'dSub' },
      { label: `もらえる経験値：${EXP_RATE_NAMES[dif.exp]}`, value: 'dExp' },
      { label: `敵の強さ：${foeName(dif.enemy)}`, value: 'dEnemy' },
      { header: true, label: '画面と音・戦い', cls: 'set-hdr' },
      { label: `戦いの速さ（エフェクト）：${sp}`, value: 'speed' },
      { label: `文字の速さ：${tsp}`, value: 'textSpeed' },
      { label: `戦いの文字の大きさ：${bfs}`, value: 'bfont' },
      { label: `戦いのコマンドの数：${bden}`, value: 'bdense' },
