      { label: `メニューの表示：${MENU_VIEWS[menuViewOf(c)]}`, value: 'menuView' },
    ];
    // 第50回 N3: 大事な物の すぐ使う ボタン（すぐ使える 大事な物を 持っている 人だけ。data/quick-item.js）
    if (quickList(c).length) {
      const qk = quickItemOf(c);
