        } else if (it.value === 'hand') {
          // 第67回: たて持ちを 自分で ならべて いる ときは、まず 今までの ならびに もどす
          if (loadLayout().tate) {
            saveLayout('tate', null);
            toast('たて持ちのボタンを、もとのならびにもどしました');
          } else nextHand();
        } else if (it.value === 'layout') {
          // メニューを とじて ならべる 画面へ（ボタンが 見えるように）
          this.close();
          layoutEditor(g).then((saved) => { if (saved) toast('ボタンの配置を決めました'); });
          return;
        } else if (it.value === 'pad') {
          g.input.padOn = !g.input.padOn;
        } else if (it.value === 'awake') {
          g.awakeOn = !g.awakeOn;
        } else if (it.value === 'silent') {
          g.audio.silentPlay = !g.audio.silentPlay;
          g.audio.sfx('confirm');
        } else if (it.value === 'quickItem') {
          // すぐ使う 大事な物を えらぶ（なし も できる）
          this.sub.blur();
          const qk = quickItemOf(c);
          const list = quickList(c).map((k) => ({ label: ITEMS[k].name, right: k === qk ? '今' : '', value: k }));
          this.pick('すぐ使う大事な物', [...list, { label: 'なし（ボタンを出さない）', value: '' }, { label: 'やめる', value: null }], { start: qk || '' }).then(async (v) => {
            if (v !== null && v !== undefined && v !== (qk || '') && this.root) await this.menuCall({ t: 'menu', action: 'quickSet', id: v });
            again(idx);
          });
          return;
        } else if (it.value === 'quickPad') {
          const now = QUICK_PADS.findIndex((p) => p.b === quickPadOf(c));
          g.net.send({ t: 'menu', action: 'quickPad', pad: QUICK_PADS[(now + 1) % QUICK_PADS.length].b });
        } else if (it.value === 'menuView') {
          // サーバーの 返事を まって 作りなおす（かんたん の 時だけ キャラに 項目が のこる）
          this.sub.blur();
          const next = menuSimple(c) ? 'full' : 'simple';
          this.menuCall({ t: 'menu', action: 'settings', menuView: next }).then(() => again(idx));
          return;
        } else if (it.value === 'stamps') {
          this.sub.blur();
          openStampEditor(g).then(() => again(idx));
          return;
        } else if (it.value === 'rescue') {
          this.close();
          g.rescue();
          return;
        } else if (it.value === 'errlog') {
          this.errLogPopup().then(() => again(idx));
          return;
        }
        setTimeout(() => again(idx), 200);
      },
    });
    const foeNote = `敵の強さをハード（1.2倍）・ベリーハード（1.5倍）・スーパーハード（2倍）にすると、魔物のHP・MP・攻撃・守り・素早さ・魔力がその倍になる（もらえる経験値・ゴールド・落とす物は同じ）。パーティーでは、リーダーの設定で戦う。${lead ? `\n今は${lead.name}の設定で戦っている：${foeName(leadRate || 1)}` : ''}`;
    box.append(m.root, el('div', { class: 'detail', text: `ゲームの難しさ: 目的地のしるしを「出さない」にすると、地図のしるしと仲間の「行き先は〇〇のほう」が出なくなる。経験値を0.75倍・0.5倍・0.25倍・0.1倍にすると、レベルが上がりにくくなる（仲間・馬車の仲間も同じ）。\n${foeNote}\nウェイトをONにすると、コマンドを選ぶ間は戦いの時間が止まる（じっくり考えたい人におすすめ）\n音楽の音を「前の音」にすると、前までの音楽の鳴り方にもどる。音の重さを「かるい」にすると、音のひびきと重ねを止めて、スマホが軽くなる。まわりの音は、町のざわめきや波・風の音（新しい音の時だけ）\nメニューの表示を「かんたん」にすると、呪文・技の画面がかんたんになる（覚えた技は、今の職業の技が先で強い技が上。お気に入りのならびかえと、命令の一覧に出さない技の切りかえは出さない。前に決めたことは、そのまま戦いで使われる）。キャラごとに決められる` +(quickList(c).length ? '\n大事な物のボタン: 時の砂時計などを、画面の右上のボタン（使える場所だけ出る）・コントローラーのボタン・キーボードのTで、すぐ使える。「道具」の「大事な物」からも選べる' : '') + (g.input.touch ? '\n画面が消えると家族との通信がとぎれやすいので「画面を消さない」はONがおすすめ' : '') }));
    return box;
  }

  // もらえる 経験値を えらぶ まど（5つの 倍率と みじかい せつめい。カーソルは 今の 倍率）。えらんだ 倍率（やめる なら null）
  pickExpRate(now) {
    const items = EXP_RATES.map((r) => ({
      html: `${esc(EXP_RATE_NAMES[r])}${r === now ? '<span class="tag gold">今</span>' : ''}<span class="sk-desc">${esc(EXP_RATE_NOTES[r])}</span>`,
      right: `${r}倍`,
      value: r,
      cls: 'sk',
    }));
    const note = '戦いでもらえる経験値が、この倍になる。\n仲間・馬車の仲間も同じ。ゴールド・落とす物は同じ。';
    return this.pick('もらえる経験値', [...items, { label: 'やめる', value: null }], { wide: true, cls: 'foe-pick', start: now, note: { text: note, cls: 'info' } });
  }

  // 敵の 強さを えらぶ まど（4つの 強さと みじかい せつめい。カーソルは 今の 強さ）。えらんだ 倍率（やめる なら null）
  // lead … パーティーに さそわれて いる ときの リーダー（その 人の 設定 leadRate で 戦う）
  pickEnemyRate(now, lead = null, leadRate = null) {
    const items = ENEMY_RATES.map((r) => ({
      html: `${esc(ENEMY_RATE_NAMES[r])}${r === now ? '<span class="tag gold">今</span>' : ''}<span class="sk-desc">${esc(ENEMY_RATE_NOTES[r])}</span>`,
      right: `${r}倍`,
      value: r,
      cls: 'sk',
    }));
    const lines = ['魔物のHP・MP・攻撃・守り・素早さ・魔力が、この倍になる。', 'もらえる経験値・ゴールド・落とす物は同じ。', 'パーティーでは、リーダーの設定で戦う。'];
    if (lead) lines.push(`今は${lead.name}の設定で戦っている：${foeName(leadRate || 1)}`);
    return this.pick('敵の強さ', [...items, { label: 'やめる', value: null }], { wide: true, cls: 'foe-pick', start: now, note: { text: lines.join('\n'), cls: 'info' } });
  }
}

// キャンバスの 字（設定の「字の形」に あわせる。まだ 読みこんで いない 字は 読みこんでおく）
function canvasFont(px, text) {
  const fam = uiFontFamily();
  const f = `${px}px ${fam}, sans-serif`;
  try { document.fonts?.load(f, text).catch(() => {}); } catch { /* */ }
  return f;
}

