const MAP_COLORS = {
  [T.GRASS]: '#5bab4b', [T.FLOWERS]: '#79c663', [T.TALLGRASS]: '#4a953f', [T.DIRT]: '#caa367', [T.SAND]: '#ead79c', [T.WATER]: '#3c80d6',
  [T.DEEP]: '#2a58a8', [T.TREE]: '#2f7a36', [T.PINE]: '#2a6a3a', [T.MOUNTAIN]: '#8f8270', [T.HILL]: '#6cb558', [T.ROCK]: '#8f8270',
  [T.BRIDGE_H]: '#a8733e', [T.BROKEN_BRIDGE]: '#3c80d6', [T.SWAMP]: '#6a4a7a', [T.FOREST_FLOOR]: '#3f7d3a', [T.STEPPING]: '#8a9ab8',
  [T.CAVE_FLOOR]: '#6a5a4a', [T.CAVE_WALL]: '#1d1714', [T.CAVE_WATER]: '#1f3f6e', [T.BOSS_FLOOR]: '#5a4870',
  [T.PIER]: '#a8733e', [T.WHIRLPOOL]: '#9a8ad8',
};

export function renderMiniMap(game, canvas, full = false) {
  const f = game.field;
  const m = f.map;
  if (!m) return;
  const ctx = ctxOf(canvas);
  const pxPer = full ? Math.max(2, Math.min(5, Math.floor(Math.min(innerWidth * 0.86 / m.w, innerHeight * 0.72 / m.h)))) : 2;
  let x0 = 0, y0 = 0, w = m.w, h = m.h;
  if (!full) {
    w = Math.floor(canvas.width / pxPer);
    h = Math.floor(canvas.height / pxPer);
    x0 = Math.floor(f.me.x - w / 2);
    y0 = Math.floor(f.me.y - h / 2);
  } else {
    canvas.width = m.w * pxPer;
    canvas.height = m.h * pxPer;
  }
  ctx.fillStyle = '#0a0b1e';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const mx = x0 + x, my = y0 + y;
      if (mx < 0 || my < 0 || mx >= m.w || my >= m.h) continue;
      if (!f.isExplored(mx, my)) continue;
      const t = m.gates.length ? effectiveTile(m, mx, my, (fl) => f.gateFlag(fl)) : tileAt(m, mx, my);
      ctx.fillStyle = themeHex(MAP_COLORS[t] || TILE_INFO[t]?.mapColor || (t >= 30 && t < 70 ? '#c8bfae' : '#555'), m.theme, t);
      ctx.fillRect(x * pxPer, y * pxPer, pxPer, pxPer);
    }
  }
  const dot = (x, y, c, r = 2) => {
    ctx.fillStyle = '#000';
    ctx.fillRect((x - x0) * pxPer - r - 1, (y - y0) * pxPer - r - 1, r * 2 + 2, r * 2 + 2);
    ctx.fillStyle = c;
    ctx.fillRect((x - x0) * pxPer - r, (y - y0) * pxPer - r, r * 2, r * 2);
  };
  // ばしょの なまえ（行ったことが ある ところ だけ）
  const labels = m.id === 'overworld' ? Object.values(PLACES) : m.labels || [];
  if (full) {
    for (const p of labels) {
      if (!f.isExplored(p.x + Math.floor(p.w / 2), p.y + Math.floor(p.h / 2))) continue;
      ctx.fillStyle = '#fff';
      ctx.font = canvasFont(Math.max(10, pxPer * 4), p.name);
      ctx.fillText(p.name, Math.max(2, (p.x - x0) * pxPer), Math.max(12, (p.y - y0) * pxPer - 3));
    }
  }
  // お店の しるし（行ったことが ある ところ だけ）
  for (const b of m.boards || []) {
    if (!f.isExplored(b.x, b.y)) continue;
    const ic = mapIconCanvas(b.kind);
    const px = Math.round((b.x + 0.5 - x0) * pxPer - ic.width / 2), py = Math.round((b.y + 0.5 - y0) * pxPer - ic.height / 2);
    if (px + ic.width < 0 || py + ic.height < 0 || px > canvas.width || py > canvas.height) continue;
    ctx.drawImage(ic, px, py);
  }
  drawQuestMarks(game, ctx, canvas, x0, y0, pxPer, full);
  for (const o of f.others.values()) dot(o.x, o.y, o.partyId === game.party?.id ? '#ffd66b' : '#8fd0ff', full ? 3 : 2);
  const blink = Math.floor(performance.now() / 300) % 2;
  dot(f.me.x, f.me.y, blink ? '#ff5a5a' : '#ffffff', full ? 3 : 2);
}

// 仲間会話（はなす）: 仲間が 1人ずつ 今の 目標の ヒントを 話す。さいごに 行き先の 方角
const DIR8 = ['東', '南東', '南', '南西', '西', '北西', '北', '北東'];
export function questDirection(game) {
  const f = game.field;
  const m = visibleMarks(game.me, questMarks(game.me, f.mapId, currentObjective(game))).find((x) => x.kind === 'main');
  if (!m) return '';
  const dx = m.x + 0.5 - f.me.x, dy = m.y + 0.5 - f.me.y;
  const dist = Math.hypot(dx, dy);
  if (dist < 3) return m.via ? '次の行き先へは、すぐそこの出入り口から行ける。' : '次の行き先は、すぐ近くだ。';
  const i = ((Math.round(Math.atan2(dy, dx) / (Math.PI / 4)) % 8) + 8) % 8;
  const where = `ここから${DIR8[i]}${dist > 40 ? 'のずっと先' : 'のほう'}`;
  return m.via ? `次の行き先へは、${where}にある出入り口から行ける。` : `次の行き先は、${where}。`;
}
export async function partyTalk(game) {
  const g = game;
  const obj = currentObjective(g);
  const p = g.party;
  const speakers = [];
  for (const s of p?.supports || []) speakers.push(memberTalk({ key: s.key, name: s.name, species: s.species }, obj));
  for (const gu of p?.guests || []) speakers.push(memberTalk({ key: gu.id, name: gu.name }, obj));
  g.audio.sfx('confirm');
  if (!speakers.length) await g.script.say(g.me.name, talkFor(obj, 'self'));
  for (const sp of speakers.slice(0, 4)) await g.script.say(sp.mon ? '' : sp.name, sp.text);
  const dir = questDirection(g);
  if (dir) await g.script.say('', `――${dir}`);
  const side = sideQuestHint(g.me);
  if (side) await g.script.say('', side);
  g.script.closeDialog();
}

// 目標の しるし: ピンク＝次の 行き先、水色＝たのまれごと、みどり＝報告できる。
// 小さい 地図の 外に ある ときは ふちに 矢じるし
const QUEST_COLORS = { main: '#ff5fd2', sub: '#5fd8ff', subReady: '#7dff8a', ask: '#ffd84a' }; // ask … 困っている人（第50回 N4）
export function currentObjective(game) {
  return game.visitingLeader?.() ? game.party?.objective : game.me?.objective;
}
function drawQuestMarks(game, ctx, canvas, x0, y0, pxPer, full) {
  // ゲームの 難しさで 出さない しるしは かかない
  const marks = visibleMarks(game.me, questMarks(game.me, game.field.mapId, currentObjective(game)));
  const t = performance.now();
  const pulse = 0.5 + 0.5 * Math.sin(t / 220);
  // 下から メインが いちばん うえに なるように
  marks.sort((a, b) => (b.kind === 'main') - (a.kind === 'main'));
  for (const m of marks.reverse()) {
    const col = QUEST_COLORS[m.kind];
    let px = (m.x + 0.5 - x0) * pxPer, py = (m.y + 0.5 - y0) * pxPer;
    const r = full ? Math.max(5, pxPer * 1.6) : 4;
    const out = px < r || py < r || px > canvas.width - r || py > canvas.height - r;
    if (out) {
      if (full) continue;
      // ふちの 矢じるし（中心から その 向きへ）
      const cx = canvas.width / 2, cy = canvas.height / 2;
      const ang = Math.atan2(py - cy, px - cx);
      const k = Math.min((cx - 5) / Math.max(1e-6, Math.abs(Math.cos(ang))), (cy - 5) / Math.max(1e-6, Math.abs(Math.sin(ang))));
      px = cx + Math.cos(ang) * k;
      py = cy + Math.sin(ang) * k;
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(ang);
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.moveTo(6, 0); ctx.lineTo(-4, -5); ctx.lineTo(-4, 5); ctx.closePath(); ctx.fill();
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.moveTo(4.5, 0); ctx.lineTo(-3, -3.5); ctx.lineTo(-3, 3.5); ctx.closePath(); ctx.fill();
      ctx.restore();
      continue;
    }
    ctx.save();
    ctx.translate(px, py);
    if (m.kind === 'main') {
      // ひし形（ドラクエの 目的地の ように 光る）
      ctx.globalAlpha = 0.35 + 0.4 * pulse;
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(0, 0, r * (1.5 + 0.5 * pulse), 0, Math.PI * 2); ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.moveTo(0, -r - 1.5); ctx.lineTo(r + 1.5, 0); ctx.lineTo(0, r + 1.5); ctx.lineTo(-r - 1.5, 0); ctx.closePath(); ctx.fill();
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.moveTo(0, -r); ctx.lineTo(r, 0); ctx.lineTo(0, r); ctx.lineTo(-r, 0); ctx.closePath(); ctx.fill();
    } else {
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.arc(0, 0, r * 0.85 + 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = col;
      ctx.beginPath(); ctx.arc(0, 0, r * 0.85, 0, Math.PI * 2); ctx.fill();
      if (full && m.kind === 'subReady') {
        ctx.fillStyle = '#000';
        ctx.font = canvasFont(Math.max(9, r * 1.5), '!');
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('!', 0, 0.5);
      }
    }
    ctx.restore();
    if (full) {
      const label = m.via ? `${m.label}（この先）` : m.label;
      ctx.font = canvasFont(Math.max(10, pxPer * 3.4), label);
      ctx.lineWidth = 3;
      ctx.strokeStyle = '#000';
      ctx.fillStyle = col;
      const tx = Math.min(canvas.width - ctx.measureText(label).width - 2, Math.max(2, px + r + 3));
      const ty = Math.max(12, py - r - 2);
      ctx.strokeText(label, tx, ty);
      ctx.fillText(label, tx, ty);
    }
  }
}

// 地図の しるしの せつめい（行ったことが ある お店 だけ）
function mapLegend(game) {
  const f = game.field;
  const seen = new Map();
  for (const b of f.map.boards || []) if (f.isExplored(b.x, b.y) && !seen.has(b.kind)) seen.set(b.kind, b.name);
  if (!seen.size) return null;
  const box = el('div', { class: 'map-legend small' });
  for (const [kind, name] of seen) box.append(el('span', { class: 'lg' }, el('img', { src: boardIconURL(kind), alt: '' }), name));
  return box;
}

export function openWorldMap(game) {
  if (document.querySelector('.worldmap')) return;
  const back = el('div', { class: 'modal-back' });
  const box = el('div', { class: 'win panel center-panel worldmap', style: { width: 'auto', maxWidth: '96vw' } });
  const cv = makeCanvas(10, 10);
  const head = el('div', { class: 'wm-head' }, el('span', { class: 'gold', text: game.field.map.name }),
    el('button', { class: 'btn closebtn', text: '✕ 閉じる', 'aria-label': '地図を閉じる' }));
  // しるしの せつめい（ゲームの 難しさで 出さない しるしは のせない）
  const dif = difficultyOf(game.me);
  const qlg = dif.mainMarks || dif.subMarks ? el('div', { class: 'map-legend small' },
    dif.mainMarks ? el('span', { class: 'lg' }, el('i', { class: 'qdot qmain' }), '次の行き先') : null,
    dif.subMarks ? el('span', { class: 'lg' }, el('i', { class: 'qdot sub' }), 'たのまれごと') : null,
    dif.subMarks ? el('span', { class: 'lg' }, el('i', { class: 'qdot ready' }), '報告できる') : null) : null;
  box.append(...[head, cv, qlg, mapLegend(game)].filter(Boolean), el('div', { class: 'small muted', text: `赤い点: 自分　黄色: パーティー　青: 家族　（${game.input.touch ? 'タップで閉じる' : 'B/Xで閉じる'}）` }));
  document.getElementById('ui').append(back, box);
  renderMiniMap(game, cv, true);
  const iv = setInterval(() => renderMiniMap(game, cv, true), 400);
  const h = { el: box, onNav: (a) => { if (a === 'b' || a === 'a' || a === 'map') close(); } };
  const close = () => {
    clearInterval(iv);
    game.input.pop(h);
    back.remove();
    box.remove();
    game.audio.sfx('cancel');
  };
  box.addEventListener('click', close);
  back.addEventListener('click', close);
  game.input.push(h);
}

// 第78回 3-6: かんたん表示の CSS（css/style.css は ほかの 人も かえるので、ここで 入れる。はじめて かんたん表示を 出した 時に 1回だけ）
//   技の 画面の すみ（見出しの 右下）に「かんたん表示（設定で変えられます）」
let simpleCssOn = false;
function addSimpleCss() {
  if (simpleCssOn || typeof document === 'undefined') return;
  simpleCssOn = true;
  const st = document.createElement('style');
  st.textContent = '.skills-view .sk-head .simple-note { text-align: right; font-size: 0.72em; color: var(--muted, #aab); margin: 0.05em 0.2em 0.1em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }';
  document.head.append(st);
}

js/client/ui/missions.js:
// 第78回 3-10: メニューの「家族ミッション」と「家族の記録」（docs/plan-r78-mission.md）
//   ・数えるのは サーバー（shared/world/missions.js）。ここは 見せるだけ（{ t: 'mission', action } で 聞く・受けとる）
//   ・画面を 大きく 使う まど 1まい（冒険のしおりと おなじ 考え。たて画面は 1列、よこ画面・PC は 2〜3列）
//   ・キーボード・ゲームパッド（上下左右・決定・もどる）・タップの どれでも（dom.js の ListMenu）
//   ・ひとりで遊ぶサイトでは「家族サーバーでいっしょに遊ぶと進みます」だけ（エラーに しない）
import { el, ListMenu, esc, toast } from './dom.js';
import './r78-mission-css.js';
import { request } from './syncui.js';

const OFFLINE_TEXT = '家族サーバーでいっしょに遊ぶと進みます';
const HOW = '人間のキャラが2人いじょう、同じパーティーで遊んだ時だけ進む。ひとりの時は進まない。';

// サーバーに 聞く（ひとりモードでも この ブラウザの 世界が { offline: true } と こたえる）
export async function fetchMissions(g, msg = { action: 'view' }) {
  if (!g?.net) return null;
  const m = await request(g, { t: 'mission', ...msg }, 'mission', 8000);
  if (m && !m.timeout) g.missionSum = m;
  return m;
}

// メニューを 開いた 時に 先に 聞いて おく（冒険のしおりの「家族ミッション」の 行。とどかなくても よい）
//   とどいた 時に 見本を 出して いれば かきなおす
export function prefetchMissions(menu) {
  fetchMissions(menu.game).then(() => {
    if (menu.root && menu.current === 'mission' && menu.menu?.active) menu.preview('mission');
  }).catch(() => {});
}

const rewardText = (r) => `${r.gold}G・${r.items.map((x) => `${x.name}×${x.n}`).join('・')}`;
const pct = (a, b) => Math.round(Math.max(0, Math.min(1, b ? a / b : 0)) * 100);

function missionHtml(x) {
  const st = x.done ? (x.got ? '<span class="ms-tag got">受けとりずみ</span>' : '<span class="ms-tag ok">達成！</span>') : '';
  return `<div class="ms-top"><span class="ms-text">${esc(x.text)}</span>${st}</div>`
    + `<div class="ms-bar ${x.done ? 'done' : ''}"><i style="width:${pct(x.now, x.need)}%"></i></div>`
    + `<div class="ms-sub"><span class="ms-num">${x.now}/${x.need}</span>${x.mine ? `<span class="ms-mine">自分も${x.mine}</span>` : ''}</div>`
    + `<div class="ms-rew">ごほうび：${esc(rewardText(x.reward))}</div>`;
}

// メニューの 右の 見本（カーソルを あわせた だけ）
export function missionsPreview(menu) {
  const g = menu.game;
  const box = el('div', { class: 'ms-pv' });
  box.append(el('div', { class: 'muted', text: `週がわりの、家族みんなのミッション。\n${HOW}\n選ぶと、大きく開く。` }));
  const m = g.missionSum;
  if (m?.offline) box.append(el('div', { class: 'ms-pv-off', text: OFFLINE_TEXT }));
  else if (m?.week) {
    box.append(el('div', { class: 'ms-pv-days', text: `今週のミッション（のこり${m.week.days}日）` }));
    for (const x of m.week.list) box.append(el('div', { class: 'ms-pv-row' }, el('span', { text: `${x.done ? '★' : '・'}${x.text}` }), el('span', { class: 'ms-pv-num', text: `${x.now}/${x.need}` })));
  }
  return box;
}

// 大きな まどを 開く。とじたら おわる Promise
export function openMissions(menu) {
  const g = menu.game;
  const sfx = (x) => g.audio?.sfx?.(x);
  return new Promise((resolve) => {
    let data = g.missionSum || null;
    let page = 'main';
    let list = null;
    let mainIdx = -1;
    let busy = false;
    const back = el('div', { class: 'modal-back', style: { zIndex: 4 }, onclick: () => { sfx('cancel'); finish(); } });
    const title = el('h2', { class: 'ms-title', text: '家族ミッション' });
    const sub = el('span', { class: 'ms-days' });
    const closeBtn = el('button', { class: 'btn ms-close', text: '✕ 閉じる', 'aria-label': '家族ミッションを閉じる', onclick: (e) => { e.stopPropagation(); sfx('cancel'); onBack(); } });
    const body = el('div', { class: 'ms-body' });
    const foot = el('div', { class: 'ms-foot', text: HOW });
    const box = el('div', { class: 'win mission-pop', role: 'dialog', 'aria-label': '家族ミッション' }, el('div', { class: 'ms-head' }, title, sub, closeBtn), body, foot);

    const finish = () => {
      list?.blur();
      back.remove();
      box.remove();
      menu.popupOpen = false;
      resolve();
    };
    function onBack() {
      if (page !== 'main') show('main');
      else finish();
    }
    function makeList(items, start, onSelect) {
      list?.blur();
      body.innerHTML = '';
      list = new ListMenu(g.input, { items, className: 'ms-list', sound: sfx, back: null, start, onSelect, onCancel: () => onBack() });
      body.append(list.root);
      list.focus();
      list.scrollToSel?.();
    }

    async function act(v) {
      if (busy || !v) return;
      if (v.act === 'record') return show('record');
      if (v.act === 'wear') return show('wear');
      if (v.act === 'close') return finish();
      if (v.act === 'claim' || v.act === 'setWear') {
        busy = true;
        const r = await fetchMissions(g, v.act === 'claim' ? { action: 'claim', which: v.which } : { action: 'wear', n: v.n });
        busy = false;
        if (!box.isConnected) return;
        if (!r || r.timeout) {
          toast('通信がおくれています');
          sfx('buzz');
          return;
        }
        data = r;
        if (r.text) toast(r.text, 5000);
        sfx(r.ok ? 'item' : 'buzz');
        show(v.act === 'setWear' ? 'main' : page);
      }
    }

    // ───── 1まい目: 今週の 3つ・ごほうび・しょうごう・記録への 入口 ─────
    function mainItems() {
      const items = [];
      if (!data) {
        items.push({ html: '<div class="ms-note">読みこんでいます…</div>', value: null, cls: 'ms-wide' });
        return items;
      }
      if (data.timeout) {
        items.push({ html: '<div class="ms-note">通信がおくれています。もう一度開いてみてね。</div>', value: { act: 'close' }, cls: 'ms-wide' });
        return items;
      }
      if (data.offline) {
        items.push({ html: `<div class="ms-off">${esc(OFFLINE_TEXT)}</div><div class="ms-note">${esc(HOW)}\nこのサイトはひとりで遊ぶサイトなので、ミッションは進まない。</div>`, value: { act: 'close' }, cls: 'ms-wide' });
        return items;
      }
      const w = data.week;
      items.push({ header: true, label: `今週のミッション（のこり${w.days}日）` });
      w.list.forEach((x, i) => items.push({ html: missionHtml(x), value: { act: 'info', i }, cls: `ms-card ${x.done ? 'done' : ''}` }));
      items.push({ header: true, label: 'ごほうび' });
      if (w.claim) items.push({ html: `<div class="ms-big">ごほうびを受けとる（${w.claim}こ）</div>`, value: { act: 'claim', which: 'cur' }, cls: 'ms-claim' });
      else items.push({ html: `<div class="ms-note">${esc(w.joined ? 'ミッションを達成すると、ここで受けとれる。' : 'この週に、家族といっしょに遊ぶと受けとれる。')}</div>`, value: { act: 'info' }, cls: 'ms-info' });
      if (data.prev?.claim) items.push({ html: `<div class="ms-big">先週のごほうびを受けとる（${data.prev.claim}こ）</div><div class="ms-note">先週の分は、今週のうちに受けとろう。</div>`, value: { act: 'claim', which: 'prev' }, cls: 'ms-claim' });
      items.push({ header: true, label: 'しょうごう・スタンプ' });
      const me = data.me;
      const nx = me.next ? `つぎは、3つとも達成した週があと${me.next.left}週で「${me.next.title}」` : 'しょうごうを、全部集めた！';
      items.push({
        html: `<div class="ms-big">${esc(me.title ? `しょうごう：${me.title}` : 'しょうごう：なし')}</div><div class="ms-note">3つとも達成した週：${me.full}週\n${esc(nx)}${me.titles.length ? '\n選ぶと、つけるしょうごうを変えられる。' : ''}</div>`,
        value: me.titles.length ? { act: 'wear' } : { act: 'info' }, cls: 'ms-info',
      });
      items.push({ header: true, label: '家族の記録' });
      items.push({ html: `<div class="ms-big">家族の記録を見る</div><div class="ms-note">いっしょにたおした魔物・勝った戦い・今週のがんばり・先週の結果</div>`, value: { act: 'record' }, cls: 'ms-info' });
      return items;
    }

    // ───── 家族の 記録 ─────
    function recordItems() {
      const r = data.record;
      const items = [{ header: true, label: '家族の記録' }];
      const stat = (k, v) => ({ html: `<div class="ms-k">${esc(k)}</div><div class="ms-v">${esc(v)}</div>`, value: null, cls: 'ms-stat' });
      items.push(stat('いっしょにたおした魔物', `${r.kills}ひき`));
      items.push(stat('いっしょに勝った戦い', `${r.wins}回`));
      items.push(stat('3つとも達成した週', `${r.full}週`));
      items.push(stat('達成したミッション', `${r.done}こ`));
      items.push({ header: true, label: '今週のがんばり' });
      if (data.people.length) {
        for (const p of data.people) items.push({ html: `<div class="ms-k">${esc(p.name)}${p.me ? '（自分）' : ''}</div><div class="ms-note">いっしょの戦い${p.b}回・魔物${p.k}ひき・ミッション${p.sum}</div>`, value: null, cls: `ms-stat ${p.me ? 'me' : ''}` });
      } else items.push({ html: '<div class="ms-note">今週は、まだだれもいっしょに遊んでいない。</div>', value: null, cls: 'ms-stat ms-wide' });
      items.push({ header: true, label: '先週の結果' });
      const pv = data.prev;
      if (pv) {
        const n = pv.list.filter((x) => x.done).length;
        items.push({ html: `<div class="ms-big">${pv.full ? '3つとも達成！' : `${n}つ達成`}</div>`, value: null, cls: 'ms-stat ms-wide' });
        for (const x of pv.list) items.push({ html: `<div class="ms-k">${x.done ? '★' : '・'}${esc(x.text)}</div><div class="ms-note">${x.now}/${x.need}</div>`, value: null, cls: 'ms-stat' });
      } else items.push({ html: '<div class="ms-note">まだありません。</div>', value: null, cls: 'ms-stat ms-wide' });
      items.push({ header: true, label: 'いっしょにたおしたボス' });
      if (r.bosses.length) for (const b of r.bosses) items.push(stat(b.name, `${b.n}回`));
      else items.push({ html: '<div class="ms-note">まだいません。</div>', value: null, cls: 'ms-stat ms-wide' });
      items.push({ label: '← もどる', value: { act: 'back' }, cls: 'ms-backrow' });
      return items;
    }

    // ───── しょうごうを えらぶ ─────
    function wearItems() {
      const me = data.me;
      const items = [{ header: true, label: 'つけるしょうごうを選ぶ（チャットの名前の横に出る）' }];
      for (const t of me.titles) items.push({ html: `<div class="ms-big">${esc(t.title)}</div><div class="ms-note">${t.n}週でもらった。スタンプ「${esc(t.stamp)}」</div>`, right: me.wear === t.n ? 'つけている' : '', value: { act: 'setWear', n: t.n }, cls: 'ms-info' });
      items.push({ html: '<div class="ms-big">つけない</div>', right: me.wear ? '' : '今', value: { act: 'setWear', n: 0 }, cls: 'ms-info' });
      return items;
    }

    function show(p) {
      page = p;
      closeBtn.textContent = p === 'main' ? '✕ 閉じる' : '← もどる';
      title.textContent = p === 'record' ? '家族の記録' : '家族ミッション';
      sub.textContent = data?.week ? `のこり${data.week.days}日` : '';
      if (p === 'record' && data?.record) {
        makeList(recordItems(), -1, (it) => { if (it.value?.act === 'back') show('main'); });
        body.scrollTop = 0;
        return;
      }
      if (p === 'wear' && data?.me) {
        makeList(wearItems(), -1, (it) => act(it.value));
        return;
      }
      page = 'main';
      makeList(mainItems(), mainIdx, (it, i) => {
        mainIdx = i;
        act(it.value);
      });
    }

    document.getElementById('ui').append(back, box);
    menu.popupOpen = true;
    show('main');
    // いちばん 新しい ようすを 聞いて かきなおす
    fetchMissions(g).then((m) => {
      if (!box.isConnected) return;
      if (!m || m.timeout) {
        if (!data) {
          data = { timeout: true };
          show(page);
        }
        return;
      }
      data = m;
      show(page);
    });
  });
}

js/client/ui/monarena-live.js:
// 第67回 C班: モンスター闘技場の「その場で家族と対戦」（リアルタイムの 家族対戦）。docs/plan-r67-monster-arena.md
//
// 受付の はじめの えらびしに 足す（ui/monarena.js の MONARENA_EXTRA。value 'live'）。サーバーの 窓口は svc kind:'monlive'（shared/world/monarena-live.js）
//   申しこむ 人: 受付 →「その場で家族と対戦」→ 闘技場に いる 家族を 選ぶ → 強さ（そのままの強さ／レベルをそろえる）→ へんじを 待つ（やめられる）
//              → うけて もらえたら 4ひきを 選ぶ → 相手を 待つ（選びなおす・やめる）→ 2人とも 決まったら 戦い
//   申しこまれた 人: どこに いても（闘技場の 中の 原っぱ・メニュー・受付の 画面）まどが 出る →「うける！」か「ことわる」
//              → うけると その場で 受付の まど（カウンター）が 開いて 4ひきを 選ぶ → 相手を 待つ → 戦い
//   戦いの 画面は ふだんと おなじ（相手の 画面は サーバーが 敵と みかたを 入れかえて 送る。自分の 魔物が 下に 出る）
//   サーバーからの 知らせ { t:'monLive', id, role, state:'ask'|'pick'|'go'|'battle'|'end', opp, even, meReady, oppReady, left, text } は game.js → onMonLive
import { el, ListMenu, toast, CONFIRM_Z } from './dom.js';
import { Counter } from './counter.js';
import { request } from './shop.js';
import { faceURL } from '../field.js';
import { boardIconURL } from '../render/boards.js';
import { MONARENA_EXTRA, monArenaPickTeam, monArenaTeamCards, monArenaCss } from './monarena.js';

const wait = (ms) => new Promise((ok) => setTimeout(ok, ms));
const evenText = (even) => (even ? 'レベルをそろえる' : 'そのままの強さ');
const EVEN_NOTE = '「そのままの強さ」…おたがい、今のレベルのままで戦う。\n「レベルをそろえる」…両方の魔物が、みんな同じレベルになって戦う。小さい子の魔物でも、いい勝負！';
const HINT = '家族と2人で闘技場に来て、その場で対戦を申しこむ。\n相手が「受ける」と、おたがいに4ひきを選んで、コマンドを選んで戦うよ。\n（「めいれいさせろ」の魔物は、自分でコマンドを選ぶ）';
// 知らせが こない 時間（これより 長いと 通信が とぎれたと 見る。サーバーは 2.5びょうごとに 送る）
const LOST_MS = 9000;

// 今の 対戦の ようす（いちばん 新しい 知らせ）。ver … ようすが かわった 回数（待っている 画面を 先へ すすめる）
export const live = { cur: null, ver: 0, at: 0, recv: null, prompt: null, flow: null, asked: new Set() };

// サーバーの 窓口（ほかの 窓口の へんじと まざらない ように、前の へんじを 待ってから）
async function svcQ(game, msg) {
  for (let i = 0; i < 60 && game.svcWaiter; i++) await wait(50);
  return request(game, msg);
}
const svcLive = (game, msg) => svcQ(game, { kind: 'monlive', ...msg });
// へんじの いらない とりやめ（画面を とじた 時）
function quietCancel(game, id) {
  if (!id) return;
  try { game.net.send({ t: 'svc', kind: 'monlive', op: 'cancel', id, quiet: true }); } catch { /* きれた */ }
}

const curOf = (id) => (live.cur && live.cur.id === id ? live.cur : null);
const ended = (id) => {
  const c = curOf(id);
  return !c || c.state === 'end' || c.state === 'battle';
};

// ───────────── サーバーからの 知らせ（game.js）─────────────
export function onMonLive(game, m) {
  if (!m || !m.id) return;
  const prev = live.cur;
  live.at = Date.now();
  if (!prev || prev.id !== m.id || prev.state !== m.state) live.ver++;
  live.cur = m;
  if (m.state === 'end') {
    live.asked.delete(m.id);
    if (live.prompt?.id === m.id) {
      live.prompt.close();
      if (m.text) toast(m.text, 4500);
    } else if (live.flow !== m.id && m.text) toast(m.text, 4500);
    return;
  }
  if (m.state === 'ask' && m.role === 'b' && !live.asked.has(m.id)) {
    live.asked.add(m.id);
    askBox(game, m).catch((e) => console.error(e));
  }
  if (m.state === 'pick' && prev?.id === m.id && m.oppReady && !prev.oppReady && live.flow === m.id) toast(`${m.opp}のチームが決まったよ！`);
}

// 待っている 間に 知らせが くる（または とぎれる）と、カウンターの 待ちを とく
async function guarded(ct, id, fn) {
  const v0 = live.ver;
  const iv = setInterval(() => {
    const c = curOf(id);
    if (c && c.state !== 'end' && c.state !== 'battle' && Date.now() - live.at > LOST_MS) {
      live.cur = { ...c, state: 'end', text: '通信がとぎれてしまったみたい…' };
      live.ver++;
    }
    if (live.ver !== v0) for (const f of [...ct.hooks]) f();
  }, 80);
  try {
    return await fn();
  } finally {
    clearInterval(iv);
  }
}

async function endSay(ct, id) {
  const text = curOf(id)?.text || '対戦は、なしになった…';
  ct.list(null);
  ct.info(null);
  await ct.say(text);
  await ct.tap(2600);
}

function vsBox(game, st, team, oppName, even, note) {
  const box = el('div', { class: 'ct-item' });
  box.append(el('div', { class: 'mona-vs small' }, el('span', { class: 'who', text: `相手: ${oppName}` }), `（${evenText(even)}）`));
  if (team?.length) box.append(el('div', { class: 'mona-h', text: `${game.me?.name || ''}のチーム` }), monArenaTeamCards(team, st.monsters || []));
  if (note) box.append(el('div', { class: 'mona-note small', text: note }));
  return box;
}

// ───────────── 4ひきを 選んで 相手を 待つ（2人 おなじ）─────────────
// もどりち: 'go'（戦いが はじまる）/ 'end'（なしに なった）/ 'closed'（画面が とじた）
async function teamStage(ctx, id) {
  const { game, ct, st } = ctx;
  const info0 = curOf(id);
  const opp = info0?.opp || '相手';
  const even = !!info0?.even;
  const title = `${opp}との対戦`;
  ct.list(null);
  ct.info(vsBox(game, st, null, opp, even, even ? `この対戦は、みんなレベル${info0?.evenLv || 50}にそろえて戦う。` : 'この対戦は、おたがい今のレベルのままで戦う。'));
  await guarded(ct, id, async () => {
    await ct.say(`${opp}との対戦だ！\n強さは「${evenText(even)}」。戦う4ひきを選んでね。`);
    await ct.tap(1800);
  });
  for (;;) {
    if (ct.closed) return 'closed';
    if (ended(id)) return 'end';
    const team = await guarded(ct, id, () => ctx.pickTeam({ purpose: 'fight', title }));
    if (ct.closed) return 'closed';
    if (ended(id)) return 'end';
    if (!team) {
      const a = await guarded(ct, id, () => ct.ask('対戦をやめる？', ['やめる', '続ける']));
      if (ct.closed) return 'closed';
      if (ended(id)) return 'end';
      if (a === 0) {
        await svcLive(game, { op: 'cancel', id });
        live.cur = { ...(curOf(id) || { id }), state: 'end', text: '対戦をやめたよ。' };
        return 'end';
      }
      continue;
    }
    const r = await svcLive(game, { op: 'team', id, team });
    if (ct.closed) return 'closed';
    if (r?.go || r?.me?.state === 'go') return 'go';
    if (!r?.ok) {
      if (!r?.me) {
        if (!ended(id)) live.cur = { ...(curOf(id) || { id }), state: 'end', text: r?.text || '対戦は、なしになった…' };
        return 'end';
      }
      ct.list(null);
      await ct.say(r.text || 'そのチームでは戦えないみたい');
      await ct.tap(2000);
      continue;
    }
    st.team = [...team];
    // 相手を 待つ（選びなおす・やめる）
    let again = false;
    while (!again) {
      ct.info(vsBox(game, st, team, opp, even, curOf(id)?.oppReady ? `${opp}のチームも決まったよ！` : `${opp}は、まだチームを選んでいるところ。\n決まったら、すぐに戦いが始まるよ。`));
      const it = await guarded(ct, id, async () => {
        await ct.say(`${opp}がチームを選ぶのを待っているよ…`);
        return ct.pick([{ value: 're', label: 'チームを選びなおす' }, { value: 'stop', label: '対戦をやめる' }], { back: null });
      });
      if (ct.closed) return 'closed';
      if (curOf(id)?.state === 'go') return 'go';
      if (ended(id)) return 'end';
      if (!it) continue;
      if (it.value === 'stop') {
        await svcLive(game, { op: 'cancel', id });
        live.cur = { ...(curOf(id) || { id }), state: 'end', text: '対戦をやめたよ。' };
        return 'end';
      }
      const u = await svcLive(game, { op: 'unready', id });
      if (u?.me?.state === 'go' || curOf(id)?.state === 'go') return 'go';
      again = true;
    }
  }
}

async function goSay(ctx, id, team) {
  const { game, ct, st } = ctx;
  const c = curOf(id);
  ct.list(null);
  ct.info(vsBox(game, st, team || st.team, c?.opp || '相手', !!c?.even, ''));
  game.audio?.sfx('confirm');
  await ct.say(`${c?.opp || '相手'}との対戦、始め！\nがんばってね！`);
  await ct.tap(1000);
}

// ───────────── 申しこむ 人（受付の 画面から）─────────────
function personInfo(p, rec, note = '') {
  const box = el('div', { class: 'ct-item' });
  box.append(el('div', { class: 'hd' }, el('span', { class: 'gold', text: p.name }), el('span', { class: 'st', text: `Lv${p.level}` })));
  box.append(el('div', { class: 'bank-row' }, el('span', { text: '戦える魔物' }), el('span', { text: `${p.mons}ひき` })));
  const r = rec?.[p.charId];
  box.append(el('div', { class: 'bank-row' }, el('span', { text: 'その場の対戦の記録' }), el('span', { class: 'gold', text: r ? `${r.w}勝${r.l}敗` : 'まだ' })));
  if (!p.can) box.append(el('div', { class: 'mona-note small', text: `今は申しこめない（${p.why}）` }));
  if (note) box.append(el('div', { class: 'mona-note small', text: note }));
  return box;
}

function face(p) {
  try { return faceURL({ look: p.look, job: p.job }); } catch { return ''; }
}

async function waitAnswer(ctx, id, name) {
  const { game, ct } = ctx;
  ct.list(null);
  const left = el('span', { class: 'gold', text: '' });
  const tick = () => {
    const c = curOf(id);
    const ms = c?.left ? Math.max(0, c.left - (Date.now() - live.at)) : 0;
    left.textContent = ms ? `あと${Math.ceil(ms / 1000)}びょう` : '';
  };
  ct.info(el('div', { class: 'ct-item' }, el('div', { class: 'mona-h', text: `${name}のへんじを待っている…` }), el('div', { class: 'bank-row' }, el('span', { text: 'のこり' }), left),
    el('div', { class: 'mona-note small', text: `${name}の画面に、申しこみのまどが出ているよ。\n「受ける」を選んでもらってね。` })));
  tick();
  const iv = setInterval(tick, 500);
  try {
    let first = true;
    for (;;) {
      const it = await guarded(ct, id, async () => {
        if (first) await ct.say(`${name}に申しこんだよ！\nへんじを待っているね…`);
        first = false;
        return ct.pick([{ value: 'stop', label: '申しこみをやめる' }], { back: null });
      });
      if (ct.closed) return 'closed';
      const c = curOf(id);
      if (c?.state === 'pick') {
        game.audio?.sfx('join');
        ct.info(null);
        await ct.say(`${name}が、対戦を受けてくれた！`);
        await ct.tap(1400);
        return ct.closed ? 'closed' : 'pick';
      }
      if (ended(id)) {
        await endSay(ct, id);
        return 'end';
      }
      if (it?.value === 'stop') {
        await svcLive(game, { op: 'cancel', id });
        live.cur = { ...(curOf(id) || { id }), state: 'end', text: '申しこみをやめたよ。' };
        await endSay(ct, id);
        return 'end';
      }
    }
  } finally {
    clearInterval(iv);
  }
}

async function liveRun(ctx) {
  const { game, ct } = ctx;
  let start = 0;
  let id = null;
  let flowId = null;
  try {
    for (;;) {
      if (ct.closed) return null;
      ct.list(null);
      ct.info(null);
      const r = await svcLive(game, { op: 'list' });
      if (ct.closed) return null;
      if (!r?.ok) {
        await ct.say(r?.text || '今は、その場の対戦の受付ができないみたい。');
        await ct.tap(2200);
        return null;
      }
      if (r.me) {
        await ct.say('今は、ほかの対戦の話をしているところみたい。');
        await ct.tap(2200);
        return null;
      }
      const people = r.people || [];
      if (!people.length) {
        ct.info(el('div', { class: 'ct-item' }, el('div', { class: 'mona-note small', text: HINT })));
        const a = await ct.ask('今、闘技場には、ほかの家族がいないみたい。\n家族にも闘技場に来てもらってから、申しこんでね。', ['もう一度さがす', 'もどる']);
        if (a === 0) continue;
        return null;
      }
      const items = people.map((p, i) => ({ value: i, label: p.name, face: face(p), right: p.can ? `Lv${p.level}` : p.why, rightCls: p.can ? '' : 'locked', disabled: !p.can }));
      items.push({ value: 'again', label: 'もう一度さがす' });
      start = Math.min(start, people.length - 1);
      if (!people[start]?.can) start = Math.max(0, people.findIndex((p) => p.can));
      ct.info(personInfo(people[start], r.rec));
      await ct.say('だれに対戦を申しこむ？\n（今、闘技場にいる家族だよ）');
      const it = await ct.pick(items, { start, onMove: (x) => ct.info(x?.value === 'again' ? null : personInfo(people[x.value], r.rec)) });
      if (ct.closed || !it) return null;
      if (it.value === 'again') continue;
      start = it.value;
      const p = people[it.value];
      ct.info(personInfo(p, r.rec, EVEN_NOTE));
      const ev = await ct.ask(`${p.name}に申しこむんだね。\n強さは、どうする？`, ['そのままの強さ', 'レベルをそろえる', 'やめる']);
      if (ct.closed) return null;
      if (ev !== 0 && ev !== 1) continue;
      const res = await svcLive(game, { op: 'invite', sid: p.sid, even: ev === 1 });
      if (ct.closed) {
        quietCancel(game, res?.me?.id);
        return null;
      }
      if (!res?.ok || !res.me) {
        ct.info(null);
        await ct.say(res?.text || 'うまく申しこめなかった…');
        await ct.tap(2400);
        continue;
      }
      id = res.me.id;
      live.cur = { ...res.me, left: res.me.left || 30000 };
      live.at = Date.now();
      live.flow = id;
      flowId = id;
      const ans = await waitAnswer(ctx, id, p.name);
      if (ans === 'closed') return null;
      if (ans !== 'pick') {
        id = null;
        continue;
      }
      const out = await teamStage(ctx, id);
      if (out === 'closed') return null;
      if (out === 'go') {
        id = null;
        await goSay(ctx, live.cur?.id);
        ct.close();
        return 'started';
      }
      await endSay(ct, id);
      id = null;
    }
  } finally {
    if (id && !ended(id)) quietCancel(game, id);
    if (flowId && live.flow === flowId) live.flow = null;
  }
}

// ───────────── 申しこまれた 人 ─────────────
// まどを 出せる 時（原っぱ・メニュー・闘技場の 受付の 画面。ほかの 人と 話している 間・戦いの 間は 待つ）
function canAsk(game) {
  if (game.state !== 'field' || game.battle || game.battleClosing) return false;
  if (!game.busy) return true;
  return !!(live.recv && !live.recv.ct.closed);
}

function askBox(game, m) {
  return (async () => {
    for (let i = 0; i < 400; i++) {
      if (ended(m.id)) return;
      if (canAsk(game)) break;
      await wait(150);
    }
    if (ended(m.id) || !canAsk(game)) return;
    game.audio?.sfx('join');
    const ok = await new Promise((resolve) => {
      const ui = document.getElementById('ui');
      const back = el('div', { class: 'modal-back', style: { zIndex: CONFIRM_Z } });
      const menu = new ListMenu(game.input, {
        items: [{ label: '受ける！', value: true }, { label: 'ことわる', value: false }],
        sound: (x) => game.audio?.sfx(x),
        back: null,
        onSelect: (it) => finish(it.value),
        onCancel: () => {},
      });
      const left = el('div', { class: 'small muted', text: '' });
      const box = el('div', { class: 'win panel center-panel mona-ask', style: { width: 'min(92vw, 520px)', zIndex: CONFIRM_Z + 1, background: 'var(--win-solid)' } },
        el('div', { class: 'gold', text: 'モンスター闘技場' }),
        el('div', { style: { whiteSpace: 'pre-line', margin: '0.3em 0 0.5em' }, text: `${m.opp}から、魔物の対戦の申しこみが来た！\n強さ:「${evenText(m.even)}」${m.even ? `（みんなレベル${m.evenLv || 50}）` : ''}\n受ける？` }),
        left, menu.root);
      const t0 = Date.now();
      const tick = () => {
        const c = curOf(m.id);
        const ms = c?.left ? Math.max(0, c.left - (Date.now() - live.at)) : Math.max(0, (m.left || 30000) - (Date.now() - t0));
        left.textContent = `（あと${Math.ceil(ms / 1000)}びょう）`;
      };
      tick();
      const iv = setInterval(tick, 500);
      let done = false;
      const finish = (v) => {
        if (done) return;
        done = true;
        clearInterval(iv);
        menu.blur();
        back.remove();
        box.remove();
        if (live.prompt?.id === m.id) live.prompt = null;
        resolve(v);
      };
      live.prompt = { id: m.id, close: () => finish(null) };
      ui.append(back, box);
      menu.focus();
    });
    if (ok === null || ended(m.id)) return;
    if (!ok) {
      await svcLive(game, { op: 'answer', id: m.id, ok: false });
      return;
    }
    const r = await svcLive(game, { op: 'answer', id: m.id, ok: true });
    if (!r?.ok) {
      toast(r?.text || '対戦は、なしになった…', 4000);
      return;
    }
    await acceptFlow(game, m.id);
  })();
}

async function acceptFlow(game, id) {
  live.flow = id;
  try {
    // メニュー・受付の 画面を とじて、闘技場の 司会の まどで 4ひきを 選ぶ
    if (game.menuOpen) {
      game.menu.close();
      game.closeFieldUI();
    }
    if (live.recv && !live.recv.ct.closed) live.recv.ct.close();
    for (let i = 0; i < 60 && (game.busy || game.script?.running); i++) await wait(50);
    if (ended(id)) return;
    monArenaCss();
    const ct = new Counter(game, { title: 'モンスター闘技場', keeper: '闘技場の司会', icon: boardIconURL('arena'), cls: 'monarena-panel' });
    ct.say('ちょっと待ってね…');
    const st = await svcQ(game, { kind: 'monarena', action: 'status' });
    if (ct.closed) return quietCancel(game, id);
    if (!st?.ok) {
      await svcLive(game, { op: 'cancel', id });
      await ct.say('ごめんね、今は受付のじゅんびをしているところなんだ。');
      await ct.tap(2400);
      ct.close();
      return;
    }
    for (const k of ['ranks', 'monsters', 'family', 'team', 'reg']) if (!Array.isArray(st[k])) st[k] = [];
    const ctx = { game, ct, st, data: {} };
    ctx.svc = (msg) => svcQ(game, { kind: 'monarena', ...msg });
    ctx.pickTeam = (opts) => monArenaPickTeam(ctx, opts);
    const out = await teamStage(ctx, id);
    if (out === 'closed') {
      if (!ended(id)) quietCancel(game, id);
      return;
    }
    if (out === 'go') {
      await goSay(ctx, id);
      ct.close();
      return;
    }
    await endSay(ct, id);
    ct.close();
  } finally {
    if (live.flow === id) live.flow = null;
  }
}

// ───────────── 受付の えらびしに 足す ─────────────
MONARENA_EXTRA.push({
  value: 'live',
  label: 'その場で家族と対戦',
  hint: HINT,
  // 受付の 画面を おぼえておく（申しこまれた 時に とじて、4ひきを 選ぶ まどに する）
  show: (ctx) => {
    live.recv = ctx;
    return true;
  },
  run: (ctx) => liveRun(ctx),
});

js/client/ui/monarena-team.js:
// 第67回 A班: モンスター闘技場の チーム選び（画面を 使わない きまりだけ。テストでも 読む。画面は ui/monarena.js）
//
// status（B班の svc kind:'monarena' action:'status' の へんじ）:
//   { ranks: [{ rank, name, open, cleared, lv, hint }], team: [key…]（前回）, reg: [key…]（登録）,
//     monsters: [{ key, name, species, level, hp, mp, atk, def, agi, where: 'party'|'wagon'|'storage' }],
//     family: [{ charId, name, reg: [{ species, name, level }] }] }
export const TEAM_MAX = 4;

export const WHERE_LABEL = { party: 'パーティー', wagon: '馬車', storage: 'あずかり所', tavern: '酒場' };
export const whereLabel = (w) => WHERE_LABEL[w] || '';

const num = (v) => (Number.isFinite(+v) ? +v : 0);

// 強さの 目安（おまかせ・ならべる 時）。HP は 大きい 数なので 少し 小さく 見る
export function monPower(m) {
  if (!m) return 0;
  return num(m.hp) * 0.5 + num(m.mp) * 0.15 + num(m.atk) * 1.4 + num(m.def) + num(m.agi) * 0.9 + num(m.level) * 2;
}

// 持っている 魔物だけ・同じ 魔物は 1回・4ひきまで
export function normTeam(keys, monsters) {
  const have = new Set((monsters || []).map((m) => m.key));
  const out = [];
  for (const k of Array.isArray(keys) ? keys : []) {
    if (have.has(k) && !out.includes(k)) out.push(k);
    if (out.length >= TEAM_MAX) break;
  }
  return out;
}

// 強い 順（同じ 強さなら レベル・名前の 順。いつも 同じ ならび）
export function sortStrong(monsters) {
  return [...(monsters || [])].sort((a, b) => monPower(b) - monPower(a) || num(b.level) - num(a.level) || String(a.name).localeCompare(String(b.name)) || String(a.key).localeCompare(String(b.key)));
}

// おまかせ（強い 順に 4ひき）
export function autoTeam(monsters) {
  return sortStrong(monsters).slice(0, TEAM_MAX).map((m) => m.key);
}

// 1回で 選ぶ: 'last'（前回の チーム）/ 'reg'（登録チーム）/ 'auto'（おまかせ）
export function presetTeam(kind, st) {
  const mons = st?.monsters || [];
  if (kind === 'last') return normTeam(st?.team, mons);
  if (kind === 'reg') return normTeam(st?.reg, mons);
  if (kind === 'auto') return autoTeam(mons);
  return [];
}

// はじめに 出す チーム。戦う 時は 前回 → 登録 → おまかせ、登録する 時は 登録 → 前回 → おまかせ
export function initialTeam(st, purpose = 'fight') {
  const order = purpose === 'reg' ? ['reg', 'last', 'auto'] : ['last', 'reg', 'auto'];
  for (const k of order) {
    const t = presetTeam(k, st);
    if (t.length) return t;
  }
  return [];
}

// i ばんめの わくに key を 入れる。もう チームに いれば 入れかえ（i が あいている わくなら うしろに つめる）
export function placeInSlot(team, i, key) {
  const t = [...team];
  const j = t.indexOf(key);
  if (j >= 0) {
    if (i >= t.length) {
      t.splice(j, 1);
      t.push(key);
    } else [t[i], t[j]] = [t[j], t[i]];
    return t;
  }
  if (i >= t.length) {
    if (t.length < TEAM_MAX) t.push(key);
  } else t[i] = key;
  return t;
}
export const removeAt = (team, i) => team.filter((_, k) => k !== i);
export function moveUp(team, i) {
  if (i <= 0 || i >= team.length) return [...team];
  const t = [...team];
  [t[i - 1], t[i]] = [t[i], t[i - 1]];
  return t;
}
export const sameTeam = (a, b) => a.length === b.length && a.every((k, i) => k === b[i]);

// ランクの 一覧の 1行（ひらいている・勝った・まだ）
export function rankState(r) {
  if (!r?.open) return 'locked';
  return r.cleared ? 'cleared' : 'open';
}
export const rankName = (r) => r?.name || `ランク${r?.rank ?? ''}`;

// 家族の 登録チーム（自分の ほかで、1ぴき いじょう 登録している 人）
export function familyRows(st, myId) {
  return (st?.family || []).filter((f) => f && f.charId !== myId && Array.isArray(f.reg) && f.reg.length);
}

// チームの 数字（レベルの 平均など）
export function teamStats(keys, monsters) {
  const by = new Map((monsters || []).map((m) => [m.key, m]));
  const list = keys.map((k) => by.get(k)).filter(Boolean);
  const lv = list.length ? Math.round(list.reduce((s, m) => s + num(m.level), 0) / list.length) : 0;
  return { list, n: list.length, avgLv: lv, power: Math.round(list.reduce((s, m) => s + monPower(m), 0)) };
}
export const avgLevel = (reg) => (reg?.length ? Math.round(reg.reduce((s, m) => s + num(m.level), 0) / reg.length) : 0);

