// メニューの「お知らせ」（第35回。shared/data/news.js）
//   一覧（日付・題。まだ 読んでいない 物に ●）と、下に えらんだ 物の 中み。
//   開いた ときに 出ている 物は ぜんぶ 読んだ ことに する（1つずつ 開かなくて よい。● は この 画面の 間は 出した まま）
import { el } from './dom.js';
import { NEWS, newsReadOf, newsDate } from '../../shared/data/news.js';
import './r35-css.js';

// menu: FieldMenu（mkSub・back を 使う）。active: えらべる 画面か（false は 右の 見本）
export function newsView(menu, active) {
  const g = menu.game;
  const read = newsReadOf(g.me);
  const box = el('div', { class: 'items-view news-view' });
  const detail = el('div', { class: 'detail item-detail news-body' });
  const rows = NEWS.map((n) => ({
    html: `<span class="nd">${newsDate(n)}</span>${n.title}`,
    value: n.id,
    cls: `news-row ${read.has(n.id) ? '' : 'unread'}`,
  }));
  if (!active) {
    const fresh = NEWS.filter((n) => !read.has(n.id));
    box.append(el('div', { class: 'muted', text: fresh.length ? `新しいお知らせが${fresh.length}こあります。\n${fresh.slice(0, 3).map((n) => `・${n.title}`).join('\n')}` : 'ゲームの新しいしくみや、アップデートのお知らせを見る。' }));
    return box;
  }
  const show = (it) => {
    const n = NEWS.find((x) => x.id === it?.value);
    detail.innerHTML = '';
    if (n) detail.append(el('div', { class: 'nb-date', text: `${newsDate(n)}　${n.title}` }), el('div', { text: n.text }));
  };
  const m = menu.mkSub({ items: rows, onMove: (it) => show(it), onSelect: (it) => show(it) });
  box.append(m.root, detail);
  // 読んだ ことに する（サーバーに 記録。キャラごと）
  const fresh = NEWS.filter((n) => !read.has(n.id)).map((n) => n.id);
  if (fresh.length) g.net.send({ t: 'menu', action: 'newsRead', ids: fresh });
  return box;
}

js/client/ui/padnav.js:
// 第35回 A: コントローラー（十字キー・A・B）だけで、ボタンが ならんだ 画面を そうさする
//   タイトル・キャラを 作る 画面・引っこしコード など、ListMenu ではない 画面で 使う。
//   十字キー … 画面で その 向きに ある いちばん 近い ボタンへ（見た まま うごく。はじめの 1回は カーソルを 出すだけ）
//   A … そのボタンを おす（文字を 入れる 所は 入力を はじめる。Enter で おわる）
//   B … onB（もどる・とじる）
//
//   const h = padNav(root, { onB, start, sound });  game.input.push(h);  …  game.input.pop(h);
//   h.refresh() … 中みを 作りなおした あと（カーソルの ボタンが なくなったら はじめの ボタンへ）
//   h.focusEl(e) … カーソルを その ボタンへ
import './r35-css.js';

const SEL = 'button:not([disabled]), input:not([disabled]), textarea:not([disabled]), [data-pad]';

// 画面に 見えている ボタン
function targets(root) {
  return [...root.querySelectorAll(SEL)].filter((e) => e.offsetParent !== null && !e.closest('[hidden]') && !e.classList.contains('no-pad'));
}

const center = (r) => ({ x: r.left + r.width / 2, y: r.top + r.height / 2 });

// from から d の 向きに ある いちばん 近い もの（同じ 行・列に ちかい ものを 先に）
export function nearest(from, list, d) {
  const a = center(from);
  let best = null;
  let bestScore = Infinity;
  for (const r of list) {
    if (r === from) continue;
    const b = center(r);
    const dx = b.x - a.x, dy = b.y - a.y;
    const horiz = d === 'left' || d === 'right';
    const main = d === 'left' ? -dx : d === 'right' ? dx : d === 'up' ? -dy : dy;
    // よこの ずれ（上下に うごく とき）・たての ずれ（左右）は、はしと はしの すきま（重なって いれば 0）
    const cross = horiz ? Math.max(0, r.top - from.bottom, from.top - r.bottom) : Math.max(0, r.left - from.right, from.left - r.right);
    if (main <= 2) continue;
    // 左右は 同じ 行（たてに 重なる もの）を 先に。なければ ちかい 行
    const score = horiz ? (cross > 0 ? 1e5 : 0) + main + cross * 4 : main + cross * 2;
    if (score < bestScore) { bestScore = score; best = r; }
  }
  return best;
}

// pad: スマホで 画面の 十字キー（#pad）を 出すか（ボタンを タップする 画面は ふつう 出さない）
export function padNav(root, { onB = null, start = null, sound = null, onFocus = null, pad = false } = {}) {
  let cur = null;
  const mark = (e) => {
    for (const x of root.querySelectorAll('.pad-focus')) x.classList.remove('pad-focus');
    cur = e;
    if (!e) return;
    e.classList.add('pad-focus');
    e.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
    onFocus?.(e);
  };
  const first = () => {
    const list = targets(root);
    const s = typeof start === 'function' ? start() : start;
    return (s && list.includes(s) ? s : null) || list.find((e) => e.classList.contains('sel') || e.classList.contains('primary')) || list[0] || null;
  };
  const h = {
    pad,
    el: root,
    onNav: (a) => {
      if (!root.isConnected) return;
      const list = targets(root);
      if (!cur || !list.includes(cur)) {
        if (a === 'b') return onB?.();
        mark(first());
        if (!cur) return;
        // A は すぐ おす（タイトルの「始める」など）。十字キーは カーソルを 出すだけ
        if (a !== 'a') { sound?.('cursor'); return; }
      }
      if (a === 'b') {
        if (document.activeElement === cur && /^(INPUT|TEXTAREA)$/.test(cur.tagName)) { cur.blur(); return; }
        return onB?.();
      }
      if (a === 'a') {
        if (/^(INPUT|TEXTAREA)$/.test(cur.tagName)) {
          cur.focus();
          return;
        }
        cur.click();
        // おした あと 画面が かわったら、つぎの ボタンへ
        if (!cur.isConnected) mark(null);
        return;
      }
      if (!['up', 'down', 'left', 'right'].includes(a)) return;
      if (document.activeElement === cur) cur.blur?.();
      const rects = list.map((e) => e.getBoundingClientRect());
      const from = cur.getBoundingClientRect();
      const r = nearest(from, rects, a);
      if (!r) return;
      sound?.('cursor');
      mark(list[rects.indexOf(r)]);
    },
    refresh() {
      if (cur && !targets(root).includes(cur)) mark(first());
    },
    focusEl(e) { mark(e); },
    get current() { return cur; },
  };
  // 1行の 文字の 入力は Enter で おわる（Input は 文字の 入力中の キーを 見ないので、そのあと 十字キーで うごける）
  for (const inp of root.querySelectorAll('input')) {
    inp.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' || e.isComposing) return;
      e.preventDefault();
      // 下の Input に とどくと、もう一度 A（入力の はじめ）に なる
      e.stopPropagation();
      inp.blur();
      mark(inp);
    });
  }
  return h;
}

js/client/ui/paper-pop.js:
// 第76回: お仕事いらい板の はり紙を 大きな まど 1まいで 見せる（家族の ねがい: もっと 大きく、見やすく わかりやすく）
//   中み（p）は shared/data/sidequests-family.js の boardPaper:
//     { name, paper, town, where, who, job, jobs: [系統の 職業の 名前], has, pro, rewards: [{ kind, id, name, n }], gold, medals, state, ask }
//   下の 大きな ボタン（うける／やめる など）で えらぶ。キーボード・ゲームパッド（左右・上下・決定・もどる）・タッチで うごく。
//   見ている だけの 人（spectator）は 少しの 間 はり紙を 見せて とじる
import { el, ListMenu, esc } from './dom.js';
import { rareNameHtml } from './rarity.js';
import { ITEMS } from '../../shared/data/items.js';

const KIND_NAMES = { acc: 'アクセサリー', vehicle: '乗り物', goods: '道具・素材' };
const KIND_ICONS = { acc: '◆', vehicle: '▶', goods: '●' };

function section(cls, title, ...kids) {
  return el('section', { class: `pp-sec ${cls}` }, el('h3', { class: 'pp-h', text: title }), ...kids);
}

export function paperBody(p) {
  const top = el('div', { class: 'pp-top' },
    el('span', { class: 'pp-kind', text: 'お仕事いらい' }),
    p.town ? el('span', { class: 'pp-town', text: p.town }) : null,
    p.state ? el('span', { class: `pp-state ${p.state}`, text: p.state === 'done' ? 'すんだ' : '受けている' }) : null);
  const title = el('h2', { class: 'pp-title', text: `「${p.name}」` });
  const ask = el('div', { class: 'pp-paper', text: p.paper || '' });
  const where = section('pp-where', '会う人・場所',
    el('div', { class: 'pp-who', text: p.who || '' }),
    el('div', { class: 'pp-place', text: p.where || '' }));
  const has = el('span', { class: `pp-has ${p.has ? 'yes' : 'no'}`, text: p.has ? `○いる${p.pro ? `（${p.pro}）` : ''}` : '×いない' });
  const jobs = section('pp-job', '解決できそうな職業',
    el('div', { class: 'pp-jobline' }, el('span', { class: 'pp-jobname', text: `${p.job}の系統` }), has),
    el('div', { class: 'pp-chips' }, ...(p.jobs || []).map((n) => el('span', { class: 'pp-chip', text: n }))),
    el('div', { class: 'pp-note', text: p.has ? 'この職業の人が、パーティーにいる。だいじょうぶ！' : 'この職業の人が、パーティーにひとりいればだいじょうぶ（酒場の仲間や、家族の仲間でもいいよ）' }));
  const rows = (p.rewards || []).map((r) => {
    const name = r.kind === 'vehicle' || !ITEMS[r.id] ? esc(r.name) : rareNameHtml(r.id, r.name);
    return el('li', { class: `pp-rw ${r.kind}` },
      el('span', { class: `pp-ic ${r.kind}`, text: KIND_ICONS[r.kind] || '●' }),
      el('span', { class: 'pp-rn', html: `${name}${r.n > 1 ? `<span class="pp-n">×${r.n}</span>` : ''}` }),
      el('span', { class: 'pp-rk', text: KIND_NAMES[r.kind] || '' }));
  });
  rows.push(el('li', { class: 'pp-rw gold' }, el('span', { class: 'pp-ic gold', text: 'G' }), el('span', { class: 'pp-rn', text: `${p.gold}ゴールド` }), el('span', { class: 'pp-rk', text: '' })));
  rows.push(el('li', { class: 'pp-rw medal' }, el('span', { class: 'pp-ic medal', text: '★' }), el('span', { class: 'pp-rn', text: `小さなメダル${p.medals}まい` }), el('span', { class: 'pp-rk', text: '' })));
  const reward = section('pp-reward', 'ごほうび', el('ul', { class: 'pp-rws' }, ...rows));
  const body = el('div', { class: 'pp-body' }, section('pp-ask', 'たのみごと', ask), where, jobs, reward);
  // たて画面: 職業の 系統（○いる／×いない）を 題の 下にも（くわしい 一らんは 下の ほう。CSS で たて画面だけ 出す）
  const need = el('div', { class: 'pp-need' }, el('span', { class: 'pp-jobname', text: `必要な職業：${p.job}の系統` }), el('span', { class: `pp-has ${p.has ? 'yes' : 'no'}`, text: has.textContent }));
  return el('div', { class: 'pp-paperwrap' }, top, title, need, body);
}

// sp … ScriptPlayer・options … ボタンの 名前・かえす もの: えらんだ ばんごう
export function paperPop(sp, p, options, spectator, who) {
  const g = sp.game;
  return new Promise((resolve) => {
    const box = el('div', { class: `win paper-pop${spectator ? ' watch' : ''}` });
    box.append(paperBody(p));
    document.body.classList.add('big-choice');
    let menu = null;
    let timer = null;
    const finish = (v) => {
      clearTimeout(timer);
      menu?.blur();
      g.input.pop(watchH);
      box.remove();
      document.body.classList.remove('big-choice');
      if (sp.popClose === close) sp.popClose = null;
      resolve(v);
    };
    const close = () => finish(0);
    sp.popClose = close;
    // 見ている だけ: 「〜が読んでいます」。決定・もどる か 少し たつと とじる
    const watchH = { onNav: (a) => { if (a === 'a' || a === 'b') finish(0); } };
    if (spectator) {
      box.append(el('div', { class: 'pp-q muted', text: `（${who || '仲間'}が、はり紙を読んでいます…）` }));
      document.getElementById('ui').append(box);
      g.input.push(watchH);
      timer = setTimeout(() => finish(0), 6000);
      return;
    }
    const q = el('div', { class: 'pp-q', text: p.ask || '' });
    const last = options.length - 1;
    menu = new ListMenu(g.input, {
      items: options.map((o, i) => ({ label: o, value: i, cls: `pp-btn${i === 0 && options.length > 1 ? ' main' : ''}` })),
      cols: options.length > 1 ? 2 : 1,
      // 受けている はり紙は「つづける」に カーソル（まちがえて やめない ように）
      start: p.state === 'taken' ? last : -1,
      className: 'pp-btns',
      sound: (s) => g.audio.sfx(s),
      back: null,
      onSelect: (it) => finish(it.value),
      onCancel: () => { g.audio.sfx('cancel'); finish(last); },
    });
    box.append(el('div', { class: 'pp-foot' }, q, menu.root));
    document.getElementById('ui').append(box);
    menu.focus();
  });
}

