.tabs.lv-tabs .btn.sel { color: var(--accent); border-color: var(--accent); background: rgba(255, 214, 107, 0.14); }
.menu.fav-grid .item .favmk { color: var(--accent); margin-right: 0.1em; }
.menu.fav-grid .item.dis { opacity: 0.55; }
