/* 下にはりつくせつめい（覚えた技・お気に入り）の高さぶん、カーソルの技を上に出す（--sk-info-h は client/ui/menu.js の stickInfo がはかる） */
.skills-view.sticky-info .menu.fav-grid .item { scroll-margin-bottom: var(--sk-info-h, 8.5em); }
