// 美容室（ドラクエ風の カウンター）
//   「どんなご用でしょう？」→ かみがた／かみの色／目もと／はだの色 を えらぶ（みぎに 大きな みほん。くるくる 回る）
//   → 決める →「〇〇ゴールドになりますが、よろしいですか？」はい／いいえ → サーバーで たしかめて 変わる
import { el, esc } from './dom.js';
import { Counter } from './counter.js';
import { request } from './shop.js';
import { boardIconURL } from '../render/boards.js';
import { previewCache } from '../render/hero.js';
import { HAIR_STYLES, HAIR_COLORS, FACES, SKIN_TONES, SALON_FEE, lookIds, STYLE_BY_ID, HCOL_BY_ID, FACE_BY_ID, TONE_BY_ID } from '../../shared/data/looks.js';
import { shownEquip } from '../../shared/look-equip.js';

const DIRS = ['down', 'left', 'up', 'right'];
const PARTS = [
  { key: 'style', label: 'かみがた', ask: 'どのかみがたにしますか？', list: HAIR_STYLES, by: STYLE_BY_ID },
  { key: 'hcol', label: 'かみの色', ask: 'どの色にしますか？', list: HAIR_COLORS, by: HCOL_BY_ID },
  { key: 'face', label: '目もと', ask: 'どんな目もとにしますか？', list: FACES, by: FACE_BY_ID },
  { key: 'tone', label: 'はだの色', ask: 'はだの色は、どうしますか？', list: SKIN_TONES, by: TONE_BY_ID },
];
const nameOf = (part, id) => part.by.get(id)?.name || '';

// みほん（大きな え。くるくる 回る）
function previewBox(game) {
  const big = el('canvas', { class: 'salon-big', width: 128, height: 168 });
  const now = el('canvas', { class: 'salon-now', width: 128, height: 168 });
  const label = el('div', { class: 'salon-names' });
  const note = el('div', { class: 'small muted salon-note', text: 'かぶとは外して見せています。' });
  const fee = el('div', { class: 'small gold' });
  const box = el('div', { class: 'salon-info' },
    el('div', { class: 'salon-pv' },
      el('div', { class: 'salon-col' }, el('div', { class: 'small muted', text: 'いま' }), now),
      el('div', { class: 'salon-col main' }, el('div', { class: 'small gold', text: '変えたあと' }), big)),
    label, fee, note);
  const cache = previewCache(24);
  const sprite = (look, dir, f) => {
    const me = game.me;
    const eq = me.equip ? { ...shownEquip(me), head: null } : undefined;
    return cache(look, me.job, eq, dir, f, 8);
  };
  let t = 0;
  const S = { draft: null, current: null };
  const draw = () => {
    if (!S.draft) return;
    const dir = DIRS[Math.floor(t / 4) % 4], f = t % 2;
    for (const [cv, look] of [[big, S.draft], [now, S.current]]) {
      const x = cv.getContext('2d');
      x.clearRect(0, 0, cv.width, cv.height);
      x.imageSmoothingEnabled = false;
      x.drawImage(sprite(look, cv === big ? dir : 'down', f), 0, 0);
    }
  };
  const timer = setInterval(() => { t++; draw(); }, 320);
  return {
    box,
    set(draft, current) {
      S.draft = draft;
      S.current = current;
      const ids = lookIds(draft);
      label.innerHTML = PARTS.map((p) => `<div><span class="muted">${esc(p.label)}</span>　${esc(nameOf(p, ids[p.key]))}</div>`).join('');
      fee.textContent = `代金 ${SALON_FEE}G`;
      draw();
    },
    stop() { clearInterval(timer); },
  };
}

// いまの look に えらんだ ものを かさねる（みほん だけ。きめるのは サーバー）
function withPart(look, key, id) {
  return { ...look, [key]: id };
}

export async function salonUI(game, data) {
  const ct = new Counter(game, { title: '美容室', keeper: data.keeper || '美容師', icon: boardIconURL('salon'), cls: 'salon-panel' });
  const pv = previewBox(game);
  ct.hook(() => pv.stop());
  const current = () => ({ ...(game.me.look || {}), ...lookIds(game.me.look) });
  let draft = current();
  const show = () => { pv.set(draft, current()); ct.info(pv.box); };
  show();
  let line = data.hello || 'いらっしゃいませ！\nかみがたや、かみの色を変えてみませんか？';
  let last = 0;
  while (!ct.closed) {
    await ct.say(line);
    show();
    const changed = ['style', 'hcol', 'face', 'tone'].some((k) => lookIds(draft)[k] !== lookIds(game.me.look)[k]);
    const items = [
      ...PARTS.map((p) => ({ label: p.label, value: p.key, right: nameOf(p, lookIds(draft)[p.key]), rightCls: 'muted' })),
      { label: changed ? 'これで決める' : 'これで決める（変わっていない）', value: 'ok', right: changed ? `${SALON_FEE}G` : '', rightCls: 'gold', disabled: !changed },
      { label: 'やめる', value: 'exit' },
    ];
    const cmd = await ct.pick(items, { back: null, start: last });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    last = items.findIndex((x) => x.value === cmd.value);
    if (cmd.value === 'ok') {
      const ids = lookIds(draft);
      if ((game.me.gold || 0) < SALON_FEE) {
        await ct.say('おや？ゴールドが足りないようですね。');
        await ct.tap(1800);
        line = 'ほかにも何かご用はありますか？';
        continue;
      }
      const yes = await ct.ask(`かみがたは「${nameOf(PARTS[0], ids.style)}」、かみの色は「${nameOf(PARTS[1], ids.hcol)}」ですね。\n${SALON_FEE}ゴールドになりますが、よろしいですか？`);
      if (ct.closed) return;
      if (yes !== 0) { line = 'ほかにも何かご用はありますか？'; continue; }
      const res = await request(game, { kind: 'salon', look: { style: ids.style, hcol: ids.hcol, face: ids.face, tone: ids.tone } });
      ct.updGold();
      if (!res.ok) {
        await ct.say(res.text || 'おや？何かおかしいようですね。');
        await ct.tap(1800);
        line = 'ほかにも何かご用はありますか？';
        continue;
      }
      game.audio.sfx('buff');
      // サーバーの look を そのまま つかう（とどくまで まつ）
      if (res.look) game.me.look = res.look;
      draft = current();
      show();
      await ct.say(res.text || 'はい、できあがり！');
      await ct.tap(2400);
      line = 'ほかにも何かご用はありますか？';
      continue;
    }
    // えらぶ（うごかすと みほんが かわる）
    const part = PARTS.find((p) => p.key === cmd.value);
    await ct.say(part.ask);
    const before = draft;
    const curId = lookIds(draft)[part.key];
    const rows = part.list.map((x) => ({
      value: x.id,
      label: x.name,
      html: x.hex ? `<span class="salon-sw" style="background:${x.hex}"></span>${esc(x.name)}` : esc(x.name),
      right: x.id === lookIds(game.me.look)[part.key] ? 'いま' : '',
      rightCls: 'muted',
    }));
    const pick = await ct.pick(rows, {
      start: Math.max(0, rows.findIndex((r) => r.value === curId)),
      onMove: (it) => { if (it) { draft = withPart(before, part.key, it.value); show(); } },
    });
    if (ct.closed) return;
    draft = pick ? withPart(before, part.key, pick.value) : before;
    show();
    line = pick ? 'いかがでしょう？\nほかに変えたいところはありますか？' : 'ほかに変えたいところはありますか？';
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(null);
  await ct.say('またのおこしをお待ちしております。');
  await ct.tap(1400);
  ct.close();
}

js/client/ui/script.js:
// だいほんの さいせい（メッセージ・えらぶ・えんしゅつ）
import { el } from './dom.js';
import { paintRare } from './rarity.js';
import { ListMenu } from './dom.js';
import { openServiceUI } from './services.js';
import { monsterCanvas } from '../render/monsters.js';
import { npcSprite } from '../field.js';
import { reportError } from '../errlog.js';
// 第76回: お仕事いらい板の 大きな はり紙
import { paperPop } from './paper-pop.js';
// 第6章: 時の砂時計の 砂の うず
import { timeShiftFx, clearTimeShift } from '../time-shift.js';

const TYPE_MS = 28;

export class ScriptPlayer {
  constructor(game) {
    this.game = game;
    this.queue = [];
    this.running = false;
    this.gen = 0;
  }

  enqueue(msg) {
    this.queue.push(msg);
    if (!this.running) this.run();
  }

  async run() {
    const gen = this.gen;
    this.running = true;
    this.game.busy = true;
    try {
      while (this.queue.length) {
        const msg = this.queue.shift();
        let choice;
        for (const step of msg.steps) {
          let r;
          try {
            r = await this.step(step, msg);
          } catch (e) {
            // 1つの えんしゅつが こわれても とまらない（「だいほん中」の まま うごけなく ならない ように つぎへ）
            reportError(this.game, e, `script:${step?.[0]}`);
            this.closeDialog();
          }
          if (gen !== this.gen) return; // とちゅうで リセットされた
          if (step[0] === 'choice') choice = r;
        }
        if (!msg.spectator) this.game.net.send({ t: 'ack', runId: msg.runId, choice });
      }
    } finally {
      if (gen === this.gen) {
        this.running = false;
        this.closeDialog();
        if (this.game.scriptEnded) this.game.endScript();
      }
    }
  }

  // つなぎなおした ときなど: いま とちゅうの だいほんを すてる
  reset() {
    this.gen += 1;
    this.rolling = false;
    document.querySelectorAll('#fx .roll').forEach((x) => x.remove());
    clearTimeShift();
    // 第76回: とちゅうの はり紙の 大きな まど
    this.popClose?.();
    this.queue = [];
    this.running = false;
    this.advance = null;
    this.closeDialog();
  }

  fill(text, msg) {
    return String(text).replaceAll('{name}', msg.who || this.game.me?.name || '');
  }

  async step(st, msg) {
    const g = this.game;
    const [op, ...a] = st;
    switch (op) {
      case 'say': return this.say(a[0] ? this.fill(a[0], msg) : null, this.fill(a[1], msg), msg.spectator);
      case 'choice':
        // 第76回: お仕事いらい板の はり紙は 大きな まど（client/ui/paper-pop.js）
        if (a[3] && typeof a[3] === 'object') return paperPop(this, a[3], a[1], msg.spectator, msg.who);
        return this.choice(this.fill(a[0], msg), a[1], msg.spectator, msg.who, a[2]);
      case 'fade': return g.fade(a[0] === 'out');
      case 'flash': return g.flash();
      case 'shake':
        g.field.shakeT = 700;
        g.audio.sfx('rumble');
        return wait(500);
      case 'night':
        g.field.nightOverride = a[0] ? true : null;
        return null;
      case 'clock':
        // 宿屋で ねている あいだに 時間が すすんだ（sky.js）
        g.sky?.scriptClock(a[0]);
        return null;
      case 'bgm':
        if (a[0] === null) g.audio.stop(0.4);
        else if (a[0] === 'resume') g.audio.play(g.field.areaBgm());
        else g.audio.play(a[0]);
        g.scriptBgm = a[0];
        return null;
      case 'sfx':
        g.audio.sfx(a[0]);
        return null;
      case 'wait': return wait(a[0]);
      case 'actor':
        g.field.spawnActor(a[0], a[1]);
        return null;
      case 'move':
        return g.field.moveActor(a[0], a[1]);
      case 'face':
        g.field.faceActor(a[0], a[1]);
        return null;
      case 'remove':
        g.field.removeActor(a[0]);
        return null;
      case 'chapter': return this.chapter(a[0], a[1]);
      // 第5章 Step 9: エンディングの ふりかえり（スタッフロールふう）と「第1部 完」
      case 'roll': return this.roll(a[0] || {}, msg);
      // 第6章: 時の砂時計で 時代を 切りかえる（client/time-shift.js）
      case 'timeShift': return timeShiftFx(g, a[0], a[1], a[2]);
      case 'teleport': {
        g.field.lookAt = null;
        const mine = (a[4] || []).find((e) => e[0] === g.sid);
        if (mine) g.applyPos(a[0], mine[1], mine[2], a[3], mine[3]);
        return null;
      }
      case 'objective':
        // 見ている なかまは 自分の 目標は そのまま（リーダーの 目標として 出す）
        if (msg.spectator) {
          if (g.party) g.party.objective = a[0];
          g.refreshObjective();
        } else g.setObjective(a[0]);
        return null;
      case 'guestHide':
        g.field.hideGuests = !!a[0];
        return null;
      case 'hideNpc':
        // ['hideNpc', id, false] … もう一度 見せる（イベントの さいごに、役者から 本物の NPC に もどす）
        if (a[1] === false) g.field.scriptHidden.delete(a[0]);
        else g.field.scriptHidden.add(a[0]);
        return null;
      case 'chestOpen':
        return null;
      case 'showMon':
        this.showMon(a[0]);
        return null;
      case 'crest':
        return this.crest();
      case 'ui':
        if (msg.spectator) return null;
        this.closeDialog();
        return openServiceUI(g, a[0], a[1]);
      // 第3章: トロッコに のる（[[x, y], ...]）・自分を かくす・天気を かえる（null で もとに もどす）
      case 'ride':
        this.closeDialog();
        g.audio.sfx('train');
        return g.field.ride(a[0], a[1]);
      case 'hideMe':
        g.field.hideMe = !!a[0];
        return null;
      case 'weather':
        g.field.weatherOverride = a[0] === undefined ? null : a[0];
        return null;
      // カメラを その 場所へ ゆっくり 向ける（大きな 竜が 画面に 入るように）。['look'] で 自分に もどす
      case 'look':
        g.field.lookAt = a.length >= 2 ? { x: a[0], y: a[1] } : null;
        return wait(a.length >= 2 ? 650 : 250);
      default:
        return null;
    }
  }

  // ───── メッセージ ─────
  ensureDialog() {
    if (!this.dlg) {
      this.dlg = el('div', { class: 'win dialog', role: 'dialog', 'aria-live': 'polite' });
      this.dlgSpeaker = el('div', { class: 'speaker' });
      this.dlgText = el('div', { class: 'text' });
      this.dlgMore = el('div', { class: 'more', text: '▼' });
      this.dlg.append(this.dlgSpeaker, this.dlgText, this.dlgMore);
      this.dlg.addEventListener('click', () => this.advance?.());
      // がめんの どこを タップしても すすむ（スマホで ゆびが とどきやすいように）
      this.catcher = el('div', { class: 'talk-catcher', onclick: () => this.advance?.() });
      document.getElementById('ui').append(this.catcher, this.dlg);
      document.body.classList.add('talking');
    }
    return this.dlg;
  }

  // なかまに なりたそうな モンスター（'npc:<みため>' … 人の すがた。水がめに うつる 女王 など）
  showMon(sp) {
    this.monBox?.remove();
    this.monBox = null;
    if (!sp) return;
    const src = sp.startsWith('npc:') ? npcSprite(sp.slice(4), 'down', 0) : monsterCanvas(sp, 0);
    if (!src) return;
    const c = document.createElement('canvas');
    c.width = src.width;
    c.height = src.height;
    c.getContext('2d').drawImage(src, 0, 0);
    // こまかい え（res 4）も 見た目の 大きさで
    const r = src.res || 1, w = src.width / r, h = src.height / r;
    const k = Math.max(2, Math.min(5, Math.floor(160 / Math.max(w, h))));
    c.style.width = `${w * k}px`;
    c.style.height = `${h * k}px`;
    this.monBox = el('div', { class: 'win mon-pop' }, c);
    document.getElementById('ui').append(this.monBox);
  }

  // 紋章が ひかる
  crest() {
    const fx = document.getElementById('fx');
    const cv = document.createElement('canvas');
    cv.width = 64;
    cv.height = 64;
    const x = cv.getContext('2d');
    x.imageSmoothingEnabled = false;
    const star = (r1, r2, col) => {
      x.fillStyle = col;
      x.beginPath();
      for (let i = 0; i < 10; i++) {
        const r = i % 2 ? r2 : r1;
        const a = -Math.PI / 2 + i * Math.PI / 5;
        x.lineTo(32 + Math.cos(a) * r, 32 + Math.sin(a) * r);
      }
      x.closePath();
      x.fill();
    };
    x.strokeStyle = '#ffd66b';
    x.lineWidth = 3;
    x.beginPath(); x.arc(32, 32, 27, 0, Math.PI * 2); x.stroke();
    x.strokeStyle = '#fff6d0';
    x.lineWidth = 1;
    x.beginPath(); x.arc(32, 32, 23, 0, Math.PI * 2); x.stroke();
    star(20, 8, '#ffd66b');
    star(12, 5, '#ffffff');
    const box = el('div', { class: 'crest-fx' }, cv);
    fx.append(box);
    return new Promise((resolve) => setTimeout(() => { box.remove(); resolve(); }, 1800));
  }

  closeDialog() {
    this.monBox?.remove();
    this.monBox = null;
    this.dlg?.remove();
    this.catcher?.remove();
    this.dlg = null;
    this.catcher = null;
    document.body.classList.remove('talking');
  }

  say(speaker, text, spectator) {
    const g = this.game;
    const d = this.ensureDialog();
    d.classList.toggle('spectator', !!spectator);
    this.dlgSpeaker.hidden = !speaker;
    this.dlgSpeaker.textContent = speaker || '';
    this.dlgText.textContent = '';
    this.dlgMore.hidden = true;
    return new Promise((resolve) => {
      let i = 0;
      let done = false;
      const chars = [...text];
      let timer = null;
      const finishType = () => {
        clearInterval(timer);
        paintRare(this.dlgText, text); // レア装備の 名前に 色と ★（ui/rarity.js）
        done = true;
        this.dlgMore.hidden = false;
        if (spectator) autoTimer = setTimeout(close, 1200 + chars.length * 45);
      };
      const close = () => {
        clearTimeout(autoTimer);
        g.input.pop(h);
        this.advance = null;
        resolve();
      };
      let autoTimer = null;
      this.advance = () => {
        if (!done) finishType();
        else {
          g.audio.sfx('cursor');
          close();
        }
      };
      const h = { onNav: (act) => { if (act === 'a' || act === 'b') this.advance(); } };
      g.input.push(h);
      timer = setInterval(() => {
        i += 1;
        paintRare(this.dlgText, chars.slice(0, i).join(''));
        // 第77回 C: 話す 人ごとに 高さの ちがう 文字の 音（名前の ない 地の 文は 今まで どおり）
        if (i % 3 === 0 && chars[i - 1] !== ' ') {
          if (speaker) g.audio.blip(speaker);
          else g.audio.sfx('talk');
        }
        if (i >= chars.length) finishType();
      }, TYPE_MS);
    });
  }

  // info … えらぶ 物ごとの せつめい（第65回 お仕事いらい板: カーソルを 合わせた はり紙の 職業・ごほうび）。
  //   第76回: せつめいの ある ときは 画面を 大きく 使う まど（よこ画面は 右・たて画面は 下に せつめい）
  choice(question, options, spectator, who, info = null) {
    const g = this.game;
    if (spectator) {
      return this.say(null, `（${who}が選んでいます…）\n${question}`, true).then(() => 0);
    }
    return new Promise((resolve) => {
      const hasInfo = Array.isArray(info) && info.some(Boolean);
      const box = el('div', { class: `win choice${hasInfo ? ' has-info' : ''}` });
      if (question) box.append(el('div', { class: 'q', text: question }));
      const infoBox = hasInfo ? el('div', { class: 'choice-info' }) : null;
      const showInfo = (i) => {
        if (!infoBox) return;
        const t = String(info[i] || '');
        infoBox.textContent = t;
        infoBox.classList.toggle('empty', !t);
      };
      const menu = new ListMenu(g.input, {
        items: options.map((o, i) => ({ label: o, value: i })),
        sound: (s) => g.audio.sfx(s),
        back: null,
        onSelect: (it) => finish(it.value),
        onCancel: () => finish(options.length - 1),
        onMove: (it, i) => showInfo(it?.value ?? i),
      });
      box.append(menu.root);
      if (infoBox) { box.append(infoBox); showInfo(menu.idx || 0); }
      document.getElementById('ui').append(box);
      // 第76回: せつめいの ある えらぶ まど（お仕事いらい板の 一らん）は 画面を 大きく 使う（下の メッセージは かくす）
      if (hasInfo) document.body.classList.add('big-choice');
      menu.focus();
      const finish = (v) => {
        menu.blur();
        box.remove();
        if (hasInfo) document.body.classList.remove('big-choice');
        resolve(v);
      };
    });
  }

  chapter(title, sub) {
    const g = this.game;
    this.closeDialog();
    g.audio.play('chapter');
    const fx = document.getElementById('fx');
    const card = el('div', { class: 'chapter' }, el('div', { class: 'c1', text: title }), el('div', { class: 'c2', text: sub }));
    fx.append(card);
    return new Promise((resolve) => setTimeout(() => { card.remove(); resolve(); }, 4200));
  }
}

// ───── エンディングの ふりかえり（第5章 Step 9。data/story-castle-top.js の PART1_ROLL）─────
// lines: [['h', 見出し] | ['t', 文] | ['s']]。星空の 上を 下から 上へ ゆっくり ながれる。
// タップ（決定）で 3ばいの はやさ。さいごに end（「第1部 完」）と sub を 出して おわる
const ROLL_PX_PER_S = 34;
ScriptPlayer.prototype.roll = function roll(o, msg) {
  const g = this.game;
  this.closeDialog();
  const fx = document.getElementById('fx');
  const box = el('div', { class: 'roll' });
  const sky = el('div', { class: 'roll-sky' });
  for (let i = 0; i < 46; i++) {
    const st = el('i', { class: 'roll-star' });
    st.style.left = `${(i * 37) % 100}%`;
    st.style.top = `${(i * 53) % 100}%`;
    st.style.animationDelay = `${(i % 7) * 0.4}s`;
    sky.append(st);
  }
  const col = el('div', { class: 'roll-col' });
  for (const [kind, text] of o.lines || []) {
    if (kind === 's') col.append(el('div', { class: 'roll-gap' }));
    else col.append(el('div', { class: kind === 'h' ? 'roll-h' : 'roll-t', text: this.fill(text || '', msg) }));
  }
  const end = el('div', { class: 'roll-end' }, el('div', { class: 'e1', text: this.fill(o.end || '', msg) }), el('div', { class: 'e2', text: this.fill(o.sub || '', msg) }));
  box.append(sky, col, end);
  fx.append(box);
  let speed = 1;
  const fast = () => { speed = 3; };
  box.addEventListener('click', fast);
  const h = { onNav: (act) => { if (act === 'a' || act === 'b') fast(); } };
  g.input.push(h);
  this.rolling = true;
  return new Promise((resolve) => {
    let y = box.clientHeight || 600;
    let last = performance.now();
    const stop = col.offsetHeight || 1200;
    col.style.transform = `translateY(${Math.round(y)}px)`;
    const tick = (now) => {
      // つなぎなおし などで すてられた（reset）
      if (!box.isConnected) { g.input.pop(h); resolve(); return; }
      // コマが おそい 端末でも 時計で すすむ（かくれていた 時の 大きな とびだけ おさえる）
      const dt = Math.min(0.5, Math.max(0, (now - last) / 1000));
      last = now;
      y -= ROLL_PX_PER_S * speed * dt;
      col.style.transform = `translateY(${Math.round(y)}px)`;
      if (y > -stop) { requestAnimationFrame(tick); return; }
      col.remove();
      end.classList.add('show');
      setTimeout(() => {
        box.classList.add('out');
        setTimeout(() => { g.input.pop(h); box.remove(); this.rolling = false; resolve(); }, 1200);
      }, speed > 1 ? 2600 : 4200);
    };
    requestAnimationFrame(tick);
  });
};

export function wait(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

