      }
      main.append(el('div', { class: 'detail', text: e.desc || '' }));
      if (e.sec === 'roster' && e.inParty && !e.active) main.append(el('div', { class: 'detail', text: '今はパーティーの人数がいっぱいなので待っている。' }));
      if (e.inWagon) main.append(el('div', { class: 'detail', text: e.family ? '馬車に乗っている。本人にも経験値のおすそわけが少し届く。' : '馬車に乗っている。戦いに出なくても、戦った仲間と同じ経験値をもらえる（洞窟や塔の中では半分）。' }));
      if (e.here) main.append(el('div', { class: 'detail', text: '今は本人がいっしょに遊んでいるので、うつしは待っている。' }));
    };
    const menu = new ListMenu(game.input, {
      items: items(),
      sound: sfx,
      onMove: (it) => show(it?.value),
      onSelect: (it) => act(it.value),
      back: null,
      onCancel: () => back(),
    });
    const refresh = (r) => {
      if (r?.tavern) {
        info = r.tavern;
        entries = byKey();
      }
      menu.setItems(items());
      s.right.textContent = partyText();
      show(menu.current?.value);
    };
    // 画面を かえる（入口に もどる ときは 前に えらんだ 行に）
    const setView = (v) => {
      if (view === 'top') topIdx = menu.idx;
      view = v;
      if (v !== 'breed') parentA = null;
      titleEl.textContent = TITLES[v];
      menu.back = v === 'top' ? null : 'もどる';
      menu.setItems(items(), false);
      if (v === 'top' && topIdx >= 0 && topIdx < menu.items.length) {
        menu.idx = topIdx;
        menu.render();
      }
      side.scrollTop = 0;
      show(menu.current?.value);
    };
    // 第70回: カーソルを その 行へ（なければ そのまま）
    const putCursor = (pred) => {
      const i = menu.items.findIndex((it) => !it.header && !it.disabled && pred(it));
      if (i >= 0) {
        menu.idx = i;
        menu.render();
      }
      show(menu.current?.value);
    };
    // 第70回: 作れる 魔物（サーバーの world/breed.js の breedFinder。みるだけ）
    const askFinder = (child = null) => request(game, { kind: 'tavern', action: 'breedFinder', child, low: findLow, room: !!room });
    const openFinder = async (at = null, row = null) => {
      menu.blur();
      const r = await askFinder();
      if (shut) return;
      menu.focus();
      if (!r.ok || !r.finder) {
        toast(r.text || '調べられなかった');
        return;
      }
      finder = r.finder;
      finderKid = null;
      setView('find');
      // カーソルは 前の 行 → 前に えらんだ 子 → いちばん 上の 子
      if (row) putCursor((it) => it.value === row);
      else if (at && finder.kids.some((k) => k.sp === at)) putCursor((it) => it.value === `kid:${at}`);
      else putCursor((it) => String(it.value).startsWith('kid:'));
