    const back = () => {
      // 第70回: 親の 組 → 作れる 魔物の 一覧（えらんでいた 子に）→ 配合の 画面（「作れる魔物から選ぶ」に）
      if (view === 'findKid') {
        finderKid = null;
        setView('find');
