          desc.textContent = id ? ABILITIES[id]?.desc || '' : it?.value?.startsWith?.('#auto:') ? `${pv.names?.[it.value.slice(6)] || ''}の強い技から${pv.max}つ選ぶ` : '';
        },
        onSelect: (it) => {
