    const breedPreviewBox = (top, A0, B0, pick = null) => {
      const { o, f } = pairInfo(A0, B0, pick);
      const img = childImg(o.child, o.unseen, { class: 'breed-pv-img' });
      top.append(img, el('div', { class: 'breed-pv-txt' },
        // 「（ランクB）＋3」は 行の とちゅうで わかれない ように
        el('div', { class: 'small gold' }, `生まれる子: ${childLabel(o)}`,
          el('span', { style: { whiteSpace: 'nowrap' }, text: `（ランク${o.rank}）＋${o.plus}` })),
        el('div', { class: `small ${TREND_CLS[f.trend]}`, text: `${trendText(f)}（生まれた時 HP${f.born.maxHp} 力${f.born.str}）` }),
        o.unseen ? el('div', { class: 'small good', text: '★ まだ見たことがない魔物！' })
          : o.firstFriend ? el('div', { class: 'small good', text: '★ 初めて仲間になる！' }) : null,
        KIND_TEXT[o.kind] ? el('div', { class: 'small good', text: `${KIND_TEXT[o.kind]}${o.item ? `（${ITEMS[o.item]?.name || ''}を使う）` : ''}` }) : null,
        o.count > 1 && !pick ? el('div', { class: 'small muted', text: `生まれる子は${o.count}種から選べる` }) : null));
    };
    // 子を えらぶ（候補が 2つ いじょう）。見たことが ない 子は かげと NEW。↓は 親より 弱く なるかも
    const faceCache = new Map();
    const childFace = (sp, hidden) => {
      if (!hidden) return faceURL({ mon: sp });
      if (!faceCache.has(sp)) {
        let u = '';
        try { u = childImg(sp, true, {}).toDataURL(); } catch { u = ''; }
        faceCache.set(sp, u);
      }
      return faceCache.get(sp);
    };
    // 第71回: さがし表の 絵（shared/breed-finder.js の kidArt・parentArt → 絵の URL。おなじ 絵は 1回だけ つくる）
    const artFace = (a) => (a ? childFace(a.mon, a.hidden) : '');
    const pickChild = (pv) => {
      const note = el('div', { class: 'small good', style: { minHeight: '1.3em' } });
      const say = (ch) => { note.textContent = ch ? `${KIND_TEXT[ch.kind] || ''}${ch.item ? `（${ITEMS[ch.item]?.name || ''}がなくなる）` : ''}` : ''; };
      say(pv.choices[0]);
      return choose(game, `生まれる子を選んでね（${pv.choices.length}種）\n↓…親より弱くなるかも　ランク↓…ランクが1つ下`, [
        ...pv.choices.map((ch) => ({
          face: childFace(ch.sp, ch.unseen), value: ch.sp,
          html: `${ch.unseen ? '？？？' : esc(MONSTERS[ch.sp]?.name || '')} <span class="muted small">ランク${ch.rank} ＋${ch.plus}</span>${ch.unseen ? '<span class="tag good">NEW</span>' : ''}${ch.low ? '<span class="tag warn">ランク↓</span>' : ''}`,
          right: TREND_MARK[ch.trend], rightCls: TREND_CLS[ch.trend],
        })),
        { label: 'やめる', value: null },
      ], { top: note, onMove: (it) => say(pv.choices.find((x) => x.sp === it?.value)) });
    };
    // 2ひきを きめた あと: 受けつぐ 技 → 名前 → たしかめ → 配合。やめても 1ぴきめは えらんだ まま
    //   第70回: want … 作れる 魔物から 選んだ 子（子を えらぶ まどは 出さない。ほかの たしかめは いつもと 同じ）
    const breedWith = async (a, b, want = null) => {
      const ask = (child) => request(game, { kind: 'tavern', action: 'breedPreview', a, b, child });
      let r = await ask(want);
      if (!r.ok || !r.preview) {
        toast(r.text || '配合できない');
        return null;
      }
      let pv = r.preview;
      // 生まれる 子が 2つ いじょう: えらぶ（いちばん 上が おすすめ）
      if (!want && pv.choices?.length >= 2) {
        const sp = await pickChild(pv);
        if (!sp) return null;
        if (sp !== pv.child) {
          r = await ask(sp);
          if (!r.ok || !r.preview) {
            toast(r.text || '配合できない');
            return null;
          }
          pv = r.preview;
        }
      }
      // 第53回 D: 色の石が あって、色ちがいが ある 子なら、使うか えらぶ（色の石は 配合した ときだけ なくなる）
      let color = null;
      if (pv.stone > 0 && pv.colors?.length) {
        const v = await choose(game, `色の石を使う？（のこり${pv.stone}こ）\n色ちがいの子は、属性の強さ・弱さがかわる`, [
          { label: '使わない', value: '#none' },
          ...pv.colors.map((x) => ({ label: pv.unseen ? `${VARIANT_KINDS[x.kind]?.prefix || ''}？？？` : x.name, value: x.kind, right: '色の石' })),
          { label: 'やめる', value: null },
        ]);
        if (!v) return null;
        if (v !== '#none') color = pv.colors.find((x) => x.kind === v) || null;
      }
      const inherit = pv.skills.a.length || pv.skills.b.length ? await pickSkills(pv) : { a: [], b: [] };
      if (!inherit) return null;
      // まだ 見たことがない 子は 名前も ひみつ
      const label = childLabel(pv);
      const A = entries.get(a), B = entries.get(b);
      const ok = await confirmBox(game.input, `${A.name}と${B.name}を配合しますか？\n→ ${color && !pv.unseen ? color.name : label}（ランク${pv.rank} ＋${pv.plus}）が生まれる\n※ ${A.name}と${B.name}は旅立っていく（装備はふくろにもどる）${pv.itemName ? `\n※ ${pv.itemName}を使う（なくなる）` : ''}${color ? '\n※ 色の石を使う（なくなる）' : ''}`, '配合する', 'やめる', sfx);
      if (!ok) return null;
      // 第63回: 名前は 生まれて 姿を 見てから（さいしょは 種族の 名前。サーバーの world/breed.js）
      const res = await request(game, { kind: 'tavern', action: 'breed', a, b, child: pv.child, inherit, name: '', color: color?.kind || null });
      if (!res.ok) {
        toast(res.text || '配合できない');
        refresh(res);
        return res;
      }
      sfx('bond');
      refresh(res);
      if (res.born) await bornName(res);
      return res;
    };
    // 第63回: 「〜が生まれた！」の まど（姿・せつめい）→「名前をつける？」→ 名前を 書く
    const bornName = async (r) => {
      const b = r.born;
      const img = childImg(colorMon(b.species, b.color), false, { style: { height: '5em', width: 'auto', imageRendering: 'pixelated' } });
      const yes = await new Promise((resolve) => {
        const back = el('div', { class: 'modal-back', style: { zIndex: 20 } });
        const menu = new ListMenu(game.input, {
          items: [{ label: '名前をつける', value: true }, { label: `${b.name}のままでいい`, value: false }],
          sound: sfx,
          back: null,
          onSelect: (it) => finish(it.value),
          onCancel: () => finish(false),
        });
        const box = el('div', { class: 'win panel center-panel born-pop', style: { width: 'min(90vw, 520px)', zIndex: 21, background: 'var(--win-solid)' } },
          el('div', { style: { display: 'flex', justifyContent: 'center', margin: '0.2em 0 0.4em' } }, img),
          el('div', { style: { whiteSpace: 'pre-line', marginBottom: '0.3em' }, text: r.text || `${b.name}が生まれた！` }),
          el('div', { class: 'gold', style: { marginBottom: '0.3em' }, text: '名前をつける？' }),
          menu.root);
        const finish = (v) => {
          menu.blur();
          back.remove();
          box.remove();
          resolve(v);
        };
        document.getElementById('ui').append(back, box);
        menu.focus();
      });
      if (!yes) return;
      const nm = await askText(game.input, { title: `${b.name}の名前`, max: 8, initial: b.name });
      if (nm && nm !== b.name) await doReq({ action: 'rename', key: b.key, name: nm });
    };
    // 配合の 画面で えらんだ: 1ぴきめ → 2ひきめ（配合へ）。1ぴきめを もう一度 えらぶと はずす
    const breedPick = async (key) => {
      const x = entries.get(key);
      if (!x?.species) return;
      if (x.level < BREED_MIN_LEVEL) {
        sfx('buzz');
        toast(`レベル${BREED_MIN_LEVEL}になると配合できる`);
        return;
      }
      if (!parentA || parentA === key) {
        parentA = parentA === key ? null : key;
        refresh();
        // 1ぴきめを えらんだら、カーソルは いちばん 上の 相手へ（とくべつな 配合が できる 相手が 先）
        if (parentA) {
          const i = menu.items.findIndex((it) => !it.header && !it.disabled && it.value && it.value !== parentA && it.value !== SORT_KEY);
          if (i >= 0) {
            menu.idx = i;
            menu.render();
            show(menu.current?.value);
          }
        }
        return;
      }
      menu.blur();
      const r = await breedWith(parentA, key);
      if (r?.ok) parentA = null;
      refresh();
      menu.focus();
      // 配合して あける モード: 配合が すんだら、まっている 仲間の ところへ（第43回 C）
      if (r?.ok && room) endRoom(true);
    };
    // 配合して あける モードを おわる（ok … 配合した）。戦いの あとは 画面を とじる（サーバーが つづける）
    const endRoom = (ok) => {
      const done = room?.done;
      room = null;
      if (!done) return close();
      parentA = null;
      setView('human');
      done(ok);
    };
    // 酒場で 人を さそう 時: 配合して あける（配合したら true・やめたら false）
    const breedRoom = (name) => new Promise((resolve) => {
      room = { name, done: resolve };
      parentA = null;
      setView('breed');
      menu.focus();
    });
    // あずかり所へ 送る 魔物（酒場で 待っている 魔物が 先・レベルの 低い じゅん。world/farewell.js の storeList と 同じ）
    const pickStore = async () => {
      const busy = (x) => (x.inParty || x.inWagon ? 1 : 0);
      const list = info.roster.filter((x) => x.species).map((x, i) => ({ x, i })).sort((p, q) => busy(p.x) - busy(q.x) || p.x.level - q.x.level || p.i - q.i).map(({ x }) => x);
      const key = await ask('だれをあずかり所へ送る？\n（あずかり所の魔物は、あとで酒場にもどせる）', [
        ...list.map((x) => ({ face: face(x), label: `${x.name}（${who(x)}${busy(x) ? '・いっしょ' : ''}）`, value: x.key })),
        { label: 'もどる', value: null },
      ]);
      return (key && entries.get(key)) || null;
    };
    // 仲間が いっぱいの 時: 配合して あける・あずかり所へ 送る・さよなら・やめる（world/farewell.js の befriendFullSteps と 同じ）
    //   もどりち: { farewell } / { store } / { bred: true } / null（やめる）
    const pickFull = async (e) => {
      for (;;) {
        const me = game.me || {};
        const opts = [];
        if (canBreedRoom(me)) opts.push({ label: '配合してあける', value: 'breed' });
        if (canStore(me)) opts.push({ label: 'あずかり所へ送る', value: 'store' });
        opts.push({ label: 'だれかとさよならする', value: 'bye' }, { label: 'やめる', value: null });
        const a = await ask(`仲間がいっぱい！（${info.roster.length}/${info.rosterMax}）\n${e.name}のために、どうする？`, opts);
        if (!a) return null;
        if (a === 'bye') {
          const x = await pickFarewell(e.name);
          if (x) return { farewell: x };
        } else if (a === 'store') {
          const x = await pickStore();
          if (x) return { store: x };
        } else if (a === 'breed') {
          const ok = await breedRoom(e.name);
          if (shut) return null;
          menu.blur();
          if (ok && info.roster.length < info.rosterMax) return { bred: true };
          if (ok) toast('あずかり中の魔物どうしの配合では、仲間はあかない…');
        }
      }
    };
    const act = async (key) => {
      if (key === V_HUMAN) return setView('human');
      if (key === V_MON) return setView('monster');
      if (key === V_BREED) return setView('breed');
      if (key === SORT_KEY) {
        // ならびを かえる（仲間に なった順 → 種類順 → レベル順）。カーソルは この 行の まま
        sortMode = nextRosterSort(sortMode);
        setRosterSortPref(sortMode);
        refresh();
        return;
      }
      if (key === ARRANGE_KEY) {
        menu.blur();
        await arrange();
        menu.focus();
        return;
      }
      // 第70回: 作れる 魔物から 選ぶ
      if (key === FIND_KEY) {
        findAt = null;
        return openFinder();
      }
      if (key === FIND_LOW) {
        findLow = !findLow;
        return openFinder(null, FIND_LOW);
      }
      if (typeof key === 'string' && key.startsWith('kid:')) return openKid(key.slice(4));
      if (typeof key === 'string' && key.startsWith('pair:')) return pickPair(Number(key.slice(5)));
      if (view === 'breed') return breedPick(key);
      const e = entries.get(key);
      if (!e) return;
      menu.blur();
      // つれていく ところ: パーティー → 馬車 → どちらも いっぱいなら 入れかわり（ui/wagon.js）
      const place = tavernPlace(info, partyKeys().length);
      const full = place.full;
      if (e.sec === 'recruit') {
        // 仲間が いっぱい: だれかと さよならして 入れる？（world/farewell.js。第35回）
        let bye = null;
        let store = null;
        if (info.roster.length >= (info.rosterMax || info.roster.length + 1)) {
          // 配合して あける・あずかり所へ 送る・さよなら（第43回 C の pickFull）
          const how = await pickFull(e);
          if (!how) {
            if (!shut) menu.focus();
            return;
          }
          bye = how.farewell || null;
          store = how.store || null;
        }
        const gone = bye || store;
        const full2 = tavernPlace(info, partyKeys().length).full && !(gone && (gone.inParty || gone.inWagon));
        const farewell = bye?.key || null;
        const a = await ask(`${e.name}（${who(e)}）を仲間にする？`, [
          { label: full2 ? '仲間にして入れかわる' : `仲間にして連れていく${place.note}`, value: 'join' },
          { label: '仲間にして酒場で待ってもらう', value: 'wait' },
          { label: 'やめる', value: null },
        ]);
        if (a === 'join') {
          let swap = null;
          if (full2) swap = await pickSwap(e.name);
          if (!full2 || swap) await doReq({ action: 'recruit', key, swap, farewell, store: store?.key || null });
        } else if (a === 'wait') await doReq({ action: 'recruit', key, join: false, farewell, store: store?.key || null });
      } else if (e.inWagon) {
        const opts = [...tavernWagonOpts(info, e)];
        if (e.sec === 'roster') opts.push({ label: '名前を変える', value: 'rename' });
        if (e.sec === 'roster') opts.push({ label: '別れる', value: 'release' });
        opts.push({ label: 'やめる', value: null });
        const a = await ask(`${e.name}をどうする？`, opts);
        if (a === 'rename') await rename(e);
        else if (a === 'release') {
          const ok = await confirmBox(game.input, byeText(e), '別れる', 'やめる', sfx);
          if (ok) await doReq({ action: 'release', key });
        } else if (a) await tavernWagonAct(wagonCtx(), e, a);
      } else if (e.inParty) {
        const opts = [...tavernWagonOpts(info, e), { label: '酒場で待っていてもらう', value: 'wait' }];
        if (e.sec === 'roster') opts.push({ label: '名前を変える', value: 'rename' });
        opts.push({ label: 'やめる', value: null });
        const a = await ask(`${e.name}をどうする？`, opts);
        if (a === 'wait') await doReq({ action: 'wait', key });
        else if (a === 'rename') await rename(e);
        else if (a) await tavernWagonAct(wagonCtx(), e, a);
      } else {
        const opts = [{ label: `連れていく${place.note}`, value: 'join' }, ...tavernWagonOpts(info, e)];
        if (e.sec === 'roster') opts.push({ label: '名前を変える', value: 'rename' });
        if (e.sec === 'roster') opts.push({ label: '別れる', value: 'release' });
        opts.push({ label: 'やめる', value: null });
        const a = await ask(`${e.name}をどうする？`, opts);
        if (a === 'join') {
          let swap = null;
          if (full) swap = await pickSwap(e.name);
          if (!full || swap) await doReq({ action: 'join', key, swap });
        } else if (a === 'rename') await rename(e);
        else if (a === 'release') {
          const ok = await confirmBox(game.input, byeText(e), '別れる', 'やめる', sfx);
          if (ok) await doReq({ action: 'release', key });
        } else if (a) await tavernWagonAct(wagonCtx(), e, a);
      }
      menu.focus();
    };
    const wagonCtx = () => ({ info, entries, ask, doReq, face, who });
    const rename = async (e) => {
      const nm = await askText(game.input, { title: `${e.name}の新しい名前`, max: 8, initial: e.name });
      if (nm) await doReq({ action: 'rename', key: e.key, name: nm });
    };
    const close = () => {
      menu.blur();
      s.root.remove();
      // 酒場で 人を さそう とちゅうで とじた（第43回 C の breedRoom）
      shut = true;
      room?.done?.(false);
      room = null;
      resolve();
    };
    s.onClose = close;
    side.append(menu.root);
    // 戦いの あとの 配合して あける モードは 配合の 画面から（第43回 C）
    if (room) setView('breed');
    s.right.textContent = partyText();
    show(menu.current?.value);
    menu.focus();
  });
}

// ちいさな えらぶ まど（Promise で えらんだ value。やめたら null）
// top: タイトルの 下に 出す まど（えらぶ 前の みほん など）、onMove: カーソルを うごかした とき
export function choose(game, title, items, { top = null, onMove = null } = {}) {
  return new Promise((resolve) => {
    const back = el('div', { class: 'modal-back', style: { zIndex: 6 }, onclick: () => { game.audio.sfx('cancel'); done(null); } });
    const box = el('div', { class: 'win panel center-panel choose-pop', style: { width: 'min(90vw, 440px)', zIndex: 7 } }, el('div', { class: 'small gold', style: { whiteSpace: 'pre-line' }, text: title }), top);
    const hasCancel = items.some((i) => i.value === null);
    const m = new ListMenu(game.input, {
      items,
      sound: (x) => game.audio.sfx(x),
      back: hasCancel ? null : 'やめる',
      onMove: onMove ? (it) => onMove(it) : undefined,
      onSelect: (it) => done(it.value),
      onCancel: () => done(null),
    });
    box.append(m.root);
    document.getElementById('ui').append(back, box);
    m.focus();
    const done = (v) => {
      m.blur();
      back.remove();
      box.remove();
      resolve(v);
    };
  });
}

// ───────────── でんごんばん ─────────────
function boardUI(game, data) {
  return new Promise((resolve) => {
    const s = shell('けいじ板');
    s.game = game;
    const main = el('div', { class: 'win main scroll', style: { gridColumn: '1 / -1' } });
    s.body.append(main);
    let posts = data.posts || [];
    const render = () => {
      main.innerHTML = '';
      if (!posts.length) main.append(el('div', { class: 'muted', text: 'まだ何も書かれていない。' }));
      for (const p of posts.slice(0, 20)) {
        main.append(el('div', { class: 'combo-row' }, el('span', { class: 'gold', text: p.from }), el('span', { class: 'muted small', text: `　${ago(p.time)}` }), el('div', { text: p.text })));
      }
    };
    render();
    const menu = new ListMenu(game.input, {
      items: [{ label: '書きこむ', value: 'post' }, { label: '閉じる', value: 'close' }],
      cols: 2,
      sound: (x) => game.audio.sfx(x),
      onSelect: async (it) => {
        if (it.value === 'close') return close();
        menu.blur();
        const text = await askText(game.input, { title: 'けいじ板に書く', placeholder: '今日は洞窟まで行ったよ！', max: 120 });
        if (text) {
          const r = await request(game, { kind: 'board', action: 'post', text });
          toast(r.text || '');
          if (r.posts) posts = r.posts;
          render();
        }
        menu.focus();
      },
      back: null,
      onCancel: () => close(),
    });
    main.before(menu.root);
    const close = () => {
      menu.blur();
      s.root.remove();
      resolve();
    };
    s.onClose = close;
    menu.focus();
  });
}

export function ago(t) {
  const d = (Date.now() - t) / 1000;
  if (d < 60) return 'たった今';
  if (d < 3600) return `${Math.floor(d / 60)}分前`;
  if (d < 86400) return `${Math.floor(d / 3600)}時間前`;
  return `${Math.floor(d / 86400)}日前`;
}

// ───────────── ほしのかけら ─────────────
function starUI(game, data) {
  return new Promise((resolve) => {
    const s = shell('星のかけらこうかん');
    s.game = game;
    const main = el('div', { class: 'win main scroll', style: { gridColumn: '1 / -1' } });
    const detail = el('div', { class: 'detail' });
    s.body.append(main);
    const upd = () => { s.right.textContent = `星のかけら ${itemCount(game.me, 'star_shard')}個`; };
    upd();
    // 第50回 D3: なかまの 絵・NEW・装備の くらべ・こうかんの えんしゅつ（ui/prizes.js）。お話が 進むと ふえる
    const rows = () => starTradeRows(game, data);
    const show = (it) => {
      detail.innerHTML = '';
      if (!it || it.header) return;
      detail.append(el('div', { text: itemDetail(it.value) }));
      // 装備の くらべ・魔物の 絵・乗り物の せつめい（名前と せつめいは 上と おなじなので はぶく）
      const box = prizeInfo(game, it.value);
      box.querySelector('.hd')?.remove();
      box.querySelector('.detail')?.remove();
      detail.append(box);
    };
    const menu = new ListMenu(game.input, {
      items: rows(),
      sound: (x) => game.audio.sfx(x),
      onMove: (it) => show(it),
      onSelect: async (it) => {
        const t = it.trade;
        if (!t) return;
        menu.blur();
        if (await confirmBox(game.input, `星のかけら${t.shards}個で${ITEMS[t.item].name}とこうかんする？`, 'はい', 'いいえ', (x) => game.audio.sfx(x))) {
          const r = await request(game, { kind: 'starTrade', item: t.item });
          if (r.ok) prizeFx(game, t.item, { big: t.shards >= 30 });
          else game.audio.sfx('buzz');
          toast(`${r.text || ''}${r.ok ? useHint(t.item) : ''}`);
          setTimeout(() => {
            upd();
            menu.setItems(rows(), true);
          }, 100);
        }
        menu.focus();
      },
      back: null,
      onCancel: () => close(),
    });
    const close = () => {
      menu.blur();
      s.root.remove();
      resolve();
    };
    s.onClose = close;
    main.append(menu.root, detail);
    if (data.more) main.append(el('div', { class: 'detail muted', text: '（旅が進むと、こうかんできる品がふえるよ）' }));
    menu.focus();
  });
}

