// 第78回: メニューの「冒険のしおり」（docs/plan-r78-shiori.md）
//   つぎに 何を すれば いいか・何が のこって いるかを、画面を 大きく 使う まど 1まいで 見せる。
//   中みは shared/world/shiori.js の shioriOf（キャラだけで 決まる。サーバーでも ひとりモードでも おなじ）
//   ・物語（今の 部・章・幕と つぎの 目標）／おすすめ（3つまで）／のこって いる こと（しくみごとの 数と 棒）
//   ・えらぶと くわしい 一覧（のこって いる 物の 名前と 場所）。もどるで もとの 場所に もどる
//   ・キーボード・ゲームパッド（上下左右・決定・もどる）・タップの どれでも（dom.js の ListMenu）
import { el, ListMenu, esc } from './dom.js';
import './r78-shiori-css.js';
import { shioriOf, trackCount, trackRate } from '../../shared/world/shiori.js';

const NL = (s) => esc(s).replace(/\n/g, '<br>');
const whereHtml = (w) => (w ? `<div class="sh-where">${esc(w)}</div>` : '');

function storyTitle(st) {
  const t = [st.title ? `「${st.title}」` : '', st.actTitle].filter(Boolean).join(' ');
  return t;
}

function storyHtml(st) {
  const title = storyTitle(st);
  const clear = st.cleared ? '<span class="sh-st-clear">クリア！</span>' : '';
  const obj = st.objective ? `<div class="sh-st-obj">${NL(st.objective)}</div>` : '';
  const hint = st.bossHints?.length ? '<div class="sh-where">ボスのヒントがあるよ（選ぶと見られる）</div>' : '';
  return `<div class="sh-st-label">${esc(st.label)}${clear}</div>${title ? `<div class="sh-st-title">${esc(title)}</div>` : ''}${obj}${whereHtml(st.where)}${hint}`;
}

function recHtml(r) {
  const tag = r.kind === 'story' ? '物語' : 'より道';
  return `<span class="sh-rec-tag">${tag}</span><span class="sh-rec-text">${esc(r.text)}</span>${whereHtml(r.where)}`;
}

function barHtml(t) {
  if (!t.total) return '';
  return `<div class="sh-bar"><i style="width:${Math.round(trackRate(t) * 100)}%"></i></div>`;
}

function trackHtml(t) {
  const note = String(t.note || '').split('\n')[0];
  return `<div class="sh-tr-top"><span class="sh-tr-name">${esc(t.name)}</span><span class="sh-tr-num">${esc(trackCount(t))}</span></div>${barHtml(t)}<div class="sh-tr-note">${esc(note)}</div>`;
}
// ひみつのダンジョンは 終わりが ない ので、つぎの 番人の 階に ついても みどりに しない
const isFull = (t) => !!t.total && t.now >= t.total && t.id !== 'sd';

// メニューの 右の 見本（カーソルを あわせた だけ。えらぶと 大きな まど）
export function shioriPreview(menu) {
  const s = shioriOf(menu.game.me, { missions: menu.game.missionSum });
  const box = el('div', { class: 'sh-pv' });
  box.append(el('div', { class: 'muted', text: 'つぎに何をすればいいか、何がのこっているかを、1まいで見る。\n選ぶと、大きく開く。' }));
  box.append(el('div', { class: 'sh-pv-story', text: [s.story.label, storyTitle(s.story)].filter(Boolean).join(' ') }));
  for (const r of s.recs) box.append(el('div', { class: 'sh-pv-rec', text: `・${r.text}` }));
  return box;
}

// 大きな まどを 開く。とじたら おわる Promise
export function openShiori(menu) {
  const g = menu.game;
  const sfx = (x) => g.audio?.sfx?.(x);
  return new Promise((resolve) => {
    const data = shioriOf(g.me, { missions: g.missionSum });
    const back = el('div', { class: 'modal-back', style: { zIndex: 4 }, onclick: () => { sfx('cancel'); finish(); } });
    const title = el('h2', { class: 'sh-title', text: '冒険のしおり' });
    const who = el('span', { class: 'sh-who', text: g.me?.name ? `${g.me.name}の冒険` : '' });
    const closeBtn = el('button', { class: 'btn sh-close', text: '✕ 閉じる', 'aria-label': 'しおりを閉じる', onclick: (e) => { e.stopPropagation(); sfx('cancel'); onBack(); } });
    const body = el('div', { class: 'sh-body' });
    const foot = el('div', { class: 'sh-foot', text: '決定で、くわしく見る。もどるで、閉じる。' });
    const box = el('div', { class: 'win shiori-pop', role: 'dialog', 'aria-label': '冒険のしおり' }, el('div', { class: 'sh-head' }, title, who, closeBtn), body, foot);
    let list = null;
    let detailOpen = false;
    let mainIdx = -1;
    let mainTop = 0;

    const finish = () => {
      list?.blur();
      back.remove();
      box.remove();
      menu.popupOpen = false;
      resolve();
    };
    function onBack() {
      if (detailOpen) showMain();
      else finish();
    }

    // ───── 1まい目: 物語・おすすめ・のこって いる こと ─────
    function showMain() {
      detailOpen = false;
      list?.blur();
      body.innerHTML = '';
      closeBtn.textContent = '✕ 閉じる';
      foot.textContent = '決定で、くわしく見る。もどるで、閉じる。';
      const st = data.story;
      const items = [
        { header: true, label: '物語' },
        { html: storyHtml(st), value: { go: 'story' }, cls: 'sh-story sh-wide' },
      ];
      if (data.recs.length) {
        items.push({ header: true, label: 'おすすめ' });
        for (const r of data.recs) items.push({ html: recHtml(r), value: { go: r.go }, cls: `sh-rec ${r.kind}` });
      }
      items.push({ header: true, label: 'のこっていること' });
      for (const t of data.tracks) items.push({ html: trackHtml(t), value: { go: t.id }, cls: `sh-track ${isFull(t) ? 'full' : ''}` });
      list = new ListMenu(g.input, {
        items,
        className: 'sh-list',
        sound: sfx,
        back: null,
        start: mainIdx,
        onSelect: (it, i) => {
          mainIdx = i;
          mainTop = body.scrollTop;
          showDetail(it.value.go);
        },
        onCancel: () => finish(),
      });
      body.append(list.root);
      body.scrollTop = mainTop;
      list.focus();
      list.scrollToSel();
    }

    // ───── くわしい 一覧 ─────
    function showDetail(go) {
      detailOpen = true;
      list?.blur();
      body.innerHTML = '';
      closeBtn.textContent = '← もどる';
      foot.textContent = 'もどるで、しおりにもどる。';
      const top = el('div', { class: 'sh-detail-top' });
      let items = [];
      if (go === 'story') {
        const st = data.story;
        top.append(el('div', { class: 'sh-tr-top' }, el('span', { class: 'sh-tr-name', text: `${st.label}${st.cleared ? '（クリア！）' : ''}` })));
        const t2 = storyTitle(st);
        if (t2) top.append(el('div', { class: 'sh-note', text: t2 }));
        if (st.objective) top.append(el('div', { class: 'sh-note', text: `つぎの目標：${st.objective}` }));
        if (st.where) top.append(el('div', { class: 'sh-where', text: `場所：${st.where}` }));
        if (st.hint) top.append(el('div', { class: 'sh-hint', text: `仲間のひとこと：${st.hint}` }));
        // 第80回 E班: ボスに 負けた 時に 出た ヒント（勝つと 消える）
        for (const b of st.bossHints || []) b.hints.forEach((h, i) => top.append(el('div', { class: 'sh-hint', text: `ボスのヒント${i + 1}：${h}` })));
        if (st.end) top.append(el('div', { class: 'sh-note', text: '物語の続きは、アップデートを待とう。それまでは、より道やいらいを楽しもう！' }));
      } else {
        const t = data.tracks.find((x) => x.id === go);
        if (!t) return showMain();
        top.append(el('div', { class: 'sh-tr-top' }, el('span', { class: 'sh-tr-name', text: t.name }), el('span', { class: 'sh-tr-num', text: trackCount(t) })));
        if (t.total) top.append(el('div', { class: 'sh-bar', html: `<i style="width:${Math.round(trackRate(t) * 100)}%"></i>` }));
        if (t.where) top.append(el('div', { class: 'sh-where', text: `場所：${t.where}` }));
        if (t.note) top.append(el('div', { class: 'sh-note muted', text: t.note }));
        items = t.items.map((x) => ({
          html: `<span class="sh-dname">${esc(x.name)}</span>${x.where ? `<span class="sh-dwhere">${esc(x.where)}</span>` : ''}`,
          right: x.right || '',
          value: x,
          cls: `st-${x.state}`,
        }));
        for (const x of t.extra || []) items.push({ html: `<span class="sh-dname">${esc(x.name)}</span>`, right: x.right, value: x, cls: 'st-now' });
      }
      if (!items.length) items.push({ label: 'しおりにもどる', value: null, cls: 'sh-backrow' });
      // カーソルは のこって いる 物の いちばん 上に（すんだ 物から 始めない）
      const first = items.findIndex((it) => it.value?.state && it.value.state !== 'done');
      list = new ListMenu(g.input, {
        items,
        className: 'sh-dlist',
        sound: sfx,
        back: null,
        start: first,
        onSelect: (it) => { if (it.value === null) showMain(); },
        onCancel: () => showMain(),
      });
      body.append(top, list.root);
      body.scrollTop = 0;
      list.focus();
    }

    document.getElementById('ui').append(back, box);
    menu.popupOpen = true;
    showMain();
  });
}

js/client/ui/shop.js:
// お店と 教会（ドラクエの ながれ）
//
// お店:  「どんなご用でしょう？」→ 買いにきた／売りにきた／やめる
//   買う: 品物を えらぶ（みぎに みんなの 強さが どう かわるか）→ いくつ？（道具）→「〇〇ゴールドですが、よろしいですか？」はい／いいえ
//         → 装備品なら「ここで装備していきますか？」→「どなたが装備しますか？」→「今までの〇〇は引き取りましょうか？」
//   売る: 品物を えらぶ → いくつ？ →「〇〇ゴールドで引き取りましょう。よろしいですか？」はい／いいえ
// 教会:  おいのりをする／生き返らせる／毒を治す／やめる（寄付の かくにん つき）
import { rareNameHtml } from './rarity.js';
import { Counter, EQUIP_TYPES, compareTeam, itemInfo, whoItems } from './counter.js';
import { ITEMS, sellPrice } from '../../shared/data/items.js';
import { itemCount } from '../../shared/stats.js';
import { boardIconURL } from '../render/boards.js';

// サーバーの へんじを まつ
export function request(game, msg) {
  return new Promise((resolve) => {
    game.svcWaiter = resolve;
    game.net.send({ t: 'svc', ...msg });
    setTimeout(() => {
      if (game.svcWaiter === resolve) {
        game.svcWaiter = null;
        resolve({ ok: false, text: '通信がおくれています' });
      }
    }, 6000);
  });
}

const AGAIN = 'ほかにも何かお求めですか？';

// ───────────── お店 ─────────────
export async function shopUI(game, data) {
  const ct = new Counter(game, { title: data.name, keeper: data.keeper || '店の人', icon: boardIconURL(data.kind) });
  let line = data.hello || 'いらっしゃいませ！\nどんなご用でしょう？';
  while (!ct.closed) {
    await ct.say(line);
    ct.info(null);
    const cmd = await ct.pick([
      { label: '買いにきた', value: 'buy' },
      { label: '売りにきた', value: 'sell' },
      { label: 'やめる', value: 'exit' },
    ], { back: null });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    if (cmd.value === 'buy') await buyLoop(game, ct, data);
    else await sellLoop(game, ct);
    line = 'ほかにも何かご用はありますか？';
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(null);
  await ct.say('またのおこしをお待ちしております。');
  await ct.tap(1400);
  ct.close();
}

// 店の ねだん（ひみつのダンジョンの お店は その 店だけの ねだん。data/secret-shop.js）
const priceOf = (data, id) => data?.prices?.[id] ?? ITEMS[id].price;

function buyRow(game, id, data) {
  const it = ITEMS[id];
  const price = priceOf(data, id);
  let tag = '';
  if (EQUIP_TYPES.includes(it.type)) {
    const team = compareTeam(game, id);
    if (!team.some((r) => r.can)) tag = '<span class="tag muted">装備できない</span>';
    else if (team.some((r) => r.can && !r.same && r.main.d > 0)) tag = '<span class="tag up">↑強くなる</span>';
  }
  return { value: id, label: it.name, html: `${rareNameHtml(id)}${tag}`, right: `${price}G`, rightCls: game.me.gold < price ? 'dis' : 'gold' };
}

async function buyLoop(game, ct, data) {
  let line = 'どれをお求めですか？';
  let idx = 0;
  while (!ct.closed) {
    await ct.say(line);
    const rows = data.items.filter((id) => ITEMS[id]).map((id) => buyRow(game, id, data));
    const it = await ct.pick(rows, { start: idx, onMove: (x) => ct.info(x ? itemInfo(game, x.value) : null) });
    if (!it) return;
    idx = rows.findIndex((r) => r.value === it.value);
    line = await buyOne(game, ct, it.value, priceOf(data, it.value));
  }
}

async function buyOne(game, ct, id, price = ITEMS[id].price) {
  const it = ITEMS[id];
  const eq = EQUIP_TYPES.includes(it.type);
  let qty = 1;
  if (!eq) {
    // 1つの 道具は 99個まで（第60回: 10個ずつ 買える ように なったので、持てない 分は 買わせない）
    const room = 99 - itemCount(game.me, id);
    if (room < 1) {
      await ct.say(`${it.name}は、もうこれ以上持てないようですね。`);
      await ct.tap(1800);
      return AGAIN;
    }
    const max = Math.min(room, Math.floor(game.me.gold / price));
    if (max < 1) {
      await ct.say(`${it.name}は${price}ゴールドです。\nおや？ゴールドが足りないようですね。`);
      await ct.tap(1800);
      return AGAIN;
    }
    qty = await ct.qty(`${it.name}ですね。\nいくつお求めですか？`, max, price, `持っている数: ${itemCount(game.me, id)}`);
    if (!qty) return AGAIN;
  }
  const total = price * qty;
  const yes = await ct.ask(qty > 1
    ? `${it.name}を${qty}個ですね。\n全部で${total}ゴールドになりますが、よろしいですか？`
    : `${it.name}ですね。\n${total}ゴールドになりますが、よろしいですか？`);
  if (ct.closed || yes !== 0) return AGAIN; // 買わない
  if (game.me.gold < total) {
    await ct.say('おや？ゴールドが足りないようですね。');
    await ct.tap(1800);
    return AGAIN;
  }
  let who = null;
  let sellOld = false;
  if (eq) {
    const rows = compareTeam(game, id);
    if (rows.some((r) => r.can && !r.same)) {
      const now = await ct.ask('ここで装備していきますか？');
      if (now === 0) {
        await ct.say('どなたが装備しますか？');
        const pick = await ct.pick(whoItems(rows), { box: 'info', back: '装備しない' });
        if (pick) {
          who = pick.value;
          const r = rows.find((x) => x.key === who);
          if (r?.cur && sellPrice(r.cur) > 0) {
            const ans = await ct.ask(`${r.name}が今まで装備していた${ITEMS[r.cur].name}は、\n${sellPrice(r.cur)}ゴールドで引き取りましょうか？`);
            sellOld = ans === 0;
          }
        }
      }
    }
  }
  if (ct.closed) return AGAIN;
  const res = await request(game, { kind: 'shop', action: 'buy', id, qty, who, sellOld });
  ct.updGold();
  if (!res.ok) {
    await ct.say(res.text || 'おや？何かおかしいようですね。');
    await ct.tap(1800);
    return AGAIN;
  }
  game.audio.sfx(who ? 'buff' : 'item');
  ct.info(itemInfo(game, id));
  await ct.say(res.text, { narr: true });
  await ct.tap(2400);
  return `まいどありがとうございます！\n${AGAIN}`;
}

async function sellLoop(game, ct) {
  const AGAIN_SELL = 'ほかに売る物はありますか？';
  let line = '何を売っていただけますか？';
  let idx = 0;
  while (!ct.closed) {
    // おなじ 品物は 1行に まとめる
    const counts = new Map();
    for (const e of game.me.items || []) if (ITEMS[e.id] && ITEMS[e.id].type !== 'key') counts.set(e.id, (counts.get(e.id) || 0) + e.n);
    const bag = [...counts].map(([id, n]) => ({ id, n }));
    if (!bag.length) {
      ct.list(null);
      ct.info(null);
      await ct.say('おや？売れる物は持っていないようですね。');
      await ct.tap(1800);
      return;
    }
    await ct.say(line);
    const rows = bag.map((e) => ({
      value: e.id,
      label: ITEMS[e.id].name,
      html: `${rareNameHtml(e.id)}${ITEMS[e.id].type === 'mat' ? '<span class="tag mat">素材</span>' : ''}<span class="cnt">×${e.n}</span>`,
      right: sellPrice(e.id) > 0 ? `${sellPrice(e.id)}G` : '―',
      rightCls: 'gold',
      disabled: sellPrice(e.id) <= 0,
    }));
    const it = await ct.pick(rows, { start: Math.min(idx, rows.length - 1), onMove: (x) => ct.info(x ? itemInfo(game, x.value, { sell: true }) : null) });
    if (!it) return;
    idx = rows.findIndex((r) => r.value === it.value);
    const d = ITEMS[it.value];
    const price = sellPrice(it.value);
    const have = itemCount(game.me, it.value);
    let qty = 1;
    if (have > 1) {
      qty = await ct.qty(`${d.name}ですね。\nいくつ売りますか？`, have, price, `持っている数: ${have}`);
      if (!qty) {
        line = AGAIN_SELL;
        continue;
      }
    }
    const total = price * qty;
    const yes = await ct.ask(qty > 1
      ? `${d.name}を${qty}個ですね。\nそれなら全部で${total}ゴールドで引き取りましょう。よろしいですか？`
      : `${d.name}ですね。\nそれなら${total}ゴールドで引き取りましょう。よろしいですか？`);
    if (ct.closed) return;
    if (yes !== 0) {
      line = AGAIN_SELL;
      continue;
    }
    const res = await request(game, { kind: 'shop', action: 'sell', id: it.value, qty });
    ct.updGold();
    if (!res.ok) {
      await ct.say(res.text || 'おや？何かおかしいようですね。');
      await ct.tap(1800);
      line = AGAIN_SELL;
      continue;
    }
    game.audio.sfx('item');
    line = `まいどありがとうございます！\n${AGAIN_SELL}`;
  }
}

// ───────────── 教会 ─────────────
export async function churchUI(game, data) {
  const ct = new Counter(game, { title: data.title || '教会', keeper: data.keeper || '神父さま', icon: boardIconURL('church') });
  let info = data;
  const AGAIN_C = 'ほかにも何かご用かな？';
  let line = 'おお、迷える子羊よ。神の家によくぞ来られた。\n今日はどんなご用かな？';
  while (!ct.closed) {
    await ct.say(line);
    ct.info(null);
    const cmd = await ct.pick([
      { label: 'おいのりをする', value: 'record' },
      { label: '生き返らせる', value: 'revive' },
      { label: '毒を治す', value: 'cure' },
      { label: 'やめる', value: 'exit' },
    ], { back: null, onMove: (x) => ct.info(churchHint(x?.value)) });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    if (cmd.value === 'record') {
      const yes = await ct.ask('神にいのりをささげて、\nここを、いのりの場所として記録しますか？');
      if (yes === 0) {
        const r = await request(game, { kind: 'church', action: 'record' });
        if (r.ok) game.audio.sfx('heal');
        await ct.say(r.text || '');
        await ct.tap(2400);
      }
      line = AGAIN_C;
      continue;
    }
    const list = cmd.value === 'revive' ? info.dead : info.poisoned;
    if (!list.length) {
      await ct.say(cmd.value === 'revive' ? '生き返らせる者は、おらぬようじゃな。' : '毒にかかっている者は、おらぬようじゃな。');
      await ct.tap(1800);
      line = AGAIN_C;
      continue;
    }
    await ct.say(cmd.value === 'revive' ? 'だれを生き返らせるのかな？' : 'だれの毒を治すのかな？');
    const who = await ct.pick(list.map((d) => ({ value: d.ref, label: d.name, right: `${d.price}G`, rightCls: 'gold' })), { back: 'やめる' });
    if (ct.closed) return;
    if (!who) {
      line = AGAIN_C;
      continue;
    }
    const d = list.find((x) => x.ref === who.value);
    const yes = await ct.ask(cmd.value === 'revive'
      ? `${d.name}を生き返らせるには、\n${d.price}ゴールドの寄付が必要じゃ。よろしいかな？`
      : `${d.name}の毒を治すには、\n${d.price}ゴールドの寄付が必要じゃ。よろしいかな？`);
    if (ct.closed) return;
    if (yes !== 0) {
      line = AGAIN_C;
      continue;
    }
    const r = await request(game, { kind: 'church', action: cmd.value, ref: d.ref });
    ct.updGold();
    if (r.church) info = r.church;
    if (r.ok) game.audio.sfx('heal');
    ct.list(null);
    await ct.say(r.text || '');
    await ct.tap(2400);
    line = AGAIN_C;
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(null);
  await ct.say('あなたに神のご加護がありますように。');
  await ct.tap(1400);
  ct.close();
}

function churchHint(action) {
  const text = {
    record: 'おいのりをすると、ここが「いのりの場所」になる。\n全員がたおれたときは、最後においのりした教会で目を覚ますよ。',
    revive: '死んでしまった仲間を、寄付と引きかえに生き返らせてもらえる。',
    cure: '毒にかかった仲間を、寄付と引きかえに治してもらえる。',
    exit: '',
  }[action];
  if (!text) return null;
  const box = document.createElement('div');
  box.className = 'detail';
  box.textContent = text;
  return box;
}

js/client/ui/skillinfo.js:
// 戦いの 呪文・特技・道具の せつめい（カーソルを 合わせた とき、メッセージの まどに 出す。2026年10月 見なおし）
//   1行め: 種類と 属性（炎属性の ダメージの 呪文 など）・MP・相手（敵1体・敵全体・自分 など）
//   2行め: 威力・効果の 目安（ふつうの 攻撃の 何倍・ダメージ・回復の 量・何が 上がるか）
//   3行め: せつめい（data の desc）。転職の ペナルティ・上位の 技なども
// 相手を えらぶ 前（敵が 1体・自分に かける・全体の 技でも）に 見える。client/battle.js の abilityMenu・itemMenu
import { ABILITIES, abilityTypeText, abilityRole } from '../../shared/data/abilities.js';
import { abilityFor, abilityLabel } from '../../shared/ability-label.js';
import { ITEMS } from '../../shared/data/items.js';
import { JOBS } from '../../shared/data/jobs.js';
import { SKILL_UPS } from '../../shared/data/skill-ups.js';
import { mpCost, penaltyFor, comboAllowed } from '../../shared/stats.js';
import { targetText, itemDetail } from './info.js';
// 第38回 C: バフ・デバフは 3回行動のあいだ・じわじわ回復の 回数は 技の レベルで（shared/buff-acts.js）
import { REGEN_BASE, regenTimes, skillLevel } from '../../shared/buff-acts.js';
// 第50回 N1: 今の 魔力・回復魔力での 威力の 目安（shared/skill-power.js）
import { powStats, powMults, partPower, partPowerText } from '../../shared/skill-power.js';
export { powStats };
// 第50回 D4: 上の 職業の 技ほど 補助が 長く・2段階・回復が 多い（shared/skill-tier.js）。文は tierText だけで つくる
import { skillMods, TIER_MODS } from '../../shared/skill-tier.js';
import { stackMult } from '../../shared/battle.js';

const STAT = { atk: '攻撃力', def: '守備力', agi: '素早さ', mag: '魔力', heal: '回復魔力', eva: 'かわしやすさ', dfn: '守備力', hit: '命中' };
const STATUS = { sleep: 'ねむり', paralyze: 'マヒ', confuse: '混乱', blind: 'まぼろし', silence: '呪文ふうじ', poison: '毒', stop: '動けない' };
const SEED = { str: '力', def: '身の守り', agi: '素早さ', mag: '攻撃魔力', hp: '最大HP', mp: '最大MP', heal: '回復魔力' };
const ITEM_TARGET = { self: '自分', ally: '味方1人', deadAlly: '死んだ味方1人', allies: '味方全員' };

const num = (x) => (Math.round(x * 10) / 10).toString();
const range = (b, k = 1) => (Array.isArray(b) ? `${Math.round(b[0] * k)}〜${Math.round(b[1] * k)}` : `${Math.round((b || 0) * k)}`);
const pct = (x) => `${Math.round(x * 100)}%`;

// 補助の 倍率と 回数（tm: 技の ランクの こうか。2段階の 技は 2段階めの 倍率）
//   基本職 … 攻撃力1.3倍・3回行動のあいだ ／ 伝説 … 攻撃力1.8倍（2段階）・5回行動のあいだ
function tierText(m, tm, acts = true) {
  const st = tm.stages >= 2 ? `${num(stackMult(m, tm.stages))}倍（${tm.stages}段階）` : `${num(m)}倍`;
  return acts ? `${st}・${tm.acts}回行動のあいだ` : `${st}（${tm.acts}回行動）`;
}

// 1つの 効果の 威力の 目安（pm: 職業レベル・転職の ペナルティを かけた 威力の 倍率。lv: 技の レベル〈じわじわ回復の 回数〉。道具は 0）
// st: 今の 魔力・回復魔力（{ mag, heal }。あれば 魔力で 上がる 呪文は 今の 魔力での ダメージ・回復を 出す。第50回 N1）
// tm: 技の ランクの こうか（skill-tier.js。道具・ランク0は TIER_MODS[0]。第50回 D4）
function partText(e, pm, lv = 0, st = null, tm = TIER_MODS[0]) {
  if (!e) return '';
  switch (e.type) {
    case 'phys': {
      const m = (e.mult ?? 1) * pm;
      const hits = e.hits > 1 ? `×${e.hits}回${e.random ? '（ランダム）' : ''}` : '';
      const extra = [e.ignoreDef ? `守りを${pct(e.ignoreDef)}むし` : '', e.status ? `${STATUS[e.status.status] || ''}（${pct(e.status.chance ?? 1)}）` : '', e.debuff ? `${STAT[e.debuff.stat] || ''}${tierText(e.debuff.mult, tm, false)}` : ''].filter(Boolean).join('・');
      return `ふつうの攻撃の約${num(m)}倍${hits}${extra ? `・${extra}` : ''}`;
    }
    case 'magic':
      if (st) return `${nowText(e, pm, st)}${e.status ? `・${STATUS[e.status.status] || ''}` : ''}`;
      return `ダメージ約${range(e.base, pm)}${e.stat === 'heal' ? '（回復魔力で上がる）' : (e.thr ?? 20) < 99 ? '（魔力で上がる）' : ''}${e.status ? `・${STATUS[e.status.status] || ''}` : ''}`;
    case 'heal': return st && !e.fixed ? `今の回復魔力でHPを約${range(nowRange(e, pm, st), tm.healMul)}回復` : `HPを約${range(e.base, pm * tm.healMul)}回復`;
    case 'regen': return st && !e.fixed ? `毎ターンの初めにHPを${range(nowRange(e, pm, st), tm.healMul)}回復・${lv ? regenTimes(lv) : REGEN_BASE}回（今の回復魔力で）` : `毎ターンの初めにHPを${range(e.base, tm.healMul)}回復・${lv ? regenTimes(lv) : REGEN_BASE}回`;
    // 推理（弱点の 属性で 攻撃）・ミナデイン（仲間の MPを 集める）
    case 'deduce':
    case 'gather': return e.base ? (st ? nowText(e, pm, st) : `ダメージ約${range(e.base, pm)}`) : '';
    // 第72回: 元気玉（集めたHP×倍率。戦いの 中は 今の みんなで どれくらいか。shared/skill-power.js）
    case 'genki': return partPowerText(partPower(e, pm, st));
    case 'mpHeal': return `MPを約${range(e.base)}回復`;
    case 'buff': {
      const st = (e.stats || [e.stat]).map((s) => STAT[s] || s).join('・');
      const foe = e.target === 'enemy' || e.target === 'enemies' ? '敵の' : '';
      if (e.add) return `${foe}${st}+${pct(Math.min(0.6, e.add * tm.stages))}${tm.stages >= 2 ? `（${tm.stages}段階）` : ''}・${tm.acts}回行動のあいだ`;
      return `${foe}${st}${tierText(e.mult, tm)}`;
    }
    case 'debuff': return `敵の${(e.stats || [e.stat]).map((s) => STAT[s] || s).join('・')}${tierText(e.mult, tm)}${e.chance ? `（${pct(e.chance)}）` : ''}`;
    case 'status': return `${STATUS[e.status] || e.status}にする（${pct(e.chance ?? 1)}）${e.also ? `・${STATUS[e.also.status] || ''}` : ''}`;
    case 'atbSet': return `敵の動きを止める（${pct(e.chance ?? 1)}）`;
    case 'cure': return `${(e.statuses || []).map((s) => STATUS[s] || s).join('・')}を治す`;
    case 'revive': return `生き返らせる（HP${pct(Math.min(1, (e.hpRatio || 0.25) * tm.healMul))}）`;
    case 'reviveAll': return 'たおれた味方みんなを生き返らせる';
    case 'charge': return `次の攻撃が${num(e.mult)}倍`;
    case 'drainHp': return `ふつうの攻撃の約${num((e.mult ?? 1) * pm)}倍・HPをすいとる`;
    case 'drainMp': return `MPを${range(e.amount)}すいとる`;
    case 'cover': return `味方をかばう・${TIER_MODS[0].acts}回行動のあいだ${e.defMult ? `（守備力${num(e.defMult)}倍）` : ''}`;
    case 'steal': return `物をぬすむ（${pct(e.chance ?? 1)}）`;
    case 'dispel': return '敵の強化を消す';
    case 'escape': return '戦いからにげる';
    case 'seed': return `${SEED[e.stat] || ''}が${range(e.amount)}上がる（ずっと）`;
    case 'multi': return (e.parts || []).map((p) => partText(p, pm, lv, st, tm)).filter(Boolean).join('＋');
    default: return '';
  }
}

// 今の 魔力での ダメージ（「今の魔力でダメージ約120〜150」。相手の 耐性は 考えない）
function nowText(e, pm, st) {
  return partPowerText(partPower(e, pm, st));
}
function nowRange(e, pm, st) {
  const p = partPower(e, pm, st);
  return p ? [p.min, p.max] : e.base;
}

// リストの 2行めに 出す 威力の みじかい 文（第50回 N1。オートで 使う 技・メニューの「呪文・技」）
//   物理「威力×1.8」・魔力「今の魔力でダメージ約120〜150」・回復「今の回復魔力で約80〜95回復」・そのほかは 効果の 文
// st: 今の 魔力（{ mag, heal }。たくさん ならべる ときは 先に powStats で 1回だけ 出して わたす）
export function skillPowerLine(id, pc, { who = pc, lv = null, st = powStats(pc) } = {}) {
  const a = abilityFor(id, who);
  if (!a?.effect) return '';
  const { pm, base } = powMults(pc, id);
  const slv = lv || skillLvFor(pc, id);
  // 第50回 D4: 上の 職業の 技は 回復が 多い（ランクの 倍率）
  const tm = skillMods(pc, id);
  const one = (e) => {
    if (e?.type === 'multi') return (e.parts || []).map(one).filter(Boolean).join('＋');
    const heal = e?.type === 'heal' || e?.type === 'regen';
    const p = partPower(e, heal ? pm * tm.healMul : pm, st, base);
    return p ? partPowerText(p) : partText(e, pm, slv, st, tm);
  };
  return one(a.effect);
}

// 第71回: メニューの お気に入り（ならびかえ）で えらんでいる 技の せつめい。戦いの せつめいと おなじ 中身を みじかく
//   head: 【種類（属性）】MP・相手 / pow: 威力の 目安（skillPowerLine）/ desc: せつめい / warn: 今の 職業で ない 技の ⚠
export function skillCardInfo(id, pc, who = pc) {
  const a = abilityFor(id, who);
  if (!a) return null;
  const cost = a.effect?.type === 'mahouken' ? null : pc ? mpCost(pc, id) : a.mp || 0;
  const pen = pc ? penaltyFor(pc, id) : null;
  return {
    head: `【${abilityTypeText(a)}】${cost === null ? '' : `MP${cost}・`}${targetText(a) || '—'}`,
    pow: skillPowerLine(id, pc, { who }),
    desc: a.desc || '',
    warn: pen?.penalized ? `⚠${pen.label}` : '',
  };
}

// 技の 効果の 目安（メニューの「呪文・技」にも 出す。lv: 技の レベル）
export function skillEffectText(id, pc, lv = 1, who = pc) {
  const a = abilityFor(id, who);
  if (!a) return '';
  const pen = pc ? penaltyFor(pc, id) : { powMult: 1 };
  return partText(a.effect, pen.powMult || 1, lv, powStats(pc), skillMods(pc, id));
}

// 技の レベル（pc.skillUse か、戦いの slv〈Lv2 いじょうの 技〉から）
export function skillLvFor(pc, id, slv = null) {
  if (slv) return slv[id] || 1;
  return skillLevel(pc?.skillUse, id);
}

// 呪文・特技の せつめい（pc: 使う 人。{ job, jobs }。touch: タッチの とき「もう一度タップで使う」）
// who: 名前・説明を きめる 人（look を 見る。男の子の 美少女戦士などは かわる。ability-label.js。look の ない pc なら もとの まま）
// lv: 技の レベル（第38回 C。じわじわ回復の 回数に かかわる。わからない ときは pc.skillUse から）
// compact: スマホの たてむき（第61回）。3行まで: 見出し・威力・せつめいの 1文め（⚠だけ そえる。「もう一度タップ」は 出さない）
export function battleSkillText(id, pc, { touch = false, who = pc, lv = null, compact = false } = {}) {
  const a = abilityFor(id, who);
  if (!a) return '';
  const lines = [];
  const pen = pc ? penaltyFor(pc, id) : { powMult: 1 };
  const pm = pen.powMult || 1;
  // 見出し（「炎属性のダメージの呪文」など。属性も ここに 入る）・MP・相手
  const cost = a.effect?.type === 'mahouken' ? null : pc ? mpCost(pc, id) : a.mp || 0;
  // compact: 「炎属性のダメージの呪文」→「炎・ダメージの呪文」、「今の魔力でダメージ約22〜30」→「ダメージ約22〜30」
  const type = compact ? abilityTypeText(a).replace(/属性の/, '・') : abilityTypeText(a);
  lines.push(`【${type}】${cost === null ? '' : `MP${cost}・`}${targetText(a) || '—'}`);
  const role = abilityRole(a);
  const slv = lv || skillLvFor(pc, id);
  const pw0 = partText(a.effect, pm, slv, powStats(pc), skillMods(pc, id));
  const pw = compact && pw0 ? pw0.replace(/^今の[^で、]{1,8}で/, '') : pw0;
  if (pw) lines.push(`${role === 'dmg' ? '威力' : '効果'}：${pw}`);
  const notes = [];
  if (slv > 1) notes.push(`技Lv${slv}`);
  if (pen.jobPow > 1 && role !== 'sup') notes.push(`職業レベルで威力+${Math.round((pen.jobPow - 1) * 100)}%`);
  if (SKILL_UPS[id] && ABILITIES[SKILL_UPS[id]]) notes.push(`${abilityLabel(SKILL_UPS[id], who)}の上位の技`);
  if (pen.penalized) notes.push(`⚠${pen.label}`);
  if (a.kind === 'combo' && pc?.job && JOBS[pc.job] && !comboAllowed(pc, id)) notes.push('⚠今の職業では使えない');
  if (compact) {
    const warn = notes.filter((n) => n.startsWith('⚠'));
    lines.push([firstSentence(a.desc), warn.length ? `（${warn.join('・')}）` : ''].filter(Boolean).join(''));
    return lines.filter(Boolean).join('\n');
  }
  lines.push([a.desc || '', notes.length ? `（${notes.join('・')}）` : ''].filter(Boolean).join(''));
  if (touch) lines.push('▶もう一度タップで使う');
  return lines.filter(Boolean).join('\n');
}

// せつめいの 1文め（「。」まで。かっこの 中の 「。」では 切らない）
export function firstSentence(desc) {
  const t = String(desc || '');
  let depth = 0;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (ch === '（' || ch === '「' || ch === '(') depth++;
    else if ((ch === '）' || ch === '」' || ch === ')') && depth > 0) depth--;
    else if (ch === '。' && depth === 0) return t.slice(0, i + 1);
  }
  return t;
}

// 戦いの 呪文・特技の 一覧: 長おし・Yキーで お気に入り（第27回）の ひとこと を そえる
export function favHint(text, touch = false) {
  if (!text) return text;
  if (touch) return text.replace('▶もう一度タップで使う', '▶もう一度タップで使う・長おしでお気に入り');
  // 第69回: 種類（タブ）は L・R（キーボードの Q・E）で かえる
  return `${text}\n（L・R〈Q・E〉で種類を切りかえ）\n（長おし・Yキーでお気に入り）`;
}

// 第71回: 戦いの 技の せつめいの ☆お気に入り ボタンの 下の ひとこと（どう おせば お気に入りに できるか）
//   スマホ: 長おし / キーボード・ゲームパッド: Y（on: もう お気に入り → はずす）
export function favKeyHint(touch = false, on = false) {
  return `${touch ? '長おし' : 'Y'}：${on ? 'はずす' : 'お気に入り'}`;
}

// 道具の せつめい（戦いの 中）
export function battleItemText(id, { touch = false } = {}) {
  const it = ITEMS[id];
  if (!it) return '';
  const lines = itemLines(it);
  if (touch) lines.push('▶もう一度タップで使う');
  return lines.join('\n');
}

// 道具の 1〜3行め（だれに・効果・せつめい）。戦いと メニューで おなじ 文
function itemLines(it) {
  const lines = [`【道具】${ITEM_TARGET[it.target] || '自分'}`];
  const pw = partText(it.effect, 1);
  if (pw) lines.push(`効果：${pw}`);
  if (it.desc) lines.push(it.desc);
  return lines;
}

// どこで 使えるか（第27回 メニューの 道具）
export function itemWhereText(it) {
  if (!it || it.type !== 'use') return '';
  if (it.battle && it.field) return '使える所：戦い・フィールド';
  if (it.battle) return '使える所：戦いだけ';
  if (it.field) return '使える所：フィールドだけ（戦いでは使えない）';
  return '';
}

// メニューの「道具」の せつめい（第27回）。使う 道具は 戦いと おなじ 文（だれに・効果・せつめい）＋ 使える所。
// 装備・素材・大事な物は info.js の itemDetail（強さ・装備できる 人）。touch: スマホで「もう一度タップで…」
const GEAR = ['weapon', 'armor', 'shield', 'head', 'acc'];
export function menuItemText(id, { touch = false, mons = null } = {}) {
  const it = ITEMS[id];
  if (!it) return '';
  const lines = it.type === 'use' && it.effect ? [...itemLines(it), itemWhereText(it)] : [itemDetail(id, mons)];
  if (touch && it.type !== 'key') lines.push(`▶もう一度タップで${it.type === 'use' && it.field ? '「使う」など' : GEAR.includes(it.type) ? '「装備する」など' : '「捨てる」など'}`);
  return lines.filter(Boolean).join('\n');
}

js/client/ui/soundtest.js:
// 第77回 D: 設定 →「音楽を聞く」（聞いた ことの ある 曲の 一覧。新しい音 ／ 前の音 の 聞きくらべ。場面で かわる 音楽を ためす）
//   曲を えらぶと 鳴る。強さ・ピンチ・だん・昼と夜・まわりの音は 新しい音で 次の 小節から かわる
//   タッチ・マウス・キーボード・コントローラー どれでも（ListMenu。左右で 強さ・だんを かえる）
//   とじると ためした 場面の 音楽を もとに もどして、今の 場所の 曲に もどる
import { el, ListMenu } from './dom.js';
import { TRACK_IDS } from '../audio.js';
import { trackName, AMBIENCE_NAMES } from '../audio-names.js';
import { AMBIENCES } from '../music-amb.js';

const Z = 8;
const INT_STEPS = [0, 0.25, 0.5, 0.75, 1];

const CSS = `
.sound-test { width: min(94vw, 520px); }
.sound-test .menu { overflow-y: auto; min-height: 0; }
.sound-test .item.st-ctl > .l { color: var(--accent); }
.sound-test .item.st-now > .r { color: var(--accent); }
.sound-test .st-note { white-space: pre-line; }
`;

function addCss() {
  if (typeof document === 'undefined' || document.getElementById('soundtest-css')) return;
  const st = document.createElement('style');
  st.id = 'soundtest-css';
  st.textContent = CSS;
  document.head.append(st);
}

export function openSoundTest(g) {
  addCss();
  return new Promise((resolve) => {
    const au = g.audio;
    const sfx = (x) => au?.sfx(x);
    const before = { amb: au.ambience, tod: au.adaptive.want.tod, autoResume: au.autoResume };
    // ジングルの あとに 前の 曲へ もどらない（えらんだ 曲だけ 鳴らす）
    au.autoResume = false;
    const st = { intensity: 1, pinch: false, phase: 0, tod: before.tod, amb: null };
    let playing = null;
    const heard = () => au.heardTracks();
    const ids = () => TRACK_IDS.filter((id) => id in heard());
    const bars = (v) => '■'.repeat(Math.round(v * 4)) + '□'.repeat(4 - Math.round(v * 4));
    const rows = () => {
      const h = heard();
      const list = ids();
      const items = [
        { label: playing ? `止める（${trackName(playing, h)}）` : '止める', value: 'stop', cls: 'st-ctl' },
        { label: `音：${au.engineMode === 'old' ? '前の音' : '新しい音'}`, right: '聞きくらべ', value: 'mode', cls: 'st-ctl' },
        { label: `強さ：${bars(st.intensity)}`, right: '◀▶', value: 'int', cls: 'st-ctl' },
        { label: `ピンチ：${st.pinch ? 'ON' : 'OFF'}`, value: 'pinch', cls: 'st-ctl' },
        { label: `だん：${st.phase + 1}`, right: '◀▶', value: 'phase', cls: 'st-ctl' },
        { label: `昼と夜：${st.tod === 'night' ? '夜' : '昼'}`, value: 'tod', cls: 'st-ctl' },
        { label: `まわりの音：${st.amb ? AMBIENCE_NAMES[st.amb] : 'なし'}`, right: '◀▶', value: 'amb', cls: 'st-ctl' },
        { header: true, label: `曲（${list.length}/${TRACK_IDS.length}曲）` },
      ];
      if (!list.length) items.push({ label: 'まだ聞いた曲がない', value: 'none', disabled: true });
      for (const id of list) items.push({ label: trackName(id, h), right: id === playing ? '♪' : '', value: `tr:${id}`, cls: id === playing ? 'st-now' : '' });
      return items;
    };
    const back = el('div', { class: 'modal-back', style: { zIndex: Z }, onclick: () => { sfx('cancel'); close(); } });
    const box = el('div', { class: 'win panel center-panel sound-test', style: { zIndex: Z + 1, background: 'var(--win-solid)' } },
      el('div', { class: 'small gold', text: `音楽を聞く（${ids().length}/${TRACK_IDS.length}曲）` }));
    const apply = () => {
      au.setIntensity(st.intensity);
      au.setPinch(st.pinch);
      au.setPhase(st.phase);
      au.setTimeOfDay(st.tod);
    };
    const play = (id) => {
      playing = id;
      au.play(id, { force: true });
      // 曲が かわると ピンチ・だんは もとに もどるので、えらんで いる 値を もう一度
      apply();
    };
    const change = (v, d) => {
      if (v === 'int') st.intensity = INT_STEPS[Math.max(0, Math.min(INT_STEPS.length - 1, INT_STEPS.indexOf(st.intensity) + d))];
      else if (v === 'phase') st.phase = Math.max(0, Math.min(3, st.phase + d));
      else if (v === 'amb') {
        const list = [null, ...AMBIENCES];
        st.amb = list[(list.indexOf(st.amb) + d + list.length) % list.length];
        au.playAmbience(st.amb);
      } else return false;
      apply();
      return true;
    };
    const m = new ListMenu(g.input, {
      items: rows(),
      back: '閉じる',
      sound: sfx,
      onSelect: (it) => act(it.value),
      onCancel: () => close(),
      onSide: (d) => {
        const it = m.items[m.idx];
        if (it && change(it.value, d)) {
          sfx('cursor');
          refresh();
        }
      },
    });
    const note = el('div', { class: 'detail small st-note', text: '曲を選ぶと鳴る（聞いたことのある曲だけ）。「音」で新しい音と前の音を聞きくらべられる。\n強さ・ピンチ・だん・昼と夜・まわりの音は、新しい音で次の小節から変わる（ゲームの場面で変わる音楽のためし）。' });
    box.append(m.root, note);
    document.getElementById('ui').append(back, box);
    m.focus();
    const refresh = () => {
      if (!box.isConnected) return;
      const idx = m.idx;
      m.setItems(rows());
      m.idx = Math.min(idx, m.items.length - 1);
      m.render();
    };
    const act = (v) => {
      if (v === 'stop') {
        playing = null;
        au.stop(0.3);
      } else if (v === 'mode') {
        au.setEngineMode(au.engineMode === 'old' ? 'new' : 'old');
        if (playing) apply();
      } else if (v === 'pinch') {
        st.pinch = !st.pinch;
        apply();
      } else if (v === 'tod') {
        st.tod = st.tod === 'night' ? 'day' : 'night';
        apply();
      } else if (!change(v, 1) && typeof v === 'string' && v.startsWith('tr:')) {
        play(v.slice(3));
      }
      refresh();
    };
    const close = () => {
      m.blur();
      back.remove();
      box.remove();
      // ためした ことを もとに もどす
      au.adaptive.byTrack.clear();
      au.setTimeOfDay(before.tod);
      au.setIntensity(1);
      au.setPinch(false);
      au.setPhase(0);
      au.playAmbience(before.amb);
      au.autoResume = before.autoResume;
      au.resumeTrack = null;
      let bgm = null;
      try { bgm = g.field?.areaBgm?.(); } catch { /* */ }
      if (bgm) au.play(bgm, { force: true });
      else au.stop(0.3);
      resolve();
    };
  });
}

js/client/ui/sources.js:
// 第64回 ⑥a: 足りない 素材の 入手先を 見る（ふしぎなかじ・れん金がま）と、その 魔物を さがす（フィールドで 赤く 点めつ）
//   入手先は shared/item-sources.js（魔物は 出る 場所・ダンジョンの 名前。図鑑で 見て いない 魔物は ？？？で 場所だけ）
//   魔物を えらぶと game.hunt に 入れる。フィールドの その 魔物（いっしょに いる 群れも）が 赤く 光る（field.js）
//   素材が 手に入るか、ボタンの「やめる」で おわる（HuntButton）
import { el, esc, toast } from './dom.js';
import { ITEMS } from '../../shared/data/items.js';
import { MONSTERS } from '../../shared/data/monsters.js';
import { itemCount } from '../../shared/stats.js';
import { itemSources, sourceText } from '../../shared/item-sources.js';

const nameOf = (id) => ITEMS[id]?.name || id;
const seenBy = (c) => (sp) => !!c?.bestiary?.[sp];

// lacks: [{ id, need, have }]。ct … ui/counter.js の まど
export async function sourcesFlow(game, ct, lacks) {
  if (!lacks?.length) return;
  const yes = await ct.ask('足りない素材の入手先を見るか？');
  if (ct.closed || yes !== 0) return;
  let id = lacks[0].id;
  if (lacks.length > 1) {
    await ct.say('どの素材の入手先を見る？');
    const p = await ct.pick(lacks.map((x) => ({ label: nameOf(x.id), right: `${x.have}/${x.need}`, rightCls: 'dis', value: x.id })));
    if (ct.closed || !p) return;
    id = p.value;
  }
  const list = itemSources(id, seenBy(game.me));
  if (!list.length) {
    await ct.say(`${nameOf(id)}の入手先は、まだわからない。\n宝の地図の洞窟や、ひみつの場所を探してみよう。`);
    await ct.tap(2400);
    return;
  }
  await ct.say(`${nameOf(id)}の入手先だ。\n魔物を選ぶと、フィールドで赤く光らせるぞ。`);
  const rows = list.slice(0, 12).map((s, i) => ({
    html: esc(sourceText(s)),
    value: i,
    disabled: s.kind !== 'monster' || !s.places.length,
  }));
  const p = await ct.pick(rows, { back: 'もどる' });
  if (ct.closed || !p) return;
  const s = list[p.value];
  if (s?.kind !== 'monster') return;
  setHunt(game, s.species, id);
  toast(`${s.seen ? s.name : '？？？'}（${s.places.slice(0, 2).join('・')}）が、フィールドで赤く光るよ`, 4500);
}

// さがす 魔物を きめる（同じ 魔物を もう一度 えらぶと そのまま）
export function setHunt(game, species, item) {
  game.hunt = { species, item, have: itemCount(game.me, item), name: MONSTERS[species]?.name || '' };
}

// フィールドの まもの（sp … すがた・gs … いっしょに いる 群れ）が さがしている 魔物か
export function huntMatch(hunt, sym) {
  if (!hunt || !sym) return false;
  return sym.sp === hunt.species || (Array.isArray(sym.gs) && sym.gs.includes(hunt.species));
}

const CSS = `
.hud-btn.hud-hunt { color: #ffd0c8; border-color: #ff6a5a; }
`;

// フィールドの ボタンの 列に「さがす：〇〇（やめる）」
export class HuntButton {
  constructor(game) {
    this.game = game;
    if (!document.getElementById('hunt-btn-css')) document.head.append(el('style', { id: 'hunt-btn-css', text: CSS }));
    this.btn = el('button', { class: 'win hud-btn hud-hunt', text: '', onclick: () => this.stop() });
    this.btn.hidden = true;
    game.hud.btns.append(this.btn);
  }

  update() {
    const g = this.game;
    const h = g.hunt;
    if (h && g.me && itemCount(g.me, h.item) > h.have) {
      toast(`${nameOf(h.item)}を手に入れた！（さがすのをやめた）`, 4000);
      g.hunt = null;
    }
    const show = !!g.hunt && g.state === 'field';
    if (show) {
      const label = `さがす：${nameOf(g.hunt.item)}（やめる）`;
      if (this.btn.textContent !== label) this.btn.textContent = label;
    }
    if (this.btn.hidden === show) this.btn.hidden = !show;
  }

  stop() {
    const g = this.game;
    if (!g.hunt) return;
    g.hunt = null;
    g.audio?.sfx?.('cancel');
    toast('さがすのをやめた');
    this.update();
  }
}

js/client/ui/stamps.js:
// 第50回 N7: 「スタンプを変える」まど（HUD の スタンプの さいごの 行・設定 から。ことばは shared/data/stamps.js）
//   ばしょ（1〜12）を えらぶ →「ことばを選ぶ」（なかまわけの 一覧）・「自分で書く」・ひとつ前へ／うしろへ・はずす
//   「もとにもどす」で はじめの スタンプへ。かえる たびに サーバーへ おくる（menuAction の 'stamps'）
//   タッチ・マウス・キーボード・コントローラー どれでも（ListMenu・askText・confirmBox）
import { el, ListMenu, askText, confirmBox } from './dom.js';
import {
  STAMP_SLOTS, STAMP_LEN, stampPresetsOf, DEFAULT_STAMPS, stampsOf, cleanStampText, putStamp, dropStamp, moveStamp,
} from '../../shared/data/stamps.js';

const Z = 8; // メニューの えらぶ まど（4・5）より 前、たしかめる まど（20）より うしろ

// 小さな えらぶ まど（えらんだ value。やめる なら null）
function pickBox(g, title, items, { cols = 1, start = -1 } = {}) {
  return new Promise((resolve) => {
    const sfx = (x) => g.audio?.sfx(x);
    const back = el('div', { class: 'modal-back', style: { zIndex: Z + 2 }, onclick: () => { sfx('cancel'); done(null); } });
    const box = el('div', { class: 'win panel center-panel stamp-pick', style: { width: cols > 1 ? 'min(94vw, 460px)' : 'min(86vw, 360px)', zIndex: Z + 3, background: 'var(--win-solid)' } },
      el('div', { class: 'small gold', text: title }));
    const m = new ListMenu(g.input, { items, cols, sound: sfx, back: 'もどる', start, onSelect: (it) => done(it.value), onCancel: () => done(null) });
    box.append(m.root);
    document.getElementById('ui').append(back, box);
    m.focus();
    const done = (v) => {
      m.blur();
      back.remove();
      box.remove();
      resolve(v ?? null);
    };
  });
}

// ことばを 選ぶ（なかまわけ → ことば）。えらんだ ことば（やめる なら null）
async function pickPreset(g, now) {
  for (;;) {
    // 第78回 3-10: 家族ミッションで もらった スタンプも（shared/data/stamps.js の stampPresetsOf）
    const presets = stampPresetsOf(g.me);
    const cat = await pickBox(g, 'どんなことば？', presets.map((p, i) => ({ label: p.name, right: `${p.list.length}こ`, value: i })));
    if (cat === null) return null;
    const list = presets[cat].list;
    const v = await pickBox(g, presets[cat].name, list.map((s) => ({ label: s, value: s })), { cols: 2, start: list.indexOf(now) });
    if (v !== null) return v;
  }
}

// まどを 開く。とじたら おわる Promise
export function openStampEditor(g) {
  return new Promise((resolve) => {
    const sfx = (x) => g.audio?.sfx(x);
    let list = stampsOf(g.me);
    const save = (next) => {
      list = next;
      // 先に 自分の 画面へ（サーバーの 返事 self でも おなじに なる）
      if (g.me) {
        if (next.length === DEFAULT_STAMPS.length && next.every((s, i) => s === DEFAULT_STAMPS[i])) delete g.me.stamps;
        else g.me.stamps = next.slice();
      }
      g.net.send({ t: 'menu', action: 'stamps', list: next });
    };
    const rows = () => {
      const items = [];
      for (let i = 0; i < STAMP_SLOTS; i++) {
        const s = list[i];
        // あいている ところは 1つだけ えらべる（つぎに うまる ところ）
        items.push(s ? { label: s, right: `${i + 1}`, value: i } : { label: '（あき）', right: `${i + 1}`, value: i, cls: 'muted', disabled: i > list.length });
      }
      items.push({ label: 'もとにもどす', value: 'reset', cls: 'stamp-edit' });
      return items;
    };
    const back = el('div', { class: 'modal-back', style: { zIndex: Z }, onclick: () => { sfx('cancel'); close(); } });
    const box = el('div', { class: 'win panel center-panel stamp-editor', style: { width: 'min(94vw, 460px)', zIndex: Z + 1, background: 'var(--win-solid)' } },
      el('div', { class: 'small gold', text: 'スタンプを変える（変えたいところを選ぶ）' }));
    const m = new ListMenu(g.input, {
      items: rows(),
      cols: 2,
      fit: true,
      back: '閉じる',
      sound: sfx,
      onSelect: (it, idx) => act(it.value, idx),
      onCancel: () => close(),
    });
    const note = el('div', { class: 'detail small', text: `チャットのスタンプを${STAMP_SLOTS}こまで選べる。自分で書くときは${STAMP_LEN}文字まで。` });
    box.append(m.root, note);
    document.getElementById('ui').append(back, box);
    m.focus();
    const again = (idx) => {
      if (!box.isConnected) return;
      m.setItems(rows());
      if (idx >= 0 && idx < m.items.length && !m.items[idx].disabled) {
        m.idx = idx;
        m.render();
      }
      m.focus();
    };
    const close = () => {
      m.blur();
      back.remove();
      box.remove();
      resolve();
    };
    const act = async (v, idx) => {
      m.blur();
      if (v === 'reset') {
        const ok = await confirmBox(g.input, 'スタンプを、最初のスタンプにもどしますか？', 'もどす', 'やめる', sfx);
        if (ok) save(DEFAULT_STAMPS.slice());
        return again(idx);
      }
      const i = v;
      const now = list[i];
      const opts = [{ label: 'ことばを選ぶ', value: 'preset' }, { label: '自分で書く', value: 'write' }];
      if (now) {
        opts.push({ label: 'ひとつ前へ', value: 'up', disabled: i === 0 },
          { label: 'ひとつうしろへ', value: 'down', disabled: i >= list.length - 1 },
          { label: 'はずす', value: 'drop', disabled: list.length <= 1 });
      }
      const what = await pickBox(g, now ? `${i + 1}ばんめ「${now}」` : `${i + 1}ばんめ（あき）`, opts);
      let at = idx;
      if (what === 'preset') {
        const s = await pickPreset(g, now);
        if (s) save(putStamp(list, i, s));
      } else if (what === 'write') {
        const s = cleanStampText(await askText(g.input, { title: `スタンプのことば（${STAMP_LEN}文字まで）`, max: STAMP_LEN, initial: now || '', placeholder: 'がんばろう！' }) || '');
        if (s) save(putStamp(list, i, s));
        // 決めた Enter が この まどの 決定に ならないように、すこし まってから もどる
        await new Promise((r) => setTimeout(r, 80));
      } else if (what === 'up' || what === 'down') {
        const d = what === 'up' ? -1 : 1;
        save(moveStamp(list, i, d));
        at = idx + d; // カーソルも いっしょに うごく
      } else if (what === 'drop') {
        save(dropStamp(list, i));
      }
      again(at);
    };
  });
}

js/client/ui/storage.js:
// 魔物あずかり所（第43回 C。ドラクエ風の カウンター。きまりは shared/world/storage.js）
//
// 「どうする？」→ 魔物をあずける／魔物をひきとる／やめる
//   あずける: 仲間の 魔物を えらぶ（パーティー・馬車に いても よい。装備は ふくろへ）→「〇〇をあずかるね。いい？」
//   ひきとる: あずかり中の 魔物を えらぶ → 酒場へ（仲間が いっぱい〈40〉なら できない）
import { el, esc } from './dom.js';
import { Counter } from './counter.js';
import { request } from './shop.js';
import { faceURL } from '../field.js';
import { boardIconURL } from '../render/boards.js';
import { MONSTERS } from '../../shared/data/monsters.js';
// 第53回 D: 色ちがいの 仲間の 絵
import { colorMon } from '../../shared/data/variants.js';

const AGAIN = 'ほかにもご用はある？';

// みぎの まど: 数と せつめい
function summary(data, hint = '') {
  const box = el('div', { class: 'ct-item bank-sum' });
  box.append(
    el('div', { class: 'hd' }, el('span', { class: 'gold', text: '魔物あずかり所' })),
    el('div', { class: 'bank-row' }, el('span', { text: 'あずけている魔物' }), el('span', { class: 'gold', text: `${data.stored.length}／${data.storageMax}ひき` })),
    el('div', { class: 'bank-row' }, el('span', { text: '仲間' }), el('span', { text: `${data.rosterCount}／${data.rosterMax}` })),
  );
  box.append(el('div', { class: 'detail small', text: hint || 'あずけた魔物は戦わないし、育たない。\n酒場の配合では、親に選べる（「あずかり中」のしるし）。' }));
  return box;
}

const HINTS = {
  deposit: '仲間の魔物をあずける。\nパーティーや馬車にいても、あずけられる（装備はふくろへ）。\n人間の仲間はあずけられない。',
  withdraw: 'あずけた魔物をひきとる。\nひきとった魔物は、酒場で待っている。\n仲間がいっぱいの時は、ひきとれない。',
  exit: '',
};

const row = (e) => ({
  value: e.key,
  face: faceURL({ mon: colorMon(e.species, e.color) }),
  label: e.name,
  html: `${esc(e.name)}${e.plus ? `<span class="plus">+${e.plus}</span>` : ''} <span class="muted small">${esc(MONSTERS[e.species]?.name || '')} Lv${e.level}</span>`,
  right: e.where,
});

export async function storageUI(game, data) {
  let info = data;
  const ct = new Counter(game, { title: info.name || '魔物あずかり所', keeper: info.keeper || 'あずかり所の人', icon: boardIconURL('monster') });
  let line = info.hello || 'ここは魔物あずかり所。\nどうする？';
  while (!ct.closed) {
    await ct.say(line);
    ct.info(summary(info));
    const cmd = await ct.pick([
      { label: '魔物をあずける', value: 'deposit' },
      { label: '魔物をひきとる', value: 'withdraw' },
      { label: 'やめる', value: 'exit' },
    ], { back: null, onMove: (x) => ct.info(summary(info, HINTS[x?.value])) });
    if (ct.closed) return;
    if (!cmd || cmd.value === 'exit') break;
    info = await loop(game, ct, info, cmd.value === 'deposit');
    line = AGAIN;
  }
  if (ct.closed) return;
  ct.list(null);
  ct.info(summary(info));
  await ct.say('またおいでね。\n魔物たちは、ちゃんとめんどうを見ておくよ。');
  await ct.tap(1400);
  ct.close();
}

// あずける・ひきとる を くりかえす。もどりち: 新しい info
async function loop(game, ct, info, deposit) {
  let line = deposit ? 'どの魔物をあずける？' : 'どの魔物をひきとる？';
  let idx = 0;
  while (!ct.closed) {
    const list = deposit ? info.roster : info.stored;
    if (!list.length) {
      ct.list(null);
      ct.info(summary(info));
      await ct.say(deposit ? 'あずけられる魔物の仲間がいないみたい。' : '今は、だれもあずかっていないよ。');
      await ct.tap(1800);
      return info;
    }
    if (deposit && info.stored.length >= info.storageMax) {
      await ct.say(`ごめんね、あずかり所はいっぱいなんだ（${info.storageMax}ひきまで）。`);
      await ct.tap(1800);
      return info;
    }
    if (!deposit && info.rosterCount >= info.rosterMax) {
      await ct.say(`仲間がいっぱいだね（${info.rosterMax}）。\n酒場でだれかと別れるか、先にほかの魔物をあずけてね。`);
      await ct.tap(2200);
      return info;
    }
    await ct.say(line);
    const rows = list.map(row);
    const it = await ct.pick(rows, { start: Math.min(idx, rows.length - 1), onMove: () => ct.info(summary(info, HINTS[deposit ? 'deposit' : 'withdraw'])) });
    if (ct.closed || !it) return info;
    idx = rows.findIndex((r) => r.value === it.value);
    const e = list.find((x) => x.key === it.value);
    const yes = await ct.ask(deposit ? `${e.name}をあずかるね。いい？${e.where === 'いっしょ' ? '\n（パーティーや馬車からはなれる）' : ''}` : `${e.name}を酒場へ送るね。いい？`);
    if (ct.closed) return info;
    if (yes !== 0) {
      line = deposit ? 'ほかにあずける魔物はいる？' : 'ほかにひきとる魔物はいる？';
      continue;
    }
    const res = await request(game, { kind: 'storage', action: deposit ? 'deposit' : 'withdraw', key: e.key });
    if (ct.closed) return info;
    if (res.storage) info = res.storage;
    if (res.ok) game.audio.sfx(deposit ? 'leave' : 'join');
    ct.info(summary(info));
    await ct.say(res.text || 'あれ？何かおかしいみたい。', { narr: !!res.ok });
    await ct.tap(1600);
    line = deposit ? 'ほかにあずける魔物はいる？' : 'ほかにひきとる魔物はいる？';
  }
  return info;
}

js/client/ui/subquest-hints.js:
// 第50回 N4: 困っている人（まだ 受けていない たのまれごと。shared/data/subquest-hints.js）
//   ・クエストの 画面に「困っている人」の 一らん（場所と 人と ひとこと）。「クエスト」を えらぶと 1人ずつ 見られて、地図に 黄色の しるし
//   ・新しく 困っている人が 出たら 知らせ（1回だけ）。クエストの 画面を 見るまで メニューに ●
import { el, toast } from './dom.js';
import { availableSubQuests, newAsks, askLine, askJobNote, askToastText, setAskPin, askPin } from '../../shared/data/subquest-hints.js';

const CSS = `
.qdot.ask { background: #ffd84a; }
.ask-row .l { white-space: normal; }
.ask-row .ap { color: var(--muted); font-size: 0.85em; margin-right: 0.3em; }
.ask-list .ah { color: var(--muted); font-size: 0.9em; margin: 0 0 0.25em 1.2em; white-space: pre-line; }
.ask-body { white-space: pre-line; line-height: 1.6; }
`;
function addCss() {
  if (typeof document === 'undefined' || document.getElementById('r50-ask-css')) return;
  const st = document.createElement('style');
  st.id = 'r50-ask-css';
  st.textContent = CSS;
  document.head.append(st);
}

// 見た ことに する（クエストの 画面を 見たら サーバーに 送る）。
// メニューを とじるまでは「（新しい）」の まま（recent。AskWatcher が とじた 時に けす）
const recent = new Set();
function freshIds(g) {
  const fresh = newAsks(g.me, 'seen').map((q) => q.id);
  for (const id of fresh) recent.add(id);
  if (fresh.length) g.net.send({ t: 'menu', action: 'subAsk', kind: 'seen', ids: fresh });
  return recent;
}
// 新しい 人を 先に
const newFirst = (list, fresh) => [...list.filter((q) => fresh.has(q.id)), ...list.filter((q) => !fresh.has(q.id))];
const PREVIEW_MAX = 6;

// クエストの 画面（右の 見本）に 入れる 一らん
export function askSection(g) {
  addCss();
  const c = g.me;
  const list = availableSubQuests(c);
  const box = el('div', { class: 'ask-list' });
  box.append(el('h3', { style: { marginTop: '0.6em' }, text: '困っている人' }));
  if (!list.length) {
    box.append(el('div', { class: 'muted small', text: '今は、だれも困っていないみたい。お話が進むと、また困っている人が出てくるよ。' }));
    return box;
  }
  const unseen = freshIds(g);
  const pin = askPin();
  const shown = newFirst(list, unseen);
  for (const q of shown.slice(0, PREVIEW_MAX)) {
    box.append(el('div', { class: 'kv' }, el('span', {}, el('i', { class: 'qdot ask' }), `${q.place}の、${q.who}${unseen.has(q.id) ? '（新しい）' : ''}${pin === q.id ? '（しるし）' : ''}`)));
    box.append(el('div', { class: 'ah', text: `${q.hint}${askJobNote(q, c) ? `\n${askJobNote(q, c)}` : ''}` }));
  }
  const more = shown.length - PREVIEW_MAX;
  box.append(el('div', { class: 'small muted', text: `${more > 0 ? `ほかに${more}人。` : ''}「クエスト」を選ぶと、全部の人が見られて、会いに行く人に地図の黄色のしるしをつけられる。` }));
  return box;
}

// 「クエスト」を えらんだ 時: 1人ずつ 見て、地図に しるし（menu: FieldMenu）。困っている人が いない ときは null
export function askView(menu) {
  addCss();
  const g = menu.game;
  const c = g.me;
  const all = availableSubQuests(c);
  if (!all.length) return null;
  const unseen = freshIds(g);
  const list = newFirst(all, unseen);
  const box = el('div', { class: 'items-view ask-view' });
  const detail = el('div', { class: 'detail item-detail ask-body' });
  const pin = askPin();
  const rows = list.map((q) => ({
    html: `<span class="ap">${q.place}</span>${q.who}${unseen.has(q.id) ? '（新しい）' : ''}${pin === q.id ? '（しるし）' : ''}`,
    value: q.id,
    cls: 'ask-row',
  }));
  const show = (it) => {
    const q = list.find((x) => x.id === it?.value);
    detail.innerHTML = '';
    if (!q) return;
    const job = askJobNote(q, c);
    detail.append(el('div', { text: `${askLine(q)}\n${q.hint}${job ? `\n${job}` : ''}\n${askPin() === q.id ? '（地図に黄色のしるしがついている。もう一度選ぶと消す）' : '（選ぶと、地図に黄色のしるしをつける）'}` }));
  };
  const m = menu.mkSub({
    items: rows,
    onMove: (it) => show(it),
    onSelect: (it) => {
      const q = list.find((x) => x.id === it.value);
      if (!q) return;
      const on = askPin() !== q.id;
      setAskPin(on ? q.id : null);
      toast(on ? `${q.place}の、${q.who}に、地図のしるしをつけた` : 'しるしを消した');
      menu.redraw();
    },
  });
  box.append(el('div', { class: 'small gold', text: '困っている人（選ぶと、地図に黄色のしるし）' }), m.root, detail);
  return box;
}

// 新しく 困っている人が 出たら 1回だけ 知らせる（hud.js の update から。フィールドで 何も して いない 時だけ）
export class AskWatcher {
  constructor(game) {
    this.game = game;
    this.sent = new Set();
  }

  update() {
    const g = this.game;
    if (!g.menuOpen) recent.clear();
    if (!g.me || g.state !== 'field' || g.busy || g.menuOpen) return;
    const fresh = newAsks(g.me, 'told').filter((q) => !this.sent.has(q.id));
    if (!fresh.length) return;
    for (const q of fresh) this.sent.add(q.id);
    toast(askToastText(fresh), 6000);
    g.net.send({ t: 'menu', action: 'subAsk', kind: 'told', ids: fresh.map((q) => q.id) });
  }
}

js/client/ui/sugoroku.js:
// 第37回 B: すごろく場の まど（受付 → すごろくの 盤）
//   さいころ・マスの できごと・こまの 場所は サーバー（shared/world/sugoroku.js）。ここは 見せるだけ
//   受付（Counter）: すごろくで あそぶ・すごろく券を 買う・あそび方
//   盤（casinoShell）: 盤の 絵（render/sugoroku.js）と、さいころ・分かれ道・宝部屋・お店・戦いの ボタン
//   戦いの マスで「戦う！」→ まどを とじる → 戦い（サーバーの だいほん）→ 終わると また この まどが 開く（盤は そのまま）
//   十字キー・A・B: ボタンを えらぶ（ui/padnav.js）。A で 決定・B で 閉じる（ことばは A・B・タップで すすむ）
// 第50回 D2: 豪華な えんしゅつ（render/sugoroku.js）・すごろくの 音（sfx-sugoroku.js）・あたらしい マス（ルーレット・宝探し・
//   すごろく商人・おみやげ・応援・落とし穴）・ゴールの 景品を 1つずつ 見せる。うごいて いる ときに タップ／A で 早おくり
import { el } from './dom.js';
import { itemInfo } from './counter.js';
import { request } from './shop.js';
import { padNav } from './padnav.js';
import { CasinoCounter, casinoShell, fmt, sendClose, helpBox } from './casino.js';
import { celebrate, stopFx } from './casino-fx.js';
import { boardIconURL } from '../render/boards.js';
import { iconURL, symbolURL } from '../render/casino.js';
import { SgBoardView, SQ_LOOK, dieURL } from '../render/sugoroku.js';
import { sgSound } from '../sfx-sugoroku.js';
import { rareNameHtml } from './rarity.js';
import { monsterCanvas } from '../render/monsters.js';
import { playerSprite } from '../field.js';
import { shownEquip } from '../../shared/look-equip.js';
import { ITEMS } from '../../shared/data/items.js';
import { MONSTERS } from '../../shared/data/monsters.js';
import { itemCount } from '../../shared/stats.js';
import { coinsOf, medalsHeld } from '../../shared/data/casino.js';
import { BOARD_BY_ID, DICE, TICKET_ITEM, SQ_NAME, squareText, WHEEL } from '../../shared/data/sugoroku.js';

const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const DIR = (b, from, to) => {
  const a = b.sq[from], t = b.sq[to];
  if (!a || !t) return '';
  if (t.x > a.x) return '→';
  if (t.x < a.x) return '←';
  return t.y > a.y ? '↓' : '↑';
};

// サーバーの へんじ（すごろくの ようす）を 受けとる
const sgReq = (game, msg) => request(game, { kind: 'casino', ...msg });

export async function sugorokuUI(game, data) {
  ensureSgStyle();
  let info = { ...data };
  // まどを 開いた ときの ようす（つなぎなおしで 古い まどの データが とどく ことが あるので、サーバーに 聞きなおす）
  const fresh = await sgReq(game, { action: 'sgState' });
  if (fresh.ok) info = { ...info, run: fresh.sg, tickets: fresh.tickets, medals: fresh.medals, coins: fresh.coins ?? info.coins, after: [...(info.after || []), ...(fresh.after || [])] };
  let result = 'close';
  for (let guard = 0; guard < 200; guard++) {
    if (!document.getElementById('ui')) break;
    if (info.run) {
      const r = await boardScreen(game, info);
      info.after = [];
      if (r === 'fight') { result = 'fight'; break; }
      if (r === 'close') break;
      // おわった・やめた → 受付へ
      const st = await sgReq(game, { action: 'sgState' });
      info = { ...info, run: st.sg ?? null, tickets: st.tickets ?? info.tickets, medals: st.medals ?? info.medals, last: null };
      if (st.clears) info.boards = info.boards.map((b) => ({ ...b, clears: st.clears[b.id] || 0 }));
      continue;
    }
    const r = await deskUI(game, info);
    if (!r) break;
    info = { ...info, run: r.sg, tickets: r.tickets, medals: r.medals, startOps: r.ops, last: null };
  }
  sendClose(game);
  return result;
}

// ───────────── 受付 ─────────────
class SgCounter extends CasinoCounter {
  updGold() {
    const me = this.game.me;
    if (!me || !this.goldEl) return;
    this.goldEl.innerHTML = '';
    this.goldEl.append(
      el('span', { class: 'cs-purse' }, el('img', { class: 'cs-ico', src: iconURL('coin'), alt: '' }), `${fmt(coinsOf(me))}枚`),
      el('span', { class: 'cs-purse sg-tk', text: `券 ${itemCount(me, TICKET_ITEM)}まい` }),
      el('span', { class: 'cs-purse' }, el('img', { class: 'cs-ico', src: iconURL('medal'), alt: '' }), `${medalsHeld(me)}まい`),
    );
  }
}

async function deskUI(game, info) {
  const ct = new SgCounter(game, { title: 'すごろく場', keeper: 'すごろく場の受付', icon: boardIconURL('casino'), purse: 'coins' });
  const t = info.tier || { tier: 0, clears: 0, left: 3 };
  const next = (info.boards || []).find((b) => !b.open);
  const note = next ? `\n（宝の地図をあと${next.left}こクリアすると「${next.name}」があらわれます）` : '';
  let line = `いらっしゃいませ！すごろく場へようこそ。\nすごろく券で、さいころのすごろくがあそべます。${note}`;
  // 負けて おわった（戦いの あと）: さいごの けっか
  if (info.last && info.last.reason === 'lose') {
    for (const a of info.last.after || []) {
      await ct.say(a, { narr: true });
      await ct.tap(2400);
    }
    line = `おかえりなさい。おつかれさまでした！${note}`;
  }
  let out = null;
  while (!ct.closed && !out) {
    await ct.say(line);
    ct.info(helpBox([
      `宝の地図をクリアした数: ${t.clears}こ（${t.name || ''}）`,
      'すごろく券は、コイン100枚で1まい。小さなメダル1まいで2まい。',
      'さいころをふれる回数がなくなるか、ゴールしたらおしまい。手に入れた物は持って帰れる。',
    ]));
    const cmd = await ct.pick([
      { label: 'すごろくであそぶ', value: 'play' },
      { label: 'すごろく券を買う', value: 'buy' },
      { label: 'あそび方を聞く', value: 'help' },
      { label: 'やめる', value: 'exit' },
    ], { back: null });
    if (ct.closed || !cmd || cmd.value === 'exit') break;
    if (cmd.value === 'help') {
      await howTo(ct);
      line = 'ほかに何かご用はありますか？';
      continue;
    }
    if (cmd.value === 'buy') {
      await buyTickets(game, ct, info);
      line = 'ほかに何かご用はありますか？';
      continue;
    }
    // すごろくを 選ぶ
    await ct.say('どのすごろくであそびますか？');
    const tk = itemCount(game.me, TICKET_ITEM);
    const rows = (info.boards || []).map((b) => ({
      value: b.id, label: b.name, b,
      right: b.open ? `券${b.tickets}まい` : `地図あと${b.left}こ`, rightCls: !b.open || tk < b.tickets ? 'dis' : 'gold',
    }));
    const pick = await ct.pick(rows, { back: 'もどる', onMove: (x) => ct.info(x ? boardInfo(x.b) : null) });
    if (ct.closed) break;
    if (!pick) { line = 'ほかに何かご用はありますか？'; continue; }
    const b = pick.b;
    if (!b.open) {
      game.audio.sfx('buzz');
      await ct.say(`「${b.name}」は、宝の地図をあと${b.left}こクリアすると、あそべるようになります。\n宝探しのダイゴさんのところへ行ってみては？`);
      await ct.tap(2600);
      line = 'ほかに何かご用はありますか？';
      continue;
    }
    if (itemCount(game.me, TICKET_ITEM) < b.tickets) {
      game.audio.sfx('buzz');
      const yes = await ct.ask(`「${b.name}」には、すごろく券が${b.tickets}まいいります。\n（今${itemCount(game.me, TICKET_ITEM)}まい）すごろく券を買いますか？`);
      if (ct.closed) break;
      if (yes === 0) await buyTickets(game, ct, info);
      line = 'ほかに何かご用はありますか？';
      continue;
    }
    const yes = await ct.ask(`「${b.name}」ですね。\nすごろく券を${b.tickets}まい使います。よろしいですか？`);
    if (ct.closed) break;
    if (yes !== 0) { line = 'ほかに何かご用はありますか？'; continue; }
    const r = await sgReq(game, { action: 'sgStart', board: b.id });
    ct.updGold();
    if (!r.ok || !r.sg) {
      game.audio.sfx('buzz');
      await ct.say(r.text || 'おや？何かおかしいようですね。');
      await ct.tap(2000);
      line = 'ほかに何かご用はありますか？';
      continue;
    }
    game.audio.sfx('confirm');
    await ct.say('それでは、いってらっしゃいませ！\nよい目が出ますように！');
    await ct.tap(1200);
    out = r;
  }
  if (!ct.closed && !out) {
    ct.list(null);
    ct.info(null);
    await ct.say('またのおこしをお待ちしております。');
    await ct.tap(1200);
  }
  ct.close();
  return out;
}

function boardInfo(b) {
  const B = BOARD_BY_ID[b.id];
  const lines = [b.desc, `さいころ: ${b.rolls}回 ／ すごろく券: ${b.tickets}まい`, b.open ? `ゴールした回数: ${b.clears}回` : `宝の地図をあと${b.left}こクリアすると、あそべる`];
  if (B?.goal?.first && !b.clears && b.open) lines.push(`初めてゴールすると「${ITEMS[B.goal.first]?.name}」ももらえる！`);
  if (B?.bosses?.length) lines.push(`ボス: ${B.bosses.map((x) => x.name).join('・')}`);
  return helpBox(lines);
}

async function howTo(ct) {
  const lines = [
    'すごろくは、さいころをふって、自分のこまを進めるあそびです。\nゴールにつくと、大きな景品がもらえます！',
    'さいころをふれる回数には、かぎりがあります。\nなくなると、そこでおしまい。それまでに手に入れた物は持って帰れます。',
    'マスには、ゴールド・道具・宿屋・わな・前へ／後ろへ・？？？などがあります。\n？？？は、止まった時のおたのしみ！',
    '宝の地図をたくさんクリアすると、大きなすごろくがあらわれます。\n分かれ道・戦い・ワープ・スイッチ・ボス・宝部屋・お店…\n上のすごろくほど、しかけもいっぱい！',
    'ボーナスチャンス・ルーレット・宝探し・すごろく商人・\n魔物のおみやげ・家族のおうえん・落とし穴の下の地下の道…\nたのしいマスもたくさん！ゴールの景品もすごいですよ。',
    'うごいているときに画面をタップするか、Aボタンをおすと、\nはやおくりできます。',
    '戦いのマスでは、本当に魔物と戦います。\n負けるとすごろくは終わりですが、お金はへりません。',
  ];
  for (const l of lines) {
    await ct.say(l);
    await ct.tap(6000);
    if (ct.closed) return;
  }
}

async function buyTickets(game, ct, info) {
  const price = info.ticketCoins || 100;
  const per = info.medalTickets || 2;
  const how = await ct.pick([
    { label: `コインで買う（1まい ${price}枚）`, value: 'coins', right: `${fmt(coinsOf(game.me))}枚`, rightCls: coinsOf(game.me) < price ? 'dis' : 'gold' },
    { label: `小さなメダルとこうかん（1まいで${per}まい）`, value: 'medal', right: `${medalsHeld(game.me)}まい`, rightCls: medalsHeld(game.me) < 1 ? 'dis' : 'gold' },
  ], { back: 'もどる' });
  if (ct.closed || !how) return;
  const coins = coinsOf(game.me);
  const max = how.value === 'coins' ? Math.min(info.buyMax || 20, Math.floor(coins / price), 99 - itemCount(game.me, TICKET_ITEM))
    : Math.min(10, medalsHeld(game.me), Math.floor((99 - itemCount(game.me, TICKET_ITEM)) / per));
  if (max < 1) {
    game.audio.sfx('buzz');
    await ct.say(how.value === 'coins' ? `コインが足りないようです。\nすごろく券は1まい${price}枚です。` : '小さなメダルを持っていないようです。');
    await ct.tap(2200);
    return;
  }
  const n = how.value === 'coins'
    ? await ct.qty('何まい買いますか？', max, null, `1まいでコイン${price}枚`)
    : await ct.qty('小さなメダルを何まいこうかんしますか？', max, null, `メダル1まいで、すごろく券${per}まい`);
  if (!n || ct.closed) return;
  const r = await sgReq(game, { action: 'sgBuy', pay: how.value, n });
  ct.updGold();
  if (!r.ok) {
    game.audio.sfx('buzz');
    await ct.say(r.text || 'おや？何かおかしいようですね。');
    await ct.tap(2000);
    return;
  }
  game.audio.sfx('coin');
  await ct.say(r.text, { narr: true });
  await ct.tap(2000);
}

// ───────────── 盤 ─────────────
function boardScreen(game, info) {
  return new Promise((resolve) => {
    const B = BOARD_BY_ID[info.run.board];
    const sh = casinoShell(game, { title: B.name, cls: 'sugoroku-panel' });
    sh.setCoins(info.coins ?? coinsOf(game.me));
    let run = info.run;
    let busy = false;
    let closed = false;
    let picking = null; // 数を 選ぶ さいころ（'pick' | 'gold'）
    let summary = null;
    let msgDone = null;

    const cv = el('canvas', { class: 'sg-canvas' });
    const wrap = el('div', { class: 'sg-wrap' }, cv);
    const hud = el('div', { class: 'sg-hud' });
    const msgText = el('div', { class: 'sg-msgtext' });
    const msgMore = el('div', { class: 'ct-more sg-more', text: '▼' });
    const msg = el('div', { class: 'cs-msg sg-msg', onclick: () => msgDone?.() }, msgText, msgMore);
    const extra = el('div', { class: 'sg-extra' });
    const controls = el('div', { class: 'cs-controls sg-controls' });
    const side = el('div', { class: 'win sg-side' }, hud, msg, extra, controls);
    sh.body.classList.add('sg-body');
    sh.body.append(el('div', { class: 'win sg-boardbox' }, wrap), side);
    const me = game.me;
    const eq = shownEquip(me);
    const view = new SgBoardView(cv, B, { sprite: (dir, f) => playerSprite(me.look, me.job, dir, f, eq) });
    view.setRun(run, { snap: true });

    // 盤を タップ: 光っている マス（分かれ道・竜の背）を 選ぶ・ほかの マスは 説明
    cv.addEventListener('click', (e) => {
      const r = cv.getBoundingClientRect();
      // うごいて いる ときは 早おくり
      if (busy) { view.speed = 3; msgDone?.(); return; }
      const s = view.squareAt(e.clientX - r.left, e.clientY - r.top);
      if (!s) return;
      const k = view.hl.indexOf(s.i);
      if (k >= 0 && run?.pending) return choose(k);
      if (!msgDone) setMsg(`${SQ_NAME[s.t]}のマス: ${squareText(B, s)}`);
    });

    const setMsg = (t) => { msgText.textContent = t; msgMore.hidden = true; };
    // ことば（A・B・タップで すすむ。ms で じどう）
    const say = (t, ms = 2600) => new Promise((res) => {
      if (view.speed > 1) ms = Math.min(ms, 900);
      msgText.textContent = t;
      msgMore.hidden = false;
      let timer = null;
      const done = () => {
        if (msgDone !== done) return;
        clearTimeout(timer);
        msgDone = null;
        msgMore.hidden = true;
        res();
      };
      msgDone = done;
      timer = setTimeout(done, ms);
    });

    const renderHud = () => {
      hud.innerHTML = '';
      if (!run) return;
      // のこりの 回数・ゴールまで・ボーナスは 盤の 上（render/sugoroku.js）。ここは 手に入れた 物
      const items = [
        el('span', { class: 'sg-chip gold', text: `+${fmt(run.gold)}G` }),
      ];
      if (run.bonus) items.push(el('span', { class: 'sg-chip bonus', text: '×2' }));
      if (B.stars.length) items.push(el('span', { class: 'sg-chip star', text: `★ ${run.stars.length}/${B.stars.length}` }));
      if (B.sq.some((s) => s.t === 'switch')) items.push(el('span', { class: 'sg-chip', text: `スイッチ ${run.sw ? 'ON' : 'OFF'}` }));
      const got = run.got.reduce((a, [, n]) => a + n, 0);
      if (got) items.push(el('span', { class: 'sg-chip', text: `手に入れた物 ${got}こ` }));
      if (run.coins) items.push(el('span', { class: 'sg-chip', text: `コイン+${fmt(run.coins)}` }));
      hud.append(...items);
    };

    const btn = (text, act, cls = '', disabled = false) => el('button', { class: `btn ${cls}`, text, disabled, onclick: () => { if (!busy) act(); } });

    const renderControls = () => {
      controls.innerHTML = '';
      view.hl = [];
      const add = (...b) => controls.append(...b);
      // おわった あとは けっか（extra）を のこす
      if (summary) {
        add(btn('受付にもどる', () => finish('desk'), 'primary cs-big'));
        refreshNav();
        return;
      }
      extra.innerHTML = '';
      if (!run) return;
      const p = run.pending;
      if (!p) {
        if (picking) {
          const max = picking === 'gold' ? 12 : 6;
          setMsg(`${DICE[picking].name}！\n進みたい数を選んでね。`);
          for (let n = 1; n <= max; n++) add(btn(String(n), () => roll(picking, n), 'sg-num'));
          add(btn('もどる', () => { picking = null; renderControls(); }, 'sg-small'));
        } else {
          add(btn('さいころをふる', () => roll('normal'), 'primary cs-big sg-roll'));
          for (const d of ['double', 'pick', 'gold']) {
            const n = run.dice?.[d] || 0;
            if (!n) continue;
            const b = el('button', { class: `btn sg-die ${d}`, onclick: () => { if (busy) return; if (d === 'double') roll('double'); else { picking = d; renderControls(); } } },
              el('img', { src: dieURL(d === 'double' ? 2 : d === 'gold' ? 6 : 3, d === 'gold'), alt: '' }), `${DICE[d].name} ×${n}`);
            add(b);
          }
          add(btn(view.mode === 'all' ? 'こまを見る' : 'ぜんたいを見る', () => { view.mode = view.mode === 'all' ? 'follow' : 'all'; renderControls(); }, 'sg-small'));
          add(btn('やめる', () => quit(), 'sg-small'));
        }
      } else if (p.kind === 'branch' || p.kind === 'dragon') {
        view.hl = p.options.slice();
        p.options.forEach((to, k) => {
          const s = B.sq[to];
          const lab = `${k + 1}. ${p.kind === 'branch' ? DIR(B, p.at, to) : '竜で'} ${SQ_NAME[s.t]}${p.kind === 'branch' ? 'の道' : 'のマスへ'}`;
          add(btn(lab, () => choose(k), 'sg-opt'));
        });
      } else if (p.kind === 'vault' || p.kind === 'hunt') {
        for (let k = 0; k < (p.n || 3); k++) add(el('button', { class: `btn sg-box ${p.kind}`, style: `animation-delay: ${k * 0.15}s`, onclick: () => { if (!busy) pickBox(k); } }, el('span', { class: 'sg-boxart', text: '宝' }), `宝箱${k + 1}`));
      } else if (p.kind === 'shop') {
        p.items.forEach((it, k) => {
          const ok = (game.me.gold || 0) >= it.price;
          const b = btn(`${ITEMS[it.id]?.name || it.id} ${fmt(it.price)}G${it.was ? `（もとは${fmt(it.was)}G）` : ''}`, () => buy(k), `sg-opt ${ok ? '' : 'dis'} ${it.was ? 'sale' : ''}`);
          b.addEventListener('focus', () => showItem(it.id));
          b.addEventListener('mouseenter', () => showItem(it.id));
          add(b);
        });
        add(btn('買わない', () => buy(-1), 'sg-small'));
        extra.append(el('div', { class: 'small muted', text: `所持金 ${fmt(game.me.gold)}G` }));
      } else if (p.kind === 'battle') {
        const box = el('div', { class: 'sg-mons' });
        for (const sp of p.mons || []) {
          const c = monsterCanvas(sp, 0, 40);
          if (c) { const img = el('img', { class: 'sg-mon', alt: MONSTERS[sp]?.name || '' }); img.src = c.toDataURL(); box.append(img); }
        }
        extra.append(box);
        add(btn(p.boss !== null && p.boss !== undefined ? 'ボスと戦う！' : '戦う！', () => fight(), 'primary cs-big'));
      }
      refreshNav();
    };

    const showItem = (id) => {
      extra.innerHTML = '';
      const node = itemInfo(game, id);
      if (node) extra.append(node);
    };

    // 音（sg_ … すごろくの 音。sfx-sugoroku.js）
    const sgs = (name, arg) => { if (!sgSound(game.audio, name, arg)) game.audio.sfx(name); };
    // ことばの 音と、盤の えんしゅつ（サーバーの sfx の なまえで きめる）
    const SAY_FX = {
      coin: ['sg_coins', 'coins'], chest: ['sg_chest', 'chest'], item: ['item', 'item'], heal: ['heal', 'heal'], hurt: ['sg_trap', 'trap'],
      buzz: ['buzz', 'buzz'], sparkle: ['sg_star', 'star'], win: ['win', 'star'], key: ['key', null], jackpot: [null, 'jackpot'],
      sg_bonus: ['sg_bonus', 'bonus'], sg_merchant: ['sg_merchant', 'merchant'], sg_gift: ['sg_gift', null], sg_cheer: ['sg_cheer', null],
      // うごく 音は つぎの jump で ならす
      warp: [null, null], sg_fall: [null, null], sg_ladder: [null, null],
    };
    const sfx = (name) => {
      if (!name) return;
      // 第50回 N5: 当たりは コインの 雨と 光も（casino-fx.js）。ゴールは 盤の 花火（view.celebrate）だけ
      if (name === 'fanfare') {
        game.audio.play('jackpot');
        sgs('sg_fanfare');
        view.onPop = () => sgs('sg_firework');
        view.celebrate();
        return;
      }
      if (name === 'jackpot') { game.audio.play('jackpot'); celebrate(game, { level: 'big', sound: false }); }
      else if (name === 'win') celebrate(game, { level: 'small', sound: false });
      const [snd, fx] = SAY_FX[name] || [name, null];
      if (snd) sgs(snd);
      if (fx) view.burst(fx);
    };
    const JUMP_SND = { fall: 'sg_fall', climb: 'sg_ladder', dragon: 'sg_warp', warp: 'sg_warp' };

    // サーバーの できごとを じゅんに 見せる
    const playOps = async (ops = []) => {
      for (const op of ops) {
        if (closed) return;
        switch (op.op) {
          case 'dice':
            // のこりの 回数は すぐ へらす（さいごに サーバーの ようすで そろう）
            if (run) { run = { ...run, rolls: Math.max(0, run.rolls - 1) }; view.setRun(run); }
            await view.rollDice(op.dice, op.die === 'gold' ? 12 : 6, sgs);
            setMsg(op.dice.length > 1 ? `${op.dice.join('と')}で${op.total}！` : `${op.total}が出た！`);
            view.hideDice();
            break;
          case 'move':
            await view.moveAlong(op.path, (n) => sgs('sg_step', op.back ? 0 : n));
            sgs('sg_land');
            break;
          case 'jump':
            sgs(JUMP_SND[op.how] || 'sg_warp');
            await view.jumpTo(op.to, op.how || 'warp');
            break;
          case 'switch':
            if (run) run.sw = op.sw;
            view.burst('switch');
            break;
          case 'slot':
            await showSlot(op.reels);
            break;
          case 'wheel':
            await view.spinWheel(WHEEL.map((w) => w.g), op.pick, sgs);
            break;
          case 'vault':
          case 'hunt':
            showVault(op);
            if (op.op === 'hunt') view.burst(op.hit ? 'chest' : 'buzz');
            break;
          case 'gift':
            view.burst('gift', { sp: op.sp });
            break;
          case 'cheer':
            view.burst('cheer', { name: op.name });
            break;
          case 'say':
            sfx(op.sfx);
            // ゴールの あとは 景品の カードを 先に 見せて、ことばは 少し 早く
            if (op.sfx === 'fanfare') {
              const over = ops.find((o) => o.op === 'over');
              if (over?.reveal) showReveal(over);
            }
            await say(op.text, revealEl ? 1700 : 2600);
            break;
          case 'over':
            summary = op;
            break;
          default:
        }
      }
    };

    // ゴールの 景品（カードが 1まいずつ ぽんと 出る）
    let revealEl = null;
    const TAG = { first: '初めて！', big: '大景品', extra: 'おまけ', stars: '星のおまけ' };
    const showReveal = (over) => {
      revealEl?.remove();
      const list = el('div', { class: 'sg-rv-list' });
      revealEl = el('div', { class: 'sg-reveal', onclick: () => { revealEl?.classList.add('out'); } },
        el('div', { class: 'sg-rv-title', text: over.first ? '初めてのゴール！' : 'ゴールの景品' }), list);
      // まず 花火と「ゴール！」を 見せてから
      const box = revealEl;
      setTimeout(() => { if (!closed && revealEl === box) wrap.append(box); }, 1500);
      (over.reveal || []).forEach((x, k) => {
        setTimeout(() => {
          if (closed || !revealEl) return;
          let card;
          if (x.gold !== undefined) {
            card = el('div', { class: 'sg-rv-card gold' }, el('span', { class: 'sg-rv-tag', text: '景品' }),
              el('span', { class: 'sg-rv-name', text: `${fmt(x.gold)}G${x.coins ? `＋コイン${fmt(x.coins)}枚` : ''}` }));
          } else {
            card = el('div', { class: `sg-rv-card ${x.tag || ''}` }, el('span', { class: 'sg-rv-tag', text: TAG[x.tag] || '' }),
              el('span', { class: 'sg-rv-name', html: `${rareNameHtml(x.id)}${x.n > 1 ? ` ×${x.n}` : ''}` }));
          }
          list.append(card);
          sgs('sg_reveal');
        }, 2100 + k * 520);
      });
    };

    const showSlot = async (reels) => {
      extra.innerHTML = '';
      const syms = ['seven', 'bar', 'star', 'bell', 'cherry'];
      const imgs = reels.map(() => el('img', { class: 'sg-slotsym', alt: '' }));
      extra.append(el('div', { class: 'sg-slot' }, ...imgs));
      for (let k = 0; k < 3; k++) {
        const t0 = performance.now();
        while (performance.now() - t0 < 380) {
          for (let j = k; j < 3; j++) imgs[j].src = symbolURL(syms[Math.floor(Math.random() * syms.length)]);
          await wait(60);
        }
        imgs[k].src = symbolURL(reels[k]);
        game.audio.sfx('reel');
      }
      await wait(300);
    };

    const showVault = (op) => {
      extra.innerHTML = '';
      const box = el('div', { class: 'sg-vault' });
      op.boxes.forEach((name, k) => box.append(el('div', { class: `sg-vbox ${k === op.picked ? 'on' : ''} ${name === 'からっぽ' ? 'empty' : ''}`, style: `animation-delay: ${k === op.picked ? 0 : 0.35 + k * 0.12}s` },
        el('span', { class: 'sg-boxart open', text: name === 'からっぽ' ? '空' : '宝' }), el('span', { text: name }))));
      extra.append(box);
    };

    // へんじを うけとって 見せる
    const apply = async (r) => {
      if (!r.ok) {
        game.audio.sfx('buzz');
        if (r.text) await say(r.text, 2200);
        if ('sg' in r) run = r.sg;
        return;
      }
      await playOps(r.ops);
      if (closed) return;
      run = r.sg ?? null;
      view.setRun(run, { snap: true });
      sh.setCoins(r.coins ?? coinsOf(game.me));
      if (!run && summary) showSummary();
    };

    const act = async (msgObj) => {
      if (busy || closed) return;
      busy = true;
      sh.lock(true);
      controls.querySelectorAll('button').forEach((b) => { b.disabled = true; });
      view.speed = 1;
      const r = await sgReq(game, msgObj);
      if (closed) return;
      await apply(r);
      view.speed = 1;
      busy = false;
      sh.lock(false);
      renderHud();
      renderControls();
      if (run?.pending) promptPending(true);
      else if (run && !summary) setMsg(`のこり${run.rolls}回。\nさいころをふろう！`);
    };

    // fresh … いま 止まった（戦いの ひかり）
    const promptPending = (fresh = false) => {
      const p = run.pending;
      if (fresh && p.kind === 'battle') {
        view.burst('battle');
        sgs('sg_battle');
      }
      if (p.kind === 'branch') setMsg('分かれ道だ！\nどちらへ進む？（光っているマスをタップしてもよい）');
      else if (p.kind === 'dragon') setMsg('竜の背！\nどこへ連れていってもらう？');
      else if (p.kind === 'vault') setMsg('宝部屋！\n3つの宝箱から、1つだけ選んで開けよう。');
      else if (p.kind === 'hunt') setMsg('宝探し！\nお宝が入っているのは、どの箱かな？');
      else if (p.kind === 'shop') setMsg(p.sale ? 'すごろく商人！\nどれでも半額。ゴールドで買える。' : 'お店のマス！\nすごろくの中だけの品。ゴールドで買える。');
      else if (p.kind === 'battle') setMsg(p.name ? `${p.name}が立ちはだかる！` : `${(p.mons || []).map((sp) => MONSTERS[sp]?.name).filter(Boolean).join('と')}があらわれた！`);
    };

    const roll = (die, n) => {
      picking = null;
      setMsg('えいっ！');
      return act({ action: 'sgRoll', die, ...(n ? { n } : {}) });
    };
    const choose = (i) => act({ action: 'sgChoose', i });
    const pickBox = (i) => act({ action: 'sgPick', i });
    const buy = (i) => act({ action: 'sgShop', i });
    const quit = async () => {
      if (busy) return;
      controls.innerHTML = '';
      setMsg('すごろくをやめますか？\n（今までに手に入れた物は持って帰れる。すごろく券はもどらない）');
      controls.append(btn('やめる', () => act({ action: 'sgQuit' }), 'sg-opt'), btn('つづける', () => { renderControls(); setMsg('さいころをふろう！'); }, 'primary'));
      refreshNav();
    };
    const fight = async () => {
      if (busy) return;
      busy = true;
      const r = await sgReq(game, { action: 'sgFight' });
      busy = false;
      if (!r.ok) { renderControls(); return; }
      game.audio.sfx('encounter');
      finish('fight');
    };

    const showSummary = () => {
      const s = summary;
      extra.innerHTML = '';
      const L = [];
      const why = { goal: 'ゴール！', rolls: 'さいころがなくなった', lose: '力つきた', quit: 'とちゅうでやめた' }[s.reason] || '';
      L.push(el('div', { class: 'gold sg-sumhead', text: `けっか: ${why}` }));
      L.push(el('div', { text: `ゴールド +${fmt(s.gold)}G${s.coins ? `／コイン +${fmt(s.coins)}枚` : ''}` }));
      for (const [id, n] of s.got || []) L.push(el('div', { class: s.prizes?.includes(id) ? 'gold' : '', text: `${ITEMS[id]?.name || id}${n > 1 ? ` ×${n}` : ''}` }));
      extra.append(el('div', { class: 'sg-sum scroll' }, ...L));
      setMsg(s.reason === 'goal' ? 'おめでとう！\n景品はふくろに入れておいたよ。' : 'おつかれさま！\n手に入れた物は、ふくろに入っているよ。');
      renderHud();
      renderControls();
    };

    // ───── キー・パッド ─────
    let nav = null;
    const refreshNav = () => {
      if (!nav) return;
      nav.refresh();
    };
    nav = padNav(sh.root, { onB: () => close(), sound: (x) => game.audio.sfx(x) });
    const h = {
      el: sh.root,
      onNav: (a) => {
        if (msgDone && (a === 'a' || a === 'b')) { msgDone(); return; }
        // うごいて いる ときの A は 早おくり
        if (busy) { if (a === 'a') view.speed = 3; return; }
        nav.onNav(a);
      },
    };
    game.input.push(h);

    const finish = (why) => {
      if (closed) return;
      closed = true;
      view.destroy();
      stopFx();
      game.input.pop(h);
      sh.remove();
      resolve(why);
    };
    const close = () => {
      if (busy || closed) return;
      game.audio.sfx('cancel');
      finish(summary ? 'desk' : 'close');
    };
    sh.onClose = close;

    // はじめ（つづきから・戦いの あと）
    (async () => {
      busy = true;
      sh.lock(true);
      renderHud();
      const after = info.after || [];
      const startOps = info.startOps || [];
      info.startOps = null;
      if (startOps.length) await playOps(startOps);
      else if (!after.length) await say(run.turn ? `${B.name}の続きから！\nのこり${run.rolls}回。` : `${B.name}、スタート！`, 1600);
      for (const a of after) await say(a);
      busy = false;
      sh.lock(false);
      renderHud();
      renderControls();
      if (run?.pending) promptPending();
      else setMsg(`のこり${run.rolls}回。\nさいころをふろう！`);
    })();
  });
}

