      el('button', { class: 'btn', text: '引っこしコード', onclick: () => { cleanup(); showTransfer(game, chars); } }),
      chars.length ? el('button', { class: 'btn danger', text: 'キャラを消す', onclick: () => delFlow() }) : null));
  wrap.append(head, list, foot);
  ui.append(wrap);
  let idx = 0;
  const all = [...items.map((i) => i.card), newBtn];
  const sel = () => all.forEach((c, i) => c.classList.toggle('sel', i === idx));
  sel();
  const choose = (c) => {
    cleanup();
    game.audio.sfx('confirm');
    notePlayed(game, c.id);
    game.net.send({ t: 'play', id: c.id });
  };
  // 第35回: 十字キーで カードの 下の ボタン（引っこしコード・キャラを消す など）にも 行ける（ui/padnav.js）
  const h = padNav(wrap, {
    pad: true,
    start: () => all[idx],
    sound: (x) => game.audio.sfx(x),
    onFocus: (e) => {
      const i = all.indexOf(e);
      if (i >= 0) idx = i;
      all.forEach((c) => c.classList.toggle('sel', c === e));
    },
  });
  game.input.push(h);
  const cleanup = () => game.input.pop(h);
  // 「連れていく」リンクで 開いた ときは、ここで 聞く。
  // 家族サーバーでは、スマホの データを 合わせてから（とどいて いなければ ときどき 取りに 行く）
  setTimeout(async () => {
    if (game.net.mode === 'server' && !game.syncing) {
      game.syncing = true;
      try {
        if (!(await syncOnServer(game))) await maybeRoundTrip(game);
      } finally {
        game.syncing = false;
      }
    }
    offerPendingImport(game);
  }, 0);
  const delFlow = async () => {
    cleanup();
    const name = await askText(game.input, { title: '消すキャラクターの名前を入れてください（元にもどせません）', max: 8 });
    const c = chars.find((x) => x.name === name);
    if (c && await confirmBox(game.input, `${c.name}を本当に消しますか？\n（セーブも全て消えます）`, '消す', 'やめる', (x) => game.audio.sfx(x))) {
      game.net.send({ t: 'deleteChar', id: c.id, confirm: c.name });
    } else if (name) toast('やめました');
    showSelect(game, game.chars || chars);
  };
}

// 家族サーバー ⇄ ひとりで遊ぶサイト（データを 合わせる）
function syncButtons(game, cleanup) {
  if (game.net.local?.cloud?.inViewer) return [];
  // 行かなかった（やめた）ときは「だれで遊ぶ？」に もどる
  const go = (fn) => async () => {
    cleanup();
    if (!(await fn(game))) showSelect(game, game.chars || []);
  };
  if (game.net.mode === 'server') {
    return [
      el('button', { class: 'btn', text: '📱 ひとりで遊ぶサイトへ', onclick: go(goSite) }),
      el('button', { class: 'btn', text: '🔄 スマホと合わせる', onclick: go(roundTrip) }),
    ];
  }
  const out = [el('button', { class: 'btn primary', text: '家族サーバーで遊ぶ', onclick: go(goFamilyServer) })];
  if (familyServer()) out.push(el('button', { class: 'btn', text: 'アドレス', 'aria-label': '家族サーバーのアドレスを変える', onclick: () => changeServer(game) }));
  return out;
}

// ───────────── 行き来の リンク（ひとりで遊ぶサイト ⇄ 家族サーバー） ─────────────
function goTo(game, url) {
  // claude.ai の 中では 新しい タブ、それ以外は この タブで 開く（ポップアップを ブロックされない）
  if (game.net.local?.cloud?.inViewer) window.open(url, '_blank', 'noopener');
  else location.assign(url);
}

async function offerPendingImport(game) {
  const code = pendingImport();
  if (!code || game.importOffering || document.querySelector('.modal-back, .transfer-panel, .create')) return;
  game.importOffering = true;
  clearPendingImport();
  try {
    const r = parseCode(code);
    if (!r.ok) {
      toast(r.reason, 6000);
      return;
    }
    const place = game.net.mode === 'server' ? `家族サーバー「${game.net.family || 'わが家'}」` : 'このブラウザ';
    const ok = await confirmBox(game.input, `${r.char.name}（Lv${r.char.level}）を\n${place}に連れてきますか？`, '連れてくる', 'やめる', (x) => game.audio.sfx(x));
    if (!ok) {
      toast('やめました');
      return;
    }
    const res = await request(game, { t: 'importChar', code }, 'importResult');
    toast(res.text || '', 6000);
    game.audio.sfx(res.ok ? 'join' : 'buzz');
  } finally {
    game.importOffering = false;
    if (game.state === 'select') showSelect(game, game.chars || []);
  }
}

// ───────────── 引っこしコード（キャラクターを べつの 場所へ つれていく） ─────────────
// コピー: iPhone の Safari（http の 家族サーバー）や アプリの 中では、新しい コピーの しくみ
// （navigator.clipboard）が つかえない ことが あるので、まず 文字を 全部 選んで コピーする
function selectAllText(ta) {
  ta.focus({ preventScroll: true });
  ta.select();
  ta.setSelectionRange(0, ta.value.length);
}

function copyBySelect(ta) {
  selectAllText(ta);
  try {
    return document.execCommand('copy');
  } catch {
    return false;
  }
}

// 書き出す: キャラを えらぶ → コードが 出る → コピー
// 連れてくる: コードを はりつける → 「だれで遊ぶ？」に くわわる
function request(game, msg, want) {
  return new Promise((resolve) => {
    game.transferWaiter = (m) => {
      if (m.t !== want) return false;
      game.transferWaiter = null;
      resolve(m);
      return true;
    };
    game.net.send(msg);
    setTimeout(() => {
      if (game.transferWaiter) {
        game.transferWaiter = null;
        resolve({ ok: false, text: '通信がおくれています' });
      }
    }, 8000);
  });
}

// 第78回: コードを ファイルで 出す（.txt。スマホは 共有の メニューが 使えれば それで、だめなら ダウンロード）
function fileButton(game, r) {
  const save = async () => {
    const d = new Date();
    const ymd = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
    // ファイルの 名前は 英数字だけ（日本語だと「download」に なって しまう ブラウザが ある）
    const name = `kizuna-${String(r.id || 'chara').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 24)}-${ymd}.txt`;
    const text = `きずなの紋章の引っこしコード（${r.name}）\n「② コードから連れてくる」→「ファイルから読む」で、このファイルを選んでね。\n\n${r.code}\n`;
    const blob = new Blob([text], { type: 'text/plain' });
    try {
      const f = new File([blob], name, { type: 'text/plain' });
      if (navigator.canShare?.({ files: [f] }) && navigator.share) {
        await navigator.share({ files: [f], title: `${r.name}の引っこしコード` });
        toast('ファイルを出しました');
        return;
      }
    } catch (e) {
      if (e?.name === 'AbortError') return;
    }
    const url = URL.createObjectURL(blob);
    const a = el('a', { href: url, download: name, style: { display: 'none' } });
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    toast(`${name} を保存しました`, 4000);
    game.audio.sfx('confirm');
  };
  return el('button', { class: 'btn', text: '📄 ファイルで出す', onclick: save });
}

export function showTransfer(game, chars) {
  clearUI();
  const ui = document.getElementById('ui');
  const where = saveWhere(game).place;
  const wrap = el('div', { class: 'panel center-panel transfer-panel', style: { width: 'min(96vw, 720px)' } });
  const box = el('div', { class: 'win scroll', style: { maxHeight: 'calc(88vh - var(--pad-h))' } });
  const body = el('div', { class: 'col', style: { gap: '0.6em' } });
  const close = el('button', { class: 'btn closebtn', text: '✕ 閉じる', 'aria-label': '閉じる' });
  const head = el('div', { class: 'svc-head', style: { marginBottom: '0.3em' } }, el('span', { class: 'gold', text: '引っこしコード' }), close);
  box.append(head, body);
  wrap.append(box);
  ui.append(wrap);
  const h = padNav(box, { sound: (x) => game.audio.sfx(x), onB: () => done() });
  game.input.push(h);
  const done = () => {
    game.input.pop(h);
    game.transferWaiter = null;
    showSelect(game, game.chars || chars);
  };
  close.addEventListener('click', done);

  const top = () => {
    body.innerHTML = '';
    body.append(
      el('div', { class: 'small', text: `キャラクターを、べつの場所へ連れていけます。\n今いる場所: ${where}` }),
      el('div', { class: 'detail', text: 'れい: 家族サーバーの電源がないときに、スマホの「ひとりで遊ぶモード」で進めたキャラを、あとで家族サーバーに連れてくる。\n書き出したあとは、連れていった先で続きを遊んでね（両方で遊ぶと、あとで進んだほうのデータになります）。' }),
      el('div', { class: 'row', style: { gap: '0.5em', flexWrap: 'wrap' } },
        el('button', { class: 'btn primary', text: '① キャラを書き出す', disabled: !chars.length, onclick: pickExport }),
        el('button', { class: 'btn primary', text: '② コードから連れてくる', onclick: importView })),
      game.net.mode === 'server'
        ? el('div', { class: 'col', style: { gap: '0.3em' } },
          el('div', { class: 'small', text: 'PCがついていない時も、スマホだけで遊べる「ひとりで遊ぶサイト」があります。ここから開くと、この家族サーバーのアドレスを覚えるので、あとで1タップで連れてこられます。' }),
          el('div', { class: 'row' }, el('button', { class: 'btn', text: '📱 ひとりで遊ぶサイトを開く', onclick: () => goTo(game, linkToSite(game.net.site || DEFAULT_SITE, { server: siteServerAddress(game.net) })) })))
        : null);
  };

  const pickExport = () => {
    body.innerHTML = '';
    body.append(el('div', { class: 'small gold', text: 'だれを書き出す？' }));
    const row = el('div', { class: 'row', style: { gap: '0.4em', flexWrap: 'wrap' } });
    for (const c of chars) row.append(el('button', { class: 'btn', text: `${c.name}（Lv${c.level}）`, onclick: () => exportView(c) }));
    body.append(row, el('button', { class: 'btn', text: '← もどる', onclick: top }));
  };

  const exportView = async (c) => {
    body.innerHTML = '';
    body.append(el('div', { class: 'small muted', text: 'コードを作っています…' }));
    const r = await request(game, { t: 'exportChar', id: c.id }, 'exportCode');
    body.innerHTML = '';
    if (!r.code) {
      body.append(el('div', { class: 'warn', text: r.text || '書き出せませんでした' }), el('button', { class: 'btn', text: '← もどる', onclick: top }));
      return;
    }
    // 第78回: LINE の 1通に 入らない ときは 2通、3通…に 分ける（どの じゅんで はりつけても 読める）
    const parts = splitCode(r.code);
    const hint = el('div', { class: 'small' });
    const copyBox = (text, label, done) => {
      const ta = el('textarea', { class: 'textin codearea', readonly: true, rows: parts.length > 1 ? '3' : '5', spellcheck: 'false' });
      ta.value = text;
      const btn = el('button', { class: 'btn primary', text: label });
      btn.addEventListener('click', () => {
        const copied = () => {
          ta.setSelectionRange(0, 0);
          ta.blur();
          toast('コピーしました！');
          game.audio.sfx('confirm');
          hint.className = 'small good';
          hint.textContent = done;
        };
        const manual = () => {
          ta.style.display = '';
          selectAllText(ta);
          hint.className = 'small warn';
          hint.textContent = '自動でコピーできませんでした。コードを全部選んであるので、青いところを長おし →「コピー」してください。';
        };
        // http の 家族サーバーや アプリの 中でも コピーできる やりかたから ためす
        if (ta.style.display !== 'none' && copyBySelect(ta)) return copied();
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(copied, manual);
        else manual();
      });
      return { ta, btn };
    };
    const send = parts.length === 1
      ? 'べつのスマホへは、LINE・メッセージ・AirDrop・メモなどで送れます。'
      : `LINEでは${parts.length}つに分けて送ってね。メッセージ・AirDrop・メモ・ファイルなら1回で送れます。`;
    const pasteHelp = '連れていく先で「② コードから連れてくる」を開いて、はりつけてください。';
    const codeRows = [];
    if (parts.length === 1) {
      const { ta, btn } = copyBox(r.code, 'コピーする', `コピーしました！　${pasteHelp}\n（同じスマホなら、そのまま連れていく先をブラウザで開いて、はりつけるだけ）`);
      codeRows.push(ta, el('div', { class: 'row', style: { gap: '0.5em', flexWrap: 'wrap' } }, btn, fileButton(game, r), el('button', { class: 'btn', text: '← もどる', onclick: top })));
    } else {
      codeRows.push(el('div', { class: 'warn', text: `コードが長いので、${parts.length}つに分けました。LINEでは1つずつ送ってね（どのじゅんばんで、はりつけてもだいじょうぶ）。` }));
      parts.forEach((part, i) => {
        const { ta, btn } = copyBox(part, `${i + 1}つめをコピー`, `${i + 1}つめをコピーしました！　送ったら、つぎのコードもコピーしてね。全部そろうと、むこうで読めます。`);
        codeRows.push(el('div', { class: 'col', style: { gap: '0.3em' } }, el('div', { class: 'small gold', text: `${i + 1}つめ（${parts.length}つのうち）` }), ta, el('div', { class: 'row' }, btn)));
      });
      const all = copyBox(r.code, '全部まとめてコピー', `全部コピーしました！　メモ・メール・AirDropなら、このまま1回で送れます。${pasteHelp}`);
      all.ta.style.display = 'none';
      codeRows.push(all.ta, el('div', { class: 'row', style: { gap: '0.5em', flexWrap: 'wrap' } }, all.btn, fileButton(game, r), el('button', { class: 'btn', text: '← もどる', onclick: top })));
    }
    // 1タップで 連れていく（リンクで 開くと、むこうで「連れてきますか？」と 聞かれる）
    const jump = [];
    if (game.net.mode === 'server') {
      jump.push(el('button', { class: 'btn primary', text: '📱 ひとりで遊ぶサイトへ連れていく', onclick: () => goTo(game, linkToSite(game.net.site || DEFAULT_SITE, { code: r.code, server: siteServerAddress(game.net) })) }));
    } else {
      const toServer = async () => {
        let server = familyServer();
        if (!server) {
          const typed = await askText(game.input, { title: '家族サーバーのアドレスを入れてください（PCの画面に出ている「同じWi-Fiのスマホから」のアドレス）', placeholder: '192.168.1.23:3000', max: 60, initial: '' });
          if (typed === null) return;
          server = setFamilyServer(typed);
          if (!server) {
            toast('アドレスの形がちがうみたい（例: 192.168.1.23:3000）', 5000);
            return;
          }
        }
        goTo(game, linkToFamilyServer(server, r.code));
      };
      jump.push(el('button', { class: 'btn primary', text: '家族サーバーへ連れていく', onclick: toServer }));
      if (familyServer()) jump.push(el('button', { class: 'btn', text: 'アドレスを変える', onclick: async () => {
        const typed = await askText(game.input, { title: '家族サーバーのアドレス', placeholder: '192.168.1.23:3000', max: 60, initial: familyServer().replace(/^https?:\/\//, '') });
        if (typed !== null && !setFamilyServer(typed)) toast('アドレスの形がちがうみたい', 4000);
      } }));
    }
    body.append(
      el('div', { class: 'gold', text: `${r.name}の引っこしコード` }),
      el('div', { class: 'small', text: '連れていく先の「だれで遊ぶ？」→「引っこしコード」→「② コードから連れてくる」で、このコードをはりつけてください。' }),
      el('div', { class: 'row', style: { gap: '0.5em', flexWrap: 'wrap' } }, ...jump),
      el('div', { class: 'small muted', text: game.net.mode === 'server' ? '同じスマホなら、このボタンだけでOK（ひとりで遊ぶサイトが開いて、連れていくか聞かれます）。' : '家に帰ってPCがついていれば、このボタンだけでOK（家族サーバーが開いて、連れていくか聞かれます）。' }),
      ...codeRows,
      hint,
      el('div', { class: 'detail', text: `コードの長さ: ${r.code.length}文字。${send}\n全部コピーしてね（とちゅうで切れると読めません）。「ファイルで出す」でとっておくと、もしものときのバックアップにもなります。` }));
  };

  const importView = () => {
    body.innerHTML = '';
    const ta = el('textarea', { class: 'textin codearea', rows: '5', spellcheck: 'false', autocomplete: 'off', autocapitalize: 'off', autocorrect: 'off', placeholder: 'ここに引っこしコードをはりつける（KIZUNA-…）' });
    const go = el('button', { class: 'btn primary', text: '連れてくる' });
    const msg = el('div', { class: 'small' });
    // 第78回: 分けた コード（KIZUNA-5-P1/2-…）は、そろうまで ここに ためる（どの じゅんでも よい）
    let got = '';
    const gotBox = el('div', { class: 'small gold' });
    const reset = el('button', { class: 'btn', text: 'やりなおす', style: { display: 'none' } });
    const showGot = (p) => {
      gotBox.textContent = p ? `読んだコード: ${p.have.join('・')}つめ（${p.total}つのうち）` : '';
      reset.style.display = p ? '' : 'none';
    };
    reset.addEventListener('click', () => {
      got = '';
      showGot(null);
      msg.textContent = '';
      ta.value = '';
    });
    const tryImport = async (text) => {
      if (!cleanCode(text)) {
        toast('コードをはりつけてください');
        return;
      }
      // 分けて いない コードを はりつけた ときは、ためた 分は つかわない
      if (joinParts(cleanCode(text)).none) {
        got = '';
        showGot(null);
      }
      const all = cleanCode(`${got}${text}`);
      const p = joinParts(all);
      if (p.bad) {
        msg.textContent = p.bad;
        msg.className = 'small warn';
        game.audio.sfx('buzz');
        return;
      }
      if (p.total) {
        got = all;
        ta.value = '';
        showGot(p);
        msg.textContent = `${p.reason}。のこりのコードを、わくにはりつけて「連れてくる」をおしてね。`;
        msg.className = 'small good';
        game.audio.sfx('confirm');
        return;
      }
      go.disabled = true;
      msg.className = 'small';
      msg.textContent = '読みこんでいます…';
      const r = await request(game, { t: 'importChar', code: all }, 'importResult');
      go.disabled = false;
      msg.textContent = r.text || '';
      msg.className = r.ok ? 'small good' : 'small warn';
      game.audio.sfx(r.ok ? 'join' : 'buzz');
      if (r.ok) {
        got = '';
        showGot(null);
        if (r.mode !== 'kept') ta.value = '';
      }
    };
    go.addEventListener('click', () => tryImport(ta.value));
    // ファイルから 読む（「ファイルで出す」で 作った .txt）
    const file = el('input', { type: 'file', accept: '.txt,text/plain', style: { display: 'none' } });
    file.addEventListener('change', async () => {
      const f = file.files?.[0];
      file.value = '';
      if (!f) return;
      if (f.size > 2000000) {
        msg.textContent = 'ファイルが大きすぎます。引っこしコードのファイルを選んでね';
        msg.className = 'small warn';
        return;
      }
      let text = '';
      try {
        text = await f.text();
      } catch {
        text = '';
      }
      if (!text.includes('KIZUNA-')) {
        msg.textContent = 'このファイルには、引っこしコードが入っていないみたい';
        msg.className = 'small warn';
        game.audio.sfx('buzz');
        return;
      }
      ta.value = text.trim();
      tryImport(text);
    });
    const fromFile = el('button', { class: 'btn', text: '📄 ファイルから読む', onclick: () => file.click() });
    body.append(
      el('div', { class: 'small', text: `書き出したコードを、ここにはりつけてね。キャラクターが「${where}」にやってきます。\niPhone・iPad: わくの中を長おし →「ペースト」\nいくつかに分かれたコードは、1つずつはりつけて「連れてくる」をおしてね（どのじゅんばんでもOK）。` }),
      ta,
      gotBox,
      el('div', { class: 'row', style: { gap: '0.5em', flexWrap: 'wrap' } }, go, fromFile, reset, el('button', { class: 'btn', text: '← もどる', onclick: top })),
      file,
      msg,
      el('div', { class: 'detail', text: 'もういるキャラクターのコードなら、コードのほうが後で遊んだデータのときだけ入れかえます。' }));
    setTimeout(() => ta.focus(), 50);
  };
  top();
}

export function showCreate(game) {
  clearUI();
  const ui = document.getElementById('ui');
  // あたらしい みため（style / hcol / tone / face）。むかしの 番号（hair など）は サーバーが あわせて つける
  const look = { body: 0, style: 'short', hcol: 'brown', tone: 'light', face: 'std', color: 1 };
  let job = 'warrior';
  let dirI = 0;
  const dirs = ['down', 'left', 'up', 'right'];
  const wrap = el('div', { class: 'panel center-panel', style: { width: 'min(96vw, 860px)' } });
  const box = el('div', { class: 'win scroll', style: { maxHeight: 'calc(86vh - var(--pad-h))' } });
  const preview = makeCanvas(128, 168);
  const sprite = previewCache(16);
  const name = el('input', { class: 'textin', id: 'cname', maxlength: '8', placeholder: '名前（8文字まで）', autocomplete: 'off' });
  const jobDesc = el('div', { class: 'jobdesc' });
  const draw = () => {
    const x = ctxOf(preview);
    x.clearRect(0, 0, preview.width, preview.height);
    x.drawImage(sprite(look, job, undefined, dirs[dirI], Math.floor(performance.now() / 300) % 2, 8), 0, 0);
  };
  const timer = setInterval(draw, 150);
  const upd = [];
  const refresh = () => { upd.forEach((f) => f()); draw(); };
  const row = (label, node, note) => el('div', { class: 'col', style: { gap: '0.2em' } },
    el('span', { class: 'small gold' }, label, note ? el('span', { class: 'muted cr-note' }, note) : ''), node);
  // ボタンを ならべる（えらんだ ものに しるし）
  const opts = (values, get, set, render) => {
    const o = el('div', { class: 'opt' });
    values.forEach((v) => {
      const b = render(v);
      b.addEventListener('click', () => {
        set(v);
        game.audio.sfx('cursor');
        refresh();
      });
      o.append(b);
    });
    upd.push(() => values.forEach((v, i) => o.children[i].classList.toggle('sel', get() === v)));
    return o;
  };
  // ◀ なまえ ▶（数が 多い ものは じゅんばんに めくる）
  const stepper = (list, key) => {
    const nm = el('span', { class: 'step-name' });
    const no = el('span', { class: 'small muted step-no' });
    const go = (d) => {
      const i = list.findIndex((x) => x.id === look[key]);
      look[key] = list[(i + d + list.length) % list.length].id;
      game.audio.sfx('cursor');
      refresh();
    };
    upd.push(() => {
      const i = list.findIndex((x) => x.id === look[key]);
      nm.textContent = list[i]?.name || '';
      no.textContent = `${i + 1}/${list.length}`;
    });
    return el('div', { class: 'stepper' },
      el('button', { class: 'btn', text: '◀', 'aria-label': 'まえ', onclick: () => go(-1) }), nm, no,
      el('button', { class: 'btn', text: '▶', 'aria-label': 'つぎ', onclick: () => go(1) }));
  };
  const swatches = (list, key, label) => opts(list.map((x) => x.id), () => look[key], (v) => { look[key] = v; },
    (v) => el('button', { class: 'swatch', style: { background: list.find((x) => x.id === v).hex }, 'aria-label': label }));
  const nameOf = (list, key) => {
    const s = el('span');
    upd.push(() => { s.textContent = `　${list.find((x) => x.id === look[key])?.name || ''}`; });
    return s;
  };
  const bodyOpt = opts([0, 1], () => look.body, (v) => { look.body = v; }, (v) => el('button', { class: 'btn', text: v ? '女性' : '男性' }));
  const hairOpt = stepper(HAIR_STYLES, 'style');
  const hairCol = swatches(HAIR_COLORS, 'hcol', 'かみの色');
  const faceOpt = opts(FACES.map((x) => x.id), () => look.face, (v) => { look.face = v; }, (v) => el('button', { class: 'btn', text: FACE_BY_ID.get(v).name }));
  const skinOpt = swatches(SKIN_TONES, 'tone', 'はだの色');
  const clothOpt = opts(CLOTH_COLORS.map((_, i) => i), () => look.color, (v) => { look.color = v; }, (v) => el('button', { class: 'swatch', style: { background: CLOTH_COLORS[v] }, 'aria-label': '服の色' }));
  const pick = (list) => list[Math.floor(Math.random() * list.length)].id;
  const rnd = el('button', { class: 'btn', text: 'おまかせ', onclick: () => {
    look.style = pick(HAIR_STYLES);
    look.hcol = pick(HAIR_COLORS);
    look.face = pick(FACES);
    look.tone = pick(SKIN_TONES);
    look.color = Math.floor(Math.random() * CLOTH_COLORS.length);
    game.audio.sfx('cursor');
    refresh();
  } });
  const jobsEl = el('div', { class: 'jobs' });
  JOB_ORDER.forEach((j) => {
    const b = el('button', { class: `btn jobbtn ${j === job ? 'sel' : ''}` }, el('span', { class: 'jn', text: jobLabel(j, { look }) }), el('span', { class: 'jd', text: {
      warrior: '固くて強い', monk: 'とても素早い', priest: '回復の女神', mage: '攻撃呪文', performer: 'みんなをおうえん',
      jester: '何が起こるかな？', salaryman: 'チームを支える', idol: 'みんなの人気者', railman: '時間に正確', ballplayer: 'かっとばせ！',
      schoolkid: 'のびざかり！', civil_local: '町を守る', cook: '食べて元気に', parttimer: '何でもこなす',
      neet: 'のびしろ無限大', saiyan: '戦闘民族', youtuber: '動画で人気者', gamer: 'ゲームの達人', okan: 'みんなのおかん',
      spy: 'ひみつの任務', shonen_tantei: 'なぞを解く', neko_robot: '未来から来た', kappa: 'すもうが得意',
      rurouni: '旅の剣士でござる',
      magician: 'タネも仕かけもない', alchemist: '形を作りかえる',
      plumber: 'ジャンプが得意',
      kishou: '明日の天気を当てる',
    }[j] }));
    b.addEventListener('click', () => {
      job = j;
      [...jobsEl.children].forEach((x) => x.classList.toggle('sel', x === b));
      jobDesc.textContent = jobFor(j, { look }).desc;
      game.audio.sfx('cursor');
      draw();
    });
    jobsEl.append(b);
    // 第43回: 体で 名前が かわる 職業（ももの姫／配管工。shared/job-label.js）
    if (JOBS[j].masc) upd.push(() => { b.firstChild.textContent = jobLabel(j, { look }); if (j === job) jobDesc.textContent = jobFor(j, { look }).desc; });
  });
  jobDesc.textContent = jobFor(job, { look }).desc;
  const turn = el('button', { class: 'btn', text: '回す', onclick: () => { dirI = (dirI + 1) % 4; draw(); } });
  const ok = el('button', { class: 'btn primary', text: 'これで始める！' });
  const back = el('button', { class: 'btn', text: 'もどる' });
  box.append(
    el('h2', { text: 'キャラクターを作る' }),
    el('div', { class: 'create' },
      el('div', { class: 'preview' }, preview, el('div', { class: 'col pv-btns' }, turn, rnd)),
      el('div', { class: 'col' },
        row('名前', name),
        row('体', bodyOpt),
        row('かみがた', hairOpt),
        row('かみの色', hairCol, nameOf(HAIR_COLORS, 'hcol')),
        row('目もと', faceOpt),
        row('はだの色', skinOpt, nameOf(SKIN_TONES, 'tone')),
        row('服の色', clothOpt),
        row('最初の職業（後で転職できる）', jobsEl),
        jobDesc,
        el('div', { class: 'row end' }, back, ok))),
  );
  wrap.append(box);
  ui.append(wrap);
  refresh();
  // 第35回: 十字キーと A で 作れる（ui/padnav.js。名前は A で 入力 → Enter で おわる）
  const h = padNav(box, { start: name, sound: (x) => game.audio.sfx(x), onB: () => doBack() });
  game.input.push(h);
  const cleanup = () => {
    clearInterval(timer);
    game.input.pop(h);
  };
  const doBack = () => {
    cleanup();
    showSelect(game, game.chars || []);
  };
  back.addEventListener('click', doBack);
  ok.addEventListener('click', () => {
    const n = name.value.trim();
    if (!n) {
      toast('名前を入れてください');
      name.focus();
      return;
    }
    cleanup();
    game.audio.sfx('join');
    game.pendingPlay = true;
    game.net.send({ t: 'createChar', name: n, look: cleanLook(look), job });
  });
  setTimeout(() => name.focus(), 50);
}

js/client/ui/treasure.js:
// 宝の地図（メニューの「道具」に ならぶ・地図の 絵・ほる・見つけた 穴）
import { el, ListMenu, confirmBox, esc, toast } from './dom.js';
import { MAPS, tileAt } from '../../shared/maps/index.js';
import { T } from '../../shared/tiles.js';
import { hash2 } from '../../shared/rng.js';
import { caveInfo, tmTitle, foundFlag, TM_THEMES, TM_MAX } from '../../shared/data/treasure.js';
import { treasureHintLines, fromHereLine, tmPlaceShort } from '../../shared/data/treasure-hint.js';
import { MONSTERS } from '../../shared/data/monsters.js';
import { makeCanvas, ctxOf } from '../render/pixel.js';

// 第75回: .tmfull-view … 地図が いっぱいの ときに どれを 捨てるか えらぶ まど（askTreasureFull）
const CSS = `
.tmap-view { width: min(92vw, 440px); z-index: 5; background: var(--win-solid); align-items: center; gap: 0.35em; }
.tmap-view .tm-title { align-self: stretch; }
.tmap-view canvas.tm-pic { width: min(80vw, 380px); max-height: 44vh; object-fit: contain; image-rendering: pixelated; border-radius: 6px; box-shadow: 0 0 0 2px #5a3e22, 0 4px 14px rgba(0,0,0,0.5); }
.tmap-view .tm-info { align-self: stretch; white-space: pre-wrap; line-height: 1.55; }
.tmap-view .tm-hint { align-self: stretch; color: #ffd66b; }
.tmap-view .menu { align-self: stretch; }
.menu .tag.tm-new { color: #ffd66b; }
.menu .tag.tm-found { color: #8fd0ff; }
.menu .tag.tm-clear { color: var(--muted); }
@media (orientation: landscape) and (max-height: 520px) {
  .tmap-view { width: min(94vw, 720px); display: grid; grid-template-columns: auto 1fr; align-items: start; }
  .tmap-view .tm-title { grid-column: 1 / 3; }
  .tmap-view canvas.tm-pic { grid-row: 2 / 5; width: min(46vw, 340px); max-height: 60vh; }
}
.menu .tag.tm-pend { color: #ff9b6b; }
.tmfull-view { width: min(94vw, 520px); z-index: 5; background: var(--win-solid); gap: 0.4em; }
.tmfull-view .tmf-new { border: 2px solid #ffd66b; border-radius: 8px; padding: 0.35em 0.6em; background: rgba(255, 214, 107, 0.08); }
.tmfull-view .tmf-new .tmf-name { color: #ffd66b; }
.tmfull-view .tmf-ask { white-space: pre-wrap; }
.tmfull-view .tmf-list { overflow-y: auto; flex: 1 1 auto; min-height: 6em; }
.tmfull-view .tmf-list > li { flex-shrink: 0; }
.tmfull-view .tmf-list .item { padding-top: 0.25em; padding-bottom: 0.25em; }
.tmfull-view .tmf-list .item.dis .tmf-sub { color: #6d6c88; }
.tmfull-view .tmf-sub { display: block; font-size: var(--fs-small); color: var(--muted); line-height: 1.35; margin-top: 0.1em; }
.tmfull-view .menu .item.sel .tmf-sub { color: #d8d4f0; }
.tmfull-view .menu .item.tmf-act { color: #ffd66b; }
@media (orientation: landscape) and (max-height: 520px) {
  .tmfull-view { width: min(96vw, 820px); display: grid; grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr); align-items: start; column-gap: 0.8em; }
  .tmfull-view .tmf-head { grid-column: 1; }
  .tmfull-view .tmf-list { grid-column: 2; grid-row: 1 / 5; max-height: calc(100dvh - 56px - var(--safe-b) - var(--safe-t)); }
}
`;
let cssDone = false;
function ensureCss() {
  if (cssDone || typeof document === 'undefined') return;
  cssDone = true;
  document.head.append(el('style', { text: CSS }));
}

const STATE = (tm) => (tm.cleared ? ['tm-clear', 'クリア'] : tm.found ? ['tm-found', '発見'] : ['tm-new', '未発見']);

// 道具の 一覧に ならべる 行（第75回: 地図が いっぱいで あずかっている 新しい 地図は いちばん 上。えらぶと どれを 捨てるか 決める）
export function treasureRows(c) {
  const list = Array.isArray(c?.treasureMaps) ? c.treasureMaps : [];
  const pend = (Array.isArray(c?.tmPending) ? c.tmPending : []).map((tm) => {
    const name = tmTitle(tm);
    return { html: `${esc(name)}<span class="tag tm-pend">いっぱい</span>`, label: name, value: `tm:pend:${tm.id}`, tmap: `pend:${tm.id}` };
  });
  return [...pend, ...list.map((tm) => {
    const [cls, label] = STATE(tm);
    const name = tmTitle(tm);
    return { html: `${esc(name)}<span class="tag ${cls}">${label}</span>`, label: name, value: `tm:${tm.id}`, tmap: tm.id };
  })];
}

const findMap = (game, id) => (game.me?.treasureMaps || []).find((t) => t.id === id);

// どの あたりの 地図か（目じるしからの 方角と 歩数・まわりの 地形。data/treasure-hint.js）
function whereText(tm) {
  return treasureHintLines(tm).join('\n');
}

// 今いる 場所から 何の 方角へ 何歩か（同じ マップの ときだけ）
function nearHint(game, tm) {
  const f = game.field;
  if (!f?.me) return '';
  return fromHereLine(tm, f.mapId, f.me.x, f.me.y);
}

function stateText(tm) {
  const cave = caveInfo(tm.seed, tm.lv);
  if (tm.cleared) return `${cave.caveName}の主をたおした。\n（また入ることもできる）`;
  if (tm.found) return `${cave.caveName}の入り口を見つけた。\n（地下${cave.floors}階まである。いちばんおくに主がいる）`;
  return 'まだ宝の場所を見つけていない。\n宝の場所は、地面が赤く光っている。';
}

export function treasureDetail(game, id) {
  const pend = pendOf(game, id);
  if (pend) return `地図がいっぱいで、まだ持てない新しい地図。\n${tmInfoLine(pend)}\n選ぶと、どの地図を捨てるか決められる。`;
  const tm = findMap(game, id);
  if (!tm) return '';
  const hint = nearHint(game, tm);
  return `${whereText(tm)}\n${stateText(tm)}${hint ? `\n${hint}` : ''}`;
}

// ───────────── 地図の 絵（地形だけ。宝の 場所の しるしは 見つけるまで かかない）─────────────
const PAPER = '#ead7a8';
const INK = '#5c3f22';
function tileLook(t) {
  switch (t) {
    case T.TREE: case T.PINE: return ['#c9c58c', 'tree'];
    case T.FOREST_FLOOR: return ['#d6cf98', null];
    case T.MOUNTAIN: case T.ROCK: case T.CLIFF: case T.RUBBLE_WALL: return ['#cdae84', 'mtn'];
    case T.HILL: return ['#e1cd98', 'hill'];
    case T.WATER: case T.STEPPING: case T.BROKEN_BRIDGE: return ['#a9c3c3', 'wave'];
    case T.DEEP: case T.WHIRLPOOL: return ['#93b3b9', 'wave'];
    case T.SAND: return ['#f0e1b6', 'dot'];
    case T.DIRT: return ['#d2b27c', null];
    case T.SWAMP: return ['#baa9a2', 'dot'];
    case T.BRIDGE_H: case T.BRIDGE_V: case T.PIER: return ['#b08a58', null];
    case T.CAVE_ENTRANCE: case T.STAIRS_DOWN: return ['#6a4a30', null];
    case T.FLOWERS: case T.TOWN_FLOWERS: return ['#ecd6a8', 'dot'];
    default:
      if (t >= 30 && t < 70) return ['#c29c6a', 'house'];
      return [PAPER, null];
  }
}

export function drawTreasurePicture(canvas, tm) {
  const m = MAPS[tm.map];
  const VW = 24, VH = 17, P = 6;
  canvas.width = VW * P;
  canvas.height = VH * P;
  const x = ctxOf(canvas);
  x.fillStyle = PAPER;
  x.fillRect(0, 0, canvas.width, canvas.height);
  if (!m) return canvas;
  // 宝の 場所が まんなかに ならない ように すこし ずらす（地図ごとに きまった ずれ）
  const ox = Math.round((hash2(tm.seed, 1, 71) - 0.5) * 12), oy = Math.round((hash2(tm.seed, 2, 73) - 0.5) * 7);
  const x0 = Math.max(0, Math.min(m.w - VW, tm.x + ox - (VW >> 1)));
  const y0 = Math.max(0, Math.min(m.h - VH, tm.y + oy - (VH >> 1)));
  for (let ty = 0; ty < VH; ty++) {
    for (let tx = 0; tx < VW; tx++) {
      const mx = x0 + tx, my = y0 + ty;
      const t = tileAt(m, mx, my);
      const [base, sym] = tileLook(t);
      const px = tx * P, py = ty * P;
      x.fillStyle = base;
      x.fillRect(px, py, P, P);
      const n = hash2(mx, my, 5);
      x.fillStyle = INK;
      if (sym === 'tree' && n < 0.8) {
        // 木（すこし ずらして 手がきの ように）
        const dx = Math.floor(hash2(mx, my, 6) * 3) - 1, dy = Math.floor(hash2(mx, my, 8) * 2);
        x.globalAlpha = 0.5;
        x.fillRect(px + 2 + dx, py + dy, 2, 1);
        x.fillRect(px + 1 + dx, py + 1 + dy, 4, 2);
        x.globalAlpha = 0.7;
        x.fillRect(px + 2 + dx, py + 3 + dy, 1, 2);
      } else if (sym === 'mtn') {
        x.globalAlpha = 0.6;
        for (let k = 0; k < 3; k++) { x.fillRect(px + 2 - k, py + 1 + k, 1, 1); x.fillRect(px + 2 + k, py + 1 + k, 1, 1); }
        x.fillRect(px, py + 4, 6, 1);
      } else if (sym === 'wave' && n < 0.35) {
        x.globalAlpha = 0.4;
        x.fillRect(px + 1, py + 2, 2, 1);
        x.fillRect(px + 3, py + 3, 2, 1);
      } else if (sym === 'dot' && n < 0.4) {
        x.globalAlpha = 0.35;
        x.fillRect(px + 2, py + 2, 1, 1);
      } else if (sym === 'hill' && n < 0.3) {
        x.globalAlpha = 0.35;
        x.fillRect(px + 1, py + 3, 4, 1);
        x.fillRect(px + 2, py + 2, 2, 1);
      } else if (sym === 'house') {
        x.globalAlpha = 0.35;
        x.fillRect(px, py + 5, 6, 1);
      }
      x.globalAlpha = 1;
    }
  }
  // 見つけた 地図だけ 赤い ✕
  if (tm.found) {
    const cx = (tm.x - x0) * P + P / 2, cy = (tm.y - y0) * P + P / 2;
    x.fillStyle = '#c0281c';
    for (let k = -4; k <= 4; k++) {
      x.fillRect(cx + k - 1, cy + k - 1, 2, 2);
      x.fillRect(cx + k - 1, cy - k - 1, 2, 2);
    }
  }
  // 方角の しるし（北が 上。ヒントの「北へ」「南東へ」と あわせて 見る）
  {
    const cx = canvas.width - 10, cy = 5;
    x.globalAlpha = 0.85;
    x.fillStyle = INK;
    x.beginPath();
    x.moveTo(cx, cy);
    x.lineTo(cx + 3.5, cy + 5);
    x.lineTo(cx - 3.5, cy + 5);
    x.closePath();
    x.fill();
    x.font = 'bold 9px sans-serif';
    x.textAlign = 'center';
    x.textBaseline = 'top';
    x.fillText('北', cx, cy + 6);
    x.globalAlpha = 1;
  }
  // 古い 紙の ふち（こげた ような かげ）
  const g = x.createRadialGradient(canvas.width / 2, canvas.height / 2, canvas.height * 0.35, canvas.width / 2, canvas.height / 2, canvas.width * 0.62);
  g.addColorStop(0, 'rgba(120, 80, 30, 0)');
  g.addColorStop(1, 'rgba(110, 70, 25, 0.55)');
  x.fillStyle = g;
  x.fillRect(0, 0, canvas.width, canvas.height);
  x.fillStyle = 'rgba(70, 40, 15, 0.8)';
  for (let i = 0; i < canvas.width; i++) {
    x.fillRect(i, 0, 1, 1 + Math.floor(hash2(i, 0, tm.seed & 0xffff) * 3));
    x.fillRect(i, canvas.height - 1 - Math.floor(hash2(i, 1, tm.seed & 0xffff) * 3), 1, 3);
  }
  for (let j = 0; j < canvas.height; j++) {
    x.fillRect(0, j, 1 + Math.floor(hash2(0, j, tm.seed & 0xffff) * 3), 1);
    x.fillRect(canvas.width - 1 - Math.floor(hash2(1, j, tm.seed & 0xffff) * 3), j, 3, 1);
  }
  return canvas;
}

// ───────────── 地図を 見る（ほる・捨てる）─────────────
export function openTreasureMap(menu, id) {
  const g = menu.game;
  if (pendOf(g, id)) return askTreasureFull(g, { menu }); // 第75回: あずかりの 地図
  const tm = findMap(g, id);
  if (!tm) return;
  ensureCss();
  menu.sub?.blur();
  const cave = caveInfo(tm.seed, tm.lv);
  const back = el('div', { class: 'modal-back', style: { zIndex: 4 } });
  const box = el('div', { class: 'win panel center-panel tmap-view' });
  const pic = drawTreasurePicture(makeCanvas(10, 10), tm);
  pic.classList.add('tm-pic');
  const hint = nearHint(g, tm);
  box.append(
    el('div', { class: 'gold tm-title', text: `${tmTitle(tm)}　（${TM_THEMES[cave.theme].label}の洞窟）` }),
    pic,
    el('div', { class: 'small tm-info', text: `${whereText(tm)}\n${stateText(tm)}` }),
    ...(hint ? [el('div', { class: 'small tm-hint', text: hint })] : []),
  );
  const done = (next) => {
    lm.blur();
    back.remove();
    box.remove();
    menu.popupOpen = false;
    if (next === 'close') menu.close();
    else setTimeout(() => { if (menu.root) menu.focusSub(menu.itemsList(true)); }, next === 'drop' ? 150 : 0);
  };
  const lm = new ListMenu(g.input, {
    items: [
      { label: tm.found ? '洞窟に入る（この場所を調べる）' : 'ほる（この場所を調べる）', value: 'dig' },
      { label: '地図を捨てる', value: 'drop' },
      { label: '閉じる', value: null },
    ],
    sound: menu.sfx,
    back: null,
    onCancel: () => done(),
    onSelect: async (it) => {
      if (it.value === 'dig') {
        g.net.send({ t: 'menu', action: 'tmap', op: 'dig', id: tm.id });
        return done('close');
      }
      if (it.value === 'drop') {
        lm.blur();
        const ok = await confirmBox(g.input, `${tmTitle(tm)}を捨てますか？\n（捨てた地図はもどってこない）`, '捨てる', 'やめる', menu.sfx);
        if (ok) {
          g.net.send({ t: 'menu', action: 'tmap', op: 'discard', id: tm.id });
          return done('drop');
        }
        lm.focus();
        return;
      }
      done();
    },
  });
  box.append(lm.root);
  back.addEventListener('click', () => { menu.sfx('cancel'); done(); });
  document.getElementById('ui').append(back, box);
  menu.popupOpen = true;
  lm.focus();
}

// ───────────── 見つけた 地図の 場所に 穴（自分の 地図だけ。フラグで 出る）─────────────
let gateSig = '';
export function syncTreasureGates(game) {
  const list = (game?.me?.treasureMaps || []).filter((t) => t.found && MAPS[t.map]);
  const sig = list.map((t) => `${t.map}:${t.x}:${t.y}:${t.seed}`).join('|');
  if (sig === gateSig) return;
  gateSig = sig;
  for (const id of ['overworld', 'sea']) {
    const m = MAPS[id];
    if (!m) continue;
    m.gates = m.gates.filter((gt) => !gt.tm);
    m.gateAt = undefined;
  }
  for (const t of list) {
    const m = MAPS[t.map];
    const closed = tileAt(m, t.x, t.y);
    if (closed === T.STAIRS_DOWN) continue;
    m.gates.push({ x: t.x, y: t.y, closed, open: T.STAIRS_DOWN, flag: foundFlag(t.seed), tm: true });
  }
}

// ───────────── 第75回: 地図が いっぱい → どれを 捨てるか えらぶ ─────────────
// 家族の 声:「宝の地図が一杯の時は、今持っている地図を捨てるか選ばせて。」
// サーバーは 新しい 地図を「あずかり」（c.tmPending。セーブに のこる）に 入れて まつ（world/treasure.js の grantTreasureMap）。
// 画面は フィールドで 落ちついた とき（会話・戦い・メニューが ない）に この まどを 出す（watchTreasureFull。game.js の frame から）。
// 「あとで決める」・B なら しまって、メニューの「道具」→「宝の地図」の いちばん 上の 行から いつでも 選べる。
const pendOf = (game, id) => {
  const pid = String(id || '').startsWith('pend:') ? String(id).slice(5) : null;
  return pid ? (game.me?.tmPending || []).find((t) => t.id === pid) || null : null;
};
const STATE_TXT = (tm) => (tm.cleared ? 'クリア' : tm.found ? '入り口を見つけた' : 'まだほっていない');

// 地図の みじかい 説明（洞窟の しゅるい・主・場所）
export function tmInfoLine(tm) {
  const cave = caveInfo(tm.seed, tm.lv);
  const boss = MONSTERS[cave.boss]?.name || '？';
  return `${TM_THEMES[cave.theme].label}の洞窟・主：${boss}\n${tmPlaceShort(tm)}`;
}

// 捨てる 地図の ならび: 主を たおした 地図 → 入り口を 見つけた 地図 → まだの 地図（それぞれ 古い じゅん）
export function discardOrder(list) {
  const rank = (t) => (t.cleared ? 0 : t.found ? 1 : 2);
  return [...list].sort((a, b) => rank(a) - rank(b) || (a.at || 0) - (b.at || 0));
}

const fullState = { open: false, t: 0, later: new Set() };

// フィールドで 落ちついたら（idle）、あずかりの 地図を 聞く。「あとで」に した 地図は もう 聞かない（メニューから 選べる）
export function watchTreasureFull(game, dt, idle) {
  const pend = game.me?.tmPending;
  if (!idle || fullState.open || !Array.isArray(pend) || !pend.some((t) => !fullState.later.has(t.id))) {
    fullState.t = 0;
    return;
  }
  fullState.t += dt;
  if (fullState.t < 700) return;
  fullState.t = 0;
  askTreasureFull(game);
}

// menu … メニューから 開いた ときの FieldMenu（おわったら 道具の 一覧に もどる）
export function askTreasureFull(game, { menu = null } = {}) {
  const g = game;
  const c = g.me;
  const nw = (c?.tmPending || []).find((t) => menu || !fullState.later.has(t.id)) || c?.tmPending?.[0];
  if (!nw || fullState.open || typeof document === 'undefined') return;
  ensureCss();
  fullState.open = true;
  const sfx = (k) => g.audio?.sfx(k);
  if (menu) menu.sub?.blur();
  else g.menuOpen = true;
  sfx('confirm');
  // 今 いる 洞窟の 地図は 捨てられない（サーバーと おなじ きまり）
  const here = /^tm_([0-9a-z]+)_/.exec(g.field?.mapId || '')?.[1];
  const list = discardOrder(c.treasureMaps || []);
  const back = el('div', { class: 'modal-back', style: { zIndex: 4 } });
  const box = el('div', { class: 'win panel center-panel tmfull-view' });
  const head = el('div', { class: 'tmf-head' },
    el('div', { class: 'gold', text: '宝の地図がいっぱい！' }),
    el('div', { class: 'tmf-new' },
      el('div', { class: 'small muted', text: '新しい地図' }),
      el('div', { class: 'tmf-name', text: `${tmTitle(nw)}（${STATE_TXT(nw)}）` }),
      el('div', { class: 'small tmf-ask', text: tmInfoLine(nw) })),
    el('div', { class: 'small tmf-ask', text: `持てる地図は${TM_MAX}まいまで。\nどれか1まい捨てると、新しい地図を持てるよ。` }));
  // 「あきらめる」「あとで」は 上に（20まいの 下まで さがさなくても 見える）。カーソルは はじめの 地図
  const mapRows = list.map((tm) => {
    const busyHere = here && tm.id === here;
    const [cls, label] = STATE(tm);
    return {
      html: `${esc(tmTitle(tm))}<span class="tag ${cls}">${busyHere ? '今いる洞窟' : label}</span><span class="tmf-sub">${esc(tmInfoLine(tm).replace('\n', '・'))}</span>`,
      label: tmTitle(tm),
      value: tm.id,
      disabled: !!busyHere,
    };
  });
  const items = [
    { label: '新しい地図をあきらめる', value: '#give', cls: 'tmf-act' },
    { label: 'あとで決める', value: '#later' },
    { header: true, label: '捨てる地図を選ぶ' },
    ...mapRows,
  ];
  const start = items.findIndex((it) => !it.header && !it.disabled && !String(it.value).startsWith('#'));
  const finish = (sent) => {
    lm.blur();
    back.remove();
    box.remove();
    fullState.open = false;
    fullState.t = 0;
    if (menu) {
      menu.popupOpen = false;
      setTimeout(() => { if (menu.root) menu.focusSub(menu.itemsList(true)); }, sent ? 250 : 0);
    } else g.menuOpen = false;
  };
  const later = () => {
    fullState.later.add(nw.id);
    if (!menu) toast('メニューの「道具」→「宝の地図」で、あとで選べるよ', 4200);
    finish(false);
  };
  const send = (msg) => {
    g.net.send({ t: 'menu', action: 'tmap', pid: nw.id, ...msg });
    finish(true);
  };
  const lm = new ListMenu(g.input, {
    items,
    sound: sfx,
    back: null,
    start,
    className: 'tmf-list',
    onCancel: () => later(),
    onSelect: async (it) => {
      if (it.value === '#later') return later();
      lm.blur();
      if (it.value === '#give') {
        const ok = await confirmBox(g.input, `${tmTitle(nw)}をあきらめますか？\n（持っている地図は、そのまま）`, 'あきらめる', 'やめる', sfx);
        if (ok) return send({ op: 'pendGive' });
      } else {
        const ok = await confirmBox(g.input, `${it.label}を捨てて、\n${tmTitle(nw)}を持ちますか？\n（捨てた地図は、もどってこない）`, '捨てる', 'やめる', sfx);
        if (ok) return send({ op: 'pendKeep', id: it.value });
      }
      lm.focus();
    },
  });
  box.append(head, lm.root);
  back.addEventListener('click', () => { sfx('cancel'); later(); });
  document.getElementById('ui').append(back, box);
  if (menu) menu.popupOpen = true;
  lm.focus();
}

