// 第37回 A: サファラ闘技場の 王者たちの しかけ（battle.js・ai.js・battle-ch5.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・チームの 合体技（monsters の arena.team。ランク2 砂嵐三兄弟・ランク8 伝説のチャンピオン・第65回 ランク10 星の大王者）
//   リーダー（arena.lead）が 合図（前ぶれ。cond 'c5:arTeam2' … 組の 2人いじょうが 生きている）→ 次の 番に 合体技（効果 arCombo）。
//   ダメージは 生きている 組の 数 ÷ はじめの 組の 数 ばい（3人 そろえば そのまま・2人なら 3分の2）。1人だけに なると くずれて 出せない
// ・属性の よろい（monsters の arena.armor。ランク7 七色の魔導王・第65回 ランク10 星の大王者〈合体技の 組の リーダーでも ある〉）
//   炎・氷・雷・風の どれかを まとう（効果 arArmor。はじめから 1つ まとっている）。よろいと おなじ 属性の 攻撃は すいこんで HPが ふえる
//   （absorb ばい）。弱点（weak）の 属性で 当てると weakMult ばいの ダメージで よろいが くだける。くだけて から wait 回 動くと また まとう
//   （cond 'c5:arNoArmor'）。よろいの 大呪文（効果 arSpell）は まとっている よろいと おなじ 属性
// ・オートの 仲間（ふつう）は 何も かわらない。シミュレーター（tools/sim-arena.mjs）の 知っている 人（b.knowsArena）は、
//   大技の 前に 身を 守る（arenaPlan）・合体技の 組の 子分を 先に ねらう・よろいの 属性を さけて 弱点を ねらう・
//   ふたごの 剣士は HPの 多い ほうを ねらって 2人を そろえて たおす（arenaAdjust）
// ・第68回 C: こおる・とける（monsters の arena.frost。ランク11 白銀の大王者ボレアス）
//   はじめは 体が こおっている（arFrozen）。こおっている 間は 炎 いがいの ダメージが cut ばい（ほとんど 効かない）。
//   炎の ダメージが 最大HPの melt ぶん たまると とける（大ふぶきの 前ぶれも 止まる）。とけている 間は thawMult ばいの ダメージ。
//   とけて から wait 回 動くと 自分で また こおる（cond 'c5:arThawWait'・効果 arFreeze）。おともの 雪の子（arena.frostHelp）は、
//   王者が とけていると すぐに こおらせる（cond 'c5:arKingThawed'）→ 雪の子を 先に たおすと、とけている 時間が 長い
//   知っている 人: こおっている 王者には 炎・とけたら みんなで 王者・雪の子が いる 間は 雪の子を 先に
// ・第74回 C: あわの よろい（monsters の arena.bubble。ランク12 深海の大王者リヴァイアス）
//   はじめは あわの よろいを まとっている（arBubble … のこりの あわの 数。max こ）。あわが ある 間は、どんな 攻撃も
//   1回 当たるごとに あわが 1つ はじけて ダメージは 0（強い 技でも 弱い 技でも おなじ 1つ。みんなを ねらう 技・何回も 打つ 技が とくい）。
//   あわが ぜんぶ はじけると、openMult ばいの ダメージ（大チャンス）。はじけて から wait 回 動くと、また あわを まとう
//   （cond 'c5:arBubbleWait'・効果 arBubble）。あわを まとっている 間に うずを まき始めると、次の 番に 大うずしお（ARENA_BIG）。
//   大うずしおは、のこりの あわが 多いほど 強い（bigBase ＋ bigPer × あわの 数 ばい）→ 前ぶれの 間に あわを わると 弱く なる
//   知っている 人: あわが ある 間は 王者に 強い 技を 使わない（ふつうの 攻撃・みんなを ねらう 技・何回も 打つ 技で あわを わる）・
//   あわが なくなったら みんなで 王者（合体技も その 時だけ）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES, ELEMENT_NAMES } from './data/abilities.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';

// 知っている 人が 身を 守る 大技（前ぶれの つぎ）
export const ARENA_BIG = new Set(['m_ar1_bomb', 'm_ar2_combo', 'm_ar5_finish', 'm_ar7_rainbow', 'm_ar8_combo', 'm_ar9_fire_blast', 'm_ar9_ice_blast', 'm_ar10_combo', 'm_ar11_blizzard', 'm_ar12_maelstrom']);
const confOf = (m) => MONSTERS[m?.species]?.arena || null;
const teamOf = (m) => confOf(m)?.team || null;
const armorConf = (m) => confOf(m)?.armor || null;
const frostConf = (m) => confOf(m)?.frost || null;
// 第74回 C: あわの よろい（王者だけ）
export const bubbleConf = (m) => confOf(m)?.bubble || null;
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || a.effect : a?.effect || {});
const actsOf = (m) => Object.values(m.used || {}).reduce((s, n) => s + n, 0);
// 組の 人（たおれた 人も ふくむ・にげた 人は のぞく）
export function teamMembers(b, m) {
  const team = teamOf(m);
  return team ? b.enemies.filter((e) => teamOf(e) === team) : [];
}
export const teamAlive = (b, m) => teamMembers(b, m).filter((e) => e.alive);

// ───────────── はじめ（battle.js の constructor）─────────────
// 属性の よろいを まとった まま 始まる
export function setupArena(b) {
  for (const e of b.enemies) {
    if (armorConf(e) && !e.arArmor) wearArmor(b, e, null);
    if (frostConf(e) && e.arFrozen === undefined) freeze(b, e, null);
    if (bubbleConf(e) && e.arBubble === undefined) wearBubbles(b, e, null);
  }
}

// ───────────── 魔物の こうどうの じょうけん（battle-ch5.js の towerCond から。'c5:' の あと）─────────────
export function arenaCond(b, m, cond) {
  if (cond === 'arTeam2') return teamAlive(b, m).length >= 2;
  if (cond === 'arNoArmor') {
    const conf = armorConf(m);
    return !!conf && !m.arArmor && actsOf(m) - (m.arBreakAt ?? -99) >= (conf.wait ?? 2);
  }
  if (cond === 'arArmored') return !!m.arArmor;
  // 第68回 C: こおる・とける
  if (cond === 'arFrozen') return !!frostConf(m) && !!m.arFrozen;
  if (cond === 'arThawWait') {
    const conf = frostConf(m);
    return !!conf && !m.arFrozen && actsOf(m) - (m.arThawAt ?? -99) >= (conf.wait ?? 3);
  }
  if (cond === 'arKingThawed') return !!thawedKing(b, m);
  // 第74回 C: あわの よろい
  if (cond === 'arBubbled') return !!bubbleConf(m) && m.arBubble > 0;
  if (cond === 'arBubbleWait') {
    const conf = bubbleConf(m);
    return !!conf && !(m.arBubble > 0) && actsOf(m) - (m.arPopAt ?? -99) >= (conf.wait ?? 3);
  }
  return null;
}

// ───────────── 技の こうか（battle-ch5.js の towerEffect から）─────────────
export function arenaEffect(b, c, a, eff, ev, targets = []) {
  switch (eff.type) {
    case 'arCombo': combo(b, c, a, eff, ev, targets); return true;
    case 'arArmor': {
      wearArmor(b, c, ev);
      return true;
    }
    case 'arFreeze': {
      // 自分（王者）か、とけている 王者を こおらせる（雪の子）
      const k = frostConf(c) ? c : thawedKing(b, c);
      if (k && !k.arFrozen) freeze(b, k, ev, k === c ? null : c);
      else ev.lines.push('しかし、何もおこらなかった。');
      return true;
    }
    case 'arBubble': {
      // 第74回 C: あわの よろいを まとい直す（もう ぜんぶ ある ときは 何も おこらない）
      if (bubbleConf(c) && c.arBubble < bubbleConf(c).max) wearBubbles(b, c, ev);
      else ev.lines.push('しかし、何もおこらなかった。');
      return true;
    }
    case 'arSpell': {
      const conf = armorConf(c);
      const el = c.arArmor || (conf ? b.rng.pick(conf.els) : 'fire');
      ev.lines.push(`${ELEMENT_NAMES[el]}の力が、うずをまいた！`);
      b.applyAbility(c, { ...a, anim: a.anim, effect: { type: 'magic', element: el, base: eff.base, thr: eff.thr ?? 99 } }, {}, ev, 1, targets);
      return true;
    }
    default: return false;
  }
}

function combo(b, c, a, eff, ev, targets) {
  const all = teamMembers(b, c);
  const alive = all.filter((e) => e.alive);
  if (alive.length < 2 || !all.length) {
    ev.lines.push('しかし、仲間がいない…。\n合体技のかまえが、くずれてしまった！');
    ev.arBroken = true;
    ev.fx = { type: 'ability', anim: 'none', actor: c.id, targets: [], side: c.side };
    return;
  }
  const k = alive.length / all.length;
  if (alive.length < all.length) ev.lines.push(`（${alive.length}人だけの合体技だ！いきおいが弱い…！）`);
  ev.arCombo = alive.length;
  b.applyAbility(c, { ...a, effect: { type: 'phys', mult: (eff.mult ?? 1.5) * k, ignoreDef: eff.ignoreDef || 0 } }, {}, ev, 1, targets);
}

// よろいを まとう（ev が null … 戦いの はじめ。ことばは 出さない）
function wearArmor(b, c, ev) {
  const conf = armorConf(c);
  if (!conf) return;
  const pool = conf.els.filter((e) => e !== c.arLast);
  const el = b.rng.pick(pool.length ? pool : conf.els);
  c.arArmor = el;
  c.arLast = el;
  const weak = conf.weak?.[el];
  // 弱点の ダメージは arenaDamage（resist には 入れない。オートの みつもりには 見えない）
  c.arBase = c.arBase || { ...c.resist };
  c.resist = { ...c.arBase, [el]: Math.min(c.arBase[el] ?? 1, 1) };
  if (weak) c.resist[weak] = Math.max(c.arBase[weak] ?? 1, 1);
  if (!ev) return;
  ev.lines.push(`${c.name}は、${ELEMENT_NAMES[el]}のよろいをまとった！`, `（${ELEMENT_NAMES[el]}の攻撃は、すいこまれてしまう！${weak ? `${ELEMENT_NAMES[weak]}が弱点だ！` : ''}）`);
  ev.fx = { type: 'ability', anim: 'buff', actor: c.id, targets: [c.id], side: c.side, element: el };
  ev.arArmor = el;
  ev.upd.push(c);
}

// ───────────── 第68回 C: こおる・とける ─────────────
// 雪の子（arena.frostHelp）から見て、とけている 王者（いなければ null）
function thawedKing(b, m) {
  if (!confOf(m)?.frostHelp) return null;
  return b.enemies.find((e) => e.alive && e.side === m.side && frostConf(e) && !e.arFrozen) || null;
}
// こおる（ev が null … 戦いの はじめ。by … こおらせた 雪の子）
function freeze(b, c, ev, by = null) {
  const conf = frostConf(c);
  if (!conf) return;
  c.arFrozen = true;
  c.arMelt = 0;
  // 炎が よく 効く（オートの みつもりにも 見える）。とけたら もとに もどす
  c.frBase = c.frBase || { ...c.resist };
  c.resist = { ...c.frBase, fire: Math.max(c.frBase.fire ?? 1, conf.fireRes ?? 1.5) };
  if (!ev) return;
  if (by) ev.lines.push(`${by.name}は、${c.name}に、つめたいいきをふきかけた！`);
  ev.lines.push(`${c.name}の体が、かちかちにこおりついた！`, '（こおった体には、炎いがいは、ほとんど効かない！炎でとかそう！）');
  ev.fx = { type: 'ability', anim: 'guard', actor: (by || c).id, targets: [c.id], side: c.side, element: 'ice' };
  ev.arFreeze = c.id;
  ev.upd.push(c);
}
function thaw(b, t, ev) {
  t.arFrozen = false;
  t.arMelt = 0;
  t.arThawAt = actsOf(t);
  if (t.frBase) t.resist = { ...t.frBase };
  ev.postLines = ev.postLines || [];
  ev.postLines.push(`${t.name}のこおりが、とけた！今が大チャンスだ！`);
  if (t.telegraph && ARENA_BIG.has(t.telegraph)) {
    t.telegraph = null;
    ev.postLines.push('大ふぶきの前ぶれが、止まった！');
  }
  ev.arThaw = t.id;
  ev.upd.push(t);
}
// ダメージ（arenaDamage から）。こおっている … 炎は とかす・ほかは cut ばい / とけている … thawMult ばい
function frostDamage(b, c, t, dmg, info, ev) {
  const conf = frostConf(t);
  if (!t.arFrozen) return Math.round(dmg * (conf.thawMult ?? 1.3));
  if (info?.element === 'fire') {
    t.arMelt = (t.arMelt || 0) + dmg;
    if (t.arMelt >= t.maxHp * (conf.melt ?? 0.05)) thaw(b, t, ev);
    return dmg;
  }
  const line = `こおった体に、はばまれた…！`;
  if (!ev.lines.includes(line)) ev.lines.push(line);
  return Math.max(1, Math.round(dmg * (conf.cut ?? 0.35)));
}

// ───────────── 第74回 C: あわの よろい ─────────────
// あわを まとう（ev が null … 戦いの はじめ）
function wearBubbles(b, c, ev) {
  const conf = bubbleConf(c);
  if (!conf) return;
  c.arBubble = conf.max ?? 4;
  if (!ev) return;
  ev.lines.push(`${c.name}の体が、${c.arBubble}つの大きなあわに、つつまれた！`, '（あわは、どんな攻撃でも、1回当たると1つはじける！）');
  ev.fx = { type: 'ability', anim: 'guard', actor: c.id, targets: [c.id], side: c.side, element: 'water' };
  ev.arBubble = c.id;
  ev.upd.push(c);
}
// ダメージ（arenaDamage から）。あわが ある … 1つ はじけて ダメージは なし（null）/ ない … openMult ばい
function bubbleDamage(b, c, t, dmg, ev) {
  const conf = bubbleConf(t);
  if (!(t.arBubble > 0)) return Math.round(dmg * (conf.openMult ?? 1.3));
  t.arBubble -= 1;
  ev.lines.push(t.arBubble > 0 ? `あわが1つはじけて、攻撃をうけとめた！（のこりのあわ ${t.arBubble}つ）` : '最後のあわがはじけて、攻撃をうけとめた！');
  ev.results = ev.results || [];
  ev.results.push({ id: t.id, dmg: 0, pop: true });
  if (t.arBubble <= 0) {
    t.arPopAt = actsOf(t);
    ev.postLines = ev.postLines || [];
    ev.postLines.push(`${t.name}のあわのよろいが、全部はじけた！今が大チャンスだ！`);
    ev.arPop = t.id;
  }
  ev.upd.push(t);
  return null;
}

// あわの 王者の 大技（大うずしお）: のこりの あわが 多いほど 強い
function bubbleBig(c, dmg, ev) {
  const conf = bubbleConf(c);
  const n = Math.max(0, c.arBubble || 0);
  if (!ev.arBigNote) {
    ev.arBigNote = true;
    ev.lines.push(n > 0 ? `（あわが${n}つのこっていて、うずがとても大きい！）` : '（あわが全部はじけていて、うずが小さい！）');
  }
  return Math.max(1, Math.round(dmg * ((conf.bigBase ?? 0.4) + (conf.bigPer ?? 0.2) * n)));
}

function breakArmor(b, t, ev) {
  const el = t.arArmor;
  t.arArmor = null;
  t.arBreakAt = actsOf(t);
  if (t.arBase) t.resist = { ...t.arBase };
  ev.postLines = ev.postLines || [];
  const line = `弱点をついた！${ELEMENT_NAMES[el]}のよろいが、くだけちった！`;
  if (!ev.postLines.includes(line)) ev.postLines.push(line);
  ev.arBreak = t.id;
  ev.upd.push(t);
}

// ───────────── ダメージ（battle.js の damage）─────────────
// よろいと おなじ 属性 … すいこむ（null を かえすと ダメージは なし）/ 弱点 … 大きく 当たって よろいが くだける
export function arenaDamage(b, c, t, dmg, info, ev) {
  if (c && t && c.side !== t.side && bubbleConf(c) && ARENA_BIG.has(ev.ability) && dmg > 0) return bubbleBig(c, dmg, ev);
  if (t && c && c.side !== t.side && bubbleConf(t) && t.alive !== false && dmg > 0) return bubbleDamage(b, c, t, dmg, ev);
  if (t && c && c.side !== t.side && frostConf(t) && t.alive !== false && dmg > 0) return frostDamage(b, c, t, dmg, info, ev);
  if (!t?.arArmor || !c || c.side === t.side) return dmg;
  const conf = armorConf(t);
  const el = info?.element;
  if (!conf || !el || el === 'phys') return dmg;
  if (el === t.arArmor) {
    const heal = Math.max(0, Math.min(t.maxHp - t.hp, Math.round(dmg * (conf.absorb ?? 0.5))));
    t.hp += heal;
    ev.lines.push(`${ELEMENT_NAMES[el]}のよろいが、${ELEMENT_NAMES[el]}の力をすいこんだ！`, heal > 0 ? `${t.name}のHPが${heal}回復した！` : `${t.name}はダメージを受けない！`);
    ev.results = ev.results || [];
    ev.results.push({ id: t.id, heal, absorb: true, element: el });
    ev.upd.push(t);
    return null;
  }
  if (el === conf.weak?.[t.arArmor]) {
    breakArmor(b, t, ev);
    return Math.round(dmg * (conf.weakMult ?? 1.5));
  }
  return dmg;
}

// ───────────── 知っている 人（シミュレーター）─────────────
// 大技が 自分の 次の 番より 先に 来るなら 身を 守る（合体技は 組が 2人いじょう いる とき）
export function arenaPlan(b, c) {
  if (c.side !== 'ally' || !b.knowsArena) return null;
  const mine = 100 / atbRate(c);
  for (const e of b.aliveEnemies()) {
    if (!ARENA_BIG.has(e.telegraph)) continue;
    if (teamOf(e) && teamAlive(b, e).length < 2) continue;
    if ((100 - e.atb) / atbRate(e) <= mine) return { type: 'defend' };
  }
  return null;
}

// 第74回 C: 知っている 人が あわを 1つ わる ことの ねうち（ダメージの 点数と くらべる）
const ARENA_POP_VALUE = 900;
// えらぶ 技の 点数を かえる（ai.js の chooseAttack。opts … { cmd, final }）
export function arenaAdjust(b, c, opts) {
  if (c.side !== 'ally' || !b.knowsArena) return;
  const foes = b.aliveEnemies();
  if (!foes.some((f) => confOf(f))) return;
  for (const o of opts) {
    const cmd = o.cmd;
    const t = b.get(cmd.target);
    const a = cmd.type === 'ability' ? ABILITIES[cmd.id] : null;
    const all = a?.target === 'enemies';
    const el = a ? prim(a).element : null;
    const hit = all ? foes : t ? [t] : [];
    // よろい: おなじ 属性は さける・弱点は ねらう
    for (const f of hit) {
      if (!f.arArmor || !el) continue;
      const conf = armorConf(f);
      if (el === f.arArmor) o.final *= 0.02;
      else if (el === conf?.weak?.[f.arArmor]) o.final *= 1.8;
    }
    // 第68回 C: こおっている 王者には 炎・ほかの 攻撃は さける。とけたら 王者を ねらう
    for (const f of hit) {
      if (!frostConf(f)) continue;
      if (f.arFrozen) o.final *= el === 'fire' ? 2.5 : 0.25;
      else o.final *= foes.some((x) => confOf(x)?.frostHelp) ? 1.3 : 1.8;
    }
    // 第74回 C: あわの よろい。あわが ある 間は 王者に 強い 技を 使わない（1回 当たれば 1つ われる。ふつうの 攻撃・何回も 打つ 技で わる）。
    //   みんなを ねらう 技は、あわを わりながら おとも にも 当たるので よい。あわが なくなったら 王者を ねらう
    for (const f of hit) {
      if (!bubbleConf(f)) continue;
      if (f.arBubble > 0) {
        if (all) o.final *= 1.3;
        else o.final = (cmd.type === 'attack' ? 1 : o.mp > 0 ? 0.25 : 0.6) * ARENA_POP_VALUE * Math.min(f.arBubble, prim(a).hits || 1);
      } else o.final *= 1.8;
    }
    if (!t || all) continue;
    const tc = confOf(t);
    // 雪の子（王者を こおらせる）を 先に（王者が こおっている 間）
    if (tc?.frostHelp) {
      const king = foes.find((f) => frostConf(f));
      if (king?.arFrozen && el !== 'fire') o.final *= 2.4;
    }
    // 合体技の 組の 子分を 先に（リーダーより）
    if (tc?.team && !tc.lead && teamAlive(b, t).length >= 2) o.final *= 2.4;
    // ふたご: HPの 多い ほうを ねらう。もう片方が 元気な うちに たおして しまう 一撃は さける
    if (tc?.twin) {
      const p = foes.find((f) => f.species === tc.twin);
      if (p) {
        const ratio = t.hp / t.maxHp, pr = p.hp / p.maxHp;
        o.final *= ratio >= pr ? 1.6 : 0.6;
        if (pr > 0.3 && o.score >= t.hp) o.final *= 0.3;
      }
    }
  }
}

js/shared/battle-c7.js:
// 第2部 第7章 第1幕「緑の王国」の ボスの 戦いの しかけ（battle-ch6.js・battle-ch5.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・水門の ウツボきょうだい（monsters-c7.js の c7.kind 'twin'。Step 1 の さいごの 中ボス）「2ひきで 1組」
//   2ひきとも 生きている 間は、どちらかが 1回 動く たびに「いき」の しるし（b.c7twin.left。はじめは twin.sync）が 1つ へる。
//   しるしが 1つの ときに どちらかが 動くと、かならず「ふたごの大うずしお」（m7g_swirl。みんなに 物理の 大技。身を 守ると 半分）→ しるしは また いっぱい。
//   かたほうが たおれると、もう かたほうが twin.call 回めの 行動で「よびもどし」（m7g_call）: HP callHp で 生き返り、2ひきとも 攻撃力 ×rage（rageMax 回まで）。
//   その 前に のこった 1ぴきも たおせば 勝ち（「いっしょに たおそう」）。1ぴきの 間は 大うずしおは ない
// ・うずの魔女オクタリア（c7.kind 'witch'。みどりの水の神殿の ボス）「声うばい」
//   every 回 動く たびに（しるし c.witch.left）「声うばいの歌」（m7t_steal）: 1人の 声を 声の貝（c7_shell。べつの 敵）に すいこむ
//   （呪文が 使えない … マホトーン〈voice〉。呪文の 多い 人から ねらう）。貝の 中の 声が chorusAt いじょうなら かわりに
//   「うばった声の大合唱」（m7t_chorus。みんなに 大きな 呪文。声 1つで per ずつ 強く なる）。
//   声の貝を こわすと、声が みんな もどり、魔女は よろめく（ゲージ 0・守り ×stagger〈3回 行動の 間〉・前ぶれも とりやめ）。
//   貝が ない 間は 声を うばえない（しるしは すすまない）。貝は 魔女が regrow 回 動くと また できる（からっぽ）。
//   HP が p2At より へると（2だんめ）every が p2Every に（はやく なる）
// ・ふつうの オート（家族が「オート」に した とき）: 大うずしお・大合唱が 自分の 次の 番より 先に 来る とき、HPが へっていれば よく 身を 守る
//   （battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ。b.c6Naive … しない 人）
// ・知っている 人（シミュレーター tools/sim-ch7.mjs。b.knowsCh6）: 大うずしお・大合唱の 前に 身を 守る（b.c6NoGuard … しない）／
//   ウツボは HP の 多い ほうを ねらって 2ひきを いっしょに へらす（b.c7NoSplit … しない）／声が 貝に 入ったら 貝を こわす（b.c7NoShell … しない）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C7_GATE, C7_GATE_B, C7_TEMPLE, C7_SHELL } from './data/monsters-c7.js';
import { BUFF_ACTS } from './buff-acts.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';
// 第2部 第7章 第2幕: ジョリーホック号（しおの満ち引き）・ホック船長（板わたり）。battle-c7s.js
import { setupC7s, c7sTurnStart, c7sEffect, c7sPlan, c7sPub, c7sDamage, c7sKill } from './battle-c7s.js';

export { C7_GATE, C7_GATE_B, C7_TEMPLE, C7_SHELL };
export const SWIRL = 'm7g_swirl';
export const CALL = 'm7g_call';
export const STEAL = 'm7t_steal';
export const CHORUS = 'm7t_chorus';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});

const c7Conf = (m) => MONSTERS[m?.species]?.c7 || null;
const twinConf = (m) => ({ call: 3, callHp: 0.5, rage: 1.12, rageMax: 2, sync: 6, swirl: {}, ...(c7Conf(m)?.twin || {}) });
const witchConf = (m) => ({ every: 3, p2At: 0.5, p2Every: 2, chorusAt: 2, chorus: {}, regrow: 4, stagger: 0.8, ...(c7Conf(m)?.witch || {}) });
export const isShell = (m) => !!MONSTERS[m?.species]?.c7shell;
const partnerOf = (b, c) => b.enemies.find((e) => e !== c && e.twin && e.species === twinConf(c).partner) || null;
// 短い 名前（「ウツボのザブン」→「ザブン」。セリフ用）
const short = (c) => MONSTERS[c?.species]?.short || c?.name || '';
const shellOf = (b) => b.enemies.find((e) => isShell(e) && !e.fled) || null;
const witchOf = (b) => b.enemies.find((e) => e.witch && e.alive) || null;
// 2だんめか（HP が p2At より へった）
const witchP2 = (c) => c.hp / c.maxHp < witchConf(c).p2At;
const everyOf = (c) => (witchP2(c) ? witchConf(c).p2Every : witchConf(c).every);
// 貝の 中の 声（声を とりもどした 人〈ほかの 方法で マホトーンが とけた 人〉は 数えない）
export function voicesOf(b, w) {
  if (!w?.witch) return 0;
  w.witch.voices = w.witch.voices.filter((id) => b.get(id)?.status?.silence?.voice);
  return w.witch.voices.length;
}

// ───────────── はじめ（battle-ch6.js の setupCh6 の さいご）─────────────
export function setupC7(b) {
  const lines = [];
  let twinMax = 0;
  for (const e of b.enemies) {
    const conf = c7Conf(e);
    if (!conf) continue;
    if (conf.kind === 'twin') {
      e.twin = { call: 0, rage: 0 };
      twinMax = Math.max(twinMax, twinConf(e).sync);
    }
    if (conf.kind === 'witch') {
      const wc = witchConf(e);
      e.witch = { left: wc.every, voices: [], down: 0, steals: 0, choruses: 0, breaks: 0 };
      lines.push(`${e.name}の首で、大きな貝のペンダントが、あやしく光っている…！`, '（あの貝に、人の声をすいこむようだ…！）');
      // がめんへ（pub）: 声の貝も 中の 声の 数を 見る
      for (const s of b.enemies) if (isShell(s)) s.c7w = e.witch;
    }
  }
  if (twinMax) {
    b.c7twin = { left: twinMax, max: twinMax, swirls: 0, calls: 0 };
    // がめんへ（pub）: 2ひきとも おなじ いきの しるしを 見る
    for (const e of b.enemies) if (e.twin) e.twin.sync = b.c7twin;
    lines.push('2ひきのウツボが、水門の前で、ぐるぐると回っている…！', '（かたほうだけたおしても、もうかたほうが、よびもどしそうだ…！）');
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
  // 第7章 第2幕の ボス（battle-c7s.js）
  setupC7s(b);
}

// ───────────── 行動の はじめ（battle-ch6.js の ch6TurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c7TurnStart(b, c, ev, stuck) {
  c7sTurnStart(b, c, ev, stuck);
  if (c.twin) twinTurn(b, c, ev, stuck);
  else if (c.witch) witchTurn(b, c, ev, stuck);
}

function twinTurn(b, c, ev, stuck) {
  const p = partnerOf(b, c);
  const tw = b.c7twin;
  if (!p || !tw || c.telegraph) return;
  if (!p.alive) {
    // よびもどしまでの 数（たおれた ときに c7Kill が call に する）
    if (!(c.twin.call > 0)) c.twin.call = twinConf(c).call;
    if (c.twin.call <= 1) {
      if (!stuck) c.telegraph = CALL;
    } else {
      c.twin.call--;
      ev.lines.push(c.twin.call > 1 ? `${c.name}は、水の底の${short(p)}を、じっと見ている…（よびもどすまで、あと${c.twin.call}回）` : `${c.name}が、大きく口を開けた…！（次に動くと、${short(p)}をよびもどす！）`);
      ev.c7CallLeft = { id: c.id, left: c.twin.call };
    }
    ev.upd.push(c);
    return;
  }
  if (tw.left <= 1) {
    if (!stuck) c.telegraph = SWIRL;
  } else {
    tw.left--;
    ev.lines.push(tw.left > 1 ? `2ひきのいきが、合ってきた…（大うずしおまで、あと${tw.left}）` : '2ひきが、ぐるぐると回る速さを上げた…！');
    if (tw.left === 1) ev.lines.push('（次にどちらかが動くと、ふたごの大うずしお…！身を守れ！）');
    ev.c7Sync = { id: c.id, left: tw.left, max: tw.max };
  }
  ev.upd.push(c, p);
}

function witchTurn(b, c, ev, stuck) {
  const w = c.witch;
  const wc = witchConf(c);
  const shell = shellOf(b);
  // こわれた 貝が また できる
  if (shell && !shell.alive) {
    w.down--;
    if (w.down <= 0) {
      Object.assign(shell, { alive: true, hp: shell.maxHp, status: {}, buffs: {}, debuffs: {}, ready: false, queued: false, telegraph: null });
      shell.atb = 0;
      const k = b.killed.lastIndexOf(shell.species);
      if (k >= 0) b.killed.splice(k, 1);
      w.left = everyOf(c);
      ev.lines.push(`${c.name}の首に、また声の貝ができた…！`);
      ev.c7Regrow = { id: c.id, shell: shell.id };
      ev.upd.push(shell);
    } else ev.lines.push(`（声の貝が、また大きくなろうとしている…あと${w.down}回）`);
  }
  if (c.telegraph) return;
  // 2だんめ: はやく なる
  w.left = Math.min(w.left, everyOf(c));
  if (!shell?.alive) return;
  const n = voicesOf(b, c);
  if (w.left <= 1) {
    if (!stuck) c.telegraph = n >= wc.chorusAt ? CHORUS : STEAL;
  } else {
    w.left--;
    if (w.left === 1) {
      if (n >= wc.chorusAt) ev.lines.push(`声の貝が、ぶるぶるとふるえ出した…！（${n}人の声）`, '（次にオクタリアが動くと、うばった声の大合唱…！貝をこわすか、身を守れ！）');
      else ev.lines.push(`${c.name}が、歌う前のように、大きくいきをすった…`, '（次にオクタリアが動くと、だれかの声がうばわれる…！）');
    }
    ev.c7Witch = { id: c.id, left: w.left, voices: n, chorus: n >= wc.chorusAt };
  }
  ev.upd.push(c);
}

// ───────────── 技の こうか（battle-ch6.js の ch6Effect の のこり）─────────────
export function c7Effect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c7Swirl': swirl(b, c, ev); return true;
    case 'c7Call': call(b, c, ev); return true;
    case 'c7Steal': steal(b, c, ev); return true;
    case 'c7Chorus': chorus(b, c, ev); return true;
    // 第7章 第2幕（battle-c7s.js）
    default: return c7sEffect(b, c, a, eff, ev);
  }
}

// ふたごの大うずしお（2ひきが そろって いる ときだけ）
function swirl(b, c, ev) {
  const p = partnerOf(b, c);
  const tw = b.c7twin;
  if (tw) tw.left = tw.max;
  if (!p?.alive) {
    ev.lines.push(`しかし、${c.name}ひとりでは、うずしおがおこらない！`);
    return;
  }
  const sc = twinConf(c).swirl;
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a7g_swirl', actor: c.id, targets: targets.map((t) => t.id), side: 'enemy', pair: p.id };
  for (const t of targets) b.physHit(c, t, { mult: sc.mult ?? 1.6, ignoreDef: sc.ignoreDef ?? 0.35, acc: 1.2 }, ev, 'phys');
  if (tw) {
    tw.swirls++;
    (ev.postLines = ev.postLines || []).push(`（2ひきのいきが、またもとにもどった…　あと${tw.max}）`);
  }
  ev.c7Swirl = { id: c.id, pair: p.id };
  ev.warn = true;
  ev.upd.push(c, p);
}

// よびもどし: たおれた きょうだいが 生き返る・2ひきとも 少し 強く なる
function call(b, c, ev) {
  const p = partnerOf(b, c);
  const tc = twinConf(c);
  c.twin.call = 0;
  if (!p || p.alive || p.fled) {
    ev.lines.push('しかし、何も起こらなかった。');
    return;
  }
  Object.assign(p, { alive: true, hp: Math.max(1, Math.round(p.maxHp * (tc.callHp ?? 0.5))), status: {}, buffs: {}, debuffs: {}, ready: false, queued: false, telegraph: null, stance: null });
  p.atb = 0;
  if (p.twin) p.twin.call = 0;
  // 経験値は 1回 たおした ぶんだけ（図鑑の 数も ふやさない）
  const k = b.killed.lastIndexOf(p.species);
  if (k >= 0) b.killed.splice(k, 1);
  ev.fx = { type: 'ability', anim: 'a7g_call', actor: c.id, targets: [p.id], side: 'enemy' };
  ev.lines.push(`水の底から、${p.name}がよみがえった！`);
  let angry = false;
  for (const e of [c, p]) {
    if ((e.twin?.rage || 0) >= (tc.rageMax ?? 2)) continue;
    e.twin.rage = (e.twin.rage || 0) + 1;
    e.atk = Math.round(e.atk * (tc.rage ?? 1.12));
    angry = true;
  }
  if (angry) ev.lines.push('2ひきは、いかりで体をふるわせた！（攻撃力が上がった）');
  (ev.postLines = ev.postLines || []).push('（2ひきを、いっしょにたおさないと…！）');
  if (b.c7twin) b.c7twin.calls++;
  ev.c7Call = { id: c.id, back: p.id };
  ev.warn = true;
  ev.upd.push(c, p);
}

// 声うばいの歌: 呪文の 多い 人から 1人（もう 声を うばわれた 人は のぞく）
function steal(b, c, ev) {
  const w = c.witch;
  const wc = witchConf(c);
  if (w) w.left = everyOf(c);
  const shell = shellOf(b);
  if (!w || !shell?.alive) {
    ev.lines.push('しかし、声の貝がない！');
    return;
  }
  const pool = b.aliveAllies().filter((x) => !x.status.silence?.voice);
  if (!pool.length) return chorus(b, c, ev);
  const score = (x) => (x.mag || 0) + (x.healPow || 0) + b.rng.float(0, 30);
  const t = pool.sort((x, y) => score(y) - score(x))[0];
  t.status.silence = { turns: 99, voice: true };
  w.voices.push(t.id);
  w.steals++;
  const n = voicesOf(b, c);
  ev.fx = { type: 'ability', anim: 'a7t_steal', actor: c.id, targets: [t.id], side: 'enemy', shell: shell.id };
  ev.lines.push(`${t.name}の声が、光のたまになって、声の貝にすいこまれた！`, `${t.name}は、声が出ない！（呪文が使えない）`);
  (ev.postLines = ev.postLines || []).push(n >= wc.chorusAt ? `（声の貝の中で、${n}人の声がないている…！声がたまると、大合唱…！）` : '（声の貝をこわせば、声がもどりそうだ…！）');
  ev.c7Steal = { id: c.id, who: t.id, voices: n };
  ev.warn = true;
  ev.upd.push(t, shell, c);
}

// うばった声の大合唱（声の 数だけ 強い 呪文）。声は 貝に のこる（こわせば もどる）
function chorus(b, c, ev) {
  const w = c.witch;
  const wc = witchConf(c);
  if (w) w.left = everyOf(c);
  const n = voicesOf(b, c);
  const ch = wc.chorus;
  const k = 1 + (ch.per ?? 0.45) * n;
  const base = (ch.base || [300, 330]).map((v) => Math.round(v * k));
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a7t_chorus', actor: c.id, targets: targets.map((t) => t.id), side: 'enemy', voices: n };
  for (const t of targets) b.magicHit(c, t, { type: 'magic', base, thr: 99 }, ev, 1);
  if (w) w.choruses++;
  ev.c7Chorus = { id: c.id, voices: n };
  ev.warn = true;
  ev.upd.push(c);
}

// ───────────── たおれた（battle-ch5.js の towerKill から）─────────────
// ウツボ: もう 1ぴきが よびもどしの 数を はじめる / 声の貝: 声が もどり、魔女が よろめく
export function c7Kill(b, t, ev) {
  c7sKill(b, t, ev);
  if (t.twin) {
    const p = partnerOf(b, t);
    if (!p?.alive) return;
    p.twin.call = twinConf(p).call;
    t.telegraph = null;
    if (!ev) return;
    (ev.postLines = ev.postLines || []).push(`${short(p)}「${short(t)}…！今、よびもどしてやる…！」`, `（${short(p)}が${p.twin.call}回動くと、${short(t)}がよみがえる…！その前に、たおそう！）`);
    ev.c7Down = { id: t.id, partner: p.id, call: p.twin.call };
    ev.upd.push(p);
    return;
  }
  if (!isShell(t)) return;
  const w = witchOf(b);
  if (!w) return;
  const wc = witchConf(w);
  const back = [];
  for (const id of w.witch.voices) {
    const a = b.get(id);
    if (a?.status?.silence?.voice) {
      delete a.status.silence;
      back.push(a);
    }
  }
  w.witch.voices = [];
  w.witch.down = wc.regrow;
  w.witch.breaks++;
  w.witch.left = everyOf(w);
  // よろめく: ならんでいた 行動・前ぶれは とりやめ・ゲージは 0 から・守りが 下がる（3回 行動の 間）
  if (w.queued) {
    b.queue = b.queue.filter((q) => q.id !== w.id);
    w.queued = false;
  }
  w.ready = false;
  w.atb = 0;
  if (w.telegraph === STEAL || w.telegraph === CHORUS) w.telegraph = null;
  w.debuffs.def = { mult: wc.stagger ?? 0.8, lv: 1, left: BUFF_ACTS };
  if (!ev) return;
  const post = (ev.postLines = ev.postLines || []);
  post.push('声の貝が、パリーン！とわれた！');
  if (back.length) post.push(`${back.map((a) => a.name).join('と')}の声が、もどってきた！`);
  post.push(`${w.name}は、ぐらりとよろめいた！（守りが下がった）`);
  ev.c7Break = { id: w.id, back: back.map((a) => a.id) };
  ev.upd.push(w, ...back);
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// ふたごの大うずしおが c の 次の 番より 先に 来るか
export function swirlBefore(b, c) {
  const tw = b.c7twin;
  if (!tw) return false;
  const eels = b.enemies.filter((e) => e.twin && e.alive);
  if (eels.length < 2) return false;
  if (eels.some((e) => e.telegraph === SWIRL)) return true;
  return eels.reduce((s, e) => s + actsBefore(b, c, e), 0) >= tw.left;
}
// うばった声の大合唱が c の 次の 番より 先に 来るか
export function chorusBefore(b, c, w = witchOf(b)) {
  if (!w?.witch) return false;
  if (w.telegraph === CHORUS) return true;
  const shell = shellOf(b);
  if (!shell?.alive || voicesOf(b, w) < witchConf(w).chorusAt) return false;
  return actsBefore(b, c, w) >= w.witch.left;
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。{ cmd, dmg }）
function bestHit(b, c, t) {
  const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
  let best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}

// ───────────── オート（battle-ch6.js の ch6Plan の はじめ）─────────────
// 第7章の ボスが いなければ null（ほかの ボスの 考えへ）
export function c7Plan(b, c, decide) {
  if (c.side !== 'ally' || b.c7Inner) return null;
  // 第7章 第2幕の ボス（ジョリーホック号・ホック船長。battle-c7s.js）
  const sp = c7sPlan(b, c, decide);
  if (sp) return sp;
  const eels = b.aliveEnemies().filter((e) => e.twin);
  const w = witchOf(b);
  if (!eels.length && !w) return null;
  const soon = eels.length ? swirlBefore(b, c) : chorusBefore(b, c, w);
  // ふつうの オート: 大技が 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  if (!b.knowsCh6) {
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c7Inner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c7Inner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  if (eels.length) {
    if (soon && !b.c6NoGuard) return { type: 'defend' };
    // 2ひきを いっしょに へらす（HP の 多い ほうを ねらう）
    if (eels.length === 2 && !b.c7NoSplit && base?.target) {
      const tgt = b.get(base.target);
      const ab = base.type === 'ability' ? ABILITIES[base.id] : null;
      const single = base.type === 'attack' || (ab && (ab.target === 'enemy' || ab.target === 'group'));
      if (tgt?.twin && single) {
        const hi = eels.slice().sort((x, y) => y.hp / y.maxHp - x.hp / x.maxHp)[0];
        if (hi !== tgt && hi.hp / hi.maxHp - tgt.hp / tgt.maxHp > 0.03) return { ...base, target: hi.id };
      }
    }
    return base;
  }
  // オクタリア: 声が 貝に 入ったら 貝を こわす（大合唱が 近い ときは とくに）
  const shell = shellOf(b);
  const n = voicesOf(b, w);
  if (shell?.alive && !b.c7NoShell && (n > 0 || soon)) {
    const h = bestHit(b, c, shell);
    // 1回で こわせる・大合唱が まだ 先・守らない 人は 貝へ（ほとんど 当たらない 人〈貝の HP の 8%より 小さい〉は ふだんの 行動）
    if (h.dmg >= shell.hp || ((!soon || b.c6NoGuard) && h.dmg >= shell.maxHp * 0.08)) return h.cmd;
  }
  if (soon && !b.c6NoGuard) return { type: 'defend' };
  return base;
}

// ───────────── がめんへ（battle-ch6.js の ch6Pub の さいご）─────────────
// ウツボ: twinLeft・twinMax（大うずしおまでの いき）・callLeft（よびもどしまで）・rage
// オクタリア: witchLeft・witchEvery（声うばいまで）・voices（貝の 中の 声）・chorus（次は 大合唱）・p2・shellDown（貝が また できるまで）
// 声の貝: c7shell・voices
export function c7Pub(c, o) {
  c7sPub(c, o);
  if (c.twin) {
    o.twin = 1;
    if (c.twin.sync) {
      o.twinLeft = c.twin.sync.left;
      o.twinMax = c.twin.sync.max;
    }
    if (c.twin.call > 0) o.callLeft = c.twin.call;
    if (c.twin.rage) o.rage = c.twin.rage;
  }
  if (c.witch) {
    const wc = witchConf(c);
    o.witchLeft = c.witch.left;
    o.witchEvery = everyOf(c);
    o.voices = c.witch.voices.length;
    o.chorus = c.witch.voices.length >= wc.chorusAt ? 1 : 0;
    if (witchP2(c)) o.p2 = 1;
    if (c.witch.down > 0) o.shellDown = c.witch.down;
  }
  if (isShell(c)) {
    o.c7shell = 1;
    o.voices = c.c7w ? c.c7w.voices.length : 0;
  }
}

// ───────────── ダメージ（battle-ch6.js の ch6Damage の さいご。味方 → 敵 だけ）─────────────
// 第7章 第2幕: のり上げた ジョリーホック号は 受ける ダメージが ふえる（battle-c7s.js）
export function c7Damage(b, c, t, dmg, info, ev) {
  return c7sDamage(b, c, t, dmg, info, ev);
}

js/shared/battle-c7i.js:
// 第2部 第7章 第3幕「ひとりぼっちの星」の ボスの 戦いの しかけ（battle-c7s.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・いばらの魔女マレフィナ（monsters-c7i.js の c7i.kind 'witch'。Step 5 の さいごの 中ボス。2だん）
//   1だんめ（魔女）「いばらのかべ」: 前に いばらのかべ（c7_thorn。べつの 敵。炎が よく効く）が ある 間、魔女が 受ける ダメージは thorn.cut ばい。
//     かべを こわすと、魔女が thorn.regrow 回 動くまで かべは ない（また はえる）。
//     curse.every 回 動く たびに（しるし c.c7mal.left）「百年ねむりののろい」（m7m_curse）: 身を 守って いない 人を みんな ねむらせる。
//     身を 守って いる 人は のろいを はね返す（ねむらない）。
//   HP が p2At より へると、次の 番に「本当の姿」（m7m_transform）… 黒い 竜に 変身する。それまでは HP が p2At より 下がらない（いっきに たおせない）。
//     変身で いばらのかべは もえて 消え、攻撃力と 速さが 上がる。行動は 竜の 技に 入れかわる（DRAGON_ACTIONS）。え は 竜の すがた（pub の c7form 2）
//   2だんめ（黒い 竜）: dragon.every 回 動く たびに「黒いほのおのいき」（m7d_breath。みんなに 炎の 大技。身を 守ると 半分）。
//     HP が dragon.p3At より へると dragon.p3Every に（はやく なる）
// ・カイの影（c7i.kind 'shade'。第7章の さいごの ボス）「かげブーメラン」
//   every 回 動く たびに、行動の はじめに 1人を ねらう（c.c7shade.aims。頭の 上に ねらいの しるし）。そのあとは ふつうに 動く。
//   lead 回 あとの 影の 番に、かならず「かげブーメラン」（m7h_throw）:
//     ねらわれた 人が 身を 守って いれば、はね返す … 影に 最大HPの reflect の ダメージ・影は ふらつく（次の 番は 動けない・守りが stagger ばい）。
//     守って いなければ、その 人に とても 大きな ダメージ（hit）・もどってくる ブーメランが ほかの みんなにも 当たる（back）。
//   HP が p2At より へると「かげぶんしん」… 2人を いっしょに ねらう・every が p2Every に（はやく なる）
// ・ふつうの オート（家族が「オート」に した とき）: 大技（のろい・いき・ねらわれた 人への ブーメラン）が 自分の 次の 番より 先に 来る とき、
//   HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ。b.c6Naive … しない 人）
// ・知っている 人（シミュレーター tools/sim-ch7.mjs。b.knowsCh6）: のろい・いきの 前に 身を 守る（b.c6NoGuard … しない）／
//   いばらのかべが ある 間は かべを 先に こわす（炎の 技が あれば 炎。b.c7iNoThorn … しない）／
//   ねらわれたら、ブーメランの 前に 身を 守って はね返す（b.c7iNoGuardAim … しない）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C7_WITCH, C7_THORN, C7_SHADOW, DRAGON_ACTIONS } from './data/monsters-c7i.js';
import { BUFF_ACTS } from './buff-acts.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';
// 第2部 第8章 第1幕: オウムのイアゴン（オウムがえし）・大臣ジャハール（さいみんじゅつ → とぐろ → ランプ）。battle-c8a.js
import { setupC8a, c8aTurnStart, c8aEffect, c8aPlan, c8aPub, c8aDamage, c8aKill } from './battle-c8a.js';

export { C7_WITCH, C7_THORN, C7_SHADOW };
export const CURSE = 'm7m_curse';
export const TRANSFORM = 'm7m_transform';
export const BREATH = 'm7d_breath';
export const THROW = 'm7h_throw';
export const DAZE = 'm7h_daze';
export const DRAGON_NAME = '黒竜マレフィナ';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});

const confOf = (m) => MONSTERS[m?.species]?.c7i || null;
export function witchConf(m) {
  const c = confOf(m) || {};
  return {
    thorn: { cut: 0.35, regrow: 3, ...(c.thorn || {}) },
    curse: { every: 4, turns: [2, 3], ...(c.curse || {}) },
    p2At: c.p2At ?? 0.5,
    dragon: { every: 3, p3At: 0.25, p3Every: 2, breath: {}, atk: 1.1, speed: 1, ...(c.dragon || {}) },
  };
}
export const shadeConf = (m) => ({ every: 3, lead: 1, p2At: 0.5, p2Every: 2, hit: {}, back: {}, reflect: 0.05, stagger: 0.8, daze: true, ...(confOf(m)?.shade || {}) });
export const isThorn = (m) => !!MONSTERS[m?.species]?.c7thorn;
export const isDragon = (m) => !!m?.c7mal?.dragon;
export const thornOf = (b) => b.enemies.find((e) => isThorn(e) && !e.fled) || null;
const witchOf = (b) => b.enemies.find((e) => e.c7mal && e.alive) || null;
const shadeOf = (b) => b.enemies.find((e) => e.c7shade && e.alive) || null;
const breathEvery = (c) => {
  const d = witchConf(c).dragon;
  return c.hp / c.maxHp < d.p3At ? d.p3Every : d.every;
};
const shadeP2 = (c) => c.hp / c.maxHp < shadeConf(c).p2At;
const aimEvery = (c) => (shadeP2(c) ? shadeConf(c).p2Every : shadeConf(c).every);
// いばらのかべが 立って いるか
export const thornUp = (b) => !!thornOf(b)?.alive;
// ねらわれて いる 人（たおれた 人は のぞく）
export function aimed(b, s = shadeOf(b)) {
  if (!s?.c7shade) return [];
  return s.c7shade.aims.map((id) => b.get(id)).filter((x) => x?.alive);
}

// ───────────── はじめ（battle-c7s.js の setupC7s の さいご）─────────────
export function setupC7i(b) {
  const lines = [];
  for (const e of b.enemies) {
    const conf = confOf(e);
    if (!conf) continue;
    if (conf.kind === 'witch') {
      e.c7mal = { dragon: false, left: witchConf(e).curse.every, down: 0, curses: 0, breaths: 0, breaks: 0, burnt: false };
      // がめんへ（pub）: いばらのかべも 魔女の ようすを 見る
      for (const s of b.enemies) if (isThorn(s)) s.c7m = e.c7mal;
      lines.push(`${e.name}の前に、黒いいばらのかべが、ぐんぐんのびていく…！`, '（いばらのかべがある間は、魔女にダメージがとどきにくい。炎でよくもえそうだ…！）');
    }
    if (conf.kind === 'shade') {
      e.c7shade = { left: aimEvery(e), aims: [], lead: 0, daze: false, marks: 0, throws: 0, reflects: 0, hits: 0 };
      lines.push(`${e.name}が、黒いブーメランを、くるくる回している…`, '（ねらわれた人は、身を守ると、ブーメランをはね返せそうだ…！）');
    }
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
  // 第8章 第1幕の ボス（battle-c8a.js）
  setupC8a(b);
}

// ───────────── 行動の はじめ（battle-c7s.js の c7sTurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c7iTurnStart(b, c, ev, stuck) {
  // 第8章 第1幕（battle-c8a.js）
  c8aTurnStart(b, c, ev, stuck);
  if (c.c7mal) witchTurn(b, c, ev, stuck);
  else if (c.c7shade) shadeTurn(b, c, ev, stuck);
}

function witchTurn(b, c, ev, stuck) {
  const w = c.c7mal;
  const wc = witchConf(c);
  // こわれた いばらのかべが また はえる（魔女の 間だけ）
  const th = thornOf(b);
  if (!w.dragon && th && !th.alive && !w.burnt) {
    w.down--;
    if (w.down <= 0) {
      Object.assign(th, { alive: true, hp: th.maxHp, status: {}, buffs: {}, debuffs: {}, ready: false, queued: false, telegraph: null });
      th.atb = 0;
      const k = b.killed.lastIndexOf(th.species);
      if (k >= 0) b.killed.splice(k, 1);
      ev.lines.push(`${c.name}の前に、また、いばらのかべがのびてきた…！`);
      ev.c7iRegrow = { id: c.id, thorn: th.id };
      ev.upd.push(th);
    } else ev.lines.push(`（いばらが、また、のびようとしている…あと${w.down}回）`);
  }
  if (c.telegraph) return;
  if (!w.dragon) {
    // HP が へったら、次の 番で 黒い 竜に
    if (c.hp / c.maxHp < wc.p2At) {
      if (!stuck) c.telegraph = TRANSFORM;
      ev.upd.push(c);
      return;
    }
    if (w.left <= 1) {
      if (!stuck) c.telegraph = CURSE;
    } else {
      w.left--;
      if (w.left === 1) ev.lines.push(`${c.name}の糸車が、からからと回り出した…！`, '（次にマレフィナが動くと、百年ねむりののろい…！身を守れ！）');
      ev.c7iCurse = { id: c.id, left: w.left, every: wc.curse.every };
    }
    ev.upd.push(c);
    return;
  }
  // 黒い 竜: 黒いほのおのいきまで
  w.left = Math.min(w.left, breathEvery(c));
  if (w.left <= 1) {
    if (!stuck) c.telegraph = BREATH;
  } else {
    w.left--;
    if (w.left === 1) ev.lines.push(`${c.name}のむねが、黒く光り出した…！`, '（次に竜が動くと、黒いほのおのいき…！身を守れ！）');
    ev.c7iBreath = { id: c.id, left: w.left, every: breathEvery(c) };
  }
  ev.upd.push(c);
}

function shadeTurn(b, c, ev, stuck) {
  const s = c.c7shade;
  if (c.telegraph) return;
  // はね返された あとは ふらふら（1回 動けない）
  if (s.daze) {
    s.daze = false;
    if (!stuck) c.telegraph = DAZE;
    ev.upd.push(c);
    return;
  }
  // ねらって いる 人が いる: lead が のこり 1つの 番に ブーメラン
  s.aims = aimed(b, c).map((x) => x.id);
  if (s.aims.length) {
    if (s.lead <= 1) {
      if (!stuck) c.telegraph = THROW;
    } else {
      s.lead--;
      const names = s.aims.map((id) => b.get(id).name).join('と');
      ev.lines.push(`${c.name}は、${names}を、じっとねらっている…`);
      if (s.lead === 1) ev.lines.push(`（次に影が動くと、かげブーメラン…！${names}は身を守れ！）`);
      ev.c7iAimLeft = { id: c.id, who: s.aims.slice(), lead: s.lead };
    }
    ev.upd.push(c);
    return;
  }
  // 2だんめ: はやく なる
  s.left = Math.min(s.left, aimEvery(c));
  if (s.left <= 1) {
    // ねらう（この 番は ふつうに 動く）
    const n = shadeP2(c) ? 2 : 1;
    const pool = b.aliveAllies().slice();
    const picks = [];
    while (picks.length < n && pool.length) picks.push(pool.splice(b.rng.int(0, pool.length - 1), 1)[0]);
    if (!picks.length) return;
    const sc = shadeConf(c);
    s.aims = picks.map((x) => x.id);
    s.lead = Math.max(1, sc.lead);
    s.left = aimEvery(c);
    s.marks++;
    const names = picks.map((x) => x.name).join('と');
    ev.lines.push(`${c.name}の黒いひとみが、${names}をとらえた…！`, `（${names}がねらわれた！ブーメランが来る前に身を守ると、はね返せる！）`);
    ev.c7iMark = { id: c.id, who: s.aims.slice(), lead: s.lead };
    ev.warn = true;
    ev.upd.push(c, ...picks);
    return;
  }
  s.left--;
  ev.c7iShade = { id: c.id, left: s.left, every: aimEvery(c) };
  ev.upd.push(c);
}

// ───────────── 技の こうか（battle-c7s.js の c7sEffect の のこり）─────────────
export function c7iEffect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c7iCurse': curse(b, c, ev); return true;
    case 'c7iTransform': transform(b, c, ev); return true;
    case 'c7iBreath': breath(b, c, ev); return true;
    case 'c7iThrow': throwAt(b, c, ev); return true;
    case 'c7iDaze': daze(b, c, ev); return true;
    // 第8章 第1幕（battle-c8a.js）
    default: return c8aEffect(b, c, a, eff, ev);
  }
}

// 百年ねむりののろい: 身を 守って いない 人を みんな ねむらせる（守って いる 人は はね返す）
function curse(b, c, ev) {
  const w = c.c7mal;
  const wc = witchConf(c);
  if (w) w.left = wc.curse.every;
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a7m_curse', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  const slept = [], safe = [];
  for (const t of targets) {
    if (t.defending) {
      safe.push(t);
      continue;
    }
    if (b.tryStatus(c, t, { status: 'sleep', chance: 1, turns: wc.curse.turns, quiet: true }, ev)) slept.push(t);
  }
  if (safe.length) ev.lines.push(`${safe.map((x) => x.name).join('と')}は、身を守って、のろいをはね返した！`);
  if (w) w.curses++;
  ev.c7iSleep = { id: c.id, slept: slept.map((x) => x.id), safe: safe.map((x) => x.id) };
  ev.warn = true;
  ev.upd.push(c);
}

// 本当の姿: 黒い 竜に 変身（いばらのかべは もえて 消える。ならんで いた 行動・前ぶれは そのまま）
function transform(b, c, ev) {
  const w = c.c7mal;
  const wc = witchConf(c);
  if (!w || w.dragon) return;
  w.dragon = true;
  w.burnt = true;
  w.left = breathEvery(c);
  c.name = DRAGON_NAME;
  c.actions = DRAGON_ACTIONS.map((x) => ({ ...x }));
  c.atk = Math.round(c.atk * (wc.dragon.atk ?? 1));
  c.speed = (c.speed || 1) * (wc.dragon.speed ?? 1);
  ev.fx = { type: 'ability', anim: 'a7m_transform', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('マレフィナの体を、みどりのほのおがつつみこんだ…！', 'マレフィナは、大きな黒い竜に姿をかえた！');
  const th = thornOf(b);
  if (th?.alive) {
    th.alive = false;
    th.hp = 0;
    th.telegraph = null;
    if (th.queued) {
      b.queue = b.queue.filter((q) => q.id !== th.id);
      th.queued = false;
    }
    ev.lines.push('いばらのかべは、ほのおにまかれて、もえつきた！');
    ev.upd.push(th);
  }
  (ev.postLines = ev.postLines || []).push('（黒い竜は、ときどき黒いほのおのいきをはく…！むねが光ったら、身を守れ！）');
  ev.c7iDragon = { id: c.id, thorn: th?.id || null };
  ev.warn = true;
  ev.upd.push(c);
}

// 黒いほのおのいき（みんなに 炎の 物理の 大技。身を 守ると 半分）
function breath(b, c, ev) {
  const w = c.c7mal;
  if (w) {
    w.left = breathEvery(c);
    w.breaths++;
  }
  const bc = witchConf(c).dragon.breath || {};
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a7d_breath', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  for (const t of targets) b.physHit(c, t, { mult: bc.mult ?? 1.3, ignoreDef: bc.ignoreDef ?? 0.3, acc: 1.2 }, ev, 'fire');
  ev.c7iFire = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// かげブーメラン: ねらった 人へ（守って いれば はね返す）
function throwAt(b, c, ev) {
  const s = c.c7shade;
  const sc = shadeConf(c);
  const list = s ? aimed(b, c) : [];
  if (s) {
    s.aims = [];
    s.lead = 0;
    s.left = aimEvery(c);
    s.throws++;
  }
  if (!list.length) {
    ev.lines.push('しかし、ねらった相手が、もういない！');
    return;
  }
  ev.fx = { type: 'ability', anim: 'a7h_throw', actor: c.id, targets: list.map((x) => x.id), side: 'enemy' };
  const back = [], hit = [];
  let reflected = 0;
  for (const t of list) {
    if (!c.alive) break;
    if (t.defending) {
      back.push(t);
      ev.lines.push(`${t.name}は、身を守って、かげブーメランをはね返した！`);
      const dmg = Math.max(1, Math.round(c.maxHp * (sc.reflect ?? 0.05)));
      b.damage(t, c, dmg, ev, { element: 'phys' });
      reflected++;
    } else {
      hit.push(t);
      b.physHit(c, t, { mult: sc.hit.mult ?? 2.0, ignoreDef: sc.hit.ignoreDef ?? 0.3, acc: 1.3 }, ev, 'phys');
    }
  }
  // もどってくる ブーメラン（当たった ぶんだけ。ねらわれて いない 人へ）
  if (hit.length && c.alive) {
    const others = b.aliveAllies().filter((x) => !list.includes(x));
    if (others.length) ev.lines.push('もどってくるブーメランが、みんなをおそった！');
    for (const x of others) for (let i = 0; i < hit.length; i++) b.physHit(c, x, { mult: sc.back.mult ?? 0.55, ignoreDef: sc.back.ignoreDef ?? 0.2, acc: 1.1 }, ev, 'phys');
  }
  if (s) {
    s.reflects += reflected;
    s.hits += hit.length;
  }
  if (reflected && c.alive) {
    // ふらつく: 次の 番は 動けない・守りが 下がる
    if (s && sc.daze) s.daze = true;
    c.debuffs.def = { mult: sc.stagger ?? 0.8, lv: 1, left: BUFF_ACTS };
    (ev.postLines = ev.postLines || []).push(`${c.name}は、はね返されたブーメランに当たって、ふらついた！（守りが下がった）`);
  }
  ev.c7iThrow = { id: c.id, back: back.map((x) => x.id), hit: hit.map((x) => x.id) };
  ev.warn = !!hit.length;
  ev.upd.push(c, ...list);
}

function daze(b, c, ev) {
  ev.c7iDaze = { id: c.id };
}

// ───────────── ダメージ（battle-c7s.js の c7sDamage の さいご。味方 → 敵 だけ）─────────────
// いばらのかべが ある 間の 魔女は cut ばい。変身の 前は HP が p2At より 下がらない
export function c7iDamage(b, c, t, dmg, info, ev) {
  // 第8章 第1幕: イアゴンの 聞き耳・ジャハールの とぐろ・のびきり・ランプの 中・変身の 前（battle-c8a.js）
  dmg = c8aDamage(b, c, t, dmg, info, ev);
  if (!(dmg > 0) || !t.c7mal || t.c7mal.dragon) return dmg;
  const wc = witchConf(t);
  if (thornUp(b)) {
    dmg = Math.max(1, Math.round(dmg * wc.thorn.cut));
    if (!ev.c7iCut) {
      ev.c7iCut = true;
      (ev.postLines = ev.postLines || []).push('いばらのかべにはばまれて、ダメージが小さくなった…！');
    }
  }
  const floor = Math.ceil(t.maxHp * wc.p2At) - 1;
  if (t.hp - dmg < floor) dmg = Math.max(0, t.hp - floor);
  return dmg;
}

// ───────────── たおれた（battle-c7s.js の c7sKill の さいご）─────────────
// いばらのかべ: 魔女が regrow 回 動くと また はえる
export function c7iKill(b, t, ev) {
  // 第8章 第1幕: へびのつえ・黒いランプが こわれた（battle-c8a.js）
  c8aKill(b, t, ev);
  if (!isThorn(t)) return;
  const w = witchOf(b);
  if (!w?.c7mal || w.c7mal.dragon) return;
  w.c7mal.down = witchConf(w).thorn.regrow;
  w.c7mal.breaks++;
  if (!ev) return;
  (ev.postLines = ev.postLines || []).push('いばらのかべが、くずれおちた！', `（今なら、${w.name}にダメージがとどく！）`);
  ev.c7iBreak = { id: w.id, thorn: t.id };
  ev.upd.push(w);
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// のろい・いき（みんなへの 大技）が c の 次の 番より 先に 来るか
export function witchBigBefore(b, c, w = witchOf(b)) {
  if (!w?.c7mal) return false;
  if (w.telegraph === CURSE || w.telegraph === BREATH) return true;
  if (w.telegraph === TRANSFORM) return false;
  if (!w.c7mal.dragon && w.hp / w.maxHp < witchConf(w).p2At) return false;
  return actsBefore(b, c, w) >= w.c7mal.left;
}
// かげブーメランが c の 次の 番より 先に c に 来るか（c が ねらわれて いる とき）
export function throwBefore(b, c, s = shadeOf(b)) {
  if (!s?.c7shade || !s.c7shade.aims.includes(c.id)) return false;
  if (s.telegraph === THROW) return true;
  return actsBefore(b, c, s) >= Math.max(1, s.c7shade.lead);
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。{ cmd, dmg }）
function bestHit(b, c, t) {
  const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
  let best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}

// ───────────── オート（battle-c7s.js の c7sPlan の はじめ）─────────────
// 第7章 第3幕の ボスが いなければ null（ほかの ボスの 考えへ）
export function c7iPlan(b, c, decide) {
  if (c.side !== 'ally' || b.c7iInner || c.status?.rift) return null;
  // 第8章 第1幕の ボス（イアゴン・ジャハール。battle-c8a.js）
  const ap = c8aPlan(b, c, decide);
  if (ap) return ap;
  const w = witchOf(b);
  const s = shadeOf(b);
  if (!w && !s) return null;
  const soon = w ? witchBigBefore(b, c, w) : throwBefore(b, c, s);
  // ふつうの オート: 大技が 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  if (!b.knowsCh6) {
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c7iInner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c7iInner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  // カイの影: ねらわれたら 身を 守って はね返す（回復より 先）
  if (s && soon && !b.c7iNoGuardAim) return { type: 'defend' };
  if (saving) return base;
  if (w) {
    if (soon && !b.c6NoGuard) return { type: 'defend' };
    // いばらのかべを 先に こわす（炎の 技が あれば 炎が いちばん 大きい。敵みんなへの 技は そのまま … かべにも 当たる）
    const th = thornOf(b);
    if (th?.alive && !w.c7mal.dragon && !b.c7iNoThorn) {
      if (a?.target !== 'enemies') {
        const h = bestHit(b, c, th);
        if (h.dmg > 0) return h.cmd;
      }
    }
    return base;
  }
  return base;
}

// ───────────── がめんへ（battle-c7s.js の c7sPub の さいご）─────────────
// マレフィナ: c7form（1 魔女・2 黒い 竜）・curseLeft・curseEvery（のろいまで）・breathLeft・breathEvery（いきまで）・thornDown（かべが また はえるまで）・cut（かべの 間の ダメージの ばい）
// いばらのかべ: c7thorn
// カイの影: aimLeft・aimEvery（ねらいまで）・aims（ねらわれた 人の id）・aimLead（ブーメランまで）・daze・p2（かげぶんしん）
export function c7iPub(c, o) {
  // 第8章 第1幕（battle-c8a.js）
  c8aPub(c, o);
  if (c.c7mal) {
    const wc = witchConf(c);
    o.c7form = c.c7mal.dragon ? 2 : 1;
    if (c.c7mal.dragon) {
      o.breathLeft = c.c7mal.left;
      o.breathEvery = breathEvery(c);
    } else {
      o.curseLeft = c.c7mal.left;
      o.curseEvery = wc.curse.every;
      if (c.c7mal.down > 0) o.thornDown = c.c7mal.down;
      o.cut = wc.thorn.cut;
    }
  }
  if (isThorn(c)) o.c7thorn = 1;
  if (c.c7shade) {
    o.aimLeft = c.c7shade.left;
    o.aimEvery = aimEvery(c);
    o.aims = c.c7shade.aims.slice();
    o.aimLead = c.c7shade.lead;
    if (c.c7shade.daze) o.daze = 1;
    if (shadeP2(c)) o.p2 = 1;
  }
}

