// 第2部 第7章 第2幕「海の紋章」の ボスの 戦いの しかけ（battle-c7.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・海賊船ジョリーホック号（monsters-c7s.js の c7s.kind 'tide'。Step 3 の さいごの 中ボス）「しおの満ち引き」
//   満ち潮（c.c7tide.phase 'high'）: 船が 1回 動く たびに しるし（c.c7tide.left。はじめは tide.high）が 1つ へる。
//     しるしが 1つの ときに 船が 動くと、かならず「いっせいほうげき」（m7r_broadside。みんなに 物理の 大技。身を 守ると 半分）。
//   ほうげきの はんどうで 引き潮（'low'）に なり、船は サンゴしょうに のり上げる: tide.low 回 動く 間、たるが ころがる だけ（m7r_stuck）・
//     受ける ダメージが tide.aground ばい（「今が チャンス！」）。tide.low 回めの 行動で しおが 満ちて、うき上がる（その 番は ふつうに 動く）。
//   HP が p2At より へると 満ち潮の しるしが p2High に（ほうげきが はやく 来る）
// ・ホック船長（c7s.kind 'captain'。しずむ前の島の灯台の ボス）「板わたり」
//   every 回 動く たびに（しるし c.c7cap.left）「板わたりの号令」（m7l_plank）: 1人を 灯台から 海へ のびる 板の 先へ 歩かせる。
//   その 人は 動けない・回復も とどかない（battle-earth.js の 地われと おなじ status.rift。kind 'plank'）。
//   合体技の よやくを して いる 人が いれば その 組の 人を ねらい、組の みんなの 手を ひきはなす（ゲージは 0 から。ノクトの 地われと おなじ）。
//   船長が 動く たびに 1歩 すすみ、さいごの 1歩で かならず「ドボン！」（m7l_drop）: その 人は 海へ 落ちて 戦えなくなり、
//   大波が みんなを おそう（物理の 大技。身を 守ると 半分）。仲間が「手をのばす」と すぐ もどる（地われと おなじ コマンド）。
//   板の 上に 人が いる 間は、号令の しるしは すすまない。
//   HP が p2At より へると（2だんめ）every が p2Every に（はやく なる）。船長が たおれると 板の 上の 人は もどる
// ・ふつうの オート（家族が「オート」に した とき）: いっせいほうげきが 自分の 次の 番より 先に 来る とき、HPが へっていれば よく 身を 守る
//   （battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ。b.c6Naive … しない 人）。板の 上の 人は「手をのばす」（ai.js の reachPlan。回復の あと）
// ・知っている 人（シミュレーター tools/sim-ch7.mjs。b.knowsCh6）: いっせいほうげきの 前に 身を 守る（b.c6NoGuard … しない）／
//   のり上げて いる 間は いちばん ダメージの 大きい 攻撃（b.c7sNoFocus … しない）／板の 上の 人を 回復より 先に 助ける（b.c7sNoReach … ふつうと おなじ）／
//   合体技は 板わたりの号令の すぐ 前と、板の 上に 人が いる 間は しない（シミュレーターの dual7）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C7_REEF, C7_LIGHT } from './data/monsters-c7s.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';
import { TRAP_KINDS, REACH } from './battle-earth.js';
// 合体技の よやくの 組（ノクトの 地われと おなじ。板わたりは 組の 人を ねらって、手を ひきはなす）
import { bondTeams, breakTeam } from './battle-nocto.js';
// 第2部 第7章 第3幕: いばらの魔女マレフィナ（いばらのかべ・黒い 竜）・カイの影（かげブーメラン）。battle-c7i.js
import { setupC7i, c7iTurnStart, c7iEffect, c7iPlan, c7iPub, c7iDamage, c7iKill } from './battle-c7i.js';

export { C7_REEF, C7_LIGHT };
export const BROADSIDE = 'm7r_broadside';
export const STUCK = 'm7r_stuck';
export const PLANK = 'm7l_plank';
export const DROP = 'm7l_drop';
export const PLANK_KIND = 'plank';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});

const c7sConf = (m) => MONSTERS[m?.species]?.c7s || null;
const tideConf = (m) => ({ high: 4, low: 3, p2At: 0.5, p2High: 3, broadside: {}, aground: 1.5, ...(c7sConf(m)?.tide || {}) });
const plankConf = (m) => ({ every: 3, p2At: 0.5, p2Every: 2, steps: 1, wave: {}, ...(c7sConf(m)?.plank || {}) });
const tideP2 = (c) => c.hp / c.maxHp < tideConf(c).p2At;
const highOf = (c) => (tideP2(c) ? tideConf(c).p2High : tideConf(c).high);
const capP2 = (c) => c.hp / c.maxHp < plankConf(c).p2At;
const everyOf = (c) => (capP2(c) ? plankConf(c).p2Every : plankConf(c).every);
const shipOf = (b) => b.enemies.find((e) => e.c7tide && e.alive) || null;
const captainOf = (b) => b.enemies.find((e) => e.c7cap && e.alive) || null;
// 板の 上の 人（もどった・たおれた ときは null）
export function plankWho(b, cap) {
  const id = cap?.c7cap?.who;
  const x = id ? b.get(id) : null;
  return x?.alive && x.status?.rift?.kind === PLANK_KIND ? x : null;
}
export const aground = (m) => m?.c7tide?.phase === 'low';

// 板わたり（battle-earth.js の 地われと おなじ status.rift の ことばだけ かえる）
const PLANK_TEXT = {
  name: '板の上',
  // 板の 上の 人の 番: 動けない（自分では もどれない。船長が 動くと 1歩 すすむ・さいごの 1歩で ドボン）
  turn(b, c, ev) {
    ev.name = '板の上';
    ev.fx = { type: 'n1RiftTurn', actor: c.id, kind: PLANK_KIND };
    ev.lines.push(`${c.name}は、板の上で、足がすくんで動けない…！`);
  },
  reach(t, c, by, ev) {
    ev.c7sSave = { who: t.id, by: c.id };
    return [`${t.name}は、その手をつかんで、板の上からとびもどった！`];
  },
  free: (x) => `${x.name}は、板の上から、灯台へもどってきた！`,
};

// ───────────── はじめ（battle-c7.js の setupC7 の さいご）─────────────
export function setupC7s(b) {
  const lines = [];
  for (const e of b.enemies) {
    const conf = c7sConf(e);
    if (!conf) continue;
    if (conf.kind === 'tide') {
      const h = highOf(e);
      e.c7tide = { phase: 'high', left: h, max: h, broadsides: 0, grounds: 0 };
      lines.push(`${e.name}が、満ち潮にのって、ぐんぐん近づいてくる…！`, '（しおが満ちきると、たいほうをいっせいにうってきそうだ…！）');
    }
    if (conf.kind === 'captain') {
      TRAP_KINDS[PLANK_KIND] = PLANK_TEXT;
      e.c7cap = { left: everyOf(e), who: null, steps: 0, planks: 0, falls: 0, saves: 0 };
      lines.push('灯台のてっぺんから、海の上へ、長い板がつき出している…！', `${e.name}「ようこそ、わしの灯台へ。板わたりの用意は、できておるぞ…！」`, '（板の上に歩かされたら、仲間が「手をのばす」と助けられる…！）');
    }
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
  // 第7章 第3幕の ボス（battle-c7i.js）
  setupC7i(b);
}

// ───────────── 行動の はじめ（battle-c7.js の c7TurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c7sTurnStart(b, c, ev, stuck) {
  c7iTurnStart(b, c, ev, stuck);
  if (c.c7tide) tideTurn(b, c, ev, stuck);
  else if (c.c7cap) capTurn(b, c, ev, stuck);
}

function tideTurn(b, c, ev, stuck) {
  const t = c.c7tide;
  if (c.telegraph) return;
  if (t.phase === 'high') {
    t.max = highOf(c);
    t.left = Math.min(t.left, t.max);
    if (t.left <= 1) {
      if (!stuck) c.telegraph = BROADSIDE;
    } else {
      t.left--;
      ev.lines.push(t.left > 1 ? `しおが満ちてくる…（いっせいほうげきまで、あと${t.left}）` : 'しおが、いっぱいに満ちた…！船のたいほうが、全部こちらをむいた！');
      if (t.left === 1) ev.lines.push('（次に船が動くと、いっせいほうげき…！身を守れ！）');
      ev.c7sTide = { id: c.id, phase: 'high', left: t.left, max: t.max };
    }
    ev.upd.push(c);
    return;
  }
  // 引き潮: サンゴしょうに のり上げて いる（たるが ころがる だけ）。low 回めで しおが 満ちる
  t.left--;
  if (t.left <= 0) {
    t.phase = 'high';
    t.max = highOf(c);
    t.left = t.max;
    ev.lines.push(`しおが満ちてきた！${c.name}が、サンゴしょうからうき上がった！`, `（いっせいほうげきまで、あと${t.left}）`);
    ev.c7sTide = { id: c.id, phase: 'high', left: t.left, max: t.max, float: true };
  } else {
    if (!stuck) c.telegraph = STUCK;
    ev.lines.push(`${c.name}は、サンゴしょうにのり上げたまま…（しおが満ちるまで、あと${t.left}）`);
    ev.c7sTide = { id: c.id, phase: 'low', left: t.left };
  }
  ev.upd.push(c);
}

function capTurn(b, c, ev, stuck) {
  const p = c.c7cap;
  if (c.telegraph) return;
  // 板の 上の 人（もどった・たおれた ときは もう いない）: 1歩 すすむ・さいごの 1歩で ドボン（号令の しるしは すすまない）
  const who = plankWho(b, c);
  if (!who) p.who = null;
  else {
    if (p.steps <= 1) {
      if (!stuck) c.telegraph = DROP;
    } else {
      p.steps--;
      ev.lines.push(`${who.name}は、板の先へ、1歩…（海まで、あと${p.steps}歩）`);
      if (p.steps === 1) ev.lines.push('（次に船長が動くと、海へドボン…！早く「手をのばす」！）');
      ev.c7sStep = { id: c.id, who: who.id, steps: p.steps };
      ev.warn = true;
      ev.upd.push(who);
    }
    ev.upd.push(c);
    return;
  }
  // 2だんめ: はやく なる
  p.left = Math.min(p.left, everyOf(c));
  if (p.left <= 1) {
    if (!stuck) c.telegraph = PLANK;
  } else {
    p.left--;
    if (p.left === 1) ev.lines.push(`${c.name}が、板の方を、ちらりと見た…（次に動くと、板わたりの号令！）`);
    ev.c7sCap = { id: c.id, left: p.left, every: everyOf(c) };
  }
  ev.upd.push(c);
}

// ───────────── 技の こうか（battle-c7.js の c7Effect の のこり）─────────────
export function c7sEffect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c7sBroadside': broadside(b, c, ev); return true;
    case 'c7sPlank': plank(b, c, ev); return true;
    case 'c7sDrop': drop(b, c, ev); return true;
    // 第7章 第3幕（battle-c7i.js）
    default: return c7iEffect(b, c, a, eff, ev);
  }
}

// いっせいほうげき（満ち潮の さいご）→ 引き潮で のり上げる
function broadside(b, c, ev) {
  const t = c.c7tide;
  const tc = tideConf(c);
  const sc = tc.broadside || {};
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a7r_broadside', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  for (const x of targets) b.physHit(c, x, { mult: sc.mult ?? 1.0, ignoreDef: sc.ignoreDef ?? 0.3, acc: 1.2 }, ev, 'phys');
  ev.c7sBroadside = { id: c.id };
  ev.warn = true;
  if (!t || !c.alive) return;
  t.phase = 'low';
  t.left = tc.low;
  t.broadsides++;
  t.grounds++;
  const post = (ev.postLines = ev.postLines || []);
  post.push(`いっせいほうげきのはんどうで、${c.name}が、サンゴしょうにのり上げた！`, `しおが引いていく…（今がチャンス！船が受けるダメージが${tc.aground}倍）`);
  ev.c7sGround = { id: c.id, left: t.left, k: tc.aground };
  ev.upd.push(c);
}

// 板わたりの号令: 1人を 板の 先へ（もう だれかが 板の 上・のこりが 2人より 少ない ときは できない）
function plank(b, c, ev) {
  const p = c.c7cap;
  if (p) p.left = everyOf(c);
  const free = b.aliveAllies().filter((x) => !x.status?.rift);
  if (!p || plankWho(b, c) || free.length < 2) {
    ev.lines.push('しかし、だれも板の上に乗せられなかった！');
    return;
  }
  // 合体技の よやくの 組の 人を ねらう（手を ひきはなす）
  const teams = bondTeams(b);
  const team = teams.flatMap((tm) => tm.members).filter((x) => free.includes(x));
  const t = b.rng.pick(team.length ? team : free);
  const torn = teams.filter((tm) => tm.members.includes(t));
  trapPlank(b, t, c);
  for (const tm of torn) {
    breakTeam(b, tm, ev);
    ev.lines.push(`${tm.members.map((x) => x.name).join('と')}の、つながろうとしていた手が、ひきはなされた！`);
  }
  if (torn.length) ev.n1Torn = torn.length;
  p.who = t.id;
  p.steps = plankConf(c).steps;
  p.planks++;
  ev.fx = { type: 'ability', anim: 'a7l_plank', actor: c.id, targets: [t.id], side: 'enemy' };
  ev.lines.push(`${t.name}は、かぎにひっかけられて、板の上へ歩かされた！`, `（動けない！回復もとどかない…！海まで、あと${p.steps}歩）`);
  (ev.postLines = ev.postLines || []).push(p.steps <= 1 ? '（次に船長が動くと、海へドボン…！すぐに「手をのばす」！）' : '（仲間が「手をのばす」と、すぐに助けられる！）');
  ev.c7sPlank = { id: c.id, who: t.id, steps: p.steps };
  ev.warn = true;
  ev.upd.push(t, c);
}

// 動けなく する（battle-earth.js の trap と おなじ。ならんで いた 行動・合体技の よやく・さそいも とりやめ）
function trapPlank(b, t, by) {
  t.status.rift = { turns: 99, by: by.id, kind: PLANK_KIND };
  for (const q of b.queue) if (q.id === t.id && q.cmd?.type === 'dual') b.releasePartners(q.cmd);
  b.queue = b.queue.filter((q) => q.id !== t.id);
  if (t.waitDual) b.endWait(t, null, false);
  for (const inv of [...b.invites.values()]) if (inv.from === t.id || inv.to === t.id || inv.partners?.includes(t.id)) b.endInvite(inv, '動けない');
  Object.assign(t, { ready: false, queued: false, defending: false, cover: null, atb: 0 });
}

// ドボン！: 板の 上の 人は 海へ（戦えなくなる。生き返りの 呪文・道具で もどる）→ 大波が みんなを おそう
function drop(b, c, ev) {
  const p = c.c7cap;
  const who = plankWho(b, c);
  if (!p || !who) {
    ev.lines.push('しかし、板の上には、もうだれもいない！');
    return;
  }
  p.who = null;
  p.steps = 0;
  p.falls++;
  delete who.status.rift;
  ev.lines.push(`${who.name}は、板の先から、海へドボン！`, ...b.kill(who, null, ev));
  const wc = plankConf(c).wave || {};
  const targets = b.aliveAllies().filter((x) => !x.status?.rift);
  ev.fx = { type: 'ability', anim: 'a7l_drop', actor: c.id, targets: [who.id, ...targets.map((x) => x.id)], side: 'enemy' };
  ev.lines.push('ザッブーン！大波が、灯台のてっぺんまでおしよせた！');
  for (const x of targets) b.physHit(c, x, { mult: wc.mult ?? 1.0, ignoreDef: wc.ignoreDef ?? 0.3, acc: 1.2 }, ev, 'phys');
  ev.c7sFall = { id: c.id, who: who.id };
  ev.warn = true;
  ev.upd.push(who, c);
}

// ───────────── ダメージ（battle-c7.js の c7Damage。味方 → 敵 だけ）─────────────
// のり上げた 船は 受ける ダメージが aground ばい
export function c7sDamage(b, c, t, dmg, info, ev) {
  if (dmg > 0 && aground(t)) return Math.round(dmg * tideConf(t).aground);
  // 第7章 第3幕: いばらのかべの 間の 魔女・変身の 前の 魔女（battle-c7i.js）
  return c7iDamage(b, c, t, dmg, info, ev);
}

// ───────────── たおれた（battle-c7.js の c7Kill の はじめ）─────────────
// 船長が たおれた ときの 板の 上の 人は battle-earth.js の earthKill が もどす（文は PLANK_TEXT.free）
export function c7sKill(b, t, ev) {
  if (t.c7cap) t.c7cap.who = null;
  // 第7章 第3幕: いばらのかべが くずれた（battle-c7i.js）
  c7iKill(b, t, ev);
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// いっせいほうげきが c の 次の 番より 先に 来るか
export function broadsideBefore(b, c, ship = shipOf(b)) {
  if (!ship?.c7tide || ship.c7tide.phase !== 'high') return false;
  if (ship.telegraph === BROADSIDE) return true;
  return actsBefore(b, c, ship) >= ship.c7tide.left;
}
// 板の 上の 人が c の 次の 番より 先に 海へ 落ちるか（ドボンの 大波が 来るか）
export function fallBefore(b, c, cap = captainOf(b)) {
  if (!cap?.c7cap || !plankWho(b, cap)) return false;
  if (cap.telegraph === DROP) return true;
  return actsBefore(b, c, cap) >= Math.max(1, cap.c7cap.steps);
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。{ cmd, dmg }）
function bestHit(b, c, t) {
  const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
  let best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}

// ───────────── オート（battle-c7.js の c7Plan の はじめ）─────────────
// 第7章 第2幕の ボスが いなければ null（ほかの ボスの 考えへ）
export function c7sPlan(b, c, decide) {
  if (c.side !== 'ally' || b.c7sInner || c.status?.rift) return null;
  // 第7章 第3幕の ボス（マレフィナ・カイの影。battle-c7i.js）
  const ip = c7iPlan(b, c, decide);
  if (ip) return ip;
  const ship = shipOf(b);
  const cap = captainOf(b);
  if (!ship && !cap) return null;
  // ふつうの オート: ほうげきが 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る（板わたりは ai.js の reachPlan）
  if (!b.knowsCh6) {
    if (b.c6Naive || !ship || !broadsideBefore(b, c, ship)) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c7sInner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c7sInner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  if (ship) {
    if (broadsideBefore(b, c, ship) && !b.c6NoGuard) return { type: 'defend' };
    // のり上げて いる 間は いちばん 大きい 攻撃（回復・補助より 先。HPが へっている 人が いる ときは ふだんの 行動）
    if (aground(ship) && !b.c7sNoFocus && !b.allies.some((x) => !x.fled && x.alive && x.hp / x.maxHp < 0.5)) {
      const h = bestHit(b, c, ship);
      if (h.dmg > 0) return h.cmd;
    }
    return base;
  }
  // ホック船長: 板の 上の 人を 回復より 先に 助ける（とても あぶない 人の 回復・生き返りは 上で そのまま）
  const who = plankWho(b, cap);
  if (who && who !== c && !b.c7sNoReach) return { type: REACH, target: who.id };
  return base;
}

// ───────────── がめんへ（battle-c7.js の c7Pub の さいご）─────────────
// ジョリーホック号: tide（1 満ち潮・2 のり上げ）・tideLeft・tideMax・aground（ダメージの ばい）
// ホック船長: capLeft・capEvery（板わたりまで）・plankWho（板の 上の 人の id）・plankSteps（海まで）・plankMax・p2
export function c7sPub(c, o) {
  // 第7章 第3幕（battle-c7i.js）
  c7iPub(c, o);
  if (c.c7tide) {
    o.c7tide = c.c7tide.phase === 'low' ? 2 : 1;
    o.c7tideLeft = c.c7tide.left;
    o.c7tideMax = c.c7tide.phase === 'low' ? tideConf(c).low : c.c7tide.max;
    if (c.c7tide.phase === 'low') o.aground = tideConf(c).aground;
  }
  if (c.c7cap) {
    o.capLeft = c.c7cap.left;
    o.capEvery = everyOf(c);
    o.plankWho = c.c7cap.who || null;
    o.plankSteps = c.c7cap.who ? c.c7cap.steps : 0;
    o.plankMax = plankConf(c).steps;
    if (capP2(c)) o.p2 = 1;
  }
}

js/shared/battle-c8a.js:
// 第2部 第8章 第1幕「月の王宮の うらぎり」の ボスの 戦いの しかけ（battle-c7i.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・オウムのイアゴン（monsters-c8a.js の c8a.kind 'parrot'。Step 1 の さいごの 中ボス）「オウムがえし」
//   every 回 動く たびに（しるし c.c8par.left）「オウムがえし」（m8p_echo）。しるしが のこり listen いかの 間は「聞き耳」:
//   その 間に 味方が イアゴンに 当てた 呪文（ダメージの ある 呪文。1回の 行動で 1つ）を 覚える（max まで。頭の 上の ふきだし）。
//   オウムがえし: 覚えた 呪文を みんなに はね返す（覚えた 数だけ 強い・さいごの 呪文の 属性・身を 守ると 半分）。
//   何も 覚えて いないと しっぱいして 目を まわす（次の 番は 動けない・守りが dizzy ばい）。HP が p2At より へると every が p2Every に
// ・大臣ジャハール（c8a.kind 'vizier'。第1幕の さいごの ボス。3だん）
//   1だんめ（へびの つえの 魔術師）「さいみんじゅつ」: 横に へびのつえ（c8_staff。べつの 敵）。staff.every 回 動く たびに（しるし c.c8viz.left）
//     さいみんじゅつ（m8j_hypno）… 1人を あやつる（こんらん）。つえが こわれると、あやつられた 人は 目を さまし、ジャハールは うろたえて 1回 動けない
//     （ならべて いた さいみんじゅつも とりやめ）。つえは ジャハールが staff.regrow 回 動くと もどる。つえが ない 間は しるしは すすまない
//   HP が p2At より へると、次の 番に「大へびの姿」（m8j_cobra）… 大きな コブラに。それまで HP は p2At より 下がらない。つえは 消える
//   2だんめ（大きな コブラ）「とぐろ」: cobra.every 回 動く たびに「とぐろをまく」（m8c_coil）。とぐろの 間に コブラを 攻撃すると、
//     その 人に かみつく（カウンター。1回の 行動で 1回）。次の コブラの 番に かならず「大へびのいちげき」（m8c_strike。みんなに 物理の 大技。
//     かみついた 数だけ 強い・身を 守ると 半分）。だれも 攻撃して いなければ からぶりして のびきる（open.turns 回 動く 間、受ける ダメージが open.k ばい）
//   HP が p3At より へると、次の 番に「ランプの魔人」（m8c_genie）。横に 黒いランプ（c8_lamp。b.addEnemies）が あらわれる。それまで HP は p3At より 下がらない
//   3だんめ（ランプの 魔人）「ランプ」: genie.every 回 動く たびに「むげんの魔力」（m8g_blast。みんなに 闇の 大技。身を 守ると 半分）。
//     黒いランプを こわすと、魔人は 自分の ランプに すいこまれる（ならべて いた 大技も とりやめ）: seal.turns 回 動けない・受ける ダメージ seal.k ばい。
//     出てくると、ランプに また 火が ともる（HP は lampGrow ばいずつ ふえる）。HP が p4At より へると every が p4Every に
// ・ふつうの オート（家族が「オート」に した とき）: 大技（オウムがえし・いちげき・むげんの魔力）が 自分の 次の 番より 先に 来る とき、
//   HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ。b.c6Naive … しない 人）
// ・知っている 人（シミュレーター tools/sim-ch8.mjs。b.knowsCh6）:
//   イアゴン … 聞き耳の 間は 呪文を 当てない（物理の 攻撃に かえる。b.c8aNoQuiet … しない）・オウムがえしの 前に（覚えて いれば）身を 守る（b.c6NoGuard）
//   ジャハール … さいみんじゅつが 近い ときは つえを こわす（b.c8aNoStaff）・とぐろの 間は コブラを 攻撃しない（b.c8aNoCoil）・
//     黒いランプを 先に こわす（b.c8aNoLamp）・むげんの魔力の 前に 身を 守る（b.c6NoGuard）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C8_PET, C8_JAFAR, C8_STAFF, C8_LAMP, COBRA_ACTIONS, GENIE_ACTIONS } from './data/monsters-c8a.js';
import { BUFF_ACTS } from './buff-acts.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate, pub } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';
// 第2部 第8章 第2幕: ペイニックと パニクル（ばけばけ大作戦）・よみの王ハデロス（たましいのけいやく → おこった 赤い 炎）。battle-c8b.js
import { setupC8b, c8bTurnStart, c8bEffect, c8bPlan, c8bPub, c8bDamage, c8bKill } from './battle-c8b.js';

export { C8_PET, C8_JAFAR, C8_STAFF, C8_LAMP };
export const ECHO = 'm8p_echo';
export const DIZZY = 'm8p_dizzy';
export const HYPNO = 'm8j_hypno';
export const DAZE = 'm8j_daze';
export const COBRA = 'm8j_cobra';
export const COIL = 'm8c_coil';
export const STRIKE = 'm8c_strike';
export const GENIE = 'm8c_genie';
export const BLAST = 'm8g_blast';
export const SEALED = 'm8g_sealed';
export const COBRA_NAME = '大へびジャハール';
export const GENIE_NAME = '魔人ジャハール';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});
// 属性の よびかた（オウムがえしの ことば）
const EL_NAME = { fire: '炎', ice: '氷', bolt: '雷', wind: '風', light: '光', dark: '闇', water: '水', blast: 'ばくはつ', void: '魔法' };

const confOf = (m) => MONSTERS[m?.species]?.c8a || null;
export const parrotConf = (m) => ({ every: 4, listen: 2, max: 3, echo: { base: [180, 200], per: 0.5 }, p2At: 0.5, p2Every: 3, dizzy: 0.8, ...(confOf(m)?.parrot || {}) });
export function vizierConf(m) {
  const c = confOf(m) || {};
  return {
    staff: { every: 4, regrow: 4, hypno: { n: 1, turns: [2, 3] }, ...(c.staff || {}) },
    p2At: c.p2At ?? 0.67,
    cobra: { every: 3, counter: { mult: 0.85, ignoreDef: 0.3 }, strike: { mult: 0.9, per: 0.25, max: 2.0, ignoreDef: 0.3 }, open: { k: 1.5, turns: 2 }, atk: 1.06, ...(c.cobra || {}) },
    p3At: c.p3At ?? 0.34,
    genie: { every: 3, p4At: 0.15, p4Every: 2, blast: { base: [220, 250] }, seal: { turns: 3, k: 1.6 }, lampGrow: 1.25, atk: 1.04, ...(c.genie || {}) },
  };
}
export const isStaff = (m) => !!MONSTERS[m?.species]?.c8staff;
export const isLamp = (m) => !!MONSTERS[m?.species]?.c8lamp;
export const staffOf = (b) => b.enemies.find((e) => isStaff(e) && !e.fled) || null;
export const lampOf = (b) => b.enemies.find((e) => isLamp(e) && !e.fled) || null;
const parrotOf = (b) => b.enemies.find((e) => e.c8par && e.alive) || null;
const vizierOf = (b) => b.enemies.find((e) => e.c8viz && e.alive) || null;
export const staffUp = (b) => !!staffOf(b)?.alive;
export const lampUp = (b) => !!lampOf(b)?.alive;
export const formOf = (m) => m?.c8viz?.form || 0;
const echoEvery = (c) => {
  const pc = parrotConf(c);
  return c.hp / c.maxHp < pc.p2At ? pc.p2Every : pc.every;
};
const blastEvery = (c) => {
  const g = vizierConf(c).genie;
  return c.hp / c.maxHp < g.p4At ? g.p4Every : g.every;
};
// イアゴンが 聞き耳を して いるか（オウムがえしの 前の listen 回）
export function listening(p) {
  if (!p?.c8par || p.c8par.dizzy) return false;
  return p.telegraph === ECHO || p.c8par.left <= parrotConf(p).listen;
}

// ───────────── はじめ（battle-c7i.js の setupC7i の さいご）─────────────
export function setupC8a(b) {
  const lines = [];
  for (const e of b.enemies) {
    const conf = confOf(e);
    if (!conf) continue;
    if (conf.kind === 'parrot') {
      e.c8par = { left: echoEvery(e), words: [], dizzy: false, echoes: 0, empties: 0, heard: 0 };
      lines.push(`${e.name}「ジャハールさまのじゃまは、させないぞー！」`, '（イアゴンは、聞いた呪文をまねするらしい…！耳をすませている間は、呪文をひかえよう…！）');
    }
    if (conf.kind === 'vizier') {
      e.c8viz = { form: 1, left: vizierConf(e).staff.every, down: 0, daze: false, hypno: [], hypnos: 0, breaks: 0, coiled: false, counters: 0, open: 0, coils: 0, strikes: 0, whiffs: 0, seal: 0, seals: 0, blasts: 0 };
      lines.push(`${e.name}「フフフ…このへびのつえの前では、だれもさからえぬ…」`, '（へびのつえの目が、あやしく光っている…！こわせば、さいみんじゅつは使えないはずだ！）');
    }
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
  // 第8章 第2幕の ボス（battle-c8b.js）
  setupC8b(b);
}

// ───────────── 行動の はじめ（battle-c7i.js の c7iTurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c8aTurnStart(b, c, ev, stuck) {
  // 第8章 第2幕（battle-c8b.js）
  c8bTurnStart(b, c, ev, stuck);
  if (c.c8par) parrotTurn(b, c, ev, stuck);
  else if (c.c8viz) vizierTurn(b, c, ev, stuck);
}

function parrotTurn(b, c, ev, stuck) {
  const p = c.c8par;
  const pc = parrotConf(c);
  if (c.telegraph) return;
  // オウムがえしに しっぱいして 目を まわして いる（1回 動けない）
  if (p.dizzy) {
    p.dizzy = false;
    if (!stuck) c.telegraph = DIZZY;
    ev.upd.push(c);
    return;
  }
  p.left = Math.min(p.left, echoEvery(c));
  if (p.left <= 1) {
    if (!stuck) c.telegraph = ECHO;
    ev.upd.push(c);
    return;
  }
  p.left--;
  if (p.left === pc.listen) ev.lines.push(`${c.name}が、耳をすませ始めた…`, '（聞き耳だ！今、呪文を当てると、覚えられてしまう…！）');
  if (p.left === 1) ev.lines.push(`${c.name}が、むねをふくらませた…！`, `（次に${c.name}が動くと、オウムがえし…！${p.words.length ? '身を守れ！' : '何も覚えていなければ、しっぱいするはずだ！'}）`);
  ev.c8aParrot = { id: c.id, left: p.left, every: echoEvery(c), listen: p.left <= pc.listen };
  ev.upd.push(c);
}

function vizierTurn(b, c, ev, stuck) {
  const v = c.c8viz;
  const vc = vizierConf(c);
  // こわれた へびのつえが もどる（1だんめの 間だけ）
  if (v.form === 1) {
    const st = staffOf(b);
    if (st && !st.alive && v.down > 0) {
      v.down--;
      if (v.down <= 0) {
        revivePart(b, st);
        ev.lines.push(`へびのつえが、${c.name}の手に、すうっともどってきた…！`);
        ev.c8aStaffBack = { id: c.id, staff: st.id };
        ev.upd.push(st);
      } else ev.lines.push(`（へびのつえが、もどろうとしている…あと${v.down}回）`);
    }
  }
  if (c.telegraph) return;
  // つえを こわされて うろたえて いる（1回 動けない）
  if (v.daze) {
    v.daze = false;
    if (!stuck) c.telegraph = DAZE;
    ev.upd.push(c);
    return;
  }
  if (v.form === 1) {
    if (c.hp / c.maxHp < vc.p2At) {
      if (!stuck) c.telegraph = COBRA;
      ev.upd.push(c);
      return;
    }
    // つえが ない 間は さいみんじゅつの しるしは すすまない
    if (!staffUp(b)) {
      ev.upd.push(c);
      return;
    }
    if (v.left <= 1) {
      if (!stuck) c.telegraph = HYPNO;
    } else {
      v.left--;
      if (v.left === 1) ev.lines.push(`${c.name}のつえの目が、赤くぎらぎらと光り出した…！`, '（次にジャハールが動くと、さいみんじゅつ…！その前に、へびのつえをこわせ！）');
      ev.c8aHypnoLeft = { id: c.id, left: v.left, every: vc.staff.every };
    }
    ev.upd.push(c);
    return;
  }
  if (v.form === 2) {
    if (c.hp / c.maxHp < vc.p3At) {
      if (!stuck) c.telegraph = GENIE;
      ev.upd.push(c);
      return;
    }
    // とぐろの あとは かならず 大へびのいちげき
    if (v.coiled) {
      if (!stuck) c.telegraph = STRIKE;
      ev.upd.push(c);
      return;
    }
    if (v.open > 0) {
      v.open--;
      if (v.open === 0) ev.lines.push(`${c.name}が、体をたてなおした…`);
    }
    if (v.left <= 1) {
      if (!stuck) c.telegraph = COIL;
    } else {
      v.left--;
      if (v.left === 1) ev.lines.push(`${c.name}が、長い体を、ゆっくりとまき始めた…`, '（次にコブラが動くと、とぐろ…！とぐろの間に攻撃すると、かみつかれるぞ！）');
      ev.c8aCoilLeft = { id: c.id, left: v.left, every: vc.cobra.every };
    }
    ev.upd.push(c);
    return;
  }
  // 3だんめ: ランプに すいこまれて いる 間は 動けない
  if (v.seal > 0) {
    v.seal--;
    if (v.seal > 0) {
      if (!stuck) c.telegraph = SEALED;
      ev.upd.push(c);
      return;
    }
    // 出てくる（この 番は ふつうに 動く）。ランプに また 火が ともる
    const lamp = lampOf(b);
    if (lamp) {
      lamp.maxHp = Math.round(lamp.maxHp * vc.genie.lampGrow);
      revivePart(b, lamp);
      ev.upd.push(lamp);
    }
    ev.lines.push(`${c.name}が、ランプの中から、けむりといっしょにとび出してきた！`, '黒いランプに、また火がともった…！');
    ev.c8aOut = { id: c.id, lamp: lamp?.id || null };
    ev.warn = true;
  }
  v.left = Math.min(v.left, blastEvery(c));
  if (v.left <= 1) {
    if (!stuck) c.telegraph = BLAST;
  } else {
    v.left--;
    if (v.left === 1) ev.lines.push(`黒いランプから、魔力があふれ出しそうだ…！`, '（次に魔人が動くと、むげんの魔力…！ランプをこわすか、身を守れ！）');
    ev.c8aBlastLeft = { id: c.id, left: v.left, every: blastEvery(c) };
  }
  ev.upd.push(c);
}

// こわれた つえ・ランプを もどす（いばらのかべと おなじ。たおした 数からも はずす）
function revivePart(b, m) {
  Object.assign(m, { alive: true, hp: m.maxHp, status: {}, buffs: {}, debuffs: {}, ready: false, queued: false, telegraph: null });
  m.atb = 0;
  const k = b.killed.lastIndexOf(m.species);
  if (k >= 0) b.killed.splice(k, 1);
}
// つえ・ランプを けす（変身の とき。たおした ことには ならない）
function vanishPart(b, m) {
  if (!m?.alive) return false;
  m.alive = false;
  m.hp = 0;
  m.telegraph = null;
  if (m.queued) {
    b.queue = b.queue.filter((q) => q.id !== m.id);
    m.queued = false;
  }
  return true;
}
// あやつられた 人が 目を さます
function wake(b, v, ev) {
  const woke = [];
  for (const id of v.hypno) {
    const x = b.get(id);
    if (x?.alive && x.status?.confuse) {
      delete x.status.confuse;
      woke.push(x);
      ev.upd.push(x);
    }
  }
  v.hypno = [];
  if (woke.length) (ev.postLines = ev.postLines || []).push(`${woke.map((x) => x.name).join('と')}は、はっと目をさました！`);
  return woke;
}

// ───────────── 技の こうか（battle-c7i.js の c7iEffect の のこり）─────────────
export function c8aEffect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c8aEcho': echo(b, c, ev); return true;
    case 'c8aDizzy': ev.c8aDizzy = { id: c.id }; return true;
    case 'c8aHypno': hypno(b, c, ev); return true;
    case 'c8aDaze': ev.c8aDaze = { id: c.id }; return true;
    case 'c8aCobra': toCobra(b, c, ev); return true;
    case 'c8aCoil': coil(b, c, ev); return true;
    case 'c8aStrike': strike(b, c, ev); return true;
    case 'c8aGenie': toGenie(b, c, ev); return true;
    case 'c8aBlast': blast(b, c, ev); return true;
    case 'c8aSealed': ev.c8aSealed = { id: c.id, left: c.c8viz?.seal || 0 }; return true;
    // 第8章 第2幕（battle-c8b.js）
    default: return c8bEffect(b, c, a, eff, ev);
  }
}

// みんなへの 呪文の 大技（身を 守ると 半分。calcMagic の 0.75 に もう少し かける）
function magicAll(b, c, base, element, k, ev) {
  for (const t of b.aliveAllies()) {
    const r = b.calcMagic(c, t, { base, thr: 99, element }, k);
    let dmg = r.dmg;
    if (t.defending) dmg = Math.round(dmg * 0.67);
    if (r.resisted || dmg <= 0) {
      ev.lines.push(`${t.name}はダメージを受けない！`);
      continue;
    }
    b.damage(c, t, dmg, ev, { element });
  }
}

// オウムがえし: 聞き耳の 間に 覚えた 呪文を はね返す（何も なければ しっぱいして 目を まわす）
function echo(b, c, ev) {
  const p = c.c8par;
  const pc = parrotConf(c);
  const words = p ? p.words.splice(0) : [];
  if (p) p.left = echoEvery(c);
  if (!words.length) {
    if (p) {
      p.empties++;
      p.dizzy = true;
    }
    c.debuffs.def = { mult: pc.dizzy, lv: 1, left: BUFF_ACTS };
    ev.fx = { type: 'ability', anim: 'a8p_dizzy', actor: c.id, targets: [c.id], side: 'enemy' };
    ev.lines.push(`…しかし、${c.name}は、何も覚えていなかった！`, `${c.name}「あれ？えーっと…なんだっけ？」`);
    (ev.postLines = ev.postLines || []).push(`${c.name}は、目をまわした！（次の番は動けない・守りが下がった！）`);
    ev.c8aEcho = { id: c.id, n: 0 };
    ev.upd.push(c);
    return;
  }
  const last = words[words.length - 1];
  const k = 1 + (pc.echo.per ?? 0.5) * (words.length - 1);
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a8p_echo', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy', element: last.el || undefined };
  ev.lines.push(`${c.name}「${words.map((w) => w.name).join('！')}！」`, '覚えた呪文を、そっくりそのまま、はね返した！');
  magicAll(b, c, pc.echo.base, last.el, k, ev);
  if (p) p.echoes++;
  ev.c8aEcho = { id: c.id, n: words.length, el: last.el || null, names: words.map((w) => w.name) };
  ev.warn = true;
  ev.upd.push(c);
}

// さいみんじゅつ: n 人を あやつる（こんらん）
function hypno(b, c, ev) {
  const v = c.c8viz;
  const vc = vizierConf(c);
  if (v) v.left = vc.staff.every;
  if (!staffUp(b)) {
    ev.lines.push('しかし、へびのつえがない！');
    return;
  }
  const pool = b.aliveAllies().filter((x) => !x.status?.confuse && !x.status?.rift);
  const picks = [];
  while (picks.length < (vc.staff.hypno.n || 1) && pool.length) picks.push(pool.splice(b.rng.int(0, pool.length - 1), 1)[0]);
  ev.fx = { type: 'ability', anim: 'a8j_hypno', actor: c.id, targets: picks.map((x) => x.id), side: 'enemy' };
  const hit = [], safe = [];
  for (const t of picks) {
    if (b.tryStatus(c, t, { status: 'confuse', chance: 1, turns: vc.staff.hypno.turns, quiet: true }, ev)) hit.push(t);
    else safe.push(t);
  }
  if (hit.length) {
    ev.lines.push(`${hit.map((x) => x.name).join('と')}は、${c.name}にあやつられてしまった！`);
    (ev.postLines = ev.postLines || []).push('（へびのつえをこわすと、さいみんじゅつがとける…！）');
  }
  if (safe.length) ev.lines.push(`${safe.map((x) => x.name).join('と')}は、ぐっとこらえて、目をそらした！`);
  if (v) {
    v.hypno.push(...hit.map((x) => x.id));
    v.hypnos++;
  }
  ev.c8aHypno = { id: c.id, who: hit.map((x) => x.id), safe: safe.map((x) => x.id) };
  ev.warn = !!hit.length;
  ev.upd.push(c, ...picks);
}

// 大へびの姿（2だんめ）: つえは 消え、あやつられた 人は 目を さます
function toCobra(b, c, ev) {
  const v = c.c8viz;
  const vc = vizierConf(c);
  if (!v || v.form !== 1) return;
  v.form = 2;
  v.left = vc.cobra.every;
  v.daze = false;
  c.name = COBRA_NAME;
  c.actions = COBRA_ACTIONS.map((x) => ({ ...x }));
  c.atk = Math.round(c.atk * (vc.cobra.atk ?? 1));
  ev.fx = { type: 'ability', anim: 'a8j_cobra', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('ジャハールの体が、ぐんぐんのびて、うろこにおおわれていく…！', 'ジャハールは、大きなコブラに姿をかえた！');
  const st = staffOf(b);
  if (vanishPart(b, st)) {
    ev.lines.push('へびのつえは、コブラの体にすいこまれて消えた！');
    ev.upd.push(st);
  }
  wake(b, v, ev);
  (ev.postLines = ev.postLines || []).push('（コブラは、ときどきとぐろをまく…！とぐろの間は、攻撃するとかみつかれるぞ！）');
  ev.c8aCobra = { id: c.id, staff: st?.id || null };
  ev.warn = true;
  ev.upd.push(c);
}

// とぐろをまく（次の 番に 大へびのいちげき。とぐろの 間に 攻撃すると かみつく）
function coil(b, c, ev) {
  const v = c.c8viz;
  if (!v) return;
  v.coiled = true;
  v.counters = 0;
  v.coils++;
  v.left = vizierConf(c).cobra.every;
  (ev.postLines = ev.postLines || []).push('（とぐろの間に攻撃すると、かみつかれる…！次のコブラの番は、大へびのいちげき！）');
  ev.c8aCoil = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// 大へびのいちげき（かみついた 数だけ 強い）／だれも 攻撃して いなければ からぶりして のびきる
function strike(b, c, ev) {
  const v = c.c8viz;
  const cc = vizierConf(c).cobra;
  const n = v?.counters || 0;
  if (v) {
    v.coiled = false;
    v.counters = 0;
  }
  if (!n) {
    if (v) {
      v.open = cc.open.turns;
      v.whiffs++;
    }
    ev.fx = { type: 'ability', anim: 'a8c_whiff', actor: c.id, targets: [c.id], side: 'enemy' };
    ev.lines.push('だれも攻撃してこない…！コブラは、しびれをきらしてとびかかった！', 'しかし、いきおいあまって、柱に、どーんと頭を打った！');
    (ev.postLines = ev.postLines || []).push(`${c.name}は、のびきってしまった！（今なら、ダメージが${cc.open.k}倍！）`);
    ev.c8aWhiff = { id: c.id, k: cc.open.k, turns: cc.open.turns };
    ev.upd.push(c);
    return;
  }
  const sc = cc.strike;
  const mult = Math.min(sc.max ?? 2, (sc.mult ?? 0.9) + (sc.per ?? 0.25) * n);
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a8c_strike', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  for (const t of targets) b.physHit(c, t, { mult, ignoreDef: sc.ignoreDef ?? 0.3, acc: 1.2 }, ev, 'phys');
  if (v) v.strikes++;
  ev.c8aStrike = { id: c.id, n };
  ev.warn = true;
  ev.upd.push(c);
}

// ランプの魔人（3だんめ）: 黒いランプが あらわれる
function toGenie(b, c, ev) {
  const v = c.c8viz;
  const vc = vizierConf(c);
  if (!v || v.form !== 2) return;
  v.form = 3;
  v.left = blastEvery(c);
  v.coiled = false;
  v.counters = 0;
  v.open = 0;
  c.name = GENIE_NAME;
  c.actions = GENIE_ACTIONS.map((x) => ({ ...x }));
  c.atk = Math.round(c.atk * (vc.genie.atk ?? 1));
  ev.fx = { type: 'ability', anim: 'a8j_genie', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('コブラの体が、赤いけむりにつつまれていく…！', 'ジャハールは、大きなランプの魔人に姿をかえた！');
  let lamp = lampOf(b);
  if (lamp) {
    revivePart(b, lamp);
    ev.upd.push(lamp);
  } else {
    const added = b.addEnemies([C8_LAMP]);
    lamp = added[0];
    if (lamp) {
      lamp.atb = 0;
      ev.joined = (ev.joined || []).concat(added.map(pub));
    }
  }
  if (lamp) ev.lines.push('魔人のそばに、黒いランプがうかび上がった！');
  (ev.postLines = ev.postLines || []).push('（魔人の力は、あの黒いランプから来ているようだ…！ランプをこわすと、どうなる…？）');
  ev.c8aGenie = { id: c.id, lamp: lamp?.id || null };
  ev.warn = true;
  ev.upd.push(c);
}

// むげんの魔力（みんなに 闇の 大技。身を 守ると 半分）
function blast(b, c, ev) {
  const v = c.c8viz;
  if (v) {
    v.left = blastEvery(c);
    v.blasts++;
  }
  const bc = vizierConf(c).genie.blast || {};
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a8g_blast', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy', element: 'dark' };
  magicAll(b, c, bc.base || [220, 250], 'dark', 1, ev);
  ev.c8aBlast = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// ───────────── ダメージ（battle-c7i.js の c7iDamage の はじめ。味方 → 敵 だけ）─────────────
// イアゴン: 聞き耳の 間に 当たった 呪文を 覚える／ジャハール: とぐろの 間は かみつく・のびきった 間と ランプの 中は ダメージが ふえる・変身の 前は HP が 下がりきらない
export function c8aDamage(b, c, t, dmg, info, ev) {
  // 第8章 第2幕: 小鬼の パニック・けんか／ハデロスの けいやくしょ・頭が ひえる・おこる 前（battle-c8b.js）
  dmg = c8bDamage(b, c, t, dmg, info, ev);
  if (!(dmg > 0) || c?.side !== 'ally') return dmg;
  if (t.c8par) hear(b, c, t, info, ev);
  const v = t.c8viz;
  if (!v) return dmg;
  const vc = vizierConf(t);
  if (v.form === 2) {
    if (v.coiled && c.alive && !ev.c8aBit) bite(b, t, c, ev);
    if (v.open > 0) dmg = Math.round(dmg * vc.cobra.open.k);
  }
  if (v.form === 3 && v.seal > 0) dmg = Math.round(dmg * vc.genie.seal.k);
  const at = v.form === 1 ? vc.p2At : v.form === 2 ? vc.p3At : 0;
  if (at > 0) {
    // 小数の ずれで ちょうど at に ならない ように（90000 × 0.34 ＝ 30600.000…04）
    const floor = Math.ceil(t.maxHp * at - 1e-6) - 1;
    if (t.hp - dmg < floor) dmg = Math.max(0, t.hp - floor);
  }
  return dmg;
}

// 聞き耳の 間に 当たった 呪文（ダメージの ある 呪文・物理で ない 合体技。1回の 行動で 1つ）を 覚える
function hear(b, c, t, info, ev) {
  if (info.phys || ev.c8aHeard || !listening(t)) return;
  // 呪文（技）か 合体技の 名前
  const name = ev.dual?.name || (ev.ability ? ABILITIES[ev.ability]?.name : null);
  if (!name) return;
  ev.c8aHeard = true;
  const p = t.c8par;
  const max = parrotConf(t).max;
  const el = info.element && info.element !== 'phys' ? info.element : null;
  const a = { name };
  p.words.push({ id: ev.dual?.id || ev.ability, el, name });
  while (p.words.length > max) p.words.shift();
  p.heard++;
  const elTxt = el && EL_NAME[el] ? `${EL_NAME[el]}の` : '';
  (ev.postLines = ev.postLines || []).push(`${t.name}「${a.name}！${a.name}！」（${elTxt}呪文を、覚えられてしまった…！）`);
  ev.c8aLearn = { id: t.id, words: p.words.map((w) => w.el || 'none') };
  ev.upd.push(t);
}

// とぐろの 間の かみつき（1回の 行動で 1回）
function bite(b, cobra, c, ev) {
  ev.c8aBit = true;
  const v = cobra.c8viz;
  v.counters++;
  const cc = vizierConf(cobra).cobra.counter || {};
  (ev.postLines = ev.postLines || []).push(`${cobra.name}が、とぐろの中から、${c.name}にかみついた！`);
  b.physHit(cobra, c, { mult: cc.mult ?? 0.85, ignoreDef: cc.ignoreDef ?? 0.3, acc: 1.3 }, ev, 'phys');
  ev.c8aBite = { id: cobra.id, who: c.id, n: v.counters };
  ev.upd.push(cobra, c);
}

// ───────────── たおれた（battle-c7i.js の c7iKill の はじめ）─────────────
// へびのつえ: あやつられた 人が 目を さます・ジャハールは うろたえる／黒いランプ: 魔人が ランプに すいこまれる
export function c8aKill(b, t, ev) {
  // 第8章 第2幕: 小鬼の かたほうが たおれた（battle-c8b.js）
  c8bKill(b, t, ev);
  if (!isStaff(t) && !isLamp(t)) return;
  const w = vizierOf(b);
  if (!w?.c8viz) return;
  const v = w.c8viz;
  const vc = vizierConf(w);
  const post = ev ? (ev.postLines = ev.postLines || []) : [];
  if (isStaff(t) && v.form === 1) {
    v.down = vc.staff.regrow;
    v.breaks++;
    v.left = vc.staff.every;
    v.daze = true;
    // ならべて いた さいみんじゅつは とりやめ
    if (w.telegraph === HYPNO) w.telegraph = null;
    const woke = ev ? wake(b, v, ev) : [];
    if (!ev) v.hypno = [];
    post.push('へびのつえが、くだけちった！', `${w.name}「な、なに…！？わたしのつえが…！」`, `（${w.name}は、うろたえている！）`);
    if (ev) {
      ev.c8aBreak = { id: w.id, staff: t.id, woke: woke.map((x) => x.id) };
      ev.upd.push(w);
    }
    return;
  }
  if (isLamp(t) && v.form === 3) {
    v.seal = vc.genie.seal.turns + 1;
    v.seals++;
    v.left = blastEvery(w);
    // ならべて いた 大技も とりやめ（ランプに すいこまれる）
    w.telegraph = null;
    if (w.queued) {
      b.queue = b.queue.filter((q) => q.id !== w.id);
      w.queued = false;
    }
    w.ready = false;
    w.atb = 0;
    post.push('黒いランプが、ひびわれた…！', `${w.name}「な、なんだ…！？ランプに、すいこまれる…！」`, `${w.name}は、自分のランプの中に、すいこまれてしまった！（ダメージが${vc.genie.seal.k}倍！）`);
    if (ev) {
      ev.c8aSeal = { id: w.id, lamp: t.id, turns: vc.genie.seal.turns, k: vc.genie.seal.k };
      ev.upd.push(w);
    }
  }
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// オウムがえし（覚えた 呪文が ある とき）が c の 次の 番より 先に 来るか
export function echoBefore(b, c, p = parrotOf(b)) {
  if (!p?.c8par || p.c8par.dizzy || !p.c8par.words.length) return false;
  if (p.telegraph === ECHO) return true;
  return actsBefore(b, c, p) >= p.c8par.left;
}
// ジャハールの みんなへの 大技（いちげき〈かみついた とき〉・むげんの魔力）が c の 次の 番より 先に 来るか
export function vizierBigBefore(b, c, w = vizierOf(b)) {
  const v = w?.c8viz;
  if (!v) return false;
  if (v.form === 2) return v.coiled && v.counters > 0 && (w.telegraph === STRIKE || actsBefore(b, c, w) >= 1);
  if (v.form !== 3 || v.seal > 0) return false;
  if (w.telegraph === BLAST) return true;
  if (w.telegraph) return false;
  return actsBefore(b, c, w) >= v.left;
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。physOnly … 呪文は のぞく。{ cmd, dmg }）
function bestHit(b, c, t, physOnly = false) {
  const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
  let best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic' && !physOnly) dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}
// 敵に 当てる 呪文か（イアゴンが 覚える もの）
const isSpell = (cmd) => cmd?.type === 'ability' && FOES.has(ABILITIES[cmd.id]?.target) && prim(ABILITIES[cmd.id]).type === 'magic';
// 敵に ダメージを あたえる 行動か（とぐろの 間は しない）
function isAttack(cmd) {
  if (!cmd) return false;
  if (cmd.type === 'attack' || cmd.type === 'dual') return true;
  if (cmd.type !== 'ability') return false;
  const a = ABILITIES[cmd.id];
  return FOES.has(a?.target) && ['phys', 'magic', 'allMp', 'pay'].includes(prim(a).type);
}

// ───────────── オート（battle-c7i.js の c7iPlan の はじめ）─────────────
// 第8章 第1幕の ボスが いなければ null（ほかの ボスの 考えへ）
export function c8aPlan(b, c, decide) {
  if (c.side !== 'ally' || b.c8aInner || c.status?.rift) return null;
  // 第8章 第2幕の ボス（ペイニックと パニクル・ハデロス。battle-c8b.js）
  const bp = c8bPlan(b, c, decide);
  if (bp) return bp;
  const p = parrotOf(b);
  const w = vizierOf(b);
  if (!p && !w) return null;
  const soon = p ? echoBefore(b, c, p) : vizierBigBefore(b, c, w);
  // ふつうの オート: 大技が 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  if (!b.knowsCh6) {
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c8aInner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c8aInner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  if (p) {
    if (soon && !b.c6NoGuard) return { type: 'defend' };
    // 聞き耳の 間は 呪文を 当てない（いちばん 大きい 物理の 攻撃に かえる）
    if (listening(p) && !b.c8aNoQuiet && isSpell(base)) return bestHit(b, c, p, true).cmd;
    return base;
  }
  const v = w.c8viz;
  if (v.form === 1) {
    // さいみんじゅつが 近い ときは、へびのつえを こわす
    const st = staffOf(b);
    if (st?.alive && !b.c8aNoStaff && (v.left <= 2 || w.telegraph === HYPNO) && a?.target !== 'enemies') {
      const h = bestHit(b, c, st);
      if (h.dmg > 0) return h.cmd;
    }
    return base;
  }
  if (v.form === 2) {
    // とぐろの 間は 攻撃しない（守る。回復・補助は そのまま）
    if (v.coiled && !b.c8aNoCoil && isAttack(base)) return { type: 'defend' };
    if (soon && !b.c6NoGuard) return { type: 'defend' };
    return base;
  }
  // 3だんめ: ランプを 先に こわす（大技が 来る 前に こわせない ときは 守る）
  const lamp = lampOf(b);
  if (lamp?.alive && v.seal <= 0 && !b.c8aNoLamp) {
    const h = bestHit(b, c, lamp);
    if (soon && h.dmg < lamp.hp && !b.c6NoGuard) return { type: 'defend' };
    if (a?.target !== 'enemies' && h.dmg > 0) return h.cmd;
    return base;
  }
  if (soon && !b.c6NoGuard) return { type: 'defend' };
  return base;
}

// ───────────── がめんへ（battle-c7i.js の c7iPub の さいご）─────────────
// イアゴン: echoLeft・echoEvery（オウムがえしまで）・listen（聞き耳）・words（覚えた 呪文の 属性）・dizzy
// ジャハール: c8form（1 魔術師・2 コブラ・3 魔人）・hypnoLeft・hypnoEvery・staffDown（つえが もどるまで）・coilLeft・coilEvery・coiled・counters・
//   openLeft・openK（のびきった 間）・blastLeft・blastEvery・sealLeft・sealK（ランプの 中）
// へびのつえ: c8staff／黒いランプ: c8lamp
export function c8aPub(c, o) {
  // 第8章 第2幕（battle-c8b.js）
  c8bPub(c, o);
  if (c.c8par) {
    o.echoLeft = c.c8par.left;
    o.echoEvery = echoEvery(c);
    o.words = c.c8par.words.map((w) => w.el || 'none');
    if (listening(c)) o.listen = 1;
    if (c.c8par.dizzy) o.dizzy = 1;
  }
  if (c.c8viz) {
    const v = c.c8viz;
    const vc = vizierConf(c);
    o.c8form = v.form;
    if (v.form === 1) {
      o.hypnoLeft = v.left;
      o.hypnoEvery = vc.staff.every;
      if (v.down > 0) o.staffDown = v.down;
    } else if (v.form === 2) {
      o.coilLeft = v.left;
      o.coilEvery = vc.cobra.every;
      if (v.coiled) {
        o.coiled = 1;
        o.counters = v.counters;
      }
      if (v.open > 0) {
        o.openLeft = v.open;
        o.openK = vc.cobra.open.k;
      }
    } else {
      o.blastLeft = v.left;
      o.blastEvery = blastEvery(c);
      if (v.seal > 0) {
        o.sealLeft = Math.max(1, v.seal - 1);
        o.sealK = vc.genie.seal.k;
      }
    }
  }
  if (isStaff(c)) o.c8staff = 1;
  if (isLamp(c)) o.c8lamp = 1;
}

js/shared/battle-c8b.js:
// 第2部 第8章 第2幕「よみの 青い火」の ボスの 戦いの しかけ（battle-c8a.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・ペイニックと パニクル（monsters-c8b.js の c8b.kind 'imps'。Step 3 の さいごの 中ボス。2ひきで 1組）「ばけばけ大作戦」
//   2ひきとも 生きている 間は、どちらかが 1回 動く たびに「ばけばけ」の しるし（b.c8imps.left）が 1つ へる。のこり imps.plot いかは「ひそひそ相談」:
//   その 間に どちらかに、1回の 行動で その 魔物の HP の breakAt いじょうの ダメージを 当てると、作戦が ばれて「けんか」
//   （2ひきとも 次の 番は 動けない・しるしは もどる）。しるしが なくなると「ばけばけ大がったい」（m8i_fuse。みんなに 物理の 大技。身を 守ると 半分）
//   かたほうが たおれると、のこった ほうは「パニック」: panic.turns 回 動く 間 あたふた して（何も できない）、受ける ダメージが panic.k ばい。
//   その 間に たおせないと「カンカン」（攻撃力 rage.atk ばい・はやさ rage.spd ばい）。rage.every 回 動く たびに「ひとりばけばけ」（m8i_solo）
// ・よみの王ハデロス（c8b.kind 'hades'。第2幕の さいごの ボス。2だん）
//   1だんめ（青い 炎。氷に 弱く 炎に 強い）「たましいのけいやく」: contract.every 回 動く たびに（しるし c.c8hd.left）1人に けいやくしょ（m8h_contract）。
//     ハデロスが 動く たびに その 人の HP を drain ずつ すいとり、contract.turns 回 すいとった 次の 番に「たましいを いただく」（m8h_soul。その 人は たおれる）。
//     けいやくの 間に ハデロスに 炎を 当てると（炎は あまり 効かないが）、けいやくしょが もえる（その 人は 助かる・ハデロスは あちちっと 1回 動けない）。けいやくの 間は しるしは すすまない
//   HP が p2At + 0.08 より へると、かみの毛の 炎が 赤く ちらちら（前ぶれ）。p2At より へると、次の 番に「おこったハデロス」（m8h_anger）。
//     それまで HP は p2At より 下がらない。けいやくしょは おこった 炎で もえて しまう
//   2だんめ（赤い 炎。炎に 弱く 氷に 強い。弱点が ひっくりかえる）「よみの大ふん火」: erupt.every 回 動く たびに（しるし c.c8hd.left）m8h_erupt
//     （みんなに 炎の 大技。身を 守ると 半分）。ふん火の 前ぶれ（しるし のこり 1）の 間に 氷を 当てると（氷は あまり 効かないが）、頭が ひえて ふん火が しぼむ（次の 番は 動けない・しるしは もどる）。
//     HP が erupt.p3At より へると every が erupt.p3Every に
// ・ふつうの オート（家族が「オート」に した とき）: 大技（大がったい・ひとりばけばけ・たましいを いただく〈その 人〉・大ふん火）が 自分の 次の 番より 先に
//   来る とき、HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ。b.c6Naive … しない 人）
// ・知っている 人（シミュレーター tools/sim-ch8.mjs。b.knowsCh6）:
//   小おに … 相談の 間は いちばん 大きい 1回の 攻撃を 1ぴきに 当てる（b.c8bNoPlot … しない）・パニックの 小おにを ねらう・2ひきの HP を
//     そろえて へらす（HP の 多い ほうを ねらう。b.c8bNoOrder … しない）・大がったいの 前に 身を 守る（b.c6NoGuard）
//   ハデロス … けいやくの 間は 炎を 当てる（b.c8bNoBurn）・ふん火の 前ぶれに 氷を 当てる（b.c8bNoChill）・大ふん火の 前に 身を 守る（b.c6NoGuard）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C8_PAIN, C8_PANIC, C8_HADES, HADES_BLUE, HADES_RED, RED_ACTIONS } from './data/monsters-c8b.js';
import { BUFF_ACTS } from './buff-acts.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';
// 第2部 第8章 第3幕: マジカメック（でっかくなあれ）・初代大魔王クッパード（ギガクッパード・橋のオノ）。battle-c8c.js
import { setupC8c, c8cTurnStart, c8cEffect, c8cPlan, c8cPub, c8cDamage, c8cKill } from './battle-c8c.js';

export { C8_PAIN, C8_PANIC, C8_HADES };
export const FUSE = 'm8i_fuse';
export const QUARREL = 'm8i_quarrel';
export const PANIC = 'm8i_panic';
export const RAGE = 'm8i_rage';
export const SOLO = 'm8i_solo';
export const CONTRACT = 'm8h_contract';
export const SOUL = 'm8h_soul';
export const HOT = 'm8h_hot';
export const ANGER = 'm8h_anger';
export const ERUPT = 'm8h_erupt';
export const COOL = 'm8h_cool';
export const RED_NAME = 'おこったハデロス';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});
const post = (ev) => (ev.postLines = ev.postLines || []);

const confOf = (m) => MONSTERS[m?.species]?.c8b || null;
export function impsConf(m) {
  const c = confOf(m)?.imps || {};
  return {
    every: 5, plot: 2, breakAt: 0.07, ...c,
    fuse: { mult: 0.95, ignoreDef: 0.3, ...(c.fuse || {}) },
    panic: { turns: 3, k: 1.5, ...(c.panic || {}) },
    rage: { atk: 1.3, spd: 1.25, every: 3, mult: 0.85, ...(c.rage || {}) },
  };
}
export function hadesConf(m) {
  const c = confOf(m) || {};
  return {
    contract: { every: 4, turns: 2, drain: 0.12, heal: 0.008, soulHeal: 0.04, ...(c.contract || {}) },
    p2At: c.p2At ?? 0.5,
    red: { atk: 1.08, ...(c.red || {}) },
    erupt: { every: 3, p3At: 0.2, p3Every: 2, base: [380, 410], chillAt: 1, ...(c.erupt || {}) },
  };
}
const short = (m) => MONSTERS[m?.species]?.short || m?.name || '';
export const impsOf = (b) => b.enemies.filter((e) => e.c8imp);
const aliveImps = (b) => impsOf(b).filter((e) => e.alive);
export const bothUp = (b) => aliveImps(b).length >= 2;
const partnerOf = (b, c) => impsOf(b).find((e) => e !== c) || null;
const hadesOf = (b) => b.enemies.find((e) => e.c8hd && e.alive) || null;
export const formOfH = (m) => m?.c8hd?.form || 0;
// ひそひそ相談の 間か（2ひきとも 生きていて、しるしが plot いか・けんかの 間は ない）
export function plotting(b) {
  const s = b.c8imps;
  if (!s || !bothUp(b)) return false;
  if (aliveImps(b).some((e) => e.c8imp.quarrel)) return false;
  return s.left <= impsConf(aliveImps(b)[0]).plot;
}
const soloEvery = (c) => impsConf(c).rage.every;
const eruptEvery = (c) => {
  const e = hadesConf(c).erupt;
  return c.hp / c.maxHp < e.p3At ? e.p3Every : e.every;
};
// ふん火の 前ぶれ（しるし のこり 1。次の 番が ふん火）
//   （しるし のこり erupt.chillAt いか … かみの 毛が 高く もえて いる 間は 氷で ひやせる）
export const eruptSoon = (h) => !!h?.c8hd && h.c8hd.form === 2 && !h.c8hd.cool && h.c8hd.left <= hadesConf(h).erupt.chillAt;
// けいやくされて いる 人
export function bound(b, h = hadesOf(b)) {
  const id = h?.c8hd?.contract?.id;
  const x = id ? b.get(id) : null;
  return x?.alive ? x : null;
}

// ───────────── はじめ（battle-c8a.js の setupC8a の さいご）─────────────
export function setupC8b(b) {
  const lines = [];
  let imps = 0;
  for (const e of b.enemies) {
    const conf = confOf(e);
    if (!conf) continue;
    if (conf.kind === 'imps') {
      e.c8imp = { role: conf.role, quarrel: false, panic: 0, rage: false, left: 0 };
      imps++;
    }
    if (conf.kind === 'hades') {
      e.c8hd = { form: 1, left: hadesConf(e).contract.every, contract: null, hot: false, cool: false, flicker: false, contracts: 0, burns: 0, souls: 0, erupts: 0, cools: 0 };
      lines.push(`${e.name}「やあやあ、ようこそ、よみの国へ！ゆっくりしていきなよ。…ずーっとね！」`, '（ハデロスのかみの毛は、青い炎…！青い炎のときは、氷がよく効きそうだ…！）');
    }
  }
  if (imps) {
    const any = impsOf(b)[0];
    const ic = impsConf(any);
    b.c8imps = { left: ic.every, every: ic.every, plotAt: ic.plot, both: bothUp(b), quarrel: false, fuses: 0, quarrels: 0, panics: 0, rages: 0, solos: 0 };
    // がめんへ（pub）: 2ひきとも おなじ しるしを 見る
    for (const e of impsOf(b)) e.c8imp.s = b.c8imps;
    lines.push('ペイニック「いくぞ、パニクル！」', 'パニクル「お、おう、ペイニック！」', '（2ひきが、ひそひそ相談を始めたら、強い一撃でじゃまをしよう…！）');
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
  // 第8章 第3幕の ボス（battle-c8c.js）
  setupC8c(b);
}

// ───────────── 行動の はじめ（battle-c8a.js の c8aTurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c8bTurnStart(b, c, ev, stuck) {
  // 第8章 第3幕（battle-c8c.js）
  c8cTurnStart(b, c, ev, stuck);
  if (c.c8imp) impTurn(b, c, ev, stuck);
  else if (c.c8hd) hadesTurn(b, c, ev, stuck);
}

function impTurn(b, c, ev, stuck) {
  const me = c.c8imp;
  const s = b.c8imps;
  const ic = impsConf(c);
  if (c.telegraph || !s) return;
  // けんかの あいだ（1回 動けない）
  if (me.quarrel) {
    me.quarrel = false;
    s.quarrel = aliveImps(b).some((e) => e.c8imp.quarrel);
    if (!stuck) c.telegraph = QUARREL;
    ev.upd.push(c);
    return;
  }
  if (bothUp(b)) {
    if (s.left <= 1) {
      if (!stuck) c.telegraph = FUSE;
      ev.upd.push(...aliveImps(b));
      return;
    }
    s.left--;
    if (s.left === ic.plot) ev.lines.push('ペイニックとパニクルが、ひそひそ相談を始めた…', '（今、どちらかに強い一撃を当てれば、作戦をじゃまできそうだ…！）');
    if (s.left === 1) ev.lines.push('2ひきが、目を合わせて、にやりとわらった…！', '（次にどちらかが動くと、ばけばけ大がったい…！じゃまするか、身を守れ！）');
    ev.c8bImpLeft = { id: c.id, left: s.left, every: s.every, plot: s.left <= ic.plot };
    ev.upd.push(...aliveImps(b));
    return;
  }
  // ひとりに なった: パニック → カンカン → ひとりばけばけ
  if (me.panic > 0) {
    me.panic--;
    if (!stuck) c.telegraph = PANIC;
    if (me.panic === 0) post(ev).push(`（${c.name}が、だんだん顔を赤くしてきた…！次は、カンカンにおこるぞ！）`);
    ev.c8bPanicLeft = { id: c.id, left: me.panic };
    ev.upd.push(c);
    return;
  }
  if (!me.rage) {
    if (!stuck) c.telegraph = RAGE;
    ev.upd.push(c);
    return;
  }
  me.left = Math.min(me.left || soloEvery(c), soloEvery(c));
  if (me.left <= 1) {
    if (!stuck) c.telegraph = SOLO;
  } else {
    me.left--;
    if (me.left === 1) ev.lines.push(`${c.name}が、ぷくーっと大きくふくらみ始めた…！`, `（次に${c.name}が動くと、ひとりばけばけ…！身を守れ！）`);
    ev.c8bSoloLeft = { id: c.id, left: me.left, every: soloEvery(c) };
  }
  ev.upd.push(c);
}

function hadesTurn(b, c, ev, stuck) {
  const h = c.c8hd;
  const hc = hadesConf(c);
  if (c.telegraph) return;
  // けいやくしょが もえて あちちっ・頭が ひえた（1回 動けない）
  if (h.hot) {
    h.hot = false;
    if (!stuck) c.telegraph = HOT;
    ev.upd.push(c);
    return;
  }
  if (h.cool) {
    h.cool = false;
    if (!stuck) c.telegraph = COOL;
    ev.upd.push(c);
    return;
  }
  if (h.form === 1) {
    if (c.hp / c.maxHp < hc.p2At) {
      if (!stuck) c.telegraph = ANGER;
      ev.upd.push(c);
      return;
    }
    // けいやくの あいだ: HP を すいとる → たましいを いただく
    if (h.contract) {
      const x = bound(b, c);
      if (!x) h.contract = null;
      else if (h.contract.left <= 0) {
        if (!stuck) c.telegraph = SOUL;
        ev.upd.push(c);
        return;
      } else {
        drain(b, c, x, ev);
        ev.upd.push(c);
        return;
      }
    }
    if (h.left <= 1) {
      if (!stuck) c.telegraph = CONTRACT;
    } else {
      h.left--;
      if (h.left === 1) ev.lines.push(`${c.name}が、ふところから、まき物をとり出した…`, '（次にハデロスが動くと、たましいのけいやく…！けいやくしょは、炎でもえるはずだ！）');
      ev.c8bContractLeft = { id: c.id, left: h.left, every: hc.contract.every };
    }
    ev.upd.push(c);
    return;
  }
  // 2だんめ: よみの大ふん火まで
  h.left = Math.min(h.left, eruptEvery(c));
  if (h.left <= 1) {
    if (!stuck) c.telegraph = ERUPT;
  } else {
    h.left--;
    const ca = hadesConf(c).erupt.chillAt;
    if (h.left === ca && ca > 1) ev.lines.push(`${c.name}のかみの毛が、ぐんぐん高くなってきた…！`, '（もうすぐ、よみの大ふん火…！今のうちに、氷で頭をひやせ！）');
    if (h.left === 1) ev.lines.push(`${c.name}のかみの毛が、ごうごうと、高くもえ上がった…！`, '（次にハデロスが動くと、よみの大ふん火…！氷で頭をひやすか、身を守れ！）');
    ev.c8bEruptLeft = { id: c.id, left: h.left, every: eruptEvery(c) };
  }
  ev.upd.push(c);
}

// けいやくした 人の HP を すいとる
function drain(b, c, x, ev) {
  const h = c.c8hd;
  const hc = hadesConf(c).contract;
  const amt = Math.max(1, Math.round(x.maxHp * hc.drain));
  ev.lines.push(`けいやくしょが、あやしく光った…！${x.name}のたましいが、すいとられていく…`);
  const d = Math.min(amt, Math.max(0, x.hp - 1));
  if (d > 0) b.damage(c, x, d, ev, { element: 'dark' });
  const heal = Math.round(c.maxHp * hc.heal);
  c.hp = Math.min(c.maxHp, c.hp + heal);
  h.contract.left--;
  h.contract.drains++;
  if (h.contract.left <= 0) post(ev).push(`（次にハデロスが動くと、${x.name}のたましいが、とられてしまう…！炎で、けいやくしょをもやせ！）`);
  ev.c8bDrain = { id: c.id, who: x.id, left: h.contract.left, dmg: d };
  ev.upd.push(x);
}

// ───────────── 技の こうか（battle-c8a.js の c8aEffect の のこり）─────────────
export function c8bEffect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c8bFuse': fuse(b, c, ev); return true;
    case 'c8bQuarrel': ev.c8bQuarrelAct = { id: c.id }; return true;
    case 'c8bPanic': ev.c8bPanicAct = { id: c.id, left: c.c8imp?.panic || 0 }; return true;
    case 'c8bRage': rage(b, c, ev); return true;
    case 'c8bSolo': solo(b, c, ev); return true;
    case 'c8bContract': contract(b, c, ev); return true;
    case 'c8bSoul': soul(b, c, ev); return true;
    case 'c8bHot': ev.c8bHot = { id: c.id }; return true;
    case 'c8bAnger': anger(b, c, ev); return true;
    case 'c8bErupt': erupt(b, c, ev); return true;
    case 'c8bCool': ev.c8bCoolAct = { id: c.id }; return true;
    // 第8章 第3幕（battle-c8c.js）
    default: return c8cEffect(b, c, a, eff, ev);
  }
}

// みんなへの 物理の 大技（身を 守ると 半分）
function physAll(b, c, mult, ignoreDef, ev) {
  const targets = b.aliveAllies();
  for (const t of targets) b.physHit(c, t, { mult, ignoreDef, acc: 1.2 }, ev, 'phys');
  return targets;
}

// ばけばけ大がったい（2ひきで 大きな おばけに ばけて、みんなに 物理の 大技）
function fuse(b, c, ev) {
  const s = b.c8imps;
  const ic = impsConf(c);
  const p = partnerOf(b, c);
  if (s) {
    s.left = s.every;
    s.fuses++;
  }
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'b8i_fuse', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  if (!p?.alive) {
    ev.lines.push('しかし、あいぼうがいない！');
    return;
  }
  ev.lines.push(`${short(c)}と${short(p)}が、ボワンとけむりにつつまれて、大きな大きなおばけにばけた！`);
  physAll(b, c, ic.fuse.mult, ic.fuse.ignoreDef, ev);
  post(ev).push('2ひきは、もとのすがたにもどった。');
  ev.c8bFuse = { id: c.id, partner: p.id };
  ev.warn = true;
  ev.upd.push(c, p);
}

// 相談の 間に 大きな 一撃: けんかを はじめる（2ひきとも 1回 動けない）
function quarrel(b, t, by, ev) {
  const s = b.c8imps;
  ev.c8bQuarrel = { id: t.id, by: by.id };
  s.left = s.every;
  s.quarrels++;
  s.quarrel = true;
  const imps = aliveImps(b);
  for (const e of imps) {
    e.c8imp.quarrel = true;
    if (e.telegraph === FUSE) e.telegraph = null;
  }
  const p = partnerOf(b, t);
  post(ev).push(
    `${short(t)}「いてててっ！おい、${short(p)}！ちゃんと見はってろって言っただろ！」`,
    `${short(p)}「ええっ！？ぼくのせいじゃないよ！」`,
    '2ひきは、けんかを始めた！（次の番は、2ひきとも動けない！）',
  );
  ev.upd.push(...imps);
}

// カンカン（あいぼうが たおれて パニックの あと）
function rage(b, c, ev) {
  const me = c.c8imp;
  const rc = impsConf(c).rage;
  if (!me || me.rage) return;
  me.rage = true;
  me.left = rc.every;
  c.atk = Math.round(c.atk * rc.atk);
  c.speed = (c.speed || 1) * rc.spd;
  if (b.c8imps) b.c8imps.rages++;
  ev.fx = { type: 'ability', anim: 'b8i_rage', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push(`${c.name}は、顔をまっかにして、カンカンにおこった！（攻撃力と素早さが上がった！）`);
  ev.c8bRage = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// ひとりばけばけ（カンカンの あと）
function solo(b, c, ev) {
  const me = c.c8imp;
  const rc = impsConf(c).rage;
  if (me) me.left = rc.every;
  if (b.c8imps) b.c8imps.solos++;
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'b8i_solo', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  ev.lines.push(`${c.name}は、大きなおばけにばけて、とびかかってきた！`);
  physAll(b, c, rc.mult, 0.3, ev);
  ev.c8bSolo = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// たましいのけいやく（1人に けいやくしょ）
function contract(b, c, ev) {
  const h = c.c8hd;
  const hc = hadesConf(c);
  if (h) h.left = hc.contract.every;
  const pool = b.aliveAllies();
  const x = pool.length ? pool[b.rng.int(0, pool.length - 1)] : null;
  ev.fx = { type: 'ability', anim: 'b8h_contract', actor: c.id, targets: x ? [x.id] : [], side: 'enemy' };
  if (!x || !h) return;
  h.contract = { id: x.id, left: hc.contract.turns, drains: 0 };
  h.contracts++;
  ev.lines.push(`${x.name}の前に、まき物のけいやくしょが、ふわりとうかんだ…！`, `けいやくしょが、${x.name}にぴたりとはりついた！`);
  post(ev).push(`（ハデロスが動くたびに、${x.name}のHPがすいとられる…！ハデロスに炎を当てれば、けいやくしょがもえるはずだ！）`);
  ev.c8bContract = { id: c.id, who: x.id, turns: hc.contract.turns };
  ev.warn = true;
  ev.upd.push(c, x);
}

// たましいを いただく（けいやくした 人が たおれる）
function soul(b, c, ev) {
  const h = c.c8hd;
  const hc = hadesConf(c).contract;
  const x = h ? bound(b, c) : null;
  if (h) {
    h.contract = null;
    h.left = hc.every;
  }
  ev.fx = { type: 'ability', anim: 'b8h_soul', actor: c.id, targets: x ? [x.id] : [], side: 'enemy' };
  if (!x) {
    ev.lines.push('しかし、けいやくした人は、もういない！');
    return;
  }
  const dmg = x.hp;
  x.hp = 0;
  ev.results = ev.results || [];
  ev.results.push({ id: x.id, dmg, element: 'dark' });
  ev.lines.push(`けいやくしょが、${x.name}のたましいを、すいこんでしまった！`, ...b.kill(x, 'dark', ev));
  c.hp = Math.min(c.maxHp, c.hp + Math.round(c.maxHp * hc.soulHeal));
  post(ev).push(`${c.name}「ごちそうさま！いやー、いいたましいだ」（ハデロスのHPが、少し回復した…）`);
  h.souls++;
  ev.c8bSoul = { id: c.id, who: x.id };
  ev.warn = true;
  ev.upd.push(c, x);
}

// おこったハデロス（2だんめ）: 赤い 炎。弱点が ひっくりかえる。けいやくしょは もえる
function anger(b, c, ev) {
  const h = c.c8hd;
  const hc = hadesConf(c);
  if (!h || h.form !== 1) return;
  h.form = 2;
  h.left = eruptEvery(c);
  h.hot = false;
  h.flicker = false;
  c.name = RED_NAME;
  c.actions = RED_ACTIONS.map((x) => ({ ...x }));
  c.atk = Math.round(c.atk * (hc.red.atk ?? 1));
  Object.assign(c.resist, HADES_RED);
  ev.fx = { type: 'ability', anim: 'b8h_anger', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('ハデロスのかみの毛が、ボッ！と、まっ赤な炎になって、もえ上がった！', 'ハデロスは、カンカンにおこった！');
  const x = bound(b, c);
  if (h.contract) {
    h.contract = null;
    if (x) ev.lines.push(`赤い炎で、${x.name}のけいやくしょが、もえてしまった！`);
  }
  post(ev).push('（赤い炎のハデロスは、氷があまり効かない…！今度は、炎がよく効きそうだ！）');
  ev.c8bAnger = { id: c.id, freed: x?.id || null };
  ev.warn = true;
  ev.upd.push(c);
}

// よみの大ふん火（みんなに 炎の 大技。身を 守ると 半分）
function erupt(b, c, ev) {
  const h = c.c8hd;
  if (h) {
    h.left = eruptEvery(c);
    h.erupts++;
  }
  const base = hadesConf(c).erupt.base;
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'b8h_erupt', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy', element: 'fire' };
  for (const t of targets) {
    const r = b.calcMagic(c, t, { base, thr: 99, element: 'fire' }, 1);
    let dmg = r.dmg;
    if (t.defending) dmg = Math.round(dmg * 0.67);
    if (r.resisted || dmg <= 0) {
      ev.lines.push(`${t.name}はダメージを受けない！`);
      continue;
    }
    b.damage(c, t, dmg, ev, { element: 'fire' });
  }
  ev.c8bErupt = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// ───────────── ダメージ（battle-c8a.js の c8aDamage の はじめ。味方 → 敵 だけ）─────────────
// 小おに: パニックの 間は ダメージが ふえる・相談の 間の 大きな 一撃で けんか／
// ハデロス: けいやくの 間の 炎で けいやくしょが もえる・ふん火の 前ぶれの 氷で 頭が ひえる・おこる 前は HP が 下がりきらない
export function c8bDamage(b, c, t, dmg, info, ev) {
  // 第8章 第3幕: 橋の オノ・ギガクッパードの かたい 体・ギガに なる 前（battle-c8c.js）
  dmg = c8cDamage(b, c, t, dmg, info, ev);
  if (!(dmg > 0) || c?.side !== 'ally') return dmg;
  if (t.c8imp) {
    const ic = impsConf(t);
    if (t.c8imp.panic > 0) dmg = Math.round(dmg * ic.panic.k);
    if (plotting(b) && !ev.c8bQuarrel) {
      ev.c8bHit = ev.c8bHit || {};
      ev.c8bHit[t.id] = (ev.c8bHit[t.id] || 0) + dmg;
      if (ev.c8bHit[t.id] >= t.maxHp * ic.breakAt) quarrel(b, t, c, ev);
    }
    return dmg;
  }
  const h = t.c8hd;
  if (!h) return dmg;
  const hc = hadesConf(t);
  const el = info.element;
  if (h.form === 1 && h.contract && el === 'fire' && !ev.c8bBurn) burn(b, t, c, ev);
  if (h.form === 2 && el === 'ice' && !ev.c8bChill && eruptSoon(t)) chill(b, t, c, ev);
  if (h.form === 1) {
    const floor = Math.ceil(t.maxHp * hc.p2At - 1e-6) - 1;
    if (t.hp - dmg < floor) dmg = Math.max(0, t.hp - floor);
    // かみの毛が 赤く ちらちら（おこる 前ぶれ）
    if (!h.flicker && (t.hp - dmg) / t.maxHp < hc.p2At + 0.08) {
      h.flicker = true;
      post(ev).push(`${t.name}のかみの毛の炎が、ちらちらと赤くなってきた…！（もうすぐ、おこりそうだ…！）`);
      ev.c8bFlicker = { id: t.id };
      ev.upd.push(t);
    }
  }
  return dmg;
}

// けいやくしょが もえる（その 人は 助かる・ハデロスは あちちっ）
function burn(b, h, c, ev) {
  ev.c8bBurn = true;
  const x = bound(b, h);
  const hd = h.c8hd;
  hd.contract = null;
  hd.left = hadesConf(h).contract.every;
  hd.hot = true;
  hd.burns++;
  post(ev).push(`${c.name}の炎が、けいやくしょに、もえうつった！`, x ? `${x.name}のけいやくしょが、もえてなくなった！` : 'けいやくしょが、もえてなくなった！', `${h.name}「あちちちっ！」（ハデロスは、あわてている！）`);
  ev.c8bBurnt = { id: h.id, who: x?.id || null, by: c.id };
  ev.upd.push(h);
  if (x) ev.upd.push(x);
}

// ふん火の 前ぶれに 氷: 頭が ひえて ふん火が しぼむ
function chill(b, h, c, ev) {
  ev.c8bChill = true;
  const hd = h.c8hd;
  hd.left = eruptEvery(h);
  hd.cool = true;
  hd.cools++;
  if (h.telegraph === ERUPT) h.telegraph = null;
  post(ev).push(`${c.name}の氷で、${h.name}の頭が、ひえひえになった！`, 'よみの大ふん火が、しゅうっとしぼんだ！（次の番は動けない！）');
  ev.c8bCool = { id: h.id, by: c.id };
  ev.upd.push(h);
}

// ───────────── たおれた（battle-c8a.js の c8aKill の はじめ）─────────────
// 小おにの かたほうが たおれた: のこった ほうは パニック
export function c8bKill(b, t, ev) {
  // 第8章 第3幕: 魔法じんの 子分・橋の オノ（battle-c8c.js）
  c8cKill(b, t, ev);
  if (!t?.c8imp) return;
  const p = partnerOf(b, t);
  if (!p?.alive || p.c8imp.panic > 0 || p.c8imp.rage) return;
  const ic = impsConf(p);
  p.c8imp.panic = ic.panic.turns;
  p.c8imp.quarrel = false;
  if (p.telegraph === FUSE) p.telegraph = null;
  if (b.c8imps) {
    b.c8imps.panics++;
    b.c8imps.both = false;
    b.c8imps.quarrel = false;
  }
  if (!ev) return;
  post(ev).push(`${short(p)}「あ、あいぼうーっ！うわわわ、どうしよう、どうしよう！」`, `（${short(p)}は、あわてている！今なら、ダメージが${ic.panic.k}倍！${ic.panic.turns}回動くまでに、たおせ！）`);
  ev.c8bPanic = { id: p.id, down: t.id, turns: ic.panic.turns, k: ic.panic.k };
  ev.upd.push(p);
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// 小おにの みんなへの 大技（大がったい・ひとりばけばけ）が c の 次の 番より 先に 来るか
export function impBigBefore(b, c) {
  const s = b.c8imps;
  const imps = aliveImps(b);
  if (!s || !imps.length) return false;
  if (imps.some((e) => e.telegraph === FUSE || e.telegraph === SOLO)) return true;
  if (imps.length >= 2) {
    if (imps.some((e) => e.c8imp.quarrel)) return false;
    return imps.reduce((n, e) => n + actsBefore(b, c, e), 0) >= s.left;
  }
  const e = imps[0];
  if (!e.c8imp.rage) return false;
  return actsBefore(b, c, e) >= (e.c8imp.left || soloEvery(e));
}
// ハデロスの 大技（たましいを いただく〈けいやくした 人〉・大ふん火）が c の 次の 番より 先に 来るか
export function hadesBigBefore(b, c, h = hadesOf(b)) {
  const hd = h?.c8hd;
  if (!hd || hd.hot || hd.cool) return false;
  if (hd.form === 1) return !!hd.contract && hd.contract.id === c.id && hd.contract.left <= 0 && actsBefore(b, c, h) >= 1;
  if (h.telegraph === ERUPT) return true;
  return actsBefore(b, c, h) >= hd.left;
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。el … その 属性だけ。{ cmd, dmg }）
function bestHit(b, c, t, el = null) {
  let best = { cmd: null, dmg: 0 };
  if (!el) {
    const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
    best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  }
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    if (el && e.element !== el) continue;
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}
// 1体を ねらう 行動か（ねらいを かえられる）
function single(cmd) {
  if (!cmd) return false;
  if (cmd.type === 'attack') return true;
  if (cmd.type !== 'ability') return false;
  const a = ABILITIES[cmd.id];
  return a?.target === 'enemy' && ['phys', 'magic'].includes(prim(a).type);
}

// ───────────── オート（battle-c8a.js の c8aPlan の はじめ）─────────────
// 第8章 第2幕の ボスが いなければ null（ほかの ボスの 考えへ）
export function c8bPlan(b, c, decide) {
  if (c.side !== 'ally' || b.c8bInner || c.status?.rift) return null;
  // 第8章 第3幕の ボス（マジカメック・クッパード。battle-c8c.js）
  const cp = c8cPlan(b, c, decide);
  if (cp) return cp;
  const imps = aliveImps(b);
  const h = hadesOf(b);
  if (!imps.length && !h) return null;
  const soon = imps.length ? impBigBefore(b, c) : hadesBigBefore(b, c, h);
  // ふつうの オート: 大技が 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  if (!b.knowsCh6) {
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c8bInner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c8bInner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  if (imps.length) return impPlan(b, c, base, a, imps, soon);
  return hadesPlan(b, c, base, a, h, soon);
}

function impPlan(b, c, base, a, imps, soon) {
  // パニックの 小おにを ねらう（いちばん 大きい 1回の 攻撃）
  const pan = imps.find((e) => e.c8imp.panic > 0);
  if (pan) {
    if (a?.target === 'enemies' || a?.target === 'group') return base;
    const h = bestHit(b, c, pan);
    return h.dmg > 0 ? h.cmd : base;
  }
  // 相談の 間は、いちばん 大きい 1回の 攻撃で じゃまを する（とどく ときだけ）
  if (plotting(b) && !b.c8bNoPlot) {
    let best = null;
    for (const e of imps) {
      const h = bestHit(b, c, e);
      if (h.dmg >= e.maxHp * impsConf(e).breakAt * 0.9 && (!best || h.dmg / e.maxHp > best.dmg / best.e.maxHp)) best = { ...h, e };
    }
    if (best) return best.cmd;
  }
  // 大技の 前ぶれ（次に 小おにが 動くと 大技）が 出て いる ときだけ 身を 守る
  const warned = imps.length >= 2 ? b.c8imps.left <= 1 : (imps[0].c8imp.left || 9) <= 1;
  if (soon && warned && !b.c6NoGuard) return { type: 'defend' };
  // 2ひきの HP を そろえて へらす（HP の 多い ほうを ねらう。おなじ くらいなら はやい パニクル）→ かたほうを たおしたら、パニックの 間に もう かたほうも
  if (!b.c8bNoOrder && imps.length >= 2 && single(base)) {
    const r = (e) => e.hp / e.maxHp + (e.c8imp.role === 'panic' ? 0.05 : 0);
    const focus = imps.slice().sort((x, y) => r(y) - r(x))[0];
    if (base.target !== focus.id) {
      const h = bestHit(b, c, focus);
      if (h.cmd) return h.cmd;
    }
  }
  return base;
}

function hadesPlan(b, c, base, a, h, soon) {
  const hd = h.c8hd;
  // けいやくの 間は 炎を 当てる（けいやくしょが もえる）
  if (hd.form === 1 && hd.contract && !b.c8bNoBurn) {
    const f = bestHit(b, c, h, 'fire');
    if (f.dmg > 0) return f.cmd;
  }
  // ふん火の 前ぶれに 氷を 当てる（頭が ひえる）
  if (eruptSoon(h) && !b.c8bNoChill) {
    const i = bestHit(b, c, h, 'ice');
    if (i.dmg > 0) return i.cmd;
  }
  if (soon && !b.c6NoGuard) return { type: 'defend' };
  return base;
}

// ───────────── がめんへ（battle-c8a.js の c8aPub の さいご）─────────────
// 小おに: impLeft・impEvery（ばけばけ大がったいまで）・plot（相談）・quarrel・panicLeft・panicK・rage・soloLeft・soloEvery・impForm（2 … パニック・カンカンの え）
// ハデロス: c8hform（1 青・2 赤）・contractLeft・contractEvery・soulLeft（けいやくの のこり）・bound（けいやくした 人）・flicker・hot・cool・eruptLeft・eruptEvery
export function c8bPub(c, o) {
  // がめんは まえの ようすに 上書きで まぜる（client/battle.js の Object.assign）ので、なくなった しるしも 0・null で おくる
  // 第8章 第3幕（battle-c8c.js）
  c8cPub(c, o);
  if (c.c8imp) {
    const me = c.c8imp;
    const s = me.s;
    const show = !!s?.both && !(me.panic > 0) && !me.rage;
    o.impLeft = show ? s.left : 0;
    o.impEvery = show ? s.every : 0;
    o.plot = show && !s.quarrel && s.left <= s.plotAt ? 1 : 0;
    o.quarrel = me.quarrel ? 1 : 0;
    o.panicLeft = me.panic > 0 ? me.panic : 0;
    o.panicK = impsConf(c).panic.k;
    o.rage = me.rage ? 1 : 0;
    o.soloLeft = me.rage ? me.left : 0;
    o.soloEvery = me.rage ? soloEvery(c) : 0;
    o.impForm = me.panic > 0 || me.rage ? 2 : 1;
  }
  if (c.c8hd) {
    const h = c.c8hd;
    const blue = h.form === 1;
    o.c8hform = h.form;
    o.bound = blue && h.contract ? h.contract.id : null;
    o.soulLeft = blue && h.contract ? h.contract.left : 0;
    o.contractLeft = blue && !h.contract ? h.left : 0;
    o.contractEvery = blue && !h.contract ? hadesConf(c).contract.every : 0;
    o.flicker = blue && h.flicker ? 1 : 0;
    o.eruptLeft = blue ? 0 : h.left;
    o.eruptEvery = blue ? 0 : eruptEvery(c);
    o.hot = h.hot ? 1 : 0;
    o.cool = h.cool ? 1 : 0;
  }
}
