// 第2部 第8章 第3幕「くろがねの 空中ようさい」の ボスの 戦いの しかけ（battle-c8b.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・マジカメック（monsters-c8c.js の c8c.kind 'kamek'。Step 5 の さいごの 中ボス。子分 2ひきと いっしょ）「でっかくなあれ」
//   マジカメックが 動く たびに しるし（c.c8km.left）が へる。のこり grow.aimAt に なると、子分 1ぴきの 足もとに 魔法じん（前ぶれ・e.c8aimed）。
//   しるしが なくなった 次の マジカメックの 番に「でっかくなあれ」（m8k_grow）… 魔法じんの 子分が「デカ〜」に なる（HP grow.hp・攻撃力 grow.atk・
//   みんなを ふみつける）。魔法じんの 上の 子分は うける ダメージ grow.soft ばい。
//   その 前に 魔法じんの 子分を たおすと、次の 番に 魔法は から回り（m8k_fizzle「あれれ？」。その 番は 何も できない）。
//   から回りした 魔法は はね返って、マジカメックが「ちびカメック」に（tiny.turns 回 動く 間 うける ダメージ tiny.k ばい）。
//   子分が summon.below ひき より へると「出てこい子分」（m8k_summon。魔法じんの 間は よばない。summon.cd 回は よばない）。
//   HP が broomAt より へると、次の 番に「ほうきに のる」（m8k_broom。魔法が grow.broomEvery 回ごとに はやく なる・ほうきアタック）
// ・初代大魔王クッパード（c8c.kind 'bowser'。第3幕の さいごの ボス。2だん）
//   1だんめ（ふつう）: pound.every 回 動く たびに（しるし c.c8bw.left）「ドッスンヒップドロップ」（m8b_pound。みんなに 物理の 大技。身を 守ると 半分）
//   HP が gigaAt + 0.07 より へると、黒い星の かけらが 光る（前ぶれ）。gigaAt より へると、次の 番に「ギガクッパード」（m8b_giga）。
//     はじめて ギガに なるまで HP は gigaAt より 下がらない
//   2だんめ（ギガ）: うける ダメージ giga.cut ばい。giga.every 回 動く たびに「ギガほのお」（m8b_gigafire。みんなに 炎の 大技。身を 守ると 半分）。
//     ギガに なると「橋のオノ」（c8_axe。HP ＝ のこりの たたく 回数）が あらわれる。オノを ぶきで たたく たびに 1 へり（呪文では 動かない）、
//     0 に なると 橋が おちて、クッパードは ふつうの 大きさに もどる（最大HP の fall の ダメージ・次の 番は 動けない「あいたたた」）。
//     もどって giga.regrow 回 動くと、また ギガに なる（オノも また あらわれる。1つ前の 番に 前ぶれ）
// ・ふつうの オート（家族が「オート」に した とき）: 大技（ドッスンヒップドロップ・ギガほのお）が 自分の 次の 番より 先に 来る とき、
//   HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD。b.c6Naive … しない 人）。魔法じんにも 橋のオノにも 気づかない
// ・知っている 人（シミュレーター tools/sim-ch8.mjs。b.knowsCh6）:
//   マジカメック … 魔法じんの 子分を いちばん 大きい 1回の 攻撃で たおしに いく（b.c8cNoAim … しない）
//   クッパード … 橋のオノが ある 間は ぶきで たたく（たたく 人が 足りて いれば ほかは ふつう。b.c8cNoAxe … しない）・大技の 前に 身を 守る（b.c6NoGuard）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { C8_KAMEK, C8_BOWSER, C8_AXE, KAMEK_KIDS, GIGA_ACTIONS, BOWSER_ACTIONS, GIGA_KID_ACTION, GIGA_NAME } from './data/monsters-c8c.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate, pub } from './battle.js';
import { canUse } from './ai.js';
import { AUTO_GUARD } from './battle-ch6.js';

export { C8_KAMEK, C8_BOWSER, C8_AXE };
export const GROW = 'm8k_grow';
export const SUMMON = 'm8k_summon';
export const BROOM = 'm8k_broom';
export const FIZZLE = 'm8k_fizzle';
export const BROOM_HIT = 'm8k_broomhit';
export const POUND = 'm8b_pound';
export const GIGA = 'm8b_giga';
export const GIGAFIRE = 'm8b_gigafire';
export const FALLEN = 'm8b_fallen';
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});
const post = (ev) => (ev.postLines = ev.postLines || []);

const confOf = (m) => MONSTERS[m?.species]?.c8c || null;
export function kamekConf(m) {
  const c = confOf(m) || {};
  return {
    grow: { every: 4, broomEvery: 3, aimAt: 2, hp: 21000, atk: 1700, def: 1.2, soft: 2, ...(c.grow || {}) },
    summon: { kids: KAMEK_KIDS, cd: 2, below: 2, hp: 1.15, ...(c.summon || {}) },
    tiny: { turns: 2, k: 2, ...(c.tiny || {}) },
    broomAt: c.broomAt ?? 0.5,
  };
}
export function bowserConf(m) {
  const c = confOf(m) || {};
  return {
    pound: { every: 3, mult: 1.0, ignoreDef: 0.3, ...(c.pound || {}) },
    gigaAt: c.gigaAt ?? 0.5,
    giga: { atk: 1.12, cut: 0.7, every: 3, base: [560, 600], regrow: 5, fall: 0.05, axeHits: 3, ...(c.giga || {}) },
  };
}
const kamekOf = (b) => b.enemies.find((e) => e.c8km && e.alive) || null;
const bowserOf = (b) => b.enemies.find((e) => e.c8bw && e.alive) || null;
export const kidsAlive = (b) => b.enemies.filter((e) => e.c8kid && e.alive);
export const aimedKid = (b) => b.enemies.find((e) => e.c8kid && e.alive && e.c8aimed) || null;
export const axeOf = (b) => b.enemies.find((e) => e.c8ax && e.alive) || null;
export const growEvery = (c) => {
  const g = kamekConf(c).grow;
  return c.c8km?.broom ? g.broomEvery : g.every;
};
export const formOfB = (m) => m?.c8bw?.form || 0;

// マジカメックの 子分（魔法で 少し じょうぶ。HP summon.hp ばい）
function kidUp(km, m) {
  m.c8kid = true;
  m.maxHp = m.hp = Math.round(m.maxHp * kamekConf(km).summon.hp);
}

// ───────────── はじめ（battle-c8b.js の setupC8b の さいご）─────────────
export function setupC8c(b) {
  const lines = [];
  for (const e of b.enemies) {
    const conf = confOf(e);
    if (!conf) continue;
    if (conf.kind === 'kamek') {
      e.c8km = { left: kamekConf(e).grow.every, aim: null, broom: false, summonCd: 0, tiny: 0, grows: 0, fizzles: 0, summons: 0 };
      for (const k of b.enemies) if (KAMEK_KIDS.includes(k.species)) kidUp(e, k);
      lines.push(`${e.name}「ヒッヒッヒ…大魔王さまのじゃまは、させませんぞ！」`, '（マジカメックが、子分に魔法をかけようとしたら、先にその子分をたおそう…！）');
    }
    if (conf.kind === 'bowser') {
      e.c8bw = { form: 1, left: bowserConf(e).pound.every, flicker: false, fallen: false, everGiga: false, regrow: 0, axe: null, atk0: e.atk, gigas: 0, falls: 0, pounds: 0, fires: 0 };
      lines.push(`${e.name}「ガッハッハ！ワガハイこそ、空の大魔王クッパードさまだ！」`, '（まわりは、ようさいの大橋…はしっこに、大きなオノがある…）');
    }
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
}

// ───────────── 行動の はじめ（battle-c8b.js の c8bTurnStart の はじめ）─────────────
// 動けない 番も しるしを 数える（しるしが 1つの 番が 動けない ときは、次の 番に）
export function c8cTurnStart(b, c, ev, stuck) {
  if (c.c8km) kamekTurn(b, c, ev, stuck);
  else if (c.c8bw) bowserTurn(b, c, ev, stuck);
}

function kamekTurn(b, c, ev, stuck) {
  const k = c.c8km;
  const kc = kamekConf(c);
  if (c.telegraph) return;
  // ほうきに のる（HP が broomAt より へった）
  if (!k.broom && c.hp / c.maxHp < kc.broomAt) {
    if (!stuck) c.telegraph = BROOM;
    ev.upd.push(c);
    return;
  }
  if (k.summonCd > 0) k.summonCd--;
  // ちびカメック（魔法が はね返って ちぢんだ）の のこり
  if (k.tiny > 0) {
    k.tiny--;
    if (k.tiny === 0) post(ev).push(`${c.name}は、ポン！ともとの大きさにもどった。`);
  }
  // 魔法じんの 子分が もう いない: から回り（あれれ？）
  if (k.aim) {
    const t = b.get(k.aim);
    if (!t?.alive || t.c8giga) {
      if (!stuck) c.telegraph = FIZZLE;
      ev.upd.push(c);
      return;
    }
    // 魔法じんの 子分に「でっかくなあれ」
    if (k.left <= 1) {
      if (!stuck) c.telegraph = GROW;
      ev.upd.push(c);
      return;
    }
  }
  // 子分が へった: よぶ（魔法じんの 間は よばない）
  if (!k.aim && kidsAlive(b).length < kc.summon.below && k.summonCd <= 0) {
    if (!stuck) c.telegraph = SUMMON;
    ev.upd.push(c);
    return;
  }
  k.left = Math.min(k.left, growEvery(c));
  if (k.left > 1) k.left--;
  if (k.aim && k.left === 1) {
    const t = b.get(k.aim);
    ev.lines.push(`${t.name}の足もとの魔法じんが、強く光り出した…！`, `（次にマジカメックが動くと、${t.name}が大きくなってしまう…！）`);
  }
  if (!k.aim && k.left <= kc.grow.aimAt) {
    const pool = kidsAlive(b).filter((e) => !e.c8giga);
    if (pool.length) {
      const t = pool[b.rng.int(0, pool.length - 1)];
      k.aim = t.id;
      t.c8aimed = true;
      ev.lines.push(`${c.name}がつえをふると、${t.name}の足もとに、魔法じんがうかび上がった…！`, `（もうすぐ、${t.name}が大きくされてしまう…！先にたおせ！）`);
      ev.c8cAim = { id: c.id, who: t.id };
      ev.upd.push(t);
    } else k.left = kc.grow.aimAt + 1;
  }
  ev.c8cGrowLeft = { id: c.id, left: k.left, every: growEvery(c) };
  ev.upd.push(c);
}

function bowserTurn(b, c, ev, stuck) {
  const w = c.c8bw;
  const bc = bowserConf(c);
  if (c.telegraph) return;
  // 橋から おちて 目を まわしている（1回 動けない）
  if (w.fallen) {
    w.fallen = false;
    if (!stuck) c.telegraph = FALLEN;
    ev.upd.push(c);
    return;
  }
  if (w.form === 1) {
    // はじめて ギガに なる（HP）・もどってから また ギガに なる（行動の 数）
    if ((!w.everGiga && c.hp / c.maxHp < bc.gigaAt) || (w.regrow > 0 && w.regrow <= 1)) {
      if (!stuck) c.telegraph = GIGA;
      ev.upd.push(c);
      return;
    }
    if (w.regrow > 1) {
      w.regrow--;
      if (w.regrow === 1) ev.lines.push(`${c.name}のむねで、黒い星のかけらが、また光り出した…！`, '（次にクッパードが動くと、また、ギガクッパードになる…！）');
      ev.c8cRegrow = { id: c.id, left: w.regrow };
    }
    if (w.left <= 1) {
      if (!stuck) c.telegraph = POUND;
    } else {
      w.left--;
      if (w.left === 1) ev.lines.push(`${c.name}が、ひざをまげて、ぐっとしゃがみこんだ…！`, '（次にクッパードが動くと、ドッスンヒップドロップ…！身を守れ！）');
      ev.c8cPoundLeft = { id: c.id, left: w.left, every: bc.pound.every };
    }
    ev.upd.push(c);
    return;
  }
  // 2だんめ（ギガ）: ギガほのおまで
  if (w.left <= 1) {
    if (!stuck) c.telegraph = GIGAFIRE;
  } else {
    w.left--;
    if (w.left === 1) ev.lines.push(`${c.name}の口の中が、まっ赤にかがやき始めた…！`, '（次にギガクッパードが動くと、ギガほのお…！身を守るか、橋のオノを、ぶきでたたけ！）');
    ev.c8cFireLeft = { id: c.id, left: w.left, every: bc.giga.every };
  }
  ev.upd.push(c);
}

// ───────────── 技の こうか（battle-c8b.js の c8bEffect の のこり）─────────────
export function c8cEffect(b, c, a, eff, ev) {
  switch (eff.type) {
    case 'c8cGrow': grow(b, c, ev); return true;
    case 'c8cFizzle': fizzle(b, c, ev); return true;
    case 'c8cSummon': summon(b, c, ev); return true;
    case 'c8cBroom': broom(b, c, ev); return true;
    case 'c8cPound': pound(b, c, ev); return true;
    case 'c8cGiga': giga(b, c, ev); return true;
    case 'c8cGigaFire': gigaFire(b, c, ev); return true;
    case 'c8cFallen': ev.c8cFallenAct = { id: c.id }; return true;
    default: return false;
  }
}

// でっかくなあれ（魔法じんの 子分が デカ〜に なる）
function grow(b, c, ev) {
  const k = c.c8km;
  const t = k?.aim ? b.get(k.aim) : null;
  if (k) {
    k.aim = null;
    k.left = growEvery(c);
  }
  if (!t?.alive || t.c8giga) return fizzle(b, c, ev);
  t.c8aimed = false;
  const g = kamekConf(c).grow;
  t.c8giga = true;
  t.name = `デカ${t.name}`;
  t.maxHp = Math.max(t.maxHp, g.hp);
  t.hp = t.maxHp;
  t.atk = Math.max(t.atk, g.atk);
  t.dfn = Math.round(t.dfn * g.def);
  t.actions = [{ ...GIGA_KID_ACTION }, ...t.actions];
  if (k) k.grows++;
  ev.fx = { type: 'ability', anim: 'c8k_grow', actor: c.id, targets: [t.id], side: 'enemy' };
  ev.lines.push('魔法じんが、ピカーッと光った！', `${t.name.slice(2)}が、むくむくむく…と、大きくなった！`);
  post(ev).push(`（${t.name}のHPと攻撃力が、とても上がった…！）`);
  ev.c8cGrow = { id: c.id, who: t.id };
  ev.warn = true;
  ev.upd.push(c, t);
}

// 魔法の から回り（魔法じんの 子分が もう いない）: 魔法が はね返って、マジカメックが ちぢむ（tiny.turns 回 動く 間 うける ダメージ tiny.k ばい）
function fizzle(b, c, ev) {
  const k = c.c8km;
  const tc = kamekConf(c).tiny;
  if (k) {
    k.aim = null;
    k.left = growEvery(c);
    k.fizzles++;
    k.tiny = tc.turns + 1;
  }
  for (const e of b.enemies) e.c8aimed = false;
  ev.fx = { type: 'ability', anim: 'c8k_fizzle', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('しかし、魔法をかける子分が、もういない！', '魔法がはね返って、マジカメックが、ちっちゃくなった！');
  post(ev).push(`（ちびカメックは、ダメージが${tc.k}倍！今のうちに攻撃だ！）`);
  ev.c8cFizzle = { id: c.id, k: tc.k };
  ev.upd.push(c);
}

// 出てこい子分（子分を 2ひきまで よぶ）
function summon(b, c, ev) {
  const k = c.c8km;
  const kc = kamekConf(c);
  if (k) {
    k.summonCd = kc.summon.cd;
    k.summons++;
  }
  const alive = kidsAlive(b);
  const room = Math.min(2 - alive.length, 7 - b.aliveEnemies().length);
  ev.fx = { type: 'ability', anim: 'c8k_summon', actor: c.id, targets: [c.id], side: 'enemy' };
  if (room <= 0) {
    ev.lines.push('しかし、だれも来なかった！');
    return;
  }
  const want = kc.summon.kids.filter((sp) => !alive.some((e) => e.species === sp));
  const list = [...want, ...kc.summon.kids].slice(0, room);
  const added = b.addEnemies(list);
  for (const m of added) {
    kidUp(c, m);
    m.atb = b.rng.float(0, 30);
  }
  ev.lines.push(added.length > 1 ? `${added.map((m) => m.name).join('と')}が、とびこんできた！` : `${added[0].name}が、とびこんできた！`);
  ev.joined = (ev.joined || []).concat(added.map(pub));
  ev.c8cSummon = { id: c.id, who: added.map((m) => m.id) };
  ev.upd.push(c);
}

// ほうきに のる（魔法が はやく なる・ほうきアタック）
function broom(b, c, ev) {
  const k = c.c8km;
  if (!k || k.broom) return;
  k.broom = true;
  k.left = Math.min(k.left, growEvery(c));
  c.actions = [{ w: 3, id: BROOM_HIT, cond: `notRecent:${BROOM_HIT}` }, ...c.actions];
  ev.fx = { type: 'ability', anim: 'c8k_broom', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push(`${c.name}は、ほうきにのって、空へまい上がった！`);
  post(ev).push('（でっかくなあれの魔法が、速くなった…！魔法じんに気をつけろ！）');
  ev.c8cBroom = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// みんなへの 物理の 大技（身を 守ると 半分）
function physAll(b, c, mult, ignoreDef, ev) {
  const targets = b.aliveAllies();
  for (const t of targets) b.physHit(c, t, { mult, ignoreDef, acc: 1.2 }, ev, 'phys');
  return targets;
}

// ドッスンヒップドロップ
function pound(b, c, ev) {
  const w = c.c8bw;
  const pc = bowserConf(c).pound;
  if (w) {
    w.left = pc.every;
    w.pounds++;
  }
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'c8w_pound', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy' };
  ev.lines.push(`${c.name}が、ドッスーン！と、おしりからおちてきた！`, '橋が、ぐらぐらとゆれた！');
  physAll(b, c, pc.mult, pc.ignoreDef, ev);
  ev.c8cPound = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// ギガクッパード（2だんめ）: 大きく なる・橋の オノが あらわれる
function giga(b, c, ev) {
  const w = c.c8bw;
  const gc = bowserConf(c).giga;
  if (!w || w.form === 2) return;
  w.form = 2;
  w.everGiga = true;
  w.regrow = 0;
  w.flicker = false;
  w.left = gc.every;
  w.gigas++;
  c.name = GIGA_NAME;
  c.actions = GIGA_ACTIONS.map((x) => ({ ...x }));
  c.atk = Math.round(w.atk0 * gc.atk);
  ev.fx = { type: 'ability', anim: 'c8w_giga', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.lines.push('黒い星のかけらが、ぎらりと光った…！', 'クッパードの体が、ぐんぐんぐんぐん大きくなった！', 'ギガクッパードがあらわれた！');
  // 橋の オノ（はじめは 新しく・2回目からは また あらわれる）
  let axe = w.axe ? b.get(w.axe) : null;
  if (axe) {
    Object.assign(axe, { alive: true, hp: axe.maxHp, ready: false, queued: false, status: {}, buffs: {}, debuffs: {}, telegraph: null });
    axe.atb = 0;
  } else if (b.aliveEnemies().length < 7) {
    [axe] = b.addEnemies([C8_AXE]);
    axe.maxHp = axe.hp = gc.axeHits;
    axe.c8ax = { by: c.id };
    axe.atb = 0;
    w.axe = axe.id;
    ev.joined = (ev.joined || []).concat([pub(axe)]);
  }
  if (axe) {
    post(ev).push(`（ギガクッパードは、かたくて、ダメージが通りにくい…！でも、橋のはしに、大きなオノがある…！ぶきで${gc.axeHits}回たたけば、橋がおちるかも…！）`);
    ev.upd.push(axe);
  }
  ev.c8cGiga = { id: c.id, axe: axe?.id || null };
  ev.warn = true;
  ev.upd.push(c);
}

// ギガほのお（みんなに 炎の 大技。身を 守ると 半分）
function gigaFire(b, c, ev) {
  const w = c.c8bw;
  const gc = bowserConf(c).giga;
  if (w) {
    w.left = gc.every;
    w.fires++;
  }
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'c8w_gigafire', actor: c.id, targets: targets.map((x) => x.id), side: 'enemy', element: 'fire' };
  for (const t of targets) {
    const r = b.calcMagic(c, t, { base: gc.base, thr: 99, element: 'fire' }, 1);
    let dmg = r.dmg;
    if (t.defending) dmg = Math.round(dmg * 0.67);
    if (r.resisted || dmg <= 0) {
      ev.lines.push(`${t.name}はダメージを受けない！`);
      continue;
    }
    b.damage(c, t, dmg, ev, { element: 'fire' });
  }
  ev.c8cGigaFire = { id: c.id };
  ev.warn = true;
  ev.upd.push(c);
}

// 橋が おちる（オノを たたききった）: ギガクッパードは 下へ おちて ふつうの 大きさに もどる
function fall(b, h, by, ev) {
  const w = h.c8bw;
  const bc = bowserConf(h);
  w.form = 1;
  w.fallen = true;
  w.falls++;
  w.regrow = bc.giga.regrow;
  w.left = bc.pound.every;
  h.name = MONSTERS[h.species].name;
  h.actions = BOWSER_ACTIONS.map((x) => ({ ...x }));
  h.atk = w.atk0;
  if (h.telegraph) h.telegraph = null;
  b.queue = b.queue.filter((q) => q.id !== h.id);
  h.queued = false;
  const d = Math.max(0, Math.min(h.hp - 1, Math.round(h.maxHp * bc.giga.fall)));
  h.hp -= d;
  if (!ev) return;
  ev.results = ev.results || [];
  if (d > 0) ev.results.push({ id: h.id, dmg: d });
  post(ev).push('ガラガラガラ…！橋が、くずれおちた！', `${MONSTERS[h.species].short || h.name}「うおおおおっ！？」`, `${h.name}は、下へおちて、もとの大きさにもどった！${d > 0 ? `（${d}のダメージ！）` : ''}`, '（クッパードは、目を回している！今のうちに攻撃だ！）');
  ev.c8cFall = { id: h.id, by: by?.id || null, dmg: d };
  ev.upd.push(h);
}

// ───────────── ダメージ（battle-c8b.js の c8bDamage の はじめ。味方 → 敵 だけ）─────────────
// 橋の オノ: ぶきで たたくと 1 へる（呪文では 動かない）／ギガクッパード: うける ダメージ cut ばい／はじめて ギガに なる 前は HP が 下がりきらない
export function c8cDamage(b, c, t, dmg, info, ev) {
  if (!(dmg > 0) || c?.side !== 'ally') return dmg;
  // 魔法じんの 上の 子分は、魔法を うける じゅんびで 体が やわらかい（ダメージ grow.soft ばい）
  if (t.c8kid && t.c8aimed) {
    const km = kamekOf(b);
    dmg = Math.round(dmg * (km ? kamekConf(km).grow.soft : 1.5));
    if (!ev.c8cSoft) {
      ev.c8cSoft = true;
      post(ev).push(`（魔法じんの上の${t.name}は、ぐにゃぐにゃして、ダメージが大きい！）`);
    }
    return dmg;
  }
  if (t.c8ax) {
    if (!info.phys) {
      if (!ev.c8cAxeMagic) {
        ev.c8cAxeMagic = true;
        post(ev).push('（橋のオノは、呪文では動かない…！ぶきでたたこう！）');
      }
      return 0;
    }
    const left = t.hp - 1;
    ev.c8cAxeHit = { id: t.id, left };
    if (left > 0) post(ev).push(`橋のオノが、ぐらりとかたむいた！（あと${left}回！）`);
    return 1;
  }
  // ちびカメック: ダメージ tiny.k ばい
  if (t.c8km?.tiny > 0) return Math.round(dmg * kamekConf(t).tiny.k);
  const w = t.c8bw;
  if (!w) return dmg;
  const bc = bowserConf(t);
  if (w.form === 2) {
    dmg = Math.max(1, Math.round(dmg * bc.giga.cut));
    if (!ev.c8cCut) {
      ev.c8cCut = true;
      post(ev).push('ギガクッパードの体は、かたくて、ダメージが通りにくい…！');
    }
    return dmg;
  }
  if (!w.everGiga) {
    const floor = Math.ceil(t.maxHp * bc.gigaAt - 1e-6) - 1;
    if (t.hp - dmg < floor) dmg = Math.max(0, t.hp - floor);
    // 黒い星の かけらが 光る（ギガに なる 前ぶれ）
    if (!w.flicker && (t.hp - dmg) / t.maxHp < bc.gigaAt + 0.07) {
      w.flicker = true;
      post(ev).push(`${t.name}のむねで、黒い星のかけらが、あやしく光り始めた…！（もうすぐ、何かが起こりそうだ…！）`);
      ev.c8cFlicker = { id: t.id };
      ev.upd.push(t);
    }
  }
  return dmg;
}

// ───────────── たおれた（battle-c8b.js の c8bKill の はじめ）─────────────
// 魔法じんの 子分が たおれた・橋の オノが たおれた（橋が おちる）
export function c8cKill(b, t, ev) {
  if (t?.c8kid && t.c8aimed) {
    t.c8aimed = false;
    if (ev) {
      post(ev).push('魔法じんが、すうっと消えた！（でっかくなあれの魔法は、から回りするはずだ！）');
      ev.c8cAimGone = { id: t.id };
    }
  }
  if (t?.c8ax) {
    const h = bowserOf(b);
    if (h?.c8bw?.form === 2) fall(b, h, null, ev);
  }
}

// ───────────── 大技が 近いか ─────────────
// その 敵が c の 次の 番までに 何回 動くか
function actsBefore(b, c, e) {
  if (!e?.alive) return 0;
  const re = atbRate(e);
  if (!(re > 0)) return 0;
  const mine = 100 / atbRate(c);
  const t0 = e.ready || e.queued ? 0 : (100 - e.atb) / re;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / re));
}
// クッパードの 大技（ドッスンヒップドロップ・ギガほのお）が c の 次の 番より 先に 来るか
export function bowserBigBefore(b, c, h = bowserOf(b)) {
  const w = h?.c8bw;
  if (!w || w.fallen) return false;
  if (h.telegraph === POUND || h.telegraph === GIGAFIRE) return true;
  if (h.telegraph) return false;
  if (w.form === 1 && ((!w.everGiga && h.hp / h.maxHp < bowserConf(h).gigaAt) || (w.regrow > 0 && w.regrow <= 1))) return false;
  return actsBefore(b, c, h) >= w.left;
}

// その 敵に いちばん 大きい ダメージの 1回の 行動（攻撃・1体の 技。{ cmd, dmg }）
function bestHit(b, c, t) {
  const r0 = b.calcPhys(c, t, { mult: 1 }, 1, 'phys', true);
  let best = { cmd: { type: 'attack', target: t.id }, dmg: r0.dmg * r0.hit };
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || a.target !== 'enemy' || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, e.element || 'phys', true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}

// ───────────── オート（battle-c8b.js の c8bPlan の はじめ）─────────────
// 第8章 第3幕の ボスが いなければ null（ほかの ボスの 考えへ）
export function c8cPlan(b, c, decide) {
  if (c.side !== 'ally' || b.c8cInner || c.status?.rift) return null;
  const km = kamekOf(b);
  const h = bowserOf(b);
  if (!km && !h) return null;
  const soon = h ? bowserBigBefore(b, c, h) : false;
  // ふつうの オート: 大技が 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  if (!b.knowsCh6) {
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c8cInner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c8cInner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  if (km) {
    // 魔法じんの 子分を たおしに いく（全体の 攻撃なら そのまま）
    const t = aimedKid(b);
    if (t && !b.c8cNoAim) {
      if (a && FOES.has(a.target) && a.target !== 'enemy' && ['phys', 'magic'].includes(prim(a).type)) return base;
      const hit = bestHit(b, c, t);
      if (hit.dmg > 0) return hit.cmd;
    }
    return base;
  }
  // 橋の オノを ぶきで たたく（ほかの 人の たたく 番が 足りて いる ときは ふつう）
  const axe = axeOf(b);
  if (axe && !b.c8cNoAxe) {
    const coming = b.queue.filter((q) => q.cmd?.type === 'attack' && q.cmd.target === axe.id).length;
    if (coming < axe.hp) return { type: 'attack', target: axe.id };
  }
  if (soon && !b.c6NoGuard) return { type: 'defend' };
  return base;
}

// ───────────── がめんへ（battle-c8b.js の c8bPub の さいご）─────────────
// マジカメック: kmForm（1 ふつう・2 ほうき）・growLeft・growEvery（でっかくなあれまで）／子分: aimed（魔法じん）・giga（デカ）
// クッパード: bwForm（1 ふつう・2 ギガ）・poundLeft・poundEvery・fireLeft・fireEvery・flicker・regrowLeft・fallen／橋の オノ: axeLeft・axeMax
export function c8cPub(c, o) {
  // がめんは まえの ようすに 上書きで まぜる（client/battle.js の Object.assign）ので、なくなった しるしも 0 で おくる
  if (c.c8km) {
    const k = c.c8km;
    o.kmForm = k.broom ? 2 : 1;
    o.growLeft = k.aim ? 1 : k.left;
    o.growEvery = growEvery(c);
    o.tiny = k.tiny > 0 ? 1 : 0;
    o.tinyK = kamekConf(c).tiny.k;
  }
  if (c.c8kid) {
    o.aimed = c.c8aimed ? 1 : 0;
    o.giga = c.c8giga ? 1 : 0;
  }
  if (c.c8bw) {
    const w = c.c8bw;
    const bc = bowserConf(c);
    const g = w.form === 2;
    o.bwForm = w.form;
    o.poundLeft = g ? 0 : w.left;
    o.poundEvery = g ? 0 : bc.pound.every;
    o.fireLeft = g ? w.left : 0;
    o.fireEvery = g ? bc.giga.every : 0;
    o.flicker = !g && !w.everGiga && w.flicker ? 1 : 0;
    o.regrowLeft = !g && w.regrow > 0 ? w.regrow : 0;
    o.fallen = w.fallen ? 1 : 0;
  }
  if (c.c8ax) {
    o.axeLeft = c.alive ? c.hp : 0;
    o.axeMax = c.maxHp;
  }
}
void C8_KAMEK; void C8_BOWSER;

js/shared/battle-ch4.js:
// 第4章の たたかいの しかけ（battle.js・ai.js から よぶ。ほかの たたかいは かわらない）
//
// ・まぼろしの分身（Step 5 の 大臣ザイード。Step 7 の モルガナでも 使える）
//   おなじ しゅるいの 魔物が 2体いじょう いて、その しゅるいに mirage が ある とき、1体だけが 本物（shade … 足もとに 小さな 影）、
//   のこりは 分身（clone）。3体とも 名前も すがたも おなじ（A・B・C は ならびの じゅん）
//   ・分身に 攻撃・呪文・特技が 当たると「まぼろしだった！」と 消える（たおした ことには ならない。経験値も ない）。
//     そのたびに 本物の「まぼろしのわらい」で、当てた 人の MPが へる
//   ・分身は 本物より 弱い 攻撃しか しない（mirage.cloneAtk・cloneActions）。HPは 本物と おなじに 見せる
//   ・本物は、分身が 消えてから mirage.cycle 回 動くと、まぼろしを 作りなおす（分身が もどり、3体の ならびが いれかわる）。
//     もどる 1つ前の 番に 前ぶれ（空気が ゆらゆら）
//   ・月の鏡（道具の コマンド。パーティーが 持っている）: 分身が ぜんぶ 消え、本物は つぎの 番 動けない（まぶしい）。
//     本物が mirage.mirror 回 動くまで、鏡の 光は もどらない（「3ターンに1回」）
//   ・本物が たおれると、分身も 消える
// ・そうびしたまま 使える 道具（items の equipUse。魔神のランプ）: 道具の コマンドで 1回の たたかいに 1回 使える
// ・砂に もぐる（Step 6 の 砂クジラ）: 技の 効果 { type: 'burrow', next: '<とび出す 技>' }。
//   「砂の中に もぐった！」→ つぎの 自分の 番まで ねらえない（味方の 攻撃・呪文・特技の 的に ならない。全体の 呪文も 当たらない）。
//   ゲージが たまってくると「砂が もり上がった…！」（前ぶれ。身を 守る じかん）→ つぎの 番に 出てきて とび出す 技（ai.js の telegraph）
import { MONSTERS } from './data/monsters.js';
import { ITEMS } from './data/items.js';
import { ABILITIES } from './data/abilities.js';
import { DUAL_TECHS } from './data/dual.js';
// こうどうゲージの はやさ（battle.js。たがいに よびあうが、つかうのは たたかいの 中だけ）
import { atbRate } from './battle.js';

export const MIRROR_ID = 'moon_mirror';
const LETTERS = 'ABCDEFGH';

// ───────────── まぼろしの分身 ─────────────
// たたかいの はじめ（Battle の constructor）。分身の いる たたかいなら b.mirage を 作る
export function setupMirage(b) {
  const groups = new Map();
  for (const e of b.enemies) {
    if (!MONSTERS[e.species]?.mirage) continue;
    if (!groups.has(e.species)) groups.set(e.species, []);
    groups.get(e.species).push(e);
  }
  const list = [...groups.values()].find((g) => g.length >= 2);
  if (!list) return;
  const conf = MONSTERS[list[0].species].mirage;
  const real = b.rng.pick(list);
  real.shade = true;
  for (const e of list) {
    if (e === real) continue;
    e.clone = true;
    e.atk = Math.round(e.atk * (conf.cloneAtk ?? 0.5));
    e.actions = (conf.cloneActions || [{ w: 1, id: 'attack' }]).map((a) => ({ ...a }));
  }
  b.mirage = {
    species: list[0].species, real: real.id, clones: list.filter((e) => e !== real).map((e) => e.id),
    // cycle … 分身が 消えてから もどるまでの 本物の 番。mirror … 月の鏡の 光が もどるまでの 本物の 番。cd … のこり
    cycle: conf.cycle ?? 3, count: 0, mirror: conf.mirror ?? 3, cd: 0, laugh: conf.laugh || [10, 16],
  };
  if (conf.intro) b.emit({ t: 'msg', lines: conf.intro.slice(), dur: 1500 });
}

const cloneList = (b) => (b.mirage ? b.mirage.clones.map((id) => b.get(id)).filter(Boolean) : []);

// 消える（たおれた ことには しない。killed に 入れない）
function vanish(b, t) {
  Object.assign(t, {
    alive: false, hp: 0, ready: false, queued: false, defending: false, cover: null,
    status: {}, buffs: {}, debuffs: {}, telegraph: null, stance: null, chant: null,
  });
  b.queue = b.queue.filter((q) => q.id !== t.id);
}

// 分身に 当たった（c … 当てた 人）。消えたら true（その 当たりは そこで おしまい）
// battle.js の physHit・magicHit・damage・tryStatus・applyDebuff・trySteal・banish・drainMp の はじめで よぶ
export function mirageHit(b, c, t, ev) {
  if (!t?.clone || !t.alive || !b.mirage || !c || c.side === t.side) return false;
  vanish(b, t);
  ev.lines.push(`まぼろしだった！${t.name}は、すうっと消えた…！`);
  (ev.results = ev.results || []).push({ id: t.id, vanish: true });
  ev.upd.push(t);
  laugh(b, c, ev);
  return true;
}

// まぼろしの わらい: 当てた 人の MPが へる（1回の 行動で いくつ 消しても、ことばは 1回。へる MPは 消した 数だけ）
function laugh(b, c, ev) {
  const real = b.get(b.mirage.real);
  // 分身に 当てると 本物の キズが いえる 魔物（Step 7 の モルガナ。mirage.heal … 最大HPの わりあい）
  const conf = MONSTERS[b.mirage.species].mirage;
  if (conf.heal) return mirageHeal(b, real, conf, ev);
  // 合体技の 2人の 力を 合わせた かげ（battle.js の dualProxy）でも、ほんとうの 人の MPを へらす
  const who = b.get(c.id) || c;
  if (!real?.alive || who.side !== 'ally') return;
  const [mn, mx] = b.mirage.laugh;
  const d = Math.min(who.mp, b.rng.int(mn, mx));
  who.mp -= d;
  ev.upd.push(who);
  const L = ev.laugh || (ev.laugh = {});
  L[who.id] = (L[who.id] || 0) + d;
  const text = (id, n) => {
    const w = b.get(id);
    return n > 0 ? `まぼろしのわらい！${w.name}のMPが${n}へった！` : `まぼろしのわらい！…しかし${w.name}のMPは、もうない。`;
  };
  ev.postLines = ev.postLines || [];
  if (!ev.laughAt) {
    ev.postLines.push(`どこからか、${MONSTERS[b.mirage.species].laughBy || 'わらい声'}がひびく…「フハハハ…！」`);
    ev.laughAt = {};
  }
  if (ev.laughAt[who.id] === undefined) {
    ev.laughAt[who.id] = ev.postLines.length;
    ev.postLines.push(text(who.id, L[who.id]));
  } else ev.postLines[ev.laughAt[who.id]] = text(who.id, L[who.id]);
}

// 分身に 当てた: 本物の HPが 少し 回復する（1回の 行動で 何体 消しても、ことばは 1回。回復は 消した 数だけ）。
// 名前は 言わない（どれが 本物か 分からない ように）
function mirageHeal(b, real, conf, ev) {
  if (!real?.alive) return;
  const h = Math.min(real.maxHp - real.hp, Math.round(real.maxHp * conf.heal));
  real.hp += h;
  mirageSync(b, real);
  ev.upd.push(real);
  ev.mirageHeal = (ev.mirageHeal || 0) + h;
  ev.postLines = ev.postLines || [];
  const name = MONSTERS[b.mirage.species].name;
  const text = ev.mirageHeal > 0 ? `${name}のキズが、${ev.mirageHeal}回復した…！` : `${name}は、キズひとつない…。`;
  if (ev.healAt === undefined) {
    ev.postLines.push(`どこからか、${conf.laughBy || 'わらい声'}がひびく…「ふふふ…」`);
    ev.healAt = ev.postLines.length;
    ev.postLines.push(text);
  } else ev.postLines[ev.healAt] = text;
}

// kill() の はじめ: 分身は 消える（たおした ことに ならない）。消えた ときの ことば（分身で なければ null）
export function mirageVanish(b, t, ev) {
  if (!t.clone) return null;
  vanish(b, t);
  if (ev) ev.upd.push(t);
  return [`まぼろしだった！${t.name}は、すうっと消えた…！`];
}

// 本物が たおれた: 分身も みんな 消える（kill() の おわりで よぶ。ことばの ならび）
export function mirageDown(b, t, ev) {
  if (!b.mirage || t.id !== b.mirage.real) return [];
  const gone = cloneList(b).filter((x) => x.alive);
  for (const x of gone) {
    vanish(b, x);
    if (ev) ev.upd.push(x);
  }
  return gone.length ? [MONSTERS[b.mirage.species].mirage.downMsg || 'まぼろしの分身も、砂になって消えていった…！'] : [];
}

// 本物の HPが かわった: 分身の HPも おなじに 見せる（どれが 本物か、HPでは 分からない）
export function mirageSync(b, t) {
  if (!t.shade || !b.mirage) return;
  for (const x of cloneList(b)) if (x.alive) x.hp = t.hp;
}

// 魔物の 番の はじめ（ai.js の decideMonster）。本物の 番なら、まぶしくて 動けない・まぼろしを 作りなおす（ほかは null）
export function mirageAction(b, m) {
  const M = b.mirage;
  if (!M || m.id !== M.real) return null;
  const cur = b.cur;
  if (M.cd > 0) M.cd--;
  if (cur) cur.mirror = M.cd;
  const missing = cloneList(b).some((x) => !x.alive);
  if (missing) M.count++;
  // つぎの 番に まぼろしが もどる: 前ぶれ（月の鏡を 使う じゅんびを する じかん）
  const hint = () => {
    if (missing && M.count + 1 >= M.cycle && cur) cur.postLines = (cur.postLines || []).concat(`（${m.name}のまわりの空気が、ゆらゆらとゆれ始めた…）`);
  };
  // 月の鏡で まぶしい 番は、何も できない（まぼろしを 作りなおすのも つぎの 番）
  if (m.dazzled) {
    m.dazzled = false;
    hint();
    return { type: 'ability', id: MONSTERS[m.species].mirage.dazzled || 'm_mirage_dazzled' };
  }
  if (missing && M.count >= M.cycle) {
    M.count = 0;
    return { type: 'ability', id: MONSTERS[m.species].mirage.remake };
  }
  hint();
  return null;
}

// まぼろしを 作りなおす（技の 効果 { type: 'mirage' }。battle.js の applyAbility）
export function mirageRemake(b, c, ev) {
  const M = b.mirage;
  if (!M || c.id !== M.real) {
    ev.lines.push('しかし、何も起こらなかった…。');
    return;
  }
  const clones = cloneList(b);
  for (const x of clones) {
    if (x.alive) continue;
    Object.assign(x, { alive: true, hp: c.hp, maxHp: c.maxHp, ready: false, queued: false, status: {}, buffs: {}, debuffs: {}, telegraph: null, stance: null, chant: null });
    x.atb = b.rng.float(0, 30);
  }
  // ならびを いれかえる（本物が どこに いるか 分からなく なる）。名前の A・B・C は 左からの じゅん
  const group = [c, ...clones];
  const slots = group.map((x) => x.slot).sort((p, q) => p - q);
  b.rng.shuffle(group).forEach((x, i) => {
    x.slot = slots[i];
    x.letter = LETTERS[i];
    x.name = x.baseName + x.letter;
  });
  ev.lines.push(`${MONSTERS[M.species].name}は、まぼろしを作り出した！`, `${group.length}人の${MONSTERS[M.species].name}が、すばやく入れかわった…！`);
  ev.fx = { type: 'ability', anim: 'mirage', actor: c.id, targets: group.map((x) => x.id), side: c.side, mirage: true };
  ev.warn = true;
  for (const x of group) ev.upd.push(x);
}

// ───────────── 月の鏡 ─────────────
// 使えるか（validate）
export function mirrorCheck(b) {
  const M = b.mirage;
  if (!M) return { ok: false, reason: '今は使えない' };
  if (M.cd > 0) return { ok: false, reason: `月の鏡の光が、まだもどっていない…（あと${M.cd}）` };
  return { ok: true };
}

export function useMirror(b, c, ev) {
  ev.name = ITEMS[MIRROR_ID]?.name || '月の鏡';
  ev.lines.push(`${c.name}は、月の鏡を高くかかげた！`);
  const M = b.mirage;
  if (!M || M.cd > 0) {
    ev.lines.push('しかし、鏡の光は、まだ弱い…。');
    return;
  }
  ev.lines.push('月の光が、あたりをてらした…！');
  M.cd = M.mirror;
  ev.mirror = M.cd;
  const gone = cloneList(b).filter((x) => x.alive);
  ev.results = ev.results || [];
  for (const x of gone) {
    vanish(b, x);
    ev.upd.push(x);
    ev.results.push({ id: x.id, vanish: true });
  }
  if (gone.length) ev.lines.push(gone.length > 1 ? 'まぼろしの分身が、すべて消えた！' : 'まぼろしの分身が消えた！');
  else ev.lines.push('…まぼろしは、どこにもいない。');
  const real = b.get(M.real);
  if (real?.alive) {
    // つぎの 番は まぶしくて 動けない（もう ならんで いる 行動も とりやめ）
    real.dazzled = true;
    b.queue = b.queue.filter((q) => q.id !== real.id);
    real.queued = false;
    ev.lines.push(`${real.name}は、まぶしそうに目をおおった！`);
    ev.upd.push(real);
  }
  ev.fx = { type: 'mirror', actor: c.id, targets: [...gone.map((x) => x.id), ...(real?.alive ? [real.id] : [])], side: 'ally' };
}

// まぼろしを 知っている 人（tools/sim.js の「知っている人」。b.knowsMirage）: 月の鏡の コマンド（使わない ときは null）
export function mirrorPlan(b) {
  const M = b.mirage;
  if (!M || M.cd > 0) return null;
  const real = b.get(M.real);
  if (!real?.alive || real.dazzled) return null;
  return { type: 'item', id: MIRROR_ID };
}

// ───────────── そうびしたまま 使える 道具（魔神のランプ）─────────────
export function equipUseCheck(c, id) {
  if (c.acc !== id) return { ok: false, reason: '装備していない' };
  if ((c.equipUsed || []).includes(id)) return { ok: false, reason: 'この戦いでは、もう使った' };
  return { ok: true };
}

function useEquip(b, c, cmd, ev) {
  const it = ITEMS[cmd.id];
  const u = it.equipUse;
  ev.name = it.name;
  ev.lines.push(`${c.name}は${it.name}を使った！`);
  if (!equipUseCheck(c, cmd.id).ok) {
    ev.lines.push('しかし、何も起こらなかった！');
    return;
  }
  c.equipUsed = [...(c.equipUsed || []), cmd.id];
  if (u.msg) ev.lines.push(u.msg);
  const targets = b.sideOf(c, true).filter((x) => x.alive);
  ev.fx = { type: 'item', actor: c.id, targets: targets.map((x) => x.id), side: 'ally', anim: 'heal1' };
  for (const t of targets) {
    const d = Math.min(t.maxMp - t.mp, b.rng.int(u.base[0], u.base[1]));
    t.mp += d;
    ev.lines.push(d > 0 ? `${t.name}のMPが${d}回復した！` : `${t.name}のMPは満タンだ。`);
    ev.upd.push(t);
  }
  ev.upd.push(c);
}

// ───────────── 道具の コマンド（battle.js の validate・useItem の はじめ）─────────────
// 第4章の とくべつな 道具なら { ok, reason }（ほかは null で、ふつうの 道具の きまり）
export function ch4ItemCheck(b, c, id) {
  if (id === MIRROR_ID) return mirrorCheck(b);
  if (ITEMS[id]?.equipUse) return equipUseCheck(c, id);
  return null;
}

// 第4章の とくべつな 道具を 使った（ふつうの 道具なら false）
export function ch4UseItem(b, c, cmd, ev) {
  if (cmd.id === MIRROR_ID) {
    useMirror(b, c, ev);
    return true;
  }
  if (ITEMS[cmd.id]?.equipUse) {
    useEquip(b, c, cmd, ev);
    return true;
  }
  return false;
}

// クライアントへ おくる 月の鏡の ようす（まぼろしの いない たたかいは null）
export function mirrorSnap(b) {
  return b.mirage ? { cd: b.mirage.cd, max: b.mirage.mirror } : null;
}

// ───────────── 砂に もぐる（Step 6 の 砂クジラ）─────────────
// warnAt … ゲージが ここまで たまると「砂がもり上がった…！」（前ぶれ。身を 守る じかん）
export const BURROW_WARN = 60;

// c から t を ねらえない（砂に もぐった 敵）。battle.js の sideOf・こんらんの 相手
export function hiddenFrom(c, t) {
  return !!t?.burrow && !!c && t.side !== c.side;
}

// 技の 効果 { type: 'burrow', next, warnAt }（battle.js の applyAbility）
export function burrowStart(b, c, eff, ev) {
  c.burrow = { warnAt: eff.warnAt ?? BURROW_WARN, warned: false };
  // つぎの 番は とび出す 技（ai.js の decideMonster の telegraph）
  c.telegraph = eff.next || null;
  c.stance = null;
  c.chant = null;
  // この 番の のこりの 行動は とりやめ（砂の 中で つぎの 番を まつ）
  b.queue = b.queue.filter((q) => q.id !== c.id);
  ev.forceLast = true;
  ev.atbAfter = eff.atbAfter ?? 0;
  ev.fx = { ...(ev.fx || {}), type: 'ability', actor: c.id, targets: [c.id], side: c.side, burrow: true };
  ev.warn = true;
  ev.lines.push(`（${c.name}には、攻撃がとどかない…！）`);
  ev.upd.push(c);
}

// ゲージが たまってきた: 前ぶれ（battle.js の advance で よぶ。pub … クライアントへ おくる 形）
export function burrowWarn(b, pub) {
  for (const c of b.combatants) {
    if (!c.burrow || c.burrow.warned || !c.alive || c.fled || c.atb < c.burrow.warnAt) continue;
    c.burrow.warned = true;
    const lines = ['砂がもり上がった…！', `${c.name}が、今にも飛び出してきそうだ…！`];
    const dur = b.pace(500, 380, lines.length, 900);
    b.emit({ t: 'msg', id: c.id, lines, upd: [pub(c)], fx: { type: 'burrowRise', actor: c.id }, warn: true, dur });
    b.lock = Math.max(b.lock, dur);
  }
}

// もぐっていた 魔物の 番（ai.js の decideMonster の はじめ）: 砂から 出てくる
export function burrowSurface(b, m) {
  if (!m.burrow) return;
  m.burrow = null;
  if (b.cur) b.cur.upd.push(m);
}

// 敵を ねらう 行動か（ねらえる 敵が いないと 空ぶり）
function aimsAtFoes(cmd) {
  if (['attack', 'mahouken'].includes(cmd.type)) return true;
  if (cmd.type === 'ability') return ['enemy', 'group', 'enemies'].includes(ABILITIES[cmd.id]?.target);
  if (cmd.type === 'dual') return ['enemy', 'group', 'enemies'].includes(DUAL_TECHS[cmd.id]?.target);
  return false;
}

// 味方が 敵を ねらう 行動を したが、敵が みんな 砂の 中（battle.js の perform の はじめ）。
// 何も しないで おわる（MPも へらない）。ほかの ときは false
export function burrowBlock(b, c, cmd, ev) {
  if (c.side !== 'ally' || !cmd || cmd.confused) return false;
  const foes = b.enemies.filter((e) => e.alive);
  if (!foes.length || !foes.every((e) => e.burrow) || !aimsAtFoes(cmd)) return false;
  ev.lines.push(`しかし、${foes[0].name}は砂の中にもぐっている！`, `${c.name}は、ねらいをつけられない…！`);
  ev.fx = { type: 'burrowMiss', actor: c.id, side: 'ally' };
  return true;
}

// 砂に もぐる 魔物を 知っている 人（tools/sim.js の「知っている人」。b.knowsBurrow）: とび出す 前に 身を 守る。
// 知らない 人（b.ignoreBurrow）: ねらえる 敵が いなくても 攻撃しようと する（空ぶり）。ほかは null（ふつうの オート）
export function burrowPlan(b, c, foes) {
  const hidden = b.enemies.filter((e) => e.alive && e.burrow);
  if (!hidden.length) return null;
  if (b.knowsBurrow) {
    // つぎの 自分の 番より 先に、もぐった 敵の 番が 来る（前ぶれが 出た ときも）
    const mine = 100 / atbRate(c);
    if (hidden.some((e) => e.burrow.warned || (100 - e.atb) / atbRate(e) <= mine)) return { type: 'defend' };
  }
  if (b.ignoreBurrow && !foes.length) return { type: 'attack', target: hidden[0].id };
  return null;
}

js/shared/battle-ch5.js:
// 第5章 Step 2「星の塔」の たたかいの しかけ（battle.js・ai.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・見通しの目（星の番人アルゴス。monsters の foresee）:
//   「アルゴスの3つの目が、〇〇をじっと見ている…」で、その 人の 次の 行動の 種類（KINDS: 攻撃・呪文・回復・防御）を 読む。
//   読む 種類は、その 人が この 戦いで さいごに 使った 行動の 種類（まだ 何も して いなければ、職業と 技から いちばん しそうな もの）。
//   読まれた 人が 次に その 種類の 行動を そのまま 使うと（foreseeHit）:
//     攻撃（ふつうの 攻撃・特技・魔法剣）… かわされて、アルゴスの 反撃（foresee.counter ばい）
//     呪文（回復 いがい）… MPを はらって、はね返される（foresee.bounce ばい・さいだいHPの foresee.cap まで。ダメージの ない 呪文は かき消される）
//     回復（回復・生き返り・治す 技と 道具）… MPを はらって、かき消される（道具は へらない）
//     防御 … 守りを 見ぬかれて、身を 守れず 守備力が 下がる
//   ちがう 種類の 行動を すれば「読みが外れた！」で、アルゴスの こうどうゲージが foresee.daze へる（目が くらむ）。
//   読みは その 人の 次の 番まで（ねむり・マヒで 動けない 番が 来ても 消える）。HPが foresee.two より へると 2人を 同時に 読む
//   合体技（ミナデインも）・にげる・混乱した 時の 行動は 読まれない（読みは 消える）
// ・オートの 仲間: 読まれた 種類の 行動を さけて、ちがう 行動を えらぶ（towerPlan）。シミュレーター（tools/sim.js）の
//   b.argosNaive … 知らない 人（読まれても そのまま）／ b.knowsArgos … 知っている 人（星のさばきの 前に 身を 守る も）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { abilityFor } from './ability-label.js';
import { ITEMS } from './data/items.js';
import { mpCost, penaltyFor } from './stats.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
// 第5章 Step 4: ガイアイーターの 多部位の 戦い（battle-gaia.js。ここから よぶ）
import { gaiaEffect, gaiaCond, gaiaKill, gaiaPlan, gaiaPub } from './battle-gaia.js';
// 第5章 Step 5: ノクトの影（職業の まね・合体技の よやくを こわす。battle-nocto.js。ここから よぶ）
import { noctoCond, noctoEffect, noctoCheck, noctoKill, noctoPlan, noctoPub } from './battle-nocto.js';
// 第5章 Step 6・7: ノクト（1回目）・大地の神殿の 魔物（かげぶんしん・地われ・まもる・おこる。battle-earth.js。ここから よぶ）
import { earthCond, earthEffect, earthKill, earthPlan, earthPub, earthTurnStart } from './battle-earth.js';
// 第5章 Step 9: ノクト（本気）・魔王ソリトゥス（ひとりにする・よびかける・きずなを食べる・家族の きずな技。battle-final.js。ここから よぶ）
import { finalCond, finalEffect, finalCheck, finalKill, finalPlan, finalPub, finalTurnStart } from './battle-final.js';
// 第5章 Step 8: 影の城の 3人の まぼろし（風のかべ・かげ火の力・水かさ。battle-phantom.js。ここから よぶ）
import { phantomCond, phantomEffect, phantomPlan, phantomPub, phantomTurnStart } from './battle-phantom.js';
// 第2部 第6章 Step 1・2: サンドクロック（砂が落ちきると…）・ギアドン（まき戻し）。battle-ch6.js。ここから よぶ
import { ch6Cond, ch6Effect, ch6Plan, ch6Pub, ch6TurnStart } from './battle-ch6.js';
// 第2部 第6章 Step 6: ゼンマイの 歯車が こわれると 針が もどる（battle-tokei6.js）
import { tokei6Kill } from './battle-tokei6.js';
// 第2部 第7章 第1幕: ウツボが たおれると もう 1ぴきが よびもどす・声の貝が こわれると 声が もどる（battle-c7.js）
import { c7Kill } from './battle-c7.js';
// 第37回 A: サファラ闘技場の 王者の しかけ（チームの 合体技・属性の よろい）
import { arenaCond, arenaEffect } from './battle-arena.js';
// 第51回 C1: 幻の職業の 技（気を ためる・影分身・自動最適化。battle-phantom-a.js）
import { phantomAEffect, phantomATurnStart } from './battle-phantom-a.js';

export const ARGOS = 'argos';
export const JUDGE = 'm_argos_judge';
export const KINDS = ['phys', 'spell', 'heal', 'guard'];
export const KIND_NAMES = { phys: '攻撃', spell: '呪文', heal: '回復', guard: '防御' };
// 回復の なかまの 技の こうか
const HEAL_TYPES = new Set(['heal', 'revive', 'reviveAll', 'cure', 'mpHeal', 'regen']);
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || a.effect : a?.effect || {});
const isSpell = (a) => !!a && (a.kind === 'spell' || !!a.spellLike);
const confOf = (m) => MONSTERS[m?.species]?.foresee || null;
// ことばで 使う みじかい 名前（星の番人アルゴス → アルゴス）
const shortName = (m) => (m.species === ARGOS ? 'アルゴス' : m.name);

// ───────────── 行動の 種類 ─────────────
// cmd の 種類（読まれない 行動は null）
export function actKind(cmd) {
  if (!cmd) return null;
  switch (cmd.type) {
    case 'attack': case 'mahouken': return 'phys';
    case 'defend': return 'guard';
    case 'item': return 'heal';
    case 'ability': {
      const a = ABILITIES[cmd.id];
      if (!a) return null;
      if (HEAL_TYPES.has(prim(a).type)) return 'heal';
      return isSpell(a) ? 'spell' : 'phys';
    }
    default: return null;
  }
}

// アルゴスが 読む 種類: さいごに 使った 行動の 種類。まだ なければ、職業と 技から いちばん しそうな もの
export function predictKind(c) {
  if (c.lastKind) return c.lastKind;
  const abs = (c.abilities || []).map((id) => ABILITIES[id]).filter(Boolean);
  const attackSpell = abs.some((a) => isSpell(a) && prim(a).type === 'magic' && FOES.has(a.target));
  const healSpell = abs.some((a) => HEAL_TYPES.has(prim(a).type) && prim(a).type === 'heal');
  if (attackSpell && (c.mag || 0) >= (c.atk || 0) * 0.9) return 'spell';
  if (healSpell && (c.healPow || 0) >= (c.atk || 0)) return 'heal';
  return 'phys';
}

// 読める 人（生きている・まだ 読まれていない・もう 行動を きめて ならんで いない・水のろうに いない）
function gazeTargets(b) {
  return b.aliveAllies().filter((x) => !x.foresee && !x.queued && !x.status?.prison);
}
// 今 何人を 同時に 読むか
function gazeCount(m) {
  const conf = confOf(m);
  return conf && m.hp / m.maxHp < (conf.two ?? 0) ? 2 : 1;
}
const readBy = (b, m) => b.allies.filter((x) => x.alive && x.foresee?.by === m.id);

// 魔物の こうどうの じょうけん（ai.js の condOk。'c5:' の あと）
export function towerCond(b, m, cond) {
  const g = gaiaCond(b, m, cond);
  if (g !== null) return g;
  const n = noctoCond(b, m, cond);
  if (n !== null) return n;
  const e = earthCond(b, m, cond);
  if (e !== null) return e;
  const fc = finalCond(b, m, cond);
  if (fc !== null) return fc;
  const ph = phantomCond(b, m, cond);
  if (ph !== null) return ph;
  const c6 = ch6Cond(b, m, cond);
  if (c6 !== null) return c6;
  const ar = arenaCond(b, m, cond);
  if (ar !== null) return ar;
  if (cond === 'gaze') return !!confOf(m) && readBy(b, m).length < gazeCount(m) && gazeTargets(b).length > 0;
  return true;
}

// ───────────── 技の こうか（battle.js の applyAbility の のこり）─────────────
export function towerEffect(b, c, a, eff, ev, targets = []) {
  if (gaiaEffect(b, c, a, eff, ev)) return true;
  if (noctoEffect(b, c, a, eff, ev)) return true;
  if (earthEffect(b, c, a, eff, ev, targets)) return true;
  if (finalEffect(b, c, a, eff, ev, targets)) return true;
  if (phantomEffect(b, c, a, eff, ev, targets)) return true;
  if (ch6Effect(b, c, a, eff, ev, targets)) return true;
  if (arenaEffect(b, c, a, eff, ev, targets)) return true;
  if (phantomAEffect(b, c, a, eff, ev)) return true;
  if (eff.type !== 'foresee') return false;
  foreseeStart(b, c, ev);
  return true;
}

function foreseeStart(b, c, ev) {
  const pool = gazeTargets(b);
  const want = Math.max(0, gazeCount(c) - readBy(b, c).length);
  const picks = [];
  while (picks.length < want && pool.length) {
    const t = b.rng.pick(pool);
    pool.splice(pool.indexOf(t), 1);
    picks.push(t);
  }
  if (!picks.length) {
    ev.lines.push('しかし、だれのことも見通せなかった。');
    return;
  }
  const A = shortName(c);
  for (const t of picks) {
    const kind = predictKind(t);
    t.foresee = { by: c.id, kind };
    ev.lines.push(`${A}の3つの目が、${t.name}をじっと見ている…`, `（${t.name}の次の「${KIND_NAMES[kind]}」が、読まれている…！）`);
    ev.upd.push(t);
  }
  ev.lines.push('（読まれた種類とはちがう行動をすれば、外れるはずだ…！）');
  ev.fx = { type: 'foresee', anim: 'foresee', actor: c.id, targets: picks.map((t) => t.id), kinds: picks.map((t) => t.foresee.kind), side: 'enemy' };
  ev.warn = true;
}

// ───────────── こうどうの はじめ（battle.js の executeNext）─────────────
// 動けない 番（ねむり・マヒ・水のろう）でも 読みは 消える。読んだ アルゴスが もう いなければ 消える
export function towerTurnStart(b, c, ev, cmd) {
  earthTurnStart(b, c, ev);
  finalTurnStart(b, c, ev, cmd);
  phantomTurnStart(b, c, ev, cmd);
  ch6TurnStart(b, c, ev, cmd);
  phantomATurnStart(b, c, ev, cmd);
  if (c.side !== 'ally' || !c.foresee) return;
  const by = b.get(c.foresee.by);
  if (!by?.alive || cmd?.type === 'incapacitated') {
    delete c.foresee;
    if (by?.alive) ev.lines.push(`${shortName(by)}の目が、${c.name}からはなれた。`);
    ev.upd.push(c);
  }
}

// ───────────── 行動の はじめ（battle.js の perform の さいしょ）─────────────
// 読まれた 種類と おなじ 行動なら しかえし（true … この 行動は ここで おわり）。ちがえば 外れ（false … ふつうに つづける）
export function foreseeCheck(b, c, cmd, ev) {
  if (c.side !== 'ally') return false;
  // ノクトの影は 合体技を 見ると 次に きずなくだきの 前ぶれ（battle-nocto.js）
  if (noctoCheck(b, c, cmd)) return true;
  // ソリトゥスも 合体技を 見ると 次に きずなを食べるの 前ぶれ（battle-final.js）
  finalCheck(b, c, cmd);
  const kind = cmd.confused ? null : actKind(cmd);
  const f = c.foresee;
  if (kind) c.lastKind = kind;
  if (!f) return false;
  delete c.foresee;
  ev.upd.push(c);
  const by = b.get(f.by);
  if (!by?.alive || !kind) return false;
  if (kind !== f.kind) {
    foreseeMiss(b, c, by, ev);
    return false;
  }
  return foreseeHit(b, c, cmd, ev, by, kind);
}

// 読みが 外れた: アルゴスの 目が くらむ（こうどうゲージが へる。もう 行動を きめて いる ときは そのまま）
function foreseeMiss(b, c, by, ev) {
  const conf = confOf(by) || {};
  const A = shortName(by);
  (ev.postLines = ev.postLines || []).push(`${A}の読みが外れた！`, `${A}の3つの目が、くらくらしている…！`);
  if (!by.queued && !by.ready) by.atb = Math.max(0, (by.atb || 0) - (conf.daze ?? 20));
  ev.foreseeMiss = { by: by.id, who: c.id };
  ev.upd.push(by);
}

// 読まれた 種類の 行動を そのまま 使った
function foreseeHit(b, c, cmd, ev, by, kind) {
  const conf = confOf(by) || {};
  const A = shortName(by);
  // 何を しようと したか（ふつうの 行動と おなじ はじめの ことば）
  // 使う 人 むけの 技の 名前・セリフ（男の子の 美少女戦士など。ability-label.js）
  const a = cmd.type === 'ability' ? abilityFor(cmd.id, c) : null;
  if (a) {
    // MPが たりない・呪文が ふうじられて いる: ふつうに しっぱい（読みは 消える）
    const cost = mpCost(c.penChar, cmd.id);
    if (cost > c.mp || (isSpell(a) && (c.status.silence || b.noSpells))) return false;
    c.mp -= cost;
    ev.name = a.name;
    ev.ability = cmd.id;
    const t = cmd.target ? b.get(cmd.target) : null;
    ev.lines.push(String(a.cast || `{a}は${a.name}を使った！`).replaceAll('{a}', c.name).replaceAll('{t}', t ? t.name : ''));
  } else if (cmd.type === 'attack' || cmd.type === 'mahouken') {
    ev.name = '攻撃';
    ev.lines.push(`${c.name}の攻撃！`);
  } else if (cmd.type === 'item') {
    const it = ITEMS[cmd.id];
    ev.name = it?.name || '道具';
    ev.lines.push(`${c.name}は${it?.name || '道具'}を使おうとした！`);
  } else {
    ev.name = '防御';
    ev.lines.push(`${c.name}は身を守ろうとした！`);
  }
  ev.fx = { type: 'foreseeHit', anim: 'foresee_hit', actor: c.id, by: by.id, kind, targets: [c.id], side: 'enemy' };
  ev.foreseeHit = { by: by.id, who: c.id, kind };
  ev.warn = true;
  if (kind === 'phys') {
    // かわして 反撃
    ev.lines.push(`しかし${A}は、3つの目で動きを見切っていた！`, `${A}は、ひらりとかわして反撃してきた！`);
    (ev.results = ev.results || []).push({ id: by.id, miss: true });
    const res = b.calcPhys(by, c, { mult: conf.counter ?? 1.3 });
    if (res.miss) {
      ev.lines.push(`${c.name}はひらりと身をかわした！`);
      ev.results.push({ id: c.id, miss: true });
    } else b.damage(by, c, res.dmg, ev, { element: 'phys' });
  } else if (kind === 'spell') {
    const e = a ? prim(a) : {};
    if ((e.type === 'magic' || e.type === 'gather' || e.type === 'deduce') && Array.isArray(e.base) && FOES.has(a.target)) {
      // はね返す（となえた 人に。1回で たおれない ように さいだいHPの cap まで）
      ev.lines.push(`しかし${A}の目が光り、呪文をはね返した！`);
      const k = conf.bounce ?? 0.6;
      const pow = penaltyFor(c.penChar, cmd.id).powMult;
      const res = b.calcMagic(c, c, { ...e, type: 'magic', base: e.base.map((v) => Math.max(1, Math.round(v * k))) }, pow);
      const dmg = Math.min(res.dmg, Math.max(1, Math.round(c.maxHp * (conf.cap ?? 0.32))));
      if (res.resisted || dmg <= 0) ev.lines.push(`${c.name}はダメージを受けない！`);
      else b.damage(c, c, dmg, ev, { element: e.element });
    } else ev.lines.push(`しかし呪文の力は、${A}の目にかき消された！`);
  } else if (kind === 'heal') {
    ev.lines.push(`しかし${A}の目が光り、回復の光をすいこんでしまった！`);
  } else {
    // 防御: 身を 守れず、守りが 下がる
    c.defending = false;
    ev.lines.push(`しかし${A}は、守りのすきを見ぬいていた！`);
    b.applyDebuff(by, c, { stat: 'def', mult: 0.75, chance: 1 }, ev);
  }
  ev.upd.push(c, by);
  return true;
}

// たおれた（battle.js の kill）: アルゴスが たおれると、読みも みんな 消える
export function towerKill(b, t, ev) {
  gaiaKill(b, t, ev);
  noctoKill(b, t, ev);
  earthKill(b, t, ev);
  finalKill(b, t, ev);
  tokei6Kill(b, t, ev);
  c7Kill(b, t, ev);
  if (t.side !== 'enemy' || !confOf(t)) return;
  for (const x of b.allies) {
    if (x.foresee?.by !== t.id) continue;
    delete x.foresee;
    if (ev) ev.upd.push(x);
  }
}

// ───────────── オートの 仲間・シミュレーター（ai.js の decideAlly の はじめ）─────────────
// 知っている 人（b.knowsArgos）は 星のさばきの 前に 身を 守る。読まれて いれば、読まれた 種類を さけて えらぶ
// （b.argosNaive … 知らない 人。読まれても そのまま）。decide … ai.js の decideAlly（さけた あとの えらびなおしに 使う）
export function towerPlan(b, c, decide) {
  if (c.side !== 'ally') return null;
  // ガイアイーター（知っている 人: しっぽ → 体 → 頭・大技の 前に 身を 守る。battle-gaia.js）
  const gp = gaiaPlan(b, c, decide);
  if (gp) return gp;
  // ノクトの影（知っている 人: きずなくだきの 前に 身を 守る・まねられた 人は 攻撃しない。battle-nocto.js）
  const np = noctoPlan(b, c, decide);
  if (np) return np;
  // ノクト（1回目。知っている 人: 影を 先に たおす・前ぶれで 身を 守る・手を のばす。battle-earth.js）
  const ep = earthPlan(b, c);
  if (ep) return ep;
  // 魔王ソリトゥス（だれでも: きずな技の ゲージが たまったら 使う。知っている 人: よびかける・前ぶれで 身を 守る。battle-final.js）
  const flp = finalPlan(b, c);
  if (flp) return flp;
  // 影の城の まぼろし（知っている 人: 大技の 前に 身を 守る・風のかべには 呪文・かげ火を 先に。battle-phantom.js）
  const pp = phantomPlan(b, c, decide);
  if (pp) return pp;
  // 第6章の ボス（知っている 人: 大砂流の 前ぶれに 氷・まき戻しの 間に 雷・ギアプレスの 前に 身を 守る。battle-ch6.js）
  const c6p = ch6Plan(b, c, decide);
  if (c6p) return c6p;
  if (b.knowsArgos && c.foresee?.kind !== 'guard') {
    const mine = 100 / atbRate(c);
    const j = b.aliveEnemies().find((e) => e.telegraph === JUDGE);
    if (j && (100 - j.atb) / atbRate(j) <= mine) return { type: 'defend' };
  }
  if (!c.foresee || b.argosNaive || b.fsInner) return null;
  let cmd;
  b.fsInner = true;
  try {
    cmd = decide(b, c);
  } finally {
    b.fsInner = false;
  }
  if (actKind(cmd) !== c.foresee.kind) return cmd;
  return dodgeCmd(b, c, c.foresee.kind);
}

// 読まれた 種類（kind）を さけた 行動: 攻撃・呪文・回復の うち いちばん よい もの。なければ 防御（防御を 読まれたら 攻撃）
export function dodgeCmd(b, c, kind) {
  const foes = b.aliveEnemies();
  const boss = foes.find((f) => f.boss) || foes.slice().sort((x, y) => y.hp - x.hp)[0];
  if (!boss) return { type: 'defend' };
  const opts = [];
  if (kind !== 'phys') {
    const r = b.calcPhys(c, boss, { mult: 1 }, 1, 'phys', true);
    opts.push({ cmd: { type: 'attack', target: boss.id }, score: r.dmg * r.hit });
  }
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const k = actKind({ type: 'ability', id });
    if (k === kind) continue;
    const e = prim(a);
    const pow = penaltyFor(c.penChar, id).powMult;
    if (k === 'spell' && e.type === 'magic' && FOES.has(a.target)) {
      const n = a.target === 'enemies' ? foes.length : a.target === 'group' ? foes.filter((f) => f.species === boss.species).length : 1;
      opts.push({ cmd: { type: 'ability', id, target: boss.id }, score: b.calcMagic(c, boss, e, pow, true).dmg * Math.min(n, 2) / (1 + mpCost(c.penChar, id) * 0.02) });
    }
    if (k === 'heal' && e.type === 'heal') {
      const hurt = b.aliveAllies().filter((x) => x.hp / x.maxHp < 0.5).sort((x, y) => x.hp / x.maxHp - y.hp / y.maxHp);
      if (!hurt.length) continue;
      if (a.target === 'ally') opts.push({ cmd: { type: 'ability', id, target: hurt[0].id }, score: 9999 - mpCost(c.penChar, id) });
      else if (a.target === 'allies' && hurt.length >= 2) opts.push({ cmd: { type: 'ability', id }, score: 9998 });
    }
  }
  opts.sort((x, y) => y.score - x.score);
  if (opts[0] && opts[0].score > 0) return opts[0].cmd;
  return kind === 'guard' ? { type: 'attack', target: boss.id } : { type: 'defend' };
}

// ───────────── がめんへ ─────────────
// pub（battle.js）に まぜる: 読まれている 種類（味方だけ）
export function towerPub(c) {
  return c.side === 'ally' ? { foresee: c.foresee?.kind || null, ...noctoPub(c), ...earthPub(c), ...finalPub(c) } : { ...gaiaPub(c), ...noctoPub(c), ...earthPub(c), ...finalPub(c), ...phantomPub(c), ...ch6Pub(c) };
}

js/shared/battle-ch6.js:
// 第2部 第6章 Step 1・2 の ボスの たたかいの しかけ（battle.js・battle-ch5.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・サンドクロック（monsters-past.js の ch6.kind 'sand'。時のほこらの いちばん 下）「砂が落ちきると…」
//   体の 中の 砂（sand.max）が、サンドクロックが 1回 動く たびに 1つ 落ちる（がめんに 砂の 目もり）。
//   砂が 0 に なると、その 番に かならず 前ぶれ「最後の砂」→ 次の 番に「大砂流」（みんなに 物理の 大技。身を 守ると 半分）。
//   大砂流の あとは 砂時計が ひっくり返って、砂は また いっぱい。
//   しかえし: 氷の 攻撃（呪文・特技・合体技。1回の 行動で 1回）を 当てると、砂が こおって sand.ice 上に もどる（落ちるのを おくらせる）。
//             前ぶれの 間に 氷を 当てると、こおった 砂が つまって 大砂流は 止まる（砂は sand.stopTo）
//   HPが sand.fastAt より へると、砂の いっぱいが sand.fast に（はやく 落ちきる）
// ・ギアドン（ch6.kind 'gear'。時のいせきの 番人の間）「まきもどし」
//   gear.every 回 動くと、かならず「時を覚える」（今の HPを おぼえる）。そこから gear.wind 回 動くと「まきもどし」で、
//   HPが おぼえた ときまで もどる（その 間に あたえた キズが なくなる）。
//   しかえし: 覚えてから まきもどすまでの 間に、雷の 攻撃を gear.need 回（1回の 行動で 1回）当てると、むねの 大歯車が こわれて
//             まきもどしは 止まる。ギアドンは よろめいて（ゲージが 0 から・ならんでいた 行動も とりやめ）、守りが gear.cut ばいに（3回 行動の 間）
//   HPが gear.fastAt より へると、時を おぼえるのが gear.fastEvery 回ごとに。ほかに 大歯車を かかげる → ギアプレス（ふつうの 前ぶれの 大技）
// ・オートの 仲間（ふつう）は、大砂流・ギアプレスが 自分の 番より 先に 来る とき、HPが へっていれば よく 身を 守る（AUTO_GUARD。氷・雷は 使い分けない）。
//   シミュレーター（tools/sim-ch6.mjs）の 知っている 人（b.knowsCh6）は ch6Plan
//   （b.c6NoIce・b.c6NoBolt・b.c6NoGuard … 知っている 人の しかけを 1つずつ はずして くらべる とき）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { SAND_CLOCK, GEARDON } from './data/monsters-past.js';
import { BUFF_ACTS } from './buff-acts.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';
// 第2部 第6章 Step 3・4: 星くいのよる鳥（星くい）・ペンデュラ（時のふりこ）・星座の 魔物（昼と 夜）。battle-road.js
import { setupRoad, roadTurnStart, roadEffect, roadDamage, roadKnow, roadPub, ROAD_BIG } from './battle-road.js';
// 第2部 第6章 Step 5: カリヨン（時のかね。知っている 人・かねの 前の 守り）。battle-tokei.js
import { tokeiKnow, bellBefore } from './battle-tokei.js';
// 第2部 第6章 Step 6: ゼンマイ（家来の しかけを じゅんばんに・2だんめの 針と 歯車）。battle-tokei6.js
import { setupTokei6, tokei6TurnStart, tokei6TurnEnd, tokei6Effect, tokei6Know, tokei6Pub, collapseBefore } from './battle-tokei6.js';
// 第2部 第7章 第1幕: ウツボきょうだい（2ひきで 1組・大うずしお）・オクタリア（声うばい・声の貝）。battle-c7.js
import { setupC7, c7TurnStart, c7Effect, c7Plan, c7Pub, c7Damage } from './battle-c7.js';

export { SAND_CLOCK, GEARDON };
export const FALL = 'm6_sc_fall';
export const FALL_CHARGE = 'm6_sc_fall_charge';
export const RECORD = 'm6_gd_record';
export const REWIND = 'm6_gd_rewind';
export const PRESS = 'm6_gd_press';
// ふつうの オートが 大技の 前に 身を 守る（HPが この わりあいより 少ない とき・この たしかさで。影の城の まぼろしと おなじ）
export const AUTO_GUARD = { hp: 0.8, chance: 0.6 };
const BIG = new Set([FALL, PRESS, ...ROAD_BIG]);
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});

// c6 … その 戦いだけの しかけの 数（ゼンマイは 今の しかけ だけ。battle-tokei6.js）
const confOf = (m) => m?.c6 || MONSTERS[m?.species]?.ch6 || null;
const sandConf = (m) => confOf(m)?.sand || null;
const gearConf = (m) => confOf(m)?.gear || null;

// ───────────── はじめ（battle.js の constructor）─────────────
const INTRO = {
  sand: ['サンドクロックの体の中で、砂がさらさらと落ち始めた…！', '（砂が落ちきると、何かが起こりそうだ…！）'],
  gear: ['ギアドンのむねの大歯車が、ギリギリと回っている…！', '（あの歯車、雷に弱そうだ…）'],
};
export function setupCh6(b) {
  const kinds = new Set();
  for (const e of b.enemies) {
    const sc = sandConf(e), gc = gearConf(e);
    if (sc) e.sand = { lv: sc.max ?? 6, max: sc.max ?? 6, fast: false };
    if (gc) e.gear = { count: 0, rec: null, left: 0, hits: 0, fast: false };
    if (sc || gc) kinds.add(confOf(e).kind);
  }
  for (const k of kinds) if (INTRO[k]) b.emit({ t: 'msg', lines: INTRO[k].slice(), dur: 1300 });
  setupRoad(b);
  setupTokei6(b);
  setupC7(b);
}

// ───────────── 魔物の こうどうの じょうけん（battle-ch5.js の towerCond から。'c5:' の あと）─────────────
//   scEmpty … 砂が 落ちきった（前ぶれで ない。ふだんは ch6TurnStart が 前ぶれを 出す）/ gdIdle … まきもどしの 間でも 前ぶれでも ない
export function ch6Cond(b, m, cond) {
  if (cond === 'scEmpty') return !!m.sand && m.sand.lv <= 0 && !m.telegraph;
  if (cond === 'gdIdle') return !m.gear?.rec && !m.telegraph;
  return null;
}

// ───────────── 行動の はじめ（battle-ch5.js の towerTurnStart から）─────────────
// 砂が 落ちる・まきもどしまでの 数・時を おぼえる 数（動けない 番も 数える。前ぶれの 番は 数えない）
export function ch6TurnStart(b, c, ev, cmd = null) {
  if (c.side !== 'enemy' || !c.alive) return;
  const stuck = cmd?.type === 'incapacitated';
  // ゼンマイ: しかけが おわったら 次の しかけへ・2だんめの 針（battle-tokei6.js）
  tokei6TurnStart(b, c, ev, stuck);
  // 第7章の ボス: いきの しるし・よびもどし・声うばい（battle-c7.js）
  c7TurnStart(b, c, ev, stuck);
  if (c.sand && !c.telegraph) {
    const sc = sandConf(c) || {};
    // HPが へると、砂の いっぱいが へる（はやく 落ちきる）
    if (!c.sand.fast && sc.fast && c.hp / c.maxHp < (sc.fastAt ?? 0.5)) {
      c.sand.fast = true;
      c.sand.max = sc.fast;
      c.sand.lv = Math.min(c.sand.lv, c.sand.max);
      ev.lines.push(`${c.name}のガラスの首が、広がった…！`, '（砂の落ちるのが、はやくなった！）');
    }
    if (c.sand.lv > 0) {
      c.sand.lv--;
      const { lv, max } = c.sand;
      ev.lines.push(lv > 0 ? `${c.name}の砂が、さらさらと落ちていく…（砂${lv}/${max}）` : `${c.name}の砂が、落ちきった…！（砂0/${max}）`);
      if (lv === 1) ev.lines.push('（あと1つで、砂が落ちきる…！氷でこおらせれば、もどせるかも…！）');
      ev.scSand = { id: c.id, lv, max };
    }
    // 砂が 落ちきった: この 番は かならず 前ぶれ（ai.js の decideMonster が telegraph を 出す。動けない 番は 次の 番に）
    if (c.sand.lv <= 0 && !stuck) c.telegraph = FALL_CHARGE;
    ev.upd.push(c);
  }
  if (c.gear && !c.telegraph) {
    const gc = gearConf(c) || {};
    if (!c.gear.fast && gc.fastEvery && c.hp / c.maxHp < (gc.fastAt ?? 0.4)) c.gear.fast = true;
    if (c.gear.rec !== null) {
      c.gear.left--;
      if (c.gear.left <= 0) {
        if (!stuck) c.telegraph = REWIND;
      } else ev.lines.push(`${c.name}のぜんまいが、ギリギリとまかれていく…（まきもどしまで、あと${c.gear.left}）`);
      ev.gdWind = { id: c.id, left: Math.max(0, c.gear.left) };
    } else {
      c.gear.count++;
      const every = c.gear.fast ? gc.fastEvery : (gc.every ?? 4);
      if (c.gear.count >= every && !stuck) c.telegraph = RECORD;
    }
    ev.upd.push(c);
  }
  roadTurnStart(b, c, ev, cmd);
  tokei6TurnEnd(b, c);
}

// ───────────── 技の こうか（battle-ch5.js の towerEffect から）─────────────
export function ch6Effect(b, c, a, eff, ev, targets = []) {
  switch (eff.type) {
    case 'scFall': sandFall(b, c, eff, ev); return true;
    case 'gdRecord': record(b, c, ev); return true;
    case 'gdRewind': rewind(b, c, ev); return true;
    default: return roadEffect(b, c, a, eff, ev, targets) || tokei6Effect(b, c, a, eff, ev) || c7Effect(b, c, a, eff, ev);
  }
}

// 大砂流（みんなに 物理の 大技。身を 守ると 半分）。おわると 砂時計が ひっくり返って 砂は いっぱい
function sandFall(b, c, eff, ev) {
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a6_fall', actor: c.id, targets: targets.map((t) => t.id), side: 'enemy' };
  for (const t of targets) {
    b.physHit(c, t, { mult: eff.mult ?? 1.5, ignoreDef: eff.ignoreDef ?? 0.4, acc: 1.2 }, ev, 'phys');
    if (eff.debuff && t.alive) b.applyDebuff(c, t, eff.debuff, ev);
  }
  if (c.sand) {
    c.sand.lv = c.sand.max;
    (ev.postLines = ev.postLines || []).push(`${c.name}は、くるりとひっくり返った！`, `（砂がまた、いっぱいになった…　砂${c.sand.lv}/${c.sand.max}）`);
  }
  ev.scFall = c.id;
  ev.warn = true;
  ev.upd.push(c);
}

// 時を覚える（今の HP）
function record(b, c, ev) {
  const gc = gearConf(c) || {};
  if (!c.gear) return;
  Object.assign(c.gear, { rec: c.hp, left: gc.wind ?? 3, hits: 0, count: 0 });
  const need = gc.need ?? 2;
  ev.lines.push(`（${c.name}は、今の体を時の中に覚えた…！）`, `（雷の攻撃を${need}回当てれば、歯車を止められそうだ…！）`);
  ev.fx = { type: 'ability', anim: 'a6_record', actor: c.id, targets: [c.id], side: 'enemy' };
  ev.gdRecord = { id: c.id, need };
  ev.warn = true;
  ev.upd.push(c);
}

// まきもどし: HPが おぼえた ときまで もどる（弱く なる 力も 消える）
function rewind(b, c, ev) {
  if (!c.gear) return;
  const rec = c.gear.rec;
  Object.assign(c.gear, { rec: null, left: 0, hits: 0, count: 0 });
  ev.fx = { type: 'ability', anim: 'a6_rewind_big', actor: c.id, targets: [c.id], side: 'enemy' };
  if (rec === null) {
    ev.lines.push('しかし、何も起こらなかった。');
    return;
  }
  const heal = Math.max(0, Math.min(c.maxHp, rec) - c.hp);
  c.hp += heal;
  c.debuffs = {};
  ev.lines.push(heal > 0 ? `時がまきもどって、${c.name}のキズが${heal}もとにもどった！` : `時がまきもどった！…しかし、${c.name}のキズは、ふえていなかった。`);
  (ev.results = ev.results || []).push({ id: c.id, heal });
  ev.gdRewind = { id: c.id, heal };
  ev.warn = true;
  ev.upd.push(c);
}

// ───────────── ダメージ（battle.js の damage。phantomDamage の あと）─────────────
// 氷で 砂が こおる・雷で 大歯車が こわれる（どちらも 1回の 行動で 1回）。ダメージは そのまま
export function ch6Damage(b, c, t, dmg, info, ev) {
  if (!c || dmg <= 0 || t.side !== 'enemy' || c.side !== 'ally' || !t.alive) return dmg;
  if (t.sand && info.element === 'ice' && !ev.scIce) {
    const sc = sandConf(t) || {};
    const post = (ev.postLines = ev.postLines || []);
    ev.scIce = true;
    if (t.telegraph === FALL) {
      t.telegraph = null;
      t.sand.lv = Math.max(t.sand.lv, Math.min(t.sand.max, sc.stopTo ?? 2));
      post.push('こおった砂が、ガラスの首につまった！', `大砂流は、止まった！（砂${t.sand.lv}/${t.sand.max}）`);
      ev.scStop = t.id;
    } else if (t.sand.lv < t.sand.max && (sc.ice ?? 1) > 0) {
      // ice: 0 … 氷で もどらない（ゼンマイ。前ぶれの 間に 当てて 止める だけ）
      t.sand.lv = Math.min(t.sand.max, t.sand.lv + (sc.ice ?? 1));
      post.push(`氷で砂がこおって、上にもどった！（砂${t.sand.lv}/${t.sand.max}）`);
      ev.scBack = { id: t.id, lv: t.sand.lv };
    }
    ev.upd.push(t);
  }
  if (t.gear?.rec !== null && t.gear?.rec !== undefined && info.element === 'bolt' && !ev.gdBolt) {
    const gc = gearConf(t) || {};
    const post = (ev.postLines = ev.postLines || []);
    ev.gdBolt = true;
    t.gear.hits++;
    const need = gc.need ?? 2;
    if (t.gear.hits >= need) {
      Object.assign(t.gear, { rec: null, left: 0, hits: 0, count: 0 });
      // よろめく: ならんでいた 行動は とりやめ・ゲージは 0 から・守りが 下がる（3回 行動の 間）
      if (t.queued) {
        b.queue = b.queue.filter((q) => q.id !== t.id);
        t.queued = false;
      }
      t.ready = false;
      t.atb = 0;
      t.debuffs.def = { mult: gc.cut ?? 0.75, lv: 1, left: BUFF_ACTS };
      post.push('雷で、むねの大歯車がショートした！', '大歯車がくだけて、まきもどしは止まった！', `${t.name}は、ぐらりとよろめいた！（守りが下がった）`);
      ev.gdBreak = t.id;
    } else {
      post.push(`雷で、大歯車に火花がちった！（あと${need - t.gear.hits}回）`);
      ev.gdSpark = { id: t.id, left: need - t.gear.hits };
    }
    ev.upd.push(t);
  }
  // 第2部 第7章 第2幕: のり上げた 船は ダメージが ふえる（battle-c7.js → battle-c7s.js）
  return c7Damage(b, c, t, roadDamage(b, c, t, dmg, info, ev), info, ev);
}

// ───────────── 知っている 人の オート（battle-ch5.js の towerPlan から。b.knowsCh6）─────────────
// サンドクロック … 大砂流の 前ぶれ: 氷の 技が あれば 氷（止める）・なければ 身を 守る / 砂が のこり 2つ いかなら 氷で もどす
// ギアドン … 時を 覚えている 間は 雷の 技（大歯車を こわす）/ ギアプレスが 自分の 番より 先に 来る ときは 身を 守る
// （だれかが とても あぶない ときの 回復・生き返りは そのまま）
export function ch6Plan(b, c, decide) {
  if (c.side !== 'ally' || b.c6Inner) return null;
  // 第7章の ボス（ウツボきょうだい・オクタリア。battle-c7.js）
  const c7p = c7Plan(b, c, decide);
  if (c7p) return c7p;
  const boss = b.aliveEnemies().find((e) => confOf(e));
  if (!boss) return null;
  const mine = 100 / atbRate(c);
  // ふつうの オート（家族が「オート」に した とき）も、大砂流・ギアプレスが 自分の 番より 先に 来る ときは、HPが へっていれば よく 身を 守る
  //   （b.c6Naive … シミュレーターで これも しない 人）
  if (!b.knowsCh6) {
    // カリヨンの 時のかねは 前ぶれで なく、かねの しるしで 分かる（battle-tokei.js の bellBefore）
    // ゼンマイの 2だんめは 文字ばんの 針で 分かる（battle-tokei6.js の collapseBefore）
    const soon = boss.zen?.phase === 2 ? collapseBefore(b, c, boss) : boss.bell ? bellBefore(b, c, boss) : BIG.has(boss.telegraph) && (100 - boss.atb) / atbRate(boss) <= mine;
    if (b.c6Naive || !soon) return null;
    return c.hp / c.maxHp < AUTO_GUARD.hp && b.rng.chance(AUTO_GUARD.chance) ? { type: 'defend' } : null;
  }
  let base;
  b.c6Inner = true;
  try {
    base = decide(b, c);
  } finally {
    b.c6Inner = false;
  }
  const a = base?.type === 'ability' ? ABILITIES[base.id] : null;
  const saving = a && ['heal', 'revive', 'reviveAll'].includes(prim(a).type) && b.allies.some((x) => !x.fled && (!x.alive || x.hp / x.maxHp < 0.35));
  if (saving) return base;
  // ゼンマイの 2だんめ（1だんめは 下の 家来と おなじ）
  if (boss.zen?.phase === 2) return tokei6Know(b, c, boss, base);
  if (boss.stars || boss.pend) return roadKnow(b, c, boss, base, { elemHit });
  if (boss.bell) return tokeiKnow(b, c, boss, base);
  if (boss.sand) {
    if (boss.telegraph === FALL) {
      const ice = b.c6NoIce ? null : elemHit(b, c, boss, 'ice');
      if (ice) return ice;
      if (!b.c6NoGuard) return { type: 'defend' };
    }
    if (!b.c6NoIce && boss.sand.lv <= 1 && (sandConf(boss)?.ice ?? 1) > 0) {
      const ice = elemHit(b, c, boss, 'ice');
      if (ice) return ice;
    }
  }
  if (boss.gear) {
    if (boss.telegraph === PRESS && !b.c6NoGuard && (100 - boss.atb) / atbRate(boss) <= mine) return { type: 'defend' };
    if (boss.gear.rec !== null && !b.c6NoBolt) {
      const bolt = elemHit(b, c, boss, 'bolt');
      if (bolt) return bolt;
    }
  }
  return base;
}

// その 属性の 技で いちばん ダメージの 大きい もの（なければ null）
export function elemHit(b, c, t, el) {
  let best = null;
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    if (e.element !== el) continue;
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, el, true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (!best || dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best?.cmd || null;
}

// ───────────── がめんへ（battle.js の pub。battle-ch5.js の towerPub から）─────────────
// 敵: 砂（sand・sandMax）・まきもどし（gearRec … 覚えている・gearLeft … まきもどしまで・gearHits … 当てた 雷・gearNeed）
export function ch6Pub(c) {
  if (c.side !== 'enemy') return {};
  const o = roadPub(c);
  tokei6Pub(c, o);
  c7Pub(c, o);
  if (c.sand) {
    o.sand = c.sand.lv;
    o.sandMax = c.sand.max;
  }
  if (c.gear) {
    o.gearRec = c.gear.rec !== null ? 1 : 0;
    o.gearLeft = c.gear.left;
    o.gearHits = c.gear.hits;
    o.gearNeed = gearConf(c)?.need ?? 2;
  }
  return o;
}

js/shared/battle-dual.js:
// 合体技の しくみ（2人・3人・4人。battle.js の Battle から よぶ）
//
// ・出す 人（c）が 合体技を えらぶ → 仲間 みんなの ゲージが たまって いれば すぐ、まだ なら「よやく」（c.waitDual）
// ・よやく中は、仲間の ゲージが たまった しゅんかんに たしかめる。
//   ほかの 仲間が まだ なら、その 仲間は ゲージが たまった まま まつ（p.dualHold。AI・オート・自分が 動かす 仲間）。
//   家族（ほかの 人が 動かす キャラ）は まつのを おしつけない（ふつうに 番が 来て、コマンドを えらんでいる あいだは「今」）
// ・みんな そろったら、家族には「参加する？」と 聞く（2人技と おなじ。何人でも、1人でも ことわれば 出ない）
// ・よやくで ゲージが たまって まっている 人（よやくした 人・先に たまって まつ 仲間）が ダメージを 受けると、
//   その 人の ゲージは 半分から やり直し（よやくは つづく。ゲージが まだ たまって いない 人は かわらない。dualHurt）
// ・強さ: 出す 人が それぞれ、その 組の 技（か ふつうの 攻撃）を 出した ときの ダメージの 合計 × DUAL_POWER[人数] × k
//   （この 敵に 当てた ときの 見つもり。守り・弱点・バフも 入る。属性は 合体技の 属性で かかる）
// 第50回 D4: 合体技の 補助の だんかい・回数（skill-tier.js）
import { tierMods, DUAL_TIER, SUPPORT_TYPES } from './skill-tier.js';
import { ABILITIES, ELEMENT_NAMES } from './data/abilities.js';
import { DUAL_TECHS, dualOptions, partnerNow } from './data/dual.js';
import { weaponOk, comboAllowed, penaltyFor } from './stats.js';
// 第27回: 推理（敵 それぞれの いちばんの 弱点の 属性で 当てる）の 合体技
import { deduceElement } from './data/abilities-jobs6.js';
import { MONSTERS } from './data/monsters.js';
// 第33回: 男の子の 美少女戦士が 出す ときは 合体技の 名前・セリフが かわる（ability-label.js の dualFor）
import { dualFor } from './ability-label.js';

// 人数ごとの 強さ（別々に 1回ずつ 動いた ときの 合計の 何倍か。全体技は parts の k で 下げる）
// 第55回: マルチプレイで 弱すぎると 家族の 声。2人分の 番と まつ 時間に 見あう ように 上げた（前は 1.8・2.2・3.0）
export const DUAL_POWER = { 2: 2.4, 3: 3.0, 4: 4.0 };
// 第31回: ボスが 1回で たおれすぎない ように、ボスへの 1回の ダメージは さいだいHPの この わりあいまで（人数ごと。技の bossCap で うわがき）。
// ミナデインは 0.35（いちばん 強い）。超級職の 4人などで ないと とどかない（tools/sim-dual.mjs minadein）
export const DUAL_BOSS_CAP = { 2: 0.25, 3: 0.3, 4: 0.35 }; // 第55回: 前は 0.2・0.25・0.3
// 合体技に さそわれた 家族が こたえるまで まつ 時間（ミリびょう）
export const DUAL_ASK_MS = 7000;
// 動けない じょうたい（合体技に 入れない）
const OUT = ['sleep', 'paralyze', 'confuse', 'prison', 'rift'];
const cantJoin = (p) => !p || !p.alive || p.fled || OUT.some((s) => p.status?.[s]);

export const partnersOf = (cmd) => (cmd?.partners?.length ? cmd.partners : cmd?.partner ? [cmd.partner] : []);
const sameTeam = (o, ids) => o.partners.length === ids.length && ids.every((id) => o.partners.includes(id));
// 家族（ほかの 人が 動かしている キャラ）なので 聞く ひつようが ある
const needsAsk = (c, p) => !!p.controller && !p.auto && p.controller !== c.controller;
const nowOf = (p) => partnerNow({ queued: p.queued, hold: p.dualHold, ready: p.ready, atb: p.atb });

// c が 今 出せる 合体技（exec: 出す しゅんかんの たしかめ。よやくした 相手も かぞえる）
// anyGauge: 仲間の ゲージが まだでも よやく できる ものも かぞえる
export function optionsFor(b, c, others = null, exec = false, anyGauge = false) {
  // 第32回: モンスターの 仲間も 入れる（モンスターの 仲間の 組が ある 技だけ。data/dual.js の fitsGroup）
  if (!c || c.side !== 'ally') return [];
  const list = (others || b.allies.filter((x) => x !== c)).filter((x) => x && x.side === 'ally');
  const info = (x) => ({
    id: x.id, name: x.name, job: x.job, mon: x.mon, alive: x.alive, abilities: x.abilities || [], mp: x.mp, atb: x.atb, ready: x.ready, hold: !!x.dualHold,
    queued: exec && x.dualWith === c.id ? false : !!x.queued,
    // ほかの 人の 合体技に 入る ことに なっている
    busy: !!x.dualWith && x.dualWith !== c.id,
    inviting: !exec && x !== c && !!(x.inviting || x.invited),
    // ほかの 人の 合体技を まっている・まって もらって いる
    waiting: x !== c && (!!x.waitDual || (!!x.dualTarget && x.dualTarget !== c.id)),
    // 呪文が ふうじられた 場所では、呪文の 合体技は 出せない（マホトーンと おなじ）。水のろうの 中も 出られない
    statuses: [...Object.keys(x.status || {}), ...(x.status?.prison || x.status?.rift ? ['paralyze'] : []), ...(b.noSpells ? ['silence'] : [])], weaponCat: x.weaponCat,
    usable: (id) => {
      const a = ABILITIES[id];
      return !!a && (a.kind !== 'combo' || comboAllowed(x.penChar, id)) && weaponOk(a, x.weaponCat);
    },
  });
  return dualOptions(info(c), list.map(info), weaponOk, { anyGauge });
}

// その 仲間と その 技が 出せるか（出せる ものを かえす）
export function findOpt(b, c, id, ids, exec = false, anyGauge = false) {
  const ps = ids.map((x) => b.get(x));
  if (ps.some((p) => !p)) return null;
  return optionsFor(b, c, ps, exec, anyGauge).find((o) => o.id === id && sameTeam(o, ids)) || null;
}

// コマンドの たしかめ（battle.js の validate）
export function validateDual(b, c, cmd) {
  const ids = partnersOf(cmd);
  if (!ids.length || new Set(ids).size !== ids.length) return { ok: false, reason: '合体技は出せない' };
  return findOpt(b, c, cmd.id, ids, false, true) ? { ok: true } : { ok: false, reason: '合体技は出せない' };
}

// ほかの 仲間を まつ（ゲージは たまった まま。番は 合体技に 使う）
function hold(b, c, p) {
  p.dualTarget = c.id;
  if (p.dualHold) return;
  p.dualHold = true;
  p.atb = 100;
  p.ready = false;
  b.emit({ t: 'dualHold', id: p.id, by: c.id });
}

// まつのを やめる（ゲージは たまって いるので、すぐ 自分の 番）
function unhold(b, p) {
  if (!p.dualHold) return;
  p.dualHold = false;
  if (p.alive && !p.fled && !p.queued) {
    p.atb = 100;
    b.onReady(p);
  }
}

// 合体技を はじめる（家族が いれば さそう。AI・自分の 仲間なら すぐ）
// 仲間の ゲージが まだ たまって いなければ「よやく」して まつ（みんな たまった ときに 出す）
export function startDual(b, c, cmd) {
  const ids = partnersOf(cmd);
  const ps = ids.map((id) => b.get(id));
  if (!ps.length || ps.some((p) => !p)) return { ok: false, reason: 'no' };
  if (!ps.every(nowOf)) return waitForPartners(b, c, cmd);
  const ask = ps.filter((p) => needsAsk(c, p));
  if (!ask.length) {
    reserveDual(b, c, ps, cmd);
    return { ok: true };
  }
  // 家族の 返事を まつ あいだ、ほかの 仲間は ゲージが たまった まま まつ
  for (const p of ps) if (!ask.includes(p)) hold(b, c, p);
  const inv = {
    id: 'd' + (++b.inviteSeq), from: c.id, to: ask[0].id, asks: ask.map((p) => p.id), pending: new Set(ask.map((p) => p.id)),
    partners: ids, tech: cmd.id, target: cmd.target, remaining: DUAL_ASK_MS,
  };
  b.invites.set(inv.id, inv);
  c.inviting = inv.id;
  const names = [c.name, ...ps.map((p) => p.name)];
  for (const p of ask) {
    p.invited = inv.id;
    b.emit({ t: 'dualInvite', invite: inv.id, from: c.id, to: p.id, tech: cmd.id, fromName: c.name, toName: p.name, partners: ids, names, ms: DUAL_ASK_MS });
  }
  return { ok: true, pending: true };
}

// よやく: 自分の 番を とっておき、仲間 みんなの ゲージが たまったら いっしょに 出す
function waitForPartners(b, c, cmd) {
  const ids = partnersOf(cmd);
  const ps = ids.map((id) => b.get(id));
  c.ready = false;
  c.waitDual = { id: cmd.id, partner: ids[0], partners: ids, target: cmd.target };
  for (const p of ps) p.dualTarget = c.id;
  // もう 番が 来ている 仲間（AI・オート・自分が 動かす 仲間）は、ほかの 仲間を まつ
  for (const p of ps) if (p.ready && !p.queued && !needsAsk(c, p)) hold(b, c, p);
  const t = dualFor(cmd.id, [c, ...ps]);
  b.emit({ t: 'dualWait', id: c.id, partner: ids[0], partners: ids, tech: cmd.id, lines: [`${c.name}は${ps.map((p) => p.name).join('・')}と「${t?.name || '合体技'}」を出すため、力をためている！`] });
  return { ok: true, waiting: true };
}

// まっている 人を しらべる（仲間が 出られなく なった・出せなく なった・みんなの 番が 来ている）
export function checkWaits(b) {
  for (const c of b.allies) {
    const w = c.waitDual;
    if (!w) continue;
    const ps = w.partners.map((id) => b.get(id));
    if (!waitStillOk(b, c, ps)) continue;
    // 番が 来ている 自分の 仲間・AIは まつ
    for (const p of ps) if (p.ready && !p.queued && !p.dualHold && !needsAsk(c, p)) hold(b, c, p);
    // みんなの 番が 来ている（家族は コマンドを えらんでいる あいだ）。自分の ゲージが みだれて ためなおしている 間は まつ
    if (!w.slow && ps.every((p) => p.dualHold || (p.ready && !p.queued))) fire(b, c);
  }
}

// よやくが まだ 出せるか（だめなら よやくを 終わりに して false）
export function waitStillOk(b, c, ps) {
  if (!c.alive) {
    endWait(b, c, null, false);
    return false;
  }
  const bad = ps.find(cantJoin);
  if (bad !== undefined) {
    endWait(b, c, `${bad?.name || '仲間'}は合体技に参加できなくなった…`);
    return false;
  }
  if (!findOpt(b, c, c.waitDual.id, c.waitDual.partners, true, true)) {
    endWait(b, c, '合体技は出せなくなった…');
    return false;
  }
  return true;
}

// よやくした 合体技を 出す
function fire(b, c) {
  const w = c.waitDual;
  c.waitDual = null;
  for (const id of w.partners) {
    const p = b.get(id);
    if (p && p.dualTarget === c.id && !p.dualHold) p.dualTarget = null;
  }
  c.ready = true;
  return startDual(b, c, { type: 'dual', id: w.id, partner: w.partner, partners: w.partners, target: w.target });
}

// 仲間 p の ゲージが たまった（p.dualTarget の c が まっている）。p の 番を 合体技に 使ったら true
export function fireWait(b, c, p) {
  const w = c?.waitDual;
  if (!w || !w.partners.includes(p.id)) return false;
  const ps = w.partners.map((id) => b.get(id));
  if (!waitStillOk(b, c, ps)) return false;
  const others = ps.filter((x) => x !== p);
  if (!w.slow && others.every((x) => x.dualHold || (x.ready && !x.queued))) {
    const r = fire(b, c);
    // 家族に「参加する？」と 聞いている ときは、家族の 番は ふつうに 来る（参加すると その 番を 使う）。ほかの 仲間は まつ
    return !!r?.ok && ((!r.pending && !r.waiting) || !!p.dualHold);
  }
  // まだ そろって いない: ほかの 仲間を まつ（家族は まつのを おしつけない）
  if (!needsAsk(c, p)) {
    hold(b, c, p);
    return true;
  }
  return false;
}

// よやくを おわりに して、自分の 番に もどす（まっていた 仲間も 自分の 番に）
export function endWait(b, c, msg, back = true) {
  const w = c.waitDual;
  c.waitDual = null;
  for (const id of w?.partners || []) {
    const p = b.get(id);
    if (!p || p.dualTarget !== c.id) continue;
    p.dualTarget = null;
    unhold(b, p);
  }
  b.emit({ t: 'dualWaitEnd', id: c.id, partners: w?.partners || [], lines: msg ? [msg] : [] });
  if (back && c.alive) b.onReady(c);
}

// みんなの 番を おさえて、合体技を 出す じゅんばんに ならべる
function reserveDual(b, c, ps, cmd) {
  for (const p of ps) {
    p.ready = false;
    p.queued = true;
    p.dualWith = c.id;
    p.dualHold = false;
    if (p.dualTarget === c.id) p.dualTarget = null;
    b.emit({ t: 'queued', id: p.id });
  }
  c.inviting = null;
  const ids = ps.map((p) => p.id);
  b.enqueue(c, { type: 'dual', id: cmd.id, partner: ids[0], partners: ids, target: cmd.target });
  b.emit({ t: 'queued', id: c.id, dual: cmd.id, partner: ids[0], partners: ids });
}

// 合体技の 仲間を もとに もどす（出せなかった とき）。cmd か 仲間の id
export function releasePartners(b, cmdOrId) {
  const ids = typeof cmdOrId === 'string' ? [cmdOrId] : partnersOf(cmdOrId);
  for (const id of ids) {
    const p = b.get(id);
    if (!p || !p.dualWith) continue;
    p.dualWith = null;
    p.queued = false;
  }
}

// さそわれた 家族の こたえ
export function answerDual(b, pid, cmd) {
  const inv = b.invites.get(cmd.invite);
  if (!inv || !inv.pending.has(pid)) return { ok: false, reason: 'もう終わっている' };
  if (!cmd.ok) {
    endInvite(b, inv, 'ことわった', pid);
    return { ok: true };
  }
  inv.pending.delete(pid);
  const p = b.get(pid);
  const c = b.get(inv.from);
  if (p) p.invited = null;
  // ほかの 家族の 返事を まつ（参加する 人は、ゲージが たまった まま まつ）
  if (inv.pending.size) {
    if (p && c) hold(b, c, p);
    b.emit({ t: 'dualAnswer', invite: inv.id, ok: true, partial: true, from: inv.from, to: pid });
    return { ok: true };
  }
  b.invites.delete(inv.id);
  const ps = inv.partners.map((id) => b.get(id));
  const ok = c && c.alive && c.ready && !ps.some(cantJoin) && findOpt(b, c, inv.tech, inv.partners);
  if (!ok) {
    if (c) c.inviting = null;
    for (const x of ps) if (x && c && x.dualTarget === c.id) { x.dualTarget = null; unhold(b, x); }
    b.emit({ t: 'dualAnswer', invite: inv.id, ok: false, from: inv.from, to: pid, reason: '出せなくなった' });
    return { ok: true };
  }
  b.emit({ t: 'dualAnswer', invite: inv.id, ok: true, from: c.id, to: pid });
  reserveDual(b, c, ps, { id: inv.tech, target: inv.target });
  return { ok: true };
}

// さそいを おわりに する（ことわった・時間切れ・やめた・倒れた）。by … ことわった 人
export function endInvite(b, inv, reason, by = null) {
  b.invites.delete(inv.id);
  const c = b.get(inv.from);
  if (c && c.inviting === inv.id) c.inviting = null;
  for (const id of inv.asks || [inv.to]) {
    const p = b.get(id);
    if (p && p.invited === inv.id) p.invited = null;
  }
  // まっていた 仲間は 自分の 番に
  for (const id of inv.partners || []) {
    const p = b.get(id);
    if (p && c && p.dualTarget === c.id) {
      p.dualTarget = null;
      unhold(b, p);
    }
  }
  const who = by || (reason === '時間切れ' ? [...(inv.pending || [])][0] : null) || inv.to;
  b.emit({ t: 'dualAnswer', invite: inv.id, ok: false, from: inv.from, to: who, reason });
  // オートの 人は ふつうに 動く
  if (c && c.alive && c.ready && (!c.controller || c.auto)) {
    c.ready = false;
    b.onReady(c);
  } else if (c && c.alive && c.ready) b.emit({ t: 'ready', id: c.id });
}

// ───── 強さ ─────
// その 人が 技 id を この 敵に ふつうに 出した ときの ダメージ（見つもり。属性は のぞく）
export function skillEstimate(b, m, id, tg, ignoreDef = 0) {
  const a = ABILITIES[id];
  const e = a?.effect;
  if (!e) return 0;
  const pen = m.penChar ? penaltyFor(m.penChar, id).powMult : 1;
  let best = 0;
  for (const p of e.type === 'multi' ? e.parts || [] : [e]) {
    if (p.type === 'phys') {
      const eff = { ...p, element: undefined, ignoreDef: Math.max(p.ignoreDef || 0, ignoreDef) };
      // 第55回: ランダムに 何回も 当たる 技も その 回数で 見つもる（前は 1回ぶん だけ。ほかの 敵に それる ぶん 少し ひく）
      best = Math.max(best, b.calcPhys(m, tg, eff, pen, 'phys', true).dmg * (p.random ? Math.max(1, (p.hits || 1) * 0.75) : p.hits || 1));
    } else if (p.type === 'magic' && Array.isArray(p.base)) {
      best = Math.max(best, b.calcMagic(m, tg, { ...p, element: undefined }, pen, true).dmg);
    }
  }
  return best;
}

// 合体技に 入った 人の ぶん: list の 技で いちばん 強い もの（なければ ふつうの 攻撃）
export function memberPower(b, m, list, tg, ignoreDef = 0) {
  let best = b.calcPhys(m, tg, { mult: 1, ignoreDef }, 1, 'phys', true).dmg;
  const set = new Set(list);
  for (const id of m.abilities || []) {
    if (!set.has(id) || !weaponOk(ABILITIES[id], m.weaponCat)) continue;
    best = Math.max(best, skillEstimate(b, m, id, tg, ignoreDef));
  }
  return best;
}

// 合体技に 入った 人の 回復の 力: その 組の 回復の 技で いちばん 強い もの（1人ぶん）
function memberHeal(m, list) {
  let best = 0;
  const set = new Set(list);
  for (const id of m.abilities || []) {
    if (!set.has(id)) continue;
    const e = ABILITIES[id]?.effect;
    for (const p of e?.type === 'multi' ? e.parts || [] : [e]) {
      if (p?.type !== 'heal' || !Array.isArray(p.base)) continue;
      const scale = p.fixed ? 1 : 1 + Math.max(0, Math.min(1, ((m.healPow || 0) - (p.thr ?? 20)) / 150));
      best = Math.max(best, ((p.base[0] + p.base[1]) / 2) * scale);
    }
  }
  return best;
}

// 合体技の ダメージ（敵 1体ぶんの 見つもり）: 出す 人 それぞれが ふつうに 出せる いちばん 強い 技（か ふつうの 攻撃）の 合計 × DUAL_POWER × k
// （組の 技に かぎらない。「2人が 1回ずつ 動く」より はっきり 強く なる ように）
export function dualPower(b, members, tg, part, n) {
  let sum = 0;
  for (const m of members) sum += memberPower(b, m, m.abilities || [], tg, part.ignoreDef || 0);
  return sum * DUAL_POWER[n] * (part.k ?? 1);
}

// ───── 出す ─────
export function performDual(b, c, cmd, ev) {
  const ids = partnersOf(cmd);
  const ps = ids.map((id) => b.get(id));
  const t = dualFor(cmd.id, [c, ...ps]);
  ev.name = t?.name || '合体技';
  const bad = ps.find(cantJoin);
  if (!t || !ps.length || bad !== undefined) {
    ev.lines.push(`しかし${bad?.name || '仲間'}は合体技に参加できなかった！`);
    releasePartners(b, cmd);
    return;
  }
  const opt = findOpt(b, c, cmd.id, ids, true);
  if (!opt) {
    ev.lines.push('しかし合体技は出せなかった！');
    releasePartners(b, cmd);
    return;
  }
  const team = opt.partners.map((id) => b.get(id));
  const members = [c, ...team];
  c.mp -= opt.mp[0];
  team.forEach((p, i) => { p.mp -= opt.mp[i + 1]; });
  const n = members.length;
  ev.dual = { id: cmd.id, name: t.name, a: c.id, b: team[0].id, m: members.map((x) => x.id), n };
  ev.lines.push(`${members.map((x) => x.name).join('と')}の合体技！`, `${t.name}！`);
  // 第66回: 幻の職業の 技の 条件にも 数える（参加した みんな）
  b.featDual?.(members, t);
  // 組の じゅんの 人と、その 人の 組（強さの 見つもりに 使う）
  const byGroup = opt.who.map((id) => b.get(id));
  const groups = byGroup.map((m) => t.need[opt.who.indexOf(m.id)]);
  const hit = new Set();
  for (const part of t.parts) {
    if (part.say) ev.lines.push(part.say);
    const scope = part.target || t.target;
    if (part.type === 'power') {
      const element = part.elementFrom !== undefined ? opt.element || undefined : part.element;
      powerHit(b, c, byGroup, part, scope, element, cmd, ev, hit, n);
    } else if (part.type === 'heal') {
      const sum = byGroup.reduce((s, m, i) => s + memberHeal(m, groups[i]), 0);
      for (const x of b.targetsFor(c, { target: scope === 'enemies' || scope === 'enemy' ? 'allies' : scope }, cmd)) {
        const amt = Math.max(1, Math.round(x.maxHp * (part.pct || 0) + sum * DUAL_POWER[n] * (part.k ?? 0)));
        b.heal(c, x, { base: [amt, Math.round(amt * 1.06)], fixed: true }, ev, 1);
        hit.add(x.id);
      }
    } else if (part.type === 'revive') {
      const dead = b.targetsFor(c, { target: 'deadAllies' }, cmd);
      if (dead.length) b.applyAbility(c, { name: t.name, effect: { type: 'revive', hpRatio: part.pct || 0.3 }, target: 'deadAllies', anim: t.anim }, cmd, ev, 1, dead);
      for (const x of dead) hit.add(x.id);
    } else {
      const eff = { ...part };
      delete eff.say;
      delete eff.target;
      const ab = { name: t.name, effect: eff, target: scope, anim: t.anim };
      const targets = b.targetsFor(c, ab, cmd);
      ev.inMulti = true;
      // 第50回 D4: 合体技の 補助（バフ・デバフ）は 超級職の 技と おなじ（2だんかい・4回行動。skill-tier.js）
      if (SUPPORT_TYPES.has(eff.type)) ev.tier = { by: c.id, ...tierMods(DUAL_TIER), healMul: 1 };
      b.applyAbility(c, ab, cmd, ev, 1, targets);
      delete ev.tier;
      delete ev.inMulti;
      for (const x of targets) hit.add(x.id);
    }
  }
  ev.fx = { type: 'dual', anim: t.anim, actor: c.id, partner: team[0].id, members: ev.dual.m, targets: [...hit], side: 'ally', element: opt.element || t.element, size: n };
  ev.extraLock = (ev.extraLock || 0) + 700 + 300 * (n - 2);
  for (const p of team) {
    p.atb = 0;
    p.ready = false;
  }
  releasePartners(b, cmd);
  ev.upd.push(c, ...team);
}

// ───── よやくの 待ち中に ダメージ（第31回）─────
// よやくで ゲージが たまって まっている 人が ダメージを 受けると、その 人の ゲージは 半分から やり直し（よやくは つづく）
//  ・よやくした 人（c.waitDual）: ゲージが また たまるまで、みんな そろっても 出さない（waitDual.slow）
//  ・先に ゲージが たまって まっている 仲間（p.dualHold）: まつのを やめて、ゲージが また たまったら もう一度 まつ・出す
//  ・ゲージが まだ たまって いない 仲間・家族に「参加する？」と 聞いている 間は かわらない
// battle.js の damage から よぶ（t … ダメージを 受けた 人、ev … 今の 行動の できごと）
export const DUAL_BREAK_ATB = 50;
export function dualHurt(b, t, ev) {
  if (t.side !== 'ally' || !t.alive || t.hp <= 0) return;
  if (t.waitDual && !t.waitDual.slow) t.waitDual.slow = true;
  else if (t.dualHold && b.get(t.dualTarget)?.waitDual) t.dualHold = false;
  else return;
  t.atb = DUAL_BREAK_ATB;
  t.ready = false;
  ev.lines.push(`${t.name}の力あわせがみだれた！`);
  ev.dualBreak = [...(ev.dualBreak || []), t.id];
  ev.upd.push(t);
}

// よやくした 人の ゲージが また たまった（battle.js の advance。true … この 番は よやくの まま まつ）
export function dualRecharged(b, c) {
  if (!c.waitDual?.slow) return false;
  c.waitDual.slow = false;
  return true;
}

// 合体技の ダメージを 当てる（hits 回に 分けて）
function powerHit(b, c, byGroup, part, scope, element, cmd, ev, hit, n) {
  const targets = b.targetsFor(c, { target: scope }, cmd);
  if (!targets.length) {
    ev.lines.push('しかし効果がなかった！');
    return;
  }
  // 推理（element: 'deduce'）: ことばは 敵の しゅるいごとに 1回
  const told = new Set();
  let last = element;
  for (const tg of targets) {
    if (!tg.alive) continue;
    hit.add(tg.id);
    if (part.kind === 'phys') b.noteCounter(c, tg, ev);
    let el = element;
    if (element === 'deduce') {
      el = deduceElement(tg) || undefined;
      last = el || last;
      if (tg.species && !tg.clone && !told.has(tg.species)) {
        told.add(tg.species);
        const nm = MONSTERS[tg.species]?.name || tg.name;
        ev.lines.push(el ? `${nm}の弱点は…${ELEMENT_NAMES[el]}だ！` : `${nm}には、弱点がない…！`);
      }
    }
    const r = el && el !== 'phys' ? tg.resist?.[el] ?? 1 : 1;
    if (r === 0) {
      ev.lines.push(`しかし${tg.name}には効かなかった！`);
      (ev.results = ev.results || []).push({ id: tg.id, miss: true, element: el, aff: b.noteTried(tg, el) || undefined });
      continue;
    }
    let d = dualPower(b, byGroup, tg, part, n) * r * b.rng.float(0.92, 1.08);
    if (tg.boss) d = Math.min(d, tg.maxHp * (DUAL_TECHS[cmd.id]?.bossCap ?? DUAL_BOSS_CAP[n] ?? 0.3));
    if (tg.metal) d = b.rng.int(1, n + 1);
    const hits = Math.max(1, part.hits || 1);
    const each = Math.max(1, Math.round(d / hits));
    for (let h = 0; h < hits && tg.alive; h++) b.damage(c, tg, tg.metal && h > 0 ? 0 : each, ev, { element: el || 'phys' });
    if (part.dispel && tg.alive) b.dispel(tg, ev);
    if (part.status && tg.alive) b.tryStatus(c, tg, part.status, ev, 1);
    if (part.debuff && tg.alive) b.applyDebuff(c, tg, part.debuff, ev, 1);
  }
  // ポイントバック（ポイント10倍デー）: 当てた 敵の お金の points 倍
  if (part.points) b.givePoints(c, targets, part, ev);
  b.afterDamage(c, ev, (element === 'deduce' ? last : element) || 'phys');
}

