// 第4章 Step 7「砂の底の神殿とモルガナ」の たたかいの しかけ（battle.js・ai.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・呪文を はね返す（reflect）: 鏡の騎士・まどわしの鏡の「体が 光った」、真の すがたの モルガナの「鏡のうろこ」。
//   光ってから つぎの 自分の 番まで、味方の 呪文（1体・グループ・全体）を はね返す（となえた 人に 半分の 強さで）。光った 番の のこりの 行動は とりやめ
// ・鏡写し（monsters の mirrorCopy。モルガナ）: おなじ 呪文を 2回 つづけて モルガナに 使うと、2回目は はね返される
// ・水の衣（monsters の veil。モルガナ）: まとっている 間は 受ける ダメージが 半分（cut）・炎は 効かない（block）。
//   雷の ダメージで はじけとぶ（breakBy）。はじけた あと wait 回 動くと、前ぶれ「水をまとい始めた…」→ つぎの 番に また まとう
// ・大波（真の すがた）: 2だんの 前ぶれ（stage 1「水がうずをまいている…」→ stage 2「うずが大きくなっていく…」）→ つぎの 番に 大波（防御で 半分）
// ・水のろう（真の すがた）: 1人を とじこめる（その 人の 番が 2回 くるまで 動けない）。ろうは 敵の がわに 出る（water_prison）。
//   ろうを こわすと 早く 出られる。モルガナが たおれると ろうも 消える（monsters の minionsFall）
// ・水の守りの歌（17-2）: morgana_true の 戦いを 始める 時、戦いに 入っている 家族の だれかが わらべ歌（SONG_FLAGS）を ぜんぶ
//   聞いていれば、はじめの SONG.waves 回の 大波の ダメージが SONG.cut ばいに なる
// ・鏡のうつし身（utsushimi）: 戦いの はじめに、パーティーの 人数ぶんの「〇〇のうつし身」に かわる（職業・レベル・見た目〈見た目装備も〉・
//   覚えている 技は うつした 人と おなじ。強さは MIRROR_RATE ばい）。技は 仲間の オートの AI（ai.js の decideAlly）で えらぶ
// ・シミュレーター（tools/sim.js）: b.knowsTemple … しかけを 知っている 人（大波の 前に 身を 守る・おなじ 呪文を つづけない・
//   水の衣に 雷の 技・水のろうを こわす）。b.templeNaive … 知らない 人（光っていても 呪文・大波でも 身を 守らない）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES, ELEMENT_NAMES } from './data/abilities.js';
// わらべ歌の フラグ（物語の データ。読むだけ）
import { SONG_FLAGS } from './maps/ch4.js';
import { decideAlly } from './ai.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate, pub } from './battle.js';
import { mirageSync } from './battle-ch4.js';

export const UTSUSHIMI = 'utsushimi';
export const PRISON = 'water_prison';
export const WAVE = 'm_big_wave';
// うつし身の 強さ（うつした 人の 強さ × これ。少し 弱く）
export const MIRROR_RATE = { hp: 1.05, atk: 0.85, dfn: 0.9, mag: 0.85, heal: 0.75, agi: 0.95 };
// はね返った 呪文の 強さ（となえた 人に 当たる）。1回で たおれて しまわない ように、さいだいHPの REFLECT_CAP まで
export const REFLECT_MULT = 0.5;
export const REFLECT_CAP = 0.3;
// 水の守りの歌: はじめの waves 回の 大波が cut ばい
export const SONG = { waves: 1, cut: 0.5 };
// うつし身が 使わない 技の こうか（戦いを こわす もの・にげる・追い出す・けしさる・生き返らせる・お金・ぬすむ・どれか ひとつ など）
const MIRROR_SKIP = new Set(['escape', 'banish', 'destroy', 'revive', 'reviveAll', 'goldThrow', 'steal', 'scan', 'allMp', 'random', 'callHelp', 'stance', 'hurt', 'overtime', 'mahouken', 'flee']);

const isSpell = (a) => !!a && (a.kind === 'spell' || !!a.spellLike);
const foeKinds = new Set(['enemy', 'group', 'enemies']);
// 番の のこりの 行動を とりやめる（構えて まつ・前ぶれ）
function endTurn(b, c, ev) {
  b.queue = b.queue.filter((q) => q.id !== c.id);
  ev.forceLast = true;
  ev.atbAfter = 0;
}

// ───────────── たたかいの はじめ（Battle の constructor。分身より 先）─────────────
export function setupTemple(b, opts = {}) {
  if (b.enemies.some((e) => e.species === UTSUSHIMI && !e.mirrorOf)) setupUtsushimi(b);
  // 水の衣: はじめから まとっている
  for (const e of b.enemies) {
    if (!MONSTERS[e.species]?.veil) continue;
    e.veil = true;
    e.veilGone = 0;
  }
  // 水の守りの歌（真の すがたの モルガナの 戦い）
  if (b.enemies.some((e) => e.species === 'morgana_true')) {
    const song = opts.song !== undefined ? !!opts.song : heardSongs(opts.allies);
    if (song) {
      b.song = { left: SONG.waves, cut: SONG.cut, now: false };
      b.emit({ t: 'msg', lines: ['水の守りの歌が、みんなをつつんでいる…', '（大波のいきおいが、やわらぎそうだ）'], fx: { type: 'song' }, dur: 1800 });
    }
  }
}

// 戦いに 入っている 家族の だれかが、わらべ歌を 4つとも 聞いている（キャラの flags）
export function heardSongs(allies = []) {
  return allies.some((a) => {
    const f = a?.char?.flags;
    return a.kind !== 'guest' && !a.char?.species && f && SONG_FLAGS.every((k) => f[k]);
  });
}

// ───────────── 鏡のうつし身 ─────────────
// 1体の しるし（utsushimi）を、パーティーの 人数ぶんの うつし身に かえる
export function setupUtsushimi(b) {
  const marks = b.combatants.filter((x) => x.side === 'enemy' && x.species === UTSUSHIMI && !x.mirrorOf);
  b.combatants = b.combatants.filter((x) => !marks.includes(x));
  for (const a of b.allies) {
    const e = mirrorCopy(a);
    e.id = 'e' + (b.nextId++);
    e.slot = b.combatants.filter((x) => x.side === 'enemy').length;
    b.combatants.push(e);
  }
}

// うつし身が 使える 技（覚えている 技から。戦いを こわす 技は 使わない）
export function mirrorSkillOk(id) {
  const a = ABILITIES[id];
  if (!a || a.hidden) return false;
  const effs = a.effect?.type === 'multi' ? a.effect.parts || [] : [a.effect || {}];
  return effs.every((e) => !MIRROR_SKIP.has(e.type));
}

const R = (v, k) => Math.max(1, Math.round((v || 0) * k));

// 味方 a の うつし身（敵の がわ）。見た目（look・職業・見た目装備 eq・魔物の 仲間なら mon）は そのまま
export function mirrorCopy(a) {
  const K = MIRROR_RATE;
  const maxHp = R(a.maxHp, K.hp);
  const name = `${a.name}のうつし身`;
  return {
    side: 'enemy', kind: 'monster', species: UTSUSHIMI, mirrorOf: a.id,
    name, baseName: name, letter: '',
    lv: a.lv, maxHp, hp: maxHp, maxMp: a.maxMp || 0, mp: a.maxMp || 0,
    atk: R(a.atk, K.atk), dfn: R(a.dfn, K.dfn), agi: R(a.agi, K.agi), mag: R(a.mag, K.mag), healPow: R(a.healPow, K.heal),
    resist: { ...(a.resist || {}) }, race: a.race || 'human', metal: false, flying: false, boss: false,
    turns: 1, size: 'm', speed: 1,
    actions: [{ w: 1, id: 'attack' }], used: {}, recent: [],
    abilities: (a.abilities || []).filter(mirrorSkillOk),
    tactics: a.tactics && a.tactics !== 'manual' ? a.tactics : 'balanced',
    autoOff: (a.autoOff || []).slice(),
    penChar: a.penChar, weaponCat: a.weaponCat, onHit: a.onHit,
    look: a.look, job: a.job, eq: a.eq, mon: a.mon,
    atb: 0, ready: false, queued: false, buffs: {}, debuffs: {}, status: {},
    alive: true, charge: 1, telegraph: null, cover: null,
  };
}

// うつし身から 見た たたかい（味方と 敵を 入れかえた かげ。仲間の オートの AI を そのまま 使う）
function mirrorView(b) {
  const v = Object.create(b);
  v.aliveAllies = () => b.aliveEnemies();
  v.aliveEnemies = () => b.aliveAllies();
  Object.defineProperty(v, 'allies', { get: () => b.enemies });
  Object.defineProperty(v, 'enemies', { get: () => b.allies });
  v.humans = () => [];
  for (const k of ['knowsMirage', 'knowsBurrow', 'ignoreBurrow', 'ignoreStance', 'ignoreChant', 'focusBoss', 'knowsTemple', 'templeNaive']) v[k] = false;
  return v;
}

// 第5章 Step 5 の ノクトの影も 使う（まねた 人の 技を えらぶ。battle-nocto.js）
export function mirrorDecide(b, m) {
  let cmd = null;
  try {
    cmd = decideAlly(mirrorView(b), m);
  } catch {
    cmd = null;
  }
  if (!cmd || !['attack', 'ability', 'defend'].includes(cmd.type)) cmd = { type: 'attack' };
  if (cmd.type === 'ability' && !m.abilities.includes(cmd.id)) cmd = { type: 'attack' };
  if (cmd.type === 'attack' && !b.get(cmd.target)?.alive) cmd.target = undefined;
  return cmd;
}

// ───────────── 魔物の 番の はじめ（ai.js の decideMonster。まぼろしの あと）─────────────
export function templeAction(b, m) {
  // うつし身: 仲間の オートの AI で えらぶ
  if (m.mirrorOf) return mirrorDecide(b, m);
  // 水の衣を また まとう（前ぶれの つぎの 番。分身は まねを する だけ）
  if (m.veilCharge && !m.clone) {
    const id = m.veilCharge;
    m.veilCharge = null;
    syncVeil(b, m);
    return { type: 'ability', id };
  }
  // 大波を 出す 番: 水の守りの歌が あれば、この 大波は 軽く なる
  if (m.waveStage && m.telegraph && ABILITIES[m.telegraph]?.effect?.type !== 'wave') {
    m.waveStage = 0;
    if (b.song?.left > 0) {
      b.song.left--;
      b.song.now = true;
    }
  }
  return null;
}

// こうどうの はじめ（battle.js の executeNext。反撃の構えと おなじ ところ）: 光が 消える・水の衣の じかん・歌の あと
export function templeTurnStart(b, c, ev) {
  if (b.song) b.song.now = false;
  if (c.reflect) {
    c.reflect = null;
    ev.lines.push(`${c.name}の光が、おさまった。`);
    ev.upd.push(c);
  }
  if (c.side === 'enemy' && !c.clone && MONSTERS[c.species]?.veil && !c.veil) c.veilGone = (c.veilGone || 0) + 1;
  // 分身にも おなじ HPを 見せる（いやしの水で 回復した あとも）
  if (c.shade) mirageSync(b, c);
}

// 魔物の こうどうの じょうけん（ai.js の condOk。't:' の あと）
export function templeCond(b, m, cond) {
  if (cond === 'noReflect') return !m.reflect;
  if (cond === 'noVeil') {
    const conf = MONSTERS[m.species]?.veil;
    return !!conf && !m.veil && !m.veilCharge && (m.veilGone || 0) >= (conf.wait ?? 2);
  }
  if (cond === 'noWave') return !m.telegraph && !m.waveStage;
  // 水のろう: まだ ろうが なく、動ける 味方が 2人いじょう
  if (cond === 'noPrison') {
    if (b.enemies.some((e) => e.alive && e.species === PRISON)) return false;
    return b.aliveAllies().filter((x) => !x.status.prison).length >= 2;
  }
  return true;
}

// ───────────── 技の こうか（battle.js の applyAbility の のこり）─────────────
export function templeEffect(b, c, a, eff, ev, targets) {
  switch (eff.type) {
    case 'reflect': {
      c.reflect = { kind: eff.kind || 'glow' };
      ev.fx = { type: 'reflect', actor: c.id, kind: c.reflect.kind };
      ev.warn = true;
      ev.lines.push('（今、呪文をとなえると、はね返されそうだ…！）');
      endTurn(b, c, ev);
      ev.upd.push(c);
      return true;
    }
    case 'veilCharge': {
      c.veilCharge = eff.next;
      syncVeil(b, c, ev);
      ev.fx = { type: 'veilCharge', actor: c.id };
      ev.warn = true;
      ev.lines.push('（次の番に、また水の衣をまとうつもりだ…！）');
      endTurn(b, c, ev);
      return true;
    }
    case 'veil': {
      c.veil = true;
      c.veilGone = 0;
      syncVeil(b, c, ev);
      ev.fx = { type: 'veil', actor: c.id, on: true, targets: [c.id, ...cloneIds(b, c).filter((id) => b.get(id)?.alive)] };
      ev.lines.push('（受けるダメージが半分になり、炎が効かなくなった…！）');
      return true;
    }
    case 'dazzle': {
      // 月の鏡で まぶしい: この 番は 何も できない（2回行動の のこりも）
      endTurn(b, c, ev);
      return true;
    }
    case 'wave': {
      c.telegraph = eff.next;
      c.waveStage = eff.stage || 1;
      ev.fx = { type: 'wave', actor: c.id, stage: c.waveStage };
      ev.warn = true;
      ev.lines.push(c.waveStage >= 2 ? '（次の番に、大波が来る！身を守れ！）' : '（もうすぐ、大きな波が来そうだ…！身を守るじゅんびを！）');
      endTurn(b, c, ev);
      ev.upd.push(c);
      return true;
    }
    case 'prison': prisonStart(b, c, eff, ev, targets); return true;
    default: return false;
  }
}

// ───────────── 水の衣 ─────────────
const cloneIds = (b, c) => (b.mirage && b.mirage.real === c.id ? b.mirage.clones.slice() : []);

// 分身も おなじ すがたに（水の衣・前ぶれ）。ev … がめんへ おくる イベント（ない ときは 今の こうどう）
function syncVeil(b, c, ev = b.cur) {
  c.veilShow = c.veilCharge ? 1 : 0;
  if (ev) ev.upd.push(c);
  for (const id of cloneIds(b, c)) {
    const x = b.get(id);
    if (!x) continue;
    x.veil = c.veil;
    x.veilShow = c.veilShow;
    if (ev) ev.upd.push(x);
  }
}

// ダメージの はじめ（battle.js の damage。分身の あと）: 水の衣（半分・炎は 効かない・雷で はじける）と 水の守りの歌。
// null … ダメージなし（ことばは ここで 出す）。ほかは ダメージの 数
export function templeDamage(b, c, t, dmg, info, ev) {
  if (!c || dmg <= 0) return dmg;
  // 水の守りの歌（大波）
  if (b.song?.now && c.side === 'enemy' && t.side === 'ally' && ev.ability === WAVE) {
    if (!ev.songLine) {
      ev.songLine = true;
      ev.lines.push('水の守りの歌が、大波のいきおいをやわらげた！');
      ev.song = true;
      if (b.song.left <= 0) (ev.postLines = ev.postLines || []).push('（水の守りの歌は、しずかに消えていった…）');
    }
    return Math.max(1, Math.round(dmg * b.song.cut));
  }
  if (!t.veil || c.side === t.side) return dmg;
  const conf = MONSTERS[t.species]?.veil;
  if (!conf) return dmg;
  const el = info?.element;
  if (el && el === conf.breakBy) {
    // 雷: そのまま 当たって、水の衣が はじけとぶ
    t.veil = false;
    t.veilGone = 0;
    syncVeil(b, t, ev);
    ev.veilBreak = t.id;
    ev.postLines = ev.postLines || [];
    if (!ev.postLines.includes('水の衣が、はじけとんだ！')) ev.postLines.push('水の衣が、はじけとんだ！');
    return dmg;
  }
  if (el && (conf.block || []).includes(el)) {
    ev.lines.push(`水の衣が、${ELEMENT_NAMES[el] || el}をかき消した！`);
    (ev.results = ev.results || []).push({ id: t.id, dmg: 0, miss: true, veil: true });
    return null;
  }
  return Math.max(1, Math.round(dmg * (conf.cut ?? 0.5)));
}

// 味方の オートの みつもり（battle.js の calcPhys・calcMagic の estimate）: 水の衣を 見る
export function templeEst(b, c, t, element) {
  if (!t?.veil || !c || c.side === t.side) return 1;
  const conf = MONSTERS[t.species]?.veil;
  if (!conf) return 1;
  // （影の城の モルガナのまぼろし〈phantom〉は、ふつうの オートも 雷を 少し えらびやすい。水かさが 下がるので。第5章 Step 8）
  if (element && element === conf.breakBy) return b.knowsTemple ? 1.5 : MONSTERS[t.species]?.phantom ? 1.3 : 1;
  if (element && (conf.block || []).includes(element)) return 0;
  return conf.cut ?? 0.5;
}

// ───────────── 呪文を はね返す・鏡写し ─────────────
// 味方が 敵に 呪文を となえた（battle.js の perform。MPを はらった あと）。はね返したら true（あたる ぶんも ここで あてる）
export function reflectSpell(b, c, a, cmd, ev, powMult, targets) {
  if (c.side !== 'ally' || !isSpell(a) || !foeKinds.has(a.target)) return false;
  const back = [];
  for (const t of targets) {
    if (!t?.alive || t.side === c.side) continue;
    if (t.reflect) back.push({ t, why: t.reflect.kind });
    else if (MONSTERS[t.species]?.mirrorCopy && !t.clone) {
      // 鏡写し: おなじ 呪文を つづけて 使うと はね返す（はね返しても おぼえて いる）
      if (cmd.id && t.lastSpell === cmd.id) back.push({ t, why: 'copy' });
      t.lastSpell = cmd.id;
    }
  }
  if (!back.length) return false;
  const keep = targets.filter((t) => !back.some((x) => x.t === t));
  if (keep.length) b.applyAbility(c, a, cmd, ev, powMult, keep);
  const { t: t0, why } = back[0];
  ev.lines.push(why === 'copy' ? '鏡写し！呪文ははね返された！' : `${t0.name}の${why === 'scale' ? 'うろこ' : '体'}が光り、呪文をはね返した！`);
  ev.reflected = back.map((x) => x.t.id);
  const hit = new Set([...(ev.fx?.targets || []), ...back.map((x) => x.t.id), c.id]);
  bounce(b, c, a, ev, powMult);
  ev.fx = { ...(ev.fx || {}), type: 'ability', anim: a.anim, actor: c.id, targets: [...hit], side: 'ally', element: a.effect?.element, reflect: t0.id, copy: why === 'copy' };
  return true;
}

// はね返った 呪文が となえた 人に 当たる（1回だけ。ダメージは REFLECT_MULT ばい）
function bounce(b, c, a, ev, powMult) {
  const e = a.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a.effect || {};
  if ((e.type === 'magic' || e.type === 'gather') && Array.isArray(e.base)) {
    const res = b.calcMagic(c, c, { ...e, type: 'magic', base: e.base.map((v) => Math.max(1, Math.round(v * REFLECT_MULT))) }, powMult);
    const dmg = Math.min(res.dmg, Math.max(1, Math.round(c.maxHp * REFLECT_CAP)));
    if (res.resisted || dmg <= 0) ev.lines.push(`${c.name}はダメージを受けない！`);
    else b.damage(c, c, dmg, ev, { element: e.element });
  } else if (e.type === 'status') b.tryStatus(c, c, e, ev, powMult);
  else if (e.type === 'debuff') b.applyDebuff(c, c, e, ev, powMult);
  else ev.lines.push('しかし、何も起こらなかった。');
  ev.upd.push(c);
}

// ───────────── 水のろう ─────────────
function prisonStart(b, c, eff, ev, targets) {
  const free = b.aliveAllies().filter((x) => !x.status.prison);
  let t = targets[0];
  if (!t || !t.alive || t.side === c.side || t.status.prison) t = free.length ? b.rng.pick(free) : null;
  if (!t || free.length < 2) {
    ev.lines.push('しかし、水のたまは、はじけて消えた！');
    return;
  }
  const [p] = b.addEnemies([PRISON]);
  p.atb = 0;
  p.holds = t.id;
  // ろうの 中に 見える 人（がめん）
  p.inside = { name: t.name, look: t.look, job: t.job, eq: t.eq, mon: t.mon };
  t.status.prison = { turns: eff.turns || 2, by: p.id };
  // とじこめられた 人は、ならんで いた 行動も できない
  b.queue = b.queue.filter((q) => q.id !== t.id || q.cmd?.type === 'dual');
  if (t.ready || t.queued) {
    t.ready = false;
    t.queued = false;
    t.atb = 0;
  }
  ev.joined = (ev.joined || []).concat(pub(p));
  ev.lines.push(`${t.name}は、水のろうにとじこめられた！`, '（ろうを攻撃してこわせば、早く助け出せそうだ…！）');
  ev.fx = { type: 'prison', actor: c.id, targets: [t.id], prison: p.id };
  ev.warn = true;
  ev.upd.push(t, p);
}

// ろうを 消す（たおした ことには しない。経験値も ない）
function vanishPrison(b, p, ev) {
  Object.assign(p, { alive: false, hp: 0, ready: false, queued: false, status: {}, buffs: {}, debuffs: {}, telegraph: null });
  b.queue = b.queue.filter((q) => q.id !== p.id);
  if (ev) {
    (ev.results = ev.results || []).push({ id: p.id, pop: true });
    ev.upd.push(p);
  }
}

// とじこめられた 人の 番（battle.js の doIncapacitated）
export function prisonTurn(b, c, ev) {
  const s = c.status.prison;
  ev.name = '水のろう';
  ev.fx = { type: 'prisonTurn', actor: c.id };
  s.turns--;
  if (s.turns > 0) {
    ev.lines.push(`${c.name}は、水のろうの中で、もがいている…！`);
    return;
  }
  delete c.status.prison;
  const p = b.get(s.by);
  if (p?.alive) vanishPrison(b, p, ev);
  ev.lines.push(`水のろうがはじけて、${c.name}は外に出られた！`);
  ev.atbAfter = 60;
  ev.upd.push(c);
}

// たおれた（battle.js の kill の はじめ）: 水のろうは こわれて 中の 人が 出る（ことばを かえす）。
// とじこめられた まま たおれた 人の ろうは 消える（null … ふつうの きまりで つづける）
export function templeKill(b, t, ev) {
  if (t.side === 'enemy' && t.species === PRISON) {
    const who = b.get(t.holds);
    vanishPrison(b, t, ev);
    const out = ['水のろうが、こわれた！'];
    if (who?.status?.prison) {
      delete who.status.prison;
      out.push(`${who.name}は、水のろうから助け出された！`);
      if (ev) ev.upd.push(who);
    }
    return out;
  }
  if (t.side === 'ally' && t.status?.prison) {
    const p = b.get(t.status.prison.by);
    if (p?.alive) vanishPrison(b, p, ev);
  }
  return null;
}

// ───────────── オートの 仲間・シミュレーター ─────────────
// 味方の オート（ai.js の decideAlly の はじめ）。知っている 人は 大波の 前に 身を 守る
export function templePlan(b, c, foes) {
  if (c.side !== 'ally' || !b.knowsTemple) return null;
  const mine = 100 / atbRate(c);
  // 大波が 自分の つぎの 番より 先に 来る
  const wave = b.aliveEnemies().find((e) => e.telegraph === WAVE);
  if (wave && (100 - wave.atb) / atbRate(wave) <= mine) return { type: 'defend' };
  return null;
}

// 水の衣を まとった 敵に 雷の 技（知っている 人。ai.js の decideAlly。第31回: 前の きずな技〈雷〉の かわり）
// mine … 使える 技（[{ id, a }]）。雷の ダメージの 技で いちばん MPの 多い もの（強い 技）。合体技の ミナデインは 人が えらぶ
const hasBolt = (e) => !!e && (e.element === 'bolt' && (e.type === 'phys' || e.type === 'magic' || e.type === 'gather')) || (e?.type === 'multi' && (e.parts || []).some(hasBolt));
// （影の城の モルガナのまぼろし〈phantom〉は、ふつうの オートも ときどき〈PHANTOM_BOLT〉雷の 技を 使う。水かさが 下がるので。第5章 Step 8）
export const PHANTOM_BOLT = 0.5;
export function veilBolt(b, c, foes, mine) {
  if (c.side !== 'ally') return null;
  const v = foes.find((f) => f.veil && !f.clone);
  if (!v) return null;
  if (!b.knowsTemple && !(MONSTERS[v.species]?.phantom && !b.templeNaive && !b.phNaive && b.rng.chance(PHANTOM_BOLT))) return null;
  const bolt = mine.filter(({ a }) => hasBolt(a.effect) && a.effect.type !== 'gather').sort((x, y) => (y.a.mp || 0) - (x.a.mp || 0))[0];
  if (!bolt) return null;
  return ['enemies', 'allies', 'self'].includes(bolt.a.target) ? { type: 'ability', id: bolt.id } : { type: 'ability', id: bolt.id, target: v.id };
}

// 大波の 前ぶれに 気づかない 人（b.templeNaive）は、ふつうの「大技に そなえる」も しない
export function waveIgnored(b, f) {
  return !!b.templeNaive && !!f.waveStage;
}

// 呪文の あたる 敵（ai.js の chooseAttack の みつもり）
function spellTargets(b, c, a, target) {
  const foes = b.sideOf(c, false).filter((x) => x.alive);
  if (a.target === 'enemies') return foes;
  const t = b.get(target);
  if (!t) return [];
  if (a.target === 'group') return foes.filter((x) => x.species === t.species);
  return [t];
}

// こうげきの えらびかた（ai.js の chooseAttack。opts の final を かえる）:
// 光っている 敵に 呪文は 使わない（知らない 人を のぞく）。知っている 人は 鏡写しを さけ、水のろうを 先に こわす
export function templeAdjust(b, c, opts) {
  if (c.side !== 'ally' || b.templeNaive) return;
  for (const o of opts) {
    const cmd = o.cmd;
    const t = b.get(cmd.target);
    if (b.knowsTemple && t?.species === PRISON && cmd.type !== 'ability') o.final *= 4;
    if (cmd.type !== 'ability') continue;
    const a = ABILITIES[cmd.id];
    if (b.knowsTemple && t?.species === PRISON && a?.target === 'enemy') o.final *= 4;
    if (!isSpell(a) || !foeKinds.has(a.target)) continue;
    const ts = spellTargets(b, c, a, cmd.target);
    // 光っている 敵: 呪文しか ない ときは 身を 守って 光が 消えるのを まつ（反撃の構えと おなじ。ai.js の risky）
    if (ts.some((x) => x.reflect)) {
      o.final *= 0.05;
      o.risky = true;
    }
    // （影の城の モルガナのまぼろし〈phantom〉は、ふつうの オートも おなじ 呪文を つづけない。第5章 Step 8）
    else if (ts.some((x) => MONSTERS[x.species]?.mirrorCopy && !x.clone && x.lastSpell === cmd.id && (b.knowsTemple || MONSTERS[x.species]?.phantom))) o.final *= 0.05;
  }
}

// ───────────── がめんへ ─────────────
// pub（battle.js）に まぜる
// （がめんは 前の じょうほうに 上がきするので、敵は 消えた ときも 0・null を おくる）
export function templePub(c) {
  if (c.side !== 'enemy') return {};
  const out = { reflect: c.reflect?.kind || null, wave: c.waveStage || 0, veilCharge: !!(c.veilShow || c.veilCharge) };
  if (c.veil !== undefined) out.veil = c.veil ? 1 : 0;
  if (c.mirrorOf) out.mirror = true;
  if (c.inside) out.inside = c.inside;
  return out;
}

// snapshot（battle.js）に まぜる: 水の守りの歌の のこり
export function templeSnap(b) {
  return b.song ? { song: b.song.left } : null;
}

js/shared/battle-tokei.js:
// 第2部 第6章 Step 5「止まった時計塔」の 戦いの しかけ（battle-road.js・battle-ch6.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・カリヨン（monsters-tokei.js の ch6.kind 'bell'。時計塔 5階の 中ボス）「時のかね」
//   かねの しるし（bell.left。はじめは bell.every）が、カリヨンが 1回 動く たびに 1つ へる（動けない 番も 数える）。
//   しるしが 1つの ときに カリヨンが 動くと、かならず「時のかね」（m6t_cr_bell）:
//     味方の バフ（強くなった 力）と、カリヨンの デバフ（弱くなった 力）が ぜんぶ 消える（ボスの 段階の ずっと つづく 物は のこる）
//     → みんなに 物理の 強い 一撃（身を 守ると 半分）→ しるしは また いっぱい
//   知っている 人: かねが 鳴った すぐ あとに 強くする（鳴る 前に かけると むだ）・しるしが 1つの ときは 身を 守る
// ・オート（ai.js の decideAlly）: かねが 近い とき（tokeiQuiet）は 強くする 技を 使わない（第41回の「強さを 見て 技を 決める」に 1つ 足す）
//   ふつうの オートは、かねが 自分の 次の 番より 先に 鳴る とき、HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD。ほかの ボスと おなじ）
// ・シミュレーター（tools/sim-ch6.mjs）の 知っている 人（b.knowsCh6）は tokeiKnow
//   （b.c6NoGuard … しるし 1つで 守らない・b.c6NoBuff … 鳴った あとに 強くしない。しかけを 1つずつ はずして くらべる とき）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { CARILLON } from './data/monsters-tokei.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate } from './battle.js';
import { canUse } from './ai.js';

export { CARILLON };
export const BELL = 'm6t_cr_bell';
// かねが この 数（のこりの しるし）より 近い ときは、オートは 強くする 技を 使わない（鳴ると 消えて むだに なる）
export const QUIET_AT = 2;

// c6 … その 戦いだけの しかけの 数（ゼンマイ。battle-tokei6.js）
const bellConf = (m) => (m?.c6 || MONSTERS[m?.species]?.ch6)?.bell || null;
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});
const FOES = new Set(['enemy', 'group', 'enemies']);

// ───────────── はじめ（battle-road.js の setupRoad から。lines に 文を 足す）─────────────
export function setupTokei(b, e, lines) {
  const bc = bellConf(e);
  if (!bc) return;
  const max = bc.every ?? 4;
  e.bell = { left: max, max, rings: 0 };
  lines.push('カリヨンの大きなかねが、カチ…カチ…と、時をきざんでいる…！', `（かねのしるしが${max}つ。全部なくなると、時のかねが鳴るようだ…！）`);
}

// ───────────── 行動の はじめ（battle-road.js の roadTurnStart から）─────────────
// しるしが 1つの ときは この 番が かねの 番（動けない 番は 次の 番に）。それ いがいは 1つ へる
export function tokeiTurnStart(b, c, ev, stuck) {
  if (!c.bell || c.telegraph) return;
  if (c.bell.left <= 1) {
    if (!stuck) c.telegraph = BELL;
  } else {
    c.bell.left--;
    const { left, max } = c.bell;
    ev.lines.push(left > 1 ? `${c.name}のかねのしるしが、1つへった…（のこり${left}/${max}）` : `${c.name}の大きなかねが、ゆらゆらとゆれ始めた…！（のこり1/${max}）`);
    if (left === 1) ev.lines.push('（次にカリヨンが動くと、時のかねが鳴る…！身を守れ！）');
    ev.tkBell = { id: c.id, left, max };
  }
  ev.upd.push(c);
}

// ───────────── 技の こうか（battle-road.js の roadEffect から）─────────────
export function tokeiEffect(b, c, a, eff, ev) {
  if (eff.type !== 'crBell') return false;
  ring(b, c, ev);
  return true;
}

// ずっと つづかない もの（バフ・デバフの のこりが ある もの）を 消す。消した 数
function clearTimed(o) {
  let n = 0;
  for (const [k, v] of Object.entries(o || {})) {
    if (v && Number.isFinite(v.left)) {
      delete o[k];
      n++;
    }
  }
  return n;
}

// 時の かね: 味方の バフ・カリヨンの デバフが 消える → みんなに 物理の 一撃 → しるしは いっぱい
function ring(b, c, ev) {
  const bc = bellConf(c) || {};
  let lost = 0;
  for (const a of b.allies) {
    if (a.fled) continue;
    const n = clearTimed(a.buffs);
    if (n) {
      lost += n;
      ev.upd.push(a);
    }
  }
  const fixed = clearTimed(c.debuffs);
  ev.lines.push('時のかねの音が、塔じゅうにひびきわたった…！');
  if (lost) ev.lines.push('みんなの強くなっていた力が、消えてしまった…！');
  if (fixed) ev.lines.push(`${c.name}の弱くなっていた力も、もとにもどった…！`);
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: 'a6t_bell', actor: c.id, targets: targets.map((t) => t.id), side: 'enemy' };
  for (const t of targets) b.physHit(c, t, { mult: bc.mult ?? 1.5, ignoreDef: bc.ignoreDef ?? 0.3, acc: 1.2 }, ev, 'phys');
  if (c.bell) {
    c.bell.left = c.bell.max;
    c.bell.rings++;
    (ev.postLines = ev.postLines || []).push(`（かねのしるしが、また${c.bell.max}つになった…）`);
  }
  ev.tkRing = { id: c.id, lost, fixed };
  ev.warn = true;
  ev.upd.push(c);
}

// ───────────── かねが 近いか ─────────────
// オートが 強くする 技を ひかえる（ai.js の decideAlly）
export function tokeiQuiet(b) {
  return b.enemies.some((e) => e.alive && e.bell && e.bell.left <= QUIET_AT);
}

// かねが c の 次の 番より 先に 鳴るか（この 番の あと、c の ゲージが たまるまでに カリヨンが のこりの しるしの 数だけ 動く）
export function bellBefore(b, c, boss) {
  if (!boss?.bell || !boss.alive) return false;
  const rb = atbRate(boss);
  if (!(rb > 0)) return false;
  const mine = 100 / atbRate(c);
  const t0 = boss.ready || boss.queued ? 0 : (100 - boss.atb) / rb;
  if (t0 > mine) return false;
  const acts = 1 + Math.floor((mine - t0) / (100 / rb));
  return acts >= boss.bell.left;
}

// ───────────── 知っている 人の オート（battle-ch6.js の ch6Plan から。b.knowsCh6）─────────────
// かねが 自分の 次の 番より 先に 鳴る … 身を 守る / かねが 鳴った すぐ あと（しるしが いっぱい か 1つ へった）… 強くする・弱くする
// （だれかが とても あぶない ときの 回復・生き返りは battle-ch6.js が 先に えらぶ）
export function tokeiKnow(b, c, boss, base) {
  if (!b.c6NoGuard && bellBefore(b, c, boss)) return { type: 'defend' };
  if (!b.c6NoBuff && boss.bell.left >= boss.bell.max - 1) {
    const p = buffPlan(b, c, boss);
    if (p) return p;
  }
  return base;
}

// みんなの 攻撃力を 上げる 技・カリヨンの 守りを 下げる 技で、まだ かかっていない もの
// （守りを 上げる だけの 技〈スクルト など〉と 自分だけを 強くする 技は えらばない。かねの 一撃は 身を 守って ふせぐ。
//   シミュレーターで くらべると、自分だけの 技〈天地の構え など〉まで 使うと 攻める 番が へって 少し 弱く なった）
export function buffPlan(b, c, boss) {
  const allies = b.aliveAllies();
  const stats = (e) => e.stats || [e.stat];
  let debuff = null;
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    if (e.type === 'buff' && a.target === 'allies' && stats(e).includes('atk')) {
      const lack = allies.filter((x) => !x.buffs.atk);
      if (lack.length >= Math.ceil(allies.length / 2)) return { type: 'ability', id };
    } else if (e.type === 'debuff' && FOES.has(a.target) && e.stat === 'def' && !debuff) {
      if (!boss.debuffs.def) debuff = { type: 'ability', id, target: boss.id };
    }
  }
  return debuff;
}

// ───────────── がめんへ（battle-road.js の roadPub から）─────────────
// カリヨン: かねの しるし（bell … のこり・bellMax）
export function tokeiPub(c, o) {
  if (!c.bell) return;
  o.bell = c.bell.left;
  o.bellMax = c.bell.max;
}

js/shared/battle-tokei6.js:
// 第2部 第6章 Step 6「時計塔の心臓」の 戦いの しかけ（battle-ch6.js から 短い よびだしで よぶ。ほかの たたかいは かわらない）
//
// ・影の時計師ゼンマイ（monsters-tokei6.js の ch6.kind 'zen'。10階の ボス）
//   1だんめ … 家来の しかけを じゅんばんに 使う（zen.order: 砂が落ちきる → まきもどし → 時のふりこ → 時のかね）。
//     しかけの 中みは 今の まま（battle-ch6.js の sand・gear、battle-road.js の pend、battle-tokei.js の bell）。
//     ゼンマイの c.c6 に「今の しかけ だけ」の 数を おいて、c.sand など を 1つずつ 作る（confOf が c.c6 を 先に 見る）。
//     しかけが 1回 おわる（大砂流・氷で 止めた／まきもどし・雷で こわした／大ふりこ／時のかね）と、次の しかけへ
//   2だんめ（HP が zen.p2At より へる。battle.js の checkPhase から tokei6Phase）… まわりに 歯車 3つ（べつの 敵。弱点が 氷・雷・光）。
//     文字ばんの 針（zen.hand）が、ゼンマイが 1回 動く たびに 1時間 進む（動けない 番も）。12時に なった 番は かならず「時の大ほうかい」
//     （みんなに とても 大きな 物理の 一撃。身を 守ると 半分）→ 針は hand.start（はじめの 時）に もどる。
//     歯車を こわすと 針が hand.back 時間 もどる（hand.start より 前には もどらない）。こわれた 歯車は、ゼンマイが hand.revive 回 動くと また 回り出す
// ・知っている 人（シミュレーター。b.knowsCh6）: 1だんめは 家来の ときと おなじ（battle-ch6.js の ch6Plan が そのまま 見る）。
//   2だんめは 針が 10時を こえたら 歯車を 弱点で こわす（こわせない なら、大ほうかいが 自分の 番より 先なら 身を 守る）。b.c6NoGear … しない 人
// ・ふつうの オート: 大ほうかいが 自分の 番より 先に 来る とき、HPが へっていれば よく 身を 守る（battle-ch6.js の AUTO_GUARD）
// ・リオンの けいこ（person: 'rion'）… 見た目を リオン（data/companions-tokei.js の RION_GUEST）に する（がめんは 人の 絵）
// ・時のまぼろし（base … もとの ボス）… しかけは もとの まま。がめんと 技の 名前は もとの ボスで 見る（c.base）
import { MONSTERS } from './data/monsters.js';
import { ABILITIES } from './data/abilities.js';
import { ZEN_GEARS } from './data/monsters-tokei6.js';
import { RION_GUEST } from './data/companions-tokei.js';
// たがいに よびあうが、つかうのは たたかいの 中だけ
import { atbRate, pub } from './battle.js';
import { canUse } from './ai.js';
import { applyTimes } from './battle-road.js';

export const COLLAPSE = 'm6z_zm_collapse';
// しかけの おわりの 技（前ぶれ → 大技）。ID は battle-ch6.js・battle-road.js・battle-tokei.js と おなじ
const FALL_CHARGE = 'm6_sc_fall_charge';
const FALL = 'm6_sc_fall';
const RECORD = 'm6_gd_record';
const SWING_CHARGE = 'm6_pd_big_charge';
const SWING = 'm6_pd_big';
const STAGE_TELE = new Set([FALL_CHARGE, FALL, RECORD, 'm6_gd_rewind', 'm6_pd_stop_charge', 'm6_pd_stop', SWING_CHARGE, SWING, 'm6t_cr_bell']);
const ARM = { sand: FALL_CHARGE, pend: SWING_CHARGE };
const FIN = { sand: FALL, pend: SWING };
const FOES = new Set(['enemy', 'group', 'enemies']);
const prim = (a) => (a?.effect?.type === 'multi' ? a.effect.parts?.[0] || {} : a?.effect || {});

export const zenConf = (m) => MONSTERS[m?.species]?.ch6?.zen || null;
export const isZenGear = (m) => !!MONSTERS[m?.species]?.zenGear;
const handOf = (c) => ({ start: 1, max: 12, back: 3, revive: 6, warn: 10, ...(zenConf(c)?.hand || {}) });

// しかけごとの はじめの ことば（家来の 名前で、何を すれば よいか 分かる ように）
const STAGE_INTRO = {
  sand: ['{a}のうしろに、大きな砂時計がうかび上がった…！', '（サンドクロックの力…！砂が落ちきると大砂流。氷でこおらせよう！）'],
  gear: ['{a}のむねで、大きな歯車が、ギリギリと回り始めた…！', '（ギアドンの力…！時を覚えたら、雷を2回当てて歯車をこわそう！）'],
  pend: ['{a}のうしろで、大きなふりこが、ゆれ始めた…！', '（ペンデュラの力…！ねらわれた人と、大ふりこの前は、身を守ろう！）'],
  bell: ['{a}の頭の上に、大きなかねがあらわれた…！', '（カリヨンの力…！かねが鳴る前に、身を守ろう！）'],
};
const fmt = (s, c) => s.replaceAll('{a}', c.name);

// ───────────── はじめ（battle-ch6.js の setupCh6 の さいご）─────────────
export function setupTokei6(b) {
  const lines = [];
  for (const e of b.enemies) {
    const m = MONSTERS[e.species];
    if (!m) continue;
    // 時のまぼろし（もとの ボス）
    if (m.base) e.base = m.base;
    // リオンの けいこ: 人の すがた
    if (m.person === 'rion') {
      e.person = 'rion';
      e.look = RION_GUEST.look;
      e.job = RION_GUEST.job;
    }
    const zc = zenConf(e);
    if (zc) {
      e.zen = { phase: 1, idx: 0, st: null, armed: false, fire: false, recSeen: false, hand: 0, down: {}, collapses: 0, breaks: 0 };
      e.c6 = { kind: 'zen' };
      lines.push(`${e.name}は、大きな時計の針を、しずかにかまえた…！`, '（家来たちの力を、じゅんばんに使ってくるようだ…！）');
      startStage(b, e, zc.order[0], lines);
    }
  }
  if (lines.length) b.emit({ t: 'msg', lines, dur: 1300 });
}

// しかけを 1つ はじめる（c.c6 に その しかけの 数だけ。じょうたいは 家来と おなじ 形）
function startStage(b, c, st, lines) {
  const z = c.zen;
  const conf = zenConf(c).stages[st] || {};
  Object.assign(z, { st, armed: false, fire: false, recSeen: false });
  c.c6 = { kind: 'zen', [st]: conf };
  if (st === 'sand') c.sand = { lv: conf.max ?? 3, max: conf.max ?? 3, fast: false };
  if (st === 'gear') c.gear = { count: 0, rec: null, left: 0, hits: 0, fast: false };
  if (st === 'pend') {
    c.pend = { pos: -(conf.reach ?? 2), dir: 1, reach: conf.reach ?? 2, target: null, frozen: [] };
    applyTimes(b, c);
  }
  if (st === 'bell') c.bell = { left: conf.every ?? 4, max: conf.every ?? 4, rings: 0 };
  lines.push(...(STAGE_INTRO[st] || []).map((s) => fmt(s, c)));
}

// しかけを おえる（止まっている 人は 動き出す・ゲージの 速さも もとに）
function endStage(b, c, ev) {
  delete c.sand;
  delete c.gear;
  delete c.bell;
  if (c.pend) {
    delete c.pend;
    c.tmul = 1;
    for (const a of b.allies) {
      if (a.tstop > 0 && a.alive) {
        ev?.lines.push(`${a.name}の時が、また動き出した！`);
        ev?.upd.push(a);
      }
      a.tstop = 0;
      a.tmul = 1;
    }
  }
  if (STAGE_TELE.has(c.telegraph)) c.telegraph = null;
  c.c6 = { kind: 'zen' };
  c.zen.st = null;
}

// ───────────── 行動の はじめ（battle-ch6.js の ch6TurnStart の はじめ。しかけの 数を 数える 前）─────────────
export function tokei6TurnStart(b, c, ev, stuck) {
  const z = c.zen;
  if (!z) return;
  if (z.phase === 1) {
    const st = z.st;
    let done = false;
    if (z.fire) done = true;
    else if (z.armed) {
      // 前ぶれの 次: 大技が 出る（つぎの 番で おわり）か、氷で 止められた（ここで おわり）
      if (c.telegraph === FIN[st]) z.fire = true;
      else done = true;
    } else if (st === 'gear') done = z.recSeen && c.gear?.rec === null;
    else if (st === 'bell') done = (c.bell?.rings || 0) > 0;
    if (done) {
      endStage(b, c, ev);
      const order = zenConf(c).order;
      z.idx = (z.idx + 1) % order.length;
      startStage(b, c, order[z.idx], ev.lines);
      ev.zenStage = { id: c.id, st: z.st };
      ev.upd.push(c, ...b.allies);
    }
    return;
  }
  // 2だんめ: こわれた 歯車が また 回り出す → 針が 1時間 進む → 12時なら 時の大ほうかい
  const hc = handOf(c);
  const back = [];
  for (const g of b.enemies) {
    if (!isZenGear(g) || g.alive || g.fled) continue;
    const n = (z.down[g.id] ?? hc.revive) - 1;
    if (n > 0) {
      z.down[g.id] = n;
      continue;
    }
    delete z.down[g.id];
    Object.assign(g, { alive: true, hp: g.maxHp, status: {}, buffs: {}, debuffs: {}, ready: false, queued: false, telegraph: null });
    g.atb = 0;
    // 経験値は 1回 たおした ぶんだけ（歯車は 0 だが、図鑑の 数も ふやさない）
    const k = b.killed.lastIndexOf(g.species);
    if (k >= 0) b.killed.splice(k, 1);
    back.push(g.id);
    ev.lines.push(`${g.name}が、また回り出した…！`);
    ev.upd.push(g);
  }
  if (back.length) ev.zenRevive = back;
  if (c.telegraph) return;
  z.hand = Math.min(hc.max, z.hand + 1);
  if (z.hand >= hc.max) {
    if (!stuck) c.telegraph = COLLAPSE;
    ev.lines.push('文字ばんの針が、12時をさした…！');
  } else {
    ev.lines.push(`文字ばんの針が、${z.hand}時に進んだ…（12時で、時の大ほうかい）`);
    if (z.hand === hc.max - 1) ev.lines.push(`（次に${c.name}が動くと、時の大ほうかい…！歯車をこわすか、身を守れ！）`);
    else if (z.hand === hc.warn) ev.lines.push('（針が10時になった…！歯車をこわせば、針がもどる！）');
  }
  ev.zenHand = { id: c.id, hand: z.hand, max: hc.max };
  ev.upd.push(c);
}

// ───────────── 行動の はじめ（ch6TurnStart の さいご。しかけの 前ぶれを 見る）─────────────
export function tokei6TurnEnd(b, c) {
  const z = c.zen;
  if (!z || z.phase !== 1) return;
  if (ARM[z.st] && c.telegraph === ARM[z.st]) z.armed = true;
  if (z.st === 'gear' && c.telegraph === RECORD) z.recSeen = true;
}

// ───────────── 2だんめへ（battle.js の checkPhase から。ダメージを うけた すぐ あと）─────────────
export function tokei6Phase(b, t, ev) {
  const z = t.zen;
  if (!z || z.phase !== 1 || !t.alive) return;
  if (t.hp / t.maxHp >= (zenConf(t).p2At ?? 0.5)) return;
  endStage(b, t, ev);
  z.phase = 2;
  z.hand = handOf(t).start;
  t.c6 = { kind: 'zen' };
  const room = 7 - b.aliveEnemies().length;
  const list = Object.values(ZEN_GEARS).slice(0, Math.max(0, room));
  const added = list.length ? b.addEnemies(list) : [];
  for (const g of added) g.atb = 0;
  if (added.length) ev.joined = (ev.joined || []).concat(added.map(pub));
  ev.phaseLines = (ev.phaseLines || []).concat(
    `${t.name}のまわりに、${added.length}つの歯車があらわれた！`,
    `（${t.name}が動くたびに、針が1時間進む…12時で、時の大ほうかい…！）`,
    '（歯車は、弱点でこわせば、針がもどりそうだ…！ほのおの歯車は氷・水の歯車は雷・影の歯車は光）',
  );
  ev.zenP2 = t.id;
  ev.warn = true;
  ev.upd.push(t, ...b.allies);
}

// ───────────── たおれた（battle-ch5.js の towerKill から）─────────────
// 歯車が こわれる と 針が もどる
export function tokei6Kill(b, t, ev) {
  if (!isZenGear(t)) return;
  const boss = b.enemies.find((e) => e.zen && e.alive);
  if (!boss || boss.zen.phase !== 2) return;
  const hc = handOf(boss);
  const z = boss.zen;
  const was = z.hand;
  z.hand = Math.max(hc.start, z.hand - hc.back);
  z.down[t.id] = hc.revive;
  z.breaks++;
  if (!ev) return;
  (ev.postLines = ev.postLines || []).push(`${t.name}がくだけた！`, was > z.hand ? `文字ばんの針が、${was - z.hand}時間もどった！（今は${z.hand}時）` : '（針は、もうもどらない…）');
  ev.zenBack = { id: boss.id, hand: z.hand, gear: t.id };
  ev.upd.push(boss);
}

// ───────────── 技の こうか（battle-ch6.js の ch6Effect の のこり）─────────────
export function tokei6Effect(b, c, a, eff, ev) {
  if (eff.type !== 'zenCollapse') return false;
  const cf = zenConf(c)?.collapse || {};
  const targets = b.aliveAllies();
  ev.fx = { type: 'ability', anim: a.anim || 'a6z_collapse', actor: c.id, targets: targets.map((t) => t.id), side: 'enemy' };
  for (const t of targets) b.physHit(c, t, { mult: cf.mult ?? 1.55, ignoreDef: cf.ignoreDef ?? 0.5, acc: 1.2 }, ev, 'phys');
  if (c.zen) {
    c.zen.hand = handOf(c).start;
    c.zen.collapses++;
    (ev.postLines = ev.postLines || []).push(`（文字ばんの針が、また${c.zen.hand}時にもどった…）`);
  }
  ev.zenCollapse = c.id;
  ev.warn = true;
  ev.upd.push(c);
  return true;
}

// ───────────── 大ほうかいが 近いか ─────────────
// ゼンマイが c の 次の 番までに 何回 動くか
export function bossActsBefore(b, c, boss) {
  const rb = atbRate(boss);
  if (!(rb > 0) || !boss.alive) return 0;
  const mine = 100 / atbRate(c);
  const t0 = boss.ready || boss.queued ? 0 : (100 - boss.atb) / rb;
  if (t0 > mine) return 0;
  return 1 + Math.floor((mine - t0) / (100 / rb));
}
// 大ほうかいが c の 次の 番より 先に 来るか（ふつうの オートの 守り。battle-ch6.js の ch6Plan）
export function collapseBefore(b, c, boss) {
  const z = boss?.zen;
  if (!z || z.phase !== 2) return false;
  if (boss.telegraph === COLLAPSE) return true;
  return bossActsBefore(b, c, boss) >= handOf(boss).max - z.hand;
}

// その 属性の 技で いちばん ダメージの 大きい もの（{ cmd, dmg }。battle-ch6.js の elemHit と おなじ 見かた）
function elemBest(b, c, t, el) {
  let best = null;
  for (const id of c.abilities || []) {
    const a = ABILITIES[id];
    if (!a || !FOES.has(a.target) || c.autoOff?.includes(id) || a.noAuto || !canUse(b, c, id)) continue;
    const e = prim(a);
    if (e.element !== el) continue;
    let dmg = 0;
    if (e.type === 'phys') {
      const r = b.calcPhys(c, t, e, 1, el, true);
      dmg = r.dmg * r.hit * (e.random ? 1 : e.hits || 1);
    } else if (e.type === 'magic') dmg = b.calcMagic(c, t, e, 1, true).dmg;
    else continue;
    if (!best || dmg > best.dmg) best = { cmd: { type: 'ability', id, target: t.id }, dmg };
  }
  return best;
}

// ───────────── 知っている 人の オート（battle-ch6.js の ch6Plan から。b.knowsCh6。2だんめ）─────────────
// 針が 10時を こえたら 歯車を 弱点で（こわせる 物を 先に）/ こわせない ときは、大ほうかいが 自分の 番より 先なら 身を 守る
export function tokei6Know(b, c, boss, base) {
  const z = boss.zen;
  if (!z || z.phase !== 2) return base;
  const hc = handOf(boss);
  const soon = collapseBefore(b, c, boss);
  if (z.hand >= hc.warn && !b.c6NoGear) {
    let pick = null;
    for (const g of b.aliveEnemies().filter(isZenGear)) {
      const h = elemBest(b, c, g, MONSTERS[g.species].zenGear);
      if (!h) continue;
      const kill = h.dmg >= g.hp;
      if (!pick || kill > pick.kill || (kill === pick.kill && h.dmg > pick.dmg)) pick = { ...h, kill };
    }
    if (pick && (pick.kill || !soon)) return pick.cmd;
  }
  if (soon && !b.c6NoGuard) return { type: 'defend' };
  return base;
}

// ───────────── がめんへ（battle-ch6.js の ch6Pub の さいご）─────────────
// zen … だん（1・2）・zenSt … 1だんめの 今の しかけ・kindAs … その しかけの 家来（がめんは 家来の 目もり・バナーを そのまま 使う）・
// hand・handMax・handWarn … 2だんめの 針 / zenGear … 歯車の 弱点 / base … 時のまぼろしの もとの ボス / person … 人の すがた（リオン）
const STAGE_KIND = { sand: 'sand_clock', gear: 'geardon', pend: 'pendula', bell: 'carillon' };
export function tokei6Pub(c, o) {
  if (c.base) o.base = c.base;
  if (c.person) o.person = c.person;
  const gw = MONSTERS[c.species]?.zenGear;
  if (gw) o.zenGear = gw;
  const z = c.zen;
  if (!z) return;
  o.zen = z.phase;
  o.zenSt = z.st;
  if (z.phase === 1 && STAGE_KIND[z.st]) o.kindAs = STAGE_KIND[z.st];
  if (z.phase === 2) {
    const hc = handOf(c);
    o.hand = z.hand;
    o.handMax = hc.max;
    o.handWarn = hc.warn;
  }
}

