  esports_king: [1, 0.81, 1.1], gold_cardman: [2.34, 2.2, 2.84], psychicer: [1.73, 1.75, 1.95],
  game_god: [1.02, 0.88, 1.07], black_cardman: [1.07, 0.98, 1.15], saiki: [1.39, 1.28, 1.55],
