// バトルエンジン（リアルタイム・ターン制）
//
// ・ひとりひとりに「こうどうゲージ」があり、すばやさが 高いほど はやく たまる
// ・ゲージが たまった キャラクターから コマンドを えらんで こうどうする
// ・コマンドを えらんでいる あいだも 時間は すすむ（ウェイトモードを のぞく）
// ・こうどうの えんしゅつ中は ゲージが とまる（メッセージが よめるように）
//
// サーバー（家族サーバー）でも ブラウザ（ひとりモード）でも おなじ コードが うごく

import { makeRng } from './rng.js';
// 第53回 D: 色ちがいの 仲間の 絵（data/variants.js）
import { colorMon } from './data/variants.js';
import { ABILITIES, ELEMENT_ORDER, ELEMENT_NAMES } from './data/abilities.js';
// 推理（deduce）で ねらう 属性（第26回の 探ていの 技）
import { deduceElement } from './data/abilities-jobs6.js';
import { HIRAMEKI, hiraChance, hiraRatio } from './data/hirameki.js';
// 合体技（2人・3人・4人。battle-dual.js）
import { optionsFor, validateDual, startDual, checkWaits, waitStillOk, fireWait, endWait, releasePartners, answerDual, endInvite, performDual, partnersOf, dualHurt, dualRecharged } from './battle-dual.js';
import { MONSTERS } from './data/monsters.js';
import { ITEMS } from './data/items.js';
import { JOBS } from './data/jobs.js';
import { computeStats, learnedAbilities, penaltyFor, mpCost, weaponOk, comboAllowed, hiraAllowed, battleAbilityOk } from './stats.js';
import { decideMonster, decideAlly } from './ai.js';
