// 攻撃呪文かどうか（魔法剣で使える）
export function isAttackSpell(id) {
  const a = ABILITIES[id];
  return !!(a && a.attackSpell);
}

// 剣技かどうか（魔法剣で使える）
export function isSwordSkill(id) {
  const a = ABILITIES[id];
  return !!(a && a.sword);
}

export const ELEMENT_NAMES = {
  fire: '炎', ice: '氷', water: '水', wind: '風', blast: '爆発', bolt: '雷', light: '光', dark: '闇', void: '消滅',
};
// 敵の 得手不得手を しらべる 属性（図鑑に のる じゅん）。水は 第47回（data/water.js）
export const ELEMENT_ORDER = ['fire', 'ice', 'water', 'wind', 'blast', 'bolt', 'light', 'dark'];

// 技の 種類（色分け）: dmg=ダメージ heal=回復 sup=補助
const DMG_TYPES = new Set(['phys', 'magic', 'drainHp', 'drainMp', 'mahouken', 'telegraph', 'multi', 'goldThrow', 'gamble', 'fixed', 'allMp', 'gather', 'genki', 'destroy', 'deduce']);
const HEAL_TYPES = new Set(['heal', 'revive', 'cure', 'mpHeal', 'regen']);
export const ROLE_NAMES = { dmg: 'ダメージ', heal: '回復', sup: '補助' };
export function abilityRole(a) {
  const t = a?.effect?.type;
  if (a?.role) return a.role;
  if (DMG_TYPES.has(t)) return 'dmg';
  if (HEAL_TYPES.has(t)) return 'heal';
  return 'sup';
}

// せつめいの 見出し（例:「炎属性のダメージ呪文」「回復の呪文」「補助の特技」）
export function abilityTypeText(a) {
  if (!a) return '';
  const kind = a.kind === 'spell' || a.spellLike ? '呪文' : a.kind === 'combo' ? '掛け合わせ技' : '特技';
  const el = a.effect?.element;
  return `${ELEMENT_NAMES[el] ? `${ELEMENT_NAMES[el]}属性の` : ''}${ROLE_NAMES[abilityRole(a)]}の${kind}`;
}

