export function potSteps(out, merge = false) {
  if (merge) return 40;
  const it = ITEMS[out];
  if (!it || it.type === 'use' || it.type === 'mat') return 30;
  const r = it.rarity || 0;
  return r >= 4 ? 60 : r === 3 ? 50 : 40;
}

