  { a: 'king_pururin', b: 'pururin_knight', child: 'queen_pururin' },
  { a: 'king_pururin', b: TREASURE_KIN, child: 'gold_pururin' },
  { a: { race: 'plant' }, b: { race: 'demon', minRank: D }, child: 'rose_queen' },
