// 第44回: ミュウ（進化した ポケモン 2ひき ＋ ふしぎないでんし）
MATERIAL_RECIPES.push(...MATERIAL_RECIPES_POKEMON);
// 第45回: こよみのせいれい（せいれい系 2ひき ＋ 四季のこよみ）・竜王のまご（ドラゴン系 2ひき ＋ 竜王のしるし）
MATERIAL_RECIPES.push(...MATERIAL_RECIPES_DQM);
export { MATERIAL_RECIPES, FOUR_RECIPES };

function specMatch(spec, sp, MONSTERS) {
  if (typeof spec === 'string') return spec === sp;
  const m = MONSTERS[sp];
  if (!m) return false;
  if (spec.race && m.race !== spec.race) return false;
  if (spec.flying !== undefined && !!m.flying !== spec.flying) return false;
  if (spec.minRank !== undefined && rankIdx(sp, MONSTERS) < spec.minRank) return false;
  // 第44回: { any: [しゅぞくID…] } … その どれか（かみなりの魔物・ほのおの魔物 など。companions-pokemon.js）
  if (Array.isArray(spec.any) && !spec.any.includes(sp)) return false;
  return true;
}

// 特定配合（しゅぞくID が 入った 組み合わせ）か
const isSpecialRecipe = (r) => typeof r.a === 'string' || typeof r.b === 'string';
const recipeMatch = (r, spA, spB, MONSTERS) =>
  (specMatch(r.a, spA, MONSTERS) && specMatch(r.b, spB, MONSTERS)) || (specMatch(r.a, spB, MONSTERS) && specMatch(r.b, spA, MONSTERS));

// その 系統で 系統配合から 生まれる ことが ある 魔物（仲間に なる 魔物。ボス・メタル・きまった 組み合わせ だけの 魔物は のぞく）
export function familyPool(race, MONSTERS) {
  return Object.keys(MONSTER_FRIENDS).filter((sp) => {
    const m = MONSTERS[sp];
    return m && m.race === race && !m.boss && !m.metal && !MONSTER_FRIENDS[sp].recipeOnly && !MONSTER_FRIENDS[sp].noFamily;
  });
}

// 第53回 A: 系統まぜ配合の 子（2つの 系統の どちらかの 魔物。breed-mix.js の 表 ＋ MONSTER_FRIENDS の mix）
//   ボス・メタル・SS・きまった 組み合わせ だけの 魔物・進化の すがたは 入れない
const mixMemo = new Map();
export function mixPool(raceA, raceB, MONSTERS) {
  if (!raceA || !raceB || raceA === raceB) return [];
  const key = mixKey(raceA, raceB);
  if (mixMemo.has(key)) return mixMemo.get(key);
  const ids = new Set(MIX_TABLE[key] || []);
  for (const [sp, f] of Object.entries(MONSTER_FRIENDS)) {
    const r = MONSTERS[sp]?.race;
    if (Array.isArray(f.mix) && (r === raceA || r === raceB) && f.mix.includes(r === raceA ? raceB : raceA)) ids.add(sp);
  }
  const out = [...ids].filter((sp) => {
    const m = MONSTERS[sp], f = MONSTER_FRIENDS[sp];
    return m && f && (m.race === raceA || m.race === raceB) && !m.boss && !m.metal && !f.recipeOnly && !EVOLVE_FROM[sp] && rankIdx(sp, MONSTERS) <= RANK_S;
  });
  mixMemo.set(key, out);
  return out;
}
// その 魔物が まぜの 子に なる 相手の 系統（図鑑の ヒント）
export function mixRacesOf(sp, MONSTERS) {
  const own = MONSTERS[sp]?.race;
  return Object.keys(RACE_NAMES).filter((r) => r !== 'human' && r !== own && mixPool(own, r, MONSTERS).includes(sp));
}

// ボス級（ランク SS）の 仲間（monsters-boss.js）
export function bossClassList(MONSTERS) {
  return Object.keys(MONSTER_FRIENDS).filter((sp) => MONSTER_FRIENDS[sp].rank === 'SS' && MONSTERS[sp]);
}

const lvOf = (x) => (Number.isFinite(x?.level) ? x.level : BREED_MIN_LEVEL);
const plusOf = (x) => Math.max(0, Math.floor(x?.plus || 0));
// 1つ上の ランクの 子も 候補に 入る（親を 育てると）: 両親の レベルの 合計 ＋ ＋の 合計の 半分 が この 数 いじょう
//   F どうし Lv10＋Lv10 → E も。ランクが 1つ上がるごとに 8 ふえる
//   第43回 A: B から 上は きびしく（B→A 80・A→S 100。前は 60・68）
export const rankUpNeed = (hi) => (hi >= 4 ? 80 + 20 * (hi - 4) : 20 + 8 * hi);
export const rankUpOk = (a, b, hi) => lvOf(a) + lvOf(b) + Math.floor((plusOf(a) + plusOf(b)) / 2) >= rankUpNeed(hi);
// ランク配合（S × S → SS）の 親の レベル。第43回 A で ランク配合は やめた（SS は 素材配合と 4体配合だけ）。前の テスト・画面の ために 数は のこす
export const RANK_BREED_LV = 30;

// ふくろに その 品が あるか（装備して いる 物は 数えない。c が ない ときは ない もの と する）
//   第44回: 大事な物（ふしぎないでんし）も 見る（c.keyItems）
const hasItem = (c, id) => (Array.isArray(c?.items) && c.items.some((e) => e && e.id === id && e.n > 0))
  || (Array.isArray(c?.keyItems) && c.keyItems.includes(id));
// 第45回: レシピの レベルの じょうけん（minLv。どちらの 親も その レベル いじょう）
const recipeLvOk = (r, a, b) => !r.minLv || (lvOf(a) >= r.minLv && lvOf(b) >= r.minLv);
// その 親が 4体配合の 親に なれるか（両親が みんな sp）
const fourOk = (x, sp) => x.species === sp && Array.isArray(x.lineage?.p) && x.lineage.p.length === 2 && x.lineage.p.every((p) => p === sp);

// ならびの じゅん: きまった 組み合わせ → 新生配合 → そのほか（ランクの 高い じゅん → 図鑑で 見ていない じゅん → まぜの 子 → 強い じゅん → ID）。親より ランクの 低い 子は さいご
//   まぜの 子（mix）は 同じ ランクの 系統配合より 先。ランクの 高い 子を 下げる ことは ない
const KIND_PRI = { four: 0, material: 0, special: 1, recipe: 1, same: 2, mix: 3, parent: 3, family: 3 };
export const SPECIAL_KINDS = ['four', 'material', 'special', 'recipe'];

// まぜの 子の ならびの 数（親の 組み合わせ ＋ 子の しゅぞくID から きまる）
function mixOrd(pairKey, sp) {
  let h = 0x811c9dc5;
  for (const ch of `${pairKey}>${sp}`) h = Math.imul(h ^ ch.charCodeAt(0), 0x01000193);
  return h >>> 0;
}

// 生まれる 子の 候補（a・b は { species, level, plus, lineage }。c … 品を もつ キャラ）
//   list: しゅぞくID の ならび（いちばん 上が おすすめ）/ items: { sp, kind, rank, item? } / hi: 高いほうの 親の ランク / up: 1つ上の ランクも 入るか
//   どちらを 1ぴきめに しても 同じ（両方の 親の 系統・組み合わせは どちら向きでも・さいごに ならびなおす）
export function breedCandidates(a, b, MONSTERS, c = null) {
  const spA = a.species, spB = b.species;
  const ra = rankIdx(spA, MONSTERS), rb = rankIdx(spB, MONSTERS);
  const hi = Math.max(ra, rb);
  const up = rankUpOk(a, b, hi);
  const found = new Map();
  const add = (sp, kind, extra = {}) => {
    if (!MONSTERS[sp] || !MONSTER_FRIENDS[sp] || found.has(sp)) return;
    found.set(sp, { sp, kind, rank: rankIdx(sp, MONSTERS), ...extra });
  };
  for (const r of FOUR_RECIPES) if (fourOk(a, r.all) && fourOk(b, r.all)) add(r.child, 'four');
  for (const r of MATERIAL_RECIPES) if (hasItem(c, r.item) && recipeMatch(r, spA, spB, MONSTERS)) add(r.child, 'material', { item: r.item });
  // 第43回 A: ランク配合（S どうし → SS）は やめた。SS は 素材配合（ボスの 品 ＋ 2ひき）と 4体配合だけ
  // 第45回: minLv（S の 特定配合）… どちらの 親も その レベル いじょう
  // 第69回: しゅぞくID が 2つの 組み合わせ（くわしい 方）を、系統で 書いた 組み合わせより 先に（ids）
  for (const r of BREED_RECIPES) if (isSpecialRecipe(r) && recipeMatch(r, spA, spB, MONSTERS) && recipeLvOk(r, a, b)) add(r.child, 'special', { ids: [r.a, r.b].filter((x) => typeof x === 'string').length });
  for (const r of BREED_RECIPES) if (!isSpecialRecipe(r) && recipeMatch(r, spA, spB, MONSTERS)) add(r.child, 'recipe');
  if (spA === spB) add(spA, 'same');
  // 第53回 C: 1つ下の ランクも えらべる（おすすめには ならない。ならびの さいご）
  const ranks = [...(hi > 0 ? [hi - 1] : []), hi, ...(up ? [hi + 1] : [])];
  const raceA = MONSTERS[spA]?.race, raceB = MONSTERS[spB]?.race;
  // 第53回 A: 系統まぜ配合（ちがう 系統の 親 どうし）
  for (const sp of mixPool(raceA, raceB, MONSTERS)) if (ranks.includes(rankIdx(sp, MONSTERS))) add(sp, 'mix');
  for (const race of new Set([raceA, raceB])) {
    if (!race) continue;
    for (const sp of familyPool(race, MONSTERS)) if (ranks.includes(rankIdx(sp, MONSTERS))) add(sp, 'family');
  }
  for (const sp of [spA, spB]) if (rankIdx(sp, MONSTERS) === hi) add(sp, 'parent');
  // 第53回 B: 同じ しゅるい・同じ ランクの 中では、図鑑で まだ 見ていない → 見た → 仲間に した の じゅん。その 次に まぜの 子
  //   まぜの 子 どうしは 親の 組み合わせで きまる じゅん（mixOrd。同じ 親なら いつも 同じ・親が かわると おすすめも かわる）
  const know = bestiaryKnow(c);
  const pairKey = [spA, spB].sort().join('|');
  const items = [...found.values()].sort((x, y) => (x.rank < hi) - (y.rank < hi) || KIND_PRI[x.kind] - KIND_PRI[y.kind]
    || (y.ids || 0) - (x.ids || 0) || y.rank - x.rank || know(x.sp) - know(y.sp) || (x.kind !== 'mix') - (y.kind !== 'mix')
    || (x.kind === 'mix' && y.kind === 'mix' ? mixOrd(pairKey, x.sp) - mixOrd(pairKey, y.sp) : 0)
    || (MONSTERS[y.sp].lv || 0) - (MONSTERS[x.sp].lv || 0) || (x.sp < y.sp ? -1 : x.sp > y.sp ? 1 : 0));
  return { list: items.map((x) => x.sp), items, hi, up };
}

// 図鑑で その 魔物を どこまで 知っているか（0: 見たことがない / 1: 見たことは ある / 2: 仲間に したことが ある）
// c … キャラ（bestiary・kills。図鑑と おなじ 数えかた）。c が ない ときは みんな 0（見たことがない）
export function bestiaryKnow(c) {
  if (typeof c === 'function') return c;
  const bs = c?.bestiary || {}, kills = c?.kills || {};
  return (sp) => {
    const b = bs[sp] || {};
    if ((b.friend || 0) > 0 || (b.bred || 0) > 0) return 2;
    if ((b.seen || 0) > 0 || (kills[sp] || 0) > 0) return 1;
    return 0;
  };
}

// うまれる こどもの「＋」: 両親の ＋の 合計÷2 ＋ 両親の レベルで 少し（新生配合〈same〉は 大きく）
export function breedPlus(a, b, same = false) {
  const base = Math.floor((plusOf(a) + plusOf(b)) / 2);
  const L = lvOf(a) + lvOf(b);
  return Math.min(99, base + (same ? Math.max(5, Math.floor(L / 5)) : Math.max(1, Math.floor(L / 10))));
}

// どんな まものが うまれるか（おすすめ〈いちばん 上〉の 子。MONSTERS を わたす: data どうしの じゅんかんを さける）
export function breedResult(spA, spB, MONSTERS, c = null) {
  return breedOutcome({ species: spA, level: BREED_MIN_LEVEL }, { species: spB, level: BREED_MIN_LEVEL }, MONSTERS, c).child;
}

// うまれる こ。a・b は { species, level, plus, lineage }、c は 図鑑と ふくろを もつ キャラ、pick は えらんだ 子（なければ おすすめ）
// サーバーの はいごう（world/breed.js）と、酒場の 一覧の みほん（client/ui/services.js）で つかう
//   child: 生まれる しゅぞく / ok: pick が 候補に あったか / plus: 「＋」/ rank: ランク / kind: 上の 配合の しゅるい / item: 使う 品
//   special: 親と ちがう しゅぞく / unseen: 図鑑に のっていない / firstFriend: はじめて 仲間に なる
//   count・unseenCount: 候補の 数・その うち 図鑑に のっていない 数 / list・items: 候補（breedCandidates）
export function breedOutcome(a, b, MONSTERS, c = null, pick = null) {
  const know = bestiaryKnow(c);
  const cand = breedCandidates(a, b, MONSTERS, c);
  const it = (pick && cand.items.find((x) => x.sp === pick)) || cand.items[0];
  const child = it.sp;
  const k = know(child);
  return {
    child, ok: !pick || it.sp === pick, kind: it.kind, item: it.item || null, rank: RANKS[it.rank], low: it.rank < cand.hi,
    plus: breedPlus(a, b, it.kind === 'same'), special: child !== a.species && child !== b.species,
    unseen: k === 0, firstFriend: k < 2,
    count: cand.list.length, unseenCount: cand.list.filter((sp) => know(sp) === 0).length,
    list: cand.list, items: cand.items, hi: RANKS[cand.hi], up: cand.up,
  };
}

// ずかんの ヒント（例: 「スライム系 ＋ スライム系」）。系統配合だけで 生まれる 魔物は「植物系 ＋ どの魔物でも（強い親から）」
// ボス級（SS）は 名前を 出さない（図鑑では ？？？）
export function recipeHint(child, MONSTERS) {
  // 第44回: きまった ヒント（ミュウ）・進化で 生まれる すがた（「ヒトカゲがLv25で進化」）
  if (MONSTER_FRIENDS[child]?.hint) return MONSTER_FRIENDS[child].hint;
  const evo = evolveHint(child, MONSTERS);
  if (evo) return evo;
  if (MONSTER_FRIENDS[child]?.rank === 'SS') return 'ボスの品 ＋ Sランク2ひき（配合でしか会えない）';
  const r = BREED_RECIPES.find((x) => x.child === child);
  // 第44回: label（かみなりの魔物 など）・minRank（「Dランク以上」。前から ある レシピには minRank は ない）
  const nm = (spec) => (typeof spec === 'string' ? MONSTERS[spec]?.name : spec.label ? spec.label : spec.flying ? '空を飛ぶ魔物'
    : `${RACE_NAMES[spec.race] || '？'}${spec.minRank !== undefined ? `（${RANKS[spec.minRank]}ランク以上）` : ''}`);
  if (r) return `${nm(r.a)} ＋ ${nm(r.b)}${r.minLv ? `（どちらもLv${r.minLv}以上）` : ''}`;
  const f = MONSTER_FRIENDS[child];
  if (f?.breedOnly && !f.recipeOnly && MONSTERS[child]) return `${RACE_NAMES[MONSTERS[child].race]} ＋ どの魔物でも（強い親から）`;
  // 第53回 A: 系統まぜ配合で 生まれる 魔物（「けもの系 ＋ ドラゴン系」。2つまで）
  const mx = MONSTERS[child] ? mixRacesOf(child, MONSTERS) : [];
  if (mx.length) return mx.slice(0, 2).map((r) => `${RACE_NAMES[MONSTERS[child].race]} ＋ ${RACE_NAMES[r]}`).join('／');
  return '';
}

// 酒場の うわさ: まだ 見たことがない 配合だけの 魔物の ヒント（弱い じゅんに n こ）
export function breedRumors(c, MONSTERS, n = 3) {
  const know = bestiaryKnow(c);
  return Object.keys(MONSTER_FRIENDS)
    .filter((sp) => MONSTER_FRIENDS[sp].breedOnly && MONSTERS[sp] && know(sp) === 0 && !EVOLVE_FROM[sp])
    .sort((x, y) => MONSTERS[x].lv - MONSTERS[y].lv)
    .slice(0, n)
    .map((sp) => recipeHint(sp, MONSTERS))
    .filter(Boolean);
}

// ずかんの ならび: ふつうの まもの（つよさじゅん）→ はいごう だけの まもの（つよさじゅん）→ ボス（client/ui/menu.js）
//   第44回: 進化した すがたは 進化の 前の すがたの すぐ うしろ（ヒトカゲ → リザード → リザードン。イーブイ → 石の 4つ）
export function bestiaryOrder(MONSTERS) {
  const all = Object.keys(MONSTERS);
  const byLv = (a, b) => (MONSTERS[a].lv || 0) - (MONSTERS[b].lv || 0);
  const normal = all.filter((sp) => !MONSTERS[sp].boss && !MONSTERS[sp].breedOnly).sort(byLv);
  const breed = [];
  const line = (sp) => {
    if (breed.includes(sp) || !MONSTERS[sp]) return;
    breed.push(sp);
    for (const to of evolveTargets(sp)) line(to);
    // 第45回: その しゅぞくの うしろに ならぶ 魔物（MONSTER_FRIENDS の after。ドラクエふう）
    for (const nx of BESTIARY_NEXT[sp] || []) line(nx);
  };
  for (const sp of all.filter((x) => MONSTERS[x].breedOnly && !EVOLVE_FROM[x] && !bestiaryAfter(x)).sort(byLv)) line(sp);
  for (const sp of all) if (MONSTERS[sp].breedOnly && !breed.includes(sp)) breed.push(sp);
  return [...normal, ...breed, ...all.filter((sp) => MONSTERS[sp].boss)];
}

// 第45回: 図鑑で すぐ うしろに ならぶ しゅぞく（MONSTER_FRIENDS の after。その しゅぞくは 配合だけの 魔物）
export const bestiaryAfter = (sp) => MONSTER_FRIENDS[sp]?.after || null;
const BESTIARY_NEXT = {};
for (const sp of Object.keys(MONSTER_FRIENDS)) {
  const to = bestiaryAfter(sp);
  if (to) (BESTIARY_NEXT[to] = BESTIARY_NEXT[to] || []).push(sp);
}

// ───────────── 進化（第44回 ポケモン P1。docs/plan-breed-new.md の 2 の C・D）─────────────
// MONSTER_FRIENDS[sp].evolve = { lv, to }（レベルで 進化）・stones = { 品ID: しゅぞくID }（石で 進化）。data/companions-pokemon.js
// 進化の しょり（みまもる／とめる・石を 使う）は world/evolve.js
export const EVERSTONE = 'everstone';
// その しゅぞくが 進化する 先（レベル → 石の じゅん）
export function evolveTargets(sp) {
  const f = MONSTER_FRIENDS[sp];
  if (!f) return [];
  const out = [];
  if (f.evolve?.to) out.push(f.evolve.to);
  for (const to of Object.values(f.stones || {})) if (!out.includes(to)) out.push(to);
  return out;
}
// 進化した すがた → 進化の 前の すがた
export const EVOLVE_FROM = {};
for (const sp of Object.keys(MONSTER_FRIENDS)) for (const to of evolveTargets(sp)) EVOLVE_FROM[to] = sp;
// レベルで 進化する 先（まだ その レベルで ない・かわらずのいしを 装備している ときは null）
export function levelEvolveTo(ch) {
  const ev = MONSTER_FRIENDS[ch?.species]?.evolve;
  if (!ev?.to || !MONSTER_FRIENDS[ev.to] || !((ch.level || 0) >= ev.lv)) return null;
  if (Object.values(ch.equip || {}).includes(EVERSTONE)) return null;
  return ev.to;
}
// 石で 進化する 先（その 石で 進化しない ときは null）
export function stoneEvolveTo(sp, itemId) {
  const to = MONSTER_FRIENDS[sp]?.stones?.[itemId];
  return to && MONSTER_FRIENDS[to] ? to : null;
}
// 図鑑の ヒント: 進化で 生まれる すがた（「ヒトカゲがLv25で進化」「イーブイにほのおのいしを使う」）。進化の すがたで ない ときは ''
export function evolveHint(sp, MONSTERS) {
  const from = EVOLVE_FROM[sp];
  if (!from) return '';
  const f = MONSTER_FRIENDS[from];
  const name = MONSTERS[from]?.name || '？';
  if (f.evolve?.to === sp) return `${name}がLv${f.evolve.lv}で進化`;
  const stone = Object.keys(f.stones || {}).find((id) => f.stones[id] === sp);
  return stone ? `${name}に${STONE_NAMES[stone] || stone}を使う` : '';
}
// 図鑑の 説明: その しゅぞくの 進化（「Lv25で進化する」「石で進化する」。進化しない ときは ''）
export function evolveNote(sp) {
  const f = MONSTER_FRIENDS[sp];
  if (f?.evolve?.to) return `Lv${f.evolve.lv}で進化する`;
  if (f?.stones && Object.keys(f.stones).length) return `${Object.keys(f.stones).map((id) => STONE_NAMES[id] || id).join('・')}で進化する`;
  return '';
}
// 進化の 石の 名前（data/items-pokemon.js と おなじ。data どうしの じゅんかんを さける ため ここにも）
export const STONE_NAMES = { fire_stone: 'ほのおのいし', water_stone: 'みずのいし', thunder_stone: 'かみなりのいし', moon_stone: 'つきのいし' };

js/shared/data/difficulty.js:
// ゲームの むずかしさ（メニューの「設定」。キャラごとに のこる）
// ・mainMarks … メインの 目標の 行き先（ピンクの しるし・仲間の「行き先は 北東の ほう」）を 出す
// ・subMarks … たのまれごとの 行き先（水色・みどりの しるし）を 出す
// ・exp … 戦いで もらえる 経験値の 倍率（1・0.75・0.5・0.25・0.1）。仲間・馬車の 仲間も おなじ 倍率
// ・enemy … 敵の 強さの 倍率（1・1.2・1.5・2）。魔物の HP・MP・攻撃・守り・素早さ・魔力が この 倍に なる
//   （もらえる 経験値・ゴールド・落とす 物は かわらない）。パーティーでは リーダーの 設定で 戦う（world/battles.js）
export const EXP_RATES = [1, 0.75, 0.5, 0.25, 0.1];
export const EXP_RATE_NAMES = { 1: 'ふつう', 0.75: '0.75倍', 0.5: '0.5倍', 0.25: '0.25倍', 0.1: '0.1倍' };
// 設定の 画面の みじかい せつめい（経験値）
export const EXP_RATE_NOTES = {
  1: '今までどおり',
  0.75: '少しレベルが上がりにくい',
  0.5: 'レベルが上がりにくい',
  0.25: 'かなりレベルが上がりにくい',
  0.1: 'とてもレベルが上がりにくい',
};
export const ENEMY_RATES = [1, 1.2, 1.5, 2];
export const ENEMY_RATE_NAMES = { 1: 'ふつう', 1.2: 'ハード', 1.5: 'ベリーハード', 2: 'スーパーハード' };
// 設定の 画面の みじかい せつめい
export const ENEMY_RATE_NOTES = {
  1: '今までどおりの強さ',
  1.2: '敵が1.2倍の強さ。少し手ごわい',
  1.5: '敵が1.5倍の強さ。かなり手ごわい',
  2: '敵が2倍の強さ。とても手ごわい',
};

export function difficultyOf(c) {
  const d = c?.difficulty || {};
  return {
    mainMarks: d.mainMarks !== false,
    subMarks: d.subMarks !== false,
    exp: EXP_RATES.includes(d.exp) ? d.exp : 1,
    enemy: ENEMY_RATES.includes(d.enemy) ? d.enemy : 1,
  };
}

// メニューから とどいた 設定を ととのえる（知らない 値は つかわない）。ぜんぶ ふつう なら undefined
export function normDifficulty(prev, msg) {
  const d = { ...difficultyOf({ difficulty: prev }) };
  if (typeof msg?.mainMarks === 'boolean') d.mainMarks = msg.mainMarks;
  if (typeof msg?.subMarks === 'boolean') d.subMarks = msg.subMarks;
  if (EXP_RATES.includes(msg?.exp)) d.exp = msg.exp;
  if (ENEMY_RATES.includes(msg?.enemy)) d.enemy = msg.enemy;
  if (d.mainMarks && d.subMarks && d.exp === 1 && d.enemy === 1) return undefined;
  return d;
}

// 戦いで もらえる 経験値・お金の きほんの 倍率（2026年10月 見なおし。前は どちらも 1）
// 「レベルと お金が たまりやすすぎる」ので、経験値は 6わり・お金は 7わりに した。
// 設定の「もらえる経験値」（1・0.75・0.5・0.25・0.1）は この 上に かかる（scaleExp）。職業レベル（戦いの 数）・店の 値段は かえない
export const REWARD_EXP_RATE = 0.6;
export const REWARD_GOLD_RATE = 0.7;
// 戦い 1回ぶんの 経験値（魔物の exp の 合計 → きほんの 倍率。0 で なければ 1 いじょう）
export function rewardExp(exp) {
  return exp > 0 ? Math.max(1, Math.round(exp * REWARD_EXP_RATE)) : 0;
}
// 戦い・宝箱・ひみつのダンジョンの ごほうびの お金（0 で なければ 1 いじょう）
export function rewardGold(gold) {
  return gold > 0 ? Math.max(1, Math.round(gold * REWARD_GOLD_RATE)) : 0;
}

// その キャラが もらう 経験値（0 で なければ 1 いじょう）
export function scaleExp(c, exp) {
  if (!(exp > 0)) return 0;
  return Math.max(1, Math.round(exp * difficultyOf(c).exp));
}

// 地図の しるしを むずかしさで しぼる（kind: main / sub / subReady）
export function visibleMarks(c, marks) {
  const d = difficultyOf(c);
  // ask … クエストの 画面で 自分で えらんだ 困っている人（第50回 N4）は いつも 出す
  return marks.filter((m) => (m.kind === 'main' ? d.mainMarks : m.kind === 'ask' || d.subMarks));
}

// 敵の 強さ（設定の「敵の強さ」）: 魔物 1体の HP（最大と 今）・MP・攻撃・守り・素早さ・魔力（回復の 力も）を rate 倍に する。
// たたかいの はじめの 魔物も、とちゅうで 来た 魔物（仲間を呼ぶ・ボスが 呼んだ 手下・まぼろしの 分身）も（battle.js の addEnemies）。
// 宝の洞窟の 強さ（data/treasure.js の scaleEnemy）の あとに かける。レベルと ほうしゅう（rewardK）は かえない
export function strengthenEnemy(m, rate) {
  if (!m || !(rate > 1) || !ENEMY_RATES.includes(rate)) return m;
  const up = (v) => Math.round((v || 0) * rate);
  m.maxHp = Math.max(1, up(m.maxHp));
  m.hp = Math.min(m.maxHp, Math.max(1, up(m.hp)));
  m.maxMp = up(m.maxMp);
  m.mp = Math.min(m.maxMp, up(m.mp));
  m.atk = up(m.atk);
  m.dfn = up(m.dfn);
  m.agi = up(m.agi);
  m.mag = up(m.mag);
  m.healPow = up(m.healPow);
  return m;
}

