// ふしぎなかじ: 作る（レシピ）と きたえる（+1〜）の きまり
//
// 作る   … 素材 ＋ ゴールドで、店では 売っていない 装備を 作る。物語が すすむと 作れる 物が ふえる
// きたえる … 武器・よろい・たて・頭の 装備を +1 → +2 → … に する（アクセサリーは できない）
//            第35回: 店で 買える 装備（★1）は きたえられない（むかし きたえた +1〜 は そのまま 使える）
//            きたえられる 回数は 装備の ランクで きまる（items-forge.js の upgradeLimit。ランク1は +1、ランク7からは +5）
//            1回ごとに 攻撃力（守備力）が もとの 1わり（少なくても 1）上がる（items-forge.js の upgradedItem）
//            素材と ゴールドは 回数が すすむほど ふえる。+3 からは 星のかけらも いる
//            第32回: れん金がまで 同じ 武具を 2つ 合わせると、その 装備の きたえられる 回数が 1 ふえる（CAP_UP_MAX 回まで。c.alchemy.cap）
//            かくし要素: 生まれ変わる 武器（items-alchemy.js の REBIRTH）は 上限を こえて きたえられ、上限＋CAP_UP_MAX まで きたえて
//            もう1回 きたえると 別の 武器に 生まれ変わる（風来のシレンの ように）
//            第35回: 1だん目は れん金がまで「店の 武器＋素材」から 作る（items-alchemy.js の REBIRTH_START・data/alchemy.js）
// バランス: 作った 物・きたえた 物を 売っても、かかった ゴールドと 素材より 高くは ならない（テストで たしかめる）
import { ITEMS, sellPrice } from './items.js';
import { UPGRADE_TYPES, upgradeId, upgradeLimit, addUpgradeItems, CAP_UP_MAX, LB_MAX, lbId } from './items-forge.js';
import { isShopGear } from './items-rare.js';
import { CH3_RECIPES } from './items-ch3.js';
import { REBIRTH } from './items-alchemy.js';
import { capUp } from './alchemy.js';
// 第65回 D1: ランク6〜10の レシピ（items-craft-r65.js）
import { FORGE_R65_OPEN, FORGE_R65_RECIPES } from './items-craft-r65.js';

// ほかの ファイルで あとから 足された 装備にも +1〜 を 作る（なんど よんでも おなじ）
addUpgradeItems(ITEMS);

// ランクごとに 作れるように なる 物語の しるし（店の 品ぞろえと おなじ ころ）
//   第65回 D1: ランク6 第3章クリア・7 水の都ドゥーナ・8 第4章クリア・9 影の城が うかぶ・10 千年前の 里（第7章の 品は レシピの open〈c7_karim〉）
export const RECIPE_OPEN = { 2: null, 3: 'c1_treant', 4: 'c2_port', 5: 'c2_clear', ...FORGE_R65_OPEN };

// レシピ（id … できる 装備 / gold … ゴールド / mats … [素材, 数]）
export const RECIPES = [
  // ランク2（ルミナの町に 着いたら）
  { id: 'fang_spear', gold: 180, mats: [['beast_fang', 4], ['iron_shard', 1]] },
  { id: 'wolf_claw', gold: 150, mats: [['beast_fang', 5]] },
  { id: 'jelly_robe', gold: 150, mats: [['jelly', 6], ['magic_powder', 2]] },
  { id: 'fang_charm', gold: 250, mats: [['beast_fang', 6], ['magic_powder', 1]] },
  // ランク3（森の主を 助けたあと）
  { id: 'flame_sword', gold: 650, mats: [['iron_shard', 5], ['magic_powder', 3]] },
  { id: 'feather_hat', gold: 320, mats: [['wind_feather', 4], ['beast_fang', 2]] },
  { id: 'shell_mail', gold: 520, mats: [['pretty_shell', 5], ['iron_shard', 2]] },
  { id: 'wind_brooch', gold: 450, mats: [['wind_feather', 4], ['magic_powder', 2]] },
  // ランク4（カモメ港に 着いたら）
  { id: 'thunder_staff', gold: 1000, mats: [['magic_powder', 6], ['silver_shard', 2]] },
  { id: 'dragon_shield', gold: 1100, mats: [['dragon_scale', 3], ['silver_shard', 2]] },
  { id: 'shell_necklace', gold: 800, mats: [['pretty_shell', 8], ['silver_shard', 1]] },
  // ランク5（第2章を クリアしたら）
  { id: 'storm_sword', gold: 3200, mats: [['silver_shard', 5], ['iron_shard', 8], ['wind_feather', 5]] },
  { id: 'dragon_mail', gold: 3600, mats: [['dragon_scale', 5], ['silver_shard', 4]] },
  // 第3章（カナトコの かじ屋 テツジイ。open の フラグで 作れるように なる）
  ...CH3_RECIPES,
  // 第65回 D1: ランク6〜10（第3章クリア 〜 第7章）
  ...FORGE_R65_RECIPES,
];

export function recipeOf(id) {
  return RECIPES.find((r) => r.id === id) || null;
}

// その レシピが 作れる ころか（hasFlag: その 世界の フラグ）
export function recipeOpen(recipe, hasFlag = () => false) {
  // レシピごとの しるし（第3章の 星の鉄 など）
  if (recipe?.open) return hasFlag(recipe.open);
  const flag = RECIPE_OPEN[ITEMS[recipe?.id]?.rank];
  if (flag === undefined) return false;
  return !flag || hasFlag(flag);
}

export function openRecipes(hasFlag = () => false) {
  return RECIPES.filter((r) => ITEMS[r.id] && recipeOpen(r, hasFlag));
}

// ───── きたえる ─────
// 1回ごとの ゴールド（もとの 値段の わりあい。+1・+2・+3・+4・+5 … +8）
const UP_GOLD = [0.25, 0.5, 0.8, 1.1, 1.5, 2.0, 2.6, 3.3];

// きたえる 回数を 見る 人（c を わたさない ときの 人。ブラウザでは 自分のキャラ〈client/ui/alchemy.js〉。サーバーでは いつも c を わたす）
let viewer = null;
export function setForgeViewer(fn) {
  viewer = typeof fn === 'function' ? fn : null;
}
const viewerChar = () => (viewer ? viewer() : null);

// きたえるのに 使う 素材（武器の 種類・よろいの 種類で きまる。upMat が あれば それ）
export function upgradeMat(it) {
  if (it.upMat) return it.upMat;
  switch (it.type) {
    case 'weapon': return { staff: 'magic_powder', whip: 'beast_fang', fan: 'wind_feather' }[it.cat] || 'iron_shard';
    case 'armor': return { heavy: 'iron_shard', robe: 'magic_powder' }[it.armorType] || 'beast_fang';
    case 'head': return it.helm ? 'iron_shard' : it.bonus?.mag > 0 ? 'magic_powder' : 'beast_fang';
    default: return 'iron_shard';
  }
}

// もとの 装備の ねうち（店の 値段。売っていない 物は 売り値から）
function worth(id) {
  const it = ITEMS[id];
  return Math.max(20 * (it.rank || 1), it.price > 0 ? it.price : Math.round(sellPrice(id) * 4 / 3));
}

// その 装備を 何回まで きたえられるか（ランクで きまる ＋ れん金で ふやした 回数。きたえられない 物は 0）
// c … 持ち主（れん金で ふやした 回数を 見る）。わたさない ときは viewer
export function maxPlus(id, c = viewerChar()) {
  const it = ITEMS[id];
  if (!it || !UPGRADE_TYPES.includes(it.type)) return 0;
  const lim = upgradeLimit(ITEMS[it.base || id] || it);
  // 店で 買える 装備（★1）は 0（れん金で ふやした 回数も きかない）
  return lim ? lim + capUp(c, it.base || id) : 0;
}
// 店で 買える 装備か（★1。きたえられない。第35回）
export function isShopForge(id) {
  const it = ITEMS[id];
  return !!it && UPGRADE_TYPES.includes(it.type) && isShopGear(ITEMS[it.base || id] || it);
}

// 生まれ変わる 武器か（{ to, gold, mats, at: この 回数で きたえると 生まれ変わる }。ちがう ときは null）
export function rebirthOf(id) {
  const base = ITEMS[id]?.base || id;
  const rb = REBIRTH[base];
  if (!rb || !ITEMS[base] || !ITEMS[rb.to] || isShopGear(ITEMS[base])) return null;
  return { ...rb, at: upgradeLimit(ITEMS[base]) + CAP_UP_MAX };
}

// ほんとうに きたえられる 回数（生まれ変わる 武器は 上限を こえて at まで）
export function forgeTop(id, c = viewerChar()) {
  const rb = rebirthOf(id);
  return Math.max(maxPlus(id, c), rb ? rb.at : 0);
}

// 第65回: 限界とっぱ（★1〜★3。items-forge.js の LB_MAX）
export const LIMIT_STONE = 'limit_stone';
// 生まれ変わりの 武器（2だん目から）も 限界とっぱ しない（かくし要素の 道すじの まま）
const REBORN_TO = new Set(Object.values(REBIRTH).map((r) => r.to));
export const lbOf = (id) => ITEMS[id]?.lb || 0;
// 次に きたえた ときの id（★は そのまま）
const nextId = (id, n) => lbId(ITEMS[id]?.base || id, n, lbOf(id));
// 限界とっぱ できるか（上限まで きたえて ある・★が LB_MAX より 少ない・生まれ変わる 武器では ない）
export function canLimitBreak(id, c = viewerChar()) {
  const it = ITEMS[id];
  if (!it || !UPGRADE_TYPES.includes(it.type) || rebirthOf(id) || REBORN_TO.has(it.base || id)) return false;
  const top = maxPlus(id, c);
  const plus = it.plus || 0;
  return top > 0 && plus >= top && lbOf(id) < LB_MAX && !!ITEMS[lbId(it.base || id, plus, lbOf(id) + 1)];
}

export function canUpgrade(id, c = viewerChar()) {
  const it = ITEMS[id];
  if (!it || !UPGRADE_TYPES.includes(it.type)) return false;
  const plus = it.plus || 0;
  const rb = rebirthOf(id);
  if (rb && plus === rb.at) return true;
  if (plus < forgeTop(id, c) && ITEMS[nextId(id, plus + 1)]) return true;
  return canLimitBreak(id, c);
}

// id を 1回 きたえる ための もの（きたえられない ときは null）
//  { from, to, base, n: きたえたあとの 回数, gold, mats: [[素材, 数], ...], over?: 上限を こえている, reborn?: 生まれ変わる }
export function upgradeCost(id, c = viewerChar()) {
  if (!canUpgrade(id, c)) return null;
  const it = ITEMS[id];
  const base = it.base || id;
  const b = ITEMS[base];
  const n = (it.plus || 0) + 1;
  const rb = rebirthOf(id);
  if (rb && n === rb.at + 1) return { from: id, to: rb.to, base, n, gold: rb.gold, mats: rb.mats.map(([m, k]) => [m, k]), over: true, reborn: true };
  const rank = b.rank || 1;
  // 第65回: 上限まで きたえて ある → 限界とっぱ（限界の石・星のかけら。★が ふえるほど 多く）
  if (!(n - 1 < forgeTop(id, c) && ITEMS[nextId(id, n)])) {
    const k = lbOf(id) + 1;
    const p = n - 1;
    const gold = Math.max(3000 * k, 10 * (p + k) * rank, Math.round((worth(base) * (UP_GOLD[Math.min(UP_GOLD.length, p) - 1] + 0.5 * k)) / 10) * 10);
    return { from: id, to: lbId(base, n - 1, k), base, n: n - 1, lb: k, gold, mats: [[LIMIT_STONE, k], ['star_shard', 2 + k]], limit: true };
  }
  const gold = Math.max(10 * n * rank, Math.round((worth(base) * UP_GOLD[n - 1]) / 10) * 10);
  const mats = [[upgradeMat(b), n + Math.floor((rank - 1) / 2)]];
  if (rank >= 4) mats.push(['silver_shard', n]);
  // +3 からは 星のかけら（回数が すすむほど・ランクが 高いほど 多く）
  if (n >= 3) mats.push(['star_shard', n - 2 + (rank >= 4 ? 1 : 0)]);
  const out = { from: id, to: nextId(id, n), base, n, gold, mats };
  if (n > maxPlus(id, c)) out.over = true;
  return out;
}

// 素材と ゴールドが たりるか（ふくろの 中だけ。預かり所の 物は 使えない）
export function lackOf(c, cost) {
  const have = (id) => (c?.items || []).find((e) => e.id === id)?.n || 0;
  const mats = (cost?.mats || []).filter(([id, n]) => have(id) < n).map(([id, n]) => ({ id, need: n, have: have(id) }));
  return { gold: Math.max(0, (cost?.gold || 0) - (c?.gold || 0)), mats, ok: !mats.length && (c?.gold || 0) >= (cost?.gold || 0) };
}

js/shared/data/fq-common.js:
// お仕事いらい板の たのまれごとで 使う どうぐ（第39回 C の sidequests-family.js から 分けた。第41回）
// ・職業の 系統（jobLine）・その 系統の 人（lineMember）・いない 時の ヒント（need）・乗り物を もらう（vehicleSteps）
// ・sidequests-family.js（はじめの 5つ）と sidequests-work.js（第41回の 6つ）の どちらも ここを 使う
import { JOBS, jobAncestry } from './jobs.js';
import { FAMILY_VEHICLES } from './vehicles-family.js';
// 第6章 Step 6: ぜんまい馬（vehicles-tokei.js）も おなじ 形で わたせる
import { TOKEI_VEHICLES } from './vehicles-tokei.js';

export const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
export const N = (...lines) => lines.map((l) => ['say', null, l]);

// ───────────── 職業の 系統 ─────────────
// roots の どれかから 転職で つながる 職業（roots も 入る。新しい 職業が ふえても 合う）
const lineCache = new Map();
export function jobLine(roots) {
  const key = roots.join(',');
  if (lineCache.has(key)) return lineCache.get(key);
  const set = new Set();
  for (const id of Object.keys(JOBS)) if (roots.some((r) => jobAncestry(id).has(r))) set.add(id);
  lineCache.set(key, set);
  return set;
}
// 系統の 職業の 名前（基本職 → 上級職 → 超級職 → その先 の じゅん）
export function jobLineNames(roots) {
  return [...jobLine(roots)].sort((a, b) => (JOBS[a].tier || 0) - (JOBS[b].tier || 0)).map((id) => JOBS[id].name);
}
// chars … いっしょに 戦う 人の キャラ。その 系統の 人（魔物の 仲間は 職業が ないので 数えない）
export function lineMember(chars, roots) {
  const line = jobLine(roots);
  return (chars || []).find((c) => c && !c.species && line.has(c.job)) || null;
}
export function partyHasLine(chars, roots) {
  return !!lineMember(chars, roots);
}
const partyOfCtx = (x) => (x.partyChars ? x.partyChars() : [x.c].filter(Boolean));
export const proOf = (x, q) => lineMember(partyOfCtx(x), q.roots);

// いない 時の ヒント（系統の 名前は 4つまで）
export function needText(q) {
  const names = jobLineNames(q.roots);
  const list = names.slice(0, 4).join('・') + (names.length > 4 ? ' など' : '');
  return [`${q.job}の人が、パーティーにいてくれたら…。`, `（${list}の人と、いっしょに来よう。\n酒場の仲間や、家族の仲間でもいいよ）`];
}
export const need = (q) => N(...needText(q));

// 乗り物を もらう（パーティーの みんな。もう 持っていたら そのまま）。第6章クリアの ぜんまい馬（'zenmai_horse'）も
export function vehicleSteps(id) {
  const v = FAMILY_VEHICLES[id] || TOKEI_VEHICLES[id];
  return [
    ['call', (run) => {
      for (const m of run.everyone) {
        const c = m.char;
        if (!Array.isArray(c.vehicles)) c.vehicles = [];
        if (!c.vehicles.includes(id)) c.vehicles.push(id);
      }
      run.world.markDirty();
      run.say(`${run.who()}は${v.name}をもらった！\n（メニューの「乗り物」で、走る時に乗れる）`);
    }],
    ['sfx', 'key'],
  ];
}

// クエストの 画面の どうぐ（いくつ すんだか・まだの 1つめ）
export const cnt = (f, list) => list.filter((k) => f(k)).length;
export const firstMissing = (f, list) => list.findIndex((k) => !f(k));

