// 階 n の k ばんめの 宝箱 → { item, n }（A の マップ用。ない ときは null）
export function c7sChest(floor, k) {
  const item = C7S_TREASURE[floor]?.[k];
  return item ? { item, n: C7S_TREASURE_N[floor]?.[k] || 1 } : null;
}

