export function baseItemId(id) {
  return (id && ITEMS[id]?.base) || id;
}

export function sellPrice(id) {
  const it = ITEMS[id];
  if (!it || it.type === 'key') return 0;
  if (it.sell !== undefined) return it.sell;
  return Math.floor((it.price || 0) * 3 / 4);
}

