Object.assign(OBJECTIVE_TALK, CH6_OBJECTIVE_TALK);
// 第7章（story-c7.js）
Object.assign(OBJECTIVE_TALK, CH7_OBJECTIVE_TALK);
// 第8章（story-c8.js）
Object.assign(OBJECTIVE_TALK, CH8_OBJECTIVE_TALK);

// 目標の 文の 章（第3〜5章の 表に あれば その章。ほかは 第2章まで あつかい）
export function objectiveChapter(objective) {
  const o = objective || '';
  // 第6章の 目標は、かくし要素の ヒントでは 第5章（第1部の さいご）と おなじ あつかい
  if (CH5_OBJECTIVE_TALK[o] || CH6_OBJECTIVE_TALK[o] || CH7_OBJECTIVE_TALK[o]) return 5;
  if (CH8_OBJECTIVE_TALK[o]) return 5;
  if (CH4_OBJECTIVE_TALK[o]) return 4;
  if (CH3_OBJECTIVE_TALK[o] || o === C3_LEAD_OBJECTIVE) return 3;
  return 2;
}

// 話す 内容（目標が 表に ない ときは 目標の 文を そのまま）
export function talkFor(objective, style) {
  const t = OBJECTIVE_TALK[objective || ''];
  if (t) return t[style] || t.kind;
  const plain = String(objective || '').replace(/\n/g, '');
  if (!plain) return style === 'kid' ? 'どこへ行こうかなあ。ぼく、どこでもいいよ！' : '次にどこへ行くか、町の人に話を聞いてみるのもいいかもしれない。';
  return style === 'bold' ? `次は「${plain}」だったな。` : style === 'kid' ? `次は「${plain}」だよ！` : `次は「${plain}」ですね。`;
}

// 仲間 1人の 一言。モンスターは しぐさで 話す
export function memberTalk(m, objective) {
  if (m.species) {
    const name = MONSTERS[m.species]?.name || '';
    return { name: m.name, text: `${m.name}は、行き先のほうをじっと見つめている。`, mon: true, kind: name };
  }
  const style = TALK_STYLE[m.key] || TALK_STYLE[m.id] || 'kind';
  // 第35回: ときどき（じゅんばんに）かくし要素の ヒント（data/secret-hints.js）
  const hint = nextPartyHint(objectiveChapter(objective));
  if (hint) return { name: m.name, text: hint, hint: true };
  return { name: m.name, text: talkFor(objective, style) };
}

