// 風の笛（sky.js）
Object.assign(OBJECTIVE_TARGETS, SKY_OBJECTIVE_TARGETS);
// 第3章（story-ch3.js）
OBJECTIVE_TARGETS[C3_LEAD_OBJECTIVE] = [{ npc: 'elder' }];
