// たのまれごと（name … クエストの 名前、who … 報告する 人、ready … もう 報告できる）
export function subQuests(c) {
  const f = (k) => !!c.flags?.[k];
  const has = (id) => (c.items || []).some((e) => e.id === id && e.n > 0) || (c.keyItems || []).includes(id);
  const out = [];
  if (f('q_mike_start') && !f('q_mike_done')) {
    if (f('q_mike_found')) out.push({ name: '迷子のねこミケ', who: 'mike_girl', ready: true, text: 'リリに報告しよう' });
    else out.push({ name: '迷子のねこミケ', who: 'mike_girl', find: 'mike', ready: false, text: '星見の丘で探そう' });
  }
  if (f('q_jelly_start') && !f('q_jelly_done')) {
    const n = Math.min(3, (c.items || []).find((i) => i.id === 'jelly')?.n || 0);
    out.push({ name: 'コックの特製ゼリー', who: 'cook', ready: n >= 3, text: n >= 3 ? '酒場のコックに届けよう' : `ぷるりんゼリー ${n}/3` });
  }
  if (f('q_wolf_start') && !f('q_wolf_done')) {
    const n = Math.max(0, (c.kills?.wolf || 0) - (c.quests?.wolfBase || 0));
    out.push({ name: 'ウルフ退治', who: 'farmer_wolf', ready: n >= 5, text: n >= 5 ? '牧場のおじさんに報告しよう' : `${Math.min(5, n)}/5ひき` });
  }
  if (has('bottle_letter') && !f('q_bottle_done')) out.push({ name: 'びんの手紙', who: 'mina', ready: true, text: 'カモメ港のミナにわたそう' });
  // 夜だけの たのまれごと（night.js）
  if (f('q_ghost_start') && !f('q_ghost_done')) {
    if (has('music_box')) out.push({ name: 'ゆうれいのオルゴール', who: 'night_ghost', ready: true, text: '夜のホシフル村で、ゆうれいの女の子にわたそう' });
    else out.push({ name: 'ゆうれいのオルゴール', who: 'night_ghost', find: 'night_glint', ready: false, text: '夜の星見の丘で探そう' });
  }
  // 第3章（story-ch3.js）
  const count = (id) => (c.items || []).filter((i) => i.id === id).reduce((s, i) => s + (i.n || 0), 0);
  out.push(...ch3SubQuests(c, f, has, count));
  // 第4章クリアの あとの たのまれごと（sidequests.js）
  out.push(...labSubQuests(c, f, has));
  return out;
}

let npcIndex = null;
function npcPos(id) {
  if (!npcIndex) {
    npcIndex = new Map();
    for (const m of Object.values(MAPS)) for (const n of m.npcs || []) if (!npcIndex.has(n.id)) npcIndex.set(n.id, { map: m.id, x: Math.floor(n.x), y: Math.floor(n.y) });
  }
  return npcIndex.get(id) || null;
}

// unless の ついた 行き先を、もう すんだ ぶんだけ はぶく
export function liveTargets(c, specs) {
  const left = specs.filter((s) => !s.unless || !c?.flags?.[s.unless]);
  return left.length ? left : specs;
}

function resolve(spec) {
  if (spec.npc) return npcPos(spec.npc);
  return MAPS[spec.map] ? { map: spec.map, x: spec.x, y: spec.y } : null;
}

// マップの つながり（出入り口・船）
let links = null;
function mapLinks() {
  if (links) return links;
  links = [];
  for (const m of Object.values(MAPS)) for (const w of m.warps || []) if (w.to?.map) links.push({ from: m.id, x: w.x, y: w.y, to: w.to.map });
  // ほかの つながり（第4章の すなかぜ号: ドゥナの さんばしの 船 ⇔ 砂の海の さんばし。マップの links）
  for (const m of Object.values(MAPS)) for (const l of m.links || []) links.push({ from: m.id, x: l.x, y: l.y, to: l.to });
  // 船: さんばしの しおかぜ号 ⇔ カモメ港の 船長
  const ship = npcPos('ship');
  const cap = npcPos('port_captain');
  if (ship && cap) {
    links.push({ from: ship.map, x: ship.x, y: ship.y, to: cap.map });
    links.push({ from: cap.map, x: cap.x, y: cap.y, to: ship.map });
  }
  return links;
}

// いまの マップから 行き先の マップへ 行く ための 最初の 出口
function firstStep(fromMap, toMap) {
  if (fromMap === toMap) return null;
  const prev = new Map([[fromMap, null]]);
  const q = [fromMap];
  while (q.length) {
    const cur = q.shift();
    if (cur === toMap) break;
    for (const l of mapLinks()) {
      if (l.from !== cur || prev.has(l.to)) continue;
      prev.set(l.to, { map: cur, link: l });
      q.push(l.to);
    }
  }
  if (!prev.has(toMap)) return null;
  let node = toMap;
  let step = null;
  while (prev.get(node)) {
    step = prev.get(node).link;
    node = prev.get(node).map;
  }
  return step ? { x: step.x, y: step.y } : null;
}

// このマップに 出す しるし: kind は 'main'（次の 行き先）/ 'sub'（たのまれごと）/ 'subReady'（報告できる）
// via … 別の マップに ある ときの 出口（とちゅうの 道しるべ）
export function questMarks(c, mapId, objective = c?.objective) {
  const out = [];
  const add = (specs, kind, label) => {
    const spots = specs.map(resolve).filter(Boolean);
    if (!spots.length) return;
    const here = spots.filter((p) => p.map === mapId);
    if (here.length) {
      for (const p of here) out.push({ x: p.x, y: p.y, kind, label, via: false });
      return;
    }
    const step = firstStep(mapId, spots[0].map);
    if (step) out.push({ x: step.x, y: step.y, kind, label, via: true });
  };
  const main = OBJECTIVE_TARGETS[objective || ''];
  if (main) add(liveTargets(c, main), 'main', '次の行き先');
  for (const q of subQuests(c || {})) {
    if (q.find) add([{ npc: q.find }], 'sub', q.name);
    add([{ npc: q.who }], q.ready ? 'subReady' : 'sub', q.name);
  }
  // 第50回 N4: 困っている人（黄色。クエストの 画面で えらんだ 1人）
  const ask = askPinQuest(c);
  if (ask) add([{ npc: ask.npc }], 'ask', ask.who);
  // おなじ 場所は 1つに（メイン → 報告できる → たのまれごと → 困っている人 の じゅん）
  const rank = { main: 0, subReady: 1, sub: 2, ask: 3 };
  const seen = new Map();
  for (const m of out) {
    const k = `${m.x},${m.y}`;
    if (!seen.has(k) || rank[m.kind] < rank[seen.get(k).kind]) seen.set(k, m);
  }
  return [...seen.values()];
}

// 目標の 場所の 名前（クエストの 画面に 出す）
export function whereName(spec) {
  const p = resolve(spec);
  const m = p && MAPS[p.map];
  if (!m) return '';
  // 村・町・港・森などの 名前（なければ マップの 名前）
  return m.areaName?.(Math.floor(p.x), Math.floor(p.y)) || m.name || '';
}

js/shared/data/quick-item.js:
// 第50回 N3: 大事な物の「すぐ使う」ボタン（時の砂時計・ミナモの星読み・星読みのしおり など、物語で 何回も 使う 大事な物）
// ・すぐ使える 大事な物 … メニューの「道具」→「使う」が ある もの（ITEMS の menuUse か hourglass）
// ・c.quickItem … ボタンの 大事な物の ID（'' … 使わない。ない・もう 持っていない ときは 持っている 物の はじめの 1つ）
// ・c.quickPad … コントローラーの ボタン（QUICK_PADS の b。ない ときは ZL）。キーボードは T（client/input.js）
// ・はじめて 手に 入れた ときは 自動で ボタンに なる（stats.js の addItem → autoQuick）
// ・ひきつぎの 合言葉（transfer.js）には 入れない（ひきついだ あとは はじめの 1つに もどる）
// ITEMS だけを 読む（stats.js からも 読むので、maps などは 読まない）
import { ITEMS } from './items.js';

// メニューの 使う と おなじ サーバーの 道具の 名前（world/services.js の menuAction）
export function quickUseOf(id) {
  const it = typeof id === 'string' && Object.prototype.hasOwnProperty.call(ITEMS, id) ? ITEMS[id] : null;
  if (!it || it.type !== 'key') return null;
  return it.menuUse || (it.hourglass ? 'timeGlass' : null);
}

// HUD の ボタンの 短い 名前（ない ものは 品物の 名前）
const LABELS = { timeGlass: '砂時計', starSight: '星読み', bookmark: 'しおり' };
export const quickLabel = (id) => LABELS[quickUseOf(id)] || ITEMS[id]?.name || '';

// 持っている すぐ使える 大事な物（手に 入れた じゅん）
export const quickList = (c) => (Array.isArray(c?.keyItems) ? c.keyItems.filter((k) => quickUseOf(k)) : []);

// 今の ボタンの 大事な物（なし … null）
export function quickItemOf(c) {
  if (!c || c.quickItem === '') return null;
  const list = quickList(c);
  return list.includes(c.quickItem) ? c.quickItem : (list[0] || null);
}

// 大事な物を 手に 入れた（stats.js の addItem）: ボタンが まだ ない ときは それに する
export function autoQuick(c, id) {
  if (!c || c.species || !quickUseOf(id) || c.quickItem === '') return;
  const list = quickList(c);
  if (!list.includes(c.quickItem)) c.quickItem = list[0] || id;
}

// えらぶ（メニュー。id が '' なら 使わない）。{ ok, text }
export function setQuickItem(c, id) {
  if (id === '' || id === null) {
    c.quickItem = '';
    return { ok: true, text: 'すぐ使うボタンを使わないことにした。' };
  }
  if (!quickUseOf(id) || !quickList(c).includes(id)) return { ok: false, text: 'それはボタンにできない' };
  c.quickItem = id;
  return { ok: true, text: `${ITEMS[id].name}を、すぐ使うボタンにした！` };
}

// コントローラーの ボタン（あいている もの。A0・B1・X2・Y3・L4・R5・ZR7・SELECT8・START9 は 使っている）
export const QUICK_PADS = [
  { b: 6, name: 'ZL（LT）' },
  { b: 10, name: 'L3（左スティックをおしこむ）' },
  { b: 11, name: 'R3（右スティックをおしこむ）' },
  { b: -1, name: 'なし' },
];
export const QUICK_PAD_DEFAULT = 6;
export const quickPadOf = (c) => (QUICK_PADS.some((p) => p.b === c?.quickPad) ? c.quickPad : QUICK_PAD_DEFAULT);
export const quickPadName = (b) => (QUICK_PADS.find((p) => p.b === b) || QUICK_PADS[0]).name;

export function setQuickPad(c, b) {
  if (!QUICK_PADS.some((p) => p.b === b)) return { ok: false, text: '' };
  if (b === QUICK_PAD_DEFAULT) delete c.quickPad;
  else c.quickPad = b;
  return { ok: true, text: `大事な物のボタンを「${quickPadName(b)}」にした。` };
}

// セーブを 読んだ ときの 手直し（save.js の repairChar）
export function cleanQuick(c) {
  if (!c || typeof c !== 'object' || c.species) return;
  if (c.quickItem !== undefined && c.quickItem !== '' && !quickUseOf(c.quickItem)) delete c.quickItem;
  if (c.quickPad !== undefined && !QUICK_PADS.some((p) => p.b === c.quickPad && p.b !== QUICK_PAD_DEFAULT)) delete c.quickPad;
}

// この 場所で ボタンを 出すか（クライアントの HUD。くわしい きまりは サーバー。だめな ときは サーバーが わけを 知らせる）
//   maps … MAPS、o … { flying: 空の 上, visiting: リーダーの 冒険を 手伝っている }
export function quickHere(c, maps, mapId, x, y, o = {}) {
  const id = quickItemOf(c);
  const map = maps?.[mapId];
  if (!id || !map) return false;
  const use = quickUseOf(id);
  if (use === 'bookmark') return map.tkFloor != null;
  if (o.flying) return false;
  if (use === 'timeGlass') {
    if (o.visiting || !map.timePair || !maps[map.timePair]) return false;
    return !map.timeNoUse?.(Math.floor(x), Math.floor(y));
  }
  if (use === 'starSight') return !o.visiting && (c.guests || []).some((g) => g === 'minamo' || g?.id === 'minamo');
  return true;
}

