// その 数で もどる コイン（かけた ぶんも ふくむ）と、当たった 場所
export function roulettePayout(bets, n) {
  let win = 0;
  const hits = [];
  for (const [key, c] of Object.entries(bets)) {
    const b = parseBetKey(key);
    if (!b) continue;
    const kind = BET_KINDS[b.k];
    if (!kind.wins(n, b.v)) continue;
    win += c * kind.mult;
    hits.push(key);
  }
  return { win, hits };
}

