    ...accept('子ラクダのコブを、いっしょにさがす？', [
      ...S(NASIM, 'ほんとう！？ありがとう！', '妹のルルと、東の門の見張りの兵士さんに、聞いてみて！'),
    ], S(NASIM, 'そっか…。'), CAMEL8.start),
