    ...S(who, '森の入り口のあたりで、まいごになっているかもしれんな。'),
    ['flag', CAMEL8_VOICES[1]], ['sync'],
  ];
};
// 王家の森の 子ラクダ（話を 聞いた あと: つれて 帰り方を えらぶ。まちがえると にげる → もう一度）
const camelLost = (x) => {
