  const look = N('小さな子ラクダが、木のかげで、ぶるぶるふるえている…。');
  if (!all(x, CAMEL8_VOICES)) return [...look, ...N('近づこうとすると、子ラクダは、さっと木のうしろへかくれた。', '（コブのことを、もう少し聞いてみよう）')];
