};
const marketServant = (x) => {
  if (x.flag(MARKET8.done) || x.flag(MARKET8.solved)) return S(ZURURI, '…あの時は、わるかったよ。', 'こんどから、ちゃんと、ほんものの分銅で買い物をするさ。');
