// ───────────── クエストの 画面・地図の しるし（data/sidequests-c7.js の c7SubQuests に たす）─────────────
export function c8dSubQuests(c, f) {
  const out = [];
  if (!f(C8D_OPEN)) return out;
  const q = (id, o) => out.push({ name: Q[id].name, ...o });
  // 1. 迷子の 子ラクダ
  if (f(CAMEL8.start) && !f(CAMEL8.done)) {
