const goodsName = ([id, n]) => `${ITEMS[id]?.name || id}×${n}`;
export function rewardNames(r) {
  return [r.item && FAMILY_ITEMS[r.item]?.name, r.vehicle && FAMILY_VEHICLES[r.vehicle]?.name, ...(r.goods || []).map(goodsName)].filter(Boolean);
}
// 第65回 D2: はり紙の 一らんで カーソルを 合わせた 時の せつめい（スマホの たて画面でも 読めるように 3行）
export function boardInfo(x, q) {
  const r = q.reward;
  const has = !!proOf(x, q);
  return [
    `必要な職業：${q.job}の系統（${has ? '○いる' : '×いない'}）`,
    `ごほうび：${rewardNames(r).join('・')}`,
    `${r.gold}ゴールド・小さなメダル${r.medals}まい`,
  ].join('\n');
}
// できそうな 職業の ページ（1行 BOARD_LINE 文字まで・1ページ 2行。系統が 長い 職業でも はみ出さない）。
// 名前の 間は「、」（「ネオ・クイーン・セレニティ」の ように 名前に「・」が ある 職業が あるので）
const BOARD_LINE = 20;
function jobPages(q) {
  const lines = [];
  for (const name of jobLineNames(q.roots)) {
    const last = lines.length - 1;
    if (last >= 0 && lines[last].length + 1 + name.length <= BOARD_LINE) lines[last] += '、' + name;
    else lines.push(name);
  }
  const out = [];
  for (let i = 0; i < lines.length; i += 2) out.push(`【解決できそうな職業】${i ? '（続き）' : ''}\n${lines.slice(i, i + 2).join('\n')}`);
  out.push('（その職業の人が、パーティーにひとりいればだいじょうぶ）');
  return N(...out);
}
// 第76回: はり紙を 文だけで 読む 形（今は 大きな まど〈boardPaper〉で 見せる。テストで 中みを たしかめる のに のこす）
export function boardPage(x, q) {
  const r = q.reward;
  const state = x.flag(q.done) ? 'このたのまれごとは、もうすんでいる。' : boardTaken((k) => x.flag(k), q) ? '今、このたのまれごとを受けている。' : null;
  return [
    ...N(`「${q.name}」\n${q.paper}`),
    ...jobPages(q),
    ...N(`【会う人】\n${q.where}にいる、${q.who}に話しかけよう。`),
    ...N(['【ごほうび】', r.item && `${FAMILY_ITEMS[r.item].name}（アクセサリー）`, r.vehicle && `${FAMILY_VEHICLES[r.vehicle].name}（乗り物）`, r.goods?.length && r.goods.map(goodsName).join('・'), `${r.gold}ゴールド・小さなメダル${r.medals}まい`].filter(Boolean).join('\n')),
    ...(state ? N(`（${state}）`) : []),
  ];
}
// はり紙の 一らんは 1ページ BOARD_PAGE まい（第41回で 11まいに ふえた。ページ送りで 読みやすく）。
// 読みおわると、その ページの 一らんに もどる
export const BOARD_PAGE = 6;
// 第68回 D班: はり紙は 出る フラグ（open。ない ものは 第1部クリア）が そろった ものだけ。x が ない 時は ぜんぶ
export const boardOpen = (x, q) => (q.open || [FQ_OPEN]).every((k) => x.flag(k));
export const boardList = (x) => (x ? FAMILY_QUESTS.filter((q) => boardOpen(x, q)) : FAMILY_QUESTS);
export const boardPages = (x) => Math.ceil(boardList(x).length / BOARD_PAGE);
function boardMenu(x, page = 0) {
  const pages = boardPages(x);
  const list = boardList(x).slice(page * BOARD_PAGE, (page + 1) * BOARD_PAGE);
  const go = (p) => [['call', (run) => run.runSteps(boardMenu(x, p))]];
  const opts = list.map((q) => q.name + boardMark(x, q));
  // 第76回: はり紙は 大きな まど 1まいで ぜんぶ 見せる（何ページも の メッセージを やめた。boardTake）
  const acts = list.map((q) => boardTake(x, q, go(page)));
  // 第65回 D2: カーソルを 合わせた はり紙の 職業・ごほうび（client/ui/script.js の choice の せつめい）
  const info = list.map((q) => boardInfo(x, q));
  if (page + 1 < pages) { opts.push('つぎのページへ'); acts.push(go(page + 1)); info.push(''); }
  if (page > 0) { opts.push('前のページへ'); acts.push(go(page - 1)); info.push(''); }
  opts.push('やめる');
  acts.push([]);
  info.push('');
  return [['choice', `どのはり紙を読む？${pages > 1 ? `（${page + 1}/${pages}ページ）` : ''}`, opts, acts, info]];
}
// 第65回 D2: はり紙を 読んだ あと「受ける？」（受けると 地図の しるし・クエストの 画面に 出る）・受けている ものは「やめる？」
// やめると 受けた しるしと 始めた しるし（start）を けす。とちゅうまでの ことは おぼえていて、また 受けると 続きから
// 第76回: はり紙の 大きな まど（家族の ねがい: もっと 大きく、見やすく）。choice の 5つ目に はり紙の 中みを つける
//   （client/ui/script.js の paperPop。見ている だけの 人や 古い 画面には、はり紙の 文と 問いを ふつうの 文で）
function paperChoice(x, q, ask, opts, acts) {
  const p = boardPaper(x, q);
  return ['choice', `「${q.name}」\n${q.paper}\n${ask}`, opts, acts, null, { ...p, ask }];
}
function boardTake(x, q, back) {
  if (x.flag(q.done)) return [paperChoice(x, q, 'このたのまれごとは、もうすんでいる。', ['もどる'], [back])];
  const take = takeFlag(q);
  if (boardTaken((k) => x.flag(k), q)) {
    return [paperChoice(x, q, 'このいらいを、やめる？', ['いらいをやめる', 'つづける'], [
      [['unflag', take], ['unflag', q.start], ['sync'], ...N(`「${q.name}」をやめた。\n（とちゅうまでのことは覚えている。また受けると、続きから）`), ...back],
      back,
    ])];
  }
  return [paperChoice(x, q, 'このいらいを、うける？', ['うける', 'やめる'], [
    [['flag', take], ['sync'], ['sfx', 'key'], ...N(`「${q.name}」を受けた！\n${q.where}にいる、${q.who}に会いに行こう。\n（地図にしるしが出る）`), ...back],
    back,
  ])];
}
// 第76回: はり紙の 大きな まどの 中み（たのみごと・会う人と 場所・職業の 系統〈○いる／×いない〉・ごほうび）
export function boardPaper(x, q) {
  const r = q.reward;
  const pro = proOf(x, q);
  const rewards = [];
  if (r.item) rewards.push({ kind: 'acc', id: r.item, name: FAMILY_ITEMS[r.item]?.name || ITEMS[r.item]?.name || r.item, n: 1 });
  if (r.vehicle) rewards.push({ kind: 'vehicle', id: r.vehicle, name: FAMILY_VEHICLES[r.vehicle]?.name || r.vehicle, n: 1 });
  for (const [id, n] of r.goods || []) rewards.push({ kind: 'goods', id, name: ITEMS[id]?.name || id, n });
  return {
    name: q.name, paper: q.paper, town: q.town || '', where: q.where, who: q.who,
    job: q.job, jobs: jobLineNames(q.roots), has: !!pro, pro: pro?.name || null,
    rewards, gold: r.gold, medals: r.medals,
    state: x.flag(q.done) ? 'done' : boardTaken((k) => x.flag(k), q) ? 'taken' : null,
  };
}
function questBoard(x) {
  // 第1部クリアの 前: けいじ板は 立っているが、はり紙は まだ ない
  if (!x.flag(FQ_OPEN)) return N('〜 お仕事いらい板 〜\nまだ、はり紙は1まいもはられていない。', '（世界が平和になったころ、各地からたのみごとがとどくらしい。\n第1部をクリアしたら、また見にこよう）');
  const papers = boardList(x);
  const left = papers.filter((q) => !x.flag(q.done)).length;
  return [
    ...N('〜 お仕事いらい板 〜\n各地からとどいた、たのみごとのはり紙がはってある。', left ? `（はり紙は${papers.length}まい。まだすんでいないのは${left}まい）` : '（全部のたのまれごとが、すんでいる！）'),
    ...boardMenu(x),
  ];
}

// ───────────── だいほんの 一らん（story.js に まぜる）─────────────
export const FAMILY_SCRIPTS = {
  fq_board: questBoard,
  fq_th_manager: thManager, fq_th_clerk: thClerk, fq_th_lobbyguest: thLobbyGuest, fq_th_fan: thFan, fq_th_hot: thHot, fq_th_guest: thGuest,
