    else q('thd', { who: W, find: 'fq_thd_cloud', ready: false, text: 'かみなり雲に近づこう', hint: `島のみんなの話を思い出して、かみなり雲と話をつけよう。まちがえても、やり直せる。${jobHint('thd')}` });
