    else q({ name: '星読みの塔', who: 'q_star_reader', ready: true, text: '夜に星読みのナジュムをたずねよう', hint: '星読みのナジュムは、夜にまた来てほしいと言っていた。宿屋で「夜まで休む」と、すぐ夜になる。' });
