      : { name: '古代都市のなぞ', who: 'hassan', find: 'lab_dragon', ready: false, text: '大迷宮のいちばん下の石板を写そう', hint: '砂の古代都市は、砂の海の東のはし。大迷宮のいちばん下、地下10階に石板があるらしい。' });
