// ───── story.js から: だいほんを まぜる（今の トキネ・より道「時をこえる手紙」・パーティー全員で 見る イベント）─────
export function applyCh7(SCRIPTS, STORY_SCRIPTS) {
  Object.assign(SCRIPTS, CH7_SCRIPTS);
  for (const id of CH7_STORY_SCRIPTS) STORY_SCRIPTS.add(id);
  // 今の ほしみの丘の トキネ: 第6章クリアの あとは まず 第7章の はじまり（砂時計の かざりの より道は そのあと）
  const tokine = SCRIPTS.c6_tokine || (() => []);
  SCRIPTS.c6_tokine = Object.assign((x) => {
    if (x.flag('c6_clear') && !x.flag(C7.start)) return tokineLead();
    if (x.flag(C7.start) && !x.flag(ARRIVE7) && x.flag('c6_orn_start')) return S('トキネ', 'コガネ地方の、町の外で、砂時計を使ってみてね。', 'かざりのことも、わすれないでね！');
    return tokine(x);
  }, tokine);
  // より道「時をこえる手紙」（sidequests-c7.js）
  applyC7Side(SCRIPTS);
  // 第2幕「海の紋章」（story-c7s.js。今の トキネの 第2幕の はじまりは この あとで つつむ）
  applyCh7s(SCRIPTS, STORY_SCRIPTS);
  // 第3幕「ひとりぼっちの星」（story-c7i.js。今の トキネの 第3幕の はじまりは この あとで つつむ）
  applyCh7i(SCRIPTS, STORY_SCRIPTS);
}

