export function applyCh7i(SCRIPTS, STORY_SCRIPTS) {
  Object.assign(SCRIPTS, CH7I_SCRIPTS);
  for (const id of CH7I_STORY_SCRIPTS) STORY_SCRIPTS.add(id);
  // 今の ほしみの丘の トキネ: カイが 仲間に なった あとは まず 第3幕の はじまり
