const FLOOR_OBJ = { 2: 'f2', 3: 'f3', 4: 'f4', 5: 'f5', 6: 'f6', 7: 'f7', 8: 'f8', 9: 'f9', 10: 'f10', 11: 'f11', 12: 'f12' };

