  3: () => N('カラカラカラ…。', 'どこかで、風車の回る音がする…。', 'まん中の通路を、強い風がふさいでいる。'),
  4: () => [
    ['bgm', null],
    ...N('ゴオオオ…！', '北の広間から、はげしい風の音がひびいてくる…。'),
