  6: () => N('ひんやり…。', '炎の階なのに、この階だけ、空気がつめたい…。', '広間のまん中に、大きな氷の像が立っている。'),
  7: () => N('ゴオオオ…！', '北の階だんの前に、炎の大門が、ごうごうともえている…！'),
