  ],
  10: () => N('サラサラサラ…。', 'ゆかの上を、水が、矢じるしの向きに流れている…。'),
  11: () => N('ゴトン…ゴトン…。', '西と東から、水車の音が聞こえる…。', '北の階だんの前を、水のとびらがふさいでいる。'),
