// 第2章「海をわたる風」の だいほん（story.js で まぜる）
// 四ツ影の1人「嵐の将軍ストルム」が 風の守り星の力で 海をとざしている。
// さんばしで 船長マリナから しおかぜ号を かりて 海へ。灯台に 光をともすと 嵐の中に 道がひらく。
import { POS } from '../maps/index.js';
import { SEA_POS } from '../maps/sea.js';
import { innSteps } from './inn.js';

const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
const N = (...lines) => lines.map((l) => ['say', null, l]);

// 第2章の すすみかた（STORY_STEPS の うしろに つづく）
export const CH2_STEPS = ['c2_start', 'c2_ship', 'c2_port', 'c2_kraken', 'c2_light', 'c2_tower', 'c2_boss', 'c2_clear'];

// パーティー全員で 見る イベント
export const CH2_STORY_SCRIPTS = ['ch2_intro', 'captain_pier', 'port_arrive', 'harbor_master', 'squid_event', 'lighthouse_keeper', 'tower_enter', 'storm_event', 'wind_altar'];

const toSea = () => [['sfx', 'door'], ['fade', 'out'], ['teleport', 'sea', SEA_POS.arrive.x, SEA_POS.arrive.y, 'down'], ['bgm', 'sea'], ['fade', 'in']];

export const CH2_SCRIPTS = {
  // ───────────── はじまり（ホシミばあちゃん）─────────────
  ch2_intro: () => [
    ...S('ホシミばあちゃん', '{name}、よく来たね。守り星の石が、また何かを伝えようとしておる。',
      '南の海の向こうに「風の島」という島がある。\nそこから、2つ目の守り星の気配がするのじゃ。',
      'じゃが、ここ何日も海は大あれ…。船が1そうも来なくなってしもうた。',
      'ちょうど今朝、村のさんばしに、嵐をぬけてきた船が着いたそうじゃ。\n船長さんに話を聞いてみなさい。'),
    ['chapter', '第2章', '海をわたる風'],
    ['flag', 'c2_start'],
    ['objective', '村の南のさんばしで、船長さんに会おう'],
  ],

  // ───────────── さんばしの 船長 ─────────────
  captain_pier: (x) => {
    if (x.flag('c2_ship')) return S('船長マリナ', 'しおかぜ号は、さんばしの先につないであるよ。\n話しかければ、いつでも出航できるさ！');
    return [
      ...S('船長マリナ', 'あんたたちが、うわさの紋章の子かい？あたしはマリナ。「しおかぜ号」の船長さ。',
        'カモメ港から来たんだけどね、とちゅうの海は嵐だらけ。命からがら、ここまで来たよ。',
        '嵐の真ん中には「嵐の島」があって、あやしい塔が建っている。\nあそこから、嵐がふき出しているのさ。'),
      ['choice', 'しおかぜ号で、カモメ港へ行く？', ['行く！', 'まだ準備する'], [
        [
          ...S('船長マリナ', 'いい返事だ！しおかぜ号は、あんたたちに貸してあげるよ。\nかじの取り方はかんたん。行きたい方へ進むだけさ！',
            'あたしは先に港へ帰って、港長に話しておくよ。\nカモメ港は、ここから南西の「風の島」にあるからね。'),
          ['sfx', 'key'],
          ...N('しおかぜ号を借りた！'),
          ['flag', 'c2_ship'],
          ['objective', 'さんばしの先の、しおかぜ号に話しかけて出航しよう。\nカモメ港は南西の「風の島」'],
        ],
        [...S('船長マリナ', '準備ができたら、また声をかけておくれ。')],
      ]],
    ];
  },

  // さんばしの 船（話しかけると 出航）
  ship_board: (x) => (!x.flag('c2_ship') ? N('りっぱな船だ。「しおかぜ号」と書いてある。', 'そばにいる船長さんに、話を聞いてみよう。') : [
    ['choice', 'しおかぜ号で海へ出る？', ['出航する', 'やめる'], [
      [...toSea(), ['if', (y) => !y.flag('c2_sailed'), [...N('しおかぜ号は、風の海へこぎ出した！', '（水の上では、行きたい方へそのまま進めるよ）'), ['flag', 'c2_sailed']], []]],
      [],
    ]],
  ]),

  // 海の 北の さんばし（ミドリナへ 帰る）
  sea_go_home: () => [
    ['choice', 'ミドリナ地方にもどる？', ['もどる', 'やめる'], [
      [['fade', 'out'], ['teleport', 'overworld', POS.pierEnd[0], POS.pierEnd[1], 'up'], ['bgm', 'field'], ['fade', 'in']],
      [],
    ]],
  ],

  // ───────────── カモメ港 ─────────────
  port_arrive: () => [
    ['bgm', 'town'],
    ...N('カモメ港に着いた！', 'しおのかおりと、カモメの鳴き声…。\nでも、港の船はどれも、つながれたままだ。'),
    ['flag', 'c2_port_seen'],
    ['if', (x) => !x.flag('c2_port'), [['objective', '港長の家（町のまん中の下）で、話を聞こう']], []],
  ],

  harbor_master: (x) => {
    if (!x.flag('c2_port')) {
      return [
        ...S('港長ガモン', 'おお、マリナから聞いておるよ。紋章の子らよ、よく来てくれた。',
          'この海には「嵐の島」がある。そこに、四ツ影の1人「嵐の将軍」が住みついたのじゃ。',
          'やつは風の守り星の力で嵐を起こし、海をとざしてしもうた。',
          '嵐の中を進む方法は1つだけ。東の「灯台島」の灯台に火をともせば、\n嵐の海に、安全な道がてらし出される。',
          'ところが灯台の火「光の玉」は、海鳴りの洞窟にすむ大王イカにうばわれてしもうた。',
          '海鳴りの洞窟は、この島の南の小島じゃ。\nどうか、光の玉を取りもどしておくれ！'),
        ['flag', 'c2_port'],
        ['objective', '南の小島の「海鳴りの洞窟」で、光の玉を取りもどそう'],
      ];
    }
    if (!x.flag('c2_kraken')) return S('港長ガモン', '海鳴りの洞窟は、この島の南の小島じゃ。\n大王イカは、洞窟のいちばんおくにいるはずじゃ。');
    if (!x.flag('c2_light')) return S('港長ガモン', 'おお、光の玉を取りもどしたか！\n東の灯台島の灯台守に、わたしておくれ。');
    if (!x.flag('c2_boss')) return S('港長ガモン', '灯台の光が、嵐の中に道をてらしておる！\n嵐の島の塔では、嵐の将軍が待ちかまえておるぞ。');
    if (!x.flag('c2_clear')) return S('港長ガモン', '嵐がやんだ…！\n風の守り星を、町の北の「風のさいだん」にもどしておくれ。');
    return S('港長ガモン', '海が元どおりになった。船乗りたちも大よろこびじゃ！\nいつでもカモメ港に来ておくれ。');
  },

  captain_port: (x) => {
    if (!x.flag('c2_kraken')) return S('船長マリナ', '港長の話は聞いたかい？大王イカは手ごわいよ。\n宿屋でしっかり休んでから行きな。');
    if (!x.flag('c2_boss')) return S('船長マリナ', '灯台の光が見えるかい？\n嵐の島には、北がわの光の道から入れるはずさ！');
    if (!x.flag('c2_clear')) return S('船長マリナ', 'やったんだね！空が青い…！\n早く風の守り星をさいだんにもどしておくれ！');
    return S('船長マリナ', '次はどこへ行くんだい？\nしおかぜ号なら、どこへだって行けるさ！');
  },

  port_inn: (x) => innSteps('宿屋のおかみ', 20, x),
  port_arms: () => [['shop', 'port_arms']],
  port_items: () => [['shop', 'port_item']],
  port_church: () => [['church']],

  old_sailor: () => S('年よりの船乗り', 'むかし、星の竜の背中に乗って、空をとんだ勇者がいたそうじゃ…。',
    '竜は今も、北の山のどこかでねむっておると、じいさまから聞いたもんじゃ。'),
  fisher: (x) => (x.flag('c2_clear')
    ? S('漁師', '海が静かになって、魚もたくさんとれるようになったぜ！')
    : S('漁師', '海には小さな島がいくつかあってな。\n宝箱がのっているらしいぜ。船で行ってみな！')),
  sailor: (x) => (x.flag('c2_light')
    ? S('船乗り', '見ろよ、灯台の光だ！嵐の海に、1本の道ができてる！')
    : S('船乗り', 'この島の南の小島に、海鳴りの洞窟があるぜ。\nザザーンって音がするから、すぐわかるさ。')),
  port_kid: (x) => (x.flag('c2_boss')
    ? S('港の子ども', 'すげえ！嵐の将軍をやっつけたんだって！？\nおいらも大きくなったら、紋章の子になる！')
    : S('港の子ども', '嵐の島の塔には、雷を落とすこぞうがいるんだって！\n雷に弱い魔物もいるらしいよ。')),
  mina: (x) => {
    if (x.flag('q_bottle_done')) return S('ミナ', 'おじいちゃんの手紙、大切にするね。本当にありがとう！');
    if (x.has('bottle_letter')) {
      return [
        ...S('ミナ', 'え…！この手紙、「カモメ港のミナへ」って…。\nおじいちゃんの字だ！'),
        ['takeItem', 'bottle_letter', 1],
        ...S('ミナ', '「ミナ、海はこわいけれど、とてもきれいだ。\nいつか、いっしょに星の竜を見に行こう」…',
          'ありがとう！お礼に、これをあげる！'),
        ['item', 'sea_charm', 1],
        ['flag', 'q_bottle_done'],
      ];
