    return S('ミナ', 'わたしのおじいちゃん、むかし海に手紙を流したんだって。\nどこかの島に流れついていないかなあ…');
  },

  // ───────────── 海鳴りの洞窟 ─────────────
  seacave_enter: () => [
    ...N('ザザーン…。\n洞窟の中まで、波の音がひびいている。'),
    ['flag', 'c2_cave_seen'],
