// 第3章「星の竜がねむる山」の だいほん（story.js で まぜる）
// 四ツ影の1人「炎の魔女イグニア」が 竜守りの村の「炎の守り星」を うばい、星竜山の 万年氷を とかしている。
// 氷の洞窟（ブリザマンモス）→ 鉱山の町カナトコ（マグマゴーレム）→ 温泉の里ユノハ → 炎の山（炎の騎士フレアード）
// → 竜の試練の神殿（勇気・ちえ・きずな）→ 竜の門 → 星竜山 → 頂上で イグニアを たおすと 星の竜アステルが 目覚める
import { NORTH_PLACES } from '../maps/north.js';
import { CART_RIDES, WISDOM_ORDER, WISDOM_FLAGS, BOND_PLATES, TRIAL_FLAGS, VOLCANO_LEVERS } from '../maps/ch3.js';
import { innSteps } from './inn.js';
import { C4_LEAD_OBJECTIVE } from './sky.js';

const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
const N = (...lines) => lines.map((l) => ['say', null, l]);
const VIL = NORTH_PLACES.dragon_village, KAN = NORTH_PLACES.kanatoko, YUN = NORTH_PLACES.yunoha;
const V = (x, y) => [VIL.x + x + 0.5, VIL.y + y + 0.5];
const K = (x, y) => [KAN.x + x + 0.5, KAN.y + y + 0.5];
const Y = (x, y) => [YUN.x + x + 0.5, YUN.y + y + 0.5];

// 第3章の すすみかた（STORY_STEPS の うしろに つづく）
// 3つの 試練（c3_courage / c3_wisdom / c3_bond）は どの じゅんでも よいので ここには 入れない
export const CH3_STEPS = ['c3_start', 'c3_arrive', 'c3_village', 'c3_elder', 'c3_icecave', 'c3_mammoth', 'c3_kanatoko', 'c3_miners', 'c3_mine',
  'c3_yunoha', 'c3_onsen', 'c3_flare', 'c3_temple', 'c3_gate', 'c3_peak', 'c3_hut', 'c3_ignia', 'c3_dragon', 'c3_clear'];

// ───── 目標 ─────
export const C3_OBJ = {
