  gate: 'ユキナといっしょに、竜の門をこえて「星竜山」をのぼろう',
  peak: '星竜山の頂上をめざそう（とちゅうに山小屋があるらしい）',
  hut: '山小屋で休んだら、星竜山の頂上へ向かおう',
  clear: '第3章クリア！自由に冒険しよう（続きはアップデートで！）',
};

// パーティー全員で 見る イベント
export const CH3_STORY_SCRIPTS = ['ch3_intro', 'c3_arrive', 'c3_village_arrive', 'c3_elder', 'c3_icecave_enter', 'c3_mammoth_event',
  'c3_kanatoko_arrive', 'c3_donga', 'c3_golem_event', 'c3_yunoha_arrive', 'c3_obaba', 'c3_volcano_enter', 'c3_flare_event',
  'c3_temple_enter', 'c3_courage_event', 'c3_wz_n', 'c3_wz_e', 'c3_wz_s', 'c3_wz_w', 'c3_bond_plate', 'c3_peak_enter', 'c3_hut_arrive',
  'c3_ignia_event', 'c3_m2_guards', 'c3_fox_home',
  'c3_cart_m1_camp', 'c3_cart_m1_left', 'c3_cart_m1_right', 'c3_cart_m2_hub', 'c3_cart_m2_a', 'c3_cart_m2_b', 'c3_cart_m2_c'];

// ───── しかけ ─────
// トロッコ（maps/ch3.js の CART_RIDES）
function cartSteps(x, id) {
  const r = CART_RIDES[id];
  const leg = r.lever && x.flag(r.lever) ? r.on : r.off;
  const [tx, ty, dir] = leg.to;
  return [
    ['choice', 'トロッコに乗る？', ['乗る', 'やめる'], [
      [['ride', leg.path], ['teleport', r.map, tx, ty, dir]],
      [],
    ]],
  ];
}

// レバー（ゴトン！と 行き先・流れが かわる）
function leverSteps(x, flag, onText, offText, sfx = 'door') {
  const on = !x.flag(flag);
  return [
    ...N('レバーを動かした！'),
    ['sfx', sfx], ['toggle', flag], ['sync'],
    ...N(on ? onText : offText),
  ];
}

// 温泉・大浴場（ただで HP・MPが 回復）
function bathSteps(first, after) {
  return [
    ...N(first),
    ['choice', 'お湯につかる？', ['つかる', 'やめる'], [
      [['fade', 'out'], ['sfx', 'heal'], ['heal'], ['wait', 900], ['fade', 'in'], ...N(after, 'HPとMPがすっかり回復した！')],
      [],
    ]],
  ];
}

// 3つの 試練: のりこえた 数（いま のりこえた ものを ふくめる）
function trialCount(x, just) {
  return TRIAL_FLAGS.filter((f) => f === just || x.flag(f)).length;
}

// 試練を 1つ のりこえた あと（3つ そろったら 竜の門が ひらく）
function trialDone(x, just) {
  const n = trialCount(x, just);
  if (n < 3) {
    return [
      ...N(`竜の門の紋章が、1つ光った気がする…。\n（3つの試練のうち、${n}つをのりこえた！）`),
      ['objective', C3_OBJ.temple],
    ];
  }
  const g = VIL.x + 16, gy = 32.5;
  return [
    ...N('……'),
    ...S('ふしぎな声', '3つの試練を、すべてのりこえし者たちよ…。\nそなたたちの勇気、ちえ、そしてきずな…たしかに見とどけた。', '竜の門は、今ひらかれる！'),
    ['shake'], ['flash'], ['sfx', 'sparkle'],
    ['fade', 'out'],
    ['teleport', 'north', g + 0.5, gy, 'up'],
    ['bgm', 'temple'],
    ['fade', 'in'],
    ['shake'],
    ...N('ゴゴゴゴゴ……！', '竜の門が、ゆっくりとひらいていく…！'),
    ['flag', 'c3_gate'], ['sync'],
    ['actor', 'yukina_g', { sprite: 'yukina', x: g + 0.5, y: gy + 7, dir: 'up' }],
    ['move', 'yukina_g', [[g + 0.5, gy + 1.2]]],
    ...S('ユキナ', '{name}さーん！', '竜の門が光るのが、村から見えました！\nとうとう…3つの試練をのりこえたんですね！',
      '星の竜さまを目覚めさせるには、竜のみこの歌がいります。\nわたしも、頂上までいっしょに行かせてください！'),
    ['remove', 'yukina_g'],
    ['sync'], ['guest', 'yukina'], ['sfx', 'join'],
    ...N('ユキナが仲間に加わった！'),
    ...S('ユキナ', '星竜山は、外はふぶき、中は氷のほらあなです。\nとちゅうに山小屋があるはずですから、そこで休みましょう。'),
    ['objective', C3_OBJ.gate],
  ];
}

// ちえの間: かがり火（日の 道すじ: 東 → 南 → 西 → 北 の じゅん）
const DIR_NAME = { n: '北', e: '東', s: '南', w: '西' };
function wisdomSteps(x, d) {
  if (x.flag('c3_wisdom')) return N('かがり火が、あかあかともえている。');
  if (x.flag(WISDOM_FLAGS[d])) return N('もう火がついている。');
  const lit = WISDOM_ORDER.filter((k) => x.flag(WISDOM_FLAGS[k]));
  const next = WISDOM_ORDER[lit.length];
  if (d !== next) {
    const reset = WISDOM_ORDER.map((k) => ['unflag', WISDOM_FLAGS[k]]);
    return [
      ...N(`${DIR_NAME[d]}のかがり火に、手をかざした…。`),
      ['sfx', 'debuff'],
      ...(lit.length ? N('しかし、ほかのかがり火まで、ふっと消えてしまった！') : N('しかし、火はつかなかった…。')),
      ...reset, ['sync'],
      ...N('（火をともすじゅんばんが、ちがうようだ。\n入り口のそばの石ばんを、もう一度読んでみよう）'),
    ];
  }
  const steps = [...N(`${DIR_NAME[d]}のかがり火に、手をかざした…。`), ['sfx', 'fire'], ['flag', WISDOM_FLAGS[d]], ['sync'], ...N('かがり火に、火がともった！')];
  if (lit.length + 1 < WISDOM_ORDER.length) return steps;
  return [
    ...steps,
    ['flash'], ['sfx', 'sparkle'],
    ...N('4つのかがり火が、いっせいに強くかがやいた！', 'まん中の星の台に、光が集まる…！'),
    ...S('ふしぎな声', '日はのぼり、日はしずみ、夜には動かぬ星がかがやく…。\n日と星の道すじを知る者よ。ちえの試練、ここに見とどけた。'),
    ['flag', 'c3_wisdom'], ['sync'],
    ...N('ちえの宝玉が光った！'),
    ...trialDone(x, 'c3_wisdom'),
  ];
}

// きずなの間: 3つの スイッチに いっしょに 乗る（ひとりでも 仲間が かわりに 乗ってくれる）
async function bondPlates(run) {
  // run.partyNow(): いっしょに いる 人（people）と 仲間（helpers: サポート・ゲスト・馬車）。world/scripts.js
  const { people: all, helpers } = run.partyNow();
  const people = all.filter((m) => m.inWorld && m.map === 'trial_bond');
  const onPlate = BOND_PLATES.map(([px, py]) => people.find((m) => Math.floor(m.x) === px && Math.floor(m.y) === py) || null);
  const players = onPlate.filter(Boolean).length;
  const free = BOND_PLATES.length - players;
  if (helpers.length < free) {
    await run.runSteps([
      ...N(`スイッチが1つ、かすかに光った…。\n（${BOND_PLATES.length}つのスイッチのうち、${players}つに人が乗っている）`),
      ...N('しかし、何も起こらない。', '（3つのスイッチに、いっしょに乗らないといけないようだ。\n仲間を連れてこよう。酒場や「仲間」のメニューで、仲間を集められるよ）'),
    ]);
    return;
  }
  const names = helpers.slice(0, free).map((c) => c.name);
  await run.runSteps([
    ...(names.length ? N(`${names.join('と')}が、のこりのスイッチに乗った！`) : N('みんなが、3つのスイッチに乗った！')),
    ['sfx', 'bond'], ['flag', 'c3_bond'], ['sync'], ['flash'],
    ...N('3つのスイッチが、まぶしくかがやいた！', '光の線がつながり、まん中の竜の像を、温かい光がつつんでいく…。'),
    ...S('ふしぎな声', '心を1つに合わせし者たちよ…。\nそなたたちのきずな、たしかに見とどけた。'),
    ...N('きずなの宝玉が光った！'),
    ...trialDone({ flag: (f) => !!run.owner.char.flags?.[f] }, 'c3_bond'),
  ]);
}

