js/shared/data/story-ch4-duna.js:
// 第4章 Step 6「砂の海賊と砂クジラ」の だいほん（story-ch4.js で まぜる）
// 南の砂ばくの 谷の 見張りに 手紙を 見せる（story-ch4.js の dunaLookout）→ 谷の 門が 開く（c4_duna）→ 砂の港ドゥナ
// → かしらバルガ（手紙を 読んでも「口だけなら、何とでも言える」）→ むすめの サラが 仲間に なる（ゲスト。c4_sara）
// → バルガの 試練: 東の「砂の古城」から、ぬすまれた「船のかじ」を 取りもどす
//   （1階の 2つの 石の 板を 同時に ふむ。家族なら 2人で、ひとりなら サラや 馬車の 仲間が もう1つを ふむ。c4_castle_gate）
//   → 2階の たからべやで 古城の よろい 2体 → 船のかじ（c4_castle）
// → バルガ「…むすめが、あんたたちを信じると言うなら」→ 砂の船「すなかぜ号」（c4_ship）で 砂の海へ（港から 港へ。第2章の しおかぜ号と おなじ）
// → 砂の海の まん中の「クジラの ねどこ」で 砂クジラ（すなかぜ号の かんぱんで ボス戦。砂に もぐる。battle-ch4.js）
// → 正気に もどった 砂クジラ「砂の底の神殿の 入口は、わたしが ねむっていた 所の 下だ」（c4_whale）
// → ドゥナの さんばしへ もどり、サラは パーティーから はなれて さんばしで 待つ → 第4章の 続きは アップデートで！
import { DUNA_POS, CASTLE_PLATES, CASTLE_GATE_FLAG, SANDSEA_POS } from '../maps/duna.js';
import { GUESTS } from './shops.js';
import { CH4_GUESTS } from './items-ch4.js';
import { innSteps } from './inn.js';

// サラ（ゲスト。items-ch4.js）を ゲストの 一覧に まぜる（world/party.js・world/scripts.js の GUESTS）
Object.assign(GUESTS, CH4_GUESTS);

const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
const N = (...lines) => lines.map((l) => ['say', null, l]);
// マスの まん中
const C = (p) => [p.x + 0.5, p.y + 0.5];

// 第4章 Step 6 の すすみかた（story-ch4.js の CH4_STEPS の うしろに つづく）
// c4_duna（谷の 門が 開いた）・c4_sara（サラが 仲間に なった）・c4_castle（船のかじを 取りもどした）・
// c4_ship（すなかぜ号に かじが ついた）・c4_whale（砂クジラが 正気に もどった）
export const DUNA_STEPS = ['c4_duna', 'c4_sara', 'c4_castle', 'c4_ship', 'c4_whale'];

// 目標（story-ch4.js の C4_OBJ に まぜる。名前は「その フラグの あとの 目標」）
// castlegate は 物語の すすみぐあいでは ない フラグ（c4_castle_gate）の あとの 目標
export const DUNA_OBJ = {
  duna: '砂の港ドゥナの「かしらの館」（広場の東）で、砂の海賊のかしらバルガに会おう',
  sara: '町の東の門を出て、がけの道を北へ。「砂の古城」から、ぬすまれた「船のかじ」を取りもどそう',
  castlegate: '鉄のこうしが開いた！北のかいだんから、砂の古城の2階へ上ろう',
  castle: '取りもどした船のかじを、ドゥナのかしらバルガ（かしらの館）にとどけよう',
  ship: 'さんばしの先の「すなかぜ号」で砂の海へ。まん中の「クジラのねどこ」をめざそう',
  // Step 6 の さいご。Step 7 で「さんばしの サラに 話す」に かえた（Step 6 の 版の 文は story-ch4.js の OLD_C4_OBJ.whale。repairObjective で 今の 文に なおる）
  whale: 'ドゥナのさんばしで待つサラに、声をかけよう（砂クジラの力は、もどったかな？）',
};

// パーティー全員で 見る イベント（リーダーの 世界で すすむ）
export const DUNA_STORY_SCRIPTS = [
  'c4_duna_arrive', 'c4_barga', 'c4_castle_enter', 'c4_castle2_enter', 'c4_castle_plate', 'c4_rudder_event', 'c4_rudder',
  'c4_sand_ship', 'c4_sea_to_duna', 'c4_whale_event',
];

// ───────────── かしらバルガ ─────────────
// はじめて 会う: 手紙を 読んでも「口だけなら、何とでも言える」→ サラ → バルガの 試練（サラが 仲間に なる）
function bargaFirst() {
  const [s0x, s0y] = [DUNA_POS.barga.x + 4.5, DUNA_POS.barga.y + 1.5];
  const [s1x, s1y] = [DUNA_POS.barga.x + 2.5, DUNA_POS.barga.y + 1.5];
  return [
    ['bgm', null],
    ...S('かしらバルガ', '…おまえたちか。王国の手紙を持ってきたというのは。'),
    ...N('（女王さまの手紙を、バルガにわたした…）'),
    ['takeItem', 'queen_letter'],
    ...N('バルガは、だまって手紙を読んでいる…。'),
    ...S('かしらバルガ', '「砂の海賊のみなさんに、あやまらなければ」…だと？', '…フン。口だけなら、何とでも言える。'),
    ...S('かしらバルガ', 'ひと月前、王国はおれたちに罪をきせて、国から追い出した。\n…おれの妻のミラが、守り星といっしょに消えたってのにな。',
      '王国のやつらは、ミラを探すどころか、\nおれたちを「どろぼう」とよんだんだ！'),
    ...S('かしらバルガ', '帰んな。王国の者の手は、かりねえ。'),
    ['hideNpc', 'sara_duna'],
    ['actor', 'sara_c', { sprite: 'sara', x: s0x, y: s0y, dir: 'left' }],
    ...S('少女の声', '待って、父さん！'),
    ['move', 'sara_c', [[s1x, s1y]]],
    ['face', 'sara_c', 'left'],
    ['if', (y) => y.flag('c4_sara_seen'), S('サラ', 'あんたたち…王都で会った…！'), []],
    ...S('サラ', '父さん、聞いて！\nネフィは…女王は、ずっと大臣にあやつられてたんだよ。', 'この人たちが、ネフィを助けてくれたんだ！'),
    ...S('かしらバルガ', '…サラ。'),
    ...S('サラ', '母さんは、水の神殿にいたの。きっと、まだ生きてる。', 'あたし、この人たちといっしょに、母さんを探しに行く！'),
    ...S('かしらバルガ', '……。'),
    ...S('かしらバルガ', '…よかろう。そこまで言うなら、試してやる。'),
    ...S('かしらバルガ', 'おれたちの砂の船「すなかぜ号」の、船のかじがぬすまれちまってな。\n東の「砂の古城」に住みついた、魔物どものしわざだ。'),
    ...S('かしらバルガ', 'かじを取りもどしてきたら、話を聞いてやる。\n…それができなきゃ、口だけのやつらと同じだ。'),
    ...S('サラ', 'あたしも行く！古城への道なら、あたしが知ってる。', 'あたしはサラ。ムチなら、だれにも負けないよ！'),
    ['remove', 'sara_c'],
    ['sync'], ['guest', 'sara'], ['sfx', 'join'],
    ...N('サラが仲間に加わった！'),
    ['flag', 'c4_sara'], ['sync'],
    ...S('かしらバルガ', '東の門の見張りには、話を通しておく。\n…サラ。むちゃは、するなよ。'),
    ['bgm', 'resume'],
    ['objective', DUNA_OBJ.sara],
  ];
}

// 船のかじを とどけた: バルガが みとめて、すなかぜ号で 砂の海へ
function bargaAccept() {
  return [
    ['bgm', null],
    ...S('サラ', '父さん！見て、船のかじ…取りもどしてきたよ！'),
    ...N('（船のかじを、バルガにわたした…）'),
    ['takeItem', 'ship_rudder'],
    ...S('かしらバルガ', '…！まちがいねえ。すなかぜ号のかじだ…。'),
    ...S('サラ', 'この人たちが、古城の魔物をやっつけて、取りもどしてくれたんだよ！'),
    ...S('かしらバルガ', '……。'),
    ...S('かしらバルガ', '…むすめが、あんたたちを信じると言うなら。', '…いや。おれも、信じよう。\n王国の手紙じゃねえ。あんたたちの、その目をな。'),
    ['bgm', 'duna'],
    ...S('かしらバルガ', '水の守り星と、ミラは…きっと、砂の海の底の「砂の底の神殿」だ。\nおれたち砂の海賊が、ずっと昔から守ってきた、古い神殿よ。'),
    ...S('かしらバルガ', 'だが、神殿は砂の海の底にしずんでいて、\n入口の場所は、もう、だれも知らねえ…。'),
    ...S('かしらバルガ', 'それに、ひと月前から、砂の海の主「砂クジラ」があばれだしてな。\n砂の海のまん中の「クジラのねどこ」には、だれも近づけねえ。', '…もしかしたら、そこに何かあるのかもしれん。'),
    ['sfx', 'key'],
    ...S('かしらバルガ', 'すなかぜ号に、かじをつけておいた。\nさんばしの先の船に話しかければ、いつでも砂の海へ出られる。'),
    ...S('かしらバルガ', 'サラ。この人たちを、たのんだぞ。'),
    ...S('サラ', 'まかせて、父さん！'),
    ...N('（すなかぜ号で、砂の海へ出られるようになった！）'),
    ['flag', 'c4_ship'], ['sync'],
    ['bgm', 'resume'],
    ['objective', DUNA_OBJ.ship],
  ];
}

function bargaTalk(x) {
  if (!x.flag('c4_sara')) return bargaFirst();
  if (!x.flag('c4_castle')) {
    return S('かしらバルガ', '砂の古城は、町の東の門を出て、がけの道を北だ。', 'ぬすまれた船のかじを取りもどしてこい。\n…話は、それからだ。');
  }
  if (!x.flag('c4_ship')) return bargaAccept();
  if (!x.flag('c4_whale')) {
    return S('かしらバルガ', 'すなかぜ号は、さんばしの先につないである。',
      '砂クジラは、ひと月前から、ずっとあれくるっている。\n砂にもぐったら、どこから飛び出してくるか分からねえ。気をつけろよ。');
  }
  return S('かしらバルガ', '砂の底の神殿の入口は、クジラのねどこの下か…。', 'ミラ…。待っていろ。\nかならず、むかえに行く。');
}

// ───────────── 砂の古城の 2つの 石の 板 ─────────────
// 2つの 板に 同時に 人が 乗ると、北の 鉄の こうしが 開く（第3章の きずなの間と おなじ 考え方）
// 家族で 2人 いじょう いる ときは、2人で ふむ。ひとりの ときは、サラ（ゲスト）か 馬車・酒場の 仲間が もう1つを ふんで くれる
const OPEN_GATE = () => [
  ['sfx', 'click'],
  ...N('2つの石の板が、同時にゴトン…としずんだ！'),
  ['flag', CASTLE_GATE_FLAG], ['sync'],
  ['sfx', 'door'], ['shake'],
  ...N('ゴゴゴゴ…！北の鉄のこうしが、ゆっくりと上がっていく！'),
  ['objective', DUNA_OBJ.castlegate],
];

export async function castlePlates(run) {
  // run.partyNow(): いっしょに いる 人（people）と 仲間（helpers: サポート・ゲスト・馬車）。world/scripts.js
  const { people: all, helpers } = run.partyNow();
  const people = all.filter((m) => m.inWorld && m.map === 'sand_castle1');
  const onPlate = CASTLE_PLATES.map(([px, py]) => people.find((m) => Math.floor(m.x) === px && Math.floor(m.y) === py) || null);
  const players = onPlate.filter(Boolean).length;
  if (!players) return;
  if (players >= CASTLE_PLATES.length) {
    await run.runSteps(OPEN_GATE());
    return;
  }
  const [ox, oy] = CASTLE_PLATES[onPlate.findIndex((m) => !m)];
  // 家族: もう 1人が、反対がわの 板に 乗るのを 待つ
  if (people.length >= 2) {
    await run.runSteps(N('石の板が、ゴトン…としずんだ。', '（反対がわの石の板にも、だれかが乗らないと…！\n家族のもう1人に、ふんでもらおう）'));
    return;
  }
  // ひとり: サラ（ゲスト）が いれば サラ、いなければ 馬車・酒場の 仲間
  const sara = helpers.find((h) => h.id === CH4_GUESTS.sara.id);
  const helper = sara || helpers[0];
  if (!helper) {
    await run.runSteps(N('石の板が、ゴトン…としずんだ。', 'しかし、何も起こらない…。',
      '（1人では、2つの板を同時にふめない。\n仲間を連れてこよう。酒場や「仲間」のメニューで、仲間を集められるよ）'));
    return;
  }
  if (helper === sara) {
    await run.runSteps([
      ...N('石の板が、ゴトン…としずんだ。'),
      ...S('サラ', 'もう1つの板は、あたしにまかせて！'),
      ['actor', 'sara_c', { sprite: 'sara', x: ox + 0.5, y: oy + 0.5, dir: 'up' }],
      ['look', ox + 0.5, oy + 0.5],
      ['sfx', 'whip'],
      ...N('サラはムチを柱にまきつけて、ひらりと反対がわの板にとびうつった！'),
      ...OPEN_GATE(),
      ['remove', 'sara_c'],
      ['look'],
    ]);
    return;
  }
  await run.runSteps([...N('石の板が、ゴトン…としずんだ。', `${helper.name}が、反対がわの石の板に乗った！`), ...OPEN_GATE()]);
}

// ───────────── 船のかじ（砂の古城 2階の たからべや）─────────────
function rudderEvent() {
  return [
    ['bgm', null],
    ...N('へやのおくに、大きな船のかじが立てかけてある！'),
    ...S('サラ', 'あった！すなかぜ号のかじだ！'),
    ['sfx', 'rumble'], ['shake'],
    ...N('そのとき、かじの両わきのよろいが、ギギギ…と動き出した！'),
    ...S('古城のよろい', 'ガシャン…ガシャン…！\nタカラ…ワタサヌ…！'),
    ['battle', 'rudder_guard'],
    ['bgm', null],
    ...N('古城のよろいは、ガラガラとくずれおちた…。'),
    ['item', 'ship_rudder'],
    ['flag', 'c4_castle'], ['sync'],
    ...S('サラ', 'やった…！これで、父さんも分かってくれるはず！', '早く、ドゥナへもどろう！'),
    ['bgm', 'resume'],
    ['objective', DUNA_OBJ.castle],
  ];
}

// ───────────── すなかぜ号と 砂の海 ─────────────
const toSandSea = () => [
  ['sfx', 'door'], ['fade', 'out'],
  ['teleport', 'sand_sea', SANDSEA_POS.arrive.x, SANDSEA_POS.arrive.y, 'down'],
  ['bgm', 'sand_sea'], ['fade', 'in'],
];

// 砂クジラの ねどこに 近づいた（すなかぜ号の かんぱんで ボス戦）
function whaleEvent() {
  const [nx, ny] = C(SANDSEA_POS.nest);
  return [
    ['bgm', null],
    ['shake'],
    ...N('とつぜん、砂の海が大きくうねった…！'),
    ...S('サラ', 'なに、これ…！？\n砂の下に、何か大きなものがいる！'),
    ['look', nx, ny],
    ['sfx', 'rumble'], ['shake'],
    ['showMon', 'sand_whale'],
    ...N('ザバアアン…！', '砂の中から、山のように大きなクジラが飛び出した！'),
    ...S('サラ', '砂クジラ…！砂の海の主だよ！', 'でも、目が赤く光ってる…！\nいつもの、やさしい砂クジラじゃない！'),
    ...S('砂クジラ', 'グオオオオ…ン……！'),
    ['showMon', null],
    ['look'],
    ...S('サラ', '来るよ！すなかぜ号の上で、むかえうつしかない！'),
    ['bgm', 'whale'],
    ['battle', 'sand_whale'],
    ...whaleAfter(),
  ];
