// 砂クジラが 正気に もどる → 神殿の 入口の 話 → ドゥナへ もどる
function whaleAfter() {
  const [nx, ny] = C(SANDSEA_POS.nest);
  return [
    ['bgm', null],
    ...N('砂クジラは、大きく体をふるわせると――', '赤く光っていた目が、ゆっくりと、おだやかな青にもどっていった…。'),
    ['flag', 'c4_whale'], ['sync'],
    ['look', nx, ny],
    ['bgm', 'sand_sea'],
    ...S('砂クジラ', '…わたしは…何を…。', '…そうか。ひと月前、水鏡の魔人のあやしい歌を聞いてから、\nずっと、わるい夢を見ていたようだ…。'),
    ...S('砂クジラ', '小さき者たちよ。わたしを止めてくれたこと、礼を言う。'),
    ...S('サラ', '砂クジラ…！母さんを…水のみこのミラを、知らない？'),
    ...S('砂クジラ', 'みこ…。ひと月前の夜、水鏡の魔人が、青く光る星と、\n1人のみこをつれて、砂の海の底へしずんでいった…。'),
