// 第3章クリアの あとの 長老ハクゲン（story.js が c3_elder に かぶせる）
export function elderCh4(x) {
  if (!x.flag('c4_start')) return introCh4();
  if (!x.flag('c4_ami')) {
    return S('長老ハクゲン', '砂の国へは、風の笛でアステルさまを呼んで、\n風の海の南のはしをこえるのじゃ。', '{name}、気を付けて行っておいで。');
  }
  if (x.flag('c4_zaid')) {
    return S('長老ハクゲン', '王都の大臣が、砂の魔神じゃったとな…！\n女王さまが正気にもどられて、本当によかった。',
      '砂嵐も弱くなり、南の港へも行けるようになったそうじゃな。\n砂の海賊か…。気を付けて行っておいで。');
  }
  if (x.flag('c4_mirror')) {
    return S('長老ハクゲン', 'なんと…王家のピラミッドで、月の鏡を見つけたとな！',
      '本当のすがたをうつす鏡…。\nその鏡が、女王さまを助けるかぎになるやもしれん。気を付けて行っておいで。');
  }
  if (x.flag('c4_fountain')) {
    return S('長老ハクゲン', '王都の女王さまが、水がめの中で泣いておられた…じゃと？',
      '本当のすがたをうつす「月の鏡」か…。\nまやかしの力が、はたらいておるのかもしれん。気を付けて行っておいで。');
  }
  if (x.flag('c4_capital')) {
    return S('長老ハクゲン', '砂の国の都、サファラに着いたそうじゃな。',
      '都にも、水が足りぬとは…。\n水の守り星に、何が起きておるのか…。気を付けて行っておいで。');
  }
  if (x.flag('c4_scorpion')) {
    return S('長老ハクゲン', '砂の国の村に、水がもどったそうじゃな。\nアステルさまも、よろこんでおられたぞ。',
