      '水鏡の魔人モルガナ…。\n水の守り星を持ち去ったのは、その者かもしれん。',
      '砂の海賊は、昔から砂の海の底の古い神殿を守ってきた一族じゃ。\nかれらなら、何か知っておるかもしれんのう。');
  }
  if (x.flag('c4_mirror')) {
    return S('学者ハサン', 'おお…！それが、月の鏡か…！\nまさか、本当に王のへやから持ち帰るとは…。',
      'まぼろしも、まやかしも、月の鏡の前では本当のすがたをあらわす…。\nじゃが、月の鏡は、月の光の下でこそ、本当の力を出すという。',
      '夜の水がめにうつっていた、本当の女王さま…。\n夜の宮殿で、女王さまを、その鏡にうつしてみるのじゃ。',
      'それと、古い書物には、こうも書いてあった。\n「まぼろしには、影がない。本物の足もとにだけ、影がある」とな…。');
  }
  if (x.flag('c4_pyramid')) {
    return S('学者ハサン', 'なに、ピラミッドの入口が開いたとな！\nほっほっ、わしの読みは当たっておったか。',
      'ピラミッドの中では、帰り道の羽も、みちびきの糸も、使えんという。\n薬草をたっぷり持って、来た道を歩いてもどるつもりで行くのじゃぞ。',
      '王家の宝には、のろいがかけられた物もあると聞く。\n強い力には、気を付けるのじゃ。');
  }
  if (x.flag('c4_song')) {
    return S('学者ハサン', `ピラミッドの入口は、${OBELISK_RIDDLE}。`,
      'オベリスクは、王都の東の門を出た先、王家のピラミッドの前に立っておる。\n昼の12時ごろに、オベリスクのまわりを調べてみなされ。',
      '王都の宿屋で「昼まで休む」と、ちょうど昼の前に目が覚めるぞ。\nそれから歩いて行けば、間に合うじゃろう。');
  }
  if (x.flag('c4_hassan')) {
    return S('学者ハサン', '月の鏡は、王家のピラミッドの「王のへや」じゃ。',
      `ピラミッドの入口は、${OBELISK_RIDDLE}。\n昼の12時ごろに、オベリスクのまわりを調べてみなされ。`,
      x.flag('c4_song') ? 'わらべ歌も、ちゃんと覚えたかの？\n太陽・砂・月・星…歌のじゅんばんが、大事なのかもしれんぞ。' : '町の子どもたちの、わらべ歌も聞いておくのじゃぞ。');
  }
  if (!x.flag('c4_fountain')) {
    return S('学者ハサン', 'ほっほっ。わしは学者のハサン。\nこの国の、古い言い伝えを調べておる。',
      'この砂の国には、王家に伝わる宝がいくつもあってのう。\n王家のピラミッドには、むかしの王さまたちが、今もねむっておるそうじゃ。',
      x.flag('c4_queen') ? '女王さまの様子が、おかしい？…ふむ。\nわしには分からんが…何か、ふしぎな力がはたらいておるのかもしれん。' : '旅の人かね。ゆっくり見ていきなされ。');
  }
  const allSongs = SONG_FLAGS.every((f) => x.flag(f));
  return [
    ...S('学者ハサン', 'なに、夜の水がめに、本当の女王さまがうつって…\n「月の鏡で、うつして」と…！？'),
    ...S('学者ハサン', '月の鏡…。それは、王家に伝わる、本当のすがたをうつす鏡じゃ。',
      'まぼろしも、まやかしも、月の鏡の前では、本当のすがたをあらわすという…。'),
    ...S('学者ハサン', '月の鏡は、王家のピラミッドの「王のへや」に、ねむっておる。',
      'じゃが、ピラミッドの入口は、ふだんは大きな石でとざされておるのじゃ。\n古い書物には、こう書いてある。'),
    ['sfx', 'sparkle'],
    ...S('学者ハサン', `「ピラミッドの入口は…\n${OBELISK_RIDDLE}」`),
    ...S('学者ハサン', 'オベリスクとは、砂ばくに立つ、大きな石の柱のことじゃ。\n王都の東の門を出た先、王家のピラミッドの前に、1本立っておる。',
      '太陽が真上…つまり、昼の12時ごろじゃな。'),
    ...S('学者ハサン', 'それと…ピラミッドの中には、ふしぎなしかけがあるという。\n町の子どもたちが歌う、古いわらべ歌に、そのヒントがかくされておるそうじゃ。'),
    ['flag', 'c4_hassan'], ['sync'],
    ...(allSongs ? [...N('（わらべ歌なら、もう4人ぶん聞いている…！）'), ...songDone({ flag: (f) => f === 'c4_hassan' || x.flag(f) })] : [['objective', C4_OBJ.hassan]]),
  ];
}

// ───────────── Step 4: 王家のピラミッド ─────────────
// オベリスクの 影の ようす（パーティーの 時計 x.clock。ない ときは 昼すぎ）
const sunOf = (x) => sunSide(x.clock ?? 0.4);
function shadowLine(x) {
  return {
    am: '（オベリスクの影は、西の方へ長くのびている…）',
    noon: '（オベリスクの影が、まっすぐ北へのびて…\nピラミッドの入口の石を、ぴたりとさしている！）',
    pm: '（オベリスクの影は、東の方へ長くのびている…）',
  }[sunOf(x)] || '（お日さまが出ていなくて、オベリスクの影は見えない…）';
}
// 日時計の とびらが 開く 時間か（リーダーの 時計で 11時〜13時）
export const doorOpenTime = (x) => x.clock !== null && x.clock !== undefined && isNoonFrac(x.clock);

// オベリスク（大きな 石の 柱。きざまれた ことばと 影）
function obeliskTalk(x) {
  if (x.flag('c4_pyramid')) {
    return [...N('大きな石の柱、オベリスクだ。', OBELISK_TEXT), ...N(shadowLine(x)), ...N('（ピラミッドの入口のとびらは、もう開いている）')];
  }
  const steps = [...N('大きな石の柱だ。てっぺんが、金色にかがやいている。', `柱には、古い文字がきざまれている…。\n${OBELISK_TEXT}`), ...N(shadowLine(x))];
  if (sunOf(x) === 'noon') steps.push(...N('（影がさしている入口の石を、調べてみよう！）'));
  else if (x.flag('c4_song')) steps.push(...N('（お日さまが真上に来たら、影はどこをさすのだろう…？）'));
  return steps;
}

// 日時計の とびら（ピラミッドの 南の まん中）。昼の 12時ごろ（11時〜13時）に しらべると 開く。一度 開いたら しまらない
function pyramidDoor(x) {
  const look = N('大きな石のとびらだ。まん中に、太陽のしるしがきざまれている。', 'おしても引いても、びくともしない…。');
  // ハサンの なぞと わらべ歌が そろう 前は、ふしぎな とびら だけ
  if (!x.flag('c4_song')) return [...look, ...N(shadowLine(x))];
  if (!doorOpenTime(x)) {
    const when = {
      am: '（オベリスクの影は、まだ西へのびている。\nお日さまが、もっと高くのぼるまで待とう）',
      pm: '（オベリスクの影は、もう東へのびている。\n昼の12時ごろを、すぎてしまったようだ…）',
    }[sunOf(x)] || '（お日さまが出ていないので、オベリスクの影ができない…。\n昼になったら、また来よう）';
    return [...look, ...N(when), ...N('（王都の宿屋で「昼まで休む」と、お昼に合わせられる）')];
  }
  return [
    ['bgm', null],
    ['look', PYRAMID_POS.obelisk.x + 0.5, PYRAMID_POS.obelisk.y - 1],
    ...N('お日さまが、真上にのぼった…。', 'オベリスクの影が、まっすぐ北へのびて…\nとびらの太陽のしるしに、ぴたりと重なった！'),
    ['sfx', 'sparkle'], ['flash'],
    ...N('太陽のしるしが、まぶしく光り始めた…！'),
    ['sfx', 'rumble'], ['shake'],
    ...N('ゴゴゴゴゴ…！'),
    ['flag', 'c4_pyramid'], ['sync'],
    ['look', PYRAMID_POS.door.x + 0.5, PYRAMID_POS.door.y + 0.5],
    ...N('大きな石のとびらが、ゆっくりと開いていく…！'),
    ['look'],
    ['bgm', 'resume'],
    ...N('（王家のピラミッドの入口が開いた！\n一度開いたとびらは、もうしまらないようだ）'),
    ['objective', C4_OBJ.pyramid],
  ];
}

// 歌の ボタン（1階）。わらべ歌の 順番（太陽 → 砂 → 月 → 星）に おす。まちがえると 足もとが ぬけて 地下へ（みんな いっしょに）
const BUTTON_ORDER = ['sun', 'sand', 'moon', 'star'];
function pressButton(x, key) {
  const b = PYR_BUTTONS.find((k) => k.key === key);
  if (x.flag(PYR_DOOR_FLAG)) return N(`${b.name}のしるしのボタンは、光ったままだ。`);
  if (x.flag(b.flag)) return N(`${b.name}のしるしのボタンは、もう光っている。`);
  const next = BUTTON_ORDER.find((k) => !x.flag(PYR_BUTTONS.find((o) => o.key === k).flag));
  const steps = [...N(`${b.name}のしるしのボタンをおした！`), ['sfx', 'click']];
  if (key === next) {
    steps.push(['flag', b.flag], ['sfx', 'sparkle']);
    if (key !== 'star') return [...steps, ...N(`${b.name}のしるしが、金色に光った！`), ['sync']];
    return [
      ...steps,
      ...N(`${b.name}のしるしが、金色に光った！`, '4つのボタンが、全部光った！'),
      ['sync'],
      ['sfx', 'rumble'], ['shake'],
      ['look', 15.5, 8],
      ...N('ゴゴゴゴ…！', '北の石のとびらが、開いていく！'),
      ['look'],
      ['objective', C4_OBJ.pb],
    ];
  }
  // まちがい: ボタンの 光は みんな 消えて、足もとの ゆかが ぬける（地下の ミイラのへやへ）
  return [
    ...steps,
    ...N('カチッ…。'),
    ...PYR_BUTTONS.map((o) => ['unflag', o.flag]),
    ['sync'],
    ['sfx', 'rumble'], ['shake'],
    ...N('ボタンの光が、全部消えた…！', '足もとのゆかが、ぬけた！'),
    ['sfx', 'fall'],
    ['fade', 'out'],
    ['teleport', PYR_FALL.map, PYR_FALL.x, PYR_FALL.y, 'down'],
    ['fade', 'in'],
    ['shake'],
    ...N('ドサッ！'),
    ...N('…ここは、ピラミッドの地下のようだ。\n東のかいだんから、1階へもどれそうだ。'),
    ...N(x.flag('c4_song') ? '（ボタンは、わらべ歌の順番におすのかもしれない…。\n♪お日さまのぼって、砂がまう…）' : '（ボタンをおす順番に、ひみつがありそうだ…）'),
  ];
}

// 金色の つぼ（のろいのつぼ が 化けている。たおすと 中の 宝が 手に入る）
function goldPot(x, flag, reward) {
  return [
    ...N('金色にかがやく、大きなつぼだ。', 'つぼの中で、何かがきらりと光った…？'),
    ['choice', 'のぞいてみる？', ['のぞく', 'やめる'], [
      [
        ...N('つぼのふたが、ガタガタ…！'),
        ['sfx', 'dark'], ['shake'],
        ...N('のろいのつぼだった！'),
        ['battle', 'pot_ambush'],
        ['flag', flag],
        ...N('のろいのつぼを、やっつけた！', 'われたつぼの中に、何かが入っている…。'),
        reward,
      ],
      N('…何だか、あやしい気がする。やめておこう。'),
    ]],
  ];
}

// ミイラの王アンク（4階の 王のへや）
function ankuEvent() {
