  return [
    ['bgm', null],
    ['look', ax, ay - 1],
    ...N('へやのおくに、金色の台と、2つのひつぎ…。', 'まん中に、ほうたいにまかれた王が立っている…！'),
    ['sfx', 'dark'], ['shake'],
    ...S('ミイラの王アンク', '……だれだ……。', '王のねむりを……さまたげる者は……！'),
    ...S('ミイラの王アンク', '月の鏡を……うばいに来たか……。\nならぬ……。王家の宝は……だれにも、わたさぬ……！'),
    ['sfx', 'rumble'],
    ...N('ひつぎのふたが開いて、ミイラ兵たちが起き上がった！'),
    ...S('ミイラの王アンク', 'わが兵よ……目を覚ませ……！'),
    ['look'],
    ['battle', 'mummy_king'],
    ['bgm', null],
    ['look', ax, ay - 1],
    ...N('ミイラの王アンクは、ひざをついた…。'),
    ...S('ミイラの王アンク', '……その手の……紋章……。\nそうか……そなたたちが……星の光の子ら……。',
      '……月の鏡は……まやかしを、やぶるもの……。\nわが王家の子を……ネフィを……たのむ……。'),
