}

// 月の鏡（Step 4 の さいご）
function takeMirror() {
  return [
    ...N('まるい鏡が、月の光のように、青白く光っている…。'),
    ['sfx', 'sparkle'],
    ['item', 'moon_mirror'],
    ['flag', 'c4_mirror'], ['sync'],
    ...N('鏡をのぞきこむと…自分たちのすがたが、ありのままにうつっている。'),
    ...N('（学者ハサンは、「まぼろしも、まやかしも、月の鏡の前では、\n本当のすがたをあらわす」と言っていた…）'),
    ...N('（夜の宮殿で、女王さまを月の鏡にうつしてみよう。\n帰りは、来た道を歩いてもどろう）'),
