// ───────────── Step 5: 月の鏡と 大臣の 正体 ─────────────
// 王の間の 場所（フィールドの マスの まん中）: 玉座の 女王・となりの 大臣・とびらの 前に 立つ パーティー
const HALL = {
  queen: () => C(SAFARA_POS.throne),
  zaid: () => SF(27, 25),
  party: () => SF(25, 28),
};

// 夜の 中庭: 王の間へ つづく とびらを 月の鏡で てらすと、まやかしの カギが とける（リーダーの 時計で 夜。昼は 鏡が くもる）
function courtDoor(x) {
  const look = N('中庭と王の間をつなぐ、がんじょうなとびらだ。', 'カギがかかっていて、びくともしない…。');
  if (!x.flag('c4_mirror')) return look;
  if (!x.night) {
    return [...look, ...N('月の鏡を、とびらにかざしてみた…。\nでも、鏡はくもったように、光をうしなっている。',
      '（月の鏡は、月の光の下でこそ、本当の力を出すのかもしれない。\n夜になったら、もう一度来よう）')];
  }
  return zaidEvent();
}

// 大臣ザイードの 正体（月の鏡）→ 大臣ザイード（まぼろしの 分身）→ 砂の魔神ザイード → 女王が 目を 覚ます
function zaidEvent() {
  const [qx, qy] = HALL.queen();
  const [zx, zy] = HALL.zaid();
  const [px, py] = HALL.party();
  return [
    ['bgm', null],
    ...N('とびらの向こうから、ひそひそと話し声が聞こえる…。'),
    ...S('大臣ザイードの声', '…よいですか、女王さま。\n明日も、民にこう言うのです。'),
    ...S('女王ネフィの声', '…水の守り星は…砂の海賊が…ぬすんだのです…。'),
    ...S('大臣ザイードの声', 'ククク…それでよい…。'),
    ['sfx', 'sparkle'],
    ...N('そのとき、月の鏡が、青白く光り始めた…！', '鏡の光が、とびらのカギ穴にさしこむと――'),
    ['sfx', 'door'],
    ...N('カチリ…。', 'とびらにかけられていた、まやかしのカギがとけた！'),
    ['fade', 'out'],
    ['teleport', 'south', px, py, 'up'],
    ['actor', 'nefi_c', { sprite: 'nefi', x: qx, y: qy, dir: 'down' }],
    ['actor', 'zaid_c', { sprite: 'zaid', x: zx, y: zy, dir: 'left' }],
    ['fade', 'in'],
    ['look', qx + 1, qy + 1],
    ...N('月明かりの王の間で、女王さまと大臣ザイードが向かい合っている…。'),
    ['face', 'zaid_c', 'down'],
    ...S('大臣ザイード', '…！だれだ！', '夜ふけに、王の間へしのびこむとは…。\n…きさまら、あの時の旅の者か！'),
    ...S('女王ネフィ', '…水の守り星は…砂の海賊が…。'),
    ...N('女王さまは、つめたい目のまま、同じ言葉をくりかえしている…。', '（今だ！月の鏡で、女王さまをうつそう！）'),
    ['sfx', 'sparkle'], ['flash'],
    ...N('{name}は、月の鏡を高くかかげた！', '月の光が、まっすぐに女王さまをてらす…！'),
    ['showMon', 'zaid_demon'],
    ...N('鏡の中に…女王さまのうしろに立つ、大きな砂の魔神がうつっている…！',
      '魔神の手から、黒い糸のようなものがのびて…\n女王さまの心を、あやつっている…！'),
    ['showMon', null],
    ['sfx', 'dark'], ['shake'],
    // 鏡に てらされた 大臣の 影が、ゆかに 大きな 魔神の 形で のびる（Step 3 の 中庭と おなじ 影）
    ['actor', 'zaid_shade', { sprite: 'zaid_demon', x: zx, y: zy + 1.7, dir: 'down' }],
    ...S('大臣ザイード', '……見たな。'),
    ['remove', 'zaid_shade'],
    ...S('大臣ザイード', 'ククク…あの小むすめを、水鏡にとじこめて、あやつり…\nこの国の水を、すべていただくはずだったものを…。'),
    ...S('大臣ザイード', 'じゃまをする者は、まぼろしの中で、まよい消えるがいい！'),
    ['sfx', 'dark'], ['flash'],
    ['look'],
    ['bgm', 'sand_demon'],
    ['battle', 'zaid'],
    // ── 真の すがた（あいだに 月の鏡の 光。HPは ぜんぶ・MPは 少しだけ）──
    ['bgm', null],
    ['look', zx, zy],
    ...S('大臣ザイード', 'ぐぬぬ…！月の鏡さえ、なければ…！', '…よかろう。ならば、本当のすがたで相手をしてやろう！'),
    ['sfx', 'rumble'], ['shake'], ['flash'],
    ['remove', 'zaid_c'],
    ['actor', 'demon_c', { sprite: 'zaid_demon_true', x: zx, y: zy, dir: 'down' }],
    ...N('大臣の体が、さらさらと砂になってくずれ――', '大きな砂の魔神のすがたになった！'),
    ...S('砂の魔神ザイード', 'グオオオ…！われこそは、砂の魔神ザイード！\n四ツ影の1人、水鏡の魔人モルガナさまのしもべなり！'),
    ...S('砂の魔神ザイード', 'この国の水は、すべてモルガナさまのもの…！\nきさまらも、砂にうもれて消えるがいい！'),
    // 月の鏡の 光: HPは ぜんぶ（たおれた 人も 起きる）、MPは 少しだけ（まぼろしに 使った MPは もどらない。tools/sim.js の ch4zaid と おなじ）
    ['sfx', 'sparkle'], ['flash'],
    ...N('そのとき、月の鏡が、やさしく光った…！', '月の光が、みんなの体をつつみこむ…。'),
    ['sfx', 'heal'], ['heal', { mp: 0.3 }],
    ...N('みんなのHPが回復した！\nMPも、少しだけ回復した！'),
    ['look'],
    ['bgm', 'sand_demon'],
    ['battle', 'zaid_demon'],
    ...zaidAfter(),
  ];
}

// 砂の魔神ザイードを たおした: 女王が 目を 覚ます → 女王の 話と 手紙
function zaidAfter() {
  const [qx, qy] = HALL.queen();
  const [zx, zy] = HALL.zaid();
  return [
    ['bgm', null],
    ['look', zx, zy],
    ...S('砂の魔神ザイード', 'グ…グオオ…！', 'バカな…このわたしが…。\n…モルガナさま…お…ゆるし…を…。'),
    ['sfx', 'rumble'], ['shake'],
