export function elderCh5(x) {
  if (!x.flag(C5.hood)) return festival();
  if (!x.flag(C5.stones)) {
    return S('ホシミばあちゃん', '守り星の石に、紋章をかざしておくれ。', '…さっきのフードの子のことは、今は、気にせんでええ。');
  }
  if (!x.flag(C5.wings)) return astelScene();
  if (!x.flag(C5.veil)) {
    return S('ホシミばあちゃん', '星の羽…！なんと美しい光じゃ。', '風の笛でアステルさまを呼んで、空の上で「雲の上へ」とねがってごらん。');
  }
  if (!x.flag(BOOK_FLAG) && !x.flag(C5.tower)) return bookScene();
  if (!x.flag(C5.tower)) {
    return S('ホシミばあちゃん', '星の塔は、村の北の山じゃ。\nとびらに紋章をかざしてごらん。', '塔の中は長い。4階に、休むための場所があるそうじゃよ。');
  }
  if (!x.flag(C5.sky)) {
    return S('ホシミばあちゃん', '書物には、こうも書いてあった。\n「星座のゆかは、夜にこそ道を教える」…とな。', '{name}、むりはせんでな。\n4階の休み所で、しっかり休むんじゃよ。');
  }
  // Step 3・4（story-kumoi.js）。守り星の かけらの あとは Step 5（story-hoshiyomi.js）
  if (!x.flag('c5_shard')) return elderKumoi(x);
  // 長ソラネから 大地の 神殿の 話を 聞いた あとは Step 6・7（story-earth.js）
  if (!x.flag('c5_root')) return elderHoshiyomi(x);
  // ノクト（本気）を たおした あと（エンディングの 続き・クリアの あと）は Step 9（story-castle-top.js）
  if (x.flag('c5_nocto2')) return elderTop(x);
  return elderEarth(x);
}

