// 第5章 Step 6・7: 本物の ノクトに 会った あとの 長ソラネ・ピピ（story-earth.js）
import { soraneEarth, pipiEarth } from './story-earth.js';

const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
const N = (...lines) => lines.map((l) => ['say', null, l]);

// ───── 物語の すすみかた（CH5_STEPS の c5_sky の うしろ。plan-ch5.md の 13 の 名前の 約束）─────
export const KUMOI_STEPS = [K5.kumoi, K5.hanono, K5.pipi, K5.ruin, K5.gaia, K5.shard];

// ───── 目標 ─────
