  const G = KUMOI_POS.gate[0];
  return [
    ['bgm', null],
    ['sfx', 'wind'],
    ...N('アステルは、星の羽を大きく広げて、天のとばりの穴をくぐりぬけた…！', '雲をぬけると――'),
    ['bgm', 'kumoi'],
    ['flash'],
    ...N('目の前いっぱいに、白い雲の海が広がっていた。', '雲の海の上に、大小の島が、いくつもうかんでいる…！'),
    ...S('星の竜アステル', 'ここが、空にうかぶ島々…。\nクモイ地方か。'),
    ...S('星の竜アステル', '…見よ。島のふちが、雲にとけている。\n木も柱も、かたむいて…。', 'やはり、島は少しずつ、しずんでいるのだ。'),
    ...S('星の竜アステル', 'それに、島のまわりの風が、ひどくあれている。\nわたしが飛べるのは、このいちばん大きな島の上だけのようだ。'),
    ['look', G.x + 1, G.y],
    ...N('いちばん大きな島の上に、町が見える…。'),
    ...S('星の竜アステル', 'あの町で、話を聞いてみよう。'),
    ['look'],
    ['flag', K5.kumoi], ['sync'],
    ...N('（竜の上では、Aボタンか「降りる」でおりられる。\n町の門は、島の北にある）'),
    ['objective', OBJ.kumoi],
  ];
}

// ───────────── ハネノの 町（門番・長ソラネ・ピピ）─────────────
function townArrive() {
