function soraneScene() {
  return [
    ['bgm', null],
    ...S('長ソラネ', 'ようこそ、ハネノの町へ。\nわたしは、この町の長、ソラネです。'),
    ...S('長ソラネ', 'その手の紋章…。\n言い伝えの「紋章の子」が、本当に来てくださるなんて…。'),
    ...S('長ソラネ', '聞いてください。\nこのクモイ地方の島々は、大地の守り星の力で、雲の上にうかんでいました。'),
    ...S('長ソラネ', 'ですが、ひと月ほど前…\n島々のまん中の神殿から、大地の守り星がうばわれてしまったのです。'),
    ['sfx', 'rumble'], ['shake'],
    ...N('ゴゴゴ…と、足もとが小さくゆれた…。'),
    ...S('長ソラネ', '…このとおりです。\nあの日から、島々は少しずつ、雲の海へしずみ始めました。', 'わたしたちハネビトの羽も、日に日に弱っています。\nもう、遠くの島までは、飛んでいけません…。'),
    ...S('長ソラネ', '守り星をうばったのは…\nフードを深くかぶった、子どもでした。'),
    ...N('（フードの子…！\n星祭りの夜に見た、あの子だろうか…）'),
    ...S('長ソラネ', '西の「しずみゆく島」の古い神殿には、昔、大地の守り星のかけらが、おさめられたと伝わっています。'),
    ...S('長ソラネ', 'かけらの光があれば、島のしずみを、少しは止められるかもしれません。\nですが、あの島は、いちばん先にしずみ始めた島…。'),
    ...S('長ソラネ', '神殿へ行くには、風の道を使うしかありません。\n風の道のことなら、ピピがくわしいはずです。'),
    ...S('長ソラネ', '町の北東の見晴らし台に、ピピという子がいます。\n…あの子は今、少し、さびしがっているかもしれませんが。'),
