function sorane(x) {
  if (x.flag('c5_nocto')) return soraneEarth(x);
  if (!x.flag(K5.hanono)) return soraneScene();
  if (!x.flag(K5.pipi)) return S('長ソラネ', 'ピピは、町の北東の見晴らし台にいます。\n風の道のことを、聞いてみてください。');
  if (!x.flag(K5.ruin)) return S('長ソラネ', '風の道ののりばは、ハネノの島の西の船着き場です。', 'ノクト…。あのフードの子の名前ですね。\n…ピピは、あの子のことが、大好きでしたから。');
  if (!x.flag(K5.shard)) return S('長ソラネ', '古い神殿の4階には、昔のハネビトの休み所があったと聞きます。\nどうか、むりはなさらないで。');
  return S('長ソラネ', '島のゆれが、おさまりました…！\n本当に、ありがとうございます。',
    '守り星のかけらに、泣いている子の思い出が…？', '…西の雲の向こうの小島に、星を読む人々の「星読みの里」があります。\n里の星読みのじいさまカナタなら、何か分かるかもしれません。',
    'しずみゆく島の北西の風見の石を回せば、里へ風の道が開くはずです。');
}

