const ROLL = {
  f2: (east) => (east
    ? N('ゴロゴロゴロ…！', '岩が東へころがって、西の通路が開いた！\n（そのかわり、東の小べやの入口が、岩でふさがれた）')
    : N('ゴロゴロゴロ…！', '岩が西へころがって、西の通路をふさいだ…。\n（東の小べやの入口は、開いた）')),
  f3: (east) => (east
