    : N('ゴロゴロ…。', '岩が、てんびんの左の皿から、西へころがり落ちた…。')),
  f5: (east) => (east
    ? N('ザザザザ…！', '水が東の水路へ流れて、西の水路の水が引いた！\n（そのかわり、東の水路は水でいっぱいになった）')
    : N('ザザザザ…！', '水が西の水路へもどってきた…。\n（東の水路の水は、引いた）')),
};
function tiltSteps(x, key) {
  const K = TILTS[key];
  const east = x.flag(K.flag);
  const after = key === 'f3' ? [['call', (run) => scaleCheck(run, 'f3', 'lever')]] : [];
  return [
