// 第4章クリアの あとの より道「砂の古代都市」と「古代の大迷宮」の だいほん（story.js で まぜる）
// 入口: 砂の海の 東の はしの 小島（第4章クリアで 門が 砂から 出てくる）→ 砂の古代都市（休み所・転送の門・学者の弟子ユスフ）
// → 地下1〜9階（1階に 1つの 見どころ。3・6・9階は 休み所と 転送の門）→ 地下10階「古竜のねどこ」（ねむれる古竜オルドラ）
// マップは maps/labyrinth.js、ボスは data/monsters-lab.js
import {
  LAB_FLAGS, WARP_FLAGS, REST_FLOORS, LAB_NAMES, FLOOR_POS, CITY_POS, ringPos, labMapId, LAB_FLOORS,
} from '../maps/labyrinth.js';

const S = (who, ...lines) => lines.map((l) => ['say', who, l]);
const N = (...lines) => lines.map((l) => ['say', null, l]);
const F = LAB_FLAGS;

// パーティー全員で 見る イベント（リーダーの 世界で すすむ）
export const LAB_STORY_SCRIPTS = ['lab_guards', 'lab_dragon'];

// 小さなメダルを もらう（たのまれごとの ごほうび）。メダルは 見つけた 場所の id で 数える（c.medalSpots。world/casino.js）ので、
// ごほうびごとに きまった id（lab_<key>_1〜n）。話しかけた 人が もらう。2回 もらっても 数は ふえない
export function grantMedals(c, key, n, now = Date.now()) {
  c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
  for (let i = 1; i <= n; i++) if (!c.medalSpots[`lab_${key}_${i}`]) c.medalSpots[`lab_${key}_${i}`] = now;
}
export function medalSteps(key, n) {
  return [
    ['call', (run) => { grantMedals(run.init.char, key, n, run.world.now()); run.world.markDirty(); }],
    ['sfx', 'key'], ['say', null, `{name}は小さなメダルを${n}枚手に入れた！`],
  ];
}

// ───── 休み所の 聖なる 火（回復と 記録。何度でも）─────
function restFire() {
  return [
    ...N('古代の休み所だ。', '石の台の上で、聖なる火が、やさしくゆれている…。'),
    ['choice', '聖なる火で休む？', ['休む', 'やめる'], [
      [['fade', 'out'], ['sfx', 'heal'], ['heal'], ['wait', 700], ['fade', 'in'],
        ...N('聖なる火が、ふわりと大きくなった…。\nみんなのHPとMPが、すっかり回復した！'), ['church']],
      [],
    ]],
  ];
}

// ───── 転送の門（近道）─────
// n … いま いる 階（0 は 古代都市）。地下3・6・9階の 門は、はじめて ふむと 光って、古代都市の 門と つながる
const floorLabel = (k) => (k === 0 ? '砂の古代都市' : `地下${k}階`);
function ringDest(k) {
  const r = ringPos(k);
  return ['teleport', labMapId(k), r.x + 0.5, r.y + 1.6, 'down'];
}
export function ringSteps(x, n) {
  const out = [];
  const lit = n === 0 || x.flag(WARP_FLAGS[n]);
  if (!lit) {
    out.push(['sfx', 'sparkle'], ['flag', WARP_FLAGS[n]], ['sync'], ['flash'],
      ...N('足もとの、古い転送の門に、光がともった！', '（砂の古代都市の転送の門から、この階へ一気に来られるようになった！）'));
  }
  const dests = [0, ...REST_FLOORS].filter((k) => k !== n && (k === 0 || x.flag(WARP_FLAGS[k])));
  if (!dests.length) {
    out.push(...N('古い転送の門だ。', 'まだ、どこにもつながっていない…。\n（大迷宮の地下3階・6階・9階にも、同じ門があるらしい）'));
    return out;
  }
  out.push(...N('古い転送の門が、青白く光っている…。'));
  out.push(['choice', 'どこへ行く？', [...dests.map(floorLabel), 'やめる'], [
    ...dests.map((k) => [['sfx', 'spell'], ['fade', 'out'], ringDest(k), ['fade', 'in'], ...N(`${floorLabel(k)}の転送の門に着いた。`)]),
    [],
  ]]);
  return out;
}

