export const THEME_KEYS = Object.keys(TM_THEMES);

// ほる 場所の ある マップ（ID の 1文字）
export const SPOT_MAPS = { o: 'overworld', s: 'sea' };
const SPOT_CODE = { overworld: 'o', sea: 's' };

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const seed36 = (seed) => (seed >>> 0).toString(36);

// ───────────── ID ─────────────
export function caveKey(tm) {
  return `tm_${seed36(tm.seed)}_${tm.lv}_${SPOT_CODE[tm.map] || 'o'}${tm.x}x${tm.y}`;
}
export function floorMapId(tm, floor) {
  return `${caveKey(tm)}_${floor}`;
}
const FLOOR_ID = /^tm_([0-9a-z]{1,7})_(\d{1,2})_([os])(\d{1,3})x(\d{1,3})_(\d{1,2})$/;
export function isTreasureMapId(id) {
  return typeof id === 'string' && id.startsWith('tm_');
}
// 'tm_…' → { seed, lv, spot: { map, x, y }, floor }（形が ちがえば null）
export function parseFloorId(id) {
  const m = typeof id === 'string' ? FLOOR_ID.exec(id) : null;
  if (!m) return null;
  const seed = parseInt(m[1], 36);
  const lv = Number(m[2]);
  const floor = Number(m[6]);
  if (!Number.isFinite(seed) || seed < 0 || seed > 0x7fffffff || lv < 1 || lv > TM_LV_MAX || floor < 1) return null;
  return { seed, lv, spot: { map: SPOT_MAPS[m[3]], x: Number(m[4]), y: Number(m[5]) }, floor };
}
// フラグ・宝箱の なまえ（地図を 捨てた ときに まとめて 消せる ように seed を 入れる）
export const clearedFlag = (seed) => `tmc_${seed36(seed)}`;
export const foundFlag = (seed) => `tmf_${seed36(seed)}`;
export const chestPrefix = (seed) => `tm_${seed36(seed)}_`;

// ───────────── 洞窟の なかみ（seed と レベルで きまる）─────────────
export function caveInfo(seed, lv) {
  const r = makeRng((seed ^ 0x5bd1e995) >>> 0);
  const theme = r.weighted([{ k: 'earth', w: 4 }, { k: 'ice', w: 3 }, { k: 'lava', w: 3 }]).k;
  const th = TM_THEMES[theme];
  const word = r.pick(th.words);
  const floors = clamp(2 + Math.floor((lv - 1) / 2) + (r.chance(0.35) ? 1 : 0), 2, 6);
  const boss = r.pick(th.bosses);
  return { seed, lv, theme, word, floors, boss, caveName: `${word}の洞窟`, mapName: `${word}の宝の地図` };
}

// 地図の なまえ（「大地の宝の地図 Lv3」）
export function tmTitle(tm) {
  return `${caveInfo(tm.seed, tm.lv).mapName} Lv${tm.lv}`;
}

// 第40回: 洞窟の ふつうの 魔物は、その レベルの ふつうの 魔物より 少し 手ごわく（もとの 魔物は 技が 少ないので。HP・攻撃・魔力に かける）
export const TM_CAVE_POW = 1.15;
// 第65回 C: 地図 Lv26 からの 魔物（deep）は もとから 技が 多いので、少しだけ ひかえめ（0.95。ほうしゅうは へらさない）
//   第68回 C: Lv36 からの 第7章の 魔物（c7）も おなじ 0.95（node tools/sim-tm.mjs 60 36,38,40 で 9わり 以上・HP残 7わり）
//   めやす（tools/sim-tm.mjs）: 魔物の レベル＋3 の 4人（店の 装備）で 勝率 9わり 以上・HP残 7わり くらい（Lv26 95%・30 94%・35 94%）
export const TM_DEEP_POW = 0.95;
export const tmCavePow = (lv) => (lv >= TM_DEEP_FROM ? TM_DEEP_POW : TM_CAVE_POW);
// 魔物の 強さ（レベル）。深い 階ほど すこし 強い
export function enemyLvOf(lv, floor = 1) {
  return 9 + lv * 2 + (floor - 1) * 0.6;
}
// 主の 強さ（いちばん 下の 階の 魔物より すこし 上）
export function bossLvOf(seed, lv) {
  return enemyLvOf(lv, caveInfo(seed, lv).floors) + 1.5;
}
// 主の 強さの 倍率（scaleEnemy の pow。HP・攻撃・魔力に かけ、守りは その 平方根）
// 第40回: 主も その レベルの 魔物の めやす（data/tm-curve.js）で 強くする ように した ので、倍率を 合わせ直した。
//   めやす（tools/sim-boss.mjs の tm）: 主の レベル＋3 の 主人公（その ころの 店の 装備・職業Lv10・完全オート）で 勝率 7〜9わり（地図Lv4 88%・8 81%・12 85%・16 72%・20 86%・25 86%。12回ずつ）。
//   地図 Lv の 間は まっすぐ つなぐ。TM_BOSS_ADJ … 主ごとの ちがいを ならす（ゴーレムは 手下を よぶので ひかえめ・へびと パンサーは 軽いので 多め）
//   （第32回の 「地図 Lv8 から +30〜105%」 と tmPow は、前の 強くしかた〈(L+6)/(L0+6)〉の ための もの。もう 使わない）
//   第65回 C: 地図 Lv26〜35（主は Lv65〜84）を 足した。おなじ めやすで 30回ずつ（node tools/sim-boss.mjs 30 tm 26,28,30,32,35）:
//     地図Lv26 88%・28 86%・30 87%・32 84%・35 82%（第65回の 今の しくみでは Lv25 の 0.66 は 97%。Lv25 までは かえない）。
//     倍率の 0.03 の ちがいで 勝率が 1わり 以上 かわる（0.70 で 9わり半・0.76 で 5〜7わり）ので、Lv26 から 少し 上げて 0.74（Lv35 は 0.73）に
//   第68回 C: 地図 Lv36〜40（主は Lv85.5〜93.5）を 足した。0.73 の ままだと Lv40 が 74%（竜ガルドラ 55%）なので Lv40 を 0.71 に
//     （node tools/sim-boss.mjs 30 tm 35,36,37,38,39,40。0.70 で 91%・0.71 で 85%）
//   第74回 C: 地図 Lv41〜45（主は Lv95.5〜103.5）を 足した。あわせて Lv33〜40 も 合わせ直した
//     （第7章 第3幕・第8章 第1幕の 強い 魔物が ふえて めやす〈tm-curve.js〉が 上がり、0.73・0.71 の ままでは Lv33 43%・Lv38 63%・Lv40 44% に なっていた。
//      これからは めやすを Lv83 まで〈CURVE_LV_MAX〉で 止めたので、新しい 幕の 魔物で ずれない）。
//     node tools/sim-boss.mjs 30 tm 33,35,38,40,42,45: 倍率 0.65 で 87〜98%・0.68 で 39〜98%・0.70 で 16〜92%（高い レベルほど きびしく かわる）→ 下の 数
export const TM_BOSS_POW = [[1, 1.35], [4, 1.35], [8, 1.19], [12, 0.97], [16, 0.86], [20, 0.77], [25, 0.66], [26, 0.74], [30, 0.74], [33, 0.70], [35, 0.70], [38, 0.70], [40, 0.68], [42, 0.67], [45, 0.65]];
export const TM_BOSS_ADJ = { tm_golem: 0.85, tm_dragon: 0.9, tm_king: 0.97, tm_knight: 0.97, tm_serpent: 1.06, tm_panther: 1.06 };
export const TM_POW_FROM = 8;
export function tmBossPow(lv, species) {
  const t = TM_BOSS_POW;
  const L = clamp(lv, t[0][0], t[t.length - 1][0]);
  let base = t[t.length - 1][1];
  for (let i = 0; i + 1 < t.length; i++) {
    const [a, pa] = t[i], [b, pb] = t[i + 1];
    if (L >= a && L <= b) { base = pa + (pb - pa) * ((L - a) / (b - a)); break; }
  }
  return Math.round(base * (TM_BOSS_ADJ[species] ?? 1) * 100) / 100;
}

// ───────────── 出てくる 魔物 ─────────────
export function encounterZone(lv, theme) {
  return `tm${lv}${theme[0]}`;
}

// 出てくる かもしれない 魔物（地図 Lv26 からは deep も・第68回: Lv36 からは c7 だけ・第74回: Lv41 からは c8 だけ）
export function tmPoolOf(lv, theme) {
  const th = TM_THEMES[theme];
  if (lv >= TM_C8_FROM && th.c8?.length) return th.c8.slice();
  if (lv >= TM_C7_FROM && th.c7?.length) return th.c7.slice();
  return lv >= TM_DEEP_FROM ? [...th.pool, ...(th.deep || [])] : th.pool.slice();
}

// 地図の レベルと 洞窟の しゅるいで きまる 魔物の くみあわせ（ENCOUNTER_TABLES に 入れる）
export function ensureEncounterTable(lv, theme) {
  const zone = encounterZone(lv, theme);
  if (ENCOUNTER_TABLES[zone]) return zone;
  const L = enemyLvOf(lv, 1);
  const pool = tmPoolOf(lv, theme).filter((sp) => MONSTERS[sp]).sort((a, b) => MONSTERS[a].lv - MONSTERS[b].lv);
  // 第68回 C: 地図 Lv36 からは 第7章の 魔物 ぜんぶ（もとの レベルは Lv68〜76。洞窟の レベルまで curve で 強くする）
  //   第74回 C: Lv41 からの c8 も おなじ（もとの レベルは Lv70〜83。6しゅより 多い ときは もとの レベルの 高い 6しゅ）
  let pick = lv >= TM_C7_FROM && pool.length >= 4 ? pool.slice() : pool.filter((sp) => MONSTERS[sp].lv <= L + 1 && MONSTERS[sp].lv >= L - 9);
  if (pick.length < 4) pick = pool.slice().sort((a, b) => Math.abs(MONSTERS[a].lv - L) - Math.abs(MONSTERS[b].lv - L)).slice(0, 4).sort((a, b) => MONSTERS[a].lv - MONSTERS[b].lv);
  pick = pick.slice(-6);
  const max = (sp) => (MONSTERS[sp].size === 'l' ? 2 : 3);
  const table = pick.map((sp) => ({ w: 3, group: [[sp, 1, max(sp)]] }));
  for (let i = 0; i + 1 < pick.length; i += 2) table.push({ w: 2, group: [[pick[i + 1], 1, 2], [pick[i], 1, 1]] });
  ENCOUNTER_TABLES[zone] = table;
  ZONE_BG[zone] = TM_THEMES[theme].bg;
  return zone;
}

// 魔物を 地図の レベルに あわせて 強くする（たたかいの はじめに 1体ずつ）
// pow … さらに かける 倍率（ひみつのダンジョンの 深い 階。data/secret.js の sdPower）。HP・攻撃・守り・魔力に かける
//   1より 小さい 時は 弱く する（ひみつのダンジョンの 番人の 一部。data/secret-guard.js）。ほうしゅうは へらさない
// curve … 第40回: 宝の洞窟。その レベルの ふつうの 魔物と おなじ くらいの 強さに する（data/tm-curve.js）。
//   HP・攻撃・守り・魔力・素早さを、それぞれ めやすの わりあいで 上げる（もとの 魔物の 得意・苦手は のこる）。
//   ほうしゅうも その レベルの ふつうの 魔物と おなじ くらい（rewardExpK・rewardGoldK）
export function scaleEnemy(m, L, pow = 1, { curve = false } = {}) {
  const L0 = m.lv || 1;
  if (Number.isFinite(pow) && pow > 0 && pow !== 1) powerUp(m, pow);
  if (!Number.isFinite(L) || Math.abs(L - L0) < 0.01) {
    if (m.powK) m.rewardK = m.powK;
    return m;
  }
  if (curve) return curveScale(m, L0, L);
  const k = (L + 6) / (L0 + 6);
  const hk = Math.pow(k, m.boss ? 1.3 : 1.15);
  m.maxHp = m.hp = Math.max(1, Math.round(m.maxHp * hk));
  m.maxMp = m.mp = Math.round(m.maxMp * k);
  m.atk = Math.round(m.atk * k);
  m.dfn = Math.round(m.dfn * k);
  m.mag = Math.round(m.mag * k);
  m.healPow = Math.round(m.healPow * k);
  m.agi = Math.round(m.agi * Math.sqrt(k));
  m.lv = Math.round(L);
  m.rewardK = k * (m.powK || 1);
  return m;
}

function curveScale(m, L0, L) {
  const K = (key) => curveK(key, L0, L);
  const kHp = K('hp'), kStr = K('str'), kMag = K('mag');
  m.maxHp = m.hp = Math.max(1, Math.round(m.maxHp * kHp));
  m.maxMp = m.mp = Math.round(m.maxMp * Math.max(kStr, kMag));
  m.atk = Math.round(m.atk * kStr);
  m.dfn = Math.round(m.dfn * K('def'));
  m.mag = Math.round(m.mag * kMag);
  m.healPow = Math.round(m.healPow * kMag);
  m.agi = Math.round(m.agi * K('agi'));
  m.lv = Math.round(L);
  const pk = m.powK || 1;
  m.rewardK = kStr * pk;
  m.rewardExpK = K('exp') * pk;
  m.rewardGoldK = K('gold') * pk;
  return m;
}

function powerUp(m, pow) {
  const up = (v) => Math.round((v || 0) * pow);
  m.maxHp = m.hp = Math.max(1, up(m.maxHp));
  m.atk = up(m.atk);
  m.dfn = Math.round((m.dfn || 0) * Math.sqrt(pow));
  m.mag = up(m.mag);
  m.healPow = up(m.healPow);
  m.powK = Math.sqrt(Math.max(1, pow));
}

// 強くした 魔物の ぶん ふえる 経験値・ゴールド
export function scaledRewardBonus(battle) {
  let exp = 0, gold = 0;
  for (const c of battle.combatants) {
    if (c.side !== 'enemy' || c.alive || c.fled || !(c.rewardK || c.rewardExpK)) continue;
    const m = MONSTERS[c.species];
    if (!m) continue;
    exp += Math.round((m.exp || 0) * ((c.rewardExpK ?? Math.pow(c.rewardK, 1.2)) - 1));
    gold += Math.round((m.gold || 0) * ((c.rewardGoldK ?? c.rewardK) - 1));
  }
  return { exp, gold };
}

// ───────────── 宝箱の なかみ ─────────────
// 第31回: 地図の 名前（大地・氷・炎 …）に ちなんだ レア装備（data/rare-loot.js）。地図の レベルが 高いほど ランクと レア度が 上がる
//   ふつうの 宝箱 … レア装備 6〜13%（★2〜★4）・店の 装備 15% ほか / 主の 宝箱（bossA）… 75% レア装備（★3・★4 が 出やすい）、こうふくの靴が まれに
// 店の 装備の ランク（地図 Lv1〜3 は 3・Lv12〜25 で 7・第65回: Lv26 から 9）
export function equipRankOf(lv) {
  return clamp(tmGearRank(lv) - 1, 3, 9);
}
let equipCache = null;
function equipPools() {
  if (equipCache) return equipCache;
  const all = Object.entries(ITEMS).filter(([, it]) => SLOTS.includes(it.type) && !it.unique && it.rank && !it.base);
  equipCache = {
    shop: (rank) => all.filter(([, it]) => !it.star && !it.rarity && it.price > 0 && it.rank >= rank - 1 && it.rank <= rank).map(([id]) => id),
  };
  return equipCache;
}

const CONSUMABLES = [
  ['herb', 4, 1, 3], ['moonherb', 3, 1, 99], ['antidote', 1, 1, 2], ['magic_water', 3, 1, 99], ['holy_water', 1, 1, 99],
  ['return_wing', 2, 1, 99], ['revive_flower', 1, 1, 99], ['smoke_ball', 1, 1, 99],
];
// 第50回: 種（強さを 上げる 道具）は 宝の洞窟から 出ない。かわりに めずらしい 回復の 道具（店に ない）
const TM_GOODIES = ['elf_drink', 'revive_flower'];
// （かわらずのいしは 装備なので 宝箱には 入れない。カジノ・メダル王）
// 第53回 D: 色の石（配合で 色ちがいの 子）も まれに
const TM_STONES = ['fire_stone', 'water_stone', 'thunder_stone', 'moon_stone', 'color_stone'];

// rng … 宝箱ごとに きまった 乱数（洞窟の seed から）/ kind: 'normal' | 'bossA' | 'bossB'
// cave … { theme, word }（caveInfo。宝箱の レア装備を 地図の 名前に ちなませる）
// 第65回: 主の 宝箱に 限界の石が 入る 地図の レベル
export const TM_LIMIT_LV = 30;
export function chestLoot(rng, lv, kind = 'normal', cave = null) {
  const pools = equipPools();
  const rank = equipRankOf(lv);
  const rare = () => {
    const shoes = luckyShoesRate(lv, kind);
    if (shoes > 0 && rng.chance(shoes)) return { item: LUCKY_SHOES };
    const id = pickTmGear(rng, lv, cave, kind);
    return id ? { item: id } : { item: 'revive_flower' };
  };
  const equip = () => {
    const list = pools.shop(rank);
    return list.length ? { item: rng.pick(list) } : { gold: 100 };
  };
  // 第64回 ⑥d: 装備が 手に入りすぎるので へらして、そのぶん きたえる 素材（data/forge.js・data/salvage.js で 使う）
  const mat = () => {
    const pool = lv >= 5 ? [['star_shard', 1], ['silver_shard', 2]] : lv >= 3 ? [['silver_shard', 1], ['star_shard', 1], ['iron_shard', 3]] : [['iron_shard', 2], ['beast_fang', 2], ['magic_powder', 2]];
    const [item, n] = rng.pick(pool);
    return { item, n };
  };
  // 第65回: 地図 Lv30 から、主の 宝箱の 素材の かわりに 限界の石が 出る ことが ある（data/forge.js の 限界とっぱ）
  const stone = () => (lv >= TM_LIMIT_LV && rng.chance(0.6) ? { item: 'limit_stone', n: 1 } : mat());
  if (kind === 'bossA') return rng.chance(0.5) ? rare() : stone();
  if (kind === 'bossB') {
    const r = rng.next();
    if (r < 0.45) return { gold: Math.round((400 + lv * 220) * rng.float(0.9, 1.2) * REWARD_GOLD_RATE / 10) * 10 };
    if (r < 0.75) return lv >= 3 && rng.chance(0.5) ? { item: rng.pick(TM_STONES) } : { item: rng.pick(TM_GOODIES), n: 2 };
    return { item: rng.pick(['revive_flower', 'magic_water']), n: 2 };
  }
  const r = rng.next();
  // 第64回 ⑥d: レア装備 0.06+0.006×Lv → 0.04+0.004×Lv・店の 装備 15% → 5%（のこりの 10% は 素材）
  // 第65回 C: Lv25 より 上は Lv25 の 14% の まま（TM_RARE_LV_CAP）
  const rareP = 0.04 + Math.min(lv, TM_RARE_LV_CAP) * 0.004;
  if (r < rareP) return rare();
  if (r < rareP + 0.05) return equip();
  if (r < rareP + 0.15) return mat();
  // 第44回（ポケモン P1）: ときどき 進化の 石（地図 Lv3 から。data/items-pokemon.js）/ 第50回: 種の かわりに めずらしい 回復の 道具
  if (r < rareP + 0.28) return lv >= 3 && rng.chance(0.15) ? { item: rng.pick(TM_STONES) } : { item: rng.pick(TM_GOODIES) };
  if (r < rareP + 0.57) return { gold: Math.round((50 + lv * 40) * rng.float(0.7, 1.4) * REWARD_GOLD_RATE / 10) * 10 };
  const list = CONSUMABLES.filter(([, , a, b]) => lv >= a && lv <= b).map(([id, w]) => ({ id, w }));
  const id = rng.weighted(list).id;
  return { item: id, n: id === 'herb' ? 3 : 1 };
}

// ───────────── 地図が 手に入る ─────────────
// 戦いの あとで 宝の地図を 拾う 確率（第1章を クリアした あとだけ。world/treasure.js）
export function mapDropRate({ inCave = false, boss = false, fixed = false, maxEnemyLv = 1, playerLv = 1 } = {}) {
  if (fixed) return boss ? 0.5 : 0;
  if (inCave) return 1 / 60;
  if (maxEnemyLv >= 12 || maxEnemyLv >= playerLv - 2) return 1 / 100;
  return 1 / 180;
}
// 拾った 地図の レベル（戦った 魔物の 強さから）
export function dropMapLevel(rng, enemyLv) {
  const base = Math.round((enemyLv - 8) / 2);
  return clamp(base + (rng.chance(0.3) ? 1 : 0) - (rng.chance(0.2) ? 1 : 0), 1, TM_LV_MAX);
}
// 主を たおした ときに もらえる 地図の レベル（おなじ か 上）
export function nextMapLevel(rng, lv) {
  const r = rng.next();
  return clamp(lv + (r < 0.45 ? 0 : r < 0.9 ? 1 : 2), 1, TM_LV_MAX);
}

// ───────────── セーブ ─────────────
// こわれた・知らない 形の 地図は すてる（何回 よんでも おなじ けっか）
export function repairTreasureMaps(c) {
  if (!c || (c.treasureMaps === undefined && c.tmPending === undefined)) return;
  const seen = new Set();
  const fix = (list) => {
    const out = [];
    for (const tm of Array.isArray(list) ? list : []) {
      if (!tm || typeof tm !== 'object') continue;
      const seed = Number(tm.seed);
      if (!Number.isInteger(seed) || seed < 0 || seed > 0x7fffffff || seen.has(seed)) continue;
      if (!SPOT_CODE[tm.map] || !Number.isInteger(tm.x) || !Number.isInteger(tm.y) || tm.x < 0 || tm.y < 0 || tm.x > 999 || tm.y > 999) continue;
      seen.add(seed);
      const rec = { id: seed36(seed), seed, lv: clamp(Math.floor(Number(tm.lv) || 1), 1, TM_LV_MAX), map: tm.map, x: tm.x, y: tm.y, found: !!tm.found, cleared: !!tm.cleared };
      if (Number.isFinite(tm.at)) rec.at = tm.at;
      out.push(rec);
    }
    return out;
  };
  if (c.treasureMaps !== undefined && !Array.isArray(c.treasureMaps)) delete c.treasureMaps;
  const held = c.treasureMaps === undefined ? undefined : fix(c.treasureMaps);
  // 第75回: あずかりの 地図（持っている 地図と おなじ 地図は のぞく）。持ちきれない 地図も あずかりへ（なくさない）
  //   （あずかりの 地図は まだ ほっていない 新しい 地図として あつかう）
  const pend = [...(held || []).slice(TM_MAX), ...fix(c.tmPending)].slice(0, TM_PEND_MAX).map((t) => ({ ...t, found: false, cleared: false }));
  if (held) c.treasureMaps = held.slice(0, TM_MAX);
  if (pend.length) c.tmPending = pend;
  else delete c.tmPending;
}

// 家族サーバーと スマホで 地図を 合わせる（merge.js）。両方で ふえた 地図は 両方、どちらかで 捨てた 地図は 捨てる
export function mergeTreasureMaps(b, a, t) {
  const list = (x) => (Array.isArray(x) ? x.filter((e) => e && e.id) : []);
  const B = new Map(list(b).map((e) => [e.id, e]));
  const A = new Map(list(a).map((e) => [e.id, e]));
  const T = new Map(list(t).map((e) => [e.id, e]));
  if (!A.size && !T.size && !B.size) return undefined;
  const out = [];
  for (const [id, e] of [...A, ...T]) {
    if (out.some((x) => x.id === id)) continue;
    if (B.has(id) && (!A.has(id) || !T.has(id))) continue;
    const ea = A.get(id), et = T.get(id);
    const m = { ...(ea || et) };
    m.found = !!(ea?.found || et?.found);
    m.cleared = !!(ea?.cleared || et?.cleared);
    out.push(JSON.parse(JSON.stringify(m)));
  }
  return out.slice(0, TM_MAX);
}

