    k: { hp: 1.5, str: 1.1, def: 1.3, agi: 1, mag: 1 }, exp: 2.5, gold: 6,
    resist: {}, desc: '金色にかがやく、めずらしい色ちがい。たおすとお金をたくさん落とす。',
  },
  // 第2部 第6章 Step 5: 止まった時計塔の ぜんまいじかけ（真ちゅう色。時のいせきの からくりの 魔物を 使い回す。encounters-tokei.js）
  clock: {
    prefix: 'ぜんまい', tint: { hueTo: 38, sat: 0.85, light: 0.95 },
    k: { hp: 1.25, str: 1.2, def: 1.25, agi: 1.05, mag: 1.15 }, exp: 1.7, gold: 1.6,
    resist: { bolt: 1.2, poison: 0.5 }, desc: '時計塔のぜんまいで動く、真ちゅう色の色ちがい。体がかたく、雷に少し弱い。',
  },
};
export const VARIANT_PREFIX = 'v_';
export const variantId = (baseId, kind) => `${VARIANT_PREFIX}${kind}_${baseId}`;

const r = (v, k) => Math.max(0, Math.round((Number(v) || 0) * k));
// 色の かえかたを かさねる（もとの 魔物が 色がえの 絵〈宝の洞窟の 主 など〉なら その 上に）
function mixTint(a, b) {
  if (!a) return { ...b };
  const out = { hue: a.hue || 0, sat: (a.sat ?? 1) * (b.sat ?? 1), light: (a.light ?? 1) * (b.light ?? 1) };
  if (b.hueTo !== undefined) out.hueTo = b.hueTo;
  else out.hue += b.hue || 0;
  return out;
}

// 色ちがいの データを 作る（とうろくは しない。もとが なければ null）
export function makeVariant(baseId, kind) {
  const m = MONSTERS[baseId];
  const v = VARIANT_KINDS[kind];
  if (!m || !v || m.variant) return null;
  const resist = colorResist(m.resist, kind);
  return {
    ...m,
    name: `${v.prefix}${m.name}`,
    hp: Math.max(1, r(m.hp, v.k.hp)), mp: r(m.mp, 1),
    str: r(m.str, v.k.str), def: r(m.def, v.k.def), agi: r(m.agi, v.k.agi), mag: r(m.mag, v.k.mag),
    exp: r(m.exp, v.exp), gold: r(m.gold, v.gold),
    resist,
    actions: (m.actions || [{ w: 1, id: 'attack' }]).map((a) => ({ ...a })),
    drops: m.drops ? JSON.parse(JSON.stringify(m.drops)) : undefined,
    art: m.art || baseId,
    tint: mixTint(m.tint, v.tint),
    variant: { base: baseId, kind },
    noBefriend: true,
    desc: v.desc,
  };
}

// MONSTERS に とうろく（何回 よんでも おなじ。ID を かえす。作れなければ null）
export function registerVariant(baseId, kind) {
  const id = variantId(baseId, kind);
  if (Object.prototype.hasOwnProperty.call(MONSTERS, id)) return id;
  const data = makeVariant(baseId, kind);
  if (!data) return null;
  Object.defineProperty(MONSTERS, id, { value: data, enumerable: false, configurable: true, writable: true });
  return id;
}

// その しゅるいが あるか（'__proto__' などは だめ）
export const kindOk = (kind) => typeof kind === 'string' && Object.prototype.hasOwnProperty.call(VARIANT_KINDS, kind);
// 属性の 強さ・弱さに 色ちがいの しゅるいを かさねる（効きにくい ほうは 小さい ほう・弱い ほうは 大きい ほう）
export function colorResist(base, kind) {
  const resist = { ...(base || {}) };
  if (!kindOk(kind)) return resist;
  for (const [el, x] of Object.entries(VARIANT_KINDS[kind].resist || {})) resist[el] = x < 1 ? Math.min(resist[el] ?? 1, x) : Math.max(resist[el] ?? 1, x);
  return resist;
}

// 第53回 D: 色ちがいの 仲間（配合で 色の石を 使う。world/breed.js の char.color。しゅぞくは もとの 魔物の まま）
// その 魔物に とうろく ずみの 色ちがいの しゅるい（敵に 出る 色ちがいが ある 魔物だけ。新しい 色ちがいを 足すと ふえる）
export const colorKinds = (sp) => Object.keys(VARIANT_KINDS).filter((k) => Object.prototype.hasOwnProperty.call(MONSTERS, variantId(sp, k)));
// 色ちがいの 仲間の 絵の ID（顔・ついてくる 絵・戦い。色が ない・作れない ときは もとの ID）
export const colorMon = (sp, kind) => (sp && kindOk(kind) ? registerVariant(sp, kind) || sp : sp || undefined);

// 色ちがいなら { base, kind }（ちがえば null）
export function variantOf(sp) {
  return MONSTERS[sp]?.variant || null;
}
// もとの 魔物の ID（色ちがいで なければ そのまま）
export const baseSpecies = (sp) => variantOf(sp)?.base || sp;
// 名前が もう その ことばで 始まる 魔物（ダークトレント など）には、その しゅるいを 作らない
export const variantFits = (baseId, kind) => !!MONSTERS[baseId] && !!VARIANT_KINDS[kind] && !MONSTERS[baseId].name.startsWith(VARIANT_KINDS[kind].prefix);

// 第67回 B: ID（'v_<しゅるい>_<もとの 魔物>'）から 色ちがいを とうろく（画面が まだ 知らない 色ちがい。
//   モンスター闘技場で 家族の 色ちがいの 仲間が 敵の がわに 出る 時。client/battle.js）。とうろく できた ID か null
export function ensureVariantId(id) {
  if (typeof id !== 'string' || !id.startsWith(VARIANT_PREFIX)) return null;
  if (Object.prototype.hasOwnProperty.call(MONSTERS, id)) return id;
  const rest = id.slice(VARIANT_PREFIX.length);
  const i = rest.indexOf('_');
  if (i <= 0) return null;
  const kind = rest.slice(0, i);
  return kindOk(kind) ? registerVariant(rest.slice(i + 1), kind) : null;
}

