// 第47回: 新しい 属性「水」（water）。魔物の 水の 効きぐあいを、かんたんな きまりで つける（docs/plan-r47-water.md）
//
// ・monsters.js の おわりで applyWater(MONSTERS) を よぶ。数えない 形（色ちがい いがいの かくれた 魔物）も ふくめて
//   MONSTERS[id].resist.water に かずを 書く（ふつうの 魔物も 1 と 書くので、あとから 見て わかる）
// ・色ちがい（variants.js）は もとの 魔物の resist を うつすので、もとの 水を うけつぐ
// ・データに もう resist.water が 書いてある 魔物は、その かずを つかう（きまりより 先）
// ・古い セーブ・水の ない データは、resist.water が なくても `?? 1` で ふつう（1倍）
// ・ここは ほかの データを import しない（monsters.js から 読まれる）

// 水の 効きぐあいの かず
export const WATER_VALUES = { weak: 1.5, weakSoft: 1.25, none: 1, resistSoft: 0.75, resist: 0.5, metal: 0 };

// ボスの 弱点は ここまで（ていねいに 調整した ボスが、水で きゅうに やさしく ならない ように）。
// さらに ボスは、もとからの いちばんの 弱点（炎〜闇の いちばん 大きい かず）を こえない
export const WATER_BOSS_WEAK_MAX = 1.25;

// 1. 1体ずつ きめた もの（ポケモンは タイプの とおり。ボスで きまりと ちがう ものも ここ）
export const WATER_OVERRIDE = {
  // ポケモン（ほのおタイプは 弱い・みず と くさは 強い・ほかは ふつう）
  charmander: 1.5, charmeleon: 1.5, charizard: 1.5, flareon: 1.5,
  squirtle: 0.5, wartortle: 0.5, blastoise: 0.5, vaporeon: 0.5,
  bulbasaur: 0.5, ivysaur: 0.5, venusaur: 0.5,
  pikachu: 1, raichu: 1, eevee: 1, jolteon: 1, umbreon: 1, snorlax: 1, gengar: 1, mew: 1,
  // 第6章の ボスは しかけ（砂・時を おぼえる・かねの 音）で 調整ずみなので ふつう
  sand_clock: 1, geardon: 1, carillon: 1,
  // 水が かれて ひからびた カエル（カエルだが 水の 中に いない）
  dry_frog: 1,
  // 第2部 第8章 第2幕: よみの王ハデロスは 炎の 色で 弱点が かわる しかけ（炎と 氷）で 調整ずみなので ふつう
  c8_hades: 1,
  // 第2部 第8章 第3幕: 初代大魔王クッパードは 橋の オノの しかけで 調整ずみなので ふつう
  c8_bowser: 1,
};

// 2. 水の 魔物（海・川・ぬま・雨・魚・カニ・カメ・くらげ・イカ・水の 竜）→ 0.5
export const WATER_SEA = [
  'marine_slime', 'hedoron', 'frog', 'armor_crab', 'shell_knight', 'sea_serpent', 'coral_golem', 'glow_jelly',
  'tobiuo', 'uzumaki_gai', 'hoseki_game', 'kiba_walrus', 'penguin_knight', 'sand_crab', 'crab_star',
  'water_spirit', 'water_dragon', 'prison_guard', 'water_prison', 'mirror_jelly', 'shade_serpent', 'foam_siren', 'star_jelly',
  'ss_kraken', 'giant_squid', 'tm_king', 'tm_serpent', 'morgana', 'morgana_true', 'phantom_morgana',
  // 第2部 第7章 第1幕（monsters-c7.js）: 神殿の 水の 魔物・ウツボきょうだい・うずの魔女と 声の貝
  'uzu_eel', 'gesso', 'water_youma', 'c7_gate', 'c7_gate_b', 'c7_temple', 'c7_shell',
  // 第2部 第7章 第2幕（monsters-c7s.js）: 海の 魚（プクプク・魚人の海賊）
  'pukupuku', 'fish_pirate',
  // 第74回 C: 闘技場 ランク12（monsters-arena.js）: 深海の 竜・カニ・クラゲ
  'ar_leviathan', 'ar_bubble_crab', 'ar_glow_jelly',
  // 第2部 第8章 第2幕（monsters-c8b.js）: 海の 底の 魔物（ホネギョ・ビリクラゲ・ヒドラン）
  'bone_fish', 'biri_jelly', 'hydran',
];

// 3. 炎の 魔物。きまり: 炎が 0.5いか で 氷が 1.2いじょう（この ゲームの 炎の 魔物は みんな 氷に 弱い）。
//    それに 当てはまらない 炎の 魔物は ここに 書く → 1.5（竜は うろこが かたいので 1.25）
export const WATER_FIRE = ['lantern_ghost', 'ryuou_grandson'];

// 4. 砂・土の 体、砂の 中に すむ（水で くずれる）→ 1.5
export const WATER_SAND = [
  'sand_slime', 'sand_golem', 'sand_sprite', 'sandstorm_spirit', 'sandstone_golem', 'haniwa_soldier',
  'sand_worm', 'sand_shark', 'ar_shark', 'ar_sharkking', 'sand_whale',
];

// 5. 岩・石の 体（かたいので 少しだけ。いちばんの 弱点は 今までの 爆発など）→ 1.25
export const WATER_ROCK = [
  'rockman', 'rock_shard', 'golem', 'goldoon', 'tm_golem', 'ss_goldoon', 'stone_keeper', 'dragon_statue', 'trial_guardian',
  'gargoyle', 'stone_gargoyle', 'ruin_sentinel',
  // 第2部 第8章 第3幕（monsters-c8c.js）: 石の かたまり
  'dosshiin',
];

// 6. からくり・機械・鉄の 体（さびる。いちばんの 弱点は 今までの 雷）→ 1.25
export const WATER_MACHINE = [
  'clockwork_knight', 'buriki', 'clockwork_guard', 'sky_guard', 'gear_beetle', 'chrono_knight', 'cog_roller',
  'killer', 'killer_karakuri', 'castle_armor', 'ss_sky_giant',
  // 第2部 第8章 第3幕（monsters-c8c.js）: ブリキの おもちゃ・大ほうの 黒い たま
  'buriki_koopa', 'dodeka_killer',
];

const ELEMS7 = ['fire', 'ice', 'wind', 'blast', 'bolt', 'light', 'dark'];
const SEA = new Set(WATER_SEA), FIRE = new Set(WATER_FIRE), SAND = new Set(WATER_SAND), ROCK = new Set(WATER_ROCK), MACHINE = new Set(WATER_MACHINE);

// メタル（どの 属性も 0）
export const isMetalResist = (r) => !!r && ELEMS7.every((k) => r[k] === 0);
// 炎の 魔物（きまり）
export const isFireBody = (id, m) => FIRE.has(id) || ((m.resist?.fire ?? 1) <= 0.5 && (m.resist?.ice ?? 1) >= 1.2);

// どの きまりで、いくつに なるか（{ value, rule }）。rule は ドキュメントと テストの ための 名前
export function waterRuleOf(id, m) {
  const r = m?.resist || {};
  if (Object.prototype.hasOwnProperty.call(r, 'water') && !AUTO.has(r)) return { value: r.water, rule: 'data' };
  let out;
  if (Object.prototype.hasOwnProperty.call(WATER_OVERRIDE, id)) out = { value: WATER_OVERRIDE[id], rule: 'override' };
  else if (m.metal || isMetalResist(r)) out = { value: WATER_VALUES.metal, rule: 'metal' };
  else if (SEA.has(id)) out = { value: WATER_VALUES.resist, rule: 'sea' };
  else if (isFireBody(id, m)) out = { value: m.race === 'dragon' ? WATER_VALUES.weakSoft : WATER_VALUES.weak, rule: 'fire' };
  else if (SAND.has(id)) out = { value: WATER_VALUES.weak, rule: 'sand' };
  else if (ROCK.has(id)) out = { value: WATER_VALUES.weakSoft, rule: 'rock' };
  else if (MACHINE.has(id)) out = { value: WATER_VALUES.weakSoft, rule: 'machine' };
  else if ((r.ice ?? 1) <= 0.5) out = { value: WATER_VALUES.resistSoft, rule: 'ice' };
  else if (m.race === 'plant') out = { value: WATER_VALUES.resistSoft, rule: 'plant' };
  else out = { value: WATER_VALUES.none, rule: 'none' };
  // ボスの 弱点は WATER_BOSS_WEAK_MAX まで。そのうえ、もとからの いちばんの 弱点を こえない
  // （ボスの「この 属性が 効く」と いう 作戦が かわらない。1体ずつ きめた ものは そのまま）
  if (m.boss && out.rule !== 'override' && out.value > 1) {
    const cap = Math.min(WATER_BOSS_WEAK_MAX, Math.max(1, ...ELEMS7.map((k) => r[k] ?? 1)));
    if (out.value > cap) out = { value: cap, rule: `${out.rule}+boss` };
  }
  return out;
}

// applyWater が 作った resist（2回目に よんでも「データに 書いてある」と まちがえない ため）
const AUTO = new WeakSet();
// applyWater で きまった きまりの 名前（id → 'sea' など。テストと 図鑑の 見なおし用）
export const WATER_RULE = {};

// 表の すべての 魔物に resist.water を つける（resist は あたらしい オブジェクトに する。
// ROCK_RESIST・METAL_RESIST のような 共有の オブジェクトを かきかえない ため）
export function applyWater(table) {
  for (const id of Object.getOwnPropertyNames(table)) {
    const m = table[id];
    if (!m || typeof m !== 'object') continue;
    const { value, rule } = waterRuleOf(id, m);
    m.resist = { ...(m.resist || {}), water: value };
    AUTO.add(m.resist);
    WATER_RULE[id] = rule;
  }
  return table;
}

js/shared/equip-plan.js:
// さいきょう装備の 見こみ（ドラクエ風。サーバーの 'bestEquip' と メニューの「何が 何に 変わるか」で おなじ 計算を 使う）
// ふくろの 中から、攻撃力（武器）・守備力（よろい・たて・頭）が いちばん 上がる ものを えらぶ。アクセサリーは そのまま
// 呪文が 得意な 職業（魔法使い・僧侶・賢者 など）の 武器は、攻撃魔力・回復魔力も 重く みる（やりより つえ）
import { ITEMS } from './data/items.js';
import { JOBS } from './data/jobs.js';
import { computeStats, canEquipChar, addItem, removeItem } from './stats.js';

export const BEST_SLOTS = ['weapon', 'armor', 'shield', 'head'];

// みんなさいきょう装備で きめる じゅんばん: 戦う 仲間（ならびの じゅん。自分は selfPos の ところ）→ 馬車の 仲間
// （1つしか ない 物は 先の 人が 使う。サーバーの ownTeamChars と メニューの bestTeam で おなじ じゅんに する）
export function bestTeamOrder(self, sups, wagon, selfPos) {
  const pos = Math.max(0, Math.min(sups.length, Number.isInteger(selfPos) ? selfPos : 0));
  return [...sups.slice(0, pos), self, ...sups.slice(pos), ...(wagon || [])];
}

// 武器で 重く みる 強さ。呪文の 職業（攻撃魔力か 回復魔力が 力より はっきり 高い）は 魔力も、それ以外は 攻撃力だけ
export function weaponWeights(ch) {
  const m = !ch?.species && JOBS[ch?.job]?.mods;
  if (!m || Math.max(m.mag, m.heal) < m.str + 0.3) return { atk: 1, mag: 0, heal: 0 };
  const top = Math.max(m.mag, m.heal);
  return { atk: 0.35, mag: m.mag / top, heal: m.heal / top };
}

// その 部位に id を 装備した ときの 強さ（大きいほど 強い。id が null なら 外した とき）。みんなさいきょう装備と 装備を えらぶ まどの「強さ順」で 使う
//   大事な 強さ（武器は 攻撃力〈呪文の 職業は 魔力も〉、よろい・たて・頭は 守備力。アクセサリーは なし）→ 強さの 合計 の じゅんで くらべる
export function gearScore(ch, slot, id, w = weaponWeights(ch)) {
  const st = computeStats({ ...ch, equip: { ...(ch?.equip || {}), [slot]: id } });
  const main = slot === 'weapon' ? st.atk * w.atk + st.mag * w.mag + st.heal * w.heal : slot === 'acc' ? 0 : st.dfn;
  return Math.round(main * 100) * 10000 + st.str + st.def + st.agi + st.mag + st.heal + st.maxHp + st.maxMp;
}

// 1人ぶん: ch の 装備を bag から いれかえる（ch.equip と bag は かえる。変えた 部位を かえす）
function bestFor(ch, bag) {
  const changes = [];
  const w = weaponWeights(ch);
  for (const slot of BEST_SLOTS) {
    const score = (id) => gearScore(ch, slot, id, w);
    const cur = ch.equip?.[slot] || null;
    // ふしぎな 力の ある 装備（しあわせのぼうし など。data/items-r31.js）は 自分で つけた ものなので はずさない
    if (ITEMS[cur]?.perk) continue;
    let best = cur;
    let bestScore = score(cur);
    for (const e of bag.items) {
      if (e.n < 1 || ITEMS[e.id]?.type !== slot || !canEquipChar(ch, e.id)) continue;
      const sc = score(e.id);
      if (sc > bestScore) { best = e.id; bestScore = sc; }
    }
    if (!best || best === cur || !removeItem(bag, best, 1)) continue;
    // はずした 物は ふくろへ（つぎの 人が 使える）
    if (cur) addItem(bag, cur, 1);
    ch.equip[slot] = best;
    changes.push({ slot, from: cur, to: best });
  }
  return changes;
}

// team: [{ key, char }]（ならびの じゅんに きめる）。bag: ふくろ（{ items: [{ id, n }] }）
// どちらも かえない。かえす もの: 変わる 人だけ [{ key, name, changes: [{ slot, from, to }], before, after }]
//   before・after は computeStats の 結果（強さが どう 変わるか 見せる）
export function bestEquipPlan(team, bag) {
  const pool = { items: (bag?.items || []).map((e) => ({ id: e.id, n: e.n })), keyItems: [] };
  const out = [];
  for (const m of team || []) {
    if (!m?.char) continue;
    const ch = { ...m.char, equip: { ...(m.char.equip || {}) } };
    const before = computeStats(ch);
    const changes = bestFor(ch, pool);
    if (changes.length) out.push({ key: m.key, name: ch.name, changes, before, after: computeStats(ch) });
  }
  return out;
}

// ───── 装備を えらぶ まど（メニューの「装備」→ 部位。client/ui/menu.js の pickGear）─────
// ならべかた: got … 入手順（ふくろの じゅん。手に 入れた じゅん）／ power … 強さ順（gearScore の 大きい じゅん）
export const GEAR_SORTS = { got: '入手順', power: '強さ順' };

// ch が その 部位に 装備できる 物（職業の 武器・よろい・たて・かぶとの きまり、魔物の しゅぞくの きまり。stats.js の canEquipChar）だけ。
// bag … ふくろ（{ items: [{ id, n }] }）、others … ほかの 人 [{ key, char }]（その 人が 装備している 物も 入れかえの 候補）
// かえす もの: [{ id, n, from: null（ふくろ）か 仲間の key, score }]。ふくろの じゅん → ほかの 人の じゅん
export function gearChoices(ch, slot, bag, others = []) {
  const w = weaponWeights(ch);
  const out = [];
  const seen = new Set();
  for (const e of bag?.items || []) {
    if (!(e?.n > 0) || ITEMS[e.id]?.type !== slot || seen.has(e.id) || !canEquipChar(ch, e.id)) continue;
    seen.add(e.id);
    out.push({ id: e.id, n: e.n, from: null, score: gearScore(ch, slot, e.id, w) });
  }
  for (const m of others || []) {
    const id = m?.char?.equip?.[slot];
    if (!id || ITEMS[id]?.type !== slot || !canEquipChar(ch, id)) continue;
    out.push({ id, n: 1, from: m.key, score: gearScore(ch, slot, id, w) });
  }
  return out;
}

// 強さ順: ふくろの 物を 強い じゅんに（いちばん 上が みんなさいきょう装備で えらぶ 物）。おなじ 強さなら 入手順。
// ほかの 人が 装備している 物は その あと（その 中も 強い じゅん）。入手順は そのまま
export function sortGearChoices(list, mode) {
  if (mode !== 'power') return list.slice();
  const strong = (a, b) => b.score - a.score;
  return [...list.filter((x) => !x.from).sort(strong), ...list.filter((x) => x.from).sort(strong)];
}

js/shared/favorites.js:
// 第72回: 技の お気に入りの きまり（サーバー〈world/services.js の favorite〉と 画面〈client/ui/menu.js・client/battle.js〉で おなじ）
//   家族の ねがい「覚えた技からお気に入りにしても、お気に入りにならない」:
//   まえは 30こ まで で、いっぱいの ときは だまって 入れなかった（サーバーは「入れた」と 返事を していた）。
//   → 60こ まで に ふやし、いっぱいの ときは 入れられない ことと わけを 出す。
//     もう 覚えていない 技（数に 入るが 画面に 出ない）は、いっぱいの ときに さきに すてる。
import { ABILITIES } from './data/abilities.js';

export const FAV_MAX = 60;

// いっぱいの ときの 知らせ（画面と サーバーで おなじ）
export const FAV_FULL_TEXT = `お気に入りは${FAV_MAX}こまで。「お気に入り」のタブで、使わない技をはずしてから入れよう。`;

// 今の お気に入り（ある 技だけ・かさならない）
export function favClean(cur) {
  const out = [];
  for (const x of Array.isArray(cur) ? cur : []) if (typeof x === 'string' && ABILITIES[x] && !out.includes(x)) out.push(x);
  return out;
}

// これ以上 入れられないか（learned: 覚えている 技の Set。あれば 覚えていない 技は 数えない）
export function favFull(cur, learned = null) {
  const list = favClean(cur);
  return (learned ? list.filter((x) => learned.has(x)) : list).length >= FAV_MAX;
}

// お気に入りを かえる（op: add・remove・up・down）。もどりち: { ok, list, full }
//   ok が false の ときは list は 今の まま（いっぱい・ない 技）
export function favApply(cur, id, op, learned = null) {
  let list = favClean(cur);
  if (typeof id !== 'string' || !ABILITIES[id]) return { ok: false, list };
  const i = list.indexOf(id);
  if (op === 'add') {
    if (i >= 0) return { ok: true, list };
    if (list.length >= FAV_MAX && learned) list = list.filter((x) => learned.has(x));
    if (list.length >= FAV_MAX) return { ok: false, full: true, list: favClean(cur) };
    list.push(id);
  } else if (op === 'remove') {
    if (i >= 0) list.splice(i, 1);
  } else if (op === 'up' || op === 'down') {
    const j = op === 'up' ? i - 1 : i + 1;
    if (i >= 0 && j >= 0 && j < list.length) [list[i], list[j]] = [list[j], list[i]];
  } else return { ok: false, list };
  return { ok: true, list };
}

js/shared/fieldskills.js:
// いま フィールドで つかえる 呪文・技（メニューの 呪文・技の「今使える」タブ）
// サーバーの 'cast'（world/services.js）と おなじ きまりで えらぶ:
//   ・field の ない 技（戦いだけの 技）は 出さない
//   ・掛け合わせ技を 今の 職業で 使えない とき・ぶきが 合わない ときは 出さない
//   ・ルーラは 洞窟や 塔の 中では 出さない（天井に 頭を ぶつける だけ）。リレミトは フィールドでは 出さない
//   ・MPが 足りない 技・唱える 人が 死んでいる ときは 出すが えらべない（why: 'mp' / 'dead'）
//   ・呪文が ふうじられた 場所（noSpells。王家のピラミッド 2階）では 呪文を 出すが えらべない（why: 'seal'）
import { ABILITIES } from './data/abilities.js';
import { ITEMS } from './data/items.js';
import { learnedAbilities, mpCost, comboAllowed, weaponOk } from './stats.js';
import { spellSealed } from './battle.js';
import { effectTab } from './skill-tabs.js';
import { sortByStdPower } from './skill-sort.js';

// mapKind: 今いる マップの しゅるい（'field' なら そと）
// へんじ: [{ id, cost, ok, why }]（覚えた じゅん）
export function fieldUsableAbilities(char, { mapKind = 'field', noSpells = false } = {}) {
  if (!char) return [];
  const weaponCat = ITEMS[char.equip?.weapon]?.cat || 'none';
  const out = [];
  for (const id of learnedAbilities(char)) {
    const a = ABILITIES[id];
    if (!a || !a.field) continue;
    if (a.kind === 'combo' && !comboAllowed(char, id)) continue;
    if (!weaponOk(a, weaponCat)) continue;
    if (a.effect?.type === 'warp' && mapKind !== 'field') continue;
    if (a.effect?.type === 'exit' && mapKind === 'field') continue; // リレミトは 洞窟や 塔の 中だけ（abilities-field27.js）
    const cost = mpCost(char, id);
    const why = (char.hp ?? 1) <= 0 ? 'dead' : noSpells && spellSealed(a) ? 'seal' : (char.mp || 0) < cost ? 'mp' : '';
    out.push({ id, cost, ok: !why, why });
  }
  return out;
}

// 第69回: メニューの「回復」「回復以外」の タブ（家族の ことば「使える技は、回復。回復以外で分けて。使用頻度が多いのは、回復と、ルーラ、リレミト」）
//   list: fieldUsableAbilities の へんじ。heal: 回復・生き返る・どくけし など（戦いの タブの「回復」と おなじ きまり。skill-tabs.js の effectTab）
//   どちらも 弱い じゅん（shared/skill-sort.js）。回復以外は ルーラ・リレミトが いちばん 上
export const FIELD_TOP = ['warp', 'exit'];
export function splitFieldAbilities(list) {
  const byId = new Map((list || []).map((x) => [x.id, x]));
  const ids = sortByStdPower([...byId.keys()]);
  const heal = ids.filter((id) => effectTab(ABILITIES[id]) === 'heal');
  const rest = ids.filter((id) => effectTab(ABILITIES[id]) !== 'heal');
  const top = (id) => {
    const i = FIELD_TOP.indexOf(ABILITIES[id]?.effect?.type);
    return i < 0 ? FIELD_TOP.length : i;
  };
  // sort は おなじ ときは もとの じゅん（弱い じゅん）の まま
  rest.sort((x, y) => top(x) - top(y));
  return { heal: heal.map((id) => byId.get(id)), other: rest.map((id) => byId.get(id)) };
}

js/shared/gear-base.js:
// 第76回: 装備の「もとの 強さ」（家族の ねがい: きたえると、もともとの 武器の 強さが わからなくなる）
//
// きたえた 装備（'sword+3'）・限界とっぱ（'sword+5_lb2' ★2）・れん金の 効果（char.gearFx[もとの id]）を
// ぬいた「きたえる 前の その 装備」（もとの 装備）の 強さを 出す。装備を えらぶ まど（client/ui/menu.js の pickGear）で
// 「今の 強さ」と「もとの 強さ」を ならべて、きたえた 武具と きたえていない 武具を くらべられるように する。
//
//   gearBaseId(id)       … もとの 装備の id（'sword+5_lb2' → 'sword'）
//   forgeLevel(id)       … きたえた 回数（★も 1回に 数える。+5★2 は 7。強さは +7 と 同じ。items-forge.js の lbItem）
//   forgeLabel(id)       … 「+5★2」（きたえていない ときは ''）
//   gearBaseStats(id)    … もとの 装備の 数字（{ id, name, atk, def, bonus }）
//   gearOwn(char, slot, id)      … その 装備 そのものの 強さ（外した 時との 差。[{ k, n, v }]）
//   gearOwnBase(char, slot, id)  … もとの 装備の 強さ（きたえ・★・れん金 なし）
//   sameForgeId(id, level, char) … もとの 装備を level 回 きたえた ときの id（きたえられる 回数で 止める）
//   gearCompare(char, slot, curId, candId) … くらべる まどの 数字（今・もと・同じだけ きたえると）
//   baseStronger(char, slot, curId, candId) … もとの 装備どうしで くらべて 強いか（「もとが強い」の しるし）
import { ITEMS, baseItemId } from './data/items.js';
import { UPGRADE_TYPES, upgradeId, lbId, LB_MAX } from './data/items-forge.js';
import { maxPlus, rebirthOf } from './data/forge.js';
import { computeStats } from './stats.js';
import { gearScore } from './equip-plan.js';

// 装備で 変わる 強さ（お店の くらべ counter.js・装備の まどと おなじ ならび）
export const GEAR_STAT_LABELS = [['atk', '攻撃力'], ['dfn', '守備力'], ['agi', '素早さ'], ['mag', '攻撃魔力'], ['heal', '回復魔力'], ['maxHp', '最大HP'], ['maxMp', '最大MP']];

// もとの 装備の id（items.js の baseItemId〈items-forge.js の base〉。表に ない ときは id の 形から: 'x+3' 'x+5_lb1'）
export function gearBaseId(id) {
  if (!id) return null;
  if (ITEMS[id]) return baseItemId(id);
  const m = /^(.+?)\+\d+(?:_lb\d+)?$/.exec(String(id));
  return m && ITEMS[m[1]] ? m[1] : id;
}
export const forgeLevel = (id) => (ITEMS[id]?.plus || 0) + (ITEMS[id]?.lb || 0);
export function forgeLabel(id) {
  const it = ITEMS[id];
  if (!it?.plus && !it?.lb) return '';
  return `+${it.plus || 0}${it.lb ? `★${it.lb}` : ''}`;
}
// きたえた・★・れん金の どれかで、もとの 強さと ちがう 物か
export function hasBoost(char, id) {
  if (!id) return false;
  return gearBaseId(id) !== id || !!(char?.gearFx?.[gearBaseId(id)]?.length);
}

// もとの 装備の 数字（その まま。キャラの 強さに した ものは gearOwnBase）
export function gearBaseStats(id) {
  const b = gearBaseId(id);
  const it = ITEMS[b];
  if (!it) return null;
  return { id: b, name: it.name, atk: it.atk || 0, def: it.def || 0, bonus: { ...(it.bonus || {}) } };
}

// れん金の 効果を ぬいた キャラ（ids の もとの 装備の ぶんだけ。ほかの 部位の 効果は のこす）
export function withoutFx(char, ...ids) {
  if (!char?.gearFx) return char;
  const fx = { ...char.gearFx };
  for (const id of ids) if (id) delete fx[gearBaseId(id)];
  return { ...char, gearFx: fx };
}

// その 装備 そのものの 強さ（その 部位を 外した 時と くらべて 上がる 分。[{ k, n, v }]）。id が null なら []
export function gearOwn(char, slot, id) {
  if (!id) return [];
  const off = computeStats({ ...char, equip: { ...(char?.equip || {}), [slot]: null } });
  const on = computeStats({ ...char, equip: { ...(char?.equip || {}), [slot]: id } });
  return GEAR_STAT_LABELS.map(([k, n]) => ({ k, n, v: (on?.[k] ?? 0) - (off?.[k] ?? 0) })).filter((x) => x.v);
}
// もとの 装備の 強さ（きたえ・★・れん金 なし）
export function gearOwnBase(char, slot, id) {
  if (!id) return [];
  return gearOwn(withoutFx(char, id), slot, gearBaseId(id));
}

// もとの 装備を level 回 きたえた ときの id（★も 1回。きたえられる 回数〈れん金で ふやした 分・★〉で 止める）
// かえす もの: { id, level: ほんとうの 回数, capped: とどかない, none: きたえられない（店の 品・アクセサリー）}
export function sameForgeId(id, level, char = null) {
  const b = gearBaseId(id);
  const it = ITEMS[b];
  const want = Math.max(0, level | 0);
  if (!it) return null;
  if (!UPGRADE_TYPES.includes(it.type) || !maxPlus(b, char)) return { id: b, level: 0, capped: want > 0, none: true };
  const rb = rebirthOf(b);
  let out = b;
  if (rb) {
    // 生まれ変わる 武器は ★なし。上限を こえて rb.at まで
    const n = Math.min(want, rb.at);
    if (n > 0 && ITEMS[upgradeId(b, n)]) out = upgradeId(b, n);
  } else {
    const top = maxPlus(b, char);
    if (want <= top) out = upgradeId(b, want);
    else {
      const k = Math.min(LB_MAX, want - top);
      out = ITEMS[lbId(b, top, k)] ? lbId(b, top, k) : upgradeId(b, top);
    }
    if (!ITEMS[out]) out = b;
  }
  const got = forgeLevel(out);
  return { id: out, level: got, capped: got < want, none: false };
}

const toMap = (list) => new Map((list || []).map((x) => [x.k, x.v]));

// くらべる まどの 数字。cur … 今の 装備（null は なし）・cand … えらんでいる 物（null は 外す）
//  { cur: { id, base, level, label }, cand: { …, same: { id, level, label, capped, none } | null },
//    rows: [{ k, n, curNow, curBase, candNow, candBase, candSame, dNow, dBase, dSame }] }
//  same … えらんでいる 物を 今の 装備と 同じ 回数 きたえた とき（今の 装備が きたえて あって、えらんでいる 物の ほうが 少ない 時だけ）
export function gearCompare(char, slot, curId, candId) {
  const side = (id) => (id ? { id, base: gearBaseId(id), level: forgeLevel(id), label: forgeLabel(id), boosted: hasBoost(char, id) } : null);
  const cur = side(curId);
  const cand = side(candId);
  const curNow = toMap(gearOwn(char, slot, curId));
  const curBase = toMap(gearOwnBase(char, slot, curId));
  const candNow = toMap(gearOwn(char, slot, candId));
  const candBase = toMap(gearOwnBase(char, slot, candId));
  let sameMap = null;
  if (cand && cur && cur.level > cand.level) {
    const s = sameForgeId(candId, cur.level, char);
    if (s) {
      cand.same = { ...s, label: forgeLabel(s.id) };
      // れん金の 効果は その 人の その 装備の しゅるいに のこるので、きたえても いっしょ（gear-fx.js）
      if (!s.none) sameMap = toMap(gearOwn(char, slot, s.id));
    }
  }
  if (cand && !cand.same) cand.same = null;
  const rows = [];
  for (const [k, n] of GEAR_STAT_LABELS) {
    const r = { k, n, curNow: curNow.get(k) || 0, curBase: curBase.get(k) || 0, candNow: candNow.get(k) || 0, candBase: candBase.get(k) || 0, candSame: sameMap ? sameMap.get(k) || 0 : null };
    if (!r.curNow && !r.curBase && !r.candNow && !r.candBase && !r.candSame) continue;
    r.dNow = r.candNow - r.curNow;
    r.dBase = r.candBase - r.curBase;
    r.dSame = sameMap ? r.candSame - r.curNow : null;
    rows.push(r);
  }
  return { slot, cur, cand, rows };
}

// もとの 装備どうしで くらべて、えらんでいる 物の ほうが 強いか（gearScore と おなじ くらべかた。れん金も ぬく）
export function baseScore(char, slot, id) {
  if (!id) return gearScore(char, slot, null);
  return gearScore(withoutFx(char, id), slot, gearBaseId(id));
}
export function baseStronger(char, slot, curId, candId) {
  if (!candId || gearBaseId(candId) === gearBaseId(curId)) return false;
  return baseScore(char, slot, candId) > baseScore(char, slot, curId);
}

js/shared/guest-rule.js:
// 第78回: ゲストの 強さの きまり（docs/plan-r78-guest.md・設計メモ docs/plan-design-r77.md の 3-8）
// 「ゲストは 家族の 平均より 少し 下」
//
// ■ 物さし
//   fightPower(st) … そのままの 戦う 力 ＝ 最大HP÷3 ＋ max(こうげき, 魔力, 回復) ＋ 守り÷2 ＋ すばやさ÷2
//     ダメージは「こうげき÷2 − 守り÷4」なので 守り 1 は こうげき 1/2 ぶん。HP は ほかの 数の 2〜3倍 ある ので ÷3。
//     すばやさは 手番の 多さ（守りと おなじ 重さ）。足す だけ なので、ぜんぶの 数を k 倍 すると 力も ちょうど k 倍
//   growPower(char) … 育ちの 力（きまりで くらべる 数）＝ fightPower(装備こみ) × fightPower(レベルの ふつうの 能力) ÷ fightPower(素の 能力)
//     素の 能力 … 装備と たねを はずした その 人（職業・職業レベル・レベルは そのまま）
//     レベルの ふつうの 能力 … 職業の 得意・不得意の ない、その レベルの 能力（stats.js の baseStats）
//     → 職業の 得意・不得意（忍者は HP が 少ない・ガーディアンは こうげきが 弱い）を ならして「レベルと 装備・たねの 育ち」で くらべる。
//       そのままの 力で くらべると、忍者の ゲストは 倍率 1.7 でも とどかず、職業の 個性が こわれる
//
// ■ きまり（guestPlan）: ゲストの 育ちの 力 ＝ その 戦いに 出る 家族の キャラ（人間）の 育ちの 力の 平均 × GUEST_RATIO（0.94。はば 0.90〜0.97）
//   1. レベルを 家族の 平均レベルに 合わせる（minLevel 〜 レベルの 上限 の 中）
//   2. ずれる ぶんは 能力に 倍率 k（0.85〜1.15）を かける（HP・こうげき・守り・魔力・回復・すばやさ。MP は かけない）
//   3. 倍率の はばで とどかない ときは、レベルを ずらして とどく レベルを さがす（平均レベルに いちばん 近い もの）
//   4. てんじょう: レベルは 上限（def.maxLevel。ない ときは minLevel ＋ GUEST_LV_SPAN）と 家族の いちばん 高い レベルの 小さい ほうまで。
//      力は 家族の いちばん 強い 人を こえない（育ちの 力でも、そのままの 力でも）
//   5. 床: その ゲストの minLevel・きまった 装備・倍率 1 の 力は 下回らない（床は てんじょうより 先。ゲストは いつも 助けに なる）
//   ・装備は いつも minLevel で 作った ときの もの（def.gear と、ない 所は その レベルの ふつうの 装備）。職業・技・見た目は かえない
//   ・同じ 入力なら 同じ 結果（乱数を 使わない）。サーバーと ひとりモードは どちらも world/battles.js の makeBattle を 通る
import { computeStats, baseStats } from './stats.js';
import { makeNpcSupportChar } from './world/party.js';

export const GUEST_RATIO = 0.94;
export const GUEST_BAND = [0.90, 0.97];
export const GUEST_K = [0.85, 1.15];
// レベルの 上限（def.maxLevel が ない ゲスト）: minLevel ＋ これ
export const GUEST_LV_SPAN = 8;
export const GUEST_MAX_LEVEL = 99;

// そのままの 戦う 力（computeStats の 形か、戦いの 中の 人〈atk・dfn・mag・healPow・agi・maxHp〉）
export function fightPower(st) {
  if (!st) return 0;
  const heal = st.heal ?? st.healPow ?? 0;
  return (st.maxHp || 0) / 3 + Math.max(st.atk || 0, st.mag || 0, heal) + (st.dfn || 0) / 2 + (st.agi || 0) / 2;
}
export const charPower = (char) => fightPower(computeStats(char));

// レベルの ふつうの 能力の 力（職業の 得意・不得意 なし・装備 なし）
export function levelPower(level) {
  const b = baseStats(Math.max(1, level || 1));
  return fightPower({ maxHp: b.hp, atk: b.str, mag: b.mag, heal: b.heal, dfn: b.def, agi: b.agi });
}
// 素の 能力の 力（装備と たねを はずす）
export function barePower(char) {
  return charPower({ ...char, equip: { weapon: null, armor: null, shield: null, head: null, acc: null }, seeds: {} });
}
// 育ちの 力（きまりで くらべる 数）
export function growPower(char) {
  const bare = barePower(char);
  return bare > 0 ? (charPower(char) * levelPower(char.level)) / bare : 0;
}

export function guestLevelCap(def) {
  const min = def.minLevel || 1;
  return Math.max(min, Math.min(GUEST_MAX_LEVEL, def.maxLevel || min + GUEST_LV_SPAN));
}

// 戦いに 出る ゲストの キャラ（レベル L・装備は minLevel の もの）。HP・MP は まんたん
export function guestBaseChar(def, level) {
  const min = def.minLevel || 1;
  const c = makeNpcSupportChar({ ...def }, level);
  if (level !== min) {
    c.equip = { ...makeNpcSupportChar({ ...def }, min).equip };
    const st = computeStats(c);
    c.hp = st.maxHp;
    c.mp = st.maxMp;
  }
  return c;
}

// 数える 家族: 人間の キャラ（species が ない）。ゲストは 入れない（呼ぶ がわで 入れない）
export const humanChars = (chars) => (chars || []).filter((c) => c && !c.species);

// きまりの 計算。family … その 戦いに 出る 家族の キャラ（人間）。魔物が まざって いても 人間だけ 数える
// かえす もの: { level, k, power, avg, max, ratio, raw, rawMax, floor, cap }
//   power … ゲストの 育ちの 力（倍率 こみ）/ avg・max … 家族の 育ちの 力の 平均と いちばん 強い 人 / ratio … power ÷ avg
//   raw・rawMax … そのままの 力（ゲスト〈倍率 こみ〉と 家族の いちばん 強い 人）
//   floor … 床で きまった / cap … てんじょう（いちばん 強い 人・レベルの 上限・倍率の 上限）で 止まった
export function guestPlan(def, family) {
  const min = def.minLevel || 1;
  const fam = humanChars(family);
  // レベルの 上限: その ゲストの 上限と 家族の いちばん 高い レベル の 小さい ほう（minLevel より 下には しない）
  const famTop = Math.max(0, ...fam.map((c) => c.level || 1));
  const maxLv = Math.max(min, Math.min(guestLevelCap(def), famTop));
  const memo = new Map();
  const at = (L) => {
    if (!memo.has(L)) {
      const c = guestBaseChar(def, L);
      memo.set(L, { grow: growPower(c), raw: charPower(c) });
    }
    return memo.get(L);
  };
  const pw = (L) => at(L).grow;
  const floor0 = at(min);
  if (!fam.length) return { level: min, k: 1, power: floor0.grow, avg: 0, max: 0, ratio: 0, raw: floor0.raw, rawMax: 0, floor: true, cap: false };
  const gs = fam.map(growPower);
  const avg = gs.reduce((s, v) => s + v, 0) / gs.length;
  const max = Math.max(...gs);
  const rawMax = Math.max(...fam.map(charPower));
  const avgLv = Math.round(fam.reduce((s, c) => s + (c.level || 1), 0) / fam.length);
  const target = Math.min(avg * GUEST_RATIO, max);
  // 1・2. 平均の レベル（minLevel 〜 上限）で 倍率
  let level = Math.max(min, Math.min(maxLv, avgLv));
  let k = target / pw(level);
  // 3. 倍率の はばに 入らない ときは、とどく レベルを さがす（平均レベルに いちばん 近い もの。同じ ときは 低い ほう）
  if (k < GUEST_K[0] || k > GUEST_K[1]) {
    let best = null;
    for (let L = min; L <= maxLv; L++) {
      const kk = target / pw(L);
      if (kk < GUEST_K[0] || kk > GUEST_K[1]) continue;
      if (best == null || Math.abs(L - avgLv) < Math.abs(best - avgLv)) best = L;
    }
    if (best != null) level = best;
    else level = target > pw(maxLv) * GUEST_K[1] ? maxLv : min;
    k = target / pw(level);
  }
  let cap = k > GUEST_K[1];
  k = Math.max(GUEST_K[0], Math.min(GUEST_K[1], k));
  // 4. てんじょう: 家族の いちばん 強い 人を こえない（育ちの 力でも、そのままの 力でも）
  const room = (L) => Math.min(max / at(L).grow, rawMax / at(L).raw);
  if (k > room(level)) {
    cap = true;
    // 倍率を 下げきっても こえる → レベルを 下げる
    while (level > min && room(level) < GUEST_K[0]) level--;
    k = Math.max(GUEST_K[0], Math.min(GUEST_K[1], k, room(level)));
  }
  // 5. 床: minLevel・倍率 1 の 力は 下回らない
  let floor = false;
  if (pw(level) * k < floor0.grow - 1e-9 || at(level).raw * k < floor0.raw - 1e-9) {
    k = Math.max(floor0.grow / pw(level), floor0.raw / at(level).raw);
    floor = true;
  }
  k = Math.round(k * 1000) / 1000;
  const power = pw(level) * k;
  return { level, k, power, avg, max, ratio: power / avg, raw: at(level).raw * k, rawMax, floor, cap };
}

// 戦いに 出る ゲストの キャラと 倍率。base … パーティーの ゲスト（HP・MP・どく を うつす。ない ときは まんたん）
export function guestForBattle(def, family, base = null) {
  const plan = guestPlan(def, family);
  const c = guestBaseChar(def, plan.level);
  if (base) {
    const bs = computeStats(base);
    const st = computeStats(c);
    const hr = bs.maxHp > 0 ? Math.max(0, Math.min(1, (base.hp ?? bs.maxHp) / bs.maxHp)) : 1;
    const mr = bs.maxMp > 0 ? Math.max(0, Math.min(1, (base.mp ?? bs.maxMp) / bs.maxMp)) : 1;
    c.hp = (base.hp ?? 1) > 0 ? Math.max(1, Math.round(st.maxHp * hr)) : 0;
    c.mp = Math.round(st.maxMp * mr);
    if (base.status?.poison) c.status = { poison: true };
    if (base.tactics) c.tactics = base.tactics;
  }
  return { char: c, plan };
}

// 戦いの 中の ゲストに 倍率を かける（Battle を 作った すぐ あと 1回だけ）
const SCALE_KEYS = ['maxHp', 'atk', 'dfn', 'mag', 'healPow', 'agi'];
export function scaleGuestActor(a, k) {
  if (!a || !(k > 0) || k === 1) return a;
  const hr = a.maxHp > 0 ? a.hp / a.maxHp : 0;
  for (const key of SCALE_KEYS) if (typeof a[key] === 'number') a[key] = Math.max(key === 'maxHp' || key === 'agi' ? 1 : 0, Math.round(a[key] * k));
  a.hp = a.alive ? Math.max(1, Math.min(a.maxHp, Math.round(a.maxHp * hr))) : 0;
  a.guestK = k;
  return a;
}

// 戦いの あと: 戦いの 中の HP・MP の 割合を パーティーの ゲストへ もどす
export function guestAfterBattle(base, a) {
  const st = computeStats(base);
  base.hp = a.alive && a.hp > 0 ? Math.max(1, Math.min(st.maxHp, Math.round(st.maxHp * (a.hp / Math.max(1, a.maxHp))))) : 0;
  base.mp = Math.max(0, Math.min(st.maxMp, Math.round(st.maxMp * (a.mp / Math.max(1, a.maxMp)))));
}

js/shared/item-sources.js:
// 第64回 ⑥a: 素材・道具の 入手先（作りたい 装備を しらべた ときに 出す。client/ui/sources.js）
//   ・魔物が 落とす（monsters.js の drops・data/loot.js の MAT_DROPS）… 出る 場所（出現表 → その表を 使う マップ）
//     ダンジョンでしか 出ない ときは ダンジョンの 名前。図鑑で 見た 魔物は 名前、まだの 魔物は ？？？（場所は 出す）
//   ・店で 売っている（data/shops.js）・宝箱（マップの chests）は そのまま 場所
//   データから 自動で 作る（魔物や マップが ふえても 書きたさなくて よい）
import { ITEMS } from './data/items.js';
import { MONSTERS } from './data/monsters.js';
import { MAT_DROPS, DROP_N } from './data/loot.js';
import { ENCOUNTER_TABLES } from './data/encounters.js';
import { NIGHT_ZONES } from './data/night.js';
import { SHOPS } from './data/shops.js';
import { MAPS } from './maps/index.js';

let cache = null;

// 第65回: データから 自動で わからない 入手先（宝の地図・闘技場・ひみつのダンジョンの ごほうび）
export const EXTRA_SOURCES = {
  limit_stone: ['宝の地図の洞窟（Lv30から）の主の宝箱', '闘技場のランク9・10のごほうび', 'ひみつのダンジョンの30階からの休み所'],
};

// 出現表 → その表を 使う 場所（{ map, name, field }）。昼の 表と 夜の 表は 同じ 場所
function zonePlaces() {
  const out = new Map();
  const add = (table, p) => {
    if (!out.has(table)) out.set(table, []);
    const list = out.get(table);
    if (!list.some((x) => x.map === p.map && x.name === p.name)) list.push(p);
  };
  for (const m of Object.values(MAPS)) {
    if (!m.spawnCounts) continue;
    const zones = Object.keys(m.spawnCounts);
    // フィールドは その ちいきの 名前（ホシフル村のまわり など）。数が 多いので とびとびに しらべる
    const names = new Map();
    if (m.kind === 'field' && typeof m.zoneAt === 'function' && typeof m.areaName === 'function') {
      const step = Math.max(1, Math.floor(Math.max(m.w, m.h) / 120));
      const tally = new Map();
      for (let y = 0; y < m.h; y += step) {
        for (let x = 0; x < m.w; x += step) {
          const z = m.zoneAt(x, y);
          if (!z || !zones.includes(z)) continue;
          const nm = m.areaName(x, y);
          if (!nm) continue;
          const t = tally.get(z) || new Map();
          t.set(nm, (t.get(nm) || 0) + 1);
          tally.set(z, t);
        }
      }
      for (const [z, t] of tally) names.set(z, [...t].sort((a, b) => b[1] - a[1])[0][0]);
    }
    for (const z of zones) {
      const p = { map: m.id, name: names.get(z) || m.name, field: m.kind === 'field' };
      add(z, p);
      if (NIGHT_ZONES[z]) add(NIGHT_ZONES[z], { ...p, night: true });
    }
  }
  return out;
}

// 魔物 → 出る 場所
function build() {
  const places = zonePlaces();
  const mon = new Map();
  for (const [table, list] of Object.entries(ENCOUNTER_TABLES)) {
    const ps = places.get(table);
    if (!ps || !Array.isArray(list)) continue;
    for (const e of list) {
      for (const [sp] of e.group || []) {
        if (!mon.has(sp)) mon.set(sp, []);
        const l = mon.get(sp);
        for (const p of ps) if (!l.some((x) => x.map === p.map && x.name === p.name)) l.push(p);
      }
    }
  }
  // 道具 → 落とす 魔物（[{ species, n: 何体に 1回, kind }]）
  const drops = new Map();
  const addDrop = (id, sp, n, kind) => {
    if (!id || !ITEMS[id]) return;
    if (!drops.has(id)) drops.set(id, []);
    const l = drops.get(id);
    if (!l.some((x) => x.species === sp)) l.push({ species: sp, n, kind });
  };
  for (const [sp, m] of Object.entries(MONSTERS)) {
    const d = m.drops || {};
    if (d.common) addDrop(d.common[0], sp, d.common[1] || DROP_N.common, 'common');
    if (d.rare) addDrop(d.rare[0], sp, d.rare[1] || DROP_N.rare, 'rare');
    if (d.boss) for (const id of [].concat(d.boss)) addDrop(id, sp, 1, 'boss');
    if (d.bonus) for (const id of [].concat(d.bonus)) addDrop(id, sp, 1, 'boss');
  }
  for (const [sp, [id, n]] of Object.entries(MAT_DROPS)) addDrop(id, sp, n || DROP_N.mat, 'mat');
  // 店・宝箱
  const shops = new Map();
  for (const sh of Object.values(SHOPS)) for (const id of sh.items || []) {
    if (!shops.has(id)) shops.set(id, []);
    if (!shops.get(id).includes(sh.name)) shops.get(id).push(sh.name);
  }
  const chests = new Map();
  for (const m of Object.values(MAPS)) for (const ch of m.chests || []) {
    if (!ch?.item || !ITEMS[ch.item]) continue;
    if (!chests.has(ch.item)) chests.set(ch.item, []);
    const nm = m.kind === 'field' && typeof m.areaName === 'function' ? m.areaName(ch.x, ch.y) || m.name : m.name;
    if (!chests.get(ch.item).includes(nm)) chests.get(ch.item).push(nm);
  }
  return { mon, drops, shops, chests };
}
const data = () => (cache ||= build());

// その 魔物が 出る 場所（[{ map, name, field }]。ボスなど 出現表に ない 魔物は []）
export function monsterPlaces(species) {
  return data().mon.get(species) || [];
}

// その 道具の 入手先。seen(species) … 図鑑で 見たか（見ていない 魔物は 名前を ？？？）
//   [{ kind: 'monster', species, name, places: [名前], dungeon: ダンジョンでしか 出ない, n, boss },
//    { kind: 'shop', name }, { kind: 'chest', name }, { kind: 'note', name }（EXTRA_SOURCES）]
export function itemSources(id, seen = () => true) {
  const d = data();
  const out = [];
  // 弱い 魔物（はやく 行ける 場所）から。出る 場所の ない 魔物（配合だけ など）は ボスの ほかは 出さない
  const lv = (sp) => MONSTERS[sp]?.lv || 99;
  for (const x of (d.drops.get(id) || []).slice().sort((a, b) => lv(a.species) - lv(b.species) || a.n - b.n)) {
    const ps = monsterPlaces(x.species);
    if (!ps.length && x.kind !== 'boss' && !MONSTERS[x.species]?.boss) continue;
    const dungeon = ps.length > 0 && ps.every((p) => !p.field);
    // 「炎の山　1階」「炎の山　2階」は「炎の山」に まとめる
    const names = [...new Set(ps.map((p) => String(p.name).split('　')[0]))];
    out.push({ kind: 'monster', species: x.species, name: seen(x.species) ? MONSTERS[x.species]?.name || x.species : '？？？', seen: !!seen(x.species), places: names, dungeon, n: x.n, boss: x.kind === 'boss' || !!MONSTERS[x.species]?.boss });
  }
  for (const name of d.shops.get(id) || []) out.push({ kind: 'shop', name });
  for (const name of d.chests.get(id) || []) out.push({ kind: 'chest', name });
  for (const name of EXTRA_SOURCES[id] || []) out.push({ kind: 'note', name });
  return out;
}

// 1行の 文（「はぐれウルフ（ホシフル村のまわり）」「？？？（ねむりの洞窟）」「ルミナの道具屋で売っている」）
export function sourceText(s, maxPlaces = 2) {
  if (s.kind === 'shop') return `${s.name}で売っている`;
  if (s.kind === 'chest') return `${s.name}の宝箱`;
  if (s.kind === 'note') return s.name;
  const where = s.places.length ? `（${s.places.slice(0, maxPlaces).join('・')}${s.places.length > maxPlaces ? 'など' : ''}）` : s.boss ? '（ボス）' : '';
  // 落とす 回数の 目安（何体に 1回）
  const often = s.boss ? '' : s.n <= 5 ? 'よく' : s.n <= 12 ? 'ときどき' : 'たまに';
  return `${s.name}が${often}落とす${where}`;
}

js/shared/job-label.js:
// 職業の 名前・説明を、その 人に 合わせて えらぶ（第33回 家族が きめた こと）
//
// 男の子（look.body が 1 で ない）の 美少女戦士は「仮面のしんし」、セーラームーンは「タキシード仮面」。
// 見た目（client/render/hero-r33.js の R33_MASC）と 技（ability-label.js の abilityFor）も 男の子 むけ。女の子は 今の まま。
// 強さ・じょうけん・ID は おなじで、名前・みじかい 名前・かな・説明・神殿の うわさ だけ かわる。
//
//  職業の データに masc: { name, short, kana, desc, hint } を 書くと、男の子には それで うわがきする
//
//  jobFor(id, 人)   … その 人 むけの 職業の データ（masc が なければ もとの まま。おなじ 物を かえす）
//  jobLabel(id, 人) … その 人 むけの 職業の 名前（職業の 名前を 出す 所は ぜんぶ これ か jobFor を 使う）
//  jobShort(id, 人) … みじかい 名前
//  jobHint(id, 人)  … 神殿の うわさ（JOB_HINTS か masc.hint）
//  人 … キャラ（char）・戦いの 人（combatant）・パーティーの 人（look を もつ もの）。
//       転職の 一覧などは「見ている 人（その 職業に なる 人）」で きめる
import { JOBS, JOB_HINTS } from './data/jobs.js';

// 男の子か（見た目の look.body が 1 で ない）。モンスター（仲間の 魔物・敵）は ちがう。
// look の ない もの（職業だけの { job, jobs }・敵・古い データ）は もとの まま（ちがう 名前を 出さない ため）
// ability-label.js も これを 使う（男の子かの きめ方は ここ 1か所）
export function isMasc(who) {
  if (!who || typeof who !== 'object' || who.mon) return false;
  return !!who.look && typeof who.look === 'object' && who.look.body !== 1;
}

const cache = new WeakMap();
export function jobFor(jobId, who) {
  const j = JOBS[jobId];
  if (!j || !j.masc || !isMasc(who)) return j;
  let m = cache.get(j);
  if (!m) {
    m = { ...j, ...j.masc };
    delete m.masc;
    delete m.hint;
    cache.set(j, m);
  }
  return m;
}

export function jobLabel(jobId, who) {
  return jobFor(jobId, who)?.name || '';
}

export function jobShort(jobId, who) {
  const j = jobFor(jobId, who);
  return j?.short || j?.name || '';
}

export function jobHint(jobId, who) {
  return (isMasc(who) && JOBS[jobId]?.masc?.hint) || JOB_HINTS[jobId] || '';
}

js/shared/look-equip.js:
// 見た目装備（ドラクエ10の おしゃれ装備ふう）
//   ほんとうの 装備（char.equip）は そのまま で、見た目だけ べつの 物に できる。強さは かわらない
//   （computeStats は char.equip だけを 見る）
//
// char.lookEquip = { weapon?, armor?, shield?, head? }（ない 部位・ない ときは「今の装備と同じ」）
//   'none' … 装備なし に 見える（武器を もたない・かぶとを かぶらない・よろいは ふだんの 服）
//   品物の ID … その 品物に 見える。きたえた 物（鉄の剣+2 など）は もとの 品物の ID で おぼえる
//
// えらべる 物: 持っている 物だけ。ふくろの 中の 物と、自分・自分の 仲間（パーティー・馬車・酒場）が
//   装備している 物（メニューの 装備の まどと おなじ 考え。ふくろは みんなで 1つ）。
//   職業の きまりは 関係ない（戦士が つえを もっている ように 見せられる）
// えらんだ 物を あとで 売った・捨てた ときも、見た目は そのまま おぼえておく（ドラクエ10と おなじ）。
//   知らない 品物に なった ときや 部位が ちがう ときは「今の装備と同じ」に もどして 見せる
// モンスターの 仲間は 絵に 装備が 出ないので、見た目装備は ない
import { ITEMS, baseItemId } from './data/items.js';

export const LOOK_SLOTS = ['weapon', 'armor', 'shield', 'head'];
export const LOOK_NONE = 'none';

// その 部位の 見た目として 使える 品物か
function lookItemOk(slot, id) {
  return typeof id === 'string' && id !== LOOK_NONE && Object.prototype.hasOwnProperty.call(ITEMS, id) && ITEMS[id]?.type === slot;
}

// 見せる 装備（{ weapon, armor, shield, head, acc }）。見た目装備が ない ときは equip を そのまま かえす
// （equip が ない 人は 今までどおり 職業の はじめの 装備の 絵に なる。client/render/chars.js の parseEquip）
export function shownEquip(c) {
  const lk = c?.lookEquip;
  if (!lk || typeof lk !== 'object' || c?.species) return c?.equip;
  const out = { ...(c.equip || {}) };
  for (const sl of LOOK_SLOTS) {
    const v = lk[sl];
    if (v === LOOK_NONE) out[sl] = null;
    else if (lookItemOk(sl, v)) out[sl] = v;
  }
  return out;
}

// 見せる 装備を 1つの もじれつに（'ぶき,よろい,たて,あたま'。いちの じょうほう・戦いの 顔で つかう）
export function shownEquipKey(c) {
  const e = shownEquip(c);
  if (!e) return '';
  return [e.weapon || '', e.armor || '', e.shield || '', e.head || ''].join(',');
}

// 持っている その 部位の 物（もとの 品物の ID。かさならない。ふくろの じゅん → 装備している 人の じゅん）
//   bag … ふくろ（{ items: [{ id, n }] }）、team … 装備を 見る 人たち（キャラの ならび）
export function lookChoices(slot, bag, team = []) {
  const out = [];
  const put = (id) => {
    const b = baseItemId(id);
    if (lookItemOk(slot, b) && !out.includes(b)) out.push(b);
  };
  for (const e of bag?.items || []) if (e?.n > 0) put(e.id);
  for (const ch of team) put(ch?.equip?.[slot]);
  return out;
}

// サーバーで 使う: 自分の 持ち物を 見る 人たち（自分と 自分の 仲間 みんな）
export function ownerTeam(owner) {
  return [owner, ...(owner?.companions || []).map((e) => e?.char).filter(Boolean)];
}

// 見た目を かえる（サーバー。who … かえる 人、owner … ふくろの 持ち主）
//   id: null か 'same' … 今の装備と同じ／'none' … 装備なし／品物の ID … その 品物の 見た目
//   slot: 'all' と id: null で ぜんぶ もとに もどす
// かえす もの: { ok, text }（ok が false の ときは 何も かえない）
export function setLookEquip(who, owner, slot, id) {
  if (!who || who.species) return { ok: false, text: 'モンスターは見た目装備を変えられない' };
  if (slot === 'all') {
    if (id !== null && id !== undefined && id !== 'same') return { ok: false, text: '' };
    delete who.lookEquip;
    return { ok: true, text: `${who.name}の見た目を、今の装備と同じにもどした。` };
  }
  if (!LOOK_SLOTS.includes(slot)) return { ok: false, text: '' };
  const lk = who.lookEquip && typeof who.lookEquip === 'object' ? { ...who.lookEquip } : {};
  if (id === null || id === undefined || id === 'same') delete lk[slot];
  else if (id === LOOK_NONE) lk[slot] = LOOK_NONE;
  else {
    if (typeof id !== 'string' || !ITEMS[id]) return { ok: false, text: '' };
    const b = baseItemId(id);
    if (!lookItemOk(slot, b)) return { ok: false, text: 'その部位の装備ではない' };
    if (!lookChoices(slot, owner, ownerTeam(owner)).includes(b)) return { ok: false, text: '持っていない物は選べない' };
    lk[slot] = b;
  }
  if (Object.keys(lk).length) who.lookEquip = lk;
  else delete who.lookEquip;
  return { ok: true, text: `${who.name}の見た目を変えた！` };
}

// セーブを 読む ときの 手直し（save.js の repairChar）。形が ちがう ものは すてる。
// 知らない 品物の ID（新しい 版で えらんだ 物）は けさずに のこす（その 版では「今の装備と同じ」に 見える）
export function cleanLookEquip(c) {
  if (!c || typeof c !== 'object') return;
  if (c.lookEquip === undefined) return;
  const lk = c.lookEquip;
  const out = {};
  if (lk && typeof lk === 'object' && !Array.isArray(lk) && !c.species) {
    for (const sl of LOOK_SLOTS) {
      const v = lk[sl];
      if (typeof v === 'string' && v && v.length <= 60) out[sl] = v;
    }
  }
  if (Object.keys(out).length) c.lookEquip = out;
  else delete c.lookEquip;
}

