  if (!now) {
    const a = c7tArrive(n);
    m.triggers.push({ id: `c7_tf${n}`, x: Math.floor(a.x) - 2, y: Math.floor(a.y) - 1, w: 5, h: 3, script: `c7_tf${n}`, show: { not: [TF7(n)] } });
