  for (let n = 1; n <= C7T_FLOORS; n++) maps[c7tMapId(n)] = c7tMap(n, false);
  for (let n = 1; n <= C7T_NOW_FLOORS; n++) maps[c7tMapId(n, true)] = c7tMap(n, true);
