const PAST_ONLY = {
  '~': T.C8C_SKY, k: T.C8C_SKY, c: T.CAVE_FLOOR, e: T.C8C_SKY, r: T.C8C_PLATE, G: T.CAVE_FLOOR, a: T.C8C_STEAM_FLOOR, b: T.C8C_STEAM_FLOOR,
