};
const NOW_ONLY = {
  '~': T.C8C_CRUSH, k: T.C8C_MOSS, c: T.C8C_CRUSH, e: T.C8C_SLIDE_W, r: T.C8C_ROOTS, G: T.C8C_LOCKDOOR, a: T.C8C_CRUSH, b: T.C8C_CRUSH,
