// S=ふういんの とびら（1階 … いのりの歌で 開く / 4階・8階 … まぼろしを たおすと 開く / 12階 … てっぺんへの とびら）
// @=光の門（1階 … 5階・9階・12階への 近道。とびらを 開けるたびに 光る / 5階・9階・12階 … 1階へ もどる 門）
// F=休み所の いずみ（4階・8階）$=宝箱（はじめの 2つは ★の 宝。maps/castle.js の castleChests）P=まぼろしの 立つ 所
// 風の階: ~=雲の 海の 見える ふきぬけ（歩けない）n・e・s・w=風の流れ（北・東・南・西へ 流される）j=曲がり角の 風（2階。風見の石で 向きが かわる）
//   v=風見の石 W=風車 x・y=2人で ふむ 石（3階 … 風車の ハンドル / 7階 … 氷の像の 台 / 11階 … 水車の ハンドル）
//   Z=風の 窓から ふく 強い 風（3階。東の 小べやへ 流される。2つの 風車で 止まる）V=風の 窓
// 炎の階: a・b=炎の 柱（a と b が かわるがわる ふき上がる）c=ずっと もえている 炎の 柱（6階。氷の像の 息で 止まる）
//   g=炎の 大門（7階。2つの 氷の像で 止まる）I=氷の像（6階。しらべると 向きが かわる）L=像の 向きを かえる レバー =:ようがん
// 水の階: r=うく 石の 板（水が「上」で わたれる）t=とび石（「中」で わたれる）u=水路の 底（「中」「下」で 歩ける）
//   d=ふかい 底（「下」で 歩ける）q=水（いつも）h=水の 高さの ハンドル（9階）
//   8・6・2・4=流れる ゆか（北・東・南・西へ）R=向きの かわる 流れる ゆか（10階。レバー l で 東 ⇔ 西）l=レバー
//   U=水車 G=水の とびら（11階。2つの 水車で 水が ひく）

// 1つの 階の 紙（ぜんたいは CASTLE_W × CASTLE_H）。rect・put・line の 座標は、もとの 階（ひろげる 前）の 座標で 書く。
// 紙の 上では CASTLE_OX・CASTLE_OY だけ ずれる（ひろげた ところは、マイナスの 座標や もとの はばの 外で 書く）
function sheet(w, h, fill) {
  const g = Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (x === 0 || y === 0 || x === w - 1 || y === h - 1 ? '#' : fill)));
  const ok = (x, y) => x > 0 && y > 0 && x < w - 1 && y < h - 1;
  const api = {
    rect(x, y, rw, rh, ch = '.') { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) if (ok(i + OX, j + OY)) g[j + OY][i + OX] = ch; return api; },
    put(x, y, ch) { const X = x + OX, Y = y + OY; if (X >= 0 && Y >= 0 && X < w && Y < h) g[Y][X] = ch; return api; },
    puts(list, ch) { for (const [x, y] of list) api.put(x, y, ch); return api; },
    // (x, y) から dx, dy の 向きへ n マス
    line(x, y, dx, dy, n, ch) { for (let i = 0; i < n; i++) api.put(x + dx * i, y + dy * i, ch); return api; },
    rows() { return g.map((r) => r.join('')); },
  };
  return api;
}
export const CASTLE_W = 36;
export const CASTLE_H = 26;
// もとの 階（ひろげる 前）の 座標から 紙の 座標への ずれ（第38回で ひろげた。maps/castle.js の co が 使う）
export const CASTLE_OX = 5;
export const CASTLE_OY = 4;
const W = CASTLE_W, H = CASTLE_H, OX = CASTLE_OX, OY = CASTLE_OY;

// 1階「影の城の門」: 南の 城の 門 → 入口の 広間（西の かべに 3つの 光の門）→ 北の ふういんの とびら（いのりの歌）→ 北の 大広間 → 上りかいだん
function f1() {
  const s = sheet(W, H, '#');
  s.rect(6, 11, 14, 6); // 入口の 広間
  s.puts([[12, 17], [13, 17]], 'X');
  s.puts([[7, 12], [7, 14], [7, 16]], '@');
  s.puts([[12, 10], [13, 10]], 'S');
  s.rect(2, 3, 22, 7); // 北の 大広間
  s.put(12, 2, '<').puts([[11, 2], [13, 2]], 'i');
  s.puts([[7, 2], [17, 2]], 'i');
  s.puts([[6, 5], [6, 8], [19, 5], [19, 8], [10, 6], [15, 6]], 'p');
  s.puts([[2, 3], [23, 3]], '$');
  s.puts([[18, 15], [18, 12]], 'o');
  s.puts([[6, 10], [19, 10]], 'i');
  s.put(10, 10, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 入口の 広間の 西の 門番の へや・東の 見はりの 間（宝箱）
  s.put(5, 15, '.').rect(0, 12, 5, 6);
  s.puts([[0, 12], [4, 12]], 'p').put(4, 17, 'o').put(0, 17, '&');
  s.put(20, 13, '.').rect(21, 11, 7, 6);
  s.puts([[21, 11], [21, 16], [27, 16]], 'o').put(27, 13, '&');
  // 北の 大広間の 西と 東の 風の バルコニー（雲の 海が 見える 窓）
  s.put(1, 6, '.').rect(-3, 2, 4, 7).line(-4, 3, 0, 1, 5, '~').puts([[-3, 2], [-3, 8]], 'p');
  s.put(24, 6, '.').rect(25, 2, 4, 7).line(29, 3, 0, 1, 5, '~').puts([[28, 2], [28, 8]], 'p');
  return s.rows();
}

// 2階「風の流れ」: 雲の 海の 見える ふきぬけに 4つの 足場（南西・南東・北西・北東）。風の流れで わたる。
// 南東の 足場から 北へ ふく 風は、曲がり角 j で 西（北西の 足場）へ。北西の 足場の 風見の石を 回すと、曲がり角が 北（北東の 足場・上りかいだん）へ
function f2() {
  const s = sheet(W, H, '~');
  s.rect(2, 11, 6, 5); // 南西の 足場（下りかいだん）
  s.rect(18, 12, 6, 4); // 南東の 足場
  s.rect(2, 2, 6, 7); // 北西の 足場（風見の石）
  s.rect(17, 2, 7, 4); // 北東の 足場（上りかいだん）
  s.put(3, 15, '>');
  s.line(8, 13, 1, 0, 10, 'e'); // 南西 → 南東
  s.line(20, 11, 0, -1, 3, 'n'); // 南東 → 北へ
  s.put(20, 8, 'j'); // 曲がり角（西 / 風見の石で 北）
  s.line(19, 8, -1, 0, 12, 'w'); // 曲がり角 → 北西
  s.line(20, 7, 0, -1, 2, 'n'); // 曲がり角 → 北東
  s.line(4, 9, 0, 1, 2, 's'); // 北西 → 南西
  s.line(16, 3, -1, 0, 9, 'w'); // 北東 → 北西
  s.put(3, 3, 'v');
  s.put(22, 2, '<');
  s.puts([[22, 15], [6, 2]], '$');
  s.put(2, 8, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 北西の 足場の 西の 風見の 塔（歩いて）・北東の 足場の 北の 見晴らし（上りかいだんの 先）
  s.rect(-2, 1, 4, 6).puts([[-2, 1], [-2, 6]], 'p');
  s.rect(16, -2, 8, 4).puts([[16, -2], [23, -2]], 'p');
  // 南西の 足場 → 風（東 → 南）→ 南の 小島（宝箱）→ 風（北）→ 南西 → 南東の 風に のって 南東の 足場へ
  s.line(8, 15, 1, 0, 3, 'e').line(11, 15, 0, 1, 2, 's');
  s.rect(9, 17, 7, 3).put(15, 19, '&');
  s.line(14, 16, 0, -1, 3, 'n');
  // 南東の 足場 → 風（東）→ 東の 雲の 小島（宝箱）→ 風（西）→ 南東の 足場
  s.line(24, 15, 1, 0, 2, 'e');
  s.rect(26, 9, 4, 8).put(29, 9, '&');
  s.line(25, 12, -1, 0, 2, 'w');
  return s.rows();
}

// 3階「風車」: まん中の 通路を 風の 窓の 強い 風（Z）が ふさぐ（東の 小べやへ 流される）。西と 東の へやの 風車の ハンドル（x・y）を
// 2人 同時に ふむと 風の 窓が とじる（家族で 分かれる・ひとりは 仲間に 待っていて もらう）
function f3() {
  const s = sheet(W, H, '#');
  s.rect(8, 10, 10, 6); // まん中の 広間（下りかいだん）
  s.put(12, 16, '>');
  s.rect(12, 3, 1, 7); // 北への 通路
  s.line(12, 7, 1, 0, 3, 'Z'); // 強い 風（東へ）
  s.put(11, 7, 'V');
  s.rect(15, 6, 2, 1).rect(15, 7, 1, 3); // 風に 流された 先の 小べや → 広間へ もどる
  s.rect(9, 1, 7, 3); // 上りかいだんの へや
  s.put(12, 1, '<');
  s.rect(1, 3, 6, 11); // 西の へや（風車）
  s.rect(19, 3, 6, 11); // 東の へや（風車）
  s.rect(6, 12, 3, 1).rect(17, 12, 3, 1); // 広間 ⇔ 西・東
  s.put(3, 3, 'W').put(3, 4, 'x');
  s.put(22, 3, 'W').put(22, 4, 'y');
  s.puts([[1, 13], [24, 13]], '$');
  s.puts([[4, 9], [21, 9]], 'p');
  s.put(10, 10, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 西と 東の へやの 南の 粉ひき小屋（宝箱は 西）・西の へやの 西の 風の 窓の 回廊
  s.put(3, 14, '.').rect(1, 15, 6, 5).puts([[6, 15], [6, 19]], 'o').put(1, 19, '&');
  s.put(22, 14, '.').rect(19, 15, 6, 5).puts([[19, 15], [24, 15], [19, 19]], 'o');
  s.put(0, 8, '.').rect(-3, 5, 3, 7).line(-4, 6, 0, 1, 5, '~');
  // 上りかいだんの へやの 西と 東の 見晴らし（風の 窓が とじてから。東に 宝箱）
  s.put(8, 1, '.').rect(2, -2, 6, 4).line(2, -3, 1, 0, 6, '~');
  s.put(16, 1, '.').rect(17, -2, 6, 4).line(17, -3, 1, 0, 6, '~').put(22, -2, '&');
  return s.rows();
}

// 4階「嵐の間」: 南の 休み所（いずみ・本だな）→ 北の 大広間に 嵐の将軍ストルムの まぼろし → その おくの ふういんの とびら2 → 上りかいだん
function f4() {
  const s = sheet(W, H, '#');
  s.rect(7, 12, 12, 5); // 休み所
  s.put(8, 16, '>');
  s.put(16, 12, 'F').put(18, 12, 'k');
  s.rect(12, 10, 2, 2); // 休み所 → 大広間
  s.rect(3, 3, 20, 7); // 大広間
  s.put(12, 4, 'P');
  s.puts([[12, 2], [13, 2]], 'S');
  s.put(12, 1, '<').put(13, 1, '<');
  s.puts([[5, 4], [5, 8], [20, 4], [20, 8]], 'p');
  s.puts([[3, 9], [22, 9]], '$');
  s.puts([[3, 3], [22, 3]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 休み所の 西の 書庫（本だな）・東の 雲の 見える 窓の 間（宝箱）
  s.put(6, 14, '.').rect(0, 12, 6, 6).puts([[0, 12], [1, 12], [4, 12], [5, 12]], 'k');
  s.put(19, 14, '.').rect(20, 11, 6, 6).line(26, 12, 0, 1, 4, '~').put(25, 16, '&');
  // 大広間の 西と 東の 回廊（ストルムの まぼろしの 前を とおって から。西に 宝箱）
  s.put(2, 4, '.').rect(-2, 2, 4, 5).puts([[-2, 6], [1, 6]], 'p').put(-2, 2, '&');
  s.put(23, 4, '.').rect(24, 2, 4, 5).puts([[24, 6], [27, 6]], 'p');
  return s.rows();
}

// 5階「炎の柱」: 長い 通路に 炎の 柱（a と b が かわるがわる ふき上がる）。炎が 止まっている 間に 通りぬける。
// 南の 通路 → 東の 通路 → まん中の 通路 → 西の 通路 → 北の 通路 → 上りかいだん。下りかいだんの そばに 1階へ もどる 光の門
function f5() {
  const s = sheet(W, H, '#');
  s.rect(1, 14, 23, 2); // 南の 通路
  s.rect(1, 12, 3, 2);
  s.put(1, 13, '>').put(2, 12, '@');
  s.rect(22, 9, 2, 5); // 東の 通路（北へ）
  s.rect(3, 9, 19, 2); // まん中の 通路（西へ）
  s.rect(3, 4, 2, 5); // 西の 通路（北へ）
  s.rect(5, 3, 19, 2); // 北の 通路（東へ）
  s.put(23, 2, '<').put(22, 2, 'i');
  for (const x of [6, 12, 18]) s.line(x, 14, 0, 1, 2, 'a');
  for (const x of [9, 15]) s.line(x, 14, 0, 1, 2, 'b');
  s.line(22, 11, 1, 0, 2, 'b');
  for (const x of [17, 11]) s.line(x, 9, 0, 1, 2, 'a');
  for (const x of [14, 7]) s.line(x, 9, 0, 1, 2, 'b');
  s.line(3, 6, 1, 0, 2, 'a');
  for (const x of [9, 15]) s.line(x, 3, 0, 1, 2, 'b');
  for (const x of [12, 19]) s.line(x, 3, 0, 1, 2, 'a');
  // わきの 小べや（宝箱）
  s.rect(10, 12, 3, 1).put(11, 13, '.').put(10, 12, '$');
  s.rect(6, 6, 3, 2).put(5, 6, '.').put(8, 6, '$');
  s.put(24, 10, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 北西の 炎の へや: 炎の 柱（a）の 列の むこうに 宝箱
  s.put(2, 5, '.').rect(-3, 0, 5, 7).line(-3, 3, 1, 0, 5, 'a').put(-3, 0, '&');
  // 東の 炎の 見晴らし: 炎の 柱（b）の 列の むこうに 宝箱
  s.put(24, 13, '.').rect(25, 9, 5, 7).line(27, 9, 0, 1, 7, 'b').puts([[29, 9], [29, 15]], '=').put(29, 12, '&');
  // 南の 炎の 宝物庫（入口に 炎の 柱 b）
  s.put(13, 16, 'b').rect(6, 17, 13, 3).puts([[7, 18], [10, 18], [16, 18]], '=').put(18, 19, '&');
  return s.rows();
}

// 6階「氷の像」: まん中の 広間に 大きな 氷の像（I）。像の 向いている 方の、まっすぐな 線の 上の 炎の 柱（c）が こおって 止まる。
// しらべる（か レバー L）と、像は 南 → 西 → 北 → 東 → 南 の じゅんに 向きを かえる。東の 炎の 先の へやから 北へ、
// 北の ふきぬけ（雲の 海。息は とどく）の 先の 炎を こおらせて、西の 上りかいだんへ
function f6() {
  const s = sheet(W, H, '#');
  s.rect(9, 7, 7, 5); // まん中の 広間
  s.put(12, 9, 'I');
  s.rect(12, 12, 1, 3); // 南の 通路（下から 来る）
  s.put(12, 12, 'c');
  s.rect(10, 15, 5, 2); // 下りかいだんの へや
  s.put(10, 16, '>').put(14, 15, 'L');
  s.rect(4, 9, 5, 1).put(8, 9, 'c'); // 西の 通路
  s.rect(1, 7, 3, 5).put(1, 7, '$'); // 西の へや
  s.rect(16, 9, 2, 1).put(16, 9, 'c'); // 東の 通路
  s.rect(18, 7, 6, 5).put(22, 10, 'L'); // 東の へや
  s.rect(21, 3, 1, 4); // 東の へや → 北
  s.rect(2, 2, 20, 2); // 北の 通路
  s.line(12, 4, 0, 1, 3, '~'); // 広間の 北の ふきぬけ（雲の 海。像の 息が とどく）
  s.puts([[12, 2], [12, 3]], 'c');
  s.rect(1, 1, 4, 3).put(2, 1, '<').put(4, 1, 'L'); // 上りかいだんの へや（北西）
  s.puts([[23, 7], [7, 3]], '$');
  s.puts([[9, 7], [15, 7], [9, 11], [15, 11]], 'p');
  s.put(13, 15, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 下りかいだんの へやの 東の 小べや（宝箱）・西の へやの 南の へや
  s.put(15, 16, '.').rect(16, 13, 5, 5).puts([[16, 13], [20, 13]], 'p').put(20, 17, '&');
  s.put(2, 12, '.').rect(-2, 13, 6, 5).puts([[-2, 13], [3, 17]], 'p');
  // 東の へやの 東の 見張り台（宝箱）・北の 通路の 北の 回廊（どちらも 像の 息の 線の 外）
  s.put(24, 10, '.').rect(25, 6, 5, 7).puts([[27, 8], [27, 11]], '=').put(29, 6, '&');
  s.puts([[7, 1], [7, 0]], '.').rect(3, -2, 8, 2).puts([[3, -2], [10, -2]], 'p');
  return s.rows();
}

// 7階「炎の大門」: 北の 上りかいだんの 前に 炎の 大門（g）。西と 東の へやの 氷の像の 台（x・y）に 2人 同時に 手を かざすと、
// 像の 息で 大門が こおって 止まる。西と 東の へやへの 通路には 炎の 柱（a・b）
function f7() {
  const s = sheet(W, H, '#');
  s.rect(8, 11, 10, 5); // 南の 広間（下りかいだん）
  s.put(12, 16, '>');
  s.rect(10, 5, 6, 6); // 大門の 前
  s.line(10, 4, 1, 0, 6, 'g'); // 炎の 大門
  s.rect(10, 1, 6, 3);
  s.put(13, 1, '<');
  s.rect(3, 13, 5, 1).put(4, 13, 'a').put(6, 13, 'b'); // 西の 通路（a と b の 間に 待つ マス。となりあうと 通れない）
  s.rect(1, 3, 3, 11); // 西の へや
  s.put(2, 3, 'I').put(2, 4, 'x');
  s.rect(18, 13, 5, 1).put(19, 13, 'b').put(21, 13, 'a'); // 東の 通路（b と a の 間に 待つ マス）
  s.rect(22, 3, 3, 11); // 東の へや
  s.put(23, 3, 'I').put(23, 4, 'y');
  s.puts([[1, 13], [24, 13]], '$');
  s.puts([[1, 6], [24, 6]], '=');
  s.puts([[11, 6], [14, 6]], 'p');
  s.put(9, 11, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 大門の 前の 西と 東の 炎の 祭だん（溶岩）
  s.put(9, 7, '.').rect(5, 5, 4, 5).puts([[5, 5], [5, 9]], '=');
  s.put(16, 7, '.').rect(17, 5, 4, 5).puts([[20, 5], [20, 9]], '=');
  // 西と 東の へやを ひろげる（東に 宝箱）
  s.rect(-3, 7, 4, 6).puts([[-3, 7], [-3, 12]], '=');
  s.rect(25, 7, 4, 6).puts([[28, 7]], '=').put(28, 12, '&');
  // 上りかいだんの へやの 北の 見晴らし（炎の 大門の 先。宝箱）
  s.put(11, 0, '.').rect(7, -3, 12, 3).puts([[7, -3], [7, -1]], 'p').put(18, -3, '&');
  return s.rows();
}

// 8階「炎の間」: 南の 休み所 → 北の 大広間に 炎の魔女イグニアの まぼろし → ふういんの とびら3 → 上りかいだん
function f8() {
  const s = sheet(W, H, '#');
  s.rect(4, 12, 18, 5); // 休み所
  s.put(20, 16, '>');
  s.put(6, 12, 'F').put(4, 12, 'k');
  s.rect(12, 10, 2, 2);
  s.rect(3, 3, 20, 7); // 大広間
  s.put(13, 4, 'P');
  s.puts([[12, 2], [13, 2]], 'S');
  s.put(12, 1, '<').put(13, 1, '<');
  s.puts([[3, 5], [3, 7], [22, 5], [22, 7]], '=');
  s.puts([[7, 4], [7, 8], [18, 4], [18, 8]], 'p');
  s.puts([[4, 9], [21, 9]], '$');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 休み所の 西と 東の へや（西に 宝箱）・大広間の 西と 東の 回廊（東に 宝箱）
  s.put(3, 14, '.').rect(-2, 12, 5, 6).puts([[-2, 12], [2, 12]], 'p').put(-2, 17, '&');
  s.put(22, 14, '.').rect(23, 12, 5, 6).puts([[27, 12], [27, 17]], '=');
  s.put(2, 4, '.').rect(-2, 2, 4, 5).puts([[-2, 6], [1, 6]], 'p');
  s.put(23, 4, '.').rect(24, 2, 4, 5).puts([[24, 6]], 'p').put(27, 2, '&');
  // 休み所の 南の 溶岩の 見晴らし（休み所から）
  s.put(12, 17, '.').rect(7, 18, 12, 3).puts([[8, 19], [11, 19], [14, 19], [17, 19]], '=');
  return s.rows();
}

// 9階「水の高さ」: ハンドル（h）を 回すと 水の 高さが 上 → 中 → 下 → 上。上は うく 石の 板（r）・中は とび石（t）・下は ふかい 底（d）を わたれる。
// 南の 岸 →（板）→ 西の 島 →（とび石）→ 東の 島 →（ふかい 底）→ 北の 岸（上りかいだん）。どの 岸・島にも ハンドル
function f9() {
  const s = sheet(W, H, 'q');
  s.rect(1, 13, 24, 4); // 南の 岸
  s.put(2, 16, '>').put(3, 16, '@').put(6, 13, 'h');
  s.line(5, 12, 0, -1, 4, 'r'); // 南の 岸 → 西の 島（うく 石の 板）
  s.rect(2, 5, 6, 4); // 西の 島
  s.put(3, 5, 'h');
  s.line(8, 6, 1, 0, 9, 't'); // 西の 島 → 東の 島（とび石）
  s.rect(17, 5, 7, 4); // 東の 島
  s.put(22, 8, 'h');
  s.line(20, 4, 0, -1, 2, 'd'); // 東の 島 → 北の 岸（ふかい 底）
  s.rect(14, 1, 10, 2); // 北の 岸
  s.put(22, 1, '<').put(15, 1, 'h');
  s.line(12, 12, 0, -1, 3, 'u').put(12, 9, '$'); // 南の 岸 → 宝箱（水路の 底。中・下で）
  s.line(2, 9, 0, 1, 4, 'u'); // 西の 島 → 南の 岸（水路の 底）
  s.puts([[18, 5], [23, 16]], '$');
  s.put(8, 13, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 南の 岸の 南の しずんだ 庭（水が「下」の とき だけ 歩ける ふかい 底。宝箱）
  s.put(10, 17, 'u').rect(5, 18, 13, 3, 'd').put(11, 19, '&');
  // 東の 島の 東の 小島（うく 石の 板。水が「上」で わたれる。宝箱）
  s.line(24, 6, 1, 0, 2, 'r').rect(26, 3, 4, 7).put(29, 3, '&');
  // 北の 岸の 西の 水鏡の 見晴らし・南の 岸の 西の 水門の へや
  s.rect(8, 1, 6, 2).rect(2, -2, 6, 5).rect(4, -1, 2, 2, 'q').puts([[2, -2], [7, -2]], 'p');
  s.rect(-3, 12, 4, 5).puts([[-3, 12], [-3, 16]], 'o');
  return s.rows();
}

// 10階「流れるゆか」: 流れる ゆかに のると、矢じるしの 方へ 流される。西の レバー（l）で、まん中の ゆか（R）の 向きが 東 ⇔ 西
function f10() {
  const s = sheet(W, H, '#');
  s.rect(1, 13, 6, 4); // 南西の へや（下りかいだん）
  s.put(1, 16, '>');
  s.put(2, 13, 'l');
  s.line(7, 15, 1, 0, 12, '6'); // 南の 流れ（東へ）
  s.rect(19, 13, 6, 4); // 南東の へや
  s.line(21, 12, 0, -1, 4, '8'); // 南東 → 北へ
  s.rect(19, 6, 6, 3); // 東の へや
  s.line(18, 7, 1, 0, 1, '.');
  s.line(17, 7, -1, 0, 1, 'R').line(16, 7, -1, 0, 1, 'R').line(15, 7, -1, 0, 1, 'R'); // まん中の ゆか（ふだんは 東へ）
  s.rect(9, 6, 6, 3); // まん中の へや
  s.line(11, 5, 0, -1, 2, '8'); // まん中 → 北
  s.rect(9, 1, 16, 3); // 北の 通路
  s.put(23, 1, '<');
  s.line(8, 7, -1, 0, 3, '4'); // まん中 → 西の へや
  s.rect(1, 5, 5, 5); // 西の へや
  s.line(3, 10, 0, 1, 3, '2'); // 西の へや → 南西
  s.line(24, 4, 0, 1, 2, '2'); // 北の 通路 → 東の へや（帰り道）
  s.line(23, 9, 0, 1, 4, '2'); // 東の へや → 南東の へや（帰り道）
  s.line(18, 14, -1, 0, 12, '4'); // 南東 → 南西（帰り道）
  s.put(1, 5, '$').put(24, 8, '$');
  s.put(2, 9, 'l');
  s.put(6, 16, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 南東の へやの 南 → 流れる ゆか（西へ）→ 南西の 倉庫（宝箱）→ 流れる ゆか（北へ）→ 南西の へや
  s.put(22, 17, '.').rect(19, 18, 6, 2);
  s.line(18, 19, -1, 0, 10, '4');
  s.rect(5, 18, 4, 2).put(8, 18, '&');
  s.put(5, 17, '8');
  // 北の 通路の 西の 水の 庭・東の へやの 東の 小べや（宝箱）
  s.put(8, 2, '.').rect(1, 0, 7, 4).rect(3, 1, 2, 2, 'q').puts([[1, 0], [7, 0]], 'p');
  s.put(25, 7, '.').rect(26, 4, 4, 8).put(29, 4, '&').puts([[26, 11], [29, 11]], 'p');
  // 南西の へやの 西の 物見
  s.rect(-3, 12, 4, 6).puts([[-3, 12], [-3, 17]], 'p');
  return s.rows();
}

// 11階「水車の間」: 北の 上りかいだんの 前を 水の とびら（G）が ふさぐ。西と 東の 水車の ハンドル（x・y）を 2人 同時に 回すと 水が ひく
function f11() {
  const s = sheet(W, H, '#');
  s.rect(8, 12, 10, 5); // 南の 広間
  s.put(13, 16, '>');
  s.rect(11, 5, 4, 7);
  s.rect(11, 3, 4, 2, 'G'); // 水の とびら
  s.rect(10, 1, 6, 2);
  s.put(12, 1, '<');
  s.rect(2, 4, 5, 9); // 西の へや
  s.rect(7, 14, 1, 1).rect(5, 13, 3, 1).put(7, 13, '.');
  s.put(3, 4, 'U').put(3, 5, 'x');
  s.rect(19, 4, 5, 9); // 東の へや
  s.rect(18, 14, 1, 1).rect(18, 13, 3, 1);
  s.put(22, 4, 'U').put(22, 5, 'y');
  s.line(4, 8, 0, 1, 3, 'q').line(21, 8, 0, 1, 3, 'q');
  s.puts([[2, 12], [23, 12]], '$');
  s.put(9, 12, '!');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 南の 広間の 西と 東の 倉庫（西に 宝箱）・北の 見晴らし（水の とびらの 先）
  s.put(7, 16, '.').rect(1, 15, 6, 5).puts([[6, 15], [6, 19]], 'o').put(1, 19, '&');
  s.put(18, 16, '.').rect(19, 15, 6, 5).puts([[19, 15], [24, 19]], 'o');
  s.put(14, 0, '.').rect(6, -2, 14, 2).puts([[6, -2], [19, -2]], 'p');
  // 西と 東の 水車の へやを ひろげる（東に 宝箱）
  s.rect(-2, 4, 4, 7).puts([[-2, 4], [-2, 10]], 'p');
  s.rect(24, 4, 4, 7).puts([[27, 10]], 'p').put(27, 4, '&');
  return s.rows();
}

// 12階「水鏡の間」: 南の 広間（1階へ もどる 光の門）→ 北の 大広間に 水鏡の魔人モルガナの まぼろし → てっぺんへの とびら → 上りかいだん（てっぺんへ）
function f12() {
  const s = sheet(W, H, '#');
  s.rect(7, 12, 12, 5); // 南の 広間
  s.put(12, 16, '>').put(17, 15, '@');
  s.rect(12, 10, 2, 2);
  s.rect(3, 3, 20, 7); // 大広間
  s.rect(5, 5, 4, 3, 'q').rect(17, 5, 4, 3, 'q');
  s.put(12, 4, 'P');
  s.puts([[12, 2], [13, 2]], 'S');
  s.put(12, 1, '<').put(13, 1, '<');
  s.puts([[3, 9], [22, 9]], '$');
  s.puts([[3, 3], [22, 3]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う。& … わき道の 宝箱）──
  // 南の 広間の 西と 東の へや（西に 宝箱）・大広間の 西と 東の 回廊（東に 宝箱）
  s.put(6, 14, '.').rect(0, 12, 6, 6).puts([[0, 12], [5, 12]], 'p').put(0, 17, '&');
  s.put(19, 14, '.').rect(20, 12, 6, 6).rect(22, 14, 2, 2, 'q');
  s.put(2, 4, '.').rect(-2, 2, 4, 5).puts([[-2, 6], [1, 6]], 'p');
  s.put(23, 4, '.').rect(24, 2, 4, 5).puts([[24, 6]], 'p').put(27, 2, '&');
  return s.rows();
}

export const CASTLE_ROWS = { 1: f1(), 2: f2(), 3: f3(), 4: f4(), 5: f5(), 6: f6(), 7: f7(), 8: f8(), 9: f9(), 10: f10(), 11: f11(), 12: f12() };

