      { name: 'クジラのねどこ', x: N.x - 5, y: N.y - 5, w: 10, h: 10 },
      { name: '東の砂嵐', x: SANDSEA_STORM_X, y: 4, w: SANDSEA_W - SANDSEA_STORM_X, h: SANDSEA_H - 8 },
