// 第5章 Step 6・7「大地の神殿」の レイアウト（1文字 = 1マス。文字の いみは maps/earth.js の EARTH_LEGEND）
// 8階。1階が いちばん 上で、下へ 下へ（> … 下の 階へ / < … 上の 階へ）。島々を ささえる 大きな 木の 根が、神殿を つつんでいる
// #=かべ .=ゆか ~=根の すきまの ふかい 谷（歩けない）X=神殿の 入口（1階。根の島へ）i=たいまつ O=柱 M=かべ画 R=大きな 根（歩けない）
// 1〜4=根の 水がめ（しらべると その 水がめの 根が のびる・ちぢむ。同じ 数字は 同じ 水がめ）
// a〜d=ふだんは ちぢんでいる 根（水がめ 1〜4 で のびて 橋に なる）A〜D=ふだんは のびている 根（水がめ 1〜4 で ちぢんで 谷に なる）
// G=土の 守り手（石の ゴーレム。むきは maps/earth.js の EARTH_GOLEMS）S=守り手の 石板 U=もとに もどす 石板 o=ゆかの あな（ゴーレムで うまる）
// x・y=ふむ石（4階。西・東）==根の とびら（4階。2つの ふむ石が 同時に ふまれると 開く）
// L=こわれた 上り下りの ゆか（1階 ⇔ 5階の 近道）P=重りの ゆか（5階。ゴーレムを のせると 上り下りの ゆかが 直る）
// F=大地の いずみ（5階の 休み所）k=本だな r=ピピを はさんだ 根（5階。ピピを 助けると ほどける）
// g=ゴーレムの 足場（7階。6階で ゴーレムを 根の すきまから 落とすと 谷が 足場に なる）T=大地の 守り星の 祭だん（8階）

// 1つの 階の 紙（ぜんたいは EARTH_W × EARTH_H）。rect・put・line の 座標は、もとの 階（ひろげる 前）の 座標で 書く。
// 紙の 上では EARTH_OX・EARTH_OY だけ ずれる（ひろげた ところは、マイナスの 座標や もとの はばの 外で 書く）
function sheet(w, h, fill) {
  const g = Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (x === 0 || y === 0 || x === w - 1 || y === h - 1 ? '#' : fill)));
  const ok = (x, y) => x > 0 && y > 0 && x < w - 1 && y < h - 1;
  const api = {
    rect(x, y, rw, rh, ch = '.') { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) if (ok(i + OX, j + OY)) g[j + OY][i + OX] = ch; return api; },
    put(x, y, ch) { const X = x + OX, Y = y + OY; if (X >= 0 && Y >= 0 && X < w && Y < h) g[Y][X] = ch; return api; },
    puts(list, ch) { for (const [x, y] of list) api.put(x, y, ch); return api; },
    // (x, y) から dx, dy の 向きへ n マス
    line(x, y, dx, dy, n, ch) { for (let i = 0; i < n; i++) api.put(x + dx * i, y + dy * i, ch); return api; },
    rows() { return g.map((r) => r.join('')); },
  };
  return api;
}
export const EARTH_W = 38;
export const EARTH_H = 28;
// もとの 階（ひろげる 前）の 座標から 紙の 座標への ずれ（第38回で ひろげた。maps/earth.js の eo が 使う）
export const EARTH_OX = 5;
export const EARTH_OY = 4;
const W = EARTH_W, H = EARTH_H, OX = EARTH_OX, OY = EARTH_OY;

// 1階「根のげんかん」: 根の道の 初めて。入口の 広間の 水がめで、谷を わたる 根が のびる（北の 広間にも 同じ 水がめ）。
// 入口の 広間に こわれた 上り下りの ゆか（5階で 直すと 近道）。北の 広間の かべに 大地の 守り星の かべ画
function f1() {
  const s = sheet(W, H, '#');
  s.rect(9, 13, 10, 5); // 入口の 広間
  s.puts([[13, 18], [14, 18]], 'X');
  s.rect(3, 8, 22, 5, '~'); // 根の すきまの 谷
  s.rect(5, 3, 18, 5); // 北の 広間（下りかいだん）
  s.line(14, 8, 0, 1, 5, 'a');
  s.put(10, 14, '1').put(17, 7, '1');
  s.put(20, 4, '>');
  s.put(16, 15, 'L');
  s.puts([[9, 2], [10, 2], [11, 2], [12, 2]], 'M');
  s.puts([[6, 2], [21, 2], [8, 15], [19, 15]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // 西の 根の 小べや（入口の 広間から）。水がめ2で 根（b）が 谷の 上に のびて、北西の 根の 物見へ（かべ画・宝箱）
  s.rect(4, 16, 5, 1);
  s.rect(-2, 13, 6, 6);
  s.put(-2, 14, '2');
  s.rect(-3, 8, 6, 5, '~');
  s.line(0, 8, 0, 1, 5, 'b');
  s.rect(-3, 3, 6, 5);
  s.puts([[-1, 2], [0, 2]], 'M').puts([[-3, 2], [2, 2]], 'i').put(2, 4, 'O');
  // 東の 見晴らしの 間（北の 広間から。根の 谷を 見おろす）
  s.rect(23, 5, 2, 1);
  s.rect(25, 1, 7, 8);
  s.rect(25, 9, 3, 3, '~');
  s.puts([[27, 2], [30, 2], [30, 7]], 'O').puts([[26, 0], [30, 0]], 'i');
  // 南東の 根の 物置（入口の 広間から）
  s.rect(19, 16, 2, 1);
  s.rect(21, 14, 6, 5);
  s.puts([[21, 14], [26, 18]], 'R').put(24, 13, 'i');
  return s.rows();
}

// 2階「根の道を2本つなぐ」: 水がめ1で 西の 根（A）が ちぢみ、東の 根（a）が のびる（てんびんと おなじ「片方が 上がると 片方が 下がる」）。
// まん中の 島の 水がめ2で、南の 小べや（宝箱）への 根（b）が のびる
function f2() {
  const s = sheet(W, H, '~');
  s.rect(2, 8, 5, 5); // はじめの 島
  s.put(4, 7, '<');
  s.line(7, 10, 1, 0, 4, 'A');
  s.rect(11, 7, 6, 7); // まん中の 島
  s.line(17, 10, 1, 0, 4, 'a');
  s.rect(21, 7, 5, 7); // 東の 島（下りかいだん）
  s.put(23, 6, '>');
  s.put(3, 12, '1').put(12, 7, '1').put(24, 13, '1');
  s.put(15, 13, '2');
  s.line(13, 14, 0, 1, 2, 'b');
  s.rect(12, 16, 4, 3); // 南の 小べや
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // まん中の 島の 水がめ3で 北の 根（c）が のびて、北の 見晴らしの 島へ。そこの 水がめ4で 東の 根（d）→ 北東の 小島（宝箱）
  s.put(13, 7, '3');
  s.line(14, 4, 0, 1, 3, 'c');
  s.rect(10, 0, 8, 4);
  s.puts([[10, 0], [17, 0], [10, 3]], 'O');
  s.put(16, 3, '4');
  s.line(18, 2, 1, 0, 3, 'd');
  s.rect(21, 1, 6, 3);
  // 東の 島の 東の 小島: 西の 根と おなじ「水がめ1で ちぢむ 根」（A）。東の 島の 水がめで 水を ぬくと わたれる
  s.line(26, 10, 1, 0, 2, 'A');
  s.rect(28, 8, 4, 5);
  // 南の 小べやを ひろげる（根の 広間）・西の 小島（はじめの 島から 歩いて）
  s.rect(10, 16, 8, 5);
  s.puts([[10, 20], [17, 20]], 'O');
  s.put(1, 10, '.');
  s.rect(-3, 7, 4, 7);
  s.puts([[-3, 7], [-3, 13]], 'O');
  return s.rows();
}

// 3階「土の守り手」: 北の 島の ゴーレム（南むき）を 石板で 歩かせ、根の 橋（A）を わたって、石の 道の あなを うめる。
// 水がめ1は 南の 小べやへの 根（a）を のばすが、ゴーレムの 通る 根（A）は ちぢむ（ゴーレムが 谷へ 落ちたら もとに もどす 石板）
function f3() {
  const s = sheet(W, H, '~');
  s.rect(2, 6, 7, 6); // 西の 島
  s.put(4, 5, '<');
  s.put(7, 7, 'S').put(3, 10, 'U').put(6, 11, '1');
  s.line(9, 8, 1, 0, 11, '.'); // 石の 道
  s.put(14, 8, 'o');
  s.rect(20, 6, 6, 6); // 東の 島（下りかいだん）
  s.put(23, 12, '>');
  s.rect(12, 1, 5, 3); // 北の 島（ゴーレム）
  s.put(14, 3, 'G');
  s.line(14, 4, 0, 1, 4, 'A');
  s.line(5, 12, 0, 1, 3, 'a');
  s.rect(3, 15, 5, 3); // 南の 小べや
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // 西の 根の 広間（西の 島から）・東の がけの 広間（東の 島から。宝箱）
  s.put(1, 9, '.');
  s.rect(-3, 5, 4, 8);
  s.puts([[-3, 5], [-3, 12]], 'O');
  s.put(26, 9, '.');
  s.rect(27, 5, 5, 8);
  s.puts([[27, 12], [31, 12]], 'O');
  // 北の 島（ゴーレムの いた 所）を ひろげる
  s.rect(9, 0, 11, 1).rect(9, 1, 3, 3).rect(17, 1, 3, 3);
  s.puts([[9, 0], [19, 0]], 'O');
  // 南の 小べやの 水がめ2で 南の 根（b）が のびて、根の 下の 小島へ（宝箱）
  s.put(7, 15, '2');
  s.line(5, 18, 0, 1, 2, 'b');
  s.rect(2, 20, 7, 3);
  return s.rows();
}

// 4階「2つに分かれる道」: 西と 東の 道の おくに ふむ石。2つが 同時に ふまれると、まん中の 根の とびらが 開く
// （家族なら 2組に 分かれる。ひとりなら 仲間に 片方の ふむ石で 待っていてもらう）
function f4() {
  const s = sheet(W, H, '#');
  s.rect(10, 14, 8, 4); // はじめの へや
  s.put(13, 18, '<');
  s.rect(13, 10, 2, 4); // まん中の 通路
  s.puts([[13, 9], [14, 9]], '=');
  s.rect(10, 3, 8, 6); // おくの へや（下りかいだん）
  s.put(16, 4, '>');
  // 西の 道
  s.rect(3, 15, 7, 1).rect(3, 5, 1, 10).rect(2, 2, 4, 3);
  s.put(3, 3, 'x');
  s.rect(5, 9, 3, 3).put(4, 10, '.');
  // 東の 道
  s.rect(18, 15, 7, 1).rect(24, 5, 1, 10).rect(22, 2, 4, 3);
  s.put(24, 3, 'y');
  s.rect(20, 9, 3, 3).put(23, 10, '.');
  s.puts([[11, 2], [16, 2]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // 東の 道の わきの「守り手の 小べや」: 南むきの 土の守り手を 石板で 歩かせ、あなを うめると、おくの 小べや（宝箱）へ
  s.rect(25, 12, 2, 1);
  s.rect(27, 9, 5, 5);
  s.put(29, 10, 'G').put(27, 11, 'S');
  s.put(29, 14, 'o');
  s.rect(27, 15, 5, 3);
  s.puts([[26, 16], [30, 18]], 'i');
  // 西の 道の 南西の 柱の 広間（宝箱）
  s.rect(0, 15, 3, 1);
  s.rect(-3, 16, 5, 6);
  s.puts([[-2, 17], [0, 17], [-2, 20], [0, 20]], 'O');
  // 根の とびらの おく: 北の 見晴らしの 広間（下りかいだんの へやの 北）
  s.puts([[13, 2], [14, 2]], '.');
  s.rect(9, -2, 10, 4);
  s.puts([[9, -2], [9, 1], [18, 1]], 'O');
  return s.rows();
}

// 5階「休み所と近道」: 大地の いずみ（回復と 記録）。東の へやの ゴーレム（東むき）を 重りの ゆかに のせると、
// こわれた 上り下りの ゆかが 直って 1階 ⇔ 5階の 近道に。北の へやの 根の かべの 前に ピピ（助けると 根が ほどけて 下りかいだんへ）
function f5() {
  const s = sheet(W, H, '#');
  s.rect(3, 10, 14, 7); // 休み所の 広間
  s.put(5, 17, '<');
  s.put(9, 11, 'F').put(3, 10, 'k').put(4, 10, 'k');
  s.rect(17, 12, 2, 1); // 東の へやへの 通路
  s.rect(19, 10, 7, 4); // 東の へや（上り下りの ゆか）
  s.put(20, 12, 'G').put(23, 12, 'P').put(24, 10, 'L').put(21, 10, 'S');
  s.rect(11, 8, 2, 2); // 北の へやへの 通路
  s.rect(8, 3, 8, 5); // 北の へや
  s.line(10, 3, 0, 1, 5, 'r');
  s.put(8, 4, '>');
  s.puts([[6, 9], [14, 9]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // 休み所の 西の 根の 庭・東の へやの 南の 物置（宝箱）・北の へやの 東の 見晴らし台
  s.put(2, 13, '.');
  s.rect(-3, 9, 5, 9);
  s.puts([[-3, 9], [1, 9], [-3, 17], [1, 17], [-1, 13]], 'R');
  s.put(22, 14, '.');
  s.rect(19, 15, 7, 5);
  s.puts([[19, 19], [25, 15]], 'k');
  s.put(16, 5, '.');
  s.rect(17, 1, 8, 6);
  s.puts([[18, 2], [23, 2], [18, 5], [23, 5]], 'O');
  return s.rows();
}

// 6階「根の道とゴーレム」: 西の 島の ゴーレム（東むき）を、根の 橋 a を わたらせて、根の すきま A から 下の 階へ 落とす（7階の 足場）。
// 水がめ1（3つとも 同じ 水がめ）で a が のびると A が ちぢむ
function f6() {
  const s = sheet(W, H, '~');
  s.rect(2, 7, 6, 7); // 西の 島
  s.put(4, 6, '<');
  s.put(6, 10, 'G').put(5, 8, 'S').put(3, 8, 'U').put(3, 13, '1');
  s.line(8, 10, 1, 0, 2, 'a');
  s.rect(10, 7, 5, 7); // まん中の 島
  s.put(12, 13, '1');
  s.line(15, 10, 1, 0, 2, 'A');
  s.rect(17, 7, 6, 7); // 東の 島（下りかいだん）
  s.put(20, 13, '1');
  s.put(21, 6, '>');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // まん中の 島の 水がめ2で 北の 根（b）が のびて、北の 島へ（宝箱）
  s.put(11, 7, '2');
  s.line(12, 4, 0, 1, 3, 'b');
  s.rect(9, 0, 8, 4);
  s.puts([[9, 0], [9, 3]], 'O');
  // まん中の 島の 南の 根の 広場・東の 島の 東の 台地（宝箱）
  s.rect(11, 14, 1, 2);
  s.rect(8, 16, 9, 4);
  s.puts([[8, 16], [16, 16], [8, 19], [16, 19]], 'O');
  s.rect(23, 13, 2, 1);
  s.rect(25, 11, 6, 5);
  return s.rows();
}

// 7階「大地のこどう」: ときどき 地面が ふるえて、数歩 歩くと 落石（立ち止まれば 当たらない。world/tremor.js）。
// 北の 大どうくつの 谷に、6階で 落とした ゴーレムが 足場に なっている（g）
function f7() {
  const s = sheet(W, H, '#');
  s.rect(2, 13, 6, 5); // はじめの へや
  s.put(4, 18, '<');
  s.rect(8, 15, 10, 1); // 長い 通路
  s.rect(17, 6, 1, 9);
  s.rect(9, 8, 5, 4).rect(14, 10, 3, 1); // わきの 小べや
  s.rect(12, 2, 8, 4); // 北の 大どうくつ（西）
  s.rect(20, 2, 1, 4, '~');
  s.put(20, 3, 'g');
  s.rect(21, 2, 5, 4); // 北の 大どうくつ（東。下りかいだん）
  s.put(24, 6, '>');
  s.puts([[2, 12], [7, 12]], 'i');
  // ── 第38回で ひろげた ところ（座標は もとの 階の 座標。マイナスや はばの 外も 使う）──
  // はじめの へやの 北: 古い 祭の 間を とおって、北の 大どうくつへ（もう 1つの 道。地面は ここでも ふるえる）
  s.rect(4, 6, 2, 7);
  s.rect(1, 1, 8, 5);
  s.puts([[2, 2], [7, 2], [2, 5]], 'O');
  s.rect(9, 3, 3, 1);
  // 長い 通路の 南の 柱の 広間・東の 通路の 東の 根の 物置（宝箱）
  s.put(12, 16, '.');
  s.rect(9, 17, 8, 5);
  s.puts([[9, 17], [16, 17], [9, 21], [16, 21]], 'O');
  s.rect(18, 12, 2, 1);
  s.rect(20, 9, 7, 6);
  s.puts([[20, 9], [20, 14], [26, 14]], 'R');
  return s.rows();
}

