// 'drop' … 根の すきまから 下の 階へ 落ちる / 'gap' … 谷へ 落ちる / 'wall' … 道の おわり
export function golemCellKind(n, i, has) {
  const G = EARTH_GOLEMS[n];
  const c = G.track[i];
  if (!c) return 'wall';
  if (c.ch === 'o') return has(G.done) ? 'floor' : 'pit';
