// maps/index.js の buildMaps から（ほかの マップが そろった あと・finishMap の 前）
export function attachFamilyQuests(maps) {
  Object.assign(maps, theaterMaps(), shopMap(), mineMaps());
  // 1. 劇場（王都サファラの 南西の すみ）: 日干しれんがの たてもの・赤い やね・かんばん
  const south = maps.south;
  stamp(south, THEATER.x, THEATER.y, THEATER.w, THEATER.h, T.ADOBE, 'red', THEATER_DOOR);
  south.tiles[(THEATER.y + 3) * south.w + THEATER.x + 2] = T.SIGN;
  south.signs.push({ x: THEATER.x + 2, y: THEATER.y + 3, text: '〜 サファラ劇場 〜\n歌とおどりの、楽しいおしばい。\n毎日、夕方から上演中！' });
  for (const d of THEATER_DOOR) south.warps.push({ x: d.x, y: d.y, to: { map: 'fq_th_lobby', x: TH_POS.lobbyIn.x, y: TH_POS.lobbyIn.y, dir: 'up' } });
  // 2. おみやげ屋（ユノハの 南）: 木の たてもの・雪の やね
  const north = maps.north;
  stamp(north, SOUVENIR.x, SOUVENIR.y, SOUVENIR.w, SOUVENIR.h, T.WALL_WOOD, 'snowred', [SOUVENIR_DOOR]);
  north.tiles[(SOUVENIR.y + 3) * north.w + SOUVENIR.x + 4] = T.SIGN;
  north.signs.push({ x: SOUVENIR.x + 4, y: SOUVENIR.y + 3, text: '〜 おみやげ　ゆきえ 〜\n（字がかすれて、ほとんど読めない…）' });
  north.warps.push({ x: SOUVENIR_DOOR.x, y: SOUVENIR_DOOR.y, to: { map: 'fq_shop', x: 6, y: 5.2, dir: 'up' } });
  // 5. 古い 鉱山の 入り口（カナトコの 北の かべ。第1部クリアで 板が 外れて 入れる）
  north.tiles[OLD_MINE_DOOR.y * north.w + OLD_MINE_DOOR.x] = T.MINE_BEAM;
  north.gates.push({ x: OLD_MINE_DOOR.x, y: OLD_MINE_DOOR.y, closed: T.MINE_BEAM, open: T.CAVE_ENTRANCE, flag: FQ.railStart });
  delete north.gateAt;
  north.warps.push({ x: OLD_MINE_DOOR.x, y: OLD_MINE_DOOR.y, to: { map: 'fq_old_mine', x: 4.5, y: 12.4, dir: 'up' } });
  // 町の 人・物
  for (const [id, name, sprite, script, mid, base, dx, dy, o] of TOWN_NPCS) {
    const m = maps[mid];
    const { fixed, ...opts } = o;
    // fixed … その いちに 置く（町の 外・ならぶ 人）。ほかは ちかくの あいた ゆかを さがす
    const [x, y] = fixed ? [base.x + dx, base.y + dy] : openSpot(m, base.x + dx, base.y + dy);
    m.npcs.push(npc(id, name, [x, y], sprite, script, { dir: 'down', ...opts }));
  }
  // 6〜11（第41回）
  attachWorkQuests(maps);
  return maps;
}

// 外の いち（クエストの 画面・テスト）
export function familySpot(maps, id) {
  for (const m of Object.values(maps)) {
    const n = m.npcs?.find((x) => x.id === id);
    if (n) return { map: m.id, x: Math.floor(n.x), y: Math.floor(n.y) };
  }
  return null;
}

// その マスに 立てるか（町の 中の あいた ゆか。テスト）
export function walkable(m, x, y) {
  return !(TILE_INFO[m.tiles[y * m.w + x]]?.solid ?? true);
}

js/shared/maps/flow.js:
// 流れる 砂の きまり（第4章 Step 4・王家のピラミッド 3階の ありじごく）
// client/field.js の 流される うごきと おなじ。テストと しかけ作りで つかう
//  ・流れる 砂（TILE_INFO の flow）に のると、その マスの むきへ 1マスずつ 流される（流されて いる あいだは 歩けない）
//  ・流れの 先も 流れる 砂なら、その マスの むきへ（曲がる 流れも ある）
//  ・流れる 砂では ない ゆかに 着いたら とまる。流れの 先が かべなら、その マスで とまる（そこからは 歩ける）
//  ・ありじごく（ワープの マス）に 流れこむと、下の 階へ おちる
import { TILE_INFO } from '../tiles.js';
import { effectiveTile, isBlocked } from './index.js';

const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];

// (x, y) の 流れの むき（[dx, dy]。流れる 砂で なければ null）
export function flowAt(map, x, y, has) {
  if (x < 0 || y < 0 || x >= map.w || y >= map.h) return null;
  return TILE_INFO[effectiveTile(map, x, y, has)]?.flow || null;
}

const warpAt = (map, x, y) => !!map.warpAt?.get(y * map.w + x) || !!map.warps?.some((w) => w.x === x && w.y === y);

// (x, y) に 立った ときに 流される 先: { x, y, pit, path }（path … とおる マス。pit … ワープ（ありじごく）に おちる）
export function carry(map, x, y, has) {
  const path = [[x, y]];
  let cx = x, cy = y;
  const seen = new Set([`${x},${y}`]);
  for (let guard = 0; guard < 400; guard++) {
    if (warpAt(map, cx, cy)) return { x: cx, y: cy, pit: true, path };
    const d = flowAt(map, cx, cy, has);
    if (!d) break;
    const nx = cx + d[0], ny = cy + d[1];
    if (isBlocked(map, nx, ny, has)) break;
    cx = nx;
    cy = ny;
    const k = `${cx},${cy}`;
    // 流れが ぐるっと まわる ときは そこで とまる（マップの まちがい。テストで 見つける）
    if (seen.has(k)) return { x: cx, y: cy, pit: false, path, loop: true };
    seen.add(k);
    path.push([cx, cy]);
  }
  return { x: cx, y: cy, pit: warpAt(map, cx, cy), path };
}

// 歩いて・流されて 行ける ところ: { stops: Set('x,y'), pits: Set('x,y') }
// stops … 立ちどまれる マス（流れる 砂の 上は、流れの 先が かべの とき だけ）
export function flowReach(map, start, has) {
  const stops = new Set();
  const pits = new Set();
  const q = [];
  const add = (x, y) => {
    const r = carry(map, x, y, has);
    const k = `${r.x},${r.y}`;
    if (r.pit) { pits.add(k); return; }
    if (stops.has(k)) return;
    stops.add(k);
    q.push([r.x, r.y]);
  };
  // 第71回: 階だんで ついた ところ（出入り口の 上に 立っている）からは そのまま 歩きだせる（world/stairs.js）
  if (warpAt(map, start[0], start[1])) {
    stops.add(`${start[0]},${start[1]}`);
    q.push([start[0], start[1]]);
  } else add(start[0], start[1]);
  for (let head = 0; head < q.length; head++) {
    const [x, y] = q[head];
    for (const [dx, dy] of DIRS) {
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h || isBlocked(map, nx, ny, has)) continue;
      add(nx, ny);
    }
  }
  return { stops, pits };
}

// start から goal まで 行けるか（流されて とまる ところを つたって）
export function flowCanReach(map, start, goal, has) {
  return flowReach(map, start, has).stops.has(`${goal[0]},${goal[1]}`);
}

