  // 第67回 A班: モンスター闘技場（maps/monarena-a.js。千年前の マップには 出さない ので attachCh6 の あと）
  attachMonArena(maps);
  // 夜の 町・村（夜だけ 出る 人・夜は 家に 帰る 人）
  addNightNpcs(maps);
  for (const m of Object.values(maps)) finishMap(m);
  return maps;
}

function finishMap(m) {
  m.npcById = Object.fromEntries(m.npcs.map((n) => [n.id, n]));
  m.chestAt = new Map(m.chests.map((c) => [c.y * m.w + c.x, c]));
  m.signAt = new Map((m.signs || []).map((s) => [s.y * m.w + s.x, s]));
  m.warpAt = new Map(m.warps.map((w) => [w.y * m.w + w.x, w]));
  // しらべると だいほんが はじまる マス（レバー・かがり火・温泉 など。第3章）
  m.actionAt = new Map((m.actions || []).map((a) => [a.y * m.w + a.x, a]));
}

// 宝の洞窟（'tm_…'）と ひみつのダンジョンの 階（'sd_<階>'）は はじめて さわった ときに ID から つくる
// （maps/treasure-cave.js・maps/secret-dungeon.js）。
// Object.values(MAPS) には 出さない。たくさん たまったら 古い ものから わすれる（また おなじ 形に つくれる）
const lazyIds = [];
function lazyMap(t, k) {
  if (typeof k !== 'string' || !(k.startsWith('tm_') || k.startsWith('sd_')) || Object.prototype.hasOwnProperty.call(t, k)) return;
  const m = k.startsWith('tm_') ? buildTreasureFloor(k) : buildSecretFloor(k);
  if (!m) return;
  finishMap(m);
  Object.defineProperty(t, k, { value: m, enumerable: false, configurable: true, writable: true });
  lazyIds.push(k);
  if (lazyIds.length > 160) delete t[lazyIds.shift()];
}
export const MAPS = new Proxy(buildMaps(), {
  get(t, k, r) { lazyMap(t, k); return Reflect.get(t, k, r); },
  has(t, k) { lazyMap(t, k); return Reflect.has(t, k); },
  getOwnPropertyDescriptor(t, k) { lazyMap(t, k); return Reflect.getOwnPropertyDescriptor(t, k); },
});

// ───────────── べんりな かんすう ─────────────
export function tileAt(map, x, y) {
  if (x < 0 || y < 0 || x >= map.w || y >= map.h) return T.VOID;
  return map.tiles[y * map.w + x];
}

// フラグで かわる タイル（こわれた橋・カギの とびら）
// invert: フラグが たつと しまる（レバーで ようがんの 流れを かえる など。第3章）
export function effectiveTile(map, x, y, hasFlag) {
  const t = tileAt(map, x, y);
  if (map.gateAt === undefined) map.gateAt = new Map(map.gates.map((g) => [g.y * map.w + g.x, g]));
  const g = map.gateAt.get(y * map.w + x);
  // levels: [[フラグ, タイル], …] … さいしょに たっている フラグの タイル。どれも なければ closed（第4章 Step 7 の 水の 高さ。3つ いじょうの すがた）
  if (g?.levels) {
    for (const [f, tile] of g.levels) if (hasFlag(f)) return tile;
    return g.closed;
  }
  if (g && (g.invert ? !hasFlag(g.flag) : hasFlag(g.flag))) return g.open;
  return g?.invert ? g.closed : t;
}

// すべる 氷の マスか（client/field.js）
export function slidesAt(map, x, y, hasFlag) {
  return !!TILE_INFO[effectiveTile(map, Math.floor(x), Math.floor(y), hasFlag)]?.slide;
}

// 船で すすめる タイル（水・第4章の 砂の海。sail の ある タイル）
const sailTile = (t) => t === T.WATER || t === T.DEEP || !!TILE_INFO[t]?.sail;

export function isBlocked(map, x, y, hasFlag) {
  const t = effectiveTile(map, x, y, hasFlag);
  // 海の マップでは 船で 水の 上を すすめる（第4章の 砂の海は すなかぜ号で 砂の 上を）
  if (map.sailable && sailTile(t)) return false;
  if (TILE_INFO[t]?.solid ?? true) return true;
  return false;
}

// 船に のっている（海の マップで 水の 上に いる。砂の海の 上も）
export function onWater(map, x, y, hasFlag) {
  if (!map.sailable) return false;
  const t = effectiveTile(map, Math.floor(x), Math.floor(y), hasFlag);
  return sailTile(t);
}

// NPCや たからばこの 表示じょうけん
export function condOk(show, hasFlag) {
  if (!show) return true;
  if (show.all && !show.all.every(hasFlag)) return false;
  if (show.not && show.not.some(hasFlag)) return false;
  return true;
}

// 人の 体の 大きさ（足もとが (x, y)。client/field.js の あたり判定と おなじ）
export const BODY = { hw: 0.28, top: 0.3, bot: 0.08 };
export function bodyPoints(x, y) {
  const { hw, top, bot } = BODY;
  return [[x - hw, y - top], [x + hw, y - top], [x - hw, y + bot], [x + hw, y + bot]];
}

// (cx, cy) に いる NPC が (tx, ty) の マスを ふさぐか（大きな 人は 横3マス・たて2マス）
export function npcCovers(n, cx, cy, tx, ty) {
  if (n.big) return Math.abs(tx + 0.5 - cx) < 1.5 && ty <= Math.floor(cy) && ty >= Math.floor(cy) - 1;
  return Math.floor(cx) === tx && Math.floor(cy) === ty;
}

// (x, y) に 立てるか: 体が かべ・人・宝箱に かからず、ワープの 上でも ない（人は 家の いちで みる）
export function canStand(map, x, y, hasFlag) {
  for (const [px, py] of bodyPoints(x, y)) {
    const tx = Math.floor(px), ty = Math.floor(py);
    if (isBlocked(map, tx, ty, hasFlag)) return false;
    const ch = map.chestAt?.get(ty * map.w + tx);
    if (ch && condOk(ch.show, hasFlag)) return false;
    for (const n of map.npcs) {
      if (n.solid && condOk(n.show, hasFlag) && npcCovers(n, n.x + 0.5, n.y + 0.5, tx, ty)) return false;
    }
  }
  return !map.warpAt?.has(Math.floor(y) * map.w + Math.floor(x));
}

// (x, y) の ちかくで 立てる ところ（そのままで よければ そのまま。だめなら いちばん ちかい マスの まん中。
// 下 → 左 → 右 → 上 の じゅんに さがす）。全滅して 教会で 目を覚ます とき、教会の 人と 重ならないように
export function standSpot(map, x, y, hasFlag, limit = 900) {
  if (canStand(map, x, y, hasFlag)) return { x, y };
  const sx = Math.floor(x), sy = Math.floor(y);
  // かべの 中から さがす とき いがいは、かべを こえない（おなじ へやの 中で さがす）
  const inWall = isBlocked(map, sx, sy, hasFlag);
  const seen = new Set([sy * map.w + sx]);
  const q = [[sx, sy]];
  for (let head = 0; head < q.length && head < limit; head++) {
    const [cx, cy] = q[head];
    if (canStand(map, cx + 0.5, cy + 0.5, hasFlag)) return { x: cx + 0.5, y: cy + 0.5 };
    for (const [dx, dy] of [[0, 1], [-1, 0], [1, 0], [0, -1]]) {
      const nx = cx + dx, ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h) continue;
      const k = ny * map.w + nx;
      if (seen.has(k)) continue;
      seen.add(k);
      if (!inWall && isBlocked(map, nx, ny, hasFlag)) continue;
      q.push([nx, ny]);
    }
  }
  return { x, y };
}

export function searchLoot(mapId, x, y) {
  // つぼ・たる・たな などを しらべた ときに でる もの（ばしょで きまる）
  const r = hash2(x, y, mapId.length * 31);
  if (r < 0.28) return { item: 'herb' };
  if (r < 0.40) return { item: 'antidote' };
  if (r < 0.50) return { item: 'star_shard' };
  if (r < 0.58) return { gold: 5 + Math.floor(hash2(x, y, 9) * 20) };
  if (r < 0.62) return { item: 'moonherb' };
  if (r < 0.64) return { item: 'magic_water' };
  // ふしぎなかじの 素材（町・どうくつ・海で ちがう）
  if (r < 0.74) {
    const mats = ch3SearchMats(mapId) || ch4SearchMats(mapId) || (mapId === 'sea' ? ['pretty_shell', 'wind_feather', 'iron_shard'] : mapId.startsWith('cave') ? ['iron_shard', 'magic_powder'] : ['beast_fang', 'iron_shard', 'magic_powder']);
    return { item: mats[Math.floor(hash2(x, y, 17) * mats.length)] };
  }
  return null;
}

export function sparkleLoot(zone, roll) {
  const tables = {
    outskirts: [['herb', 5], ['antidote', 2], ['star_shard', 3]],
    plains: [['herb', 4], ['antidote', 2], ['star_shard', 3], ['moonherb', 1]],
    forest: [['herb', 3], ['moonherb', 2], ['star_shard', 3]],
    swamp: [['antidote', 4], ['star_shard', 3]],
    east: [['herb', 3], ['star_shard', 4], ['magic_water', 0.6]],
  };
  const t = tables[zone] || NORTH_SPARKLE_LOOT[zone] || SOUTH_SPARKLE_LOOT[zone] || tables.plains;
  const total = t.reduce((s, e) => s + e[1], 0);
  let r = roll * total;
  for (const [id, w] of t) {
    r -= w;
    if (r < 0) return id;
  }
  return t[0][0];
}

export { PLACES, SEA_PLACES, zoneAt, areaName, OW_W, OW_H };

