// 第5章 Step 5「ノクトの思い出の迷宮」の レイアウト（1文字 = 1マス。文字の いみは maps/memory.js の MEMORY_LEGEND）
// 6階。1つの 階が 1つの 思い出の 年（5さい・7さい・9さい・11さい・13さい・今）。下へ 下へ（> … 下の 階へ / < … 上の 階へ）
// #=思い出の かべ .=ゆか ~=思い出の とぎれた ところ（もや。歩けない）O=思い出の 柱（ランプの 光で 影が のびる）
// 1〜4=ランプ台（しらべると 星読みの ランプの 光を うつす。光る ランプ台は 1つの 階に 1つだけ）
// a〜d=影の 道（ランプ台 1〜4 が 光っている ときだけ 見える・歩ける）A〜D=ゆかに おちた 影（ランプ台 1〜4 が 光っている とき）
// S=思い出の かけら X=思い出の 出口（1階。星読みの 里へ）F=休み所の 星の いずみ（3階）
// 影の 道は、ランプ台から 見て 柱の うしろへ まっすぐ のびる（柱の 向こうがわに だけ できる）
// 第38回 A: どの 階も 東や 南・北に わき道・行き止まりの 宝の へや・思い出の 広場を たして 広くした（34×18〜34×20）。
//   前からの へや・ランプ台・柱・影の 道・かいだんの 場所（ざひょう）は そのまま（マップの 東と 南を のばした）。
//   3階の 休み所に、しなくても よい 2つ目の ランプ台（南の 雪の 広場への 影の 道）

function sheet(w, h) {
  const g = Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (x === 0 || y === 0 || x === w - 1 || y === h - 1 ? '#' : '~')));
  const ok = (x, y) => x > 0 && y > 0 && x < w - 1 && y < h - 1;
  const api = {
    rect(x, y, rw, rh, ch = '.') { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) if (ok(i, j)) g[j][i] = ch; return api; },
    put(x, y, ch) { if (x >= 0 && y >= 0 && x < w && y < h) g[y][x] = ch; return api; },
    puts(list, ch) { for (const [x, y] of list) api.put(x, y, ch); return api; },
    // (x, y) から dx, dy の 向きへ n マス
    line(x, y, dx, dy, n, ch) { for (let i = 0; i < n; i++) api.put(x + dx * i, y + dy * i, ch); return api; },
    rows() { return g.map((r) => r.join('')); },
  };
  return api;
}
// もとの 大きさは 26×18。第38回 A で 東へ 34 まで（南へ 20 まで）のばした
const W = 34, H = 18, H2 = 20;

// 1階「5さい 星祭りの夜」: はじめての 影の 道。ランプ台1 → 柱の 影が 北へ のびて 下りかいだんの へやへ。
// ランプ台2 → 東へ のびて 思い出の かけらの へやへ（かけらを 取ると、その 影の 道は 消えなくなる）
// わき道: 北の へやの 東に つづきの へや・かけらの へやの 東に 星祭りの 広場
function f1() {
  const s = sheet(W, H);
  s.rect(4, 11, 12, 4); // はじめの へや
  s.rect(9, 15, 2, 2); // 出口への 通路
  s.puts([[9, 17], [10, 17]], 'X');
  s.rect(4, 2, 9, 4); // 北の へや（下りかいだん）
  s.put(8, 3, '>');
  s.put(7, 12, 'O').put(7, 14, '1').put(7, 11, 'A').line(7, 10, 0, -1, 5, 'a');
  s.put(14, 12, 'O').put(12, 12, '2').put(15, 12, 'B').line(16, 12, 1, 0, 4, 'b');
  s.rect(20, 10, 4, 5); // 東の へや（かけら）
  s.put(22, 12, 'S');
  s.rect(13, 2, 8, 4); // 北の へやの 東の つづき
  s.put(16, 3, 'O');
  s.put(24, 12, '.').rect(25, 9, 7, 7); // かけらの へや → 星祭りの 広場
  s.puts([[27, 11], [29, 13]], 'O');
  return s.rows();
}

// 2階「7さい ひとりで見上げた星」: 影の 道を 2本 つないで 進む。
// はじめの へや（ランプ台1）→ まん中の へや（ランプ台2で 北へ・ランプ台4で 東の かけらの へやへ）→ 北の へや（下りかいだん。ランプ台3で 西の へやへ もどれる）
// わき道: 北の へやの 東に つづきの へや・かけらの 小べやの 東に 東の へや・まん中の へやの 南に 南の へや
function f2() {
  const s = sheet(W, H2);
  s.rect(2, 12, 8, 4); // はじめの へや
  s.put(5, 16, '<');
  s.put(8, 13, 'O').put(6, 13, '1').put(9, 13, 'A').line(10, 13, 1, 0, 4, 'a');
  s.rect(14, 11, 7, 5); // まん中の へや
  s.put(15, 12, 'O').put(15, 14, '2').put(15, 11, 'B').line(15, 10, 0, -1, 4, 'b');
  s.put(19, 13, 'O').put(17, 13, '4').put(20, 13, 'D').line(21, 13, 1, 0, 2, 'd');
  s.rect(23, 12, 2, 4); // 東の 小べや（かけら）
  s.put(24, 13, 'S');
  s.rect(13, 2, 8, 5); // 北の へや（下りかいだん）
  s.put(19, 3, '>');
  s.put(14, 4, 'O').put(16, 4, '3').put(13, 4, 'C').line(12, 4, -1, 0, 5, 'c');
  s.rect(2, 2, 6, 5); // 西の へや
  s.rect(2, 7, 2, 5); // 西の へや ⇔ はじめの へや
  s.rect(21, 2, 6, 5); // 北の へやの 東の つづき
  s.put(24, 5, 'O');
  s.put(25, 13, '.').rect(26, 10, 6, 7); // かけらの 小べや → 東の へや
  s.put(28, 12, 'O');
  s.put(17, 16, '.').rect(13, 17, 9, 2); // まん中の へや → 南の へや
  return s.rows();
}

// 3階「9さい 雪の夜」: 休み所（星の いずみ・魔物は 出ない）。かけらは ランプ台1の 影の 道の 先
// わき道: ランプ台2（しなくても よい）→ 柱の 影が 南へ のびて 雪の 広場へ。かけらの 小べやの 東に 東の へや
function f3() {
  const s = sheet(W, H2);
  s.rect(3, 3, 15, 10);
  s.put(5, 2, '<');
  s.put(10, 5, 'F');
  s.put(16, 11, '>');
  s.put(16, 7, 'O').put(14, 7, '1').put(17, 7, 'A').line(18, 7, 1, 0, 3, 'a');
  s.rect(21, 5, 3, 5); // 東の 小べや（かけら）
  s.put(22, 7, 'S');
  s.puts([[6, 9], [13, 4]], 'O');
  s.put(9, 11, 'O').put(9, 10, '2').put(9, 12, 'B').line(9, 13, 0, 1, 3, 'b');
  s.rect(3, 16, 15, 3); // 雪の 広場
  s.puts([[5, 17], [14, 17]], 'O');
  s.put(24, 7, '.').rect(25, 4, 6, 7); // かけらの 小べや → 東の へや
  return s.rows();
}

// 4階「11さい 暗い声」: まん中の 台の 1本の 柱。ランプ台を かえると、影が 北・東・西へ 回る
// 南（ランプ台1）→ 影は 北の 島（かけら）/ 西（ランプ台2）→ 東の 島（下りかいだん）/ 東（ランプ台3）→ 西の 島
// わき道: 東の 島の 東・西の 島の 南・はじめの へやの 東に つづきの へや
function f4() {
  const s = sheet(W, H);
  s.rect(9, 13, 8, 4); // はじめの へや
  s.put(12, 16, '<');
  s.rect(11, 11, 1, 2); // はじめの へや ⇔ まん中の 台
  s.rect(9, 6, 7, 5); // まん中の 台
  s.put(12, 8, 'O');
  s.put(12, 10, '1').puts([[12, 7], [12, 6]], 'A').line(12, 5, 0, -1, 3, 'a');
  s.put(10, 8, '2').puts([[13, 8], [15, 8]], 'B').line(16, 8, 1, 0, 4, 'b');
  s.put(14, 8, '3').puts([[11, 8], [9, 8]], 'C').line(8, 8, -1, 0, 4, 'c');
  s.rect(9, 1, 7, 2); // 北の 島（かけら）
  s.put(12, 1, 'S');
  s.rect(20, 6, 4, 5); // 東の 島（下りかいだん）
  s.put(22, 8, '>');
  s.rect(1, 6, 4, 5); // 西の 島
  s.rect(24, 5, 7, 7); // 東の 島の 東
  s.put(27, 8, 'O');
  s.rect(1, 11, 4, 5); // 西の 島の 南
  s.rect(17, 13, 6, 4); // はじめの へやの 東
  return s.rows();
}

// 5階「13さい 雲の上の町」: 2つ目の へやの 3つの ランプ台。南（下りかいだん）・東（かけら）・西（はじめの へやへ もどる）
// わき道: かけらの 小べやの 東に 見晴らし台・南の へやの 西に つづきの へや
function f5() {
  const s = sheet(W, H2);
  s.rect(2, 2, 6, 5); // はじめの へや
  s.put(4, 1, '<');
  s.put(6, 4, 'O').put(4, 4, '1').put(7, 4, 'A').line(8, 4, 1, 0, 4, 'a');
  s.rect(12, 2, 7, 7); // 2つ目の へや
  s.put(13, 7, 'O').put(13, 5, '2').put(13, 8, 'B').line(13, 9, 0, 1, 4, 'b');
  s.put(17, 5, 'O').put(15, 5, '3').put(18, 5, 'C').line(19, 5, 1, 0, 2, 'c');
  s.put(13, 3, 'O').put(15, 3, '4').put(12, 3, 'D').line(11, 3, -1, 0, 4, 'd');
  s.rect(21, 3, 3, 5); // 東の 小べや（かけら）
  s.put(22, 5, 'S');
  s.rect(12, 13, 6, 3); // 南の へや（下りかいだん）
  s.put(16, 14, '>');
  s.put(24, 5, '.').rect(25, 2, 7, 8); // かけらの 小べや → 見晴らし台
  s.puts([[27, 4], [29, 7]], 'O');
  s.rect(4, 14, 8, 4); // 南の へやの 西
  return s.rows();
}

// 6階「今 星祭りの夜、ふたたび」: 影の 道の 先の 大広間で、ノクトの 影が 待っている。北の 小べやに かけら
// わき道: 北の 小べやの 上・はじめの へやの 南に 小べや。大広間の 東に 東の へや（ノクトの 影の あと）
function f6() {
  const s = sheet(W, H2);
  s.rect(2, 12, 6, 4); // はじめの へや
  s.put(4, 16, '<');
  s.put(6, 14, 'O').put(4, 14, '1').put(7, 14, 'A').line(8, 14, 1, 0, 4, 'a');
  s.put(3, 13, 'O').put(3, 15, '2').put(3, 12, 'B').line(3, 11, 0, -1, 4, 'b');
  s.rect(2, 4, 5, 4); // 北の 小べや（かけら）
  s.put(4, 5, 'S');
  s.rect(12, 3, 12, 13); // 大広間
  s.puts([[15, 5], [21, 5], [15, 12], [21, 12]], 'O');
  s.rect(2, 1, 8, 3); // 北の 小べやの 上
  s.put(7, 16, '.').rect(5, 17, 6, 2); // はじめの へや → 南の 小べや
  s.put(24, 9, '.').rect(25, 4, 7, 11); // 大広間 → 東の へや
  s.puts([[27, 6], [29, 12]], 'O');
  return s.rows();
}

export const MEMORY_ROWS = { 1: f1(), 2: f2(), 3: f3(), 4: f4(), 5: f5(), 6: f6() };
// ランプ台の 影の 道の うち、思い出の かけらを 取ると 消えなく なる もの（かけらの へやから 帰れる ように）
export const MEMORY_KEEP = { 1: ['b'], 2: ['d'], 3: ['a'], 4: ['a'], 5: ['c'], 6: ['b'] };

