// 第5章 Step 4「しずみゆく島の古い神殿」の レイアウト（1文字 = 1マス。文字の いみは maps/sink-ruin.js の RUIN_LEGEND）
// 1階が いちばん 上。下の 階へ 下りて いく（> … 下の 階へ / < … 上の 階へ）
// #=古い 石の かべ .=石の ゆか p=かたむいた 柱 i=たいまつ !=石の 文字ばん o=つぼ k=本だな G=かべ画 O=出口（外へ）
// かたむく ゆか: /=かたむく ゆか（かたむきの石で 西 ⇔ 東）L=かたむきの石 R=岩（西に かたむいている 時）r=岩が ころがって くる ところ（東に かたむいた 時）
//               ~=水たまり（西に かたむいている 時）w=水が 流れて くる ところ（東に かたむいた 時）
// 重さの てんびん: a・b=てんびんの 皿 q=岩が ころがって くる 皿（3階）Z=てんびんの 柱 |=てんびんの とびら
// c=入りこんだ 雲（強い 魔物・よい 宝）H=たて穴（2階。縄ばしごを かけると 5階へ）h=まるめた 縄ばしご（5階）
// F=休み所の 星の いずみ T=守り星の かけらの 台 g=島の 根
// 第38回 A: どの 階も 東や 南・北に わき道・行き止まりの 宝の へや・見晴らしの よい 広間を たして 広くした。
//   前からの へや・しかけ・かいだんの 場所（ざひょう）は そのまま（マップの 東と 南を のばした）。
//   4階の 休み所の 東に 小さな 重さの てんびんの 宝物庫（しなくても 先へ 行ける）

function sheet(w, h, fill = '#') {
  const g = Array.from({ length: h }, () => Array(w).fill(fill));
  const ok = (x, y) => x >= 0 && y >= 0 && x < w && y < h;
  const api = {
    w, h,
    rect(x, y, rw, rh, ch = '.') { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) if (ok(i, j)) g[j][i] = ch; return api; },
    put(x, y, ch) { if (ok(x, y)) g[y][x] = ch; return api; },
    puts(list, ch) { for (const [x, y] of list) api.put(x, y, ch); return api; },
    rows() { return g.map((r) => r.join('')); },
  };
  return api;
}

// 1階「神殿の入口」（41×22）: 南の 出口 → 大広間（北の かべに 大地の 守り星の かべ画・かたむいた 柱）→ 北東の 下りかいだん
// わき道: 大広間の 東に 東の 回廊（柱の 間から 雲の 海が 見える）・北西に 古い 祭だん・入口の 通路の 東に 小べや
function f1() {
  const s = sheet(41, 22);
  s.rect(4, 6, 22, 12); // 大広間
  s.rect(12, 18, 6, 3); // 入口の 通路
  s.puts([[14, 21], [15, 21]], 'O');
  s.puts([[11, 5], [12, 5], [13, 5], [14, 5]], 'G');
  s.rect(20, 2, 7, 4); // 北東の へや
  s.put(25, 2, '>');
  s.puts([[7, 9], [22, 9], [7, 14], [22, 14]], 'p');
  s.puts([[3, 8], [26, 8], [3, 14], [26, 14]], 'i');
  s.puts([[5, 16], [24, 7]], 'o');
  s.put(12, 19, '!');
  s.rect(26, 11, 2, 1).rect(28, 6, 11, 12); // 大広間 → 東の 回廊
  s.puts([[30, 8], [36, 8], [30, 15], [36, 15]], 'p');
  s.puts([[39, 8], [39, 12], [39, 16], [27, 7]], 'i');
  s.put(6, 5, '.').rect(3, 2, 7, 3); // 大広間 → 北西の 古い 祭だん
  s.puts([[2, 3], [10, 3]], 'i');
  s.puts([[5, 2], [7, 2]], 'k');
  s.put(18, 20, '.').rect(19, 19, 7, 2); // 入口の 通路 → 南東の 小べや
  s.put(25, 19, 'o');
  return s.rows();
}

// 2階「かたむく ゆか」（30×22）: 北西の へや → かたむく 大広間（かたむきの石）→ 西の 通路（岩）→ 下の へや（下りかいだん・たて穴）
// 西に かたむいている 時は 岩が 西の 通路を ふさぐ。東に かたむけると 岩は 東へ ころがって、東の 小べやの 入口を ふさぐ
// わき道（40×27）: 東の 小べやの 先に 古い 宝物庫（西に かたむいている 時だけ 行ける）・大広間の 北に 回廊・下の へやの 南に 小べや
function f2() {
  const s = sheet(40, 27);
  s.rect(2, 2, 5, 4); // 北西の へや
  s.put(3, 1, '<');
  s.rect(7, 3, 20, 10, '/'); // かたむく 大広間
  s.put(16, 4, 'L');
  s.puts([[12, 7], [21, 7]], 'p');
  s.rect(8, 13, 2, 5); // 西の 通路
  s.puts([[8, 13], [9, 13]], 'R');
  s.puts([[26, 7], [26, 8]], 'r');
  s.rect(27, 7, 2, 2); // 東の 小べや（宝箱）
  s.rect(4, 18, 17, 3); // 下の へや
  s.put(19, 20, '>');
  s.put(6, 19, 'H');
  s.put(5, 2, '!');
  s.puts([[1, 3], [27, 4]], 'i');
  s.put(20, 18, 'o');
  s.put(29, 7, '.').rect(30, 3, 9, 10); // 東の 小べや → 古い 宝物庫
  s.puts([[32, 5], [36, 5], [32, 10], [36, 10]], 'p');
  s.puts([[39, 6], [39, 10], [34, 2]], 'i');
  s.rect(12, 1, 9, 2); // 大広間の 北の 回廊（かたむかない ゆか）
  s.puts([[11, 1], [21, 1]], 'i');
  s.put(12, 21, '.').rect(6, 22, 12, 4); // 下の へや → 南の 小べや
  s.puts([[9, 23], [14, 23]], 'p');
  s.put(6, 22, 'o');
  return s.rows();
}

// 3階「重さの てんびん」（30×22）: 北西の へや → 大広間（てんびんの 2つの 皿・かたむきの石・岩）→ 南の とびら → 下の へや
// 東に かたむけると 岩が 左の 皿（q）に ころがる。右の 皿（b）に だれかが のると つりあって、南の とびらが 開く
// わき道（40×27）: 大広間の 北に 回廊・東に 東の へや。下の へや（とびらの 先）の 南に 南の へや
function f3() {
  const s = sheet(40, 27);
  s.rect(2, 2, 6, 4); // 北西の へや
  s.put(3, 1, '<');
  s.rect(4, 6, 22, 9); // 大広間
  s.rect(5, 10, 6, 1, '/'); // 岩の ころがる ゆか
  s.put(5, 10, 'R');
  s.put(10, 10, 'q');
  s.put(20, 10, 'b');
  s.put(15, 10, 'Z');
  s.put(15, 7, 'L');
  s.rect(2, 9, 2, 3); // 西の 小べや（宝箱）
  s.rect(15, 15, 2, 4); // 南の 通路
  s.puts([[15, 15], [16, 15]], '|');
  s.rect(10, 19, 12, 2); // 下の へや
  s.put(20, 20, '>');
  s.put(7, 6, '!');
  s.puts([[22, 7], [8, 13]], 'p');
  s.puts([[26, 8], [3, 7]], 'i');
  s.put(12, 5, '.').rect(10, 2, 13, 3); // 大広間 → 北の 回廊
  s.puts([[14, 3], [18, 3]], 'p');
  s.rect(26, 11, 2, 1).rect(28, 6, 10, 8); // 大広間 → 東の へや
  s.puts([[30, 8], [35, 11]], 'p');
  s.puts([[38, 8], [38, 12]], 'i');
  s.put(11, 21, '.').rect(9, 22, 10, 4); // 下の へや → 南の へや
  s.puts([[12, 23], [15, 23]], 'p');
  return s.rows();
}

// 4階「休み所」（41×24）: 北西の へや → 大広間の まん中に 星の いずみ（回復と 記録）・ハネビトの 古い 日記 → 南東の 下りかいだん
// わき道: 北に 雲見の 露台・南西に 小べや。東に てんびんの 間（a・b の 皿に 同時に 重さが のると、南の とびらの 先の 宝物庫が 開く。しなくても よい）
function f4() {
  const s = sheet(41, 24);
  s.rect(2, 2, 5, 3);
  s.put(3, 1, '<');
  s.rect(3, 5, 24, 14);
  s.put(15, 9, 'F');
  s.puts([[11, 6], [12, 6]], 'k');
  s.puts([[10, 8], [20, 8], [10, 12], [20, 12]], 'p');
  s.rect(22, 19, 4, 2);
  s.put(24, 20, '>');
  s.put(16, 13, '!');
  s.puts([[2, 9], [27, 9], [2, 15], [27, 15]], 'i');
  s.puts([[4, 6], [25, 6]], 'o');
  s.put(17, 4, '.').rect(8, 2, 18, 2); // 大広間 → 雲見の 露台
  s.puts([[7, 2], [26, 2]], 'i');
  s.rect(27, 11, 2, 1).rect(29, 6, 11, 8); // 大広間 → てんびんの 間
  s.put(31, 8, 'a').put(38, 8, 'b').put(34, 7, 'Z');
  s.puts([[30, 12], [38, 12]], 'p');
  s.puts([[34, 14], [35, 14]], '|').rect(32, 15, 6, 4); // てんびんの とびら → 宝物庫
  s.puts([[31, 16], [38, 16]], 'i');
  s.put(6, 19, '.').rect(3, 20, 9, 3); // 大広間 → 南西の 小べや
  s.put(10, 20, 'o');
  return s.rows();
}

// 5階「水の 流れる ゆかと 縄ばしご」（30×22）: 北の へや（かたむきの石）→ 西の 水路 → 南西の へや（下りかいだん）
//                                       → 東の 水路 → 南東の へや（まるめた 縄ばしご。2階への 近道）。南の へやには 雲が 入りこんでいる
// 西に かたむいている 時は 西の 水路が 水たまり。東に かたむけると 水が 東の 水路へ 流れる
// わき道（40×25）: 北の へやの 東に 北東の へや。南東の へやの 東に 雲の 小べや（東の 水路が かわいている 時だけ）。南西の へやの 南に 南の へや
function f5() {
  const s = sheet(40, 25);
  s.rect(2, 2, 26, 5); // 北の へや
  s.put(3, 1, '<');
  s.put(14, 3, 'L');
  s.rect(4, 7, 3, 8); // 西の 水路
  s.rect(4, 9, 3, 3, '~');
  s.rect(22, 7, 3, 8); // 東の 水路
  s.rect(22, 9, 3, 3, 'w');
  s.rect(2, 15, 10, 5); // 南西の へや
  s.put(3, 19, '>');
  s.rect(18, 15, 10, 5); // 南東の へや
  s.put(26, 16, 'h');
  // 雲（南の へやの 下の ほう）
  s.rect(5, 18, 7, 2, 'c');
  s.rect(18, 17, 10, 3, 'c');
  s.put(8, 2, '!');
  s.puts([[12, 4], [17, 4]], 'p');
  s.puts([[1, 4], [28, 4]], 'i');
  s.rect(28, 5, 2, 1).rect(30, 2, 9, 6); // 北の へや → 北東の へや
  s.puts([[32, 4], [36, 4]], 'p');
  s.put(28, 18, 'c').rect(29, 14, 8, 7, 'c'); // 南東の へや → 雲の 小べや
  s.put(6, 20, '.').rect(2, 21, 10, 3); // 南西の へや → 南の へや
  s.puts([[5, 22], [9, 22]], 'p');
  return s.rows();
}

// 6階「はなれた 重さの てんびん」（30×22）: 大広間の 西と 東の はしに 皿（19マス はなれている）。2つ 同時に のると 南の とびらが 開く
// 雲が 大広間の 下の ほうまで 入りこんでいる
// わき道（41×27）: 大広間の 東に 東の 回廊（とびらの 前）。南の へや（とびらの 先）の 下に 雲の 下の 広間
function f6() {
  const s = sheet(41, 27);
  s.rect(2, 2, 26, 13); // 大広間
  s.put(3, 1, '<');
  s.put(4, 9, 'a');
  s.put(25, 9, 'b');
  s.put(14, 8, 'Z');
  s.rect(2, 11, 9, 4, 'c');
  s.rect(19, 11, 9, 4, 'c');
  s.rect(14, 15, 2, 3); // 南の 通路
  s.puts([[14, 15], [15, 15]], '|');
  s.rect(6, 18, 18, 3, 'c'); // 南の へや（雲）
  s.rect(11, 18, 8, 2);
  s.put(14, 20, '>');
  s.put(6, 3, '!');
  s.puts([[9, 5], [20, 5]], 'p');
  s.puts([[1, 6], [28, 6]], 'i');
  s.rect(28, 8, 2, 1).rect(30, 2, 10, 12); // 大広間 → 東の 回廊
  s.rect(30, 10, 10, 4, 'c');
  s.puts([[32, 4], [37, 4], [32, 8], [37, 8]], 'p');
  s.puts([[8, 21], [21, 21]], 'c').rect(4, 22, 26, 4, 'c'); // 南の へや → 雲の 下の 広間
  s.puts([[10, 23], [17, 24], [24, 23]], 'p');
  return s.rows();
}

// 7階「島の 根の 間」（40×22）: 北の かいだん → 大広間（島を むしばむ 大ムカデ）→ 南の 小べやに 守り星の かけらの 台
// わき道: 北の 通路の 西と 東に 小べや（ガイアイーターの 前）。大広間の 東に 根の へや（雲。ガイアイーターの あと）
function f7() {
  const s = sheet(40, 22);
  s.rect(13, 2, 4, 5);
  s.put(14, 1, '<');
  s.rect(3, 7, 24, 12);
  s.rect(3, 7, 3, 12, 'c');
  s.rect(24, 7, 3, 12, 'c');
  s.rect(6, 17, 18, 2, 'c');
  s.rect(13, 19, 4, 2);
  s.put(14, 20, 'T');
  s.puts([[2, 9], [2, 12], [2, 15], [27, 10], [27, 13], [27, 16], [8, 19], [20, 19], [10, 6], [19, 6]], 'g');
  s.put(12, 4, '.').rect(3, 2, 9, 4); // 北の 通路 → 西の 小べや
  s.put(17, 4, '.').rect(18, 2, 9, 4); // 北の 通路 → 東の 小べや
  s.puts([[2, 3], [27, 3], [6, 1], [23, 1]], 'g');
  s.rect(27, 11, 2, 2).rect(29, 8, 10, 10, 'c'); // 大広間 → 東の 根の へや
  s.puts([[32, 7], [36, 7], [39, 10], [39, 14], [32, 18], [36, 18]], 'g');
  return s.rows();
}

export const RUIN_ROWS = { 1: f1(), 2: f2(), 3: f3(), 4: f4(), 5: f5(), 6: f6(), 7: f7() };

