const SIGNS = {
  1: [{ x: 12, y: 19, text: '石の文字ばんに、こう書いてある。\n「大地の守り星の神殿。\n島の根は、星の光で空にささえられている」' }],
  2: [{ x: 5, y: 2, text: '石の文字ばんに、こう書いてある。\n「かたむきの石をおせば、ゆかは東へ、また西へ。\n岩も水も、ひくい方へころがる」' }],
  3: [{ x: 7, y: 6, text: '石の文字ばんに、こう書いてある。\n「重さのてんびん。左右の皿がつりあえば、とびらは開く。\n岩でも、人でも、重さは重さ」' }],
  4: [{ x: 16, y: 13, text: '石の文字ばんに、こう書いてある。\n「ここは神殿の休み所。星のいずみで、つかれをいやせ」' }],
  5: [{ x: 8, y: 2, text: '石の文字ばんに、こう書いてある。\n「水はひくい方へ流れる。\n上へ行く道は、縄ばしごがつなぐ」' }],
  6: [{ x: 6, y: 3, text: '石の文字ばんに、こう書いてある。\n「はなれた2つの皿。ひとりでは、つりあわぬ。\n友の重さをかりよ」' }],
};

const toward = (p, map, dy, dir) => ({ map, x: p.x + 0.5, y: p.y + 0.5 + dy, dir });
// かいだんの となりの 歩ける マス（上 → 左 → 右 → 下の じゅん）
const WALK = new Set(['.', '/', 'c']);
function besideOf(n, p, dir) {
  const rows = RUIN_ROWS[n];
  for (const [dx, dy] of [[0, -1], [-1, 0], [1, 0], [0, 1]]) if (WALK.has(rows[p.y + dy]?.[p.x + dx])) return { map: ruinMapId(n), x: p.x + dx + 0.5, y: p.y + dy + 0.5, dir };
  return toward(p, ruinMapId(n), -1, dir);
}

function ruinMap(n) {
  const rows = RUIN_ROWS[n];
  const t = parseRows(rows, RUIN_LEGEND);
  const id = ruinMapId(n);
  const theme = ruinTheme(n);
  const m = {
    id, name: RUIN_NAMES[n], kind: 'dungeon', bgm: 'sink_ruin', dark: false, theme,
    sky3d: SKY3D[theme],
    w: t.w, h: t.h, tiles: t.tiles, gates: [],
    npcs: [], chests: ruinChests(n), signs: SIGNS[n] || [], warps: [], triggers: [], actions: [], sparkles: [], roofs: [], links: [],
    areaName: () => RUIN_NAMES[n],
    ruinFloor: n,
    zoneAt: zoneOf(n, t.tiles, t.w),
    spawnCounts: SPAWNS[n],
    // 形の 版と 着く 所（古い セーブで この 階の 中に いた 人を 移す 先。1階は 外からの 入口、ほかは 上からの かいだんの 下）
    layoutVer: RUIN_LAYOUT,
    layoutArrive: n === 1 ? { ...RUIN_OUT.inside, dir: 'up' } : { x: RUIN_POS[n].up.x + 0.5, y: RUIN_POS[n].up.y + 1.5, dir: 'down' },
  };
  for (const s of m.signs) m.tiles[s.y * m.w + s.x] = T.SIGN;
  const P = RUIN_POS[n];
  // かいだん: 上は 1つ 上の 階の 下りかいだんの 手前へ（1つ 下の 階の 上りかいだんの 下へ）
  if (P.up && n > 1) m.warps.push({ x: P.up.x, y: P.up.y, to: besideOf(n - 1, RUIN_POS[n - 1].down, 'up') });
  if (P.down) m.warps.push({ x: P.down.x, y: P.down.y, to: toward(RUIN_POS[n + 1].up, ruinMapId(n + 1), 1, 'down') });
  // 階に 入った ときの ことば（1回だけ。目標が かわる）
  const a = n === 1 ? { x: 12, y: 16, w: 6, h: 3 } : { x: P.up.x - 2, y: P.up.y + 1, w: 5, h: 2 };
  m.triggers.push({ id: `c5_rf${n}`, ...a, script: `c5_rf${n}`, show: { not: [RF(n)] } });
  return m;
}

// かたむく ゆか: 岩・水・ゆかの 絵が フラグで かわる。かたむきの石を しらべる
function addTilt(m, key) {
  const K = TILTS[key];
  for (const p of K.slope) {
    if (K.rocks.some((r) => r.x === p.x && r.y === p.y) || K.rolled.some((r) => r.x === p.x && r.y === p.y)) continue;
    m.gates.push({ x: p.x, y: p.y, closed: T.TILT_FLOOR_W, open: T.TILT_FLOOR_E, flag: K.flag });
  }
  const floorTile = (p) => (K.slope.some((s) => s.x === p.x && s.y === p.y) ? T.TILT_FLOOR_E : T.CAVE_FLOOR);
  for (const p of K.rocks) m.gates.push({ x: p.x, y: p.y, closed: T.BOULDER, open: floorTile(p), flag: K.flag });
  for (const p of K.rolled) {
    if (m.tiles[p.y * m.w + p.x] === T.SCALE_PAN) continue; // 3階の 皿は addScale
    m.gates.push({ x: p.x, y: p.y, closed: T.TILT_FLOOR_W, open: T.BOULDER, flag: K.flag });
  }
  for (const p of K.water) m.gates.push({ x: p.x, y: p.y, closed: T.CAVE_WATER, open: T.CAVE_FLOOR, flag: K.flag });
  for (const p of K.flowed) m.gates.push({ x: p.x, y: p.y, closed: T.CAVE_FLOOR, open: T.CAVE_WATER, flag: K.flag });
  m.gates.push({ x: K.lever.x, y: K.lever.y, closed: T.TILT_LEVER, open: T.TILT_LEVER_ON, flag: K.flag });
  m.actions.push({ x: K.lever.x, y: K.lever.y, script: `c5_tilt_${key}` });
}

// 重さの てんびん: 皿に のると しらべる（同じ マップの 家族も）。とびら・柱
function addScale(m, key) {
  const S = SCALES[key];
  // 左の 皿（3階は 岩が のる。つりあうと 下がった まま）
  if (S.rock) m.gates.push({ x: S.a.x, y: S.a.y, closed: T.SCALE_PAN, levels: [[S.rock, T.PAN_ROCK], [S.flag, T.SCALE_PAN_ON]] });
  else m.gates.push({ x: S.a.x, y: S.a.y, closed: T.SCALE_PAN, open: T.SCALE_PAN_ON, flag: S.flag });
  m.gates.push({ x: S.b.x, y: S.b.y, closed: T.SCALE_PAN, open: T.SCALE_PAN_ON, flag: S.flag });
  for (const p of S.door) {
    m.gates.push({ x: p.x, y: p.y, closed: T.SCALE_DOOR, open: T.CAVE_FLOOR, flag: S.flag });
    m.actions.push({ x: p.x, y: p.y, script: `c5_sdoor_${key}`, show: { not: [S.flag] } });
  }
  for (const p of [S.a, S.b]) m.triggers.push({ id: `c5_pan_${key}_${p.x}`, x: p.x, y: p.y, w: 1, h: 1, script: `c5_pan_${key}`, show: { not: [S.flag] } });
  m.actions.push({ x: S.beam.x, y: S.beam.y, script: `c5_beam_${key}` });
}

export function buildRuinMaps() {
  const maps = {};
  for (let n = 1; n <= RUIN_FLOORS; n++) {
    const m = ruinMap(n);
    maps[m.id] = m;
  }
  // 1階: 出口・かべ画
  const f1 = maps[ruinMapId(1)];
  for (const p of RUIN_POS[1].exit) f1.warps.push({ x: p.x, y: p.y, to: { map: 'kumoi', ...RUIN_OUT.outside, dir: 'down' } });
  f1.actions.push(...RUIN_POS[1].murals.map((p) => ({ x: p.x, y: p.y, script: 'c5_r_mural' })));
  f1.links.push({ x: RUIN_POS[1].exit[0].x, y: RUIN_POS[1].exit[0].y, to: 'kumoi' });
  // かたむく ゆか（2階・3階・5階）
  addTilt(maps[ruinMapId(2)], 'f2');
  addTilt(maps[ruinMapId(3)], 'f3');
  addTilt(maps[ruinMapId(5)], 'f5');
  // 重さの てんびん（3階・6階）
  addScale(maps[ruinMapId(3)], 'f3');
  addScale(maps[ruinMapId(6)], 'f6');
  addScale(maps[ruinMapId(4)], 'f4');
  // 縄ばしご（2階の たて穴 ⇔ 5階の まるめた 縄ばしご。5階で かけると つながる）
  const f2 = maps[ruinMapId(2)], f5 = maps[ruinMapId(5)];
  const H = RUIN_POS[2].shaft, C = RUIN_POS[5].coil;
  f2.gates.push({ x: H.x, y: H.y, closed: T.RUIN_SHAFT, open: T.ROPE_LADDER, flag: LADDER_FLAG });
  f2.warps.push({ x: H.x, y: H.y, to: { map: f5.id, x: RUIN_POS[5].ladderOut.x + 0.5, y: RUIN_POS[5].ladderOut.y + 0.5, dir: 'left' } });
  f2.actions.push({ x: H.x, y: H.y, script: 'c5_shaft', show: { not: [LADDER_FLAG] } });
  f5.gates.push({ x: C.x, y: C.y, closed: T.ROPE_COIL, open: T.ROPE_LADDER, flag: LADDER_FLAG });
  f5.warps.push({ x: C.x, y: C.y, to: { map: f2.id, x: RUIN_POS[2].ladderOut.x + 0.5, y: RUIN_POS[2].ladderOut.y + 0.5, dir: 'right' } });
  f5.actions.push({ x: C.x, y: C.y, script: 'c5_ladder', show: { not: [LADDER_FLAG] } });
  // 4階: 休み所の 星の いずみ・ハネビトの 古い 日記
  const f4 = maps[ruinMapId(4)];
  f4.actions.push({ ...RUIN_POS[4].font, script: 'c5_r_rest' });
  f4.actions.push(...RUIN_POS[4].books.map((p) => ({ x: p.x, y: p.y, script: 'c5_r_diary' })));
  // 7階: ガイアイーター・守り星の かけらの 台
  const f7 = maps[ruinMapId(7)], P7 = RUIN_POS[7];
  f7.npcs.push(npc('gaia_npc', 'ガイアイーター', [P7.gaia.x, P7.gaia.y], 'mon:gaia_eater', 'c5_gaia_event', { big: true, dir: 'up', show: { not: ['c5_gaia'] } }));
  f7.triggers.push({ id: 'c5_gaia', ...P7.trigger, script: 'c5_gaia_event', show: { not: ['c5_gaia'] } });
  f7.actions.push({ ...P7.altar, script: 'c5_r_altar' });
  return maps;
}

js/shared/maps/slide.js:
// 氷の しかけの きまり（client/field.js の すべる うごきと おなじ。テストと しかけ作りで つかう）
//  ・ふつうの ゆかから となりへ: 氷なら すべりだす / ゆかなら 1歩
//  ・氷の 上で とまっている ときは、むいた ほうへ すべる
//  ・すべると、つぎの マスが ふさがっているか、氷では ない ゆかに 着いたら とまる
import { isBlocked, slidesAt } from './index.js';

const DIRS = [[0, -1], [1, 0], [0, 1], [-1, 0]];

// ふさがっている マス（タイル・宝箱・人。extra … ほかに ふさぐ マスの Set('x,y')）
export function slideSolid(map, has, extra = null) {
  const npcs = new Set();
  for (const n of map.npcs || []) {
    if (!n.solid || (n.show && !condShow(n.show, has))) continue;
    npcs.add(`${Math.floor(n.x)},${Math.floor(n.y)}`);
  }
  return (x, y) => {
    if (x < 0 || y < 0 || x >= map.w || y >= map.h) return true;
    if (isBlocked(map, x, y, has)) return true;
    const ch = map.chestAt?.get(y * map.w + x);
    if (ch && (!ch.show || condShow(ch.show, has))) return true;
    const k = `${x},${y}`;
    return npcs.has(k) || !!extra?.has(k);
  };
}

function condShow(show, has) {
  if (show.all && !show.all.every(has)) return false;
  if (show.not && show.not.some(has)) return false;
  return true;
}

// (x, y) で とまっている とき、行ける ところ（とまる マス）の 一覧
export function slideMoves(map, x, y, has, solid = slideSolid(map, has)) {
  const ice = (tx, ty) => slidesAt(map, tx, ty, has);
  const out = [];
  for (const [dx, dy] of DIRS) {
    const nx = x + dx, ny = y + dy;
    if (solid(nx, ny)) continue;
    if (!ice(x, y) && !ice(nx, ny)) {
      out.push([nx, ny]);
      continue;
    }
    // すべる
    let cx = ice(x, y) ? x : nx, cy = ice(x, y) ? y : ny;
    if (!ice(x, y)) { /* 氷に のった */ }
    for (let guard = 0; guard < 400; guard++) {
      if (!ice(cx, cy)) break;
      if (solid(cx + dx, cy + dy)) break;
      cx += dx;
      cy += dy;
    }
    if (cx !== x || cy !== y) out.push([cx, cy]);
  }
  return out;
}

// start から 行ける とまる マス（Set of 'x,y'）
export function slideReach(map, start, has, solid = slideSolid(map, has)) {
  const seen = new Set([`${start[0]},${start[1]}`]);
  const q = [start];
  for (let head = 0; head < q.length; head++) {
    const [x, y] = q[head];
    for (const [nx, ny] of slideMoves(map, x, y, has, solid)) {
      const k = `${nx},${ny}`;
      if (seen.has(k)) continue;
      seen.add(k);
      q.push([nx, ny]);
    }
  }
  return seen;
}

// いちばん 少ない 手数（とどかなければ -1）。手数は 1歩・1すべり を 1回と かぞえる
export function slideSteps(map, start, goal, has, solid = slideSolid(map, has)) {
  const key = (p) => `${p[0]},${p[1]}`;
  const dist = new Map([[key(start), 0]]);
  const q = [start];
  for (let head = 0; head < q.length; head++) {
    const p = q[head];
    if (p[0] === goal[0] && p[1] === goal[1]) return dist.get(key(p));
    for (const n of slideMoves(map, p[0], p[1], has, solid)) {
      if (dist.has(key(n))) continue;
      dist.set(key(n), dist.get(key(p)) + 1);
      q.push(n);
    }
  }
  return -1;
}

// とじこめられる 場所（start から 行けるのに、start へ もどれない とまる マス）
export function slideTraps(map, start, has, solid = slideSolid(map, has)) {
  const reach = slideReach(map, start, has, solid);
  const traps = [];
  for (const k of reach) {
    const [x, y] = k.split(',').map(Number);
    if (!slideReach(map, [x, y], has, solid).has(`${start[0]},${start[1]}`)) traps.push([x, y]);
  }
  return traps;
}

js/shared/maps/south.js:
// 第4章の フィールド「コガネ地方」（南の 砂の国。map id 'south'）
// 毎回 おなじ 形に なるように、シード付きの ノイズで 砂丘・岩山を つくってから、村や 井戸を はめこむ。
//
// ・北の海辺 … 星の竜アステルが おりる ところ（砂嵐が おさまるまで、空は この 上だけ。data/sky.js）
// ・オアシスの村ハミル（西）… 北に 北の古井戸。南へ 行くと 砂嵐のかべ
// ・砂嵐のかべ（y=60〜63）… 王都の 方へは まだ 行けない（道の ところは c4_scorpion、ほかは c4_morgana で はれる）
// ・かべの 南: 王都サファラ（Step 3。道の つきあたり）
// ・王都の 東の 門の 先: 王家のピラミッドと オベリスク（Step 4。昼の 12時ごろ、オベリスクの 影が とびらを さす）
// ・王都の 南の 門の 先: 南の 砂嵐（Step 5。道の ところは 大臣ザイードを たおすと 弱まる）→ 南の砂ばく → 砂の港ドゥナへの 谷
//   （谷は 砂の海賊が 木の さくで とざしている。ドゥナの 町は Step 6 から）
import { T, TILE_INFO, parseRows } from '../tiles.js';
import { fbm, hash2 } from '../rng.js';
import { HAMIL_ROWS, SAFARA_ROWS } from './south-rows.js';

export const SOUTH_W = 144;
export const SOUTH_H = 144;

// 町・村（左上の マス）
export const SOUTH_PLACES = {
  hamil: { x: 16, y: 24, w: 30, h: 24, name: 'オアシスの村ハミル', bgm: 'oasis' },
  // 王都サファラ（Step 3）: 砂嵐の 切れ目から 南へ のびる 道の つきあたり（北の 門の まん中が 道の さき）
  safara: { x: 15, y: 84, w: 51, h: 40, name: '王都サファラ', bgm: 'safara' },
};
const HAM = SOUTH_PLACES.hamil;
const SAF = SOUTH_PLACES.safara;
// 王都の 中の 場所（町の 左上からの マス → フィールドの マス）
const SF = (x, y) => ({ x: SAF.x + x, y: SAF.y + y });
// 王都の 町の 文字（south-rows.js の SAFARA_ROWS。ほかは tiles.js の LEGEND）
export const SAFARA_LEGEND = { V: T.DRY_FOUNTAIN, '#': T.CANAL_WALL, '@': T.WELL_HOLE };
export const SAFARA_POS = {
  gate: SF(25, 0), // 北の 門（まん中）
  eastGate: SF(50, 13), // 東の 門（東の 砂ばくへ。Step 4 から）
  well: SF(13, 11), // 町の 井戸（東へ 行列）
  fountain: SF(25, 18), // 宮殿の 前の かれた ふん水（まん中）
  temple: SF(6, 15), // 水の神殿の とびら
  pedestal: SF(6, 25), // 水の神殿の 守り星の 台座（からっぽ。2マス）
  palaceDoor: SF(25, 22), // 宮殿の とびら（夜は しまる）
  throne: SF(25, 25), // 王の間の 玉座（北の かべを せにして 南を むく。入り口の ろうかから 左右の すきまを 通って 前へ）
  courtDoor: SF(25, 30), // 王の間 ⇔ 中庭の とびら（カギが かかっている）
  jar: SF(25, 33), // 中庭の 水がめ（夜に 本当の 女王が うつる）
  bench: SF(21, 35), // 中庭の ベンチ（女王の 絵日記）
  courtWell: SF(18, 33), // 中庭の 古井戸（地下水路へ）
  canal: SF(6, 32), // 宮殿の地下水路の 入り口（町の 南西。かいだん）
  hassan: SF(42, 16), // 学者ハサンの 家の とびら
  arena: SF(41, 24), // 闘技場の とびら
  arenaGate: SF(44, 33), // 闘技場の 門（大会は お休み。Step 8）
  southGate: SF(13, 39), // 南の 門（2マス。13・14。Step 5 から 南の 砂嵐の 切れ目へ）
};
// 王の間（宮殿の 中）と 中庭（王の間の うしろ。地下水路からしか 入れない）
export const PALACE_HALL = { x: SAF.x + 15, y: SAF.y + 22, w: 21, h: 9 };
export const PALACE_COURT = { x: SAF.x + 16, y: SAF.y + 31, w: 19, h: 8 };
// ───── 王家のピラミッド（Step 4）─────
// 王都の 東の 門から 道ぞいに 東へ。15×15 マスの 大きな ピラミッド（まん中ほど 高い。2.5D では だんだんの 山）
// 南の かべの まん中に 日時計の とびら、その 5マス 南に オベリスク。まえの 広場は 魔物が 出ない
export const PYRAMID = { x: 93, y: 81, w: 15, h: 15, name: '王家のピラミッド' };
export const PYRAMID_PLAZA = { x: 88, y: 96, w: 25, h: 9 };
export const PYRAMID_POS = {
  door: { x: 100, y: 95 }, // 日時計の とびら（c4_pyramid で 開く）
  obelisk: { x: 100, y: 100 }, // オベリスク（大きな 石の 柱。人の え は client/render/chars.js の obelisk）
};
// オベリスクの 影（お日さまの むきで のびる。昼の 12時ごろは 北へ のびて、とびらを さす）
//   '@am' … 西へ 5マス / '@noon' … 北へ 4マス（とびらの 前まで）/ '@pm' … 東へ 5マス
export const OBELISK_SHADOW = {
  '@am': [1, 2, 3, 4, 5].map((d) => ({ x: PYRAMID_POS.obelisk.x - d, y: PYRAMID_POS.obelisk.y })),
  '@noon': [1, 2, 3, 4].map((d) => ({ x: PYRAMID_POS.obelisk.x, y: PYRAMID_POS.obelisk.y - d })),
  '@pm': [1, 2, 3, 4, 5].map((d) => ({ x: PYRAMID_POS.obelisk.x + d, y: PYRAMID_POS.obelisk.y })),
};
// ピラミッドの マスの 高さ（ふちから 何だん目か。0〜7）
export function pyramidLevel(x, y) {
  const P = PYRAMID;
  return Math.max(0, Math.min(x - P.x, P.x + P.w - 1 - x, y - P.y, P.y + P.h - 1 - y));
}

// 竜が おりる 北の海辺（空を とべる 場所。data/sky.js の box）
export const SOUTH_LANDING = { x: 50, y: 2, w: 44, h: 16 };
// 大臣ザイードを たおした あと（Step 5）に 竜が 飛べる 所: 北の海辺から 王都サファラ・砂の港ドゥナの 近くまで
// （ピラミッドも ふくむ。東の はしの 星読みの塔の あたりは、モルガナを たおすまで 砂嵐。data/sky.js の box の 2だんめ）
export const SOUTH_SKY_ZAID = { x: 2, y: 2, w: 112, h: 139 };
export const SOUTH_ARRIVE = { x: 72.5, y: 9.5 };
export const LANDING_BEACH = { x: 56, y: 5, w: 32, h: 10, name: '北の海辺' };
// 小さな オアシス（北東。旅の 商人が 休んでいる）
export const OASIS2 = { x: 108, y: 30, r: 3.2 };
export const OASIS_CAMP = { x: 102, y: 25, w: 13, h: 11 };

// 出入り口・だいじな 場所
export const SOUTH_POS = {
  well: { x: 12, y: 12 }, // 北の古井戸（なわばしごで 下へ）
  canal: { x: 52, y: 52 }, // かれた地下水路（Step 2）
  tower: { x: 124, y: 46 }, // 星読みの塔（Step 8）
};

// 砂嵐のかべ（東西 ぜんぶ）。道の ところ（GAP）は よろい大サソリを たおすと 弱まる
export const STORM_Y = [60, 63];
export const STORM_GAP_X = [35, 38];
export const STORM_FLAG = 'c4_scorpion';
export const STORM_END_FLAG = 'c4_morgana';
// 日時計の とびらが 開いた（Step 4。物語の すすみぐあい CH4_STEPS の c4_pyramid）
export const PYRAMID_FLAG = 'c4_pyramid';
// 南の 砂嵐（Step 5。王都の 南の 東西 ぜんぶ）。道の ところ（SOUTH_STORM_GAP_X）は 大臣ザイードを たおすと（c4_zaid）弱まる。
// のこりは 北の かべと おなじく c4_morgana で 晴れる
export const SOUTH_STORM_Y = [126, 127];
export const SOUTH_STORM_GAP_X = [27, 30];
export const SOUTH_STORM_FLAG = 'c4_zaid';
// 砂の港ドゥナへの 谷（南の がけの きれめ。Step 5 では 砂の海賊が 木の さくで とざしている。ドゥナの 町は Step 6）
// DUNA_GATE … さくの 門（カギの かかった とびら）。DUNA_VALLEY … 谷の まわり（魔物が 出ない）
export const DUNA_GATE = { x: 37, y: 140 };
export const DUNA_VALLEY = { x: 32, y: 136, w: 11, h: 8, name: '砂の港ドゥナへの谷' };

// 道（ふみかためた 砂の 道）
const ROADS = [
  // 北の海辺 → 村の 東の 門
  [[72, 11], [70, 17], [62, 24], [52, 31], [HAM.x + HAM.w + 0.5, HAM.y + 10]],
  // 村の 北の 門 → 北の古井戸
  [[HAM.x + 15, HAM.y - 0.5], [HAM.x + 14, 18], [24, 14.5], [SOUTH_POS.well.x + 1, SOUTH_POS.well.y + 1.5]],
  // 村の 南の 門 → 砂嵐のかべ → 王都サファラの 北の 門（Step 3）
  [[HAM.x + 15, HAM.y + HAM.h], [33, 54], [36.5, 59], [36.5, 72], [40, 84]],
  // 北の海辺 → 小さな オアシス
  [[78, 12], [88, 18], [100, 26], [OASIS2.x - 3, OASIS2.y]],
  // 王都の 東の 門 → 東の 砂ばく → 王家のピラミッドの まえの 広場（Step 4）
  [[SAF.x + SAF.w - 0.5, SAF.y + 14], [74, 98], [84, 100.5], [91, 100.5]],
  // 王都の 南の 門 → 南の 砂嵐の 切れ目 → 南の砂ばく → 砂の港ドゥナへの 谷（Step 5。谷は 南の がけを けずって 地図の はしまで）
  [[SAF.x + 14, SAF.y + SAF.h - 0.5], [SAF.x + 14, 131.5], [DUNA_GATE.x + 0.5, 137], [DUNA_GATE.x + 0.5, SOUTH_H - 0.5]],
];

function distToSeg(px, py, ax, ay, bx, by) {
  const dx = bx - ax, dy = by - ay;
  const l2 = dx * dx + dy * dy || 1;
  let t = ((px - ax) * dx + (py - ay) * dy) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}
function distToPath(px, py, pts) {
  let d = Infinity;
  for (let i = 0; i < pts.length - 1; i++) d = Math.min(d, distToSeg(px, py, pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]));
  return d;
}
const inRect = (x, y, r, pad = 0) => x >= r.x - pad && y >= r.y - pad && x < r.x + r.w + pad && y < r.y + r.h + pad;
// 海の きし（この y より 上は 海）
export const shoreY = (x) => 3 + fbm(x * 0.07, 0.5, 801) * 2.6;
const oasis2D = (x, y) => Math.hypot(x + 0.5 - OASIS2.x, (y + 0.5 - OASIS2.y) * 1.25) / OASIS2.r + (fbm(x * 0.3, y * 0.3, 803) - 0.5) * 0.3;

export function buildSouth() {
  const W = SOUTH_W, H = SOUTH_H;
  const t = new Uint8Array(W * H).fill(T.DESERT);
  const set = (x, y, v) => { if (x >= 0 && y >= 0 && x < W && y < H) t[y * W + x] = v; };
  const get = (x, y) => (x >= 0 && y >= 0 && x < W && y < H ? t[y * W + x] : T.SANDSTONE);
  const nearPlace = (x, y, pad) => [HAM, SAF, LANDING_BEACH, OASIS_CAMP, PYRAMID, PYRAMID_PLAZA].some((p) => inRect(x, y, p, pad));
  const nearRoad = (x, y, d) => ROADS.some((r) => distToPath(x + 0.5, y + 0.5, r) < d);
  const nearPos = (x, y, p, d) => Math.hypot(x - p.x, y - p.y) < d;

  // 1) 海と 砂浜（北）・西と 東と 南の 砂岩の がけ
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const sh = shoreY(x);
      if (y < sh - 1.6) { set(x, y, T.DEEP); continue; }
      if (y < sh) { set(x, y, T.WATER); continue; }
      const west = 2.5 + fbm(1.3, y * 0.09, 805) * 3;
      const east = W - 3 - fbm(2.1, y * 0.09, 807) * 3;
      const south = H - 3 - fbm(x * 0.08, 0.7, 809) * 3;
      if (x < west || x > east || y > south) set(x, y, T.SANDSTONE);
      else if (y < sh + 2.2) set(x, y, T.SAND);
    }
  }

  // 2) 砂丘（こえられない 大きな 砂の 山。風で ながく のびる）と 岩山
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      if (get(x, y) !== T.DESERT) continue;
      if (nearPlace(x, y, 4) || nearRoad(x, y, 3.2) || y < shoreY(x) + 5) continue;
      if (nearPos(x, y, SOUTH_POS.well, 6) || nearPos(x, y, SOUTH_POS.canal, 6) || nearPos(x, y, SOUTH_POS.tower, 7)) continue;
      // ながい 砂丘の すじ（風は 西から 東へ）
      const n = fbm(x * 0.035 + y * 0.012, y * 0.11, 811);
      const ridge = 1 - Math.abs(n * 2 - 1);
      const patch = fbm(x * 0.05, y * 0.05, 813);
      if (ridge > 0.9 && patch > 0.38) set(x, y, T.DUNE);
      else if (fbm(x * 0.09, y * 0.09, 815) > 0.72 && hash2(x, y, 817) < 0.9) set(x, y, T.SANDSTONE);
      else if (hash2(x, y, 819) < 0.012) set(x, y, T.CACTUS);
    }
  }

  // 3) オアシスの まわりの 緑（村の まわり）と 小さな オアシス
  for (let y = HAM.y - 7; y < HAM.y + HAM.h + 7; y++) {
    for (let x = HAM.x - 7; x < HAM.x + HAM.w + 7; x++) {
      if (inRect(x, y, HAM)) continue;
      const cur = get(x, y);
      if (![T.DESERT, T.DUNE, T.CACTUS].includes(cur)) continue;
      const d = Math.max(HAM.x - x, x - (HAM.x + HAM.w - 1), HAM.y - y, y - (HAM.y + HAM.h - 1));
      const green = fbm(x * 0.2, y * 0.2, 821) + (5 - d) * 0.09;
      if (green > 0.62 && hash2(x, y, 823) < 0.13 && !nearRoad(x, y, 2)) set(x, y, T.PALM);
      else if (green > 0.58) set(x, y, hash2(x, y, 825) < 0.3 ? T.TALLGRASS : T.GRASS);
      else if (cur !== T.DESERT) set(x, y, T.DESERT);
    }
  }
  for (let y = OASIS_CAMP.y - 2; y < OASIS_CAMP.y + OASIS_CAMP.h + 2; y++) {
    for (let x = OASIS_CAMP.x - 2; x < OASIS_CAMP.x + OASIS_CAMP.w + 2; x++) {
      const d = oasis2D(x, y);
      if (d < 0.75) set(x, y, d < 0.45 ? T.DEEP : T.WATER);
      else if (d < 1.05) set(x, y, T.SAND);
      else if (d < 1.9) set(x, y, hash2(x, y, 827) < 0.16 ? T.PALM : hash2(x, y, 829) < 0.4 ? T.TALLGRASS : T.GRASS);
      else if ([T.DUNE, T.SANDSTONE, T.CACTUS].includes(get(x, y))) set(x, y, T.DESERT);
    }
  }

  // 4) 道（砂丘も 岩も けずる）
  for (const road of ROADS) {
    const minX = Math.min(...road.map((p) => p[0])) - 3, maxX = Math.max(...road.map((p) => p[0])) + 3;
    const minY = Math.min(...road.map((p) => p[1])) - 3, maxY = Math.max(...road.map((p) => p[1])) + 3;
    for (let y = Math.floor(minY); y <= maxY; y++) {
      for (let x = Math.floor(minX); x <= maxX; x++) {
        const d = distToPath(x + 0.5, y + 0.5, road);
        const cur = get(x, y);
        if ([T.WATER, T.DEEP].includes(cur)) continue;
        if (d < 0.95) set(x, y, T.DIRT);
        else if (d < 2.4 && [T.DUNE, T.SANDSTONE, T.CACTUS, T.PALM].includes(cur)) set(x, y, T.DESERT);
      }
    }
  }
  // 北の海辺（竜が おりる ところ）は ひらけた 砂浜
  for (let y = LANDING_BEACH.y; y < LANDING_BEACH.y + LANDING_BEACH.h; y++) {
    for (let x = LANDING_BEACH.x; x < LANDING_BEACH.x + LANDING_BEACH.w; x++) {
      if ([T.DUNE, T.SANDSTONE, T.CACTUS].includes(get(x, y))) set(x, y, T.DESERT);
    }
  }

  // 5) はめこみ（村・王都）。まわり 1マスは 歩ける 砂に する
  const stamp = (place, rows, extra = null) => {
    const p = parseRows(rows, extra);
    for (let y = 0; y < p.h; y++) for (let x = 0; x < p.w; x++) set(place.x + x, place.y + y, p.tiles[y * p.w + x]);
  };
  for (const pl of [HAM, SAF]) {
    for (let y = pl.y - 1; y < pl.y + pl.h + 1; y++) for (let x = pl.x - 1; x < pl.x + pl.w + 1; x++) {
      if ([T.DUNE, T.SANDSTONE, T.CACTUS, T.PALM].includes(get(x, y))) set(x, y, T.DESERT);
    }
  }
  stamp(HAM, HAMIL_ROWS);
  stamp(SAF, SAFARA_ROWS, SAFARA_LEGEND);

  // 5b) 王家のピラミッド（Step 4）: まえの 広場は 砂ばく、ピラミッドの 南の まん中に 日時計の とびら、オベリスクの 台
  for (let y = PYRAMID_PLAZA.y; y < PYRAMID_PLAZA.y + PYRAMID_PLAZA.h; y++) {
    for (let x = PYRAMID_PLAZA.x; x < PYRAMID_PLAZA.x + PYRAMID_PLAZA.w; x++) if (get(x, y) !== T.DIRT) set(x, y, T.DESERT);
  }
  for (let y = PYRAMID.y; y < PYRAMID.y + PYRAMID.h; y++) for (let x = PYRAMID.x; x < PYRAMID.x + PYRAMID.w; x++) set(x, y, T.PYRAMID);
  set(PYRAMID_POS.door.x, PYRAMID_POS.door.y, T.PYR_DOOR);
  set(PYRAMID_POS.obelisk.x, PYRAMID_POS.obelisk.y, T.OBELISK_BASE);

  // 6) 北の古井戸（日干しれんがの わくの 中の あな。南から 入る）
  const wl = SOUTH_POS.well;
  for (let y = wl.y - 3; y <= wl.y + 3; y++) for (let x = wl.x - 3; x <= wl.x + 3; x++) {
    if (x > 2 && [T.DUNE, T.SANDSTONE, T.CACTUS].includes(get(x, y))) set(x, y, T.DESERT);
  }
  for (let x = wl.x - 1; x <= wl.x + 1; x++) set(x, wl.y - 1, T.ADOBE);
  set(wl.x - 1, wl.y, T.ADOBE);
  set(wl.x + 1, wl.y, T.ADOBE);
  set(wl.x, wl.y, T.WELL_HOLE);
  set(wl.x, wl.y + 1, T.DIRT);

  // 7) 歩いて 行けない すきま（砂丘や 岩に かこまれた 小さな 場所）は 砂丘で うめる
  //    （魔物や きらきらが 行けない 所に 出ない ように。砂嵐のかべの 南も ふくめて つながりを 見る）
  //    村と 王都の 中は そのまま（王都の 中庭は 地下水路から、闘技場は カギの とびらの むこう）
  const seen = new Uint8Array(W * H);
  const open = (x, y) => x >= 0 && y >= 0 && x < W && y < H && !TILE_INFO[t[y * W + x]]?.solid;
  const q = [[Math.floor(SOUTH_ARRIVE.x), Math.floor(SOUTH_ARRIVE.y)]];
  seen[q[0][1] * W + q[0][0]] = 1;
  for (let i = 0; i < q.length; i++) {
    const [x, y] = q[i];
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, ny = y + dy;
      if (!open(nx, ny) || seen[ny * W + nx]) continue;
      seen[ny * W + nx] = 1;
      q.push([nx, ny]);
    }
  }
  const FILL = new Set([T.DESERT, T.SAND, T.GRASS, T.TALLGRASS, T.DIRT]);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) if (!seen[y * W + x] && FILL.has(t[y * W + x]) && !inRect(x, y, HAM) && !inRect(x, y, SAF)) set(x, y, T.DUNE);
  }

  // 8) 砂嵐のかべ（東西 ぜんぶ。道の ところだけ さきに 弱まる）
  const gates = [];
  // 日時計の とびら（ピラミッドの 南の まん中。昼の 12時ごろに しらべると 開く: c4_pyramid）
  gates.push({ x: PYRAMID_POS.door.x, y: PYRAMID_POS.door.y, closed: T.PYR_DOOR, open: T.PYR_GATE, flag: PYRAMID_FLAG });
  // オベリスクの 影（お日さまの むきで のびる。とびらと ちがって フラグは 時間の しるし）
  for (const [f, list] of Object.entries(OBELISK_SHADOW)) for (const p of list) gates.push({ x: p.x, y: p.y, closed: T.DESERT, open: T.SUN_SHADOW, flag: f });
  for (let y = STORM_Y[0]; y <= STORM_Y[1]; y++) {
    for (let x = 0; x < W; x++) {
      const cur = get(x, y);
      if (cur === T.SANDSTONE) continue;
      const flag = x >= STORM_GAP_X[0] && x <= STORM_GAP_X[1] ? STORM_FLAG : STORM_END_FLAG;
      set(x, y, T.SANDSTORM);
      gates.push({ x, y, closed: T.SANDSTORM, open: cur, flag });
    }
  }
  // 南の 砂嵐（Step 5。王都の 南。道の ところは 大臣ザイードを たおすと 弱まる）
  for (let y = SOUTH_STORM_Y[0]; y <= SOUTH_STORM_Y[1]; y++) {
    for (let x = 0; x < W; x++) {
      const cur = get(x, y);
      if (cur === T.SANDSTONE) continue;
      const flag = x >= SOUTH_STORM_GAP_X[0] && x <= SOUTH_STORM_GAP_X[1] ? SOUTH_STORM_FLAG : STORM_END_FLAG;
      set(x, y, T.SANDSTORM);
      gates.push({ x, y, closed: T.SANDSTORM, open: cur, flag });
    }
  }
  // 9) 砂の港ドゥナへの 谷の 木の さく（砂の海賊が とざしている。まん中は カギの かかった 門。開くのは Step 6）
  for (let x = DUNA_GATE.x - 3; x <= DUNA_GATE.x + 3; x++) {
    if (TILE_INFO[get(x, DUNA_GATE.y)]?.solid) continue;
    set(x, DUNA_GATE.y, x === DUNA_GATE.x ? T.LOCKED_DOOR : T.FENCE);
  }
  return { w: W, h: H, tiles: t, gates };
}

// どの ちいき（出てくる モンスター）か
// 王都の 東の 砂ばく（ピラミッドの まわり）は s_pdesert（Step 4。岩の 魔物・夜は ランプの魔人も）
export function southZoneAt(x, y) {
  for (const [id, p] of Object.entries(SOUTH_PLACES)) if (inRect(x, y, p)) return 'safe:' + id;
  // 南の 砂嵐の 先（Step 5）: 南の砂ばく。ドゥナへの 谷の まわりは 魔物が 出ない
  if (inRect(x, y, DUNA_VALLEY)) return 'safe:duna';
  if (y >= SOUTH_STORM_Y[0]) return 's_sdesert';
  if (inRect(x, y, LANDING_BEACH)) return 'safe:landing';
  if (inRect(x, y, OASIS_CAMP, -2)) return 'safe:camp';
  if (inRect(x, y, PYRAMID_PLAZA) || inRect(x, y, PYRAMID, 1)) return 'safe:pyramid';
  if (y <= 12) return 's_coast';
  if (inRect(x, y, HAM, 8) || inRect(x, y, OASIS_CAMP, 6)) return 's_oasis';
  if (y > STORM_Y[1] && x >= SAF.x + SAF.w) return 's_pdesert';
  return 's_dune';
}

// ばしょの なまえ（がめんの 左上に でる）
export function southAreaName(x, y) {
  // 王都の 中の 宮殿と 中庭
  if (inRect(x, y, PALACE_COURT)) return '宮殿の中庭';
  if (inRect(x, y, PALACE_HALL)) return 'サファラの宮殿';
  for (const p of Object.values(SOUTH_PLACES)) if (inRect(x, y, p)) return p.name;
  if (inRect(x, y, LANDING_BEACH) || y <= 12) return LANDING_BEACH.name;
  if (Math.hypot(x - SOUTH_POS.well.x, y - SOUTH_POS.well.y) < 7) return '北の古井戸';
  if (inRect(x, y, OASIS_CAMP, 3)) return '小さなオアシス';
  if (Math.abs(x - SOUTH_POS.canal.x) <= 4 && Math.abs(y - SOUTH_POS.canal.y) <= 4) return 'かれた地下水路';
  if (inRect(x, y, PYRAMID, 2) || inRect(x, y, PYRAMID_PLAZA)) return PYRAMID.name;
  if (inRect(x, y, DUNA_VALLEY)) return DUNA_VALLEY.name;
  if (y >= SOUTH_STORM_Y[0]) return y <= SOUTH_STORM_Y[1] ? '南の砂嵐のかべ' : '南の砂ばく';
  if (y > STORM_Y[1] && x >= SAF.x + SAF.w) return '王家の墓の砂ばく';
  if (y > STORM_Y[1]) return 'サファラの砂ばく';
  if (y >= 54) return '砂嵐のかべ';
  return 'コガネ砂丘';
}

// 天気（砂ぼこり。砂嵐のかべの 近くは 砂嵐）
export function southWeatherAt(x, y) {
  if (inRect(x, y, HAM, 1) || inRect(x, y, SAF, 1)) return null;
  // 砂嵐の かべの 近く（南がわも すこし）は 砂嵐。はなれると 砂ぼこり
  if (y >= 52 && y <= STORM_Y[1] + 7) return 'sandstorm';
  // 南の 砂嵐（Step 5）の 近くも
  if (y >= SOUTH_STORM_Y[0] - 2 && y <= SOUTH_STORM_Y[1] + 3) return 'sandstorm';
  if (y <= 14 || inRect(x, y, OASIS_CAMP, 2)) return null;
  return 'sand';
}

// 音楽（村の 中は 村の 曲。外は 昼と 夜で かわる）
export function southBgmAt(x, y, night = false) {
  for (const p of Object.values(SOUTH_PLACES)) if (inRect(x, y, p)) return p.bgm;
  return night ? 'desert_night' : 'desert';
}

