// 第6章 Step 2「時のいせき」の 階の 形（maps/toki-ruin.js が 使う）。どの 階も 今と 千年前で おなじ 形（文字の いみが 時代で ちがう）
// 34×26。かべで かこんで から、しかけを かく（座標は マップの 座標）
// 文字（今 / 千年前）:
//   # かべ / . ゆか / O 柱 / i たいまつ / < 上りかいだん / > 下りかいだん / X 出口（1階。遺跡の 外へ）/ C ふかい 谷（どちらも 通れない）
//   d 今は くずれて 通れる / 千年前は とびらが しまっている
//   h 今は ゆかに あな（通れない）/ 千年前は まだ ゆか
//   R 今は 木の根の 道 / 千年前は 谷（根が まだ ない）
//   r 今は 木の根の かべ / 千年前は まだ ゆか
//   1 2 千年前の レバー（今は こわれて うもれている）/ A B その レバーで 開く とびら（どちらの 時代も。開くと 今は がれきの 道）
//   S 石像（千年前で おすと、今も その 場所に ある。動く 道は toki-ruin.js）/ W 重りの 石（7階。千年前で おす）
//   P 今は 重りの ゆか（石像が のると G が 開く）/ 千年前は ゆか
//   G 今は とびら（P に 石像が のると 開く）/ 千年前は しまった とびら
//   U もとに もどす 石板（千年前だけ。石像・重りの 石が はじめの 場所へ）
//   a 今の 時の ふむ石 / 千年前は ゆか    b 千年前の 時の ふむ石 / 今は ゆか（7階）
//   Z 2つの 時代で 同時に ふむと 開く とびら（7階。どちらの 時代も）
//   Y 千年前は 番人の 間への 下りかいだん / 今は くずれた かべ（7階）
//   F 時の いずみ（4階。回復と 記録）/ k 古い 本だな / M かべ画 / $ 宝箱の 場所（どちらの 時代かは toki-ruin.js）
export const RUIN_W = 34, RUIN_H = 26;

function floor(draw) {
  const g = Array.from({ length: RUIN_H }, (_, y) => Array.from({ length: RUIN_W }, (_, x) => (x === 0 || y === 0 || x === RUIN_W - 1 || y === RUIN_H - 1 ? '#' : '.')));
  const put = (x, y, ch) => { if (x >= 0 && y >= 0 && x < RUIN_W && y < RUIN_H) g[y][x] = ch; };
  const h = (y, x0, x1, ch) => { for (let x = x0; x <= x1; x++) put(x, y, ch); };
  const v = (x, y0, y1, ch) => { for (let y = y0; y <= y1; y++) put(x, y, ch); };
  const fill = (x0, y0, x1, y1, ch) => { for (let y = y0; y <= y1; y++) h(y, x0, x1, ch); };
  draw({ put, h, v, fill });
  return g.map((r) => r.join(''));
}
// どの 階にも ある かざり（柱・たいまつ）
const deco = (d, rows) => {
  for (const y of rows) for (const x of [6, 27]) d.put(x, y, 'O');
};

export const RUIN_ROWS = {
  // 1階: 切りかえの 練習（千年前は とびらが しまっている・今は くずれて 通れる → 今は ゆかに あな・千年前は まだ 通れる）
  1: floor((d) => {
    d.h(17, 1, 32, '#'); for (const x of [8, 17, 26]) d.put(x, 17, 'd');
    d.h(8, 1, 32, '#'); d.h(8, 5, 7, 'h'); d.h(8, 26, 28, 'h');
    d.put(17, 4, '>');
    d.put(1, 1, 'i'); d.put(32, 1, 'i'); d.put(3, 3, 'M'); d.put(30, 3, 'M');
    d.put(27, 6, '$');
    // 西の 小べや（今は くずれた 入口から 入れる）
    d.h(10, 1, 5, '#'); d.v(5, 10, 16, '#'); d.put(5, 13, 'd'); d.put(2, 13, '$');
    d.put(11, 11, 'M'); d.put(23, 11, 'M');
    deco(d, [12, 20]);
    d.h(25, 16, 18, 'X');
  }),
  // 2階: 今の 木の根の 道で 谷を わたる → 今の 根の かべは 千年前なら 通れる
  2: floor((d) => {
    d.put(17, 2, '<');
    d.fill(1, 8, 32, 10, 'C'); d.v(10, 8, 10, 'R');
    d.h(16, 1, 32, '#'); d.h(16, 20, 22, 'r');
    d.put(17, 22, '>');
    // 北東の 小べや（今は ゆかに あな。千年前は 通れる）
    d.h(4, 25, 32, '#'); d.v(25, 1, 4, '#'); d.put(25, 2, 'h'); d.put(30, 2, '$');
    // 南西の 小べや（千年前は とびらが しまっている。今は くずれて 通れる）
    d.h(18, 1, 6, '#'); d.v(6, 18, 24, '#'); d.put(6, 21, 'd'); d.put(2, 21, '$');
    d.put(3, 13, 'M'); d.put(30, 13, 'M');
    deco(d, [5, 20]);
  }),
  // 3階: 石像を おす（千年前で おすと、今も そこに ある）。今の 重りの ゆかに 石像を のせると、今の とびらが 開く
  3: floor((d) => {
    d.put(17, 23, '<');
    d.h(17, 1, 32, '#'); d.put(17, 17, 'h');
    d.h(8, 1, 32, '#'); d.put(17, 8, 'G');
    d.put(6, 12, 'S'); d.put(10, 12, 'P'); d.put(14, 12, 'O'); d.put(4, 10, 'U');
    d.put(17, 3, '>');
    d.put(28, 3, '$'); d.put(29, 14, '$');
    d.put(3, 4, 'M'); d.put(24, 20, 'M');
    d.fill(20, 10, 22, 11, 'O');
    deco(d, [21]);
  }),
  // 4階: 休み所（時の いずみ。回復と 記録。どちらの 時代にも ある）。魔物は 出ない
  4: floor((d) => {
    d.put(17, 2, '<');
    d.fill(11, 8, 23, 8, '#'); d.fill(11, 15, 23, 15, '#'); d.v(11, 8, 15, '#'); d.v(23, 8, 15, '#');
    d.put(17, 8, '.'); d.put(17, 15, '.');
    d.put(17, 11, 'F'); d.put(13, 9, 'k'); d.put(21, 9, 'k');
    d.h(18, 1, 32, '#'); d.put(8, 18, 'd'); d.put(26, 18, 'r');
    d.put(17, 22, '>');
    d.put(30, 22, '$'); d.put(21, 13, '$');
    deco(d, [4, 12]);
  }),
  // 5階: 今の 木の根の 道 × 千年前の とびら（千年前の レバーで とびらを 開け、今の 根で 谷を わたり、千年前で 根の かべを ぬける）
  5: floor((d) => {
    d.put(17, 23, '<');
    d.put(4, 20, '1');
    d.h(17, 1, 32, '#'); d.put(17, 17, 'A');
    d.fill(1, 11, 32, 13, 'C'); d.v(26, 11, 13, 'R');
    d.h(8, 1, 32, '#'); d.h(8, 6, 8, 'r');
    d.put(17, 3, '>');
    d.put(30, 3, '$'); d.put(2, 15, '$');
    d.put(10, 20, 'M');
    deco(d, [4, 21]);
  }),
  // 6階: 2つの レバーと 根の 道（千年前 → 今 → 千年前）
  6: floor((d) => {
    d.put(17, 2, '<');
    d.put(30, 3, '1');
    d.h(6, 1, 32, '#'); d.put(17, 6, 'A');
    d.fill(1, 11, 32, 13, 'C'); d.v(6, 11, 13, 'R');
    d.put(29, 15, '2');
    d.h(17, 1, 32, '#'); d.put(25, 17, 'B');
    d.put(17, 22, '>');
    d.put(2, 3, '$'); d.put(31, 22, '$');
    d.put(3, 8, 'M');
    deco(d, [9, 20]);
  }),
  // 7階: 2つの 時代で 同時に（今の ふむ石 a と 千年前の ふむ石 b。ひとりなら 千年前で 重りの 石を a の 場所へ）
  7: floor((d) => {
    d.put(17, 23, '<');
    d.h(12, 1, 32, '#'); d.put(17, 12, 'Z');
    d.put(6, 19, 'a'); d.put(28, 19, 'b');
    // 千年前の ふむ石は 小べやの 中（千年前は とびらが しまっている。今の くずれた 入口から 入って、中で 時を こえる）
    d.h(17, 25, 31, '#'); d.h(22, 25, 31, '#'); d.v(25, 17, 22, '#'); d.v(31, 17, 22, '#'); d.put(25, 19, 'd');
    d.put(6, 15, 'W'); d.put(6, 22, 'O'); d.put(3, 14, 'U');
    d.put(17, 3, 'Y');
    d.put(29, 3, '$'); d.put(2, 24, '$');
    d.put(17, 15, 'M'); d.put(14, 6, 'M');
    deco(d, [5]);
    d.put(11, 21, 'O'); d.put(23, 21, 'O');
  }),
};

// 番人の 間（千年前だけ。26×20）: 南の 上りかいだん・大広間・おくに ギアドンと 時の 神殿の 心（時の砂時計の 台座の 形）
export const BOSS_W = 26, BOSS_H = 20;
export const BOSS_ROWS = (() => {
  const g = Array.from({ length: BOSS_H }, () => Array(BOSS_W).fill('#'));
  const inHall = (x, y) => ((x - 12.5) / 11) ** 2 + ((y - 7.5) / 6.6) ** 2 <= 1;
  for (let y = 1; y <= 14; y++) for (let x = 1; x < BOSS_W - 1; x++) if (inHall(x, y)) g[y][x] = '.';
  for (let y = 14; y <= 18; y++) for (let x = 10; x <= 15; x++) g[y][x] = '.';
  for (const [x, y] of [[6, 4], [19, 4], [4, 9], [21, 9]]) g[y][x] = 'O';
  g[18][12] = '<';
  g[2][12] = 'T';
  return g.map((r) => r.join(''));
})();

