// 第5章 Step 2「星の塔」の レイアウト（1文字 = 1マス。文字の いみは maps/tower.js の TOWER_LEGEND）
// #=塔の 石の かべ .=石の ゆか p=柱 i=たいまつ <=上の 階へ >=下の 階へ !=石の 文字ばん o=つぼ Y=像 k=本だな
// w=星空が 見える 窓 G=昔の 勇者の かべ画 C=星図 E=星の エレベーター（近道） F=休み所の 星の いずみ *=星空の もようの ゆか
// 上り下りの ゆか: L=ゆか u=ゆかの 通り道（だん） K=重りの ゆか（7階の 2つ目は M・m・J）
// 星座の ゆか: 1〜5=本物の 星（ふむ じゅん） x=にせの 星 D=星の とびら
// 風の 窓: V=風の 窓 v=風見の石 a・b=風（東へ 流される。3階は a が 下・b が 上） R=ふきぬけの 上の 風の 道（風見の石で ふく） P=ふきぬけ Q=6階の 近道の とびら
// 1階: O=出口 / てっぺん: ^=ふちの 石がき _=石の ゆか T=紋章の さいだん
// 第38回 A: どの 階も 東や 南に わき道・行き止まりの 宝の へや・見晴らしの よい 広間を たして 広くした。
//   前からの へや・しかけ・かいだんの 場所（ざひょう）は そのまま（マップの 東と 南を のばした）

// マップを かく どうぐ（maps/labyrinth.js と おなじ 形）
function sheet(w, h, fill = '#') {
  const g = Array.from({ length: h }, () => Array(w).fill(fill));
  const ok = (x, y) => x >= 0 && y >= 0 && x < w && y < h;
  const api = {
    w, h,
    rect(x, y, rw, rh, ch = '.') { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) if (ok(i, j)) g[j][i] = ch; return api; },
    put(x, y, ch) { if (ok(x, y)) g[y][x] = ch; return api; },
    puts(list, ch) { for (const [x, y] of list) api.put(x, y, ch); return api; },
    rows() { return g.map((r) => r.join('')); },
  };
  return api;
}

// 1階「星の塔の入口」（42×22）: 南の 出口 → 大広間（北の かべに 昔の 勇者の かべ画・まん中に 2つの 像）→ 北東の かいだん。西に エレベーター
// わき道: 大広間の 東に 星見の回廊（柱と 窓）→ その 南に 行き止まりの 宝の 小べや。入口の 通路の 東に 見張りの へや・西に 物置
function f1() {
  const s = sheet(42, 22);
  s.rect(3, 2, 22, 14); // 大広間
  s.rect(11, 16, 6, 5); // 入口の 通路
  s.puts([[13, 21], [14, 21]], 'O');
  s.puts([[9, 1], [10, 1], [11, 1], [12, 1]], 'G');
  s.puts([[4, 1], [19, 1], [2, 6], [25, 6], [2, 12]], 'w');
  s.put(23, 1, '<');
  s.put(2, 9, 'E');
  s.puts([[6, 4], [11, 4], [16, 4], [21, 4], [6, 12], [21, 12]], 'p');
  s.puts([[12, 8], [15, 8]], 'Y');
  s.puts([[5, 14], [22, 14], [16, 19]], 'o');
  s.put(11, 17, '!');
  s.puts([[3, 2], [24, 15]], 'i');
  s.rect(25, 10, 4, 2); // 大広間 → 星見の回廊
  s.rect(29, 3, 11, 12); // 星見の回廊
  s.puts([[31, 5], [37, 5], [31, 12], [37, 12]], 'p');
  s.puts([[32, 2], [36, 2], [40, 6], [40, 11]], 'w');
  s.puts([[39, 3], [29, 14]], 'i');
  s.rect(31, 15, 3, 4); // 回廊の 南の 宝の 小べや（行き止まり）
  s.put(17, 18, '.').rect(18, 17, 6, 4); // 見張りの へや
  s.puts([[23, 17], [18, 20]], 'o');
  s.put(10, 19, '.').rect(4, 18, 6, 3); // 西の 物置
  s.puts([[4, 18], [9, 20]], 'o');
  return s.rows();
}

// 2階「上り下りのゆか」（42×22）: 下の 広間の 北に 高い だん。上り下りの ゆか（L）は、東の 小べやの 重りの ゆか（K）に だれかが のると 上がる
// わき道: 下の 広間の 東に 東の 広間。そこの 2つ目の 上り下りの ゆか（M・m・J）は 宝の 屋根うらへ（しなくても 先へ 行ける）。南西に 小べや
function f2() {
  const s = sheet(42, 22);
  s.rect(6, 2, 17, 4); // 上の だん
  s.put(14, 1, '<');
  s.puts([[13, 6], [13, 7]], 'u');
  s.rect(4, 8, 19, 10); // 下の 広間
  s.put(13, 8, 'L');
  s.rect(23, 12, 5, 4); // 東の 小べや（重りの ゆか）
  s.put(26, 13, 'K');
  s.rect(10, 18, 7, 2); // かいだんの まえ
  s.put(13, 20, '>');
  s.put(9, 19, 'E');
  s.put(3, 10, '!');
  s.puts([[7, 10], [19, 10], [7, 15], [19, 15]], 'p');
  s.puts([[7, 1], [21, 1], [3, 14], [28, 13]], 'w');
  s.puts([[5, 16], [27, 15]], 'o');
  s.rect(23, 9, 6, 1); // 下の 広間 → 東の 広間
  s.rect(29, 8, 11, 10); // 東の 広間
  s.put(30, 16, 'J'); // 2つ目の 重りの ゆか
  s.puts([[37, 6], [37, 7]], 'm');
  s.put(37, 8, 'M'); // 2つ目の 上り下りの ゆか
  s.rect(34, 2, 6, 4); // 宝の 屋根うら（2つ目の ゆかが 上がると 行ける）
  s.puts([[33, 10], [33, 15], [39, 13]], 'p');
  s.puts([[40, 11], [40, 15], [35, 1]], 'w');
  s.puts([[39, 17], [34, 2]], 'o');
  s.rect(4, 18, 4, 3); // 南西の 小べや
  return s.rows();
}

// 3階「風の窓」（38×24）: 南の へや → 風（a）→ まん中の へや → 風（b）→ 北の へや。風見の石（v）は 南と まん中に 1つずつ。
// 風に 流されると 東の はしの 小道から 手前の へやへ もどされる
// わき道: 北の へやの 西に 見晴らし台・まん中の へやの 東に 東の へや・南の へやの 東に 南東の 広間・南西に 小べや
function f3() {
  const s = sheet(38, 24);
  s.rect(9, 2, 10, 3); // 北の へや
  s.put(14, 1, '<');
  s.puts([[4, 5], [4, 6]], 'V').rect(5, 5, 19, 2, 'b'); // 上の 風
  s.rect(5, 7, 16, 5); // まん中の へや
  s.rect(21, 8, 3, 1).put(23, 7, '.'); // 上の 風の 小道（まん中の へやへ もどる）
  s.put(7, 9, 'v');
  s.puts([[4, 12], [4, 13]], 'V').rect(5, 12, 19, 2, 'a'); // 下の 風
  s.rect(7, 14, 14, 7); // 南の へや（かいだん）
  s.rect(21, 15, 3, 1).put(23, 14, '.'); // 下の 風の 小道（南の へやへ もどる）
  s.put(9, 16, 'v');
  s.put(14, 21, '>');
  s.put(6, 19, 'E');
  s.put(12, 15, '!');
  s.puts([[18, 3], [19, 10], [19, 18]], 'o');
  s.puts([[10, 1], [18, 1], [25, 9], [6, 16]], 'w');
  s.rect(3, 2, 6, 2); // 北の へやの 西の 見晴らし台
  s.puts([[4, 1], [7, 1], [2, 2]], 'w');
  s.rect(21, 10, 6, 1).rect(27, 8, 10, 4); // まん中の へや → 東の へや
  s.puts([[29, 7], [33, 7]], 'w');
  s.puts([[30, 9], [33, 10]], 'p');
  s.rect(21, 18, 5, 1).rect(26, 15, 11, 8); // 南の へや → 南東の 広間
  s.puts([[28, 17], [33, 17], [28, 20], [33, 20]], 'p');
  s.puts([[37, 18], [30, 14]], 'w');
  s.put(26, 22, 'o');
  s.rect(7, 21, 5, 2); // 南の へやの 南西の 小べや
  return s.rows();
}

// 4階「休み所」（40×22）: かいだんの へや → 休み所（星の いずみ・エレベーター）→ 北の かいだん。西に 昔の 勇者の 本だな
// わき道: 東の へやの 東に 星見の 広間（大きな 窓が ならぶ）。かいだんの へやの 西と 東に 小べや
function f4() {
  const s = sheet(40, 22);
  s.rect(10, 16, 9, 4); // かいだんの へや
  s.put(14, 20, '>');
  s.rect(13, 14, 4, 2);
  s.rect(9, 7, 12, 7); // 休み所
  s.put(14, 9, 'F');
  s.put(19, 8, 'E');
  s.puts([[10, 8], [10, 12], [20, 12]], 'p');
  s.rect(13, 2, 4, 5); // 北の 通路
  s.put(14, 1, '<');
  s.rect(2, 4, 6, 8); // 西の 本の へや
  s.rect(8, 9, 1, 2);
  s.puts([[3, 3], [4, 3], [5, 3], [6, 3]], 'k');
  s.rect(22, 4, 6, 8); // 東の へや（宝）
  s.rect(21, 10, 1, 2);
  s.puts([[11, 6], [18, 6], [1, 8], [28, 8]], 'w');
  s.put(16, 17, '!');
  s.puts([[3, 11], [26, 5]], 'o');
  s.rect(28, 10, 2, 2).rect(30, 3, 8, 10); // 東の へや → 星見の 広間
  s.puts([[31, 2], [33, 2], [35, 2], [38, 5], [38, 8], [38, 11]], 'w');
  s.puts([[32, 6], [35, 6], [32, 10], [35, 10]], 'p');
  s.put(9, 17, '.').rect(3, 15, 6, 5); // かいだんの へや → 西の 小べや
  s.puts([[3, 15], [8, 19]], 'o');
  s.put(19, 18, '.').rect(20, 15, 7, 5); // かいだんの へや → 東の 小べや
  s.puts([[27, 17], [23, 14]], 'w');
  return s.rows();
}

// 5階「星座のゆか」（30×24）: かいだんの へや（北の かべに 星図）→ 星空の 大広間（竜の 星座の 5つの 星と にせの 星）→ 星の とびら → 北の かいだん
export const STAR_ORDER = [[7, 7], [11, 9], [15, 7], [19, 10], [22, 13]];
export const STAR_FAKE = [[5, 11], [9, 13], [13, 12], [17, 6], [21, 7], [24, 11], [8, 10], [18, 14], [25, 6]];
// わき道（41×24）: 星空の 大広間の 東に 星見台（星空の もようの ゆか）。かいだんの へやの 東に 小べや
function f5() {
  const s = sheet(41, 24);
  s.rect(9, 18, 12, 4); // かいだんの へや
  s.put(14, 22, '>');
  s.puts([[9, 17], [10, 17], [11, 17]], 'C');
