// 文字の マスを ぜんぶ さがす
export function cellsOf(rows, chars) {
  const out = [];
  rows.forEach((row, y) => [...row].forEach((ch, x) => { if (chars.includes(ch)) out.push([x, y]); }));
  return out;
}
