const walk = (ch) => ['.', '*', '_'].includes(ch);
// となりの 歩ける マス（エレベーターから 出る ところ）
function besideOf(rows, p) {
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (walk(rows[p.y + dy]?.[p.x + dx])) return { x: p.x + dx, y: p.y + dy };
  return p;
}

