// 乱数ユーティリティ（サーバーとブラウザの両方で動く）

// シード付き乱数（mulberry32）。マップ生成など「毎回同じ結果」が必要な所で使う
export function makeRng(seed = Date.now()) {
  let a = seed >>> 0;
  const next = () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const rng = {
    next,
    // min以上max以下の整数
    int(min, max) { return min + Math.floor(next() * (max - min + 1)); },
    // min以上max未満の実数
    float(min, max) { return min + next() * (max - min); },
    chance(p) { return next() < p; },
    pick(arr) { return arr[Math.floor(next() * arr.length)]; },
    // [{w:重み, ...}] から重み付きで1つ選ぶ
    weighted(list, key = 'w') {
      const total = list.reduce((s, e) => s + (e[key] ?? 1), 0);
      let r = next() * total;
      for (const e of list) {
        r -= e[key] ?? 1;
        if (r < 0) return e;
      }
      return list[list.length - 1];
    },
    shuffle(arr) {
      const a = arr.slice();
      for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
      }
      return a;
    },
  };
  return rng;
}

// 座標から決まる疑似乱数（0〜1）。タイルの見た目のばらつき等に使う
export function hash2(x, y, seed = 0) {
  let h = (x * 374761393 + y * 668265263 + seed * 2147483647) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = (h ^ (h >>> 16)) >>> 0;
  return h / 4294967296;
}

// なめらかなノイズ（地形の形を自然にするため）
export function valueNoise(x, y, seed = 0) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const s = (t) => t * t * (3 - 2 * t);
  const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed);
  const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed);
  const u = s(xf), v = s(yf);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

export function fbm(x, y, seed = 0, octaves = 3) {
  let sum = 0, amp = 1, freq = 1, norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += valueNoise(x * freq, y * freq, seed + i * 101) * amp;
    norm += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return sum / norm;
}

js/shared/roster-sort.js:
// 酒場で 待っている 仲間の ならび（仲間は 40ひきまで。data/companions.js の ROSTER_MAX）
//   got   … 仲間に なった じゅん（今までと 同じ）
//   kind  … 種類じゅん（人の 仲間 → 魔物は 図鑑の じゅん。同じ 種類は レベルの 高い じゅん）
//   level … レベルの 高い じゅん（同じ レベルは 仲間に なった じゅん）
// 画面は client/ui/services.js の 酒場。えらんだ ならびは この 機械に のこす（client/prefs.js の rosterSortPref）
import { MONSTERS } from './data/monsters.js';

export const ROSTER_SORTS = [
  ['got', '仲間になった順'],
  ['kind', '種類順'],
  ['level', 'レベル順'],
];
export const rosterSortName = (mode) => (ROSTER_SORTS.find(([k]) => k === mode) || ROSTER_SORTS[0])[1];
export const nextRosterSort = (mode) => {
  const i = ROSTER_SORTS.findIndex(([k]) => k === mode);
  return ROSTER_SORTS[(i + 1) % ROSTER_SORTS.length][0];
};

// 図鑑の じゅん（MONSTERS に 書いた じゅん）
let dexOrder = null;
function dexIndex(sp) {
  if (!dexOrder) dexOrder = new Map(Object.keys(MONSTERS).map((k, i) => [k, i]));
  return dexOrder.has(sp) ? dexOrder.get(sp) : 1e6;
}

// list: [{ key, species?, level, … }]（酒場の じょうほう。もとの じゅんが 仲間に なった じゅん）
export function sortRoster(list, mode = 'got') {
  const rows = list.map((e, i) => ({ e, i }));
  const lv = (e) => Number(e.level) || 0;
  if (mode === 'kind') {
    rows.sort((a, b) => (a.e.species ? 1 : 0) - (b.e.species ? 1 : 0)
      || (a.e.species ? dexIndex(a.e.species) - dexIndex(b.e.species) : 0)
      || lv(b.e) - lv(a.e) || a.i - b.i);
  } else if (mode === 'level') {
    rows.sort((a, b) => lv(b.e) - lv(a.e) || a.i - b.i);
  }
  return rows.map((r) => r.e);
}

js/shared/skill-power.js:
// 技・呪文の 威力の 目安（第50回 N1。メニューの「呪文・技」・オートで 使う 技・戦いの せつめいで 使う）
//   物理: ふつうの 攻撃の 何倍か（「威力×1.8」「威力×0.6×4回」。転職の ペナルティ・職業レベルの 威力も かける）
//   魔力で 強く なる 呪文・技: 今の 魔力で どれくらいの ダメージか（相手の 耐性・守りは 考えない）
//   回復: 今の 回復魔力で どれくらい 回復するか
// しきは shared/battle.js の calcPhys・calcMagic・heal・healAmountOf と おなじ（ふりはばは 両はし、会心・耐性は 入れない）
import { abilityFor } from './ability-label.js';
import { computeStats, penaltyFor } from './stats.js';
// 第72回: 元気玉（みんなの HPを 10%ずつ 集める。battle-genki.js）
import { genkiTotal } from './battle-genki.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
// 倍率の 数（1.0・1.8 の ように 小数 1けた。1より 小さい ときは 0.55 の ように 2けたまで）
export const fmtMult = (x) => (x < 0.995 ? (Math.round(x * 100) / 100).toString() : (Math.round(x * 10) / 10).toFixed(1));
const pair = (b) => (Array.isArray(b) ? [b[0] || 0, b[1] ?? b[0] ?? 0] : [b || 0, b || 0]);
const rangeText = (mn, mx) => (mn === mx ? `${mn}` : `${mn}〜${mx}`);

// 今の 魔力・回復魔力（{ mag, heal }。わからない ときは null）
//   戦いの 中: pub の pow（バフも 入った 今の 魔力）を pc.pow に 入れて わたす
//   メニュー: セーブの キャラ（レベル・職業・装備）から computeStats
//   第72回: char.partyHp（戦いの 中の 味方 みんなの 今の HP。client/battle.js の abilityMenu）が あれば party に（元気玉の 目安）
export function powStats(char) {
  if (!char) return null;
  const party = Array.isArray(char.partyHp) ? { party: char.partyHp } : {};
  if (char.pow && Number.isFinite(char.pow.mag)) return { mag: char.pow.mag, heal: char.pow.heal || 0, ...party };
  if (!char.level || !(char.job || char.species)) return null;
  try {
    const st = computeStats(char);
    return { mag: st.mag || 0, heal: st.heal || 0, ...party };
  } catch {
    return null;
  }
}

// 魔力の 伸び（calcMagic・heal と おなじ）
export function powScale(pow, e) {
  return 1 + clamp(((pow || 0) - (e.thr ?? 20)) / 150, 0, e.scaleCap ?? 1);
}

// 1つの 効果の 威力（{ type, ... }。威力の ない 効果は null）
//   pm: 転職の ペナルティ・職業レベルを かけた 威力の 倍率 / base: ペナルティ なしの 倍率 / st: 今の 魔力（なければ 目安だけ）
export function partPower(e, pm = 1, st = null, base = pm) {
  if (!e) return null;
  switch (e.type) {
    case 'phys':
    case 'drainHp': {
      const m = (e.mult ?? 1) * pm;
      return { type: 'phys', mult: m, full: (e.mult ?? 1) * base, hits: e.type === 'phys' && e.hits > 1 ? e.hits : 1, random: !!e.random };
    }
    case 'magic':
    case 'deduce':
    case 'gather': {
      if (!e.base) return null;
      const [a, b] = pair(e.base);
      const stat = e.stat === 'heal' ? 'heal' : 'mag';
      const k = (st ? powScale(st[stat], e) : 1) * pm;
      return { type: 'magic', stat, min: Math.round(a * k), max: Math.round(b * k), now: !!st, more: e.type === 'gather' };
    }
    // 第72回: 元気玉 … 集めた HP × 倍率（転職の ペナルティ・職業レベルも かける）。st.party（味方の 今の HP）が あれば 今の みんなで どれくらいか
    case 'genki': {
      const m = (e.mult || 1) * pm;
      const got = Array.isArray(st?.party) ? genkiTotal(st.party, e.rate) : null;
      return { type: 'genki', mult: m, got, est: got === null ? null : Math.round(got * m) };
    }
    case 'heal':
    case 'regen': {
      if (!e.base) return null;
      const [a, b] = pair(e.base);
      const scale = !e.fixed && st ? powScale(st.heal, e) : 1;
      // じわじわ 回復は 1回で 1より 少なく ならない（healAmountOf）
      const lo = Math.round(a * scale * pm), hi = Math.round(b * scale * pm);
      return { type: e.type, min: e.type === 'regen' ? Math.max(1, lo) : lo, max: e.type === 'regen' ? Math.max(1, hi) : hi, now: !e.fixed && !!st };
    }
    default: return null;
  }
}

// 威力の みじかい 文（リストの 2行め よう）。威力の ない 効果は ''
export function partPowerText(p) {
  if (!p) return '';
  if (p.type === 'phys') {
    const hits = p.hits > 1 ? `×${p.hits}回${p.random ? '（ランダム）' : ''}` : '';
    // 本職で ない 技は、本来の 倍率も（「威力×1.0（本来×1.5）」）
    const full = p.full - p.mult > 0.005 ? `（本来×${fmtMult(p.full)}）` : '';
    return `威力×${fmtMult(p.mult)}${hits}${full}`;
  }
  if (p.type === 'magic') return `${p.now ? (p.stat === 'heal' ? '今の回復魔力で' : '今の魔力で') : ''}ダメージ約${rangeText(p.min, p.max)}${p.more ? '（仲間がいると上がる）' : ''}`;
  if (p.type === 'genki') return `集めたHP×${fmtMult(p.mult)}${p.got === null ? '' : p.got > 0 ? `（今のみんなでHP${p.got}・約${p.est}）` : '（今は元気が集まらない）'}`;
  if (p.type === 'heal') return `${p.now ? '今の回復魔力で' : ''}約${rangeText(p.min, p.max)}回復`;
  if (p.type === 'regen') return `${p.now ? '今の回復魔力で' : ''}毎ターン約${rangeText(p.min, p.max)}回復`;
  return '';
}

// 効果の 中の 威力を ぜんぶ（multi は 中の 効果を じゅんに）
export function effectPowers(e, pm = 1, st = null, base = pm) {
  if (!e) return [];
  if (e.type === 'multi') return (e.parts || []).flatMap((p) => effectPowers(p, pm, st, base));
  const p = partPower(e, pm, st, base);
  return p ? [p] : [];
}

// 転職の ペナルティ（pm: かける 倍率・base: ペナルティ なしの 倍率〈職業レベルの 威力は 入れる〉）
export function powMults(char, id) {
  let pen = { powMult: 1 };
  try {
    if (char) pen = penaltyFor(char, id);
  } catch {
    pen = { powMult: 1 };
  }
  const pm = pen.powMult || 1;
  return { pm, base: pen.penalized ? (pen.jobPow || 1) : pm, penalized: !!pen.penalized };
}

// 技の 威力の 目安（char: 使う 人〈セーブの キャラ か 戦いの pc〉。who: 名前・見た目を きめる 人）
//   { parts: [...], text: '威力×1.8' など（威力の ない 技は ''）, pm, penalized }
export function skillPower(id, char, { who = char, st = undefined } = {}) {
  const a = abilityFor(id, who);
  const { pm, base, penalized } = powMults(char, id);
  if (!a || !a.effect) return { parts: [], text: '', pm, penalized };
  const stats = st === undefined ? powStats(char) : st;
  const parts = effectPowers(a.effect, pm, stats, base);
  return { parts, text: parts.map(partPowerText).filter(Boolean).join('＋'), pm, penalized };
}

js/shared/skill-sort.js:
// 第69回: 技の ならび（家族の ことば「技の並びを、ダメージ、回復倍率が低いの昇順にして。職業補正は無しで、標準の技の強さベースで」）
//   ・職業の ほせい（転職の ペナルティ・職業レベル・上の 職業の 強さ）も、その 人の 強さも 入れない。
//     みんな おなじ「ふつうの キャラ」（STD）が 使った ときの、だいたいの ダメージ・回復の 量で くらべる。
//     （物理の 倍率の 技と、数で きまる 呪文・回復が くらべられる。ふりはばは まんなか、何回も あたる 技は 回数を かける、
//      いくつも 効果の ある 技は たす。ダメージも 回復も おなじ ものさし）
//   ・弱い 技から じゅんに（ダメージ・回復の ある 技 → その あとに 強くする・弱くする・そのほかの 技を MPの 少ない じゅん）
//   ・おなじ ときは MPの 少ない ほう → 覚えた じゅん
// しきは shared/battle.js の calcPhys・calcMagic・healAmountOf と おなじ（会心・耐性・守りの バフは 入れない）
// テスト: test/skill-menu-r69.test.js
import { ABILITIES } from './data/abilities.js';
import { REGEN_BASE } from './buff-acts.js';
// 第72回: 元気玉（みんなの HPを 10%ずつ 集める。battle-genki.js）
import { genkiTotal } from './battle-genki.js';

// ふつうの キャラ（どの 技も この 強さで くらべる）
//   atk: 攻撃力・foeDfn: 相手の 守備力・mag: 魔力・heal: 回復魔力・maxHp: 生き返る 人の 最大HP・mp: のこりの MP（マダンテ）・lv: レベル（銭投げ）
//   party・partyHp: 元気玉の みんなの 人数と 1人の HP（ほかの 技の ふつうに 合わせた 数。HP満タンの 4人で、
//     伝説の 職業の 強い 全体攻撃〈ギガデイン・極 290〉の 約1.3倍。tools/sim-genki.mjs の Lv60〜80 の くらべと だいたい おなじ）
export const STD = { atk: 120, foeDfn: 60, mag: 80, heal: 80, maxHp: 200, mp: 100, lv: 30, party: 4, partyHp: 400 };

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const avg = (b) => (Array.isArray(b) ? ((b[0] || 0) + (b[1] ?? b[0] ?? 0)) / 2 : Number(b) || 0);
const scale = (pow, e) => 1 + clamp(((pow || 0) - (e.thr ?? 20)) / 150, 0, e.scaleCap ?? 1);

// ふつうの 攻撃 1回の ダメージ（守りを むしする 技・かならず 会心の 技も）
function physUnit(e) {
  if (e.forceCrit) return STD.atk;
  return Math.max(1, STD.atk / 2 - (STD.foeDfn * (1 - (e.ignoreDef || 0))) / 4);
}

// 1つの 効果の 強さ（ダメージ・回復の 量。ない ときは 0）
export function partStdPower(e) {
  if (!e) return 0;
  switch (e.type) {
    case 'multi': return (e.parts || []).reduce((s, p) => s + partStdPower(p), 0);
    case 'phys': return physUnit(e) * (e.mult ?? 1) * (e.hits > 1 ? e.hits : 1);
    case 'drainHp':
    case 'arCombo':
    case 'piInferno':
    case 'scFall':
      return physUnit(e) * (e.mult ?? 1);
    case 'magic':
    case 'deduce':
    case 'gather':
    case 'arSpell':
    case 'weatherStrike':
      if (!e.base) return 0;
      return avg(e.base) * scale(e.stat === 'heal' ? STD.heal : STD.mag, e);
    case 'heal':
      if (!e.base) return 0;
      return avg(e.base) * (e.fixed ? 1 : scale(STD.heal, e));
    // じわじわ 回復: 1回の 量 × ふつうの 回数
    case 'regen':
      if (!e.base) return 0;
      return Math.max(1, avg(e.base) * (e.fixed ? 1 : scale(STD.heal, e))) * REGEN_BASE;
    case 'mpHeal': return avg(e.base);
    case 'revive':
    case 'reviveAll':
      return STD.maxHp * (e.hpRatio || 0.25);
    // 元気玉: ふつうの 4人（HP満タン）から 集めた HP × 倍率
    case 'genki': return genkiTotal(Array(STD.party).fill(STD.partyHp), e.rate) * (e.mult || 1);
    case 'allMp': return (STD.mp + (e.paid || 0)) * (e.mult || 1);
    case 'goldThrow': return ((Number(e.base) || 50) + STD.lv * (e.perLv || 10)) * (e.mult || 1);
    default: return 0;
  }
}

// 技の ふつうの 強さ（ダメージ・回復の ない 技は 0）
export function skillStdPower(id) {
  const a = ABILITIES[id];
  if (!a?.effect) return 0;
  return Math.round(partStdPower(a.effect) * 10) / 10;
}

// 技の もとの MP（職業の ほせい なし）
export const skillStdMp = (id) => Number(ABILITIES[id]?.mp) || 0;

// 弱い じゅんに ならべた あたらしい 配列（ids は かえない）。知らない 技は さいごに（もとの じゅん）
export function sortByStdPower(ids) {
  const rows = (ids || []).map((id, i) => ({ id, i, known: !!ABILITIES[id], pow: skillStdPower(id), mp: skillStdMp(id) }));
  rows.sort((x, y) => {
    if (x.known !== y.known) return x.known ? -1 : 1;
    // ダメージ・回復の ある 技が さき
    const px = x.pow > 0, py = y.pow > 0;
    if (px !== py) return px ? -1 : 1;
    if (px && x.pow !== y.pow) return x.pow - y.pow;
    if (x.mp !== y.mp) return x.mp - y.mp;
    return x.i - y.i;
  });
  return rows.map((r) => r.id);
}

// ───────────── 第69回: お気に入りの ならびかえ（メニューの お気に入りで つかんで 十字キーで うごかす） ─────────────
// 戦いの ★の タブと おなじ わけかた（呪文 と 特技。client/battle.js の openCommand）。どちらでも ない 技は null
export function favSection(a) {
  if (!a) return null;
  if (a.kind === 'spell' || a.spellLike) return 'spell';
  if (a.kind === 'skill' || a.kind === 'monster' || a.kind === 'combo') return 'skill';
  return null;
}

// つかんだ 技を うごかす（左右: 1つ・上下: 1行〈cols こ〉。はしで とまる。となりと 入れかえる）
//   もどりち: { ids, pos }（うごかない ときは null）
export function moveInGrid(ids, pos, dir, cols = 2) {
  const d = { left: -1, right: 1, up: -cols, down: cols }[dir];
  if (!d || pos < 0 || pos >= ids.length) return null;
  const to = Math.max(0, Math.min(ids.length - 1, pos + d));
  if (to === pos) return null;
  const out = ids.slice();
  [out[pos], out[to]] = [out[to], out[pos]];
  return { ids: out, pos: to };
}

// お気に入りの ぜんぶの ならび（full）の うち、oldSec の 技の 場所に newSec の じゅんで 入れなおす
//   （呪文と 特技は おなじ 1つの 配列。かえるのは その 見出しの 中の じゅん だけ）
export function mergeSectionOrder(full, oldSec, newSec) {
  const set = new Set(oldSec);
  let k = 0;
  return (full || []).map((id) => (set.has(id) && k < newSec.length ? newSec[k++] : id));
}

js/shared/skill-tabs.js:
// 第35回 A: 戦いの 技えらびの タブ（効果ごと）。家族が 決めた こと（docs/idea-r35.md の L「戦いの技えらび」）
//   ・タブ: 今の職業／攻撃（1体）／攻撃（全体）／回復／強くする／弱くする・状態異常／そのほか（空の タブは 出さない）
//   ・お気に入りも 1つの タブ（★）。上の 技を 覚えても 下の 技は かくさない。技の ならびは かえない（今の じゅんの まま）
//   ・わかっている 弱点の 属性の 技に「弱点」の しるし（client/battle.js）
// ここは 画面に よらない きまり（テスト: test/ui-r35.test.js）

// ダメージを あたえる 効果
const DMG = new Set(['phys', 'magic', 'drainHp', 'drainMp', 'mahouken', 'telegraph', 'goldThrow', 'gamble', 'fixed', 'allMp', 'gather', 'genki', 'destroy', 'deduce']);
// 回復（HP・MP・状態・生き返る・じわじわ）
const HEAL = new Set(['heal', 'revive', 'reviveAll', 'cure', 'mpHeal', 'regen']);
// 味方を 強くする（ちから・守り・かばう・ためる など）
const BUFF = new Set(['buff', 'charge', 'cover', 'veil', 'veilCharge', 'reflect', 'stance', 'overtime']);
// 敵を 弱くする・状態異常（行動を おくらせる・強さを 消す も ここ）
const DEBUFF = new Set(['debuff', 'status', 'dispel']);

// タブの じゅんと 名前（label: タブの 札。title: 見出しに 出す 名前）
export const SKILL_TABS = [
  { id: 'fav', label: '★', title: 'お気に入り' },
  { id: 'job', label: '今の職業', title: '今の職業' },
  { id: 'one', label: '攻撃1体', title: '攻撃（1体）' },
  { id: 'all', label: '攻撃全体', title: '攻撃（全体）' },
  { id: 'heal', label: '回復', title: '回復' },
  { id: 'buff', label: '強くする', title: '強くする' },
  { id: 'debuff', label: '弱くする', title: '弱くする・状態異常' },
  { id: 'other', label: 'そのほか', title: 'そのほか' },
];

// 敵に あたる 相手か
const FOE = new Set(['enemy', 'group', 'enemies']);

// 1つの 効果が どの 種類か（dmg・heal・buff・debuff・null）。target: その 技の 相手
function partKind(p, target) {
  const t = p?.type;
  if (!t) return null;
  if (DMG.has(t)) return 'dmg';
  if (HEAL.has(t)) return 'heal';
  if (BUFF.has(t)) return 'buff';
  if (DEBUFF.has(t)) return t === 'dispel' && !FOE.has(target) ? 'heal' : 'debuff';
  // 行動ゲージ: 味方は はやく（強くする）・敵は おそく（弱くする）
  if (t === 'atbSet') return FOE.has(target) ? 'debuff' : 'buff';
  return null;
}

// 技の 効果の タブ（'one'・'all'・'heal'・'buff'・'debuff'・'other'）。今の職業・お気に入りは 別に きめる
export function effectTab(ab) {
  const e = ab?.effect;
  if (!e) return 'other';
  const target = ab.target;
  const parts = e.type === 'multi' ? (e.parts || []) : [e];
  const kinds = parts.map((p) => partKind(p, p.target || target));
  // ダメージが あれば こうげき（敵1体 → 1体、グループ・全体・ランダムに 何回も → 全体）
  if (kinds.includes('dmg')) {
    if (target === 'enemy' && !e.random) return 'one';
    if (FOE.has(target) || e.random) return 'all';
  }
  if (kinds.includes('heal')) return 'heal';
  if (kinds.includes('buff')) return 'buff';
  if (kinds.includes('debuff')) return 'debuff';
  return 'other';
}

// 技の 属性（いくつも ある 技は ぜんぶ。物理は 入れない）
export function abilityElements(ab) {
  const e = ab?.effect;
  if (!e) return [];
  const parts = e.type === 'multi' ? (e.parts || []) : [e];
  const out = [];
  for (const p of parts) if (p?.element && p.element !== 'phys' && !out.includes(p.element)) out.push(p.element);
  return out;
}

// タブごとの 技（ids の じゅんの まま。空の タブは 出さない）
//   abs: id → 技（男の子むけの 名前 など。なければ ABILITIES）。job: 今の 職業。favs: お気に入り（その ならび）
//   もどりち: [{ id, label, title, ids }]
export function skillTabs(ids, { abs, job, favs = [] } = {}) {
  const get = (id) => abs?.(id);
  const lists = { fav: favs.filter((id) => ids.includes(id)), job: [], one: [], all: [], heal: [], buff: [], debuff: [], other: [] };
  for (const id of ids) {
    const ab = get(id);
    if (!ab) continue;
    if (job && ab.job === job) lists.job.push(id);
    lists[effectTab(ab)].push(id);
  }
  return SKILL_TABS.filter((t) => lists[t.id].length).map((t) => ({ ...t, ids: lists[t.id] }));
}

// はじめに 出す タブ: まえに 使った タブ → お気に入り → 今の職業 → さいしょ
export function startTab(tabs, last) {
  if (!tabs.length) return null;
  return (tabs.find((t) => t.id === last) || tabs.find((t) => t.id === 'fav') || tabs.find((t) => t.id === 'job') || tabs[0]).id;
}

js/shared/skill-tier.js:
// 第50回 D4: 上の 職業の 技ほど 補助・回復が 強い（家族の ねがい「名前が ちがう だけで 効果が おなじ 技が 多すぎる」）
//
// 技の ランク … その 技の 職業（ABILITIES[id].job）の tier（0 基本職・1 上級職・2 超級職・3 伝説・4 幻の職業〈第51回〉）
//   ・ひらめき技 … job が ついて いるので その 職業の ランク
//   ・job の ない 技 … 覚える 職業（JOBS の learn）の いちばん 上の ランク。掛け合わせ技（combo）は 上級職から ひらめくので 1 より 下に しない
//   ・仲間の キャラの 技（ノクトの 技 など）・じゃんけんの グー など … 0
//   ・合体技 … 2（DUAL_TIER。補助の だんかい・回数だけ。回復と MP は 合体技の きまりの まま）
// 強く なるのは
//   ・補助・回復の 技（SUPPORT_TYPES を ふくみ、ダメージの 技では ない もの）だけ。ダメージの 技（おまけの デバフ つきも）は かわらない
//   ・職業の ある 人（家族・酒場の 仲間）が 使う とき だけ。魔物の 仲間・敵は かわらない（skillMods）
//
// ランクごとの こうか（TIER_MODS）
//   mpMul  … 消費MP（転職の ペナルティは この あとに かける）
//   acts   … バフ・デバフが つづく 行動の 回数
//   stages … 1回で 上がる（下がる）だんかい（上限は battle.js の BUFF_STACK・stackMult の まま）
//   healMul … 回復の 量（回復の 技・じわじわ回復・生き返らせる ときの HP）
// サーバーでも ブラウザでも つかう（stats.js の mpCost・battle.js・client/ui/skillinfo.js）
import { ABILITIES, abilityRole } from './data/abilities.js';
import { JOBS } from './data/jobs.js';
import { BUFF_ACTS } from './buff-acts.js';

export const TIER_MODS = [
  { mpMul: 1, acts: BUFF_ACTS, stages: 1, healMul: 1 },
  { mpMul: 0.9, acts: BUFF_ACTS + 1, stages: 1, healMul: 1.05 },
  { mpMul: 0.8, acts: BUFF_ACTS + 1, stages: 2, healMul: 1.1 },
  { mpMul: 0.7, acts: BUFF_ACTS + 2, stages: 2, healMul: 1.2 },
  // 第51回: 幻の職業（MP −35%・6回行動・2だんかい・回復 ×1.25）
  { mpMul: 0.65, acts: BUFF_ACTS + 3, stages: 2, healMul: 1.25 },
];
const TOP = TIER_MODS.length - 1;
export const DUAL_TIER = 2;
export const SUPPORT_TYPES = new Set(['buff', 'debuff', 'heal', 'regen', 'revive']);

// 補助・回復の 技か（multi・random は 中の こうかも 見る）
function hasSupport(e, depth = 0) {
  if (!e || depth > 3) return false;
  if (SUPPORT_TYPES.has(e.type)) return true;
  if (e.type === 'multi') return (e.parts || []).some((p) => hasSupport(p, depth + 1));
  if (e.type === 'random') return (e.options || []).some((id) => hasSupport(ABILITIES[id]?.effect, depth + 1));
  return false;
}
export function isSupportSkill(id) {
  const a = ABILITIES[id];
  return !!a && a.kind !== 'monster' && abilityRole(a) !== 'dmg' && hasSupport(a.effect);
}

// 技の id → ランク（はじめて 使う ときに 1回だけ 作る。データの 読みこみの じゅんに よらない ように）
let TIERS = null;
function build() {
  const learners = {};
  for (const j of Object.values(JOBS)) {
    for (const [, id] of j.learn || []) learners[id] = Math.max(learners[id] ?? 0, j.tier || 0);
  }
  const map = {};
  for (const [id, a] of Object.entries(ABILITIES)) {
    if (a.kind === 'monster') continue;
    let t = a.job && JOBS[a.job] ? JOBS[a.job].tier || 0 : learners[id] ?? 0;
    if (a.kind === 'combo') t = Math.max(1, t, ...(a.requires || []).map((r) => (ABILITIES[r]?.job ? JOBS[ABILITIES[r].job]?.tier || 0 : 0)));
    if (t) map[id] = Math.min(TOP, t);
  }
  return map;
}

export function skillTier(id) {
  if (!TIERS) TIERS = build();
  return TIERS[id] || 0;
}

export function tierMods(tier) {
  return TIER_MODS[Math.max(0, Math.min(TOP, tier | 0))];
}

// 職業の ある 人か（家族・酒場の 仲間。魔物の 仲間〈species〉・職業の ない 人は ちがう）
export function tierUser(char) {
  return !!char && !char.species && !!JOBS[char.job];
}

// その 人が その 技を 使う ときの こうか（職業の ない 人・補助と 回復で ない 技は いつも ランク0）
let SUP = null;
export function skillMods(char, id) {
  if (!tierUser(char)) return TIER_MODS[0];
  if (!SUP) SUP = new Map();
  if (!SUP.has(id)) SUP.set(id, isSupportSkill(id));
  return SUP.get(id) ? tierMods(skillTier(id)) : TIER_MODS[0];
}

// 戦いの 中の こうか（perform で ev.tier に 入れた もの。使った 人 本人の ときだけ。道具・敵・反撃などは ランク0）
export function evMods(c, ev) {
  return ev?.tier && ev.tier.by === c?.id ? ev.tier : TIER_MODS[0];
}

// 消費MP（ランクの ぶん へらす。もとが 1 いじょうなら 1 より 下に しない）
export function tierMp(char, id) {
  const mp = ABILITIES[id]?.mp || 0;
  if (mp < 1) return mp;
  return Math.max(1, Math.round(mp * skillMods(char, id).mpMul));
}

js/shared/skill-view.js:
// 第71回 E: メニューの「覚えた技」の 見方（家族の ねがい「一覧だと見づらすぎる」。docs/plan-r69-skill-menu.md）
//   2つの 見方を 切りかえる（client/ui/menu.js の skillsView。Y か 画面の ボタン）
//   ・種類で見る: 呪文・特技 に わけて、その 中を 戦いの 技えらびと おなじ 種類（今の職業・攻撃1体・攻撃全体・回復・強くする・弱くする・そのほか）
//   ・職業で見る: 覚えた 職業ごと（今の 職業が 先、あとは 職業の じゅん）。ひらめき・魔物の 技などは「そのほか」
//   どちらも 中は 弱い じゅん（shared/skill-sort.js）。空の タブは 出さない。タブは L・R（Q・E）で じゅんに かえる
// ここは 画面に よらない きまり（テスト: test/skill-menu-r71.test.js）
import { ALL_JOBS, JOBS } from './data/jobs.js';
import { jobAbilities } from './stats.js';
import { skillTabs } from './skill-tabs.js';
import { sortByStdPower, favSection } from './skill-sort.js';
import { jobLabel } from './job-label.js';

export const LEARN_VIEWS = { kind: '種類で見る', job: '職業で見る' };
export const LEARN_SECS = [['spell', '呪文'], ['skill', '特技']];

// 種類で見る: [{ key: 'spell:one', sec: 'spell', id, label, title, ids }]。呪文の タブが 先、つぎに 特技
//   abs: id → 技（男の子むけの 名前 など）。job: 今の 職業（「今の職業」の タブ）。★お気に入りの タブは 出さない（「お気に入り」の タブが ある）
export function learnedKindTabs(ids, { abs, job } = {}) {
  const sorted = sortByStdPower(ids);
  const secOf = (id) => favSection(abs(id)) || 'skill';
  return LEARN_SECS.flatMap(([k]) => skillTabs(sorted.filter((id) => secOf(id) === k), { abs, job })
    .filter((t) => t.id !== 'fav')
    .map((t) => ({ ...t, sec: k, key: `${k}:${t.id}` })));
}

// 職業で見る: [{ key: 'job:mage', id: 'mage', label, ids }]。今の 職業 → 職業の じゅん（ALL_JOBS）→ そのほか
//   1つの 技を いくつもの 職業で 覚えた ときは 先の タブだけに 出す
export function learnedJobTabs(char, ids) {
  const sorted = sortByStdPower(ids);
  const tabs = [];
  const owner = new Map();
  if (!char?.species) {
    const has = (j) => JOBS[j] && char?.jobs?.[j];
    const order = [char?.job, ...ALL_JOBS.filter((j) => j !== char?.job)].filter(has);
    for (const j of order) for (const id of jobAbilities(char, j)) if (!owner.has(id)) owner.set(id, j);
    for (const j of order) {
      const list = sorted.filter((id) => owner.get(id) === j);
      if (list.length) tabs.push({ key: `job:${j}`, id: j, label: jobLabel(j, char) || j, title: j === char.job ? '今の職業' : '', ids: list });
    }
  }
  const rest = sorted.filter((id) => !owner.has(id));
  if (rest.length) tabs.push({ key: 'job:other', id: 'other', label: 'そのほか', title: char?.species ? '' : 'ひらめき・ほかの技', ids: rest });
  return tabs;
}

// 前に 見た タブ（なければ 1つめ）。kind の 見方で 前の タブが ない ときは おなじ 呪文・特技の 1つめ
export function pickLearnTab(tabs, last) {
  if (!tabs.length) return null;
  const hit = tabs.find((t) => t.key === last);
  if (hit) return hit;
  const sec = String(last || '').split(':')[0];
  return tabs.find((t) => t.sec && t.sec === sec) || tabs[0];
}

// L・R: となりの タブ（はしから はしへ まわる）
export function nextLearnTab(tabs, key, d) {
  if (!tabs.length) return null;
  const i = Math.max(0, tabs.findIndex((t) => t.key === key));
  return tabs[(i + d + tabs.length) % tabs.length];
}

