// キャラクターの つよさ計算・レベルアップ・転職ペナルティ
import { gearFxStats } from './data/gear-fx.js';
import { JOBS, ALL_JOBS, JOB_MAX_LEVEL, JOB_EASY_RATE, jobBattlesForLevel, jobBases, jobAncestry, jobReqSets, jobBodyOk, superMasteredCount } from './data/jobs.js';
import { ITEMS, SLOTS, baseItemId } from './data/items.js';
import { ABILITIES, isAttackSpell, isSwordSkill } from './data/abilities.js';
import { MONSTERS } from './data/monsters.js';
import { MONSTER_FRIENDS, monsterNatural, gearOf, monsterLevelCap } from './data/companions.js';
import { ougiLearn } from './data/abilities-ougi.js';
// 第43回 A: 魔物の 育ち・ランクの 強さ（data/companions.js の rankIdx）
import { rankIdx } from './data/companions.js';
// 第44回（ポケモン P1）: レベルで 進化
import { levelEvolveTo } from './data/companions.js';
// 第53回 D: 色ちがいの 仲間（char.color。data/variants.js・data/breed-mix.js）
import { VARIANT_KINDS, kindOk, colorResist } from './data/variants.js';
import { COLOR_STAT_RATE } from './data/breed-mix.js';
import { HIRAMEKI, hiraRatio } from './data/hirameki.js';
import { cleanLook } from './data/looks.js';
import { SKILL_UPS } from './data/skill-ups.js';
import { jobLabel } from './job-label.js';
// 第50回 N3: 大事な物の すぐ使う ボタン（はじめて 手に 入れた ときに 自動で えらぶ）
import { autoQuick } from './data/quick-item.js';
// 第50回 D4: 上の 職業の 技ほど 消費MPが へる（skill-tier.js）
import { tierMp } from './skill-tier.js';
// 第38回 B: 超級職からの 職業レベルの 上限（職業の試練）と Lv11〜 の 強さ
import { jobLevelCap, jobUpStats } from './data/job-trials.js';
// 第51回 F: 幻の職業の やりこみの 条件（data/phantom.js）
import { phantomCondsMet } from './data/phantom.js';

// 長い 物語に なるので レベルは 150まで（第40回で 99 → 150。レベルで ふえる つよさは ひかえめ）
export const MAX_LEVEL = 150;
export const STAT_KEYS = ['hp', 'mp', 'str', 'def', 'agi', 'mag', 'heal'];
export const STAT_NAMES = {
  hp: '最大HP', mp: '最大MP', str: '力', def: '身の守り', agi: '素早さ',
  mag: '攻撃魔力', heal: '回復魔力', atk: '攻撃力', dfn: '守備力',
};

// レベルに必要な 累計けいけんち（EXP_RATE: レベル上げの むずかしさ。2.25 = はじめの 版の 2.25倍 ひつよう）
export const EXP_RATE = 2.25;
// レベル99より 上は、1つ 上がるのに いる 経験値が 2.5倍（第50回。家族が 決めた。99までは 前の まま）
export const HIGH_LEVEL = 99;
export const HIGH_EXP_MULT = 2.5;
const baseExp = (lv) => (lv <= 1 ? 0 : Math.round((6 * Math.pow(lv - 1, 2.5) + 6 * (lv - 1)) * EXP_RATE));
export function expForLevel(lv) {
  if (lv <= HIGH_LEVEL) return baseExp(lv);
  const b = baseExp(HIGH_LEVEL);
  return b + Math.round((baseExp(lv) - b) * HIGH_EXP_MULT);
}

// レベルごとの 基本ステータス（職業の倍率を かける前）
// レベルで ふえる ぶんは ひかえめ。職業の 得意な つよさは computeStats で レベルと いっしょに のびる（職業レベルは 少しの 補正）
export function baseStats(level) {
  const L = level - 1;
  return {
    hp: 26 + 3.6 * L + 0.015 * L * L,
    mp: 12 + 1.5 * L,
    str: 13 + 1.0 * L,
    def: 8 + 0.7 * L,
    agi: 13 + 0.9 * L,
    mag: 13 + 1.0 * L,
    heal: 13 + 1.0 * L,
  };
}

// 得意な つよさ（職業の 倍率が 1いじょうの もの）の のび。メインは キャラの レベル、職業レベルは 少しの 補正（2026年10月 第23回）
// キャラの レベル 1つで ふえる わりあい。Lv21 で 上げ止まり（1.3倍）。そのあとは 基本の つよさと 装備で のびる
export const LEVEL_AFFINITY = 0.015;
export const LEVEL_AFFINITY_MAX = 0.3;
// 職業レベル 1つで ふえる わりあい（Lv10 で 1.18倍。前は 0.05 で 1.45倍）
export const JOB_BOOST = 0.02;
// 職業の「ずっと残る ボーナス」（perLv）に かける 数
export const PER_LV_MULT = 2;
// ずっと残る ボーナスの 合計は、レベルの つよさの この わりあいまで（たくさんの 職業を きわめても 強く なりすぎない）
export const PER_LV_CAP = 0.6;
// 職業レベル 1つで ふえる、その 職業の 技の 威力
export const JOB_POWER = 0.04;

// その 技の 職業の レベルで 上がる 威力（マスターで +36%）
// 上位の 技（data/skill-ups.js。超かめはめ波 など）は、もとの 技の 職業レベルの 威力も うけつぐ（大きい ほう）
export function jobPower(char, abilityId, depth = 0) {
  const a = ABILITIES[abilityId];
  // 第38回 B: Lv11〜（職業の試練）では 威力は ふえない（Lv10 で 止まる）
  const own = !a?.job || !JOBS[a.job] || !char?.jobs ? 1 : 1 + JOB_POWER * (Math.min(JOB_MAX_LEVEL, jobLevel(char, a.job)) - 1);
  const base = SKILL_UPS[abilityId];
  return base && depth < 8 ? Math.max(own, jobPower(char, base, depth + 1)) : own;
}

export function jobLevel(char, jobId = char.job) {
  return char.jobs?.[jobId]?.lv || 1;
}

// そうびの ボーナス合計
function equipBonus(char) {
  const out = { atk: 0, dfn: 0, hp: 0, mp: 0, str: 0, def: 0, agi: 0, mag: 0, heal: 0 };
  const resist = {};
  let weaponCat = 'none';
  let onHit = null;
  let crit = 0, mpRegen = 0;
  for (const slot of SLOTS) {
    const id = char.equip?.[slot];
    if (!id) continue;
    const it = ITEMS[id];
    if (!it) continue;
    if (slot === 'weapon') {
      out.atk += it.atk || 0;
      weaponCat = it.cat;
      onHit = it.onHit || null;
    } else {
      out.dfn += it.def || 0;
    }
    if (it.bonus) for (const [k, v] of Object.entries(it.bonus)) out[k] = (out[k] || 0) + v;
    if (it.resist) for (const [k, v] of Object.entries(it.resist)) resist[k] = (resist[k] ?? 1) * v;
    // 第31回: 会心の 出やすさ・行動ごとの MP回復（レア装備。shared/battle.js）
    if (it.crit) crit += it.crit;
    if (it.mpRegen) mpRegen += it.mpRegen;
  }
  // 第65回: れん金で つけた 装備の 効果（攻撃力・守備力・HP・素早さ・会心・属性や 状態に 強い。data/gear-fx.js）
  const gx = gearFxStats(char);
  for (const [k, v] of Object.entries(gx.add)) if (v) out[k] = (out[k] || 0) + v;
  for (const [k, v] of Object.entries(gx.resist)) resist[k] = (resist[k] ?? 1) * v;
  crit += gx.crit;
  return { out, resist, weaponCat, onHit, crit, mpRegen };
}

// キャラクターの いまの つよさ
export function computeStats(char) {
  if (char.species) return monsterCompanionStats(char);
  const job = JOBS[char.job];
  const b = baseStats(char.level);
  // 第38回 B: 得意な 強さの のびは Lv10 まで（Lv11〜 は jobUpStats の +1〜2 だけ）
  const jl = Math.min(JOB_MAX_LEVEL, jobLevel(char));
  const boost = 1 + Math.min(LEVEL_AFFINITY_MAX, LEVEL_AFFINITY * (char.level - 1)) + JOB_BOOST * (jl - 1);
  const s = {};
  for (const k of STAT_KEYS) {
    const m = job.mods[k];
    let v = b[k] * m;
    if (m >= 1) v *= boost;
    s[k] = v;
  }
  // すべての職業の レベルから もらえる ずっと残るボーナス（転職しても のこる）。合計は レベルの つよさの PER_LV_CAP まで
  const perSum = {};
  for (const [jid, info] of Object.entries(char.jobs || {})) {
    const per = JOBS[jid]?.perLv;
    if (!per) continue;
    for (const [k, v] of Object.entries(per)) perSum[k] = (perSum[k] || 0) + v * PER_LV_MULT * (Math.min(JOB_MAX_LEVEL, info.lv || 1) - 1);
  }
  for (const [k, v] of Object.entries(perSum)) s[k] += Math.min(v, b[k] * PER_LV_CAP);
  // 第38回 B: 職業の試練で Lv10 より 上に なった ぶん（今の 職業の 得意な 数値が 1レベル +1〜2。data/job-trials.js）
  for (const [k, v] of Object.entries(jobUpStats(char.job, jobLevel(char)))) s[k] += v;
  // たねで ふえた ぶん
  for (const [k, v] of Object.entries(char.seeds || {})) s[k] = (s[k] || 0) + v;
  const eq = equipBonus(char);
  for (const k of STAT_KEYS) s[k] += eq.out[k] || 0;
  const r = {};
  for (const k of STAT_KEYS) r[k] = Math.max(k === 'hp' || k === 'agi' ? 1 : 0, Math.round(s[k]));
  r.maxHp = r.hp;
  r.maxMp = r.mp;
  r.atk = r.str + eq.out.atk;
  r.dfn = r.def + eq.out.dfn;
  r.weaponCat = eq.weaponCat;
  r.resist = eq.resist;
  // 職業の たいせい（ゴム人間・ニカは 雷が 効かない）
  for (const [k, v] of Object.entries(JOBS[char.job]?.passive?.resist || {})) r.resist[k] = (r.resist[k] ?? 1) * v;
  r.onHit = eq.onHit;
  r.crit = eq.crit;
  r.mpRegen = eq.mpRegen;
  return r;
}

// 第43回 A: 魔物の 育ち（人の「レベルで 得意な 強さが のびる」＋「職業の ボーナス」の かわり。魔物は 転職しないので レベルだけで のびる）
//   レベル 1つで MON_GROW ずつ。Lv51 で 1＋MON_GROW_MAX（1.6倍）で 上げ止まり
export const MON_GROW = 0.012;
export const MON_GROW_MAX = 0.6;
// ランクの 強さ（F〜★。めずらしい 魔物ほど 少し 強い。ランクは data/monster-ranks.js の「めずらしさ」）
export const RANK_MULT = [1.00, 1.02, 1.04, 1.06, 1.08, 1.10, 1.12, 1.15, 1.15];
// その 魔物の 育ちの 倍率（レベル × ランク）
export function monsterGrowMult(char) {
  const L = Math.max(1, char.level || 1);
  const r = RANK_MULT[rankIdx(char.species, MONSTERS)] ?? 1;
  return (1 + Math.min(MON_GROW_MAX, MON_GROW * (L - 1))) * r;
}

// なかまの モンスターの つよさ（しゅぞくの のびかた × レベル × 育ち ＋ からだの つよさ）
function monsterCompanionStats(char) {
  const f = MONSTER_FRIENDS[char.species] || {};
  const g = f.growth || {};
  const b = baseStats(char.level);
  const s = {};
  // はいごうの「＋」と おやから うけついだ つよさ
  const plus = 1 + Math.min(99, char.plus || 0) * 0.01;
  // 第43回 A: 育ち（レベル × ランク）
  const grow = monsterGrowMult(char);
  // 第53回 D: 色ちがいの 仲間は 色ちがいの 倍率の 半分だけ 強い（1.3 → 1.15）
  const vk = kindOk(char.color) ? VARIANT_KINDS[char.color].k : {};
  const ck = (k) => 1 + ((vk[k] ?? 1) - 1) * COLOR_STAT_RATE;
  for (const k of STAT_KEYS) s[k] = b[k] * (g[k] ?? 1) * plus * grow * ck(k) + (char.bonus?.[k] || 0);
  for (const [k, v] of Object.entries(char.seeds || {})) s[k] = (s[k] || 0) + v;
  const eq = equipBonus(char);
  for (const k of STAT_KEYS) s[k] += eq.out[k] || 0;
  const r = {};
  for (const k of STAT_KEYS) r[k] = Math.max(k === 'hp' || k === 'agi' ? 1 : 0, Math.round(s[k]));
  // からだの つよさにも 同じ 育ちを かける（第43回 A）
  const nat = monsterNatural(char.level, grow);
  r.mag += Math.round(nat.mag * (g.mag ?? 1));
  r.heal += Math.round(nat.heal * (g.heal ?? 1));
  r.maxHp = r.hp;
  r.maxMp = r.mp;
  // からだの つよさ ＋ 装備（武器の 攻撃力・よろい・たて・かぶとの 守備力）
  r.atk = Math.round(r.str + nat.atk + eq.out.atk);
  r.dfn = Math.round(r.def + nat.dfn + eq.out.dfn);
  // 武器を もっていれば その 種類（剣の 技などが つかえる）。もっていなければ 'none'（こぶしの 技は つかえる）
  r.weaponCat = eq.weaponCat;
  // しゅぞくの たいせい（つよすぎない ように ぞくせいは 0.3まで）
  // 第53回 D: 色ちがいの 仲間は 色ちがいの 属性（レッド … 火に 強く 氷に 弱い など）
  const base = colorResist(f.resist || MONSTERS[char.species]?.resist, char.color);
  const res = {};
  for (const [k, v] of Object.entries(base)) res[k] = ['fire', 'ice', 'water', 'wind', 'blast', 'bolt', 'light', 'dark', 'void'].includes(k) ? Math.max(0.3, v) : v;
  for (const [k, v] of Object.entries(eq.resist)) res[k] = (res[k] ?? 1) * v;
  r.resist = res;
  // 毒のナイフ など（武器の おまけ）
  r.onHit = eq.onHit;
  // 第45回: しゅぞくの 会心の 出やすさ（ひとくい箱。data/companions-dqm.js の crit）
  r.crit = eq.crit + (f.crit || 0);
  r.mpRegen = eq.mpRegen;
  return r;
}

// なかまの モンスターが おぼえている わざ
export function monsterAbilities(char) {
  const f = MONSTER_FRIENDS[char.species];
  const out = f ? f.learn.filter(([l, id]) => l <= char.level && ABILITIES[id]).map(([, id]) => id) : [];
  // はいごうで おやから うけついだ わざ
  for (const id of char.inherit || []) if (ABILITIES[id] && !out.includes(id)) out.push(id);
  // 第43回 B: 系統の 奥義（Lv30・45・60。data/abilities-ougi.js）
  for (const [l, id] of ougiLearn(MONSTERS[char.species]?.race)) if (l <= char.level && ABILITIES[id] && !out.includes(id)) out.push(id);
  return out;
}

// 職業ごとに おぼえている 技
export function jobAbilities(char, jobId) {
  const lv = jobLevel(char, jobId);
  return JOBS[jobId].learn.filter(([l]) => l <= lv).map(([, id]) => id);
}

// おぼえている 技 すべて（職業で 覚えた 技 ＋ ひらめいた 技）
export function learnedAbilities(char) {
  if (char.species) return monsterAbilities(char);
  const set = new Set();
  for (const jid of ALL_JOBS) {
    if (!char.jobs?.[jid]) continue;
    for (const id of jobAbilities(char, jid)) set.add(id);
  }
  for (const id of Array.isArray(char.hirameki) ? char.hirameki : []) if (ABILITIES[id]) set.add(id);
  return [...set];
}

// むかしの きまり（もとの 技を 両方 覚えたら 掛け合わせ技を 覚える）で 覚えていた 掛け合わせ技。
// セーブの ひきつぎで、今までの キャラの 技を なくさない ために 使う
export function comboUnlocked(char, id, learnedSet) {
  const a = ABILITIES[id];
  if (!a || a.kind !== 'combo') return false;
  const known = learnedSet || new Set(learnedAbilities(char));
  if (!a.requires.every((r) => known.has(r))) return false;
  if (a.reqJobLv) {
    for (const [jid, lv] of Object.entries(a.reqJobLv)) if (jobLevel(char, jid) < lv) return false;
  }
  return true;
}

export function oldComboUnlocks(char) {
  if (!char || char.species) return [];
  const set = new Set(learnedAbilities(char));
  return Object.keys(ABILITIES).filter((id) => ABILITIES[id].kind === 'combo' && comboUnlocked(char, id, set));
}

// その 技を 今 ひらめける 職業か（char: { job, jobs }）
//   掛け合わせ技 … もとの 職業を 合わせ持つ 上級職から（＋職業レベルの じょうけん）
//   職業の ひらめき技 … その 職業か、その 職業から 進んだ 職業
export function hiraAllowed(char, id) {
  const a = ABILITIES[id];
  if (!a || !HIRAMEKI[id] || !char?.job || !JOBS[char.job]) return false;
  if (a.kind === 'combo') {
    if (!comboAllowed(char, id)) return false;
    for (const [jid, lv] of Object.entries(a.reqJobLv || {})) if (jobLevel(char, jid) < lv) return false;
    return true;
  }
  return a.job ? jobAncestry(char.job).has(a.job) : true;
}

// ───── 今の パーティーに 関係する ひらめき技 ─────
// ひらめき技の 一覧（メニューの「ひらめき」・ひらめきの賢者）には、まだ ひらめいていない 技は
// 今の パーティーの 職業に 関係する ものだけ 出す（ぜんぶ 出すと 多すぎて わからなく なる）。ひらめいた 技は いつも 出す。
// パーティーの 職業（partyJobSet）… いっしょに 戦う 人（自分・家族・仲間。馬車の 仲間は 入れない）の
//   今の 職業と、そこに いたるまでの 職業（jobAncestry）と、マスターした 職業
// 関係する（hiraRelated）… その 技を ひらめく 職業（job）か、元に なる 技（from）の 職業が パーティーの 職業に ある
// chars: [{ job, jobs?, mjobs? }]（mjobs … マスターした 職業の id の ならび。jobs が とどかない 家族の キャラ）
export function partyJobSet(chars) {
  const set = new Set();
  for (const c of chars || []) {
    if (!c || c.species || !JOBS[c.job]) continue;
    for (const j of jobAncestry(c.job)) set.add(j);
    for (const j of Object.keys(c.jobs || {})) if (JOBS[j] && jobLevel(c, j) >= JOB_MAX_LEVEL) set.add(j);
    for (const j of c.mjobs || []) if (JOBS[j]) set.add(j);
  }
  return set;
}

// マスターした 職業の id（家族の キャラの ぶんを パーティーの みんなへ おくる。world/party.js）
export function masteredJobs(char) {
  return Object.keys(char?.jobs || {}).filter((j) => JOBS[j] && jobLevel(char, j) >= JOB_MAX_LEVEL);
}

export function hiraRelated(id, jobSet) {
  const a = ABILITIES[id], h = HIRAMEKI[id];
  if (!a || !h) return false;
  if (a.job && jobSet.has(a.job)) return true;
  return Object.keys(h.from).some((k) => jobSet.has(ABILITIES[k]?.job));
}

// その 人の ひらめきの 一覧に 出す 技（ひらめいた 技 ＋ パーティーに 関係する 技）。ならびは HIRAMEKI の じゅん
export function hiraVisible(char, jobSet) {
  const known = new Set(learnedAbilities(char));
  return Object.keys(HIRAMEKI).filter((id) => ABILITIES[id] && (known.has(id) || hiraRelated(id, jobSet)));
}

// 第32回: メニューの「ひらめき」の 一覧は、その 人が 今 ついている 職業の ひらめき技だけ（ひらめいた 技も、ほかの 職業の ものは 出さない）
//   職業の ひらめき技 … 技の 職業（a.job）が 今の 職業 / 掛け合わせ技 … 今の 職業で ひらめける もの（comboAllowed）
//   魔物の 仲間・職業の ない 人は なし。ならびは HIRAMEKI の じゅん
export function hiraOfJob(char) {
  if (!char || char.species || !JOBS[char.job]) return [];
  return Object.keys(HIRAMEKI).filter((id) => {
    const a = ABILITIES[id];
    if (!a) return false;
    return a.kind === 'combo' ? comboAllowed(char, id) : a.job === char.job;
  });
}

// ひらめきの すすみぐあい（0〜1。1 で ひらめける）
export function hiraProgress(char, id) {
  const h = HIRAMEKI[id];
  return h ? Math.min(1, hiraRatio(char?.skillUse, h.from)) : 0;
}

// 掛け合わせ技の もとになる 職業
export function comboJobs(id) {
  const a = ABILITIES[id];
  if (!a?.requires) return [];
  return [...new Set(a.requires.map((r) => ABILITIES[r]?.job).filter(Boolean))];
}

// 掛け合わせ技の もとになる 基本職（例: 魔法剣 → 戦士・魔法使い）
export function comboBaseJobs(id) {
  const out = [];
  for (const j of comboJobs(id)) for (const b of jobBases(j)) if (!out.includes(b)) out.push(b);
  return out;
}

// 掛け合わせ技は、もとに なった 職業を ぜんぶ あわせもつ 上級職いじょうで ないと つかえない
// （例: 魔法剣は 魔法戦士・竜の騎士…、メドロは 賢者・魔法戦士・忍者・占い師…）
export function comboAllowed(char, id) {
  const a = ABILITIES[id];
  if (!a || a.kind !== 'combo') return true;
  const j = JOBS[char.job];
  if (!j || !j.tier) return false;
  const have = jobBases(char.job);
  return comboBaseJobs(id).every((b) => have.includes(b));
}

// その 掛け合わせ技が つかえる 上級職の なまえ
// who: 見ている キャラ（職業の 名前を その 人 むけに。job-label.js）
export function comboJobNames(id, who = null) {
  const need = comboBaseJobs(id);
  return ALL_JOBS.filter((j) => JOBS[j].tier === 1 && need.every((b) => jobBases(j).includes(b))).map((j) => jobLabel(j, who));
}

// ぶきの じょうけん
export function weaponOk(ability, weaponCat) {
  if (!ability.weapon) return true;
  if (ability.weapon === 'blade') return ['sword', 'dagger', 'axe'].includes(weaponCat);
  if (ability.weapon === 'fist') return weaponCat === 'claw' || weaponCat === 'none';
  return ability.weapon === weaponCat;
}

// たたかいで 今の 職業・ぶきの まま つかえる 技か（MP・ふういん など その ときの ぐあいは みない）
//   フィールドだけの 呪文・きずな技・かくれた 技・今の 職業で だせない 掛け合わせ技・ぶきが あわない 技は つかえない。
//   たたかいの コマンドには つかえる 技だけ 出す（client/battle.js）。サーバーの たしかめ（battle.js の validate）も おなじ
export function battleAbilityOk(char, id, weaponCat) {
  const a = ABILITIES[id];
  if (!a || a.fieldOnly || a.hidden || a.kind === 'bond') return false;
  if (a.kind === 'combo' && !comboAllowed(char || {}, id)) return false;
  return weaponOk(a, weaponCat);
}

// 転職ペナルティ
// いまの職業 以外で おぼえた 技を つかうと MPが ふえたり いりょくが さがったりする
export function penaltyFor(char, abilityId) {
  const p = basePenalty(char, abilityId);
  const jp = jobPower(char, abilityId);
  return jp === 1 ? p : { ...p, powMult: p.powMult * jp, jobPow: jp };
}

// 本職で ない 技の ペナルティ（職業レベルの 威力を かける まえ）
function basePenalty(char, abilityId) {
  const a = ABILITIES[abilityId];
  const none = { mpMult: 1, powMult: 1, penalized: false, label: '' };
  if (!a) return none;
  const cur = char.job;
  const curJob = JOBS[cur];
  if (!curJob) return none; // モンスターの なかまは じぶんの わざを そのまま つかえる
  // 掛け合わせ技は つかえる 職業なら そのまま（つかえるかは comboAllowed）
  if (a.kind === 'bond' || a.kind === 'monster' || a.kind === 'combo') return none;
  if (!a.job || a.job === cur) return none;
  // いまの 職業に なるまでに とおった 職業の わざも そのまま（バトルマスターの 大地斬 など）
  if (jobAncestry(cur).has(a.job)) return none;
  const origin = JOBS[a.job];
  const light = curJob.versatile || origin.family === curJob.family;
  let mpMult, powMult;
  if (a.kind === 'spell') {
    mpMult = light ? 1.25 : 1.5;
    powMult = light ? 0.9 : 0.75;
  } else {
    mpMult = light ? 1.0 : 1.25;
    powMult = light ? 0.85 : 0.7;
  }
  // もとの職業を マスターしている（レベル10）と ペナルティが はんぶんに
  const mastered = jobLevel(char, a.job) >= JOB_MAX_LEVEL;
  if (mastered) {
    mpMult = 1 + (mpMult - 1) / 2;
    powMult = 1 - (1 - powMult) / 2;
  }
  const pct = Math.round(powMult * 100);
  const label = `${jobLabel(a.job, char)}の技：MP${mpMult === 1 ? 'そのまま' : mpMult + '倍'}・威力${pct}%${mastered ? '（マスターしたので軽め）' : ''}`;
  return { mpMult, powMult, penalized: true, label };
}

export function mpCost(char, abilityId) {
  const a = ABILITIES[abilityId];
  if (!a) return 0;
  const p = penaltyFor(char, abilityId);
  return Math.ceil(tierMp(char, abilityId) * p.mpMult);
}

// 魔法剣の くみあわせ（こうげき呪文 × 剣技）
export function mahoukenOptions(char, learned = learnedAbilities(char)) {
  if (!learned.includes('mahouken')) return [];
  // 1体を ねらう こうげき呪文 × 戦士の けんわざ
  const spells = learned.filter((id) => isAttackSpell(id) && ABILITIES[id].target === 'enemy');
  const skills = learned.filter((id) => isSwordSkill(id) && ABILITIES[id].job === 'warrior' && ABILITIES[id].target === 'enemy');
  const out = [];
  for (const sp of spells) {
    for (const sk of skills) {
      out.push({
        spell: sp, skill: sk,
        name: ABILITIES[sp].name + ABILITIES[sk].name,
        mp: mpCost(char, sp) + mpCost(char, sk),
      });
    }
  }
  return out;
}

// そうびできるか
export function canEquip(jobId, itemId) {
  // きたえた 装備（+1〜+3）は もとの 装備と おなじ 職業が 装備できる
  const it = ITEMS[baseItemId(itemId)];
  const job = JOBS[jobId];
  if (!it || !job) return false;
  switch (it.type) {
    // 第53回: 第6章クリアの 幻の職業むけの 武器（phantomOk）は、幻の職業（tier 4）なら しゅるいに かかわらず 装備できる
    case 'weapon': return job.weapons.includes(it.cat) || (!!it.phantomOk && (job.tier || 0) >= 4);
    case 'armor': return job.armor.includes(it.armorType);
    case 'shield': return !!job.shield;
    case 'head': return !it.helm || !!job.helm;
    // 第44回: かわらずのいし（魔物だけ。monsterOnly）
    case 'acc': return !it.monsterOnly;
    default: return false;
  }
}

// モンスターの なかまが 装備できる 物（しゅぞくの けいの きまり ＋ しゅぞくごとの うわがき。companions.js の RACE_GEAR）
//   { weapons: [武器の 種類], armor: [よろいの 種類], shield: true/false, head: false/'hat'/'helm' }
export function monsterGear(species) {
  return gearOf(species, MONSTERS[species]?.race);
}

// その まものが そうびできるか（アクセサリーは だれでも）
export function canEquipMonster(species, itemId) {
  // きたえた 装備（+1〜+3）は もとの 装備で きめる（canEquip と おなじ）
  const it = ITEMS[baseItemId(itemId)];
  if (!it) return false;
  if (it.type === 'acc') return true;
  const g = monsterGear(species);
  switch (it.type) {
    case 'weapon': return g.weapons.includes(it.cat);
    case 'armor': return g.armor.includes(it.armorType);
    case 'shield': return !!g.shield;
    // ぼうし（helm でない 物）は 'hat' でも 'helm' でも。かぶとは 'helm' だけ
    case 'head': return g.head === 'helm' || (g.head === 'hat' && !it.helm);
    default: return false;
  }
}

// その まものが つかえる 装備の 部位（そうびできない 部位は メニューに 出さない）
export function monsterSlots(species) {
  const g = monsterGear(species);
  const ok = { weapon: g.weapons.length > 0, armor: g.armor.length > 0, shield: !!g.shield, head: !!g.head, acc: true };
  return SLOTS.filter((s) => ok[s]);
}

// その キャラクターが そうびできるか（モンスターの なかまは しゅぞくで きまる）
export function canEquipChar(char, itemId) {
  if (char.species) return canEquipMonster(char.species, itemId);
  return canEquip(char.job, itemId);
}

