// れん金がま（第32回 C）の うごき。きまりは data/alchemy.js
//   forgePotGift … かじ屋で かまを もらう・親方が レシピを 1つ 教えて くれる（world/forge.js の forgeInfo）
//   alchemyAction … かまの そうさ（svc の kind 'alchemy'。status・put）
//   alchemySteps … 歩くと できあがりに 近づく（world.js の onMove。マスが かわった ときの 歩数）
//   alchemyShelf … 本だなで れん金の 本を 読む（world.js の searchTile）
//   useAlchemyMemo … れん金のメモを 使う（services.js の useItem）
//   alchemyMemoLoot … フィールドの 宝箱に メモが 入っている ことが ある（world/fieldchests.js）
//   repairAlchemy・mergeAlchemy … セーブを ととのえる・データ合わせ
import { ITEMS, baseItemId } from '../data/items.js';
import { addItem, removeItem, itemCount, ownsItem } from '../stats.js';
import {
  ALCHEMY_POT, ALCHEMY_MEMO, POT_FLAG, STARTER_RECIPES, KEEPER_RECIPES, MERGE_RECIPE, CAP_UP_MAX, LB_MAX, RECIPE_BY_ID,
  hasPot, matchPot, learnableRecipes, knowsRecipe, insText, capUp, POT_FAST_JOBS, POT_FAST_RATE,
} from '../data/alchemy.js';
import { partyOf } from './party.js';
import { GEAR_FX, fxBlock, fxMatsOf, rollFx, fxListOf, mergeFx, fxSlots, fxText } from '../data/gear-fx.js';
import { bossRareOf } from '../data/rare-loot.js';

// 本だなの きろくの 数（多すぎる ときは 古い ものから わすれる）
const SHELF_MAX = 400;

function rec(c) {
  if (!c.alchemy || typeof c.alchemy !== 'object' || Array.isArray(c.alchemy)) c.alchemy = {};
  return c.alchemy;
}
// レシピを 覚える（新しく 覚えたら true）
export function learnRecipe(c, id) {
  if (!RECIPE_BY_ID[id]) return false;
  const a = rec(c);
  if (!Array.isArray(a.known)) a.known = [];
  if (a.known.includes(id)) return false;
  a.known.push(id);
  return true;
}
const ownFlags = (c) => (f) => !!c?.flags?.[f];
// 同じ 章の 中から 1つ（早い 章を 先に）
function pickLearnable(list, rng) {
  if (!list.length) return null;
  const t = list[0].tier;
  const same = list.filter((r) => r.tier === t);
  return rng ? rng.pick(same) : same[0];
}
const recipeLine = (r) => `「${insText(r.ins)}」で、${ITEMS[r.out].name}ができる`;

// ───────────── かじ屋で もらう・教わる ─────────────
// かまを もらう（カモメ港に 着いた あと。どの かじ屋でも）。もう 持っていれば、その 親方の レシピを 1つ 教わる
// かえす: { gift?: もらった ときの 文, tip?: 教わった ときの 文 }
export function forgePotGift(world, s, place) {
  const c = s.char;
  if (!c) return {};
  if (!hasPot(c)) {
    if (!c.flags?.[POT_FLAG]) return {};
    addItem(c, ALCHEMY_POT, 1);
    for (const id of STARTER_RECIPES) learnRecipe(c, id);
    world.sendSelf(s);
    world.markDirty();
    return {
      gift: 'おっと、そうだ。これを持っていけ。\nむかし使っていた「れん金がま」だ。\n装備や道具を入れて歩くと、新しい物ができる。',
      giftNote: `${c.name}は、れん金がまを手に入れた！\n（メニューの「道具」のいちばん上から使える）`,
    };
  }
  // 第36回: 生まれ変わりの 武器の レシピを 先に
  const list = learnableRecipes(c, ownFlags(c), KEEPER_RECIPES[place] || []);
  const reborn = list.filter((x) => x.reborn);
  const r = pickLearnable(reborn.length ? reborn : list, null);
  if (!r) return {};
  learnRecipe(c, r.id);
  world.sendSelf(s);
  world.markDirty();
  return { tip: `そうだ、れん金のコツを1つ教えよう。\n${recipeLine(r)}ぞ。` };
}

// ───────────── れん金術師が いると 歩数が 半分（第33回） ─────────────
// いっしょに 歩いている パーティー（自分・家族・仲間）で、れん金術師の 系統に 今 ついている 人（いなければ null）
export function potHelper(world, s) {
  const chars = [s?.char];
  const p = world?.parties && s ? partyOf(world, s) : null;
  if (p) {
    for (const sid of p.members || []) chars.push(world.sessions?.get(sid)?.char);
    for (const x of p.supports || []) chars.push(x?.char);
  }
  return chars.find((c) => c && !c.species && POT_FAST_JOBS.includes(c.job)) || null;
}
// 1歩で 何歩ぶん 進むか（れん金術師が いれば POT_FAST_RATE）
export function potRate(world, s) {
  return potHelper(world, s) ? POT_FAST_RATE : 1;
}

// ───────────── かまの そうさ ─────────────
// 画面に 出す かまの ようす（できる 物の 名前は、知っている レシピ だけ）。rate … potRate（のこりの 歩数を その ぶん へらして 見せる）
export function potView(c, rate = 1) {
  const p = c?.alchemy?.pot;
  if (!p || !ITEMS[p.out]) return null;
  return { out: p.out, left: Math.max(1, Math.ceil(p.left / (rate || 1))), merge: p.merge || null, lb: p.lb || null, known: p.recipe === MERGE_RECIPE || knowsRecipe(c, p.recipe), ins: p.ins || [] };
}

// reply(ok, text, extra)
export function alchemyAction(world, s, msg, reply, { ownChar = () => null } = {}) {
  const c = s.char;
  if (!hasPot(c)) return reply(false, 'れん金がまを持っていない。');
  switch (msg.action) {
    case 'status': return reply(true, '', { pot: potView(c, potRate(world, s)) });
    // 第64回 ⑥c・第65回: 装備に 効果を つける（すぐ できる。効果は ランダム。data/gear-fx.js）
    case 'enchant': {
      if (s.busy) return reply(false, '今はできない。');
      const who = msg.who && msg.who !== 'self' ? ownChar(String(msg.who)) : c;
      const slot = String(msg.slot || '');
      if (!who) return reply(false, 'うまくいかなかった。');
      const id = who.equip?.[slot];
      if (!id) return reply(false, 'その場所には、何も装備していない。');
      const block = fxBlock(id);
      if (block) return reply(false, block);
      const mats = fxMatsOf(id);
      const lack = mats.filter(([m, n]) => itemCount(c, m) < n);
      if (lack.length) return reply(false, `素材が足りない。\n（${lack.map(([m, n]) => `${ITEMS[m].name}があと${n - itemCount(c, m)}こ`).join('・')}）`, { lack: lack.map(([m, n]) => ({ id: m, need: n, have: itemCount(c, m) })) });
      for (const [m, n] of mats) removeItem(c, m, n);
      const base = baseItemId(id);
      const roll = rollFx(world.rng, id);
      const now = fxListOf(who, id);
      const r = mergeFx(now, roll, fxSlots(who, id));
      const head = `れん金がまが、ふしぎな光につつまれた…！\n${who.name}の${ITEMS[base].name}に、`;
      if (r.kind === 'full') {
        // いっぱい: 入れかえるか 前の ままか えらぶ（enchantPick）
        rec(c).fxPending = { who: msg.who || 'self', slot, base, roll };
        world.markDirty();
        return reply(true, `${head}${fxText(roll.k, roll.v)}の力が生まれた！\n（効果はもういっぱい。入れかえるか、前のままにするか選ぼう）`, { fxRoll: roll, fxNow: now, fxChoose: true });
      }
      if (!who.gearFx || typeof who.gearFx !== 'object') who.gearFx = {};
      who.gearFx[base] = r.list;
      if (who !== c) world.sendParty(partyOf(world, s));
      world.markDirty();
      const got = r.list.find((x) => x.k === roll.k);
      const text = r.kind === 'up' ? `${GEAR_FX[roll.k].name}の力がかさなった！\n${fxText(got.k, got.v)}（+${roll.v}）` : `${fxText(roll.k, roll.v)}の力がやどった！`;
      return reply(true, head + text, { fxRoll: roll, fxNow: r.list, fxKind: r.kind });
    }
    // 第65回: 効果が いっぱいの とき: 入れかえる（replace … 入れかえる 効果の 番号）か 前の まま（-1）
    case 'enchantPick': {
      const p = c.alchemy?.fxPending;
      if (!p) return reply(false, '選ぶ効果はない。');
      delete c.alchemy.fxPending;
      const who = p.who && p.who !== 'self' ? ownChar(String(p.who)) : c;
      const id = who?.equip?.[p.slot];
      if (!who || !id || baseItemId(id) !== p.base) return reply(false, '装備がかわったので、生まれた力は消えてしまった。');
      const i = Number(msg.replace);
      const list = fxListOf(who, id);
      if (!Number.isInteger(i) || i < 0 || i >= list.length) {
        world.markDirty();
        return reply(true, `生まれた${GEAR_FX[p.roll.k].name}の力は消えた。\n（前の効果のまま）`, { fxNow: list });
      }
      const old = list[i];
      list[i] = { ...p.roll };
      if (!who.gearFx || typeof who.gearFx !== 'object') who.gearFx = {};
      who.gearFx[p.base] = list;
      if (who !== c) world.sendParty(partyOf(world, s));
      world.markDirty();
      return reply(true, `${GEAR_FX[old.k].name}の力が消えて、\n${fxText(p.roll.k, p.roll.v)}の力がやどった！`, { fxNow: list });
    }
    case 'put': {
      if (s.busy) return reply(false, '今はできない。');
      if (c.alchemy?.pot) return reply(false, 'れん金がまの中では、まだ何かが完成するのを待っている。', { pot: potView(c, potRate(world, s)) });
      const ids = Array.isArray(msg.ids) ? msg.ids.filter((x) => typeof x === 'string').slice(0, 4) : [];
      if (ids.length < 2) return reply(false, '2つ以上入れよう。');
      if (ids.length > 3) return reply(false, '入れられるのは3つまで。');
      // ふくろに あるか（同じ 物を 2つ 入れる ときは 2つ いる）
      const need = new Map();
      for (const id of ids) need.set(id, (need.get(id) || 0) + 1);
      for (const [id, n] of need) if (!ITEMS[id] || ITEMS[id].type === 'key' || itemCount(c, id) < n) return reply(false, 'ふくろに入っていない物がある。');
      const m = matchPot(ids, c);
      if (!m.ok) {
        if (m.why === 'shop') return reply(false, `${ITEMS[baseItemId(ids[0])].name}は店の品（★1）なので、\n2つ合わせても、きたえられる回数はふえない。\n（入れた物は、ふくろにもどした）`);
        if (m.why === 'capMax') return reply(false, `${ITEMS[baseItemId(ids[0])].name}は、もうこれ以上きたえられる回数をふやせない。\n（ふやせるのは${CAP_UP_MAX}回まで。\n上限まできたえた物を2つ入れると、限界とっぱできる）`);
        if (m.why === 'lbMax') return reply(false, `${ITEMS[baseItemId(ids[0])].name}は、もう★${LB_MAX}まで限界とっぱしている。\n（入れた物は、ふくろにもどした）`);
        if (m.why === 'rebirth') return reply(false, `${ITEMS[baseItemId(ids[0])].name}は、生まれ変わる武器なので、\n限界とっぱはできない。\n（入れた物は、ふくろにもどした）`);
        return reply(false, `${insText(ids)}…\nこの組み合わせは、うまくいきそうにない。\n（入れた物は、ふくろにもどした）`);
      }
      for (const [id, n] of need) removeItem(c, id, n);
      const known = m.recipe === MERGE_RECIPE || knowsRecipe(c, m.recipe);
      rec(c).pot = { out: m.out, recipe: m.recipe, left: m.steps, ins: ids, ...(m.merge ? { merge: m.merge } : {}), ...(m.lb ? { lb: m.lb } : {}) };
      const name = ITEMS[m.out].name;
      // 第33回: れん金術師が いると 歩数が 半分
      const helper = potHelper(world, s);
      const rate = helper ? POT_FAST_RATE : 1;
      const steps = Math.ceil(m.steps / rate);
      let text;
      if (m.lb) text = `${insText(ids)}を、れん金がまに入れた！\nあと${steps}歩ほど歩くと、\n${ITEMS[m.merge].name}が限界とっぱする。（★${m.lb}）`;
      else if (m.merge) text = `${insText(ids)}を、れん金がまに入れた！\nあと${steps}歩ほど歩くと、\n${ITEMS[m.merge].name}のきたえられる回数がふえる。`;
      else if (known) text = `${insText(ids)}を、れん金がまに入れた！\nあと${steps}歩ほど歩くと、${name}ができる。`;
      else text = `${insText(ids)}を、れん金がまに入れた！\n…うまくいきそうだ！\nあと${steps}歩ほど歩くと、何かができる。`;
      if (helper) text += `\n（${helper.name}のれん金術で、歩数が半分！）`;
      world.markDirty();
      return reply(true, text, { pot: potView(c, rate), steps });
    }
    default: return reply(false, '');
  }
}

// ───────────── 歩くと できあがる ─────────────
// n … 前の マスから 何マス 動いたか（world.js の onMove）。空を 飛んでいる 間は 数えない
export function alchemySteps(world, s, n) {
  const c = s?.char;
  const p = c?.alchemy?.pot;
  if (!p || !(n > 0) || s.flying) return false;
  // 第33回: れん金術師が パーティーに いると 1歩で 2歩ぶん
  p.left = (Number(p.left) || 0) - n * potRate(world, s);
  world.markDirty();
  if (p.left > 0) return false;
  finishPot(world, s);
  return true;
}

// できあがり: ふくろに 入れて、知らせる
export function finishPot(world, s) {
  const c = s.char;
  const p = c.alchemy?.pot;
  if (!p) return null;
  delete c.alchemy.pot;
  const it = ITEMS[p.out];
  if (!it) return null;
  addItem(c, p.out, 1);
  let text;
  if (p.lb) {
    text = `れん金がまが、まばゆく光った…！\n${it.name}が完成した！\n限界とっぱ！${p.lb === 1 ? '\nれん金の効果を2つつけられるようになった。' : ''}\n（ふくろに入れた）`;
  } else if (p.merge) {
    const a = rec(c);
    a.cap = a.cap && typeof a.cap === 'object' ? a.cap : {};
    a.cap[p.merge] = Math.min(CAP_UP_MAX, capUp(c, p.merge) + 1);
    text = `れん金がまで\n${it.name}が完成した！\n${ITEMS[p.merge].name}は、きたえられる回数が1ふえた！\n（ふくろに入れた）`;
  } else {
    const fresh = learnRecipe(c, p.recipe);
    text = `れん金がまで\n${it.name}が完成した！\n（ふくろに入れた）${fresh ? '\n新しいレシピを覚えた！' : ''}`;
  }
  world.send(s, { t: 'toast', text, sfx: 'sparkle', afterBattle: true });
  world.sendSelf(s);
  world.markDirty();
  return { out: p.out, text };
}

// ───────────── 本だな・メモ・宝箱 ─────────────
// 本だなを 調べた（key: 'マップ:x:y'）。かまを 持っていて、まだ 読んでいない 本だなで、わかる レシピが あれば 1つ
// かえす: runSteps に わたす steps か null（ふつうの 本だなと おなじ）
export function alchemyShelf(world, s, key) {
  const c = s.char;
  if (!hasPot(c)) return null;
  const a = rec(c);
  if (!Array.isArray(a.shelves)) a.shelves = [];
  if (a.shelves.includes(key)) return null;
  const r = pickLearnable(learnableRecipes(c, ownFlags(c)), world.rng);
  if (!r) return null;
  a.shelves.push(key);
  if (a.shelves.length > SHELF_MAX) a.shelves.splice(0, a.shelves.length - SHELF_MAX);
  learnRecipe(c, r.id);
  world.sendSelf(s);
  world.markDirty();
  return [['sfx', 'item'], ['say', null, `本だなに、れん金の本があった！\n${recipeLine(r)}らしい。\n新しいレシピを覚えた！`]];
}

// れん金のメモを 使う（わかる レシピが ない ときは へらない）
export function useAlchemyMemo(world, s, id, reply) {
  const c = s.char;
  const r = pickLearnable(learnableRecipes(c, ownFlags(c)), world.rng);
  if (!r) return reply(false, 'れん金のメモを読んだ。\nでも、もう知っていることばかりだ。');
  removeItem(c, id, 1);
  learnRecipe(c, r.id);
  return reply(true, `れん金のメモを読んだ。\n${recipeLine(r)}らしい！\n新しいレシピを覚えた！`);
}

// フィールドの 宝箱（かまを 持っていて、わかる レシピが 残っている 人だけ。6回に 1回）
export const MEMO_CHEST_RATE = 1 / 6;
export function alchemyMemoLoot(c, rng) {
  if (!hasPot(c) || !learnableRecipes(c, ownFlags(c)).length) return null;
  return rng.chance(MEMO_CHEST_RATE) ? { item: ALCHEMY_MEMO, n: 1 } : null;
}

// ───────────── セーブ ─────────────
const str = (v) => typeof v === 'string';
// こわれた 形を なおす（なんど よんでも おなじ）。第32回: もう たおした 物語の ボスの 品（かならず 落とす ように なった）を わたす
export function repairAlchemy(c) {
  if (!c || typeof c !== 'object') return;
  if (c.alchemy !== undefined) {
    const a = c.alchemy;
    if (!a || typeof a !== 'object' || Array.isArray(a)) delete c.alchemy;
    else {
      if (a.known !== undefined) a.known = Array.isArray(a.known) ? [...new Set(a.known.filter((id) => str(id) && RECIPE_BY_ID[id]))] : [];
      if (a.shelves !== undefined) a.shelves = Array.isArray(a.shelves) ? [...new Set(a.shelves.filter(str))].slice(-SHELF_MAX) : [];
      if (a.cap !== undefined) {
        const cap = {};
        if (a.cap && typeof a.cap === 'object') for (const [id, n] of Object.entries(a.cap)) if (ITEMS[id] && Number.isInteger(n) && n > 0) cap[id] = Math.min(CAP_UP_MAX, n);
        a.cap = cap;
      }
      const p = a.pot;
      if (p !== undefined && (!p || typeof p !== 'object' || !ITEMS[p.out] || !Number.isFinite(p.left) || (p.recipe !== MERGE_RECIPE && !RECIPE_BY_ID[p.recipe]) || (p.merge && !ITEMS[p.merge]))) delete a.pot;
    }
  }
  // ボスの 品（人の キャラだけ。たおした ことが ある ボスで、まだ 持っていない 物）
  if (c.species || !c.kills || typeof c.kills !== 'object' || !Array.isArray(c.items)) return;
  if (c.alchemy?.fill) return;
  for (const [sp, n] of Object.entries(c.kills)) {
    const id = n > 0 ? bossRareOf(sp) : null;
    if (!id || ownsItem(c, id)) continue;
    addItem(c, id, 1);
    c.bestiary = c.bestiary && typeof c.bestiary === 'object' ? c.bestiary : {};
    c.bestiary[sp] = { ...(c.bestiary[sp] && typeof c.bestiary[sp] === 'object' ? c.bestiary[sp] : {}), [`drop_${id}`]: 1 };
  }
  rec(c).fill = 1;
}

// データ合わせ（b: わかれる 前・a: こちら・t: あちら）。レシピ・本だなは 両方、回数は 多い ほう、かまの 中は あとで 遊んだ ほう
export function mergeAlchemy(b, a, t, tLater) {
  const A = a && typeof a === 'object' ? a : {};
  const T = t && typeof t === 'object' ? t : {};
  if (!a && !t) return undefined;
  const out = {};
  const union = (k) => {
    const list = [...new Set([...(Array.isArray(A[k]) ? A[k] : []), ...(Array.isArray(T[k]) ? T[k] : [])])];
    if (list.length) out[k] = list;
  };
  union('known');
  union('shelves');
  const cap = {};
  for (const src of [A.cap, T.cap]) if (src && typeof src === 'object') for (const [id, n] of Object.entries(src)) if (Number.isInteger(n)) cap[id] = Math.max(cap[id] || 0, n);
  if (Object.keys(cap).length) out.cap = cap;
  const pot = tLater ? (T.pot ?? A.pot) : (A.pot ?? T.pot);
  if (pot) out.pot = JSON.parse(JSON.stringify(pot));
  if (A.fill || T.fill) out.fill = 1;
  return out;
}

js/shared/world/arena.js:
// 第37回 A: サファラ闘技場（ランク戦の 3連戦・ごほうび・王者のかべ・かけ試合）。だいほんの 'call' から よぶ（data/story-arena.js）
//
// ・ランク戦（受付。物語と おなじ「パーティー みんなで 見る」だいほん。そばに いる 家族も いっしょに 戦う）
//   砂の 闘技場の まん中へ → 1戦目 → 2戦目 → 3戦目（王者）。戦いの 間に 回復しない（HP・MPは 戦いの あとの まま。
//   world/battles.js の finishBattle が キャラに もどす）。道具は 戦いの 中で 使える。にげられない（encounters-arena.js）
//   負けた（loseOk）… お金は へらない。受付の 前に もどって HP・MPが もどる / 勝ちぬいた … ごほうび（キャラごとに はじめてか 2回目からか）
//   とちゅうで かけつけた 家族（battles.js の joinBattle）も、次の 戦いから 3連戦の なかまに 入る（adopt）
// ・かけ試合（かけ試合の 係。ひとりずつ）: 4ひきの 魔物の トーナメント。本物の 戦いの しくみで 戦わせる（betDuel）。
//   オッズは 強さ（data/arena.js の winChances）から。けっかは 短い 戦いの ようす（client/ui/arena.js の arenaBoutUI）で 見せる
import { Battle } from '../battle.js';
import { decideMonster } from '../ai.js';
import { enemyFixedScale } from '../battle.js';
import { MONSTERS } from '../data/monsters.js';
import { ITEMS } from '../data/items.js';
import { addItem } from '../stats.js';
import { scaleEnemy } from '../data/treasure.js';
import { startFixedBattle } from './battles.js';
import { partyOf } from './party.js';
import { FIXED_ENCOUNTERS } from '../data/encounters.js';
import { ARENA_HOOKS } from '../data/story-arena.js';
import {
  ARENA_RANKS, ARENA_LEGEND_RANK, ARENA_POS, ARENA_MAP, rankInfo, rankLabel, rankOpen, rankCleared, visibleRanks, noteClear, nextRepeatMedal, firstMedalId,
  wallRows, arenaRecord, BET_LV, BET_POOL, BET_AMOUNTS, BET_PAIRS, ODDS_TRIES, duelRate, winChances, oddsOf, payout,
} from '../data/arena.js';
// 第45回: 竜王のしるしを もらえるか（data/companions-dqm.js）
import { dqKeyDue } from '../data/companions-dqm.js';

const say = (who, text) => ['say', who, text];
const CLERK = '闘技場の受付';
const CALLER = '闘技場の司会';
const BETMAN = 'かけ試合の係';
const fmt = (n) => Number(n).toLocaleString('ja-JP');
const ownerFlag = (run) => (f) => !!run.owner.char.flags?.[f];

async function flushOk(run) {
  const r = await run.flush();
  if (r.aborted) {
    run.abort();
    return false;
  }
  return true;
}

// ───────────── 受付 ─────────────
export async function arenaDesk(run) {
  const c = run.owner.char;
  const steps = [];
  if (!c.flags.arena_seen) {
    steps.push(
      say(CLERK, 'ようこそ、サファラ闘技場へ！\n水がもどって、大会がまたはじまったんだ！'),
      say(CLERK, 'ランク戦は、休みなしの3連戦。\n3戦目には、そのランクの「王者」が待っているぞ。'),
      say(CLERK, '戦いの間に、回復はできない。\n道具は戦いの中で使えるが、にげることはできない。'),
      say(CLERK, '負けても、お金はへらない。\nここにもどって、手当てをしてやるからな。'),
      ['flag', 'arena_seen'],
    );
  } else steps.push(say(CLERK, `ようこそ、サファラ闘技場へ！\n${bestText(c)}`));
  steps.push(['choice', '何をする？', ['ランク戦に出る', '王者のかべを見る', '闘技場のきまりを聞く', 'やめる'], [
    [['call', rankMenu]],
    [['call', wallOpen]],
    rulesSteps(),
    [say(CLERK, 'またいつでも来な！')],
  ]]);
  await run.runSteps(steps);
}

function bestText(c) {
  const best = Math.max(0, ...ARENA_RANKS.filter((R) => rankCleared(c, R.rank)).map((R) => R.rank));
  if (!best) return 'まずは、ランク1からちょうせんだ！';
  // 第65回 C: ランク10・ランク8（伝説のチャンピオン）。第68回 C: ランク11。第74回 C: ランク12（いちばん 上）
  if (best >= 12) return '深海の大王者のあわまで、全部はじいた、闘技場の伝説が来てくれるとは…！';
  if (best >= 11) return '白銀の大王者のこおりまでとかした、闘技場の伝説が来てくれるとは…！';
  if (best >= 10) return '星の大王者に勝った、闘技場の大王者が来てくれるとは…！';
  if (best === ARENA_LEGEND_RANK) return '伝説のチャンピオンに勝った者が、また来てくれるとは…！';
  return `${c.name}は、${rankLabel(best)}まで勝ちぬいているな。`;
}

function rulesSteps() {
  return [
    say(CLERK, 'ランク1〜5は、だれでも出られる。\n1つ前のランクを勝ちぬくと、次のランクに出られるぞ。'),
    say(CLERK, 'ランク5の上には「伝説の部」がある。\n世界のどこかで大きな戦いを乗りこえると、開くといううわさだ。'),
    say(CLERK, '初めて勝ちぬくと、とくべつなごほうび！\n2回目からは、ゴールドと小さなメダルを1まいだ。'),
    say(CLERK, 'そばにいる家族も、いっしょに戦える。\n勝ちぬくと、入口の「王者のかべ」に名前がきざまれるぞ。'),
    say(CLERK, '砂の闘技場では、モンスターのかけ試合もやっている。\nかけ試合の係に、話しかけてみな。'),
  ];
}

// ランクを えらぶ（リーダーの 記録で。開いていない ランクは 理由を 話す）
async function rankMenu(run) {
  const c = run.owner.char;
  const flag = ownerFlag(run);
  const ranks = visibleRanks(flag);
  const labels = ranks.map((n) => {
    const R = rankInfo(n);
    const open = rankOpen(n, flag, c).ok;
    const mark = rankCleared(c, n) ? '★' : '';
    if (!open && R.legend && !flag(R.needFlag)) return `${rankLabel(n)}　？？？`;
    return `${mark}${rankLabel(n)}　${R.champ}（おすすめLv${R.lv}）${open ? '' : '　まだ出られない'}`;
  });
  await run.runSteps([['choice', 'どのランクに出る？', [...labels, 'やめる'], [
    ...ranks.map((n) => [['call', (r) => rankConfirm(r, n)]]),
    [say(CLERK, 'またいつでも来な！')],
  ]]]);
}

async function rankConfirm(run, n) {
  const c = run.owner.char;
  const R = rankInfo(n);
  const o = rankOpen(n, ownerFlag(run), c);
  if (!o.ok) {
    const text = o.why === 'prev' ? `${rankLabel(n)}に出るには、まず${rankLabel(n - 1)}を勝ちぬくんだ！` : `伝説の部は、まだ開いていないんだ…。\n${R.lockText || ''}`;
    await run.runSteps([say(CLERK, text)]);
    return;
  }
  const who = run.everyone.length > 1 ? `${run.everyone.map((m) => m.char.name).join('と')}のパーティー` : c.name;
  await run.runSteps([
    say(CLERK, `${rankLabel(n)}は、休みなしの3連戦。\n3戦目の王者は「${R.champ}」だ。`),
    say(CLERK, `（${who}で出る。戦いの間に回復はできないぞ）`),
    ['choice', `${rankLabel(n)}にちょうせんする？`, ['ちょうせんする', 'やめる'], [
      [['call', (r) => runRank(r, n)]],
      [say(CLERK, 'じゅんびができたら、また来な！')],
    ]],
  ]);
}

// とちゅうで かけつけた 家族（戦いの あとで だいほんの 外に のこった 人）を 3連戦の なかまに 入れる
function adopt(run) {
  const w = run.world;
  const p = partyOf(w, run.init);
  for (const sid of p?.members || []) {
    const m = w.sessions.get(sid);
    if (!m || run.parts.includes(m) || m.busy !== 'script' || (m.runId && w.runs.has(m.runId))) continue;
    run.parts.push(m);
    m.runId = run.id;
  }
}

// HPと 位置の 立てなおし（負けた・とちゅうで やめた）。受付の 前に もどって 手当て
function backToDesk(lines) {
  const P = ARENA_POS.desk;
  return [
    ['fade', 'out'], ['teleport', ARENA_MAP, P.x + 0.5, P.y + 0.5, 'right'], ['heal'], ['bgm', 'resume'], ['fade', 'in'],
    ...lines,
  ];
}

// ランク戦の 3連戦
export async function runRank(run, n) {
  const R = rankInfo(n);
  const w = run.world;
  const P = ARENA_POS.ring;
  const names = () => run.everyone.map((m) => m.char.name);
  await run.runSteps([
    ['fade', 'out'], ['teleport', ARENA_MAP, P.x + 0.5, P.y + 0.5, 'up'], ['fade', 'in'],
    say(CALLER, `さあ、${rankLabel(n)}のちょうせん者、\n${names().join('と')}の入場だ！`),
    ['sfx', 'encounter'],
  ]);
  for (let i = 0; i < 3; i++) {
    const enc = R.battles[i];
    if (i < 2) run.batch.push(say(CALLER, i === 0 ? '第1戦、始め！' : '第2戦！休むひまはないぞ！'));
    else {
      run.batch.push(say(CALLER, `いよいよ第3戦！\n${rankLabel(n)}の王者、${R.champ}の登場だ！`));
      run.batch.push(['showMon', champOf(enc)]);
    }
    if (!(await flushOk(run))) return;
    const res = await startFixedBattle(w, run.init, run.everyone, enc);
    run.batch.push(['showMon', null]);
    adopt(run);
    if (res !== 'win') {
      if (res === 'lose') {
        await run.runSteps(backToDesk([
          say(CLERK, `おつかれさん！\n${rankLabel(n)}は、第${i + 1}戦で力つきてしまったな。`),
          say(null, '受付の人が、手当てをしてくれた。\nHPとMPがもどった！（お金はへっていない）'),
          say(CLERK, `${R.hint}\nまたちょうせんしな！`),
        ]));
      } else await run.runSteps(backToDesk([say(CLERK, '戦いが止まったようだ…。\nまたちょうせんしな！')]));
      return;
    }
    if (i < 2) run.batch.push(say(null, `第${i + 1}戦に勝った！\n（HPとMPは、回復しないまま…次の戦いへ！）`));
  }
  // 勝ちぬいた
  run.batch.push(['sfx', 'win'], say(CALLER, `勝者、${names().join('と')}！\n${rankLabel(n)}、勝ちぬきだ！！`));
  const lines = clearRewards(run, n);
  await run.runSteps([...lines, ...backToDesk([say(CLERK, clearText(n))])]);
}

// 勝ちぬいた ときの 受付の ことば（第65回 C: ランク8 は 伝説のチャンピオン・ランク10 は いちばん 上）
function clearText(n) {
  if (n >= 12) return 'あの深海の大王者のあわのよろいを、やぶってしまうとは…！\nあんたたちの名前は、海の底まで、とどろいているぞ！';
  if (n >= 11) return 'あの白銀の大王者のこおりを、とかしてしまうとは…！\nあんたたちこそ、闘技場の伝説の中の伝説だ！';
  if (n >= 10) return 'なんと、星の大王者にまで勝つとは…！\nあんたたちこそ、闘技場の大王者だ！';
  if (n === ARENA_LEGEND_RANK) return 'まさか、伝説のチャンピオンに勝つとは…！\nあんたたちこそ、本物の伝説だ！';
  return 'おめでとう！入口の「王者のかべ」にも、名前がきざまれたぞ！';
}

// 王者の すがた（台本の showMon）: 3戦目の グループの リーダー（合体技の 組）か ボスの 魔物
export function champOf(enc) {
  const g = FIXED_ENCOUNTERS[enc]?.group || [];
  const lead = g.find(([sp]) => MONSTERS[sp]?.arena?.lead) || g.find(([sp]) => MONSTERS[sp]?.boss && !MONSTERS[sp]?.arena?.twin) || g[0];
  return lead?.[0] || null;
}

// ごほうび（キャラごと）。はじめて … first の 品と 小さなメダル / 2回目から … ゴールドと 小さなメダル 1まい
export function clearRewards(run, n) {
  const R = rankInfo(n);
  const w = run.world;
  const now = w.now();
  const out = [];
  const people = run.everyone;
  const names = people.map((m) => m.char.name);
  for (const m of people) {
    const c = m.char;
    const first = noteClear(c, n, now, names.filter((x) => x !== c.name));
    if (first) {
      for (const id of R.first.items) {
        addItem(c, id, 1);
        out.push(['sfx', 'item'], say(null, `${c.name}は${ITEMS[id].name}を手に入れた！`));
      }
      // 第65回 C: きたえる 素材（ランク9・10）
      const mats = (R.first.mats || []).filter(([id, k]) => ITEMS[id] && k > 0);
      for (const [id, k] of mats) addItem(c, id, k);
      if (mats.length) out.push(['sfx', 'item'], say(null, `${c.name}は${mats.map(([id, k]) => `${ITEMS[id].name}を${k}個`).join('と')}手に入れた！`));
      c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
      for (let i = 1; i <= R.first.medals; i++) if (!c.medalSpots[firstMedalId(n, i)]) c.medalSpots[firstMedalId(n, i)] = now;
      out.push(['sfx', 'key'], say(null, `${c.name}は小さなメダルを${R.first.medals}枚手に入れた！`));
    } else {
      c.gold = Math.min(9999999, (c.gold || 0) + R.repeatGold);
      c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
      c.medalSpots[nextRepeatMedal(c)] = now;
      out.push(['sfx', 'item'], say(null, `${c.name}は${fmt(R.repeatGold)}ゴールドと、小さなメダルを1枚手に入れた！`));
      // 第65回: 限界の石（ランク9・10）
      const rm = (R.repeatMats || []).filter(([id, k]) => ITEMS[id] && k > 0);
      for (const [id, k] of rm) addItem(c, id, k);
      if (rm.length) out.push(say(null, `${c.name}は${rm.map(([id, k]) => `${ITEMS[id].name}を${k}個`).join('と')}手に入れた！`));
    }
    // 第45回: 大事な物（ランク8 の 竜王のしるし。1人 1つ）
    if (R.key && dqKeyDue(c, R.key)) {
      addItem(c, R.key, 1);
      out.push(['sfx', 'key'], say(null, `${c.name}は${ITEMS[R.key].name}を手に入れた！\n（ドラゴン系の魔物2ひきと配合すると…？）`));
    }
    w.sendSelf(m);
  }
  w.markDirty();
  return out;
}

