    if (sid === s.id) continue;
    const m = world.sessions.get(sid);
    // 大鳥で 空を とんでいる 人・たたかいの けっかを 読んでいる 人は まきこまれない（travel.js）
    if (!m || !m.inWorld || m.busy || m.away || m.flying || m.map !== s.map || readingResult(m)) continue;
    if (Math.hypot(m.x - s.x, m.y - s.y) > JOIN_RADIUS) continue;
    out.push(m);
  }
  return out;
}

// たたかっている なかまの ところへ かけつけて さんかする（ふつうの たたかいも、ボス・物語の たたかいも。
//   第34回: 会話の 時に そばに いなかった 人・会話の タイミングが ずれた 人も、あとから かけつけられる）
export function joinBattle(world, s, targetSid) {
  if (s.busy || s.away || s.flying || !s.inWorld) return { ok: false };
  const t = world.sessions.get(targetSid);
  if (!t || t === s || t.busy !== 'battle' || t.partyId !== s.partyId || t.map !== s.map) return { ok: false };
  const ctx = world.battles.get(t.battleId);
  if (!ctx || ctx.battle.over || ctx.battle.pendingEnd) return { ok: false };
  if (Math.hypot(t.x - s.x, t.y - s.y) > LATE_JOIN_RADIUS) return { ok: false };
  if (ctx.sids.includes(s.id)) return { ok: false };
  // 1人で 戦う きまった 戦い（リオンの けいこ。encounters の solo）には 入れない
  if (ctx.opts.solo) return { ok: false, reason: 'これは1人で戦うけいこだ…' };
  // プレイヤーは 5人まで いっしょに 戦える（world/party.js の PARTY_MAX）
  if (ctx.battle.allies.filter((a) => a.kind !== 'guest').length >= PARTY_MAX) return { ok: false, reason: '戦いの場所がいっぱいだ…' };
  const a = ctx.battle.joinAlly({ char: s.char, kind: 'player', controller: s.id, auto: !!s.char.battleSettings?.auto });
  ctx.actorMap[a.id] = { type: 'human', sid: s.id, char: s.char };
  noteSeen(s.char, [...new Set(ctx.battle.combatants.filter((x) => x.side === 'enemy').map((x) => x.species))]);
  ctx.sids.push(s.id);
  s.busy = 'battle';
  s.battleId = ctx.id;
  s.moving = false;
  // じぶんの なかまで「めいれいさせろ」の なかまは、かけつけた じぶんが うごかす
  for (const ally of ctx.battle.allies) {
    const who = ctx.actorMap[ally.id];
    if (who?.type === 'support' && who.owner === s.charId && who.manual && !ally.controller) {
      ally.controller = s.id;
      ctx.battle.setAuto(ally.id, !!s.char.battleSettings?.auto);
    }
  }
  world.send(s, { t: 'battleStart', snap: ctx.battle.snapshot(), mine: mineOf(ctx, s.id), boss: !!ctx.opts.boss, story: !!ctx.opts.fixed, joined: true });
  world.broadcastPositions = true;
  return { ok: true };
}

// たたかいの けっかを まだ 読んでいるか
export function readingResult(s) {
  return !!s.reading && s.invuln > 0;
}

// けっかを 読みおわった（クライアントから）: ここから すこしだけ むてき
export function resultDone(world, s) {
  // 第61回: リーダーが とじた → いっしょに たたかった 仲間の けっかの まども とじる
  const fol = s.resultFollowers;
  s.resultFollowers = null;
  for (const sid of fol || []) {
    const m = world.sessions.get(sid);
    if (m?.reading) world.send(m, { t: 'resultClose', id: s.resultFollowId });
  }
  if (!s.reading) return;
  s.reading = false;
  s.invuln = Math.min(s.invuln, AFTER_RESULT_MS);
}

// 敵の 強さ（設定の「敵の強さ」。data/difficulty.js）: パーティーでは リーダーの 設定（ものがたりと おなじ）。ひとりなら 自分の 設定
export function enemyRateFor(world, party, sessions) {
  const leader = (party && world.sessions.get(party.leader)) || sessions?.[0];
  return difficultyOf(leader?.char).enemy;
}

// その 人が うごかす キャラ（じぶん＋「めいれいさせろ」の なかま）。じぶんが さいしょ
export function mineOf(ctx, sid) {
  // 第67回 C: その場の 対戦（敵の がわの 魔物も 人が うごかす。world/monarena-live.js）
  if (ctx.mineFor) return ctx.mineFor(sid);
  const out = ctx.battle.allies.filter((a) => a.controller === sid);
  out.sort((x, y) => (x.kind === 'player' ? 0 : 1) - (y.kind === 'player' ? 0 : 1));
  return out.map((a) => a.id);
}

function makeBattle(world, sessions, party, enemies, opts) {
  const leader = world.sessions.get(party.leader) || sessions[0];
  const settings = leader.char.battleSettings || {};
  const allies = [];
  const actorMap = {};
  const entries = []; // ならびの じゅん（先頭ほど 敵に ねらわれやすい）
  // なかま: さくせんが「めいれいさせろ」なら もちぬしが コマンドを えらぶ（もちぬしが いない ときは AI）
  // 第53回: 1人で 戦う（opts.solo。リオンの けいこ）… 仲間・ゲストは 入らない
  const sups = (opts.solo ? [] : party.supports).map((sup) => {
    const tac = sup.char.tactics || 'balanced';
    const owner = tac === 'manual' ? sessions.find((m) => m.charId === sup.owner) : null;
    return {
      map: { type: 'support', key: sup.key, owner: sup.owner, kind: sup.kind, char: sup.char, manual: tac === 'manual' },
      ally: {
        char: sup.char, kind: sup.kind === 'monster' ? 'monster' : 'support',
        controller: owner ? owner.id : null, auto: owner ? !!owner.char.battleSettings?.auto : true,
        tactics: tac === 'manual' ? 'balanced' : tac, tacBy: sup.owner, manual: tac === 'manual',
      },
    };
  });
  const humans = sessions.map((m) => ({
    map: { type: 'human', sid: m.id, char: m.char },
    ally: { char: m.char, kind: 'player', controller: m.id, auto: !!m.char.battleSettings?.auto },
  }));
  const pos = Math.max(0, Math.min(sups.length, selfPosOf(world, party)));
  entries.push(...sups.slice(0, pos), ...humans, ...sups.slice(pos));
  for (const e of entries) allies.push(e.ally);
  // 第54回: 味方が 5人（PARTY_MAX）そろって いる ときは、ゲストは 戦いに 入らない（6人目は いらない）
  const guests = opts.solo ? [] : party.guests.slice(0, Math.max(0, PARTY_MAX - allies.length));
  // 第78回: ゲストの 強さの きまり（shared/guest-rule.js）。その 戦いに 出る 家族の キャラ（人＋家族の 仲間。人間だけ）の 平均の 0.94 くらい。
  //   戦いの 中の キャラは きまりで 作った べつの キャラ（HP・MP は パーティーの ゲストの 割合）。戦いの あとで 割合を もどす
  const famChars = entries.filter((e) => e.map.type === 'human' || e.map.kind === 'family').map((e) => e.ally.char);
  const ruled = guests.map((g) => (GUESTS[g.id] ? guestForBattle(GUESTS[g.id], famChars.length ? famChars : entries.map((e) => e.ally.char), g.char) : null));
  guests.forEach((g, j) => allies.push({ char: ruled[j]?.char || g.char, kind: 'guest', auto: true, tactics: g.char.tactics }));
  const b = new Battle({
    id: 'b' + (battleSeq++),
    rng: world.rng,
    allies,
    enemies,
    ...normBattleSettings(settings),
    wait: !!settings.wait,
    canFlee: opts.canFlee !== false,
    boss: !!opts.boss,
    // 呪文が ふうじられた マップ（王家のピラミッド 2階）
    noSpells: !!MAPS[sessions[0]?.map]?.noSpells,
    bg: opts.bg,
    bgm: opts.bgm,
    preemptive: opts.preemptive || null,
    // 宝の洞窟: 魔物を 地図の レベルに あわせて 強くする（ひみつのダンジョンの 深い 階は enemyPow 倍）
    // 第40回: 宝の洞窟は その レベルの ふつうの 魔物と おなじ 強さ（enemyCurve。data/tm-curve.js）
    enemyMod: opts.enemyLv ? (m) => scaleEnemy(m, opts.enemyLv, opts.enemyPow, { curve: !!opts.enemyCurve }) : null,
    // 敵の 強さ（ハード 1.2倍 など）。リーダーの 設定。宝の洞窟の 強さの 上に かける（ほうしゅうは かわらない）
    enemyRate: enemyRateFor(world, party, sessions),
    hooks: {
      // リーダー（物語の もちぬし）の フラグ（第5章 Step 9 の ノクト〈本気〉: 思い出の かけら・ピピの 手紙で ことばが かわる。battle-final.js）
      leaderFlag: (id) => !!leader?.char?.flags?.[id],
      // 第6章 Step 3・4: 昼か 夜か（星座の 魔物は 夜だけ 強い／昼だけ 強い。battle-road.js）
      night: () => isNightFor(world, leader),
      hasItem: (actor, id) => {
        const m = actor.controller && world.sessions.get(actor.controller);
        return m ? itemCount(m.char, id) > 0 : false;
      },
      consumeItem: (actor, id) => {
        const m = actor.controller && world.sessions.get(actor.controller);
        if (!m) return false;
        const ok = removeItem(m.char, id, 1);
        if (ok) world.sendSelf(m);
        return ok;
      },
      // 銭投げ: 持っている お金から はらう（たりなければ あるだけ）
      spendGold: (actor, want) => {
        const m = actor.controller && world.sessions.get(actor.controller);
        if (!m || !(m.char.gold > 0)) return 0;
        const paid = Math.min(m.char.gold, Math.max(1, Math.round(want)));
        m.char.gold -= paid;
        world.sendSelf(m);
        return paid;
      },
      // 大型買収: おいだした 敵の お金を もらう
      gainGold: (actor, species, mult = 1) => {
        const m = (actor.controller && world.sessions.get(actor.controller)) || sessions[0];
        const g = rewardGold(Math.round((MONSTERS[species]?.gold || 0) * mult));
        if (!m || g <= 0) return 0;
        m.char.gold = Math.min(9999999, m.char.gold + g);
        world.sendSelf(m);
        return g;
      },
      // 盗塁・お宝さがし: 敵の 持ち物を ぬすむ
      steal: (actor, species) => {
        const m = (actor.controller && world.sessions.get(actor.controller)) || sessions[0];
        const id = m ? stealPick(species, world.rng) : null;
        if (!id) return null;
        addItem(m.char, id, 1);
        noteDrop(m.char, species, id);
        world.sendSelf(m);
        return ITEMS[id].name;
      },
    },
  });
  // 第38回 B: 戦いを 作った すぐ あとの しかけ（職業の試練の 師しょうのまぼろし。world/job-trials.js）
  if (opts.setup) opts.setup(b);
  // だれが どの キャラか
  let i = 0;
  for (const e of entries) actorMap[b.allies[i++].id] = e.map;
  guests.forEach((g, j) => {
    const a = b.allies[i++];
    actorMap[a.id] = { type: 'guest', id: g.id, char: g.char, ruled: !!ruled[j] };
    if (ruled[j]) scaleGuestActor(a, ruled[j].plan.k);
  });
  // モンスターマスターが いると なかまの まものが つよくなる
  const boost = Math.max(1, ...sessions.map((m) => JOBS[m.char.job]?.passive?.monsterBoost || 1));
  if (boost > 1) {
    for (const a of b.allies) if (a.mon) { a.atk = Math.round(a.atk * boost); a.dfn = Math.round(a.dfn * boost); }
  }
  // ずかん: みた まもの
  const seen = [...new Set(enemies)];
  for (const m of sessions) noteSeen(m.char, seen);
  const ctx = { id: b.id, battle: b, sids: sessions.map((m) => m.id), partyId: party.id, map: sessions[0].map, actorMap, opts };
  world.battles.set(ctx.id, ctx);
  for (const m of sessions) {
    m.busy = 'battle';
    m.battleId = ctx.id;
    world.send(m, { t: 'battleStart', snap: b.snapshot(), mine: mineOf(ctx, m.id), boss: !!opts.boss, story: !!opts.fixed, preemptive: opts.preemptive || null });
  }
  world.broadcastPositions = true;
  return ctx;
}

export function startFieldBattle(world, s, sym) {
  const party = partyOf(world, s);
  const sessions = battleSessions(world, s);
  sym.busy = true;
  const zone = sym.zone;
  // うしろから ふれたら せんせいこうげき、おいかけられて ぶつかったら ふいうち
  let preemptive = null;
  const r = world.rng.next();
  if (sym.state !== 'chase' && r < 0.12) preemptive = 'ally';
  else if (sym.state === 'chase' && r < 0.06) preemptive = 'enemy';
  // 魔物よせ（マモノヨセ・魔物よせの笛）: 強めの 組が 出やすい（world/field27.js の lureGroup）
  if (sessions.some((m) => lureOn(m, world.now()))) sym.group = lureGroup(world, sym);
  const ctx = makeBattle(world, sessions, party, sym.group, {
    bg: ZONE_BG[sym.table] || (MAPS[s.map].kind === 'dungeon' ? 'cave' : 'grass'),
    bgm: sym.table === 'rare' ? 'battle' : 'battle',
    canFlee: true,
    preemptive,
    symbolId: sym.id,
    mapId: s.map,
    enemyLv: MAPS[s.map].enemyLv,
    enemyPow: MAPS[s.map].enemyPow,
    enemyCurve: !!MAPS[s.map].enemyCurve,
  });
  return ctx;
}

// ストーリーの たたかい（まけると だいほんが とまる）
// extra … makeBattle に わたす ほかの もの（第38回 B: setup … 戦いを 作った すぐ あとの しかけ。world/job-trials.js）
// 第53回: enc.solo … はじめた 人 1人だけで 戦う（リオンの けいこ）/ enc.pick(now) … その 日の 敵の むれ（時のまぼろし）
export function startFixedBattle(world, initiator, participants, encId, extra = {}) {
  const enc = FIXED_ENCOUNTERS[encId];
  const party = partyOf(world, initiator);
  const sessions = (enc.solo ? [initiator] : participants).filter((m) => m && m.inWorld);
  const enemies = [];
  const group = typeof enc.pick === 'function' ? enc.pick(world.now()) : enc.group;
  for (const [sp, mn] of group) for (let i = 0; i < mn; i++) enemies.push(sp);
  return new Promise((resolve) => {
    for (const m of sessions) m.busy = null; // だいほんの あいだは busy='script' だが たたかいに きりかえる
    const ctx = makeBattle(world, sessions, party, enemies, { bg: enc.bg, bgm: enc.bgm, canFlee: enc.canFlee, boss: enc.boss, fixed: encId, enemyLv: enc.enemyLv, enemyPow: enc.enemyPow, enemyCurve: !!enc.enemyCurve, loseOk: !!enc.loseOk, solo: !!enc.solo, ...extra });
    ctx.resolve = resolve;
  });
}

export function battleTick(world, ctx, dt) {
  const evs = ctx.battle.tick(dt);
  if (evs.length) {
    markDuals(world, ctx, evs);
    for (const sid of ctx.sids) {
      const m = world.sessions.get(sid);
      // 第67回 C: ctx.evsFor … 人ごとに 見え方を かえる（その場の 対戦の 相手の 画面は 敵と みかたを 入れかえる。world/monarena-live.js）
      if (m) world.send(m, { t: 'battleEv', id: ctx.id, evs: ctx.evsFor ? ctx.evsFor(sid, evs) : evs });
    }
  }
  // 第67回 B: ctx.finish … べつの おわり方（モンスター闘技場。world/monarena.js の finishMon）
  if (ctx.battle.over) (ctx.finish || finishBattle)(world, ctx);
}

// たたかいが こわれて すすまない（まいフレーム エラー）: にげた ことに して みんなを フィールドへ もどす
// （物語の たたかいは だいほんが そこで おわる。もう一度 話しかければ やりなおせる）
export function abortBattle(world, ctx) {
  try {
    if (!ctx.battle.over) ctx.battle.endBattle({ outcome: 'flee' });
    (ctx.finish || finishBattle)(world, ctx);
    return;
  } catch (e) {
    console.error('battle abort error', e);
  }
  // さいごの 手だて: たたかいを けして「たたかい中」の しるしを とく
  world.battles.delete(ctx.id);
  for (const sid of ctx.sids) {
    const m = world.sessions.get(sid);
    if (!m || m.battleId !== ctx.id) continue;
    m.busy = ctx.resolve ? 'script' : null;
    m.battleId = null;
    m.reading = false;
    m.invuln = 3000;
    world.send(m, { t: 'battleEnd', id: ctx.id, outcome: 'flee', lines: [], levelUp: false, story: !!ctx.resolve });
    world.sendSelf(m);
  }
  if (ctx.resolve) ctx.resolve('flee');
}

// 合体技は 一度 使うと 効果が わかる（出した 人 みんなの もちぬしの キャラに char.dualSeen）
function markDuals(world, ctx, evs) {
  for (const ev of evs) {
    const d = ev.dual;
    if (!d?.id) continue;
    ctx.mDual = (ctx.mDual || 0) + 1; // 家族ミッション（world/missions.js）
    const fresh = [];
    for (const id of d.m || [d.a, d.b]) {
      const who = ctx.actorMap[id];
      const ch = who?.type === 'human' ? who.char : who?.type === 'support' ? world.data.characters[who.owner] : null;
      if (ch && !ch.dualSeen?.[d.id]) {
        ch.dualSeen = { ...(ch.dualSeen || {}), [d.id]: 1 };
        if (!fresh.includes(ch)) fresh.push(ch);
      }
    }
    // 第51回 B: はじめて 使った 家族を けいじ板に（1回の 合体技で 1こ）
    if (fresh.length) boardDual(world, fresh, d.id);
  }
}

export function battleCommand(world, s, msg) {
  const ctx = world.battles.get(s.battleId);
  if (!ctx) return;
  const b = ctx.battle;
  if (msg.auto !== undefined) {
    const a = b.get(msg.actor);
    if (a && a.controller === s.id) {
      b.setAuto(msg.actor, !!msg.auto);
      if (a.kind === 'player') s.char.battleSettings = { ...(s.char.battleSettings || {}), auto: !!msg.auto };
    }
    return;
  }
  // 馬車の 仲間と いれかえ（world/wagon.js）
  if (msg.cmd?.type === 'swap') return wagonBattleSwap(world, s, ctx, msg);
  // なかまの さくせんを かえる（world/tactics.js）
  // 第67回 C: ctx.tactics … その場の 対戦（敵の がわの 魔物の 作戦も その もちぬしが かえる。world/monarena-live.js）
  if (msg.tactics !== undefined) return (ctx.tactics || battleTactics)(world, s, ctx, msg);
  const r = b.command(msg.actor, msg.cmd, s.id);
  if (!r.ok) world.send(s, { t: 'battleRej', reason: r.reason || 'できません' });
}

// サーバーから プレイヤーが ぬけたとき
export function battleLeave(world, s) {
  const ctx = world.battles.get(s.battleId);
  if (!ctx) return;
  for (const a of ctx.battle.allies) if (a.controller === s.id) ctx.battle.setAuto(a.id, true);
}

function finishBattle(world, ctx) {
  world.battles.delete(ctx.id);
  const b = ctx.battle;
  const res = b.result;
  const party = world.parties.get(ctx.partyId);
  const sessions = ctx.sids.map((sid) => world.sessions.get(sid)).filter(Boolean);
  // 第78回 3-10: 家族ミッション（技の 回数を 書きかえる 前に）
  missionBattle(world, ctx, sessions);
  // HP・MPを もどす
  for (const a of b.allies) {
    const who = ctx.actorMap[a.id];
    const ch = who?.char;
    if (!ch) continue;
    // 第78回: きまりで 作った ゲストは HP・MP の 割合を もどす
    if (who.ruled) guestAfterBattle(ch, a);
    else {
      ch.hp = a.alive ? a.hp : 0;
      ch.mp = a.mp;
    }
    ch.status = a.status.poison && a.alive ? { poison: true } : {};
  }
  // 技を 使った 回数と、ひらめいた 技を のこす（自分・自分の 仲間。家族の キャラと ゲストは のこさない）
  const hiraLines = [];
  // 第38回 B: 職業の試練の 修行（自分の キャラが 今の 職業の 技を この 戦いで 使った 回数。勝った ときに たす）
  const trialUse = new Map();
  // 第66回: 幻の職業の 記録は 主人公 いがいも（人の 仲間・家族の キャラは 本人の 記録に。うつしでは なく）
  const featChars = [];
  for (const a of b.allies) {
    const who = ctx.actorMap[a.id];
    if (!who?.char || !a.feat || who.type === 'guest' || who.char.species) continue;
    const real = who.kind === 'family' && String(who.key || '').startsWith('fam:') ? world.data.characters?.[who.key.slice(4)] : who.char;
    if (!real || real.species) continue;
    addFeats(real, a.feat);
    if (who.type === 'support') featChars.push({ char: real, owner: who.owner });
  }
  for (const a of b.allies) {
    const who = ctx.actorMap[a.id];
    const ch = who?.char;
    if (!ch || !a.use || who.type === 'guest' || who.kind === 'family') continue;
    if (who.type === 'human') trialUse.set(ch, trialUseCount(ch.job, ch.skillUse, a.use));
    ch.skillUse = { ...a.use };
    if (a.hiraNew?.length) {
      ch.hirameki = [...new Set([...(Array.isArray(ch.hirameki) ? ch.hirameki : []), ...a.hiraNew])];
      for (const id of a.hiraNew) hiraLines.push(`★ ${ch.name}は「${abilityLabel(id, ch)}」をひらめいた！（これからも使える）`);
      boardHirameki(world, ch, a.hiraNew);
    }
  }

  const outcome = res.outcome;
  const perSession = {};
  let befriend = null;
  if (outcome === 'win') {
    let exp = 0, gold = 0;
    for (const sp of res.killed) {
      const m = MONSTERS[sp];
      exp += m.exp;
      gold += m.gold;
    }
    const bonus = scaledRewardBonus(b); // 強くした 魔物の ぶん
    exp += bonus.exp;
    gold += bonus.gold;
    // 海賊・会社員など: お金が ふえる 職業が いると ゴールドが ふえる
    //   第45回: ゴールドぷるりん（魔物の 仲間）も（いちばん 大きい 倍率だけ）
    const goldMult = Math.max(1, ...Object.values(ctx.actorMap).map((w) => JOBS[w?.char?.job]?.passive?.gold || MONSTER_FRIENDS[w?.char?.species]?.passive?.gold || 1));
    // きほんの 倍率（経験値 0.6・お金 0.7。data/difficulty.js。設定の「もらえる経験値」は この あとの scaleExp）
    exp = rewardExp(exp);
    gold = rewardGold(Math.round(gold * goldMult));
    // 職業の しゅぎょう: かった たたかい 1かい（ボスは 3かいぶん）。
    // ワンパンチ（なかまの 1回めの こうどうで おわった たたかい）は 半分。なかま・馬車の なかまも おなじ
    const oneBlow = (b.allyActs || 0) <= 1;
    const trainN = (b.boss ? 3 : 1) * jobTrainMult(oneBlow);
    const leaderName = sessions[0]?.char.name || '';
    // しあわせのぼうし: その 戦いの パーティー（馬車も ふくむ）で いちばん レベルが 高い 人には 効かない（world/perks.js）
    // （レベルが 上がる 前に きめる）
    const top = topLevel(battleTeamChars(world, ctx));
    const hat = (ch) => expHatMult(ch, top);
    // レベルアップの まとめ（world/growth.js）: 人ごとの 行・★の 知らせ
    const own = {};
    for (const m of sessions) {
      const c = m.char;
      // ゲームの むずかしさ（設定）で 経験値が へる（difficulty.js）
      const hm = hat(c);
      const myExp = scaleExp(c, exp) * hm;
      const lines = [];
      lines.push(res.killed.length ? '魔物たちをやっつけた！' : '戦いに勝った！');
      if (myExp > 0) lines.push(`${c.name}は${myExp}ポイントの経験値をかくとく！${hm > 1 ? '（しあわせのぼうしで2倍）' : ''}`);
      if (gold > 0) lines.push(`${gold}ゴールドを手に入れた！`);
      c.gold = Math.min(9999999, c.gold + gold);
      for (const sp of res.killed) c.kills[sp] = (c.kills[sp] || 0) + 1;
      // ドロップ（1体から 1つまで。ボスは かならず。loot.js）
      const drops = [];
      for (const sp of res.killed) {
        for (const id of rollDrops(sp, world.rng, { map: ctx.map })) {
          if (ITEMS[id].unique && ownsItem(c, id)) continue; // ボスの 品は 1人 1つ
          addItem(c, id, 1);
          noteDrop(c, sp, id);
          drops.push(id);
          // 1つ 1行（第31回: 「手に入れた！」の 行は はぶく。けっかの まどで 緑の 字）
          lines.push(`${MONSTERS[sp].name}は${ITEMS[id].name}を持っていた！`);
        }
      }
      const ups = gainExp(c, myExp);
      let jups = [];
      if (JOBS[c.job] && (c.jobs[c.job]?.lv || 1) < jobLevelCap(c, c.job)) {
        jups = gainJobBattles(c, trainN);
        if (oneBlow) lines.push('（一撃で終わったので、職業の修行は半分）');
      }
      // 職業の試練の 修行（data/job-trials.js）
      const tu = addTrialUses(c, c.job, trialUse.get(c) || 0);
      if (tu) {
        lines.push(`（${trialName(c.job, tu.trial.n, c)}：修行 ${tu.to}/${tu.need}回）`);
        if (tu.done) lines.push(`★ ${c.name}は${trialName(c.job, tu.trial.n, c)}の修行をやりとげた！\n（ルミナの町の神殿の、試練の番人に話そう）`);
      }
      own[m.id] = growthSummary(c.name, ups, jups, c, { self: true });
      perSession[m.id] = { lines, levelUp: ups.length > 0, jobUp: jups.length > 0, drops };
    }
    // なかま: たたかいに でた なかまだけ そだつ。家族の キャラには おれいが とどく
    const compRows = [], compNotes = [], expLines = [];
    const grow = (ch, x, trains) => {
      const { ups, jups } = growCompanion(ch, x * hat(ch), trains);
      const g = growthSummary(ch.name, ups, jups, ch);
      compRows.push(...g.lines);
      compNotes.push(...g.notes);
    };
    for (const a of b.allies) {
      const who = ctx.actorMap[a.id];
      if (who?.type !== 'support' || !who.char) continue;
      if (who.kind === 'family') {
        if (who.char.ownerId) creditSupportOwner(world, who.char.ownerId, scaleExp(world.data.characters[who.char.ownerId], exp) * hat(who.char), gold, leaderName);
        continue;
      }
      const trains = !who.char.species ? trainN : 0;
      // 仲間は もちぬしの むずかしさ
      grow(who.char, scaleExp(world.data.characters[who.owner], exp), trains);
    }
    // 馬車の 仲間（フィールドは 同じ・洞窟などは 半分。world/wagon.js）
    wagonShare(world, ctx, { exp, trainN, grow, mult: hat, say: (l) => expLines.push(l) });
    // 1画面に まとめる: 経験値・お金・ドロップ → レベルアップ（自分 → いっしょに 戦った 家族 → 仲間・馬車）→ ★の 知らせ
    for (const m of sessions) {
      const L = perSession[m.id].lines;
      L.push(...expLines);
      const rows = [...own[m.id].lines];
      for (const o of sessions) if (o !== m) rows.push(...own[o.id].lines);
      rows.push(...compRows);
      L.push(...rows, ...own[m.id].notes, ...compNotes);
      perSession[m.id].levelUp = rows.length > 0;
    }
    // まものが なかまに なりたがる（ふつうの たたかい だけ。ひみつのダンジョンの 中では ならない: map.noBefriend）
    if (!ctx.resolve && !b.boss && res.killed.length && !MAPS[ctx.map]?.noBefriend) {
      const target = sessions.find((m) => m.id === party?.leader) || sessions[0];
      // まもの使い・モンスターマスターが いると なかまに なりやすい
      let mult = Math.max(1, ...b.allies.map((a) => JOBS[a.job]?.passive?.befriend || 1));
      // 仲間の粉（data/friend-powder.js）: いっしょに 戦った だれかが 使っていれば 2倍。使った 人 みんな のこりが 1回 へる
      // （仲間に なれる 魔物が いた 戦い だけ 数える）
      const can = !!target?.char?.flags?.monster_bond && res.killed.some((x) => befriendChance(target.char, x) > 0);
      const powdered = can ? sessions.filter((m) => powderLeft(m.char) > 0) : [];
      if (powdered.length) mult *= POWDER.mult;
      const info = {};
      const sp = target && rollBefriend(world, target.char, res.killed, mult, info);
      if (sp) befriend = { s: target, species: sp, level: befriendLevel(target.char, sp) };
      for (const m of powdered) {
        m.char.befriendBoost = powderLeft(m.char) - 1;
        if (!m.char.befriendBoost) delete m.char.befriendBoost;
        perSession[m.id]?.lines.push(m.char.befriendBoost ? `（仲間の粉の力：のこり${m.char.befriendBoost}回）` : '（仲間の粉の力が消えた）');
      }
      // 仲間が いっぱいで 入れなかった（だまって 消えると「仲間に ならない」と 思うので 知らせる）
      if (info.full && perSession[target.id]) perSession[target.id].lines.push(`${MONSTERS[info.full].name}が仲間になりたそうにしていたが、仲間がいっぱいだ…`, '（酒場でだれかと別れると、また仲間になる）');
    }
    // 家族の パーティー: いっしょに 戦った 家族の 酒場にも（「はい」の とき。world/recruit-share.js）
    if (befriend) befriend.share = befriendShare(sessions, befriend.s);
    if (befriend) missionFriend(world, sessions);
  } else if (outcome === 'lose') {
    // ほんとうの 全滅: それぞれ 自分の 持っている お金が 半分に（預かり所の お金は へらない）
    // 負けても 物語が すすむ 戦い（encounters の loseOk）では へらない
    for (const m of sessions) {
      if (ctx.opts.loseOk) {
        perSession[m.id] = { lines: [`${m.char.name}たちは力つきた…`] };
        continue;
      }
      // ひみつのダンジョンの 中では お金は へらない（入口の 広間で 目を覚ます。world/secret.js）
      if (MAPS[ctx.map]?.sd) {
        perSession[m.id] = { lines: [`${m.char.name}たちは全滅してしまった…`, 'ひみつのダンジョンでは、お金はへらない。'] };
        continue;
      }
      const lines = [`${m.char.name}たちは全滅してしまった…`];
      const g = wipeGoldLoss(m.char);
      let note = '';
      if (g.lost > 0) {
        note = `所持金が半分になってしまった…${bankGold(m.char) > 0 ? '\n（預かり所のお金は無事だ）' : ''}`;
        lines.push(`所持金が半分になってしまった…（${g.before}G→${g.after}G）`);
      }
      perSession[m.id] = { lines, wipeNote: note };
    }
  } else if (outcome === 'flee') {
    for (const m of sessions) perSession[m.id] = { lines: [] };
  }

  if (hiraLines.length) for (const m of sessions) (perSession[m.id] = perSession[m.id] || { lines: [] }).lines.push(...hiraLines);
  // 宝の地図を 拾う（第1章クリアの あと）
  treasureAfterBattle(world, ctx, sessions, perSession);
  // 第51回 F: 幻の職業の 条件が 見えた・なれるように なった（1回だけ。掲示板にも。world/phantom.js）
  for (const m of sessions) {
    const pn = phantomAfterBattle(world, m.char);
    if (pn.length) (perSession[m.id] = perSession[m.id] || { lines: [] }).lines.push(...pn);
  }
  // 第66回: 人の 仲間・家族の キャラ（なった 知らせは 仲間の もちぬしに）
  for (const { char, owner } of featChars) {
    const pn = phantomAfterBattle(world, char);
    const m = sessions.find((x) => x.charId === owner) || sessions[0];
    if (pn.length && m) (perSession[m.id] = perSession[m.id] || { lines: [] }).lines.push(...pn);
  }
  // 第53回 B: 時のまぼろし（止まった時の間）に 勝った: 1日1回の 素材・はじめての 勝ちは けいじ板へ（world/tokei-phantom.js）
  tokiPhantomAfter(world, ctx, sessions, perSession, outcome);
  // 第80回 E班: ボスに 負けた 時の ヒント（world/boss-hints.js）
  bossHintAfter(world, ctx, sessions, outcome);

  // シンボル
  if (ctx.opts.symbolId) {
    const ms = world.mapStates.get(ctx.opts.mapId);
    const sym = ms?.symbols.get(ctx.opts.symbolId);
    if (sym) {
      if (outcome === 'win') ms.symbols.delete(sym.id);
      else {
        sym.busy = false;
        sym.stun = 3000;
      }
    }
  }
  // 第61回: パーティーで たたかった ときは、仲間の けっかの まどは リーダーが とじた 時に いっしょに とじる
  //   （リーダーも いっしょに たたかって、リーダーにも 読む 行が ある 時だけ。resultDone で 'resultClose' を 送る）
  const lead = party ? sessions.find((m) => m.id === party.leader) : null;
  const leadReads = !!lead && (perSession[lead.id]?.lines || []).length > 0;
  if (lead) { lead.resultFollowers = []; lead.resultFollowId = ctx.id; }
  for (const m of sessions) {
    m.busy = ctx.resolve ? 'script' : null;
    m.battleId = null;
    // 第44回: レベルが 上がって 進化を まっている 仲間は、けっかを 読みおわった あとで たずねる（world.js の tick・world/evolve.js）
    m.evoCheck = true;
    const r = perSession[m.id] || { lines: [] };
    // けっかの まどを 読んでいる あいだは むてき（読みおわると AFTER_RESULT_MS だけ のこる）
    m.reading = r.lines.length > 0;
    m.invuln = m.reading ? RESULT_MAX_MS : 3000;
    const follow = leadReads && m !== lead && m.reading;
    if (follow) lead.resultFollowers.push(m.id);
    world.send(m, { t: 'battleEnd', id: ctx.id, outcome, lines: r.lines, levelUp: !!r.levelUp, story: !!ctx.resolve,
      ...(follow ? { followLeader: lead.char?.name || 'リーダー' } : {}) });
  }
  if (outcome === 'lose') {
    // 負けても よい 戦いは その場で 立ち上がって 物語の つづきへ
    if (ctx.opts.loseOk) for (const m of sessions) fullHeal(m.char);
    else for (const m of sessions) world.respawn(m, perSession[m.id]?.wipeNote);
    for (const a of b.allies) {
      const who = ctx.actorMap[a.id];
      if (who && who.type !== 'human' && who.char) fullHeal(who.char);
    }
  }
  // ずかん: ためした 属性を おぼえる（いっしょに たたかった 人 みんな）
  for (const m of sessions) noteTried(m.char, ctx.battle.tried);
  for (const m of sessions) world.sendSelf(m);
  if (party) world.sendParty(party);
  world.markDirty();
  if (ctx.resolve) ctx.resolve(outcome);
  if (befriend && world.sessions.has(befriend.s.id) && !befriend.s.away) world.offerBefriend(befriend.s, befriend.species, befriend.level, befriend.share);
}

js/shared/world/boss-hints.js:
// 第80回 E班: ボスに 負けた 時の ヒント（docs/plan-r80-hints.md。ネタバレ注意）
//
// 流れ
//   1. ボスの きまった 戦い（boss: true・loseOk で ない・BOSS_HINTS に ある 戦い）で 全滅すると、
//      world/battles.js の finishBattle が bossHintAfter を よぶ → その 戦いに 出た 人 みんなの キャラに 負けた 回数を 1 足す
//      （c.bossLoss = { 戦いの id: 回数 }。ふだんは この 項目は ない。勝つと 消える。引っこしコードは ほとんど 長く ならない）
//      その 人の s.bossHint に 「何を 言うか」を おく
//   2. いのりの場所で 目を 覚まして、けっかを 読みおわった あと（world.js の tick。進化の たずねと 同じ ころ）に bossHintCheck が
//      その 戦いの ゲスト（いなければ トキネ）の ひとことで ヒントを 言う（回数ごとに 1つ目 → 2つ目 → 3つ目）
//   3. リーダー（ひとりの 時は 自分）は「もう一度いどむ／あとにする」を えらぶ。もう一度 … ボスの 台本が 始まる マスの 手前へ
//      （いっしょに 戦って、同じ 所で 目を 覚ました 家族も いっしょに）。行き先が 分からない 戦いは えらぶ 文を 出さない
//   全滅の 決まり（お金が 半分・いのりの場所で 回復）は かえない
import { BOSS_HINTS, BOSS_RETRY, BOSS_HINT_WHO, HINT_SPEAKER, bossHintAt } from '../data/boss-hints.js';
import { MAPS, canStand, isBlocked } from '../maps/index.js';
import { runSteps } from './scripts.js';
import { partyOf } from './party.js';

const LOSS_MAX = 9;

// 負けた 回数（ない ときは 0）
export function bossLossOf(c, id) {
  return Math.max(0, Math.floor(Number(c?.bossLoss?.[id]) || 0));
}

// ヒントを 出す 戦いか（ボスの きまった 戦い・負けても よい 戦いで ない・ヒントが ある）
export function hintBattle(opts) {
  return !!(opts?.boss && opts.fixed && !opts.loseOk && !opts.solo && BOSS_HINTS[opts.fixed]);
}

function addLoss(c, id) {
  if (!c) return 0;
  const n = Math.min(LOSS_MAX, bossLossOf(c, id) + 1);
  c.bossLoss = { ...(c.bossLoss && typeof c.bossLoss === 'object' ? c.bossLoss : {}), [id]: n };
  return n;
}

export function clearLoss(c, id) {
  if (!c?.bossLoss || typeof c.bossLoss !== 'object') return;
  delete c.bossLoss[id];
  if (!Object.keys(c.bossLoss).length) delete c.bossLoss;
}

// その 戦いの ゲスト（いなければ トキネ）
function speakerOf(ctx) {
  if (BOSS_HINT_WHO[ctx.opts.fixed]) return BOSS_HINT_WHO[ctx.opts.fixed];
  const g = Object.values(ctx.actorMap || {}).find((w) => w?.type === 'guest' && w.char?.name);
  return g ? g.char.name : HINT_SPEAKER;
}

// finishBattle から（勝った → 数を 消す・全滅 → 数を 足して ヒントの よやく）
export function bossHintAfter(world, ctx, sessions, outcome) {
  if (!hintBattle(ctx.opts)) return;
  const id = ctx.opts.fixed;
  if (outcome === 'win') {
    for (const m of sessions) clearLoss(m.char, id);
    return;
  }
  if (outcome !== 'lose') return;
  const party = world.parties.get(ctx.partyId);
  const chooser = sessions.find((m) => m.id === party?.leader) || sessions[0];
  const who = speakerOf(ctx);
  const sids = sessions.map((m) => m.id);
  for (const m of sessions) {
    const n = addLoss(m.char, id);
    m.bossHint = { id, n, who, map: ctx.map, choose: m === chooser, sids };
  }
}

// ───── もう一度いどむ 行き先 ─────
// その ボスの 台本が 始まる マス（trigger）の 手前（ボスと 反対の がわ・2〜8マス はなれた 立てる マス・そこから マスまで 歩ける）
function reaches(map, sx, sy, tr, hasFlag, limit = 40000) {
  const inTr = (x, y) => x >= tr.x && y >= tr.y && x < tr.x + tr.w && y < tr.y + tr.h;
  const seen = new Set([sy * map.w + sx]);
  const q = [[sx, sy]];
  for (let h = 0; h < q.length && h < limit; h++) {
    const [x, y] = q[h];
    if (inTr(x, y)) return true;
    for (const [dx, dy] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h) continue;
      const k = ny * map.w + nx;
      if (seen.has(k) || isBlocked(map, nx, ny, hasFlag)) continue;
      seen.add(k);
      q.push([nx, ny]);
    }
  }
  return false;
}

export function retryTrigger(id, mapId) {
  const sc = BOSS_RETRY[id];
  if (!sc) return null;
  const find = (m) => (m?.triggers || []).find((t) => t.script === sc);
  if (find(MAPS[mapId])) return { mapId, map: MAPS[mapId], tr: find(MAPS[mapId]), sc };
  for (const [mid, m] of Object.entries(MAPS)) {
    const tr = find(m);
    if (tr) return { mapId: mid, map: m, tr, sc };
  }
  return null;
}

// { map, x, y, dir } か null（分からない）
export function retrySpot(id, mapId, hasFlag = () => false) {
  const t = retryTrigger(id, mapId);
  if (!t) return null;
  const { map, tr, sc } = t;
  const flat = tr.w >= tr.h; // よこに 長い マス（ボスは 上か 下）
  const npc = (map.npcs || []).find((n) => n.script === sc);
  // ボスの がわ（-1 … 上・左 / +1 … 下・右）。ボスが いない マスは 階段（warps）の 多い がわから 来る
  let bossSide;
  if (npc) bossSide = flat ? (npc.y < tr.y ? -1 : 1) : (npc.x < tr.x ? -1 : 1);
  else {
    let lo = 0, hi = 0;
    for (const w of map.warps || []) {
      const v = flat ? w.y : w.x, a = flat ? tr.y : tr.x, b = flat ? tr.y + tr.h : tr.x + tr.w;
      if (v < a) lo++;
      else if (v >= b) hi++;
    }
    bossSide = hi >= lo ? -1 : 1;
  }
  const side = -bossSide;
  const span = flat ? [tr.x, tr.w] : [tr.y, tr.h];
  const mid = span[0] + Math.floor((span[1] - 1) / 2);
  const offs = [0];
  for (let k = 1; k <= span[1]; k++) offs.push(k, -k);
  // 2〜8マス はなれた 所から さがす。ない 時は となりの 列（時計塔 5階のように マスの すぐ 下が かべの 階）
  for (const d of [2, 3, 4, 5, 6, 7, 8, 1]) {
    const line = side > 0 ? (flat ? tr.y + tr.h - 1 : tr.x + tr.w - 1) + d : (flat ? tr.y : tr.x) - d;
    for (const o of offs) {
      const along = mid + o;
      const [x, y] = flat ? [along, line] : [line, along];
      if (x < 0 || y < 0 || x >= map.w || y >= map.h) continue;
      if (!canStand(map, x + 0.5, y + 0.5, hasFlag)) continue;
      if (!reaches(map, x, y, tr, hasFlag)) continue;
      const dir = flat ? (side > 0 ? 'up' : 'down') : (side > 0 ? 'left' : 'right');
      return { map: t.mapId, x: x + 0.5, y: y + 0.5, dir };
    }
  }
  return null;
}

// ───── ヒントの 台本 ─────
const LEADS = [
  'さっきの戦い、くやしかったね…。\nヒントを1つ、思いついたよ。',
  'もう一度、よく考えてみたよ。',
  'こうすれば、きっと勝てるよ！',
];

export function bossHintSteps(h, dest) {
  const hint = bossHintAt(h.id, h.n);
  if (!hint) return [];
  const steps = [
    ['say', h.who, LEADS[Math.min(h.n, LEADS.length) - 1]],
    ['say', h.who, hint],
  ];
  if (!dest) return steps;
  if (!h.choose) {
    steps.push(['say', null, '（もう一度いどむかは、リーダーが決めるよ）']);
    return steps;
  }
  steps.push(['choice', 'どうする？', ['もう一度いどむ', 'あとにする'], [
    [['call', (run) => retryNow(run, h)]],
    [['say', h.who, 'じゅんびを整えてから、また行こうね。\n（ヒントは、冒険のしおりの「物語」でも見られるよ）']],
  ]]);
  return steps;
}

// もう一度いどむ: 自分（台本）と、いっしょに 戦って 同じ 所に いる 家族を ボスの 手前へ
async function retryNow(run, h) {
  const w = run.world;
  const s = run.init;
  const dest = retrySpot(h.id, h.map, w.hasFlagFn(s));
  if (!dest) return;
  const from = s.map;
  const others = (h.sids || []).map((sid) => w.sessions.get(sid)).filter((m) => m && m !== s && m.inWorld && !m.away && m.map === from && m.busy !== 'battle' && partyOf(w, m) === partyOf(w, s));
  await run.runSteps([['fade', 'out'], ['teleport', dest.map, dest.x, dest.y, dest.dir]]);
  for (const m of others) {
    const at = canStand(MAPS[dest.map], dest.x, dest.y + (dest.dir === 'up' ? 1 : -1), w.hasFlagFn(s)) ? { x: dest.x, y: dest.y + (dest.dir === 'up' ? 1 : -1) } : { x: dest.x, y: dest.y };
    w.placeSession(m, dest.map, at.x, at.y, dest.dir, true);
  }
  if (others.length) w.broadcastPlayers?.();
  await run.runSteps([['fade', 'in'], ['say', h.who, 'この先に、さっきの相手がいるよ。\nヒントを思い出して、がんばろう！']]);
}

// world.js の tick から（ひまに なった 時に 1回だけ）
export function bossHintCheck(world, s) {
  const h = s.bossHint;
  s.bossHint = null;
  if (!h || !world.sessions.has(s.id) || !s.inWorld) return false;
  const dest = retrySpot(h.id, h.map, world.hasFlagFn(s));
  const steps = bossHintSteps(h, dest);
  if (!steps.length) return false;
  runSteps(world, s, steps);
  return true;
}

js/shared/world/breed.js:
// まものの はいごう（ドラゴンクエストモンスターズ ふう。第35回で 作りなおし）
//   生まれる 子の 候補・＋・ランクは data/companions.js の breedOutcome、能力の 受けつぎ・めやす・血統は shared/breed-calc.js
//   どちらも 酒場の 画面（client/ui/services.js）と 同じ 計算
import { MONSTERS } from '../data/monsters.js';
import { ABILITIES } from '../data/abilities.js';
import { ITEMS, SLOTS } from '../data/items.js';
import { MONSTER_FRIENDS, BREED_MIN_LEVEL, BREED_INHERIT_MAX, BREED_INHERIT_TOTAL, breedOutcome, bestiaryKnow, RANKS } from '../data/companions.js';
import { ougiLearn } from '../data/abilities-ougi.js';
import { computeStats, learnedAbilities, newMonsterCompanion, addItem, removeItem, itemCount } from '../stats.js';
// 第43回 A: 配合の あとの 追いつき
import { catchUpLevel } from '../stats.js';
// 第44回: 大事な物を 使う 素材配合（ミュウ）
import { hasKeyItem } from '../stats.js';
import { inheritBonus, breedForecast, makeLineage } from '../breed-calc.js';
import { ensureCompanions, companionOf, putInParty, afterRosterChange } from './party.js';
// 第43回 C: あずかり中の 魔物も 親に なれる（world/party.js の breedEntry・world/storage.js）
import { breedEntry, storedOf } from './party.js';
// 第53回 D: 色の石で 色ちがいの 子（data/variants.js・data/breed-mix.js）
import { VARIANT_KINDS, colorKinds } from '../data/variants.js';
import { COLOR_STONE } from '../data/breed-mix.js';
// 第70回: 作れる 魔物から 選ぶ（shared/breed-finder.js）
import { MATERIAL_RECIPES } from '../data/companions.js';
import { breedParents, breedMatrix, kidList, kidSummary, kidPairs } from '../breed-finder.js';

// おやから うけつげる わざ（第43回 B: 親ごとに 4つずつ・あわせて 8つ。docs/plan-monsters.md の 2-4）
//   { a: [親A の 技], b: [親B の 技] }。両方の 親が 知っている 技は a に だけ 入れる（1つと 数える。b の あいた ぶんは ほかの 技から えらべる）
//   かくれた 技・系統の おうぎ（data/abilities-ougi.js）・子が じぶんで 覚える 技（child を わたした とき）は のぞく
export function inheritableSkills(A, B, child = null) {
  const own = ownSkills(child);
  const seen = new Set();
  const list = (p) => {
    const out = [];
    for (const id of learnedAbilities(p.char)) {
      const ab = ABILITIES[id];
      if (!ab || ab.hidden || ab.ougi || own.has(id) || seen.has(id)) continue;
      seen.add(id);
      out.push(id);
    }
    return out;
  };
  const a = list(A);
  return { a, b: list(B) };
}

// 子が じぶんで 覚える 技（しゅぞくの 技・系統の おうぎ）
function ownSkills(child) {
  const own = new Set((MONSTER_FRIENDS[child]?.learn || []).map(([, id]) => id));
  for (const [, id] of ougiLearn(MONSTERS[child]?.race)) own.add(id);
  return own;
}

// MPの おおきい（つよい）じゅんに n こ
const strongest = (ids, n = BREED_INHERIT_MAX) => [...ids].sort((x, y) => (ABILITIES[y].mp || 0) - (ABILITIES[x].mp || 0)).slice(0, n);

// おまかせ: 親ごとに MPの おおきい（つよい）わざから 4つずつ（こどもが じぶんで おぼえる ものは のぞく）。{ a: [], b: [] }
export function autoInherit(A, B, child) {
  const sk = inheritableSkills(A, B, child);
  return { a: strongest(sk.a), b: strongest(sk.b) };
}

// うけつぐ わざを えらんだ ものに しぼる（親ごとに 4つまで・あわせて 8つまで）
//   inherit: { a: [], b: [] }（第43回 B）か、前の 平らな ならび（どちらの 親の 技かで わける）。それ いがいは おまかせ
export function pickInherit(sk, inherit, auto) {
  let a, b;
  if (Array.isArray(inherit)) {
    a = inherit.filter((id) => sk.a.includes(id));
    b = inherit.filter((id) => sk.b.includes(id));
  } else if (inherit && typeof inherit === 'object' && (Array.isArray(inherit.a) || Array.isArray(inherit.b))) {
    a = (Array.isArray(inherit.a) ? inherit.a : []).filter((id) => sk.a.includes(id));
    b = (Array.isArray(inherit.b) ? inherit.b : []).filter((id) => sk.b.includes(id));
  } else return { a: [...auto.a], b: [...auto.b] };
  const uniq = (l) => [...new Set(l)].slice(0, BREED_INHERIT_MAX);
  return { a: uniq(a), b: uniq(b) };
}

// 配合の 計算に わたす 親（companions.js・breed-calc.js の 形）
const parentOf = (e) => ({ ...e.char, species: e.species });

// はいごうの まえに みせる じょうほう（pick: えらんだ 子。なければ おすすめ〈いちばん 上〉）
//   choices: 生まれる ことが ある 子 みんな（{ sp, kind, rank, item, unseen, plus, trend }）。2つ いじょうなら 酒場で えらぶ
export function breedPreview(c, keyA, keyB, pick = null) {
  ensureCompanions(c);
  const A = breedEntry(c, keyA), B = breedEntry(c, keyB);
  if (!A || !B || A === B) return { ok: false, reason: '魔物を2ひき選んでね' };
  if (A.kind !== 'monster' || B.kind !== 'monster') return { ok: false, reason: '配合できるのはモンスターの仲間だけ' };
  if (A.char.level < BREED_MIN_LEVEL || B.char.level < BREED_MIN_LEVEL) return { ok: false, reason: `レベル${BREED_MIN_LEVEL}以上の魔物同士でないと配合できない` };
  const pa = parentOf(A), pb = parentOf(B);
  const o = breedOutcome(pa, pb, MONSTERS, c, pick);
  if (!o.ok) return { ok: false, reason: 'その魔物は生まれない' };
  const know = bestiaryKnow(c);
  const choices = o.items.map((it) => {
    const plus = breedOutcome(pa, pb, MONSTERS, c, it.sp).plus;
    return { sp: it.sp, kind: it.kind, rank: RANKS[it.rank], item: it.item || null, unseen: know(it.sp) === 0, low: o.items[0] && it.rank < RANKS.indexOf(o.hi), plus, trend: breedForecast(pa, pb, it.sp, plus).trend };
  });
  const fc = breedForecast(pa, pb, o.child, o.plus);
  return {
    ok: true, child: o.child, childName: MONSTERS[o.child].name, plus: o.plus, rank: o.rank, special: o.special, kind: o.kind, item: o.item,
    itemName: o.item ? ITEMS[o.item]?.name || '' : '', unseen: o.unseen, firstFriend: o.firstFriend, count: o.count, unseenCount: o.unseenCount,
    choices, trend: fc.trend, cap: fc.cap,
    // 受けつげる 技（第43回 B）: skills・auto は { a: 親A, b: 親B }。max は 親ごと（4）・total は あわせて（8）。names は 列の 見出し
    skills: inheritableSkills(A, B, o.child), auto: autoInherit(A, B, o.child), max: BREED_INHERIT_MAX, total: BREED_INHERIT_TOTAL,
    names: { a: A.char.name, b: B.char.name },
    // 第53回 D: 色の石（stone … ふくろの 数）で えらべる 色ちがい（colors … { kind, name }。色ちがいが ない 子は から）
    stone: itemCount(c, COLOR_STONE), colors: colorKinds(o.child).map((kind) => ({ kind, name: `${VARIANT_KINDS[kind].prefix}${MONSTERS[o.child].name}` })),
  };
}

// はいごう する。child: えらんだ 子（なければ おすすめ）、inherit: うけつぐ わざ（{ a: [], b: [] } で 親ごとに 4つまで。前の 平らな ならびも よい。なければ おまかせ）、name: こどもの なまえ
//   color: 色の石を 使う 色ちがいの しゅるい（第53回 D。pv.colors の どれか。色の石は 配合できた ときだけ なくなる）
export function breedMonsters(world, s, { a, b, child, inherit, name, color } = {}) {
  const c = ensureCompanions(s.char);
  const pv = breedPreview(c, a, b, child || null);
  if (!pv.ok) return pv;
  if (color && !pv.colors.some((x) => x.kind === color)) return { ok: false, reason: 'その色ちがいは生まれない' };
  if (color && pv.stone < 1) return { ok: false, reason: '色の石がふくろにない' };
  const colorName = color ? pv.colors.find((x) => x.kind === color).name : '';
  // 素材配合: ボスの 品が ふくろに ある か（配合すると なくなる）
  // 第44回: ふしぎないでんし（ミュウ）は 大事な物（c.keyItems）
  const keyItem = !!pv.item && ITEMS[pv.item]?.type === 'key';
  if (pv.item && (keyItem ? !hasKeyItem(c, pv.item) : itemCount(c, pv.item) < 1)) return { ok: false, reason: `${pv.itemName}がふくろにない` };
  const A = breedEntry(c, a), B = breedEntry(c, b);
  // あずかり中の 親から 生まれた 子は あずかり所に 入る（仲間の 親の ぶん 1つ あく。第43回 C）
  const fromStore = !!(storedOf(c, a) || storedOf(c, b));
  const chosen = pickInherit(pv.skills, inherit, pv.auto);
  // ch.inherit は 前と 同じ 平らな ならび（8つまで。セーブの 形は かわらない）
  const pick = [...chosen.a, ...chosen.b].slice(0, BREED_INHERIT_TOTAL);
  const nm = String(name || '').replace(/[<>&"'\s]/g, '').slice(0, 8) || (colorName.length <= 8 ? colorName : '') || MONSTERS[pv.child].name;
  const wasInParty = c.partyKeys.includes(a) || c.partyKeys.includes(b);
  // 受けつぐ 能力と 血統は 親が いる うちに
  const bonus = inheritBonus(parentOf(A), parentOf(B));
  const lineage = makeLineage(parentOf(A), parentOf(B));
  if (keyItem) c.keyItems = c.keyItems.filter((k) => k !== pv.item);
  else if (pv.item) removeItem(c, pv.item, 1);
  if (color) removeItem(c, COLOR_STONE, 1);
  // おやは たびだっていく（そうびは ふくろへ）
  for (const p of [A, B]) for (const slot of SLOTS) if (p.char.equip?.[slot]) addItem(c, p.char.equip[slot], 1);
  c.companions = c.companions.filter((e) => e !== A && e !== B);
  if (fromStore) c.storage = c.storage.filter((e) => e !== A && e !== B);
  c.partyKeys = c.partyKeys.filter((k) => k !== a && k !== b);
  if (Array.isArray(c.wagonKeys)) c.wagonKeys = c.wagonKeys.filter((k) => k !== a && k !== b);
  while (c.companions.some((e) => e.key === `m${c.monsterSeq}`)) c.monsterSeq++;
  const key = 'm' + (c.monsterSeq++);
  const ch = newMonsterCompanion({ id: `${c.id}:${key}`, name: nm, species: pv.child, level: 1 });
  ch.plus = pv.plus;
  ch.bonus = bonus;
  ch.inherit = pick;
  ch.parents = [A.char.name, B.char.name];
  ch.lineage = lineage;
  if (color) ch.color = color;
  // 第43回 A: 追いつき（強いほうの 親の レベルの 3/4 までは 経験値 3倍。stats.js の gainExp）
  ch.catchUp = catchUpLevel(A.char, B.char);
  const st = computeStats(ch);
  ch.hp = st.maxHp;
  ch.mp = st.maxMp;
  (fromStore ? c.storage : c.companions).push({ key, kind: 'monster', species: pv.child, char: ch });
  if (wasInParty && !fromStore) putInParty(c, key);
  c.bestiary = c.bestiary || {};
  const bs = c.bestiary[pv.child] || (c.bestiary[pv.child] = {});
  bs.bred = (bs.bred || 0) + 1;
  bs.friend = (bs.friend || 0) + 1;
  // 第53回 D: 図鑑に 色ちがいの しるし（color_<しゅるい>。数）
  if (color) bs[`color_${color}`] = (bs[`color_${color}`] || 0) + 1;
  afterRosterChange(world, s);
  return { ok: true, key, name: nm, species: pv.child, plus: pv.plus, rank: pv.rank, kind: pv.kind, itemName: pv.itemName, inherit: pick, joined: wasInParty && !fromStore, newEntry: pv.unseen, stored: fromStore, color: color || null, colorName };
}

// 第70回: 作れる 魔物から 選ぶ（酒場の「作れる魔物から選ぶ」。みるだけ・なにも かわらない）
//   child なし … 生まれる 子の 一覧（kids。shared/breed-finder.js の kidList）
//   child あり … その 子が 生まれる 2ひきの 組（pairs。よい じゅん。多い ときは PAIR_MAX まで ＋ more）
//   low … ランクが 下がる 子・組も 見る / room … 配合して あける モード（あずかり中 どうしは のぞく）
//   parents … 親の key → { name, species, level, plus, where〈party・wagon・tavern・storage〉, color }
//   同じ 親・同じ 品の あいだは さがし表を セッションに 覚えて おく（一覧 → 組 と 2回 きいても 1回だけ 計算）
export const PAIR_MAX = 60;
function finderSig(c, parents, room) {
  const mats = MATERIAL_RECIPES.map((r) => r.item).filter((id, i, a) => a.indexOf(id) === i)
    .filter((id) => (c.items || []).some((e) => e && e.id === id && e.n > 0) || (c.keyItems || []).includes(id));
  const ps = parents.map((p) => [p.key, p.species, p.level, p.plus || 0, p.bonus || null, p.seeds || null, p.lineage?.p || null, p.where]);
  return JSON.stringify([room ? 1 : 0, mats, ps]);
}
export function breedFinder(s, { child = null, low = false, room = false } = {}) {
  const c = ensureCompanions(s.char);
  const parents = breedParents(c);
  const sig = finderSig(c, parents, room);
  let memo = s.breedFinderMemo;
  if (!memo || memo.sig !== sig) {
    memo = { sig, m: breedMatrix(parents, MONSTERS, c, { room }) };
    s.breedFinderMemo = memo;
  }
  const { m } = memo;
  // 図鑑は 配合の あとで かわるので、ここで 見なおす
  const know = bestiaryKnow(c);
  for (const k of m.kids.values()) k.know = know(k.sp);
  const info = {};
  for (const p of parents) info[p.key] = { name: p.name, species: p.species, level: p.level, plus: p.plus || 0, where: p.where, ...(p.color ? { color: p.color } : {}) };
  const out = { ok: true, parents: info, count: parents.length, pairCount: m.pairs, low: !!low };
  if (child) {
    const k = m.kids.get(child);
    if (!k) return { ...out, ok: false, reason: 'その魔物は今の仲間からは生まれない' };
    const all = kidPairs(k, low);
    return { ...out, child: kidSummary(k, MONSTERS, low), pairs: all.slice(0, PAIR_MAX).map((p) => ({ ...p })), more: Math.max(0, all.length - PAIR_MAX) };
  }
  const kids = kidList(m.kids, MONSTERS, low);
  const hidden = low ? 0 : kidList(m.kids, MONSTERS, true).length - kids.length;
  return { ...out, kids, hidden };
}

