// カジノ（コイン・スロット・ポーカー・景品）と 小さなメダル（見つける・メダル王）の しょり
//
// 乱数と コインの 計算は ぜんぶ ここ（サーバー）。クライアントの メッセージは ひとつずつ たしかめる。
//   s.casino … いま 開いている まど（'coins' 'slot' 'poker' 'prizes' 'medal'）
//   s.poker  … ポーカーの とちゅう（くばった カード・賭けた コイン・ダブルアップ）。セーブには のこさない
// キャラクターに のこす もの（どれも なくても よい。むかしの セーブも そのまま 読める）
//   c.coins        … コインの 数
//   c.medalSpots   … 小さなメダルを 見つけた 場所 { id: 時こく }
//   c.medalsGiven  … メダル王に わたした 数
//   c.medalRewards … もらった ごほうび { 5: true, 10: true, … }
//   c.prizeSeen    … 第50回 D3: 景品の NEW の しるしの ため 見た 品（world/prizes-r50.js）
import { ITEMS } from '../data/items.js';
import { addItem } from '../stats.js';
import {
  COIN_PRICE, COIN_MAX, COIN_BUY_MAX, COIN_PACKS, coinsOf, SLOT_BETS, REELS, slotLine, slotPay,
  POKER_BETS, JOKER, DOUBLE_MAX, evalPoker, doubleOutcome, PRIZES, prizesFor, MEDAL_REWARDS,
  medalsFound, medalsGiven, medalsHeld, medalRewardOpen,
} from '../data/casino.js';
// 第50回 D3: 景品の NEW の しるし・なかま・乗り物券の かさなり・メダル王の お話で ふえる ごほうび
import { casinoPrizeShelf, prizeBlock, prizeHave, medalRewardRows, medalFresh } from './prizes-r50.js';
import { MEDAL_SPOTS, MEDAL_SPOT_BY_ID, medalSparkleId } from '../maps/casino.js';
import { MAPS, tileAt, condOk } from '../maps/index.js';
import { T } from '../tiles.js';
// 第37回 B: ルーレット・すごろく場・宝の地図の 段で ふえる 景品
import { ROULETTE_CHIPS, ROULETTE_MAX_TOTAL, normBets, roulettePayout } from '../data/roulette.js';
import { tierInfo } from '../data/casino-tier.js';
import { sugorokuInfo, sugorokuAction } from './sugoroku.js';
import { SUGOROKU_MAP } from '../data/sugoroku.js';

// 見つけた 光る 場所は もう 光らない（sparkles の 時こくを ずっと 先に）
export const MEDAL_TAKEN_AT = 9e15;
const fmt = (n) => Number(n).toLocaleString('ja-JP');
const CASINO_MODES = { coins: 'coins', slot1: 'slot', slot10: 'slot', poker: 'poker', prizes: 'prizes', roulette: 'roulette', sugoroku: 'sugoroku' };
// その まどを 開ける マップ（すごろくは カジノの 地下の すごろく場）
const MODE_MAP = { sugoroku: SUGOROKU_MAP };

// ───────────── まどを 開く ─────────────
export function casinoOpen(world, s, kind, arg) {
  const c = s.char;
  if (kind === 'medalKing') {
    if (s.map !== 'medal_castle') return null;
    s.casino = 'medal';
    world.markDirty();
    return { mode: 'medal', ...medalInfo(c), fresh: medalFresh(c) };
  }
  const mode = CASINO_MODES[arg];
  if (kind !== 'casino' || !mode || s.map !== (MODE_MAP[mode] || 'casino')) return null;
  settlePoker(world, s);
  s.casino = mode;
  const base = { mode, coins: coinsOf(c), coinMax: COIN_MAX };
  switch (mode) {
    case 'coins': return { ...base, price: COIN_PRICE, packs: COIN_PACKS, buyMax: COIN_BUY_MAX };
    case 'slot': return { ...base, bets: SLOT_BETS, bet: arg === 'slot10' ? 10 : 1 };
    case 'poker': return { ...base, bets: POKER_BETS, doubleMax: DOUBLE_MAX };
    case 'prizes': {
      // 宝の地図の クリア数の 段で 景品が ふえる（tier。data/casino-tier.js）
      const t = tierInfo(c);
      // 第50回 D3: NEW（前に 開いた ときに なかった 品）・なかま（装備・見た目・便利・魔物）・持っている 品
      const { prizes, fresh, cats } = casinoPrizeShelf(c, t.tier);
      const story = PRIZES.some((p) => p.need && !c.flags?.[p.need]);
      const have = prizes.filter((p) => prizeHave(c, p.id)).map((p) => p.id);
      world.markDirty();
      return { ...base, prizes, more: prizes.length < PRIZES.length, story, tier: t, fresh, cats, have };
    }
    case 'roulette': return { ...base, chips: ROULETTE_CHIPS, maxTotal: ROULETTE_MAX_TOTAL };
    case 'sugoroku': return { ...base, ...sugorokuInfo(world, s) };
    default: return null;
  }
}

// ポーカーの とちゅうで まどを 閉じた: カードを そのまま 見せて 役を きめる（コインは もどらない ことは ない）
// ダブルアップの カードを えらぶ 前に 閉じたら、賭けた コインは もどらない
function settlePoker(world, s) {
  const p = s.poker;
  s.poker = null;
  if (!p || p.stage !== 'hold') return;
  const win = evalPoker(p.hand).mult * p.bet;
  if (win) addCoins(s.char, win);
  world.markDirty();
}

function addCoins(c, n) {
  const before = coinsOf(c);
  c.coins = Math.min(COIN_MAX, before + n);
  return c.coins - before; // 本当に ふえた 数（持てる 数を こえた ぶんは なくなる）
}

// ───────────── そうさ ─────────────
export function casinoAction(world, s, msg) {
  const c = s.char;
  const reply = (ok, text, extra = {}) => {
    world.sendSelf(s);
    world.send(s, { t: 'svcRes', ok, text, coins: coinsOf(c), gold: c.gold, ...extra });
    world.markDirty();
  };
  // まどが 開いている あいだ（係の人・台の だいほんの とちゅう）だけ
  if (msg.action !== 'close' && s.busy !== 'script') return reply(false, '今はできません');
  if (msg.kind === 'medal') return medalAction(world, s, msg, reply);
  // すごろく場（world/sugoroku.js）
  if (msg.action !== 'close' && s.casino === 'sugoroku') return sugorokuAction(world, s, msg, reply);
  if (s.map !== 'casino' && !(msg.action === 'close' && s.map === SUGOROKU_MAP)) return reply(false, 'ここはカジノではない');
  const want = (mode) => s.casino === mode;
  const coins = coinsOf(c);
  switch (msg.action) {
    case 'buyCoins': {
      if (!want('coins')) return reply(false, '');
      const n = msg.n;
      if (!Number.isInteger(n) || n < 1 || n > COIN_BUY_MAX) return reply(false, 'その枚数は買えません');
      if (coins + n > COIN_MAX) return reply(false, `コインは${fmt(COIN_MAX)}枚までしか持てません`);
      const cost = n * COIN_PRICE;
      if (c.gold < cost) return reply(false, 'ゴールドが足りないようです');
      c.gold -= cost;
      c.coins = coins + n;
      return reply(true, `${fmt(cost)}ゴールドをはらって、コインを${fmt(n)}枚手に入れた！`, { bought: n });
    }
    case 'slot': {
      if (!want('slot')) return reply(false, '');
      const bet = msg.bet;
      if (!SLOT_BETS.includes(bet)) return reply(false, 'その枚数はかけられません');
      if (coins < bet) return reply(false, 'コインが足りません');
      const stops = REELS.map((r) => world.rng.int(0, r.length - 1));
      const line = slotLine(stops);
      const pay = slotPay(line);
      c.coins = coins - bet;
      const win = pay ? addCoins(c, pay.mult * bet) : 0;
      return reply(true, '', { stops, line, pay: pay ? { id: pay.id, name: pay.name, mult: pay.mult } : null, win, bet });
    }
    case 'pokerDeal': {
      if (!want('poker')) return reply(false, '');
      if (s.poker && ['hold', 'pick'].includes(s.poker.stage)) return reply(false, '勝負のとちゅうです');
      const bet = msg.bet;
      if (!POKER_BETS.includes(bet)) return reply(false, 'その枚数はかけられません');
      if (coins < bet) return reply(false, 'コインが足りません');
      const deck = world.rng.shuffle([...Array(JOKER + 1).keys()]);
      s.poker = { bet, deck, hand: deck.splice(0, 5), stage: 'hold', win: 0, doubles: 0 };
      c.coins = coins - bet;
      return reply(true, '', { hand: s.poker.hand, stage: 'hold', bet });
    }
    case 'pokerDraw': {
      const p = s.poker;
      if (!want('poker') || !p || p.stage !== 'hold') return reply(false, '');
      const hold = msg.hold;
      if (!Array.isArray(hold) || hold.length !== 5) return reply(false, '');
      p.hand = p.hand.map((card, i) => (hold[i] === true ? card : p.deck.shift()));
      const hand = evalPoker(p.hand);
      const win = hand.mult ? addCoins(c, hand.mult * p.bet) : 0;
      p.win = win;
      p.stage = win ? 'won' : 'done';
      return reply(true, '', { hand: p.hand, result: { id: hand.id, name: hand.name, mult: hand.mult }, win, stage: p.stage });
    }
    case 'pokerDouble': {
      // ダブルアップ: 勝った コインを かけて、表の カードより 大きい カードを 4枚の 中から 1枚 えらぶ
      const p = s.poker;
      if (!want('poker') || !p || p.stage !== 'won' || !(p.win > 0)) return reply(false, '');
      if (p.doubles >= DOUBLE_MAX) return reply(false, `ダブルアップは${DOUBLE_MAX}回までです`);
      if (coins < p.win) return reply(false, 'コインが足りません');
      const deck = world.rng.shuffle([...Array(JOKER + 1).keys()]);
      const at = deck.findIndex((x) => x !== JOKER);
      const shown = deck.splice(at, 1)[0];
      p.shown = shown;
      p.cards = deck.slice(0, 4);
      p.stake = p.win;
      p.stage = 'pick';
      c.coins = coins - p.stake;
      return reply(true, '', { shown, stage: 'pick', stake: p.stake, doubles: p.doubles });
    }
    case 'pokerPick': {
      const p = s.poker;
      if (!want('poker') || !p || p.stage !== 'pick') return reply(false, '');
      const i = msg.i;
      if (!Number.isInteger(i) || i < 0 || i > 3) return reply(false, '');
      const outcome = doubleOutcome(p.shown, p.cards[i]);
      if (outcome === 'win') {
        p.win = addCoins(c, p.stake * 2);
        p.doubles += 1;
        p.stage = p.doubles >= DOUBLE_MAX ? 'done' : 'won';
      } else if (outcome === 'draw') {
        addCoins(c, p.stake);
        p.stage = 'won';
      } else {
        p.win = 0;
        p.stage = 'done';
      }
      return reply(true, '', { shown: p.shown, cards: p.cards, picked: i, outcome, win: p.win, stage: p.stage, doubles: p.doubles });
    }
    case 'pokerTake': {
      const p = s.poker;
      if (!want('poker') || !p || p.stage !== 'won') return reply(false, '');
      p.stage = 'done';
      return reply(true, '', { win: p.win, stage: 'done' });
    }
    case 'roulette': {
      // ルーレット: かけを たしかめて、玉の 止まる 数は サーバーの 乱数
      if (!want('roulette')) return reply(false, '');
      const nb = normBets(msg.bets);
      if (!nb) return reply(false, 'そのかけ方はできません');
      if (coins < nb.total) return reply(false, 'コインが足りません');
      const n = world.rng.int(0, 36);
      const pay = roulettePayout(nb.bets, n);
      c.coins = coins - nb.total;
      const win = pay.win ? addCoins(c, pay.win) : 0;
      return reply(true, '', { n, win, bet: nb.total, hits: pay.hits });
    }
    case 'prize': {
      if (!want('prizes')) return reply(false, '');
      const pr = prizesFor(c.flags, tierInfo(c).tier).find((x) => x.id === msg.id);
      if (!pr || !ITEMS[pr.id]) return reply(false, 'その景品はありません');
      if (coins < pr.coins) return reply(false, 'コインが足りないようです');
      // 99こ まで・乗り物券は 1つだけ（もう 乗り物を 持っていたら もらえない。world/prizes-r50.js）
      const block = prizeBlock(c, pr.id);
      if (block) return reply(false, block);
      c.coins = coins - pr.coins;
      addItem(c, pr.id, 1);
      return reply(true, `コイン${fmt(pr.coins)}枚と${ITEMS[pr.id].name}をこうかんした！`, { got: pr.id });
    }
    case 'close': {
      settlePoker(world, s);
      s.casino = null;
      return reply(true, '');
    }
    default:
      return reply(false, '');
  }
}

// ───────────── メダル王 ─────────────
function medalInfo(c) {
  return {
    found: medalsFound(c), given: medalsGiven(c), held: medalsHeld(c), total: MEDAL_SPOTS.length,
    // 第50回 D3: locked … お話が 進むと もらえる ごほうび
    rewards: medalRewardRows(c),
  };
}

function medalAction(world, s, msg, reply) {
  const c = s.char;
  if (s.map !== 'medal_castle' || s.casino !== 'medal') return reply(false, '');
  if (msg.action === 'close') {
    s.casino = null;
    return reply(true, '');
  }
  if (msg.action !== 'give') return reply(false, '');
  const held = medalsHeld(c);
  const total = medalsGiven(c) + held;
  c.medalRewards = c.medalRewards && typeof c.medalRewards === 'object' ? c.medalRewards : {};
  // あとから ふえた ごほうび（第31回の 35枚）は、もう わたした 数に とどいていれば メダルが なくても もらえる
  // 第50回 D3: お話が 進むと もらえる ごほうび（need）は、その フラグが つくまで のこしておく
  const open = (r) => medalRewardOpen(c.flags, r);
  const pending = MEDAL_REWARDS.some((r) => r.at <= total && !c.medalRewards[r.at] && open(r));
  if (!held && !pending) return reply(false, '小さなメダルを持っていない', { medal: medalInfo(c) });
  c.medalsGiven = total;
  const got = [];
  for (const r of MEDAL_REWARDS) {
    if (r.at > total || c.medalRewards[r.at] || !open(r)) continue;
    c.medalRewards[r.at] = true;
    for (const [id, n] of r.items) addItem(c, id, n);
    got.push({ at: r.at, items: r.items });
  }
  return reply(true, '', { gave: held, total, got, medal: medalInfo(c) });
}

// ───────────── 小さなメダルを 見つける ─────────────
const SPOT_INDEX = new Map(MEDAL_SPOTS.filter((sp) => sp.how !== 'chest').map((sp) => [`${sp.map}:${sp.x}:${sp.y}`, sp]));

function takeMedal(world, s, spotId) {
  const c = s.char;
  c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
  const first = medalsFound(c) === 0 && medalsGiven(c) === 0;
  c.medalSpots[spotId] = world.now();
  world.markDirty();
  // パーティーの なかまにも 知らせる（見つけた 人だけが もらう）
  const p = world.parties?.get(s.partyId);
  if (p && p.members.length > 1) {
    for (const sid of p.members) if (sid !== s.id) world.send(world.sessions.get(sid), { t: 'toast', text: `${c.name}が小さなメダルを見つけた！` });
  }
  const lines = [];
  if (first) lines.push('小さなメダルは、世界中にかくされている不思議なメダル。\nメダル王という王さまが集めているらしい。');
  lines.push(`持っている小さなメダル: ${medalsHeld(c)}枚${medalsGiven(c) ? `（メダル王にわたした数: ${medalsGiven(c)}枚）` : ''}`);
  return lines.map((l) => ['say', null, l]);
}

// 調べた マス（x, y）に 小さなメダルが あれば だいほん（なければ null … ふつうの 調べる に まかせる）
export function medalSearchSteps(world, s, tx, ty) {
  const sp = SPOT_INDEX.get(`${s.map}:${tx}:${ty}`);
  if (!sp) return null;
  const c = s.char;
  const taken = !!c.medalSpots?.[sp.id];
  const open = condOk(sp.show, world.hasFlagFn(s));
  if (sp.how === 'shine') {
    // 光る 場所は ふつうの きらきら と ちがうので、取った あとは 何も ない
    if (taken || !open) return [['say', null, '何もない。']];
    c.sparkles = c.sparkles && typeof c.sparkles === 'object' ? c.sparkles : {};
    c.sparkles[medalSparkleId(sp.id)] = MEDAL_TAKEN_AT;
    return [['sfx', 'key'], ['say', null, `足元で何かが光っている…\n${c.name}は小さなメダルを拾った！`], ...takeMedal(world, s, sp.id)];
  }
  if (taken || !open) return null;
  const tile = tileAt(MAPS[s.map], tx, ty);
  const found = {
    [T.WELL]: '井戸の中をのぞきこんだ。\nなんと、小さなメダルが落ちていた！',
    [T.FOUNTAIN]: 'ふんすいの底で何かが光っている…\nなんと、小さなメダルを見つけた！',
    [T.BED]: 'ベッドの下を調べた。\nなんと、小さなメダルを見つけた！',
  }[tile];
  const names = { [T.POT]: 'つぼ', [T.BARREL]: 'たる', [T.SHELF]: 'たな', [T.BOOKSHELF]: '本だな', [T.CRATE]: '箱' };
  const text = found || `${c.name}は${names[tile] || 'それ'}を調べた。\nなんと、小さなメダルを見つけた！`;
  return [['sfx', 'key'], ['say', null, text], ...takeMedal(world, s, sp.id)];
}

// 小さなメダルの 宝箱（chest.medal … 場所の id）
export function medalChestSteps(world, s, chest) {
  const c = s.char;
  const sp = MEDAL_SPOT_BY_ID[chest.medal];
  c.chests[chest.id] = true;
  world.markDirty();
  if (!sp || c.medalSpots?.[sp.id]) return [['sfx', 'chest'], ['chestOpen', chest.id], ['say', null, '宝箱は空っぽだ。']];
  return [['sfx', 'chest'], ['chestOpen', chest.id], ['say', null, `${c.name}は宝箱を開けた！\n小さなメダルを手に入れた！`], ['sfx', 'key'], ...takeMedal(world, s, sp.id)];
}

js/shared/world/clock.js:
// 昼と夜（せかいの 時計）
//
// ・時計は サーバーが きめる（world.now()）。1日は DAY_MS（げんじつの 20分）
// ・キャラごとに「時間の ずれ」（char.timeShift）を もつ。宿屋で 休むと ずれが すすむ（朝まで・夜まで）
// ・パーティーでは リーダーの 時計を みんなで 見る（さそわれて 来た 人は リーダーの 時間）
//   ほかの パーティーは それぞれの 時計（家族サーバーで だれかが 宿屋で 休んでも、ほかの 人の 空は かわらない）
// ・クライアントは serverTime（とどいた 時こく）と パーティーの clockShift で おなじ 時間を 出す
//
// 1日の わりあい（frac: 0〜1）。0 が 朝6時
//   0.00〜0.05 明け方 → 0.05〜0.60 昼 → 0.60〜0.70 夕方 → 0.70〜0.95 夜 → 0.95〜1.00 明け方

export const DAY_MS = 20 * 60 * 1000;
export const DUSK_FROM = 0.6;
export const NIGHT_FROM = 0.7;
export const NIGHT_TO = 0.95;
export const DAY_FROM = 0.05;
// 宿屋で 休んだ あとの 時間（noon … 昼の 12時の すこし 前。王都サファラの 宿屋の「昼まで休む」。第4章 Step 3）
export const REST_TO = { morning: 0.02, night: 0.72, noon: 0.23 };

export const PHASE_NAMES = { dawn: '明け方', day: '昼', dusk: '夕方', night: '夜' };

const mod = (a, n) => ((a % n) + n) % n;

export function dayFrac(now, shift = 0) {
  return mod(now + (Number(shift) || 0), DAY_MS) / DAY_MS;
}

export function phaseOf(frac) {
  if (frac < DAY_FROM || frac >= NIGHT_TO) return 'dawn';
  if (frac < DUSK_FROM) return 'day';
  if (frac < NIGHT_FROM) return 'dusk';
  return 'night';
}

// あそびの うえでの 夜（夜の 魔物・夜の 人）
export function isNightFrac(frac) {
  return frac >= NIGHT_FROM && frac < NIGHT_TO;
}

// ───── お日さまの むきと 昼の 12時ごろ（第4章 Step 4: オベリスクの 影と 日時計の とびら）─────
// 昼の 12時ごろ … 11時〜13時（王都の 宿屋の「昼まで休む」は 11時半ごろ。休んで すぐ 歩いて 行ける）
export const NOON_FROM = 5 / 24;
export const NOON_TO = 7 / 24;
export function isNoonFrac(frac) {
  return frac >= NOON_FROM && frac < NOON_TO;
}
// お日さまの いる がわ: 'am'（朝。影は 西へ）/ 'noon'（真上。影は 北へ みじかく）/ 'pm'（午後。影は 東へ）/ null（夜・夕方・明け方）
export function sunSide(frac) {
  if (frac < DAY_FROM || frac >= DUSK_FROM) return null;
  if (frac < NOON_FROM) return 'am';
  if (frac < NOON_TO) return 'noon';
  return 'pm';
}
// '@' で はじまる 時間の しるし（NPC・とびらの 表示じょうけん。world.js の hasFlagFn と client/field.js の hasFlag）
//   '@night' … 夜 / '@noon' … 昼の 12時ごろ / '@am' … 朝の 日ざし / '@pm' … 午後の 日ざし
export function timeFlag(f, frac) {
  if (f === '@night') return isNightFrac(frac);
  if (f === '@noon' || f === '@am' || f === '@pm') return sunSide(frac) === f.slice(1);
  // 第5章 Step 8 の 影の城の 炎の 柱（maps/castle.js）: '@fireA' と '@fireB' が FIRE_HALF ミリびょう ごとに こうたい
  if (f === '@fireA' || f === '@fireB') return firePhase(frac) === (f === '@fireA' ? 0 : 1);
  return false;
}
// 影の城の 炎の 柱の じゅんばん（0 … A の 柱が ふき上がる / 1 … B の 柱が ふき上がる）。1日（DAY_MS）は FIRE_HALF で わりきれる
export const FIRE_HALF = 2400;
export function firePhase(frac) {
  return Math.floor((mod(frac, 1) * DAY_MS) / FIRE_HALF + 1e-6) % 2;
}

// くらさ（0＝昼 〜 1＝まよなか）。夕方と 明け方は だんだん
export function darkness(frac) {
  if (frac >= DAY_FROM && frac < DUSK_FROM) return 0;
  if (frac >= DUSK_FROM && frac < NIGHT_FROM) return (frac - DUSK_FROM) / (NIGHT_FROM - DUSK_FROM);
  if (frac >= NIGHT_FROM && frac < NIGHT_TO) return 1;
  // 明け方（0.95〜1.0 と 0〜0.05 を つなげて）
  const t = frac >= NIGHT_TO ? frac - NIGHT_TO : frac + (1 - NIGHT_TO);
  return Math.max(0, 1 - t / (1 - NIGHT_TO + DAY_FROM));
}

// 時こく（6時から はじまる 24時間。時計の 表示用）
export function clockHour(frac) {
  return Math.floor(mod(6 + frac * 24, 24));
}

// until（'morning'・'night'・'noon'）まで 時間を すすめた あとの ずれ（かならず 先へ すすむ）
export function restShift(now, shift, until) {
  const target = REST_TO[until] ?? REST_TO.morning;
  const cur = dayFrac(now, shift);
  let step = mod(target - cur, 1);
  if (step < 0.01) step += 1; // もう その 時間なら つぎの 日の その 時間
  return Math.round(mod((Number(shift) || 0) + step * DAY_MS, DAY_MS));
}

// ───── せかい（サーバー）の 時計 ─────
// その 人が 見ている 時計の もちぬし（さそわれて 手伝っている ときは リーダー）
export function clockOwner(world, s) {
  return world.hostOf?.(s) || s;
}

export function clockShiftOf(world, s) {
  return Number(clockOwner(world, s)?.char?.timeShift) || 0;
}

export function fracFor(world, s) {
  return dayFrac(world.now(), clockShiftOf(world, s));
}

// どうくつ・塔の 中は 夜でも かわらない（夜の 魔物は フィールドだけ）
export function isNightFor(world, s) {
  return isNightFrac(fracFor(world, s));
}

// 昼の 12時ごろか（パーティーの 時計。日時計の とびら）
export function isNoonFor(world, s) {
  return isNoonFrac(fracFor(world, s));
}

// 時計を すすめる（宿屋・夜明けのすず）。パーティーの 時計の もちぬしの ずれを かえる
export function advanceClock(world, s, until) {
  const owner = clockOwner(world, s);
  if (!owner?.char) return 0;
  const shift = restShift(world.now(), owner.char.timeShift, until);
  owner.char.timeShift = shift;
  world.markDirty?.();
  return shift;
}

js/shared/world/escape.js:
// みちびきの糸（サーバーの きまり）: 洞窟・塔の 中から、入ってきた 入り口の 外へ もどる
//   データは data/escape.js
//
// どこへ もどるか（新しい 洞窟でも データを たさずに うごく ように）
// ・宝の洞窟（'tm_…'）… 地図の 場所（ほった 穴の そば）
// ・ほかの 洞窟・塔 … ワープを たどって、フィールドへ 出る 出口を さがす（何階でも）。
//   出口が いくつも ある ときは、入ってきた 場所（c.dungeonFrom）に いちばん 近い 出口
// ・出口が 見つからない（イベントで 入った 場所 など）ときは、入る まえに いた 場所へ
// ・ひみつのダンジョンの 階（map.sd.floor）… 入口の 広間（第79回。world/secret.js の secretEscape。全滅で もどる 時と おなじ あつかい）
//
//   c.dungeonFrom … フィールドから 洞窟に 入った ときの 外の 場所 { map, x, y, dir, in: 入った 洞窟 }
//                   （placeSession で おぼえる。セーブに のこるので 読みこみなおしても 使える）
import { MAPS } from '../maps/index.js';
import { ITEMS } from '../data/items.js';
import { itemCount, removeItem } from '../stats.js';
import { warpParty } from './travel.js';
import { treasureExitPoint } from './treasure.js';
// 第79回: ひみつのダンジョンの 階では、糸・リレミトで 入口の 広間へ（帰り道の羽・ルーラは 今まで どおり 使えない）
import { secretEscape } from './secret.js';
import { SD_NAME } from '../data/secret.js';

// 糸が 使える マップ（洞窟・塔・宝の洞窟。カジノや お城などの たてものの 中は のぞく）
export function isDungeonMap(m) {
  return !!m && m.kind === 'dungeon' && !m.indoor;
}

// world.placeSession から よぶ: フィールドから 洞窟へ 入った ときの 場所を おぼえる（外に 出たら わすれる）
export function noteDungeonEntry(s, from, toMap) {
  const c = s?.char;
  if (!c || !from || from.map === toMap) return;
  const a = MAPS[from.map], b = MAPS[toMap];
  if (!b) return;
  if (isDungeonMap(b)) {
    if (a && !isDungeonMap(a) && Number.isFinite(from.x) && Number.isFinite(from.y)) {
      c.dungeonFrom = { map: from.map, x: from.x, y: from.y, dir: from.dir || 'down', in: toMap };
    }
  } else if (c.dungeonFrom) delete c.dungeonFrom;
}

// ワープで つながっている 洞窟の 階（今の 階から 近い じゅん）と、フィールドへの 出口
function chainOf(mapId) {
  const floors = [mapId];
  const seen = new Set(floors);
  const exits = [];
  for (let i = 0; i < floors.length && i < 64; i++) {
    for (const w of MAPS[floors[i]]?.warps || []) {
      const to = w?.to;
      const m = to && MAPS[to.map];
      if (!m) continue;
      if (isDungeonMap(m)) {
        if (!seen.has(m.id)) {
          seen.add(m.id);
          floors.push(m.id);
        }
      } else if (!exits.some((e) => e.map === to.map && Math.hypot(e.x - to.x, e.y - to.y) < 1.5)) {
        exits.push({ map: to.map, x: to.x, y: to.y, dir: to.dir || 'down' });
      }
    }
  }
  return { floors: seen, exits };
}

// もどる 場所（{ map, x, y, dir }）。わからなければ null
export function dungeonExit(world, s) {
  const m = MAPS[s?.map];
  if (!isDungeonMap(m)) return null;
  // 宝の洞窟: 地図の 場所（world/treasure.js）
  if (m.tm) return treasureExitPoint(m.id);
  const { floors, exits } = chainOf(m.id);
  const from = s.char?.dungeonFrom;
  const fromOk = from && MAPS[from.map] && !isDungeonMap(MAPS[from.map]) && (!from.in || floors.has(from.in));
  if (exits.length) {
    if (fromOk) {
      const near = exits.filter((e) => e.map === from.map).sort((p, q) => Math.hypot(p.x - from.x, p.y - from.y) - Math.hypot(q.x - from.x, q.y - from.y))[0];
      if (near) return near;
    }
    return exits[0];
  }
  return fromOk ? { map: from.map, x: from.x, y: from.y, dir: from.dir || 'down' } : null;
}

// みちびきの糸・帰り道の羽が 使えない 場所（map.noEscape。王家のピラミッド・砂の底の神殿）の ことば
// map.noEscapeHint … その 場所の ヒント（ない ときは ピラミッドの ことば）
export function noEscapeText(name, map = null) {
  return `${name}を使おうとした…。\nしかし、ふしぎな力にはばまれて、使えない！\n（${map?.noEscapeHint || 'ピラミッドの中では、来た道を歩いてもどろう'}）`;
}

// メニューの「道具」→「使う」（world/services.js の useItem から）。reply(ok, text)
export function useEscapeItem(world, s, id, reply) {
  const c = s.char;
  const it = ITEMS[id];
  if (itemCount(c, id) < 1) return reply(false, '持っていない');
  const here = MAPS[s.map];
  if (!isDungeonMap(here)) return reply(false, `ここでは使えない。\n（${it.name}は、洞窟や塔の中で使う道具）`);
  // 第79回: ひみつのダンジョンの 階: 入口の 広間へ（全滅で もどる 時と おなじ あつかい。world/secret.js の secretEscape）
  if (here.sd?.floor) {
    removeItem(c, id, 1);
    const note = secretEscape(world, s, it.name);
    return reply(true, `${c.name}は${it.name}を使った！\n糸をたどって、${SD_NAME}の入口へもどってきた！\n${note}`);
  }
  // 王家のピラミッド（第4章）: 糸は 使えない（道具は へらない）
  if (here.noEscape) return reply(false, noEscapeText(it.name, here));
  const to = dungeonExit(world, s);
  if (!to) return reply(false, `${it.name}を使った！\nしかし、糸がどこにもつながっていない…`);
  removeItem(c, id, 1);
  // 「ついていく」なかまも いっしょに（ルーラ・帰り道の羽と おなじ。travel.js）
  warpParty(world, s, to);
  return reply(true, `${c.name}は${it.name}を使った！\n糸をたどって、${here.name.split('　')[0]}の外へもどってきた！`);
}

js/shared/world/evolve.js:
// 第44回（ポケモン P1。docs/plan-breed-new.md の 2 の C・D）: 魔物の 進化
//
// レベルで 進化（ピカチュウ・ヒトカゲ・ゼニガメ・フシギダネの 系統。data/companions-pokemon.js の evolve）
//   1. 戦い・サポートの おれい などで レベルが 上がると、stats.js の gainExp が char.evolveTo（進化の 用意）を つける
//   2. 戦いの けっかを 読みおわった あと・台本が おわった あと・ログインした あと（フィールドに もどった とき）に、
//      world.js の tick が「…おや？〇〇のようすが…！」→「みまもる」「とめる」の 台本を その 人だけに 出す（家族の ほかの 人には 出ない）
//      （world/scripts.js の checkEvolve。s.evoCheck が ついた 人を 見る）
//   3. みまもる → 進化（evolveEntry）。とめる → 用意を 消す（次に レベルが 上がった ときに また たずねる）
//   かわらずのいし（everstone）を 装備していると、レベルで 進化しない（用意も つかない）
// 石で 進化（イーブイ。stones）: メニューの「道具」→「使う」で 石を 使うと すぐ 進化（useEvoStone。石は なくなる）
//
// 進化で かわるのは しゅぞく だけ: レベル・＋・受けついだ 強さ（bonus）・受けついだ 技・種・追いつき・血統・ランクの しるしは そのまま。
//   名前は、まだ もとの しゅぞくの 名前（ヒトカゲ・はじめの 名前の 一覧）の ときだけ 新しい しゅぞくの 名前に。
//   新しい すがたで 装備できない 物は ふくろへ。HP・MP は 満タンに。図鑑に のる
import { MONSTERS } from '../data/monsters.js';
import { ITEMS, SLOTS } from '../data/items.js';
import { MONSTER_FRIENDS, levelEvolveTo, stoneEvolveTo } from '../data/companions.js';
import { addItem, removeItem, canEquipMonster, fullHeal } from '../stats.js';
import { ensureCompanions, partyOf } from './party.js';

// 進化した あとの 名前（もとの しゅぞくの 名前の ままなら 新しい しゅぞくの 名前。自分で つけた 名前は そのまま）
export function evolvedName(name, from, to) {
  if (name === MONSTERS[from]?.name) return MONSTERS[to].name;
  const i = (MONSTER_FRIENDS[from]?.names || []).indexOf(name);
  if (i >= 0) return MONSTER_FRIENDS[to]?.names?.[i] || MONSTERS[to].name;
  return name;
}

// 進化させる（c … もちぬしの キャラ・e … 仲間の { key, kind, species, char }・to … 進化した すがた）
//   かえす もの: { ok, from, to, oldName, name, stowed: [ふくろへ しまった 装備] }
export function evolveEntry(c, e, to) {
  const ch = e?.char;
  if (!ch || e.kind !== 'monster' || !MONSTERS[to] || !MONSTER_FRIENDS[to]) return { ok: false };
  const from = ch.species;
  const oldName = ch.name;
  ch.species = to;
  e.species = to;
  ch.name = String(evolvedName(oldName, from, to)).slice(0, 8);
  // 新しい すがたで 装備できない 物は ふくろへ
  const stowed = [];
  ch.equip = ch.equip || {};
  for (const slot of SLOTS) {
    const id = ch.equip[slot];
    if (!id || canEquipMonster(to, id)) continue;
    addItem(c, id, 1);
    ch.equip[slot] = null;
    stowed.push(id);
  }
  delete ch.evolveTo;
  fullHeal(ch);
  // 図鑑（仲間に した ことが ある・進化した 回数）
  c.bestiary = c.bestiary || {};
  const b = c.bestiary[to] || (c.bestiary[to] = {});
  b.friend = (b.friend || 0) + 1;
  b.evolved = (b.evolved || 0) + 1;
  // 進化した すがたも もう 次の 進化の レベル（リザードで Lv50 いじょう など）なら、つづけて たずねる
  const next = levelEvolveTo(ch);
  if (next) ch.evolveTo = next;
  return { ok: true, from, to, oldName, name: ch.name, stowed };
}

// 進化を まっている 仲間（なければ null）。用意の あとで かわらずのいしを 装備した ときなどは 用意を 消す
export function pendingEvolve(c) {
  if (!Array.isArray(c?.companions)) return null;
  for (const e of c.companions) {
    const ch = e?.char;
    if (e?.kind !== 'monster' || !ch?.evolveTo) continue;
    if (levelEvolveTo(ch) !== ch.evolveTo) {
      delete ch.evolveTo;
      continue;
    }
    return e;
  }
  return null;
}

// 「…おや？」の 台本（その 人だけ。world/scripts.js の checkEvolve）
export function evolveAskSteps(e) {
  const ch = e.char;
  return [
    ['showMon', ch.species],
    ['sfx', 'sparkle'],
    ['say', null, `…おや？\n${ch.name}のようすが…！`],
    ['choice', `${ch.name}をどうする？`, ['みまもる', 'とめる'], [
      [['evolve', e.key, ch.evolveTo]],
      [['evolveStop', e.key]],
    ]],
    ['showMon', null],
  ];
}

const stowText = (ids) => (ids.length ? `\n（${ids.map((id) => ITEMS[id]?.name || id).join('と')}は装備できないので、ふくろにしまった）` : '');

// 家族の パーティーの ほかの 人に 知らせる（えらぶ 文は 出さない）
function tellParty(world, s, text) {
  const p = partyOf(world, s);
  if (!p || p.members.length < 2) return;
  for (const sid of p.members) {
    const m = sid !== s.id && world.sessions.get(sid);
    if (m) world.send(m, { t: 'toast', text });
  }
}

function afterChange(world, s) {
  world.sendSelf(s);
  const p = partyOf(world, s);
  if (p) world.sendParty(p);
  world.markDirty();
}

// 台本の 'evolve'（みまもる）・'evolveStop'（とめる）。かえす もの: 台本に 足す 行
export function evolveScriptStep(world, s, op, key, to) {
  const c = ensureCompanions(s.char);
  const e = c.companions.find((x) => x.key === key && x.kind === 'monster');
  if (!e) return [];
  const name = e.char.name;
  if (op === 'evolveStop') {
    delete e.char.evolveTo;
    world.markDirty();
    return [['say', null, `あれ…？\n${name}の進化が止まった！`]];
  }
  if (e.char.evolveTo !== to || levelEvolveTo(e.char) !== to) {
    delete e.char.evolveTo;
    return [['say', null, `${name}のようすが、もとにもどった…。`]];
  }
  const r = evolveEntry(c, e, to);
  if (!r.ok) return [];
  afterChange(world, s);
  tellParty(world, s, `${c.name}の${r.oldName}が${MONSTERS[to].name}に進化した！`);
  return [
    ['sfx', 'sparkle'], ['flash'], ['showMon', to], ['sfx', 'join'],
    ['say', null, `おめでとう！\n${r.oldName}は${MONSTERS[to].name}に進化した！${stowText(r.stowed)}`],
  ];
}

// 進化の 石を 使う（メニューの「道具」→「使う」。world/services.js の useItem）。target … えらんだ 人の キャラ
//   自分の 仲間の 魔物で、その 石で 進化する しゅぞく だけ（ほかは 石は へらない）
export function useEvoStone(world, s, itemId, target, reply) {
  const c = ensureCompanions(s.char);
  const it = ITEMS[itemId];
  const e = target ? c.companions.find((x) => x.kind === 'monster' && x.char === target) : null;
  if (!e) return reply(false, `${target?.name || ''}に${it.name}を使っても、何も起こらなかった…`);
  const to = stoneEvolveTo(e.char.species, itemId);
  if (!to) return reply(false, `${e.char.name}に${it.name}を使っても、何も起こらなかった…`);
  removeItem(c, itemId, 1);
  const r = evolveEntry(c, e, to);
  tellParty(world, s, `${c.name}の${r.oldName}が${MONSTERS[to].name}に進化した！`);
  return reply(true, `${c.name}は${r.oldName}に${it.name}を使った！\n${r.oldName}の体が光につつまれた…！\n${r.oldName}は${MONSTERS[to].name}に進化した！${stowText(r.stowed)}`);
}

js/shared/world/family-board.js:
// 第51回 B: 家族のけいじ板（だれかが 何かを した 知らせが 自動で のる。家族の ひとことは 作らない）
//
// ・のせる 物（どれも 自動）
//   - 転職（基本職〜伝説の職業。はじめて その 職業に なった 時だけ。services.js の jobChange）
//   - ひらめき技・掛け合わせ技を ひらめいた（world/battles.js・world/wagon.js）
//   - 合体技を はじめて 使った（world/battles.js の markDuals）
//   - 幻の職業（F 班が world.boardPost?.({ kind: 'phantom_reveal' | 'phantom_get', ... }) を よぶ）
// ・1こ: { id, kind, by, charId, job?, key?, title（見出し）, detail（なりかた・覚えかた）, at }
//   見出しだけ 一覧に 出す。detail は「見る」を おした 時だけ（ネタバレ よけ。boardRows）
// ・サーバー ぜんたいで 1つ（world.data.familyBoard。家族サーバーの セーブと いっしょに のこる）。
//   ひとりモードは その ブラウザの セーブに のこる（その ブラウザの キャラの ぶんだけ）
// ・おなじ（キャラ・しゅるい・職業か 技）は 1回だけ。多く なったら 古い 物から けす（BOARD_MAX）
// ・のった 時は 遊んでいる 人みんなに とどける（{ t: 'fboardNew', entry }。client/ui/family-board.js）
// ・まだ 見ていない 印: キャラごとの c.boardSeen（さいごに 見た 時こく）
import { JOBS, TIER_NAMES, jobReqText, BODY_NAMES } from '../data/jobs.js';
import { ABILITIES } from '../data/abilities.js';
import { HIRAMEKI } from '../data/hirameki.js';
import { DUAL_TECHS, dualSize, dualNeedLabel, dualNeedText } from '../data/dual.js';
import { abilityLabel } from '../ability-label.js';
import { jobLabel } from '../job-label.js';
import { comboJobNames } from '../stats.js';

export const BOARD_MAX = 200;
// 一覧で 1回に おくる 数（多すぎると スマホが おもい）
export const BOARD_SEND = BOARD_MAX;
// しゅるいの 名前（一覧の 小さな 札）。幻の職業の 名前は F 班の TIER_NAMES[4]
const PHANTOM_NAME = TIER_NAMES[4] || 'まぼろしの職業';
export const BOARD_KINDS = {
  job: '転職',
  hirameki: 'ひらめき',
  dual: '合体技',
  phantom_reveal: PHANTOM_NAME,
  phantom_get: PHANTOM_NAME,
};

const str = (v, n) => (typeof v === 'string' ? v.slice(0, n) : '');
const num = (v) => (Number.isFinite(v) ? v : 0);

// 1こを 読める 形に（こわれた 物は null）
export function cleanEntry(e) {
  if (!e || typeof e !== 'object') return null;
  const title = str(e.title, 80) || str(e.text, 80);
  const kind = str(e.kind, 24);
  if (!title || !kind) return null;
  const out = { id: str(e.id, 24), kind, by: str(e.by, 40), charId: str(e.charId, 40), title, detail: str(e.detail, 600), at: Math.max(0, num(e.at)) };
  if (e.job) out.job = str(e.job, 40);
  if (e.key) out.key = str(e.key, 40);
  return out;
}

// セーブを 読む ときの 手直し（save.js の upgradeSave）。古い じゅんに ならべて BOARD_MAX まで
export function cleanFamilyBoard(list) {
  if (!Array.isArray(list)) return [];
  const out = list.map(cleanEntry).filter(Boolean).sort((a, b) => a.at - b.at).slice(-BOARD_MAX);
  // id の ない 物（手で 直した セーブ など）には つける
  out.forEach((e, i) => { if (!e.id) e.id = `o${e.at.toString(36)}${i.toString(36)}`; });
  return out;
}

// キャラの「さいごに 見た 時こく」（save.js の repairChar）
export function cleanBoardSeen(c) {
  if (!c || typeof c !== 'object') return;
  if (c.boardSeen === undefined) return;
  if (Number.isFinite(c.boardSeen) && c.boardSeen > 0) c.boardSeen = Math.floor(c.boardSeen);
  else delete c.boardSeen;
}

export function boardOf(world) {
  const d = world.data;
  if (!Array.isArray(d.familyBoard)) d.familyBoard = [];
  return d.familyBoard;
}

// おなじ 知らせか（キャラ・しゅるい・職業か 技）
const sameKey = (e) => `${e.charId}|${e.kind}|${e.job || e.key || e.title}`;

let seq = 0;
// のせる（もどりち: のせた 1こ。おなじ 物が もう あれば null）。world.boardPost が よぶ
export function boardPost(world, entry) {
  const e = cleanEntry({ ...entry, at: num(entry?.at) || world.now() });
  if (!e) return null;
  const list = boardOf(world);
  const k = sameKey(e);
  if (list.some((x) => sameKey(x) === k)) return null;
  e.id = `${e.at.toString(36)}${(seq++ % 1296).toString(36)}`;
  list.push(e);
  if (list.length > BOARD_MAX) list.splice(0, list.length - BOARD_MAX);
  world.markDirty?.();
  world.broadcast?.({ t: 'fboardNew', entry: e });
  return e;
}

// 家族の キャラか（酒場の 仲間・魔物・ゲストは のせない）
export function familyChar(world, c) {
  return !!c && !c.species && typeof c.id === 'string' && world.data.characters?.[c.id] === c;
}

// ───── 転職 ─────
// 職業の なりかた（見る を おした 時に 出る）
export function jobHowText(jobId, who = null) {
  const j = JOBS[jobId];
  if (!j) return '';
  const jn = (r) => jobLabel(r, who);
  const req = jobReqText(jobId, jn);
  const body = j.body !== undefined ? `\n（${BODY_NAMES[j.body]}だけがなれる）` : '';
  const tier = TIER_NAMES[j.tier || 0] || '';
  if (!req) return `${jn(jobId)}は${tier}。最初からなれる。${body}\n神殿で転職できる。`;
  return `${jn(jobId)}（${tier}）のなりかた：\n${req}${body}\n神殿で転職できる。`;
}

// 転職した あと（first … その 職業に はじめて なった。changeJob の 前に c.jobs[jobId] が なかった）
export function boardJobChange(world, c, jobId, first) {
  const tier = JOBS[jobId]?.tier || 0;
  if (!first || tier > 3 || !familyChar(world, c)) return null;
  return world.boardPost({
    kind: 'job', by: c.name, charId: c.id, job: jobId,
    title: `${c.name}が${jobLabel(jobId, c)}になった！`, detail: jobHowText(jobId, c),
  });
}

// ───── ひらめき技 ─────
// ひらめきかた（見る を おした 時に 出る）
export function hiraHowText(id, who = null) {
  const h = HIRAMEKI[id], a = ABILITIES[id];
  if (!h || !a) return '';
  const uses = Object.entries(h.from).map(([k, n]) => `${k === '@atk' ? 'ふつうの攻撃' : `「${abilityLabel(k, who)}」`}を${n}回`).join('、');
  let where = '';
  if (a.kind === 'combo') where = `掛け合わせ技。${comboJobNames(id, who).join('・')}（その先の超級職も）で、`;
  else if (a.job && JOBS[a.job]) where = `${jobLabel(a.job, who)}（そこから進んだ職業も）で、`;
  const lv = Object.entries(a.reqJobLv || {}).map(([j, n]) => `${jobLabel(j, who)}のレベル${n}`).join('と');
  return `${where}${uses}使うと、戦いの中でひらめくことがある。${lv ? `\n（${lv}以上が必要）` : ''}`;
}

export function boardHirameki(world, c, ids) {
  if (!familyChar(world, c)) return [];
  const out = [];
  for (const id of ids || []) {
    if (!HIRAMEKI[id] || !ABILITIES[id]) continue;
    const kind = ABILITIES[id].kind === 'combo' ? '掛け合わせ技' : 'ひらめき技';
    const e = world.boardPost({
      kind: 'hirameki', by: c.name, charId: c.id, key: id,
      title: `${c.name}が${kind}『${abilityLabel(id, c)}』を覚えた！`, detail: hiraHowText(id, c),
    });
    if (e) out.push(e);
  }
  return out;
}

// ───── 合体技 ─────
export function dualHowText(id, who = null) {
  const t = DUAL_TECHS[id];
  if (!t) return '';
  return `${dualSize(id)}人でいっしょに出す合体技。\n${dualNeedLabel(id)}：${dualNeedText(id, false, who)}\n出せるかは、今ついている職業で決まる。戦いで自分のゲージがたまった時に「合体技」から選ぶ。`;
}

// chars: その 合体技を はじめて 使った 家族の キャラ（1回の 合体技で 1こに まとめる）
export function boardDual(world, chars, id) {
  const fam = (chars || []).filter((c) => familyChar(world, c));
  const t = DUAL_TECHS[id];
  if (!fam.length || !t) return null;
  const names = fam.map((c) => c.name).join('と');
  return world.boardPost({
    kind: 'dual', by: names, charId: fam[0].id, key: id,
    title: `${names}が合体技『${t.name}』を覚えた！`, detail: dualHowText(id, fam[0]),
  });
}

// ───── 見る 人へ ─────
// まだ 見ていない 知らせの さいごの 時こく（自分の 知らせは 入れない）
export function boardLastFor(world, charId) {
  let last = 0;
  for (const e of boardOf(world)) if (e.charId !== charId && e.at > last) last = e.at;
  return last;
}

// クライアントからの { t: 'fboard', action }（world.js の handle）
//   list … 一覧（新しい じゅん）を おくる / seen … ここまで 見た（c.boardSeen）/ peek … さいごの 時こくだけ
export function boardMessage(world, s, msg) {
  const c = s.char;
  if (!c) return;
  switch (msg?.action) {
    case 'list': {
      const list = boardOf(world).slice(-BOARD_SEND).reverse();
      world.send(s, { t: 'fboardList', list, last: boardLastFor(world, c.id) });
      return;
    }
    case 'seen': {
      const at = Math.min(num(msg.at), world.now());
      if (at > num(c.boardSeen)) {
        c.boardSeen = Math.floor(at);
        world.sendSelf(s);
        world.markDirty();
      }
      return;
    }
    case 'peek':
      world.send(s, { t: 'fboardLast', last: boardLastFor(world, c.id) });
      return;
    default:
  }
}

// ───── 一覧の 見た目の もと（client/ui/family-board.js・テスト）─────
// list: 新しい じゅん。opened: 「見る」を おした id の Set。me: 見ている キャラ（{ id, boardSeen }）
// detail は 開いた 物だけ（ほかは null）
export function boardRows(list, opened, me) {
  const seen = num(me?.boardSeen);
  return (list || []).map((e) => {
    const open = !!opened?.has(e.id);
    return {
      id: e.id, kind: e.kind, tag: BOARD_KINDS[e.kind] || 'お知らせ', title: e.title, at: e.at,
      mine: e.charId === me?.id, unread: e.charId !== me?.id && e.at > seen,
      open, detail: open ? e.detail || 'くわしいことは書いていない。' : null,
    };
  });
}

// まだ 見ていない 知らせが あるか（メニューの ●）
export function boardUnread(last, me) {
  return num(last) > num(me?.boardSeen);
}

// 時こくの 文（例: 10月29日 18:05）
export function boardWhen(at) {
  const d = new Date(num(at));
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getMonth() + 1}月${d.getDate()}日 ${p(d.getHours())}:${p(d.getMinutes())}`;
}

