// 酒場が いっぱいの ときの さよなら（第35回。家族の ねがい「新しい 仲間を 入れる 時に、だれかに さよならして 入れたい」）
//   ・酒場で 新しい 人間の 仲間を さそう 時（world/services.js の 'recruit' の farewell・client/ui/services.js）
//   ・戦いの あとで 魔物が 仲間に なりたがった 時（world.js の offerBefriend → scripts.js の 'befriend' の 4つめ）
//   ・人間の 仲間とも 別れられる。人間は あとで 酒場で また さそえる（レベル1から。world/party.js の companionRelease）
//   ・配合は 2ひき → 1ぴきなので いっぱいでも できる（さよならは いらない）
// 第43回 C: いっぱいの 時の えらぶ文は「配合してあける」「あずかり所へ送る」「だれかとさよならする」「やめる」（befriendFullSteps）
//   ・配合してあける … 台本の ['breedOpen', id] で 酒場の 配合の 画面を「あける モード」で 開く（scripts.js・client/ui/services.js）
//   ・あずかり所へ送る … 魔物を 1ぴき あずかり所へ（world/storage.js）。あいた 所に 新しい 魔物
//   ・酒場で 人間の 仲間を さそう 時も 同じ えらぶ文（client/ui/services.js の pickFull・world/services.js の 'recruit'）
import { MONSTERS } from '../data/monsters.js';
import { ROSTER_MAX, BREED_MIN_LEVEL } from '../data/companions.js';
import { jobLabel } from '../job-label.js';
import { ensureCompanions, companionRelease, ensureStorage, STORAGE_MAX } from './party.js';

// 酒場が いっぱいか（パーティー・馬車・酒場の 仲間 みんなで ROSTER_MAX）
export function rosterIsFull(c) {
  return ensureCompanions(c).companions.length >= ROSTER_MAX;
}

// さよならの 候補: 酒場で 待っている 仲間が 先・レベルの 低い じゅん（家族の キャラは 入らない）
export function farewellList(c) {
  ensureCompanions(c);
  const busy = new Set([...(c.partyKeys || []), ...(c.wagonKeys || [])]);
  return c.companions
    .map((e, i) => ({ e, i }))
    .sort((x, y) => busy.has(x.e.key) - busy.has(y.e.key) || (x.e.char.level || 1) - (y.e.char.level || 1) || x.i - y.i)
    .map(({ e }) => ({
      key: e.key, name: e.char.name, human: e.kind !== 'monster',
      label: `${e.char.name}（${e.species ? MONSTERS[e.species]?.name || '' : jobLabel(e.char.job, e.char)} Lv${e.char.level}${busy.has(e.key) ? '・いっしょ' : ''}）`,
    }));
}

// さよなら した ときの ことば
export function farewellText(r) {
  if (!r?.ok) return '';
  return r.human ? `${r.name}とさよならした。\n「また酒場でさそってね！」` : `${r.name}とさよならした。\n「今までありがとう！」`;
}

// さよなら する（台本の 'befriend' から）。ことばを かえす
export function sayFarewell(world, s, key) {
  return farewellText(companionRelease(world, s, String(key || '')));
}

// 配合して あけられるか（Lv10いじょうの 魔物が 2ひき。1ぴきは 仲間〈40〉の 中。あずかり中の 魔物も 親に なれる）
//   あずかり中の 親から 生まれた 子は あずかり所に 入る（world/breed.js）ので、仲間の 魔物を 1ぴき 使えば 1つ あく
export function canBreedRoom(c) {
  ensureStorage(ensureCompanions(c));
  const ok = (e) => e?.kind === 'monster' && (e.char?.level || 1) >= BREED_MIN_LEVEL;
  const mine = c.companions.filter(ok).length;
  return mine >= 1 && mine + c.storage.filter(ok).length >= 2;
}

// あずかり所へ 送れるか（仲間に 魔物が いて、あずかり所に あきが ある）
export function canStore(c) {
  ensureStorage(ensureCompanions(c));
  return c.storage.length < STORAGE_MAX && c.companions.some((e) => e.kind === 'monster');
}

// あずかり所へ 送る 候補（魔物だけ。酒場で 待っている 魔物が 先・レベルの 低い じゅん。farewellList と 同じ ならび）
export function storeList(c) {
  return farewellList(c).filter((x) => !x.human);
}

// 魔物が 仲間に なりたがった とき、仲間が いっぱいなら: どうやって あけるか えらぶ 台本（world.js の offerBefriend の「はい」）
//   again … えらぶ文に もどって きた 時（さいしょの ことばを くりかえさない。scripts.js の 'befriendFull'）
export function befriendFullSteps(c, id, monName, again = false) {
  const labels = [], branches = [];
  const back = [['befriendFull', id]];
  if (canBreedRoom(c)) {
    labels.push('配合してあける');
    branches.push([['breedOpen', id]]);
  }
  if (canStore(c)) {
    const list = storeList(c);
    labels.push('あずかり所へ送る');
    branches.push([['choice', 'だれをあずかり所へ送る？', [...list.map((x) => x.label), 'もどる'], [
      ...list.map((x) => [['befriend', id, null, null, x.key]]),
      back,
    ]]]);
  }
  const list = farewellList(c);
  labels.push('だれかとさよならする');
  branches.push([['choice', 'だれとさよならする？', [...list.map((x) => x.label), 'もどる'], [
    ...list.map((x) => [['befriend', id, null, x.key]]),
    back,
  ]]]);
  labels.push('やめる');
  branches.push([['say', null, `${monName}はさびしそうに去っていった…`], ['befriend', id, false]]);
  return [
    ...(again ? [] : [['say', null, `仲間がいっぱいだ（${ROSTER_MAX}）。\n1つあければ、${monName}を仲間にできる。`]]),
    ['choice', `${monName}のために、どうする？`, labels, branches],
  ];
}

// 前の 名前（第35回）
export const befriendFarewellSteps = befriendFullSteps;

js/shared/world/field27.js:
// フィールドの 呪文と 道具（サーバーの きまり）: リレミト・トヘロス・マモノヨセ・聖水・魔物よせの笛
//   データは data/abilities-field27.js
//
// 魔物よけ（トヘロス・聖水）と 魔物よせ（マモノヨセ・魔物よせの笛）
// ・s.repelUntil … 魔物よけが 切れる 時こく（今までの 聖水と 同じ。world/monsters.js が 見る）
// ・s.lureUntil  … 魔物よせが 切れる 時こく（world/monsters.js・battles.js が 見る）
// ・char.aura    … 画面に 出す しるし { kind: 'repel'|'lure', until, name }（client/ui/hud.js。セーブに のこっても 時こくで 切れる）
// ・あとから 使った ほうが 勝つ（片方を 使うと もう 片方は 消える）
// ・家族と いっしょの ときは、同じ 場所に いる パーティーの 家族にも 効く
import { MAPS } from '../maps/index.js';
import { ABILITIES } from '../data/abilities.js';
import { ITEMS } from '../data/items.js';
import { AURA_NAMES, LURE } from '../data/abilities-field27.js';
import { mpCost, itemCount, removeItem } from '../stats.js';
import { partyOf } from './party.js';
import { isDungeonMap, dungeonExit } from './escape.js';
import { secretEscape } from './secret.js';
import { SD_NAME } from '../data/secret.js';
import { warpParty } from './travel.js';
import { rollGroup } from './monsters.js';
import { ENCOUNTER_TABLES } from '../data/encounters.js';
import { MONSTERS } from '../data/monsters.js';

// ここで あつかう 効き目
export const FIELD27_EFFECTS = new Set(['exit', 'repel', 'lure']);

// 今 効いている もの（'repel' / 'lure' / null）
export function auraOf(s, now) {
  if (!s) return null;
  if (s.lureUntil > now) return 'lure';
  if (s.repelUntil > now) return 'repel';
  return null;
}
export const lureOn = (s, now) => !!s && s.lureUntil > now;

// 魔物よせの 戦い: 出現表から 組を ふりなおして、強い ほう（経験値の 合計が 多い ほう）に する
//   きらきらぷるりんなど 逃げる 魔物の 組・出現表の ない 魔物は そのまま
export function lureGroup(world, sym) {
  const table = ENCOUNTER_TABLES[sym.table];
  if (!table || !Array.isArray(sym.group) || sym.sp === 'kirakira') return sym.group;
  const power = (g) => g.reduce((a, sp) => a + (MONSTERS[sp]?.exp || 0), 0);
  let best = sym.group;
  for (let i = 1; i < LURE.strong; i++) {
    const g = rollGroup(world.rng, sym.table);
    if (power(g) > power(best)) best = g;
  }
  return best;
}

// 効き目を つける 人: 自分と、同じ 場所に いる パーティーの 家族
function auraTargets(world, s) {
  const out = [s];
  const p = partyOf(world, s);
  for (const sid of p?.members || []) {
    const m = world.sessions.get(sid);
    if (m && m !== s && m.inWorld && m.char && m.map === s.map) out.push(m);
  }
  return out;
}

// kind: 'repel' | 'lure'、seconds: 何秒、name: しるしに 出す 名前
export function setAura(world, s, kind, seconds, name) {
  const now = world.now();
  const until = now + seconds * 1000;
  const people = auraTargets(world, s);
  for (const m of people) {
    if (kind === 'lure') {
      m.lureUntil = until;
      m.repelUntil = 0;
    } else {
      m.repelUntil = until;
      m.lureUntil = 0;
    }
    m.char.aura = { kind, until, name: name || AURA_NAMES[kind] };
    if (m !== s) {
      world.sendSelf(m);
      world.send(m, { t: 'toast', text: kind === 'lure' ? `${s.char.name}の${name}で、魔物がどんどん寄ってくる…！` : `${s.char.name}の${name}で、弱い魔物が近よらなくなった。` });
    }
  }
  world.markDirty?.();
  return people.length;
}

const auraText = (kind, before) => {
  const swap = before && before !== kind ? (kind === 'lure' ? '\n（魔物よけの力は消えた）' : '\n（魔物よせの力は消えた）') : '';
  return kind === 'lure' ? `しばらく魔物がよく出て、強い魔物の組も出やすくなる！${swap}` : `しばらく弱い魔物が寄ってこない。${swap}`;
};

// 道具（聖水・魔物よせの笛。world/services.js の useItem から）
export function useAuraItem(world, s, id, reply) {
  const c = s.char;
  const it = ITEMS[id];
  if (!it || itemCount(c, id) < 1) return reply(false, '持っていない');
  const kind = it.effect.type;
  const before = auraOf(s, world.now());
  removeItem(c, id, 1);
  const n = setAura(world, s, kind, it.effect.seconds, it.name);
  const head = kind === 'lure' ? `${c.name}は${it.name}をふいた！\nピィーーッ…！` : `${c.name}は${it.name}をふりまいた！`;
  return reply(true, `${head}\n${auraText(kind, before)}${n > 1 ? '\n（いっしょにいる家族にも効く）' : ''}`);
}

// 呪文（リレミト・トヘロス・マモノヨセ。world/services.js の 'cast' から）。reply(ok, text)
export function castField27(world, s, caster, id, reply) {
  const a = ABILITIES[id];
  const type = a.effect?.type;
  const head = `${caster.name}は${a.name}を唱えた！`;
  if (type === 'exit') {
    // リレミト: みちびきの糸と 同じ（world/escape.js）。使えない 所では MPは へらない
    const here = MAPS[s.map];
    if (!isDungeonMap(here)) return reply(false, `${head}\nしかし、何も起こらなかった…\n（${a.name}は、洞窟や塔の中で使う呪文）`);
    // 第79回: ひみつのダンジョンの 階: 入口の 広間へ（いっしょの 家族も。全滅で もどる 時と おなじ あつかい。world/secret.js）
    if (here.sd?.floor) {
      const cost = mpCost(caster, id);
      if (caster.mp < cost) return reply(false, 'MPが足りない！');
      caster.mp -= cost;
      const note = secretEscape(world, s, a.name);
      return reply(true, `${head}\nまばゆい光につつまれて、${SD_NAME}の入口へもどってきた！\n${note}`);
    }
    if (here.noEscape) return reply(false, `${head}\nしかし、ふしぎな力にはばまれて、何も起こらなかった！\n（${here.noEscapeHint || '来た道を歩いてもどろう'}）`);
    const to = dungeonExit(world, s);
    if (!to) return reply(false, `${head}\nしかし、出口が見つからない…`);
    const cost = mpCost(caster, id);
    if (caster.mp < cost) return reply(false, 'MPが足りない！');
    caster.mp -= cost;
    // 「ついていく」なかま・いっしょの 家族も（糸・ルーラと 同じ。travel.js）
    warpParty(world, s, to);
    return reply(true, `${head}\nまばゆい光につつまれて、${here.name.split('　')[0]}の外へもどってきた！`);
  }
  if (type === 'repel' || type === 'lure') {
    const cost = mpCost(caster, id);
    if (caster.mp < cost) return reply(false, 'MPが足りない！');
    const before = auraOf(s, world.now());
    caster.mp -= cost;
    const n = setAura(world, s, type, a.effect.seconds, a.name);
    return reply(true, `${head}\n${auraText(type, before)}${n > 1 ? '\n（いっしょにいる家族にも効く）' : ''}`);
  }
  return reply(false, '今は使えない');
}

js/shared/world/fieldchests.js:
// フィールドの 宝箱（ランダムに あらわれ、開けると きえる。data/fieldchests.js）
// ・マップの じょうたい（monsters.js の mapState）に もつ。サーバーに 1つ（家族で 見る ものは おなじ。先に 開けた 人が もらう）
// ・プレイヤーが その マップに いる ときだけ ふえる。開けられない まま 古く なった ものは べつの 場所へ
// ・クライアントへは snap の fc（かわった ときだけ）
import { MAPS, isBlocked } from '../maps/index.js';
import { T } from '../tiles.js';
import { ITEMS } from '../data/items.js';
import { addItem } from '../stats.js';
import { FIELD_CHEST_COUNT, FIELD_CHEST_RESPAWN_MS, FIELD_CHEST_LIFE_MS, fieldChestLoot } from '../data/fieldchests.js';
import { alchemyMemoLoot } from './alchemy.js';
import { chestMemo } from '../data/secret-hints.js';

const GROUND = new Set([T.GRASS, T.FLOWERS, T.TALLGRASS, T.FOREST_FLOOR, T.SAND, T.HILL, T.DIRT, T.SNOW, T.DEEP_SNOW, T.ASH, T.DESERT]);
const SPACING = 10; // ほかの 宝箱との あいだ（マス）
const AWAY = 5; // プレイヤーの すぐ 近くには 出さない

// 出られる マス（町・村の そば、出入り口・かんばん・人・きらきらの 上は さける）
function spots(ms) {
  if (ms.fcSpots) return ms.fcSpots;
  const map = MAPS[ms.id];
  const out = [];
  const near = new Set();
  const mark = (x, y, r) => { for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) near.add(`${x + dx},${y + dy}`); };
  for (const w of map.warps) mark(w.x, w.y, 2);
  for (const n of map.npcs) mark(Math.floor(n.x), Math.floor(n.y), 1);
  for (const c of map.chests) mark(c.x, c.y, 1);
  for (const s of map.signs || []) mark(s.x, s.y, 1);
  for (const s of map.sparkles || []) mark(s.x, s.y, 0);
  // fcStart が ある マップは、そこから 歩いて 行ける ところ だけ（山の 中の すきま などに 出さない）
  const reach = map.fcStart ? walkable(map, map.fcStart) : null;
  for (let y = 2; y < map.h - 2; y++) {
    for (let x = 2; x < map.w - 2; x++) {
      if (!GROUND.has(map.tiles[y * map.w + x]) || near.has(`${x},${y}`)) continue;
      if (reach && !reach[y * map.w + x]) continue;
      if (isBlocked(map, x, y, () => true) || isBlocked(map, x, y, () => false)) continue;
      // 町・村の 中と その まわり 2マスは だめ
      let safe = false;
      for (let dy = -2; dy <= 2 && !safe; dy++) for (let dx = -2; dx <= 2 && !safe; dx++) if (String(map.zoneAt(x + dx, y + dy)).startsWith('safe')) safe = true;
      if (safe) continue;
      out.push([x, y]);
    }
  }
  ms.fcSpots = out;
  return out;
}

// start から 歩いて 行ける マス（しかけは ぜんぶ ひらいた として）
function walkable(map, start) {
  const seen = new Uint8Array(map.w * map.h);
  const q = [start];
  seen[start[1] * map.w + start[0]] = 1;
  for (let h = 0; h < q.length; h++) {
    const [x, y] = q[h];
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h) continue;
      const k = ny * map.w + nx;
      if (seen[k] || isBlocked(map, nx, ny, () => true)) continue;
      seen[k] = 1;
      q.push([nx, ny]);
    }
  }
  return seen;
}

function chestsOf(ms) {
  if (!ms.fchests) {
    ms.fchests = new Map();
    ms.fcTimer = 0;
    ms.fcVer = 1;
  }
  return ms.fchests;
}

function spawnOne(world, ms, players) {
  const list = spots(ms);
  if (!list.length) return null;
  const map = MAPS[ms.id];
  const have = [...chestsOf(ms).values()];
  for (let i = 0; i < 60; i++) {
    const [x, y] = list[Math.floor(world.rng.next() * list.length)];
    if (have.some((c) => Math.abs(c.x - x) + Math.abs(c.y - y) < SPACING)) continue;
    if (players.some((p) => Math.hypot(p.x - (x + 0.5), p.y - (y + 0.5)) < AWAY)) continue;
    world.fcSeq = (world.fcSeq || 0) + 1;
    const fc = { id: `fc${world.fcSeq}`, x, y, zone: map.zoneAt(x, y), born: world.now() };
    ms.fchests.set(fc.id, fc);
    ms.fcVer++;
    return fc;
  }
  return null;
}

// 毎 tick（world.js）。はじめて 来た マップは いっぺんに ならべる
export function tickFieldChests(world, ms, dt, players) {
  const want = FIELD_CHEST_COUNT[ms.id];
  if (!want || !players.length) return;
  const fresh = !ms.fchests;
  const chests = chestsOf(ms);
  if (fresh) {
    for (let i = 0; i < want; i++) spawnOne(world, ms, players);
    return;
  }
  // 古い ものは きえる（だれも 近くに いない とき）
  const now = world.now();
  for (const fc of [...chests.values()]) {
    if (now - fc.born < FIELD_CHEST_LIFE_MS) continue;
    if (players.some((p) => Math.hypot(p.x - (fc.x + 0.5), p.y - (fc.y + 0.5)) < 14)) continue;
    chests.delete(fc.id);
    ms.fcVer++;
  }
  if (chests.size >= want) {
    ms.fcTimer = 0;
    return;
  }
  ms.fcTimer += dt;
  if (ms.fcTimer >= FIELD_CHEST_RESPAWN_MS) {
    ms.fcTimer = 0;
    spawnOne(world, ms, players);
  }
}

// クライアントへ おくる 一覧（かわった ときだけ: s.fcSeen と くらべる）
export function fieldChestSnap(s, ms) {
  if (!ms.fchests) return undefined;
  // 3びょうに 1かいは かならず おくる（マップを うつった・つなぎなおした とき も 見えるように）
  const seen = s.fcSeen;
  const now = Date.now();
  if (seen && seen.map === ms.id && seen.ver === ms.fcVer && now - seen.at < 3000) return undefined;
  s.fcSeen = { map: ms.id, ver: ms.fcVer, at: now };
  return [...ms.fchests.values()].map((c) => [c.id, c.x, c.y]);
}

// しらべた ところの 近くの 宝箱（むいている マスか、自分の まわり）
export function fieldChestNear(ms, s, tx, ty) {
  if (!ms?.fchests?.size) return null;
  let best = null, bd = Infinity;
  for (const fc of ms.fchests.values()) {
    const dFace = Math.hypot(fc.x - tx, fc.y - ty);
    const dMe = Math.hypot(fc.x + 0.5 - s.x, fc.y + 0.5 - s.y);
    if (dFace > 1.01 && dMe > 1.5) continue;
    const d = Math.min(dFace, dMe);
    if (d < bd) { bd = d; best = fc; }
  }
  return best;
}

// 開ける（中みを もらって、宝箱は きえる）。runSteps に わたす steps を かえす
export function openFieldChest(world, s, ms, fc) {
  const c = s.char;
  ms.fchests.delete(fc.id);
  ms.fcVer++;
  ms.fcTimer = 0;
  // れん金のメモ（かまを 持っている 人だけ。world/alchemy.js）
  const loot = alchemyMemoLoot(c, world.rng) || fieldChestLoot(fc.zone, world.rng);
  c.fieldChests = (c.fieldChests || 0) + 1;
  world.markDirty();
  const steps = [['sfx', 'chest']];
  if (loot.gold) {
    c.gold = Math.min(9999999, c.gold + loot.gold);
    steps.push(['say', null, `${c.name}は宝箱を開けた！\n${loot.gold}ゴールドを手に入れた！`]);
  } else {
    addItem(c, loot.item, loot.n);
    steps.push(['say', null, `${c.name}は宝箱を開けた！\n${ITEMS[loot.item].name}${loot.n > 1 ? `を${loot.n}個` : 'を'}手に入れた！`]);
  }
  // 第35回: ときどき、かくし要素の ヒントの メモ（data/secret-hints.js）
  const memo = chestMemo(ms.id, world.rng);
  if (memo) steps.push(['say', null, memo]);
  return steps;
}

