// ふしぎなかじ屋（作る・きたえる）の そうさ
import { ITEMS } from '../data/items.js';
import { FORGES } from '../data/facilities.js';
import { RECIPES, recipeOf, recipeOpen, openRecipes, upgradeCost, lackOf, maxPlus, isShopForge } from '../data/forge.js';
import { addItem, removeItem, itemCount, canEquipChar, computeStats } from '../stats.js';
import { partyOf } from './party.js';
import { BAG_STACK } from './bank.js';
import { forgePotGift } from './alchemy.js';
import { salvageOf, salvageBlock } from '../data/salvage.js';
import { LB_MAX } from '../data/items-forge.js';

export function forgeInfo(world, s, place) {
  const f = FORGES[place] || FORGES.town;
  const open = openRecipes(world.hasFlagFn(s)).map((r) => r.id);
  const at = FORGES[place] ? place : 'town';
  // 第32回: れん金がまを もらう・れん金の レシピを 1つ 教わる（world/alchemy.js）
  const gift = forgePotGift(world, s, at);
  return { place: at, name: f.name, keeper: f.keeper, hello: f.hello, recipes: open, locked: RECIPES.length - open.length, ...gift };
}

function pay(c, cost) {
  c.gold -= cost.gold;
  for (const [id, n] of cost.mats) removeItem(c, id, n);
}

// reply(ok, text, extra) で こたえる。helpers: { equipItem, ownChar }（services.js）
export function forgeAction(world, s, msg, reply, { equipItem, ownChar }) {
  const c = s.char;
  switch (msg.action) {
    case 'craft': {
      const r = recipeOf(msg.id);
      const it = r && ITEMS[r.id];
      if (!it || !recipeOpen(r, world.hasFlagFn(s))) return reply(false, 'それは、まだ作れないな。');
      const lack = lackOf(c, r);
      if (lack.mats.length) return reply(false, `素材が足りないようだ。\n（${lack.mats.map((m) => `${ITEMS[m.id]?.name || m.id}があと${m.need - m.have}個`).join('・')}）`);
      if (lack.gold) return reply(false, 'おや？ゴールドが足りないようだな。');
      if (itemCount(c, r.id) >= BAG_STACK) return reply(false, `${it.name}は、もう持ちきれないようだ。`);
      // だれが 装備する？（じぶん か じぶんの 仲間）
      const who = msg.who ? ownChar(s, msg.who) : null;
      if (msg.who && (!who || !canEquipChar(who, r.id))) return reply(false, 'その人は装備できないようだ。');
      pay(c, r);
      addItem(c, r.id, 1);
      const lines = [`${it.name}が完成した！`];
      if (who) {
        const old = who.equip[it.type];
        equipItem(who, r.id, c);
        lines.push(`${who.name}は${it.name}を装備した！`);
        if (old) lines.push(`${ITEMS[old]?.name || old}は、ふくろに入れた。`);
        if (who !== c) world.sendParty(partyOf(world, s));
      } else {
        lines.push(`${it.name}は、ふくろに入れた。`);
      }
      return reply(true, lines.join('\n'), { made: r.id, equipped: !!who });
    }
    case 'upgrade': {
      // れん金で ふやした 回数は 持ち主（自分）の きろく
      const cost = upgradeCost(msg.id, c);
      if (!cost) {
        // 第35回: 店で 買える 装備（★1）は きたえられない
        if (isShopForge(msg.id)) return reply(false, 'それは店で売っている品だな。\n店の品（★1）は、きたえられないんだ。');
        const top = maxPlus(msg.id, c);
        if (top && (ITEMS[msg.id]?.lb || 0) >= LB_MAX) return reply(false, `それは、もう★${LB_MAX}まで限界とっぱしているな。\nこれ以上は、わしにもむりだ。`);
        return reply(false, top ? `それは、これ以上きたえられないな。\n（その装備は+${top}まで。ランクが高い装備ほど、たくさんきたえられる）` : 'それは、きたえられないな。');
      }
      // who … 装備している 人（じぶん か じぶんの 仲間）。ない ときは ふくろの 品
      const owner = msg.who ? ownChar(s, msg.who) : null;
      const slot = ITEMS[msg.id].type;
      if (msg.who) {
        if (!owner || owner.equip?.[slot] !== msg.id) return reply(false, 'その装備は見当たらないな。');
      } else {
        if (itemCount(c, msg.id) < 1) return reply(false, 'それは持っていないようだな。');
        if (itemCount(c, cost.to) >= BAG_STACK) return reply(false, `${ITEMS[cost.to].name}は、もう持ちきれないようだ。`);
      }
      if (cost.reborn && owner && !canEquipChar(owner, cost.to)) return reply(false, 'その人は、生まれ変わった武器を装備できないようだ。');
      const lack = lackOf(c, cost);
      if (lack.mats.length) return reply(false, `素材が足りないようだ。\n（${lack.mats.map((m) => `${ITEMS[m.id]?.name || m.id}があと${m.need - m.have}個`).join('・')}）`);
      if (lack.gold) return reply(false, 'おや？ゴールドが足りないようだな。');
      pay(c, cost);
      if (owner) {
        owner.equip[slot] = cost.to;
        const st = computeStats(owner);
        owner.hp = Math.min(owner.hp, st.maxHp);
        owner.mp = Math.min(owner.mp, st.maxMp);
        if (owner !== c) world.sendParty(partyOf(world, s));
      } else {
        removeItem(c, msg.id, 1);
        addItem(c, cost.to, 1);
      }
      // 生まれ変わり（かくし要素）
      if (cost.reborn) return reply(true, `カン！カン！カン！\n…なんと！\n${ITEMS[msg.id].name}は、${ITEMS[cost.to].name}に生まれ変わった！`, { upgraded: cost.to, who: msg.who || null, reborn: true, from: msg.id });
      // 第65回: 限界とっぱ
      if (cost.limit) return reply(true, `カン！カン！…キィィン！\n${ITEMS[msg.id].name}は、限界をこえて\n${ITEMS[cost.to].name}になった！${cost.lb === 1 ? '\n（れん金の効果を2つつけられるようになった）' : ''}`, { upgraded: cost.to, who: msg.who || null, limit: cost.lb });
      return reply(true, `カン！カン！カン！\n${ITEMS[msg.id].name}は、${ITEMS[cost.to].name}になった！`, { upgraded: cost.to, who: msg.who || null });
    }
    // 第64回 ⑥b: 分解（ふくろの 装備 1つ → 素材。data/salvage.js）
    case 'salvage': {
      const id = String(msg.id || '');
      const block = salvageBlock(id);
      if (block) return reply(false, block);
      if (itemCount(c, id) < 1) return reply(false, 'それは持っていないようだな。\n（装備している物は、外してから分解してくれ）');
      const mats = salvageOf(id);
      const full = mats.find(([m, n]) => itemCount(c, m) + n > BAG_STACK);
      if (full) return reply(false, `${ITEMS[full[0]].name}は、もう持ちきれないようだ。`);
      removeItem(c, id, 1);
      for (const [m, n] of mats) addItem(c, m, n);
      return reply(true, `トン、トン、トン…\n${ITEMS[id].name}を分解した！\n${mats.map(([m, n]) => `${ITEMS[m].name}を${n}個`).join('・')}手に入れた！`, { salvaged: id, mats });
    }
    default:
      return reply(false, '');
  }
}

js/shared/world/gift.js:
// 第50回 N6: 家族に 道具を あげる（メニューの 道具 →「家族にあげる」。client/ui/gift.js）
//
// ・あげる 相手: 同じ 家族サーバーの ほかの キャラ（パーティーで なくても、今 遊んでいなくても よい）
//   - キャラは サーバーの world.data.characters に いつも ある（遊んでいない 人も）。ふくろに 入れて セーブ
//     すれば なくならない（酒場に 魔物が 来る しくみ〈recruit-share.js〉と 同じ）
//   - その キャラを スマホ（ひとりで遊ぶ）で 遊んでいても、合わせる 時に ふえた ぶんは のこる（merge.js の 道具は ふえた・へった 数を たす）
// ・ひとりで遊ぶ（offline）時は できない（家族と いっしょに 遊ぶ 時の しくみ。メニューにも 出さない）
// ・あげられる 物: ふくろの 道具・装備品・種・素材（装備している 物は ふくろに ないので あげられない。外してから）
// ・あげられない 物: 大事な物・1人1つの 品（ボスの 品〈unique〉）
// ・相手の ふくろが いっぱい（1つの 品は 99こまで）なら やめる（何も へらない）
// ・知らせ: 遊んでいる 相手には その 場で（戦いの 中なら 終わってから）。いない 人は c.tavernNews に のこし、
//   つぎに 入った 時に 出す（recruit-share.js の tavernNewsText が この 文を 使う）
// ・数・相手・品物は ぜんぶ サーバーで たしかめる（クライアントの 言う ことは 信じない）
import { ITEMS } from '../data/items.js';
import { itemCount, addItem, removeItem } from '../stats.js';

export const GIFT_STACK_MAX = 99;
const NEWS_MAX = 10; // recruit-share.js の TAVERN_NEWS_MAX と 同じ

const own = (o, k) => !!o && typeof k === 'string' && Object.prototype.hasOwnProperty.call(o, k);
const qtyText = (name, n) => (n > 1 ? `${name}を${n}こ` : `${name}を`);

// 今 遊んでいる（知らせが とどく）セッション
function liveSession(world, charId) {
  for (const m of world.sessions.values()) if (m.charId === charId && m.inWorld && m.conn && !m.away) return m;
  return null;
}

// あげられる 品か（だめな 時は わけ）
export function giftBlock(c, id) {
  const it = own(ITEMS, id) ? ITEMS[id] : null;
  if (!it) return 'それはあげられない';
  if (it.type === 'key' || c?.keyItems?.includes(id)) return '大事な物はあげられない';
  if (it.unique) return `${it.name}は1人1つの品なので、あげられない`;
  return null;
}

// あげる 相手の 一覧（自分の ほかの キャラ。作った じゅん）。online … 今 遊んでいる
export function giftTargets(world, s) {
  if (world.offline) return [];
  const me = s?.char?.id;
  return Object.values(world.data.characters || {})
    .filter((c) => c && c.id && c.id !== me && !c.species)
    .sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0))
    .map((c) => ({ id: c.id, name: c.name, level: c.level, online: !!liveSession(world, c.id) }));
}

// あげる。msg: { id: 品物, to: キャラの id, n: 数 }。もどりち: { ok, text }
export function giveItem(world, s, msg) {
  const c = s?.char;
  if (!c) return { ok: false, text: '' };
  if (world.offline) return { ok: false, text: '家族サーバーで遊んでいる時だけ、家族に道具をあげられる' };
  const id = msg?.id;
  const why = giftBlock(c, id);
  if (why) return { ok: false, text: why };
  const it = ITEMS[id];
  const to = typeof msg?.to === 'string' ? msg.to : '';
  if (to && to === c.id) return { ok: false, text: '自分にはあげられない' };
  const chars = world.data.characters || {};
  const target = own(chars, to) ? chars[to] : null;
  if (!target || target.species) return { ok: false, text: 'その人が見つからない' };
  if (target === c) return { ok: false, text: '自分にはあげられない' };
  const n = msg?.n;
  if (!Number.isInteger(n) || n < 1 || n > GIFT_STACK_MAX) return { ok: false, text: 'その数はあげられない' };
  const have = itemCount(c, id);
  if (have < 1) {
    const worn = Object.values(c.equip || {}).includes(id);
    return { ok: false, text: worn ? `装備している${it.name}はあげられない\n（外してからにしよう）` : `${it.name}を持っていない` };
  }
  if (have < n) return { ok: false, text: `${it.name}は${have}こしか持っていない` };
  if (!Array.isArray(target.items)) target.items = [];
  if (itemCount(target, id) + n > GIFT_STACK_MAX) {
    return { ok: false, text: `${target.name}のふくろには、もう${it.name}が入らない\n（1つの品は${GIFT_STACK_MAX}こまで）` };
  }
  // ここまで たしかめてから 動かす（とちゅうで 止まらない）
  if (!removeItem(c, id, n)) return { ok: false, text: '' };
  addItem(target, id, n);
  const note = { gift: true, item: id, n, from: c.name, at: world.now() };
  const m = liveSession(world, target.id);
  if (m) {
    world.send(m, { t: 'toast', text: giftNewsText(note, true), afterBattle: true, sfx: 'confirm' });
    world.sendSelf(m);
  } else {
    const list = Array.isArray(target.tavernNews) ? target.tavernNews : [];
    target.tavernNews = [...list, note].slice(-NEWS_MAX);
  }
  world.markDirty();
  return { ok: true, text: `${target.name}に${qtyText(it.name, n)}あげた！` };
}

// 知らせの 文（now … その 場で もらった。ちがう 時は 遊んでいない 間に とどいた）
export function giftNewsText(n, now = false) {
  const name = own(ITEMS, n?.item) ? ITEMS[n.item].name : '道具';
  const k = Math.max(1, Math.floor(Number(n?.n) || 1));
  const from = String(n?.from || '家族');
  return now ? `${from}から${qtyText(name, k)}もらった！` : `${from}から${name}${k > 1 ? `が${k}こ` : 'が'}とどいていた！\n（ふくろに入っているよ）`;
}

js/shared/world/growth.js:
// 戦いの あとの レベルアップの まとめ（第31回）
//   1レベルずつ 出さない。1回の 戦いで 上がった ぶんを 1人 1〜2行に まとめる（client/ui/result.js が 1画面に 出す）
//     「ユウ　Lv12→15　戦士Lv3→4！　HP+20　力+9　守り+6」
//     「覚えた：ホイミ、ベホイミ」
//   マスター・新しい 職業・ヒントは べつの 行（notes。めったに 出ない 大事な 知らせ）
import { JOB_MAX_LEVEL } from '../data/jobs.js';
// 第38回 B: Lv15・Lv20（第65回: Lv25 も）の しょうごう・上限に なった ときの 試練の 知らせ（data/job-trials.js）
import { titleFor, jobTopCap, jobLevelCap, TITLE_LEVELS } from '../data/job-trials.js';
import { ABILITIES } from '../data/abilities.js';
import { abilityFor } from '../ability-label.js';
import { jobLabel } from '../job-label.js';

export const GROW_STATS = ['maxHp', 'maxMp', 'str', 'def', 'agi', 'mag', 'heal'];
const SHORT = { maxHp: 'HP', maxMp: 'MP', str: '力', def: '守り', agi: '素早さ', mag: '魔力', heal: '回復' };
export const statShort = (k) => SHORT[k] || k;

// 覚えた 技の 名前（掛け合わせ技は そう わかるように）。who: 覚えた 人（男の子の 美少女戦士などは 名前が かわる。ability-label.js）
export function learnName(id, who = null) {
  const a = abilityFor(id, who);
  if (!a) return '';
  return a.kind === 'combo' ? `掛け合わせ技「${a.name}」` : a.name;
}

// name … 名前、ups … gainExp の 結果（1レベルごと）、jups … gainJobBattles の 結果（1職業レベルごと）、who … その キャラ（技・職業の 名前に 使う。job-label.js）
// かえす もの: { lines: [まとめの 行（0〜2行）], notes: [★の 知らせ] }
// opt.self … 自分の キャラ（職業の試練を 受けられる。第38回 B）
export function growthSummary(name, ups = [], jups = [], who = null, opt = {}) {
  const lines = [], notes = [];
  if (!ups.length && !jups.length) return { lines, notes };
  const gains = {}, learned = [];
  for (const u of [...ups, ...jups]) {
    for (const [k, v] of Object.entries(u.gains || {})) if (v > 0) gains[k] = (gains[k] || 0) + v;
    for (const id of u.learned || []) if (ABILITIES[id] && !learned.includes(id)) learned.push(id);
  }
  const head = [];
  if (ups.length) head.push(`Lv${ups[0].level - 1}→${ups[ups.length - 1].level}`);
  // 職業レベル（戦いの とちゅうで 転職は しないので ふつうは 1つの 職業）
  const byJob = new Map();
  for (const u of jups) {
    const r = byJob.get(u.job) || { from: u.lv - 1, to: u.lv };
    r.to = u.lv;
    byJob.set(u.job, r);
  }
  const jn = (j) => jobLabel(j, who) || j;
  for (const [job, r] of byJob) head.push(`${jn(job)}Lv${r.from}→${r.to}`);
  const st = GROW_STATS.filter((k) => gains[k] > 0).map((k) => `${statShort(k)}+${gains[k]}`).join('　');
  lines.push(`${name}　${head.join('　')}！${st ? `　${st}` : ''}`);
  if (learned.length) lines.push(`覚えた：${learned.map((id) => learnName(id, who)).join('、')}`);
  for (const u of jups) {
    // マスターは Lv10 に なった 時だけ（第38回 B: Lv11〜 は しょうごう・上限の 知らせ）
    if (u.lv === JOB_MAX_LEVEL) notes.push(`★ ${name}は${jn(u.job)}をマスターした！`);
    if (TITLE_LEVELS.includes(u.lv)) {
      const t = titleFor(u.job, u.lv, who);
      if (t) notes.push(`★ ${name}は、しょうごう「${t}」を手に入れた！`);
    }
    // 上限に なった（まだ 試練で 上げられる）: 試練の番人の 知らせ
    if (opt.self && who && u.lv >= JOB_MAX_LEVEL && u.lv < jobTopCap(u.job) && u.lv >= jobLevelCap(who, u.job)) {
      notes.push(`☆ ${jn(u.job)}の職業レベルが、今の上限になった。\n（ルミナの町の神殿の「試練の番人」の試練で、上限を上げられる）`);
    }
    for (const id of u.unlocked || []) notes.push(`★ ${name}は${jn(id)}になれるようになった！（ルミナの町の神殿で転職できる）`);
    for (const id of u.hinted || []) notes.push(`☆ 新しい職業「${jn(id)}」のヒントを見つけた！（神殿で見られる）`);
  }
  return { lines, notes };
}

