// 第38回 B: 職業の試練（ルミナの町の 星の神殿の「試練の番人」。だいほんは data/story-trials.js、きまりは data/job-trials.js）
// ・超級職・伝説の職業で、今の 職業の「〇〇の一の試練」（Lv10 から）・「〇〇の二の試練」（Lv15 から）・
//   「〇〇の三の試練」（Lv20 から。第6章クリアの あと。第65回 D1）を 受けられる
// ・1. 修行（その 職業の 技を、勝った 戦いで N回 使う。world/battles.js が 数える）→ 2. 師しょうのまぼろしと 戦う → 上限が 15・20・25 に
// ・ひとりずつ（自分の 職業）。師しょうのまぼろしの 戦いには、そばに いる 家族も 入る（とちゅうから かけつけても よい）。
//   勝っても 上限が 上がるのは 試練を 受けた 人だけ。負けても お金は へらない（その場で 立ち上がる）
import { TRIAL_HOOKS, TRIAL_KEEPER } from '../data/story-trials.js';
import {
  TRIALS, TRIAL_FLAG_TEXT, trialState, acceptTrial, clearTrial, trialName, masterName, trialWords, titleFor, jobUpKeys, jobTopCap,
} from '../data/job-trials.js';
import { JOBS, TIER_NAMES, JOB_MAX_LEVEL } from '../data/jobs.js';
import { jobLabel } from '../job-label.js';
import { STAT_NAMES } from '../stats.js';
import { startFixedBattle, battleSessions } from './battles.js';
import { partyOf } from './party.js';
import { setupTrialPhantom } from '../battle-trial.js';

const say = (text) => ['say', TRIAL_KEEPER, text];
const note = (text) => ['say', null, text];

async function flushOk(run) {
  const r = await run.flush();
  if (r.aborted) {
    run.abort();
    return false;
  }
  return true;
}

// 得意な 数値の 名前（「力と身の守り」）
function upText(id) {
  return jobUpKeys(id).map((k) => STAT_NAMES[k] || k).join('と');
}

// ───────────── 試練の番人 ─────────────
export async function keeperTalk(run) {
  const c = run.init.char;
  const id = c.job;
  const st = trialState(c, id);
  const J = jobLabel(id, c);
  const steps = [];
  if (!c.flags?.trial_seen) {
    steps.push(
      say('わしは試練の番人。\n超級職より上の者に、職業の試練をさずけておる。'),
      say(`試練をこえると、職業レベルを${JOB_MAX_LEVEL}より上に上げられる。\n${TRIALS.map((T) => `${T.name}でLv${T.cap}`).join('、')}までじゃ。`),
      say('ただし、新しい技は覚えぬ。\nレベルが上がるたびに、その職業の得意な強さが\n少しずつのびるだけじゃ。'),
    );
    c.flags.trial_seen = true;
  }
  if (st.why === 'tier') {
    const tier = JOBS[id]?.tier || 0;
    steps.push(say(`${c.name}は今、${J}（${TIER_NAMES[tier]}）じゃな。\n試練は、超級職か伝説の職業でないと受けられぬ。`), say('上の職業をきわめたら、また来るがよい。'));
    return run.runSteps(steps);
  }
  if (st.all) {
    const t = titleFor(id, st.lv, c);
    steps.push(say(`${J}の試練は、すべてこえたな。\n${t ? `「${t}」の名に、はじぬように。` : 'あとは、レベルを上げるだけじゃ。'}`));
    if (st.lv < st.cap) steps.push(say(`今はLv${st.lv}。Lv${st.cap}まで上げられるぞ。`));
    return run.runSteps(steps);
  }
  if (st.active && !st.ready) {
    const T = st.active;
    steps.push(
      say(`${trialName(id, T.n, c)}の、修行のとちゅうじゃな。`),
      say(`${J}の技を、戦いで使って勝つこと。\n今は${st.count}回。あと${st.need - st.count}回じゃ。`),
      note('（メニューの「強さ」と「クエスト」でも、修行の数が見られる）'),
    );
    return run.runSteps(steps);
  }
  if (st.active && st.ready) {
    const T = st.active;
    const p = partyOf(run.world, run.init);
    const fam = (p?.members.length || 1) > 1;
    steps.push(
      say(`見事、${trialName(id, T.n, c)}の修行をやりとげたな。`),
      say(`いよいよ、${masterName(id, c)}のまぼろしとの戦いじゃ。\nまぼろしは、${J}の技を使ってくるぞ。`),
      say(`強さは、Lv${T.lv}くらいの者と同じくらいじゃ。\n負けても、お金はへらぬ。${fam ? '\nそばにいる家族も、いっしょに戦えるぞ。' : ''}`),
      ['choice', '師しょうのまぼろしと戦う？', ['戦う', 'やめる'], [
        [['call', (r) => trialBattle(r, id, T.n)]],
        [say('じゅんびができたら、また来るがよい。')],
      ]],
    );
    return run.runSteps(steps);
  }
  const T = st.next;
  if (st.why === 'story') {
    // 第65回 D1: 三の試練は 物語の しるし（第6章クリア）が いる
    steps.push(
      say(`${trialName(id, T.n, c)}の相手は、とても強いまぼろしじゃ。\n強さは、Lv${T.lv}くらいの者と同じくらいある。`),
      say(`${TRIAL_FLAG_TEXT[T.flag] || 'もっと旅をして'}から、受けに来るがよい。`),
    );
    return run.runSteps(steps);
  }
  if (!st.canTake) {
    steps.push(say(`${trialName(id, T.n, c)}は、${J}の職業レベルが\n${T.needLv}になったら受けられる。（今はLv${st.lv}）`), say('もっと戦って、きたえてくるがよい。'));
    return run.runSteps(steps);
  }
  steps.push(
    say(`${c.name}よ。${trialName(id, T.n, c)}を受けるか？`),
    say(`一つ目は、修行。\n${J}の技を、戦いで合計${T.uses}回使って勝つのじゃ。`),
    say(`二つ目は、${masterName(id, c)}のまぼろしとの戦い。\n勝てば、${J}の職業レベルの上限がLv${T.cap}になる。`),
    say(`上限をこえたぶんは、${upText(id)}が\nレベル1つで1〜2ずつのびるぞ。`),
    ['choice', `${trialName(id, T.n, c)}を受ける？`, ['受ける', 'やめる'], [
      [['call', (r) => trialAccept(r, id)]],
      [say('いつでも待っておるぞ。')],
    ]],
  );
  return run.runSteps(steps);
}

async function trialAccept(run, id) {
  const c = run.init.char;
  const T = acceptTrial(c, id);
  if (!T) return run.runSteps([say('…おや？今は受けられぬようじゃ。')]);
  run.world.sendSelf(run.init);
  run.world.markDirty();
  return run.runSteps([
    ['sfx', 'key'],
    note(`${c.name}は、${trialName(id, T.n, c)}を受けた！`),
    say(`${masterName(id, c)}は、よくこう言っておった。\n「${trialWords(id, c)}」`),
    say(`まずは修行じゃ。${jobLabel(id, c)}の技を、\n戦いで${T.uses}回使って勝ってくるがよい。`),
  ]);
}

// とちゅうで かけつけた 家族（戦いの あとで だいほんの 外に のこった 人）を だいほんに 入れる（world/arena.js と おなじ）
function adopt(run) {
  const w = run.world;
  const p = partyOf(w, run.init);
  for (const sid of p?.members || []) {
    const m = w.sessions.get(sid);
    if (!m || run.parts.includes(m) || m.busy !== 'script' || (m.runId && w.runs.has(m.runId))) continue;
    run.parts.push(m);
    m.runId = run.id;
  }
}

// そばに いる 家族（ふつうの 戦いと おなじ きょり。ほかの ことを していない 人）を だいほんに 入れる
function gatherFamily(run) {
  const w = run.world;
  for (const m of battleSessions(w, run.init)) {
    if (m === run.init || run.parts.includes(m)) continue;
    run.parts.push(m);
    m.busy = 'script';
    m.runId = run.id;
  }
}

// 師しょうのまぼろしとの 戦い
export async function trialBattle(run, id, n) {
  const w = run.world;
  const c = run.init.char;
  const T = TRIALS[n - 1];
  gatherFamily(run);
  const others = run.everyone.filter((m) => m !== run.init).map((m) => m.char.name);
  run.batch.push(['sfx', 'encounter']);
  if (others.length) run.batch.push(note(`${others.join('と')}も、いっしょに戦ってくれる！`));
  if (!(await flushOk(run))) return;
  const res = await startFixedBattle(w, run.init, run.everyone, T.enc, { setup: (b) => setupTrialPhantom(b, { job: id, n, who: c }) });
  adopt(run);
  if (res === 'win') {
    const r = clearTrial(c, id);
    w.sendSelf(run.init);
    w.markDirty();
    const lines = [['sfx', 'win'], note(`${c.name}は、${trialName(id, n, c)}をこえた！`)];
    if (r) lines.push(note(`${jobLabel(id, c)}の職業レベルの上限が、Lv${r.cap}になった！`));
    lines.push(say(`見事じゃ。${masterName(id, c)}も、\nきっと、よろこんでおるじゃろう。`));
    if (r && r.cap < jobTopCap(id)) lines.push(say(`職業レベルが${r.cap}になったら、\n次の試練を受けに来るがよい。`));
    else lines.push(say(`これで${jobLabel(id, c)}の試練は、すべてこえた。\nLv${r?.cap || jobTopCap(id)}をめざして、きたえるがよい。`));
    w.saveNow?.({ urgent: true });
    return run.runSteps(lines);
  }
  if (res === 'lose') {
    return run.runSteps([
      note('気がつくと、神殿でたおれていた…。\n（お金はへっていない。HPとMPはもどった）'),
      say('まぼろしとはいえ、師しょうの力は本物じゃ。\n強くなって、また来るがよい。'),
    ]);
  }
  return run.runSteps([say('戦いが止まったようじゃな。\nまた来るがよい。')]);
}

Object.assign(TRIAL_HOOKS, { keeper: keeperTalk });

js/shared/world/merge.js:
// べつべつの 場所で 遊んだ おなじ キャラを ひとつに まとめる（どちらで 進めた ぶんも なくさない）
//
//   base   … 2つに わかれる まえの キャラ（さいごに データを 合わせた ときの もの）
//   ours   … こちらの キャラ（たとえば 家族サーバー）
//   theirs … とどいた キャラ（たとえば スマホの ひとりで遊ぶサイト）
//
// ・けいけんち・ゴールド・たおした 数・職業の 勝った 数・種・技を 使った 回数・幻の職業の 記録 … 両方で ふえた（へった）ぶんを たす
// ・ひらめいた 技 … 両方を 合わせる（わすれる ことは ない）
// ・フラグ・宝箱・行った 場所・大事な物 … 両方を 合わせる（どちらかで 使った 大事な物は なくなる）
// ・道具と そうび … 品物ごとに 両方で ふえた・へった 数を たす（そうびは 手もとに ある ものだけ。ボスの 品は 1つまで）
// ・仲間 … 両方の 仲間を のこす（べつべつに 仲間に なった まものは 両方とも。家族の パーティーで 酒場に 来た まものも おなじ）
// ・預かり所 … お金も 品物も、両方で 預けた・引き出した ぶんを たす
// ・いる場所・HP・作戦 など … 両方で かわって いたら、あとで 遊んだ ほう
import { expForLevel, MAX_LEVEL, computeStats } from '../stats.js';
import { JOBS, jobBattlesForLevel } from '../data/jobs.js';
// 第38回 B: 職業の試練（クリアした 数は 多い ほう・受けている 試練の 修行は 多い ほう）。上限は クリアした 数から
import { mergeTrialInfo, jobCapOf } from '../data/job-trials.js';
import { ITEMS, SLOTS } from '../data/items.js';
import { STORY_STEPS } from '../data/story.js';
import { COMPANION_SLOTS } from '../data/companions.js';
import { STORAGE_MAX } from './party.js';
import { WAGON_SLOTS } from '../data/wagon.js';
import { repairChar } from './save.js';
import { mergeTreasureMaps } from '../data/treasure.js';
import { mergeSecret } from '../data/secret.js';
import { mergeAlchemy } from './alchemy.js';
import { mergeArena } from '../data/arena.js';
import { COIN_MAX } from '../data/casino.js';
// 第51回 F: 幻の職業の 記録（両方で ふえた ぶんを たす・どちらの 数より 下に しない）
import { mergeFeats } from './phantom.js';

const GOLD_MAX = 9999999;
const clone = (x) => (x === undefined ? undefined : JSON.parse(JSON.stringify(x)));
const num = (v) => (Number.isFinite(v) ? v : 0);
const isObj = (v) => v && typeof v === 'object' && !Array.isArray(v);

// 中みが おなじか（キーの じゅんばんは 気にしない）
export function canon(x) {
  if (Array.isArray(x)) return `[${x.map(canon).join(',')}]`;
  if (isObj(x)) return `{${Object.keys(x).filter((k) => x[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${canon(x[k])}`).join(',')}}`;
  return JSON.stringify(x ?? null);
}
const same = (x, y) => canon(x) === canon(y);

// さいごに さわった 時こく
export function charTime(c) {
  return Math.max(num(c?.lastPlayed), num(c?.savedAt));
}

// ものがたりの すすみぐあい（-1 … まだ はじまっていない）
function storyIndex(c) {
  let idx = -1;
  STORY_STEPS.forEach((f, i) => {
    if (c?.flags?.[f]) idx = i;
  });
  return idx;
}

// かわった ほうを とる（両方 かわって いたら あとで 遊んだ ほう）
function pick(b, a, t, tLater) {
  if (same(a, b)) return clone(t);
  if (same(t, b)) return clone(a);
  return clone(tLater ? t : a);
}

// ふえた・へった ぶんを たす
function add(b, a, t) {
  return Math.max(0, num(a) + num(t) - num(b));
}

// { key: あたい } を 1つずつ まとめる
function eachKey(b, a, t, fn) {
  const out = {};
  for (const k of new Set([...Object.keys(a || {}), ...Object.keys(t || {}), ...Object.keys(b || {})])) {
    const v = fn(b?.[k], a?.[k], t?.[k], k);
    if (v !== undefined && v !== null) out[k] = v;
  }
  return out;
}

// なまえの あつまり（どちらかで 消した ものは 消す。あたらしく ふえた ものは のこす）
function mergeSet(b = [], a = [], t = []) {
  const B = new Set(b), A = new Set(a), T = new Set(t);
  const out = [];
  for (const x of [...a, ...t]) {
    if (out.includes(x)) continue;
    if (B.has(x) && (!A.has(x) || !T.has(x))) continue;
    out.push(x);
  }
  return out;
}

// 地図の 行った ところ（ビットの OR）
function orBits(x, y) {
  if (!x) return y;
  if (!y || x === y) return x;
  try {
    const p = atob(x), q = atob(y);
    let s = '';
    for (let i = 0; i < Math.max(p.length, q.length); i++) s += String.fromCharCode((p.charCodeAt(i) || 0) | (q.charCodeAt(i) || 0));
    return btoa(s);
  } catch {
    return x.length >= y.length ? x : y;
  }
}

function levelForExp(exp) {
  let lv = 1;
  while (lv < MAX_LEVEL && exp >= expForLevel(lv + 1)) lv++;
  return lv;
}

// 職業ごとの 勝った 数（レベルは 勝った 数から。どちらの レベルより 下には しない）
// 第38回 B: 上限は 職業の試練の クリアの 数から（ふつう 10・超級職から 15・20）。試練の 項目は data/job-trials.js の mergeTrialInfo
function mergeJobs(b = {}, a = {}, t = {}) {
  return eachKey(b, a, t, (jb, ja, jt, id) => {
    if (!ja && !jt) return undefined;
    const tier = JOBS[id]?.tier || 0;
    const bb = add(jb?.b, ja?.b, jt?.b);
    const tri = mergeTrialInfo(id, ja || {}, jt || {});
    const cap = jobCapOf(id, tri);
    let lv = Math.max(ja?.lv || 1, jt?.lv || 1);
    while (lv < cap && bb >= jobBattlesForLevel(lv + 1, tier)) lv++;
    const out = { ...(clone(ja) || clone(jt)), lv, b: Math.max(bb, ja?.b || 0, jt?.b || 0) };
    for (const k of ['tr', 'tq', 'tn']) delete out[k];
    return { ...out, ...tri };
  });
}

// ずかん（見た 数・仲間に した 数 など）
function mergeBestiary(b = {}, a = {}, t = {}) {
  return eachKey(b, a, t, (eb, ea, et) => {
    if (!ea && !et) return undefined;
    return eachKey(eb, ea, et, (vb, va, vt) => (typeof (va ?? vt) === 'number' ? add(vb, va, vt) : pick(vb, va, vt, true)));
  });
}

// 預かり所（お金・品物ごとに 両方で ふえた・へった ぶんを たす）
function mergeBank(b, a, t) {
  const count = (x) => new Map((Array.isArray(x?.items) ? x.items : []).filter((e) => e && typeof e.id === 'string').map((e) => [e.id, num(e.n)]));
  const B = count(b), A = count(a), T = count(t);
  const items = [];
  for (const id of new Set([...A.keys(), ...T.keys(), ...B.keys()])) {
    const n = add(B.get(id), A.get(id), T.get(id));
    if (n > 0) items.push({ id, n });
  }
  return { gold: Math.min(GOLD_MAX, add(b?.gold, a?.gold, t?.gold)), items };
}

// キャラの 中みを まとめる（主人公・仲間 どちらも）。道具は あとで まとめて 数える
function mergeBody(b, a, t, tLater) {
  const out = {};
  const keys = new Set([...Object.keys(a || {}), ...Object.keys(t || {})]);
  for (const k of keys) {
    const vb = b?.[k], va = a?.[k], vt = t?.[k];
    switch (k) {
      case 'exp': out.exp = Math.max(add(vb, va, vt), num(va), num(vt)); break;
      case 'gold': out.gold = Math.min(GOLD_MAX, add(vb, va, vt)); break;
      case 'kills': case 'seeds': case 'skillUse': out[k] = eachKey(vb, va, vt, (x, y, z) => add(x, y, z) || undefined); break;
      case 'feats': out.feats = mergeFeats(vb, va, vt); break;
      case 'hirameki': out.hirameki = [...new Set([...(Array.isArray(va) ? va : []), ...(Array.isArray(vt) ? vt : [])])]; break;
      case 'jobs': out.jobs = mergeJobs(vb, va, vt); break;
      case 'bestiary': out.bestiary = mergeBestiary(vb, va, vt); break;
      case 'bank': out.bank = mergeBank(vb, va, vt); break;
      case 'flags': case 'chests': case 'visited': case 'searched': case 'dualSeen':
        out[k] = eachKey(vb, va, vt, (x, y, z) => pick(x, y, z, tLater));
        break;
      case 'quests': out.quests = eachKey(vb, va, vt, (x, y, z) => pick(x, y, z, tLater)); break;
      case 'sparkles': out.sparkles = eachKey(vb, va, vt, (x, y, z) => Math.max(num(y), num(z)) || undefined); break;
      case 'explored': out.explored = eachKey(vb, va, vt, (x, y, z) => orBits(y, z)); break;
      case 'keyItems': out.keyItems = mergeSet(vb, va, vt); break;
      // 乗り物（第37回）: どちらかで 買えば 持っている
      case 'vehicles': out.vehicles = mergeSet(vb, va, vt); break;
      case 'treasureMaps': out.treasureMaps = mergeTreasureMaps(vb, va, vt); break;
      // ひみつのダンジョンの 記録（深い ほう。もらった ごほうびは 両方）
      case 'sd': out.sd = mergeSecret(vb, va, vt); break;
      // れん金がま（レシピは 両方・回数は 多い ほう。world/alchemy.js）
      case 'alchemy': out.alchemy = mergeAlchemy(vb, va, vt, tLater); break;
      // 第37回 A: 闘技場の 記録（勝ちぬいた 回数は 両方で ふえた ぶん・はじめての 時こくは 早い ほう。data/arena.js）
      case 'arena': out.arena = mergeArena(vb, va, vt); break;
      case 'supportLog': {
        const seen = new Set((vb || []).map(canon));
        out.supportLog = [...clone(va || []), ...clone((vt || []).filter((e) => !seen.has(canon(e))))].slice(-10);
        break;
      }
      // 家族の パーティーで 酒場に 来た まものの 知らせ（まだ 見ていない ぶん。world/recruit-share.js）
      // 「わかれる まえ」に あった 知らせは、片方で 見て けした なら もう 出さない
      case 'tavernNews': {
        const arr = (x) => (Array.isArray(x) ? x : []);
        const B = new Set(arr(vb).map(canon));
        const keep = (x) => !B.has(canon(x)) || (va !== undefined && vt !== undefined && arr(va).some((y) => canon(y) === canon(x)) && arr(vt).some((y) => canon(y) === canon(x)));
        const list = [];
        for (const e of [...arr(va), ...arr(vt)]) if (e && keep(e) && !list.some((y) => canon(y) === canon(e))) list.push(clone(e));
        out.tavernNews = list.length ? list.slice(-10) : undefined;
        break;
      }
      case 'monsterSeq': out.monsterSeq = Math.max(num(va), num(vt), 1); break;
      // カジノの コイン（ふえた・へった ぶんを たす）と 小さなメダル（見つけた 場所・もらった ごほうびは 両方を 合わせる）
      case 'coins': out.coins = Math.min(COIN_MAX, add(vb, va, vt)); break;
      // フィールドの 宝箱を 開けた 数
      case 'fieldChests': out.fieldChests = add(vb, va, vt) || undefined; break;
      case 'medalSpots': case 'medalRewards': out[k] = eachKey(vb, va, vt, (x, y, z) => y ?? z); break;
      case 'medalsGiven': out.medalsGiven = Math.max(num(va), num(vt)); break;
      // 第51回 B: 家族のけいじ板を さいごに 見た 時こく（おそい ほう）
      case 'boardSeen': out.boardSeen = Math.max(num(va), num(vt)) || undefined; break;
      // 第37回 B: すごろく券に かえた メダル（両方で かえた ぶんを たす）・宝の地図の クリア数（両方で ふえた ぶんを たす。
      //   わかれる 前に まだ 数えていなかった ときは 両方で 数えなおした 数なので 多い ほう）
      case 'medalsSpent': out.medalsSpent = add(vb, va, vt) || undefined; break;
      case 'tmClears': out.tmClears = vb === undefined ? Math.max(num(va), num(vt)) : Math.max(add(vb, va, vt), num(va), num(vt)); break;
      case 'jobSys': out.jobSys = Math.max(num(va), num(vt)) || undefined; break;
      case 'createdAt': {
        const ts = [va, vt].filter(Number.isFinite);
        if (ts.length) out.createdAt = Math.min(...ts);
        break;
      }
      case 'lastPlayed': case 'savedAt': out[k] = Math.max(num(va), num(vt)) || undefined; break;
      // 馬車は どちらかで もらって いれば もっている
      case 'wagon': out.wagon = va || vt ? true : undefined; break;
      case 'level': case 'companions': case 'items': case 'equip': case 'partyKeys': case 'wagonKeys': break; // あとで
      case 'storage': break; // あとで（魔物あずかり所。第43回 C）
      default: out[k] = pick(vb, va, vt, tLater);
    }
    if (out[k] === undefined) delete out[k];
  }
  if (a?.exp !== undefined || t?.exp !== undefined) out.level = Math.max(num(a?.level) || 1, num(t?.level) || 1, levelForExp(out.exp || 0));
  return out;
}

// 仲間（key ごと。べつべつに できた おなじ key の まものは 両方 のこす）
function mergeCompanions(b = [], a = [], t = [], tLater, nextKey) {
  const byKey = (list) => new Map((list || []).filter((e) => e?.key && e.char).map((e) => [e.key, e]));
  const B = byKey(b), A = byKey(a), T = byKey(t);
  const out = [];
  const renamed = new Map();
  const mergeOne = (eb, ea, et) => {
    const e = { ...clone(tLater ? et : ea), ...mergeBody(eb, ea, et, tLater) };
    e.char = { ...mergeBody(eb?.char, ea.char, et.char, tLater), equip: mergeEquip(eb?.char?.equip, ea.char.equip, et.char.equip, tLater) };
    return e;
  };
  for (const [k, ea] of A) {
    const eb = B.get(k), et = T.get(k);
    if (eb && !et) continue; // とどいた ほうで わかれた（酒場で おわかれ・配合）
    if (!et) out.push(clone(ea));
    else if (eb) out.push(mergeOne(eb, ea, et));
    else if (ea.kind !== 'monster' || same(ea, et)) {
      // おなじ 人（両方で 酒場の 仲間に なった）… 強い ほう（もう 片方の そうびは ふくろへ）
      out.push(clone(num(et.char.exp) > num(ea.char.exp) ? et : ea));
    } else {
      // べつべつに 仲間に なった まもの → 両方
      out.push(clone(ea));
      const e2 = clone(et);
      e2.key = nextKey();
      renamed.set(k, e2.key);
      out.push(e2);
    }
  }
  for (const [k, et] of T) {
    if (A.has(k) || B.has(k)) continue; // B に あって A に ない … こちらで わかれた
    out.push(clone(et));
  }
  return { list: out, renamed };
}

function mergeEquip(b = {}, a = {}, t = {}, tLater) {
  const out = {};
  for (const slot of SLOTS) out[slot] = pick(b?.[slot] ?? null, a?.[slot] ?? null, t?.[slot] ?? null, tLater) ?? null;
  return out;
}

// 道具ぶくろ + そうび（主人公と 仲間）の 数
function inventory(c) {
  const m = new Map();
  const put = (id, n = 1) => {
    if (id) m.set(id, (m.get(id) || 0) + n);
  };
  for (const e of c?.items || []) put(e?.id, num(e?.n) || 1);
  for (const slot of SLOTS) put(c?.equip?.[slot]);
  for (const e of c?.companions || []) for (const slot of SLOTS) put(e?.char?.equip?.[slot]);
  return m;
}

// 3つの キャラから 1つを つくる。もどりち: あたらしい キャラ（ours / theirs は かえない）
export function mergeChars(base, ours, theirs) {
  const b = base || {};
  const a = ours;
  const t = theirs;
  const tLater = charTime(t) > charTime(a);
  const out = mergeBody(b, a, t, tLater);
  out.id = a.id;

  // ものがたりは すすんでいる ほうに あわせる（目標・ゲスト）
  const sa = storyIndex(a), st = storyIndex(t);
  if (sa !== st) {
    const ahead = st > sa ? t : a;
    out.objective = clone(ahead.objective);
    out.guests = clone(ahead.guests);
  }

  // 仲間（まものの 番号が かさなったら あたらしい 番号に）
  const used = new Set([...(a.companions || []), ...(t.companions || [])].map((e) => e?.key));
  for (const e of [...(a.storage || []), ...(t.storage || [])]) used.add(e?.key);
  let seq = Math.max(num(a.monsterSeq), num(t.monsterSeq), 1);
  const nextKey = () => {
    while (used.has(`m${seq}`)) seq++;
    const k = `m${seq++}`;
    used.add(k);
    return k;
  };
  let renamed = new Map();
  if (a.companions || t.companions) {
    const r = mergeCompanions(b.companions, a.companions, t.companions, tLater, nextKey);
    out.companions = r.list;
    renamed = r.renamed;
    out.monsterSeq = Math.max(out.monsterSeq || 1, seq);
  }
  // 魔物あずかり所（第43回 C）: 仲間と 同じ 合わせかた。仲間に いる 魔物は あずかり所から はずす（両方で 出し入れした 時）
  if (a.storage || t.storage) {
    const r = mergeCompanions(b.storage, a.storage, t.storage, tLater, nextKey);
    const inRoster = new Set((out.companions || []).map((e) => e.key));
    out.storage = r.list.filter((e) => !inRoster.has(e.key)).slice(0, STORAGE_MAX);
    out.monsterSeq = Math.max(out.monsterSeq || 1, seq);
  }
  out.equip = mergeEquip(b.equip, a.equip, t.equip, tLater);
  const tKeys = (t.partyKeys || []).map((k) => renamed.get(k) || k);
  const keys = pick(b.partyKeys, a.partyKeys, tKeys, tLater) || [];
  const have = new Set((out.companions || []).map((e) => e.key));
  out.partyKeys = [...new Set(keys)].filter((k) => String(k).startsWith('fam:') || have.has(k)).slice(0, COMPANION_SLOTS);
  // 馬車の 仲間（まものの 番号が かわった ぶんも あわせる。パーティーに いる 仲間は のぞく）
  if (a.wagonKeys || t.wagonKeys) {
    // 馬車の きろくが ない ほう（馬車の ない 版で 遊んだ）は、かわって いない ものと する
    const tw = Array.isArray(t.wagonKeys) ? t.wagonKeys.map((k) => renamed.get(k) || k) : b.wagonKeys;
    const aw = Array.isArray(a.wagonKeys) ? a.wagonKeys : b.wagonKeys;
    const wk = pick(b.wagonKeys, aw, tw, tLater) || [];
    // 家族の キャラ（fam:）も 乗れる。いるかどうかは データを 合わせた あとで（sync.js の fixPartyKeys）
    out.wagonKeys = [...new Set(wk)].filter((k) => (String(k).startsWith('fam:') || have.has(k)) && !out.partyKeys.includes(k)).slice(0, WAGON_SLOTS);
  }

  // 道具と そうび: 品物ごとに ふえた・へった 数を たして、そうびの ぶんを のぞいた のこりが ふくろ
  const IB = inventory(b), IA = inventory(a), IT = inventory(t);
  const total = new Map();
  for (const id of new Set([...IA.keys(), ...IT.keys(), ...IB.keys()])) {
    let n = (IA.get(id) || 0) + (IT.get(id) || 0) - (IB.get(id) || 0);
    // 1人 1つの 品（ボスの 品）は、両方で もらっても ふえない
    if (ITEMS[id]?.unique) n = Math.min(n, Math.max(IA.get(id) || 0, IT.get(id) || 0));
    if (n > 0) total.set(id, n);
  }
  const take = (id) => {
    if (!id) return null;
    const n = total.get(id) || 0;
    if (n <= 0) return null;
    total.set(id, n - 1);
    return id;
  };
  for (const slot of SLOTS) out.equip[slot] = take(out.equip[slot]);
  for (const e of out.companions || []) {
    e.char.equip = e.char.equip || {};
    for (const slot of SLOTS) e.char.equip[slot] = take(e.char.equip[slot] ?? null);
  }
  const order = [...(a.items || []), ...(t.items || [])].map((e) => e?.id);
  out.items = [];
  for (const id of new Set([...order, ...total.keys()])) {
    const n = total.get(id) || 0;
    if (n > 0 && !out.items.some((e) => e.id === id)) out.items.push({ id, n });
  }

  repairChar(out, a.id);
  // HP・MP は 最大を こえない ように
  try {
    const stats = computeStats(out);
    out.hp = Math.min(out.hp, stats.maxHp);
    out.mp = Math.min(out.mp, stats.maxMp);
  } catch { /* */ }
  return out;
}

js/shared/world/missions.js:
// 第78回 3-10: 家族ミッション・家族の記録（サーバーで 数える。docs/plan-r78-mission.md）
//
// ・数えるのは 人間の キャラが 2人 いじょう いっしょの 時だけ（同じ パーティーで 同じ 戦い・同じ マップ）。
//   クライアントの 申告は 信じない（戦いの 終わり・宝箱・階だんで サーバーが 足す）
// ・ひとりモード（world.offline）では 何も 数えない・何も 書かない（画面は「家族サーバーでいっしょに遊ぶと進みます」）
// ・しまう 場所: 家族サーバーの 世界の 側（world.data.missions。キャラの 引っこしコードには 入れない）
//     week … 今週 { no, list:[{k,need}], prog, at, by:{キャラid:{name,n,b,k}}, got:{キャラid:[0/1…]}, kinds, floors, full, fullCred }
//     prev … 先週（次の 週の 間だけ ごほうびを 受けとれる）
//     total … 家族の 記録 { kills, wins, battles, full, done, weeks, boss:{魔物:数} }
//     fullBy … キャラごとの 3つとも 達成した 週の 合計 / hist … さいきんの 週（12こまで）
// ・キャラに 持たせるのは しょうごう・スタンプ だけ（c.famm。data/missions.js）
import {
  MISSIONS, WEEK_PICK, weekNo, weekStart, daysLeft, missionText, openKinds, pickWeek, weekReward,
  MILESTONES, milestoneOf, nextMilestone, earnedOf, wornTitle, DAY_MS,
} from '../data/missions.js';
import { MONSTERS } from '../data/monsters.js';
import { ITEMS } from '../data/items.js';
import { MAPS } from '../maps/index.js';
import { addItem } from '../stats.js';
import { partyOf } from './party.js';

const HIST_MAX = 12;
const FLOOR_MAX = 300;
const ACTIVE_MS = 28 * DAY_MS;
const num = (v) => (Number.isFinite(v) ? v : 0);
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});

// ───────────── 状態 ─────────────
function cleanWeek(w) {
  if (!w || typeof w !== 'object' || !Number.isInteger(w.no) || !Array.isArray(w.list)) return null;
  const list = w.list.filter((m) => m && MISSIONS[m.k]).slice(0, WEEK_PICK).map((m) => ({ k: m.k, need: Math.max(1, Math.floor(num(m.need)) || MISSIONS[m.k].need) }));
  if (!list.length) return null;
  const arr = (v) => list.map((_, i) => Math.max(0, num(Array.isArray(v) ? v[i] : 0)));
  const by = {};
  for (const [id, e] of Object.entries(obj(w.by))) {
    if (!e || typeof e !== 'object') continue;
    by[id] = { name: String(e.name || '').slice(0, 20), n: arr(e.n), b: num(e.b), k: num(e.k) };
  }
  const got = {};
  for (const [id, g] of Object.entries(obj(w.got))) got[id] = arr(g).map((x) => (x ? 1 : 0));
  return {
    no: w.no, list, prog: arr(w.prog).map((x, i) => Math.min(x, list[i].need)), at: arr(w.at), by, got,
    kinds: Array.isArray(w.kinds) ? w.kinds.filter((x) => typeof x === 'string').slice(0, 400) : [],
    floors: Array.isArray(w.floors) ? w.floors.filter((x) => typeof x === 'string').slice(0, FLOOR_MAX) : [],
    full: num(w.full), fullCred: obj(w.fullCred),
  };
}

// 世界の 状態（なければ 作る。こわれて いれば なおす）
export function missionState(world) {
  const d = world.data;
  let st = d.missions;
  if (!st || typeof st !== 'object' || st._ok !== world) {
    const src = obj(st);
    const t = obj(src.total);
    const boss = {};
    for (const [sp, n] of Object.entries(obj(t.boss))) if (MONSTERS[sp] && num(n) > 0) boss[sp] = num(n);
    st = {
      week: cleanWeek(src.week),
      prev: cleanWeek(src.prev),
      total: { kills: num(t.kills), wins: num(t.wins), battles: num(t.battles), full: num(t.full), done: num(t.done), weeks: num(t.weeks), boss },
      fullBy: Object.fromEntries(Object.entries(obj(src.fullBy)).filter(([, n]) => num(n) > 0).map(([id, n]) => [id, num(n)])),
      hist: Array.isArray(src.hist) ? src.hist.filter((h) => h && Number.isInteger(h.no)).slice(-HIST_MAX).map((h) => ({ no: h.no, d: num(h.d), n: num(h.n) || WEEK_PICK })) : [],
    };
    // 同じ 世界で 2回 なおさない しるし（セーブには 書かない）
    Object.defineProperty(st, '_ok', { value: world, enumerable: false });
    d.missions = st;
  }
  return st;
}

// 今 遊んで いる 家族（さいきん 4週の 間に 遊んだ キャラ・今 いる キャラ）。いちばん 進んで いない 人でも できる 物を えらぶ ため
function activePool(world, no) {
  const chars = Object.values(world.data.characters || {}).filter((c) => c && !c.species);
  const since = weekStart(no) - ACTIVE_MS;
  const inWorld = new Set([...world.sessions.values()].filter((s) => s.inWorld && s.charId).map((s) => s.charId));
  const pool = chars.filter((c) => inWorld.has(c.id) || num(c.lastPlayed) >= since);
  return pool.length ? pool : chars;
}

function newWeek(no, kinds) {
  return { no, list: kinds.map((k) => ({ k, need: MISSIONS[k].need })), prog: kinds.map(() => 0), at: kinds.map(() => 0), by: {}, got: {}, kinds: [], floors: [], full: 0, fullCred: {} };
}

// 週が かわって いれば 入れかえる（月曜 0:00・日本時間）。今週を かえす
export function ensureWeek(world) {
  const st = missionState(world);
  const cur = weekNo(world.now());
  if (st.week && st.week.no === cur) return st.week;
  const old = st.week;
  if (old && old.no < cur) {
    const d = old.at.filter((x) => x > 0).length;
    if (Object.keys(old.by).length) st.total.weeks++;
    st.hist.push({ no: old.no, d, n: old.list.length });
    if (st.hist.length > HIST_MAX) st.hist.splice(0, st.hist.length - HIST_MAX);
    // 先週は 小さく して のこす（魔物の しゅるい・階の 一覧は いらない）
    st.prev = { ...old, kinds: [], floors: [] };
  }
  // 同じ 物が 2週 続かない ように: 先週（なければ 週の 番号から きまる 先週の 3つ）を さける
  const kinds = openKinds(activePool(world, cur));
  const prevKinds = st.prev && st.prev.no === cur - 1 ? st.prev.list.map((m) => m.k) : pickWeek(cur - 1, kinds);
  st.week = newWeek(cur, pickWeek(cur, kinds, prevKinds));
  world.markDirty?.();
  return st.week;
}

// ───────────── 数える ─────────────
const familyChar = (world, c) => !!c && !c.species && typeof c.id === 'string' && world.data.characters?.[c.id] === c;

// いっしょの 人（家族の キャラ。同じ キャラは 1回）
function uniqueChars(world, list) {
  const out = [];
  for (const c of list) if (familyChar(world, c) && !out.includes(c)) out.push(c);
  return out;
}

// その 人の パーティーで、同じ マップに いる 人間の キャラ（自分も 入れる）
export function togetherOnMap(world, s, map = s?.map) {
  const p = partyOf(world, s);
  if (!p || (p.members || []).length < 2) return [];
  const list = [];
  for (const sid of p.members) {
    const m = world.sessions.get(sid);
    if (!m || !m.inWorld || m.away || m.map !== map) continue;
    list.push(m.char);
  }
  return uniqueChars(world, list);
}

// いっしょに 遊んだ しるし（ごほうびを 受けとれる 人）
function touch(world, w, chars) {
  for (const c of chars) {
    if (!w.by[c.id]) {
      w.by[c.id] = { name: String(c.name || '').slice(0, 20), n: w.list.map(() => 0), b: 0, k: 0 };
      // もう 3つとも 達成した 週に あとから 来た 人も 数える
      if (w.full) creditFull(world, w, c);
    } else w.by[c.id].name = String(c.name || '').slice(0, 20);
  }
}

// kind の ミッションを amount だけ 進める（chars … いっしょに した 家族の キャラ。2人 いじょう）
export function missionBump(world, chars, kind, amount = 1) {
  if (world.offline || !(amount > 0)) return false;
  const list = uniqueChars(world, chars || []);
  if (list.length < 2) return false;
  const w = ensureWeek(world);
  touch(world, w, list);
  let moved = false;
  w.list.forEach((m, i) => {
    if (m.k !== kind || w.at[i]) return;
    const add = Math.min(amount, m.need - w.prog[i]);
    if (add <= 0) return;
    w.prog[i] += add;
    for (const c of list) w.by[c.id].n[i] += add;
    moved = true;
    if (w.prog[i] >= m.need) done(world, w, i);
  });
  if (moved) world.markDirty?.();
  return moved;
}

// 遊んでいる 人みんなに 知らせる（トースト・チャット・家族のけいじ板）
function announce(world, text, chat, key) {
  world.broadcast?.({ t: 'toast', text, sfx: 'bond', afterBattle: true });
  world.broadcast?.({ t: 'chat', from: '家族ミッション', sid: null, text: chat });
  world.boardPost?.({ kind: 'mission', by: '家族', charId: 'family', key, title: chat, detail: 'メニューの「家族ミッション」で、ごほうびを受けとれる。' });
}

function done(world, w, i) {
  w.at[i] = world.now();
  const st = missionState(world);
  st.total.done++;
  const text = missionText(w.list[i].k, w.list[i].need);
  announce(world, `★家族ミッション達成！\n「${text}」\nメニューの「家族ミッション」で、ごほうびを受けとろう`, `「${text}」を達成！`, `m${w.no}_${i}`);
  if (!w.full && w.at.every((x) => x > 0)) {
    w.full = world.now();
    st.total.full++;
    announce(world, '★★★今週の家族ミッションを3つとも達成！\nみんな、おつかれさま！', '今週のミッションを3つとも達成！', `m${w.no}_all`);
    for (const id of Object.keys(w.by)) {
      const c = world.data.characters?.[id];
      if (c) creditFull(world, w, c);
    }
  }
}

// 3つとも 達成した 週を 1つ 足す（キャラごと。しょうごう・スタンプ）
function creditFull(world, w, c) {
  if (w.fullCred[c.id]) return;
  w.fullCred[c.id] = 1;
  const st = missionState(world);
  const n = (st.fullBy[c.id] || 0) + 1;
  st.fullBy[c.id] = n;
  const m = milestoneOf(n);
  if (!m) return;
  const t = Array.isArray(c.famm?.t) ? c.famm.t : [];
  if (t.includes(n)) return;
  // あたらしい しょうごうは すぐ つける（メニューで かえられる）
  c.famm = { t: [...t, n].sort((a, b) => a - b), w: n };
  world.markDirty?.();
  for (const s of world.sessions.values()) {
    if (s.char !== c || !s.inWorld) continue;
    world.send?.(s, { t: 'toast', text: `★${c.name}は、しょうごう「${m.title}」と\nスタンプ「${m.stamp}」を手に入れた！\n（3つとも達成した週：${n}週）`, sfx: 'bond', afterBattle: true });
    world.sendSelf?.(s);
  }
}

// ───── 戦いの 終わり（world/battles.js の finishBattle の はじめ。HP・技の 回数を 書きかえる 前）─────
export function missionBattle(world, ctx, sessions) {
  try {
    countBattle(world, ctx, sessions);
  } catch (e) {
    console.error('mission error', e);
  }
}
function countBattle(world, ctx, sessions) {
  if (world.offline) return;
  const chars = uniqueChars(world, (sessions || []).map((m) => m?.char));
  if (chars.length < 2) return;
  const b = ctx.battle;
  const res = b.result || {};
  const w = ensureWeek(world);
  touch(world, w, chars);
  const st = missionState(world);
  for (const c of chars) w.by[c.id].b++;
  st.total.battles++;
  // 呪文や 技を 使った 回数（この 戦いの ぶん。ふつうの 攻撃は 入れない）
  let uses = 0;
  const sum = (u) => Object.entries(obj(u)).reduce((s, [k, v]) => s + (k.startsWith('@') ? 0 : num(v)), 0);
  for (const a of b.allies || []) {
    const who = ctx.actorMap?.[a.id];
    if (who?.type !== 'human' || !a.use) continue;
    uses += Math.max(0, sum(a.use) - sum(who.char?.skillUse));
  }
  missionBump(world, chars, 'skill', uses);
  missionBump(world, chars, 'dual', num(ctx.mDual));
  if (res.outcome !== 'win') return;
  const killed = Array.isArray(res.killed) ? res.killed : [];
  st.total.wins++;
  st.total.kills += killed.length;
  for (const c of chars) w.by[c.id].k += killed.length;
  missionBump(world, chars, 'win', 1);
  missionBump(world, chars, 'kill', killed.length);
  if (w.list.some((m) => m.k === 'kinds')) {
    const fresh = [...new Set(killed)].filter((sp) => !w.kinds.includes(sp));
    w.kinds.push(...fresh);
    missionBump(world, chars, 'kinds', fresh.length);
  }
  const humans = (b.allies || []).filter((a) => ctx.actorMap?.[a.id]?.type === 'human');
  if (humans.length && humans.every((a) => a.alive)) missionBump(world, chars, 'safe', 1);
  if (killed.length >= 4) missionBump(world, chars, 'big', 1);
  if (ctx.opts?.preemptive === 'ally') missionBump(world, chars, 'first', 1);
  if (b.boss) {
    missionBump(world, chars, 'boss', 1);
    const bosses = (b.enemies || []).filter((e) => e.boss && killed.includes(e.species)).map((e) => e.species);
    for (const sp of new Set(bosses.length ? bosses : killed)) if (MONSTERS[sp]) st.total.boss[sp] = (st.total.boss[sp] || 0) + 1;
  }
  if (String(ctx.opts?.fixed || '').startsWith('tmboss_')) missionBump(world, chars, 'tmap', 1);
  world.markDirty?.();
}

// 戦いの あと 魔物が 仲間に なりたがった（world/battles.js）
export function missionFriend(world, sessions) {
  guard(() => missionBump(world, (sessions || []).map((m) => m?.char), 'friend', 1));
}
// 数える ところで エラーが 出ても、戦い・宝箱・階だんは そのまま つづける
function guard(fn) {
  try {
    return fn();
  } catch (e) {
    console.error('mission error', e);
    return null;
  }
}

// 宝箱を 開けた（ダンジョンの 宝箱・フィールドの 宝箱。world.js）
export function missionChest(world, s) {
  if (world.offline) return;
  guard(() => missionBump(world, togetherOnMap(world, s), 'chest', 1));
}

// 階だん・出入り口で ダンジョンの 階へ 来た（world.js の onEnterTile。ついて来る 人を 動かした あと）
//   同じ 週に 同じ 階は 1回だけ（行ったり 来たりでは ふえない）
export function missionFloor(world, s, mapId) {
  if (!world.offline) guard(() => countFloor(world, s, mapId));
}
function countFloor(world, s, mapId) {
  if (MAPS[mapId]?.kind !== 'dungeon') return;
  const chars = togetherOnMap(world, s, mapId);
  if (chars.length < 2) return;
  const w = ensureWeek(world);
  if (!w.list.some((m) => m.k === 'floor')) {
    touch(world, w, chars);
    return;
  }
  if (w.floors.includes(mapId)) return;
  if (w.floors.length < FLOOR_MAX) w.floors.push(mapId);
  missionBump(world, chars, 'floor', 1);
}

// ───────────── 見る・受けとる ─────────────
function weekRows(w, c) {
  const mine = w.by[c.id];
  const got = w.got[c.id] || [];
  return w.list.map((m, i) => {
    const r = weekReward(i, c.level);
    return {
      k: m.k, text: missionText(m.k, m.need), now: w.prog[i], need: m.need, done: w.at[i] > 0, mine: mine ? mine.n[i] : 0,
      got: !!got[i], reward: { gold: r.gold, items: r.items.map((x) => ({ id: x.id, name: ITEMS[x.id]?.name || x.id, n: x.n })) },
    };
  });
}
const claimable = (w, c) => (w && w.by[c.id] ? w.list.filter((_, i) => w.at[i] > 0 && !(w.got[c.id] || [])[i]).length : 0);

// 画面に おくる 中み（c … 見て いる キャラ）
export function missionView(world, c) {
  if (world.offline) return { offline: true };
  const w = ensureWeek(world);
  const st = missionState(world);
  const now = world.now();
  const prevOk = !!st.prev && st.prev.no === w.no - 1;
  const people = Object.entries(w.by).map(([id, e]) => ({ name: e.name, sum: e.n.reduce((s, x) => s + x, 0), b: e.b, k: e.k, me: id === c.id }))
    .sort((a, b) => b.b - a.b || b.sum - a.sum);
  // いっしょに たおした ボス: 見て いる キャラが もう たおした ボスだけ 名前を 出す
  const bosses = Object.entries(st.total.boss).filter(([sp]) => num(c.kills?.[sp]) > 0)
    .map(([sp, n]) => ({ name: MONSTERS[sp].name, n })).sort((a, b) => b.n - a.n);
  const full = st.fullBy[c.id] || 0;
  const nx = nextMilestone(full);
  return {
    offline: false,
    week: { no: w.no, days: daysLeft(now), list: weekRows(w, c), full: !!w.full, joined: !!w.by[c.id], claim: claimable(w, c) },
    prev: st.prev ? { no: st.prev.no, list: weekRows(st.prev, c), full: !!st.prev.full, joined: !!st.prev.by[c.id], claim: prevOk ? claimable(st.prev, c) : 0, open: prevOk } : null,
    people,
    record: { kills: st.total.kills, wins: st.total.wins, battles: st.total.battles, full: st.total.full, done: st.total.done, weeks: st.total.weeks + (Object.keys(w.by).length ? 1 : 0), bosses, hist: st.hist.slice() },
    me: {
      full, wear: c.famm?.w || 0, title: wornTitle(c),
      titles: earnedOf(c).map((m) => ({ n: m.n, title: m.title, stamp: m.stamp })),
      next: nx ? { n: nx.n, title: nx.title, stamp: nx.stamp, left: nx.n - full } : null,
    },
  };
}

// 受けとる（which … 'cur' 今週 / 'prev' 先週。先週の 分は 次の 週の 間だけ）。{ ok, text }
export function missionClaim(world, c, which = 'cur') {
  if (world.offline) return { ok: false, text: '家族サーバーでいっしょに遊ぶと進みます' };
  const w0 = ensureWeek(world);
  const st = missionState(world);
  const w = which === 'prev' ? (st.prev && st.prev.no === w0.no - 1 ? st.prev : null) : w0;
  if (!w) return { ok: false, text: '先週のごほうびは、もう受けとれない' };
  if (!w.by[c.id]) return { ok: false, text: 'その週に、家族といっしょに遊ぶと受けとれる' };
  const got = w.got[c.id] || w.list.map(() => 0);
  const lines = [];
  let gold = 0;
  w.list.forEach((m, i) => {
    if (!(w.at[i] > 0) || got[i]) return;
    got[i] = 1;
    const r = weekReward(i, c.level);
    gold += r.gold;
    for (const it of r.items) {
      addItem(c, it.id, it.n);
      lines.push(`${ITEMS[it.id]?.name || it.id}×${it.n}`);
    }
  });
  if (!lines.length) return { ok: false, text: '受けとれるごほうびは、ありません' };
  w.got[c.id] = got;
  c.gold = Math.min(9999999, num(c.gold) + gold);
  world.markDirty?.();
  return { ok: true, text: `${c.name}は、ごほうびを受けとった！\n${gold}ゴールド・${lines.join('・')}` };
}

// しょうごうを つける（n … もらった しょうごうの 週。0 で はずす）
export function missionWear(c, n) {
  const list = earnedOf(c);
  if (!list.length) return { ok: false, text: 'しょうごうは、まだありません' };
  const m = list.find((x) => x.n === n);
  if (n && !m) return { ok: false, text: 'そのしょうごうは、まだありません' };
  c.famm = n ? { t: c.famm.t, w: n } : { t: c.famm.t };
  return { ok: true, text: m ? `しょうごう「${m.title}」をつけた` : 'しょうごうをはずした' };
}

// クライアントからの { t: 'mission', action }（world.js の handle）。返事は いつも { t: 'mission', ... }
export function missionMessage(world, s, msg) {
  const c = s.char;
  if (!c) return;
  if (world.offline) return world.send(s, { t: 'mission', offline: true });
  let r = null;
  switch (msg?.action) {
    case 'claim': r = missionClaim(world, c, msg.which === 'prev' ? 'prev' : 'cur'); break;
    case 'wear': r = missionWear(c, Number(msg.n) || 0); world.markDirty(); break;
    default:
  }
  if (r?.ok) world.sendSelf(s);
  world.send(s, { t: 'mission', ...missionView(world, c), ...(r ? { ok: r.ok, text: r.text } : {}) });
}

// チャットの 名前の 横に 出す しょうごう（つけて いる 時だけ）
export const chatName = (c) => {
  const t = wornTitle(c);
  return t ? `${c.name}〈${t}〉` : c.name;
};

export { MILESTONES };

