// 第67回 C: モンスター闘技場の「その場の 対戦」（リアルタイムの 家族対戦）。docs/plan-r67-monster-arena.md
//
// ながれ（窓口は svc kind:'monlive'。client/ui/monarena-live.js が よぶ）:
//   1. 'list' … 今 闘技場（マップ monarena）に いる 家族の 一覧（申しこめるか）
//   2. 'invite' { sid, even } … 申しこむ（even … レベルを そろえる）。相手に { t:'monLive', state:'ask' } が とどく（30びょうで 時間切れ）
//   3. 'answer' { id, ok } … 申しこまれた 人が うける／ことわる。うけると 2人とも 4ひきを 選ぶ（state:'pick'。3分まで）
//   4. 'team' { id, team } … 4ひきを 決めた（'unready' … 選びなおす）。2人とも 決めると state:'go' → 2人とも 受付の 画面を とじたら 戦いが はじまる
//   'cancel' { id } … やめる（どちらからでも。戦いの 前まで）/ 'state' { id } … 今の ようす
//   2人に { t:'monLive', id, role, state, opp, even, me/oppReady, left, text } を とどける（かわった 時と、2.5びょうごと。とぎれても 立てなおせる）
//
// 戦い: 申しこんだ 人（a）の 魔物が みかたの がわ、うけた 人（b）の 魔物が 敵の がわ（shared/battle-monarena.js の MonArenaBattle の foes）。
//   どちらも その 魔物の 作戦で 動く。「めいれいさせろ」の 魔物は もちぬしが コマンドを 選ぶ（オートにも できる）。道具なし・にげられない
//   b の 画面には 敵と みかたを 入れかえた ようす（snapFor・evsFor）を 送る → b の 魔物が 下（みかた）に 出て コマンドを 選べる
//   通信が とぎれた 人の 魔物は オートで 戦う。LIVE_AWAY_MS たっても もどらない・ぬけた 時は のこった 人の 勝ち（記録には のこさない）
//   おわり: 勝ち負けを 2人の c.monArena.live[相手の id] に のこす（はじめて 勝った 時だけ 小さなメダル 1まい）。経験値・お金は なし
import { MonArenaBattle, monFighterChar, monAllyInit, MON_EVEN_LV } from '../battle-monarena.js';
import { normBattleSettings, pub } from '../battle.js';
import { TACTICS } from '../ai.js';
import { MONSTERS } from '../data/monsters.js';
import { MONARENA_OPEN_FLAG, setMonArena, monArenaRecord, noteLiveResult, monLiveMedalId } from '../data/monarena.js';
import { monEntries, pickTeam } from './monarena.js';
import { battleTactics } from './tactics.js';
import { RESULT_MAX_MS } from './battles.js';

export const LIVE_MAP = 'monarena';
export const LIVE_ASK_MS = 30000;
export const LIVE_PICK_MS = 180000;
export const LIVE_GO_MS = 15000;
export const LIVE_AWAY_MS = 20000;
const PUSH_MS = 2500;
let seq = 1;

const evenText = (even) => (even ? 'レベルをそろえる' : 'そのままの強さ');
const store = (world) => world.monLive || (world.monLive = new Map());
export const liveMatchOf = (world, s) => (s?.monLive && store(world).get(s.monLive)) || null;
const sessOf = (world, sid) => {
  const s = world.sessions.get(sid);
  return s && s.inWorld && s.char ? s : null;
};
const roleOf = (m, s) => (m.a === s.id ? 'a' : m.b === s.id ? 'b' : null);
const other = (r) => (r === 'a' ? 'b' : 'a');

// 闘技場の 中に いて、その場の 対戦が できる 人か（away … 通信が とぎれている）
function inArena(world, s, { away = false } = {}) {
  return !!s && world.sessions.get(s.id) === s && s.inWorld && !!s.char && s.map === LIVE_MAP && (away || !s.away) && !s.flying;
}

// 申しこめない わけ（'' … 申しこめる）
function whyNot(world, s) {
  if (!inArena(world, s)) return '闘技場にいない';
  if (!s.char.flags?.[MONARENA_OPEN_FLAG]) return '魔物の仲間がいない';
  if (!monEntries(s.char).length) return '魔物の仲間がいない';
  if (s.monLive) return '対戦の話し中';
  if (s.busy === 'battle' || s.monArenaGo) return '戦っている';
  return '';
}

// ───────────── 2人への 知らせ ─────────────
function pushOne(world, m, r, extra = {}) {
  const s = sessOf(world, m[r]);
  if (!s) return;
  const o = other(r);
  const left = m.state === 'ask' ? LIVE_ASK_MS : m.state === 'pick' ? LIVE_PICK_MS : m.state === 'go' ? LIVE_GO_MS : 0;
  world.send(s, {
    t: 'monLive', id: m.id, role: r, state: m.state, opp: m.names[o], oppSid: m[o], even: m.even, evenLv: MON_EVEN_LV,
    meReady: !!m.team[r], oppReady: !!m.team[o], left: left ? Math.max(0, left - (world.now() - m.stAt)) : 0, ...extra,
  });
}
function pushBoth(world, m, extra = {}) {
  m.pushAt = world.now();
  pushOne(world, m, 'a', extra.a || {});
  pushOne(world, m, 'b', extra.b || {});
}

function setState(world, m, state) {
  m.state = state;
  m.stAt = world.now();
  pushBoth(world, m);
}

// 戦いの 前に おわる（textA・textB … それぞれの 画面の ことば）
function endMatch(world, m, textA, textB) {
  if (m.state === 'end') return;
  m.state = 'end';
  store(world).delete(m.id);
  for (const r of ['a', 'b']) {
    const s = world.sessions.get(m[r]);
    if (s && s.monLive === m.id) s.monLive = null;
  }
  pushBoth(world, m, { a: { text: textA || '' }, b: { text: textB || '' } });
}

function matchInfo(world, m, s) {
  const r = roleOf(m, s);
  if (!r) return null;
  const o = other(r);
  return { id: m.id, role: r, state: m.state, opp: m.names[o], oppSid: m[o], even: m.even, evenLv: MON_EVEN_LV, meReady: !!m.team[r], oppReady: !!m.team[o] };
}

// ───────────── 窓口（world/services.js の kind 'monlive'）─────────────
export function monLiveAction(world, s, msg) {
  const c = s.char;
  // quiet … へんじを 送らない（画面を とじた 時の とりやめ。ほかの 窓口の へんじと まざらない ように）
  const no = (text, extra = {}) => (msg.quiet ? undefined : world.send(s, { t: 'svcRes', ok: false, text, ...extra }));
  const ok = (text, extra = {}) => (msg.quiet ? undefined : world.send(s, { t: 'svcRes', ok: true, text, ...extra }));
  const m = liveMatchOf(world, s);
  const mine = m && (!msg.id || msg.id === m.id) ? m : null;
  switch (msg.op) {
    case 'list': {
      const people = [];
      for (const x of world.sessions.values()) {
        if (x === s || !x.inWorld || !x.char || x.map !== LIVE_MAP || x.charId === s.charId) continue;
        const why = whyNot(world, x);
        people.push({ sid: x.id, charId: x.charId, name: x.char.name, level: x.char.level || 1, mons: monEntries(x.char).length, can: !why, why, look: x.char.look, job: x.char.job });
      }
      people.sort((p, q) => Number(q.can) - Number(p.can) || String(p.name).localeCompare(String(q.name)));
      return ok('', { people, me: m ? matchInfo(world, m, s) : null, evenLv: MON_EVEN_LV, rec: monArenaRecord(c).live });
    }
    case 'state':
      return ok('', { me: m ? matchInfo(world, m, s) : null });
    case 'invite': {
      if (m) return no('今は、ほかの対戦の話をしているところだよ');
      const mw = whyNot(world, s);
      if (mw) return no(mw === '闘技場にいない' ? '闘技場の中で申しこんでね' : mw === '魔物の仲間がいない' ? 'まだ戦える魔物がいないみたい' : '今は申しこめないよ');
      const t = world.sessions.get(String(msg.sid || ''));
      if (!t || t === s || t.charId === s.charId) return no('その人には申しこめないよ');
      const why = whyNot(world, t);
      if (why) {
        const name = t.char?.name || '家族';
        return no(why === '闘技場にいない' ? `${name}は、今は闘技場にいないみたい` : why === '魔物の仲間がいない' ? `${name}には、まだ戦える魔物がいないみたい` : why === '戦っている' ? `${name}は、今戦っているところだよ` : `${name}は、今ほかの対戦の話をしているところだよ`);
      }
      const id = 'ml' + (seq++) + Math.floor(world.rng.next() * 1e6).toString(36);
      const nm = {
        id, a: s.id, b: t.id, aId: s.charId, bId: t.charId, names: { a: c.name, b: t.char.name }, even: !!msg.even,
        state: 'ask', at: world.now(), stAt: world.now(), pushAt: 0, team: { a: null, b: null },
      };
      store(world).set(id, nm);
      s.monLive = id;
      t.monLive = id;
      ok(`${t.char.name}に申しこんだよ`, { me: matchInfo(world, nm, s) });
      pushBoth(world, nm);
      return;
    }
    case 'cancel': {
      if (!mine) return ok('', { me: null });
      const r = roleOf(mine, s);
      if (mine.state === 'battle') return no('もう戦いが始まっているよ');
      const me = mine.names[r];
      const t = mine.state === 'ask' ? `${me}が、申しこみをやめたよ` : `${me}が、対戦をやめたよ`;
      endMatch(world, mine, r === 'a' ? '' : t, r === 'b' ? '' : t);
      return ok('対戦をやめたよ', { me: null });
    }
    case 'answer': {
      if (!mine || mine.state !== 'ask' || roleOf(mine, s) !== 'b') return no('その申しこみは、もう終わっているみたい', { me: null });
      if (!msg.ok) {
        endMatch(world, mine, `${mine.names.b}は、今は対戦できないみたい`, '');
        return ok('ことわったよ', { me: null });
      }
      if (!inArena(world, s)) return no('闘技場の中で受けてね');
      const a = sessOf(world, mine.a);
      if (!inArena(world, a)) {
        endMatch(world, mine, '', `${mine.names.a}は、もう闘技場にいないみたい`);
        return no(`${mine.names.a}は、もう闘技場にいないみたい`, { me: null });
      }
      setState(world, mine, 'pick');
      return ok('対戦を受けたよ！', { me: matchInfo(world, mine, s) });
    }
    case 'team': {
      if (!mine || (mine.state !== 'pick' && mine.state !== 'go')) return no('その対戦は、もう終わっているみたい', { me: null });
      if (mine.state === 'go') return ok('', { me: matchInfo(world, mine, s), go: true });
      const t = pickTeam(c, msg.team);
      if (!t.ok) return no(t.reason, { me: matchInfo(world, mine, s) });
      const r = roleOf(mine, s);
      mine.team[r] = t.keys;
      // 前回の チームとして おぼえる（ランク戦と おなじ）
      setMonArena(c, { team: t.keys });
      world.markDirty();
      if (mine.team.a && mine.team.b) {
        setState(world, mine, 'go');
        return ok('', { me: matchInfo(world, mine, s), go: true });
      }
      pushBoth(world, mine);
      return ok('', { me: matchInfo(world, mine, s) });
    }
    case 'unready': {
      if (!mine || mine.state !== 'pick') return ok('', { me: mine ? matchInfo(world, mine, s) : null });
      mine.team[roleOf(mine, s)] = null;
      pushBoth(world, mine);
      return ok('', { me: matchInfo(world, mine, s) });
    }
    default: return no('できません');
  }
}

// ───────────── まいフレーム（world.js の tick から）─────────────
export function tickMonLive(world) {
  const st = world.monLive;
  if (!st || !st.size) return;
  const now = world.now();
  for (const m of [...st.values()]) {
    if (m.state === 'battle' || m.state === 'end') continue;
    const sa = world.sessions.get(m.a), sb = world.sessions.get(m.b);
    const gone = (s) => !s || s.monLive !== m.id || !inArena(world, s, { away: true }) || (s.away && now - s.awayAt > LIVE_AWAY_MS) || s.busy === 'battle';
    const ga = gone(sa), gb = gone(sb);
    if (ga || gb) {
      const left = (r) => `${m.names[r]}は、闘技場をはなれたみたい…`;
      endMatch(world, m, gb ? left('b') : '', ga ? left('a') : '');
      continue;
    }
    const age = now - m.stAt;
    if (m.state === 'ask' && age > LIVE_ASK_MS) {
      endMatch(world, m, `${m.names.b}から、へんじがなかったみたい`, `${m.names.a}からの申しこみは、時間切れになったよ`);
      continue;
    }
    if (m.state === 'pick' && age > LIVE_PICK_MS) {
      const t = 'チームを選ぶ時間が、終わってしまった…';
      endMatch(world, m, t, t);
      continue;
    }
    if (m.state === 'go') {
      // 2人とも 受付の 画面（だいほん）が おわったら はじめる
      if (!sa.busy && !sb.busy && !sa.away && !sb.away && !sa.monArenaGo && !sb.monArenaGo) {
        startLive(world, m, sa, sb);
        continue;
      }
      if (age > LIVE_GO_MS) {
        const t = '戦いのじゅんびが、うまくいかなかった…';
        endMatch(world, m, t, t);
        continue;
      }
    }
    if (now - m.pushAt >= PUSH_MS) pushBoth(world, m);
  }
}

// ───────────── 戦い ─────────────
// 敵の がわ（b）を 人が うごかす 時の ウェイト: どちらかが コマンドを えらんでいる 間は 止まる
class MonLiveBattle extends MonArenaBattle {
  humans() {
    return this.combatants.filter((c) => !c.fled && c.controller && !c.auto);
  }
}

const FLIP = { ally: 'enemy', enemy: 'ally' };
// pub の うち みかたの がわだけに 入る 項目（battle.js の pub）
const ALLY_KEYS = ['slv', 'acc', 'accUsed', 'gearUses', 'abilities', 'weaponCat', 'pc', 'pow', 'favs', 'tactics', 'tacBy'];

// b の 画面の 名前: 自分の 魔物は そのままの 名前・a の 魔物に 同じ 名前が あれば A・B を つける
//   （戦いの 中の 名前は a から 見た もの。MonArenaBattle は 敵の がわ〈b〉に A・B を つける）
function liveNames(b) {
  const plain = new Map(b.enemies.map((e) => [e.id, e.livePlain || e.name]));
  const own = new Set(plain.values());
  const count = {};
  for (const a of b.allies) count[a.name] = (count[a.name] || 0) + 1;
  const seen = {};
  const map = {};
  for (const e of b.enemies) if (plain.get(e.id) !== e.name) map[e.name] = plain.get(e.id);
  for (const a of b.allies) {
    if (!own.has(a.name) && count[a.name] < 2) continue;
    const i = seen[a.name] = (seen[a.name] ?? -1) + 1;
    map[a.name] = a.name + 'ABCDEFGH'[i % 8];
  }
  const keys = Object.keys(map).sort((x, y) => y.length - x.length);
  const re = keys.length ? new RegExp(keys.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g') : null;
  return { map, re };
}
const renameText = (b, t) => (b.liveNames?.re && typeof t === 'string' ? t.replace(b.liveNames.re, (k) => b.liveNames.map[k] ?? k) : t);

// b の 画面の 1人（敵と みかたを 入れかえる）。p … その 時の pub（なければ 今の すがた）
function mirrorPub(b, p) {
  const c = b.get(p.id);
  const out = { ...p, side: FLIP[p.side] || p.side };
  if (b.liveNames?.map[out.name] !== undefined) out.name = b.liveNames.map[out.name];
  if (!c) return out;
  if (out.side === 'ally') {
    // b の 魔物: みかたの 項目（技・作戦 など）を 足す。ふつうの 魔物の 仲間と おなじく species は なし
    const full = pub({ ...c, side: 'ally' });
    for (const k of ALLY_KEYS) out[k] = full[k];
    delete out.species;
  } else {
    for (const k of ALLY_KEYS) delete out[k];
    out.species = c.mon || c.liveSp;
    out.size = MONSTERS[c.mon]?.size || MONSTERS[c.liveSp]?.size;
    out.boss = false;
  }
  return out;
}

// text … 名前を 入れかえる 文（lines・postLines など）の 中
function mirrorAny(b, x, text = false) {
  if (Array.isArray(x)) return x.map((v) => mirrorAny(b, v, text));
  if (typeof x === 'string') return text ? renameText(b, x) : x;
  if (!x || typeof x !== 'object') return x;
  if (typeof x.id === 'string' && FLIP[x.side] && 'maxHp' in x) return mirrorPub(b, x);
  const out = {};
  for (const [k, v] of Object.entries(x)) out[k] = mirrorAny(b, v, /lines$|^text$/i.test(k));
  if (FLIP[out.side]) out.side = FLIP[out.side];
  return out;
}

const FLIP_OUT = { win: 'lose', lose: 'win' };
export function mirrorEvents(b, evs) {
  return evs.map((ev) => {
    const out = mirrorAny(b, ev);
    if (ev.t === 'end' && FLIP_OUT[ev.outcome]) out.outcome = FLIP_OUT[ev.outcome];
    return out;
  });
}

export function mirrorSnapshot(b) {
  const snap = b.snapshot();
  snap.combatants = b.combatants.filter((c) => !c.fled).map((c) => mirrorPub(b, pub(c)));
  return snap;
}

function makeLive(world, m, sa, sb) {
  const ta = pickTeam(sa.char, m.team.a), tb = pickTeam(sb.char, m.team.b);
  if (!ta.ok || !tb.ok) return null;
  const lv = m.even ? MON_EVEN_LV : null;
  const setA = sa.char.battleSettings || {}, setB = sb.char.battleSettings || {};
  const na = normBattleSettings(setA), nb = normBattleSettings(setB);
  const fa = ta.entries.map((e) => ({ key: e.key, real: e.char, ch: monFighterChar(e.char, { level: lv }) }));
  const fb = tb.entries.map((e) => ({ key: e.key, real: e.char, ch: monFighterChar(e.char, { level: lv }) }));
  const b = new MonLiveBattle({
    id: 'ml' + (seq++),
    rng: world.rng,
    allies: fa.map((f) => monAllyInit(f.ch, { controller: sa.id, auto: !!setA.auto, owner: sa.charId })),
    foes: fb.map((f) => ({ char: f.ch, controller: f.ch.tactics === 'manual' ? sb.id : null, auto: !!setB.auto, owner: sb.charId })),
    enemies: [],
    // 速さは おそい ほうに・ウェイトは どちらかが ウェイトなら（小さい 子に あわせる）
    speed: Math.min(na.speed, nb.speed),
    textSpeed: Math.min(na.textSpeed, nb.textSpeed),
    wait: !!setA.wait || !!setB.wait,
    canFlee: false,
    bg: 'arena',
    bgm: 'boss',
    hooks: { hasItem: () => false, consumeItem: () => false, spendGold: () => 0, gainGold: () => 0, steal: () => null },
  });
  const actorMap = {};
  b.allies.forEach((a, i) => {
    a.liveSp = fa[i].ch.species;
    actorMap[a.id] = { type: 'support', key: fa[i].key, owner: sa.charId, kind: 'monster', char: fa[i].ch, manual: fa[i].ch.tactics === 'manual', real: fa[i].real, side: 'a' };
  });
  b.enemies.forEach((e, i) => {
    e.liveSp = fb[i].ch.species;
    e.livePlain = fb[i].ch.name;
    // 「めいれいさせろ」の しるし（b の 画面の 作戦の 名前）
    e.manualTac = fb[i].ch.tactics === 'manual';
    actorMap[e.id] = { type: 'support', key: fb[i].key, owner: sb.charId, kind: 'monster', char: fb[i].ch, manual: e.manualTac, real: fb[i].real, side: 'b' };
  });
  b.liveNames = liveNames(b);
  b.emit({ t: 'msg', lines: [`${m.names.a}と${m.names.b}の対戦、始め！`, ...(m.even ? [`みんなレベル${MON_EVEN_LV}にそろえて戦うぞ！`] : [])], dur: 1400 });
  const ctx = {
    id: b.id, battle: b, sids: [sa.id, sb.id], partyId: sa.partyId, map: sa.map, actorMap, live: m,
    opts: { fixed: 'monarena', solo: true, monarena: 'live', loseOk: true, boss: false, canFlee: false },
    finish: finishLive,
    // b の 画面は 敵と みかたを 入れかえる（battles.js の battleTick・mineOf、world.js の つなぎ直し）
    evsFor: (sid, evs) => (sid === m.b ? mirrorEvents(b, evs) : evs),
    snapFor: (sid) => (sid === m.b ? mirrorSnapshot(b) : b.snapshot()),
    mineFor: (sid) => b.combatants.filter((c) => !c.fled && c.controller === sid).map((c) => c.id),
    tactics: liveTactics,
    awayAuto: new Set(),
  };
  // まいフレーム: とぎれた 人の 魔物は オート・もどらない 人が いれば おわり
  const tick = b.tick.bind(b);
  b.tick = (dt) => {
    if (!b.over) liveWatch(world, ctx);
    return tick(dt);
  };
  return ctx;
}

function startLive(world, m, sa, sb) {
  const ctx = makeLive(world, m, sa, sb);
  if (!ctx) {
    const t = '選んだ魔物が、そろわなかった…';
    endMatch(world, m, t, t);
    return;
  }
  m.state = 'battle';
  m.battleId = ctx.id;
  world.battles.set(ctx.id, ctx);
  pushBoth(world, m);
  for (const s of [sa, sb]) {
    s.busy = 'battle';
    s.battleId = ctx.id;
    s.moving = false;
    world.send(s, { t: 'battleStart', snap: ctx.snapFor(s.id), mine: ctx.mineFor(s.id), boss: false, story: true, live: true });
  }
  world.broadcastPositions = true;
}

// 通信が とぎれた 人・ぬけた 人
function liveWatch(world, ctx) {
  const m = ctx.live;
  const b = ctx.battle;
  const now = world.now();
  const gone = {};
  for (const r of ['a', 'b']) {
    const s = world.sessions.get(m[r]);
    const out = !s || !s.inWorld || s.battleId !== ctx.id || (s.away && now - s.awayAt > LIVE_AWAY_MS);
    gone[r] = out;
    if (out || !s) continue;
    for (const c of b.combatants) {
      if (c.controller !== s.id || c.fled) continue;
      if (s.away && !c.auto) {
        b.setAuto(c.id, true);
        ctx.awayAuto.add(c.id);
      } else if (!s.away && ctx.awayAuto.has(c.id)) {
        ctx.awayAuto.delete(c.id);
        b.setAuto(c.id, !!s.char.battleSettings?.auto);
      }
    }
  }
  if (gone.a || gone.b) {
    const winner = gone.a && gone.b ? null : gone.a ? 'b' : 'a';
    ctx.forced = { winner };
    b.endBattle({ outcome: winner === 'a' ? 'win' : winner === 'b' ? 'lose' : 'flee' });
  }
}

// 戦いの 中で 作戦を かえる（battles.js の battleCommand から）。みかたの がわは ふつうと おなじ（world/tactics.js）
function liveTactics(world, s, ctx, msg) {
  const b = ctx.battle;
  const a = b.get(String(msg.actor || ''));
  if (!a || a.side === 'ally') return battleTactics(world, s, ctx, msg);
  const no = (text) => {
    world.send(s, { t: 'menuRes', ok: false, text });
    return { ok: false, reason: text };
  };
  const t = TACTICS[msg.tactics] ? String(msg.tactics) : null;
  const who = ctx.actorMap[a.id];
  if (!t || a.fled || !who || b.over) return no('作戦は変えられない');
  if (who.owner !== s.char.id) return no(`${a.name}の作戦は変えられない`);
  if (who.real) who.real.tactics = t;
  if (who.char) who.char.tactics = t;
  who.manual = t === 'manual';
  a.tactics = t === 'manual' ? 'balanced' : t;
  a.manualTac = t === 'manual';
  if (t === 'manual' && !a.controller) {
    a.controller = s.id;
    a.auto = !!s.char.battleSettings?.auto;
  } else if (t !== 'manual' && a.controller === s.id) {
    a.controller = null;
    b.setAuto(a.id, true);
  }
  b.emit({ t: 'tactics', id: a.id, tactics: t, controller: a.controller || null, auto: !!a.auto });
  world.send(s, { t: 'menuRes', ok: true, text: `${a.name}の作戦を「${TACTICS[t].name}」にした。` });
  world.sendSelf(s);
  world.markDirty();
  return { ok: true };
}

// 戦いの おわり（battles.js の battleTick・abortBattle が ctx.finish を よぶ）
export function finishLive(world, ctx) {
  world.battles.delete(ctx.id);
  const b = ctx.battle;
  const m = ctx.live;
  const outcome = b.result?.outcome || 'flee';
  const winner = ctx.forced ? ctx.forced.winner : outcome === 'win' ? 'a' : outcome === 'lose' ? 'b' : null;
  const chars = { a: world.data.characters[m.aId], b: world.data.characters[m.bId] };
  const lines = { a: [], b: [] };
  if (ctx.forced) {
    for (const r of ['a', 'b']) {
      if (winner !== r) continue;
      lines[r].push(`${m.names[other(r)]}の通信がとぎれてしまった…`, `この対戦は、${m.names[r]}の勝ち！`, '（この対戦は、記録にはのこらないよ）');
    }
  } else if (winner) {
    for (const r of ['a', 'b']) {
      const o = other(r);
      const c = chars[r];
      const win = winner === r;
      lines[r].push(win ? `${m.names[o]}の魔物たちに勝った！` : `${m.names[o]}の魔物たちに負けてしまった…`, win ? `勝者、${m.names[r]}の魔物たち！` : 'いい勝負だったね！');
      if (!c) continue;
      const first = noteLiveResult(c, m[o + 'Id'], win);
      if (first) {
        c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
        if (!c.medalSpots[monLiveMedalId(m[o + 'Id'])]) {
          c.medalSpots[monLiveMedalId(m[o + 'Id'])] = world.now();
          lines[r].push(`初めて${m.names[o]}にその場の対戦で勝った！`, `${m.names[r]}は小さなメダルを1枚手に入れた！`);
        }
      }
      const rec = monArenaRecord(c).live[m[o + 'Id']] || { w: 0, l: 0 };
      lines[r].push(`（${m.names[o]}とのその場の対戦：${rec.w}勝${rec.l}敗）`);
    }
  } else {
    lines.a.push('戦いが止まってしまった…');
    lines.b.push('戦いが止まってしまった…');
  }
  // 作戦（戦いの 中で かえた もの）は もとの 仲間に のこっている（liveTactics・tactics.js）
  m.state = 'end';
  store(world).delete(m.id);
  for (const r of ['a', 'b']) {
    const s = world.sessions.get(m[r]);
    if (!s) continue;
    if (s.monLive === m.id) s.monLive = null;
    if (s.battleId !== ctx.id) continue;
    const out = winner === r ? 'win' : winner ? 'lose' : 'flee';
    s.busy = null;
    s.battleId = null;
    s.reading = lines[r].length > 0;
    s.invuln = s.reading ? RESULT_MAX_MS : 3000;
    world.send(s, { t: 'battleEnd', id: ctx.id, outcome: out, lines: lines[r], levelUp: false, story: true, live: true });
    world.sendSelf(s);
  }
  world.markDirty();
}

js/shared/world/monarena.js:
// 第67回 B: モンスター闘技場（サーバーの 窓口・ランク戦の 3連戦・家族の 登録チームとの 対戦）。docs/plan-r67-monster-arena.md
//
// 窓口: world/services.js の serviceAction から（msg.kind 'monarena'）。A班の 画面が よぶ
//   'status' → { ok, ranks, team, reg, monsters, family }（名前の 約束は plan の とおり。ほかの 項目は おまけ）
//   'setTeam' { team } … 前回の チームとして おぼえる / 'register' { team } … 登録チーム（写しも のこす。もちぬしが 遊んで いなくても 戦える）
//   'rank' { rank, team } … ランク戦（3連戦）/ 'family' { charId, team, even } … 家族の 登録チームと 戦う（even … みんな MON_EVEN_LV に そろえる）
//   'rank'・'family' は へんじ（ok）の あとで 戦いを はじめる。だいほんの 画面（'ui' の 段）の 中から よんだ ときは、
//   その 画面を とじた（ack が とどいた）あとに 3連戦の だいほんを はさみ、おわったら もとの だいほんの つづきへ。だいほんの 外なら すぐ はじめる
//   （A班の 画面は 受付の だいほんが おわってから 送る。おわりかけ〈まって いない〉の 時は おわるのを 少し まつ）
//
// 戦い: 人は 戦わない（shared/battle-monarena.js の MonArenaBattle）。魔物は 写し（monFighterChar）で 戦う
//   ・ランク戦 … 戦いの 前に HP・MPは 満タン（写し）。3連戦の 間は 回復しない。勝つと 1戦ごとに 魔物たちが 少し 経験値（MON_EXP_RATE）
//   ・家族の 対戦 … 両方 満タン。経験値・お金は なし（記録だけ）
//   ・負けても お金は へらない・ゲームオーバーに ならない（もとの 仲間の HP は へらない）
//   ・おわりは battles.js の battleTick が ctx.finish（finishMon）を よぶ
import { MonArenaBattle, monFighterChar, monAllyInit, monSnapshot, snapChar, monStatRow, monRankFight, MON_EVEN_LV } from '../battle-monarena.js';
import { normBattleSettings } from '../battle.js';
import {
  MONARENA_RANKS, MONARENA_TEAM_MAX, MONARENA_OPEN_FLAG, MON_EXP_RATE, monRankInfo, monRankLabel, monRankOpen, monRankCleared, monChampOf, monChampName,
  monArenaRecord, setMonArena, noteMonClear, noteFamResult, monFirstMedalId, monFamMedalId, nextMonRepeatMedal,
} from '../data/monarena.js';
import { scaledRewardBonus } from '../data/treasure.js';
import { MONSTERS } from '../data/monsters.js';
import { ITEMS } from '../data/items.js';
import { addItem, itemCount, removeItem } from '../stats.js';
import { rewardExp, scaleExp, difficultyOf } from '../data/difficulty.js';
import { ensureCompanions, ensureStorage, growCompanion, noteSeen } from './party.js';
import { growthSummary } from './growth.js';
import { mineOf, RESULT_MAX_MS } from './battles.js';
import { runSteps } from './scripts.js';

const say = (who, text) => ['say', who, text];
export const MONARENA_CALLER = '闘技場の司会';
export const MONARENA_CLERK = '闘技場の受付';
const fmt = (n) => Number(n).toLocaleString('ja-JP');
let monSeq = 1;

// ───────────── 魔物の 一覧・チーム ─────────────
// 自分の 魔物（仲間の 魔物 ＋ あずかり中）。where: 'party'（いっしょ）・'wagon'（馬車）・'tavern'（酒場で 待つ）・'storage'（あずかり所）
export function monEntries(c) {
  ensureStorage(ensureCompanions(c));
  const party = new Set(c.partyKeys || []);
  const wagon = new Set(Array.isArray(c.wagonKeys) ? c.wagonKeys : []);
  const out = [];
  for (const e of c.companions) {
    if (e.kind !== 'monster' || !e.char?.species || !MONSTERS[e.char.species]) continue;
    out.push({ e, where: party.has(e.key) ? 'party' : wagon.has(e.key) ? 'wagon' : 'tavern' });
  }
  for (const e of c.storage) if (e.char?.species && MONSTERS[e.char.species]) out.push({ e, where: 'storage' });
  return out;
}

// えらんだ key を たしかめる（1〜4ひき・自分の 魔物・同じ 魔物は 1回）
export function pickTeam(c, keys) {
  if (!Array.isArray(keys) || !keys.length) return { ok: false, reason: '戦う魔物を選んでね' };
  if (keys.length > MONARENA_TEAM_MAX) return { ok: false, reason: `戦えるのは${MONARENA_TEAM_MAX}ひきまでだよ` };
  const list = keys.map((k) => String(k ?? ''));
  if (new Set(list).size !== list.length) return { ok: false, reason: '同じ魔物は2回選べないよ' };
  const mine = new Map(monEntries(c).map((x) => [x.e.key, x]));
  const entries = [];
  for (const k of list) {
    const x = mine.get(k);
    if (!x) return { ok: false, reason: 'その魔物は選べないよ' };
    entries.push(x.e);
  }
  return { ok: true, entries, keys: list };
}

// 登録チームの 写しを 今の すがたに（いなく なった 魔物は 前の 写しの まま のこす。reg の key も のこす）
export function refreshRegSnap(c) {
  const a = monArenaRecord(c);
  if (!a.reg.length && !a.regSnap.length) return false;
  const mine = new Map(monEntries(c).map((x) => [x.e.key, x.e]));
  const keys = a.reg.length ? a.reg : a.regSnap.map((x) => x.key);
  const snap = keys.map((k) => (mine.has(k) ? monSnapshot(mine.get(k)) : a.regSnap.find((x) => x.key === k) || null)).filter(Boolean);
  setMonArena(c, { regSnap: snap });
  return true;
}

// ───────────── 窓口の じょうほう ─────────────
export function monArenaStatus(world, s) {
  const c = s.char;
  const flag = (f) => !!c.flags?.[f];
  refreshRegSnap(c);
  const rec = monArenaRecord(c);
  const ranks = MONARENA_RANKS.map((R, i) => {
    const o = monRankOpen(R.rank, flag, c);
    const lock = o.ok ? '' : o.why === 'prev' ? `${monRankLabel(MONARENA_RANKS[i - 1].rank)}を勝ちぬくと、出られる` : R.lock || '（物語を進めると、開く）';
    return {
      rank: R.rank, name: R.title, open: o.ok, cleared: monRankCleared(c, R.rank), lv: R.lv, hint: R.hint,
      // おまけ: 王者の 魔物・伝説の部・出られない わけ・勝ちぬいた 回数
      champ: monChampName(R), champSp: monChampOf(R), legend: !!R.legend, lock, why: o.ok ? null : o.why, n: rec.r[R.rank]?.n || 0,
    };
  });
  const entries = monEntries(c);
  const has = new Set(entries.map((x) => x.e.key));
  const monsters = entries.map(({ e, where }) => ({
    key: e.key, name: e.char.name, species: e.char.species, level: e.char.level || 1, ...monStatRow(e.char), where,
    color: e.char.color || undefined, plus: e.char.plus || 0, tactics: e.char.tactics || 'balanced',
  }));
  const me = s.charId || c.id;
  const family = [];
  for (const [id, ch] of Object.entries(world.data.characters || {})) {
    if (!ch || id === me || ch.species) continue;
    const r = monArenaRecord(ch);
    if (!r.regSnap.length) continue;
    family.push({
      charId: id, name: ch.name, reg: r.regSnap.map((x) => ({ species: x.species, name: x.name, level: x.level, color: x.color || undefined })),
      rec: rec.fam[id] ? { w: rec.fam[id].w, l: rec.fam[id].l } : { w: 0, l: 0 }, at: r.regAt || 0,
    });
  }
  return {
    open: flag(MONARENA_OPEN_FLAG), ranks,
    team: rec.team.filter((k) => has.has(k)), reg: rec.reg.filter((k) => has.has(k)),
    monsters, family, evenLv: MON_EVEN_LV, teamMax: MONARENA_TEAM_MAX,
  };
}

// ───────────── 窓口（world/services.js から）─────────────
export function monArenaAction(world, s, msg, reply) {
  const c = s.char;
  const st = () => monArenaStatus(world, s);
  const no = (text) => reply(false, text, st());
  switch (msg.action) {
    case 'status': return reply(true, '', st());
    case 'setTeam': {
      const t = pickTeam(c, msg.team);
      if (!t.ok) return no(t.reason);
      setMonArena(c, { team: t.keys });
      return reply(true, 'チームを覚えたよ', st());
    }
    case 'register': {
      const t = pickTeam(c, msg.team);
      if (!t.ok) return no(t.reason);
      setMonArena(c, { reg: t.keys, regSnap: t.entries.map(monSnapshot).filter(Boolean), regAt: world.now() });
      return reply(true, '登録チームにしたよ！\n家族がいつでも、このチームと戦えるようになった', st());
    }
    case 'rank': {
      if (!c.flags?.[MONARENA_OPEN_FLAG]) return no('まだ魔物が仲間になっていないみたい');
      const R = monRankInfo(String(msg.rank || ''));
      if (!R) return no('そのランクはないよ');
      const o = monRankOpen(R.rank, (f) => !!c.flags?.[f], c);
      if (!o.ok) return no(o.why === 'prev' ? 'まず、1つ前のランクを勝ちぬこう' : 'そのランクは、まだ開いていない');
      const t = pickTeam(c, msg.team);
      if (!t.ok) return no(t.reason);
      if (!canStart(world, s)) return no('今は戦えないよ');
      setMonArena(c, { team: t.keys });
      reply(true, `${monRankLabel(R.rank)}にちょうせん！`, st());
      startMonRun(world, s, (run) => rankRun(run, s, R, t.keys));
      return;
    }
    case 'family': {
      const id = String(msg.charId || '');
      const opp = world.data.characters?.[id];
      if (!opp || opp.species || id === (s.charId || c.id)) return no('その家族とは戦えないよ');
      if (!monArenaRecord(opp).regSnap.length) return no(`${opp.name}は、まだチームを登録していないよ`);
      const t = pickTeam(c, msg.team);
      if (!t.ok) return no(t.reason);
      if (!canStart(world, s)) return no('今は戦えないよ');
      setMonArena(c, { team: t.keys });
      reply(true, `${opp.name}のチームと対戦！`, st());
      startMonRun(world, s, (run) => familyRun(run, s, id, t.keys, !!msg.even));
      return;
    }
    default: return no('できません');
  }
}

function canStart(world, s) {
  if (!s.inWorld || s.busy === 'battle' || s.monArenaGo) return false;
  if (s.busy === 'script') {
    const run = s.runId && world.runs.get(s.runId);
    return !!run && run.init === s;
  }
  return !s.busy;
}

// 3連戦などの だいほんを はじめる（上の せつめい）
export function startMonRun(world, s, fn) {
  const go = async (run) => {
    try {
      await fn(run);
    } catch (e) {
      if (!run.aborted) console.error('monarena error', e);
    } finally {
      s.monArenaGo = false;
    }
  };
  s.monArenaGo = true;
  const run = s.runId && world.runs.get(s.runId);
  if (run && run.init === s && run.waiting) {
    const w = run.waiting;
    const orig = w.resolve;
    w.resolve = (msg) => {
      if (msg?.aborted) {
        s.monArenaGo = false;
        return orig(msg);
      }
      go(run).then(() => orig(msg));
    };
    return true;
  }
  if (s.busy === 'script' && run && run.init === s) {
    // 受付の だいほんが おわる ところ（画面を とじた へんじの すぐ あと）: おわるのを 少し まつ
    (async () => {
      for (let i = 0; i < 60 && s.busy && world.sessions.get(s.id) === s; i++) await new Promise((ok) => setTimeout(ok, 50));
      if (s.busy || world.sessions.get(s.id) !== s) {
        s.monArenaGo = false;
        return;
      }
      runSteps(world, s, [['call', go]]);
    })();
    return true;
  }
  if (s.busy) {
    s.monArenaGo = false;
    return false;
  }
  runSteps(world, s, [['call', go]]);
  return true;
}

async function flushOk(run) {
  const r = await run.flush();
  if (r.aborted) {
    run.abort();
    return false;
  }
  return true;
}

// ───────────── ランク戦 ─────────────
export async function rankRun(run, s, R, keys) {
  const w = run.world;
  const c = s.char;
  const t = pickTeam(c, keys);
  if (!t.ok) {
    run.batch.push(say(MONARENA_CLERK, t.reason));
    await flushOk(run);
    return 'none';
  }
  // 戦いの 前に 闘技場が HP・MPを 満タンに（写し。3連戦の 間は 回復しない）
  const fighters = t.entries.map((e) => ({ key: e.key, real: e.char, ch: monFighterChar(e.char) }));
  run.batch.push(
    say(MONARENA_CALLER, `さあ、${monRankLabel(R.rank)}「${R.title}」のちょうせん者、\n${c.name}の魔物たちの入場だ！`),
    say(null, '（受付の人が、魔物たちのHPとMPを満タンにしてくれた）'),
    ['sfx', 'encounter'],
  );
  for (let i = 0; i < 3; i++) {
    if (i < 2) run.batch.push(say(MONARENA_CALLER, i === 0 ? '第1戦、始め！' : '第2戦！休むひまはないぞ！'));
    else {
      run.batch.push(say(MONARENA_CALLER, `いよいよ第3戦！\n${monRankLabel(R.rank)}の王者、${monChampName(R)}の登場だ！`));
      run.batch.push(['showMon', monChampOf(R)]);
    }
    if (!(await flushOk(run))) return 'abort';
    const res = await startMonBattle(w, s, { kind: 'rank', rank: R, fight: i, fighters });
    if (i === 2) run.batch.push(['showMon', null]);
    if (res !== 'win') {
      run.batch.push(...(res === 'lose'
        ? [
          say(MONARENA_CLERK, `おつかれさん！\n${monRankLabel(R.rank)}は、第${i + 1}戦で力つきてしまったな。`),
          say(null, '受付の人が、魔物たちの手当てをしてくれた。\n（お金はへっていない）'),
          say(MONARENA_CLERK, `${R.hint}\nまたちょうせんしな！`),
        ]
        : [say(MONARENA_CLERK, '戦いが止まったようだ…。\nまたちょうせんしな！')]));
      await flushOk(run);
      refreshRegSnap(c);
      return res;
    }
    if (i < 2) run.batch.push(say(null, `第${i + 1}戦に勝った！\n（HPとMPは、回復しないまま…次の戦いへ！）`));
  }
  run.batch.push(['sfx', 'win'], say(MONARENA_CALLER, `勝者、${c.name}の魔物たち！\n${monRankLabel(R.rank)}、勝ちぬきだ！！`));
  run.batch.push(...monClearRewards(w, s, R));
  run.batch.push(say(MONARENA_CLERK, monClearText(R.rank)));
  refreshRegSnap(c);
  w.sendSelf(s);
  w.markDirty();
  await flushOk(run);
  return 'win';
}

// 勝ちぬいた ときの 受付の ことば（第68回 C: EX を 足した・第74回 C: EX2）
function monClearText(rank) {
  if (rank === 'EX2') return '千年の月の王者まで、たおしてしまうとは…！\nあんたの魔物たちの名前は、千年先まで語りつがれるぞ！';
  if (rank === 'EX') return '星のかなたの王者にまで勝つとは…！\nあんたの魔物たちは、もう伝説をこえているぞ！';
  if (rank === 'SSS') return 'なんと、王者の中の王者に勝つとは…！\nあんたの魔物たちこそ、本物の伝説だ！';
  return 'おめでとう！\n魔物たちも、ほこらしそうにしているぞ！';
}

// ごほうび（はじめて … first の 品と 小さなメダル / 2回目から … ゴールド（と ランク C から 小さなメダル 1まい））
export function monClearRewards(world, s, R) {
  const c = s.char;
  const now = world.now();
  const out = [];
  c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
  if (noteMonClear(c, R.rank, now)) {
    const got = [];
    for (const [id, n] of R.first.items) {
      if (!ITEMS[id] || !(n > 0)) continue;
      addItem(c, id, n);
      got.push(n > 1 ? `${ITEMS[id].name}を${n}個` : ITEMS[id].name);
    }
    if (got.length) out.push(['sfx', 'item'], say(null, `${c.name}は${got.join('と')}を手に入れた！`));
    for (let i = 1; i <= R.first.medals; i++) if (!c.medalSpots[monFirstMedalId(R.rank, i)]) c.medalSpots[monFirstMedalId(R.rank, i)] = now;
    if (R.first.medals > 0) out.push(['sfx', 'key'], say(null, `${c.name}は小さなメダルを${R.first.medals}枚手に入れた！`));
  } else {
    c.gold = Math.min(9999999, (c.gold || 0) + R.repeatGold);
    if (R.repeatMedal) c.medalSpots[nextMonRepeatMedal(c)] = now;
    out.push(['sfx', 'item'], say(null, `${c.name}は${fmt(R.repeatGold)}ゴールド${R.repeatMedal ? 'と、小さなメダルを1枚' : 'を'}手に入れた！`));
  }
  world.markDirty();
  return out;
}

// ───────────── 家族の 登録チームと 戦う ─────────────
export async function familyRun(run, s, oppId, keys, even) {
  const w = run.world;
  const c = s.char;
  const opp = w.data.characters?.[oppId];
  const snaps = opp ? monArenaRecord(opp).regSnap : [];
  const t = pickTeam(c, keys);
  if (!opp || !snaps.length || !t.ok) {
    run.batch.push(say(MONARENA_CLERK, t.ok ? 'その家族のチームは、今はいないみたいだ' : t.reason));
    await flushOk(run);
    return 'none';
  }
  const lv = even ? MON_EVEN_LV : null;
  const fighters = t.entries.map((e) => ({ key: e.key, real: e.char, ch: monFighterChar(e.char, { level: lv }) }));
  const foes = snaps.map((x) => ({ char: snapChar(x, oppId, { level: lv }), owner: oppId })).filter((x) => x.char);
  run.batch.push(
    say(MONARENA_CALLER, `さあ、家族の対戦だ！\n${c.name}の魔物たちと、${opp.name}の登録チームの勝負！`),
    ...(even ? [say(MONARENA_CALLER, `この試合は、みんなレベル${MON_EVEN_LV}にそろえて戦うぞ！`)] : []),
    ['sfx', 'encounter'],
  );
  if (!(await flushOk(run))) return 'abort';
  const res = await startMonBattle(w, s, { kind: 'family', fighters, foes, oppId, oppName: opp.name, even: !!even });
  if (res === 'win' || res === 'lose') {
    const first = noteFamResult(c, oppId, res === 'win');
    const r = monArenaRecord(c).fam[oppId] || { w: 0, l: 0 };
    if (res === 'win') run.batch.push(['sfx', 'win'], say(MONARENA_CALLER, `勝者、${c.name}の魔物たち！\n${opp.name}のチームに勝った！`));
    else run.batch.push(say(MONARENA_CALLER, `勝者、${opp.name}のチーム！\nいい勝負だったぞ！`));
    if (first) {
      c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
      if (!c.medalSpots[monFamMedalId(oppId)]) {
        c.medalSpots[monFamMedalId(oppId)] = w.now();
        run.batch.push(['sfx', 'key'], say(null, `初めて${opp.name}のチームに勝った！\n${c.name}は小さなメダルを1枚手に入れた！`));
      }
    }
    run.batch.push(say(null, `（${opp.name}のチームとの記録：${r.w}勝${r.l}敗）`));
  } else run.batch.push(say(MONARENA_CLERK, '戦いが止まったようだ…。\nまた来な！'));
  w.sendSelf(s);
  w.markDirty();
  await flushOk(run);
  return res;
}

// ───────────── 戦い ─────────────
// spec: { kind: 'rank'|'family', fighters: [{ key, real, ch }], rank, fight（ランク戦）/ foes, oppId, oppName, even（家族）}
export function makeMonBattle(world, s, spec) {
  const c = s.char;
  const settings = c.battleSettings || {};
  const allies = spec.fighters.map((f) => monAllyInit(f.ch, { controller: s.id, auto: !!settings.auto, owner: c.id }));
  const R = spec.kind === 'rank' ? spec.rank : null;
  const rf = R ? monRankFight(R, spec.fight) : { enemies: [], enemyMod: null, champ: null };
  const { enemies, champ } = rf;
  const b = new MonArenaBattle({
    id: 'ma' + (monSeq++),
    rng: world.rng,
    allies,
    enemies,
    foes: spec.foes || [],
    ...normBattleSettings(settings),
    wait: !!settings.wait,
    canFlee: false,
    bg: 'arena',
    bgm: champ || spec.kind === 'family' ? 'boss' : 'battle',
    // ランク戦の 相手: ランクの レベルに そろえる（宝の洞窟と おなじ のび）。王者は 少し 上の レベルと 強さの 倍率（battle-monarena.js の monRankFight）
    enemyMod: rf.enemyMod,
    // 設定の「敵の強さ」は ランク戦だけ（家族の 魔物は そのまま）
    enemyRate: spec.kind === 'rank' ? difficultyOf(c).enemy : 1,
    hooks: {
      // 道具は ランク戦だけ（めいれいさせろの 魔物が、自分の ふくろから 使う）。家族の 対戦は 道具なし
      hasItem: (actor, id) => spec.kind === 'rank' && actor.controller === s.id && itemCount(c, id) > 0,
      consumeItem: (actor, id) => {
        if (spec.kind !== 'rank' || actor.controller !== s.id) return false;
        const ok = removeItem(c, id, 1);
        if (ok) world.sendSelf(s);
        return ok;
      },
      spendGold: () => 0,
      gainGold: () => 0,
      steal: () => null,
    },
  });
  const actorMap = {};
  b.allies.forEach((a, i) => {
    const f = spec.fighters[i];
    actorMap[a.id] = { type: 'support', key: f.key, owner: c.id, kind: 'monster', char: f.ch, manual: f.ch.tactics === 'manual', real: f.real };
  });
  if (enemies.length) noteSeen(c, [...new Set(enemies)]);
  const ctx = {
    id: b.id, battle: b, sids: [s.id], partyId: s.partyId, map: s.map, actorMap, spec, sess: s,
    // solo … ほかの 人は とちゅうから 入れない・馬車の 入れかえも なし（battles.js の joinBattle・wagon.js）
    opts: { fixed: 'monarena', solo: true, monarena: spec.kind, loseOk: true, boss: !!champ, canFlee: false },
    finish: finishMon,
  };
  return ctx;
}

export function startMonBattle(world, s, spec) {
  return new Promise((resolve) => {
    const ctx = makeMonBattle(world, s, spec);
    ctx.resolve = resolve;
    world.battles.set(ctx.id, ctx);
    s.busy = 'battle';
    s.battleId = ctx.id;
    s.moving = false;
    world.send(s, { t: 'battleStart', snap: ctx.battle.snapshot(), mine: mineOf(ctx, s.id), boss: !!ctx.opts.boss, story: true });
    world.broadcastPositions = true;
  });
}

// 戦いの おわり（battles.js の battleTick・abortBattle が ctx.finish を よぶ）
export function finishMon(world, ctx) {
  world.battles.delete(ctx.id);
  const b = ctx.battle;
  const s = ctx.sess;
  const c = s.char;
  const spec = ctx.spec;
  const outcome = b.result?.outcome || 'flee';
  // HP・MP・作戦を 写しに もどす（次の 戦いへ。もとの 仲間の HP は かえない）
  for (const a of b.allies) {
    const who = ctx.actorMap[a.id];
    if (!who?.char) continue;
    who.char.hp = a.alive ? a.hp : 0;
    who.char.mp = a.mp;
    who.char.status = a.status.poison && a.alive ? { poison: true } : {};
    if (who.real && who.char.tactics) who.real.tactics = who.char.tactics;
  }
  const lines = [];
  let levelUp = false;
  if (outcome === 'win' && spec.kind === 'rank') {
    let exp = 0;
    for (const sp of b.result.killed || []) exp += MONSTERS[sp]?.exp || 0;
    exp += scaledRewardBonus(b).exp;
    const gx = scaleExp(c, Math.round(rewardExp(exp) * MON_EXP_RATE));
    lines.push('魔物たちをやっつけた！');
    if (gx > 0) lines.push(`魔物たちは${gx}ポイントずつ経験値をかくとく！`);
    const rows = [], notes = [];
    for (const f of spec.fighters) {
      const { ups } = growCompanion(f.real, gx, 0);
      const g = growthSummary(f.real.name, ups, [], f.real);
      rows.push(...g.lines);
      notes.push(...g.notes);
      // レベルが 上がったら 強さを 計算しなおす（HP・MPは 今の まま）
      if (ups.length) {
        const { hp, mp, status } = f.ch;
        f.ch = monFighterChar(f.real, { heal: false });
        Object.assign(f.ch, { hp, mp, status });
      }
    }
    lines.push(...rows, ...notes);
    levelUp = rows.length > 0;
  } else if (outcome === 'win') lines.push(`${spec.oppName || '相手'}のチームに勝った！`);
  else if (outcome === 'lose') lines.push(`${c.name}の魔物たちは力つきた…`, '（闘技場では、お金はへらない）');
  if (world.sessions.get(s.id) === s) {
    const run = s.runId && world.runs.get(s.runId);
    s.busy = run ? 'script' : null;
    s.battleId = null;
    s.evoCheck = true;
    s.reading = lines.length > 0;
    s.invuln = s.reading ? RESULT_MAX_MS : 3000;
    world.send(s, { t: 'battleEnd', id: ctx.id, outcome, lines, levelUp, story: true });
    world.sendSelf(s);
  }
  world.markDirty();
  if (ctx.resolve) ctx.resolve(outcome);
}

