// フィールドを うろうろする モンスター（シンボル）
import { ENCOUNTER_TABLES } from '../data/encounters.js';
import { MONSTERS } from '../data/monsters.js';
import { MAPS, isBlocked } from '../maps/index.js';
import { NIGHT_ZONES, NIGHT_MORE } from '../data/night.js';
import { cursedOn, CURSE_SPAWN, CURSE_SPAWN_MS, CURSE_CHASE } from './pyramid.js';
import { LURE } from '../data/abilities-field27.js';

// 魔物よせ（マモノヨセ・魔物よせの笛。world/field27.js の s.lureUntil）が 効いている 人か
const lured = (world, p) => p?.lureUntil > world.now();

let symSeq = 1;

export function rollGroup(rng, table) {
  const e = rng.weighted(ENCOUNTER_TABLES[table]);
  const list = [];
  for (const [sp, mn, mx] of e.group) {
    const n = rng.int(mn, mx);
    for (let i = 0; i < n; i++) list.push(sp);
  }
  if (!list.length) list.push(e.group[0][0]);
  return list;
}

// マップごとの じょうたい
export function mapState(world, mapId) {
  let ms = world.mapStates.get(mapId);
  if (!ms) {
    ms = { id: mapId, symbols: new Map(), spawnTimer: 0, zoneTiles: null };
    world.mapStates.set(mapId, ms);
  }
  return ms;
}

// ちいきごとに でてこれる マスを さがしておく
function zoneTiles(ms) {
  if (ms.zoneTiles) return ms.zoneTiles;
  const map = MAPS[ms.id];
  const z = {};
  for (let y = 1; y < map.h - 1; y++) {
    for (let x = 1; x < map.w - 1; x++) {
      if (isBlocked(map, x, y, () => false)) continue;
      const zone = map.zoneAt(x, y);
      if (zone.startsWith('safe')) continue;
      (z[zone] = z[zone] || []).push([x, y]);
    }
  }
  ms.zoneTiles = z;
  return z;
}

// ちいきを 12マスの 区画に 分けて、まものが へった 区画から うめる（かたよらない ように）。
// 区画ごとの 数は マスの 広さに あわせる。ちいきごとの 数（spawnCounts）で わざと 多い・少ないは つけられる
const CELL = 12;
function zoneCells(ms) {
  if (ms.zoneCells) return ms.zoneCells;
  const out = {};
  for (const [zone, tiles] of Object.entries(zoneTiles(ms))) {
    const cells = new Map();
    for (const t of tiles) {
      const key = `${Math.floor(t[0] / CELL)},${Math.floor(t[1] / CELL)}`;
      if (!cells.has(key)) cells.set(key, { key, tiles: [] });
      cells.get(key).tiles.push(t);
    }
    // 小さすぎる 区画（はしっこ）は となりに まかせる
    out[zone] = [...cells.values()].filter((c) => c.tiles.length >= 6);
  }
  ms.zoneCells = out;
  return out;
}
const cellKeyOf = (x, y) => `${Math.floor(x / CELL)},${Math.floor(y / CELL)}`;

function cellLoad(ms, zone, cells, tod = null) {
  const count = new Map(cells.map((c) => [c.key, 0]));
  for (const s of ms.symbols.values()) {
    if (s.zone !== zone || (s.tod || null) !== tod) continue;
    const k = cellKeyOf(s.hx, s.hy);
    if (count.has(k)) count.set(k, count.get(k) + 1);
  }
  // 広さ あたりの 数（少ない ほど 先に うめる）
  return cells.map((c) => ({ c, n: count.get(c.key), load: count.get(c.key) / c.tiles.length }));
}

// 昼と 夜で 出る まものが かわる ちいきか（フィールドだけ。どうくつ・塔の 中は かわらない）
export function hasNightSplit(map, zone) {
  return map.kind === 'field' && !!NIGHT_ZONES[zone];
}

// その まものが 見えるか（night: 見る 人の 時計が 夜か）。tod の ない まものは いつでも
export function symbolVisible(sym, night) {
  return !sym.tod || sym.tod === (night ? 'night' : 'day');
}

// playersOnMap の p.night … その 人の 時計が 夜か（world.js の tick が きめる）
export function spawnSymbols(world, ms, dt, playersOnMap) {
  const map = MAPS[ms.id];
  if (!map.spawnCounts) return;
  ms.spawnTimer -= dt;
  if (ms.spawnTimer > 0) return;
  // のろいの宝（王家のピラミッド）: のろわれた 人が いると 魔物が ふえる（world/pyramid.js）
  const curse = cursedOn(ms.id, playersOnMap);
  // 魔物よせ（data/abilities-field27.js の LURE）: その マップに 効いている 人が いると、魔物が 多く・早く 出てくる
  const lure = playersOnMap.some((p) => lured(world, p));
  ms.spawnTimer = curse ? CURSE_SPAWN_MS : lure ? LURE.spawnMs : 700;
  const zc = zoneCells(ms);
  const key = (zone, tod) => `${zone}|${tod || ''}`;
  // 昼の 人・夜の 人が いるか（だれも 見ない ほうの まものは すこしずつ いなくなる）
  const wantDay = playersOnMap.some((p) => !p.night), wantNight = playersOnMap.some((p) => p.night);
  if (!wantDay || !wantNight) {
    let n = 0;
    for (const s of [...ms.symbols.values()]) {
      if (n >= 3) break;
      if (s.tod && !s.busy && (s.tod === 'day' ? !wantDay : !wantNight)) { ms.symbols.delete(s.id); n++; }
    }
  }
  const counts = {};
  for (const s of ms.symbols.values()) counts[key(s.zone, s.tod)] = (counts[key(s.zone, s.tod)] || 0) + 1;
  const near = (x, y, r) => playersOnMap.some((p) => Math.hypot(p.x - x, p.y - y) < r);
  // たりない ちいきの うち、いちばん 少ない ところから（夜が 来た すぐ あとは 3びきずつ）
  const pools = [];
  for (const [zone, base] of Object.entries(map.spawnCounts)) {
    const target = curse ? Math.round(base * CURSE_SPAWN) : lure ? Math.ceil(base * LURE.spawn) : base;
    if (!zc[zone]?.length) continue;
    if (!hasNightSplit(map, zone)) pools.push([zone, null, target]);
    else {
      if (wantDay) pools.push([zone, 'day', target]);
      if (wantNight) pools.push([zone, 'night', Math.round(target * NIGHT_MORE)]);
    }
  }
  const need = pools.filter(([zone, tod, target]) => (counts[key(zone, tod)] || 0) < target)
    .sort((a, b) => (counts[key(a[0], a[1])] || 0) / a[2] - (counts[key(b[0], b[1])] || 0) / b[2]);
  if (!need.length) {
    rebalance(world, ms, zc, near);
    return;
  }
  const [zone, tod, target] = need[0];
  const burst = (counts[key(zone, tod)] || 0) < target / 2 ? 3 : 1;
  // map.tableFor … その ときの 世界で 出現表を かえる（第4章 Step 7 の 砂の底の神殿 地下1階: 水が 高いか 低いか。maps/temple.js）
  const table = map.tableFor ? map.tableFor(zone, playersOnMap, world) : null;
  for (let k = 0; k < burst; k++) {
    const loads = cellLoad(ms, zone, zc[zone], tod).sort((a, b) => a.load - b.load || world.rng.next() - 0.5);
    spawnIn(world, ms, zone, tod, loads, near, table);
  }
}

function spawnIn(world, ms, zone, tod, loads, near, table = null) {
  for (const { c } of loads.slice(0, 2)) {
    for (let tries = 0; tries < 6; tries++) {
      const [x, y] = world.rng.pick(c.tiles);
      // プレイヤーの めの まえには でない
      if (near(x, y, 9)) continue;
      ms.symbols.set(...newSymbol(world, zone, x, y, tod, table));
      return true;
    }
  }
  return false;
}

// ぜんぶ いる ときは、こみあった 区画の まもの（だれも 見ていない もの）を ときどき 空いた 区画へ うつす
function rebalance(world, ms, zc, near) {
  ms.rebalanceT = (ms.rebalanceT || 0) + 1;
  if (ms.rebalanceT % 2) return;
  for (const [zone, cells] of Object.entries(zc)) {
    if (cells.length < 2) continue;
    const tod = hasNightSplit(MAPS[ms.id], zone) ? (ms.rebalanceT % 4 ? 'night' : 'day') : null;
    const loads = cellLoad(ms, zone, cells, tod).sort((a, b) => a.load - b.load);
    const low = loads[0], high = loads[loads.length - 1];
    if (high.n < 2 || high.load < low.load * 2 + 0.01 || high.n - low.n < 2) continue;
    const mover = [...ms.symbols.values()].find((s) => s.zone === zone && (s.tod || null) === tod && !s.busy && s.state === 'wander' && cellKeyOf(s.hx, s.hy) === high.c.key && !near(s.x, s.y, 16));
    if (!mover) continue;
    for (let tries = 0; tries < 6; tries++) {
      const [x, y] = world.rng.pick(low.c.tiles);
      if (near(x, y, 16)) continue;
      ms.symbols.delete(mover.id);
      ms.symbols.set(...newSymbol(world, zone, x, y, mover.tod || null, mover.table !== zone ? mover.table : null));
      return;
    }
  }
}

// tod: 'day' / 'night'（昼と 夜で かわる ちいき）/ null（いつでも）
function newSymbol(world, zone, x, y, tod = null, forced = null) {
  let table = forced || (tod === 'night' ? NIGHT_ZONES[zone] || zone : zone);
  if (tod !== 'night' && (zone === 'plains' || zone === 'outskirts') && world.rng.chance(0.025)) table = 'rare';
  const group = rollGroup(world.rng, table);
  const lead = group[0];
  const sym = {
    id: 'm' + (symSeq++), sp: lead, group, table, zone, tod: tod || undefined,
    x: x + 0.5, y: y + 0.5, hx: x + 0.5, hy: y + 0.5, dir: 'down',
    vx: 0, vy: 0, t: 0, state: 'wander', busy: false, stun: 0,
    speed: lead === 'kirakira' ? 3.6 : 1.4 + Math.min(1.2, (MONSTERS[lead].agi || 10) / 40),
    // よわい まものは おいかけてこない（こどもでも にげられるように）
    aggro: lead !== 'kirakira' && MONSTERS[lead].lv >= 3,
    level: MONSTERS[lead].lv,
  };
  return [sym.id, sym];
}

// うごかす
export function moveSymbols(world, ms, dt, players) {
  const map = MAPS[ms.id];
  const sec = dt / 1000;
  for (const s of ms.symbols.values()) {
    if (s.busy) continue;
    if (s.stun > 0) {
      s.stun -= dt;
      continue;
    }
    s.t -= dt;
    // いちばん ちかい プレイヤー（のろわれた 人は 遠くからでも 見つかる。world/pyramid.js）
    let target = null, best = 6, near = 6;
    for (const p of players) {
      // 空の 上の 人・その まものが 見えない（昼と 夜が ちがう）人は おいかけない
      if (p.invuln > 0 || p.busy || p.flying || !symbolVisible(s, p.night)) continue;
      const d = Math.hypot(p.x - s.x, p.y - s.y);
      const reach = cursedPlayer(map, p) ? CURSE_CHASE + 1.5 : lured(world, p) ? LURE.reach : 6;
      if (d < reach && d - reach < best - near) {
        best = d;
        near = reach;
        target = p;
      }
    }
    const lure = !!target && lured(world, target);
    const chaseR = target && cursedPlayer(map, target) ? CURSE_CHASE : lure ? LURE.chase : 4.5;
    // 魔物よけ（聖水・トヘロス）。魔物よせが 効いている ときは 効かない（あとから 使った ほうが 勝つ。world/field27.js）
    const repelled = target && !lure && target.repelUntil > world.now() && s.level <= target.level;
    if (s.sp === 'kirakira' && target && best < 4) {
      // きらきらぷるりんは にげる
      s.state = 'flee';
      const d = Math.max(0.01, best);
      s.vx = (s.x - target.x) / d;
      s.vy = (s.y - target.y) / d;
    } else if (target && (s.aggro || lure) && !repelled && best < chaseR) {
      s.state = 'chase';
      const d = Math.max(0.01, best);
      s.vx = (target.x - s.x) / d;
      s.vy = (target.y - s.y) / d;
    } else if (repelled && best < 4) {
      s.state = 'flee';
      const d = Math.max(0.01, best);
      s.vx = (s.x - target.x) / d;
      s.vy = (s.y - target.y) / d;
    } else if (s.t <= 0) {
      s.state = 'wander';
      s.t = 800 + world.rng.int(0, 2400);
      if (world.rng.chance(0.35)) {
        s.vx = 0;
        s.vy = 0;
      } else {
        // ホームから はなれすぎたら もどる
        const hd = Math.hypot(s.hx - s.x, s.hy - s.y);
        if (hd > 5) {
          s.vx = (s.hx - s.x) / hd;
          s.vy = (s.hy - s.y) / hd;
        } else {
          const a = world.rng.float(0, Math.PI * 2);
          s.vx = Math.cos(a);
          s.vy = Math.sin(a);
        }
      }
    }
    const sp = s.state === 'chase' ? s.speed * 1.55 : s.state === 'flee' ? s.speed * 1.3 : s.speed * 0.6;
    const nx = s.x + s.vx * sp * sec;
    const ny = s.y + s.vy * sp * sec;
    const okX = canStand(map, nx, s.y, s.zone);
    const okY = canStand(map, s.x, ny, s.zone);
    if (okX) s.x = nx; else s.vx = -s.vx * 0.5;
    if (okY) s.y = ny; else s.vy = -s.vy * 0.5;
    if (Math.abs(s.vx) > Math.abs(s.vy)) s.dir = s.vx > 0 ? 'right' : 'left';
    else if (Math.abs(s.vy) > 0.01) s.dir = s.vy > 0 ? 'down' : 'up';
  }
}

// のろわれた 人（王家のピラミッドの 中だけ）
const cursedPlayer = (map, p) => !!map.pyramid && !!p.char?.pyrCurse;

function canStand(map, x, y, zone) {
  const tx = Math.floor(x), ty = Math.floor(y);
  if (isBlocked(map, tx, ty, () => false)) return false;
  return map.zoneAt(tx, ty) === zone;
}

// night: 見る 人の 時計が 夜か（昼の まもの・夜の まものの どちらを 見せるか）
export function symbolSnapshot(ms, night = false) {
  const out = [];
  for (const s of ms.symbols.values()) {
    if (s.busy || !symbolVisible(s, night)) continue;
    // 第64回 ⑥a: いっしょに いる 群れの 魔物（すがたと ちがう 魔物が いる ときだけ。フィールドで さがす 魔物を 赤く 光らせる）
    const gs = Array.isArray(s.group) ? [...new Set(s.group.map((g) => (Array.isArray(g) ? g[0] : g)).filter((g) => g && g !== s.sp))] : [];
    out.push({ id: s.id, sp: s.sp, x: Math.round(s.x * 100) / 100, y: Math.round(s.y * 100) / 100, dir: s.dir, st: s.state === 'chase' ? 1 : 0, ...(gs.length ? { gs } : {}) });
  }
  return out;
}

js/shared/world/party.js:
// パーティー・なかま（酒場の なかま・モンスター・家族サポート）・ゲスト
//
// なかまは キャラクターの セーブデータに のこる（アプリを おとしても いなくならない）
//   c.companions … なかまに なった みんな（酒場で まっている なかまも ふくむ）
//   c.partyKeys  … いま いっしょに ぼうけんしている なかま（じゅんばん）。'fam:ID' は 家族の キャラ
//   c.guests     … ものがたりで いっしょに いる ゲスト（ルカ など）
// パーティーには リーダーの なかまが ついてくる（にんげんが ふえると、はいりきらない なかまは いったん まつ）
import { cmdOffList } from '../cmd-off.js';
import { newCharacter, computeStats, fullHeal, gainExp, gainJobBattles, migrateJobs, expForLevel, addItem, newMonsterCompanion, learnedAbilities, masteredJobs } from '../stats.js';
import { jobBattlesForLevel, JOBS } from '../data/jobs.js';
import { NPC_SUPPORTS, GUESTS } from '../data/shops.js';
import { MONSTERS } from '../data/monsters.js';
import { MONSTER_FRIENDS, ROSTER_MAX, COMPANION_SLOTS } from '../data/companions.js';
import { SLOTS, ITEMS } from '../data/items.js';
import { cleanWagon, hasWagon, WAGON_SLOTS } from '../data/wagon.js';
import { wagonState, wagonTavernInfo } from './wagon.js';
import { difficultyOf } from '../data/difficulty.js';

// パーティーに 入れる 人（家族の プレイヤー）は 5人まで。いっしょに フィールドを 歩いて、いっしょに 戦う
export const PARTY_MAX = 5;
// 酒場の なかまが 入るのは、人と あわせて 4人に なるまで（5人で 戦うのは プレイヤーが 5人 そろった ときだけ）
export const BATTLE_FILL = 4;
// パーティーの だれかが もっていれば みんなが とおれる フラグ
export const GATE_FLAGS = ['bridge_fixed', 'c1_door', 'c2_light', 'c2_boss'];

let partySeq = 1;

export function newParty(world, leaderSid) {
  const p = { id: 'p' + (partySeq++), leader: leaderSid, members: [leaderSid], supports: [], guests: [], bond: 0 };
  world.parties.set(p.id, p);
  return p;
}

export function partyOf(world, s) {
  return world.parties.get(s.partyId);
}

export function partySize(p) {
  return p.members.length + p.supports.length;
}

// ふるい セーブデータにも なかまの きろくを つくる
export function ensureCompanions(c) {
  if (!Array.isArray(c.companions)) c.companions = [];
  c.companions = c.companions.filter((e) => e && e.key && e.char);
  for (const e of c.companions) migrateJobs(e.char);
  if (!Array.isArray(c.partyKeys)) c.partyKeys = [];
  c.partyKeys = c.partyKeys.filter((k, i, arr) => typeof k === 'string' && arr.indexOf(k) === i
    && (k.startsWith('fam:') || c.companions.some((e) => e.key === k))).slice(0, COMPANION_SLOTS);
  if (!Array.isArray(c.guests)) {
    // まえの バージョンでは ゲストが セーブされていなかった（ルカが いなくなる ふぐあい）
    c.guests = c.flags?.p_start && !c.flags?.p_attack ? ['luca'] : [];
  }
  c.monsterSeq = c.monsterSeq || 1;
  // 馬車の 仲間（data/wagon.js）
  cleanWagon(c);
  return c;
}

export function companionOf(c, key) {
  return (c.companions || []).find((e) => e.key === key) || null;
}

// 魔物あずかり所（第43回 C。world/storage.js）
//   c.storage … あずけた 魔物（仲間と 同じ 形 { key, kind: 'monster', species, char }）。60 まで。仲間の 40 とは 別に 数える
//   あずけた 魔物は 戦わない・育たない。酒場の 配合の 親には なれる（world/breed.js の breedEntry）
//   古い セーブには ない（空の ならびに する）
export const STORAGE_MAX = 60;
export function ensureStorage(c) {
  if (!Array.isArray(c.storage)) c.storage = [];
  c.storage = c.storage.filter((e) => e && e.key && e.char && e.kind === 'monster');
  // 魔物の 番号（m12 など）が 仲間と かさならない ように、番号を あずけた 魔物より 先へ
  for (const e of c.storage) {
    const n = /^m(\d+)$/.exec(e.key);
    if (n && Number(n[1]) >= (c.monsterSeq || 1)) c.monsterSeq = Number(n[1]) + 1;
  }
  return c;
}
export function storedOf(c, key) {
  return ensureStorage(c).storage.find((e) => e.key === key) || null;
}
// 配合の 親: 酒場の 仲間か あずかり中の 魔物
export function breedEntry(c, key) {
  return companionOf(c, key) || storedOf(c, key);
}

// 家族の キャラクターを サポートとして つれていく（その ときの すがたを うつす）
//   うつしは パーティーと 馬車で おなじ ものを つかう（p.famCopies。セーブには のこらない）。
//   パーティー ⇄ 馬車の 乗りかえでは HP・MPは そのまま。酒場に もどると わすれる（つぎは 元気いっぱい）
function famSnapshot(other) {
  const snap = {
    id: other.id, name: other.name, look: other.look, job: other.job, jobs: JSON.parse(JSON.stringify(other.jobs || {})),
    level: other.level, exp: other.exp, equip: { ...other.equip }, seeds: { ...(other.seeds || {}) },
    // 見た目装備も うつす（shared/look-equip.js）
    ...(other.lookEquip ? { lookEquip: { ...other.lookEquip } } : {}),
    items: [], flags: {}, status: {}, tactics: other.tactics || 'balanced', ownerId: other.id,
  };
  fullHeal(snap);
  return snap;
}

// 家族の キャラの うつし（lc … リーダー。いない 人・自分なら null）
export function famCopy(world, p, lc, key) {
  const other = String(key || '').startsWith('fam:') ? world.data.characters[key.slice(4)] : null;
  if (!other || !lc || other.id === lc.id) return null;
  const memo = p ? (p.famCopies || (p.famCopies = new Map())) : null;
  const id = `${lc.id}|${key}`;
  let snap = memo?.get(id);
  if (!snap) {
    snap = famSnapshot(other);
    memo?.set(id, snap);
  }
  return snap;
}

// パーティーに いる 人（家族）の キャラの id（その 人の うつしは つれていかない）
export function humanCharIds(world, p) {
  return new Set((p?.members || []).map((sid) => world.sessions.get(sid)?.charId).filter(Boolean));
}

// いなくなった 家族の キャラ（消した・この セーブに いない）の しるしを はずす
export function dropMissingFam(world, c) {
  const ok = (k) => !String(k).startsWith('fam:') || !!world.data.characters[String(k).slice(4)];
  if (Array.isArray(c?.partyKeys) && !c.partyKeys.every(ok)) c.partyKeys = c.partyKeys.filter(ok);
  if (Array.isArray(c?.wagonKeys) && !c.wagonKeys.every(ok)) c.wagonKeys = c.wagonKeys.filter(ok);
}

// リーダーの なかまを パーティーに ならべなおす（ゲストは みんなの ぶんを あわせる）
export function syncParty(world, p) {
  if (!p) return;
  const leader = world.sessions.get(p.leader);
  const lc = leader?.char;
  const room = Math.max(0, BATTLE_FILL - p.members.length);
  const want = [];
  if (lc) {
    ensureCompanions(lc);
    dropMissingFam(world, lc);
    const onlineChars = humanCharIds(world, p);
    for (const key of lc.partyKeys) {
      if (want.length >= room) break;
      if (key.startsWith('fam:')) {
        const other = world.data.characters[key.slice(4)];
        if (!other || other.id === lc.id || onlineChars.has(other.id)) continue;
        want.push({ key, fam: other });
      } else {
        const e = companionOf(lc, key);
        if (e) want.push({ key, entry: e });
      }
    }
  }
  const old = new Map(p.supports.map((x) => [`${x.owner}|${x.key}`, x]));
  p.supports = want.map((w) => {
    const prev = old.get(`${lc.id}|${w.key}`);
    if (prev) return prev;
    if (w.fam) return { key: w.key, owner: lc.id, kind: 'family', char: famCopy(world, p, lc, w.key) };
    return { key: w.key, owner: lc.id, kind: w.entry.kind, char: w.entry.char };
  });
  // 家族の うつし: パーティーにも 馬車にも いない 人の ぶんは わすれる
  if (p.famCopies) {
    const keep = new Set(lc ? [...lc.partyKeys, ...(lc.wagonKeys || [])].map((k) => `${lc.id}|${k}`) : []);
    for (const id of [...p.famCopies.keys()]) if (!keep.has(id)) p.famCopies.delete(id);
  }
  // ゲスト（第61回: リーダーの ゲストだけ。さそわれた 人は 1人だけで 入る。ゲストは 自分の パーティーの 時だけ）
  const gids = [];
  for (const g of lc?.guests || []) if (!gids.includes(g) && GUESTS[g]) gids.push(g);
  const oldG = new Map(p.guests.map((g) => [g.id, g]));
  p.guests = gids.map((id) => oldG.get(id) || { id, char: guestChar(world, id, lc?.level || 1) }).filter((g) => g.char);
}

// ───────────── 酒場 ─────────────
// 酒場で 新しく 仲間に なる 人は レベル1から（第31回。モンスターの 仲間と おなじ。今 いる 仲間の レベルは そのまま）
export const TAVERN_JOIN_LEVEL = 1;
// ものがたりで 仲間に なる 人（第1章の ルカ）は 主人公の 1つ下（すぐ いっしょに 戦うので 今までどおり）
export function npcStartLevel(c, story = false) {
  return story ? Math.max(1, c.level - 1) : TAVERN_JOIN_LEVEL;
}

function companionInfo(e, activeKeys, partyKeys) {
  const ch = e.char;
  const st = computeStats(ch);
  const def = e.kind === 'npc' ? NPC_SUPPORTS.find((n) => n.id === e.key) : null;
  return {
    key: e.key, kind: e.kind, species: e.species || null, name: ch.name, job: ch.job, level: ch.level, look: ch.look, equip: ch.equip, lookEquip: ch.lookEquip,
    hp: ch.hp, maxHp: st.maxHp, mp: ch.mp, maxMp: st.maxMp, tactics: ch.tactics,
    // 第67回: 強さ（酒場で 入れかえ・配合の 相手を 決める ため。家族が ねがった）
    st: { str: st.str, def: st.def, agi: st.agi, mag: st.mag, heal: st.heal, atk: st.atk, dfn: st.dfn },
    inParty: partyKeys.includes(e.key), active: activeKeys.has(e.key),
    desc: def?.desc || MONSTER_FRIENDS[e.species]?.note || '',
    plus: ch.plus || 0, abilities: e.kind === 'monster' ? learnedAbilities(ch) : undefined, parents: ch.parents || null,
    // 配合の めやす・血統（shared/breed-calc.js。第35回）
    ...(e.kind === 'monster' ? { bonus: ch.bonus || null, seeds: ch.seeds || null, lineage: ch.lineage || null, ranked: ch.ranked || 0 } : {}),
    // 第43回 A: 配合の あとの 追いつき（この レベルまで 経験値 3倍）
    ...(e.kind === 'monster' && ch.catchUp > ch.level ? { catchUp: ch.catchUp } : {}),
    // 第53回 D: 色ちがいの 仲間（data/variants.js の colorMon で 顔の 絵）
    ...(ch.color ? { color: ch.color } : {}),
  };
}

export function tavernInfo(world, s) {
  const c = ensureCompanions(s.char);
  const p = partyOf(world, s);
  const activeKeys = new Set((p?.leader === s.id ? p.supports : []).map((x) => x.key));
  const roster = c.companions.map((e) => companionInfo(e, activeKeys, c.partyKeys));
  const recruits = [];
  for (const n of NPC_SUPPORTS) {
    if (n.unlock && !c.flags[n.unlock]) continue;
    if (companionOf(c, n.id)) continue;
    recruits.push({ key: n.id, name: n.name, job: n.job, level: npcStartLevel(c), look: n.look, desc: n.desc });
  }
  const family = [];
  const onlineInParty = humanCharIds(world, p);
  const wagonKeys = c.wagonKeys || [];
  for (const other of Object.values(world.data.characters)) {
    if (other.id === c.id) continue;
    const key = 'fam:' + other.id;
    const inParty = c.partyKeys.includes(key), inWagon = wagonKeys.includes(key);
    // 本人が パーティーに いる ときは、つれている 人だけ 出す（席が 見えなく ならないように）
    const here = onlineInParty.has(other.id);
    if (here && !inParty && !inWagon) continue;
    const copy = p?.famCopies?.get(`${c.id}|${key}`);
    const st = computeStats(copy || other);
    family.push({
      key, name: other.name, job: other.job, level: other.level, look: other.look, equip: other.equip, lookEquip: other.lookEquip, family: true,
      hp: copy ? copy.hp : st.maxHp, maxHp: st.maxHp, mp: copy ? copy.mp : st.maxMp, maxMp: st.maxMp, here,
      desc: `家族のキャラクター（${other.name}）。連れていくと${other.name}にも経験値のおすそわけが届くよ（馬車に乗っているときは少しだけ）。`,
      inParty, active: activeKeys.has(key),
    });
  }
  return wagonTavernInfo(c, {
    roster, recruits, family, slots: COMPANION_SLOTS, used: c.partyKeys.length,
    isLeader: !p || p.leader === s.id, rosterMax: ROSTER_MAX, humans: p?.members.length || 1,
    // あずかり中の 魔物（配合の 親に なれる。第43回 C）
    stored: ensureStorage(c).storage.map((e) => ({ ...companionInfo(e, activeKeys, []), stored: true })), storageMax: STORAGE_MAX,
  });
}

// レベルに あった そうび（酒場の なかまが はじめから もっている もの）
const TIER_GEAR = [
  [1, { warrior: ['wood_sword', 'cloth'], monk: [null, 'cloth'], priest: ['oak_staff', 'cloth'], mage: ['oak_staff', 'cloth'], performer: ['feather_fan', 'cloth'] }],
  [4, { warrior: ['bronze_sword', 'travel_clothes', 'leather_shield', 'leather_hat'], monk: ['bronze_knuckle', 'martial_gi', null, 'leather_hat'], priest: ['bronze_spear', 'travel_clothes', 'leather_shield', 'leather_hat'], mage: ['oak_staff', 'wizard_robe', null, 'leather_hat'], performer: ['feather_fan', 'travel_clothes', 'leather_shield', 'leather_hat'] }],
  [8, { warrior: ['bronze_sword', 'chain_mail', 'scale_shield', 'leather_hat'], monk: ['bronze_knuckle', 'martial_gi', null, 'bandana'], priest: ['bronze_spear', 'leather_armor', 'scale_shield', 'leather_hat'], mage: ['oak_staff', 'wizard_robe', null, 'pointy_hat'], performer: ['feather_fan', 'leather_armor', 'scale_shield', 'bandana'] }],
  [12, { warrior: ['iron_sword', 'iron_armor', 'iron_shield', 'iron_helm'], monk: ['iron_claw', 'dragon_gi', null, 'bandana'], priest: ['healing_staff', 'holy_robe', 'scale_shield', 'leather_hat'], mage: ['wizard_staff', 'wizard_robe', null, 'pointy_hat'], performer: ['dancer_fan', 'leather_armor', 'scale_shield', 'bandana'] }],
];

export function makeNpcSupportChar(def, level) {
  const c = newCharacter({ id: def.id, name: def.name, look: def.look, job: def.job });
  // 上級職の ゲスト（第4章の サラは 海賊）。newCharacter は さいしょの 職業しか えらべないので ここで かえる
  if (JOBS[def.job] && c.job !== def.job) {
    delete c.jobs[c.job];
    c.job = def.job;
  }
  c.level = level;
  c.exp = expForLevel(level);
  const jl = Math.max(1, Math.min(7, Math.floor(level * 0.4)));
  c.jobs[def.job] = { lv: jl, b: jobBattlesForLevel(jl) };
  let gear = TIER_GEAR[0][1];
  for (const [lv, g] of TIER_GEAR) if (level >= lv) gear = g;
  const [w, a, s, h] = gear[def.job] || [];
  c.equip = { weapon: w || null, armor: a || null, shield: s || null, head: h || null, acc: null };
  // ゲストの 装備（第4章の サラ: ムチと 砂の衣。def.gear が あれば それ）
  if (def.gear) Object.assign(c.equip, def.gear);
  // その 仲間だけの 技（第5章 Step 9 の ノクト。data/companions-castle.js の NOCTO_COMPANION.skills）は ひらめき技として 覚えている
  if (Array.isArray(def.skills)) c.hirameki = [...def.skills];
  c.items = [];
  c.tactics = def.tactics || 'balanced';
  delete c.explored;
  delete c.visited;
  fullHeal(c);
  return c;
}

// 酒場で まつ なかまの 装備は ふくろに もどす（家族の キャラは その人の ものなので そのまま）
export function stowGear(c, key) {
  const e = companionOf(c, key);
  if (!e?.char?.equip) return [];
  const out = [];
  for (const slot of SLOTS) {
    const id = e.char.equip[slot];
    if (!id) continue;
    addItem(c, id, 1);
    e.char.equip[slot] = null;
    out.push(ITEMS[id]?.name || id);
  }
  if (out.length) {
    const st = computeStats(e.char);
    e.char.hp = Math.min(e.char.hp, st.maxHp);
    e.char.mp = Math.min(e.char.mp, st.maxMp);
  }
  return out;
}

// なかまを パーティーに いれる（いっぱいなら swapKey の なかまを 酒場へ）
export function putInParty(c, key, swapKey) {
  if (c.partyKeys.includes(key)) return { ok: true };
  if (c.partyKeys.length < COMPANION_SLOTS) {
    c.partyKeys.push(key);
    return { ok: true };
  }
  const i = swapKey ? c.partyKeys.indexOf(swapKey) : -1;
  if (i < 0) return { ok: false, full: true, reason: 'パーティーがいっぱいです。だれかに酒場で待っていてもらおう' };
  c.partyKeys[i] = key;
  return { ok: true, benched: swapKey, stowed: stowGear(c, swapKey) };
}

// 仲間を つれていく（酒場・新しい 仲間・まもの）: あいている パーティー → あいている 馬車 → swapKey の 人と 入れかわる
//   入れかわった 人（パーティーか 馬車に いた 人）は 酒場へ（装備は ふくろへ）。どちらも いっぱいで swapKey が なければ full
export function placeMember(c, key, swapKey) {
  ensureCompanions(c);
  const wagon = hasWagon(c) ? c.wagonKeys : null;
  if (c.partyKeys.includes(key)) return { ok: true, where: 'party' };
  if (wagon?.includes(key)) return { ok: true, where: 'wagon' };
  if (c.partyKeys.length < COMPANION_SLOTS) {
    c.partyKeys.push(key);
    return { ok: true, where: 'party' };
  }
  if (wagon && wagon.length < WAGON_SLOTS) {
    wagon.push(key);
    return { ok: true, where: 'wagon' };
  }
  const pi = swapKey ? c.partyKeys.indexOf(swapKey) : -1;
  const wi = swapKey && wagon ? wagon.indexOf(swapKey) : -1;
  if (pi < 0 && wi < 0) {
    return { ok: false, full: true, reason: wagon ? 'パーティーも馬車もいっぱいです。だれかに酒場で待っていてもらおう' : 'パーティーがいっぱいです。だれかに酒場で待っていてもらおう' };
  }
  if (pi >= 0) c.partyKeys[pi] = key;
  else wagon[wi] = key;
  return { ok: true, where: pi >= 0 ? 'party' : 'wagon', benched: swapKey, stowed: stowGear(c, swapKey) };
}

// パーティーも 馬車も いっぱいか（つれていく ときに だれかと 入れかわる）
export function rosterFull(c) {
  ensureCompanions(c);
  return c.partyKeys.length >= COMPANION_SLOTS && (!hasWagon(c) || c.wagonKeys.length >= WAGON_SLOTS);
}

export function nameOfKey(world, c, key) {
  if (!key) return '';
  if (key.startsWith('fam:')) return world.data.characters[key.slice(4)]?.name || '';
  return companionOf(c, key)?.char.name || '';
}

export function afterRosterChange(world, s) {
  const p = partyOf(world, s);
  if (p) {
    syncParty(world, p);
    world.sendParty(p);
  }
  world.markDirty();
}

// 酒場で あたらしい なかまを さがす
export function recruitNpc(world, s, npcId, opts = {}) {
  const c = ensureCompanions(s.char);
  const def = NPC_SUPPORTS.find((n) => n.id === npcId);
  if (!def) return { ok: false, reason: '見つかりません' };
  if (def.unlock && !c.flags[def.unlock] && !opts.force) return { ok: false, reason: 'まだ仲間にできません' };
  if (companionOf(c, npcId)) return { ok: false, reason: 'もう仲間です' };
  if (c.companions.length >= ROSTER_MAX) return { ok: false, reason: `仲間は${ROSTER_MAX}人までです` };
  // opts.force … ものがたりで 仲間に なる（world/scripts.js の 'recruit'）
  const ch = makeNpcSupportChar(def, npcStartLevel(c, !!opts.force));
  ch.id = `${c.id}:${def.id}`;
  c.companions.push({ key: def.id, kind: 'npc', char: ch });
  let joined = false, where = null, benchedName = '', stowed = [];
  if (opts.join !== false) {
    // パーティー → 馬車 → 入れかわり（placeMember）
    const r = placeMember(c, def.id, opts.swap);
    joined = r.ok;
    where = r.ok ? r.where : null;
    if (r.benched) benchedName = nameOfKey(world, c, r.benched);
    stowed = r.stowed || [];
  }
  afterRosterChange(world, s);
  return { ok: true, name: ch.name, joined, where, benchedName, stowed };
}

// 酒場で まっている なかまを つれていく（パーティー → 馬車 → 入れかわり。placeMember）
export function companionJoin(world, s, key, swapKey) {
  const c = ensureCompanions(s.char);
  if (key.startsWith('fam:')) {
    const other = world.data.characters[key.slice(4)];
    if (!other || other.id === c.id) return { ok: false, reason: '見つかりません' };
  } else if (!companionOf(c, key)) return { ok: false, reason: '見つかりません' };
  if (c.partyKeys.includes(key) || (c.wagonKeys || []).includes(key)) return { ok: false, reason: 'もういっしょにいる' };
  const r = placeMember(c, key, swapKey);
  if (!r.ok) return r;
  // 酒場で やすんでいたので げんき いっぱい
  const e = companionOf(c, key);
  if (e) fullHeal(e.char);
  afterRosterChange(world, s);
  return { ok: true, name: nameOfKey(world, c, key), where: r.where, benchedName: nameOfKey(world, c, r.benched), stowed: r.stowed || [] };
}

// 酒場で まっていて もらう
export function companionWait(world, s, key) {
  const c = ensureCompanions(s.char);
  const i = c.partyKeys.indexOf(key);
  if (i < 0) return { ok: false, reason: 'パーティーにいません' };
  c.partyKeys.splice(i, 1);
  const stowed = stowGear(c, key);
  afterRosterChange(world, s);
  return { ok: true, name: nameOfKey(world, c, key), stowed };
}

// わかれる（そうびは ふくろに もどる）。第35回から 人間の 仲間とも（あとで 酒場で また さそえる。レベル1から）
export function companionRelease(world, s, key) {
  const c = ensureCompanions(s.char);
  const e = companionOf(c, key);
  if (!e) return { ok: false, reason: '見つかりません' };
  if (e.kind !== 'monster' && e.kind !== 'npc') return { ok: false, reason: 'この仲間は酒場でずっと待っていてくれるよ' };
  for (const slot of SLOTS) if (e.char.equip?.[slot]) addItem(c, e.char.equip[slot], 1);
  c.companions = c.companions.filter((x) => x !== e);
  c.partyKeys = c.partyKeys.filter((k) => k !== key);
  if (Array.isArray(c.wagonKeys)) c.wagonKeys = c.wagonKeys.filter((k) => k !== key);
  afterRosterChange(world, s);
  return { ok: true, name: e.char.name, human: e.kind === 'npc' };
}

export function companionRename(world, s, key, name) {
  const c = ensureCompanions(s.char);
  // 第63回: あずかり所の 魔物も（配合で あずかり所に 生まれた 子に 名前を つける）
  const e = companionOf(c, key) || (Array.isArray(c.storage) ? c.storage.find((x) => x?.key === key) : null) || null;
  const nm = String(name || '').replace(/[<>&"'\s]/g, '').slice(0, 8);
  if (!e || !nm) return { ok: false, reason: '名前を入れてね' };
  const old = e.char.name;
  e.char.name = nm;
  afterRosterChange(world, s);
  return { ok: true, name: nm, old };
}

// ───────────── モンスターが なかまに なる ─────────────
// たたかいで さいごに たおした まものが おきあがる（紋章の ちからに めざめていれば）
// mult: まもの使いなどが いると おおきくなる
//   info … 第34回までは 仲間が いっぱいの とき info.full に 入れていた（第35回から いっぱいでも なりたがる。world/farewell.js）
export function rollBefriend(world, c, killed, mult = 1, info = null) {
  if (!c?.flags?.monster_bond) return null;
  ensureCompanions(c);
  // 第35回: 仲間が いっぱいでも なりたがる（「はい」の あとで だれと さよならするか えらぶ。world/farewell.js）
  for (let i = killed.length - 1; i >= 0; i--) {
    const f = MONSTER_FRIENDS[killed[i]];
    if (!f || f.breedOnly || MONSTERS[killed[i]]?.boss) continue;
    return world.rng.chance(befriendChance(c, killed[i], mult)) ? killed[i] : null;
  }
  return null;
}

// 1回の 戦いで その 魔物が 仲間に なりたがる かくりつ（上限 BEFRIEND_CAP）
//   mult … 魔物使い（1.5）・モンスターマスター（2）・なかまの粉（2）を かけた もの
//   はじめての 魔物の 仲間は 3倍
export const BEFRIEND_CAP = 0.5;
export function befriendChance(c, species, mult = 1) {
  const f = MONSTER_FRIENDS[species];
  if (!f || f.breedOnly || !(f.rate > 0) || MONSTERS[species]?.boss) return 0;
  const first = !(c?.companions || []).some((e) => e.kind === 'monster');
  return Math.min(BEFRIEND_CAP, f.rate * (first ? 3 : 1) * mult);
}

// ずかん: みた まもの
export function noteSeen(c, species) {
  if (!c) return;
  c.bestiary = c.bestiary || {};
  for (const sp of species) {
    if (!MONSTERS[sp]) continue;
    const b = c.bestiary[sp] || (c.bestiary[sp] = {});
    b.seen = (b.seen || 0) + 1;
  }
}

// ずかん: たたかいで ためした 属性（どの 属性が 効くか。'まもの|属性' の あつまり）
export function noteTried(c, tried) {
  if (!c || !tried?.size) return;
  c.bestiary = c.bestiary || {};
  for (const key of tried) {
    const [sp, el] = key.split('|');
    if (!MONSTERS[sp] || !el) continue;
    const b = c.bestiary[sp] || (c.bestiary[sp] = {});
    if (!b[`el_${el}`]) b[`el_${el}`] = 1;
  }
}

// ずかん: その まものから 手に入れた 物（'drop_品物'）
export function noteDrop(c, species, item) {
  if (!c || !MONSTERS[species] || !item) return;
  c.bestiary = c.bestiary || {};
  const b = c.bestiary[species] || (c.bestiary[species] = {});
  b[`drop_${item}`] = 1;
}

// 仲間に なった まものは、主人公の レベルに かかわらず レベル1から（そだてる たのしみ）
export const MONSTER_JOIN_LEVEL = 1;
export function befriendLevel() {
  return MONSTER_JOIN_LEVEL;
}

function monsterName(c, species) {
  const f = MONSTER_FRIENDS[species];
  // あずかり中の 魔物の 名前とも かさならない ように（第43回 C）
  const used = new Set([...c.companions, ...(c.storage || [])].map((e) => e.char.name));
  for (const n of f?.names || []) if (!used.has(n)) return n;
  const base = MONSTERS[species]?.name || '魔物';
  for (let i = 2; i < 99; i++) if (!used.has(`${base}${i}`.slice(0, 8))) return `${base}${i}`.slice(0, 8);
  return base;
}

// まものを 1ぴき キャラの なかまの きろくに 入れる（さいしょは 酒場で まつ。パーティー・馬車は かえない）
//   名前は その キャラの なかまと かさならない もの・ずかんの「仲間にした」も ふやす。
//   いっぱい（ROSTER_MAX）なら 入れない（full: true）。家族の 酒場にも 入れる（world/recruit-share.js）
export function addMonsterEntry(c, species, level) {
  ensureCompanions(c);
  if (!MONSTER_FRIENDS[species]) return { ok: false, reason: 'この魔物は仲間にできない' };
  if (c.companions.length >= ROSTER_MAX) return { ok: false, full: true, reason: `仲間は${ROSTER_MAX}ひきまでです。酒場でだれかと別れよう` };
  // 番号は かさならない ように（データを 合わせた あとなど）
  while (c.companions.some((e) => e.key === `m${c.monsterSeq}`)) c.monsterSeq++;
  const key = 'm' + (c.monsterSeq++);
  const ch = newMonsterCompanion({ id: `${c.id}:${key}`, name: monsterName(c, species), species, level });
  c.companions.push({ key, kind: 'monster', species, char: ch });
  c.bestiary = c.bestiary || {};
  const b = c.bestiary[species] || (c.bestiary[species] = {});
  b.friend = (b.friend || 0) + 1;
  return { ok: true, key, name: ch.name, char: ch };
}

// なかまに なった まものの いく ところ: あいている パーティー → あいている 馬車 → どちらも いっぱいなら bench の 人と 入れかわる
// bench: 入れかわりに 酒場へ もどる なかま（パーティーか 馬車の 人）。'__tavern' なら あたらしい なかまが 酒場へ
// level: たたかいで なかまに なった まものは befriendLevel()（いつも レベル1）。テストや 特別な ときだけ ほかの レベル
export function addMonsterCompanion(world, s, species, level, bench) {
  const c = ensureCompanions(s.char);
  const add = addMonsterEntry(c, species, level);
  if (!add.ok) return add;
  const { key, char: ch } = add;
  let joined = false, where = null, benchedName = '', stowed = [];
  if (bench !== '__tavern') {
    const r = placeMember(c, key, typeof bench === 'string' ? bench : null);
    joined = r.ok;
    where = r.ok ? r.where : null;
    if (r.benched) benchedName = nameOfKey(world, c, r.benched);
    stowed = r.stowed || [];
  }
  afterRosterChange(world, s);
  return { ok: true, key, name: ch.name, joined, where, benchedName, stowed };
}

// ───────────── ゲスト ─────────────
export function guestChar(world, id, heroLevel) {
  const def = GUESTS[id];
  if (!def) return null;
  return makeNpcSupportChar({ ...def, id: def.id }, Math.max(def.minLevel || 1, heroLevel));
}

// ───────────── なかまの せいちょう ─────────────
// たたかいに でた なかまだけが そだつ（酒場で まっている なかまは そだたない）
// trainN: 職業の しゅぎょうに なった かず（てきが よわすぎると 0）
// かえす もの: { ups, jups }（レベルと 職業レベルの 上がった ぶん。まとめの 文は world/growth.js）
export function growCompanion(ch, exp, trainN = 0) {
  const ups = gainExp(ch, exp);
  const jups = !ch.species && trainN > 0 ? gainJobBattles(ch, trainN) : [];
  return { ups, jups };
}

// サポートで たたかった 家族キャラへの おれい
export function creditSupportOwner(world, ownerId, exp, gold, helperName) {
  const c = world.data.characters[ownerId];
  if (!c) return;
  const e = Math.floor(exp / 2);
  const g = Math.floor(gold / 4);
  const ups = gainExp(c, e);
  c.gold = Math.min(9999999, c.gold + g);
  c.supportLog = c.supportLog || [];
  const last = c.supportLog[c.supportLog.length - 1];
  if (last && last.helper === helperName) {
    last.exp += e;
    last.gold += g;
    last.count++;
    if (ups.length) last.level = c.level;
  } else {
    c.supportLog.push({ helper: helperName, exp: e, gold: g, count: 1, level: ups.length ? c.level : null });
    if (c.supportLog.length > 10) c.supportLog.shift();
  }
}

// ならびかえ: リーダーの c.selfPos（人の まとまりの 場所）と c.partyKeys（なかまの じゅんばん）
export function selfPosOf(world, p) {
  const lc = world.sessions.get(p.leader)?.char;
  const n = Number.isInteger(lc?.selfPos) ? lc.selfPos : 0;
  return Math.max(0, Math.min(p.supports.length, n));
}

// ならびを 変える（order: 'self' と なかまの key の じゅんばん）
export function setPartyOrder(world, s, order) {
  const c = ensureCompanions(s.char);
  const p = partyOf(world, s);
  if (p && p.leader !== s.id) return { ok: false, reason: 'ならびはリーダーが決めます' };
  if (!Array.isArray(order) || !order.includes('self')) return { ok: false, reason: '' };
  const keys = order.filter((k) => k !== 'self' && c.partyKeys.includes(k));
  if (new Set(keys).size !== keys.length) return { ok: false, reason: '' };
  const active = new Set((p?.supports || []).map((x) => x.key));
  c.selfPos = order.filter((k) => k === 'self' || keys.includes(k)).indexOf('self');
  c.partyKeys = [...keys, ...c.partyKeys.filter((k) => !keys.includes(k))];
  if (p) {
    // うごかした あとも 今の なかまは そのまま（ならびだけ かわる）
    p.supports.sort((a, b) => c.partyKeys.indexOf(a.key) - c.partyKeys.indexOf(b.key));
    if (active.size !== p.supports.length) syncParty(world, p);
  }
  return { ok: true };
}

// メニューの「全員の強さ」に 出す 強さ
const statsOf = (st) => ({ str: st.str, def: st.def, agi: st.agi, mag: st.mag, heal: st.heal, atk: st.atk, dfn: st.dfn });

// パーティーの 仲間（馬車の 仲間も おなじ 形）を クライアントへ
export function supportInfo(x) {
  const st = computeStats(x.char);
  return {
    key: x.key, name: x.char.name, job: x.char.job, level: x.char.level, hp: x.char.hp, maxHp: st.maxHp, mp: x.char.mp, maxMp: st.maxMp, st: statsOf(st),
    look: x.char.look, equip: x.char.equip, lookEquip: x.char.lookEquip, tactics: x.char.tactics || 'balanced', family: x.kind === 'family', kind: x.kind, species: x.char.species || null, owner: x.owner,
    jobs: x.kind === 'npc' ? x.char.jobs : undefined, seeds: x.kind === 'family' ? undefined : x.char.seeds, exp: x.char.exp,
    plus: x.char.plus || 0, bonus: x.char.bonus || undefined, inherit: x.char.inherit || undefined, color: x.char.color || undefined,
    hirameki: x.kind === 'npc' ? x.char.hirameki || [] : undefined, skillUse: x.kind === 'npc' ? x.char.skillUse || {} : undefined,
    favorites: x.kind === 'npc' ? x.char.favorites || [] : undefined,
    // 第66回: 幻の職業の やりこみの 記録（神殿・幻の書で 仲間の ぶんも 見る）
    feats: x.kind === 'npc' ? x.char.feats || undefined : undefined,
    // 第64回 ⑥c: れん金で つけた 装備の 効果（家族の キャラの ぶんは 出さない）
    gearFx: x.kind !== 'family' && x.char.gearFx ? x.char.gearFx : undefined,
    // 家族の キャラの マスターした 職業（jobs は おくらない。メニューで パーティーに 関係する ひらめき技を えらぶ ため。stats.js の partyJobSet）
    mjobs: x.kind === 'family' ? masteredJobs(x.char) : undefined,
    // オートで 使わない 技（作戦。家族の キャラの ぶんは 出さない）
    autoOff: x.kind !== 'family' && Array.isArray(x.char.autoOff) && x.char.autoOff.length ? x.char.autoOff : undefined,
    // 第71回: 命令の 一覧に 出さない 技（作戦の「命令で出す技を選ぶ」・呪文・技の メニュー。shared/cmd-off.js）
    cmdOff: x.kind !== 'family' && cmdOffList(x.char).length ? cmdOffList(x.char) : undefined,
    status: x.char.status?.poison ? ['poison'] : [],
  };
}

export function partyState(world, p) {
  if (!p) return null;
  // なかまは リーダーの ものがたりの 世界を 見る（人の いち・橋・とびら など）
  const lflags = world.sessions.get(p.leader)?.char?.flags || {};
  const worldFlags = Object.keys(lflags).filter((f) => lflags[f]);
  // 帰り道の羽・ルーラの 行き先も リーダーの 行った ことの ある 場所（world/travel.js の warpOwner）
  const lvisited = world.sessions.get(p.leader)?.char?.visited || {};
  return {
    id: p.id,
    leader: p.leader,
    worldFlags,
    worldVisited: Object.keys(lvisited).filter((k) => lvisited[k]),
    // リーダーの 宝の地図の まだ ほっていない 場所（手伝っている なかまの 画面でも 光らせる）
    worldTreasure: (world.sessions.get(p.leader)?.char?.treasureMaps || []).filter((t) => t && !t.found).map((t) => ({ map: t.map, x: t.x, y: t.y })),
    // リーダーの 目標（さそわれて 来ている 人の 画面に 出す）
    objective: world.sessions.get(p.leader)?.char?.objective || '',
    // パーティーの 時計（リーダーの 時間の ずれ。world/clock.js）
    clockShift: Number(world.sessions.get(p.leader)?.char?.timeShift) || 0,
    // 敵の 強さ（リーダーの 設定で 戦う。world/battles.js の enemyRateFor。設定の 画面に 出す）
    enemyRate: difficultyOf(world.sessions.get(p.leader)?.char).enemy,
    bond: p.bond,
    // ならび: 人（家族）の まとまりが なかまの 何番目に 入るか
    selfPos: selfPosOf(world, p),
    gateFlags: GATE_FLAGS.filter((f) => lflags[f]),
    members: p.members.map((sid) => {
      const m = world.sessions.get(sid);
      if (!m) return null;
      const st = computeStats(m.char);
      return { sid, charId: m.charId, name: m.char.name, job: m.char.job, level: m.char.level, hp: m.char.hp, maxHp: st.maxHp, mp: m.char.mp, maxMp: st.maxMp, st: statsOf(st), look: m.char.look, equip: m.char.equip, lookEquip: m.char.lookEquip, map: m.map, follow: !!m.follow, away: !!m.away, mjobs: masteredJobs(m.char) };
    }).filter(Boolean),
    supports: p.supports.map(supportInfo),
    // リーダーの 馬車の 仲間（馬車が なければ null。world/wagon.js）
    wagon: wagonState(world, p),
    guests: p.guests.map((g) => {
      const st = computeStats(g.char);
      return { id: g.id, name: g.char.name, job: g.char.job, level: g.char.level, look: g.char.look, equip: g.char.equip, hp: g.char.hp, maxHp: st.maxHp, mp: g.char.mp, maxMp: st.maxMp, st: statsOf(st) };
    }),
  };
}

