// 家族の パーティーで まものが なかまに なった とき、いっしょに 戦った 家族の 酒場にも 同じ しゅるいの まものを
//
// ・受け取る 人（今の しくみ: 戦いに 出ていた リーダー。いなければ 魔物に ふれた 人）は 今の まま
//   （パーティー → 馬車 → 酒場の じゅん。world.js の offerBefriend・scripts.js の 'befriend'）
// ・「はい」で 仲間に した ときだけ、その 戦いに 出ていた ほかの 家族（人）の キャラの 酒場に 入る
//   （パーティー・馬車は かえない。レベルは befriendLevel()・名前は その 人の 仲間と かさならない もの・＋値なし）
//   - 戦いに 出ていた 人 … 戦いの おわりの ctx.sids（とちゅうから かけつけた 人・馬車に 乗った 人・
//     通信が とぎれて オートで 戦っていた 人も）。同じ パーティーでも 戦いに 出ていない 人・オフラインの 人は 入らない
//   - 家族の キャラの「うつし」（サポートの 仲間）は 入れない（その 人は 遊んでいない。ひとりの 時と 同じに するため）
//   - 酒場が いっぱい（ROSTER_MAX）なら 入れない（今の しくみと 同じ。その 人に「いっぱいだった」と 知らせる）
// ・知らせ: 遊んでいる 人には その 場で（戦いの けっかを とじてから）。今 いない 人は c.tavernNews に のこし、
//   つぎに 入った ときに 出す（world.js の takeTavernNews）
import { MONSTERS } from '../data/monsters.js';
import { addMonsterEntry } from './party.js';
// 第50回 N6: 家族から もらった 道具の 知らせも 同じ 所に のこす（world/gift.js）
import { giftNewsText } from './gift.js';

export const TAVERN_NEWS_MAX = 10;

// 戦いに 出ていた 家族（人）の キャラの id（受け取る 人を のぞく。同じ キャラは 1回）
export function befriendShare(sessions, receiver) {
  const out = [];
  for (const m of sessions || []) {
    const id = m?.charId;
    if (!id || m === receiver || id === receiver?.charId || out.includes(id)) continue;
    out.push(id);
  }
  return out;
}

// 今 遊んでいる（知らせが とどく）セッション
function liveSession(world, charId) {
  for (const m of world.sessions.values()) if (m.charId === charId && m.inWorld && m.conn && !m.away) return m;
  return null;
}

// 知らせの 文
export function tavernNewsText(n) {
  if (n?.gift) return giftNewsText(n);
  const sp = MONSTERS[n?.species]?.name || '魔物';
  const who = String(n?.who || '');
  if (n?.full) return `${sp}が${who}の仲間にもなりたそうだったが、\n酒場がいっぱいで入れなかった…\n（酒場でだれかと別れると入れるよ）`;
  const name = String(n?.name || sp);
  return `${name}が、ルミナの町の酒場で待っている！\n（${n?.from ? `${n.from}といっしょに戦った` : ''}${sp}が、${who}の仲間にもなった）`;
}

// 「はい」で 仲間に なった あと: 家族の 酒場にも 入れる。もどりち: { got: [入った 人], full: [いっぱいだった 人], spName }
export function shareBefriend(world, s, species, level, share) {
  const got = [], full = [];
  const spName = MONSTERS[species]?.name || '';
  if (!Array.isArray(share) || !share.length || !spName) return { got, full, spName };
  const from = s?.char?.name || '';
  for (const id of share) {
    const c = world.data.characters[id];
    if (!c || c === s?.char) continue;
    const r = addMonsterEntry(c, species, level);
    if (!r.ok && !r.full) continue;
    const note = r.ok ? { species, name: r.name, from, who: c.name } : { species, from, who: c.name, full: true };
    (r.ok ? got : full).push(c.name);
    const m = liveSession(world, id);
    if (m) {
      world.send(m, { t: 'toast', text: tavernNewsText(note), afterBattle: true, sfx: r.ok ? 'join' : null });
      world.sendSelf(m);
    } else {
      const list = Array.isArray(c.tavernNews) ? c.tavernNews : [];
      c.tavernNews = [...list, note].slice(-TAVERN_NEWS_MAX);
    }
  }
  if (got.length || full.length) world.markDirty();
  return { got, full, spName };
}

// のこっている 知らせを 文に して けす（入った とき・つなぎなおした とき）
export function takeTavernNews(c) {
  if (!c || c.tavernNews === undefined) return [];
  const list = Array.isArray(c.tavernNews) ? c.tavernNews : [];
  delete c.tavernNews;
  return list.filter((n) => n && typeof n === 'object').map(tavernNewsText);
}

js/shared/world/salon.js:
// 美容室（かみがた・かみの色・目もと・はだの色を 変える）
// ・変えて よいのは style・hcol・face・tone だけ（体の 形・服の 色・職業は そのまま）
// ・代金は 1回 SALON_FEE ゴールド。何も 変えない ときは いらない
import { SALON_FEE, salonLook } from '../data/looks.js';
import { partyOf } from './party.js';

// 店に 入った とき（ui に わたす）
export function salonInfo(world, s) {
  s.openSalon = true;
  return { fee: SALON_FEE, keeper: '美容師のアンナ', look: s.char?.look || null };
}

// 変える（reply(ok, text, extra)）
export function salonAction(world, s, msg, reply) {
  const c = s.char;
  if (!c || c.species) return reply(false, '');
  if (!s.openSalon) return reply(false, '');
  const req = msg.look && typeof msg.look === 'object' ? msg.look : {};
  const r = salonLook(c.look, { style: req.style, hcol: req.hcol, face: req.face, tone: req.tone });
  if (!r.ok) return reply(false, r.reason);
  if (!r.changed) return reply(false, '今と同じ見た目ですね。', { look: c.look });
  if ((c.gold || 0) < SALON_FEE) return reply(false, 'おや？ゴールドが足りないようですね。', { look: c.look });
  c.gold -= SALON_FEE;
  c.look = r.look;
  // 家族の サポート仲間として 連れていかれている うつしも 新しい すがたに
  for (const p of world.parties?.values?.() || []) {
    let changed = false;
    for (const x of p.supports || []) {
      if (x.kind === 'family' && x.char && (x.char.id === c.id || x.char.ownerId === c.id)) { x.char.look = { ...c.look }; changed = true; }
    }
    if (changed) world.sendParty(p);
  }
  // まわりの 人には いつもの いち（snap）で 新しい すがたが とどく
  const p = partyOf(world, s);
  if (p) world.sendParty(p);
  return reply(true, 'はい、できあがり！\nよくお似合いですよ。', { look: c.look, fee: SALON_FEE });
}

js/shared/world/save.js:
// セーブデータの バージョンと ひきつぎ
//
// やくそく（これからも ずっと まもる こと）
// ・あたらしい ゲームは、むかしの セーブを かならず 読める。形を かえた ときは UPGRADES に 手順を たす
// ・知らない 項目や 知らない 品物・職業・モンスターは けさずに とっておく（stash）。
//   あとで その ゲームが 知っている ものに なったら もとに もどす
// ・品物・職業・モンスター・マップの ID は けさない・なまえを かえない
import { repairGearFx } from '../data/gear-fx.js';
import { ITEMS, SLOTS } from '../data/items.js';
import { JOBS } from '../data/jobs.js';
import { MONSTERS } from '../data/monsters.js';
import { migrateJobs, oldComboUnlocks, addItem, fixBodyJob } from '../stats.js';
import { repairTreasureMaps } from '../data/treasure.js';
import { ensureTmClears } from '../data/casino-tier.js';
import { repairSecret } from '../data/secret.js';
import { repairAlchemy } from './alchemy.js';
import { normBank } from './bank.js';
import { cleanWagon } from '../data/wagon.js';
import { cleanLookEquip } from '../look-equip.js';
import { cleanVehicles } from '../data/vehicles.js';
import { repairTrialInfo } from '../data/job-trials.js';
import { cleanQuick } from '../data/quick-item.js';
import { repairSubAsk } from '../data/subquest-hints.js';
import { cleanStamps } from '../data/stamps.js';
import { cleanFamilyBoard, cleanBoardSeen } from './family-board.js';
import { repairFeats } from './phantom.js';
// 第67回 B: モンスター闘技場の 記録
import { repairMonArena } from '../data/monarena.js';

export const SAVE_VERSION = 4;

const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
const num = (v, d = 0) => (Number.isFinite(v) ? v : d);
// 'constructor' などを 品物や 職業と まちがえない
const known = (table, id) => typeof id === 'string' && Object.prototype.hasOwnProperty.call(table, id);

// バージョンごとの 手順（from の バージョンから 1つ 上げる）
const UPGRADES = {
  // 1 → 2: 職業レベル（勝った 数）・仲間・ゲスト・第2章。1人ずつの 手直しは repairChar が する
  1: (d) => {
    for (const c of Object.values(d.characters)) migrateJobs(c);
  },
  // 2 → 3: 掛け合わせ技は「ひらめき」で 覚える きまりに なった。
  //        今まで 覚えていた 掛け合わせ技は、ひらめいた 技として のこす（仲間・ゲストも）
  2: (d) => {
    const keep = (c) => {
      if (!c || typeof c !== 'object' || c.species) return;
      const had = oldComboUnlocks(c);
      const list = Array.isArray(c.hirameki) ? c.hirameki : [];
      c.hirameki = [...new Set([...list, ...had])];
    };
    for (const c of Object.values(d.characters)) {
      keep(c);
      for (const e of Array.isArray(c?.companions) ? c.companions : []) keep(e?.char);
      for (const g of Array.isArray(c?.guests) ? c.guests : []) keep(g?.char);
    }
  },
  // 3 → 4: ボスが かならず 物を 落とす ように なった。もう たおした ボスの ぶんを わたす
  //        （ふくろ・装備・仲間の 装備に もう あれば わたさない）
  3: (d) => {
    const BOSS = [['c1_treant', 'dark_treant', 'forest_necklace'], ['c1_boss', 'goldoon', 'rock_bangle'],
      ['c2_kraken', 'giant_squid', 'deep_ring'], ['c2_boss', 'storm_general', 'storm_bangle']];
    for (const c of Object.values(d.characters)) {
      if (!c || typeof c !== 'object' || !c.flags || typeof c.flags !== 'object') continue;
      const have = (id) => (Array.isArray(c.items) && c.items.some((e) => e?.id === id))
        || Object.values(obj(c.equip)).includes(id)
        || (Array.isArray(c.companions) && c.companions.some((e) => Object.values(obj(e?.char?.equip)).includes(id)));
      for (const [flag, boss, id] of BOSS) {
        if (!c.flags[flag] || have(id)) continue;
        if (!Array.isArray(c.items)) c.items = [];
        addItem(c, id, 1);
        c.bestiary = obj(c.bestiary);
        c.bestiary[boss] = { ...obj(c.bestiary[boss]), [`drop_${id}`]: 1 };
      }
    }
  },
};

// 知らない ものを しまう・知っている ものに なったら もどす
function stashOf(c) {
  c.stash = obj(c.stash);
  c.stash.items = Array.isArray(c.stash.items) ? c.stash.items : [];
  c.stash.keyItems = Array.isArray(c.stash.keyItems) ? c.stash.keyItems : [];
  c.stash.companions = Array.isArray(c.stash.companions) ? c.stash.companions : [];
  return c.stash;
}

function cleanStash(c) {
  const st = c.stash;
  if (st && !st.items.length && !st.keyItems.length && !st.companions.length && !st.job && !st.storage?.length) delete c.stash;
}

// 1人ぶんを 読める 形に ととのえる（何回 よんでも おなじ けっか）
export function repairChar(c, id) {
  if (!c || typeof c !== 'object') return null;
  if (!c.id && id) c.id = id;
  c.name = typeof c.name === 'string' && c.name ? c.name : '勇者';
  repairGearFx(c); // 第64回 ⑥c: れん金で つけた 装備の 効果
  c.level = Math.max(1, Math.floor(num(c.level, 1)));
  c.exp = Math.max(0, num(c.exp, 0));
  c.gold = Math.max(0, Math.floor(num(c.gold, 0)));
  c.hp = num(c.hp, 1);
  c.mp = num(c.mp, 0);
  for (const k of ['flags', 'chests', 'kills', 'quests', 'seeds', 'status', 'visited']) c[k] = obj(c[k]);
  // 技を 使った 回数・ひらめいた 技（知らない 技も けさずに のこす）
  c.skillUse = Object.fromEntries(Object.entries(obj(c.skillUse)).filter(([, v]) => Number.isFinite(v) && v > 0));
  c.hirameki = Array.isArray(c.hirameki) ? [...new Set(c.hirameki.filter((x) => typeof x === 'string'))] : [];
  // 第51回 F: 幻の職業の 記録（ある 人だけ。引っこしの みじかい 形も もどす。world/phantom.js）
  repairFeats(c);
  if (!c.species && !Object.keys(c.visited).length) c.visited.village = true;
  const st = stashOf(c);

  // ふくろ（おなじ 品物は まとめる。知らない 品物は しまう）
  const bag = new Map();
  const put = (e) => {
    if (!e || typeof e.id !== 'string') return;
    const n = Math.max(0, Math.floor(num(e.n, 1)));
    if (!n) return;
    if (known(ITEMS, e.id)) bag.set(e.id, (bag.get(e.id) || 0) + n);
    else st.items.push({ id: e.id, n });
  };
  for (const e of Array.isArray(c.items) ? c.items : []) put(e);
  const unknown = st.items.splice(0);
  for (const e of unknown) put(e);
  c.items = [...bag].map(([iid, n]) => ({ id: iid, n }));

  // だいじな もの
  const keys = [...(Array.isArray(c.keyItems) ? c.keyItems : []), ...st.keyItems.splice(0)];
  c.keyItems = [];
  for (const k of keys) {
    if (typeof k !== 'string' || c.keyItems.includes(k) || st.keyItems.includes(k)) continue;
    (known(ITEMS, k) ? c.keyItems : st.keyItems).push(k);
  }

  // 預かり所（ある ときだけ。知らない 品物も 預けた まま のこす）
  if (c.bank !== undefined) c.bank = normBank(c.bank);

  // そうび（知らない そうびは ふくろの かわりに しまう）
  c.equip = obj(c.equip);
  for (const slot of SLOTS) {
    const eid = c.equip[slot];
    if (eid && !known(ITEMS, eid)) {
      st.items.push({ id: eid, n: 1 });
      c.equip[slot] = null;
    } else if (!eid) c.equip[slot] = null;
  }
  // 見た目装備（ない ことも ある。新しい 項目なので 版は 上げない。shared/look-equip.js）
  cleanLookEquip(c);
  // 乗り物（第37回。ない ことも ある。新しい 項目なので 版は 上げない。data/vehicles.js）
  if (!c.species) cleanVehicles(c);
  // 第50回 N3: 大事な物の すぐ使う ボタン（ない ことも ある。新しい 項目なので 版は 上げない。data/quick-item.js）
  cleanQuick(c);
  // 第50回 N7: チャットの スタンプ（ない ことも ある。新しい 項目なので 版は 上げない。data/stamps.js）
  cleanStamps(c);
  // 第51回 B: 家族のけいじ板を さいごに 見た 時こく（ない ことも ある。新しい 項目なので 版は 上げない。world/family-board.js）
  cleanBoardSeen(c);

  // 職業（知らない 職業なら 戦士に して、もとの 職業を おぼえておく）
  if (!c.species) {
    if (!known(JOBS, c.job)) {
      if (c.job && !st.job) st.job = c.job;
      c.job = 'warrior';
    } else if (st.job && known(JOBS, st.job)) {
      c.job = st.job;
      delete st.job;
    }
    c.jobs = obj(c.jobs);
    if (!c.jobs[c.job]) c.jobs[c.job] = { lv: 1, b: 0 };
    // 第38回 B: 職業レベルの 上限と 職業の試練の 項目（tr・tq・tn。古い セーブには ない。版は 上げない。data/job-trials.js）
    // （職業レベルが 1〜20 だった とても 古い しくみ〈jobSys が 2 で ない〉は、あとの migrateJobs が 1〜10 に なおす ので さわらない）
    if (c.jobSys === 2) for (const [jid, info] of Object.entries(c.jobs)) if (known(JOBS, jid) && info && typeof info === 'object') repairTrialInfo(jid, info);
  }

  // 仲間（知らない モンスターは しまう）
  if (Array.isArray(c.companions) || st.companions.length) {
    const all = [...(Array.isArray(c.companions) ? c.companions : []), ...st.companions.splice(0)];
    c.companions = [];
    for (const e of all) {
      if (!e || !e.key || !e.char) continue;
      if (e.kind === 'monster' && !known(MONSTERS, e.species || e.char.species)) st.companions.push(e);
      else {
        repairChar(e.char);
        c.companions.push(e);
      }
    }
  }
  // 魔物あずかり所（第43回 C。ない ときは そのまま〈空と 同じ〉。知らない モンスターは しまう。新しい 項目なので 版は 上げない）
  if (Array.isArray(c.storage) || st.storage?.length) {
    const all = [...(Array.isArray(c.storage) ? c.storage : []), ...(Array.isArray(st.storage) ? st.storage.splice(0) : [])];
    c.storage = [];
    for (const e of all) {
      if (!e || !e.key || !e.char) continue;
      if (!known(MONSTERS, e.species || e.char.species)) (st.storage = Array.isArray(st.storage) ? st.storage : []).push(e);
      else {
        repairChar(e.char);
        c.storage.push(e);
      }
    }
    if (Array.isArray(st.storage) && !st.storage.length) delete st.storage;
  }
  repairTreasureMaps(c); // 宝の地図（なくても よい）
  // 第37回 B: 宝の地図の クリア数（カジノの 段）。むかしの セーブは 1回だけ のこっている きろくから 数える（版は 上げない）
  if (id && !c.species) ensureTmClears(c);
  repairSecret(c); // ひみつのダンジョンの 記録（なくても よい。新しい 項目なので 版は 上げない）
  repairAlchemy(c); // れん金がま（第32回。なくても よい）・もう たおした ボスの 品
  repairMonArena(c); // 第67回 B: モンスター闘技場の 記録（なくても よい。data/monarena.js）
  repairSubAsk(c); // 第50回 N4: 困っている人を 知らせた・見た 印（なくても よい。新しい 項目なので 版は 上げない）
  // 馬車の 仲間（いなくなった 仲間の key は はずす）
  cleanWagon(c);
  cleanStash(c);
  return c;
}

// セーブ ぜんたいを 読める 形に（知らない 項目は そのまま のこす）
export function upgradeSave(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const hasChars = src.characters && typeof src.characters === 'object';
  const from = Number.isFinite(src.version) ? src.version : hasChars ? 1 : SAVE_VERSION;
  const d = { ...src };
  d.characters = hasChars ? { ...src.characters } : {};
  d.board = Array.isArray(src.board) ? src.board : [];
  // 第51回 B: 家族のけいじ板（自動の 知らせ。world/family-board.js）
  d.familyBoard = cleanFamilyBoard(src.familyBoard);
  d.createdAt = src.createdAt || Date.now();
  for (let v = from; v < SAVE_VERSION; v++) UPGRADES[v]?.(d);
  for (const [id, c] of Object.entries(d.characters)) {
    if (!repairChar(c, id)) delete d.characters[id];
    else {
      migrateJobs(c);
      // 体で なれない 職業（フルーツジッパー・アラシ）に なっていたら もとに もどす
      fixBodyJob(c);
      for (const e of Array.isArray(c.companions) ? c.companions : []) fixBodyJob(e?.char);
    }
  }
  // あたらしい ゲームで 作った セーブを 読んだ ときは、バージョンを 下げない
  d.version = Math.max(from, SAVE_VERSION);
  return { data: d, from };
}

