// だいほん（イベント）を すすめる しくみ
import { SCRIPTS, STORY_STEPS, STORY_SCRIPTS } from '../data/story.js';
import { ITEMS } from '../data/items.js';
import { addItem, removeItem, itemCount, hasKeyItem, fullHeal } from '../stats.js';
import { startFixedBattle } from './battles.js';
import { FIXED_ENCOUNTERS } from '../data/encounters.js';
import { partyOf, syncParty, ensureCompanions, recruitNpc, addMonsterCompanion, befriendLevel } from './party.js';
import { sayFarewell } from './farewell.js';
// 第43回 C: 仲間が いっぱいの 時の えらぶ文・配合して あける・あずかり所へ 送る（world/farewell.js・world/storage.js）
import { befriendFullSteps, rosterIsFull } from './farewell.js';
import { depositMonster, storeText } from './storage.js';
import { tavernInfo, ensureStorage } from './party.js';
import { MONSTERS } from '../data/monsters.js';
import { shareBefriend } from './recruit-share.js';
import { openService } from './services.js';
import { isNightFor, advanceClock, fracFor } from './clock.js';
import { grantWagon, wagonChars, wagonHere } from './wagon.js';
import { GUESTS } from '../data/shops.js';
import { unstickAll } from './hazards.js';
import { MAPS, isBlocked } from '../maps/index.js';
// 第44回（ポケモン P1）: 魔物の 進化（world/evolve.js）
import { pendingEvolve, evolveAskSteps, evolveScriptStep } from './evolve.js';

let runSeq = 1;

// だいほんに わたす じょうほう
//  s … 話しかけた 人 / owner … その 世界の もちぬし（さそわれて 手伝っている ときは リーダー）
//  ものがたりの すすみぐあい（フラグ・大事な物・たのまれごと）は owner、ふつうの 道具は 話しかけた 人
//  night … 夜か（パーティーの 時計。world/clock.js）/ helper … さそわれて 手伝っている 人
//  clock … 1日の わりあい（パーティーの 時計。0 が 朝6時。第4章の 日時計の とびら。ない ときは null）
export function scriptCtx(s, owner = s, world = null) {
  const c = s.char;
  const o = owner.char;
  return {
    c,
    name: c.name,
    night: world ? isNightFor(world, owner) : false,
    clock: world ? fracFor(world, owner) : null,
    helper: s !== owner,
    flag: (f) => !!o.flags[f],
    has: (id) => hasKeyItem(o, id) || (ITEMS[id]?.type !== 'key' && itemCount(c, id) > 0),
    count: (id) => (ITEMS[id]?.type === 'key' ? (hasKeyItem(o, id) ? 1 : 0) : itemCount(c, id)),
    kills: (sp) => o.kills?.[sp] || 0,
    quest: (k) => o.quests?.[k],
    // いっしょに 戦う 人の キャラ（自分・家族・パーティーの 仲間。馬車の 仲間は 入れない）。
    // ひらめきの賢者が、パーティーに 関係する 技の ヒントだけ 話す ため（stats.js の partyJobSet）
    partyChars: () => fightingChars(world, s),
  };
}

function fightingChars(world, s) {
  const p = world && s ? partyOf(world, s) : null;
  if (!p) return [s.char];
  const out = [s.char];
  for (const sid of p.members) {
    const m = world.sessions.get(sid);
    if (m?.char && m.char !== s.char) out.push(m.char);
  }
  for (const x of p.supports) if (x?.char) out.push(x.char);
  return out;
}

// ものがたりの すすみぐあい（STORY_STEPS の なんばんめまで おわったか。まだなら -1）
export function storyIndex(c) {
  let idx = -1;
  STORY_STEPS.forEach((f, i) => {
    if (c?.flags?.[f]) idx = i;
  });
  return idx;
}

export function setStoryFlag(c, f) {
  c.flags[f] = true;
  const i = STORY_STEPS.indexOf(f);
  if (i > 0) for (let j = 0; j < i; j++) c.flags[STORY_STEPS[j]] = true;
}

export class ScriptRun {
  constructor(world, initiator, participants, steps, meta = {}) {
    this.id = 'r' + (runSeq++);
    this.world = world;
    this.init = initiator;
    // ものがたりが すすむ 人（ふつうは はじめた 人。さそわれて 手伝っている 人が はじめた ときは リーダー）
    this.owner = meta.owner || initiator;
    this.parts = participants;
    this.steps = steps;
    this.meta = meta;
    this.batch = [];
    this.waiting = null;
    this.aborted = false;
  }

  get everyone() { return this.parts.filter((m) => this.world.sessions.has(m.id)); }

  // パーティーの イベントは リーダー（さそった 人）の ものがたり（this.owner）。
  // さそわれて 来ている なかまの ものがたり（フラグ・目標・大事な物・ゲスト・いのりの場所）は かえない。
  // ごほうび（ゴールド・ふつうの 道具・たたかいの 経験値）は みんなで もらえる

  async start() {
    for (const m of this.everyone) {
      m.busy = 'script';
      m.runId = this.id;
    }
    this.world.runs.set(this.id, this);
    try {
      await this.runSteps(this.steps);
      await this.flush();
    } catch (e) {
      if (!this.aborted) console.error('script error', e);
    }
    // おわりの かたづけで エラーが おきても、うごけなく ならない ように する
    // （ここで エラーが 出ると、Promise の エラーで 家族サーバーが 止まる おそれが あった）
    try {
      this.finish();
    } catch (e) {
      console.error('script finish error', e);
      this.world.runs.delete(this.id);
      for (const m of this.parts) {
        if (m.runId !== this.id) continue;
        m.runId = null;
        if (m.busy === 'script') m.busy = null;
      }
    }
  }

  finish() {
    this.world.runs.delete(this.id);
    // 第44回: 台本が おわったら、進化を まっている 仲間が いないか 見る（world.js の tick。checkEvolve）
    if (!this.aborted) for (const m of this.everyone) m.evoCheck = true;
    // リーダーの ものがたりが すすんだら、なかまの 画面の 世界（人・橋 など）も あわせる
    const p = partyOf(this.world, this.owner);
    if (p && p.members.length > 1) this.world.sendParty(p);
    for (const m of this.everyone) {
      if (m.runId === this.id) {
        m.runId = null;
        if (m.busy === 'script') m.busy = null;
        this.world.send(m, { t: 'scriptEnd', runId: this.id });
        this.world.sendSelf(m);
      }
    }
    // 手伝いの 人が リーダーの 世界を かえた（レバー など）: リーダーの 画面も あわせる
    if (this.owner !== this.init && !this.everyone.includes(this.owner) && this.world.sessions.has(this.owner.id)) this.world.sendSelf(this.owner);
    this.world.markDirty();
  }

  abort() {
    this.aborted = true;
    if (this.waiting) {
      const w = this.waiting;
      this.waiting = null;
      w.resolve({ aborted: true });
    }
  }

  // うけとった へんじ
  ack(s, msg) {
    if (!this.waiting) return;
    if (s.id !== this.init.id) return;
    const w = this.waiting;
    this.waiting = null;
    w.resolve(msg);
  }

  flush() {
    if (!this.batch.length) return Promise.resolve({});
    const steps = this.batch;
    this.batch = [];
    this.lastSteps = steps;
    for (const m of this.everyone) {
      this.world.send(m, { t: 'script', runId: this.id, steps, spectator: m.id !== this.init.id, who: this.init.char.name });
    }
    if (!this.world.sessions.has(this.init.id)) return Promise.resolve({ aborted: true });
    return new Promise((resolve) => { this.waiting = { resolve }; });
  }

  // つなぎなおした 人に、いま まっている ところを もういちど おくる
  resend(m) {
    if (!this.waiting || !this.lastSteps) return;
    this.world.send(m, { t: 'script', runId: this.id, steps: this.lastSteps, spectator: m.id !== this.init.id, who: this.init.char.name });
  }

  // パーティーの いま（だいほんの 'call' から つかう。第3章の きずなの間）
  //  people: いっしょに いる 人（セッション）/ helpers: サポート・ゲスト・馬車の なかまの キャラ
  partyNow() {
    const w = this.world;
    const p = partyOf(w, this.init);
    const people = (p ? p.members : [this.init.id]).map((id) => w.sessions.get(id)).filter(Boolean);
    const helpers = p ? [...p.supports.map((x) => x.char), ...p.guests.map((g) => g.char), ...wagonChars(w, p)].filter(Boolean) : [];
    return { people, helpers };
  }

  say(text, who = null) {
    this.batch.push(['say', who, text]);
  }

  who() {
    return this.everyone.length > 1 ? `${this.init.char.name}たち` : this.init.char.name;
  }

  async runSteps(steps) {
    const w = this.world;
    for (const step of steps) {
      if (this.aborted) return;
      const [op, ...a] = step;
      const all = this.everyone;
      switch (op) {
        case 'if': {
          const ok = a[0](scriptCtx(this.init, this.owner, w));
          await this.runSteps(ok ? a[1] || [] : a[2] || []);
          break;
        }
        case 'choice': {
          // a[3] … えらぶ 物ごとの せつめい（なくても よい。第65回 お仕事いらい板: カーソルを 合わせた はり紙の 職業・ごほうび）
          // a[4] … 第76回: お仕事いらい板の はり紙（大きな まどで 見せる 中み。sidequests-family.js の boardPaper）
          if (a[4] && typeof a[4] === 'object') this.batch.push(['choice', a[0], a[1], Array.isArray(a[3]) ? a[3] : null, a[4]]);
          else this.batch.push(Array.isArray(a[3]) ? ['choice', a[0], a[1], a[3]] : ['choice', a[0], a[1]]);
          const r = await this.flush();
          if (r.aborted) return this.abort();
          const idx = Math.max(0, Math.min(a[1].length - 1, Number(r.choice) || 0));
          await this.runSteps(a[2][idx] || []);
          break;
        }
        case 'flag':
          setStoryFlag(this.owner.char, a[0]);
          break;
        case 'unflag':
          // フラグを もどす（しかけの やりなおし など。ものがたりの すすみぐあいの フラグには つかわない）
          delete this.owner.char.flags[a[0]];
          break;
        case 'toggle': {
          // レバー: フラグを 入れかえる。かわった マスに 立っている 人は となりへ よける（world/hazards.js）
          const c = this.owner.char;
          if (c.flags[a[0]]) delete c.flags[a[0]];
          else c.flags[a[0]] = true;
          unstickAll(w, this.owner);
          break;
        }
        case 'sync': {
          // ここまでの えんしゅつを 見せてから、フラグの かわった 世界（とびら・橋）を 画面に 出す
          const r = await this.flush();
          if (r.aborted) return this.abort();
          for (const m of this.everyone) w.sendSelf(m);
          if (!this.everyone.includes(this.owner)) w.sendSelf(this.owner);
          const p = partyOf(w, this.owner);
          if (p && p.members.length > 1) w.sendParty(p);
          break;
        }
        case 'questBase': {
          const c = this.owner.char;
          c.quests = c.quests || {};
          c.quests[a[0]] = c.kills?.[a[1]] || 0;
          break;
        }
        case 'item': {
          const [id, n = 1] = a;
          // 大事な物は ものがたりの もちぬし（リーダー）だけ（なかまの ものがたりは かえない）
          const key = ITEMS[id]?.type === 'key';
          if (key) addItem(this.owner.char, id, n);
          else for (const m of all) addItem(m.char, id, n);
          const name = ITEMS[id]?.name || id;
          this.batch.push(['sfx', key ? 'key' : 'item']);
          this.say(`${key ? this.owner.char.name : this.who()}は${name}${n > 1 ? `を${n}個` : 'を'}手に入れた！`);
          break;
        }
        case 'takeItem': {
          // 大事な物は もちぬしから、ふつうの 道具は 話しかけた 人から
          const [id, n = 1] = a;
          if (ITEMS[id]?.type === 'key') this.owner.char.keyItems = this.owner.char.keyItems.filter((k) => k !== id);
          else removeItem(this.init.char, id, n);
          break;
        }
        case 'gold':
          for (const m of all) m.char.gold += a[0];
          this.batch.push(['sfx', 'item']);
          this.say(`${this.who()}は${a[0]}ゴールドを手に入れた！`);
          break;
        case 'objective': {
          this.owner.char.objective = a[0];
          this.batch.push(['objective', a[0]]);
          // なかまの 画面にも リーダーの 目標を 出す
          const p = partyOf(w, this.owner);
          if (p && p.members.length > 1) w.sendParty(p);
          break;
        }
        case 'heal': {
          // ['heal', { mp: 0.3 }] … HPは ぜんぶ、MPは さいだいの 3わり だけ ふえる（大臣ザイードの あとの 月の光）
          const [opt] = a;
          const heal = (ch) => {
            const mp = ch.mp;
            fullHeal(ch);
            if (opt?.mp !== undefined && Number.isFinite(mp)) ch.mp = Math.min(ch.mp, mp + Math.round(ch.mp * opt.mp));
          };
          for (const m of all) heal(m.char);
          const p = partyOf(w, this.init);
          for (const sup of p?.supports || []) heal(sup.char);
          for (const g of p?.guests || []) heal(g.char);
          for (const ch of wagonChars(w, p)) heal(ch);
          for (const m of all) w.sendSelf(m);
          if (p) w.sendParty(p);
          break;
        }
        case 'inn': {
          // ['inn', ねだん, 宿屋の人, 'morning'|'night'|'noon']（ねだん 0 は 家の ベッド。宿屋は ふつう 朝まで。昼までは 王都サファラの 宿屋）
          const price = a[0] || 0;
          const keeper = a[1] || null;
          const until = a[2] || (price ? 'morning' : null);
          const c = this.init.char;
          if (c.gold < price) {
            this.say('おや？ゴールドが足りないようですね。', keeper);
            break;
          }
          c.gold -= price;
          for (const m of all) fullHeal(m.char);
          const p = partyOf(w, this.init);
          for (const sup of p?.supports || []) fullHeal(sup.char);
          for (const g of p?.guests || []) fullHeal(g.char);
          for (const ch of wagonChars(w, p)) fullHeal(ch);
          if (price) this.say('では、ごゆっくりお休みください。', keeper);
          this.batch.push(['fade', 'out'], ['bgm', 'inn'], ['wait', 2200]);
          // 時間を すすめる（パーティーの 時計。さそわれて 手伝っている 人は かえない）
          if (until && this.owner === this.init) this.batch.push(['clock', advanceClock(w, this.init, until)]);
          this.batch.push(['bgm', 'resume'], ['fade', 'in']);
          if (price && until === 'night') {
            this.say('こんばんは。\nよくお休みになれましたか？', keeper);
            this.say('HPとMPがすっかり回復した！');
            this.say('外はもう夜です。夜は魔物が強くなりますから、お気を付けて。', keeper);
          } else if (price && until === 'noon') {
            this.say('おはようございます…と言っても、\nもうすぐお昼ですよ。ずいぶん、よくおねむりでしたね。', keeper);
            this.say('HPとMPがすっかり回復した！');
            this.say('日が高くなってきました。では、いってらっしゃいませ。', keeper);
          } else if (price) {
            this.say('おはようございます。\nゆうべは、よくねむれましたか？', keeper);
            this.say('HPとMPがすっかり回復した！');
            this.say('では、いってらっしゃいませ。', keeper);
          } else {
            this.say('{name}はぐっすりねむった。');
            this.say('HPとMPがすっかり回復した！');
          }
          for (const m of all) w.sendSelf(m);
          if (p) w.sendParty(p);
          // 宿屋で ねたら すぐ セーブ（ドラクエと おなじ 安心感）
          w.markDirty();
          w.saveNow({ urgent: true });
          break;
        }
        case 'guest': case 'unguest': {
          // ゲストは セーブデータに のこす（アプリを おとしても いなくならない）。リーダーだけ
          // ['guest', id] くわわる / ['guest', null] みんな はなれる / ['unguest', id] その 人だけ はなれる
          const gc = this.owner.char;
          ensureCompanions(gc);
          const before = gc.guests.slice();
          if (op === 'guest' && a[0]) {
            if (!gc.guests.includes(a[0])) gc.guests.push(a[0]);
          } else if (op === 'unguest') gc.guests = gc.guests.filter((g) => g !== a[0]);
          else gc.guests = [];
          const left = before.filter((g) => !gc.guests.includes(g));
          if (left.length) {
            this.batch.push(['sfx', 'leave']);
            this.say(`${left.map((g) => GUESTS[g]?.name || g).join('と')}はパーティーからはなれた。`);
          }
          const p = partyOf(w, this.owner);
          if (p) {
            syncParty(w, p);
            w.sendParty(p);
          }
          w.markDirty();
          break;
        }
        case 'recruit': {
          // ものがたりで なかまに なる（パーティーが いっぱいなら 酒場で まつ）。リーダーだけ
          const r = recruitNpc(w, this.owner, a[0], { force: true });
          if (r.ok) {
            this.batch.push(['sfx', 'join']);
            this.say(r.joined ? `${r.name}が仲間に加わった！${r.where === 'wagon' ? `\n${r.name}は馬車に乗りこんだ。` : ''}` : `${r.name}が仲間になった！\n（今はルミナの町の酒場で待っている）`);
          }
          break;
        }
        case 'wagon': {
          // 馬車を もらう（話しかけた 人の もの。data/wagon.js）
          grantWagon(this.init.char);
          const p = partyOf(w, this.init);
          if (p) w.sendParty(p);
          w.sendSelf(this.init);
          w.markDirty();
          break;
        }
        case 'befriend': {
          // たおした まものが なかまに なる（a[1]: 酒場へ もどる なかま / false: ことわった）
          const s = this.init;
          const off = s.befriendOffer;
          if (!off || off.id !== a[0]) break;
          s.befriendOffer = null;
          if (a[1] === false) break;
          // 仲間が いっぱいの ときは a[2] の 仲間と さよならしてから（world/farewell.js）
          if (a[2]) this.say(sayFarewell(w, s, a[2]));
          // a[3] の 魔物を あずかり所へ 送ってから（world/storage.js。第43回 C）
          if (a[3]) this.say(storeText(depositMonster(w, s, a[3])));
          // たたかいで なかまに なった まものは いつも レベル1（party.js の befriendLevel）
          const r = addMonsterCompanion(w, s, off.species, befriendLevel(), a[1]);
          if (!r.ok) {
            this.say(r.reason);
            break;
          }
          this.batch.push(['sfx', 'join']);
          if (r.where === 'wagon') {
            // パーティーが いっぱいで 馬車が あいていた（洞窟の 中では 馬車は 入り口で 待っている）
            this.say(wagonHere(s.map) ? `${r.name}が仲間に加わった！\n${r.name}は馬車に乗りこんだ！` : `${r.name}が仲間に加わった！\n${r.name}は入り口で待つ馬車へ向かった！`);
          } else if (r.joined) this.say(`${r.name}が仲間に加わった！`);
          else this.say(`${r.name}が仲間になった！\n${r.name}はルミナの町の酒場で待っている。`);
          if (r.benchedName) this.say(`${r.benchedName}は酒場へもどった。${r.stowed?.length ? '\n（装備はふくろにしまった）' : ''}`);
          this.say(`（名前は酒場で変えられるよ）`);
          // 家族の パーティー: いっしょに 戦った 家族の 酒場にも 入る（world/recruit-share.js）
          const sh = shareBefriend(w, s, off.species, befriendLevel(), off.share);
          if (sh.got.length) this.say(`いっしょに戦った${sh.got.join('と')}の酒場にも、\n${sh.spName}が仲間になってくれた！`);
          if (sh.full.length) this.say(`${sh.full.join('と')}の酒場はいっぱいで、\n${sh.spName}は入れなかった…`);
          w.sendSelf(s);
          break;
        }
        case 'evolve': case 'evolveStop': {
          // 第44回: 魔物の 進化（['evolve', 仲間の key, 進化した すがた] … みまもる / ['evolveStop', key] … とめる。world/evolve.js）
          for (const st of evolveScriptStep(w, this.init, op, a[0], a[1])) this.batch.push(st);
          break;
        }
        case 'befriendFull': case 'breedOpen': {
          // 第43回 C: 仲間が いっぱいの 時（world/farewell.js の befriendFullSteps）
          //   ['befriendFull', id] … えらぶ文に もどる / ['breedOpen', id] … 酒場の 配合の 画面を「あける モード」で 開く
          //   配合が すんで 1つ あいたら、まっていた 魔物が 仲間に なる。とじたら（やめたら）えらぶ文に もどる
          //   この 台本は なつかれた 人だけ（world.js の offerBefriend の runSteps）なので、家族の ほかの 人には 画面は 出ない
          const s = this.init;
          const off = s.befriendOffer;
          if (!off || off.id !== a[0]) break;
          const name = MONSTERS[off.species]?.name || '';
          let bred = false;
          if (op === 'breedOpen' && rosterIsFull(s.char)) {
            const before = s.char.companions.length + ensureStorage(s.char).storage.length;
            const r = await this.flush();
            if (r.aborted) return this.abort();
            this.batch.push(['ui', 'tavern', { ...tavernInfo(w, s), makeRoom: { name } }]);
            const r2 = await this.flush();
            if (r2.aborted) return this.abort();
            if (s.befriendOffer !== off) break;
            bred = s.char.companions.length + ensureStorage(s.char).storage.length < before;
          }
          if (!rosterIsFull(s.char)) {
            await this.runSteps([['befriend', off.id, null]]);
            break;
          }
          // あずかり中の 2ひきで 配合した 時は、仲間は あかない
          if (bred) this.say('あずかり中の魔物どうしの配合では、仲間はあかない…');
          await this.runSteps(befriendFullSteps(s.char, off.id, name, true));
          break;
        }
        case 'battle': {
          const r = await this.flush();
          if (r.aborted) return this.abort();
          const res = await startFixedBattle(w, this.init, this.everyone, a[0]);
          // 負けても よい 戦い（loseOk）は 負けても 物語が つづく
          if (res !== 'win' && !(res === 'lose' && FIXED_ENCOUNTERS[a[0]]?.loseOk)) return this.abort();
          break;
        }
        case 'call':
          // ほかの しくみの しょり（宝の地図など）。a[0](run) を まつ
          await a[0](this);
          break;
        case 'teleport': {
          const [map, x, y, dir] = a;
          const offs = [[0, 0], [-1, 0], [1, 0], [0, 1], [-1, 1], [1, 1]];
          const dest = MAPS[map];
          const has = w.hasFlagFn(this.owner);
          // かべの 中には おかない（ふさがって いたら まん中に）
          const pos = all.map((m, i) => {
            const [ox, oy] = offs[i % offs.length];
            return !dest || isBlocked(dest, Math.floor(x + ox), Math.floor(y + oy), has) ? [x, y] : [x + ox, y + oy];
          });
          const from = { map: this.init.map, x: this.init.x, y: this.init.y };
          all.forEach((m, i) => w.placeSession(m, map, pos[i][0], pos[i][1], dir || m.dir, false));
          // 「ついていく」なかまも いっしょに（トロッコ・船 など。だいほんに 入っていない 人）
          if (all.includes(this.init)) w.warpFollowers(this.init, from.map, from.x, from.y, { map, x, y, dir: dir || 'down' });
          // それぞれの いちを つたえる
          this.batch.push(['teleport', map, x, y, dir || 'down', all.map((m, i) => [m.id, pos[i][0], pos[i][1], m.posSeq])]);
          break;
        }
        case 'spawn': {
          const [map, x, y] = a;
          this.owner.char.spawn = { map, x, y, ...(MAPS[map]?.layoutVer ? { lv: MAPS[map].layoutVer } : {}) };
          break;
        }
        case 'curse': {
          // のろいの宝（第4章の 王家のピラミッド）: いっしょに いる みんなに のろい。ピラミッドの 外に 出ると とける（world/pyramid.js）
          for (const m of all) {
            if (a[0]) m.char.pyrCurse = true;
            else delete m.char.pyrCurse;
          }
          break;
        }
        // 第43回 C: 魔物あずかり所（world/storage.js）
        case 'storage':
        case 'shop': case 'jobChange': case 'tavern': case 'board': case 'starTrade': case 'church': case 'bank': case 'forge': case 'casino': case 'medalKing': case 'salon': case 'vehicles': {
          const r = await this.flush();
          if (r.aborted) return this.abort();
          const ui = openService(w, this.init, op, a[0]);
          if (!ui) break;
          this.batch.push(['ui', op, ui]);
          const r2 = await this.flush();
          if (r2.aborted) return this.abort();
          break;
        }
        case 'say':
        case 'fade': case 'flash': case 'shake': case 'night': case 'bgm': case 'sfx': case 'wait':
        case 'actor': case 'move': case 'face': case 'remove': case 'chapter': case 'guestHide': case 'chestOpen': case 'hideNpc': case 'showMon': case 'crest':
        // 第3章: トロッコに のる・自分を かくす・天気・大きな 役者
        case 'ride': case 'hideMe': case 'weather':
        // 第5章 Step 9: エンディングの ふりかえり（スタッフロールふう。client/ui/script.js の roll）
        case 'roll':
        // カメラを その 場所へ（['look', x, y]）・自分に もどす（['look']）
        case 'look':
        // 第6章: 時の砂時計の 砂の うず（client/time-shift.js）
        case 'timeShift':
          this.batch.push(step);
          break;
        default:
          console.warn('unknown step', op);
      }
    }
  }
}

// NPCや ばしょから だいほんを はじめる
// ストーリーを いっしょに すすめられる くらい 近いか
const STORY_NEAR = 16;

export function runScript(world, s, scriptId, opts = {}) {
  const fn = SCRIPTS[scriptId];
  if (!fn) return false;
  const story = STORY_SCRIPTS.has(scriptId) || opts.story;
  const p = story ? partyOf(world, s) : null;
  // パーティーでは、リーダー（さそった 人）の ストーリーを みんなで すすめる
  let init = s;
  if (p && p.leader !== s.id) {
    const leader = world.sessions.get(p.leader);
    if (leader?.inWorld) {
      // fn.sameMap … 同じ マップなら 遠くても（第4章の 砂の古城の 2つの 石の 板。家族が はなれた 板を べつべつに ふむ）
      const near = leader.map === s.map && !leader.busy && !leader.away && (fn.sameMap || Math.hypot(leader.x - s.x, leader.y - s.y) <= STORY_NEAR);
      if (!near) {
        const now = world.now();
        if (!(s.storyHintAt > now - 8000)) {
          s.storyHintAt = now;
          // リーダーが ボス・物語の たたかいの 中なら、そばへ 行けば とちゅうから 入れる（battles.js の joinBattle）
          const fighting = leader.busy === 'battle' && leader.map === s.map && world.battles.get(leader.battleId)?.opts.fixed;
          world.send(s, { t: 'toast', text: fighting ? `${leader.char.name}が戦っている！そばへ行くと、戦いに入れるよ` : `ストーリーは、リーダーの${leader.char.name}といっしょに進めよう` });
        }
        return false;
      }
      init = leader;
    }
  }
  // さそわれて 手伝っている 人が 町の 人に 話しかけた ときも、リーダーの 世界（ものがたり）で
  const owner = story ? init : (world.hostOf?.(init) || init);
  const steps = fn(scriptCtx(init, owner, world));
  if (!steps || !steps.length) return false;
  const participants = [init];
  if (init !== s && !s.busy) participants.push(s);
  if (story) {
    for (const sid of p?.members || []) {
      const m = world.sessions.get(sid);
      if (m && !participants.includes(m) && m.inWorld && m.map === init.map && !m.busy && !m.away) participants.push(m);
    }
  }
  const run = new ScriptRun(world, init, participants, steps, { scriptId, owner });
  run.start();
  return true;
}

// 第44回: 進化を まっている 仲間が いれば「…おや？」の 台本を その 人だけに 出す（world.js の tick から。ひまな ときだけ）
export function checkEvolve(world, s) {
  if (!s || !world.sessions.has(s.id) || !s.inWorld || s.busy || s.away) return false;
  const e = pendingEvolve(s.char);
  if (!e) return false;
  runSteps(world, s, evolveAskSteps(e));
  return true;
}

export function runSteps(world, s, steps) {
  const run = new ScriptRun(world, s, [s], steps, {});
  run.start();
  return run;
}

js/shared/world/secret.js:
// ひみつのダンジョン（せかいの しくみ）: 入る・階を 下りる・番人（たおすと 全回復）・休み所の ごほうび・宿屋の 階・お店の 階・
// 地上へ もどる・全滅・記録の 板
// データと 階の 形は data/secret.js と maps/secret-dungeon.js（お店の 品ぞろえは data/secret-shop.js）
//
// ちょうせん（c.sd.run）
// ・入口の 広間（案内人か 下り階段）から 入った 人だけが「ちょうせん中」。1つずつ 下りた 階が 記録に なる
// ・始める 階は 地下1階か、休み所で 記録した 階（c.sd.save。5の 倍数）までの 休み所（2026年10月 第27回）。
//   パーティーでは リーダーが 選ぶ。選べるのは、いっしょに 入る 家族 みんなが 記録した 階まで（sdStartFloors）
//   とちゅうの 階から 始めても、着いた いちばん 深い 階が 記録の 板に のる。初めて 着いた 休み所なら 大きな ごほうび
// ・休み所の ようせいの「この階を記録して地上へもどる」で、その 階を 記録して 入口の 広間へ（noteSdSave）
// ・パーティーの みんなで いっしょに 下りる（同じ 階に いる 家族を みんな つれていく）。いっしょに いた 家族の 名前も 記録に のこる
// ・とちゅうから 来た 人（さそわれて リーダーの ところへ 来た など）は mid（その ちょうせんは 記録に ならない。記録も できない。ごほうびは 小さな 物だけ）
// ・ダンジョンの 外（入口の 広間も）へ 出ると ちょうせんは 終わり（placeSession から noteSecretMove）
// ・階の 形は ちょうせんごとに かわる（2026年10月 第32回）: 入口から 始める ときに seed を 作って c.sd.run.seed に 入れ、
//   マップの ID（'sd_<階>_<seed>'）にも 入れる。いっしょに 下りる 家族は おなじ ID の 階へ 行くので おなじ 形。
//   ログインしなおしても 場所の ID に seed が のこる。前の 版の 'sd_<階>' に いた 人は、次の 階から 新しい seed
// ・第79回: seed には「いっしょに 入る みんなが 行った ことの ある ダンジョン」の しるしも 入る（階の テーマ。data/secret-themes.js）
// ・第79回: リレミト・みちびきの糸で 入口の 広間へ（secretEscape。全滅で もどる 時と おなじ あつかい）
import { MAPS, isBlocked } from '../maps/index.js';
import { fullHeal, addItem } from '../stats.js';
import { MONSTERS } from '../data/monsters.js';
import { SD_HOOKS } from '../data/story-secret.js';
import { partyOf } from './party.js';
import { SD_DOOR_OUT, GATE_ARRIVE, SD_INN_KEEPER } from '../maps/secret-dungeon.js';
import {
  SD_GATE, SD_NAME, SD_OPEN_FLAG, sdFloorId, sdFloorOf, isSdFloorId, isRestFloor, isGuardFloor, sdGuardian, sdGuardEncounter,
  sdRecommendLv, sdBigReward, sdSmallReward, rewardText, sdMedalId, noteSdFloor, sdRecordOf, sdRecordText, sdBoardRows, sdBand,
  sdSaveOf, noteSdSave, sdStartFloors, sdStartText, sdRunSeedOf, newSdSeed, sdInnPrice, sdKeyRewards,
} from '../data/secret.js';
import { ensureSdShop } from '../data/secret-shop.js';
import {
  SD_THEME, sdPartyMask, SD_CRAFTSMAN, SD_CRAFT_HELLO, SD_FAKE_STAIRS, SD_BOX_EMPTY, SD_BOX_JACK, SD_BOX_HIT, SD_TEA_LINES, SD_CART_LINE,
  SD_KOTATSU_LINE, sdDirText,
} from '../data/secret-themes.js';

const GUIDE = 'ひみつのダンジョンの案内人';
const FAIRY = '休み所のようせい';
// その 階の 宿屋・お店（maps/secret-dungeon.js の sd.kind）
const floorKind = (mapId) => MAPS[mapId]?.sd?.kind || null;

// ───────────── ちょうせんの きろく ─────────────
function sdOf(c) {
  if (!c.sd || typeof c.sd !== 'object') c.sd = { best: 0, got: [], tries: 0 };
  if (!Array.isArray(c.sd.got)) c.sd.got = [];
  return c.sd;
}
const runOf = (c) => (c?.sd?.run && typeof c.sd.run === 'object' ? c.sd.run : null);
// とちゅうから 来た 人の ちょうせん（記録に ならない。seed は その 階の もの）
function midRun(f, mapId) {
  const run = { f, mid: true, took: [] };
  const seed = sdRunSeedOf(mapId);
  if (seed) run.seed = seed;
  return run;
}

// world.placeSession から（s.map が かわる 前）: ちょうせんの つづきか、とちゅうから 来たか、外に 出たか
export function noteSecretMove(world, s, toMap) {
  const c = s?.char;
  if (!c || toMap === s.map) return;
  const step = s.sdStep;
  delete s.sdStep;
  const f = sdFloorOf(toMap);
  if (f) {
    // 下り階段・入口からの 正しい 移動は 下りた あとで 記録する（arriveFloor）。それ いがいは とちゅうから
    if (step === toMap) return;
    sdOf(c).run = midRun(f, toMap);
    return;
  }
  if (c.sd?.run) delete c.sd.run;
  // 階の 地図の きろく（ちょうせんの たびに 新しく さがす）
  if (c.explored) for (const k of Object.keys(c.explored)) if (isSdFloorId(k)) delete c.explored[k];
}

// ログインの ときの 場所（world.js の validPos）。階の 中なら そのまま（かべの 中なら 着いた 場所）、知らない 階なら 入口の 広間
export function fixSecretPos(pos) {
  const m = MAPS[pos.map];
  if (m?.sd?.floor) {
    const inside = Number.isFinite(pos.x) && Number.isFinite(pos.y) && pos.x >= 0 && pos.y >= 0 && pos.x < m.w && pos.y < m.h;
    if (inside && !isBlocked(m, Math.floor(pos.x), Math.floor(pos.y), () => false)) return pos;
    return { map: pos.map, x: m.sd.arrive.x, y: m.sd.arrive.y, dir: 'down' };
  }
  return { map: SD_GATE, x: GATE_ARRIVE.x, y: GATE_ARRIVE.y, dir: 'down' };
}

// 全滅（world.js の respawn から）: ダンジョンの 階なら 入口の 広間で 目を覚ます（お金は へらない。world/battles.js）
export function secretRespawn(world, s, note = '') {
  const f = MAPS[s.map]?.sd?.floor;
  if (!f) return false;
  fullHeal(s.char);
  world.placeSession(s, SD_GATE, GATE_ARRIVE.x, GATE_ARRIVE.y, 'down', true);
  const r = sdRecordOf(s.char);
  world.send(s, {
    t: 'toast', afterBattle: true,
    text: `${s.char.name}は${SD_NAME}の入口で目を覚ました。\n（ここでは、お金はへらない）\n今回は地下${f}階まで。最高は地下${r.best}階${note ? `\n${note}` : ''}`,
  });
  return true;
}

// 第79回: リレミト・みちびきの糸（world/escape.js・field27.js から）。ひみつのダンジョンの 階なら 入口の 広間へ もどる
//   全滅で もどる 時と おなじ あつかい:
//   ・いっしょに いる パーティーの 家族（おなじ 階に いて、ほかの ことを していない 人）も みんな 入口へ（階段で いっしょに 下りるのと おなじ）
//   ・今の ちょうせんは おわり（noteSecretMove）。いちばん 深い 階・ごほうびを もらった 休み所・記録した 階・お金は そのまま
//   ・HP・MP は 回復しない（全滅とは ちがう）。戦いの 中は 使えない（メニューが 使えない）
// how … 「リレミト」「みちびきの糸」（いっしょに もどった 家族への 知らせ）
// → 使った 人に 見せる 記録の 文（「今回は地下7階まで。最高は地下12階」。階で なければ null）
const recordLine = (f, r) => `今回は地下${f}階まで。${r.best > 0 ? `最高は地下${r.best}階` : ''}`;
export function secretEscape(world, s, how) {
  const f = MAPS[s?.map]?.sd?.floor;
  if (!f) return null;
  const from = s.map;
  const p = partyOf(world, s);
  const people = [s];
  for (const sid of p?.members || []) {
    const m = world.sessions.get(sid);
    if (!m || m === s || !m.inWorld || m.away || m.busy || m.map !== from) continue;
    people.push(m);
  }
  const gate = MAPS[SD_GATE];
  const offs = [[0, 0], [1, 0], [-1, 0], [0, 1], [1, 1], [-1, 1], [2, 0], [0, 2], [2, 1]];
  people.forEach((m, k) => {
    let x = GATE_ARRIVE.x, y = GATE_ARRIVE.y;
    for (let i = 0; i < offs.length; i++) {
      const [ox, oy] = offs[(k + i) % offs.length];
      if (!isBlocked(gate, Math.floor(x + ox), Math.floor(y + oy), () => false)) { x += ox; y += oy; break; }
    }
    world.placeSession(m, SD_GATE, x, y, 'down', true);
  });
  world.broadcastPlayers();
  // いっしょに もどった 家族には 知らせ（使った 人は メニューの 返事に 書く）
  for (const m of people) {
    if (m !== s) world.send(m, { t: 'toast', text: `${s.char.name}の${how}で、${SD_NAME}の入口へもどってきた。\n${recordLine(f, sdRecordOf(m.char))}` });
    world.sendSelf(m);
  }
  world.markDirty();
  return recordLine(f, sdRecordOf(s.char));
}

// だれも いない 階の 魔物は わすれる（world.js の tick から。また 入ると 新しい 魔物）
let pruneAt = 0;
export function pruneSecretStates(world, byMap) {
  const now = world.now();
  if (now - pruneAt < 10000) return;
  pruneAt = now;
  for (const id of [...world.mapStates.keys()]) if (isSdFloorId(id) && !byMap.has(id)) world.mapStates.delete(id);
}

// ───────────── パーティーで いっしょに ─────────────
// 同じ マップに いる 家族（ほかの ことを していない 人）を だいほんに 入れる（いっしょに 下りる・ごほうび・宿屋）
function gather(run) {
  const w = run.world, s = run.init;
  const p = partyOf(w, s);
  for (const sid of p?.members || []) {
    const m = w.sessions.get(sid);
    if (!m || m === s || run.parts.includes(m) || !m.inWorld || m.away || m.busy || m.map !== s.map) continue;
    m.busy = 'script';
    m.runId = run.id;
    run.parts.push(m);
  }
  return run.everyone.filter((m) => m.map === s.map);
}

// みんなで 階を うつる（to: マップ ID。着いた 場所は その マップの sd.arrive）
async function moveAll(run, people, to) {
  const m = MAPS[to];
  for (const x of people) x.sdStep = to;
  await run.runSteps([['sfx', 'stairs'], ['teleport', to, m.sd.arrive.x, m.sd.arrive.y, 'down']]);
  for (const x of people) delete x.sdStep;
}

// 階に 着いた: ちょうせん中の 人は 記録を のばす（いっしょに いた 家族の 名前も）
// seed … その ちょうせんの seed（ちがう ちょうせんの 人は とちゅうから 来た ことに する）
function arriveFloor(world, people, f, seed = 0) {
  const now = world.now();
  const news = [];
  for (const m of people) {
    const c = m.char;
    const sd = sdOf(c);
    const r = runOf(c);
    if (!r || r.mid || r.f !== f - 1 || (seed && r.seed && r.seed !== seed)) {
      sd.run = midRun(f, sdFloorId(f, seed));
      continue;
    }
    r.f = f;
    if (seed) r.seed = seed;
    const others = people.filter((o) => o !== m).map((o) => o.char.name);
    if (noteSdFloor(c, f, others, now)) news.push(m);
  }
  world.markDirty();
  // 宿屋・お店の 階は ひとこと（会話の まどは 出さない）
  const kind = floorKind(sdFloorId(f, seed));
  // 第79回: テーマの 階は その 名前（「スケート場の階」など）
  const th = SD_THEME[MAPS[sdFloorId(f, seed)]?.sd?.theme];
  const here = kind === 'inn' ? '\nふしぎな宿屋がある！' : kind === 'shop' ? '\nふしぎな店がある！' : th ? `\n（${th.label}）` : '';
  for (const m of people) {
    const mid = runOf(m.char)?.mid;
    const isNew = news.includes(m);
    world.send(m, { t: 'toast', text: `${SD_NAME}　地下${f}階${isNew ? '\n★新記録！' : mid ? '\n（とちゅうから来たので、今回は記録にならない）' : ''}${here}` });
    world.sendSelf(m);
  }
  return news;
}

// ───────────── 入口（ミドリナ地方）─────────────
async function doorEvent(run) {
  const s = run.init;
  if (!run.world.worldFlags(s)[SD_OPEN_FLAG]) {
    await run.runSteps([['say', null, '古い石のとびらがある。\nかたくとざされていて、びくともしない…。']]);
    return;
  }
  await run.runSteps([['sfx', 'stairs'], ['teleport', SD_GATE, GATE_ARRIVE.x, GATE_ARRIVE.y, 'down']]);
}

// ───────────── 入口の 広間 ─────────────
async function guideTalk(run) {
  const c = run.init.char;
  const r = sdRecordOf(c);
  const say = (...lines) => lines.map((l) => ['say', GUIDE, l]);
  const explain = say(
    'このダンジョンには、終わりがない。\n下の階へ行くほど、魔物が強くなるぞ。',
    '階の形は、入るたびに変わる。\nいっしょに入った家族は、みんな同じ形じゃ。',
    `5階ごとに休み所がある。\nごほうびの宝箱があるぞ。初めて着いた休み所の宝箱には、大きなごほうびが入っておる。`,
    '休み所のようせいに話せば、その階を記録して地上へもどれる。\n次は、わしに話しかければ、記録した階から始められるぞ。',
    '10階ごとの休み所では、強い番人が下り階段を守っておる。\nたおせば、HPとMPがすっかり回復するぞ。',
    '回復の泉はない。運がよければ、宿屋やお店だけの階に出会えるぞ。',
    'リレミトかみちびきの糸を使えば、この入口へもどってこられるぞ。\n帰り道の羽とルーラは使えん。',
    '全滅しても、この入口にもどされる。でも、お金はへらんから安心せい。\nいちばん深く行けた階の記録も、ちゃんとのこるぞ。',
    '階には、今までのダンジョンをまねたものがある。\n行ったことのあるダンジョンだけじゃがな。',
    'それから…ここの魔物は、なぜか仲間にならんのじゃ。',
    'とちゅうの階から始めても、いちばん深く行けた階が、となりの「家族の記録の板」にのこるぞ。',
    'パーティーを組んで入れば、いっしょにいた家族みんなの記録になる。\n何階から始めるかはリーダーが決める。選べるのは、みんなが記録した階までじゃ。',
  );
  await run.runSteps([
    ...say(r.best > 0 ? `おお、${c.name}か。\n${c.name}の最高は、地下${r.best}階じゃったな。${r.save ? `\n地下${r.save}階まで記録してあるぞ。` : ''}` : `ようこそ、${SD_NAME}へ。\nわしは、このダンジョンの案内人じゃ。`),
    ['choice', '何をする？', ['ちょうせんを始める', 'このダンジョンのこと', '記録の板を見る', 'またこんど'], [
      [['call', (x) => chooseStart(x, true)]],
      explain,
      [['call', boardOpen]],
      say('うむ。気をつけてな。'),
    ]],
  ]);
}

export function boardData(world, s) {
  return {
    family: world.familyName || '',
    offline: !!world.offline,
    rows: sdBoardRows(world.data.characters),
    me: { id: s.char.id, name: s.char.name, ...sdRecordOf(s.char), text: sdRecordText(sdRecordOf(s.char)) },
  };
}

async function boardOpen(run) {
  const r = await run.flush();
  if (r.aborted) return run.abort();
  run.batch.push(['ui', 'sdBoard', boardData(run.world, run.init)]);
  const r2 = await run.flush();
  if (r2.aborted) run.abort();
}

// ───────────── ちょうせんの はじまり（何階から 始めるか）─────────────
// 入口の 案内人（guide: true）と 下り階段から。パーティーでは リーダーが 選ぶ（同じ 広間に いる 家族 みんなが 記録した 階まで）
async function chooseStart(run, guide = false) {
  const world = run.world, s = run.init;
  const p = partyOf(world, s);
  const leader = !p || p.members.length < 2 || p.leader === s.id;
  const people = gather(run);
  const floors = leader ? sdStartFloors(...people.map((m) => sdSaveOf(m.char))) : [1];
  const notes = [];
  if (!leader && sdSaveOf(s.char) > 0) notes.push('（何階から始めるかは、パーティーのリーダーが選ぶ）');
  else if (people.length > 1) {
    const low = people.filter((m) => sdSaveOf(m.char) < Math.max(...people.map((x) => sdSaveOf(x.char))));
    if (low.length) notes.push(`（選べるのは、みんなが記録した階まで。${low.map((m) => `${m.char.name}は${sdSaveOf(m.char) ? `地下${sdSaveOf(m.char)}階` : 'まだ1階'}`).join('・')}）`);
  }
  if (floors.length === 1) {
    const q = `${SD_NAME}の地下1階へ下りますか？\n（おすすめ: レベル${sdRecommendLv(1)}くらいから）${notes.length ? `\n${notes.join('\n')}` : ''}`;
    await run.runSteps([
      ['choice', q, ['下りる', 'やめる'], [[['call', (x) => startRun(x, 1)]], guide ? [['say', GUIDE, 'うむ。準備ができたら、また来るがよい。']] : []]],
    ]);
    return;
  }
  const label = (f) => (f === 1 ? '地下1階から' : `地下${f}階の休み所から（Lv${sdRecommendLv(f)}くらい）`);
  await run.runSteps([
    ['choice', `何階から始める？${notes.length ? `\n${notes.join('\n')}` : ''}`, [...floors.map(label), 'やめる'], [
      ...floors.map((f) => [['call', (x) => startRun(x, f)]]),
      guide ? [['say', GUIDE, 'うむ。準備ができたら、また来るがよい。']] : [],
    ]],
  ]);
}

// 下り階段（入口の 広間）
async function enterEvent(run) {
  await chooseStart(run, false);
}

// f … 始める 階（1 か 記録した 休み所）
// ちょうせんの seed を 作って、いっしょに 入る 家族 みんなに 入れる（同じ 形の 階へ）
async function startRun(run, f = 1) {
  const people = gather(run);
  // 第79回: 階の テーマは、いっしょに 入る みんなが 行った ことの ある ダンジョンだけ（seed に 入れる。data/secret-themes.js）
  const seed = newSdSeed(run.world.rng, sdPartyMask(people.map((m) => m.char)));
  for (const m of people) {
    const sd = sdOf(m.char);
    sd.run = { f: f - 1, took: [], seed };
    sd.tries = (sd.tries || 0) + 1;
  }
  await moveAll(run, people, sdFloorId(f, seed));
  if (run.aborted) return;
  arriveFloor(run.world, people, f, seed);
  if (f > 1) {
    const guard = isGuardFloor(f) ? `\n下り階段の前には、番人の${MONSTERS[sdGuardian(f)]?.name || '魔物'}がいる…。` : '';
    await run.runSteps([['sfx', 'sparkle'], ['say', null, `地下${f}階の休み所から、ちょうせんを始めた！${guard}`]]);
  }
}

// ───────────── 下りる（下り階段・休み所の「先へ進む」・番人）─────────────
async function downEvent(run) {
  const world = run.world;
  const here = run.init.map;
  const f = sdFloorOf(here);
  if (!f) return;
  const people = gather(run);
  // この ちょうせんの seed（前の 版の 階なら ちょうせんの seed か、新しく 作る）
  const seed = sdRunSeedOf(here) || runOf(run.init.char)?.seed || newSdSeed(world.rng, sdPartyMask(people.map((m) => m.char)));
  if (isGuardFloor(f)) {
    const sp = sdGuardian(f);
    const name = MONSTERS[sp]?.name || '番人';
    const enc = sdGuardEncounter(f);
    await run.runSteps([
      ['bgm', null],
      ['showMon', sp],
      ['say', null, `下り階段の前に、番人の${name}が立ちはだかった！`],
      ['say', name, '…ここから先へ進みたくば、力を見せてみよ！'],
      ['showMon', null],
      ['battle', enc],
    ]);
    if (run.aborted) return;
    // 番人を たおすと、いっしょに 戦った みんなの HPと MPが 全回復（第32回。5階ごとの 回復の泉の かわり）
    await run.runSteps([
      ['bgm', 'resume'], ['sfx', 'key'], ['say', null, `番人の${name}をたおした！\n下り階段への道が開いた！`],
      ['flash'], ['heal'], ['sfx', 'heal'], ['say', null, 'ふしぎな光が、みんなをつつみこんだ…。\nHPとMPがすっかり回復した！'],
    ]);
    if (run.aborted) return;
  }
  const next = f + 1;
  const go = people.filter((m) => world.sessions.has(m.id) && m.map === here);
  await moveAll(run, go, sdFloorId(next, seed));
  if (run.aborted) return;
  arriveFloor(world, go, next, seed);
  if (isRestFloor(next)) {
    const guard = isGuardFloor(next) ? `\n下り階段の前には、番人の${MONSTERS[sdGuardian(next)]?.name || '魔物'}がいる…。` : '';
    await run.runSteps([['sfx', 'sparkle'], ['say', null, `地下${next}階の休み所に着いた！\nごほうびの宝箱がある。（地上へもどる時は、ようせいに話しかけよう）${guard}`]]);
  } else if (sdBand(next) !== sdBand(f)) {
    await run.runSteps([['say', null, `あたりの様子が変わった…。\n（${sdBand(next).label}）`]]);
  }
}

// ───────────── 休み所 ─────────────
async function restTalk(run) {
  const f = sdFloorOf(run.init.map);
  if (!isRestFloor(f)) return;
  await run.runSteps([
    ['say', FAIRY, `ここは地下${f}階の休み所。\n魔物は来ないから、ひと休みしていってね。`],
    ['choice', 'どうする？', ['先へ進む', 'この階を記録して地上へもどる', 'やめる'], [
      [['call', downEvent]],
      [['choice', `地上へもどると、今回のちょうせんはおしまい。\n地下${f}階を記録しておくと、次は入口の案内人に話して、この階から始められるよ。\nもどる？`, ['もどる', 'やめる'], [[['call', exitEvent]], []]]],
      [['say', FAIRY, 'いってらっしゃい。むりはしないでね。']],
    ]],
  ]);
}

async function exitEvent(run) {
  const world = run.world;
  const f = sdFloorOf(run.init.map);
  const people = gather(run);
  // この 階を 記録する（ちょうせん中の 人だけ。とちゅうから 来た 人は 記録できない）
  const saved = [];
  for (const m of people) {
    const r = runOf(m.char);
    if (!r || r.mid || r.f !== f || !isRestFloor(f)) continue;
    noteSdSave(m.char, f);
    saved.push(m);
  }
  world.markDirty();
  const lines = people.map((m) => {
    const rec = sdRecordOf(m.char);
    const sv = saved.includes(m)
      ? (rec.save > f ? `地下${f}階を記録した！（記録は地下${rec.save}階まであるよ）` : `地下${f}階を記録した！`)
      : '（とちゅうから来たので、記録できなかった）';
    return `${m.char.name}: ${sv}\n最高は地下${rec.best}階。${sdStartText(rec.save)}`;
  });
  for (const m of people) world.sendSelf(m);
  await run.runSteps([
    ['say', FAIRY, `おつかれさま！\n今回は地下${f}階まで来られたね。`],
    ['fade', 'out'],
    ['sfx', 'stairs'],
    ['teleport', SD_GATE, GATE_ARRIVE.x, GATE_ARRIVE.y, 'down'],
    ['fade', 'in'],
    ...lines.map((l) => ['say', null, l]),
  ]);
}

// ───────────── 宿屋の 階（運で 出る）─────────────
// すこしの ゴールドで、いっしょに いる 家族 みんなの HPと MPが 全回復（はらうのは 話しかけた 人）
async function innTalk(run) {
  const here = run.init.map;
  const f = sdFloorOf(here);
  if (floorKind(here) !== 'inn') return;
  gather(run);
  const price = sdInnPrice(f);
  const stay = async (x) => {
    const c = x.init.char;
    if ((c.gold || 0) < price) {
      await x.runSteps([['say', SD_INN_KEEPER, 'おや、ゴールドが足りないようだね…。\nまたおいで。']]);
      return;
    }
    c.gold -= price;
    x.world.markDirty();
    await x.runSteps([
      ['fade', 'out'], ['bgm', 'inn'], ['wait', 1800], ['heal'], ['bgm', 'resume'], ['fade', 'in'],
      ['sfx', 'heal'], ['say', null, 'HPとMPがすっかり回復した！'],
    ]);
  };
  await run.runSteps([
    ['choice', `${SD_INN_KEEPER}「ようこそ。\nひと休み${price}ゴールドで、HPとMPがすっかり回復するよ。休んでいくかい？」`, ['休む', 'やめる'], [
      [['call', stay]],
      [['say', SD_INN_KEEPER, '気をつけて行くんだよ。']],
    ]],
  ]);
}

// ───────────── お店の 階（運で 出る）─────────────
// 品ぞろえは その ちょうせんの seed と 階で きまる（data/secret-shop.js）。店の 画面は ふつうの お店
async function shopTalk(run) {
  const here = run.init.map;
  if (floorKind(here) !== 'shop') return;
  const f = sdFloorOf(here);
  const seed = sdRunSeedOf(here);
  await run.runSteps([['shop', ensureSdShop(f, seed)]]);
}

// ごほうびの 宝箱（1回の ちょうせんで 1人1回。初めて 着いた 休み所は 大きな ごほうび）
async function chestEvent(run) {
  const world = run.world;
  const f = sdFloorOf(run.init.map);
  if (!isRestFloor(f)) return;
  const people = gather(run);
  const steps = [];
  for (const m of people) {
    const c = m.char;
    const sd = sdOf(c);
    let r = runOf(c);
    if (!r || r.f !== f) r = sd.run = midRun(f, run.init.map);
    if (!Array.isArray(r.took)) r.took = [];
    if (r.took.includes(f)) continue;
    r.took.push(f);
    const big = !r.mid && !sd.got.includes(f);
    // 第45回: 40階の 四季のこよみ（大事な物。1人 1つ。data/secret.js の sdKeyRewards）
    const list = [...(big ? sdBigReward(f) : [sdSmallReward(f, world.rng)]), ...sdKeyRewards(f, c)];
    if (big) sd.got.push(f);
    for (const e of list) {
      if (e.gold) c.gold = Math.min(9999999, (c.gold || 0) + e.gold);
      else if (e.medal) {
        c.medalSpots = c.medalSpots && typeof c.medalSpots === 'object' ? c.medalSpots : {};
        c.medalSpots[sdMedalId(f)] = world.now();
      } else addItem(c, e.item, e.n || 1);
    }
    steps.push(['sfx', big ? 'key' : 'item']);
    if (big) steps.push(['say', null, `★地下${f}階に初めて着いたごほうび！\n${c.name}は${list.map(rewardText).join('と')}を手に入れた！`]);
    else steps.push(['say', null, `${c.name}は${list.map(rewardText).join('と')}を手に入れた！`]);
    world.sendSelf(m);
  }
  world.markDirty();
  if (!steps.length) {
    await run.runSteps([['say', null, '宝箱はからっぽだ。\n（次のちょうせんで来ると、また何か入っているよ）']]);
    return;
  }
  await run.runSteps([['sfx', 'chest'], ['say', null, 'ごほうびの宝箱を開けた！'], ...steps]);
}

// ───────────── テーマの 階の しかけ（第79回。data/secret-themes.js）─────────────
// 立っている 所で きまる 数（おなじ 所では おなじ ひとこと）
const spotNo = (s) => Math.floor(s.x) * 7 + Math.floor(s.y) * 13;
// 階段だらけの 階の にせものの 階段
async function fakeStairs(run) {
  await run.runSteps([['sfx', 'stairs'], ['say', null, SD_FAKE_STAIRS[spotNo(run.init) % SD_FAKE_STAIRS.length]]]);
}
// 宝箱だらけの 階の 宝箱（中みは 入っていない。当たりは 下り階段の むきを 教えてくれる。ごほうびの 量は かわらない）
const boxOpen = (kind) => async (run) => {
  const s = run.init;
  const d = MAPS[s.map]?.sd?.down;
  const text = kind === 'hit' ? SD_BOX_HIT(d ? sdDirText(d.x + 0.5 - s.x, d.y + 0.5 - s.y) : 'すぐ近く')
    : kind === 'jack' ? SD_BOX_JACK : SD_BOX_EMPTY[spotNo(s) % SD_BOX_EMPTY.length];
  await run.runSteps([['sfx', 'chest'], ['say', null, text]]);
};
// 休けい中の 魔物（戦いに ならない）
async function teaTalk(run) {
  await run.runSteps([['say', '休けい中の魔物', SD_TEA_LINES[spotNo(run.init) % SD_TEA_LINES.length]]]);
}
// まよいの職人（その 階の テーマの ひとこと）
async function craftTalk(run) {
  const th = SD_THEME[MAPS[run.init.map]?.sd?.theme];
  await run.runSteps([['say', SD_CRAFTSMAN, SD_CRAFT_HELLO], ...(th ? [['say', SD_CRAFTSMAN, th.craft]] : [])]);
}

// だいほんの しょり（data/story-secret.js）
Object.assign(SD_HOOKS, {
  door: doorEvent, guide: guideTalk, board: boardOpen, enter: enterEvent, down: downEvent, rest: restTalk, chest: chestEvent, inn: innTalk, shop: shopTalk,
  fake: fakeStairs, boxHit: boxOpen('hit'), boxEmpty: boxOpen('empty'), boxJack: boxOpen('jack'), tea: teaTalk, craft: craftTalk,
  cart: (run) => run.runSteps([['say', null, SD_CART_LINE]]),
  kotatsu: (run) => run.runSteps([['say', null, SD_KOTATSU_LINE]]),
});

export { SD_DOOR_OUT };

