export function openService(world, s, kind, arg) {
  switch (kind) {
    case 'shop': {
      const shop = SHOPS[arg];
      if (!shop) return null;
      s.openShop = arg;
      const has = world.hasFlagFn(s);
      return { shop: arg, name: shop.name, items: shopItems(shop, has), keeper: shop.keeper, hello: shopHello(shop, has), kind: shop.kind, prices: shop.prices };
    }
    case 'jobChange': return { jobs: ALL_JOBS };
    // 第43回 C: 魔物あずかり所（world/storage.js）
    case 'storage':
      s.openStorage = true;
      return storageInfo(world, s);
    case 'tavern': return tavernInfo(world, s);
    case 'salon': return salonInfo(world, s);
    // 乗り物屋（第37回。world/vehicles.js）
    case 'vehicles': return vehicleShopInfo(world, s);
    case 'board': return { posts: world.data.board || [] };
    case 'starTrade': return starTradeInfo(world, s);
    case 'church': return churchInfo(world, s);
    case 'bank': return bankInfo(world, s, arg);
    case 'forge': return forgeInfo(world, s, arg);
    // カジノ・メダル王（casino.js）
    case 'casino': case 'medalKing': return casinoOpen(world, s, kind, arg);
    default: return null;
  }
}

function churchInfo(world, s) {
  const p = partyOf(world, s);
  const dead = [];
  const poisoned = [];
  for (const sid of p?.members || []) {
    const m = world.sessions.get(sid);
    if (!m) continue;
    if (m.char.hp <= 0) dead.push({ ref: 'sid:' + sid, name: m.char.name, price: revivePrice(m.char.level) });
    else if (m.char.status?.poison) poisoned.push({ ref: 'sid:' + sid, name: m.char.name, price: CURE_PRICE });
  }
  for (const sup of p?.supports || []) {
    if (sup.char.hp <= 0) dead.push({ ref: 'sup:' + sup.key, name: sup.char.name, price: revivePrice(sup.char.level) });
    else if (sup.char.status?.poison) poisoned.push({ ref: 'sup:' + sup.key, name: sup.char.name, price: CURE_PRICE });
  }
  for (const g of p?.guests || []) {
    if (g.char.hp <= 0) dead.push({ ref: 'guest:' + g.id, name: g.char.name, price: revivePrice(g.char.level) });
    else if (g.char.status?.poison) poisoned.push({ ref: 'guest:' + g.id, name: g.char.name, price: CURE_PRICE });
  }
  // 馬車の 仲間も（world/wagon.js）
  wagonChurch(world, s, dead, poisoned, revivePrice, CURE_PRICE);
  return { dead, poisoned };
}

function refChar(world, s, ref) {
  if (!ref || ref === 'self') return s.char;
  if (ref.startsWith('sid:')) {
    const p = partyOf(world, s);
    const sid = ref.slice(4);
    if (!p?.members.includes(sid)) return null;
    return world.sessions.get(sid)?.char || null;
  }
  if (ref.startsWith('sup:')) {
    const p = partyOf(world, s);
    return p?.supports.find((x) => x.key === ref.slice(4))?.char || null;
  }
  if (ref.startsWith('guest:')) {
    const p = partyOf(world, s);
    return p?.guests.find((x) => x.id === ref.slice(6))?.char || null;
  }
  if (ref.startsWith('wagon:')) return wagonRefChar(world, s, ref);
  return null;
}

// じぶん か じぶんの なかま（そうび・転職・じゅもん など）。家族の サポートは えらべない
function ownChar(s, who) {
  if (!who || who === 'self') return s.char;
  const e = companionOf(ensureCompanions(s.char), who);
  return e ? e.char : null;
}

// 第69回: お気に入りの ならびを まとめて かえる（op: 'order'）。ids が 今の お気に入りと おなじ 技の くみ（FAV_MAX こまで・かさならない）の ときだけ
//   あたらしい 配列を かえす（だめな ときは null）
export function favoriteOrder(cur, ids) {
  const now = Array.isArray(cur) ? cur.filter((x) => ABILITIES[x]) : [];
  if (!Array.isArray(ids) || ids.length !== now.length || ids.length > FAV_MAX) return null;
  if (ids.some((x) => typeof x !== 'string') || new Set(ids).size !== ids.length) return null;
  const set = new Set(now);
  if (!ids.every((x) => set.has(x))) return null;
  return ids.slice();
}

// お気に入りを 戦いの 中の 人にも（つぎの 知らせで 前に もどらない）
function syncFavs(world, who) {
  for (const ctx of world.battles?.values?.() || []) {
    for (const b of ctx.battle?.combatants || []) {
      if (b.side === 'ally' && (ctx.actorMap?.[b.id]?.char === who || (who.id && b.charId === who.id))) b.favs = who.favorites.slice();
    }
  }
}

// お店などの そうさ
export function serviceAction(world, s, msg) {
  const c = s.char;
  // へんじより さきに 新しい じょうたいを おくる（がめんの ゴールドや 装備が すぐ かわるように）
  const reply = (ok, text, extra = {}) => {
    world.sendSelf(s);
    world.send(s, { t: 'svcRes', ok, text, ...extra });
    world.markDirty();
  };
  switch (msg.kind) {
    case 'casino': case 'medal': return casinoAction(world, s, msg);
    // 第66回: 幻の書（パーティーの みんなの ぶん。world/phantom.js の phantomPeople）。見るだけ なので 記録は かえない
    case 'phantomBook': return world.send(s, { t: 'svcRes', ok: true, text: '', people: phantomPeople(world, s) });
    case 'storage': return storageAction(world, s, msg, reply);
    // 第67回 B: モンスター闘技場（world/monarena.js）
    case 'monarena': return monArenaAction(world, s, msg, reply);
    case 'monlive': return monLiveAction(world, s, msg);
    case 'shop': {
      const shop = SHOPS[s.openShop];
      if (msg.action === 'buy') {
        const it = ITEMS[msg.id];
        const equipable = SLOTS.includes(it?.type);
        const qty = equipable ? 1 : Math.max(1, Math.min(99, Math.floor(msg.qty || 1)));
        // prices … その 店だけの ねだん（ひみつのダンジョンの お店の レア装備。data/secret-shop.js）
        const price = shop?.prices?.[msg.id] ?? it?.price;
        if (!shop || !shopItems(shop, world.hasFlagFn(s)).includes(msg.id) || !it || !(price > 0)) return reply(false, 'その品物はありません');
        const cost = price * qty;
        if (c.gold < cost) return reply(false, 'おや？ゴールドが足りないようですね。');
        // だれが 装備する？（じぶん か じぶんの なかま。むかしの 'equip: true' は じぶん）
        const whoKey = msg.who || (msg.equip ? 'self' : null);
        const who = whoKey && equipable ? ownChar(s, whoKey) : null;
        if (whoKey && equipable && (!who || !canEquipChar(who, msg.id))) return reply(false, 'その人は装備できないようですね。');
        c.gold -= cost;
        addItem(c, msg.id, qty);
        const lines = [`${it.name}${qty > 1 ? `を${qty}個` : 'を'}買った！`];
        if (who) {
          const old = who.equip[it.type];
          equipItem(who, msg.id, c);
          lines.push(`${who.name}は${it.name}を装備した！`);
          if (old && msg.sellOld && sellPrice(old) > 0 && removeItem(c, old, 1)) {
            c.gold += sellPrice(old);
            lines.push(`今まで装備していた${ITEMS[old].name}を${sellPrice(old)}ゴールドで売った。`);
          } else if (old) {
            lines.push(`${ITEMS[old].name}は、ふくろに入れた。`);
          }
          if (who !== c) world.sendParty(partyOf(world, s));
        } else {
          lines.push(`${it.name}は、ふくろに入れた。`);
        }
        return reply(true, lines.join('\n'), { equipped: !!who });
      }
      if (msg.action === 'sell') {
        const it = ITEMS[msg.id];
        const qty = Math.max(1, Math.min(99, Math.floor(msg.qty || 1)));
        if (!it || it.type === 'key' || sellPrice(msg.id) <= 0) return reply(false, 'それは引き取れません。');
        if (itemCount(c, msg.id) < qty) return reply(false, '持っていないようですね。');
        const price = sellPrice(msg.id);
        removeItem(c, msg.id, qty);
        c.gold += price * qty;
        return reply(true, `${it.name}を${price * qty}ゴールドで売った！`);
      }
      return reply(false, '');
    }
    case 'jobChange': {
      if (!JOBS[msg.job]) return reply(false, '');
      const who = ownChar(s, msg.who);
      if (!who || who.species) return reply(false, 'モンスターは転職できない');
      if (who.job === msg.job) return reply(false, '今の職業と同じです');
      const first = !who.jobs?.[msg.job];
      const firstTime = !who.jobs?.[msg.job];
      const r = changeJob(who, msg.job);
      // 体で なれない 職業（フルーツジッパーは 女性、アラシは 男性だけ）
      // 職業の 名前は なる 人 むけ（男の子の 美少女戦士は「仮面のしんし」。job-label.js）
      const jn = (j) => jobLabel(j, who);
      if (r.body !== undefined) return reply(false, `${jn(msg.job)}には、${BODY_NAMES[r.body]}しかなれない…`);
      if (r.locked) {
        // 幻の職業は やりこみの 条件も（data/phantom.js）
        const more = PHANTOM_JOBS[msg.job] ? `\n${PHANTOM_JOBS[msg.job].conds.map((x) => `・${x.text}`).join('\n')}` : '';
        return reply(false, `まだ${jn(msg.job)}にはなれない…\n（${jobReqText(msg.job, jn)}が必要）${more}`);
      }
      if (!r.ok) return reply(false, '');
      // 第51回 F: はじめて 幻の職業に なった（自分の キャラ。家族の 掲示板へ）
      if (firstTime && who === c && JOBS[msg.job].tier === 4) phantomGot(world, who, msg.job);
      // なかまが はずした そうびは ふくろへ
      if (who !== c) {
        for (const e of who.items || []) addItem(c, e.id, e.n);
        who.items = [];
      }
      const removed = r.removed.map((id) => ITEMS[id]?.name).filter(Boolean);
      world.sendParty(partyOf(world, s));
      boardJobChange(world, who, msg.job, first);
      return reply(true, jobDoneText(who.name, jn(msg.job), removed, msg.job, isMasc(who)), { jobChanged: true, who: msg.who || 'self' });
    }
    case 'tavern': {
      let r;
      let text = '';
      switch (msg.action) {
        case 'recruit': {
          // 酒場が いっぱい: farewell の 仲間と さよならしてから（world/farewell.js。第35回）
          let bye = '';
          if (msg.farewell) {
            if (!tavernInfo(world, s).recruits.some((x) => x.key === msg.key)) return reply(false, '見つかりません');
            const f = companionRelease(world, s, String(msg.farewell));
            if (!f.ok) return reply(false, f.reason, { tavern: tavernInfo(world, s) });
            bye = `${farewellText(f)}\n`;
          }
          // 酒場が いっぱい: store の 魔物を あずかり所へ 送ってから（world/storage.js。第43回 C）
          if (msg.store && !msg.farewell) {
            if (!tavernInfo(world, s).recruits.some((x) => x.key === msg.key)) return reply(false, '見つかりません');
            const f = depositMonster(world, s, String(msg.store));
            if (!f.ok) return reply(false, f.reason, { tavern: tavernInfo(world, s) });
            bye = `${storeText(f)}\n`;
          }
          // パーティー → 馬車 → 入れかわり（party.js の placeMember）
          r = recruitNpc(world, s, String(msg.key || ''), { swap: msg.swap ? String(msg.swap) : null, join: msg.join !== false });
          if (r.ok) text = bye + (r.joined ? `${r.name}が仲間に加わった！${r.where === 'wagon' ? `\n${r.name}は馬車に乗りこんだ。` : ''}${r.benchedName ? `\n${r.benchedName}は酒場で待っている。` : ''}${stowText(r.stowed)}` : `${r.name}が仲間になった！\n（今は酒場で待っている）`);
          break;
        }
        case 'join':
          r = companionJoin(world, s, String(msg.key || ''), msg.swap ? String(msg.swap) : null);
          if (r.ok) text = `${r.where === 'wagon' ? `${r.name}が仲間に加わって、馬車に乗りこんだ！` : `${r.name}がパーティーに加わった！`}${r.benchedName ? `\n${r.benchedName}は酒場で待っている。` : ''}${stowText(r.stowed)}`;
          break;
        case 'wait':
          r = companionWait(world, s, String(msg.key || ''));
          if (r.ok) text = `${r.name}は酒場で待っている。${stowText(r.stowed)}`;
          break;
        case 'release':
          r = companionRelease(world, s, String(msg.key || ''));
          if (r.ok) text = farewellText(r);
          break;
        case 'rename':
          r = companionRename(world, s, String(msg.key || ''), msg.name);
          if (r.ok) text = `${r.old}の名前を${r.name}に変えた！`;
          break;
        case 'breedPreview': {
          // みるだけ（なにも かわらない）
          const pv = breedPreview(ensureCompanions(s.char), String(msg.a || ''), String(msg.b || ''), msg.child ? String(msg.child) : null);
          world.send(s, { t: 'svcRes', ok: pv.ok, text: pv.ok ? '' : pv.reason, preview: pv.ok ? pv : null });
          return;
        }
        case 'breedFinder': {
          // 第70回: 作れる 魔物から 選ぶ（みるだけ。world/breed.js の breedFinder）
          const f = breedFinder(s, { child: msg.child ? String(msg.child) : null, low: !!msg.low, room: !!msg.room });
          world.send(s, { t: 'svcRes', ok: f.ok, text: f.ok ? '' : f.reason, finder: f });
          return;
        }
        case 'breed':
          r = breedMonsters(world, s, { a: String(msg.a || ''), b: String(msg.b || ''), child: msg.child ? String(msg.child) : null, inherit: msg.inherit ?? null, name: msg.name, color: msg.color ? String(msg.color) : null });
          // 第53回 D: 色の石を 使うと 色ちがいの 子（colorName）
          if (r.ok) text = `${r.itemName ? `${r.itemName}が光につつまれた…！\n` : ''}${r.color ? '色の石がにじ色に光った…！\n' : ''}${r.name}（${r.colorName || MONSTERS[r.species].name}＋${r.plus}・ランク${r.rank}）が生まれた！${r.newEntry ? `\n${MONSTERS[r.species].name}が図鑑にのった！` : ''}${r.joined ? '' : `\n${r.name}は酒場で待っている。`}`;
          break;
        default:
          // 馬車の 乗りかえ（world/wagon.js）
          r = wagonTavernAction(world, s, msg);
          if (!r) return;
          text = r.text;
      }
      // あずかり中の 親から 生まれた 子は あずかり所に いる（world/breed.js。第43回 C）
      if (msg.action === 'breed' && r.ok && r.stored) text = `${text.replace(`\n${r.name}は酒場で待っている。`, '')}\n${r.name}はあずかり所にいる。`;
      if (!r.ok) return reply(false, r.reason || 'できません', { full: !!r.full, tavern: tavernInfo(world, s) });
      // 第63回: 配合で 生まれた 子（クライアントが 姿を 見せてから「名前をつける？」と たずねる）
      const born = msg.action === 'breed' ? { key: r.key, name: r.name, species: r.species, color: r.color || null } : undefined;
      return reply(true, text, { tavern: tavernInfo(world, s), ...(born ? { born } : {}) });
    }
    case 'board': {
      if (msg.action === 'post') {
        const text = String(msg.text || '').replace(/[<>]/g, '').slice(0, 120).trim();
        if (!text) return reply(false, 'メッセージを入れてね');
        world.data.board = world.data.board || [];
        world.data.board.unshift({ from: c.name, text, time: Date.now() });
        world.data.board = world.data.board.slice(0, 40);
        world.broadcast({ t: 'board', posts: world.data.board });
        return reply(true, 'けいじ板に書きこんだ！', { posts: world.data.board });
      }
      return;
    }
    case 'salon': return salonAction(world, s, msg, reply);
    case 'vehicles': return vehicleShopAction(world, s, msg, reply);
    // 馬車の 総入れかえ（メニューから。へんじを まてるように お店と おなじ 形で。world/wagon.js）
    case 'wagon': {
      if (s.busy) return reply(false, '今はできません');
      const r = wagonMenuAction(world, s, msg);
      return reply(r.ok, r.ok ? r.text : r.reason, { same: !!r.same });
    }
    // 第50回 D3: お話が 進むと ふえる（world/prizes-r50.js）
    case 'starTrade': return starTradeAction(world, s, msg, reply);
    case 'church': {
      if (msg.action === 'record') {
        // さそわれて 手伝っている ときは、自分の いのりの場所は そのまま（自分の 冒険は かわらない）
        const host = world.hostOf?.(s);
        if (host) reply(true, `神のご加護がありますように。\n今は${host.char.name}の冒険を手伝っているので、\nいのりの場所は${host.char.name}と同じです。`);
        else {
          // lv … マップの レイアウトの 版（world.js の posOf・layoutFix。ひろげた ダンジョンの 前の 版の いのりの場所を 見分ける）
          c.spawn = { map: s.map, x: s.x, y: s.y, ...(MAPS[s.map]?.layoutVer ? { lv: MAPS[s.map].layoutVer } : {}) };
          reply(true, '神のご加護がありますように。\nここをいのりの場所として記録しました。');
        }
        world.saveNow({ urgent: true });
        return;
      }
      const target = refChar(world, s, msg.ref);
      if (!target) return reply(false, '');
      if (msg.action === 'revive') {
        if (target.hp > 0) return reply(false, 'その人は生きています');
        const price = revivePrice(target.level);
        if (c.gold < price) return reply(false, 'ゴールドが足りないようですね');
        c.gold -= price;
        target.hp = computeStats(target).maxHp;
        const info = churchInfo(world, s);
        world.sendParty(partyOf(world, s));
        for (const sid of partyOf(world, s)?.members || []) world.sendSelf(world.sessions.get(sid));
        return reply(true, `おお神よ…${target.name}を生き返らせたまえ！\n${target.name}は生き返った！`, { church: info });
      }
      if (msg.action === 'cure') {
        if (!target.status?.poison) return reply(false, '毒にはかかっていません');
        if (c.gold < CURE_PRICE) return reply(false, 'ゴールドが足りないようですね');
        c.gold -= CURE_PRICE;
        target.status = {};
        world.sendParty(partyOf(world, s));
        return reply(true, `${target.name}の毒が消えた！`, { church: churchInfo(world, s) });
      }
      return;
    }
    // 預かり所（bank.js）・ふしぎなかじ屋（forge.js）
    case 'bank': return bankAction(world, s, msg, reply);
    case 'forge': return forgeAction(world, s, msg, reply, { equipItem, ownChar });
    // れん金がま（world/alchemy.js）
    case 'alchemy': return alchemyAction(world, s, msg, reply, { ownChar: (who) => ownChar(s, who) });
    default:
  }
}

// bag: どうぐを だしいれ する ふくろ（なかまの そうびは じぶんの ふくろから）
export function equipItem(c, id, bag = c) {
  const it = ITEMS[id];
  if (!it) return false;
  const slot = it.type;
  if (!SLOTS.includes(slot)) return false;
  if (!canEquipChar(c, id)) return false;
  if (itemCount(bag, id) < 1) return false;
  const old = c.equip[slot];
  removeItem(bag, id, 1);
  if (old) addItem(bag, old, 1);
  c.equip[slot] = id;
  const st = computeStats(c);
  c.hp = Math.min(c.hp, st.maxHp);
  c.mp = Math.min(c.mp, st.maxMp);
  return true;
}

// メニュー（フィールドで つかう どうぐ・じゅもん・そうび）
// 酒場で まつ なかまの 装備を ふくろに しまった ことを 知らせる
function stowText(list) {
  return list?.length ? `\n（装備していた${list.slice(0, 3).join('・')}${list.length > 3 ? 'など' : ''}はふくろにしまった）` : '';
}

export function menuAction(world, s, msg) {
  const c = s.char;
  // 新しい ようす（自分・パーティー）を 先に おくってから 返事（menuRes）。
  // メニューは 返事が とどいた ときに、新しい HP・MP・道具の 数で 画面を 作りなおす（client/ui/menu.js の 道具を 続けて 使う）
  const reply = (ok, text) => {
    world.sendSelf(s);
    const p = partyOf(world, s);
    if (p) world.sendParty(p);
    world.send(s, { t: 'menuRes', ok, text });
    world.markDirty();
  };
  // お気に入りは 戦いの 中でも 変えられる
  if (s.busy && msg.action !== 'favorite') return reply(false, '今はできません');
  switch (msg.action) {
    case 'equip': {
      const who = ownChar(s, msg.who);
      if (!who) return reply(false, '');
      if (!equipItem(who, msg.id, c)) return reply(false, who.species ? `${who.name}には装備できない` : 'その職業では装備できない');
      return reply(true, `${who === c ? '' : who.name + 'は'}${ITEMS[msg.id].name}を装備した！`);
    }
    case 'unequip': {
      const who = ownChar(s, msg.who);
      if (!who || !SLOTS.includes(msg.slot)) return reply(false, '');
      const id = who.equip[msg.slot];
      if (!id) return reply(false, '');
      who.equip[msg.slot] = null;
      addItem(c, id, 1);
      const st = computeStats(who);
      who.hp = Math.min(who.hp, st.maxHp);
      who.mp = Math.min(who.mp, st.maxMp);
      return reply(true, `${who === c ? '' : who.name + 'の'}${ITEMS[id].name}を外した。`);
    }
    // 仲間（自分も）が 装備している 物と 入れかえる（メニューの 装備。client/ui/menu.js の pickGear）
    //   who が from の 装備を 受けとり、from は who の 今の 装備を 受けとる（装備できない ときは ふくろへ）
    case 'swapEquip': {
      const who = ownChar(s, msg.who);
      const from = ownChar(s, msg.from);
      const slot = msg.slot;
      if (!who || !from || who === from || !SLOTS.includes(slot)) return reply(false, '');
      const id = from.equip?.[slot];
      if (!id || !ITEMS[id]) return reply(false, '');
      if (!canEquipChar(who, id)) return reply(false, who.species ? `${who.name}には装備できない` : 'その職業では装備できない');
      const mine = who.equip[slot] || null;
      who.equip[slot] = id;
      from.equip[slot] = null;
      let note = '';
      if (mine) {
        if (canEquipChar(from, mine)) from.equip[slot] = mine;
        else {
          addItem(c, mine, 1);
          note = `\n（${ITEMS[mine].name}は${from.name}には装備できないので、ふくろにしまった）`;
        }
      }
      for (const x of [who, from]) {
        const st = computeStats(x);
        x.hp = Math.min(x.hp, st.maxHp);
        x.mp = Math.min(x.mp, st.maxMp);
      }
      const text = mine && from.equip[slot] === mine ? `${who.name}と${from.name}の${SLOT_NAMES[slot]}を入れかえた！` : `${who.name}は${from.name}の${ITEMS[id].name}を装備した！`;
      return reply(true, text + note);
    }
    // 見た目装備（強さは かわらない。えらべるのは 持っている 物だけ。shared/look-equip.js）
    //   msg.slot … 'weapon'・'armor'・'shield'・'head'（'all' で ぜんぶ もどす）
    //   msg.id … null（今の装備と同じ）・'none'（装備なし）・品物の ID
    // 乗り物を えらぶ・乗らない（第37回。world/vehicles.js）
    case 'vehicle': {
      const r = vehicleMenuAction(world, s, msg);
      return reply(r.ok, r.text);
    }
    case 'lookEquip': {
      const who = ownChar(s, msg.who);
      if (!who) return reply(false, '');
      const r = setLookEquip(who, c, msg.slot, msg.id ?? null);
      return reply(r.ok, r.text);
    }
    case 'discard': {
      const it = ITEMS[msg.id];
      if (!it || it.type === 'key') return reply(false, 'それは捨てられない');
      if (!removeItem(c, msg.id, Math.max(1, msg.n || 1))) return reply(false, '');
      return reply(true, `${it.name}を捨てた。`);
    }
    // 第50回 N6: 家族に 道具を あげる（world/gift.js）。giftList … あげる 相手の 一覧（返事の family）
    case 'giftList':
      return world.send(s, { t: 'menuRes', ok: true, text: '', family: giftTargets(world, s) });
    case 'gift': {
      const r = giveItem(world, s, msg);
      return reply(r.ok, r.text);
    }
    case 'useItem': {
      const it = ITEMS[msg.id];
      if (!it || it.type !== 'use' || !it.field) return reply(false, '今は使えない');
      if (itemCount(c, msg.id) < 1) return reply(false, '持っていない');
      const eff = it.effect;
      // 聖水・魔物よせの笛（あとから 使った ほうが 効く。world/field27.js）
      if (eff.type === 'repel' || eff.type === 'lure') return useAuraItem(world, s, msg.id, reply);
      // 仲間の粉（data/friend-powder.js）
      if (eff.type === 'befriendBoost') return usePowder(world, s, c, msg.id, reply);
      // れん金のメモ（world/alchemy.js）
      if (eff.type === 'alchemyMemo') return useAlchemyMemo(world, s, msg.id, reply);
      if (eff.type === 'warp') {
        // 第6章: 千年前では 使えない（行き先の 町が まだ ない。world/travel.js の PAST_WARP_TEXT）
        // 第59回: 「最後にお祈りしたところ」へは 千年前からも 飛べる
        // 第67回: 千年前では 千年前の 町へ（data/past-places.js）
        const past = isPastMap(s.map);
        if (past && msg.place !== PRAY_PLACE && !PAST_PLACES[msg.place]) return reply(false, PAST_WARP_TEXT(`${c.name}は${it.name}を空に投げた！`));
        // 王家のピラミッド（第4章）: 帰り道の羽は 使えない（道具は へらない。行き先を えらぶ 前に 知らせる）
        if (MAPS[s.map]?.noEscape) return reply(false, noEscapeText(it.name, MAPS[s.map]));
        // 行き先は リーダーと おなじ（パーティーで リーダーの 冒険に 来ている ときは リーダーの きろく。travel.js）
        const dest = msg.place && warpPlaces(warpOwner(world, s), past).includes(msg.place) ? msg.place : null;
        if (!dest) return reply(false, 'どこへ行く？');
        const kind = world.mapKind(s.map);
        if (kind !== 'field' && kind !== 'dungeon') return reply(false, '');
        const to = dest === PRAY_PLACE ? world.prayDest(s) : PAST_PLACES[dest] ? pastLanding(dest) : warpDest(dest);
        if (!to) return reply(false, 'どこへ行く？');
        removeItem(c, msg.id, 1);
        // 「ついていく」なかまも いっしょに（travel.js。ルーラと おなじ）
        warpParty(world, s, to);
        return reply(true, `${c.name}は帰り道の羽を空に投げた！`);
      }
      // 夜明けのすず・夕焼けのすず（travel.js）
      if (eff.type === 'timeBell') return useTimeBell(world, s, msg.id, reply);
      // みちびきの糸（洞窟・塔から 入り口の 外へ。escape.js）
      if (eff.type === 'exit') return useEscapeItem(world, s, msg.id, reply);
      if (String(msg.ref || '').startsWith('wagon:') && !wagonHere(s.map)) return reply(false, '馬車は入り口で待っている…');
      const target = refChar(world, s, msg.ref);
      if (!target) return reply(false, '');
      // 第44回: 進化の 石（イーブイに 使うと 進化。world/evolve.js）
      if (eff.type === 'evoStone') return useEvoStone(world, s, msg.id, target, reply);
      // 第50回 D3: 景品の 道具（乗り物券・よびぶえ・修行の書・経験の書。world/prizes-r50.js）
      if (PRIZE_USE.has(eff.type)) return usePrizeItem(world, s, msg.id, target, reply);
      const r = applyFieldEffect(world, c, target, eff);
      if (!r.ok) return reply(false, r.text);
      removeItem(c, msg.id, 1);
      return reply(true, `${c.name}は${it.name}を使った！\n${r.text}`);
    }
    // 第6章: 時の砂時計（大事な物。メニューの「道具」から）
    case 'timeGlass': return useTimeGlass(world, s, reply);
    case 'starSight': return useStarSight(world, s, reply);
    case 'bookmark': return useBookmark(world, s, reply);
    // 第50回 N3: すぐ使う ボタン（HUD・コントローラー・T キー。data/quick-item.js）。メニューの「使う」と おなじ
    case 'quickUse': {
      const id = quickItemOf(c);
      if (!id) return reply(false, 'すぐ使う大事な物がない。\n（メニューの「道具」→「大事な物」で選べる）');
      const use = quickUseOf(id);
      if (use === 'timeGlass') return useTimeGlass(world, s, reply);
      if (use === 'starSight') return useStarSight(world, s, reply);
      if (use === 'bookmark') return useBookmark(world, s, reply);
      return reply(false, '今は使えない');
    }
    case 'quickSet': {
      const r = setQuickItem(c, msg.id ?? null);
      return reply(r.ok, r.text);
    }
    case 'quickPad': {
      const r = setQuickPad(c, msg.pad);
      return reply(r.ok, r.text);
    }
    // 第50回 N7: チャットの スタンプを 変える（data/stamps.js。知らせは なし）
    case 'stamps': {
      const r = setStamps(c, msg.list);
      return reply(r.ok, r.text);
    }
    case 'cast': {
      const caster = ownChar(s, msg.who);
      if (!caster) return reply(false, '');
      if (caster.hp <= 0) return reply(false, `${caster.name}は死んでいる…`);
      // 馬車の 仲間が 唱えるのも、相手が 馬車の 仲間なのも、馬車が いっしょの ときだけ
      const inWagon = (c.wagonKeys || []).includes(msg.who) || String(msg.ref || '').startsWith('wagon:');
      if (inWagon && !wagonHere(s.map)) return reply(false, '馬車は入り口で待っている…');
      const a = abilityFor(msg.id, caster);
      if (!a || !a.field || !learnedAbilities(caster).includes(msg.id)) return reply(false, '今は使えない');
      // 呪文が ふうじられた 場所（王家のピラミッド 2階）: 呪文は 使えない（MPは へらない。特技は 使える）
      if (MAPS[s.map]?.noSpells && spellSealed(a)) return reply(false, `${caster.name}は${a.name}を唱えた！\nしかし呪文の力が、すいこまれてしまった…\n（ここでは呪文が使えない。特技や道具を使おう）`);
      // ルーラ（行った 町へ 仲間と 飛ぶ。travel.js）
      if (a.effect?.type === 'warp') return castRura(world, s, caster, msg.id, msg, reply);
      // リレミト・トヘロス・マモノヨセ（world/field27.js）
      if (FIELD27_EFFECTS.has(a.effect?.type)) return castField27(world, s, caster, msg.id, reply);
      const cost = mpCost(caster, msg.id);
      if (caster.mp < cost) return reply(false, 'MPが足りない！');
      const pen = penaltyFor(caster, msg.id);
      const targets = a.target === 'allies' ? allRefs(world, s).map((r) => refChar(world, s, r)).filter(Boolean) : [refChar(world, s, msg.ref)].filter(Boolean);
      if (!targets.length) return reply(false, '');
      const texts = [];
      let any = false;
      for (const t of targets) {
        const r = applyFieldEffect(world, caster, t, a.effect, pen.powMult, skillMods(caster, msg.id).healMul);
        if (r.ok) any = true;
        texts.push(r.text);
      }
      if (!any) return reply(false, texts[0] || '効果がなかった');
      caster.mp -= cost;
      return reply(true, `${caster.name}は${a.name}を唱えた！\n${texts.filter(Boolean).slice(0, 3).join('\n')}`);
    }
    case 'tactics': {
      const t = TACTICS[msg.tactics] ? msg.tactics : null;
      if (!t) return reply(false, '');
      if (msg.key === 'self') {
        if (t === 'manual') return reply(false, '');
        c.tactics = t;
        return reply(true, `作戦を「${TACTICS[t].name}」にした。`);
      }
      const p = partyOf(world, s);
      const own = companionOf(ensureCompanions(c), msg.key);
      const sup = p?.supports.find((x) => x.key === msg.key && x.owner === c.id);
      const target = own?.char || sup?.char;
      if (!target) return reply(false, '');
      target.tactics = t;
      return reply(true, `${target.name}の作戦を「${TACTICS[t].name}」にした。`);
    }
    // オートの ときに 使う 技・使わない 技（作戦の「オートで使う技を選ぶ」）。char.autoOff に 使わない 技を おぼえる（ai.js）
    //   key: 'self' か 自分の 仲間 / op: 'on'（使う）・'off'（使わない）・'all'（全部 使う）
    // 第71回: 命令の 一覧に 出さない 技（作戦の「命令で出す技を選ぶ」・呪文・技の メニュー）は 別の char.cmdOff（cmdSkill。shared/cmd-off.js）
    //   op: 'on'（出す）・'off'（出さない）・'all'（全部 出す）。cmdOff は 空でも 配列で のこす（autoOff から うつしかえ ずみ の しるし）
    case 'autoSkill':
    case 'cmdSkill': {
      const p = partyOf(world, s);
      const own = msg.key === 'self' ? null : companionOf(ensureCompanions(c), msg.key);
      const sup = msg.key === 'self' ? null : p?.supports.find((x) => x.key === msg.key && x.owner === c.id);
      const targets = msg.key === 'self' ? [c] : [...new Set([own?.char, sup?.char].filter(Boolean))];
      if (!targets.length) return reply(false, '');
      const t0 = targets[0];
      // autoOff を かえる 前に、まだの 人は 今の autoOff を cmdOff に うつす（第69回の 決めた ことを のこす）
      for (const t of targets) fixCmdOff(t);
      const cmd = msg.action === 'cmdSkill';
      const list = toggleOffList(cmd ? cmdOffList(t0) : t0.autoOff, learnedAbilities(t0), msg.op, msg.id);
      if (!list) return reply(false, '');
      for (const t of targets) {
        if (cmd) t.cmdOff = list;
        else if (list.length) t.autoOff = list;
        else delete t.autoOff;
      }
      if (msg.op !== 'all') return reply(true, '');
      return reply(true, cmd ? `${t0.name}は、どの技も命令の一覧に出す。` : `${t0.name}は、どの技も使う。`);
    }
    // さいきょう装備（ドラクエ風）: ふくろの 中から 攻撃力・守備力が いちばん 上がる ものを 装備する
    // モンスターの なかまも（しゅぞくで 装備できる 物だけ）
    case 'bestEquip': {
      const team = msg.who === 'all' ? ownTeamChars(world, s) : [ownChar(s, msg.who || 'self')].filter(Boolean);
      // equip-plan.js で 見こみを 出して、その とおりに 装備する（メニューの「何が 何に 変わるか」と おなじ 計算）
      const plan = bestEquipPlan(team.map((ch, i) => ({ key: i, char: ch })), c);
      const lines = [];
      for (const p of plan) {
        const who = team[p.key];
        const got = p.changes.filter((x) => equipItem(who, x.to, c)).map((x) => ITEMS[x.to].name);
        if (got.length) lines.push(`${who.name}: ${got.join('・')}`);
      }
      if (!lines.length) return reply(false, 'もういちばん強い装備をしている');
      return reply(true, `さいきょう装備にした！\n${lines.slice(0, 4).join('\n')}`);
    }
    // まんたん: 呪文で（MPの むだが 少ない じゅんに）か 道具で、みんなの HPを 満タンに
    case 'fullHeal': {
      const r = msg.mode === 'item' ? fullHealByItems(world, s) : fullHealBySpells(world, s);
      return reply(r.ok, r.text);
    }
    // 馬車の 乗りかえ（world/wagon.js）
    case 'wagon': {
      const r = wagonMenuAction(world, s, msg);
      return reply(r.ok, r.ok ? r.text : r.reason);
    }
    // パーティーの ならびかえ（先頭ほど 敵に ねらわれやすい）
    case 'order': {
      const r = setPartyOrder(world, s, msg.order);
      return reply(r.ok, r.ok ? 'ならびを変えた。' : r.reason);
    }
    // 技の お気に入り（ならびも おぼえる）。who: 'self' か 自分の 仲間
    case 'favorite': {
      const who = ownChar(s, msg.who || 'self');
      const id = msg.id;
      if (!who || who.species) return reply(false, '');
      // 第69回: ならびを まとめて（メニューの お気に入りで つかんで うごかした あと）。今の お気に入りと おなじ 技の くみ だけ
      if (msg.op === 'order') {
        const r = favoriteOrder(who.favorites, msg.ids);
        if (!r) return reply(false, '');
        who.favorites = r;
        syncFavs(world, who);
        return reply(true, 'ならびを変えた。');
      }
      if (!ABILITIES[id]) return reply(false, '');
      // 第72回: まえは 30こ いっぱいの とき だまって 入れなかった（返事は「入れた」）。
      //   今は FAV_MAX こまで。いっぱいなら 覚えていない 技を すてて、それでも いっぱいなら わけを 返す（shared/favorites.js）
      const r = favApply(who.favorites, id, msg.op, new Set(learnedAbilities(who)));
      if (!r.ok) return reply(false, r.full ? FAV_FULL_TEXT : '');
      who.favorites = r.list;
      // 戦いの 中（長おしで お気に入り。第27回）: 戦いの 人の お気に入りも（つぎの 知らせで 前に もどらない）
      syncFavs(world, who);
      return reply(true, msg.op === 'add' ? `${abilityLabel(id, who)}をお気に入りに入れた。` : msg.op === 'remove' ? `${abilityLabel(id, who)}をお気に入りからはずした。` : 'ならびを変えた。');
    }
    case 'settings': {
      const old = c.battleSettings || {};
      const cur = normBattleSettings(old);
      c.battleSettings = {
        ...old,
        sv: 2,
        speed: BATTLE_SPEEDS.includes(msg.speed) ? msg.speed : cur.speed,
        textSpeed: TEXT_SPEEDS.includes(msg.textSpeed) ? msg.textSpeed : cur.textSpeed,
        wait: msg.wait === undefined ? !!old.wait : !!msg.wait,
        auto: msg.auto === undefined ? !!old.auto : !!msg.auto,
      };
      // ゲームの むずかしさ（difficulty.js）。ぜんぶ ふつうなら のこさない
      if (msg.difficulty && typeof msg.difficulty === 'object') {
        const d = normDifficulty(c.difficulty, msg.difficulty);
        if (d) c.difficulty = d;
        else delete c.difficulty;
      }
      // 第78回 3-6: メニューの 表示（くわしい／かんたん。キャラごと。かんたん の 時だけ 項目が のこる。shared/menu-view.js）
      if (msg.menuView !== undefined) setMenuView(c, msg.menuView);
      return reply(true, '設定を変えた。');
    }
    // 第35回: お知らせを 読んだ（data/news.js。返事の 知らせ・音は なし）
    case 'newsRead': {
      if (markNewsRead(c, msg.ids)) {
        world.sendSelf(s);
        world.markDirty();
      }
      return;
    }
    // 第50回 N4: 困っている人を 知らせた（told）・クエストの 画面で 見た（seen）。返事の 知らせ・音は なし
    case 'subAsk': {
      if (markAsks(c, msg.kind, msg.ids)) {
        world.sendSelf(s);
        world.markDirty();
      }
      return;
    }
    default:
      return reply(false, '');
  }
}

// ───── さいきょう装備 ─────
// 自分と 自分の 仲間（戦う 仲間を ならびの じゅんに → 馬車の 仲間。equip-plan.js の bestTeamOrder）
function ownTeamChars(world, s) {
  const p = partyOf(world, s);
  const sups = (p?.supports || []).filter((x) => x.owner === s.char.id && x.kind !== 'family').map((x) => x.char);
  return bestTeamOrder(s.char, sups, ownWagonEntries(world, s).map((e) => e.char), s.char.selfPos);
}

// ───── まんたん ─────
// 回復の 見こみ（applyFieldEffect と おなじ 式の まんなか）
function expectedHeal(user, eff, powMult = 1) {
  let amt = (eff.base[0] + eff.base[1]) / 2;
  if (!eff.fixed) amt *= 1 + Math.max(0, Math.min(1, (computeStats(user).heal - (eff.thr ?? 20)) / 150));
  return amt * powMult;
}

// HPが へっている 生きた 仲間
function hurtRefs(world, s) {
  return allRefs(world, s).map((ref) => ({ ref, ch: refChar(world, s, ref) })).filter(({ ch }) => ch && ch.hp > 0 && ch.hp < computeStats(ch).maxHp);
}
const lack = (ch) => computeStats(ch).maxHp - ch.hp;

function fullHealSummary(world, s, used) {
  const left = hurtRefs(world, s);
  const lines = [];
  if (used.length) lines.push(used.join('、'));
  if (!left.length) lines.push('みんなのHPが満タンになった！');
  else lines.push(`まだ回復しきれていない: ${left.slice(0, 3).map(({ ch }) => `${ch.name} ${ch.hp}/${computeStats(ch).maxHp}`).join('、')}`);
  return lines.join('\n');
}

function fullHealBySpells(world, s) {
  if (!hurtRefs(world, s).length) return { ok: false, text: 'みんなのHPは満タンだ' };
  // 呪文が ふうじられた 場所では 回復の 特技だけ（呪文は つかわない）
  const sealed = !!MAPS[s.map]?.noSpells;
  const p = partyOf(world, s);
  const casters = [s.char, ...(p?.supports || []).filter((x) => x.owner === s.char.id && x.kind !== 'family').map((x) => x.char),
    ...wagonHealEntries(world, s, true).map((e) => e.char)].filter((ch) => ch.hp > 0);
  const count = new Map(); // 「名前|呪文」→ 回数
  const mpUsed = new Map();
  let any = false;
  for (let guard = 0; guard < 80; guard++) {
    const hurt = hurtRefs(world, s);
    if (!hurt.length) break;
    // 1ばん へっている 人から
    hurt.sort((a, b) => lack(b.ch) - lack(a.ch));
    const tgt = hurt[0];
    const need = lack(tgt.ch);
    const totalNeed = hurt.reduce((a, h) => a + lack(h.ch), 0);
    let best = null;
    for (const ch of casters) {
      for (const id of learnedAbilities(ch)) {
        const a = ABILITIES[id];
        if (!a?.field || a.effect?.type !== 'heal' || !['ally', 'allies'].includes(a.target)) continue;
        if (sealed && spellSealed(a)) continue;
        const cost = mpCost(ch, id);
        if (ch.mp < cost) continue;
        const pen = penaltyFor(ch, id);
        const hm = skillMods(ch, id).healMul;
        const amt = expectedHeal(ch, a.effect, pen.powMult * hm);
        // 役に立つ 回復量（あふれた ぶんは むだ）
        const useful = a.target === 'allies' ? hurt.reduce((x, h) => x + Math.min(lack(h.ch), amt), 0) : Math.min(need, amt);
        if (a.target === 'allies' && hurt.length < 2) continue;
        // MPあたりの 回復が 多い もの。1回で たりる なら 少ない MPの ものを えらぶ
        const enough = a.target === 'allies' ? useful >= totalNeed * 0.8 : amt >= need;
        const score = useful / Math.max(1, cost) + (enough ? 1000 / Math.max(1, cost) : 0);
        if (!best || score > best.score) best = { ch, id, a, cost, pen, hm, score };
      }
    }
    if (!best) break;
    const targets = best.a.target === 'allies' ? hurt.map((h) => h.ch) : [tgt.ch];
    let ok = false;
    for (const t of targets) if (applyFieldEffect(world, best.ch, t, best.a.effect, best.pen.powMult, best.hm).ok) ok = true;
    if (!ok) break;
    best.ch.mp -= best.cost;
    any = true;
    const key = `${best.ch.name}|${best.a.name}`;
    count.set(key, (count.get(key) || 0) + 1);
    mpUsed.set(best.ch.name, (mpUsed.get(best.ch.name) || 0) + best.cost);
  }
  if (!any && sealed) return { ok: false, text: 'ここでは呪文がふうじられている…\n（回復の特技か、道具で回復しよう）' };
  if (!any) return { ok: false, text: 'HPを回復できる呪文を使える人がいない…\n（MPが足りないか、回復の呪文を覚えていない）' };
  const byWho = new Map();
  for (const [k, n] of count) {
    const [who, sp] = k.split('|');
    if (!byWho.has(who)) byWho.set(who, []);
    byWho.get(who).push(`${sp}×${n}`);
  }
  const used = [...byWho].map(([who, list]) => `${who}: ${list.join('・')}（MP${mpUsed.get(who)}）`);
  return { ok: true, text: fullHealSummary(world, s, used) };
}

function fullHealByItems(world, s) {
  if (!hurtRefs(world, s).length) return { ok: false, text: 'みんなのHPは満タンだ' };
  const c = s.char;
  const count = new Map();
  let any = false;
  for (let guard = 0; guard < 99; guard++) {
    const hurt = hurtRefs(world, s);
    if (!hurt.length) break;
    hurt.sort((a, b) => lack(b.ch) - lack(a.ch));
    const tgt = hurt[0];
    const need = lack(tgt.ch);
    // たりる 中で いちばん 小さい 薬。たりなければ いちばん 大きい 薬
    const heals = c.items.filter((e) => e.n > 0 && ITEMS[e.id]?.type === 'use' && ITEMS[e.id].field && ITEMS[e.id].effect?.type === 'heal' && ITEMS[e.id].target === 'ally')
      .map((e) => ({ id: e.id, amt: expectedHeal(c, ITEMS[e.id].effect) }));
    if (!heals.length) break;
    const enough = heals.filter((h) => h.amt >= need).sort((a, b) => a.amt - b.amt);
    const pick = enough[0] || heals.sort((a, b) => b.amt - a.amt)[0];
    if (!applyFieldEffect(world, c, tgt.ch, ITEMS[pick.id].effect).ok) break;
    removeItem(c, pick.id, 1);
    any = true;
    count.set(pick.id, (count.get(pick.id) || 0) + 1);
  }
  if (!any) return { ok: false, text: 'HPを回復する道具を持っていない…' };
  const used = [`${[...count].map(([id, n]) => `${ITEMS[id].name}×${n}`).join('・')}を使った`];
  return { ok: true, text: fullHealSummary(world, s, used) };
}

function allRefs(world, s) {
  const p = partyOf(world, s);
  const refs = ['self'];
  for (const sid of p?.members || []) if (sid !== s.id) refs.push('sid:' + sid);
  for (const sup of p?.supports || []) refs.push('sup:' + sup.key);
  for (const g of p?.guests || []) refs.push('guest:' + g.id);
  // 馬車の 仲間（馬車が いっしょの とき）
  for (const e of wagonHealEntries(world, s)) refs.push('wagon:' + e.key);
  return refs;
}

// hm … 回復の 量の 倍率（技の ランク。skill-tier.js）
function applyFieldEffect(world, user, target, eff, powMult = 1, hm = 1) {
  const st = computeStats(target);
  switch (eff.type) {
    case 'heal': {
      if (target.hp <= 0) return { ok: false, text: `${target.name}は死んでいる…` };
      if (target.hp >= st.maxHp) return { ok: false, text: `${target.name}のHPは満タンだ` };
      let amt = world.rng.int(eff.base[0], eff.base[1]);
      if (!eff.fixed) amt *= 1 + Math.max(0, Math.min(1, (computeStats(user).heal - (eff.thr ?? 20)) / 150));
      amt = Math.round(amt * powMult * hm);
      const real = Math.min(st.maxHp - target.hp, amt);
      target.hp += real;
      return { ok: true, text: target.hp >= st.maxHp ? `${target.name}のキズがすっかり回復した！` : `${target.name}のHPが${real}回復した！` };
    }
    case 'mpHeal': {
      if (target.mp >= st.maxMp) return { ok: false, text: `${target.name}のMPは満タンだ` };
      const d = Math.min(st.maxMp - target.mp, world.rng.int(eff.base[0], eff.base[1]));
      target.mp += d;
      return { ok: true, text: `${target.name}のMPが${d}回復した！` };
    }
    case 'cure': {
      if (!target.status?.poison || !eff.statuses.includes('poison')) return { ok: false, text: 'しかし何も起こらなかった' };
      target.status = {};
      return { ok: true, text: `${target.name}の毒が消えた！` };
    }
    case 'revive': {
      if (target.hp > 0) return { ok: false, text: `${target.name}は生きている` };
      target.hp = Math.max(1, Math.min(st.maxHp, Math.round(st.maxHp * (eff.hpRatio || 0.25) * hm)));
      return { ok: true, text: `なんと${target.name}が生き返った！` };
    }
    case 'seed': {
      const n = world.rng.int(eff.amount[0], eff.amount[1]);
      target.seeds = target.seeds || {};
      target.seeds[eff.stat] = (target.seeds[eff.stat] || 0) + n;
      const names = { str: '力', def: '身の守り', agi: '素早さ', mag: '攻撃魔力', hp: '最大HP', mp: '最大MP', heal: '回復魔力' };
      return { ok: true, text: `${target.name}の${names[eff.stat]}が${n}上がった！` };
    }
    case 'multi': {
      // いくつかの 効き目（回復と 治す など）: 1つでも 効けば 使えた ことに する
      const rs = (eff.parts || []).map((p) => applyFieldEffect(world, user, target, p, powMult, hm)).filter((r) => r.ok);
      return rs.length ? { ok: true, text: rs.map((r) => r.text).join('\n') } : { ok: false, text: target.hp <= 0 ? `${target.name}は死んでいる…` : `${target.name}は元気だ` };
    }
    default:
      return { ok: false, text: '今は使えない' };
  }
}

export function warpPos(place) {
  if (place === 'village') return [PLACES.village.x + 16.5, PLACES.village.y - 1.5];
  if (place === 'town') return [PLACES.town.x + 24, PLACES.town.y + 37];
  return POS.villagePlaza;
}

// 帰り道の羽の 行き先（マップと いち）
export function warpDest(place) {
  const sp = SEA_PLACES[place];
  if (sp) return { map: sp.map, x: sp.x + 0.5, y: sp.y + 0.5 };
  const [x, y] = warpPos(place);
  return { map: 'overworld', x, y };
}

js/shared/world/shiori.js:
// 第78回: 冒険のしおり（docs/plan-r78-shiori.md）
//   「つぎに 何を すれば いいか」「何が のこって いるか」を 1まいで 見せる ための まとめ。
//   キャラ（c）だけを 見て 答えを 作る 純粋な 関数（c は かえない）。サーバーでも ひとりモードでも おなじ
//   （client/ui/shiori.js が g.me を わたす。サーバーは キャラを まるごと 'self' で おくって いるので、たのむ 物は ない）
//
// ネタバレの きまり（docs の 4）:
//   ・まだ 開いて いない しくみは 出さない（数にも 入れない）。先の 章で 開く 物も 入れない
//   ・ボスの 名前・物語の 先・かくれた 職業の じょうけんは 書かない。名前を 知らない 物は「？？？」
//   ・物語の 幕の 名前は、その 幕の はじまりの 文字（ゲームの 中の chapter）を 見た あとだけ
import { OBJECTIVE_TARGETS, liveTargets, whereName, subQuests } from '../data/quest-targets.js';
import { OBJECTIVE_TALK } from '../data/party-talk.js';
import { subQuestHints, availableSubQuests, subQuestStarted } from '../data/subquest-hints.js';
import { jobLine } from '../data/fq-common.js';
import { ARENA_RANKS, rankOpen, rankCleared, rankLabel, arenaOpen } from '../data/arena.js';
import { MONARENA_RANKS, MONARENA_OPEN_FLAG, monRankOpen, monRankCleared } from '../data/monarena.js';
import { TM_LV_MAX, tmTitle } from '../data/treasure.js';
import { tmPlaceShort } from '../data/treasure-hint.js';
import { tierInfo, TIER_MAX, tmClearCount } from '../data/casino-tier.js';
import { sdRecordOf, SD_OPEN_FLAG, SD_GUARD_EVERY } from '../data/secret.js';
import { phantomBook } from '../data/phantom.js';
import { JOBS, JOB_MAX_LEVEL } from '../data/jobs.js';
import { TRIALS, trialJob, trialsCleared, trialState } from '../data/job-trials.js';
import { bestiaryOrder } from '../data/companions.js';
import { MONSTERS } from '../data/monsters.js';
import { medalsFound, medalsGiven, medalsHeld, nextMedalReward } from '../data/casino.js';
import { canLimitBreak, lbOf } from '../data/forge.js';
import { LB_MAX } from '../data/items-forge.js';
import { ITEMS } from '../data/items.js';
import { MAPS, condOk } from '../maps/index.js';
import { jobLabel } from '../job-label.js';
// 第80回 E班: ボスに 負けた 時の ヒント（今までに 出た 物。物語の だんに 出す）
import { bossHintsSeen } from '../data/boss-hints.js';

const flagFn = (c) => (k) => !!c?.flags?.[k];
const npcWhere = (id) => whereName({ npc: id }) || '';

// ───────────── 1. 物語（今の 部・章・幕）─────────────
// start … その 章が 始まった しるし / clear … クリアの しるし / title … 章の 名前（seen の しるしの あとだけ 出す）
// acts … 幕（start … 幕の はじまり、title … 幕の 名前、seen … その 名前を 見た しるし）
export const CHAPTERS = [
  { n: 0, part: 1, start: null, clear: 'p_attack', title: 'ホシフル村の祭り' },
  { n: 1, part: 1, start: 'p_attack', clear: 'c1_clear', title: '始まりの星' },
  { n: 2, part: 1, start: 'c2_start', clear: 'c2_clear', title: '海をわたる風' },
  { n: 3, part: 1, start: 'c3_start', clear: 'c3_clear', title: '星の竜がねむる山' },
  { n: 4, part: 1, start: 'c4_start', clear: 'c4_clear', title: '砂の海にしずむ星' },
  { n: 5, part: 1, start: 'c5_start', clear: 'c5_clear', title: '空にうかぶ大地' },
  {
    n: 6, part: 2, start: 'c6_start', clear: 'c6_clear', title: '時の砂時計',
    acts: [
      { n: 1, start: 'c6_start' },
      { n: 2, start: 'c6_tree' },
      { n: 3, start: 'c6_flow', title: '星読みの社', seen: 'c6_flow' },
      { n: 4, start: 'c6_kanata', title: '止まった時計塔', seen: 'c6_kanata' },
    ],
  },
  {
    // 章の 名前は 千年前の コガネ地方に 着いた 時の 文字で はじめて 出る
    n: 7, part: 2, start: 'c7_start', clear: 'c7_clear', title: '最初の紋章の勇者たち', titleSeen: 'c7_arrive',
    acts: [
      { n: 1, start: 'c7_start' },
      { n: 2, start: 'c7_karim', title: '海の紋章', seen: 'c7s_arrive' },
      { n: 3, start: 'c7_kai', title: 'ひとりぼっちの星', seen: 'c7i_arrive' },
    ],
  },
  {
    n: 8, part: 2, start: 'c8_start', clear: null, title: '千年の約束',
    acts: [
      { n: 1, start: 'c8_start', title: '月の王宮のうらぎり', seen: 'c8a_arrive', clear: 'c8_jafar' },
      { n: 2, start: 'c8_jafar', title: 'よみの青い火', seen: 'c8b_arrive', clear: 'c8_hades' },
      { n: 3, start: 'c8_hades', title: 'くろがねの空中ようさい', seen: 'c8c_arrive', clear: 'c8_bowser' },
    ],
  },
];
const PART_NAMES = { 1: '第1部', 2: '第2部' };

// 今の 章・幕。{ part, chapter, act, label, title, actTitle, cleared }
export function storyPlace(c) {
  const f = flagFn(c);
  let ch = CHAPTERS[0];
  for (const C of CHAPTERS) if (C.start && f(C.start)) ch = C;
  let act = null;
  for (const A of ch.acts || []) if (f(A.start)) act = A;
  const cleared = act?.clear ? f(act.clear) : !!(ch.clear && f(ch.clear) && ch.n > 0);
  const chName = ch.n === 0 ? '序章' : `第${ch.n}章`;
  const title = !ch.titleSeen || f(ch.titleSeen) ? ch.title : '';
  const actTitle = act?.title && f(act.seen) ? act.title : '';
  const parts = [ch.n === 0 ? '' : PART_NAMES[ch.part], chName, act ? `第${act.n}幕` : ''].filter(Boolean);
  return { part: ch.n === 0 ? 0 : ch.part, chapter: ch.n, act: act?.n || 0, label: parts.join(' '), title, actTitle, cleared };
}

// 物語の つぎ（目標の 文・仲間の ひとこと・場所）
export function storyNext(c) {
  const obj = String(c?.objective || '');
  const specs = OBJECTIVE_TARGETS[obj];
  const where = specs ? liveTargets(c, specs).map((s) => whereName(s)).find(Boolean) || '' : '';
  const talk = OBJECTIVE_TALK[obj];
  const hint = talk ? talk.kind || '' : '';
  // 「続きはアップデートで！」… 今は 物語の 先が ない
  const end = /アップデート/.test(obj);
  return { objective: obj, where, hint, end };
}

// ───────────── 2. のこって いる こと（しくみごとの 進みぐあい）─────────────
// 1つの しくみ: { id, name, now, total（ない ときは null）, unit, note, where, items: [{ name, where, state, right }] }
//   state … 'done'（すんだ）・'now'（とちゅう・受けている）・'open'（できる）・'wait'（まだ）・'unknown'（？？？）
const STATE_ORDER = { now: 0, open: 1, wait: 2, unknown: 3, done: 4 };
const byState = (a, b) => STATE_ORDER[a.state] - STATE_ORDER[b.state];

const BOARD_WHERE = () => npcWhere('fq_board') || 'ルミナの町';

// お仕事いらい・より道（data/subquest-hints.js の 一らん。開いた 物だけ）
function questRows(c, board) {
  const f = flagFn(c);
  const ready = new Set(subQuests(c).filter((q) => q.ready).map((q) => q.name));
  return subQuestHints().filter((q) => !!q.board === board && q.open.every(f)).map((q) => {
    const done = f(q.done);
    const started = !done && subQuestStarted(c, q);
    const right = done ? 'すんだ' : ready.has(q.name) ? '報告できる' : started ? '受けている' : '受けられる';
    const can = board && q.roots && !done && !started ? (jobLine(q.roots).has(c?.job) ? '（今の職業で解決できそう）' : `（${q.job}の職業）`) : '';
    return { id: q.id, name: q.name, where: `${q.place}・${q.who}${can}`, state: done ? 'done' : started ? 'now' : 'open', right };
  });
}

function boardTrack(c) {
  const items = questRows(c, true);
  if (!items.length) return null;
  const done = items.filter((x) => x.state === 'done').length;
  return {
    id: 'board', name: 'お仕事いらい', now: done, total: items.length, unit: 'こ', where: `${BOARD_WHERE()}のお仕事いらい板`,
    note: 'はり紙を読むと、だれに会えば始まるかわかる。', items: items.sort(byState),
  };
}

function sideTrack(c) {
  const items = questRows(c, false);
  if (!items.length) return null;
  const done = items.filter((x) => x.state === 'done').length;
  return { id: 'side', name: 'より道（たのまれごと）', now: done, total: items.length, unit: 'こ', where: '', note: '町や村で、困っている人の話を聞こう。', items: items.sort(byState) };
}

// サファラ闘技場（物語で 開いた ランクだけ。王者の 名前は 出さない）
function arenaTrack(c) {
  const f = flagFn(c);
  if (!arenaOpen(f)) return null;
  const ranks = ARENA_RANKS.filter((R) => !R.needFlag || f(R.needFlag));
  const items = ranks.map((R) => {
    const done = rankCleared(c, R.rank);
    const ok = rankOpen(R.rank, f, c).ok;
    return { name: rankLabel(R.rank), where: `おすすめLv${R.lv}`, state: done ? 'done' : ok ? 'open' : 'wait', right: done ? '勝ちぬいた' : ok ? 'ちょうせんできる' : 'まだ' };
  });
  return {
    id: 'arena', name: 'サファラ闘技場', now: items.filter((x) => x.state === 'done').length, total: items.length, unit: 'ランク',
    where: `${npcWhere('arena_desk') || '王都サファラ'}の闘技場`, note: '1つのランクは3連戦。物語を進めると、上のランクが開く。', items,
  };
}

// モンスター闘技場
function monArenaTrack(c) {
  const f = flagFn(c);
  if (!f(MONARENA_OPEN_FLAG)) return null;
  const ranks = MONARENA_RANKS.filter((R) => f(R.need));
  const items = ranks.map((R) => {
    const done = monRankCleared(c, R.rank);
    const ok = monRankOpen(R.rank, f, c).ok;
    return { name: `ランク${R.rank}「${R.title}」`, where: `魔物のおすすめLv${R.lv}`, state: done ? 'done' : ok ? 'open' : 'wait', right: done ? '勝ちぬいた' : ok ? 'ちょうせんできる' : 'まだ' };
  });
  if (!items.length) return null;
  return {
    id: 'monarena', name: 'モンスター闘技場', now: items.filter((x) => x.state === 'done').length, total: items.length, unit: 'ランク',
    where: 'ルミナの町の東門を出てすぐ北の、モンスター闘技場', note: '育てた魔物4ひきで戦う3連戦。', items,
  };
}

// 宝の地図（ふかさ ＝ 持っている 地図の いちばん 高い レベル）とカジノの 段
function tmapTrack(c) {
  const maps = Array.isArray(c?.treasureMaps) ? c.treasureMaps.filter((t) => t && Number.isFinite(t.lv)) : [];
  const clears = tmClearCount(c);
  if (!c?.flags?.tm_intro && !maps.length && !clears) return null;
  const best = Math.max(0, ...maps.map((t) => t.lv));
  const tier = tierInfo(c);
  const left = maps.filter((t) => !t.cleared).sort((a, b) => a.lv - b.lv);
  const items = left.map((t) => ({ name: tmTitle(t), where: tmPlaceShort(t), state: t.found ? 'now' : 'open', right: t.found ? '洞窟が開いた' : 'まだほっていない' }));
  const casino = tier.tier >= TIER_MAX ? `カジノの段：${tier.name}（いちばん上）` : `カジノの段：${tier.name}（つぎの段まで、あと${tier.left}まい）`;
  return {
    id: 'tmap', name: '宝の地図', now: best, total: TM_LV_MAX, unit: 'Lv', where: '地図の場所で地面を調べる',
    note: `宝をほった地図：${clears}まい\n${casino}`, items,
  };
}

// ひみつのダンジョン（終わりが ない ので、つぎの 番人の 階までの 棒）
function sdTrack(c) {
  if (!c?.flags?.[SD_OPEN_FLAG]) return null;
  const r = sdRecordOf(c);
  const goal = (Math.floor(r.best / SD_GUARD_EVERY) + 1) * SD_GUARD_EVERY;
  return {
    id: 'sd', name: 'ひみつのダンジョン', now: r.best, total: goal, unit: '階', where: 'ルミナの町の南門の近く',
    note: `いちばん深い所：${r.best ? `${r.best}階` : 'まだ入っていない'}${r.save ? `\n記録した階：${r.save}階` : ''}\n10階ごとに番人がいる。`, items: [],
  };
}

// 職業（ついた ことの ある 職業だけ。まだ ついて いない 職業の 名前・なりかたは 出さない）
function jobsTrack(c) {
  const ids = Object.keys(c?.jobs || {}).filter((id) => JOBS[id]);
  if (!ids.length) return null;
  const items = ids.map((id) => {
    const lv = c.jobs[id]?.lv || 1;
    const done = lv >= JOB_MAX_LEVEL;
    return { name: jobLabel(id, c), where: id === c.job ? '今の職業' : '', state: done ? 'done' : id === c.job ? 'now' : 'open', right: done ? `マスター（Lv${lv}）` : `Lv${lv}/${JOB_MAX_LEVEL}` };
  }).sort(byState);
  return {
    id: 'jobs', name: '職業のマスター', now: items.filter((x) => x.state === 'done').length, total: items.length, unit: 'こ',
    where: `${npcWhere('priestess') || 'ルミナの町'}の神殿`, note: 'ついたことのある職業の数。マスターすると、新しい職業への道が開くことがある。', items,
  };
}

// 職業の 試練（超級職より 上の 職業だけ。物語で まだ 受けられない 試練は 数に 入れない）
function trialsTrack(c) {
  const ids = Object.keys(c?.jobs || {}).filter((id) => JOBS[id] && trialJob(id));
  if (!ids.length) return null;
  const f = flagFn(c);
  const per = TRIALS.filter((T) => !T.flag || f(T.flag)).length;
  const items = ids.map((id) => {
    const n = Math.min(per, trialsCleared(id, c.jobs[id]));
    const st = trialState(c, id);
    const right = n >= per ? `${n}/${per}すんだ` : st.active ? `${st.active.name}のとちゅう` : st.canTake ? `${st.next.name}を受けられる` : `${n}/${per}`;
    return { name: jobLabel(id, c), where: st.why === 'lv' ? `職業Lv${st.next.needLv}で受けられる` : '', state: n >= per ? 'done' : st.active ? 'now' : st.canTake ? 'open' : 'wait', right };
  }).sort(byState);
  return {
    id: 'trials', name: '職業の試練', now: ids.reduce((s, id) => s + Math.min(per, trialsCleared(id, c.jobs[id])), 0), total: ids.length * per, unit: 'こ',
    where: `${npcWhere('trial_keeper') || 'ルミナの町'}の試練の番人`, note: '試練をこえると、職業レベルの上限が上がる。', items,
  };
}

// 幻の職業（名前を 知らない 物は ？？？。条件は 幻の書で）
function phantomTrack(c) {
  const rows = phantomBook(c);
  if (!rows.some((r) => r.known)) return null;
  const items = rows.map((r) => (r.known
    ? { name: r.name, where: '', state: r.got ? 'done' : r.ready ? 'open' : 'now', right: r.got ? 'なった' : r.ready ? 'なれる！' : `条件${r.conds.filter((x) => x.done).length}/${r.conds.length}` }
    : { name: '？？？', where: '', state: 'unknown', right: '' })).sort(byState);
  return {
    id: 'phantom', name: '幻の職業', now: rows.filter((r) => r.got).length, total: rows.length, unit: 'こ',
    where: `${npcWhere('priestess') || 'ルミナの町'}の神殿`, note: 'くわしい条件は、メニューの「幻の書」で見られる。', items,
  };
}

// 限界とっぱ（上限まで きたえた 装備。持っている 物と 装備している 物）
function ownedGear(c) {
  const ids = [...(c?.items || []).map((e) => e?.id), ...Object.values(c?.equip || {})].filter((id) => ITEMS[id]);
  return [...new Set(ids)];
}
function limitTrack(c) {
  const list = ownedGear(c).filter((id) => lbOf(id) > 0 || canLimitBreak(id, c));
  if (!list.length) return null;
  const items = list.map((id) => {
    const k = lbOf(id);
    return { name: ITEMS[id].name, where: '', state: k >= LB_MAX ? 'done' : canLimitBreak(id, c) ? 'open' : 'now', right: `★${k}/${LB_MAX}` };
  }).sort(byState);
  return {
    id: 'limit', name: '限界とっぱ', now: list.reduce((s, id) => s + lbOf(id), 0), total: list.length * LB_MAX, unit: '★',
    where: `${npcWhere('town_smith') || 'ルミナの町'}のかじ屋・れん金がま`, note: '上限まできたえた装備を、さらに★3まで強くできる。', items,
  };
}

// 魔物ずかん（メニューの 図鑑と おなじ 数え方）・仲間・配合
function zukanTrack(c) {
  const order = bestiaryOrder(MONSTERS);
  const bs = c?.bestiary || {};
  const kills = c?.kills || {};
  let seen = 0, friend = 0, bred = 0;
  for (const sp of order) {
    const b = bs[sp] || {};
    const fr = (b.friend || 0) > 0;
    const br = (b.bred || 0) > 0;
    if ((b.seen || 0) > 0 || (kills[sp] || 0) > 0 || fr || br) seen++;
    if (fr) friend++;
    if (br) bred++;
  }
  return {
    id: 'zukan', name: '魔物図鑑', now: seen, total: order.length, unit: 'しゅ', where: 'メニューの「図鑑」',
    note: `仲間にした魔物：${friend}しゅ\n配合で生んだ魔物：${bred}しゅ`, items: [],
    extra: [{ name: '仲間にした魔物', right: `${friend}しゅ` }, { name: '配合で生んだ魔物', right: `${bred}しゅ` }],
  };
}

// 小さなメダル（メダル王の つぎの ごほうびまで）
function medalTrack(c) {
  const found = medalsFound(c);
  if (!found) return null;
  const given = medalsGiven(c);
  const held = medalsHeld(c);
  const next = nextMedalReward(c);
  return {
    id: 'medal', name: '小さなメダル', now: given + held, total: next ? next.at : given + held, unit: 'まい', where: npcWhere('medal_king') || 'メダル王の城',
    note: `見つけたメダル：${found}まい\nメダル王にわたした：${given}まい\n${next ? `つぎのごほうびは${next.at}まいで` : '今もらえるごほうびは、全部もらった'}`, items: [],
  };
}

// ダンジョンの 宝箱（宝箱を 1つでも 開けた ダンジョンだけ。開ける 前の ダンジョンは 数えない）
function chestGroups(c) {
  const f = flagFn(c);
  const opened = c?.chests || {};
  const groups = new Map();
  for (const m of Object.values(MAPS)) {
    if (m.kind !== 'dungeon' || !m.chests?.length) continue;
    const key = String(m.name || m.id).split('　')[0];
    const g = groups.get(key) || { name: key, total: 0, open: 0 };
    for (const ch of m.chests) {
      if (!condOk(ch.show, f) && !opened[ch.id]) continue;
      g.total++;
      if (opened[ch.id]) g.open++;
    }
    groups.set(key, g);
  }
  return [...groups.values()].filter((g) => g.open > 0 && g.total > 0);
}
function chestTrack(c) {
  const groups = chestGroups(c);
  if (!groups.length) return null;
  const items = groups.map((g) => ({ name: g.name, where: '', state: g.open >= g.total ? 'done' : 'now', right: g.open >= g.total ? '全部開けた' : `あと${g.total - g.open}こ` })).sort(byState);
  return {
    id: 'chest', name: 'ダンジョンの宝箱', now: groups.reduce((s, g) => s + g.open, 0), total: groups.reduce((s, g) => s + g.total, 0), unit: 'こ',
    where: '', note: '宝箱を1つでも開けたダンジョンの数。', items,
  };
}

// 第78回 3-10: 家族ミッション（家族サーバーの 世界の 側の 数。ctx.missions … サーバーの 返事 world/missions.js の missionView。ひとりモードでは 出さない）
function missionTrack(c, ctx) {
  const m = ctx?.missions;
  if (!m || m.offline || !m.week) return null;
  const list = m.week.list || [];
  return {
    id: 'mission', name: '家族ミッション', now: list.filter((x) => x.done).length, total: list.length, unit: 'つ', where: 'メニューの「家族ミッション」',
    note: `今週のミッション（のこり${m.week.days}日）。\n家族サーバーで、2人いじょうがいっしょに遊ぶと進む。`,
    items: list.map((x) => ({ name: x.text, right: x.done ? '達成！' : `${x.now}/${x.need}`, state: x.done ? 'done' : 'now' })),
  };
}

const TRACKS = [missionTrack, boardTrack, sideTrack, arenaTrack, monArenaTrack, tmapTrack, sdTrack, limitTrack, phantomTrack, jobsTrack, trialsTrack, zukanTrack, medalTrack, chestTrack];
export const TRACK_IDS = ['mission', 'board', 'side', 'arena', 'monarena', 'tmap', 'sd', 'limit', 'phantom', 'jobs', 'trials', 'zukan', 'medal', 'chest'];

export function shioriTracks(c, ctx = {}) {
  const out = [];
  for (const fn of TRACKS) {
    const t = fn(c || {}, ctx || {});
    if (t) out.push(t);
  }
  return out;
}

// ───────────── 3. おすすめ（3つまで。物語 1つ と より道）─────────────
// { kind: 'story' | 'side', text, where, go（えらんだ ときに 開く しくみの id）}
export const REC_MAX = 3;
function sideRecs(c, tracks) {
  const f = flagFn(c);
  const T = Object.fromEntries(tracks.map((t) => [t.id, t]));
  const out = [];
  const push = (go, text, where) => { if (!out.some((r) => r.go === go)) out.push({ kind: 'side', text, where, go }); };
  // 1. 報告できる たのまれごと
  const boardNames = new Set(subQuestHints().filter((q) => q.board).map((q) => q.name));
  const ready = subQuests(c).find((q) => q.ready);
  if (ready) push(boardNames.has(ready.name) ? 'board' : 'side', `たのまれごと「${ready.name}」を報告できます`, npcWhere(ready.who));
  // 2. 幻の職業に なれる
  const ph = T.phantom?.items.find((x) => x.state === 'open');
  if (ph) push('phantom', `幻の職業「${ph.name}」になれます`, T.phantom.where);
  // 3. メダル王の ごほうび
  if (T.medal && T.medal.now >= T.medal.total && nextMedalReward(c)) push('medal', 'メダル王から、ごほうびがもらえます', T.medal.where);
  // 4. 職業の 試練（今の 職業）
  const st = c?.job && JOBS[c.job] ? trialState(c, c.job) : null;
  if (st?.ready) push('trials', `${jobLabel(c.job, c)}の${st.active.name}で、師しょうのまぼろしと戦えます`, T.trials?.where || '');
  else if (st?.canTake) push('trials', `${jobLabel(c.job, c)}の${st.next.name}を受けられます`, T.trials?.where || '');
  // 5. 闘技場の つぎの ランク
  const ar = T.arena?.items.find((x) => x.state === 'open');
  if (ar) push('arena', `サファラ闘技場の${ar.name}に、ちょうせんできます`, T.arena.where);
  const mr = T.monarena?.items.find((x) => x.state === 'open');
  if (mr) push('monarena', `モンスター闘技場の${mr.name}に、ちょうせんできます`, T.monarena.where);
  // 6. 受けられる お仕事いらい・より道
  const avail = availableSubQuests(c);
  const board = avail.filter((q) => q.board);
  if (board.length) {
    const mine = board.filter((q) => q.roots && jobLine(q.roots).has(c?.job)).length;
    push('board', `受けられるお仕事いらいが${board.length}つあります${mine ? `（今の職業で解決できそうなのが${mine}つ）` : ''}`, T.board?.where || BOARD_WHERE());
  }
  const side = avail.filter((q) => !q.board);
  if (side.length) push('side', `困っている人が${side.length}人います`, side[0].place);
  // 7. 限界とっぱ できる 装備
  const lb = T.limit?.items.filter((x) => x.state === 'open').length || 0;
  if (lb) push('limit', `限界とっぱできる装備が${lb}こあります`, T.limit.where);
  // 8. まだ ほって いない 宝の地図
  if (T.tmap?.items.length) push('tmap', `まだ宝をほっていない地図が${T.tmap.items.length}まいあります`, T.tmap.items[0].where);
  // 9. 今の 職業が もう 上がらない（試練も ない）
  const cur = c?.jobs?.[c?.job];
  if (cur && (cur.lv || 1) >= JOB_MAX_LEVEL && (!st || st.why === 'tier' || st.all)) push('jobs', `${jobLabel(c.job, c)}はマスターずみ。神殿で、ほかの職業にもなってみよう`, T.jobs?.where || '');
  // 10. 宝箱の のこり
  const ch = T.chest?.items.find((x) => x.state === 'now');
  if (ch) push('chest', `${ch.name}に、まだ開けていない宝箱があります`, ch.name);
  // 11. ひみつのダンジョン
  if (T.sd && f(SD_OPEN_FLAG)) push('sd', `ひみつのダンジョンの${T.sd.total}階をめざそう`, T.sd.where);
  return out;
}

export function shioriRecs(c, tracks = shioriTracks(c)) {
  const next = storyNext(c);
  const out = [];
  if (next.objective && !next.end) {
    out.push({ kind: 'story', text: next.where ? `物語のつぎの場所は「${next.where}」です` : '物語のつぎの目標があります', where: next.where, go: 'story' });
  }
  for (const r of sideRecs(c, tracks)) {
    if (out.length >= REC_MAX) break;
    out.push(r);
  }
  return out;
}

// ───────────── まとめ ─────────────
// ctx.missions … 家族ミッション（client/ui/missions.js が サーバーに 聞いた 物。なければ 出さない）
export function shioriOf(c, ctx = {}) {
  const ch = c || {};
  const tracks = shioriTracks(ch, ctx);
  return { story: { ...storyPlace(ch), ...storyNext(ch), bossHints: bossHintsSeen(ch) }, tracks, recs: shioriRecs(ch, tracks) };
}

// 1行の 数（「12/32」）。total が ない ときは now だけ
export function trackCount(t) {
  if (t.unit === 'Lv') return `Lv${t.now}/${t.total}`;
  if (t.unit === '階') return `${t.now}階`;
  return t.total === null || t.total === undefined ? `${t.now}${t.unit}` : `${t.now}/${t.total}`;
}
// 棒の 長さ（0〜1）
export function trackRate(t) {
  if (!t.total) return 0;
  return Math.max(0, Math.min(1, t.now / t.total));
}

js/shared/world/stairs.js:
// 第71回: 階だんを 上り下り したら、行った 先の 階だんの 真上に 立つ（家族の ねがい
//   「階段の となりの マスから 始まるので、いとせず 階段を 往復して しまう」）
//
//   ・階だん（STAIRS_UP / STAIRS_DOWN。フラグで 出てくる 階だんも）から 階だんへの ワープだけ。
//     とびら・町の 入口・フィールドへの 出口・洞窟の 入口は これまで どおり（となりの マス）
//   ・行き先の 階だん … 行き先の マップの ワープの うち、階だんの マスで、もとの マップへ もどる もの。
//     ワープの 行き先（to）に いちばん 近く（PAIR_REACH マス いない）、その 行き先が もとの 階だんの
//     そば（BACK_REACH マス いない）の もの。見つからない・ふさがっている ときは これまで どおり
//   ・ついた 階だんは「いちど おりるまで」つかわない（s.stairGuard。world.js の onEnterTile）。
//     2マス はばの 階だんは、となりの 階だんの マスも おなじ 階だん（横に 1歩 でも もどらない）
//   ・マップの データ（warps の to）は かえない（みちびきの糸・ルーラ・テストの きまりは そのまま）
import { MAPS, tileAt, isBlocked, condOk, npcCovers } from '../maps/index.js';
import { T } from '../tiles.js';

const PAIR_REACH = 2.6;
const BACK_REACH = 3.2;
// 階だんから これまでの つく マス（to）まで、この 歩数で 行けない ときは これまで どおり
//   （城の 封印の とびらの おくの 階だん など。とじこめられない ように）
const STEP_REACH = 4;

export const isStairsTile = (t) => t === T.STAIRS_UP || t === T.STAIRS_DOWN;

// (x, y) が 階だんの マスか（フラグで あらわれる・きえる 階だんも 階だんと みる）
export function stairsAt(map, x, y) {
  if (!map) return false;
  if (isStairsTile(tileAt(map, x, y))) return true;
  const g = (map.gates || []).find((q) => q.x === x && q.y === y);
  if (!g) return false;
  if (isStairsTile(g.open) || isStairsTile(g.closed)) return true;
  return !!g.levels?.some(([, t]) => isStairsTile(t));
}

// 階だんの ワープ（fromId の warp）で 行く 先の 階だん { x, y（マスの まん中）, tx, ty } か null
export function stairsPair(fromId, warp) {
  const from = MAPS[fromId];
  const to = warp?.to;
  const dest = to && MAPS[to.map];
  if (!from || !dest || !stairsAt(from, warp.x, warp.y)) return null;
  let best = null;
  for (const v of dest.warps || []) {
    if (v.to?.map !== fromId || !stairsAt(dest, v.x, v.y)) continue;
    const d = Math.hypot(v.x + 0.5 - to.x, v.y + 0.5 - to.y);
    if (d > PAIR_REACH) continue;
    if (Math.hypot(v.to.x - (warp.x + 0.5), v.to.y - (warp.y + 0.5)) > BACK_REACH) continue;
    if (!best || d < best.d) best = { v, d };
  }
  return best ? { x: best.v.x + 0.5, y: best.v.y + 0.5, tx: best.v.x, ty: best.v.y } : null;
}

// (tx, ty) の 階だんと つながっている 階だんの マス（おなじ マップへ 行く ワープ。2マス はばの 階だん など）の key
export function stairsGroup(map, tx, ty) {
  const first = map?.warpAt?.get(ty * map.w + tx);
  if (!first) return [];
  const out = [], seen = new Set([ty * map.w + tx]), q = [[tx, ty]];
  while (q.length && out.length < 16) {
    const [x, y] = q.shift();
    out.push(y * map.w + x);
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, ny = y + dy, k = ny * map.w + nx;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h || seen.has(k)) continue;
      seen.add(k);
      const w = map.warpAt.get(k);
      if (w && w.to?.map === first.to?.map && stairsAt(map, nx, ny)) q.push([nx, ny]);
    }
  }
  return out;
}

// ワープで おりる ところ: 階だんどうしなら 行き先の 階だんの 上（立てない ときは これまでの to）
//   { map, x, y, dir, stair: true|false }
export function warpLanding(fromId, warp, hasFlag) {
  const to = warp.to;
  const p = stairsPair(fromId, warp);
  if (p) {
    const map = MAPS[to.map];
    const k = p.ty * map.w + p.tx;
    const chest = map.chestAt?.get(k);
    const npc = map.npcs.some((n) => n.solid && condOk(n.show, hasFlag) && npcCovers(n, n.x + 0.5, n.y + 0.5, p.tx, p.ty));
    if (!isBlocked(map, p.tx, p.ty, hasFlag) && !(chest && condOk(chest.show, hasFlag)) && !npc
      && stepsTo(map, p.tx, p.ty, Math.floor(to.x), Math.floor(to.y), hasFlag) >= 0) {
      return { map: to.map, x: p.x, y: p.y, dir: to.dir, stair: true };
    }
  }
  return { map: to.map, x: to.x, y: to.y, dir: to.dir, stair: false };
}

// (sx, sy) の 階だんから (gx, gy) まで 何歩か（STEP_REACH より 遠い・行けない ときは -1）。
//   かべ・とじた とびら・ほかの 出入り口は とおらない（おなじ 階だんの となりの マスは よい）
export function stepsTo(map, sx, sy, gx, gy, hasFlag) {
  const group = new Set(stairsGroup(map, sx, sy));
  const dist = new Map([[sy * map.w + sx, 0]]);
  const q = [[sx, sy]];
  for (let head = 0; head < q.length; head++) {
    const [x, y] = q[head];
    const d = dist.get(y * map.w + x);
    if (x === gx && y === gy) return d;
    if (d >= STEP_REACH) continue;
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, ny = y + dy, k = ny * map.w + nx;
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h || dist.has(k) || isBlocked(map, nx, ny, hasFlag)) continue;
      if (map.warpAt?.has(k) && !group.has(k)) continue;
      dist.set(k, d + 1);
      q.push([nx, ny]);
    }
  }
  return -1;
}

// ついた 階だんの 上に いる あいだは その 階だんを つかわない
export function guardStair(s, landing) {
  const map = landing?.stair && MAPS[landing.map];
  s.stairGuard = map ? { map: landing.map, keys: stairsGroup(map, Math.floor(landing.x), Math.floor(landing.y)) } : null;
}
export function stairGuarded(s, tx, ty) {
  const g = s.stairGuard;
  const map = g && g.map === s.map && MAPS[s.map];
  return !!map && g.keys.includes(ty * map.w + tx);
}

js/shared/world/star-sight.js:
// 第6章 Step 3・4（A）: ミナモの 星読みと 星の道しるべ（サーバーの きまり）
//
// ミナモの 星読み（大事な物 c6s_star_reading。メニューの「道具」→「使う」。{ t: 'menu', action: 'starSight' }）
// ・ミナモが ゲストで いっしょの ときだけ。リーダーが 使う（パーティーの みんなに 夜空が 見える）
// ・使うと フラグ c6_starsight（maps/hoshimichi.js の STARSIGHT）が たって、使った 人が STAR_STEPS 歩く まで 夜空が 見える
//   （星めぐりの古道の 星の もやの 本当の 道が 光る。5階の 星受けの台で 星を 受けとめられる）。夜は 星読みが なくても 見える（'@night'）
// ・とちゅうで 切れた などで のこった フラグは、だれも 星読みを していない とき、古道の 階を 歩くと 消える
//
// 星の もや（maps/hoshimichi.js の map.mist）: 本当の 道 いがいの もやを ふむと、もやの 入口へ もどされる（どの 人も 1人ずつ）
import { MAPS } from '../maps/index.js';
import { STARSIGHT } from '../maps/hoshimichi.js';
import { hasKeyItem } from '../stats.js';
import { ScriptRun } from './scripts.js';
import { partyOf } from './party.js';

export const STAR_ITEM = 'c6s_star_reading';
export const STAR_STEPS = 40;

export const STAR_TEXT = {
  leader: '星読みをたのめるのは、パーティーのリーダーだけ。',
  busy: '今は使えない',
  fly: '空の上では使えない。\n（おりてから使おう）',
  none: 'ミナモがいないと、星の声は聞こえない…。',
  lost: 'もやの中で、道にまよった…\n気がつくと、もやの入口にもどっていた。\n（夜空の星が見えれば、道が分かるかもしれない）',
  half: '夜空の星が、少しずつうすくなってきた…',
  end: '夜空の星が、見えなくなった…\n（ミナモの星読みで、また見られる）',
};

function sendAll(world, s) {
  world.sendSelf(s);
  const p = partyOf(world, s);
  if (p && p.members.length > 1) world.sendParty(p);
  world.markDirty();
}
const active = (world, except = null) => [...world.sessions.values()].some((m) => m !== except && m.starSight);

// メニューから（world/services.js の menuAction の 'starSight'）。reply(ok, text)
export function useStarSight(world, s, reply) {
  if (world.hostOf?.(s)) return reply(false, STAR_TEXT.leader);
  if (!hasKeyItem(s.char, STAR_ITEM)) return reply(false, STAR_TEXT.none);
  if (s.busy) return reply(false, STAR_TEXT.busy);
  if (s.flying) return reply(false, STAR_TEXT.fly);
  if (!(s.char.guests || []).includes('minamo')) return reply(false, STAR_TEXT.none);
  const p = partyOf(world, s);
  const others = (p?.members || []).map((id) => world.sessions.get(id)).filter((m) => m && m !== s && m.inWorld && !m.away && !m.busy && m.map === s.map);
  const steps = [
    ['sfx', 'spell'],
    ['say', 'ミナモ', 'まかせて。\n…星よ、わたしたちに、道を見せて。'],
    ['call', (run) => { startStarSight(run.world, s); }],
    ['sync'],
    ['flash'],
    ['say', null, `ミナモが星を読んだ！\n昼の空のおくに、夜空の星が見えてきた…！\n（しばらく、${STAR_STEPS}歩くらいの間）`],
  ];
  const run = new ScriptRun(world, s, [s, ...others], steps, { scriptId: 'star_sight', owner: s });
  run.start();
  return reply(true, '');
}

// 星読みを はじめる（だいほん・テストからも）
export function startStarSight(world, s) {
  s.char.flags[STARSIGHT] = true;
  s.starSight = { left: STAR_STEPS, full: STAR_STEPS };
  world.markDirty();
}

function endStarSight(world, s) {
  s.starSight = null;
  if (!active(world, s)) delete s.char.flags[STARSIGHT];
  world.send(s, { t: 'toast', text: STAR_TEXT.end });
  sendAll(world, s);
}

// world.js の onEnterTile から（1マス 歩くごと）
export function stepStars(world, s, tx, ty) {
  const map = MAPS[s.map];
  // 星の もや: 本当の 道 いがいを ふむと 入口へ
  if (map?.mist?.lost.has(ty * map.w + tx)) {
    const b = map.mist.back;
    world.placeSession(s, map.id, b.x, b.y, 'up', true);
    world.send(s, { t: 'toast', text: STAR_TEXT.lost });
    return true;
  }
  const st = s.starSight;
  if (st) {
    st.left -= 1;
    if (st.left <= 0) endStarSight(world, s);
    else if (st.left === Math.floor(st.full / 4)) world.send(s, { t: 'toast', text: STAR_TEXT.half });
    return false;
  }
  // のこった フラグ（とちゅうで 切れた など）を 消す
  if (!map?.hmFloor) return false;
  const owner = world.hostOf?.(s) || s;
  if (!owner.char.flags[STARSIGHT] || active(world)) return false;
  delete owner.char.flags[STARSIGHT];
  sendAll(world, owner);
  return false;
}

