// 第53回 B: 第6章クリアの あとの「止まった時の間」の 時のまぼろし（docs/plan-ch6.md の 13-3・16・17）
// ・きまった 戦い toki_phantom（data/encounters-tokei6.js）。敵は 1日ごとに 第6章の ボスの どれか（tokiPhantomBase。日本の 0時に かわる）
// ・勝つと、その 日 はじめての 勝ちなら ★5の 素材（data/items-tokei6.js の TOKI_PHANTOM_REWARD）。1日1回・キャラごと
//   キャラの きろく: c.tokiPhantom = { day: 'YYYY-MM-DD'（さいごに ごほうびを もらった 日）, wins: 勝った 数 }
// ・その キャラが はじめて 勝った 時は 家族の けいじ板へ（world.boardPost。kind 'toki_phantom'。勝ち方は「見る」で）
// ・A の 台本は ['battle', 'toki_phantom'] でも、['call', tokiPhantomRun]（今日の 相手と ごほうびの ようすを 言ってから えらぶ）でも よい
import { ITEMS } from '../data/items.js';
import { MONSTERS } from '../data/monsters.js';
import { addItem } from '../stats.js';
import { dayKeyOf, tokiPhantomBase } from '../data/encounters-tokei6.js';
import { tokiPhantomId } from '../data/monsters-tokei6.js';
import { TOKI_PHANTOM_REWARD } from '../data/items-tokei6.js';
import { familyChar, BOARD_KINDS } from './family-board.js';

export const TOKI_PHANTOM_ENC = 'toki_phantom';
// けいじ板の 小さな 札（family-board.js の boardRows が BOARD_KINDS を 見る。A の 行と かさならない ように ここで 足す）
BOARD_KINDS.toki_phantom = BOARD_KINDS.toki_phantom || '時のまぼろし';

const isObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
// キャラの きろく（こわれて いれば 空から）
export function tokiState(c) {
  const s = isObj(c?.tokiPhantom) ? c.tokiPhantom : {};
  return { day: typeof s.day === 'string' ? s.day.slice(0, 10) : '', wins: Number.isFinite(s.wins) && s.wins > 0 ? Math.floor(s.wins) : 0 };
}
// 今日の ごほうびを もう もらったか
export const tokiPhantomDone = (c, now) => tokiState(c).day === dayKeyOf(now);
// 今日の 相手（{ base … もとの ボス, id … まぼろしの 魔物, name }）
export function tokiPhantomToday(now) {
  const base = tokiPhantomBase(now);
  const id = tokiPhantomId(base);
  return { base, id, name: MONSTERS[id]?.name || '' };
}

// 戦いの おわり（world/battles.js の finishBattle）。perSession … けっかの まどの 行
export function tokiPhantomAfter(world, ctx, sessions, perSession, outcome) {
  if (ctx?.opts?.fixed !== TOKI_PHANTOM_ENC || outcome !== 'win') return;
  const now = world.now();
  const day = dayKeyOf(now);
  const foe = ctx.battle.enemies.find((e) => e.boss) || ctx.battle.enemies[0];
  const { id, n } = TOKI_PHANTOM_REWARD;
  const names = sessions.map((m) => m.char?.name).filter(Boolean);
  for (const m of sessions) {
    const c = m.char;
    if (!c || c.species) continue;
    const L = (perSession[m.id] = perSession[m.id] || { lines: [] }).lines;
    const st = tokiState(c);
    const first = st.wins === 0;
    if (st.day !== day) {
      addItem(c, id, n);
      st.day = day;
      L.push(`★ ${c.name}は${ITEMS[id].name}を${n}つ手に入れた！（時のまぼろしのごほうびは、1日1回）`);
    } else L.push('（今日の時のまぼろしのごほうびは、もうもらった。また明日！）');
    st.wins++;
    c.tokiPhantom = st;
    if (first && familyChar(world, c)) {
      const with_ = names.length > 1 ? `${names.join('と')}で` : `${c.name}ひとりで`;
      try {
        world.boardPost?.({
          kind: 'toki_phantom', by: c.name, charId: c.id,
          title: `${c.name}が時のまぼろしに勝った！`,
          detail: `${with_}、${foe?.name || '時のまぼろし'}に勝った。（Lv${c.level}）\n時のまぼろしは、日ごとに、すがたがかわる。勝つと、1日1回、${ITEMS[id].name}がもらえる。`,
        });
      } catch { /* けいじ板が なくても 戦いの おわりは とめない */ }
    }
  }
  world.markDirty?.();
}

// A の 台本から よべる（['call', tokiPhantomRun]）: 今日の 相手と ごほうびの ようすを 言ってから、戦うか えらぶ
const note = (text) => ['say', null, text];
export async function tokiPhantomRun(run) {
  const c = run.init.char;
  const now = run.world.now();
  const t = tokiPhantomToday(now);
  const steps = [note(`止まった時の間に、${t.name}が、ゆらゆらとうかんでいる…！`)];
  if (tokiPhantomDone(c, now)) steps.push(note('（今日のごほうびは、もうもらった。戦うことはできるが、ごほうびは、また明日）'));
  else steps.push(note('（勝つと、1日に1回、ごほうびがもらえるようだ…）'));
  steps.push(['choice', `${t.name}と戦う？`, ['戦う', 'やめる'], [
    [['sfx', 'encounter'], ['battle', TOKI_PHANTOM_ENC]],
    [note('…まぼろしは、しずかにゆれている。')],
  ]]);
  return run.runSteps(steps);
}

js/shared/world/tokei-use.js:
// 第6章 Step 5（A）: 星読みの しおりを メニューから 使う（world/services.js の menuAction の 'bookmark'）
// ・止まった時計塔の 中で「使う」と、その 階の ことを ミナモの 星読み（ミナモの 声）が 教えてくれる。1つの 階に 1回（フラグ BM(n)）
// ・もう 読んだ 階は、しおりに のこった 短い ことばだけ（なんどでも）
// ・時計塔の 外では 使えない
// だいほんを はじめるので、だいほんの しくみ scripts.js を 読む（story-ch6c.js は ここを 読まない）
import { MAPS } from '../maps/index.js';
import { BM } from '../maps/tokei.js';
import { hasKeyItem } from '../stats.js';
import { ScriptRun } from './scripts.js';
import { partyOf } from './party.js';
import { TK_HINTS, BOOKMARK } from '../data/story-ch6c.js';
// 第6章 Step 6: 6〜10階の ページ（story-ch6d.js）
import { TK6_HINTS } from '../data/story-ch6d.js';

const HINTS = { ...TK_HINTS, ...TK6_HINTS };

export const BOOK_TEXT = {
  none: '星読みのしおりを持っていない。',
  busy: '今は使えない',
  outside: '星読みのしおりを開いた…。\nしかし、星の文字は光らない。\n（止まった時計塔の中で使おう）',
};

export function useBookmark(world, s, reply) {
  if (!hasKeyItem(s.char, BOOKMARK)) return reply(false, BOOK_TEXT.none);
  if (s.busy) return reply(false, BOOK_TEXT.busy);
  const n = MAPS[s.map]?.tkFloor;
  const hint = HINTS[n];
  if (!hint) return reply(false, BOOK_TEXT.outside);
  const owner = world.hostOf?.(s) || s;
  const read = !!owner.char.flags[BM(n)];
  const steps = read
    ? [['say', null, `星読みのしおりを開いた。\nしおりに、ミナモの星読みの言葉が、うすくのこっている…。\n「${hint.short}」`]]
    : [
      ['sfx', 'sparkle'], ['flash'],
      ['say', null, '星読みのしおりを開いた。\n星の形のもようが、ぽうっと光った…！'],
      ...hint.full.map((l) => ['say', 'ミナモの声', l]),
      ['flag', BM(n)], ['sync'],
    ];
  const p = partyOf(world, s);
  const others = (p?.members || []).map((id) => world.sessions.get(id)).filter((m) => m && m !== s && m.inWorld && !m.away && !m.busy && m.map === s.map);
  const run = new ScriptRun(world, s, [s, ...others], steps, { scriptId: 'bookmark', owner });
  run.start();
  return reply(true, '');
}

js/shared/world/tokei.js:
// 第6章 Step 5（A）: 止まった時計塔の「止まった 部屋」（サーバーの きまり）
//
// 止まった 部屋（maps/tokei.js の map.stopRooms。2階・4階）
// ・部屋の 中は 魔物も 水も 止まっている。時の 砂時計の 光の 中に いる 人（パーティーの みんな）だけが 動ける。止まった 水の 上も 歩ける
// ・部屋に 入ると 歩数を 数える（入口の マスから。部屋の 中に 立てる マスの 数が room.steps）。
//   数えきる 前に 部屋を 出ればよい。止まりが 切れると、時が 動き出して、部屋の 入口（room.back）へ もどされる
// ・家族は 1人ずつ 数える。部屋を 出る（部屋の 外の マスを ふむ・ほかの マップへ 行く）と 数えなおし
import { MAPS } from '../maps/index.js';
// 第6章 Step 6: 8階の 歯車の ハンドル（world/tokei-gear.js）
import { stepGear } from './tokei-gear.js';

export const STOP_TEXT = {
  start: (n) => `止まった部屋だ。\n魔物も水も、時が止まって、ぴくりとも動かない。\n（止まりが切れるまで、あと${n}歩くらい）`,
  half: (n) => `カチ…カチ…。\n止まった時が、少しずつ動き出そうとしている…（あと${n}歩）`,
  back: '時が動き出した！\n目をさました魔物におされて、部屋の入口にもどされてしまった…。\n（止まった水の上なら、近道できるかもしれない）',
};
export const STOP_WARN = 5;

// world.js の onEnterTile から（1マス 歩くごと）。入口へ もどした ときは true
export function stepTokei(world, s, tx, ty) {
  stepGear(world, s, tx, ty);
  const map = MAPS[s.map];
  const rooms = map?.stopRooms;
  const k = rooms ? ty * map.w + tx : -1;
  const room = rooms?.find((r) => r.cells.has(k));
  if (!room) {
    if (s.stopRoom) s.stopRoom = null;
    return false;
  }
  const st = s.stopRoom;
  if (!st || st.map !== map.id || st.id !== room.id) {
    s.stopRoom = { map: map.id, id: room.id, left: room.steps - 1 };
    world.send(s, { t: 'toast', text: STOP_TEXT.start(room.steps) });
    return false;
  }
  if (st.left <= 0) {
    s.stopRoom = null;
    world.placeSession(s, map.id, room.back.x, room.back.y, 'down', true);
    world.send(s, { t: 'toast', text: STOP_TEXT.back });
    return true;
  }
  st.left -= 1;
  if (st.left === STOP_WARN) world.send(s, { t: 'toast', text: STOP_TEXT.half(st.left) });
  return false;
}

js/shared/world/transfer-pack.js:
// 引っこしコード KIZUNA-5 の ちぢめる しくみ（第78回。docs/plan-r78-transfer.md）
//
// えらんだ やりかた: 文脈まぜ（context mixing）＋ 算術符号
//   1ビットずつ「つぎは 0 か 1 か」を、前の 1〜6文字・同じ ならびの くりかえし（match）から 予想して、
//   その 予想を まぜて（mixer）、算術符号で 書く。deflate（zlib -9）より 2わり、下じき（transfer-prime.js）も 使うと 5わり みじかい
// きまり（node でも ブラウザでも 同じ 結果に する ため）
//   ・整数の 足し算・かけ算・わり算（2の べき）だけ。Math.exp などは 使わない（端末で 少し ちがう ことが ある）
//   ・同期・依存なし（npm の パッケージも CompressionStream も 使わない）
// ちぢめる 前の 文字は UTF-8 の バイト。書く 物: [もとの バイト数（7ビットずつ）][算術符号の バイト]

// ───── 予想を 足しやすい 形（stretch）と もどす 形（squash）。12ビット（0〜4095） ─────
const SQ = [1, 2, 3, 6, 10, 16, 27, 45, 73, 120, 194, 310, 488, 747, 1101, 1546, 2047, 2549, 2994, 3348, 3607, 3785, 3901, 3975, 4024, 4050, 4068, 4079, 4085, 4089, 4092, 4093, 4094];
function squash(d) {
  if (d > 2047) return 4095;
  if (d < -2047) return 1;
  const w = d & 127;
  const i = (d >> 7) + 16;
  return (SQ[i] * (128 - w) + SQ[i + 1] * w + 64) >> 7;
}
const STRETCH = new Int16Array(4096);
{
  let pi = 0;
  for (let x = -2047; x <= 2047; x++) {
    const v = squash(x);
    for (let i = pi; i <= v; i++) STRETCH[i] = x;
    pi = v + 1;
  }
  for (let i = pi; i < 4096; i++) STRETCH[i] = 2047;
}
// 数えた 回数ごとの 学ぶ 速さ（65536 / (n + 1.5)）
const RATE_MAX = 60;
const DT = new Int32Array(RATE_MAX + 1);
for (let n = 0; n <= RATE_MAX; n++) DT[n] = Math.floor(131072 / (2 * n + 3));

const ORDERS = [1, 2, 3, 4, 6];
// 文脈: 前の n 文字（ORDERS）
const NCTX = ORDERS.length;
const N_IN = NCTX + 3; // 0文字の 文脈・くりかえし・いつも 1（bias）
const TBITS = 19;
const MAXLEN = 62;
const MBITS = 18;

// 予想する 部品の 中み（数の 表と 今の いち）。下じき（prime）を 読ませた あとの 中みは 1回だけ 作って とっておき、
// ちぢめる・もどす たびに うつして 使う（下じきを 毎回 読むと おそい）
function newState(cap) {
  const tabSize = 1 << TBITS;
  const apmRow = new Uint16Array(33);
  for (let j = 0; j < 33; j++) apmRow[j] = squash((j - 16) * 128) * 16;
  const apm1 = new Uint16Array(256 * 33);
  const apm2 = new Uint16Array(65536 * 33);
  for (let c = 0; c < 256; c++) apm1.set(apmRow, c * 33);
  for (let c = 0; c < 65536; c++) apm2.set(apmRow, c * 33);
  return {
    prob: Array.from({ length: NCTX }, () => new Uint16Array(tabSize).fill(32768)),
    cnt: Array.from({ length: NCTX }, () => new Uint8Array(tabSize)),
    p0: new Uint16Array(256 * 256).fill(32768), // 0文字の 文脈（今の バイトの とちゅう）は 1つ前の 文字と いっしょに
    n0: new Uint8Array(256 * 256),
    mProb: new Uint16Array(64 * 2 * 256).fill(32768),
    mCnt: new Uint8Array(64 * 2 * 256),
    wts: new Float64Array(256 * N_IN).fill(Math.floor(65536 * 0.3)),
    apm1,
    apm2,
    buf: new Uint8Array(cap + 8),
    mtab: new Int32Array(1 << MBITS),
    base: new Int32Array(NCTX),
    pos: 0, mPtr: 0, mLen: 0, started: false,
  };
}
function cloneState(S, more) {
  const buf = new Uint8Array(S.pos + more + 8);
  buf.set(S.buf.subarray(0, S.pos));
  return {
    prob: S.prob.map((a) => a.slice()), cnt: S.cnt.map((a) => a.slice()),
    p0: S.p0.slice(), n0: S.n0.slice(), mProb: S.mProb.slice(), mCnt: S.mCnt.slice(), wts: S.wts.slice(),
    apm1: S.apm1.slice(), apm2: S.apm2.slice(), buf, mtab: S.mtab.slice(), base: S.base.slice(),
    pos: S.pos, mPtr: S.mPtr, mLen: S.mLen, started: S.started,
  };
}
let primed = null; // { prime, state }
function stateFor(prime, size) {
  if (!prime || !prime.length) return newState(size);
  if (!primed || primed.prime !== prime) {
    const S = newState(prime.length);
    const m = makeModel(S);
    for (let i = 0; i < prime.length; i++) for (let b = 7; b >= 0; b--) {
      m.predict();
      m.update((prime[i] >> b) & 1);
    }
    m.save();
    primed = { prime, state: S };
  }
  return cloneState(primed.state, size);
}

// 予想する 部品（書く ほうと 読む ほうで まったく 同じ）
function makeModel(S) {
  const { prob, cnt, p0, n0, mProb, mCnt, wts, apm1, apm2, buf, mtab, base } = S;
  const idx = new Int32Array(NCTX);
  const st = new Int32Array(N_IN);
  let pos = S.pos, c0 = 1, bitPos = 0;
  let mPtr = S.mPtr, mLen = S.mLen, mBit = 0;
  let pr = 2048, prMix = 2048, a1 = 0, a2 = 0, aw = 0, i0 = 0, mi = -1, wsel = 0;

  const upd = (P, C, i, y) => {
    const n = C[i];
    const p = P[i];
    P[i] = p + Math.trunc((((y << 16) - y) - p) * DT[n] / 65536);
    if (n < RATE_MAX) C[i] = n + 1;
  };
  const hashOrder = (k) => {
    let h = Math.imul(k + 1, 0x9E3779B1);
    for (let j = 1; j <= k; j++) h = Math.imul(h ^ buf[pos - j], 0x2F0B4AD5) ^ (h >>> 15);
    return h;
  };
  const startByte = () => {
    for (let k = 0; k < ORDERS.length; k++) base[k] = pos >= ORDERS[k] ? hashOrder(ORDERS[k]) : Math.imul(k + 7, 0x7FEB352D);
    // くりかえし（match）: さいごの 5文字が 前に 出て いたら、その つづきを 予想に 使う
    if (mLen > 0 && mPtr < pos) {
      mLen = Math.min(mLen + 1, MAXLEN);
      mPtr++;
    } else mLen = 0;
    if (pos >= 5) {
      let h = 0;
      for (let j = 1; j <= 5; j++) h = Math.imul(h ^ buf[pos - j], 0x01000193);
      h = (h >>> (32 - MBITS));
      if (mLen === 0) {
        const cand = mtab[h];
        if (cand > 0) {
          let len = 0;
          while (len < MAXLEN && cand - len - 1 >= 0 && buf[cand - len - 1] === buf[pos - len - 1]) len++;
          if (len >= 5) {
            mLen = len;
            mPtr = cand;
          }
        }
      }
      mtab[h] = pos;
    }
  };
  const predict = () => {
    for (let k = 0; k < NCTX; k++) {
      const i = (Math.imul(base[k] ^ Math.imul(c0, 0x6F4F2A35), 0x9E3779B1) >>> (32 - TBITS));
      idx[k] = i;
      st[k] = STRETCH[prob[k][i] >>> 4];
    }
    const c1 = pos > 0 ? buf[pos - 1] : 0;
    i0 = c1 * 256 + c0;
    st[NCTX] = STRETCH[p0[i0] >>> 4];
    // くりかえし
    if (mLen > 0) {
      const want = buf[mPtr] | 256;
      if ((want >> (8 - bitPos)) === c0) {
        mBit = (want >> (7 - bitPos)) & 1;
        mi = ((Math.min(mLen, 63) * 2 + mBit) << 8) | (c0 & 255);
        st[NCTX + 1] = STRETCH[mProb[mi] >>> 4];
      } else {
        mLen = 0;
        mi = -1;
        st[NCTX + 1] = 0;
      }
    } else {
      mi = -1;
      st[NCTX + 1] = 0;
    }
    st[NCTX + 2] = 256;
    // まぜる（重みは 今の バイトの とちゅうの 形ごと）
    wsel = (mLen > 0 ? 128 : 0) | (c0 & 127);
    const w0 = wsel * N_IN;
    let dot = 0;
    for (let k = 0; k < N_IN; k++) dot += wts[w0 + k] * st[k];
    let d = Math.floor(dot / 65536);
    if (d > 2047) d = 2047;
    if (d < -2047) d = -2047;
    prMix = squash(d);
    // 2つの 仕上げ（APM）: 今の バイトの とちゅう ／ 1つ前の 文字も
    const s = d + 2048;
    aw = s & 127;
    const j = s >> 7;
    a1 = c0 * 33 + j;
    a2 = ((c1 << 8) | c0) * 33 + j;
    const pa1 = (apm1[a1] * (128 - aw) + apm1[a1 + 1] * aw) >> 11;
    const pa2 = (apm2[a2] * (128 - aw) + apm2[a2 + 1] * aw) >> 11;
    pr = (prMix * 2 + pa1 + pa2 + 2) >> 2;
    if (pr < 1) pr = 1;
    if (pr > 4095) pr = 4095;
    return pr;
  };
  const apmUpd = (T, i, y) => {
    const g = (y << 16) + (y << 5) - y - y;
