import { PAST_PLACES, pastWarpTowns } from '../data/past-places.js';

const FOLLOW_RANGE = 12;

// ───────────── ルーラ・帰り道の羽の 行き先 ─────────────
// 行った ことの ある 町・村・港（星見の丘は のぞく）
// 第59回: 「最後にいのった場所」（いのりの場所。ダンジョンの 泉・教会。world.js の prayDest）
export const PRAY_PLACE = 'pray';
